INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8c5ff60d0229', 'en', 'US', '15 Minute Sausage Meatballs', 'Recipe video above. Save this one for those really busy nights: just chop up sausages, pan fry and voila - juicy meatballs without the fuss! A bottle of passata rather than canned tomato makes for a quick sauce which needs nothing more than a pinch of Italian Herbs and salt thanks to all the free flavour we get from the pre-seasoned meat inside the sausages. Serve over pasta, or polenta (try instant polenta!), mash or make saucy subs. YES!', 'https://www.recipetineats.com/tachyon/2025/10/Sausage-meatballs-15-minutes_0.jpg', 5, 10, 15, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_sausages", "quantity": {"value": 1.4, "unit": "pack of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_basil", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}]', '[{"ingredients":["1 tbsp olive oil","700 g / 1.4 lb good sausages","2 garlic cloves (, finely chopped)","3/4 cup chicken stock/broth (, low sodium - sub water (Note 2))","700g / 24 oz tomato passata (US: tomato sauce like Hunt''s) (Note 3)","1/2 tsp dried Italian herb mix (sub dried oregano, or 50/50 oregano/thyme)","1/2 tsp cooking salt / kosher salt (+50% for flakes, halve for table salt)","1/4 tsp red pepper flakes (, optional (hint of warmth - sub pinch of pepper))","1 sprig basil ( - stalk for sauce, leaves for garnish (optional))"]},{"ingredients":["Parmesan (, finely grated)","350g / 12oz pasta of choice (, or polenta, mash or make subs!)"],"purpose":"Serving:"}]', '[{"description":"Brown meatballs (3-4 min), add garlic for last 15 seconds. Reduce stock by half (1 min), add everything else, simmer 4 minutes. Serve!","images":[],"step":1},{"title":"Brown meatballs","description":"Heat the oil in a large non-stick pan over high heat. Add the meatballs and stir for 4 - 5 minutes until lightly browned but still raw inside. (Note 4)","duration":4.5,"images":[],"step":2},{"description":"Add garlic and stir for just 15 seconds until light golden (careful, don''t let it burn!)","images":[],"step":3},{"title":"Simmer","description":"Add the stock and simmer rapidly for 1 minute to reduce by half. Add everything else, stir, bring to a simmer, then lower heat to medium high and let it simmer energetically (but not crazy rapidly) for 4 minutes.","duration":1,"images":[],"step":4},{"description":"Serve with lots of parmesan and hand-torn basil leaves over pasta, polenta, mash or other starchy vehicle of choice, or stuff into subs!","images":[],"step":5},{"description":"Add cooked pasta with 1/2 cup of the pasta cooking water into the pan with meatballs. Toss over medium heat for 1 - 2 minutes until the sauce is stuck to the pasta and it''s stained red, rather than pooled in the base of the pan. Divide between bowls and enjoy!","duration":1.5,"images":[],"step":6}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Italian-esque","Western"],"categories":["dinner-tonight","meatball-recipes","pasta-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","sausage-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ccc413d76a32', 'en', 'US', 'Jamaican Jerk Fish', 'Recipe video above. Jerk seasoning adds a stack of flavour and makes the surface crispy too. Quick way to make a dish that punches way above its weight for effort vs results. I''ve used it for white fish fillets here but it will be excellent with salmon, prawns/shrimp, chicken or turkey.Spiciness - Packs a decent punch! See note for how to control.Jamaican menu week! This Jerk Fish with Jamaican Slaw and Jamaican Coconut Rice and Peas (beans) plus rum and raisin ice cream without an ice cream maker for dessert!', 'https://www.recipetineats.com/tachyon/2023/01/Jerk-fish_0.jpg', 5, 6, 11, 4, '[{"id": "ing_garlic_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.013, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.281, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.156, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_nutmeg_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}]', '[{"ingredients":["3 tsp garlic powder","3 tsp onion powder","2 tsp cooking salt / kosher salt (reduce to 1 1/2 tsp for table salt)","3 tsp dried thyme","2 1/2 tsp brown sugar (, lightly packed (Note 2))","2 1/4 tsp cayenne pepper (it''s spicy! See SPICE NOTE)","1 1/2 tsp smoked paprika (sub ordinary paprika)","1 1/4 tsp allspice powder","1/2 tsp cinnamon powder","1/2 tsp nutmeg powder"],"purpose":"Jerk seasoning (Note 1):"},{"ingredients":["4 x 160g/6 oz thin snapper or other white fish fillets (, skinless, boneless (up to 1.5cm / 0.6\" thick, Note 3))","3 tbsp extra virgin olive oil"],"purpose":"Fish:"}]', '[{"title":"Jerk Spice Blend","description":"Mix the Jerk Seasoning spices together in a bowl then spread in a small tray that is just large enough to fit one fish fillet.","images":[],"step":1},{"title":"Coat fish","description":"Pat fish dry with a paper towel. Then coat both sides of each fillet with the jerk seasoning, pressing to adhere. Shake off excess, place on a clean plate and coat remaining fish.","images":[],"step":2},{"title":"Cook fish","description":"Heat half the oil in a large non-stick pan over high heat. When you see small wisps of smoke, place 2 fillets presentation side down and cook for 2 minutes.","duration":2,"images":[],"step":3},{"title":"Flip","description":"the spice crust should be a deep bronze colour with a reddish tinge. Cook the other side for 1 minute until the target internal temperature is 55°C/130°F, or the fish flakes easily at the thickest point.","duration":1,"images":[],"step":4},{"description":"Rest on a rack for 2 minutes (to preserve crispy spice crust). Then serve! Recipes for pictured Jamaican sides coming on Tuesday - stay tuned!","duration":2,"images":[],"step":5}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Caribbean","Jamaican"],"categories":["dietary","dinner-tonight","fish-recipes","low-calorie-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a6b37999ff63', 'en', 'US', 'Crispy Skin Fish', 'Recipe video above. Fish with crispy skin is one of the most delicious quick ways to cook a piece of protein! To nail it every time, you need dry skin, hot oil and to press down lightly to let the skin seal against the hot pan.I''m using Barramundi here but this recipe can be used for any fish with skin that goes crispy - see Note 1.Stove to oven method recommended for thick fillets so for most even cooking of flesh with super crispy skin - see Note 3. Thin fillets can be cooked entirely on the stove. Scoring the skin is recommended for thick fillets for even cooking of the flesh and skin, plus an insurance policy to prevent the skin from curling up.Sauces and sides - See Note 7!', 'https://www.recipetineats.com/tachyon/2021/10/Crispy-Skin-Barramundi_97.jpg', 3, 0, 3, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.18, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_sauces_and_sides", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["180g/6oz x 2 barramundi or other fish fillets (, skin on, pin boned (Note 1))","2 tbsp olive oil (or vegetable, canola or grapeseed oil)","3/4 tsp cooking/kosher salt (or 1/2 tsp table salt, Note 2)","1/4 tsp black pepper","Sauces and sides (- see Note 7 below)"]}]', '[{"title":"Thick Fillets definition","description":"Fish > 2.5cm / 1\" thick at the thickest point. Best finished in the oven. (Note 3)","images":[],"step":1},{"title":"Pan type","description":"Non-stick pan, an oven proof one if you have Thick Fillets. (Note 4)","images":[],"step":2},{"title":"Preheat oven (for Thick Fillets)","description":"Preheat oven to 200°C/390°F (180°C fan).","images":[],"step":3},{"description":"Cooking:","images":[],"step":4},{"title":"Dry skin","description":"Pat skin dry with paper towels. For extra precaution, leave the fish fillets in the fridge skin side up, uncovered, for an hour. (I rarely do this)","images":[],"step":5},{"title":"Scoring skin (Note 5)","description":"For Thick Fillets, score the skin by cutting slashes into the skin as pictured in post. 4cm slashes 1cm apart, 2 - 3mm deep, through the skin and ever so slightly into the flesh (1.6\" long, 0.4\" apart, 0.1\" deep)","images":[],"step":6},{"title":"Season fish","description":"Sprinkle the flesh and skin with the salt and pepper just before cooking.","images":[],"step":7},{"title":"Heat oil well","description":"Heat oil in a non stick pan over medium high heat until you see the first small wisps of smoke.","images":[],"step":8},{"title":"Press fish down","description":"Place one fillet into the pan skin side down, then use your fingers or spatula to press down lightly for 10 seconds to allow the skin to seal flat against the hot surface. Repeat with the other fillet (PROS: Do both at the same time!).","duration":0.16666666666666666,"images":[],"step":9},{"title":"Cook skin 2","description":"3 minutes: Cook the skin side for 2 to 3 minutes until it''s crispy in the centre and golden. Lift up to check.","duration":2.5,"images":[],"step":10},{"title":"Transfer Thick Fillets to oven","description":"Transfer to oven for 10 minutes (do not flip, keep skin side still down - goes crispier!) or until the internal temperature is 55°C/131°F. (Note 6)","duration":10,"images":[],"step":11},{"title":"Thin fillets","description":"Turn and cook the flesh side in the pan.","images":[],"step":12},{"title":"Rest 3 minutes","description":"Transfer fish to a rack with the skin side UP. Rest for 3 minutes.","duration":3,"images":[],"step":13},{"title":"Serving","description":"To serve, place on a plate skin side UP. Do not pour sauce on the skin until just before serving else it will soften the fish skin. See ingredients above for suggested sauces and sides!","images":[],"step":14}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","fish-recipes","mains","other","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_44db9eac2bd1', 'en', 'US', 'Asian Chilli Chicken', 'Recipe video above. A quick chicken dinner that''s an explosion of (spicy!) Asian flavours! Make this with chicken breast, boneless thighs or tenderloins.Spiciness level: Spicy but not blow-your-head-off spicy! Remember, I like to think I''m a Spice Monster, but in reality I can''t handle the heat (literally!). To dial it back, reduce chilli flakes and see Note 2 about reducing Sriracha.', 'https://www.recipetineats.com/tachyon/2021/02/Asian-Chilli-Chicken_7a.jpg', 5, 8, 13, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.02, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_sriracha", "quantity": {"value": 0.113, "unit": "bottle of 400ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.125, "unit": "jar of 500g"}}, {"id": "ing_lime", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["500g / 1lb breast fillets, skinless and boneless (2 large) (Note 1 other cuts)","1/2 tsp each salt and pepper","1 1/2 tbsp rice flour, or all-purpose/plain flour (Note 2)","1 1/2 tbsp oil (, vegetable or canola)"],"purpose":"Chicken:"},{"ingredients":["2 tsp sesame oil","2 garlic cloves (, finely minced)","2 tsp ginger (, finely minced)","1 tsp chilli flakes / red pepper flakes (reduce for less spicy)","1/2 cup water","3 tbsp sriracha (sub ketchup for not spicy, Note 3)","1 tbsp soy sauce (, light or all purpose (Note 4))","1/4 cup honey (sub brown sugar)","3 tbsp lime juice (sub 2 tbsp rice vinegar)"],"purpose":"Sauce:"},{"ingredients":["Green onion (finely sliced), sesame seeds, fresh chilli, lime wedges"],"purpose":"Garnishes (choose):"}]', '[{"title":"Season","description":"Cut each chicken breast in half horizontally to form 4 steaks total. Sprinkle each side with salt, pepper and rice flour, shaking off excess.","images":[],"step":1},{"title":"Pan-fry","description":"Heat oil in a large skillet over high heat. Add chicken and cook for 2 minutes. Turn and cook the other side for 2 minutes, then remove to a plate.","duration":2,"images":[],"step":2},{"description":"Sticky Chilli Sauce:","images":[],"step":3},{"title":"Sesame oil","description":"Allow the skillet to cool a bit then return to the stove on medium. Add sesame oil and heat.","images":[],"step":4},{"title":"Garlic and ginger","description":"Add garlic and ginger, cook for 15 seconds.","duration":0.25,"images":[],"step":5},{"title":"Chilli flakes","description":"Add chilli flakes and cook for 30 seconds until garlic is golden.","duration":0.5,"images":[],"step":6},{"title":"Sriracha, soy and honey","description":"Turn heat up to medium-high. Add water, sriracha, soy sauce and honey, stir well, scraping the base of the pan to dissolve all the golden bits into the liquid.","images":[],"step":7},{"description":"Simmer for 2 minutes until it reduce to a thick syrup. Add lime juice, then simmer for a further 30 seconds until it thickens back to a thick syrup.","duration":2,"images":[],"step":8},{"title":"Coat chicken","description":"Turn heat off. Return chicken to pan, turning to coat in sauce.","images":[],"step":9},{"description":"Serve chicken, topping with remaining sauce in skillet, garnished with green onions, sesame seed and extra lime wedges, if desired.","images":[],"step":10}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Asian","Modern Asian"],"categories":["asian-recipes","chicken","chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","low-calorie-recipes","main-dishes","mains","modern-asian","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_438b29404531', 'en', 'US', '12 Minute Thai Chicken Peanut Noodles', 'Recipe video above. Thai Chicken Peanut Noodles is what you make when you''ve got less than 15 minutes to get dinner on the table and you need a Thai fix! Using chicken mince means no meat prep - and you can switch it out with literally any ground meat (beef, turkey, pork). It might not be authentic Thai ... but it''s fast and 100% delicious!NOTE: Trick here is to work quickly so the sauce isn''t all absorbed by the noodles which will make them bloated and clumpy. If your noodles do absorb all the sauce, just add a splash of water to thin it out.', 'https://www.recipetineats.com/tachyon/2021/01/12-Minute-Thai-Chicken-Noodles_2.jpg', 3, 9, 12, 2, '[{"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_chicken_mince", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_red_curry_paste", "quantity": {"value": 0.113, "unit": "bottle"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.469, "unit": "can of 400ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.12, "unit": "jar of 375g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 2.0, "unit": "pack of 500g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_peanuts", "quantity": {"value": 0.075, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 tbsp oil","1 garlic clove (, minced)","200g/7oz chicken mince (ground chicken) (Note 1)","1 tsp curry powder (Note 2)","1 1/2 tbsp red curry paste (, separated (Note 3))","1 tsp dark soy sauce (Note 4)","1 1/2 cups chicken stock/broth (, low sodium)","3/4 cup coconut milk ((~1/2 a can), full fat for best flavour)","2 tbsp cider vinegar","3 tbsp peanut butter","2 instant ramen or noodle cakes (~70-100g/2.5-3.5oz per cake; any brand (discard seasoning pack, Note 5))","2 (big!) handfuls baby spinach"]},{"ingredients":["2 tbsp peanuts (, finely chopped)","Roughly chopped fresh coriander/cilantro leaves","Sriracha or other chilli paste (, optional)"],"purpose":"To serve:"}]', '[{"title":"Sauté garlic","description":"Heat oil in a medium skillet over high heat (not too large, else the sauce will evaporate too quickly). Add garlic and cook for 20 seconds until it turns golden.","duration":0.3333333333333333,"images":[],"step":1},{"title":"Cook chicken","description":"Add chicken mince and cook for 2 minutes, breaking it up as you go, until it mostly changes from pink to white.","duration":2,"images":[],"step":2},{"title":"Add flavourings","description":"Add 1 tbsp red curry paste, curry powder and soy sauce. Cook for 1 minute.","duration":1,"images":[],"step":3},{"title":"Cook extra curry paste","description":"Clear a space in the middle of the pan, add remaining 1/2 tbsp curry paste, stir the curry paste for 30 seconds.","duration":0.5,"images":[],"step":4},{"title":"Simmer stock","description":"Add chicken stock, bring to a simmer then reduce to medium-high. Simmer for 1 minute.","duration":1,"images":[],"step":5},{"title":"Add noodles","description":"Squish the noodle cakes in, pushing chicken aside so the noodles are as submerged as possible.","images":[],"step":6},{"title":"Cook 45 sec, flip, 30 sec","description":"Leave to cook for 45 seconds, then flip noodles. Leave for another 30 seconds, then separate the noodles with 2 wooden spoons.","duration":0.75,"images":[],"step":7},{"title":"Add peanut sauce","description":"Push noodles aside, add coconut milk, peanut butter and vinegar, then give it a quick mix to mostly dissolve the peanut butter.","images":[],"step":8},{"title":"Toss with spinach","description":"Add spinach, toss with the noodles for 30 seconds until wilted. Make sure it''s still pretty saucy - everybody loves sauce!","duration":0.5,"images":[],"step":9},{"title":"Serve","description":"Transfer to serving bowls, sprinkle with coriander, peanuts and Sriracha or chilli paste if desired.","images":[],"step":10}]', '["gluten","peanuts","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Thai-ish"],"categories":["asian-recipes","dinner-tonight","noodles","one-pot-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5fc7e5dae9a7', 'en', 'US', 'Chop Suey - Chicken Stir Fry', 'Recipe video above. The essential ingredient for a great Chop Suey sauce is Chinese cooking wine. All Chinese restaurants use it! See notes for subs if you can''t get your hands on it. Veggie loaded, light on the meat, this is healthy and adaptable to whatever you''ve got in your fridge!', 'https://www.recipetineats.com/tachyon/2017/11/Chicken-Stir-Fry-Chop-Suey-5.jpg', 9, 6, 14, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.18, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_stems_choy_sum", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.0, "unit": "bag of 250g"}}]', '[{"ingredients":["180g (6oz ) chicken breast (, thinly sliced)","1/2 tsp baking soda / bi-carb (optional, Note 1)"],"purpose":"Optional Tenderised Chicken (Note 1):"},{"ingredients":["1 tbsp cornflour / corn starch","1 1/2 tbsp light soy sauce (, or all purpose soy(Note 3))","1 tbsp Oyster Sauce (Note 4)","1 tbsp Chinese Cooking Wine (OR Mirin (Note 5))","1/2 tsp sesame oil (optional)","Dash of white pepper (or black)","3/4 cup (185 ml) water"],"purpose":"Sauce (or use Charlie, Note 2):"},{"ingredients":["1 1/2 tbsp vegetable oil (or other cooking oil)","2 garlic cloves (, finely chopped)","1/2 onion (, sliced (white, brown, yellow))","5 - 6 stems choy sum (or other Asian greens)","1 medium carrot","1/2 cup sliced mushrooms (shiitake is authentic, but any will do)","1 cup bean sprouts"],"purpose":"Stir Fry:"}]', '[{"description":"\"Velvet\" Chicken (optional, Note 1)","images":[],"step":1},{"description":"Place chicken in a bowl, sprinkle over baking soda. Use your fingers to mix then set aside for 20 minutes, no longer than 30 minutes (can get too tender). Rinse well, pat excess water with paper towels, set aside (see video).","duration":20,"images":[],"step":2},{"description":"Prep Ingredients:","images":[],"step":3},{"title":"Sauce","description":"Place cornflour and soy sauce in a bowl. Mix until lump free. Then add remaining Sauce ingredients and stir.","images":[],"step":4},{"title":"Chop choy sum","description":"Trim end off choy sum. Then cut into 7cm (3\") pieces. Separate stems from leaves.","images":[],"step":5},{"title":"Chop carrot","description":"Peel then cut into 3cm (1.3\") pieces. Then slice the pieces thinly.","images":[],"step":6},{"description":"Heat oil in a wok or skillet over high heat. Add garlic, stir quickly, then add onion, Cook for 1 minute, moving constantly, until onion is starting to wilt.","duration":1,"images":[],"step":7},{"description":"Add chicken, cook for 1 minute until the surface changes from pink to white.","duration":1,"images":[],"step":8},{"description":"Add choy sum stems, carrot and mushrooms. Stir fry for 1 minute.","duration":1,"images":[],"step":9},{"description":"Add choy sum leaves, bean sprouts and Sauce. Stir fry for 1 to 2 minutes until the Sauce thickens to a thick syrup consistency. Vegetables should still be tender/crisp, not soggy and soft.","duration":1.5,"images":[],"step":10},{"description":"Serve immediately with rice (for low carb, low cal option, try Cauliflower Rice!)","images":[],"step":11}]', '["gluten","sesame","soy"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["American Chinese"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","dietary","dinner-tonight","low-calorie-recipes","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e299f8e365a5', 'en', 'US', 'Honey Garlic Chicken Breast', 'Recipe video above. An incredible quick and easy way to serve up chicken breast - seared then simmered in the most amazing honey garlic sauce. Don''t be deceived by the short ingredient list! It''s absolutely worth the extra step of dusting the chicken with flour because it creates a crust for the sauce to cling to. BONUS: See notes for how to make this with any protein - beef, pork, lamb, prawns/shrimp, tofu!', 'https://www.recipetineats.com/tachyon/2018/09/Honey-Garlic-Chicken-Breast_5.jpg', 4, 8, 12, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 3.5, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.167, "unit": "jar of 500g"}}]', '[{"ingredients":["500g / 1 lb chicken breast (, boneless and skinless (2 pieces))","Salt and pepper","1/4 cup flour (Note 1)","3 1/2 tbsp (50g) unsalted butter (or 2 1/2 tbsp olive oil)","2 garlic cloves (, minced)","1 1/2 tbsp apple cider vinegar (or white or other clear vinegar)","1 tbsp soy sauce (, light or all purpose (Note 2))","1/3 cup honey (or maple syrup)"]}]', '[{"description":"Cut the breasts in half horizontally to create 4 steaks in total. Sprinkle each side with salt and pepper.","images":[],"step":1},{"description":"Place flour in a shallow dish. Coat chicken in flour and shake off excess.","images":[],"step":2},{"description":"Melt most of the butter in a large skillet over high heat - hold back about 1 tsp for later.","images":[],"step":3},{"title":"Place chicken in skillet and cook for 2","description":"3 minutes until golden. Turn and cook the other side for 1 minute.","duration":2.5,"images":[],"step":4},{"description":"Turn heat down slightly to medium high.","images":[],"step":5},{"description":"Make a bit of room in the pan and add garlic and top with remaining dab of butter. Stir garlic briefly once butter melts.","images":[],"step":6},{"description":"Add vinegar, soy sauce and honey. Stir / shake pan to combine. Bring sauce to simmer, then simmer for 1 minute or until slightly thickened.","duration":1,"images":[],"step":7},{"description":"Turn chicken to coat in sauce. If the sauce gets too thick, add a touch of water and stir.","images":[],"step":8},{"description":"Remove from stove immediately. Place chicken on plates and drizzle over remaining sauce.","images":[],"step":9}]', '["gluten","milk","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","mains","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8b6d2a374fe0', 'en', 'US', 'Creamy Lemon Chicken Breast', 'Recipe video above. Cream and lemon is a luscious combination and is stellar served over crispy chicken! It''s super easy and fast to make, and the sauce is absolutely to die for. A little dusting of flour creates a terrific crispy coating on the chicken and gives the sauce something to cling to.', 'https://www.recipetineats.com/tachyon/2016/01/Creamy-Lemon-Chicken_8.jpg', 5, 10, 15, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_chicken", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_lemon", "quantity": {"value": 3.0, "unit": "net of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["600g / 1.2lb chicken breasts (2 large) (Note 1)","1/2 tsp cooking salt (kosher salt)","1/4 tsp Black pepper","1/4 cup flour (plain / all-purpose)","40g / 3 tbsp butter (, unsalted)","1 - 2 garlic clove, minced","1 1/4 cups chicken broth/stock","3/4 cup cream (, heavy/thickened (Note 2))","3 - 4 tbsp lemon juice (adjust to taste, start with 3 tbsp)","2 tsp Dijon mustard","3/4 cup parmesan cheese (, freshly grated OR store bought finely shredded (Note 3))"],"purpose":"Crispy Chicken"},{"ingredients":["Pasta of choice (I used linguine)","Finely chopped parsley"],"purpose":"To serve"}]', '[{"description":"Slice chicken breast horizontally to create two thin steaks (so you end up with 4 thin steaks in total).","images":[],"step":1},{"description":"Sprinkle each side with salt and pepper, then coat with flour, shaking off excess.","images":[],"step":2},{"description":"Melt butter in a large skillet over medium high heat. Cook chicken 2 minutes on each side until golden and crispy, then remove onto plate.","images":[],"step":3},{"title":"Add a touch of butter if your pan is dry","description":"but you shouldn''t need it. Add garlic, stir 10 seconds.","images":[],"step":4},{"description":"Then add chicken broth, cream, lemon and Dijon mustard. Bring to simmer and scrape the bottom of the pan to dissolve brown bits into the liquid. Use a whisk if needed to dissolve mustard.","images":[],"step":5},{"description":"Add parmesan then simmer rapidly for 3 minutes or until sauce thickens slightly. Add salt, pepper and adjust lemon to taste.","duration":3,"images":[],"step":6},{"description":"Return the chicken to the pan (pour in any juices on the plate too), turn to coat.","images":[],"step":7},{"description":"Place chicken on serving plates with pasta or mashed potatoes. Sprinkle with fresh parsley if using. Spoon over Lemon Sauce and serve! (Bread for mopping wouldn''t go astray either)","images":[],"step":8}]', '["gluten","milk","mustard"]', '["high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fa2342ba401a', 'en', 'US', 'Baked Fish with Lemon Cream Sauce (One Baking Dish!)', 'Recipe video above. A fantastic quick-fix dinner - baked fish in a lemon cream sauce, all made in ONE PAN! Don''t let the short ingredient list fool you, this tastes so good! The key to the tasty sauce is the fish juices that leeches out while baking and is essentially the broth for the sauce!', 'https://www.recipetineats.com/tachyon/2016/10/Baked-Fish-with-Lemon-Cream-Sauce_9.jpg', 5, 10, 15, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.25, "unit": "carton of 250ml"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 22.5, "unit": "pack of 1kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4 x 150- 180g / 5 - 6 oz fish fillets (, about 1.5cm / 1/2\" thick, skinless and boneless (Note 1))","50g / 4 tbsp unsalted butter","1/4 cup cream, heavy / thickened (See Note 2 for sub options)","1 - 2 garlic cloves (, minced)","1 tbsp Dijon mustard","1 1/2 tbsp lemon juice","Salt & pepper","1 1/2 tbsp eschallots (French onion) (, finely chopped (Note 3))","Fresh parsley and lemon slices (, to serve)"]}]', '[{"description":"Preheat oven to 200°C / 390°F (all oven types).","images":[],"step":1},{"title":"Place fish in a baking dish","description":"ensure the fish isn''t crammed in too snugly. See video or photos in post. Sprinkle both sides of fish with salt and pepper.","images":[],"step":2},{"description":"Place butter, cream, garlic, mustard, lemon juice, salt and pepper in a microwave proof jug or bowl. Microwave in 2 x 30 sec bursts, stirring in between, until melted and smooth.","images":[],"step":3},{"description":"Sprinkle fish with shallots, then pour over sauce.","images":[],"step":4},{"title":"Bake for 10","description":"12 minutes, or until fish is just cooked. Remove from oven and transfer fish to serving plates. Spoon over sauce, and garnish with parsley and lemon wedges if using.","duration":11,"images":[],"step":5}]', '["fish","milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","easter-mains-fish-seafood","emergency-recipes","fish-recipes","low-calorie-recipes","main-dishes","most-popular","one-pot-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_338eae1fe368', 'en', 'US', 'Chow Mein Ramen Noodles', 'Recipe video above. The fastest, easiest Chow Mein recipe ever! Made using a couple of cheeky shortcuts - ramen noodles, a Coleslaw mix, with the noodles cooked in the same skillet. It''s a quicker version of real Chow Mein - 99% of the flavour, but FASTER!', 'https://www.recipetineats.com/tachyon/2019/06/Chow-Mein-Ramen_3.jpg', 7, 8, 15, 2, '[{"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_chicken", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 2.0, "unit": "pack of 500g"}}, {"id": "ing_pre_shedded_coleslaw_mix", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}, {"id": "ing_heaped_cup_beansprouts", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 tbsp oil","200g/7oz chicken (, sliced (thigh, breast))","2 garlic cloves (, minced)","2 ramen or instant noodle cakes (, discard seasoning (Note 1))","200g/7oz pre shedded Coleslaw mix (, cabbage and carrot (Note 2))","3 green onion stems (, cut into 5cm/2\" lengths)","1 heaped cup beansprouts","1 cup (250 ml) water"]},{"ingredients":["1.5 tbsp light soy sauce (Note 3)","1.5 tbsp Oyster Sauce (Note 4)","1 tbsp Chinese Cooking Wine or Mirin (Note 5)","2 tsp sesame oil (, toasted (Note 6))","1 tsp white sugar (SKIP if using Mirin)"],"purpose":"Chow Mein Sauce:"}]', '[{"description":"Mix Sauce in a bowl.","images":[],"step":1},{"description":"Heat oil in a large skillet over high heat. Add garlic, cook 10 seconds.","images":[],"step":2},{"description":"Add chicken and cook until mostly changes from pink to white, then add Sauce.","images":[],"step":3},{"description":"Cook for 1 minute, then add Coleslaw mix and white part of green onions.","duration":1,"images":[],"step":4},{"description":"Cook for 1 1/2 minutes until cabbage wilts, then push everything to the side to make room for the ramen (see video & photos in post).","images":[],"step":5},{"description":"Add water then squidge the ramen cakes in side by side.","images":[],"step":6},{"description":"When water simmers, leave for 45 seconds. Flip, then leave for 30 seconds.","duration":0.75,"images":[],"step":7},{"description":"Loosen noodles, add bean sprouts and green onion, then toss energetically for 1 1/2 - 2 minutes until sauce reduces and coats noodles. (Note 7)","images":[],"step":8},{"description":"Serve immediately!","images":[],"step":9}]', '["gluten","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","dinner-tonight","emergency-recipes","noodles","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_75598a23ec49', 'en', 'US', 'Lime Marinated Grilled Chicken', 'Recipe video above. This lime marinade has a beautiful depth of flavour and really infuses the chicken with lime flavours! Touch of sugar caramelises the chicken, and depth of flavour is achieved by using soy or fish sauce instead of salt (it doesn''t taste Asiany at all, I swear!). Stove or BBQ best, but can also bake!', 'https://www.recipetineats.com/tachyon/2016/04/Lime-Chicken_2.jpg', 5, 10, 15, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 600.0, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.12, "unit": "net of 500g"}}, {"id": "ing_lime", "quantity": {"value": 0.12, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}]', '[{"ingredients":["600-750g / 1.2 - 1.5 lb chicken breasts (4 pieces) or boneless thigh ( (Note 1))","Zest of 1 lime (zest before juicing)","4 tbsp lime juice (1 - 2 limes)","2 garlic cloves (, minced)","3 tbsp brown sugar","1/4 tsp pepper","1 tbsp olive oil","2 tbsp finely chopped cilantro/coriander (optional)","1 tbsp fish sauce (OR 2 tbsp soy sauce) ( (Note 2))"],"purpose":"Chicken Marinade"},{"ingredients":["1 - 2 tbsp olive oil"],"purpose":"To Cook"}]', '[{"description":"Use fist (or rolling pin!) to pound fat end of chicken breast to about 1.7 cm / 2/3\" thickness (not required for thigh).","images":[],"step":1},{"description":"Place chicken and Marinade in a ziplock bag, massage to distribute marinade evenly. Place on a plate or bowl and refrigerate for 24 hours (min 12 hrs, max 48 hrs - Note 3)","images":[],"step":2},{"description":"Remove chicken, discard Marinade. Cook using one method below.","images":[],"step":3},{"description":"To Cook (cooked internal temp 165F/75C)","images":[],"step":4},{"title":"STOVE","description":"Heat oil in a large skillet over medium high heat. Cook chicken for 3 minutes on each side or until caramelised and golden brown (see video!).","duration":3,"images":[],"step":5},{"title":"BBQ","description":"Brush grills with oil and heat to medium high (or medium if your BBQ is strong). Cook chicken for 3 minutes on each side until caramelised (see video!).","duration":3,"images":[],"step":6},{"title":"OVEN","description":"Preheat oven to 425F/220C. Bake 15 minutes, then flick broiler/grill on high and grill for 3 minutes to caramelise surface & finish cooking.","duration":3,"images":[],"step":7},{"description":"Rest and Serve:","images":[],"step":8},{"description":"Transfer chicken to a serving plate, cover loosely with foil and rest for 3 minutes.","duration":3,"images":[],"step":9},{"description":"Garnish with extra coriander/cilantro, lime wedges and chilli if desired, then serve!","images":[],"step":10}]', '["fish","gluten","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","grilling-ideas-and-recipes","low-calorie-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_625457ad8802', 'en', 'US', 'Asian Beef Bowls', 'Recipe VIDEO above. A fabulous quick stir fry made using beef mince (ground beef) <<-- No slicing meat! It''s not saucy like usual stir fries, you don''t need sauce because the beef mixes through the rice, and it has plenty of flavour and it''s JUICY. Great recipe to add diced or julienned veggies!', 'https://www.recipetineats.com/tachyon/2017/05/Asian-beef-Bowls.jpg', 5, 7, 12, 4, '[{"id": "ing_hoisin_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.15, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 2.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 tbsp Hoisin Sauce (or sub with Oyster)","2 tbsp Oyster Sauce (or sub with 1 1/2 tbsp Hoisin)","1 tbsp Chinese cooking wine (or Mirin, dry sherry, sake or any rice wine) (Note 1)","2 1/2 tbsp dark soy sauce (Note 2)","2 tsp white sugar","1/2 tsp sesame oil","1/4 tsp white pepper (or sub with black)"],"purpose":"Sauce:"},{"ingredients":["1 tbsp oil","2 garlic cloves, minced","1 small onion, finely chopped","500 g /1 lb beef mince (ground beef) ( (lean is good))","1/2 cup shallots / scallions (, sliced, plus more for garnish)"],"purpose":"Stir Fry:"},{"ingredients":["Sesame seeds"],"purpose":"Garnishes:"}]', '[{"description":"Mix Sauce together in a bowl","images":[],"step":1},{"description":"Heat oil in a large skillet over high heat. Add garlic and onion, cook for 1 minute or until onion starts browning.","duration":1,"images":[],"step":2},{"description":"Add beef and cook, breaking it up as you go.","images":[],"step":3},{"description":"Once the beef has all changed from red to brown, add Sauce. Cook for a further 2 minutes, or until Sauce has evaporated and beef is cooked. If you want the beef cooked more, add a splash of water and keep cooking (I don''t do this).","images":[],"step":4},{"description":"Stir through shallots, then serve over rice, garnished with more shallots and sesame seeds, if desired. Or for a low carb, low cal option, try Cauliflower Rice!","images":[],"step":5}]', '["gluten","sesame","shellfish","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","beef-mince-recipes","beef-recipes","chinese-recipes","dinner-tonight","emergency-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5d7d6ed9afef', 'en', 'US', 'Crispy Pan Fried Fish', 'Recipe video above. 3 key tips to ensure your pan fried fish comes out beautifully golden and crispy every time: pat the fish dry, press flour on well but shake excess off well, and heat the pan first before adding the oil or use a heavy duty non stick pan. With a good fish, well seasoned and crispy skin, I don''t need a sauce....but I''ve added a couple in the notes just in case! :)', 'https://www.recipetineats.com/tachyon/2017/06/Crispy-Pan-Fried-Fish-3-1.jpg', 3, 5, 8, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_oil", "quantity": {"value": 2.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 thin fish fillets, around 150g/5 oz each, 1 cm / 2/5\" thick, skin on or off (Note 1)","Salt and pepper","1/4 cup / 35g flour (plain/all purpose, wholemeal)","1 tsp paprika (, optional (Note 2))","2 - 3 tbsp oil, enough to mostly thinly cover base (I use vegetable or canola)"]},{"ingredients":["Lemon wedges","Finely chopped parsley or dill (, for garnish, optional)"],"purpose":"Garnishes:"}]', '[{"description":"Use scrunched up paper towels to pat the fish dry on both sides. This is especially important if you are using thawed frozen fish.","images":[],"step":1},{"description":"Season the fish well on both sides with salt and pepper (key!).","images":[],"step":2},{"description":"Mix the flour and paprika on a plate.","images":[],"step":3},{"description":"Coat fish on both sides with flour, pressing down firmly so it adheres, but shake well to remove excess. (Note 2)","images":[],"step":4},{"description":"Heat a heavy based skillet (normal or non stick) over medium high heat until you see wisps of smoke. Add oil and swirl to coat the pan - it will heat within seconds.","images":[],"step":5},{"title":"Add fish","description":"it should sizzle straight away. Shake the pan lightly to move the fish. Cook for 2 minutes until golden and crisp, pressing down gently, then flip. Cook the other side for 2 minutes until crisp then remove.","duration":2,"images":[],"step":6},{"description":"If it''s browning too quickly, just remove pan from the stove briefly. If it''s stuck, don''t move - it will release naturally once golden.","images":[],"step":7},{"description":"Serve fish immediately with lemon wedges and garnished with dill or parsley, if using. It starts to lose crispiness after 5 minutes.","images":[],"step":8}]', '["fish","gluten"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","fish-recipes","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1778cbc607c7', 'en', 'US', 'Quick Asian Beef Ramen Noodles', 'Recipe video above. A great quick beef ramen noodle recipe that requires very little prep, and it''s a handy one-pan recipe (no need to boil the noodles separately!). It''s a great noodle stir fry that''s family friendly - everybody loves the sweet-savoury flavour of the sauce!The flavour-trick here is to caramelise the beef well, it makes all the difference, so don''t shortcut it. Next time: try the Chicken and vegetable and Mushroom versions!', 'https://www.recipetineats.com/tachyon/2018/12/Asian-Beef-Noodles_4.jpg', 7, 8, 15, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.004, "unit": "pack of 500g"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.02, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["2 packets ramen or other instant noodles (, discard seasoning (Note 1))","1 tsp oil","2 tsp sesame oil (or more oil) (Note 2)","2 garlic cloves (, minced)","1/2 onion (, sliced)","200g / 7oz beef mince (ground beef) (Note 3)","1 1/4 cups (315 ml) water, plus more as needed","Big handful bean sprouts"]},{"ingredients":["1 tbsp dark soy sauce (Note 4)","1 tbsp Oyster sauce (or Hoisin, Note 5)","2 tsp Hoisin sauce (or more Oyster sauce)","1 tbsp mirin (Note 6)"],"purpose":"Sauce:"},{"ingredients":["Finely sliced green onion / shallots","Sesame seeds"],"purpose":"Garnishes (optional):"}]', '[{"description":"Mix Sauce.","images":[],"step":1},{"title":"Sauté onion and garlic","description":"Heat oils in a medium skillet over high heat. Add onion and garlic, cook for 1 1/2 minutes until starting to go golden.","images":[],"step":2},{"title":"Cook beef","description":"Add beef and cook, breaking it up as you go, until it changes from pink to light brown.","images":[],"step":3},{"title":"Caramelise beef","description":"Add Sauce and cook for 2 to 3 minutes until well caramelised (see video).","duration":2.5,"images":[],"step":4},{"title":"Add water and noodles","description":"Push beef to the side to make enough space for the noodles. Add water, place noodles in water.","images":[],"step":5},{"title":"Cook ramen","description":"Leave for 45 seconds then turn. Leave for 30 seconds, then untangle the noodles, then toss through the beef.","duration":0.75,"images":[],"step":6},{"description":"Add beansprouts, toss for 1 minute or until sauce reduces to coat the noodles and the noodles are cooked. (Note 7)","duration":1,"images":[],"step":7},{"description":"Serve immediately, garnished with green onions and sesame seeds.","images":[],"step":8}]', '["gluten","sesame","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","beef-mince-recipes","beef-recipes","dinner-tonight","emergency-recipes","main-dishes","noodles","one-pot-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bfa4790039a1', 'en', 'US', 'Peanut Sauce for Stir Fries', 'Recipe VIDEO above. A simple, really tasty peanut sauce to use in stir fries and noodles! Tastes like a Satay Peanut Sauce. To use, follow formula below or for full directions, use this Satay Peanut Chicken Stir Fry or this Stir Fried Noodles with Peanut Sauce recipe. Makes enough sauce for 2 - 3 people, a stir fry with rice, or stir fried noodles.', 'https://www.recipetineats.com/tachyon/2018/03/Peanut-Sauce-for-Stir-Fries_5.jpg', 5, 0, 5, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.03, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.06, "unit": "jar of 375g"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_single_batch_peanut_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_proteins", "quantity": {"value": 190.0, "unit": "unit"}}, {"id": "ing_vegetables_of_choice_as_required_and_grouped_by_cooking_time", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_double_batch_peanut_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_stir_fry_ingredients_above", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_rice_noodles", "quantity": {"value": 0.267, "unit": "pack of 375g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp fish sauce (Note 1)","1/2 tbsp dark soy sauce (Note 2)","1 1/2 tsp sugar","2 tsp cornflour / cornstarch","1 garlic clove (, minced)","1 tsp grated ginger","1 tsp curry powder (any type)","1 1/2 tbsp / 30 g crunchy peanut butter, regular (Note 1)","3 tbsp water"],"purpose":"Peanut Sauce"},{"ingredients":["1 SINGLE batch Peanut Sauce (above)","2 tbsp oil","1/2 onion, sliced","1 - 2 garlic cloves, finely chopped or minced","180- 200g / 6 - 7 oz protein of choice, sliced","3 - 4 cups vegetables of choice, chopped / sliced as required and grouped by cooking time (Note 4)"],"purpose":"Stir Fry"},{"ingredients":["DOUBLE batch Peanut Sauce (tap Servings & slide)","Stir fry ingredients above","100g / 3.5 oz dried rice noodles OR 180g/6 oz fresh noodles of choice (, prepared per packet)"],"purpose":"Noodle Stir Fry – you will need"},{"ingredients":["Finely chopped coriander / cilantro, crushed peanuts"],"purpose":"Garnish (optional):"}]', '[{"description":"Place all ingredients other than water in a bowl. Mix to combine. Then add water and mix again.","images":[],"step":1},{"description":"Heat oil in a skillet or wok over high heat. Add garlic and 1/2 sliced onion. Cook 1 minute.","images":[],"step":2},{"description":"Add protein of choice or sliced tofu. Cook 2 minutes until just cooked.","images":[],"step":3},{"description":"Add vegetables in order of time to cook, starting with the veggies that take the longer. Cook briefly until just cooked but still crisp.","images":[],"step":4},{"description":"Add delicate veggies (eg bean sprouts, spinach and other leafy greens) and Sauce. Toss until Sauce thickens (add extra water if needed).","images":[],"step":5},{"description":"Garnish with peanuts and coriander / cilantro, if using. Serve over rice - or for a low carb, low cal option, try Cauliflower Rice!","images":[],"step":6},{"description":"Follow Stir Fry directions. Add NOODLES with the Sauce in step 4.","images":[],"step":7},{"title":"Toss for 1","description":"2 minutes until Sauce thickens and coats noodles. Remove from heat, garnish and serve immediately!","duration":1.5,"images":[],"step":8}]', '["fish","gluten","peanuts","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dinner-tonight","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b0b2c3e0f4be', 'en', 'US', 'Bacon Pasta with tomato pasta sauce', 'Recipe video above. You''re just 15 minutes away from this pasta with golden crispy bacon in a garlic tomato pasta sauce! Scale recipe by hovering cursor over Servings (see Note 2).', 'https://www.recipetineats.com/tachyon/2017/05/Bacon-Tomato-Pasta-3.jpg', 5, 10, 15, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.32, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_bacon", "quantity": {"value": 150.0, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["160 g / 5 oz spaghetti or other long strand pasta of choice","1 tsp olive oil (or butter)","150 - 180 g / 5 - 6 oz bacon (, diced)","1 garlic clove (, minced)","1/2 onion (, finely diced (brown, white, yellow))","400 g / 14 oz canned crushed tomato","Salt and pepper","Pinch of sugar (, if needed (Note 1))","Extra virgin olive oil","Finely chopped parsley"]}]', '[{"description":"Have the ingredients lined up and ready to start cooking at the same time.","images":[],"step":1},{"description":"Bring a large pot of water to the bowl. Add a pinch of salt. Cook pasta according to packet but MINUS 2 minutes.","images":[],"step":2},{"description":"Meanwhile, heat oil in a skillet over high heat. Add bacon and cook for 1 minute, then add garlic and onion and cook for 3 minutes or until onion is translucent and bacon is golden. Drain excess fat if desired.","duration":1,"images":[],"step":3},{"description":"Scoop out a mug of pasta cooking water, then pour about 1/2 cup into the skillet. Bring to simmer and stir, scraping the skillet to dissolve in all the golden bits stuck on the pan into the liquid.","images":[],"step":4},{"description":"Add tomato, bring to simmer and cook for 2 minutes, then turn down to medium high.","duration":2,"images":[],"step":5},{"description":"Drain pasta, or if you timed it right, use tongs to transfer it straight from the pot into the skillet.","images":[],"step":6},{"description":"Toss gently using two wooden spoons for 2 minutes, or until the sauce is no longer sitting in the skillet, it''s all on the pasta (see video). If it gets too thick, just add an extra splash of the pasta cooking water.","duration":2,"images":[],"step":7},{"description":"Season with salt and pepper (remember bacon is salty!).","images":[],"step":8},{"description":"Serve immediately, garnished with parmesan, parsley and final drizzle of olive oil if desired.","images":[],"step":9}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["dinner-tonight","italian-recipes","main-dishes","pasta-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5b92238318f5', 'en', 'US', 'One Pot Chicken Alfredo Pasta', 'Recipe video above. Pasta in a silky, creamy sauce with tender, juicy chicken, all made in ONE POT! (Well, pan:) )', 'https://www.recipetineats.com/tachyon/2017/03/One-Pot-Chicken-Alfredo-2.jpg', 2, 13, 15, 3, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["200 g / 7oz chicken breast, cut in half horizontally","Salt and pepper","1 tbsp olive oil","250 g / 8 oz fettuccine","2 cups milk, any fat %","1 1/2 cups chicken stock / broth","1 large garlic clove, minced","1/2 cup thickened / heavy cream (Note 1)","3/4 cup freshly grated parmesan (Note 2)","Parsley, for garnish"]}]', '[{"description":"Sprinkle both sides of the chicken with salt and pepper.","images":[],"step":1},{"description":"Use a skillet large enough to fit the pasta.","images":[],"step":2},{"description":"Heat oil over medium high heat. Add chicken and cook for 2 minutes on each side until golden and cooked through. Remove onto plate and rest for 5 minutes, then slice while pasta is cooking.","duration":2,"images":[],"step":3},{"description":"Add milk, chicken broth and garlic. Bring to simmer then add pasta.","images":[],"step":4},{"description":"Move pasta around every 30 seconds or so until it is softened (around 3 minutes) so it doesn''t stick. Once pasta is softened, reduce heat to medium and stir every couple of minutes.","images":[],"step":5},{"title":"At about 9","description":"10 minutes, the pasta should be almost cooked but there should still be liquid covering the base of the skillet. Add cream and parmesan and mix.","images":[],"step":6},{"description":"Simmer, stirring occasionally, for ~2 minutes, until sauce is thickened and pasta is cooked. If you cook it too long and the sauce goes gluggy, add a splash of hot tap water - will go back to silky with a few tosses.","images":[],"step":7},{"description":"Adjust salt and pepper to taste and serve immediately, garnished with freshly grated parmesan and parsley!","images":[],"step":8}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","italian-recipes","main-dishes","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bbe82b35b97c', 'en', 'US', 'Asian Steak', 'An incredible Asian Steak recipe, with a simple yet stunning sauce inspired by the great Tetsuya, a highly regarded Japanese-Australian chef. Make this with small pieces of high quality beef steak! See notes for my tips on FREEZING rice - so handy to have on standby for quick meals!', 'https://www.recipetineats.com/tachyon/2017/03/Asian-Steak-3.jpg', 5, 10, 15, 2, '[{"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_cooking_sake", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 45.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["2 beef tenderloin steaks, around 150g/5oz each (Note 1)","1 tbsp vegetable oil (or other neutral cooking oil)"]},{"ingredients":["1 tbsp soy sauce, all purpose (Note 2)","2 tbsp Mirin (Note 3)","3 tbsp cooking sake (Note 3)","45g/3tbsp unsalted butter","1 small garlic clove, minced","1/2 tsp ginger, minced (can exclude)","3 tsp shallots/scallions (green part) or chives, finely chopped"],"purpose":"Sauce"}]', '[{"description":"Take the steak out of the fridge 20 minutes prior to cooking (or 10 minutes if it''s a stinking hot summer day).","images":[],"step":1},{"description":"Combine soy sauce, Mirin and sake in a small bowl.","images":[],"step":2},{"description":"Heat oil in a skillet over medium high heat until smoking. Add steak and cook to your liking. Mine were 150g/5oz each and 3cm/1.25\" thick and I cooked it 3 minutes on the 1st side and 2 minutes on the second side for medium rare.","images":[],"step":3},{"description":"Transfer steak onto a plate and cover loosely with foil. Rest for 5 minutes.","duration":5,"images":[],"step":4},{"description":"Let the skillet cool down a bit then return to the stove over medium high heat. Add Sauce and bring to simmer, then add butter. When the butter melts and is incorporated into the sauce, immediately remove it from the stove.","images":[],"step":5},{"description":"Stir through garlic, ginger and 2 tsp of shallots (reserve rest for garnish), the sauce should be slightly thickened (if not, keep stirring, thickens more as it cools).","images":[],"step":6},{"description":"Place steak on plates and spoon over sauce. I served the steaks with finely shredded cabbage without dressing (very typical Japanese side) and white rice, plus some edamame on the side.","images":[],"step":7}]', '["gluten","milk","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","beef-recipes","modern-asian","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a138b4e67631', 'en', 'US', 'Beef Soba Noodle Bowl with Green Beans', 'A fusion Japanese soba noodle dish with an amazing dressing that matches perfectly with the juicy steak slices and for slurping up the soba noodles. Fantastic quick meal for hot summer nights!', 'https://www.recipetineats.com/tachyon/2017/03/Beef-Bean-and-Soba-Bowls.jpg', 5, 10, 15, 2, '[{"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_soba", "quantity": {"value": 170.1, "unit": "pack"}}, {"id": "ing_green_beans_trimmed", "quantity": {"value": 170.1, "unit": "pack"}}, {"id": "ing_green_onion", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["1 1/2 tbsp soy sauce, light or ordinary (Note 1)","2 1/2 tbsp peanut oil","3 tbsp rice vinegar (Note 2)","1 tbsp mirin (Note 3)","2 tsp brown sugar","2 tsp ginger, minced","1 clove garlic, minced"],"purpose":"Dressing"},{"ingredients":["200g/7 oz rump or sirloin beef steak, excess fat trimmed (Note 4)","1 tsp vegetable oil","6oz/180g soba (Note 5)","6oz/200g green beans, trimmed","1 scallion/shallot, finely sliced","1 tbsp crispy Asian Shallots (Note 6)"],"purpose":"Steak"}]', '[{"description":"Take the steak out of the fridge 30 minutes prior to cooking (or 15 minutes if it''s a stinking hot summer day).","images":[],"step":1},{"description":"Combine dressing ingredients in a jar and shake.","images":[],"step":2},{"description":"Heat the oil in a skillet over high heat until smoking, then cook the steak to your liking. I like mine medium rare - perfect for absorbing the flavours of the delicious dressing - so I cook this rump steak for 2 minutes on the first side and 1 minute 45 seconds on the second side.","duration":2,"images":[],"step":3},{"description":"Transfer to a plate and loosely cover with foil. Rest for 5 minutes, then slice into fairly thin slices against the grain (i.e. find the direction of the fibres then cut at a 90 degree angle straight through them).","duration":5,"images":[],"step":4},{"description":"Meanwhile, bring a pot of water to boil. Cook the soba according to packet instructions (usually 5 minutes). For the last 1 minute of cooking, add the green beans.","images":[],"step":5},{"description":"Drain the noodles and beans and rinse under cold water to stop them from cooking further and to cool the noodles. Roughly separate beans from noodles.","images":[],"step":6},{"description":"To serve, divide the noodles between 2 bowls, top with the beans then the steak slices. Drizzle with the dressing (over the steak and noodles), then garnish with shallot slices and Crispy Asian Shallots.","images":[],"step":7}]', '["gluten","peanuts","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","beef-recipes","dinner-tonight","main-dishes","modern-asian","noodles","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_35f1ebeeecf3', 'en', 'US', 'Chinese Pork with Noodles ("Chinese Bolognese")', 'Don''t be put off by the Asian speciality sauces, this is one of those recipes that still works GREAT using the substitutions. Some people may even prefer it made with the subs! . The proper name for this stir fried pork with noodles is "Zha Jiang Mian" noodles and is also affectionally referred to as "Chinese Bolognese". Minced / ground pork is stir fried with tasty classic Chinese flavours that are savoury with a touch of spice and sweet. Recipe video is below recipe.', 'https://www.recipetineats.com/tachyon/2016/12/Chinese-Pork-and-Noodles-7.jpg', 10, 10, 20, 3, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 700.0, "unit": "pack of 500g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_vinegar", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_chinese_sweet_bean_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_pork", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["700 - 800 g / 1.4 - 1.6 lb white noodles (flour noodles), fresh (Note 1)","2 tsp vegetable oil*","2 tsp Chinese black vinegar (Chinkiang vinegar)* (Note 2)"],"purpose":"Noodles"},{"ingredients":["1/3 cup chicken stock / broth","1 tbsp Chilli Bean Sauce (Note 3)","1 tbsp Chinese Sweet Bean Sauce (Note 4)","1 tbsp dark soy sauce (Note 5)","2 tsp Chinese black vinegar (Chinkiang vinegar)* (Note 2)","1 tsp sugar (white or brown)"],"purpose":"Sauce"},{"ingredients":["1 tbsp vegetable oil","2 garlic cloves (, minced)","1 1/2 tsp ginger (, minced or finely chopped)","1/2 onion (, finely chopped (white, brown or yellow))","400 g / 14 oz minced pork (ground pork)"],"purpose":"Stir Fry"},{"ingredients":["2 cucumbers (, cut into batons (deseed if you can be bothered, I don''t!))","Chinese chilli sauce (Note 6)","Coriander / cilantro leaves"],"purpose":"To Serve"}]', '[{"description":"Mix Sauce ingredients together.","images":[],"step":1},{"description":"Prepare noodles according to packet directions. If it says to soak the noodles, you can do that while cooking the stir fry.","images":[],"step":2},{"title":"Optional","description":"Just before serving, toss the noodles with oil and vinegar.*","images":[],"step":3},{"description":"Heat oil in a wok or skillet over medium high heat. Add onions and cook for 1 minute. Add garlic and ginger and cook for 1 minute or until onion is translucent.","duration":1,"images":[],"step":4},{"description":"Add pork and cook, breaking it up as you go, until browned.","images":[],"step":5},{"title":"Add sauce and cook for 3","description":"5 minutes, or until most of the sauce has reduced.","duration":4,"images":[],"step":6},{"description":"Divide noodles between bowls. Top with pork, coriander and fresh cucumbers on the side.","images":[],"step":7},{"description":"To eat, mix up the noodles and pork. I use chopsticks and a spoon - so it''s easier to get the pork and noodles in one mouthful. Don''t hold back on the chilli paste! It goes great with this dish!","images":[],"step":8}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","chinese-recipes","dinner-tonight","main-dishes","noodles","pork-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f61e271fd51a', 'en', 'US', 'Spicy Thai Chicken Stir Fry', 'The Thai stir fry sauce used in this recipe is a fantastic versatile stir fry sauce! It''s similar to many well known Thai stir fries like Pad See Ew, Thai Chilli Basil Chicken and Drunken Noodles (Pad Kee Mao). Make this using ground/mince chicken, pork or turkey. See notes for how to use this sauce for other stir fries. Ensure all ingredients are ready to toss into the wok before you start cooking because once you start, it cooks fast!', 'https://www.recipetineats.com/tachyon/2016/11/Spicy-Thai-Chicken-Stir-Fry_4.jpg', 7, 8, 15, 3, '[{"id": "ing_light_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 tsp light soy sauce (Note 1)","1 tsp dark soy sauce (Note 1)","2 tsp fish sauce","1 tbsp oyster sauce","1 tsp sugar"],"purpose":"Sauce"},{"ingredients":["2 tbsp cooking oil (I use peanut or vegetable oil)","3 Thai or birds eye chillis or other small hot red chilli (, finely chopped (Note 2))","4 garlic cloves (, finely chopped)","1 small onion (, halved and sliced (brown, white or yellow))","500 g / 1 lb ground / mince chicken","3 shallot / scallions stems (, chopped into slices)","1 cup coriander/cilantro leaves (loosely packed)"],"purpose":"Stir Fry"},{"ingredients":["Steamed jasmine rice"],"purpose":"Serving"}]', '[{"description":"Mix Sauce ingredients in a small bowl.","images":[],"step":1},{"description":"Heat oil in a wok or heavy based skillet over high heat. Add garlic and chilli - cook for 15 seconds.","duration":0.25,"images":[],"step":2},{"description":"Add onion and cook for 45 seconds.","duration":0.75,"images":[],"step":3},{"description":"Add chicken and cook, breaking it up as you go. When it changes from pink to white, add Sauce. Cook until the liquid mostly disappears - about 2 minutes.","images":[],"step":4},{"description":"Stir through shallots. Then stir through coriander and immediately take off the heat.","images":[],"step":5},{"title":"Serve immediately with jasmine rice or other rice","description":"or for a low carb, low cal option, try Cauliflower Rice! Add slices of cucumber and tomato wedges (very authentic Thai!). Garnish with extra chilli and coriander if desired.","images":[],"step":6}]', '["fish","gluten","peanuts","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","chicken-breast-recipes","chicken-mince-recipes","chicken-recipes","cuisines","dinner-tonight","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","stir-fries","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d1e50df8d1cc', 'en', 'US', 'Lemon Pepper Chicken', 'A homemade version of lemon pepper chicken made without store-bought lemon pepper seasoning. It tastes incredible - fresh, fragrant with lovely pops of heat from the pepper. No marinating time required. Great for pork and seafood too! RECIPE VIDEO BELOW.', 'https://www.recipetineats.com/tachyon/2016/10/Lemon-Pepper-Chicken_5.jpg', 10, 5, 15, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 4.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.25, "unit": "jar of 50g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 chicken breasts (~250 - 300g / 8 - 10oz each)","2 lemons (Note 1)","1 tbsp olive oil","3 tbsp flour","1/2 - 3/4 tsp salt","2 1/2 tsp cracked black pepper (adjust to taste) (Note 2)","1/2 tsp garlic powder (or sub with onion powder) (Note 3)"]},{"ingredients":["1 tbsp olive oil","Fresh parsley (, for garnish)"],"purpose":"Cooking"}]', '[{"description":"Cut the chicken in half horizontally to make 2 steaks. Optional: pound to make them even thickness around 1cm / 2/5\" thick (I do this).","images":[],"step":1},{"title":"Zest the lemons to make 1 1/2","description":"2 tbsp lemon zest. Avoid grating too much of the white part - it''s bitter.","images":[],"step":2},{"description":"Place zest into bowl with 1 tbsp olive oil and mix to combine. Add chicken and use your hands to slather oil mixture onto chicken.","images":[],"step":3},{"description":"Mix flour, salt, pepper and garlic powder in a shallow bowl.","images":[],"step":4},{"description":"Dip chicken into flour mixture, shaking to remove excess.","images":[],"step":5},{"description":"Heat oil in a skillet over medium high heat. Cook chicken for 2 minutes on each side, or until golden.","duration":2,"images":[],"step":6},{"title":"Optional","description":"Slice zested lemon and cook the slices, like pictured.","images":[],"step":7},{"description":"Serve chicken, garnished with fresh parsley if using.","images":[],"step":8}]', '["gluten"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","low-calorie-recipes","main-dishes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_33ef46acfc29', 'en', 'US', 'Creamy Dill Sauce with Salmon or Trout', 'A fantastic quick meal! Dill Sauce is refreshing, rather than heavy as many "creamy" sauces can be, because it is made with sour cream. The slight acidity is a great pairing with salmon or trout which are quite rich and oily. I made this with trout.', 'https://www.recipetineats.com/tachyon/2016/09/Creamy-Dill-Sauce-with-Salmon_5.jpg', 10, 5, 15, 4, '[{"id": "ing_sour_cream", "quantity": {"value": 0.45, "unit": "tub of 250g"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_dill", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_milk", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["3/4 cup sour cream (1)","2 tsp Dijon or hot English mustard (2)","1/2 tsp garlic powder or 1 small garlic clove (, minced)","2 1/2 tbsp fresh dill (, finely chopped)","1 tsp lemon zest","1 - 2 tbsp lemon juice","2 tbsp milk (or olive oil, for richness)","1/4 - 1/2 tsp salt","1/2 tsp white sugar"],"purpose":"Dill Sauce"},{"ingredients":["1/2 - 1 tbsp oil","4 salmon or trout fillets (125g / 4oz each)","Salt and pepper"],"purpose":"Fish"}]', '[{"description":"Mix the Dill Sauce ingredients together (Mix well to loosen the sour cream). Adjust consistency with milk and tartness with lemon juice. Set aside for 10 minutes if you can - if using fresh garlic, set aside for 20 min.","duration":10,"images":[],"step":1},{"description":"Pat fish dry with paper towel. Sprinkle with salt and pepper.","images":[],"step":2},{"description":"Heat oil in skillet over medium high heat. Place fish in skillet skin side down. Cook for 2 minutes, then flip and cook the other side for 1 1/2 minutes.","duration":2,"images":[],"step":3},{"description":"Remove from skillet onto serving plates. Serve with Dill Sauce on the side, garnished with fresh dill and lemon wedges if desired.","images":[],"step":4}]', '["fish","milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","dinner-tonight","easter-mains-fish-seafood","easter-recipes","fish-recipes","gluten-free-recipes","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_867c1d0de072', 'en', 'US', 'Honey Lemon Chicken', 'Succulent chicken with a lip smacking honey-lemon sauce. Dinner in a snap - 5 minutes prep, 4 minutes to cook the chicken, 3 minutes for the sauce = 12 minute dinner! Dusting the chicken in flour makes the skin slightly crispy which makes the sauce cling to it. Recipe VIDEO below!', 'https://www.recipetineats.com/tachyon/2016/03/Honey-Lemon-Chicken_2.jpg', 5, 7, 12, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_chicken", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_honey", "quantity": {"value": 0.125, "unit": "jar of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.075, "unit": "net of 500g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.075, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 lb / 500g chicken breast (2 pieces)","Salt and pepper","1/4 cup / 35 g flour (any)"],"purpose":"Chicken"},{"ingredients":["1 1/2 tbsp butter","1 tbsp olive oil","1 garlic clove, minced","3/4 cup / 185 ml chicken broth / stock","1/4 cup / 85g honey","1/4 cup / 60 ml lemon juice (fresh)","1 tsp soy sauce","2 tbsp water"],"purpose":"Sauce"},{"ingredients":["Lemon slices","Finely chopped parsley"],"purpose":"To serve (optional)"}]', '[{"description":"Slice each chicken breast horizontally to form 4 steaks in total. OPTIONAL (for more even cooking): Pound to even thickness about 1cm/ 2/5\" thick.","images":[],"step":1},{"description":"Sprinkle each side generously with salt and pepper.","images":[],"step":2},{"description":"Place flour in shallow dish. Coat the chicken in the flour, shaking off excess.","images":[],"step":3},{"description":"Mix 1 tsp of the flour (reserved from step 3) with the water. Set aside.","images":[],"step":4},{"description":"Cooking","images":[],"step":5},{"description":"Place butter and oil in a skillet over medium high heat until butter is melted and hot. Add chicken and cook for 2 minutes or until golden brown. Turn and cook the other side until golden brown, then transfer onto a plate to rest.","duration":2,"images":[],"step":6},{"description":"Add garlic into the skillet and stir for 20 seconds or until golden. Add chicken broth / stock and bring to simmer. Use a spatula to scrape the brown bits from the bottom of the pan into the liquid.","duration":0.3333333333333333,"images":[],"step":7},{"description":"Add honey, lemon juice, soy sauce and flour/water mixture (from step 4) into the skillet. Mix and bring to simmer for 2 to 3 minutes until thickened into a syrup. Add salt and pepper to taste.","duration":2.5,"images":[],"step":8},{"description":"To serve, pour Sauce over the chicken and garnish with parsley and lemon slices if using. Alternatively, return the chicken to the pan for 30 seconds (to reheat), turning to coat in the sauce.","duration":0.5,"images":[],"step":9}]', '["gluten","milk","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","low-calorie-recipes","main-dishes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0b62b8259ea8', 'en', 'US', 'Creamy Salmon Risoni / Orzo (15 Minute Meal)', 'A creamy risoni dinner in a flash! Get the ingredients out on the bench and it will take just 15 minutes to get this on the table. Watch the video to see how easy it is!', 'https://www.recipetineats.com/tachyon/2016/03/Creamy-Salmon-Risoni-Orzo_2.jpg', 5, 10, 15, 4, '[{"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.338, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.45, "unit": "pack of 500g"}}, {"id": "ing_frozen_peas", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_salmon_fillets", "quantity": {"value": 0.17, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1.5 oz / 40g / 3 tbsp unsalted butter","1/2 onion (, diced (brown, white, yellow))","2 garlic cloves (, minced)","1 tbsp plain flour","2 cups milk (light or full fat)","2 1/4 cups chicken broth / stock","1 1/2 cups dried risoni / orzo (Note 1)","2 cups frozen peas","1/2 cup grated parmesan","6 oz / 185 g hot-smoked salmon (, flaked into large chunks using 2 forks)","Parsley (, chopped, to garnish)"]}]', '[{"description":"Melt butter in a deep skillet or pot over medium high heat.","images":[],"step":1},{"description":"Add onion and garlic, cook for 2 minutes until translucent.","duration":2,"images":[],"step":2},{"description":"Add flour and cook for 1 minute.","duration":1,"images":[],"step":3},{"description":"Switch to a whisk and add half the milk. Whisk to dissolve the pasty onion mixture into the milk (about 20 seconds). Then add remaining milk, chicken broth, risoni and peas.","images":[],"step":4},{"description":"Bring to simmer then turn heat down to medium so it bubbles gently. Cook for 5 minutes - stir occasionally for the first half then more frequently during the second half.","duration":5,"images":[],"step":5},{"title":"At 5 minutes, take it off the stove","description":"it will still be quite saucy (see video) but will reduce in the next steps and while serving.","images":[],"step":6},{"description":"Stir through parmesan cheese, salt and pepper to taste. Then gently stir through salmon.","images":[],"step":7},{"description":"Serve immediately, sprinkled with parsley leaves if desired.","images":[],"step":8}]', '["fish","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dinner-tonight","fish-recipes","main-dishes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","salmon-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9e8a6628d37f', 'en', 'US', 'Fish with Spicy Salsa', 'Super fast to prepare, this is a light, fresh, healthy dinner that''s a satisfying meal for less than 500 calories. By setting the salsa aside, it sweats and the juices become the "sauce" for this recipe without the need to use tons of oil! I made this spicy - Salsa Picante (which means spicy) - but you can just as just omit the chili if you prefer! I added eggplant slices to fill this out, add nutrition and interest to the dish - but this is optional.', 'https://www.recipetineats.com/tachyon/2016/03/Italian-Fish-Spicy-Salsa_4.jpg', 5, 10, 15, 2, '[{"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_basil", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 6.0, "unit": "carton of 12"}}, {"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_bread", "quantity": {"value": 0.2, "unit": "loaf"}}]', '[{"ingredients":["2 ripe tomatoes (, deseeded and diced (Note 1))","1/2 tsp fresh chili (, finely chopped (or 1/4 tsp red pepper flakes))","2 tsp extra virgin olive oil","1/4 tsp salt","Black pepper","1/4 cup , packed, basil leaves"],"purpose":"Spicy Salsa"},{"ingredients":["6 slices eggplant (, 1cm / 1/2\" thick)","2 x 150g / 5oz fish fillets (I used perch)","Salt and pepper","1 tbsp plain flour","1 tbsp oil"],"purpose":"Fish"},{"ingredients":["4 slices sourdough bread (, toasted)"],"purpose":"To Serve"}]', '[{"description":"Combine the Spicy Salsa ingredients except basil in a bowl. Set aside for 20 minutes to sweat so juices seep and the tomatoes soften.","duration":20,"images":[],"step":1},{"description":"Season eggplant and fish generously with salt and pepper. Then dust fish with flour, shaking off excess.","images":[],"step":2},{"description":"Heat 1/2 tbsp oil in a non stick skillet over high heat. Add the eggplant and cook each side until charred and softened - about 2 minutes first side, 1 1/2 minutes second side. Remove onto a plate.","images":[],"step":3},{"description":"Heat remaining oil. Add fish and cook until light golden on both sides, pressing down with an egg flip to brown it evenly.","images":[],"step":4},{"description":"Tear basil leaves with your hands and toss through the salsa.","images":[],"step":5},{"description":"To serve, place 3 eggplants on each plate, top with a piece of fish and spoon over the salsa + juices. Serve with toasted sourdough on the side.","images":[],"step":6}]', '["fish","gluten"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["dietary","dinner-tonight","fish-recipes","italian-recipes","low-calorie-recipes","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e04cc7b5370c', 'en', 'US', 'Cajun Blackened Fish {+ Video}', '"Blackening" is a classic Cajun cooking technique which involves searing spice coated seafood and meats in a hot skillet so the rub turns black (but not burnt). I think the black crust and white juicy flesh inside looks so stunning! I served this with a simple Corn Butter Rice Salad - refer to the Notes for the recipe. This is adapted from this Blackened Fish Tacos recipe, a guest post here on RecipeTin Eats by Kathleen of Hapa Nom Nom. Watch the video on my YouTube Channel!', 'https://www.recipetineats.com/tachyon/2016/02/Cajun-Blackened-Fish_3.jpg', 5, 5, 10, 4, '[{"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["1 tbsp paprika","1 tsp ground cumin","1 tsp onion powder","1 tsp garlic powder","1 tsp dried thyme","1 tsp dry mustard","3/4 tsp salt (table salt)","1/8 tsp cayenne pepper (or to taste)","Good grind of black pepper"],"purpose":"Spice Mix"},{"ingredients":["4 firm white fish fillets (about 150g/5oz each) (Note 1)","2 tbsp extra virgin olive oil"],"purpose":"To Cook"}]', '[{"description":"Combine Spice Mix in a shallow dish and mix.","images":[],"step":1},{"description":"Coat both sides of the fish fillets with the Spice Mix, shaking off excess.","images":[],"step":2},{"description":"Heat oil in a large heavy based skillet over medium high heat.","images":[],"step":3},{"description":"Add fish and cook until the rub turns black, then flip and cook the other side until the fish is cooked to your taste. (Note 2)","images":[],"step":4},{"description":"Serve immediately. I served mine with a buttery Corn Rice Salad - refer to the Notes for the recipe.","images":[],"step":5}]', '["fish","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Cajun"],"categories":["dietary","dinner-tonight","fish-recipes","gluten-free-recipes","grilling-ideas-and-recipes","low-calorie-recipes","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_592f9a715eb2', 'en', 'US', 'Grilled Eggplant with Yoghurt Sauce', 'This is adapted from a recipe by Karen Martini, a great Australian chef. Simple to make and so incredibly delicious. A "meaty" meat free dish for carnivores! I have noted where I strayed from the original recipe. This serves 3 to 4 as a light meal (accompanied with, for example, couscous), or 6 to 8 as a side.', 'https://www.recipetineats.com/tachyon/2015/01/DSC_0489.jpg', 8, 7, 15, 3, '[{"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_tahini", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pomegranate", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_mint", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["3 large eggplants","1/4 cup olive oil","Salt and pepper"],"purpose":"Grilled Eggplant"},{"ingredients":["1 cup plain unsweetened yoghurt (Greek or natural)","1 garlic clove (, minced (Medium size. 1 large clove will make it too garlicky))","1 tsp cumin powder (Note 1)","1 to 2 tbsp fresh lemon juice (use amount to taste) (Note 2)","2 tbsp tahini (sesame paste) (you can leave this out if you don''t have it, it is still a tasty sauce)","1/4 tsp salt (, slightly heaped (about 3/8 tsp))","Black pepper"],"purpose":"Yoghurt Sauce"},{"ingredients":["1/2 pomegranate (, seeds only (Note 3))","2 tbsp mint leaves (, finely sliced)","2 tbsp coriander / cilantro leaves","Red chilli (, finely sliced (to taste) (Note 4))","Wedges or cheeks of lemon (optional)"],"purpose":"Garnish"}]', '[{"description":"Combine the Yoghurt Sauce ingredients in a bowl and mix well. Set aside for the flavours to develop. The longer you leave it, the better it will taste.","images":[],"step":1},{"description":"Use a potato peeler to peel \"strips\" off the eggplant vertically as per the photo below. If your potato peeler is not sharp enough or if the eggplant is on the soft side, you might need to do this with a small sharp knife.","images":[],"step":2},{"description":"Cut the eggplant into 1.5cm / 2/3\" thick rounds.","images":[],"step":3},{"description":"Brush one side of each eggplant with olive oil. The more you use, the yummier it will be!","images":[],"step":4},{"description":"Sprinkle the oiled side of the eggplant with salt and pepper.","images":[],"step":5},{"description":"Heat a griddle pan (or BBQ) on medium high heat. (Note 5)","images":[],"step":6},{"description":"Place the oiled side of each eggplant onto the pan and grill for 2 to 3 minutes until it gets deep char lines on it. While the first side is cooking, brush the other side of each eggplant with the remaining olive oil and sprinkle with salt and pepper.","duration":2.5,"images":[],"step":7},{"description":"Turn the eggplant and cook the other side until the eggplant is cooked through but still holding it''s shape. The easy way to tell is to prod the centre - if you feel resistance, it needs to cook more.","images":[],"step":8},{"description":"Remove the eggplant onto a serving plate and let it cool for a few minutes. Then spoon a dollop of the yoghurt sauce on each, and scatter with coriander/cilantro, mint, pomegranate seeds and chili. Drizzle with extra olive oil and serve with cheeks or wedges of lemon, if desired.","images":[],"step":9}]', '["milk","sesame"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Contemporary Middle Eastern"],"categories":["all-vegetable-sides","cuisines","dietary","easter-sides-warm-hearty","eggplant","gluten-free-recipes","grilling-ideas-and-recipes","middle-eastern-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3efd06e449ae', 'en', 'US', 'Super Quick Chicken Dinner: Crumbed Chicken with Mashed Potatoes', 'With few clever shortcuts and a bit of multi tasking, you''ll get this complete dinner on the table in 15 minutes. The crunchy crumbed chicken is sensational. The secret is mayonnaise which is used to make the panko breadcrumbs stick to the chicken, plus it provides the seasoning.', 'https://www.recipetineats.com/tachyon/2014/12/Fast-Crumbed-Chicken-1.jpg', 5, 10, 15, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.15, "unit": "jar of 400g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}, {"id": "ing_bread", "quantity": {"value": 0.113, "unit": "loaf"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["400 g / 13oz chicken breast minute steaks (4 pieces x 100g/3oz each) (Note 1)","4 tbsp mayonnaise (, preferably whole egg (Note 2))","2 tbsp parmesan cheese (, grated)","6 tbsp panko breadcrumbs (Note 3)"],"purpose":"Chicken"},{"ingredients":["2 medium potatoes ((Note 4), not peeled)","1/4 to 1/2 cup milk (full fat or low fat)","1 tbsp butter (optional)","Salt and pepper (, to taste)"],"purpose":"Fast Mashed Potato"},{"ingredients":["1 large cucumber (or 2 small cucumbers)","1 punnet cherry tomatoes (or 2 medium tomatoes)","1 tbsp lemon juice","2 tbsp olive oil","Salt and pepper (, to taste)"],"purpose":"Salad"}]', '[{"description":"Turn grill/broiler on high and place the shelf about 20cm/8\" from the heat source.","images":[],"step":1},{"description":"Place potatoes in the microwave and cook on high for 3 minutes. Then turn the potatoes over and cook on high for a further 2 minutes (or until cooked). Squeeze the potatoes to check if they are cooked.","duration":3,"images":[],"step":2},{"description":"Mix the mayonnaise and parmesan cheese in a small bowl.","images":[],"step":3},{"description":"Place the chicken in a large oven proof fry pan (Note 5). Using the back of a spoon, spread the mayonnaise mixture over each chicken breast.","images":[],"step":4},{"description":"Sprinkle panko breadcrumbs over each piece of chicken. Use your fingers to pat the panko so it sticks to the chicken. (Note 6)","images":[],"step":5},{"description":"Place chicken under the grill/broiler for 8 minutes, or until just cooked through and the crumbs are golden. Check it once at around 6 minutes and rotate the fry pan if necessary so the crumb cooks evenly all over. When cooked, set aside to rest for a few minutes before serving.","duration":8,"images":[],"step":6},{"description":"While the chicken is cooking, get the potatoes out of the microwave (use a dishcloth). Cut each potato in half, then use a dessert spoon to scoop the flesh out into a bowl. Add milk, butter, salt and pepper. Use a potato masher to mash. Add more milk to achieve the desired consistency.","images":[],"step":7},{"title":"Salad","description":"Use a potato peeler to make ribbons from the cucumber. Cut the cherry tomatoes in half. Pile the cucumber and cherry tomatoes onto a plate, then drizzle over lemon juice, olive oil and scatter with salt and pepper.","images":[],"step":8},{"title":"To Serve","description":"Place mashed potato on each plate then top with the chicken. Drizzle with extra olive oil and garnish with finely chopped fresh parsley, if desired. Serve the Salad on the side.","images":[],"step":9}]', '["egg","milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","most-popular","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_79b19833d9ef', 'en', 'US', 'Pea, Zucchini and Pesto Orzo (Risoni)', 'This is a great super quick midweek meal. It''s better made with homemade pesto, but store bought is fine too. I store homemade pesto in the freezer by pouring it into ice cube trays. That way I have serving size portions of pesto on hand when I need it. Sometimes I stir through frozen spinach to add more nutrition into this.', 'https://www.recipetineats.com/tachyon/2014/11/Green-Vegetable-Pesto-Risoni-Orzo-51.jpg', 5, 10, 15, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.2, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 0.75, "unit": "bunch"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_zucchini", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["2/3 cup risoni","1 tbsp olive oil","2 1/2 tbsp basil pesto (, preferably homemade (see notes for recipe))","1 small onion ((brown, yellow or white), diced)","1 garlic clove (, crushed)","3 cups zucchini (, diced)","1 cup frozen peas (, preferably defrosted)","1/4 tsp salt","Black pepper"]},{"ingredients":["Parmesan cheese (, freshly grated)"],"purpose":"To Serve"}]', '[{"description":"Place about 8 cups of water in a large saucepan and bring to boil.","images":[],"step":1},{"description":"Add risoni and cook for 4 minutes, then add peas and cook for a further 1 minute. Note: The risoni will be slightly underdone at this point. It will finish cooking in the remaining steps.","duration":4,"images":[],"step":2},{"description":"Scoop out 1/2 cup of the water from the saucepan, then drain the risoni and set aside until ready to add to the pan.","images":[],"step":3},{"description":"Heat olive oil in a fry pan over medium high heat.","images":[],"step":4},{"description":"Add garlic and onion and sauté for 1 minute until starting to soften.","duration":1,"images":[],"step":5},{"title":"Add zucchini and sauté for a further 2","description":"3 minutes until both the zucchini and onion are softened and the onion is starting to turn a light golden brown.","images":[],"step":6},{"description":"Add pesto, risoni, pasta water reserved in step 3, salt and pepper. Bring the water to a simmer and stir for 1 minute until the water is absorbed.","duration":1,"images":[],"step":7},{"description":"Serve immediately, garnished with freshly grated parmesan.","images":[],"step":8}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","gluten-free-recipes","pasta-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals","zucchini-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e3c745336ab5', 'en', 'US', 'Fish Piccata With Crispy Smashed Potatoes (15 Minute Meal)', 'It''s amazing what you can make in 15 minutes (from scratch) if you get a bit creative! Make this with fresh fish or good quality frozen fish. I made these with beans but I often make it with asparagus and broccolini. You can really use any vegetables you want as long as they cook quickly in a pan with just a bit of braising liquid.', 'https://www.recipetineats.com/tachyon/2014/10/Fish-Piccata-Smashed-Potatoes-Green-Beans-15-minutes.jpg', 5, 10, 15, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 6.0, "unit": "bag of 2kg"}}, {"id": "ing_green_beans", "quantity": {"value": 198.45, "unit": "pack"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_baby_capers", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2 pieces firm white fish fillets (around 150 - 200g / 5 - 7 oz each) (with or without skin, your choice) (see notes)","6 baby / chat / new potatoes (about the size of a golf ball) (see notes)","7 oz / 200 g green beans (, trimmed)","1 tbsp fresh parsley (, finely chopped)","2 tbsp olive oil","3 tbsp plain flour","1 tsp salt","Black pepper"]},{"ingredients":["1/3 cup white wine","1/2 cup water","1 - 2 tbsp fresh lemon juice (adjust to your taste)","2 tbsp butter","1 tbsp baby capers (canned)","Salt and pepper"],"purpose":"Sauce"}]', '[{"description":"Cook the potatoes in the microwave for 2 minutes, turn potatoes, then cook for another 1 1/2 - 2 minutes. You will be able to tell by squeezing them if they are ready. Don''t worry if the skin bursts, you are smashing them anyway.","duration":2,"images":[],"step":1},{"description":"Use the side of a knife, meat mallet or your hand (covered with a dish cloth) and smash each potato so they are flattened to around 1.5cm/ 0.5\" thick with a flattish surface. Sprinkle with a pinch of salt.","images":[],"step":2},{"description":"Meanwhile, combine flour, salt and pepper on a plate and dredge each side of the fish in the flour mixture. Shake off excess flour.","images":[],"step":3},{"description":"Heat olive oil in a non stick pan over high heat. Place fish and potatoes in the pan. Press the potatoes down lightly with a spatula to help it crisp up.","images":[],"step":4},{"description":"Cook the first side of both the fish and potatoes for around 2 minutes until golden brown, then turn. Make sure the potato is crispy and brown.","images":[],"step":5},{"description":"Cook the other side of the fish for 1 1/2 minutes (also see notes for fish cooking time). Then remove from the pan onto a plate and cover loosely with foil.","images":[],"step":6},{"description":"Give the potatoes another 30 seconds to 1 minute to make it nice and brown and crispy, then remove from the pan.","images":[],"step":7},{"description":"Turn heat down to medium high.","images":[],"step":8},{"description":"Add wine and water to the pan. Scrape the brown bits off the bottom of the pan and mix it in. When the liquid comes to a rapid simmer, add the beans.","images":[],"step":9},{"description":"Shake the pan occasionally to help the beans cook evenly. Cook the beans in the liquid for around 1 1/2 minutes until \"tender crisp\" (i.e. cooked but still crisp) and remove from pan. If the liquid reduces too much while cooking the beans (which might be the case if you are using a very large heavy based pan), just add a splash of water.","images":[],"step":10},{"description":"Remove pan from heat. By the time you remove the beans, there should just be a bit of sauce left at the bottom of the fry pan, not even covering the entire base of the fry pan.","images":[],"step":11},{"description":"Add lemon juice then stir through butter and capers. Adjust seasoning to taste with salt and pepper.","images":[],"step":12},{"description":"To Serve","images":[],"step":13},{"description":"Place half the beans on each plate and place 3 potatoes on top. Top with a piece of fish. Spoon over the Sauce onto each fish and scatter with parsley. Serve immediately.","images":[],"step":14}]', '["fish","gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","dinner-tonight","fish-recipes","gluten-free-recipes","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_12e89ad9167d', 'en', 'US', 'Lemon Pepper Pork', 'A complete meal on the table in just 15 minutes! Made from scratch, so fresh and easy.', 'https://www.recipetineats.com/tachyon/2014/09/Lemon-Pepper-Pork-Grilled-Veg-Feta-Couscous-4.jpg', 5, 10, 15, 2, '[{"id": "ing_pork", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_mint", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_couscous", "quantity": {"value": 75.0, "unit": "pack"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cheese", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}]', '[{"ingredients":["2 pork cutlets (, at room temperature (200g/7oz each, bone in) (see notes))","1 tbsp lemon pepper (see notes)","2 tbsp olive oil (, separated)","2 zucchinis (, sliced)","1 small red capsicum ((bell pepper), sliced)","1 small red onion ((spanish onion), sliced)","1/2 small lemon","1/4 cup mint leaves (loosely packed)","1/2 cup couscous","1/2 cup boiling water (or chicken or vegetable stock/broth)","50 g / 1.5 oz g / 1.5 oz feta cheese","Salt and pepper","Lemon wedges or cheeks (, to serve (optional))"]}]', '[{"description":"Combine couscous and boiling water in a bowl, cover with cling wrap and set aside for 5 minutes.","duration":5,"images":[],"step":1},{"description":"Sprinkle lemon pepper on both sides of each cutlet and pat to make it stick.","images":[],"step":2},{"description":"Heat 1 tbsp olive oil in fry pan over high heat. Place pork in fry pan and cook the first side for 2 minutes and the second side for 1 1/2 minutes or until cooked to your liking. I like mine medium rare. Remember the pork will continue to cook while resting.","duration":2,"images":[],"step":3},{"description":"Remove pork from the fry pan onto a plate, cover loosely with foil and set aside to rest.","images":[],"step":4},{"description":"Heat remaining 1 tbsp olive oil in the fry pan still on high heat. Add onion and capsicum and sauté for 1 minute, then add the zucchini. Stir and cook the vegetables until charred and just cooked through. Remove pan from heat.","duration":1,"images":[],"step":5},{"description":"Fluff up the couscous with a fork. Add the vegetables and mint leaves. Squeeze over a drizzle of lemon juice and season to taste with salt and pepper. Toss gently to combine.","images":[],"step":6},{"description":"Divide couscous between plates, scatter over feta cheese. Top with pork cutlet and drizzle over resting juices. Serve with lemon cheeks or wedges on the side, if using.","images":[],"step":7}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","dinner-tonight","gluten-free-recipes","grilling-ideas-and-recipes","main-dishes","pork-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ab018d3a384c', 'en', 'US', 'Chicken Marsala', 'Recipe video above. A beloved Italian-American classic comprised of a crispy golden chicken cutlet smothered in a rich Marsala wine flavoured mushroom sauce. A restaurant favourite that''s easy to make at home, one bite and you''ll be hooked for life like I was!The key flavour here is Marsala wine so if you can''t consume alcohol or don''t have it, make Chicken in Creamy Mushroom Sauce instead! Also, this dish uses more alcohol than my usual "just a splash of wine" so it''s not recommended for kids. :)', 'https://www.recipetineats.com/tachyon/2023/06/Chicken-Marsala_0b.jpg', 10, 15, 25, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_eschalots", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.333, "unit": "bottle of 750ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["2 large chicken breasts (300g/10oz each), cut in half horizontally (or 4 thighs, Note 1)","1/2 tsp cooking salt / kosher salt","1/2 tsp black pepper","1/4 cup flour (, plain/all-purpose)"],"purpose":"Golden crusted chicken:"},{"ingredients":["2 tbsp extra virgin olive oil","2 tbsp / 30g unsalted butter","2 eschalots (US: shallots), peeled and cut into 1cm / 1/3\" squares (Note 2)","1 garlic (, finely minced)","2 cups white mushrooms (, sliced 0.5cm / 1/5\" thick)","1 cup dry marsala wine (Note 3)","1/2 cup chicken stock/broth (, low sodium)","1/2 cup thickened / heavy cream ( (Note 4))","1/4 tsp cooking salt / kosher salt","1/8 tsp black pepper","1 tbsp finely chopped parsley (, for garnish (optional))"],"purpose":"Marsala sauce:"}]', '[{"description":"Chicken escalopes:","images":[],"step":1},{"title":"Pound","description":"Cut each breast in half to form 2 thin steaks. Cover with a freezer bag or Go-Between (Note 5) and pound to 1 cm / 0.4″ thickness using a meat mallet or rolling pin. This tenderises and ensures even cooking of the chicken.","images":[],"step":2},{"title":"Dust","description":"Sprinkle the surface with half the salt, pepper then flour. Lightly rub flour across surface, turn and repeat with remaining salt, pepper and flour. Shake excess flour off each piece just before cooking.","images":[],"step":3},{"title":"Cook","description":"Put half the butter and oil in a large non-stick pan over medium high heat. Once the butter is melted and foamy, place chicken in, then cook for 3 to 4 minutes until it''s gorgeously golden and crispy. Turn and cook the other side for 2 minutes. Remove onto a plate.","duration":3.5,"images":[],"step":4},{"description":"Creamy marsala sauce:","images":[],"step":5},{"title":"Sauté aromatics","description":"In the same pan, add remaining butter and oil. Once butter is melted, add eschalots and garlic. Cook for 1 minute.","duration":1,"images":[],"step":6},{"title":"Cook mushrooms","description":"Add mushrooms. Cook for 3 minutes, stirring regularly.","duration":3,"images":[],"step":7},{"title":"Reduce marsala","description":"Add marsala, turn up heat to high and boil for 3 minutes or until reduced by half.","duration":3,"images":[],"step":8},{"title":"Thicken sauce","description":"Add chicken stock, cream, salt and pepper. Stir, then lower heat so it''s simmering (not boiling rapidly) and simmer for 3 to 5 minutes until the sauce thickens to a cream consistency (not too thick, will thicken more).","duration":4,"images":[],"step":9},{"title":"Rewarm chicken","description":"Nestle chicken into sauce and leave for 30 seconds to reheat.","duration":0.5,"images":[],"step":10},{"description":"Serve! Take off the stove. Sprinkle with parsley, serve over starchy vehicle of choice (I chose mash. Rice, small pasta, polenta or bread for plate mopping also work well!).","images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian","Italian-American"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9bb071c80b13', 'en', 'US', 'Greek Lamb and Salad Dinner', 'A super quick Greek dinner!', 'https://www.recipetineats.com/tachyon/2014/08/Greek-lamb-salad-dinner-4.jpg', 10, 5, 15, 4, '[{"id": "ing_beef_steak", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.5, "unit": "pack of 3 heads"}}, {"id": "ing_cheese", "quantity": {"value": 0.25, "unit": "block of 250g"}}, {"id": "ing_olives", "quantity": {"value": 16.0, "unit": "bottle"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 0.4, "unit": "loaf"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.075, "unit": "net of 500g"}}, {"id": "ing_honey", "quantity": {"value": 0.02, "unit": "jar of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.5, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["600 g / 20 oz lamb steaks (4 pieces in total)","2 large cucumbers","4 medium tomatoes","1 red onion (spanish onion)","1/2 cup (combined) parsley and mint leaves","1/2 small garlic clove","1/4 cup crumbled feta cheese","16 olives (black or green)","2 tsp dried oregano","8 slices sourdough bread","Salt and pepper"]},{"ingredients":["1/2 cup extra virgin olive oil","1/4 cup lemon juice","2 tsp honey","1/2 garlic clove (, minced)","1 tsp salt","Black pepper"],"purpose":"Dressing"}]', '[{"description":"Combine the Dressing ingredients and mix well (or put in a jar and shake).","images":[],"step":1},{"description":"Pour 1/4 cup of the Dressing, dried oregano, and a pinch of salt and pepper onto the lamb steaks and use your hands to coat evenly.","images":[],"step":2},{"title":"To freeze","description":"Place the lamb and marinade in a ziplock bag, remove as much air as possible and freeze. To cook, defrost completely and bring back to room temperature.","images":[],"step":3},{"description":"Heat BBQ (grill) or a heavy based pan on the stove over high heat.","images":[],"step":4},{"description":"Remove lamb from marinade. Place lamb on BBQ (or in the pan) and grill each side for 1 to 1 1/2 minutes, or until cooked to your liking. Remove lamb steaks from the BBQ / pan onto a plate and cover loosely with foil to rest.","images":[],"step":5},{"description":"Cut cucumber vertically into 8 pieces.","images":[],"step":6},{"description":"Cut tomatoes into thick slices.","images":[],"step":7},{"description":"Peel red onion and slice finely.","images":[],"step":8},{"description":"Toast bread, either in the toaster or on the BBQ/grill. While still warm, rub lightly with the cut side of the garlic. Optional: drizzle with extra olive oil.","images":[],"step":9},{"description":"Slice lamb into thin slices.","images":[],"step":10},{"description":"Place 4 slices of cucumber on each plate and top with tomato slices, red onion and olives.","images":[],"step":11},{"description":"Place lamb on top, sprinkle over the feta, parsley and mint leaves.","images":[],"step":12},{"description":"Drizzle over Dressing and serve with toasted bread on the side.","images":[],"step":13}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["dinner-tonight","greek-recipes","grilling-ideas-and-recipes","lamb-recipes","main-dishes","mediterranean-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3b426a11fb45', 'en', 'US', '8 simple Italian Pasta Recipes', 'These pasta recipes are simple Italian classics you''ll find in trattorias all across Italy. “Pantry” meals that take less than 15 minutes to make, each makes enough for 6 people. For all recipes, follow the Base Steps then move onto the recipe specific steps.Use the recipe slider to change the serving size. Key step (especially for simple pastas like these) - tossing the sauce with the cooked pasta and a splash of pasta cooking water. The fat in the sauce reacts with the starch in the cooking water, thickening the sauce and making it stick to the pasta strands. This is the proper way to make pasta - no self respecting Italian or restaurant would ever skip this step!', 'https://www.recipetineats.com/tachyon/2014/06/Pasta1.jpg', 5, 15, 20, 6, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.907, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_canned_tomatoes", "quantity": {"value": 1.488, "unit": "can of 400g"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_anchovies", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_thinly_guanciale", "quantity": {"value": 0.17, "unit": "kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 2.722, "unit": "punnet of 250g"}}, {"id": "ing_basil", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_black_olives", "quantity": {"value": 113.4, "unit": "bottle"}}, {"id": "ing_capers", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_tinned_tuna", "quantity": {"value": 141.75, "unit": "pack"}}]', '[{"ingredients":["1 lb/500 g dried spaghetti (or other long pasta)"]},{"ingredients":["1/2 cup extra virgin olive oil","10 garlic cloves (, sliced)","1 tbsp red chilli flakes","1/4 cup chopped parsley"],"purpose":"PASTA WITH OLIVE OIL & GARLIC (AGLIO E OLIO):"},{"ingredients":["1/4 cup extra virgin olive oil","2 garlic cloves (, crushed)","21 oz / 600g crushed tinned tomatoes","2 tbsp chilli flakes","1/4 cup chopped parsley"],"purpose":"FIERY PASTA (ARRABIATA):"},{"ingredients":["1/3 cup extra virgin olive oil","2 garlic cloves (, crushed)","2 tbsp anchovies (, finely chopped)","1 tbsp red chilli flakes","1/4 cup chopped parsley"],"purpose":"PASTA WITH ANCHOVIES (SPAGHETTI CON LE ACCIUGHE):"},{"ingredients":["2 tbsp extra virgin olive oil","2 garlic cloves (, crushed)","1/2 brown onion (, diced)","14 oz/400g crushed tinned tomatoes","1/2 tsp red chilli flakes","6 oz/ 180g thinly sliced guanciale (, or diced pancetta or bacon)"],"purpose":"AMATRICE SPAGHETTI (SPAGHETTI ALL’AMATRICIANA):"},{"ingredients":["4 tbsp extra virgin olive oil","2 garlic cloves (, crushed)","24 oz/800g fresh cherry tomatoes (, halved)","1/4 cup fresh basil (, lightly packed)"],"purpose":"FRESH TOMATO & BASIL SAUCE (POMAROLA):"},{"ingredients":["1/4 cup olive oil","3 garlic cloves (, crushed)","1 brown onion (, diced)","28 oz / 800g crushed tinned tomatoes","1/4 cup fresh basil (, lightly packed)"],"purpose":"TOMATO SPAGHETTI (SPAGHETTI NAPOLITANA):"},{"ingredients":["1/4 cup extra virgin olive oil","2 garlic cloves (, crushed)","14 oz/400g crushed tinned tomatoes","1/2 tbsp red chilli flakes","4 oz/100g black sliced olives","2 tbsp capers","1/4 cup chopped parsley"],"purpose":"SPAGHETTI WITH OLIVES AND CAPERS (SPAGHETTI ALLA PUTTANESCA):"},{"ingredients":["1/4 cup extra virgin olive oil","2 garlic cloves (, crushed)","1/2 brown onion (, diced)","14 oz/400g crushed tinned tomatoes","5 oz/150g tinned tuna","1/4 cup chopped parsley"],"purpose":"PASTA WITH TUNA (SPAGHETTI AL TONNO):"}]', '[{"description":"Base Directions (for All):","images":[],"step":1},{"description":"Cook 1lb/500g of dried spaghetti (or any other long dried pasta) in a large pot of salted boiling water per packet MINUS 1 minute.","images":[],"step":2},{"description":"Meanwhile, prepare one of the sauces below.","images":[],"step":3},{"description":"When pasta is ready, scoop out 1 cup of pasta cooking water, and drain pasta.","images":[],"step":4},{"description":"Add pasta into chosen sauce with 3/4 cup pasta cooking water. Toss pasta until sauce thickens and sticks to pasta (called \"emulsifying\" the sauce), 1 - 2 minutes. Use more pasta water if needed to loosen sauce.","images":[],"step":5},{"description":"Season with salt and pepper to taste. Finish pasta per chosen recipe.","images":[],"step":6},{"description":"PASTA WITH OLIVE OIL & GARLIC (AGLIO E OLIO):","images":[],"step":7},{"description":"Heat oil over medium high heat. Add garlic and cook until golden - be careful not to burn it.","images":[],"step":8},{"description":"Toss with pasta and cooking water per Base Directions. Toss through parsley and chilli flakes, serve with parmesan.","images":[],"step":9},{"description":"Heat oil over medium high heat. Add garlic, stir until fragrant, then add the tinned tomatoes and chilli flakes, simmer on medium for 5 minutes.","duration":5,"images":[],"step":10},{"description":"Toss with pasta and cooking water per Base Directions. Toss through parsley and serve with parmesan.","images":[],"step":11},{"description":"PASTA WITH ANCHOVIES (SPAGHETTI CON LE ACCIUGHE):","images":[],"step":12},{"description":"Heat oil over medium high heat. Add garlic and anchovies, stir until the garlic is fragrant and the anchovies have melted.","images":[],"step":13},{"description":"Toss with pasta and cooking water per Base Directions. Toss through parsley and chilli flakes, and serve with parmesan.","images":[],"step":14},{"description":"AMATRICE SPAGHETTI (SPAGHETTI ALL’AMATRICIANA):","images":[],"step":15},{"description":"Heat oil over medium high heat. Add the garlic, onion and guanciale (or pancetta or bacon) and cook until the onion has softened and the guanciale is golden.","images":[],"step":16},{"description":"Add the tinned tomatoes and chilli flakes and bring to rapid simmer. Toss with pasta and cooking water per Base Directions. Serve with parmesan.","images":[],"step":17},{"description":"Heat oil over medium high heat. Add garlic and cook until fragrant, add tomato and cook briefly, just to warm through.","images":[],"step":18},{"description":"Toss with pasta and cooking water per Base Directions. Toss through basil, serve with parmesan.","images":[],"step":19},{"description":"TOMATO SPAGHETTI (SPAGHETTI NAPOLITANA):","images":[],"step":20},{"description":"Heat oil over medium high heat. Add garlic and cook until fragrant, then add the onion and cook until softened. Then add tinned tomatoes and 1/2 cup water, simmer 5 minutes.","images":[],"step":21},{"description":"Toss with pasta and cooking water per Base Directions. Toss through basil and serve with parmesan.","images":[],"step":22},{"description":"SPAGHETTI WITH OLIVES AND CAPERS (SPAGHETTI ALLA PUTTANESCA):","images":[],"step":23},{"description":"Heat oil over medium high heat. Add garlic and cook until fragrant, then add tinned tomatoes, chilli flakes, olives, capers and 1/2 cup water. Simmer 3 minutes.","images":[],"step":24},{"description":"Toss with pasta and cooking water per Base Directions. Toss through parsley and serve with parmesan.","images":[],"step":25},{"description":"Heat oil over medium high heat. Add garlic and cook until fragrant. Add the onion and cook until softened, then add the tinned tomatoes and 1/2 cup water. Simmer 3 minutes, then add the tuna.","images":[],"step":26},{"description":"Toss with pasta and cooking water per Base Directions. Toss through parsley. Seafood pasta typically not served with parmesan but you can if you want!","images":[],"step":27}]', '["fish","gluten"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["italian-recipes","most-popular","pasta-recipes","quick-and-easy","quick-dinner-ideas-15-minute-meals"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e6fcbcb0b379', 'en', 'US', 'Vegetable Tian', 'Recipe video above. I love this colourful Provençal vegetable bake! It’s full of vibrant colours and lovely garlicky Mediterranean flavours, making it just as good as a side dish as it is a vegetarian main. While it feels especially at home alongside French and Mediterranean food, the flavours are so adaptable that it will happily sit beside almost any Western-style meal.Enjoy warm or at room temperature.', 'https://www.recipetineats.com/tachyon/2026/06/Vegetable-tian-5a.jpg', 30, 40, 70, 6, '[{"id": "ing_olive_oil", "quantity": {"value": 0.09, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_zucchini", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_herbes_de_provence", "quantity": {"value": 1.5, "unit": "unit"}}]', '[{"ingredients":["6 tbsp extra virgin olive oil","4 garlic cloves (, finely minced with a knife)","2 tbsp tomato paste","1 eggplant (aubergine), cut in half lengthways then sliced 8mm / 0.3” half moons (~380g / 13.5oz)","3 zucchini (courgette), sliced into 6mm / 0.25” rounds (~180g / 6oz each)","3 red onion (, sliced into 3mm / 0.1” rounds (~140g / 5oz each) (use a mandolin if you have one))","5 tomato (, sliced into 5mm / 0.2” rounds (~140g / 5oz each))","2 tsp cooking / kosher salt (, (or half for table salt, +50% for flakes))","1/2 tsp black pepper","1 1/2 tsp herbes de Provence"]}]', '[{"description":"Sweat the eggplant and zucchini, spread oil, tomato paste and garlic in a dish. Arrange vegetables, alternating, drizzle/sprinkle with oil, Herbs de Provence, salt and pepper. Bake 40 minutes.","images":[],"step":1},{"title":"Preheat oven","description":"Preheat oven to 200°C / 400°F (180°C fan-forced).","images":[],"step":2},{"title":"Sweat eggplant and zucchini","description":"Toss eggplant and zucchini slices in a bowl with 1 teaspoon of salt. Place them in colander over bowl to sweat and leave to drain for about 10 minutes while you slice the remaining vegetables and prepare the baking dish. (Note 2)","images":[],"step":3},{"title":"Prepare baking dish","description":"Spread 1 tbsp olive oil, tomato paste and half the garlic over the base of a ceramic baking dish (30cm x 20cm x 5cm / 12\" x 8\" x 2\"). As the vegetables bake, they will release their juices which will mix into it to create a beautiful sauce underneath.","images":[],"step":4},{"title":"Season again","description":"Give the colander a shake to remove excess water off the eggplant and zucchini (no need to pat them dry), then put them back into a bowl. A lot of salt comes off with the water, so toss with another 1/2 teaspoon of salt.","images":[],"step":5},{"title":"Layer vegetables","description":"Arrange the vegetables vertically in the dish, alternating eggplant, zucchini, onion and tomato (I do it in this order). I usually make around 14 rows (the video is very useful here). Don''t be afraid to pack the vegetables in quite tightly. They will shrink as they bake, so arranging them snugly together helps them stay upright. (Note 3)","images":[],"step":6},{"title":"Season top","description":"Drizzle all-over with remaining olive oil. Sprinkle evenly with remaining garlic, remaining 1/2 teaspoon of salt, black pepper and Herbes de Provence.","images":[],"step":7},{"title":"Bake","description":"Bake for 40 minutes until the vegetables are soft and lightly browned on the edges. Serve immediately, or leave to cool and serve at room temperature.","duration":40,"images":[],"step":8}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["all-vegetable-sides","dietary","easter-sides-warm-hearty","eggplant","gluten-free-recipes","jbs-recipes","side-dishes","tomato","vegan-lifestyle","vegetarian-recipes","zucchini","zucchini-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ac448cf78003', 'en', 'US', 'Maple sweet potato salad - with whipped tahini and crispy chickpeas', 'Recipe video above. Channelling my inner Yotam Ottolenghi – maple-roasted sweet potato on a fluffy cloud of whipped tahini, topped with crispy spiced chickpeas and a shower of chopped pistachios. Fabulous statement side or substantial meat-free main - try stuffing into flatbreads. Ridiculously good!', 'https://www.recipetineats.com/tachyon/2025/06/Maple-sweet-potato-salad-with-whipped-tahini_4.jpg', 15, 40, 55, 5, '[{"id": "ing_sweet_potato", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_sriracha", "quantity": {"value": 0.037, "unit": "bottle of 400ml"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.375, "unit": "tub of 500g"}}, {"id": "ing_tahini", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.417, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_pistachios", "quantity": {"value": 4.0, "unit": "unit"}}]', '[{"ingredients":["1.5kg / 3 lb sweet potatoes","1 tbsp maple syrup (or 2 1/2 tbsp honey)","1 1/2 tbsp olive oil","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Maple roasted sweet potato wedges:"},{"ingredients":["400g/ 14 oz can chickpeas (, drained but not dried)","1 tbsp olive oil","1/2 tsp smoked paprika","1/4 tsp garlic powder","1/4 tsp onion powder","1/4 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Crispy seasoned chickpeas:"},{"ingredients":["3 tbsp maple syrup (sub 2 tbsp honey)","1 tbsp sriracha (Note 2)","1 tbsp extra virgin olive oil","1/4 tsp cooking salt / kosher salt (halve for table salt)","Pinch Black pepper"],"purpose":"Spicy maple sauce"},{"ingredients":["1 1/4 cups plain yogurt (, full fat, unsweetened)","3 tbsp tahini (mix well if oil is separated)","2 tbsp lemon juice","1 large garlic clove (, finely grated)","1 tbsp extra virgin olive oil","1/2 tsp cooking salt / kosher salt"],"purpose":"Whipped tahini yogurt sauce:"},{"ingredients":["2 tbsp finely chopped coriander/cilantro leaves (sub parsley)","4 tbsp toasted pistachios (, finely chopped (Note 3))"],"purpose":"Garnishes:"}]', '[{"description":"Preheat the oven to 220°C/450°F (200°C fan). Arrange the oven racks so they are 20 cm/8\" apart (for air circulation).","images":[],"step":1},{"title":"Spicy maple sauce","description":"Mix until combined. Set aside.","images":[],"step":2},{"title":"Sweet potato","description":"Cut each sweet potato lengthways into 6 wedges (or 8, if they are thicker potatoes). Put on a paper lined tray, then toss with the maple syrup, olive oil, salt and pepper. Lay sweet potato wedges on their side.","images":[],"step":3},{"title":"Chickpeas","description":"Drain the chickpeas then spread on a tray (still wet).","images":[],"step":4},{"title":"Baking","description":"Put both trays in the oven (sweet potato on the top shelf). Roast the potatoes for 30 minutes, turning them at the halfway mark. Take the chickpeas out after 10 minutes to flavour them.","duration":30,"images":[],"step":5},{"title":"Crispy seasoned chickpeas","description":"Remove the oven dried chickpeas from the oven after 10 minutes (Note 4). Push them to one side of the tray, drizzle/sprinkle and toss with the oil, spices, salt and pepper. Toss well using a rubber spatula, then return to the oven for a further 15 - 20 minutes until they''re crispy (they will clatter! Note 4).","images":[],"step":6},{"title":"Sweet potato charring (optional)","description":"After 30 minutes (or when the potatoes are soft), switch the oven grill/broiler to high. Tuck in or fold down excess paper around the tray edges (so it doesn''t touch heat element and catch fire). Stand the wedges sharp edge facing up, then pop it under the broiler for 3 to 5 minutes until a bit charred on the edges. ⚠️ SAFETY NOTE: Do not walk away, make sure the paper does not catch fire.","duration":4,"images":[],"step":7},{"title":"Whipped tahini yogurt sauce","description":"While the potatoes are roasting whisk ingredients in a heat-proof bowl just to combine. When ready to use, microwave for just 30 seconds on high, then whisk again for 10 seconds – it will resemble softly whipped cream. (Note 5)","duration":0.16666666666666666,"images":[],"step":8},{"title":"Optional tahini drizzle","description":"Remove 1/4 cup of the tahini sauce and loosen with a little water to a drizzle-able consistency.","images":[],"step":9},{"title":"Assemble","description":"Spread the whipped tahini on a large plate. Pile the sweet potato on, mostly in a single layer. Drizzle with the tahini drizzle (if using), the spicy maple sauce, sprinkle with most of the pistachio and coriander. Sprinkle over chickpeas, then sprinkle with the remaining coriander and pistachios. EAT! (PS Great served warm or at room temperature)","images":[],"step":10}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["MIddle eastern vibes","Western"],"categories":["all-vegetable-sides","dietary","gluten-free-recipes","sweet-potato","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_33d5fbd91088', 'en', 'US', 'The most amazing Chicken Kale Salad', 'Recipe video above. WORTH MAKING - don''t let the length of the ingredients deter you!! This is a big, hearty salad that may well be the best kale salad you''ve ever had. Big call I stand by! :)Filled with good-for-you nutrition yet anything but bland, that creamy tahini sauce totally makes it, thanks to the parmesan. Crunchy seasoned chickpeas add starchy bulk, flavour pops and texture, the cherry tomatoes add juicy bursts and the chicken provides protein. Oh yeah, and there''s kale in it too! :) Powerhouse greens!', 'https://www.recipetineats.com/tachyon/2024/04/Kale-salad-with-creamy-tahini-dressing_9.jpg', 20, 30, 50, 3, '[{"id": "ing_very_tightly_packed_cups_tuscan_kale", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_tomato", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_tahini", "quantity": {"value": 60.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.075, "unit": "net of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.417, "unit": "pack of 3 heads"}}, {"id": "ing_water", "quantity": {"value": 0.06, "unit": "L"}}]', '[{"ingredients":["5 very tightly packed cups Tuscan kale (cavolo nero) (, leafy part stripped off stem, sliced into 1 cm / 1/2\" ribbons (Note 1))","1 tsp extra virgin olive oil","1/4 tsp salt and pepper"],"purpose":"SOFTENED KALE:"},{"ingredients":["1/4 red onion (, very finely sliced)","1 1/2 cups shredded cooked chicken","2 soft boiled eggs (, halved (optional))"],"purpose":"SALAD:"},{"ingredients":["1 1/2 cups cherry or grape tomatoes","2 tsp extra virgin olive oil","1/4 tsp cooking salt/kosher salt","1/8 tsp black pepper"],"purpose":"BURST TOMATOES"},{"ingredients":["400 g/ 14 oz can chickpeas (, drained but not dried)","1 tbsp olive oil","1/2 tsp smoked paprika","1/4 tsp EACH garlic powder , onion powder","1/4 tsp EACH cooking salt / kosher salt & black pepper"],"purpose":"CRISPY SEASONED CHICKPEAS"},{"ingredients":["4 tbsp (60 g) tahini (, hulled (Note 3))","2 1/2 tbsp lemon juice","3 tbsp extra virgin olive oil","1/3 cup parmesan (finely grated (pack the cup tight), plus extra for serving)","1/2 tsp cooking salt/kosher salt","1/8 tsp black pepper","1 large garlic clove (, peeled)","4 tbsp water (plus more, if needed)"],"purpose":"CREAMY PARMESAN TAHINI DRESSING"}]', '[{"title":"Oven","description":"Roast tomatoes 12 min at 200°C/425°F (180°C fan). Roast plain chickpeas 10 min, toss with oil & seasonings, roast 20 min until crispy (same temp).","images":[],"step":1},{"title":"Salad","description":"Massage kale, leave 20 min. Blitz dressing. Toss kale, chicken, tomatoes, onion with half. Pile on chickpeas, drizzle with remaining dressing, shower with parmesan. EAT!","images":[],"step":2},{"description":"Preheat the oven to 200°C/425°F (180°C fan).","images":[],"step":3},{"title":"Roast tomatoes","description":"Toss the tomatoes with the oil, salt and pepper on a small tray. Roast 12 minutes, then cool on the tray.","images":[],"step":4},{"title":"Crispy chickpeas","description":"Drain the chickpeas then spread on a tray (still wet). Bake 10 minutes (same time as tomatoes). Push the oven dried chickpeas to one side of the tray. Drizzle with the oil and sprinkle with the chickpea spices, salt and pepper. Toss well using a rubber spatula, then return to the oven for a further 20 – 25 minutes until they''re crispy (They should clatter! Note 4).","images":[],"step":5},{"title":"Soften kale","description":"Rub/scrunch the kale with the oil, salt and pepper in a large bowl. Put the kale in a large bowl then drizzle with the oil and add the salt and pepper. Set aside for 20 minutes (softens leaves).","duration":20,"images":[],"step":6},{"title":"Tahini dressing","description":"Put the ingredients in a jug just large enough to fit the head of a stick blender. Blitz until smooth, using extra water if needed to loosen into a thick but pourable consistency (see video).","images":[],"step":7},{"title":"Toss","description":"Pour half the dressing over the kale and toss. Add onion, chicken and most of the tomatoes (save a few for decoration). Toss again.","images":[],"step":8},{"title":"Serve","description":"Transfer into a serving bowl or individual bowls. Top with remaining tomatoes, all the chickpeas and eggs if using. Drizzle with remaining sauce then sprinkle with extra parmesan. DIG IN. SWOON!","images":[],"step":9}]', '["egg","milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["all-vegetable-sides","beans-lentils","leafy-greens","salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e8fdbc3d0e04', 'en', 'US', 'Spicy maple roast carrots with crispy chickpeas and yogurt sauce', 'Recipe video above. This is a combination of 3 simple things that are devilishly good together: slightly spicy caramelised maple roasted carrots, crispy seasoned chickpeas and a cooling, creamy yogurt sauce with a subtle hint of garlic. The chickpeas add terrific crunch and because they''re a starch, you can easily serve this substantial side dish as a meal. Both the carrots and chickpeas take around 30 minutes in the oven but you might need to add an extra 5 minutes or so depending on how long you take when you take the trays out to toss/season etc .', 'https://www.recipetineats.com/tachyon/2024/02/Spicy-maple-roasted-carrots-with-crispy-chickpeas-and-yogurt-sauce-1.jpg', 15, 40, 55, 5, '[{"id": "ing_carrot", "quantity": {"value": 16.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 16.0, "unit": "pack of 1kg"}}, {"id": "ing_maple_syrup", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_sriracha", "quantity": {"value": 0.075, "unit": "bottle of 400ml"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.417, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_pistachios", "quantity": {"value": 3.0, "unit": "unit"}}]', '[{"ingredients":["16 Dutch carrots (, scrubbed clean and tops trimmed (keep 2cm/1\" of tops for looks))","600 g/ 1.2 lb regular carrots (5 medium), peeled, cut into quarters (Note 1)"],"purpose":"Carrots (choose one):"},{"ingredients":["3 tbsp maple syrup (or 2 1/2 tbsp honey)","2 tbsp sriracha","1 1/2 tbsp olive oil","1/4 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Spicy maple sauce (for carrots):"},{"ingredients":["400g/ 14 oz can chickpeas (, drained but not dried)","1 tbsp olive oil","1/2 tsp smoked paprika","1/4 tsp garlic powder","1/4 tsp onion powder","1/4 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Crispy seasoned chickpeas:"},{"ingredients":["1 tbsp maple syrup","1/2 tbsp sriracha"],"purpose":"Extra sauce (optional) – Note 2"},{"ingredients":["1 cup plain yogurt","1/2 tsp garlic (, finely grated)","1 tbsp lemon juice","1 tbsp extra virgin olive oil","1/4 tsp cooking salt / kosher salt"],"purpose":"Lemon garlic yogurt sauce:"},{"ingredients":["2 tbsp finely chopped coriander/cilantro leaves (sub parsley)","3 tbsp toasted pistachios (, finely chopped (Note 3))"],"purpose":"Garnishes:"}]', '[{"description":"Preheat the oven to 200°C/425°F (180°C fan). Arrange the oven racks so they are 20 cm/8\" apart (for air circulation).","images":[],"step":1},{"title":"Chickpeas & carrots","description":"Drain the chickpeas then spread on a tray (still wet). Toss the carrots with the Spicy Maple Sauce ingredients. Put both trays in the oven (carrots on the top shelf).","images":[],"step":2},{"title":"Crispy chickpeas","description":"Remove the oven dried chickpeas from the oven after 10 minutes (Note 4). Push them to one side of the tray, drizzle with the oil and sprinkle with the chickpea spices, salt and pepper. Toss well using a rubber spatula, then return to the oven for a further 20 - 25 minutes until they''re crispy (listen for the clatter when you shake the tray - or eat one! Note 4).","images":[],"step":3},{"title":"Carrots 30 min","description":"Roast the carrots for 30 minutes, tossing halfway, until they are tender and caramelised on the edges.","duration":30,"images":[],"step":4},{"title":"Yogurt Sauce","description":"Mix the ingredients in a bowl and set aside for at least 20 minutes to allow the flavours to develop.","images":[],"step":5},{"title":"Extra sauce","description":"Mix until combined.","images":[],"step":6},{"title":"Assemble","description":"Spread the yogurt sauce on a plate. Pile on the carrots, scraping out every drop of juices on the tray. Drizzle with extra sauce, if using. Sprinkle over chickpeas, then coriander and pistachios. EAT!","images":[],"step":7}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["MIddle eastern vibes","Western"],"categories":["all-vegetable-sides","beans-lentils","carrots","easter-sides-warm-hearty","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0401325e5931', 'en', 'US', 'Glass noodle salad (cellophane / bean thread noodles)', 'Recipe video above. This Asian-style salad combines glass noodles with fresh herbs, vegetables and shredded chicken with a hoisin dressing that''s slightly creamy so it clings nicely to the slippery noodles. The lime cashew crumble really makes this, so don''t skip it!Terrific no-cook meal for hot summer nights. Skip the chicken to turn it into a fabulous starch + veg side for Asian meals. Serves 3 to 4 as a meal, 5 to 6 as a side. More meal-size salads here!', 'https://www.recipetineats.com/tachyon/2023/01/Glass-noodle-salad_2.jpg', 20, 0, 20, 3, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.2, "unit": "pack of 500g"}}, {"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_cabbage", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_mint", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_roasted_cashew_nuts", "quantity": {"value": 150.0, "unit": "jar"}}, {"id": "ing_ime_zest", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_lime", "quantity": {"value": 0.015, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.225, "unit": "pack of 100g"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.056, "unit": "jar of 400g"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_ginger", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 1.25, "unit": "jar"}}]', '[{"ingredients":["100 g / 3.5 oz bean thread vermicelli noodles / cellophane noodles (Note 1)","3 cups shredded cooked chicken (about 1/2 store bought roast chicken) (Note 2)","2 packed cups ((180g) green cabbage, finely sliced)","1 cucumber (, cut in half, sliced 3mm / 1/8\" thick on the diagonal)","1 carrot (, peeled then julienned)","2 green onion stems (, finely sliced on a diagonal)","1 cup lightly packed coriander/cilantro leaves","1 cup lightly packed mint leaves"],"purpose":"Glass noodle salad:"},{"ingredients":["1 cup unsalted roasted cashew nuts (, roughly chopped)","1 1/2 tsp lime zest","2 tsp lime juice","3/4 tsp caster sugar / superfine sugar (sub ordinary / granulated)","1/2 tsp cooking/kosher salt"],"purpose":"Lime cashew crumble:"},{"ingredients":["3 tbsp light soy sauce","3 tbsp rice vinegar","1 1/2 tbsp sesame oil","1 1/2 tbsp canola oil","1 1/2 tbsp kewpie mayonnaise (or other mayo) (Note 3)","1 tbsp hoisin sauce","3/4 tsp finely grated fresh ginger","1/4 tsp Chinese five spice powder (Note 4)"],"purpose":"Creamy hoisin dressing:"}]', '[{"title":"Glass noodles","description":"Place dry noodles in a bowl and cover with freshly boiled water. Leave for 3 to 4 minutes or until transparent and softened. Drain using a colander, rinse under tap water (for rapid cool and reduce stickiness) then detangle using your fingers. Drain thoroughly before use. Set aside to fully cool.","duration":3.5,"images":[],"step":1},{"title":"Lime cashew crumble","description":"Place ingredients in a bowl and toss. (No marinating time needed)","images":[],"step":2},{"title":"Dressing","description":"Place ingredients in a jar and shake until well combined.","images":[],"step":3},{"title":"Salad","description":"Place glass noodle salad ingredients in a large bowl. Pour over dressing, toss well. Add half the cashews, toss again.","images":[],"step":4},{"title":"Serve","description":"Transfer to a large salad bowl or individual bowls. Sprinkle with remaining lime cashew crumble and serve!","images":[],"step":5}]', '["gluten","nuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner","lunch"],"cuisine":["Asian"],"categories":["all-vegetable-sides","no-cook-food","noodles","salad-recipes-main-course","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ecc2ab94db14', 'en', 'US', 'Twice Baked Potatoes (Stuffed Jacket Potatoes)', 'Recipe video above. Baked potatoes stuffed with a creamy, cheesy, mashed potato filling hit with salty pops of bacon. Think of it as the spud love-child of jacket potatoes and mashed potato! This is pretty much every cheese lovin,’ carb monster''s dream come true. Dainty food this ain''t – this is proper comfort food, turned up to 11!Serve it as a side, or as a meal.', 'https://www.recipetineats.com/tachyon/2021/05/Twice-Baked-Potatoes_5.jpg', 15, 75, 90, 8, '[{"id": "ing_potato", "quantity": {"value": 4.0, "unit": "bag of 2kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_butter", "quantity": {"value": 120.0, "unit": "block of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.333, "unit": "carton of 250ml"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_chives", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}]', '[{"ingredients":["4 x 300g / 10oz potatoes ( - Sebago (Aus), Russet (US), Maris Piper / King Edwards (UK) (Note 1))","1 tbsp canola or vegetable oil","1/2 tsp salt"]},{"ingredients":["200g / 7oz bacon (streaky) (, chopped into small batons (Note 2))","120g / 8 tbsp unsalted butter","1/3 cup cream (pure or thickened / heavy)","1 cup cheddar cheese (, shredded (Note 3))","3 green onions (, finely sliced)","1/4 tsp salt","1/4 tsp pepper"],"purpose":"Creamy potato filling:"},{"ingredients":["1 1/2 tbsp chives (, finely chopped (garnish))","Sour cream (recommended!)"],"purpose":"Garnish and serving (optional)"}]', '[{"description":"Preheat oven to 220°C / 430°F (200°C fan). Place a rack on a tray (recommended but not critical).","images":[],"step":1},{"title":"Prick potatoes","description":"Wash, scrub and dry potatoes well. Prick each potato 8 times with a fork.","images":[],"step":2},{"title":"Oil and salt","description":"Put potatoes in a bowl, pour over oil and rub onto potatoes. Then sprinkle over salt and use your hands to coat. (Just do this as best you can. Some will stick, much will not!)","images":[],"step":3},{"title":"Bake","description":"Place potatoes on rack and bake for 75 minutes or until you can pierce with a small knife with no resistance.","duration":75,"images":[],"step":4},{"description":"Prepare filling add-ins:","images":[],"step":5},{"title":"Cook bacon","description":"Place bacon in a cold non-stick pan over medium heat. When the fat starts to melt, turn the heat up to high and cook bacon until golden. Drain on paper towels.","images":[],"step":6},{"title":"Heat butter and cream","description":"Melt butter in a saucepan over medium heat. Then add cream and heat until hot, but don''t let it boil. (You could also do this in a microwave)","images":[],"step":7},{"description":"Stuff potatoes:","images":[],"step":8},{"title":"Lower oven","description":"Turn oven down to 200°C / 390°F (180°C fan).","images":[],"step":9},{"title":"Scoop out potato flesh","description":"Allow potatoes to cool enough so you can handle them (or use a tea towel). Cut in half lengthwise and scoop out potato flesh, leaving 0.7cm (1/3\") thick layer of potato still stuck to skin.","images":[],"step":10},{"title":"Mash potato","description":"Place potato flesh in a bowl and mash while hot until smooth.","images":[],"step":11},{"title":"Add-ins","description":"Add half the cheese (save the rest for topping), most of the bacon (save a bit for garnish), all the green onion, hot cream and butter, salt and pepper. Stir to combine.","images":[],"step":12},{"title":"Stuff and top with cheese","description":"Fill potato skins with the mashed potato mixture. Top with remaining cheese.","images":[],"step":13},{"title":"Bake","description":"Bake for 20 to 25 minutes until the cheese is melted, golden and bubbly.","duration":22.5,"images":[],"step":14},{"title":"Serve","description":"Serve immediately, garnish with sour cream, reserved bacon and chives.","images":[],"step":15}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["American","Western"],"categories":["all-vegetable-sides","dietary","easter-sides-warm-hearty","gluten-free-recipes","potato-recipes","potatoes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_330f864f40e2', 'en', 'US', 'Ratatouille (French Vegetable Stew)', 'Recipe video above. Ratatouille is a French vegetable stew that at first glance seems like a humble dish – because it is. Made well though, it''s a summery stunner bursting with the sunny tastes of the Mediterranean! The key to flavour-packed ratatouille is to sauté each vegetable separately before braising everything together. Ratatouille can comfortably star as a vegetarian main, otherwise it makes a perfect vegetable side.Makes side for 6 to 8 people, main meal for 4 people.', 'https://www.recipetineats.com/tachyon/2021/04/Ratatouille_0.jpg', 15, 45, 60, 8, '[{"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.09, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_black_olives", "quantity": {"value": 20.0, "unit": "bottle"}}, {"id": "ing_basil", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["1 eggplant (aubergine) (, cut into 2cm / ¾\" cubes (leave skin on) (~450g / 16oz))","1/2 tsp salt (, cooking / kosher salt)"],"purpose":"Eggplant:"},{"ingredients":["3 tomatoes (, chopped (~150g / 5oz each), Note 1 canned subs)","6 tbsp extra virgin olive oil","2 brown onion (, chopped 1cm / ⅖\" cubes (~150g / 5oz each))","2 capsicum (1 red, 1 yellow), ( cut into 2cm / ⅘\" cubes (~200g / 7oz each))","2 zucchinis (courgettes), ( diced into 1.5cm / ½\" pieces (~200g / 7oz each))","2 garlic cloves (, finely chopped (~3 tsp))","1 tsp fresh thyme leaves (, chopped (Note 2 for subs))","3/4 tsp salt (, cooking/kosher salt)","1/4 tsp black pepper","20 black olives (, pitted, halved)"],"purpose":"Other ingredients for Ratatouille:"},{"ingredients":["1 tbsp fresh basil (, finely chopped, plus more for garnish (Note 2 subs))","Extra virgin olive oil (, for drizzling)"],"purpose":"Finishing:"}]', '[{"title":"Sweat eggplant","description":"Place eggplant in a colander set over a bowl. Sprinkle with salt, toss with hands. Leave for 30 minutes to sweat (no need to wipe off water that beads on surface).","duration":30,"images":[],"step":1},{"title":"Make tomato puree","description":"Place tomato in a blender, food processor or other appliance of choice. Blitz until smooth. (No need to do this if using passata or crushed tomato.)","images":[],"step":2},{"description":"Cook vegetables:","images":[],"step":3},{"title":"Cook eggplant","description":"Heat 2 tbsp oil in a large skillet over medium high heat. Add eggplant and cook for 4 to 5 minutes, stirring regularly, until it''s golden on the surface but still somewhat firm and raw inside. Transfer to a large pot.","duration":4.5,"images":[],"step":4},{"title":"Cook onion and garlic","description":"In the same skillet, add another 1 tbsp olive oil. Add onion and garlic with a pinch of the salt. Cook for 3 minutes until onion is soft with a hint of golden on the edges. Add to pot holding eggplant.","duration":3,"images":[],"step":5},{"title":"Cook capsicum","description":"Add another 1 tbsp of olive oil and cook the capsicum with a pinch of salt for 3 minutes. It should still be firm inside. You won''t get much colour on the capsicum, this is OK. Add to pot.","duration":3,"images":[],"step":6},{"title":"Cook zucchini","description":"Add another 1 tbsp olive oil and cook the zucchini with a pinch of salt for 3 minutes. Make sure it stays firm (ie. raw inside). Like the capsicum, it won''t go golden. Add to pot.","duration":3,"images":[],"step":7},{"title":"Add remaining ingredients to pot","description":"Turn the stove under the pot to medium-high. Add tomato, thyme, olives, remaining salt and all the pepper, and mix. Once the mixture is hot, reduce heat to a low simmer.","images":[],"step":8},{"title":"Braise: Cook for 20","description":"25 minutes with the pot lid off, stirring every now and then, until all the vegetables are cooked through and the liquid has reduced. The mixture should be thick enough so you can pile it on a plate (ie. not watery), but still very moist and juicy.","duration":22.5,"images":[],"step":9},{"title":"Basil and salt","description":"Taste and add more salt if needed; vegetables can taste bland if not enough salt is added. Stir through basil then serve immediately, drizzled with extra virgin olive oil and a sprinkle of extra basil on top, if desired. Serve as a main with crusty bread, or as a side dish. See above recipe card for more ideas!","images":[],"step":10}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["French","Western"],"categories":["all-vegetable-sides","dietary","easter-sides-warm-hearty","gluten-free-recipes","low-calorie-recipes","side-dishes","stews","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_247f08932ef8', 'en', 'US', 'Eggplant Curry - South Indian Brinjal Curry', 'Recipe video above. This curry is not for the faint hearted! Eggplant (Brinjal) stars in this strong flavoured curry, roasted rather than fried for a healthier yet equally delicious (high temp does the trick here), then simmered in an intensely spiced South Indian curry sauce so it sucks up the flavour and partially collapses to create a big pot of juicy (delicious) mush. Incidentally vegan (as much of South Indian food is). See recipe notes for subs for the harder to find spices. And when you''ve made this, use the same spices to make this Vegetable Samosa Pie!Spiciness: Pretty mild. Spiciness only comes from the chilli powder so if you''re concerned, skip or reduce it!', 'https://www.recipetineats.com/tachyon/2020/08/Eggplant-Curry-Indian__2.jpg', 15, 60, 75, 4, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 58.333, "unit": "carton of 12"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_mustard", "quantity": {"value": 0.019, "unit": "jar of 200g"}}, {"id": "ing_curry_leaves", "quantity": {"value": 14.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.113, "unit": "can of 400ml"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_round_clove", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.4, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.5, "unit": "jar of 40g"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.4, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["2 tbsp vegetable oil (or canola)","700g / 1.2 lb eggplant (aubergine) (, 2 medium (Note 1))","1/2 tsp each salt and pepper"],"purpose":"Roasted Eggplant:"},{"ingredients":["3 tbsp vegetable oil (or canola)","3/4 tsp black mustard seeds (Note 2)","14 curry leaves, fresh (Note 3)","1 red onion (, quartered and thinly sliced)","3 tbsp passata or tomato pulp (or canned tomato) (Note 4)","1 tbsp garlic (, grated (4 cloves approx))","1 tbsp ginger (, grated (1.5cm piece approx))","1 1/4 cups water","3/4 tsp salt","3 tbsp coconut milk (or cream, full fat (Note 5))"],"purpose":"Curry:"},{"ingredients":["1/4 tsp cardamom powder","1/4 tsp ground clove","1/4 tsp black pepper","1/2 tsp chilli powder (or cayenne (NOT US Chilli Powder))","4 tsp coriander powder","4 tsp cumin powder"],"purpose":"Curry Spices:"},{"ingredients":["Basmati rice","Yogurt (, highly recommended)","Coriander/cilantro leaves (, optional)","Easy flatbread (as naan!) (, optional)"],"purpose":"Serving"}]', '[{"description":"Roasted Eggplant:","images":[],"step":1},{"description":"Preheat oven to 240°C / 450°F (220°C fan). Line tray with parchment/baking paper.","images":[],"step":2},{"description":"Cut eggplant into 2cm / 4/5\" slices, then cut into 2cm / 4/5\" batons.","images":[],"step":3},{"description":"Place in large bowl, toss with oil, salt and pepper.","images":[],"step":4},{"description":"Spread on tray, roast 20 minutes. Turn, roast for a further 10 minutes - edges should be caramelised, soft inside, but they''re not shrivelled up and dismal. Use per recipe.","images":[],"step":5},{"description":"Heat oil in a large pot over medium heat. Add mustard seeds, let them sizzle for 15 seconds.","duration":0.25,"images":[],"step":6},{"description":"Add curry leaves, stir, leave to sizzle for 15 seconds - seeds might pop, Indian cooking is very dramatic!","duration":0.25,"images":[],"step":7},{"description":"Add onions, cook 5 minutes until golden brown.","images":[],"step":8},{"description":"Add tomato, cook for 1 minute, stirring.","duration":1,"images":[],"step":9},{"description":"Add garlic and ginger, cook 2 minutes.","images":[],"step":10},{"description":"Add Curry Spices and salt, and cook for another 3 minutes - it will be a thick paste and might stick to the bottom of the pot, don''t let it burn (if it starts to, remove from stove and quickly add splash of water to loosen).","images":[],"step":11},{"description":"Stir in water, and then add the eggplant.","images":[],"step":12},{"description":"Gently stir, partially cover, reduce heat to low and simmer 30 minutes. Stir carefully once or twice (so the eggplants don''t break up completely), add more water if it dries out.","images":[],"step":13},{"description":"Stir in coconut milk, taste then add more salt if needed.","images":[],"step":14},{"description":"Your result should be a very thick, juicy, strongly flavoured curry with eggplant partially intact but half collapsed.","images":[],"step":15},{"description":"Serve with basmati rice and a dollop of yogurt and fresh coriander leaves, if you want.","images":[],"step":16}]', '["milk","mustard"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["all-vegetable-sides","curry-recipes","dietary","eggplant","gluten-free-recipes","indian-recipes","low-calorie-recipes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1f4ba82bdc05', 'en', 'US', 'Roasted Broccolini with Tahini Sauce', 'Recipe video above. I think that roasting is the best way to cook broccolini. It brings out the flavour and you get crunchy golden tips - the best part! It makes a wonderful side dish eaten plain, but if you drizzle it with a simple Tahini Sauce and sprinkle with nuts, it becomes company-worthy as an impressive side dish OR a main served with crusty bread or stuffed into flatbreads.Especially brilliant served with all things Middle Eastern.', 'https://www.recipetineats.com/tachyon/2020/08/Roasted-Broccolini-with-Tahini-Sauce_5.jpg', 10, 15, 25, 4, '[{"id": "ing_broccoli", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_tahini", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_honey", "quantity": {"value": 0.015, "unit": "jar of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_pine_nuts", "quantity": {"value": 0.375, "unit": "pack of 100g"}}]', '[{"ingredients":["500g/1 lb broccolini (, ends trimmed (3 standard bunches in Australia))","1 tbsp extra virgin olive oil","1/4 tsp each salt and pepper","1 garlic clove (, finely minced)"]},{"ingredients":["1/4 cup tahini","2.5 tbsp water","1.5 tsp honey","1 tbsp lemon juice","1/2 garlic clove (, pressed through garlic crusher or grated using microplan (to make sauce smooth))","1/4 tsp each salt and pepper"],"purpose":"Tahini Sauce:"},{"ingredients":["1/4 cup flaked almonds, pine nuts or pistachios (, toasted (Note 2))"],"purpose":"Garnish:"}]', '[{"description":"Preheat oven to 220°C/425°F (200°C fan).","images":[],"step":1},{"title":"Sauce","description":"Mix Tahini Sauce ingredients until combined. It should be loose enough so it can be drizzled, but not too runny. Set aside 15 minutes.","images":[],"step":2},{"title":"Toss broccolini","description":"Pile broccolini on tray, drizzle with oil, sprinkle with salt, pepper and garlic.","images":[],"step":3},{"title":"Roast for 12","description":"15 minutes until the broccolini floret ends are dark brown and crunchy (the best part!), and the broccolini stem is just tender. (But if you want it really soft, lower temp to 180C/350F and cook 20 min).","duration":13.5,"images":[],"step":4},{"title":"Plate up","description":"Transfer to serving plate, allow to cool until warm. Drizzle over tahini sauce, sprinkle with almonds or pine nuts and serve! Excellent served warm OR at room temp.","images":[],"step":5},{"description":"The Tahini Sauce goes brilliantly with other roasted vegetables too, including: carrots, cauliflower, broccoli, green beans and asparagus.","images":[],"step":6}]', '[]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["all-vegetable-sides","broccoli","quick-and-easy","side-salads","vegan-lifestyle"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_606208bf5626', 'en', 'US', 'Roasted Eggplant Lentil Salad (Aubergine Salad)', 'Recipe video above. Lentils and roasted eggplant (aubergine) is such a great combination - especially when you infuse the lentils with flavour by cooking them in a seasoned broth, and you try my method of roasting eggplant so they stay plump and juicy inside with great caramelisation on the outside! (For more roasted eggplant uses, visit this roasted eggplant recipe).Great to serve at a brunch as a main - it holds up well for hours. Serve warm, or at room temp. Serves 3 to 4 as main, 8 - 10 as a side.', 'https://www.recipetineats.com/tachyon/2020/07/Roasted-Eggplant-Lentil-Salad_4.jpg', 15, 1470, 1485, 4, '[{"id": "ing_lentils", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_egg", "quantity": {"value": 58.333, "unit": "carton of 12"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_feta_cheese", "quantity": {"value": 60.0, "unit": "block of 200g"}}]', '[{"ingredients":["1 cup dried green or brown lentils (or French/puy) (Note 1 for canned)","1 cup vegetable or chicken broth (or water + 1 bouillon cube, crumbled)","1 1/2 cups water","1 large garlic clove (, smashed, skin removed (Note 2))","Lemon peel (about 1.5 x 5 cm / 3/4 x 2\")","1 bay leaf (, dry or fresh)","2 sprigs thyme (, or 1/2 tsp dried thyme)","1 rib celery (, broken into 3 or 4 pieces (or just a handful of celery leaves, can skip))"],"purpose":"TASTY LENTILS!"},{"ingredients":["700g / 1.4 lb eggplant / aubergine (2 medium)","2 1/2 tbsp olive oil","1/4 tsp EACH salt and pepper"],"purpose":"Roasted Eggplant:"},{"ingredients":["2 tbsp lemon juice (or cider vinegar, white or red wine vinegar)","4 tbsp extra virgin olive oil","1 tsp Dijon mustard","1 garlic clove (, minced using garlic press)","1 tsp thyme leaves (, fresh (or 1/2 ts dried - can omit, or other herbs, Note 3))","1 tsp sugar (, optional)","1/2 tsp EACH salt + black pepper"],"purpose":"Garlic Lemon Dressing:"},{"ingredients":["250g/ 8 oz cherry tomatoes (, halved (large quartered))","2 handfuls rocket / arugula lettuce (, torn into 5cm/2\" pieces)","60g/ 2 oz feta (, crumbled (or more!))"],"purpose":"Salad:"}]', '[{"title":"Dressing","description":"shake in a jar.","images":[],"step":1},{"description":"Place Lentil ingredients in a saucepan, bring to simmer over medium heat. Place lid on then lower heat to medium low so it''s simmering gently.","images":[],"step":2},{"description":"Cook for 20 minutes (for al dente, my preference), or 25 minutes (for soft), stirring occasionally.","duration":20,"images":[],"step":3},{"description":"Drain, then pick out all the flavouring bits (garlic etc). BRIEFLY rinse to get grit off - don''t wash off all the flavour! Shake off excess water well.","images":[],"step":4},{"description":"Preheat oven to 240°C / 450°F (220°C fan). Line a tray with parchment/baking paper.","images":[],"step":5},{"title":"Cut eggplant into large cubes","description":"3 cm / 1.2\". Place in large bowl, drizzle with oil, salt and pepper.","images":[],"step":6},{"description":"Toss well, then immediately spread on tray and roast 20 minutes. Flip, then roast for a further 10 minutes - edges should be caramelised, soft inside, but they''re not shrivelled up and dismal.","images":[],"step":7},{"description":"Add tomato and rocket into lentils, drizzle over most of the Dressing then toss.","images":[],"step":8},{"description":"Pour onto serving platter. Pile over eggplant.","images":[],"step":9},{"description":"Drizzle eggplant with remaining Dressing, sprinkle with feta . Serve warm or at room temp! Great with a side of flatbread or this easy crusty bread.","images":[],"step":10}]', '["mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner","lunch"],"cuisine":["Western"],"categories":["all-vegetable-sides","beans-lentils","eggplant","lentil-recipes","salad-recipes-main-course","side-salads","vegan-lifestyle"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c738d2314315', 'en', 'US', 'Garlic Butter Roasted Mushrooms', 'Recipe video above. Here''s a simple, incredibly delicious way to roast mushrooms: tossed in garlic butter then roasted on a high temp to make them golden brown on the outside whilst keeping them juicy on the inside. The addition of olive oil stops the butter from burning and also adds a touch of extra flavour - but the dominant flavour is still butter (and garlic!). The lemon and thyme finishing touch is optional - it''s terrific plain - it''s an extra flavour option.Serves 2 as a main, 4 - 5 as a side.', 'https://www.recipetineats.com/tachyon/2018/10/Roasted-Mushrooms-Garlic-Butter_0.jpg', 5, 20, 25, 4, '[{"id": "ing_mushroom", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}]', '[{"ingredients":["500g / 1lb mushrooms (, button or Swiss brown / cremini OR 8 large (like portabello))","50g / 3 tbsp unsalted butter (, melted)","1 tbsp olive oil","2 garlic cloves (, finely minced)","1/2 tsp each salt and pepper"]},{"ingredients":["1 1/2 tbsp lemon juice","1 tsp fresh thyme leaves (parsley also good for colour)"],"purpose":"Optional finishing flavour:"}]', '[{"description":"Preheat oven to 220°C/450°F (200°F fan).","images":[],"step":1},{"description":"Toss mushrooms with butter, oil, garlic, salt and pepper in a large bowl using a rubber spatula.","images":[],"step":2},{"title":"Spread on a baking tray and roast for 25 minutes","description":"do not toss or turn.","duration":25,"images":[],"step":3},{"description":"Remove from oven. If using lemon and thyme, push mushrooms together onto one side of the tray, drizzle with lemon, sprinkle with thyme and toss. Serve immediately!","images":[],"step":4},{"description":"How to roast LARGE MUSHROOMS (eg portabello)","images":[],"step":5},{"description":"(Video here for large mushrooms) Place mushrooms cap side down (ie stems facing up) in a medium baking dish (so they are kind of snug - they shrink).","images":[],"step":6},{"description":"Spoon 1 tsp of butter over each mushroom, then use the rest to brush the edges (or carefully drizzle over edges).","images":[],"step":7},{"description":"Drizzle over olive oil, sprinkle with salt and pepper.","images":[],"step":8},{"description":"Roast for 20 minutes (tender but still a slight firmness) or 25 minutes (tender) - no turning. There will be juices in the pan and plenty pooled in the mushrooms caps.","duration":20,"images":[],"step":9},{"description":"Squeeze over a bit of lemon juice, sprinkle with thyme. Serve mushrooms, drizzled with pan juices (see notes for serving suggestions).","images":[],"step":10}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["all-vegetable-sides","dietary","dinner-tonight","easter-sides-warm-hearty","gluten-free-recipes","main-dishes","mushroom-recipes","mushrooms","quick-and-easy","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bf6e7621c638', 'en', 'US', 'Incredible BBQ Grilled Vegetables - marinated!', 'Recipe video above! An assortment of vegetables grilled on the BBQ until tender-crisp with charred edges, then while still hot, tossed in a Lemon Herb & Garlic Marinade so they suck up the flavour. Great served freshly made, even better the next day! See in post for serving ideas - antipasto / cheeseboard, starter, side dish, main, salad, or pasta. Oven roasted directions also included.', 'https://www.recipetineats.com/tachyon/2019/06/Marinated-Grilled-Vegetables_3.jpg', 20, 20, 40, 8, '[{"id": "ing_capsicum", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_es_asparagus", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.1, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.5, "unit": "pack of 100g"}}]', '[{"ingredients":["2 red capsicum/bell peppers","2 yellow capsicum/bell peppers","2 red onions","1 eggplant (, halved lengthwise, then 1.25cm/ 0.5\" thick semi circles)","2 zucchini (, 0.7cm / 1/3\" thick slices on diagonal)","2 bunches asparagus (, ends trimmed)","200g/ 7oz button mushrooms"],"purpose":"Vegetables (Note 1):"},{"ingredients":["1/4 cup (65ml) extra virgin olive oil","1 tsp each salt and pepper","3 cloves garlic (, minced)","1/4 cup parsley (, roughly chopped (or chives))"],"purpose":"Grilling/Roasting:"},{"ingredients":["1/3 cup (85ml) lemon juice","1/3 cup (85ml) extra virgin olive oil","2 tsp white sugar","2 garlic cloves (, minced)","1/2 tsp each salt and pepper","1/2 tsp each dried basil, parsley, oregano, thyme (Note 2)","1/2 - 1 tsp chilli flakes (adjust spice to taste, Note 3)"],"purpose":"Grilled Vegetable Marinade (Dressing):"}]', '[{"description":"Place ingredients in a jar and shake well. Set aside 10 minutes+.","images":[],"step":1},{"description":"Cutting Vegetables (see video):","images":[],"step":2},{"description":"Keep pieces large for easy handling on the BBQ (so you don''t have to turn hundreds of pieces!) and so they don''t fall through the grills.","images":[],"step":3},{"title":"Capsicum/bell peppers","description":"cut the \"walls\" off, then cut each each on the diagonal into fairly large pieces.","images":[],"step":4},{"title":"Onion (Note 4)","description":"keep the root end (hairy end!) in tact. Peel, cut in half, then cut into wedges through the root end.","images":[],"step":5},{"description":"Grilling/Roasting Vegetables:","images":[],"step":6},{"description":"Brush BBQ grills lightly with oil, then preheat to high. Or oven 250°C/480°F.","images":[],"step":7},{"description":"Place vegetables in a very large bowl or use a big tray. Drizzle with oil, sprinkle with salt, pepper and garlic. Toss with hands (there is no better way!).","images":[],"step":8},{"description":"Place on BBQ and cook until tender crisp with charred edges - cook times below. Then remove into large bowl.","images":[],"step":9},{"description":"Cook times:","images":[],"step":10},{"title":"Asparagus, zucchini","description":"grill 2 min each side. (Oven - 10 min, no flipping)","images":[],"step":11},{"title":"Capsicum, mushroom, onion","description":"grill 3 min each side (oven 15 min, flip at 10 min)","images":[],"step":12},{"title":"Eggplant","description":"grill 4 min each side. Jab in middle to ensure soft but not soggy! (oven 18 min)","images":[],"step":13},{"description":"While vegetables are still hot, drizzle over Dressing and toss.","images":[],"step":14},{"description":"Set aside 10 minutes+ before serving, sprinkled with parsley. See in post for serving ideas.","images":[],"step":15}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["all-vegetable-sides","grilling-ideas-and-recipes","side-dishes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eacdf979ea96', 'en', 'US', 'Caesar Salad - with homemade Caesar Salad Dressing', 'Recipe video above. This homemade Caesar Salad Dressing recipe will rival that of any great restaurant! Anchovy is key to proper flavour in the dressing - every self respecting restaurant uses it, so if you''ve had Caesar Salad out and loved it, you''ve eaten anchovies!Add chicken to make a meal, or serve it straight up the classic way.', 'https://www.recipetineats.com/tachyon/2016/05/Caesar-Salad_7.jpg', 20, 20, 40, 5, '[{"id": "ing_mayonnaise", "quantity": {"value": 0.375, "unit": "jar of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_milk", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 2.0, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_lettuce", "quantity": {"value": 30.0, "unit": "head"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["1 cup mayonnaise (Hellman''s or S&W Whole Egg) (Note 1)","1/2 tsp garlic (, finely minced (use garlic press, if you can))","2 anchovy fillets ( or 3/4 tsp Anchovy paste (Note 2))","2 tbsp fresh lemon juice","1 tsp Dijon mustard","1 tsp Worcestershire sauce","1/2 cup freshly grated parmesan cheese (, or 1/3 cup store bought grated parmesan cheese (Note 3))","3 - 4 tbsp milk (to adjust consistency)","1/4 tsp salt","1/4 tsp Black pepper"],"purpose":"Dressing"},{"ingredients":["2 - 3 slices white bread (, 2/3\" / 1.5cm thick (Note 4))","1 garlic (, cut in half)","1 tbsp olive oil","1/4 tsp salt"],"purpose":"Garlic Croutons"},{"ingredients":["150g / 5oz streaky bacon (, cooked and chopped)","10 cups cos / romaine lettuce (, chopped, wash & dried (1 large, 2 medium, 3 small) (Note 5))","Freshly grated parmesan (, for garnish)"],"purpose":"Salad"},{"ingredients":["2 - 4 eggs (, cooked to your taste, peeled and halved)","500g / 1lb chicken breast fillets (2 pieces)","1/2 tsp EACH salt and pepper","1 tbsp olive oil"],"purpose":"Optional Extras – Chicken & Egg"}]', '[{"description":"Whizz all ingredients in food processor until smooth, starting with 3 tbsp milk.","images":[],"step":1},{"description":"Taste and adjust salt and pepper as desired, and use milk to get the dressing to the desired consistency. (Note 6)","images":[],"step":2},{"description":"Set aside for 20 minutes+ to allow flavours to develop.","duration":20,"images":[],"step":3},{"description":"Place bacon into a cold skillet (no oil), then turn onto medium high. Cook until golden, turn, cook other side until golden. Remove onto paper towels, cool, then chop.","images":[],"step":4},{"description":"Garlic Croutons","images":[],"step":5},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":6},{"description":"Toast bread in the toaster for 1 minute (or oven for 2 minutes each side) until surface is dried but not browned.,","duration":1,"images":[],"step":7},{"description":"Rub both sides of each piece of bread with the cut side of the garlic (Note 7).","images":[],"step":8},{"description":"Remove crust from bread (optional) and cut into cubes - around 1.5 cups. Drizzle with 1 - 2 tbsp olive oil, sprinkle with salt, then bake until golden, shaking the tray once. Sandwich bread will take around 7 minutes, sourdough and similar breads take 12 - 15 min.","images":[],"step":9},{"description":"Place lettuce in bowl with 1/2 the Dressing. Toss well, taste, then decide if you want more Dressing.","images":[],"step":10},{"description":"Transfer to serving bowl. (Top with chicken and egg if using) Scatter over with bacon and croutons. Sprinkle with parmesan and serve!","images":[],"step":11},{"title":"OPTIONAL EXTRAS","description":"Chicken & Egg","images":[],"step":12},{"title":"Eggs","description":"Place the eggs in a saucepan and cover with water. Place over medium high heat and bring to simmer. Once the water is simmering, turn down to medium (gentle simmer) and cook for 3 min (for soft centres), 4 min for firm yolks and 6 min for hard boiled. Remove eggs, run under cold water for 15 sec then leave submerged in a bowl of cold tap water for 5 min. Peel then set aside. (Note 6)","duration":3,"images":[],"step":13},{"title":"Chicken","description":"Either pound the chicken to about 1.2cm/ 1/2\" even thickness, or slice each breast in half horizontally. Sprinkle both sides with salt and pepper. Use bacon fat remaining in skillet. Cook first side for 5 min, turn then cook the other side for 2 min. Remove, cover loosely with foil and rest for 5 min. Cut into slices.","duration":5,"images":[],"step":14}]', '["egg","fish","gluten","milk","mustard"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner","lunch"],"cuisine":["South Western"],"categories":["all-vegetable-sides","chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","leafy-greens","main-dishes","no-cook-food","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_19f13d87295c', 'en', 'US', 'Cinnamon Roasted Pumpkin', 'The flavour combination of caramelised roasted pumpkin with cinnamon is stellar and set off perfectly with tangy, creamy yoghurt and bursts of nutty crunch from the pine nuts. Simple to make, satisfying enough to have as a meal or a great side to accompany chicken, beef or lamb.', 'https://www.recipetineats.com/tachyon/2014/07/Cinnamon-Roasted-Pumpkin-2.jpg', 10, 30, 40, 4, '[{"id": "ing_pumpkin", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_cinnamon", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.15, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.5, "unit": "net of 500g"}}, {"id": "ing_pine_nuts", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1/4 Jap Pumpkin ((1 kg / 2lb), unpeeled, deseeded, cut into 6 wedges)","3 tbsp olive oil","1 tsp cinnamon","1/4 salt","Black pepper"],"purpose":"Roasted Pumpkin"},{"ingredients":["1/2 cup plain greek yoghurt (, loosened with a bit of water)","1/4 lemon","1 tbsp pine nuts (, toasted)","1 tbsp coriander leaves","1 birds eye chilli (, finely sliced)"],"purpose":"Garnish"}]', '[{"description":"Preheat oven to 200C/390F.","images":[],"step":1},{"description":"Combine olive oil, cinnamon, salt and pepper in a shallow dish large enough to fit the pumpkin wedges. Even a plate will work, it just needs to be large enough to lay the pumpkin wedge flat.","images":[],"step":2},{"description":"Place each side of the pumpkin wedge in the olive oil mixture, using your hands if needed to spread the cinnamon over each piece, including on the skin. Place pumpkin on baking tray and drizzle over any remaining olive oil.","images":[],"step":3},{"description":"Bake for 20 to 30 minutes until the pumpkin is golden and cooked through (no need to turn). (See notes on cooking tips)","duration":25,"images":[],"step":4},{"description":"When the pumpkin is cooked, remove from baking tray and place on serving platter. Drizzle over lemon juice. Rest for 5 to 10 minutes before garnishing.","duration":7.5,"images":[],"step":5},{"description":"If you are making it ahead, let it come to room temperature before putting on the other garnishes.","images":[],"step":6},{"description":"To serve, season with extra salt and pepper, drizzle over the yoghurt, scatter over pine nuts, coriander leaves and chilli.","images":[],"step":7}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner","lunch"],"cuisine":["Contemporary Middle Eastern"],"categories":["all-vegetable-sides","cuisines","easter-sides-warm-hearty","middle-eastern-recipes","pumpkin","pumpkin-squash","quick-and-easy","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4c234ed40853', 'en', 'US', 'Middle Eastern Roasted Eggplant with Couscous', 'Eggplant slathered in a fragrant chermoula paste, then roasted until soft and gooey, and piled high with a fresh couscous. Easy to prepare and absolutely divine. This is satisfying enough to be a meal on its own with just a very simple side salad. The recipe makes about twice the amount of couscous you actually need, but it''s difficult to make in a smaller quantity and also extra couscous on the side makes this a more complete meal. The couscous is versatile and you can easily add your own touch to it. Capers would be lovely, as would crumbled feta, sundried tomatoes, fresh tomatoes and cucumber.', 'https://www.recipetineats.com/tachyon/2014/06/Eggplant-Couscous-2-Version-2-680x1024-1.jpg', 15, 40, 55, 4, '[{"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_couscous", "quantity": {"value": 112.5, "unit": "pack"}}, {"id": "ing_sultanas", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_olives", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_almonds", "quantity": {"value": 0.15, "unit": "pack of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.75, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}]', '[{"ingredients":["2 medium eggplants"]},{"ingredients":["2 garlic cloves (, crushed)","2 tsp ground cumin","2 tsp ground coriander","1 tsp chilli flakes","1 tsp paprika","Rind of 1 medium lemon","4 tbsp olive oil","1/2 tsp salt"],"purpose":"Chermoula"},{"ingredients":["1/2 tsp salt","3/4 cup couscous","1/4 cup sultanas or currants","3/4 cup boiling water","1/4 cup roughly chopped green olives","1/4 cup flaked almonds (, dry toasted on stove or in oven)","1/4 cup scallions or spring onion (, chopped)","1/4 cup chopped cilantro (coriander) and mint (1/4 cup together)","Black pepper","Juice of 1/2 lemon","2 tbsp extra virgin olive oil"],"purpose":"Couscous"}]', '[{"description":"Preheat the oven to 350F/180C.","images":[],"step":1},{"description":"Slice the eggplant lengthwise, then use small knife to make diagonal criss cross scores deep into the eggplant, making sure you don''t cut the skin. (See notes)","images":[],"step":2},{"description":"Combine the chermoula ingredients and mix into a paste. Slather onto the eggplant.","images":[],"step":3},{"description":"Place on baking tray, flesh side up, and roast for 40 minutes until completely soft. The cooking time will vary depending on the size of the eggplant you are using.","duration":40,"images":[],"step":4},{"description":"Place the couscous, salt and sultanas into a bowl, add the boiling water and cover for 5 minutes.","duration":5,"images":[],"step":5},{"description":"Fluff the couscous with a fork, add the remaining ingredients and toss through to combine. Adjust seasoning to your taste.","images":[],"step":6},{"description":"To serve, pile each eggplant high with couscous, finish with a dollop of yoghurt (see notes for vegan alternative) and garnish with cilantro. Best served warm but also delicious at room temperature.","images":[],"step":7}]', '["gluten"]', '["vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["all-vegetable-sides","cuisines","eggplant","middle-eastern-recipes","quick-and-easy","side-dishes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_32be45094d73', 'en', 'US', 'Popcorn chicken - better than KFC!', 'Recipe video above. This is better than KFC because it''s actually crispy - KFC popcorn chicken is not, it''s soft and greasy! The flavour is remarkably similar with my copycat of the KFC''s 11 secret herbs and spices. It''s ridiculously good - you want to shovel it in your mouth by the handful!Relatively straightforward and on the easy end of frying recipes because it''s just shallow fried and takes just 2 minutes. Serve in cups or mini popcorn boxes with Honey Mustard Dipping Sauce for a fun meal or snack that everyone loves! Air fryer and baking options - not covered in this recipe, please see FAQ above for reason.', 'https://www.recipetineats.com/tachyon/2025/01/Popcorn-chicken_2-close-up.jpg', 25, 10, 35, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 0.75, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.188, "unit": "pack of 400g"}}, {"id": "ing_celery", "quantity": {"value": 0.05, "unit": "head"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_oil", "quantity": {"value": 2.5, "unit": "bottle"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["500g / 1lb chicken breast (, skinless boneless, tenderloin or boneless thighs (Note 1))"]},{"ingredients":["3/4 cup buttermilk (Note 2 for yogurt/milk sub)","1 1/2 tsp cooking salt / kosher salt (Note 3)","1 large egg (~50 - 55g, 2 oz in shell)"],"purpose":"Buttermilk marinade:"},{"ingredients":["1 1/2 cups flour (, plain / all purpose)","1/2 cup corn flour / cornstarch (makes it crispy!)"],"purpose":"Popcorn Chicken Breading (Note 4):"},{"ingredients":["1 tsp cooking salt / kosher salt (Note 3)","1/2 tsp celery salt (sub 1/4 tsp extra salt)","1 tsp black pepper","1 tsp regular paprika (aka sweet paprika, not hot or smoked)","1 tsp dried thyme (, crushed with fingers to make it finer)","1 tsp dried oregano (, crushed with fingers to make it finer)","3/4 tsp onion powder","2 tsp garlic powder","1/2 tsp mustard powder","1/2 tsp ginger powder","1/4 tsp cayenne pepper (, optional (tiniest background warmth, doesn''t make it spicy))"],"purpose":"KFC 11 Secret Herbs and Spices (Note 4):"},{"ingredients":["2 1/2 - 3 1/2 cups canola oil (2.5 cm / 1\" depth) (, or vegetable or peanut oil (Note 8 for re-use))"],"purpose":"To fry:"},{"ingredients":["1/2 batch Honey mustard dipping sauce (pictured in post)","Ketchup, tomato sauce,"],"purpose":"Dipping sauce suggestions"}]', '[{"description":"Abbreviated directions:","images":[],"step":1},{"description":"Marinade chicken 1 hour+ in Buttermilk Marinade. Dribble then rub 3 tbsp marinade in breading to make small clumps. Dredge chicken, fry 2 minutes at 180C/350F.","images":[],"step":2},{"description":"Marinade chicken:","images":[],"step":3},{"description":"Cut chicken into small 1.25 cm / 1/2\" cubes.","images":[],"step":4},{"title":"Marinade","description":"Whisk marinade in a bowl. Add chicken, stir to coat, then refrigerate for 1 hour (no longer than 24 hours).","images":[],"step":5},{"description":"Prepare breading:","images":[],"step":6},{"title":"Breading mixture","description":"Mix together Breading and all KFC Secret Herbs & Spices in a large bowl (larger surface area = coat more chicken in one go).","images":[],"step":7},{"description":"Clump = crunchy! Drizzle 3 tablespoons of the Marinade into the flour mixture. Use your fingers to rub in so you get lots of small lumpy bits all throughout (this fries up into extra crunchy bits, secret trick!).","images":[],"step":8},{"description":"Prepare to cook (work in specified order of steps):","images":[],"step":9},{"title":"Frying vessel (Note 5)","description":"Large saucepan / small pot ~20cm/8\" recommended for beginners. Large pot / deep skillet ~24cm/9.5\" or larger recommended only for capable cooks. Use heavy based (not light and flimsy), for safety and heat retention.","images":[],"step":10},{"description":"Preheat oven to 50°C/125°F, to keep cooked chicken warm.","images":[],"step":11},{"description":"Breading (PS I''m right handed):","images":[],"step":12},{"title":"Bread chicken","description":"Pick up a handful of chicken from the marinade with your left hand, then scatter across surface of the flour mixture. Spoon flour over chicken then toss with the spoon to coat.","images":[],"step":13},{"title":"Shake off excess (use right hand)","description":"Separate the chicken pieces and press the clumpy flour onto the chicken pieces. Pick up a handful, shake excess flour off through fingers (no need to be thorough). Spread chicken on tray. Repeat with remaining chicken. Voila! No clumpy flour-batter-caked fingers!","images":[],"step":14},{"title":"Separate and last minute coat (Note 6)","description":"Just before frying, use your fingers to briefly re-toss the chicken you''re about to cook in the residual flour on the tray (to freshen up the flour coating, as it sits around it sweats/gets wet), and make sure the chicken pieces are not stuck together.","images":[],"step":15},{"description":"Line a tray with paper towels (for draining cooked chicken). Preheat oven to 50°C/125°F to keep cooked chicken warm.","images":[],"step":16},{"title":"Heat oil","description":"Add oil to your pot to a depth of 2.5 cm / 1\". Heat it over medium high to 180°C/350°F (Note 7).","images":[],"step":17},{"title":"Fry 2 minutes","description":"Pick up some chicken and put it in a spider with large holes (Note 8) and shake so excess flour falls through (or use hands to shake off excess flour then then transfer into a scoop to lower into oil). Carefully lower chicken into the oil. Fry for 2 - 2.5 minutes until golden, separating any that get stuck together around halfway through.","images":[],"step":18},{"title":"Drain","description":"Scoop out with a spider and spread on a paper towel lined tray Keep cooked chicken warm in the oven and cook remaining chicken.","images":[],"step":19},{"title":"Serve chicken","description":"in popcorn boxes, for extra fun factor! - with dipping sauce of choice (pictured, Honey Mustard).","images":[],"step":20}]', '["egg","gluten","milk","mustard","peanuts"]', '["high_protein","keto_friendly","low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Southern","Western"],"categories":["american","chicken-breast-recipes","chicken-recipes","deep-fried-recipes","snacks"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_28f5dd915897', 'en', 'US', 'Chili dogs', 'Recipe video above. A pan-fried or BBQ sausage smothered in chili sauce in a hot dog bun. Cracker of a recipe for summer BBQ''s, gatherings with friends and game-day! My chili sauce is a copy-cat of the famous Ben''s Chili Bowl half-smoke chili dogs in Washington DC. Love how their boldly spiced chili sauce is thick and almost "smooth", so it stays in the hot dog better. I replicated this by blitzing the chili a bit. Releases flavour, thickens the sauce. Win!Also, skip the cheap hot dog "footy franks". Do what Ben''s does - use a good smoked sausage.', 'https://www.recipetineats.com/tachyon/2023/02/Chili-dog.jpg', 20, 210, 230, 6, '[{"id": "ing_smoked_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 2.5, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 7.5, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_sausages", "quantity": {"value": 0.012, "unit": "pack of 500g"}}, {"id": "ing_bread", "quantity": {"value": 6.0, "unit": "loaf"}}, {"id": "ing_onion", "quantity": {"value": 7.5, "unit": "pack of 1kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["3 tsp smoked paprika (sub plain paprika)","3 tsp cumin powder","1 tsp cayenne pepper (, adjust to taste)","1 1/2 tsp garlic powder","1 1/2 tsp onion powder","1 1/2 tsp oregano","1/2 tsp mustard powder","1/2 tsp black pepper"],"purpose":"Homemade chili powder (Note 1):"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, finely minced)","1/2 onion (, finely chopped)","1/2 red capsicum / bell pepper (, finely chopped)","500 g/1 lb ground beef / beef mince","1 tbsp tomato paste","400g / 14 oz canned crushed tomato","2 beef cubes (I like Oxo, easy to crumble, Note 2)","1 1/2 cups water","3/4 tsp cooking/kosher salt (, plus more to taste)"],"purpose":"Chili sauce:"},{"ingredients":["6 good smoked sausages (kransky, bratwurst, half-smoke) or hot dogs of choice (Note 3)","6 hot dog buns","1/2 white onion (, finely chopped)","Yellow mustard (I use Heinz American mustard)","2 cups Colby or Monterey Jack (, shredded (or other cheese of choice))","Plain crinkle cut potato chips (, optional side for serving (traditional!))"],"purpose":"Chili dogs:"}]', '[{"title":"Sauté aromatics","description":"Heat oil over medium high in a heavy based pot. Cook the onion, garlic and capsicum for 3 minutes.","duration":3,"images":[],"step":1},{"title":"Brown beef","description":"Add beef and cook, breaking it up as you go, until you no longer see raw meat. Add tomato paste and stir for 1 minute.","duration":1,"images":[],"step":2},{"title":"Sauce","description":"Add the spices, tomato, water, crumbled beef cube and salt. Stir well.","images":[],"step":3},{"title":"Slow cook 3 hours","description":"Bring the chili to a simmer then turn down to low, on a small burner. Put the lid partially on (to allow for sauce reduction). Simmer for 3 hours on low (goal: small bubble every now and then), stirring just to ensure the base doesn’t catch. OR put it in a 160°C/325°F oven for 3 hours (lid partially cracked).","images":[],"step":4},{"title":"Slow cooker (Note 4)","description":"Reduce water to 3/4 cup. After chili comes to a simmer on the stove, transfer everything to a slow cooker then cook on low for 6 to 8 hours on low.","images":[],"step":5},{"title":"Thicken sauce","description":"Remove 1 1/2 cups of the chili into a container so the head of a stick blender will be submerged under the chili. Then blitz until smooth (~ 15 seconds). Add the pureed sauce back in the pot and stir well.","images":[],"step":6},{"title":"Sauce goal","description":"As you stir, the remaining beef bits should become quite fine (rather than bolognese type chunks) because the beef is so tender. If the beef bits are not as small as desired, use a potato masher in the pot - it won''t take long. The chili sauce should be a thick sauce that mounds up a bit when you scoop it, not runny. (Note 5) Keep sauce warm.","images":[],"step":7},{"title":"Optional rest overnight","description":"Allow the sauce to cool then refrigerate overnight. As with most slow-cooked stewy things, the flavour improves! Reheat on the stove before proceeding.","images":[],"step":8},{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":9},{"title":"Grill/pan-fry","description":"Preheat a pan with 1/2 tbsp oil (or the BBQ) on medium / medium high. Brown the stages all over until they are heated through (they are already cooked inside, it''s just about heating/colour).","images":[],"step":10},{"title":"Assemble","description":"Place hot dog buns on a tray. Stuff with a sausage, top with a squiggle of mustard and a sprinkle of onion. Spoon over a generous amount of warm chili sauce, top with cheese.","images":[],"step":11},{"description":"Bake for 7 to 10 minutes or until the cheese is melted. Serve immediately. Traditionally with a mound of plain crinkle cut potato chips and an ice cold beer!","duration":8.5,"images":[],"step":12}]', '["milk","mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["American","Tex-Mex"],"categories":["american","beef","beef-mince-recipes","beef-recipes","grilling-ideas-and-recipes","mains","sandwiches-and-sliders","sausage-recipes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ef8334721dda', 'en', 'US', 'My best Pulled Pork', 'Recipe video above. This takes 36 hours to make - but it''s worth it. A 24-hour dry brine seasons the pork all the way through, followed by slow-roasting for 12 hours at a really low temperature. I would not tell you to roast a pork for 12 whole hours if I was not 100% sure that this produces the very best results! It really does, and the reason is simple: lower heat means less moisture loss which means more succulent meat. Plus, a great bark on the surface that everybody loves about traditional BBQ food. It’s my favourite part!', 'https://www.recipetineats.com/tachyon/2022/10/12-hour-BBQ-pulled-pork_7-3.jpg', 15, 720, 735, 15, '[{"id": "ing_pork_shoulder", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_beer", "quantity": {"value": 1.136, "unit": "bottle of 330ml"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.75, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.2, "unit": "jar of 50g"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.5, "unit": "bottle of 500ml"}}, {"id": "ing_ketchup", "quantity": {"value": 0.9, "unit": "bottle of 500g"}}, {"id": "ing_molasses", "quantity": {"value": 45.0, "unit": "jar"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 20.0, "unit": "bottle"}}, {"id": "ing_tabasco", "quantity": {"value": 2.0, "unit": "unit"}}]', '[{"ingredients":["4 - 5 kg / 8 - 10 lb pork butt / Boston butt / square cut pork shoulder (skinless, bone in, fat cap on, Note 1)","1 1/2 cups beer (, any except dark beers like Guinness (Note 2))","1 cup water"]},{"ingredients":["6 tbsp brown sugar","2 tbsp paprika powder","1 tbsp garlic powder","1 tbsp onion powder","1 tbsp mustard powder","2 tsp cumin powder","2 tsp dried oregano","1 tsp cayenne pepper (can omit)","2 tbsp cooking/kosher salt* (Note 4)","2 tsp black pepper"],"purpose":"RUB (Note 3):"},{"ingredients":["1 cup apple cider vinegar (Note 5)","3 cups ketchup (or Aussie tomato sauce)","1 cup water","3 tbsp molasses (original, not backstrap, Note 6)","2/3 cup brown sugar","4 tsp Worcestershire sauce","2 tsp Tabasco (optional spiciness)","4 tsp mustard powder","3 tsp garlic powder (sub onion powder)","2 tsp cooking/kosher salt (Note 4)","2 tsp black pepper"],"purpose":"BARBECUE SAUCE:"}]', '[{"title":"Dry brine overnight (Note 7)","description":"Pat the pork dry and place in a large ceramic dish. Mix Brine ingredients in a small bowl and rub it all over the pork, being sure to get into the cracks and crevices. Turn it fat side up (smoother side) covered with as much rub as possible. Refrigerate uncovered for 24 hours.","images":[],"step":1},{"description":"Preheat oven to 110°C (both fan-forced and standard) / 230°F.","images":[],"step":2},{"title":"Prepare for roasting","description":"Transfer pork to a roasting pan (do not wipe the rub off) with the fat side up. Discard any liquid and residual rub left in the brining dish. Pour beer and water around the pork, topping up with extra water as needed so the liquid level is 2.5 cm / 1\" (insurance against pan going dry).","images":[],"step":3},{"title":"Slow roast 12 hours (Note 8)","description":"Roast, uncovered, for 12 hours, or until the internal temperature reaches 95°C/203°F and the meat falls apart effortlessly using two forks. ⚠️ Make sure your oven does not automatically turn off mid cook, many have auto-off functions that kick in at 12 hours (also factor in oven pre-heating time)!","images":[],"step":4},{"title":"Shred","description":"Transfer the pork to a large pan (reserve juices in roasting pan). Rest for 20 minutes then shred with tongs / forks - it will be effortless! You can discard the fat cap at this stage if you want. I leave some, it makes the shredded pork even juicier.","duration":20,"images":[],"step":5},{"title":"Sauce it","description":"Pour 3/4 cup of the juices from the roasting pan and 1 cup of Barbecue Sauce (see below) over the pork, and toss.","images":[],"step":6},{"description":"Serve Pulled Pork with remaining Barbecue Sauce on the side so people can help themselves. Either make a big Southern feast with a side of cornbread, coleslaw and potato salad or macaroni salad. Or make Pulled Pork buns with soft rolls stuffed with coleslaw, Pulled Pork and the BBQ sauce!","images":[],"step":7},{"description":"Barbecue sauce:","images":[],"step":8},{"description":"Place ingredients in a large saucepan and whisk to combine.","images":[],"step":9},{"title":"Simmer 45 minutes","description":"Bring to simmer on medium heat, then reduce to a low simmer for 45 minutes. Stir occasionally.","duration":45,"images":[],"step":10},{"title":"Add pork juices","description":"When the pork is cooked, add 1/2 cup of the juices from the roasting pan into the BBQ sauce and simmer for 5 minutes. Use water to control thickness – it should have a thick syrupy consistency. Serve warm or at room temperature (not fridge cold).","duration":5,"images":[],"step":11}]', '["mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Southern"],"categories":["american","iconic-dishes","main-dishes","mains","pork","pork-recipes","slow-cooked-fall-apart","sunday-supper","super-bowl-party-food","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a6efcb1570e6', 'en', 'US', 'Mapo Tofu', 'Recipe video above. Mapo Tofu is in my all-time Top 5 foods. That''s how much I love it. So I am beyond excited to bring you this Sichuan classic that is everything a great, authentic Mapo Tofu should be - fiery, deeply savoury, unapologetically bold and so incredibly delicious, I almost wept with happiness!It''s a recipe from our RTM Chef Xiao (Hannah) Huang, born and raised in Sichuan. So she knows a thing or two about Mapo Tofu! See all Hannah''s recipes here.See Notes section for spiciness and how to control.PS I know 100g/3.5oz pork doesn''t sound like a lot compared to 600g/21oz tofu, but it seems like so much more in the finished dish! Mapo tofu magic :)', 'https://www.recipetineats.com/tachyon/2026/07/Mapo-tofu-0.jpg', 20, 25, 45, 4, '[{"id": "ing_black_pepper", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_tofu", "quantity": {"value": 2.0, "unit": "pack of 300g"}}, {"id": "ing_water", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.01, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 10.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_black_beans", "quantity": {"value": 0.037, "unit": "can of 400g"}}, {"id": "ing_broad_bean_sauce_paste", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 tbsp whole pink Sichuan peppercorns (or green) - for 1 tsp powder (Note 1)"]},{"ingredients":["600g/ 21 oz silken tofu (, cut into 1.5cm / 0.6\" squares (Note 2))","2 1/2 cups water","1 tsp cooking salt / kosher salt (halve for table salt, +50% for salt flakes)","1/2 tsp dark soy sauce (Note 3)"],"purpose":"Blanched tofu:"},{"ingredients":["1 tbsp canola oil (, or other neutral oil eg. vegetable, peanut)","100g/ 3.5 oz pork mince (ground pork), preferably 20% fat but even lean is fine, or beef (Note 4)","1 tsp light soy sauce (or regular / all-purpose soy, not dark soy sauce)"],"purpose":"Golden pork:"},{"ingredients":["1/4 cup canola oil (Note 5)","2 tbsp garlic (, finely minced (4 large cloves))","2 1/2 tbsp ginger (, finely minced with a knife)","1 tbsp preserved black beans (aka salted black beans, fermented black beans), finely chopped (Note 6)","1 tbsp broad bean sauce/paste (, we use Pixian doubanjiang, the spicy Sichuan version (Note 7))","1 tsp light soy sauce (or regular / all-purpose soy, not dark soy sauce)","2 tsp chilli powder (, pure - NOT US chili powder blend (Note 8))","1 tsp smoked paprika (substitute regular/sweet paprika)","1 tsp white sugar","1 green onion stem (, finely sliced)","3/4 cup beef stock/broth (, low sodium)","1 tsp sesame oil (toasted ie. brown, not un-toasted which is yellow)"],"purpose":"Mapo tofu:"},{"ingredients":["2 tsp cornflour / cornstarch","1/4 cup water"],"purpose":"Cornflour slurry"},{"ingredients":["White rice"],"purpose":"Serving"}]', '[{"description":"Toast, grind and sift Sichuan peppercorns. Blanch tofu 3 min. Cook pork until golden, remove.","images":[],"step":1},{"description":"Sauté garlic and ginger 90 sec, then black bean and bean sauce 3 min, then chilli and paprika 30 sec. Add beef stock and soy, simmer tofu 10 min. Add sugar, pork, 1/2 tsp Sichuan pepper, then thicken sauce with cornflour slurry. Stir in green onion and sesame, serve garnished with 1/2 tsp Sichuan pepper.","images":[],"step":2},{"description":"Sichuan pepper powder:","images":[],"step":3},{"title":"Toast peppercorns","description":"In a small skillet over medium heat (no oil), toast the peppercorns for 2 - 3 minutes until fragrant (some will “pop” and crack open).","duration":2.5,"images":[],"step":4},{"title":"Grind and sift","description":"Transfer to a mortar and pestle, or spice grinder. Cool for a few minutes, then grind as finely as possible. Sift through a fine mesh sieve to remove the coarser husks (discard these). Measure out 1 teaspoon to use in the dish.","images":[],"step":5},{"title":"Blanch","description":"Bring the water, dark soy and salt to a boil in a large saucepan over higher heat. Carefully add the tofu, then once it comes back up to the boil, lower the heat slightly so it’s simmering rapidly and simmer for 3 minutes. This step removes raw beany flavour and seasons the tofu. And don''t worry, the tofu won''t fall apart!","duration":3,"images":[],"step":6},{"title":"Remove","description":"Use a slotted spoon to carefully scoop the tofu out into a bowl. Set aside.","images":[],"step":7},{"title":"Cook golden pork","description":"Heat the oil in a wok over high heat. (Note 9) Cook pork, breaking it up as you go, until you no longer see pink. Then lower the heat to medium and cook for another 2 minutes until the pork has golden bits. Add the light soy sauce, stir for 5 seconds, the remove the pork into a bowl and set aside.","duration":0.08333333333333333,"images":[],"step":8},{"title":"Sauté aromatics","description":"Reduce heat to low. Add the rest of the oil into the wok, then cook the garlic and ginger for 90 seconds. Add black beans and broad bean paste, cook for 3 minutes, stirring constantly. Add chilli powder and paprika, cook for 30 seconds..","duration":1.5,"images":[],"step":9},{"title":"Simmer","description":"Add the beef stock and light soy. Turn the heat up to medium high, then once it starts bubbling, gently add the tofu (discard any excess water pooled in the tofu bowl). Simmer gently for 10 minutes (lower heat as needed), gently scraping the base with a rubber spatula every now and then to ensure it doesn’t catch (I push across base, avoid stirring as tofu will break). There should still be plenty of liquid at the end, mapo tofu is saucy.","duration":10,"images":[],"step":10},{"title":"Cornflour slurry","description":"Mix the water and cornflour together. This will thicken the sauce.","images":[],"step":11},{"title":"Thicken sauce","description":"Add the sugar, pork mince, 1/2 teaspoon sichuan powder. Stir gently using the rubber spatula. Pour the cornflour slurry all over the surface (not in one place) then gently stir again.","images":[],"step":12},{"title":"Finish and serve","description":"Stir in most of the green onion (reserve a little for garnish) and sesame oil. Pour into a serving bowl. Sprinkle with remaining Sichuan pepper and garnish with green onion. Serve over rice!","images":[],"step":13}]', '["gluten","peanuts","sesame","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese","Sichuan"],"categories":["asian-recipes","asian-takeout","chinese-recipes","iconic-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0350dff8c6de', 'en', 'US', 'Easy Chinese Beef Stir Fry', 'Recipe video above. This is my classic Chinese Beef Stir Fry. It''s easy and fast, and really does taste just like your favourite Chinese restaurant thanks for the stir fry sauce (the secret is Chinese cooking wine).Great recipe to use up whatever leftover greens you have in the fridge! And you''ll love the velveting beef technique - simple and highly effective Chinese restaurant method for succulent, soft beef in stir fries.Tip: Instead of making this Sauce, you can use Charlie, my All Purpose Stir Fry Sauce (see Note 3)', 'https://www.recipetineats.com/tachyon/2015/12/Chinese-Beef-Stir-Fry_8.jpg', 15, 8, 23, 3, '[{"id": "ing_beef_steak", "quantity": {"value": 0.198, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 2.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_bok_choy", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["7 oz / 200 g beef rump steak or flank (, or any other quick cooking steak cut (Note 1))","1/2 tsp baking soda / bi-carbonate soda (, for velveting (Note 2))"],"purpose":"Velveting the beef (tenderising)"},{"ingredients":["2 tbsp soy sauce, light or all-purpose (NOT dark soy (Note 4))","1 tbsp oyster sauce","2 tbsp Chinese cooking wine ( OR Mirin (Note 5))","1 tsp white sugar","1/2 tsp sesame oil (, toasted (brown) not untoasted (yellow))","Pinch white pepper (, substitute with black pepper)"],"purpose":"Sauce (Note 3)"},{"ingredients":["3 tsp cornstarch / corn flour","1/2 cup water (, separated)"],"purpose":"Sauce thickener"},{"ingredients":["1 1/2 tbsp peanut oil","1 garlic clove (, finely minced with a knife)","1/2 small onion (, sliced (yellow, brown or white))","1/2 red capsicum / bell pepper (, sliced into 7mm / 1/3\" thick slices)","1 small carrot (, peeled, halved lengthwise and sliced thinly on the diagonal)","2 bok choy (, cut leaves from stems, cut thick stems lengthways to make them all roughly the same width)","2 green onion (, cut into 1.5\"/3cm pieces, firm white end separated from soft green parts)"],"purpose":"Stir Fry"},{"ingredients":["Steamed white rice","Sesame seeds (optional)"],"purpose":"To Serve"}]', '[{"description":"Abbreviated recipe","images":[],"step":1},{"description":"Tenderise beef 20 minutes, rinse, toss with 1.5 tbsp sauce. Mix in cornflour then water into Sauce. Stir fry in this order: onion + garlic > beef > carrot + capsicum + bok choy stems + green onion stems > sauce > wilt bok choy leaves + green onion. Serve!","images":[],"step":2},{"description":"Velvet beef (tenderise)","images":[],"step":3},{"title":"Velvet beef","description":"Place the beef in a bowl. Sprinkle the baking soda over then use your fingers to toss the beef to coat as evenly as possible. Set aside for 20 minutes (no longer).","duration":20,"images":[],"step":4},{"description":"Rinse the beef under tap water in a colander to remove baking soda. Shake and pat off excess water (doesn''t need to dry fully, just don''t want it soaking). Put in a bowl.","images":[],"step":5},{"description":"Cook stir fry","images":[],"step":6},{"title":"Sauce","description":"Mix ingredients together. Measure out 1 1/2 tablespoons and use it to coat the beef. To the remaining sauce, mix in the cornflour until lump-free, then add the water.","images":[],"step":7},{"title":"Cook aromatics","description":"Heat the oil in a large non-stick pan or wok over high heat. Add the onion and garlic, cook for 10 seconds.","duration":0.16666666666666666,"images":[],"step":8},{"description":"Add the beef and cook until it changes colour from red to light brown but not cooked through.","images":[],"step":9},{"title":"Vegetables #1","description":"Add the capsicum, carrots, bok choy stems and white part of the green onions. Stir fry for 1 minute","duration":1,"images":[],"step":10},{"description":"Add Sauce, then stir until it starts to bubble (it will thicken quickly)","images":[],"step":11},{"title":"Leafy vegetables","description":"Add the bok choy leaves and green part of the green onions. Toss for another 30 seconds to 1 minute until they are just wilted, the sauce thickens and becomes glossy, coating everything nicely.","images":[],"step":12},{"title":"Serve immediately with rice","description":"or for a low carb, low cal option, try Cauliflower Rice! Garnish with sesame seeds, if desired.","images":[],"step":13}]', '["gluten","peanuts","sesame","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","beef-recipes","chinese-recipes","dinner-tonight","main-dishes","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_04b91e1bf760', 'en', 'US', 'Korean Beef Bulgogi Rice Bowls - the easy way', 'Recipe video above. This has gone straight to the top of my favourite quick way to use beef mince! An easy version of Korean Beef Bulgogi, one of Korea''s most famous food exports, made with ground beef rather than pricey steaks but using an authentic Bulgogi marinade so it takes a fraction of the effort and cost. I’ve made rice bowls, there''s many ways to serve this - noodles, rice wraps, burritos or tacos (so trendy!). See in post for list!PS Don''t skip the apple and grated onion. This is what sets bulgogi apart from generic soy + sugar + garlic "Asian" sauces!', 'https://www.recipetineats.com/tachyon/2025/09/Easy-Korean-Bulgogi-Beef-Bowls_7.jpg', 15, 10, 25, 4, '[{"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 15.0, "unit": "pack of 1kg"}}, {"id": "ing_apples", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.15, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_carrot", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 4.5, "unit": "head"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}]', '[{"ingredients":["500g / 1 lb beef mince ((ground beef), any fat % you like)","1 tbsp canola oil (, or any other plain flavoured oil, + 2 tsp (to wilt baby spinach))"]},{"ingredients":["1 tbsp onion (, finely grated (~1/4 onion) (Note 1))","3 tbsp red apple (, finely grated (skin on is fine, ~1/2 apple) (Note 1))","3 garlic cloves (, finely grated)","1 tsp ginger (, finely grated)","2 1/2 tbsp soy sauce ( - all-purpose or light (Note 2))","1 tbsp sesame oil","1 tbsp mirin (, omit for no alcohol (Note 3))","1 tbsp brown sugar","1/8 tsp black pepper"],"purpose":"Bulgogi sauce (don’t skip the onion & apple!):"},{"ingredients":["2 tbsp soy sauce ( - all-purpose or light (Note 2))","1 tbsp sesame oil","2 tsp brown sugar","2 tsp rice vinegar (or apple cider vinegar)"],"purpose":"Rice bowl drizzle sauce:"},{"ingredients":["white rice (medium or short grain, if you can)","4 large handfuls baby spinach (or similar chopped leafy greens - cabbage, kale)","1 large carrot (, peeled and julienned or grated using box grater (I use a julienne shredding tool))","1 avocado (, mashed)","1/4 cup pickled ginger (, I like pink for colour)","1 1/2 cups baby cos / romaine lettuce (, torn into bite size pieces)","1 tsp white sesame seeds","1 green onion (, finely sliced)"],"purpose":"For rice bowl (very flexible!):"}]', '[{"title":"Sauces","description":"Mix the Bulgogi sauce in a bowl, and the rice bowl drizzle sauce in a separate bowl.","images":[],"step":1},{"title":"Wilt spinach","description":"Heat the 2 teaspoons of oil in a large non-stick pan over high heat. Add half the spinach, toss with tongs until semi wilted (~30 sec), then add the rest. Toss until wilted (~ 1 minute) then remove into a bowl.","images":[],"step":2},{"title":"Cook Bulgogi beef","description":"Add 1 tablespoon oil to the pan. Still on high heat, add the beef and cook, breaking it up as you go, until you no longer see raw beef. Add the Bulgogi sauce, then let it simmer rapidly, stirring every now and then, until the sauce is mostly evaporated. Then stir regularly until the beef gets a bit of lovely caramelisation on it, but is still moist from the sauce.","images":[],"step":3},{"title":"Assemble","description":"Spoon beef over rice, place spinach and carrot. Top with pickled ginger and a dollop of mashed avocado. Tuck lettuce down the side. Sprinkle with sesame seeds and green onion. Serve with sauce for drizzling all over everything before jumbling it all up and digging in!","images":[],"step":4}]', '["gluten","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","korean fusion"],"categories":["asian-recipes","beef-mince-recipes","beef-recipes","modern-asian","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_004ad51c5489', 'en', 'US', 'Easy Crispy Thai Pork Bites with Sticky Sweet Chilli Sauce', 'Recipe video above. This is the sort of dish you find at modern Thai restaurants - golden cubes of pork tenderloin, crispy on the outside and succulent inside, tossed in a sticky limey, sweet chilli sauce.6 ingredients. Gluten free. No deep frying. All the flavour. None of the fuss! Dinner on the table in 20 minutes.PS Haven''t tried air frying but confident it will work great!', 'https://www.recipetineats.com/tachyon/2025/09/Crispy-Thai-Pork-Bites-Sweet-Chilli-Sauce_4.jpg', 10, 10, 20, 4, '[{"id": "ing_pork", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.056, "unit": "pack of 400g"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 0.75, "unit": "pack of 100g"}}, {"id": "ing_ime_juice", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["600 g / 1.2 lb pork tenderloin (, cut into 2cm/0.8\" cubes (Note 1))","1 tbsp fish sauce (Note 2)","1 1/2 tbsp + 1/2 cup cornflour / cornstarch","> 1 cup neutral flavoured oil (, 0.5cm / 0.2\" depth (canola, sunflower, vegetable, peanut oil - not olive oil))"],"purpose":"Crispy pork bites:"},{"ingredients":["1/2 cup sweet chilli sauce (Note 3)","1 1/2 tbsp lime juice","1 tbsp fish sauce (Note 2)","2 garlic cloves (. finely grated)"],"purpose":"Sweet chilli sauce:"},{"ingredients":["Coriander/cilantro leaves (, roughly torn by hand, optional)","Lime wedges (, optional)","Jasmine rice (, or other rice of choice)"],"purpose":"Garnish and serving:"}]', '[{"description":"Toss pork with fish sauce and 1.5 tbsp cornflour, then coat in 1/2 cup cornflour, shake off excess. Cook in 2 batches for 3 min until golden, remove from oil. Simmer sauce 3 min, toss to coat pork, serve.","duration":3,"images":[],"step":1},{"description":"Toss the pork with the fish sauce, then the 1 1/2 tbsp cornflour. The coating should be a bit sticky.","images":[],"step":2},{"title":"Crispy coating","description":"Sprinkle over the 1/2 cup of cornflour and toss with fingers to coat each piece, separating pieces stuck together. Give each piece a light squeeze in your fist to make the cornflour stick - you can do 2 or 3 pieces at a time in each hand. Drop into a colander, then give it a shake to remove excess cornflour - important step. (Note 4)","images":[],"step":3},{"description":"Heat 0.5 cm / 0.2\" oil in a non-stick pan or large pot over high heat - dip a piece of pork in, it should sizzle straight away.","images":[],"step":4},{"title":"3 minute cook","description":"Spread half the pork in the oil. Cook for 1 minute undisturbed until golden. Flip then cook for another 2 minutes (3 minutes in total, including time it takes to flip) or until golden and crisp. Don''t overcook - tenderloin is lean!","duration":1,"images":[],"step":5},{"title":"Drain","description":"Remove with a slotted spoon onto a paper towel-lined tray to drain. Cook remaining pork. Taste-test one \"just to check\" crispiness! ;)","images":[],"step":6},{"title":"Sauce","description":"Pour out all the oil (strain and re-use, it''s very clean). Return the pan to medium heat. Add the Sauce ingredients, stir and let it simmer for 2 minutes until it thickens into a syrupy consistency.","duration":2,"images":[],"step":7},{"title":"Quick toss","description":"Add pork, toss quickly to coat.","images":[],"step":8},{"description":"Serve immediately over rice, sprinkled with a little coriander and a lime wedge. I like to serve it classic Thai street-food style with plain tomato and cucumber wedges (no dressing) - the freshness is great with this dish!","images":[],"step":9}]', '["fish","peanuts"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["modern thai"],"categories":["asian-recipes","cuisines","mains","modern-asian","pork","pork-recipes","quick-and-easy","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_58a74d9254a2', 'en', 'US', 'Crispy Chinese Lemon Chicken - old school style!', 'Recipe video above. I like my Chinese Lemon Chicken the old school way, with a crispy battered cutlet sliced then sauced! The twice-fried Chinese fry batter used here stays crisper than regular batters (also less greasy) but once doused with the lemon sauce, it''s best served and eaten fast! Lemon sauce has a high water content so the crust will never stay crispy as long as other Chinese fried foods like, say, Honey Prawns.You''ll love the lemon sauce - brighter flavour and not tooth-achingly sweet like restaurants often are. For crispy bite size pieces, use the sauce in this recipe with the chicken from the Crispy Chinese Honey Chicken.', 'https://www.recipetineats.com/tachyon/2025/08/Crispy-Chinese-Lemon-Chicken_0.jpg', 20, 10, 30, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.094, "unit": "pack of 400g"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.008, "unit": "tub of 150g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.375, "unit": "tub of 200g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}]', '[{"ingredients":["4 x 125g/3oz chicken thigh fillets (, skinless and boneless (or 2 breasts - Note 1))","1/2 tsp cooking salt / kosher salt","1/4 cup cornflour / cornstarch","1 - 1 1/2 litres (4 - 6 cups) vegetable or canola oil (, for frying - 4cm / 1.6\" depth (re-usable, Note 2))"]},{"ingredients":["1/3 cup cornflour / cornstarch","1/3 cup + 1 tbsp plain flour (all-purpose flour)","1/2 tsp cooking salt / kosher salt","1/4 tsp baking powder","1/2 cup COLD soda water (, not sparking mineral water (Note 3))"],"purpose":"STAY-CRISP FRY BATTER"},{"ingredients":["6 tsp cornflour/cornstarch","1/2 cup chicken stock/broth (, low sodium)","1/2 cup lemon juice (, fresh)","1/3 cup white sugar","1/2 tsp garlic (, finely grated)","1/2 tsp ginger (, finely grated)","1 tbsp Chinese cooking wine (can omit for alcohol-free)"],"purpose":"LEMON SAUCE"},{"ingredients":["Lemon slices (, to serve (optional))","1 green onion (, finely sliced on the diagonal, to serve (optional))"],"purpose":"GARNISH (optional)"}]', '[{"description":"Pound chicken to 0.7cm / 1/3\", salt, dust with cornflour. Dip in batter, fry 3 min at 160°C/320°F, cool 20 min, fry again 3 min at 200°C/390°F until dark golden and crispy. Slice, serve with sauce (simmer 3 min).","images":[],"step":1},{"title":"Refrigerate batter dry","description":"Whisk the cornflour, flour, baking powder and salt in a bowl, then put it in the fridge which you proceed with other prep (Note 4)","images":[],"step":2},{"title":"Pound chicken","description":"Place chicken on a cutting board and cover with a freezer bag or similar (I use Go-Between, Note 5) then pound with a meat mallet or bottom of a skillet until it is an even 0.7cm / 1/3\" thick. Sprinkle both sides with the 1/2 teaspoon of salt.","images":[],"step":3},{"title":"Dust","description":"Spread the cornflour on a plate and dust each side of the chicken with it, shaking off excess. Put on a plate and set aside while you keep preparing.","images":[],"step":4},{"description":"Preheat oil to 160°C/320°F in a large heavy based pot (mine is 24cm/9.4\"). The oil needs to be at least 4cm/1.6\" depth so the chicken floats.","images":[],"step":5},{"title":"Finish batter","description":"Remove bowl from the fridge, add soda water and whisk just until combined, then stop - some small lumps are ok, better than whisking to death (makes crust less puffy and light). It should be a fairly thin batter, enough to coat the chicken but fairly thinly.","images":[],"step":6},{"title":"Fry #1","description":"Dip a piece of chicken in the batter and let the excess drip off, then carefully place in the oil. Do another piece (if it will fit). Fry for 3 minutes until very pale golden. Remove onto a paper towel lined tray and repeat with remaining chicken.","duration":3,"images":[],"step":7},{"description":"Cool chicken for 20 minutes. (Note 6) Meanwhile, make the sauce.","duration":20,"images":[],"step":8},{"title":"Lemon Sauce","description":"Place the cornflour and a splash of the chicken stock in a small saucepan. Whisk until lump-free, then add remaining stock and sauce ingredients. Whisk and bring to a simmer over medium heat, then let it simmer for 3 minutes, whisking every now and then until it becomes a thin honey consistency. At first, it will go very thick (too thick for sauce) then it becomes thinner. Remove from heat, cover and keep warm (reheated if needed to loosen).","duration":3,"images":[],"step":9},{"title":"Fry #2","description":"Heat the oil to 200°C/390°F. Fry 2 pieces of chicken for 3 minutes until deep golden and super crispy, turning the chicken in the oil at the halfway mark. Remove onto a paper towel lined tray and repeat with remaining chicken.","duration":3,"images":[],"step":10},{"title":"Serving","description":"Cut the chicken into 2cm thick slices (3/4\"), transfer onto individual or shared serving plate. Pour over the Lemon Sauce, garnish with green onions and lemon slices if using. Serve with steamed rice (see in post for more side options).","images":[],"step":11}]', '["gluten"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken","chicken-breast-recipes","chicken-recipes","chinese-recipes","deep-fried-recipes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6e006a653319', 'en', 'US', 'Pork Adobo', 'Recipe video above. Pork Adobo is the pride of the Philippines - one bite and you''ll be hooked! Pork braised until meltingly tender in an intense soy-garlic sauce that reduces down to a glaze, served over steaming rice, this is food so good yet so simple to make, you''ll be shaking your head in disbelief.Our adobo sauce has a well rounded flavour, intensely savoury but not overly salty or too sour (some restaurants make it really sour), and not too sweet. The sauce is meant to be thin so a little goes a long way on your rice.Slow cooker not recommended, sorry, see Note 6.', 'https://www.recipetineats.com/tachyon/2025/08/Pork-adobo-served-with-rice.jpg', 10, 120, 130, 4, '[{"id": "ing_pork_shoulder", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 13.333, "unit": "pack of 3 heads"}}, {"id": "ing_water", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.5, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.03, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_pineapple", "quantity": {"value": 6.0, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 2.0, "unit": "kg"}}]', '[{"ingredients":["1 kg/ 2 lb pork shoulder (the parts ribboned with fat not lean parts), skinless, cut into 6cm/2.5\" cubes - or belly (Note 1)","2 tbsp vegetable oil (, or any other neutral flavoured oil)","1 large onion (, cut in half then 0.8\" / 1/3\" wedges)","8 cloves garlic (, finely sliced)","3 cups water","1/2 cup light soy sauce (, sub regular/all-purpose soy (Note 2))","1 1/2 tsp dark soy sauce (Note 2)","1/4 cup rice vinegar (sub regular white vinegar)","3 tbsp (tightly packed) brown sugar","1 1/2 tsp black peppercorns (, can omit (Note 3))","5 bay leaves (, preferably fresh, dried ok too)"]},{"ingredients":["6 pineapple rings (, each cut into 8 pieces, from canned pineapple in juice not syrup, or 2 cups fresh pineapple pieces)","2 tsp vegetable oil (, or any other neutral flavoured oil)"],"purpose":"Optional pineapple (Note 4):"},{"ingredients":["1 green onion (, finely sliced)","2 batches jasmine rice"],"purpose":"Garnish/serving:"}]', '[{"description":"Brown pork, remove, sauté onion and garlic, add everything else. Return pork, bring to boil, slow cook 1 1/2 hours until fall-apart. Caramelise pineapple pieces. Remove pork, reduce sauce to 1 1/2 cups (375 ml), stir in pork and caramelised pineapple until warmed. Serve over rice!","images":[],"step":1},{"title":"Sear pork","description":"Heat the oil in a large heavy based pot over high heat. Sear half the pork until golden all over - about 4 minutes - then remove into a bowl. Repeat with remaining pork, add to the bowl.","images":[],"step":2},{"title":"Sauté","description":"Reduce heat to medium. Add the onion, cook for 2 minutes. Add garlic and cook for another minute until the onion is softened.","duration":2,"images":[],"step":3},{"title":"Braising liquid","description":"Add water, soy sauces, vinegar, sugar, peppercorns and bay leaves. Stir. Add the pork back in, including any juices accumulated in the bowl.","images":[],"step":4},{"title":"Slow cook 1 1/2 hours","description":"Bring to a boil, then partially cover with a lid (leave a 2cm / 1\" crack) and reduce the heat to low/medium low so the liquid is simmering very, very gently. (Note 5) Simmer for 1 1/2 hours or until the pork is fall-apart tender (keep simmering if not tender).","images":[],"step":5},{"title":"Caramelise pineapple","description":"While pork is simmering, heat the oil in a non-stick pan over medium heat. Spread the pineapple out in one layer and cook each side until golden, about 4 minutes each side (I use spatula + tongs to turn). Remove onto plate until required.","images":[],"step":6},{"title":"Reduce sauce","description":"Remove pork with a slotted spoon (onion etc doesn''t matter when it''s in or out). Increase heat to high and boil to reduce the liquid down to 1 1/2 cups - it will be a very thin syrup (it''s not supposed to be thick), about 7 to 10 minutes.","images":[],"step":7},{"title":"Coat pork","description":"Reduce heat to low. Add the pork and pineapple pieces, plus any juices in the bowl. Stir gently to coat in the sauce and warm the pork through again.","images":[],"step":8},{"description":"Serve over jasmine rice, garnished with green onion if using.","images":[],"step":9}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Filipino"],"categories":["asian-recipes","iconic-dishes","pork-recipes","slow-cooked-fall-apart","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d6d383962b8e', 'en', 'US', 'The fastest noodle stir fry I know - from scratch!', 'Recipe video above. This family-size noodle stir fry is a complete meal with protein and plenty of veg, made from scratch in just 15 minutes, and it’s seriously tasty. The sauce uses just two ingredients, fish sauce and kecap manis, which might sound like an unusual combination but these have more flavour than regular sauces like soy sauce! Together, they deliver big savoury, sweet, glossy flavour with zero fishiness. I can’t stop making this, it’s perfect for busy weeknights!** Saltiness note: Be sure not to miss the step to use some of the sauce to season the chicken, otherwise too much ends up on the noodles and it can taste a bit too salty. **', 'https://www.recipetineats.com/tachyon/2025/06/2-ingredient-noodle-stir-fry-_5.jpg', 7, 8, 15, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 0.14, "unit": "bunch"}}, {"id": "ing_cabbage", "quantity": {"value": 15.0, "unit": "head"}}, {"id": "ing_kecap_mani", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.0, "unit": "jar of 50g"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}]', '[{"ingredients":["400g/14oz chicken thighs (, skinless boneless, thinly sliced 0.75cm/1/4\" thick (or breast))","500g / 1 lb hokkien noodles, lo mein, other noodles (, from the fridge, prepared per packet, rinsed well, drained (Note 1))","1 tbsp peanut oil (or any other neutral oil)","2 garlic cloves (, finely minced)","7 green onions (, cut into 5cm/2\" lengths, soft dark green parts separated from the white / pale green firmer parts)","5 cups green cabbage (, sliced ~1cm / 0.4\" thick (Napa/Chinese cabbage also works))"]},{"ingredients":["2 tbsp kecap mani (sweet soy) ( (Note 2))","1/4 cup fish sauce","1 pinch white pepper (sub black pepper)"],"purpose":"Sauce (just 2 ingredients!):"},{"ingredients":["1 tbsp+ chilli crisp, chilli paste or sriracha (add > taste > add > taste!) (Note 3)"],"purpose":"Optional grown up touch:"}]', '[{"description":"Toss chicken with 2 tbsp sauce. In a large 30cm/12\" non-stick pan over high heat, cook chicken first, adding garlic and white part of green onion towards the end. Cabbage 1 1/2 minutes, then noodles, sauce (add in 2 batches) and chilli crisp. Wilt green onion, serve!","images":[],"step":1},{"title":"Sauce","description":"Mix the ingredients in a small bowl.","images":[],"step":2},{"description":"Toss the chicken with 2 tablespoons of the sauce (no marinating time needed).","images":[],"step":3},{"description":"Cooking:","images":[],"step":4},{"title":"Cook chicken","description":"Heat the oil in a large 30cm/12\" non-stick pan over high heat until very hot. Add the chicken and cook for 2 minutes. Add the garlic and white part of the green onion, cook for another 30 seconds until chicken is just cooked.","duration":2,"images":[],"step":5},{"title":"Cabbage","description":"Add the cabbage, toss for 1 1/2 minutes or until it starts to go floppy.","images":[],"step":6},{"title":"Sauce and noodles","description":"Add the noodles and half the sauce, toss for a minute until the sauce is absorbed and no longer pooling in the pan (~ 45 seconds). Then add the remaining sauce and toss again until it''s all evenly coated and no liquid remains (~ 1 minute), adding chilli crisp towards the end, if using. (Note 4)","images":[],"step":7},{"title":"Serve","description":"Toss through the green part of the green onion until it''s wilted (barely 20 seconds), then divide between bowls. Noodle slurping time!","images":[],"step":8}]', '["fish","peanuts","soy"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","noodles","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eed1600b9acf', 'en', 'US', 'Ginger chicken and rice (one pot recipe!)', 'Recipe video above. This one-pot ginger chicken and rice is inspired by the flavours of Hong Kong claypot rice, steamed with a layer of mushrooms and finished with a drizzle of sauce. It''s gone straight into my top 3 one-pot recipes!I''ve used a mix of Asian mushrooms here which have more interesting textures and impart more flavour into the rice than regular white mushrooms. But I wouldn''t hesitate to make this with any type of mushrooms!', 'https://www.recipetineats.com/tachyon/2025/06/Ginger-chicken-and-rice-with-mushrooms_5.jpg', 10, 25, 45, 4, '[{"id": "ing_oil", "quantity": {"value": 60.0, "unit": "bottle"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 225.0, "unit": "pack"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 666.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_shiitake_mushrooms", "quantity": {"value": 1.0, "unit": "pack of 150g"}}, {"id": "ing_oyster_mushrooms", "quantity": {"value": 1.0, "unit": "pack of 150g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 2.0, "unit": "jar of 50g"}}, {"id": "ing_kecap_manis_note_4", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 2.0, "unit": "jar of 50g"}}]', '[{"ingredients":["4 tbsp oil","500g/ 1 lb chicken thighs (, boneless, skinless, cut into small bite size pieces (Note 1))","1 1/2 cups long grain rice (, NOT RINSED (Note 2))","2 cups chicken stock (, low sodium)","4 green onion stems (, white part finely sliced, green flopped part cut into 5cm/2\" lengths)","1 1/2 tbsp ginger (, grated)","2 large garlic cloves (, finely minced)","4 - 5 slices ginger (~5mm / 0.2\" thick (large enough to easily pick out later), no need to peel)"]},{"ingredients":["150g / 5oz shiitake mushrooms (, fresh (~2 heaped cups), small halved, large thickly sliced)","150g / 5 oz oyster mushrooms ((~2 heaped cups), small kept whole, large cut into 2 or 3)","200g / 7 oz king mushrooms (, halved then cut into thick slices 7mm thick)","2 pinches salt and white pepper (each)"],"purpose":"Mushrooms (use any you want – Note 3):"},{"ingredients":["3 tbsp kecap manis ((sweet soy) - Note 4)","2 tbsp fish sauce","1/8 tsp white pepper (sub black)"],"purpose":"Simple claypot sauce:"}]', '[{"title":"ABBREVIATED","description":"Toss chicken with 1 1/2 tbsp sauce. Sear mushrooms in 2 batches, remove. SeaL chicken, add garlic, ginger and white part green onions towards end. Stir in rice, add stock and ginger slices, cover with mushrooms, steam 20 min. Rest 10 min, toss with sauce and green onion.","images":[],"step":1},{"title":"Sauce","description":"Mix sauce ingredients in a small bowl. Toss chicken with 1 1/2 tbsp of the sauce, set the rest aside for drizzling.","images":[],"step":2},{"title":"Lightly sear mushrooms","description":"Heat 1 1/2 tbsp oil in a large heavy based pot on high heat. Cook half the mushrooms with a pinch of salt and pepper until some of the mushrooms have a light tinge of golden on the surface, but don''t try to cook them all the way through (we want to do that in the rice). Remove into bowl. Repeat with remaining mushrooms.","images":[],"step":3},{"title":"Seal chicken","description":"Heat the remaining 1 tablespoon of oil until hot. Add the chicken and stir for 1 minute, just until the surface is sealed but inside still raw. Add white part of green onion, garlic and ginger, stir 30 seconds. Add rice, stir briefly just to coat in oil.","duration":1,"images":[],"step":4},{"title":"Simmer liquid","description":"Add stock and ginger slices. Bring to a rapid simmer. Scatter mushrooms across surface (add any pooled liquid too), then let it come to a rapid simmer again.","images":[],"step":5},{"title":"Steam 20 minutes","description":"Put the lid on, reduce stove to low (or medium low, for weak burners). Cook for 20 minutes (do not stir) until the liquid is fully absorbed.","duration":20,"images":[],"step":6},{"title":"Rest 10 minutes","description":"Remove pot from the stove with the lid still on and rest for 10 minutes.","duration":10,"images":[],"step":7},{"title":"Drizzle and toss","description":"Drizzle remaining sauce all over, add green part of green onions. Gently toss until the green onion is mostly wilted. Serve!","images":[],"step":8}]', '["fish","shellfish","soy"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","modern-asian","one-pot-recipes","quick-and-easy","rice-recipes","rice-side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f600a7f8dba3', 'en', 'US', 'Hokkien noodles with chicken', 'Recipe video above. My everyday Hokkien Noodles recipe. A great sauce. Strips of chicken. Lots of vegetables. 6 minute cook. Dinner in 20 minutes flat!', 'https://www.recipetineats.com/tachyon/2024/08/Hokkien-noodles-with-chicken_2.jpg', 14, 6, 20, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 0.16, "unit": "bunch"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cabbage", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.03, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.16, "unit": "bunch"}}]', '[{"ingredients":["500g/ 1 lb hokkien noodles (, (fridge best) (Note 1))","350g/ 12 oz chicken thighs (boneless, skinless), cut into lot of thin 0.5 x 3cm / 0.2 x 1.2\" pieces (Note 2)","2 tbsp canola oil (or vegetable, cottonseed, peanut oil)","2 garlic cloves (, finely minced)","8 green onion stems (, cut into 5cm / 2\" lengths, white part separated from green part (Note 3))","1 red capsicum (bell peppers) (, cut into thin 0.5cm / 0.2\" strips)","3 heaped cups green cabbage (, cut into thin 1 x 5cm / 0.5 x 2\" strips)"]},{"ingredients":["2 tbsp light soy sauce (Note 4)","1 1/2 tbsp dark soy sauce (Note 4)","2 tbsp oyster sauce (Note 5)","1 tbsp Mirin or Chinese cooking wine (Note 6)","1 tbsp sesame oil (, toasted (Note 7))","1/8 tsp white pepper (sub black pepper)"],"purpose":"Sauce:"},{"ingredients":["White sesame seeds","Finely sliced green onion"],"purpose":"Optional garnishes"}]', '[{"description":"Abbreviated recipe:","images":[],"step":1},{"description":"Marinate chicken with 1 1/2 tbsp Sauce. Cook chicken 1 min, add garlic and white part of green onion, cook 1 min. Add capsicum & cabbage, cook 2 min. Add green part of green onion, noodles, sauce, toss 2 min. Serve!","images":[],"step":2},{"title":"Sauce","description":"Mix the sauce in a small bowl.","images":[],"step":3},{"title":"Briefly marinate chicken","description":"Toss the chicken with 1 1/2 tbsp of the Sauce. Marinate for 10 minutes while you prepare the noodles and vegetables.","duration":10,"images":[],"step":4},{"title":"Rinse noodles","description":"Prepare the noodles per the packet directions (soak in boiling water or briefly boil). Drain in a colander then rinse briefly under tap water (Note 8)","images":[],"step":5},{"title":"Sear chicken","description":"Heat the oil in a large non-stick pan over high heat until very hot (mine is 30cm/12\", Note 9 re: wok). Add the chicken and toss for 1 minute. Add the garlic and white part of the green onion, then toss for another 1 minute or until the surface of the chicken is sealed (but still a bit raw inside)","duration":1,"images":[],"step":6},{"title":"Cook veg & noodles","description":"Add the capsicum and cabbage. Toss for 2 minutes until the cabbage is mostly wilted. Add the green part of the green onions, noodles and sauce. Toss for 1 1/2 to 2 minutes until the noodles are stained a lovely mahogany colour.","duration":2,"images":[],"step":7},{"description":"Serve immediately, sprinkled with sesame seeds and green onion if desired!","images":[],"step":8}]', '["gluten","peanuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","chinese-recipes","noodles","quick-and-easy","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3af8d4554aa7', 'en', 'US', 'Beef Tataki', 'Recipe video above. Here''s a Beef Tataki recipe, a fusion Japanese restaurant favorite with thinly sliced beef in a citrusy dressing. Making it at home costs a fraction of eating out!I make the deluxe restaurant version with beef tenderloin, crispy potato straws, and garlic oil for entertaining. Whereas the steak version with Asian Sesame Dressing and a sprinkle of crispy fried shallots with a side of Smashed Cucumbers and Garlic Pot-Steamed Rice is my sort of Monday night meal!Serves 2 as a main with sides or 4 as a starter as part of a larger banquet (see my new fusion Japanese menu here).', 'https://www.recipetineats.com/tachyon/2024/07/Beef-tataki_8.jpg', 20, 30, 50, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_cooking_sake", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_mirin", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_yuzu", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_grapes", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}]', '[{"ingredients":["250g / 8 oz beef tenderloin/fillet (PREMIUM option) (- thin piece 13-15cm long (5-6\"), cut to even thickness (Note 1))","300g /10 oz sirloin steak ((aka Porterhouse in Australia, US: New York strip) (Note 2) - EASIER)"],"purpose":"Beef – choose ONE:"},{"ingredients":["1/2 tbsp vegetable oil (or other neutral flavoured oil)","1/4 tsp cooking salt / kosher salt"],"purpose":"Cooking:"},{"ingredients":["1 tbsp cooking sake (Note 4)","2 tsp mirin (Note 4)","1 tbsp rice vinegar (substitute apple cider vinegar)","1 1/2 tbsp Japanese soy sauce (, regular (Note 5))","1 tbsp yuzu (, or 1/2 tbsp each lime and lemon juice (Note 6))"],"purpose":"Yuzu Dressing (Note 3 other options):"},{"ingredients":["2 tbsp grapeseed oil (rapeseed oil or light olive oil)","3 garlic cloves (, sliced 2 mm thick)"],"purpose":"Garlic oil (optional, Note 7)"},{"ingredients":["Crispy potato straws (Pommes Paille, pictured, \"fancier\" option!)","Crispy fried shallots (store bought, easy option)"],"purpose":"Crispy topping options – CHOOSE ONE"},{"ingredients":["1 green onion (, finely sliced (optional curling, Note 8))"],"purpose":"Garnish:"}]', '[{"description":"Beef tenderloin:","images":[],"step":1},{"title":"Prep","description":"Preheat the oven to 130°C / 275°F (all oven types). Rub the beef with the oil and sprinkle with salt. Place on a rack set on a tray.","images":[],"step":2},{"title":"Roast for 18","description":"20 minutes or until the internal temperature in the middle is 41°C / 105°F (check first at 15 minutes, Note 9).","duration":19,"images":[],"step":3},{"title":"Sear","description":"Heat a cast iron skillet on high heat until it is smoking. Sear each side of the beef for just 10 seconds, no longer (I do 4 sides).","images":[],"step":4},{"title":"Cool","description":"Transfer the beef onto a rack on a tray. Cool for 30 minutes on the counter then refrigerate uncovered for 2 hours.","duration":30,"images":[],"step":5},{"title":"Thinly slice","description":"When ready to serve, slice it as thinly as you can without tearing the beef, aiming for 3mm / 1/16\" but up to 5mm / 1/8\" thick is fine. (Note 10 for tips)","images":[],"step":6},{"description":"Place the sake and mini in a tiny saucepan on low heat. Bring to a simmer, then simmer for 1 minute. Pour into a bowl, let it cool. Then stir in remaining dressing ingredients.","duration":1,"images":[],"step":7},{"description":"Garlic infused oil:","images":[],"step":8},{"description":"Put the garlic and oil in a tiny saucepan on low heat. Simmer for 5 minutes, stirring a few times, until the garlic is light golden. Cool for 15 minutes then strain (reserve crispy garlic for another use)","duration":5,"images":[],"step":9},{"title":"Plate up","description":"Lay the beef slices on a plate, overlapping slightly. Drizzle with 3-4 tbsp of the Dressing, then 1 1/2 tbsp of the garlic oil. Pile the crispy potato in a heap in the middle, sprinkle with green onion. (Or use the easy steak garnish options above instead).","images":[],"step":10},{"title":"To eat","description":"Serve straight away. Make sure you get some crispy potato in every bite, and squidge the beef around in the tasty sauce.","images":[],"step":11},{"description":"Easy steak option:","images":[],"step":12},{"title":"Cook","description":"Rub the steak with the oil then sprinkle with the salt. Heat a cast iron skillet on high heat until it is smoking. Cook the steak to rare (1 1/2 - 2 minutes on each side, but it will depend on thickness of steak), or to your taste (Note 11 for doneness). Cool & thinly slice steak per beef tenderloin steps above.","images":[],"step":13},{"title":"Assemble","description":"Place the slices in a line, slightly overlapping. Drizzle over Dressing and oil (or alternative Sauce of choice). Sprinkle crispy fried shallots down the centre then green onion. Serve!","images":[],"step":14}]', '["fish","gluten","soy"]', '[]', '{"mealType":["dinner","snack"],"cuisine":["fusion japanese","Modern Asian"],"categories":["asian-recipes","modern-asian"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_48a44116bb5e', 'en', 'US', 'Easy Singapore Chicken Vermicelli Noodles', 'Recipe video above. This is just a downright delicious and easy noodle stir fry that channels the flavours of everybody''s favourite Singapore Noodles. Same sauce, same egg ribbons, and strips of red capsicum. But with chicken and bacon instead of having to make or hunt down Chinese BBQ Pork and peel fresh prawns! I''ve also added bean sprouts and baby spinach for extra no-chop veg quota to turn this into a complete meal. This might not be traditional but it''s quick, easy, tasty, and you can make it tonight!', 'https://www.recipetineats.com/tachyon/2024/04/Easy-Singapore-chicken-vermicelli-noodles-2.jpg', 15, 10, 25, 3, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.2, "unit": "pack of 500g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.09, "unit": "bottle of 500ml"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_bacon", "quantity": {"value": 0.5, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 1.0, "unit": "bag of 250g"}}]', '[{"ingredients":["100 g/3.5 oz dried vermicelli noodles (not glass noodles)"]},{"ingredients":["3 tbsp light soy sauce (, or all-purpose soy (not dark soy) (Note 1))","3 tbsp Chinese cooking wine (Shaoxing wine, Note 2)","3 tsp curry powder (Note 3)","1 tsp white sugar","1/2 tsp white pepper (sub black pepper)"],"purpose":"Singapore noodles sauce:"},{"ingredients":["150g/ 5 oz skinless boneless chicken thighs","1/4 tsp cooking salt / kosher salt","1/2 tsp curry powder (Note 3)"],"purpose":"Chicken:"},{"ingredients":["2 tbsp plain oil (canola, veg, peanut)","2 eggs (, whisked)","100g/3 oz streaky bacon (, chopped into small pieces)","1/2 brown onion (, finely sliced)","3 garlic cloves (, finely minced)","1 red capsicum ((bell pepper), deseeded and finely sliced)","1 very heaped cup bean sprouts (or more leafy greens)","1 very heaped cup baby spinach (or other cook-able leafy greens or more bean sprouts)"],"purpose":"Stir fry add-ins:"}]', '[{"title":"Sauce","description":"Mix the sauce in a small bowl or jug.","images":[],"step":1},{"title":"Season chicken","description":"Toss the seasoned chicken ingredients in a bowl.","images":[],"step":2},{"description":"Prepare noodles per the packet directions then drain in a colander (usually says to soak in boiled water for 3 - 5 minutes).","duration":4,"images":[],"step":3},{"title":"Egg ribbons","description":"Heat a small amount of the oil in a large non stick pan over medium high heat. Pour the egg in a swirl to make a thin omelette. Once the surface is set (literally 30 seconds), slide or flip it onto a cutting board. Cool so you can handle it, roll it up into a cigar then cut into 7mm / 1/3\" strips. Separate. Voila! Egg ribbons!","images":[],"step":4},{"title":"Stir-fry","description":"Heat the remaining oil in the same pan over high heat. Add the bacon and cook for 1 minute. Add the onion and cook until it starts to wilt and the bacon is light golden (about 2 minutes). Add the chicken and cook until the surface is seared. Then add the garlic and capsicum and cook for another 2 minutes until the chicken is cooked.","duration":1,"images":[],"step":5},{"title":"Noodles","description":"Add (in this order) the baby spinach, bean sprouts, noodles then sauce. Using 2 spatulas, toss well for 1 1/2 minutes or until the sauce stains the noodles. There will be noodle breakage - that''s normal.","images":[],"step":6},{"title":"Finish","description":"Toss through the egg ribbons (gently, just to disperse) then serve immediately!","images":[],"step":7}]', '["egg","gluten","peanuts","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_716a59c2271e', 'en', 'US', 'Thai Turmeric Chicken (Gai Yang Khamin)', 'Recipe video. This is based on a popular southern Thailand street food that''s typically made with a butterflied chicken grilled over smokey coals. It''s sweet but has complexity owing to the simple but clever marinade.Here, I''m making a home version using the marinade for bone-in chicken thighs instead and baked it in my boring oven. I miss the charcoal flavour but it''s still lip smackingly delicious! The tumeric powder really makes it. :)', 'https://www.recipetineats.com/tachyon/2015/11/Thai-Turmeric-Chicken_4.jpg', 10, 50, 230, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.15, "unit": "bottle of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_turmeric", "quantity": {"value": 15.0, "unit": "jar"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.037, "unit": "kg"}}]', '[{"ingredients":["5 large chicken thighs, skin-on, bone-in (~1.2kg/2.4lb) (Note 1)"]},{"ingredients":["4 garlic cloves (, finely minced or crushed using garlic press)","2 tbsp fish sauce","2 1/2 tbsp oyster sauce","1 tsp white pepper (, ground (sub black))","1 tbsp ground turmeric","1/4 cup brown sugar (tightly packed cup)"],"purpose":"Marinade"}]', '[{"title":"Marinade chicken","description":"Mix Marinade ingredients in a large bowl. Add chicken and toss to coat. Marinade for at least 3 hours, preferably overnight.","images":[],"step":1},{"description":"Preheat oven to 180°C/350°F (160°C fan-forced).","images":[],"step":2},{"title":"Prepare","description":"Line a tray with baking paper/parchment paper. Place chicken on the tray, skin side up. Scrape all Marinade out of th bowl and dab onto chicken.","images":[],"step":3},{"description":"Bake for 40 minutes, basting at the 30 minute and 40 minute mark using the tray juices to make it golden brown and sticky, and rotate the tray as needed for even colour.","duration":40,"images":[],"step":4},{"description":"Increase the oven temperature to 200°C/390°F (180°C fan-forced). Pop the chicken back in for a final 10 minutes to caramelise the skin.","images":[],"step":5},{"description":"Rest for 3 minutes before serving with jasmine or coconut rice, and plain chunks of tomato and cucumber the Thai way!","duration":3,"images":[],"step":6}]', '["fish","gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","australia-day","chicken-breast-recipes","chicken-recipes","cuisines","dietary","gluten-free-recipes","grilling-ideas-and-recipes","quick-and-easy","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9cb8b7f4cf19', 'en', 'US', 'Spicy Wontons - Din Tai Fung!', 'Recipe video above. Everybody knows Din Tai Fung* has the best Spicy Wontons. Here''s my copy-cat! Very specific mix of spices, it''s less spicy, less vinegary and more savoury than typical Chinese dumpling houses, designed so you can slop up every bit of that tasty sauce with the wontons without blowing your head off! So, so, very good!* Global dumpling restaurant chain that declares itself the world''s best dumplings. Many Sydney-siders would not disagree.', 'https://www.recipetineats.com/tachyon/2023/09/Spicy-wontons-din-tai-fung_7-2.jpg', 10, 5, 15, 12, '[{"id": "ing_wontons", "quantity": {"value": 11.0, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.003, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 0.06, "unit": "pack of 100g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.05, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_water", "quantity": {"value": 0.037, "unit": "L"}}]', '[{"ingredients":["1/2 tsp Chinese chicken stock powder (, or regular western stock powder (Note 5))","1 tbsp green onion (, sliced then roughly chopped, for garnish)","Extra chilli oil (, for drizzling (Note 5))"],"purpose":"Wontons:"},{"ingredients":["2 garlic cloves (, very finely minced)","1 tsp caster / superfine sugar (sub regular sugar)","1/2 tsp red chilli flakes (red pepper flakes), OPTIONAL, for spicy food lovers (Note 2)","1/4 tsp sichuan pepper powder (Note 3)","1/4 tsp Chinese five spice powder (Note 4)","1/2 tsp Chinese chicken stock powder (, or regular western stock powder (Note 5))","2 tbsp Chinese chilli oil (⚠️ Note 5), adj for spiciness (sub with sesame oil)","1 tbsp vegetable oil (sub canola, peanut or other natural oil)","2 1/2 tsp light soy sauce (, or all-purpose soy (Note 6))","1 tsp rice vinegar (sub other clean vinegar)","2 1/2 tbsp hot water (just tap is fine)"],"purpose":"Chilli oil sauce for wontons:"}]', '[{"description":"Chilli oil sauce for wontons:","images":[],"step":1},{"title":"Mix spices","description":"Put the garlic, sugar, chilli flakes, sichuan pepper, five spices and stock powder in a medium mixing bowl.","images":[],"step":2},{"title":"Heat oil","description":"Heat the chilli oil and vegetable oil in a small frying pan over medium heat until hot. Pour over garlic mixture. Enjoy the sizzle! (Don''t worry, it doesn''t spit)","images":[],"step":3},{"title":"Add sauces:","description":"Whisk in soy sauce, rice vinegar and hot water. The oil will remain a little separated on top. Set aside while you make wontons.","images":[],"step":4},{"title":"Cook wontons","description":"Bring a large saucepan of water to the boil. Add wontons and cook until they float: 4 minutes for freshly made, 6 to 8 minutes from frozen.","images":[],"step":5},{"title":"Assemble","description":"Transfer to serving dish using a slotted spoon. Pour over sauce, add an extra drizzle of chilli oil (if you dare!), sprinkle with green onion. Serve immediately!","images":[],"step":6}]', '["gluten","peanuts","sesame","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","iconic-dishes","modern-asian"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8bf5422252bf', 'en', 'US', 'Vietnamese Caramel Ginger Chicken', 'Recipe video above. Vietnamese caramel sauce is a popular sweet/savoury used in Vietnamese dishes. Here, it''s used for bite size chicken pieces that get coated in the glaze with a generous dose of ginger. It''s quick, easy, something different and outrageously good!** NOTE: Sadly seeing reader feedback that the liquid isn''t reducing and chicken isn''t caramelising. Please ensure to use a LARGE PAN and be brave, simmer RAPIDLY! Else the liquid will take ages to reduce. See Note 4.**', 'https://www.recipetineats.com/tachyon/2023/08/Vietnamese-Ginger-Caramel-Chicken_6-close-up.jpg', 7, 15, 22, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 kg / 2 lb skinless chicken thigh fillets (, cut into large 5cm/2\" pieces (Note 1))","3 tbsp fish sauce","1 bird’s eye chilli or Thai chilli (, deseeded, finely minced (optional) - Note 2)","3 tbsp vegetable oil","1/4 cup brown sugar (, tightly packed)","1/3 cup ginger (, finely julienned (about 5 cm/2\" thick piece))","2 eschallots (, halved then finely sliced (sub half red onion) (Note 3))","1/2 cup boiling water"]},{"ingredients":["Fresh coriander/cilantro or green onion slices (recommended)","Red chilli (, finely sliced (optional))","Jasmine rice"],"purpose":"Garnishes & serving:"}]', '[{"description":"Toss chicken with fish sauce and chilli, then set aside while you prepare the other ingredients. You could marinate even overnight but it''s not necessary.","images":[],"step":1},{"title":"Pan size","description":"Use a large non-stick pan (mine is 30cm/12\", must be large). Else, be prepared to remove chicken at end to speed up sauce reduction. See Note 4!","images":[],"step":2},{"title":"Caramel","description":"Mix oil and sugar in the cold pan, then turn onto medium high heat. As soon as the sugar is melted, remove the pan from the stove then carefully add the chicken (⚠️ it will sizzle so don''t throw it in!) . Add ginger and shallots, toss briefly. The caramel may harden, that''s ok, it will re-melt.","images":[],"step":3},{"title":"Cook outside of chicken","description":"Then put the pan back on the stove and stir just until the chicken changes from pink to white all over, but not browned, and definitely not cooked through.","images":[],"step":4},{"title":"Simmer 10 min","description":"Add water, stir, bring to a simmer. Simmer very rapidly, still on medium high (or even high!), for 10 to 12 minutes, until the liquid reduces right down to a glaze. It might take longer if your pan is smaller or your stove is weaker, that''s ok. Stir every now and then while watery, then once it''s reduced down to a glaze, toss regularly to get nice colour on the chicken. The further you take it, the better the colour!","duration":11,"images":[],"step":5},{"description":"Serve with jasmine rice or other plain rice garnished with extra slices of chilli and fresh coriander if desired. Smashed cucumbers or Asian Slaw would be a terrific side!","images":[],"step":6}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["asian-recipes","chicken","chicken-recipes","mains","modern-asian","quick-and-easy","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_28bfac61179b', 'en', 'US', 'Thai Coconut Pumpkin Soup', 'Recipe video above. This is a brilliant way to turn a classic pumpkin soup into something that tastes more exotic - with very little effort. Think - pumpkin soup with Thai Red Curry vibes. It''s so good!See separate tutorial for how I cut butternut pumpkin and the Pumpkin Soup recipe for how I cut pumpkin.', 'https://www.recipetineats.com/tachyon/2023/08/Thai-Coconut-Pumpkin-Soup_2.jpg', 10, 15, 25, 5, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_thai_red_curry_paste", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_pumpkin", "quantity": {"value": 1.8, "unit": "kg"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_roti_frozen_pan_fried_for_dunking_note_6", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["2 tbsp vegetable oil (or other oil)","1 brown onion (, diced)","2 garlic cloves (, finely minced)","3 tbsp Thai red curry paste (, Maesri recommended (Note 1))","1.8kg/ 3.6 lb pumpkin or butternut squash ( - peeled, deseeded then chopped into 3cm / 1.2\" chunks (~1.3 kg/2.6 lb) (Note 2))","2 1/2 cups vegetable stock (, salt reduced (or chicken stock))","400ml/ 14 oz (1 can) coconut milk, (full fat, best quality (Note 3))","1 tbsp fish sauce (sub light or regular soy sauce, Note 4)"]},{"ingredients":["Crispy Asian shallots (, highly recommended (Note 5))","Red cayenne pepper (, finely sliced)","Fresh coriander leaves","Roti ((the flaky kind), frozen, pan fried - for dunking (SO GOOD!) - Note 6)"],"purpose":"Garnishes (optional):"}]', '[{"title":"Sauté","description":"Heat oil in a large heavy based pot over medium high heat. Add onion and garlic, cook for 2 minutes until soft.","duration":2,"images":[],"step":1},{"description":"Add curry paste and cook for 2 minutes.","duration":2,"images":[],"step":2},{"description":"Add pumpkin and stir to coat in the flavours for around 2 minutes.","images":[],"step":3},{"title":"Simmer 8 minutes","description":"Set aside 1/4 cup coconut milk for garnish. Add stock, remaining coconut milk and fish sauce. Bring to simmer then reduce heat to medium and simmer for 8 minutes until the pumpkin is soft.","duration":8,"images":[],"step":4},{"description":"Blitz using stick blender until smooth.","images":[],"step":5},{"description":"Serve topped with garnishes. Dunk in roti. Enjoy!","images":[],"step":6}]', '["fish","gluten","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Thai"],"categories":["asian-recipes","asian-soups","cuisines","pumpkin","quick-and-easy","soup-recipes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e2dad4918e12', 'en', 'US', 'Japchae - Korean Noodles', 'Recipe video above. Sort of a stir fry, sort of a noodle salad, this big, colourful Korean noodle dish is tossed together in a bowl rather than on the stove and served barely warm. Made with chewy, slippery sweet potato noodles (dangmyeon) which are available in large grocery stores, though can be substitute with glass noodles (bean thread noodles) or vermicelli noodles in a pinch.Makes a big batch - leftovers make for a terrific lunch!', 'https://www.recipetineats.com/tachyon/2023/07/Japchae-Korean-noodles_9.jpg', 20, 15, 35, 5, '[{"id": "ing_beef_steak", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_sweet_potato", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}, {"id": "ing_shiitake_mushrooms", "quantity": {"value": 1.333, "unit": "pack of 150g"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 4.5, "unit": "bag of 250g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.3, "unit": "pack of 100g"}}]', '[{"ingredients":["600g/1.2lb bone-in beef short ribs *RECOMMENDED* (300g/10oz boneless)","300g/10 oz boneless beef short ribs *RECOMMENDED*","300g/10oz scotch fillet / boneless rib eye (or other steak, recommend tenderising (Note 1))"],"purpose":"Choose beef option (Note 1):"},{"ingredients":["2 tsp soy sauce (, all-purpose or light soy (Note 2))","2 tsp white sugar","2 tsp finely minced garlic","1/2 tsp black pepper"],"purpose":"Beef marinade:"},{"ingredients":["1/4 cup soy sauce (, all-purpose or light soy (Note 2))","2 tsp white sugar","1/2 tsp finely minced garlic","1 1/2 tbsp sesame oil","1/2 tsp cooking/kosher salt","1/2 tsp black pepper"],"purpose":"Noodle dressing:"},{"ingredients":["250g/ 8oz sweet potato noodles (dangmyeon), dried (Note 3)","4 tbsp vegetable oil (or other plain oil)","1 tsp cooking/kosher salt (, divided)","1 onion (, peeled, halved, sliced into 6mm/1/4\" wedges)","3 green onion stems (, cut into 5cm / 2\" lengths, white & green parts separated)","200g/7oz fresh shiitake mushrooms (, stem removed, cut into 5mm/1/5\" slices (Note 4))","2 carrots (, peeled, cut into 3mm / 1/8\" batons)","1 red capsicum/bell pepper (, cut into 0.5cm / 1/5\" slices)","4 1/2 cups (tightly packed) baby spinach","2 tbsp white sesame seeds"],"purpose":"Noodles & vegetables:"}]', '[{"description":"Quick beef marinade:","images":[],"step":1},{"description":"Cut beef into strips that are ~ 5mm thick, 1cm wide and about 5cm long (1/5\" x 2/5\" x 2\"). If using shortribs, trim excess fat, cut the meat off the bone. Then cut each piece in half lengthwise (to form 2 \"steaks\") then slice into 5mm thick. (See step photos in post or video at 0.11s, Note 6)","images":[],"step":2},{"title":"Marinate","description":"Put beef in a bowl. Add marinade ingredients, then mix. Set aside marinate while you proceed with recipe, ~15 - 20 minutes is all it needs. (Note 5)","images":[],"step":3},{"description":"Sauce and noodles:","images":[],"step":4},{"title":"Sauce","description":"Mix the Sauce ingredients in a very large mixing bowl.","images":[],"step":5},{"title":"Noodles","description":"Cook sweet potato noodles per packet directions (normally 8 min in boiling water). Drain, briefly rinse under tap water then shake off excess water well. Add noodles into the bowl with the dressing. DO NOT MIX.","images":[],"step":6},{"title":"Batch 1","description":"Heat 2 tablespoons of oil in a large non-stick pan (30cm/12\") over high heat. Cook the brown onion, white part of green onion and shiitake mushrooms with 1/2 tsp salt for 2 1/2 to 3 minutes, stirring constantly, just until starting to soften but not going golden. Pour on top of the noodles - don''t mix yet!","images":[],"step":7},{"title":"Batch 2","description":"Using the same pan still on high heat, heat 1 tbsp oil then cook the carrot and capsicum for 1 1/2 minutes, constantly stirring. Add spinach, green onion and the final 1/2 tsp salt. Keep cooking for 1 1/2 minutes until the spinach is wilted. Transfer into the noodle bowl - still don''t mix!","images":[],"step":8},{"title":"Cook beef","description":"In the same pan, heat the final 1 tbsp of oil still on high heat. Add beef and cook for 1 1/2 minutes until very lightly golden and just cooked through. Add to the noodle bowl. Don''t mix!","images":[],"step":9},{"description":"Mix! Add most of the sesame seeds (reserve some for topping). NOW you can mix! Toss, toss, toss.","images":[],"step":10},{"title":"Serve","description":"Transfer into a serving bowl, sprinkle with remaining sesame seeds. This is meant to be eaten warm, not piping hot. Eat!","images":[],"step":11}]', '["fish","gluten","sesame","soy"]', '[]', '{"mealType":["lunch","dinner"],"cuisine":["Korean"],"categories":["asian-recipes","korean-recipes","noodles","quick-and-easy","summer"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6e6cc9cb5cdb', 'en', 'US', 'Sizzling ginger steamed fish', 'Recipe video above. Named as such because the ginger and green onion topping sizzles dramatically when you pour hot oil over oven steamed fish! An incredibly simple way to make a healthy steamed fish recipe a whole lot more exciting with fresh Asian flavours.Squidge every bite of fish very well in the sauce before eating. The sauce is really tasty - it will surprise you.', 'https://www.recipetineats.com/tachyon/2023/07/Sizzling-ginger-fish_1.jpg', 5, 15, 20, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_cooking_sake", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_oil", "quantity": {"value": 10.0, "unit": "bottle"}}]', '[{"ingredients":["2 x 180g/ 6 oz thinnish white fish fillet (, skinless (~1.5 cm/ 2/3\" thick) (Note 1))","1 tsp cooking sake (sub mirin, Chinese cooking wine, dry sherry) (Note 2)","Small pinch salt","Small pinch white pepper (sub black)"]},{"ingredients":["1/2 cup green onion (, green part only, finely sliced on diagonal (Note 3))","2 tbsp ginger (, finely julienned (Note 3))","1 tbsp large red chilli (, deseeded finely julienned on diagonal, optional (Note 4))"],"purpose":"TOPPING (divide between 2 fish):"},{"ingredients":["2 tsp light soy sauce (, or all-purpose soy (Note 5))","2 tsp sesame oil (, toasted)","2 tbsp peanut oil (or veg, canola, grapeseed)"],"purpose":"SAUCE (divide between 2 fish):"}]', '[{"description":"Preheat oven to 200°C/400°F (180°C fan).","images":[],"step":1},{"title":"Prepare parcel","description":"Place a 2 x 25cm / 10\" piece of foil on a work surface. Top with a piece of parchment/baking paper slightly smaller. Place fish on paper.","images":[],"step":2},{"title":"Season fish & wrap","description":"Sprinkle each side of the fish with a SMALL pinch of salt and pepper. Drizzle the top of each fish with 1/2 tsp sake. Form a parcel - make a parcel with the paper first, then the foil. (See video or step photos).","images":[],"step":3},{"title":"Bake","description":"Place parcels on a tray. Bake for 12 minutes or until the internal temperature is 55°C/130°F (I pierce thermometer through foil) or the fish flesh flakes (open to check). Thin fish cooks fast when enclosed!","duration":12,"images":[],"step":4},{"title":"Rest 3 min","description":"Put each parcel on a plate and unwrap, folding down the sides to create a “boat” that will catch the sauce that you can squidge the fish in. Rest for 3 minutes - heat the oil while it rests.","duration":3,"images":[],"step":5},{"description":"Heat oil until hot in a tiny saucepan or small pan over medium heat.","images":[],"step":6},{"description":"Sizzle! Top the fish with green onion, ginger and chilli. Drizzle with soy and sesame oil. Pour oil all over the green onion and ginger - it will sizzle dramatically!","images":[],"step":7},{"description":"Serve immediately. Eat fish out of foil, squidging the flaky pieces well in the sauce before eating. See post for what I served it with!","images":[],"step":8}]', '["fish","gluten","peanuts","sesame","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","dietary","fish-recipes","low-calorie-recipes","mains","other","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1ad6752ed673', 'en', 'US', 'Beef Chow Mein - great beef mince noodle recipe!', 'Recipe video above. The beef mince version of everybody''s favourite Chicken Chow Mein - great way to cook up ground beef with noodles. Economical and no meat chopping required, with plenty of hidden vegetables so it''s a complete dinner! Scrambling up an egg with the beef is a neat trick to make the beef cling to the noodles better.', 'https://www.recipetineats.com/tachyon/2023/07/Beef-chow-mein_5.jpg', 15, 10, 25, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 16.667, "unit": "carton of 12"}}, {"id": "ing_cabbage", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.03, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.019, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}]', '[{"ingredients":["200g/ 7 oz chow mein noodles (, or other thin yellow egg noodles or 3 ramen cakes (Note 1))","1 1/2 tbsp canola oil","2 garlic cloves (, finely minced)","200g/ 7 oz beef mince / ground beef (any fat %)","3 green onion stems (, cut into 5cm/2\" lengths, white and green parts separated)","1 egg","2 cups green cabbage (, finely sliced (or Chinese cabbage))","1 carrot (, peeled, cut into thin batons)","1 heaped cups bean sprouts (~ 75g / 2 1/2 oz) (Note 5 - storage tip)"],"purpose":"Chow Mein:"},{"ingredients":["1 1/2 tbsp light soy sauce (or all-purpose soy sauce (Note 2))","1 1/2 tsp dark soy sauce (Note 2)","1 1/2 tbsp oyster sauce (Note 3)","1 1/2 tbsp Chinese cooking wine (Shaoxing) (Note 4)","1 1/2 tsp white sugar","Pinch white pepper"],"purpose":"Chow Mein Sauce:"},{"ingredients":["1 1/2 tsp cornflour / cornstarch","3 tbsp water"],"purpose":"Sauce thickener:"}]', '[{"title":"Sauce","description":"Mix ingredients in a small bowl then set aside. Some is used to flavour the beef, then the rest for the noodles.","images":[],"step":1},{"title":"Sauce thickener (cornflour slurry)","description":"Mix the cornflour / cornstarch and water in a separate small bowl.","images":[],"step":2},{"description":"Prepare noodles per packet directions then drain.","images":[],"step":3},{"title":"Cook beef","description":"Heat the oil in a large non-stick pan over high heat. Cook garlic for 10 seconds, then add the beef and cook until you can no longer see pink. Add 1 1/2 tablespoons of the Sauce and the white part of the green onions. Cook for another 2 minutes to get the beef nicely caramelised.","duration":0.16666666666666666,"images":[],"step":4},{"title":"Finish sauce","description":"Mix the cornflour slurry into the remaining sauce.","images":[],"step":5},{"title":"Egg","description":"Add the egg into the pan then mix it through the beef, it will sort of scramble. Egg makes the beef stick to the noodles better!","images":[],"step":6},{"title":"Cabbage & carrot","description":"When the egg is mostly cooked, add the carrot and cabbage. Cook for 1 minute until cabbage starts to wilt.","duration":1,"images":[],"step":7},{"title":"Sauce & noodles","description":"Give the sauce a quick mix. Add the bean sprouts, noodles and sauce into the pan. Toss well for 1 minute or until sauce is dispersed through the noodles. Add green part of green onions. Toss for another 1 minute.","duration":1,"images":[],"step":8},{"title":"Serve","description":"Divide between bowls and serve!","images":[],"step":9}]', '["egg","gluten","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","beef-mince-recipes","beef-recipes","chinese-recipes","dinner-tonight","noodles","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f783d2e8882d', 'en', 'US', 'Chili crisp noodles', 'Recipe video. Ridiculously good and ridiculously fast, here by popular demand after a sneak peek on Instagram! Chili crisp oil is the star ingredient here, adds spiciness, awesome crunch, savouriness, and a touch of sweet. Widely available these days - see Note 6.Tastes like Spicy Sichuan Dan Dan Noodles - but much faster to make. LOTS OF SUB OPTIONS because chili crisp carries so much of the flavour weight here!', 'https://www.recipetineats.com/tachyon/2023/06/Chili-crisp-noodles_2.jpg', 7, 0, 7, 2, '[{"id": "ing_sesame_seeds", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_ramen_noodles", "quantity": {"value": 35.0, "unit": "pack of 4"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.28, "unit": "pack of 500g"}}]', '[{"ingredients":["2 tbsp Chinese sesame paste (Note 1 subs)","2 tbsp light soy sauce (Note 2)","1 tbsp rice vinegar (Note 3)","1 tsp white sugar (or other sugar, or honey, maple)","2 tsp sesame oil (, toasted (Note 4))","1/8 tsp+ cooking / kosher salt (Note 5)","2 heaped tbsp chilli crisp (get oil + chili bits)","1 tbsp ginger (, finely minced*)","1 tbsp garlic (, finely minced*)","1 green onion stem (, finely sliced (or 1/4 red onion finely sliced))","1/3 cup coriander/cilantro (, roughly chopped*)"]},{"ingredients":["140g/ 5oz (2 cakes) instant noodles / ramen noodles","250g/8oz fresh noodles (like hokkien, lo mein)"],"purpose":"Noodle options (Note 7):"}]', '[{"title":"CHECK the spiciness of your chilli crisp","description":"taste it!! Laoganma is not actually that spicy (most store bought brands I''ve used are similar) and the quantity used is based on that brand. If yours is very spicy, start with less and add more later.","images":[],"step":1},{"title":"Base sauce","description":"Mix the sesame oil, vinegar, soy, sugar, salt and sesame paste in a bowl. Top with green onion (don’t mix in).","images":[],"step":2},{"title":"Sizzling chili crisp","description":"Heat chilli crisp and oil in a small pan over medium heat. Add ginger and garlic, stir 30 seconds until golden and it smells amazing. Pour over green onion - enjoy the sizzle! Then mix.","images":[],"step":3},{"title":"Toss","description":"Cook noodles per packet directions. Drag the noodles straight from the saucepan into the bowl (extra water loosens the sauce). Toss. Use cooking water to loosen more if needed. Toss through coriander/cilantro.","images":[],"step":4},{"title":"Adjust & finish","description":"Taste. Add more salt if needed and more chilli crisp if desired (not all chilli crisp is the same saltiness / spiciness). Eat!","images":[],"step":5}]', '["gluten","sesame","soy"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","chinese-recipes","modern-asian","noodles","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_709a5f652dd3', 'en', 'US', 'Xinjiang Cumin Lamb Stir Fry', 'Recipe video above. A cumin spiced lamb dish might sound totally un-Chinese, but it''s actually authentic and very on-trend! Hailing from the Xinjiang province of China, if you love Middle Eastern and Chinese food, you will love this. Bold cumin flavour with tingling "cold" spiciness from Sichuan pepper and earthy chilli flavour (but not spiciness) from the dried chillis.Spice level - On the upper warm buzz side, but not fiery heat because Sichuan pepper is a different type of spiciness, see note 4.Recipe credit: Adapted from Real-Deal Xinjiang Cumin Lamb from Omnivore''s Cookbook, one of my trusted sources for authentic Chinese cooking. I made a few minor tweaks to streamline but the flavour is bang on!', 'https://www.recipetineats.com/tachyon/2023/05/Xinjiang-Cumin-Lamb-Stir-Fry_3.jpg', 15, 8, 53, 4, '[{"id": "ing_lamb", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.031, "unit": "tub of 200g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.075, "unit": "pack of 400g"}}, {"id": "ing_cumin", "quantity": {"value": 0.75, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 0.75, "unit": "pack of 100g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 8.333, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["500g/ 1 lb boneless lamb leg meat (or rump) (, sliced 1/2 cm / 1/5\" thick (Note 1))","1 tbsp soy sauce (, light or all-purpose (not dark or sweet))","1 tbsp Chinese cooking wine (Note 2)","1/2 tsp cooking/kosher salt","1 1/4 tsp baking soda (, sifted if lumpy (Note 3))","2 tbsp cornflour / cornstarch"],"purpose":"Lamb & marinade:"},{"ingredients":["2 tbsp cumin powder","1/2 tsp white sugar","1/2 tsp ground Sichuan pepper (Note 4 to grind your own)"],"purpose":"Spice mix:"},{"ingredients":["4 tbsp vegetable oil (or canola, peanut)","1/2 cup dried Chinese chillis (, whole, 25-30 pcs (Note 5))","1 onion (, halved then sliced 8mm / 1/4\" thick)","2 tbsp finely minced ginger (~5cm/2\" piece)","5 cloves garlic (, finely sliced)","1/2 cup coriander/cilantro (, roughly chopped)","1 tsp toasted sesame seeds","Plain rice (, fried rice - more suggestions listed in post)"],"purpose":"Stir fry:"}]', '[{"title":"Marinade","description":"Combine lamb, soy sauce, Chinese cooking wine, salt, baking soda and cornflour in a mixing bowl. Mix well then set aside for marinade for 30 minutes (counter fine).","duration":30,"images":[],"step":1},{"title":"Spice mix","description":"Mix the ingredients in a small bowl.","images":[],"step":2},{"title":"Cook lamb","description":"Heat 3 tablespoons of the oil in a large non-stick skillet (30cm/1\") over medium-high heat until hot. Add half the lamb and spread out in a single layer. Leave for 30 seconds then, using 2 wooden spoons, toss for a further 1 minute until the lamb is slightly golden. Remove onto a plate then repeat with remaining lamb (you shouldn''t need more oil).","duration":0.5,"images":[],"step":3},{"title":"Sauté aromatics","description":"Heat the remaining 1 tablespoon of oil. Add the dried chilli, ginger and garlic. Stir for 10 seconds to release flavour, then add the onion. Cook for 2 minutes until the onion just starts to soften.","duration":0.16666666666666666,"images":[],"step":4},{"title":"Spiced lamb","description":"Add the cooked lamb then sprinkle the spice mix over. Toss well to evenly coat.","images":[],"step":5},{"title":"Finish dish","description":"Add the cilantro, sesame seeds and toss. Serve over rice! (Note: the dried chillies are not meant to be eaten.)","images":[],"step":6}]', '["gluten","peanuts","sesame","soy"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","chinese-recipes","lamb","lamb-recipes","mains","modern-asian","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8e8c2f23ee7c', 'en', 'US', 'Spicy Korean Noodle Soup (quick & healthy)', 'Recipe video above. For all those times you need a spicy Asian noodle fix - FAST! This packs a serious flavour punch. The secret is the juices from the kimchi jar and a good dollop of gochujang, that magical spicy Korean paste you can get "everywhere" these days. To add protein, cook raw prawns/shrimp or fish pieces in the broth (only takes 3 min), or top with slices of BBQ pork. You can also poach chicken in the broth using this foolproof method.', 'https://www.recipetineats.com/tachyon/2023/05/Spicy-Korean-noodle-soup_4.jpg', 5, 15, 20, 2, '[{"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_cabbage", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_kimchi_juice", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_gochujang", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_ginger", "quantity": {"value": 0.08, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_stems_choi_sum", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.125, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.75, "unit": "bunch"}}]', '[{"ingredients":["4 cups / 1 litre chicken stock/broth (, low-sodium)","2/3 cup cabbage kimchi (Note 1)","2 tbsp kimchi juice (, from kimchi tub (Note 1))","3 tbsp gochujang (Note 2)","2 tbsp light soy sauce (Note 3)","2 tsp fish sauce (sub more soy)","1 tbsp Chinese cooking wine (Shaoxing wine, Note 4)","2 slices ginger (, sliced 0.7cm / 1/3\" thick (skin on))","1 large garlic clove (, smashed (Note 5))"],"purpose":"Spicy Korean Soup Broth"},{"ingredients":["200g/ 7oz thin fresh egg noodles (or 100g/3.5oz dried - Note 6)","4 stems choi sum (or other Asian greens, cut into 7cm / 2.5\" lengths, stems separated from leafy part)","1 small carrot (, peeled, cut into thin matchsticks)","2 1/2 tsp sesame oil (, toasted (Note 8))","1/4 cup finely sliced green onions (1 stem)"],"purpose":"Add-Ins (Note 7):"}]', '[{"title":"Broth","description":"Place all broth ingredients in a saucepan. Bring to a simmer over medium-high heat, then reduce heat so it’s simmering gently. Simmer 10 minutes without a lid.","images":[],"step":1},{"title":"Cook vegetables","description":"Add choi sum stems and carrot to the broth. Simmer for 2 minutes. Add choi sum leaves and simmer for another minute. Stir in sesame oil just before serving.","duration":2,"images":[],"step":2},{"title":"Noodles","description":"Meanwhile, cook egg noodles in boiling water per packet directions. Drain, give the noodles a quick rinse under tap water. Shake off excess water well.","images":[],"step":3},{"title":"Assemble","description":"Divide noodles between bowls. Top with the vegetables. Pick the garlic and ginger out of the broth, then broth pour over the noodles. Sprinkle with green onions and serve!","images":[],"step":4}]', '["egg","fish","gluten","sesame","soy"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Korean"],"categories":["asian-recipes","asian-soups","korean-recipes","noodles","quick-and-easy","soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_34918cac7840', 'en', 'US', 'AMAZING vegetarian lettuce wraps', 'Recipe video. The meat-free version of Chinese san choy bow. You never knew vegetarian lettuce wraps could be so delicious. I never knew either, until I made these! Crumbled tofu lends the filling a meaty texture while vegetables add lovely texture, all smothered in a glossy, savoury sauce. Vegetarian food (and healthy, no less!) was never so delicious. And interesting. And easy. It''s AMAZING!Feel free to substitute the veg with other sauté-able vegetables of choice.', 'https://www.recipetineats.com/tachyon/2023/03/Vegetarian-lettuce-wraps_4.jpg', 15, 10, 25, 2, '[{"id": "ing_cornstarch", "quantity": {"value": 0.016, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_tofu", "quantity": {"value": 0.833, "unit": "pack of 300g"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 75.0, "unit": "pack of 1kg"}}, {"id": "ing_green_beans", "quantity": {"value": 75.0, "unit": "pack"}}, {"id": "ing_mushroom", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 240.0, "unit": "head"}}, {"id": "ing_peanuts", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sriracha", "quantity": {"value": 1.0, "unit": "bottle of 400ml"}}]', '[{"ingredients":["1 1/4 tsp cornflour / cornstarch","3 tbsp water","1 1/2 tbsp light soy sauce (Note 1)","1 tsp dark soy sauce (Note 1)","1 1/2 tbsp oyster sauce (Note 2)","1 tsp sesame oil (, toasted)","1 tbsp Chinese cooking wine (or sub Mirin or dry sherry, Note 3)","1 tsp white sugar","1 tsp finely grated ginger (sub garlic)"],"purpose":"San choy bow sauce:"},{"ingredients":["250g/8oz extra firm tofu (Note 4)","1 tbsp oil","1 garlic (, finely minced)","1/2 onion (, finely diced)","1/2 cup carrot (, chopped into 5mm/ 0.2\" pieces)","1/2 cup green beans (, sliced into 5mm/0.2\" rounds)","1/2 cup mushroom (, chopped into 5mm/ 0.2\" pieces)"],"purpose":"Filling:"},{"ingredients":["12 lettuce leaves (+/- depending on lettuce size, Note 5)","Peanuts (, finely chopped (I like salted, but unsalted fine))","Green onion (, finely sliced)","Sriracha (, for drizzling (highly recommended))"],"purpose":"Wraps:"}]', '[{"title":"Sauce","description":"Mix cornflour/cornstarch with water until lump free. Add everything else, then mix.","images":[],"step":1},{"title":"Crumble tofu","description":"Drain tofu, then cut into 5mm/0.2\" slices. Use your fingers to crumble into a mince. Not too fine crumbs, can always break up more when cooking (just like cooking mince/ground meat!).","images":[],"step":2},{"title":"Filling","description":"Heat oil over high heat in a large non stick pan. Cook onion, garlic and carrot for 1 minute. Add green beans and mushrooms. Cook 2 minutes - green beans should still be firm.","duration":1,"images":[],"step":3},{"title":"Sauce it","description":"Add tofu and toss through. Pour in the sauce. Stir for 1 minute or until the sauce thickens and is coating the mixture nicely. (If it evaporates too quickly, add a splash of water)","duration":1,"images":[],"step":4},{"title":"Serving","description":"Transfer filling into a bowl. Lay out on the table with lettuce leaves, green onion, peanuts and bottle of sriracha.","images":[],"step":5},{"title":"DIY lettuce wraps","description":"Spoon filling into lettuce leaf. Drizzle with sriracha, sprinkle with peanuts and green onion. Bundle / fold, eat!","images":[],"step":6}]', '["gluten","sesame","soy"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["dinner","snack"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dietary","low-calorie-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e906d00f3e36', 'en', 'US', 'Firecracker Beef', 'Recipe video above. This is a thrifty yet excellent dinner for all those times you need to scratch your Spicy Asian Food itch, fast! Seared beef mince gets tossed through a fiery Firecracker Sauce, tastes a bit like a spicy beef version of the much-loved Vietnamese Caramelised Pork Mince. Sweetness & spice level - Fairly spicy! See notes to reduce. Firecracker sauce is supposed to be a bit sweet to offset spice, also see notes.', 'https://www.recipetineats.com/tachyon/2022/11/Firecracker-beef-mince_2-2.jpg', 3, 10, 13, 4, '[{"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_sriracha", "quantity": {"value": 0.15, "unit": "bottle of 400ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 30.0, "unit": "pack"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sriracha", "quantity": {"value": 0.15, "unit": "bottle of 400ml"}}]', '[{"ingredients":["1½ tbsp oil (vegetable, canola, peanut)","500g / 1 lb beef mince / ground beef (Note 1)","2 garlic cloves (, finely minced)","1 tsp chilli flakes / red pepper flakes (adjust to your taste)","3 tbsp water"]},{"ingredients":["2 tbsp soy sauce (, light or all-purpose (Note 2))","2 tbsp rice vinegar (Note 3)","4 tbsp sriracha sauce (Note 4)","4 tbsp brown sugar (tightly packed)"],"purpose":"Firecracker sauce:"},{"ingredients":["Rice, (soba or vermicelli noodles)","1 green onion (, finely sliced)","1 tsp sesame seeds","Diced cucumber, julienned carrot, finely sliced red radish","Extra sriracha sauce (, if you dare!)"],"purpose":"To serve (optional!):"}]', '[{"title":"Sauce","description":"Mix Firecracker sauce ingredients in a small bowl and set aside.","images":[],"step":1},{"title":"Cook beef","description":"Heat oil in a large frypan over high heat. Add beef and cook, breaking it up as you go, until you can no longer see raw meat (2½ minutes). Add garlic and chilli flakes and cook for 1 minute.","duration":1,"images":[],"step":2},{"title":"Caramelise beef","description":"Add Firecracker sauce ingredients, stir to coat the beef. Cook for 5 to 7 minutes, stirring only every minute or so initially, then more towards the end, until the sauce reduces and you can see the beef caramelising. Caramelise well for good flavour!","duration":6,"images":[],"step":3},{"title":"Water","description":"Add the water and cook for 1 minute (the water makes the beef saucier!)","duration":1,"images":[],"step":4},{"description":"Serve over rice, sprinkled with sesame seeds, green onion and a squirt of extra sriracha if you''re feeling brave! Add a pile of vegetables of choice on the side. Dive in!","images":[],"step":5}]', '["gluten","peanuts","sesame","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","beef","beef-mince-recipes","beef-recipes","dinner-tonight","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b8e7f32b3af1', 'en', 'US', 'Vegetable Dumplings (Potstickers!)', 'Recipe video above. 4 years in the making, my favourite vegetable dumpling! These are a standout because you can actually taste the vegetables and it''s got good texture, rather than just being a wad of tasteless, watery mush which is sadly all too common.Don''t get too hung about about the wrapping part. If the pleating is too challenging, just seal it flat. Quicker, easier, and it tastes exactly the same. :)', 'https://www.recipetineats.com/tachyon/2022/09/Vegetable-Dumplings-1-on-plate.jpg', 45, 3, 48, 30, '[{"id": "ing_cabbage", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 8.0, "unit": "kg"}}, {"id": "ing_tofu", "quantity": {"value": 0.375, "unit": "pack of 300g"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.075, "unit": "pack of 100g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 2.0, "unit": "jar of 50g"}}, {"id": "ing_round_dumpling_wrappers", "quantity": {"value": 30.0, "unit": "unit"}}, {"id": "ing_oil", "quantity": {"value": 7.5, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}]', '[{"ingredients":["2 cups green cabbage (, finely chopped into 2mm pieces)","1/2 tsp cooking/kosher salt"],"purpose":"Wilted cabbage for Filling:"},{"ingredients":["8 dried shiitake mushroom (40 g total), medium size (Note 1)","3/4 cup firm tofu (, finely diced into 3-4mm / 1/8\" cubes (Note 2))","1/2 tsp garlic (, finely grated)","1 tsp ginger (, finely grated)","2 tbsp green onion (, finely sliced then minced)","2 tbsp finely grated floury potato (, including juices, for binding (Sebago, russet, Maris piper, Note 3))","1 1/2 tsp toasted sesame oil (Note 4)","1 tsp light soy sauce (or all-purpose, not dark soy)","1/4 tsp sugar (any)","1/4 tsp cooking/kosher salt","2 pinches white pepper (sub black)"],"purpose":"Filling:"},{"ingredients":["30 - 35 round dumpling wrappers (gow gee, Note 5)","2 - 3 tbsp canola oil","1/4 cup water per cooking batch"],"purpose":"Cooking:"}]', '[{"description":"Quick recipe (for pros):","images":[],"step":1},{"description":"Wilt cabbage 20 min, squeeze. Soak mushrooms 30 min, squeeze, finely chop. Mix with remaining Filling ingredients. Wrap. Pan fry 2 min, 1/4 cup water, pan-steam 5 min.","images":[],"step":2},{"title":"Full recipe","description":"filling:","images":[],"step":3},{"title":"Prepare cabbage","description":"Toss cabbage with 1/2 tsp salt in a bowl. Set aside for 20 minutes. Then grab handfuls and squeeze out excess water as best you can. Place squeezed cabbage in a bowl for mixing the filling in.","duration":20,"images":[],"step":4},{"title":"Shiitake mushrooms","description":"Soak mushrooms in 1 litre of boiling water for 30 minutes. Squeeze out excess liquid and finely chop into 2 mm pieces. Add to the filling bowl.","duration":30,"images":[],"step":5},{"title":"Potato","description":"Add grated potatoes to filling mix, including all the liquid that leached out when you grated it. We want all that starchy juice for its binding power!","images":[],"step":6},{"title":"Filling","description":"Add remaining ingredients into the filling bowl, mix to combine. It will look crumbly - don''t worry, everything sticks together better when steamed thanks to the potato.","images":[],"step":7},{"title":"Dumpling wrappers","description":"Take one wrapper from the packet. Keep unused wrappers covered so they don''t dry out.","images":[],"step":8},{"title":"Wrap dumplings","description":"(See video at 1m 30s!) Place a wrapper in your non-dominant hand. Dip your index finger in water and run it along the lower half of the wrapper (edge closest to you). Place 1 loosely-packed tablespoon of filling in the centre. Fold the wrapping over the filling, then seal with pleats. (If this is too hard, skip the pleats and seal flat).","images":[],"step":9},{"title":"Finished dumplings","description":"Stand dumpling upright with the pleats on top, and lightly press down to flatten the base. Shape gently into a slight curve. Place on a tray lightly dusted with cornflour/cornstarch. Repeat for remaining dumplings. Keep completed dumplings covered with a tea towel to prevent them from drying out. If you''re making ahead, cover dumplings with cling wrap and refrigerate. See storage notes.","images":[],"step":10},{"description":"Cook (pan-frying + steaming):","images":[],"step":11},{"title":"Cooking vessel","description":"Use a large non-stick pan with a lid (Note 6).","images":[],"step":12},{"title":"Pan fry","description":"Heat 1 tablespoon oil over medium high heat. Pan fry 12 to 15 dumplings for 2 minutes until the base is golden brown.","duration":2,"images":[],"step":13},{"title":"Steam","description":"Pour over 1/4 cup water over the dumplings in the skillet - it will steam and bubbly vigorously! Place the lid on and steam for 5 minutes or until the water in the pan has evaporated.","duration":5,"images":[],"step":14},{"description":"Cooked! Remove the lid. The water should have been driven off, and the wrapping should be semi-transparent (indicating it is cooked). The base should be crispy again. If not, leave the pan uncovered for a bit until the base crisps up again in the oil.","images":[],"step":15},{"title":"Serve","description":"Scoop the dumplings up with a spatula and place on a serving plate. Serve with soy sauce and chili paste for dipping, or rice vinegar mixed with soy sauce. Best served fresh - I get another batch cooking as we eat the freshly cooked ones!","images":[],"step":16},{"description":"Steaming-only option:","images":[],"step":17},{"description":"Using either a bamboo steamer set over a large wok with simmering water, or other larger steamer. Line with a fitted sheet of parchment paper with holes, and steam the dumplings for 8 minutes.","duration":8,"images":[],"step":18}]', '["gluten","sesame","soy"]', '["keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["snack","dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dumplings"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_787630138c29', 'en', 'US', 'Red Vietnamese Fried Rice', 'Recipe video above. This is the fried rice version of traditional Vietnamese red rice (plain tomato rice steamed in a pot). I added ham, peas and egg to turn it into a quick and easy meal. Frying up the tomato rice with garlic adds extra flavour which is on point!Serves 2 as a meal, or 4 to 5 as a side.', 'https://www.recipetineats.com/tachyon/2022/09/Red-Vietnamese-Fried-Rice_3.jpg', 8, 7, 15, 2, '[{"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_ham", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.375, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}]', '[{"ingredients":["30g / 2 tbsp unsalted butter","3 garlic cloves (, finely minced)","1/2 cup diced ham (I use pre-chopped, Note 1)","1 cup frozen peas","2 1/2 cups day-old cooked jasmine rice (Note 2)","2 tbsp tomato paste","2 tsp fish sauce (Note 3)","2 tsp soy sauce (all purpose or light, not dark soy, Note 4)","1/4 tsp white sugar","2 eggs (, whisked)"]}]', '[{"description":"Melt most of the butter in a large non-stick skillet over high heat (save a dab for scrambling eggs).","images":[],"step":1},{"description":"Add garlic, cook for 10 seconds.","duration":0.16666666666666666,"images":[],"step":2},{"description":"Add ham, stir for 30 seconds.","duration":0.5,"images":[],"step":3},{"description":"Add peas, stir for 30 seconds.","duration":0.5,"images":[],"step":4},{"title":"Rice and tomato paste","description":"Add rice and tomato paste, cook for 2 minutes.","duration":2,"images":[],"step":5},{"title":"Sauces","description":"Add fish sauce, soy and sugar, cook 1 minute to get a bit of nice caramelisation on the tomatoey rice.","images":[],"step":6},{"title":"Scramble eggs","description":"Push rice to one side of the pan. In the cleared space, melt reserved butter then pour in the egg and scramble until just set.","images":[],"step":7},{"title":"Serve","description":"Toss cooked egg through the rice. Serve!","images":[],"step":8}]', '["egg","fish","gluten","milk","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["asian-recipes","fried-rice","modern-asian","quick-and-easy","rice-recipes","rice-side-dishes","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a9ca2a056a5d', 'en', 'US', 'Teriyaki Salmon Noodles', 'Recipe video above. Here''s a great quick noodle recipe that''s got everything you want for a meal. It''s got carbs, veg and protein. It''s quick. It''s one-pan. It''s easy. And it''s super tasty!! This is also a delicious dish that can wring two generous meal servings from just one piece of salmon. An economical tip! :)', 'https://www.recipetineats.com/tachyon/2022/07/Teriyaki-Salmon-Noodles_1-1.jpg', 5, 10, 15, 2, '[{"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 2.0, "unit": "pack of 500g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.15, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_cooking_sake", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 tbsp oil (veg or canola)","250 g / 8 oz salmon fillet (s), skinless, sliced into 2cm / 0.7\" strips (lengthwise, Note 1)","2 instant noodle / ramen noodle cakes (discard seasoning packs) (Note 2 other noodles)","1/2 onion (, cut into 1cm / 0.3\" slices)","1 garlic clove (, finely minced)","1 small bunch Chinese broccoli (gai lan), cut into 5 cm / 2\" lengths, leaves separated from stem (Note 3)"]},{"ingredients":["2 1/2 tbsp soy sauce (, light or all-purpose (Note 4))","2 tbsp mirin (Note 5)","2 tbsp cooking sake (Note 5)","1 tsp white sugar"],"purpose":"Teriyaki Sauce:"}]', '[{"title":"Teriyaki Sauce","description":"Mix the ingredients in a small bowl until the sugar is dissolved.","images":[],"step":1},{"description":"Coat salmon with 1 tablespoon of Teriyaki Sauce in a bowl, then set aside while you cook the noodles. (No need to marinate)","images":[],"step":2},{"description":"Cook your noodles per the packet directions. Drain, briefly rinse under tap water then set aside.","images":[],"step":3},{"title":"Cook salmon","description":"Heat 1/2 tablespoon oil in a large non-stick pan over high heat. Cook the salmon for 1 1/2 minutes on each side or until golden, then remove to a plate. Pour any remaining sauce in the skillet over the salmon.","images":[],"step":4},{"title":"Cook aromatics","description":"Roughly clean the pan with a paper towel then return to the stove, still on high heat. Heat 1 tablespoon of the remaining oil and cook the onion and garlic for 30 seconds. Add Chinese broccoli stems and cook for 1 minute.","duration":0.5,"images":[],"step":5},{"title":"Noodles & sauce","description":"Add noodles and half the Sauce. Toss for 2 minutes until the Sauce is absorbed. Add the remaining Sauce and toss to disperse. Then spread the noodles out in the pan, cook for 30 seconds un-disturbed. Repeat again 3 to 4 times (~3 min total) - a trick for nice caramelisation on the noodles (which = flavour!).","duration":2,"images":[],"step":6},{"title":"Leafy greens","description":"Drizzle the remaining 1/2 tablespoon oil around the side of the pan, then add the Chinese broccoli leaves. Toss for a further 1 1/2 minutes or until the leaves wilt.","images":[],"step":7},{"title":"Add back salmon","description":"Remove pan from stove. Place salmon on top, break into large chunks then toss through.","images":[],"step":8},{"title":"Serve","description":"Divide between bowls and serve immediately!","images":[],"step":9}]', '["fish","gluten","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","noodles"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6d98a13ffa3b', 'en', 'US', 'Honey Prawns - stays crispy for ages!', 'Recipe video above. A recipe for old school Chinese restaurant style Honey Prawns! This recipe uses a proven method used in my Honey Chicken recipe for Honey Prawns that stays crispy hours even after coating in the sauce!1. Double coating - cornflour/cornstarch to seal in juices, followed by batter.2. Cold batter made with soda water = crispier coating that''s puffy and light, not dense and greasy.3. Cornflour/cornstarch + flour batter - cornflour for ultra crispiness, flour for golden colour.4. Double fry for extra long lasting, thicker crispiness AND less greasy (Asian secret!).5. No-soggy Sauce - glucose or corn syrup to make it "candy like" to stick on the prawn crust rather than soaking in, plus NO WATER in the sauce.Note - the sauce is sweet. That''s the way it''s supposed to be! But not as sickly sweet as many Chinese restaurants tend to be. Please do not try to change the sauce as it has been formulated to prevent making the batter soggy.', 'https://www.recipetineats.com/tachyon/2021/09/Honey-Prawns_23.jpg', 10, 20, 30, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.188, "unit": "pack of 400g"}}, {"id": "ing_flour", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_oil", "quantity": {"value": 3.0, "unit": "bottle"}}, {"id": "ing_honey", "quantity": {"value": 0.167, "unit": "jar of 500g"}}, {"id": "ing_corn", "quantity": {"value": 0.056, "unit": "can of 400g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.02, "unit": "bottle of 500ml"}}, {"id": "ing_rice_noodles", "quantity": {"value": 0.067, "unit": "pack of 375g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["300g/ 10oz prawns/shrimp (, peeled with tail on (600g/1.2lb whole unpeeled) (Note 1))","1/2 tsp kosher/cooking salt (halve for table salt)"],"purpose":"Prawns"},{"ingredients":["1/2 cup cornflour/cornstarch"],"purpose":"Dredging:"},{"ingredients":["9 tbsp cornflour/cornstarch (Note 2)","6 tbsp flour (, plain/all-purpose)","1/2 tsp baking powder (NOT baking soda)","1/2 tsp kosher/cooking salt (halve for table salt)","2/3 cup + 1 tbsp COLD soda water, club soda or seltzer water (NOT sparkling mineral water, Note 3)"],"purpose":"Ultra-crispy fry batter:"},{"ingredients":["3 - 4 cups vegetable or canola oil (~4cm / 1.5\" depth in a pot)"],"purpose":"Oil, for frying:"},{"ingredients":["1/3 cup (100g) honey","1.5 tbsp (25g) glucose OR corn syrup (light) (Note 4)","1 tbsp light soy sauce (or all-purpose)","2 tsp Chinese cooking wine (or mirin)"],"purpose":"Honey Sauce (Note 8 on sweetness):"},{"ingredients":["25g / 2 oz Vermicelli rice noodles (optional) (, a wad of it (not mung bean noodles, it must be rice noodles))","Sesame seeds, finely sliced green onions"],"purpose":"Garnish / serving:"}]', '[{"description":"Season and dust prawns:","images":[],"step":1},{"title":"Salt prawns","description":"Mix prawns with salt. (Don''t do this ahead, salt makes prawns sweat = compromise crispy coating!)","images":[],"step":2},{"title":"Dust","description":"Place 1/2 cup cornflour/cornstarch in a bowl. Dip prawn in, shake off excess then put on a plate. Repeat with all prawns.","images":[],"step":3},{"description":"Cold batter and fry #1:","images":[],"step":4},{"title":"Chill dry ingredients","description":"Whisk together flour, cornflour/cornstarch, baking powder and salt in a bowl. Place in fridge while oil heats up. (Helps keep batter cold, cold batter = crispier prawns)","images":[],"step":5},{"title":"Heat oil","description":"Fill small pot or large saucepan with 4cm / 1.7\" oil. Heat to 160°C/320°F on medium high stove.","images":[],"step":6},{"title":"Make cold batter","description":"When the oil is near target temp, add soda water into the dry ingredients. Then do the minimum whisks to just combine (10 or so) - a few lumps ok, better than whisking too much (changes coating texture).","images":[],"step":7},{"title":"Batter thickness","description":"Should fully coat prawns easily, not be see-through, but not thick and heavy. See video at 38 seconds for cues. Use extra soda water 1 teaspoon at a time to achieve right thickness.","images":[],"step":8},{"title":"Dredge","description":"Holding a prawn by the tail, dip into the batter then hold up for a 2 seconds to let the excess batter drip off. Then carefully place in oil. Repeat with another 5 prawns (6 per batch).","images":[],"step":9},{"title":"3 minutes Fry #1","description":"Cook for 3 minutes until light golden and crispy. When you pick them up, you can tell it''s very crispy.","duration":3,"images":[],"step":10},{"title":"Drain and repeat","description":"Place prawns on a tray with paper towels. Repeat with remaining prawns. I cook in 4 batches. Don''t crowd the pot as it brings oil temperature down too much.","images":[],"step":11},{"description":"Cool prawns for 20 minutes (Note 5). Meanwhile, make Sauce.","duration":20,"images":[],"step":12},{"title":"Simmer","description":"Place ingredients in a small saucepan over medium heat. Bring to simmer, turn down stove to medium low then leave to simmer for 3 minutes.","duration":3,"images":[],"step":13},{"title":"Syrupy consistency","description":"The consistency should be like maple syrup (see video). Turn off stove, place lid on to keep warm (when cool, it gets too thick to toss prawns in it).","images":[],"step":14},{"title":"Fry #2","description":"for ultra-crispy!","images":[],"step":15},{"description":"Heat oil to 200°C/390°F.","images":[],"step":16},{"title":"3 minutes Fry #2","description":"Place half the prawns in oil (you can crowd the pot for Fry #2). Cook for 3 minutes or until it changes from pale golden to very golden, then remove to a paper towel-lined plate. You can tell by touching that it''s built-to-last crispy! More golden = crispier (but don''t overcook the prawns!) Repeat with remaining prawns.","duration":3,"images":[],"step":17},{"description":"Sauce and serve:","images":[],"step":18},{"title":"Quickly toss","description":"Transfer prawns to a metal bowl then pour over Honey Sauce. Quickly toss with rubber spatula to coat prawns in sauce. (Sauce starts thickening if you take too long, so be quick!)","images":[],"step":19},{"title":"Garnish","description":"Pile prawns over crispy rice noodles (if using), scatter with sesame seeds, green onion and serve!","images":[],"step":20},{"description":"Puffy crispy rice noodles (optional):","images":[],"step":21},{"description":"At any point while oil is hot, drop a wad of noodles into hot oil, wait 3 seconds until it puffs up, then remove with tongs.","images":[],"step":22},{"description":"Drain on paper towels, place on plate. Top with prawns! (Note: Crispy noodles stays crispy \"forever\" so you can do this well ahead. Not for eating - is flavourless.)","images":[],"step":23}]', '["gluten","sesame","shellfish","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","deep-fried-recipes","prawns-shrimp"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2c0a261f4050', 'en', 'US', 'Sesame Crusted Tofu Steaks with Teriyaki Sauce', 'Recipe video above. Sesame seeds add excellent flavour and give tofu a crispy crust crust that stays crispy even when doused with Teriyaki Sauce. Great quick and easy recipe to convert tofu haters - so far from bland, we''re in a different stratosphere!', 'https://www.recipetineats.com/tachyon/2021/09/Crispy-Sesame-Tofu-Steaks-hero.jpg', 5, 10, 15, 4, '[{"id": "ing_tofu", "quantity": {"value": 4.0, "unit": "pack of 300g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.6, "unit": "pack of 100g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.6, "unit": "pack of 100g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_cooking_sake", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["4 extra firm or hard tofu (, cut into 10 x 5 x 1.5cm slices (4 x 2 x 0.6\"), 100g / 3.5oz each (Note 1))","1/4 tsp each salt and pepper","2 tbsp flour (, plain/all purpose)","1 egg (, lightly whisked)","4 tbsp white sesame seeds (Note 2) (yes, you really need 4 tbsp!)","4 tbsp black sesame seeds (Note 2)","2 tbsp canola/vegetable oil","2 garlic cloves (, finely sliced 1mm thick (optional, Note 2))","1 green onion (, finely sliced (for garnish))"]},{"ingredients":["2 tbsp soy sauce (, preferably Japanese all-purpose, else light soy sauce (Note 4))","2 tbsp mirin (, preferably Japanese (Note 5))","2 tbsp cooking sake (, preferably Japanese (Note 6))","2 tbsp water"],"purpose":"Teriyaki Sauce:"}]', '[{"description":"Sesame coating:","images":[],"step":1},{"title":"Season tofu","description":"Pat tofu dry with paper towels. Sprinkle with salt and pepper.","images":[],"step":2},{"title":"Prepare crust coating","description":"Place flour, egg and sesame in separate bowls (medium shallow bowls or tupperware best).","images":[],"step":3},{"title":"Sesame crust","description":"Press tofu into flour, shake off excess. Dip in egg, then let excess drip off before coat in sesame seeds, pressing to adhere all over. Repeat with remaining tofu.","images":[],"step":4},{"description":"Cooking:","images":[],"step":5},{"title":"Crispy garlic","description":"Heat oil in a non stick skillet over medium heat. Add garlic and cook until golden and crisp. Remove and drain on paper towels.","images":[],"step":6},{"title":"Cook tofu","description":"Turn heat up to medium-high. Place tofu in skillet and cook for 1 1/2 minutes until the sesame smells nutty and becomes crisp. Turn carefully and cook the other side for 1 1/2 minutes. Then use tongs to prop the tofu steaks up on its sides to sear the edges until crisp - about 30 seconds each side should do it (see video for my technique).","images":[],"step":7},{"title":"Drain","description":"Remove tofu to paper towel lined plate.","images":[],"step":8},{"title":"Teriyaki Sauce","description":"Lower heat to medium then add Teriyaki Sauce ingredients. Simmer for 1 minute until it reduces to a syrupy consistency, then remove skillet from stove.","duration":1,"images":[],"step":9},{"title":"Serve","description":"Place tofu steak on plate. Spoon over Teriyaki Sauce (it clings to sesame, don''t worry, crust stays crispy). Sprinkle with garlic and green onion. Devour, then declare, \"I LOVE TOFU!!\".","images":[],"step":10}]', '["egg","gluten","sesame","soy"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Japanese(ish)","Modern Asian"],"categories":["asian-recipes","dietary","dinner-tonight","low-calorie-recipes","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_59b37d24b607', 'en', 'US', 'Ayam Goreng (Malaysian Fried Chicken)', 'Recipe video above. Marinated in a curry paste made with lemongrass, garlic and spices then tossed in cornflour to make the coating ultra craggy and crunchy, Ayam Goreng is Malaysia''s answer to Southern Fried Chicken. Hot contender for the world''s best fried chicken!Spiciness: Very mild. Feel free to dial it up by adding more chilli powder!', 'https://www.recipetineats.com/tachyon/2021/07/Ayam-Goreng_08.jpg', 10, 30, 1480, 4, '[{"id": "ing_chicken", "quantity": {"value": 1.25, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_galangal", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_lemongrass", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_turmeric", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_eshalots_and_roughly", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.263, "unit": "can of 400ml"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.188, "unit": "pack of 400g"}}, {"id": "ing_oil", "quantity": {"value": 1750.0, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["1.25 kg / 2.5 lb chichen thighs ad drumsticks, bone in skin on ( (I use 4 thighs, 3 drumsticks, Note 1))"]},{"ingredients":["2 tsp coriander seeds","2 tsp cumin seeds","1 tsp fennel seeds"],"purpose":"Toasted spices:"},{"ingredients":["3 garlic cloves (, roughly chopped)","1 tbsp ginger (, roughly chopped)","1 tbsp galangal (, roughly chopped (Note 2))","1 1/2 tsp curry powder (any type fine, mild or spicy - your choice)","1 lemongrass (, white part only roughly chopped (Note 3))","1 tsp turmeric powder","2 small eshalots (French onions, US: shallots), peeled and roughly chopped (Note 4)","1 1/2 tsp cooking/kosher salt (or 1 tsp table salt)","1/2 tsp chilli powder (, adjust to taste (Note 5))","2 tsp brown sugar","7 tbsp coconut milk (full fat best!)"],"purpose":"Ayam Goreng Curry Paste:"},{"ingredients":["1/2 cup cornflour / cornstarch","1.75 litres / quarts vegetable or canola oil"],"purpose":"Cooking:"},{"ingredients":["1 tbsp garlic (,minced (not too small, else it burns))","1 tbsp large red chilli ((cayenne pepper), deseeded and minced)","1 tbsp green onion (, minced)","Pinch of salt","Coriander/cilantro leaves"],"purpose":"Garnish (optional):"}]', '[{"title":"Toast spices","description":"Toast spices in a small skillet over medium heat (no oil) for 2 minutes or until the spices smell fragrant. Transfer seeds into Nutribullet, small food processor OR into a tall jug that fits a stick blender.","duration":2,"images":[],"step":1},{"title":"Curry paste","description":"Add remaining Curry Paste ingredients and blend until smooth.","images":[],"step":2},{"title":"Marinate","description":"Pour Curry Paste over chicken in a ziplock bag (or bowl, Note 6). Toss to coat, then marinate for 24 hours in the fridge, up to 48 hours.","images":[],"step":3},{"description":"PREPARE TO COOK (WORK IN SPECIFIED ORDER OF STEPS):","images":[],"step":4},{"title":"Dechill chicken","description":"Remove chicken from fridge 30 minutes prior to cooking and transfer into a bowl (most marinade should be stuck to chicken).","images":[],"step":5},{"title":"Preheat oven to 80°C/175°F and place rack on tray","description":"to keep chicken warm. (Note 7)","images":[],"step":6},{"title":"Cornflour coating","description":"Add cornflour to chicken and toss to coat - it will thicken the paste, this is what makes the craggy coating.","images":[],"step":7},{"title":"Heat oil 180°C/350°F","description":"Pour oil into a wide, heavy based pot to a depth of 6 cm / 2.5 \" (my 26cm/10.5\" cast iron pot = 1.75L/quarts oil, Note 8). Heat over medium high heat to 180°C/350°F - maintain temp as best you can (Note 9). This recipe will NOT work well with an air fryer – see Note 8.","images":[],"step":8},{"title":"Fry","description":"Carefully place 3 pieces of chicken in, do not touch for 2 min (to let crust adhere). Oil temperature should drop to 150°C/300°C - increase heat if needed.","duration":2,"images":[],"step":9},{"title":"Fry 8 minutes (75°C / 167°F)","description":"Fry for 8 minutes (wings for 5 minutes), or until deep golden brown and internal temperature at thickest part is 75°C / 167°F.","duration":8,"images":[],"step":10},{"title":"Keep warm","description":"Place cooked chicken onto rack and keep warm in oven. Cook remaining chicken.","images":[],"step":11},{"description":"Serve immediately, sprinkled with coriander and garlic-chilli garnish, if using. See in post for side dish suggestions!","images":[],"step":12},{"description":"Heat 3 tbsp oil in a small skillet over medium heat. Add garlic and chilli, cook until garlic is starting to go light golden. Then add green onion and cook until garlic is golden. Drain on paper towels, sprinkle with salt. Cool then sprinkle on chicken.","images":[],"step":13}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Asian","Malaysian","South East Asian"],"categories":["asian-recipes","asian-takeout","chicken","chicken-recipes","deep-fried-recipes","iconic-dishes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_720d4ba41b50', 'en', 'US', 'Sticky Honey Soy Chicken - baked', 'Recipe video above. This is still the best, EASIEST sticky honey soy chicken recipe I have come across. And I''ve tried many over the years! Marginally adapted from this recipe by Sprinkles and Sprouts. The sauce is very thin when you put it together and gets even thinner while baking, but miraculously, it suddenly thickens into an incredible glaze to squidge the chicken in. It''s salty and sweet with a lovely hit of sesame.Please do not double the recipe or sauce, this will prevent the sauce from reducing down to the sticky glaze you see pictured.', 'https://www.recipetineats.com/tachyon/2016/02/Honey-Soy-Baked-Chicken_60.jpg', 5, 50, 55, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_honey", "quantity": {"value": 0.09, "unit": "jar of 500g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1.2kg / 2.4lb bone-in, skin-on chicken thighs OR drumsticks (5 - 6 pieces) (Note 1)","1 red onion (, peeled, cut into wedges)"]},{"ingredients":["3 cloves garlic (, minced)","3 tbsp honey","3 tbsp soy sauce (Note 2)","1 tbsp apple cider vinegar (or ordinary white vinegar)","1 tsp sesame oil","1/2 tsp black pepper"],"purpose":"Glaze"},{"ingredients":["Sesame seeds","Fresh coriander/cilantro leaves (or other green things like green onion, parsley, chives)"],"purpose":"Garnish (optional)"}]', '[{"description":"Preheat oven to 200°C/390°F (180°C fan).","images":[],"step":1},{"title":"Line pan","description":"Line a baking dish with foil then baking paper. The baking tray should fit the chicken comfortably, not too spaced apart (glaze will dry out), not too snug (glaze won''t thicken enough). (Note 3)","images":[],"step":2},{"title":"Glaze","description":"Mix the Glaze ingredients together.","images":[],"step":3},{"title":"Pour glaze over chicken","description":"Place onion and chicken in the baking dish skin side down, then pour the Glaze over.","images":[],"step":4},{"title":"Bake 50","description":"60 minutes: Bake for 25 minutes, then turn and bake for a further 25 to 35 minutes, until the chicken is browned and the glaze is sticky. If the glaze is not syrupy, remove the chicken to a plate and put the pan back in for a few minutes (it will reduce quickly).","duration":25,"images":[],"step":5},{"title":"Squidge/coat chicken","description":"Turn chicken and squidge in the glaze, then also spoon it over.","images":[],"step":6},{"description":"Serve! Serve with rice and steamed greens, sprinkled with sesame seeds and fresh cilantro/coriander leaves.","images":[],"step":7}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian influence"],"categories":["asian-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f505a0450ac5', 'en', 'US', 'Beef Satay with Thai Peanut Sauce', 'Recipe video above. Meat on sticks is always a good thing, and Thai Beef Satay is one of the best! In this beef version of Thai Chicken Satay, a secret tenderising satay marinade makes economical steak astonishingly succulent. So good, you can eat it plain – but no one in their right mind would skip the Thai Peanut Sauce!Note: Baking soda tenderised beef needs to be thoroughly cooked to be tender. The beef is still a bit chewy if it''s medium or less (because we''re using economical beef).Top tip: Excellent to grill on the BBQ, or even better, over charcoal for a truly authentic Thai experience.Use leftover sauce for Thai Chicken Satay, Gado Gado (Indonesian Salad with Peanut Sauce) or just douse a bowl of plain rice. You can''t go wrong!', 'https://www.recipetineats.com/tachyon/2021/07/Thai-Beef-Satay-with-Peanut-Sauce.jpg', 15, 15, 1470, 12, '[{"id": "ing_skewers", "quantity": {"value": 13.0, "unit": "pack of 50"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_coconut_mik", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_red_curry_paste", "quantity": {"value": 0.05, "unit": "bottle"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.417, "unit": "can of 400ml"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.133, "unit": "jar of 375g"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_peanuts", "quantity": {"value": 0.075, "unit": "jar"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["13-16 bamboo skewers (, 16cm / 6.5\" long (Note 1))"]},{"ingredients":["600g / 1.2lb beef rump steak (top sirloin in the US) (, 2.5 cm/1\" pieces (Note 2))","1/4 cup coconut mik (, full fat (I use Ayam, Note 3))","1 tbsp curry powder (Note 4)","1 tsp white sugar","2 tsp red curry paste (Note 5)","1/2 tsp baking soda / bi-carb (tenderiser, Note 6)","1 tsp salt"],"purpose":"Marinade:"},{"ingredients":["1 tbsp red curry paste (Note 5)","2/3 cup coconut milk (, full fat (I use Ayam, Note 3))","1/3 cup natural peanut butter (, smooth (Note 7))","1 1/2 tbsp white sugar","1 tsp dark soy sauce (Note 8)","1/2 tsp salt","1 tbsp cider vinegar (Note 9)","1/3 cup water"],"purpose":"Thai Peanut Sauce:"},{"ingredients":["1 1/2 tbsp vegetable oil (, for cooking)","2 tbsp peanuts (, finely chopped)","Lime wedges (optional)","Coriander / cilantro leaves and sliced red chilli (optional)"],"purpose":"Cooking & Serving:"}]', '[{"description":"If cooking on a BBQ or over charcoal, soak skewers for 2 hours in water so they don''t burn.","images":[],"step":1},{"description":"Thai Beef Satay Skewers:","images":[],"step":2},{"description":"Mix together the beef and Marinade in a bowl. Cover with cling wrap and marinate overnight (do not reduce marinating time else the beef may not tenderise enough).","images":[],"step":3},{"title":"Thread onto skewers","description":"I do 4 pieces each.","images":[],"step":4},{"description":"Heat 1.5 tbsp oil in a large non stick pan over medium high heat.","images":[],"step":5},{"title":"Cook 10 minutes (yes, well done!)","description":"Cook skewers in batches for 2 to 2 1/2 minutes on all 4 sides until deep golden (total of 8 to 10 minutes) and fully cooked through. (Note: baking soda tenderised beef needs to be thoroughly cooked to be tender. The beef is still a bit chewy if it''s medium or less.)","images":[],"step":6},{"title":"Rest","description":"Transfer skewers to plate and rest for 3 minutes before serving with Peanut Sauce.","duration":3,"images":[],"step":7},{"description":"Thai Peanut Sauce:","images":[],"step":8},{"description":"Place all Peanut Sauce ingredients in a small saucepan over medium low heat.","images":[],"step":9},{"description":"Stir to combine then simmer, stirring every now and then, for 5 minutes. Adjust consistency with water - it should be a pourable but thickish sauce.","duration":5,"images":[],"step":10},{"description":"Remove from stove, cover with lid and keep warm while cooking skewers.","images":[],"step":11},{"description":"Pour sauce into a bowl. Sprinkle with some peanuts - stir some through if you want.","images":[],"step":12},{"description":"Pile satay skewers onto a platter, sprinkle with remaining peanuts, coriander and chilli.","images":[],"step":13},{"description":"Serve with sauce on the side for dipping. Add a side of Jasmine Rice or Thai Fried Rice or Pineapple Fried Rice to complete the meal!","images":[],"step":14}]', '["gluten","peanuts","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Thai"],"categories":["asian-recipes","asian-takeout","beef","beef-recipes","cuisines","grilling-ideas-and-recipes","mains","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8d212b4e6ec6', 'en', 'US', 'Prawn Stir Fry (Shrimp)', 'Recipe video above. Dinner is sorted with these plump and juicy prawns in a classic ginger sesame Chinese stir fry sauce, with snow peas and broccolini. It’s a Chinese restaurant standard!As with all stir fries, feel free to switch the vegetables for anything you''ve got!TOP TIP: The best way to ensure you don''t overcook the prawns is to cook them first, remove, then add them back in at the end. Perfectly plump and juicy prawns, every single time!', 'https://www.recipetineats.com/tachyon/2021/06/Prawn-Stir-Fry-Shrimp_8.jpg', 10, 7, 17, 3, '[{"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 2.5, "unit": "bottle"}}, {"id": "ing_shrimp", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_broccoli", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_snow_peas", "quantity": {"value": 120.0, "unit": "unit"}}]', '[{"ingredients":["1 1/2 tbsp light soy sauce (sub all purpose soy, Note 1)","1 tbsp Chinese cooking wine (sub Mirin or dry sherry, Note 2)","2 tsp oyster sauce (Note 3)","1/2 tsp sesame oil (, toasted (Note 4))","1 tbsp cornflour/cornstarch","1/8 tsp white pepper (sub black pepper)","3/4 cup water"],"purpose":"Prawn Stir Fry Sauce:"},{"ingredients":["2 tbsp oil (, peanut, canola or vegetable)","250g / 8 oz medium prawns (, raw, peeled and deveined (equiv. 500g/1lb whole prawns, Note 5))","1/2 onion (, sliced, brown or white)","2 tsp ginger (, finely julienned (~2cm / 0.7\" piece))","2 tsp garlic (, finely chopped (~ 2 cloves))","1 1/2 bunches broccolini (, trimmed, cut into 5cm / 2\" lengths, (~1 1/2 cups. Sub normal broccoli))","120g / 4 oz snow peas (, thin string removed from both sides)"],"purpose":"Stir Fry:"}]', '[{"title":"Steam broccolini","description":"Steam broccolini until crisp-tender, about 2 - 3 minutes (remember it will cook more in the stir fry). Set aside to drain and dry.","images":[],"step":1},{"title":"Stir Fry Sauce","description":"Put all Stir Fry Sauce ingredients except water into a bowl. Mix until cornflour is dissolved. Then stir in water.","images":[],"step":2},{"title":"Cook then remove prawns","description":"Heat oil in a wok or large skillet on medium to medium-high heat. Add prawns and spread them in a single layer. Cook for 1 1/2 minutes, then turn and cook the other side for 1 minute until cooked through. Try not to make the prawns too golden (they are only lightly browned in stir fries). Remove prawns to a bowl. Set aside.","duration":1,"images":[],"step":3},{"title":"Cook onion, garlic and ginger","description":"Add more oil if the pan seems a bit dry. Still on medium-high heat, add onion and cook for 1 minute. Then add ginger and garlic and cook for another 1 minute until onion is starting to soften but not colour.","duration":1,"images":[],"step":4},{"title":"Add snow peas, then broccolini","description":"Add snow peas and toss until coated with oil. Then add broccolini and toss through.","images":[],"step":5},{"title":"Add Sauce and thicken","description":"Give the Sauce a stir (to dissolve cornflour settled at bottom), then pour into skillet. Cook, stirring, until sauce thickens to syrup consistency (about 1 minute) and coats the ingredients nicely.","images":[],"step":6},{"title":"Add prawns back in","description":"Then add the prawns back in (including any juices in the bowl). Toss for another 30 seconds until prawns are warmed through.","images":[],"step":7},{"title":"Serve","description":"Serve with rice!","images":[],"step":8}]', '["gluten","peanuts","sesame","soy"]', '["high_protein","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dinner-tonight","prawns-shrimp","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cde66a3d365b', 'en', 'US', 'Golden Turmeric Fish (Indonesian baked fish recipe)', 'Recipe video above. This homestyle Indonesian baked fish recipe is made with a Turmeric Curry Paste slathered on to white fish fillets which are then baked, and served topped with an Indonesian-style tomato salsa called Sambal Tomat.The curry paste is a gorgeously vibrant yellow colour thanks to the turmeric, and packed with fragrant and fresh South-East Asian curry flavours (as opposed to big, in-your-face-spice like Indian curries!).Sambal Tomat comes in all forms, from complex versions with flavourings like shrimp paste, to simpler and fresh ones like this one. We only need a simple one, the curry paste has plenty of flavour!', 'https://www.recipetineats.com/tachyon/2021/05/Golden-Turmeric-Fish-Indonesian_7.jpg', 15, 15, 30, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_turmeric", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_macadamia_nuts", "quantity": {"value": 22.5, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_lime", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_lemongrass", "quantity": {"value": 2.5, "unit": "bunch"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_chilli", "quantity": {"value": 10.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["4 x 180g / 6oz white fish fillets (, medium to thick, skinless (Note 1))","1/2 tsp salt","1 tbsp lime juice"],"purpose":"Quick lime marinade:"},{"ingredients":["1 small eschalot (~1/4 cup roughly chopped) (Note 2)","1 garlic clove (, finely grated*)","2 tsp fresh turmeric (, finely grated* or substitute powdered (Note 3))","1 tsp ginger (, peeled and finely grated*)","1 1/2 tbsp macadamia nuts (Note 4)","1/4 tsp salt","1/8 tsp black pepper","1 kaffir lime leaf (, torn by hand (Note 5))","2.5cm / 1\" piece of fresh lemongrass, white part only, ( cut into 1cm / 0.2\" pieces (Note 6))","1 tbsp oil","2 tbsp water"],"purpose":"Turmeric Curry Paste:"},{"ingredients":["2 tsp oil","250g / 8oz cherry tomatoes (, quartered)","1 large red chilli (cayenne pepper) (, deseeded and finely diced (adjust to taste, Note 7))","2 tsp coriander/cilantro leaves (, finely chopped (plus more for garnish))","1/4 tsp salt"],"purpose":"Sambal Tomat Topping:"}]', '[{"title":"Prep","description":"Preheat oven to 200°C / 390°F (180°C fan). Line a tray with baking / parchment paper.","images":[],"step":1},{"title":"Quick fish marinade","description":"Sprinkle fish with salt and drizzle with lime juice. Leave in fridge while making paste - just 10 minutes is fine.","images":[],"step":2},{"title":"Turmeric Curry Paste","description":"Place ingredients in a container that fits a stick blender. Then blend with stick until smooth, using extra water if needed until it is a paste consistency (ie. can be slathered on fish).","images":[],"step":3},{"title":"Slather and bake","description":"Smear paste onto surface of fish (not underside). Bake for 15 minutes until the internal temperature is 55°C/131°F (medium, just cooked but not raw at all, very juicy).","duration":15,"images":[],"step":4},{"title":"Rest","description":"Remove from oven and remove fish from tray (otherwise it keeps cooking). Rest 3 minutes, serve over rice with Sambal Tomat (below) and extra fresh coriander.","images":[],"step":5},{"title":"Sambal Tomat Topping","description":"Heat oil in a non-stick pan over medium heat. Add tomato, chilli and salt. Sauté 2 minutes until tomato is slightly softened. Stir through coriander, serve over fish.","images":[],"step":6}]', '["fish","nuts"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Indonesian"],"categories":["asian-recipes","curry-recipes","dietary","fish-recipes","gluten-free-recipes","low-calorie-recipes","mains","modern-asian","other","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_61ac668a588e', 'en', 'US', 'Galbi - Korean BBQ Marinated Beef Short Ribs', 'Recipe video above. This is an excellent Korean barbecue marinade that will work with pork, chicken or even lamb. And while it''s delicious cooked on the stove, a BBQ will better replicate the true Korean barbecue experience!Do not worry about overcooking the thin slices of beef. The marinade is magical, it keeps the thin slices of beef incredibly tender even if you cook it for over 10 minutes which would ordinarily turn the beef into inedible dry cardboard!', 'https://www.recipetineats.com/tachyon/2021/04/Korean-Beef-Short-Ribs-Galbi_6-1.jpg', 10, 10, 20, 4, '[{"id": "ing_beef_steak", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.333, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_mirin", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_onion", "quantity": {"value": 37.5, "unit": "pack of 1kg"}}, {"id": "ing_pears", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.03, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1 kg/ 2lb beef short ribs, butterflied Korean style (pictured) ( or thinly sliced through the bone (Note 1 for subs))","1 tbsp vegetable oil (, for cooking)"]},{"ingredients":["1/3 cup soy sauce (all purpose or light soy, not dark or sweet)","1/4 cup brown sugar","2 tbsp mirin (Note 2)","1/4 cup onion (, finely grated (including juice))","1/4 cup nashi pear (, finely grated including juice (sub normal pear or any red apple, Note 3))","2 tsp garlic (, finely grated)","2 tsp ginger (, finely grated)","2 tbsp water","1 tbsp toasted sesame oil (Note 4)","1 tsp black pepper"],"purpose":"Korean Barbecue Marinade:"},{"ingredients":["Green onion, sesame seeds, coriander/cilantro leaves (, for garnish)","Kimchi Fried Rice","Smashed Cucumbers"],"purpose":"Serving (optional):"}]', '[{"title":"Make Marinade","description":"Whisk Marinade ingredients in a bowl.","images":[],"step":1},{"title":"Marinade 24 hours","description":"Place beef in a ziplock bag, glass or ceramic container. Pour over Marinade, mix well to coat. Cover and marinade for 24 hours.","images":[],"step":2},{"description":"Cooking:","images":[],"step":3},{"description":"Remove beef from Marinade, discard Marinade.","images":[],"step":4},{"title":"BBQ","description":"Heat on high until smoking hot, then brush grills with vegetable oil. Lay beef on BBQ and cook for 2 minutes on one side until caramelised. Turn and cook the other side until caramelised. Remove, loosely cover with foil, cook remaining beef.","duration":2,"images":[],"step":5},{"title":"Stove","description":"Cut beef strips into pieces that will fit your skillet. Heat skillet with oil over high heat. Add beef and cook for 2 minutes until caramelised, then turn and cook the other side for 2 minutes.","duration":2,"images":[],"step":6},{"description":"Garnish beef with sesame seeds and green onions if desired. You don''t need a sauce for this one - it is literally dripping with flavour! Pictured in post with Kimchi Fried Rice and Ginger Smashed Cucumbers.","images":[],"step":7}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","BBQ","Korean"],"categories":["asian-recipes","asian-takeout","beef","beef-recipes","grilling-ideas-and-recipes","iconic-dishes","korean-recipes","mains","modern-asian"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d4b904f2b27d', 'en', 'US', 'Thai Cashew Chicken Stir Fry', 'Recipe video above. Crunchy and creamy cashews are the star in this popular Thai chicken stir fry! Tossed with a bold and savoury Thai stir fry sauce, make this as spicy as you want – or not at all.Thai Cashew Chicken is a dry-style stir fry so there''s not a ton of sauce like with Chinese Cashew Chicken. But the flavour in this one is much more intense so you don''t need nor do you want more sauce, it will be too salty!SPICINESS: Nice buzz to it from 1/2 a fresh chilli, not blow-your-head-off spicy.', 'https://www.recipetineats.com/tachyon/2021/04/Thai-Cashew-Chicken_9.jpg', 10, 8, 18, 2, '[{"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_cashews", "quantity": {"value": 75.0, "unit": "jar"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.5, "unit": "jar of 40g"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 tbsp peanut oil (or canola or vegetable oil)","1/2 cup raw cashews (, unsalted (Note 1 for roasted))","1 garlic clove (, finely minced)","1/2 onion ((brown, yellow, or white), cut into thin wedges)","200g/7oz chicken thighs (, skinless and boneless, sliced into 1cm / 1/3\" thin strips (Note 2))","2 green onions (, cut into 2.5cm / 1” lengths, white part separated from green part)","1/2 red cayenne pepper (, deseeded and finely sliced on the diagonal (omit or reduce if preferred) (Note 3))"]},{"ingredients":["1 tbsp oyster sauce (Note 4)","1 tsp dark soy sauce (Note 5)","2 tsp fish sauce (Note 6)","1 tsp white sugar","3 tbsp water"],"purpose":"Sauce:"},{"ingredients":["Red chilli (, finely sliced (optional garnish))","Jasmine rice (, for serving (or other rice of choice))"],"purpose":"Serving:"}]', '[{"title":"Sauce","description":"Mix all the Sauce ingredients in a small bowl.","images":[],"step":1},{"title":"Cook cashews","description":"Heat oil over medium heat in a wok or large skillet. Add cashews and cook for 5 minutes until they become a dark golden colour and crunchy (yep, you might have to eat one to check!). Remove from skillet with a slotted spoon.","duration":5,"images":[],"step":2},{"title":"Garlic & onion","description":"Turn heat up to high. Add garlic and onion. Cook for 30 seconds.","duration":0.5,"images":[],"step":3},{"title":"Chicken","description":"Add chicken. Cook for 1 minute until the outside changes from pink to white.","duration":1,"images":[],"step":4},{"title":"White part of green onion & chilli","description":"Add white part of green onions and chilli. Cook for 1 minute until chicken is just cooked through.","duration":1,"images":[],"step":5},{"title":"Add Sauce","description":"Cook for 1 minute until it reduces down to a syrup, coating the chicken nicely.","duration":1,"images":[],"step":6},{"title":"Green onion & cashews","description":"Add green part of green onions and cashews. Toss for 30 seconds.","duration":0.5,"images":[],"step":7},{"title":"Serve","description":"Transfer to serving dish. Serve with jasmine rice, or other rice of choice, garnished with extra red chilli (if you can handle the heat!).","images":[],"step":8}]', '["fish","gluten","peanuts","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","asian-takeout","chicken","chicken-breast-recipes","chicken-recipes","cuisines","dinner-tonight","mains","quick-and-easy","stir-fries","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b830007f7c89', 'en', 'US', 'Asian Glazed Baked Barramundi (or other fish)', 'Recipe video above. Banish boring baked fish with this sweet n'' savoury, gently spiced Asian-style barbecue glaze. A quick finish under the broiler / grill caramelises the glaze for maximum flavour! For the most juicy and perfectly cooked fish, take the fish out when the internal temperature is 55C/135F. Serve with plain or flavoured rice, and some wholesome veggies to complete.', 'https://www.recipetineats.com/tachyon/2021/02/Baked-Barramundi-with-Asian-Glaze_5.jpg', 10, 25, 35, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.05, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.3, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.12, "unit": "jar of 500g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.03, "unit": "pack of 100g"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sambal_oelek", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}]', '[{"ingredients":["4 x 180g / 6oz barramundi fillets (, skinless, boneless; or other ~2.5cm / 1\" thick firm white fish fillets (Note 1))"]},{"ingredients":["4 tsp cornflour / cornstarch","2 tbsp water","5 tbsp soy sauce (, all-purpose or light soy sauce (Note 2))","4 tbsp honey (else maple syrup or 5 tbsp brown sugar)","1 tbsp sesame oil","1 tbsp Chinese black vinegar or rice vinegar (Note 3)","1 tbsp mirin (Note 4)","1 tsp sambal oelek (, or other Asian chilli paste / sauce (Note 5))","1/2 tsp Chinese Five Spice (Note 6)","1 clove garlic (, finely minced)","1 tsp ginger (, finely grated)","1/4 tsp Sichuan pepper (, or white pepper (Note 7))"],"purpose":"Glaze:"},{"ingredients":["Sesame seeds","Green onions (Note 8)","Large red chilli, finely sliced"],"purpose":"Garnishes"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan). Line a tray with parchment/baking paper. Place shelf in middle of oven.","images":[],"step":1},{"title":"Cornflour slurry","description":"Mix water and cornflour in a small bowl.","images":[],"step":2},{"title":"Make glaze","description":"Place remaining glaze ingredients in a small saucepan over medium-low heat. Simmer for 2 minutes. Add cornflour slurry then stir well. Cook it for a further 2 minutes until it thickens into a thick paste – thick enough so it stays on the fish when brushed on. See photo in post or video. If it is just a thick syrup, it will slide off the fish.","duration":2,"images":[],"step":3},{"title":"Brush glaze on Fish","description":"Place fish fillets on tray. Dab/brush paste on on the top and sides.","images":[],"step":4},{"title":"Bake then broil/grill","description":"Bake fish for 15 minutes. Then flick to broiler/grill on high, and cook for 3 minutes to caramelise the surface. Target an internal temperature of 55°C/131°F for medium, which is just cooked but not raw at all. Fish temperature will continue to rise to 58°C/136.5°F during resting.","duration":15,"images":[],"step":5},{"title":"Garnish","description":"Remove from oven, transfer to serving plates and rest for 5 minutes. Garnish with green onion, chillies and sesame seeds, as desired. Pictured in post with a side of Coconut Rice and cucumber with Asian Sesame Dressing.","duration":5,"images":[],"step":6}]', '["fish","gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","dietary","dinner-tonight","fish-recipes","low-calorie-recipes","mains","modern-asian","other","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ad31a0106d3d', 'en', 'US', 'General Tso''s Chicken', 'Recipe video above. That perfect combination of sweet, savoury, spicy and tangy with crispy Chinese chicken bites. This is a Chinese takeout favourite that pushes all the right buttons!', 'https://www.recipetineats.com/tachyon/2020/10/General-Tsao-Chicken_1.jpg', 15, 10, 25, 4, '[{"id": "ing_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chilli", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["3 tbsp soy sauce - light or all-purpose (NOT dark soy, Note 1)","1 tbsp hoisin sauce","1 tbsp rice vinegar (sub white wine vinegar)","2 tsp chilli paste (, any (Sambal Oelak is great))","1 tsp sesame oil (toasted preferably (Note 6))","3 tbsp brown sugar","1 tbsp cornflour/cornstarch","3/4 cup chicken stock/broth (, low sodium)"],"purpose":"Sauce/Chicken Marinade:"},{"ingredients":["600g/ 1.4 lb chicken thighs (, boneless skinless, cut into 2.5cm / 1\" pieces (breast / tenderloin - Note 2))","1 tsp ginger (, finely grated)","1 tsp garlic (,finely grated)","1 cup cornflour/cornstarch (Note 5)","1 - 4 cups oil, for frying (peanut, vegetable or canola; Note 4)"],"purpose":"Chicken:"},{"ingredients":["2 tbsp oil (peanut, vegetable or canola)","2 tsp ginger (, finely chopped (Note 3))","2 cloves garlic (, finely chopped (Note 3))","1/2 teaspoon red chilli flakes (red pepper flakes)"],"purpose":"Stir Fry Sauce:"},{"ingredients":["Finely sliced green onion","Sesame seeds"],"purpose":"Garnishes (at least 1 recommended):"}]', '[{"title":"Sauce-Marinade","description":"Mix the soy, hoisin, vinegar, chilli and sesame oil.","images":[],"step":1},{"title":"Marinate Chicken","description":"Take out 2 tablespoons of Sauce-Marinade and mix with chicken. Add ginger and garlic to chicken, mix, then marinate 30 minutes.","images":[],"step":2},{"title":"Dust chicken","description":"Add cornflour into chicken and toss to coat, ensuring pieces are separated so they get fully coated.","images":[],"step":3},{"title":"Shake off excess","description":"Tip into a colander and shake to remove excess cornflour (or grab handfuls, shake so cornflour falls through your fingers).","images":[],"step":4},{"title":"Finish Sauce","description":"To the remaining Sauce-Marinade (that you made in Step 1), add sugar and cornflour. Mix, then add chicken stock and mix.","images":[],"step":5},{"title":"Heat oil","description":"Heat 2 cm / 4/5\" oil in a deep skillet (or large pot - whatever you’re comfortable with) to 200°C/390°F. To use less, see Note 4.","images":[],"step":6},{"title":"Fry","description":"Cook chicken 3 minutes, turning halfway, until golden and crispy. Drain on paper towel lined plate.","images":[],"step":7},{"title":"New / clean skillet","description":"Discard oil, wipe skillet and return to heat. Or use another large skillet.","images":[],"step":8},{"title":"Stir Fry Sauce","description":"Heat oil in a large skillet over medium heat. Add garlic, ginger, chilli flakes, saute 30 seconds until garlic is light golden. Add Sauce, bring to simmer and stir occasionally until it thickens enough that you can draw a path across pan base.","images":[],"step":9},{"title":"Toss! Add chicken, toss to coat quickly","description":"the quicker you are, the crispier the chicken stays! Transfer to serving plate, garnish and serve immediately with your rice of choice.","images":[],"step":10}]', '["gluten","peanuts","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["American Chinese","Chinese"],"categories":["asian-recipes","asian-takeout","chicken-recipes","chinese-recipes","modern-asian"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c2ace503e5a6', 'en', 'US', 'Chinese Rice Soup', 'Recipe video above. This is a really quick and easy soup recipe that''s filling and nourishing. The Asian infused soup broth adapted from my Chinese Noodle Soup has a depth of flavour that belies the few ingredients called for. As for add ins - in the spirit of simplicity and speed, I''ve just used fish and choy sum. But you''re only limited by your imagination!', 'https://www.recipetineats.com/tachyon/2020/10/Chinese-Rice-Soup_0.jpg', 5, 10, 15, 3, '[{"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.25, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_white_rice", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_stems_choy_sum", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 litre / 32 oz chicken stock/broth, low sodium (Note 1)","1 cup water","2 garlic cloves (, smashed (Note 2))","1.5 cm / 1/2\" ginger piece, (cut into 3 slices)","1 1/2 tbsp light soy sauce (, or normal all purpose soy sauce (Note 3))","1 1/2 tbsp Chinese cooking wine (, key ingredient (Note 4 subs))","1/4 - 1/2 tsp sesame oil (, toasted (optional) (Note 5))","1/4 tsp white pepper (sub black, can omit)"],"purpose":"Broth"},{"ingredients":["3/4 cup uncooked white rice (- long grain, medium grain, short grain, jasmine (Note 6))","3 stems choy sum (, cut into 2cm / 1\" lengths, stems separated from leaves (Note 8))","250g / 8 oz white fish fillets (, cut into 2.5cm / 1\" cubes (Note 8))","1 green onion (, finely sliced)"],"purpose":"Add Ins"},{"ingredients":["Crispy fried shallots (Note 9)","Crunchy fried noodles (, pictured in post (Note 9))","Chilli oil or paste"],"purpose":"Toppings (1 minimum, all best!)"}]', '[{"title":"Combine broth ingredients","description":"Place chicken stock, soy sauce, Chinesse cooking wine, garlic and ginger in a small pot over high heat.","images":[],"step":1},{"title":"Simmer to infuse","description":"Place lid on, bring to simmer then reduce to medium and simmer for 5 minutes to allow the flavours to infuse.","duration":5,"images":[],"step":2},{"title":"Add rice","description":"Add rice and cook uncovered for 10 minutes - broth surface should be bubbling very gently.","duration":10,"images":[],"step":3},{"title":"Add fish & stems","description":"Add fish and stems of choy sum, cook for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Pick garlic and ginger out of soup.","images":[],"step":5},{"description":"Stir through choy sum leaves (they will wilt almost instantly), sesame oil and pepper. Serve immediately.","images":[],"step":6}]', '["fish","gluten","sesame","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","asian-soups","chinese-recipes","emergency-recipes","fish-recipes","quick-and-easy","rice-recipes","seafood-recipes","soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9d58951cd4c5', 'en', 'US', 'Satay Chicken Curry (Malaysian)', 'Recipe video above. Forget skewers - THIS is how you get a satay fix! This Malaysian Chicken Satay Curry features chicken marinated in a homemade satay seasoning, simmered in a heady peanut satay sauce that''s coconuty and heavily seasoned. Truly restaurant quality. Yet -simple. No hunting down unsual ingredients!Spice level: Pretty warm buzz but not that spicy. If concerned, read note 1 & 3 for how to play it safe with the chilli!Adapted from a Satay recipe by a Malaysian chef and the Satay Sauce from Chinta Ria, a popular Sydney Asian restaurant - refer Note 10.', 'https://www.recipetineats.com/tachyon/2016/05/Satay-Chicken-Curry_9.jpg', 20, 25, 45, 5, '[{"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 0.005, "unit": "jar"}}, {"id": "ing_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.35, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_chicken", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_peanuts_roasted", "quantity": {"value": 112.5, "unit": "jar"}}, {"id": "ing_kecap_mani", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.08, "unit": "jar of 375g"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_lemongrass", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_peanuts", "quantity": {"value": 0.281, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 1/2 tsp coriander","1 1/2 tsp cumin powder","1 1/2 tsp tumeric","1 1/2 tsp paprika (sweet or normal, not smoked or spicy)","1 1/4 tsp chilli powder (, adjust to taste (not US \"Chili Powder\", Note 1))","3 1/2 tsp curry powder (, not HOT (any, Malaysian, generic, Clives of India, Keens))","1 1/4 tsp salt (, cooking / kosher (or 1 tsp table salt))","2 tsp white sugar"],"purpose":"Satay Seasoning"},{"ingredients":["750g / 1.5 lb chicken thigh fillets (, cut into bite size pieces (Note 2))","1/2 onion ((brown, white or yellow), grated)"],"purpose":"Chicken"},{"ingredients":["2 tbsp oil (, separated)","3 - 6 birds eye chillies or other small hot red chillies (, finely chopped (Note 3))","1/4 cup onion (brown, white or yellow), finely diced (~ 1/4 onion)","4 garlic cloves (, minced)","1 cup chicken broth / stock","3/4 cup peanuts, roasted unsalted, (, chopped, separated)","2 tsp kecap manis (Note 4)","3 tsp dark soy sauce (Note 5)","400g / 14oz coconut milk (preferably full fat but light will be ok)","2 tbsp peanut butter (, pure best but spread ok too, crunchy or smooth)","2 tbsp lime juice (, to taste)"],"purpose":"Satay Sauce"},{"ingredients":["3 makrut lime leaves (formerly kaffir lime leaves) (Note 6)","1 lemongrass stalk (, white part only, smashed to burst open (Note 7))"],"purpose":"Flavour Infusion – choose ONE:"},{"ingredients":["Peanuts (, chopped)","Cilantro / coriander leaves","Fresh chilli, finely chopped"],"purpose":"Garnish (choices)"}]', '[{"description":"Combine Satay Seasoning ingredients in a small bowl.","images":[],"step":1},{"description":"Marinate & Cook Chicken:","images":[],"step":2},{"title":"Marinate","description":"Combine chicken with 3 1/2 TABLESPOONS Satay Seasoning and onion in a bowl. Marinate for at least 3 hours, preferably overnight, minimum 20 minutes (Note 6)","images":[],"step":3},{"title":"Cook","description":"Heat 1 tbsp oil in a non stick skillet over high heat (Note 7). Cook chicken in 2 batches until browned all over but still raw inside. Transfer to bowl, cover and keep warm.","images":[],"step":4},{"title":"Saute aromatics","description":"Using the same skillet, turn heat down to medium and heat 1 tbsp oil. Add chill, onion and garlic cloves. Sauté until onion is translucent - around 2 minutes.","images":[],"step":5},{"title":"Satay Seasoning","description":"Add remaining Satay Seasoning and cook for 1 minute.","duration":1,"images":[],"step":6},{"title":"Blitz","description":"Transfer to a blender or small food processor (I use a Nutribullet). Add chicken stock and 1/2 cup of the peanuts (rest gets added later). Puree until pretty smooth - some peanut chunks can remain. Pour mixture back into the skillet.","images":[],"step":7},{"title":"Add remaining ingredients into sauce","description":"Add remaining 1/4 cup peanuts, kecap manis, dark soy sauce, coconut milk and peanut butter. Stir to combine.","images":[],"step":8},{"title":"Add lime leaf or lemongrass","description":"Crush makrut lime leaf in hand a bit (to break leaf to release the flavour). Add lime leaf OR lemongrass and chicken to sauce.","images":[],"step":9},{"title":"Simmer","description":"Bring to simmer, turn heat down to medium low and simmer for 15 minutes until thickened.","duration":15,"images":[],"step":10},{"title":"Serve","description":"Add lime juice to taste. Serve with rice (jasmine, white rice or brown rice). Garnish with peanuts, cilantro/coriander leaves and more chilli if desired. See Note 9 for suggested sides.","images":[],"step":11}]', '["gluten","peanuts","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Malaysian"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","curry-recipes","dietary","gluten-free-recipes","main-dishes","most-popular"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9064b7108256', 'en', 'US', 'Mongolian Lamb', 'Recipe video above. At “posher” establishments, Mongolian Lamb arrives at the table on a hot iron plate, sizzling and spitting for theatric effect. Sizzle aside, this homemade version is a near perfect replica. Even the velveted texture of the lamb!The sauce is sweet and savoury, with Chinese Five Spice and Hoisin the dominant flavours. It''s completely addictive!Also excellent made with beef - see Note 1.', 'https://www.recipetineats.com/tachyon/2020/08/Mongolian-lamb_9.jpg', 15, 10, 25, 4, '[{"id": "ing_lamb", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.013, "unit": "tub of 200g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.013, "unit": "pack of 400g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_chilli", "quantity": {"value": 0.075, "unit": "pack of 100g"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 4.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 0.08, "unit": "bunch"}}]', '[{"ingredients":["350g / 12 oz lamb meat (backstrap/fillet, mid loin chops, shoulder - or any cut in Note 1)","1/2 tsp baking soda (bicarb soda) (tenderiser, Note 2)","1 tsp cornflour / cornstarch","1 tbsp light soy sauce (or all purpose, Note 3)","1 tbsp Chinese cooking wine (Note 4 subs)"],"purpose":"Lamb and marinade:"},{"ingredients":["3 tsp cornflour / cornstarch","2 tsp dark soy sauce (Note 3)","1 tsp light soy sauce (or all purpose, Note 3)","1 1/2 tsp Sambal Oelak or other chilli paste (or omit for no spice)","3 tbsp hoisin sauce (I used Lee Kum Kee brand)","2 tbsp Chinese cooking wine (Note 4 subs)","1/4 tsp Chinese five spice powder (Note 5)","3/4 cup water","1 tsp sesame oil (, toasted (Note 6))"],"purpose":"Sauce:"},{"ingredients":["2 tbsp vegetable oil (or canola or peanut)","1 large onion (, cut into large 2.5cm / 1\" squares)","2 cloves garlic (, finely chopped)","4 green onions (, cut into 5cm/2\" lengths)"],"purpose":"Stir fry:"}]', '[{"description":"Tenderise Lamb:","images":[],"step":1},{"description":"Combine lamb and marinade ingredients, mix very well. Cover and refrigerate to marinate and tenderise the lamb.","images":[],"step":2},{"title":"Marinate 2 hours","description":"Backstrap, Midloin chops and other listed Tender Cuts in Note 1.","images":[],"step":3},{"title":"Marinate 24 hours","description":"lamb shoulder and other listed Economical Cuts in Note 1. (Bare minimum marinade times is 6 hrs).","images":[],"step":4},{"description":"Cooking:","images":[],"step":5},{"title":"Sauce","description":"Mix cornflour with the soy sauces, then mix in the remaining sauce ingredients. (Note 7)","images":[],"step":6},{"title":"Cook onion","description":"Heat oil over high heat in a wok or heavy based skillet. Add onions, and stir fry for 30 seconds until starting to colour. Add garlic and toss through quickly.","duration":0.5,"images":[],"step":7},{"title":"Cook Lamb","description":"Add lamb and cook for 3 minutes until most of it changes from red to brown, and some pieces start getting nice golden brown surfaces.","duration":3,"images":[],"step":8},{"title":"Add Sauce","description":"Add green onions, stir for 30 seconds (meat should all now be brown), then add Sauce. Stir and let simmer for 1 - 2 minutes until thickened.","duration":0.5,"images":[],"step":9},{"description":"Serve with rice!","images":[],"step":10}]', '["fish","gluten","peanuts","sesame","soy"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","lamb","lamb-recipes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_97919cb57f33', 'en', 'US', 'Built-to-last CRISPY Honey Chicken', 'Recipe video above. This recipe brings together a plethora of Asian cooking secrets for a crispy chicken that stays crispy for 4+ hrs even after tossing with sauce:1. Double coating - dredge in cornflour/cornstarch followed by batter2. Cold batter made with soda water = crispier chicken that''s puffy and light, not dense and greasy3. Cornflour/cornstarch + flour batter - cornflour for ultra crispiness, flour for golden colour + baking powder lift4. Double fry for extra long lasting, thicker crispiness AND less greasy (Asian secret!)5. No-Soggy Sauce - glucose or corn syrup to make it "candy like" to stick on chicken crust rather than soaking in, plus NO WATER in the sauce.See Notes for make ahead (99% like freshly made).', 'https://www.recipetineats.com/tachyon/2020/08/Honey-Chicken_0.jpg', 20, 30, 50, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.02, "unit": "bottle of 500ml"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 7.0, "unit": "tub of 200g"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.008, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_honey", "quantity": {"value": 0.167, "unit": "jar of 500g"}}, {"id": "ing_corn", "quantity": {"value": 0.056, "unit": "can of 400g"}}, {"id": "ing_rice_noodles", "quantity": {"value": 0.067, "unit": "pack of 375g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["300g/ 10oz chicken thighs (, skinless boneless, cut into 2.5cm/1\" pieces (Note 1))","1 tbsp light soy sauce (or all purpose, NOT dark soy)","2 tsp Chinese cooking wine (sub with soy)","2 tsp cornflour/cornstarch"],"purpose":"Chicken & Marinade:"},{"ingredients":["1/2 cup cornflour/cornstarch"],"purpose":"Dredging:"},{"ingredients":["6 tbsp cornflour/cornstarch (Note 8)","4 tbsp flour (, plain/all purpose)","7 - 8 tbsp COLD soda water, club soda or seltzer water (NOT sparkling mineral water, Note 2)","1/4 tsp baking powder (NOT baking soda)","1/4 tsp salt (, kosher/cooking (halve for table salt))"],"purpose":"Stay-Crispy Puffy Batter:"},{"ingredients":["2 - 3 cups vegetable oil (or canola)"],"purpose":"Oil, for frying:"},{"ingredients":["1/3 cup (100g) honey","1.5 tbsp (25g) glucose OR corn syrup (light) (Note 6)","1 tbsp light soy sauce (or all purpose)","2 tsp Chinese cooking wine (or more soy sauce)"],"purpose":"Honey Sauce (Note 8 on sweetness):"},{"ingredients":["25g / 2 oz Vermicelli rice noodles (optional) (, a wad of it (not bean noodles, must be rice noodles))","Sesame seeds, finely sliced green onions"],"purpose":"Garnish / serving:"}]', '[{"description":"Recommended step for beginners:","images":[],"step":1},{"description":"Place batter mixing bowl in the fridge with the flour, baking powder and salt. (Helps keep batter cold = crispier chicken)","images":[],"step":2},{"description":"Marinate & Dust Chicken:","images":[],"step":3},{"title":"Marinade","description":"Mix Chicken and Marinade in a bowl. Refrigerate for 30 minutes.","duration":30,"images":[],"step":4},{"title":"Dust","description":"Spread the 1/2 cup cornflour/cornstarch on a shallow plate. Scatter over about 8 to 10 chicken pieces, toss to coat, shake off excess, put on a plate. Repeat with all chicken.","images":[],"step":5},{"description":"Cold Batter & Fry #1:","images":[],"step":6},{"title":"Rack","description":"Place a rack on a tray (for draining, Note 3)","images":[],"step":7},{"title":"Heat oil","description":"Fill small pot or large saucepan with 4cm / 1.7\" oil. Heat to 180°C/350°F on medium high stove (or until chicken starts sizzle straight away when dipped).","images":[],"step":8},{"title":"Make Cold Batter","description":"Whisk together flour, cornflour/cornstarch, baking powder and salt. Pour in 7 tbsp soda water, then do minimum whisks just to combine (10 or so) - few lumps ok, better than whisking too much (changes coating texture).","images":[],"step":9},{"title":"Batter thickness","description":"should fully coat chicken easily, not be see through, but not thick and heavy - see video at 44 seconds. Use extra water 1 teaspoon at a time to achieve right thickness.","images":[],"step":10},{"title":"Dredge","description":"Drop 8 or so pieces of chicken into the batter. Turn to coat, then carefully place in oil.","images":[],"step":11},{"title":"Fry #1","description":"Cook for 3 minutes until light golden and crispy - when you pick them up, you can tell it''s very crispy.","duration":3,"images":[],"step":12},{"title":"Drain & repeat","description":"Place on rack, repeat with remaining chicken - I cook in 4 batches, don''t crowd the pot, brings oil temperature down too much.","images":[],"step":13},{"description":"Cool chicken for 20 minutes (Note 4). Meanwhile, make Sauce.","duration":20,"images":[],"step":14},{"description":"Place ingredients in a large saucepan over medium heat. Bring to simmer, then leave to simmer for 3 minutes.","duration":3,"images":[],"step":15},{"description":"Consistency should be like maple syrup (video at 1 min 11 sec). Turn off stove, place lid on to keep warm (when cool, gets too thick to toss chicken).","images":[],"step":16},{"title":"Fry #2","description":"for ultra crispy!","images":[],"step":17},{"description":"Heat oil to 200°C/390°F.","images":[],"step":18},{"description":"Add in half the chicken (you can crowd the pot for Fry #2). Cook for 90 seconds until it changes from pale golden to very golden (but not dark golden, chicken will overcook), then remove onto rack. More golden = crispier chicken.","duration":1.5,"images":[],"step":19},{"title":"Repeat with remaining chicken. (Feel the chicken","description":"you can tell it''s built-to-last crispy!)","images":[],"step":20},{"description":"Toss in Sauce & Serve:","images":[],"step":21},{"description":"Tumble into saucepan with sauce, use rubber spatula to quick toss until coated with sauce. (Sauce starts thickening if you take too long, so be quick!)","images":[],"step":22},{"description":"Pile chicken up over crispy noodles (if using), scatter with sesame seeds and green onion and serve!","images":[],"step":23},{"description":"Puffy Crispy Noodles (optional):","images":[],"step":24},{"description":"At any point while oil is hot, drop wad of noodles into hot oil, wait 3 seconds until it puffs up, then remove with tongs.","images":[],"step":25},{"description":"Drain on paper towels, place on plate to top with chicken!","images":[],"step":26}]', '["gluten","sesame","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken","chicken-breast-recipes","chicken-recipes","chinese-recipes","deep-fried-recipes","iconic-dishes","mains","modern-asian"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6437007c7815', 'en', 'US', 'Sweet and Sour Pork', 'Recipe video above. The best ever Sweet and Sour Pork recipe is loaded with tricks the Chinese have been using for centuries: double dredgeand double fry for extra crispy, cornflour instead of flour, economical pork used for juiciness, but tenderised with baking soda so you''d swear they''re pricey chops, and a sauce that''s not sickeningly sweet. Don''t let the list of ingredients daunt you. There''s a lot of repeat ingredients!OVEN option provided in notes. Because sometimes, you just have to....', 'https://www.recipetineats.com/tachyon/2020/08/Sweet-and-Sour-Pork_6.jpg', 20, 30, 50, 5, '[{"id": "ing_pork", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.009, "unit": "tub of 200g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 2.0, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.167, "unit": "bottle of 500ml"}}, {"id": "ing_pineapple", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_ketchup", "quantity": {"value": 0.09, "unit": "bottle of 500g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 2.5, "unit": "bottle"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_flour", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 2.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_pineapple", "quantity": {"value": 3.0, "unit": "unit"}}]', '[{"ingredients":["400g/14oz pork scotch roast (aka pork neck, collar butt) or shoulder / butt, (cut into 2cm / 4/5\" cubes (Note 1))","1/2 onion (, finely grated (Note 2a))","1 tsp garlic (, finely grated (Note 2a))","1 tsp ginger (, finely grated (Note 2a))","3/8 tsp baking soda (bi-carb) (Note 2b)","2 tsp cornflour/cornstarch","2 tbsp light soy sauce (, or all purpose (Note 3))"],"purpose":"Tenderised Marinated Pork:"},{"ingredients":["5 tbsp cornflour/cornstarch ( - for mixing in)","1/2 cup cornflour/cornstarch ( - for Coating)","2 - 3 cups vegetable or canola oil"],"purpose":"For frying:"},{"ingredients":["1/3 cup white sugar","1/3 cup apple cider vinegar (or 1/4 cup normal white vinegar)","3 tbsp pineapple juice (from a 227g/8oz can pineapple pieces in juice, preferably no added sugar, Note 4)","3 tbsp ketchup (or Aussie tomato sauce)","1/2 tsp Worcestershire sauce","1 tbsp soy sauce (, light)","1 tsp Oyster Sauce (Note 5)","4 tsp cornflour/corn starch","1/2 cup water"],"purpose":"Sweet & Sour Sauce:"},{"ingredients":["1 tbsp oil","1 garlic clove (, finely chopped)","2 tsp ginger (, finely chopped)","1 onion (medium), cut into 2.5cm/ 1\" cubes (brown, white, yellow)","1/2 red capsicum/bell pepper ((large), cut into 2.5cm / 1\" cubes)","1/2 green capsicum/bell pepper ((large), cut into 2.5cm / 1\" cubes)","1 cup pineapple pieces (from the can of pineapple under Sauce)"],"purpose":"Stir Frying:"}]', '[{"description":"Mix Pork with Marinade. Marinade 18 to 24 hours. (See Note 1 for marinating time for other cuts)","images":[],"step":1},{"title":"Rack & warm oven","description":"Preheat oven to 80°C/175°F and place rack on tray - to keep pork warm.","images":[],"step":2},{"title":"Sauce","description":"Place all Sauce ingredients EXCEPT water in a large jug or small bowl. Mix until combined, then mix in water.","images":[],"step":3},{"title":"Be Stir Fry Ready","description":"Have all ingredients lined up, ready to toss in. After Fry #2, things move quickly.","images":[],"step":4},{"title":"Coating #1","description":"Mix 5 tablespoons cornflour into the pork and leave for 5 minutes. At first, it will be white from the cornflour, but after a while it will sweat and make the cornflour (mostly / partially) wet, and will be sticky (this is key for coating to stick).","duration":5,"images":[],"step":5},{"title":"Coating #2","description":"Spread 1/2 cup cornflour in a shallow bowl. Coat pork, shaking off excess, and pile onto a plate.","images":[],"step":6},{"description":"Reserve cornflour in case you need to dust again just prior to frying. Pork should be at least half white when you put it into the oil (if not, just sprinkle with reserved cornflour).","images":[],"step":7},{"description":"Fried Crispy Pork (Note 6 for oven):","images":[],"step":8},{"title":"Heat oil","description":"Pour enough oil into a large saucepan or small pot so it''s 2.5cm / 1\" deep. Heat to 180°C/350°F (or until pork immediately starts sizzling when you dip it in).","images":[],"step":9},{"title":"Fry #1","description":"Cook pork in batches, being sure not to crowd the pot, for 3 minutes until golden. Drain on rack. This step is just to cook the pork. It takes me 4 batches.","duration":3,"images":[],"step":10},{"title":"Fry #2","description":"Turn the stove up slightly and heat oil to 200°C/390°F. Starting with the coolest pork, add half the pork (you can crowd the pot) and cook for 1 1/2 minutes, or until pork is deep golden brown and crispy. Transfer to rack, repeat with remaining pork - I do 2 batches.","images":[],"step":11},{"description":"Keep warm in oven.","images":[],"step":12},{"description":"Sauce & Stir Fry:","images":[],"step":13},{"description":"Heat oil in a very large skillet over high heat.","images":[],"step":14},{"description":"Add garlic, ginger and onion, stir for 1 1/2 minutes. Add capsicum and stir for 2 minutes.","duration":2,"images":[],"step":15},{"description":"Add Sauce & pinapple, then let it come to a rapid simmer. Simmer for 2 minutes until it thickens - when you drag the spoon across the base, a path should briefly appear (see video at 1 min 53 s).","duration":2,"images":[],"step":16},{"title":"10 second toss","description":"Add pork, then QUICKLY toss to coat - aim for 10 seconds!","duration":0.16666666666666666,"images":[],"step":17},{"description":"Serve asap! Pour onto serving plate, serve immediately! Will stay crispy for around 5 minutes then starts softening but still has a solid coating. This is just the reality of Sweet and Sour Pork, even at restaurants!","images":[],"step":18}]', '["gluten","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","deep-fried-recipes","modern-asian","pork-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4d2ed32f7ebe', 'en', 'US', 'Chicken Broccoli Stir Fry (extra sauce!)', 'Recipe video above. Big batch stir fry made with chicken and broccoli, and lots and lots of sauce - because broccoli florets hold lots of sauce but I still want some to soak my rice!This sauce uses the minimum ingredients you can get away with but still make something that stacks up to real Chinese take out. Chinese cooking wine (shoaxing wine) is the restaurant secret - just a small splash adds depth of flavour into the sauce.Shortcut using Charlie - see Note 5 (the sauce in this recipe is basically Charlie!).', 'https://www.recipetineats.com/tachyon/2020/07/Chicken-Broccoli-Stir-Fry_2.jpg', 10, 6, 16, 5, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.037, "unit": "tub of 200g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.075, "unit": "pack of 400g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_broccoli", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["500g/1 lb chicken breast, thinly sliced (or boneless thighs, do not tenderise)","1 1/2 tsp baking soda / bi-carb soda (Note 1)"],"purpose":"Tenderised chicken (Note 1)"},{"ingredients":["2 tbsp cornflour/cornstarch","3 tbsp light soy sauce (, or all purpose soy (Note 2))","1 1/2 tbsp Chinese cooking wine (shaoxing wine) or Mirin (Note 3)","3 tbsp oyster sauce (Note 4)","2 tsp sesame oil (, toasted (Note 5))","Dash of white pepper (sub black)"],"purpose":"Sauce (Note 6 for using Charlie all-purpose stir fry):"},{"ingredients":["2 tbsp oil (, peanut, vegetable or canola)","1/2 onion (, sliced)","2 garlic cloves (, finely minced with knife)","400g/ 14 oz broccoli florets (, broken/cut into small bite size pieces (2 medium heads, ~5 cups))","1 1/4 cups water"],"purpose":"Stir Fry:"},{"ingredients":["White rice (or other rice of choice)"],"purpose":"For serving:"}]', '[{"title":"Tenderise chicken","description":"Consider tenderising chicken breast using this method. (Not needed for thigh)","images":[],"step":1},{"title":"Broccoli","description":"steam or boil using preferred method until cooked to your taste (it won''t cook any further in the stir fry). I usually microwave steam 3 minutes on high. Drain well (waterlogged florets = diluted sauce).","images":[],"step":2},{"title":"Sauce","description":"Mix cornflour and soy sauce until lump free, then mix in remaining ingredients.","images":[],"step":3},{"title":"Cook aromatics","description":"Heat oil in a large skillet over high heat. Add garlic and onion, stir for 10 seconds until garlic starts to go golden.","duration":0.16666666666666666,"images":[],"step":4},{"title":"Cook chicken","description":"Add chicken and cook for 2 minutes or until the chicken is just cooked through.","duration":2,"images":[],"step":5},{"title":"Thicken sauce","description":"Add broccoli, Sauce and water. Stir well and cook for 1 to 2 minutes until the Sauce thickens and becomes glossy, and coats the ingredients.","duration":1.5,"images":[],"step":6},{"description":"Serve over rice!","images":[],"step":7}]', '["gluten","peanuts","sesame","soy"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["American Chinese","Asian","Chinese"],"categories":["asian-recipes","broccoli-recipes","chicken-breast-recipes","chicken-recipes","chinese-recipes","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_399afb02c305', 'en', 'US', 'Gado Gado (Indonesian Salad with Peanut Sauce)', 'Recipe video above. Fun to say, delicious to eat, the Gado Gado peanut sauce will make any vegetables into a big, healthy, tasty meal! Use any veg you want - the ones I''ve used are in the spirit of traditional Indonesian Gado Gado. Using Thai Red Curry Paste is an effective shortcut - it uses a lot of the ingredients used in Gado Gado sauce. Saves time, effort and money!All the veg can be warm or at room temp, so cook them first. Tempeh/tofu is best hot and crispy fresh out of the skillet.', 'https://www.recipetineats.com/tachyon/2020/06/Indonesian-Gado-Gado.jpg', 15, 15, 30, 2, '[{"id": "ing_peanut_butter", "quantity": {"value": 0.133, "unit": "jar of 375g"}}, {"id": "ing_red_curry_paste", "quantity": {"value": 0.1, "unit": "bottle"}}, {"id": "ing_kecap_mani", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_ime_juice", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.312, "unit": "can of 400ml"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_spinach", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_beansprouts", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 200.0, "unit": "bag of 2kg"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_shrimp", "quantity": {"value": 15.0, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_tempeh", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_peanuts", "quantity": {"value": 0.037, "unit": "jar"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}]', '[{"ingredients":["1/3 cup natural peanut butter, smooth or crunchy (your choice) (Note 1)","4 tsp red curry paste (, store bought (Maesri brand best, Note 2))","3 tsp Kecap Manis (Indonesian sweet soy sauce, Note 3)","1 tsp sambal oelak or other chilli paste (adjust spiciness to taste)","1/2 tsp salt","1 large garlic clove (, pressed using garlic press (~ 3/4 tsp))","1 1/2 tbsp lime juice (Note 4)","1/2 cup coconut milk (, full fat (Ayam brand best))","1/2 cup water"],"purpose":"Gado Gado Sauce:"},{"ingredients":["1 bunch spinach (, roots trimmed)","4 cups beansprouts","200g / 7 oz potato ( - small halved, large peeled chopped 2 cm / 1\" cubes OR 1.5cm / 1/2\" slices)","1 cucumber (, sliced on the diagonal ( or 1/2 long cucumber ie Telegraph/English))","2 - 3 boiled eggs (, peeled and halved)","15 prawn crackers (, optional (Note 6))"],"purpose":"Salad (use any veg, Note 5):"},{"ingredients":["2 tbsp vegetable or peanut oil","200g / 7 oz tempeh (or firm tofu, Note 7)"],"purpose":"Crispy Tempeh (or tofu):"},{"ingredients":["1 tbsp finely chopped peanuts (highly recommended)","Red chilli (, finely sliced, optional (small = spicy, large = less spicy))"],"purpose":"Garnishes:"}]', '[{"description":"Gado Gado Peanut Sauce:","images":[],"step":1},{"description":"Mix all ingredients in a small saucepan over medium low heat. Bring to simmer then cook for 5 minutes, stirring regularly so the bottom doesn''t catch, until it thickens. If too thick, just add more water - should be able to drizzle it (see video for thickness).","duration":5,"images":[],"step":2},{"title":"Taste and adjust as follows","description":"lime for more sour, salt, sugar for sweet.","images":[],"step":3},{"description":"Cover and keep warm.","images":[],"step":4},{"description":"Blanched Vegetables:","images":[],"step":5},{"description":"Bring a saucepan of water to the boil.","images":[],"step":6},{"description":"Add potatoes and cook for 5 minutes or until cooked through. Use a slotted spoon to transfer to colander to drain.","duration":5,"images":[],"step":7},{"description":"Cook beansprouts for 3 minutes or until just wilted. Transfer to colander, press out excess water.","duration":3,"images":[],"step":8},{"title":"Add spinach, push under to submerge","description":"will instantly wilt. Remove, transfer to colander, press out excess water.","images":[],"step":9},{"description":"Crispy tempeh or tofu:","images":[],"step":10},{"description":"Slice into 0.75 x 5 cm / 1/3 x 2\" slices (or thereabouts).","images":[],"step":11},{"description":"Heat oil in a skillet over medium high heat. Cook tempeh 2 min on each side until deep golden and crispy. (Tofu ~ 1 1/2 min)","images":[],"step":12},{"description":"Either make one platter for sharing, or individual. Vegetables and egg can be served warm or at room temp, sauce should be served warm (it thickens when cool).","images":[],"step":13},{"description":"Place vegetables and tempeh on serving plate, top with egg.","images":[],"step":14},{"description":"Pour sauce into serving bowl.","images":[],"step":15},{"description":"Serve Gado Gado Salad with peanut sauce, peanuts for sprinkling, fresh chillies and prawn crackers on the side.","images":[],"step":16}]', '["egg","gluten","peanuts","shellfish","soy"]', '["high_protein"]', '{"mealType":["dinner","lunch"],"cuisine":["Bali","Indonesian"],"categories":["asian-recipes","modern-asian","salad-recipes-main-course","sauces","side-salads","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f0b300af633a', 'en', 'US', 'Mie Goreng (Mee Goreng)', 'Recipe video above. These noodles tossed in a sticky savoury sweet sauce originates from Indonesia but is also popular in Malaysia. With chicken, prawns, vegetables and the signature egg ribbons, it''s pretty fully loaded! They''re commonly made by street vendors with instant noodles which give it the familiar crinkly noodle look, but feel free to use any noodles you want. (PS Ketchup is authentic!)', 'https://www.recipetineats.com/tachyon/2020/02/Mie-Goreng_5.jpg', 15, 10, 25, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_kecap_mani", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_ketchup", "quantity": {"value": 0.06, "unit": "bottle of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.12, "unit": "kg"}}, {"id": "ing_shrimp", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_cabbage", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_beansprouts", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}]', '[{"ingredients":["3 instant noodle cakes (I use this)","250g/8oz fresh egg noodles (, thin to medium)","150g / 5oz dried egg noodles (, thin to medium)"],"purpose":"Noodles – use ONE (Note 1):"},{"ingredients":["2 tbsp kecap manis (or dark sweet soy sauce) (Note 2)","2 tsp light soy sauce (or normal soy, Note 3)","2 tsp dark soy sauce (, or more light soy sauce (Note 3))","1 tbsp oyster sauce (Note 4)","2 tbsp ketchup (yes really!)","1 tsp sambal oelak, chilli paste or Sriracha (adjust spiciness to taste)","2 tsp sesame oil"],"purpose":"Sauce:"},{"ingredients":["2 tbsp vegetable oil","2 eggs (, lightly whisked)","3 garlic cloves (, finely chopped)","120g/4oz chicken breast or thigh (, sliced thinly into small bite size pieces)","100g/3.5oz prawns/shrimp (, raw, peeled and deveined (smaller are better))","2 cups cabbage (, finely sliced (any green or white cabbage))","1 cup beansprouts","3 green onions (, cut into 5cm/2\" lengths (green and white part))"],"purpose":"Stir Fried Noodles:"}]', '[{"description":"Mix the Sauce in a bowl.","images":[],"step":1},{"description":"Prepare noodles per packet directions just before cooking.","images":[],"step":2},{"description":"Heat 1 tbsp oil in a large skillet over medium heat. Pour in egg, swirl to coat base. Cook 1 minute until mostly set, then flip (do your best!).","images":[],"step":3},{"description":"Slide onto cutting board, roll up into loose \"wrap\". Slice into 1cm/ 1/3\" thick pieces - you now have egg ribbons!","images":[],"step":4},{"description":"Cooking:","images":[],"step":5},{"description":"Heat remaining 1 tbsp oil in same skillet over HIGH heat.","images":[],"step":6},{"description":"Add garlic and chicken, cook until half surface turns white.","images":[],"step":7},{"description":"Add prawns and cook for 1 minute until chicken is mostly cooked.","duration":1,"images":[],"step":8},{"description":"Add cabbage and bean sprouts, toss for 1 minute until a bit wilted.","duration":1,"images":[],"step":9},{"title":"Add noodles, green onions and Sauce, toss for 1","description":"2 minutes until Sauce reduces and noodles caramelise a bit.","duration":1.5,"images":[],"step":10},{"description":"Toss through egg ribbons and serve immediately!","images":[],"step":11}]', '["egg","gluten","sesame","shellfish","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Indonesian","Malaysian"],"categories":["asian-recipes","noodles"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f78cce541191', 'en', 'US', 'Momofuku Bossam (Korean Slow Cooked Pork Shoulder Roast)', 'Recipe video above. This is David Chang''s famous Momofuku Bossam (or Bo ssam), his take on the traditional Korean pork dish that costs US$250 at his NYC restuarant! Pork shoulder is dry cured so it''s seasoned from end to end, then slow roasted until fall apart tender and finished with a brown sugar crust. Serve with condiments for DIY lettuce wraps for an epic eating experience that will be remembered for years to come!', 'https://www.recipetineats.com/tachyon/2020/02/Momofuku-Bossam-Korean-Slow-Cooked-Pork-Shoulder_1-1.jpg', 10, 300, 1450, 10, '[{"id": "ing_pork", "quantity": {"value": 3.5, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.105, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 7.5, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 50.0, "unit": "bottle"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.03, "unit": "bottle of 250ml"}}, {"id": "ing_vinegar", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_ssamjang", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_gochujang", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_oil", "quantity": {"value": 50.0, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_lettuce", "quantity": {"value": 4.0, "unit": "head"}}, {"id": "ing_white_rice", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_kimchi", "quantity": {"value": 500.0, "unit": "unit"}}, {"id": "ing_oysters", "quantity": {"value": 12.0, "unit": "kg"}}]', '[{"ingredients":["3.5-4 kg/ 7-8 lb pork butt / shoulder (, bone in & skinless (Note 1))","1/2 cup (110g) white sugar","1/2 cup (115g) kosher or cooking salt (NOT table salt) (Note 2)"],"purpose":"Slow Cooked Pork:"},{"ingredients":["1 tbsp kosher or cooking salt (NOT table salt) (Note 2)","7 tbsp brown sugar (, light or normal (not dark))"],"purpose":"Brown Sugar Crust:"},{"ingredients":["2.5 cups scallions (, thinly sliced (both green and white parts, ~5-6 stems))","1/2 cup fresh ginger (, peeled and finely grated (Note 3))","1/3 cup canola oil (Note 4)","1.5 tsp light soy sauce (or all purpose, not dark soy sauce Note 5)","1 teaspoon sherry vinegar (Note 6)","1/2 tsp kosher or cooking salt (, to taste (Note 2))"],"purpose":"Ginger Shallot Sauce:"},{"ingredients":["2 tbsp ssamjang (Note 8)","1 tbsp gochujang (Note 8)","5 tsp sherry vinegar (Note 6)","2 tbsp canola oil (Note 4)","1 tbsp water","1 tsp white sugar"],"purpose":"Spicy Ssam Sauce (Note 7):"},{"ingredients":["4 - 5 heads butter/bib lettuce (40 - 50+ leaves, Note 9)","3 cups cooked white rice","500g/1lb kimchi","12 + oysters (, raw, in shell (optional, Note 10))"],"purpose":"Serving:"}]', '[{"description":"Bossam Slow Cooked Pork:","images":[],"step":1},{"description":"Mix sugar and salt together. Pat pork dry. Coat pork in sugar salt mixture, getting it into all the crevices. Rub/pat well to adhere as best you can - discard excess salt unused/falls off (usually ~ 2-3 tbsp).","images":[],"step":2},{"description":"Place in a glass dish (Note 13), cover loosely with cling wrap and refrigerated 24 - 36 hours (Note 11).","images":[],"step":3},{"description":"Preheat oven to 150°C/300°F (all oven types) with rack in the middle of oven.","images":[],"step":4},{"title":"Remove pork from fridge","description":"surface will be wet. Either transfer pork to clean pan (metal, ceramic or glass) or drain off excess liquid / scrape out salt/sugar in same glass pan. Do not rinse pork.","images":[],"step":5},{"description":"Roast 5 hours (Note 12), uncovered, spooning over pan juices once each hour, until you can easily pull the meat apart with 2 forks (check on side).","images":[],"step":6},{"description":"Remove from oven, rest for 10 minutes (up to 1 hour is fine, loosely cover in foil).","duration":10,"images":[],"step":7},{"description":"Turn oven up to 260°C/500°F (all oven types).","images":[],"step":8},{"description":"Brown Sugar Crust:","images":[],"step":9},{"description":"Mix brown sugar and salt.","images":[],"step":10},{"description":"Spoon juices all over pork.","images":[],"step":11},{"description":"Spoon sugar onto pork and use your hands to make it stick to the top and sides (not underneath). Make layer on top as even as you can (for even caramelisation).","images":[],"step":12},{"description":"Place in oven for 10 minutes until surface is a deep golden crust, sugar is bubbling and caramelised (see VIDEO!). Keep a close eye on it from 5 minutes. If the highest points start getting black, cover with small piece of foil (just stick it on).","duration":10,"images":[],"step":13},{"description":"Remove from oven and transfer to serving platter for serving. (Don''t use pan juices, it will be salty from brine)","images":[],"step":14},{"title":"Ginger Shallot Sauce","description":"Mix ingredients in bowl and stand for 20 minutes to let it soften.","duration":20,"images":[],"step":15},{"title":"Ssam Sauce","description":"Mix ingredients together. Oil will naturally separate over time if sauce is left to stand, just mix again to reincorporate.","images":[],"step":16},{"description":"Place pork on serving platter with lettuce, oysters, kimchi, rice, Ginger Shallot Sauce and Ssam Sauce on the side.","images":[],"step":17},{"title":"Attack the pork","description":"it will shred easily. Shred as much or little as you want, let people do it themselves or you can do it for them. Prepare to fight over the epic crust.","images":[],"step":18},{"description":"To eat, place lettuce in hand. Spoon in some rice, top with pulled pork, small piece of kimchi, oyster, some ginger shallot sauce then finally a little drizzle of spicy Ssam sauce.","images":[],"step":19},{"description":"Bundle up, bite and enjoy!","images":[],"step":20}]', '["gluten","milk","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Korean","Modern Asian"],"categories":["asian-recipes","dietary","gluten-free-recipes","iconic-dishes","korean-recipes","main-dishes","modern-asian","pork-recipes","roasts","slow-cooked-fall-apart"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8af630ad60ee', 'en', 'US', 'Siu Mai (Shumai - Chinese Steamed Dumplings)', 'Recipe video above. Siu Mai is the first thing you grab off the trolleys when you descend upon your favourite Yum Cha. And now you can get your Siu Mai fix on demand! These Chinese steamed dumplings are filled with a classic pork and prawn filling. Serves 2 - 3 as a main meal, or more as part of a larger spread. Also see Japanese Shumai (smaller, topped with peas!)', 'https://www.recipetineats.com/tachyon/2020/02/Siu-Mai_Chinese-steamed-dumplings_3.jpg', 30, 8, 38, 20, '[{"id": "ing_shiitake_mushrooms", "quantity": {"value": 3.0, "unit": "pack of 150g"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.013, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_shrimp", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 20.0, "unit": "carton of 12"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.05, "unit": "kg"}}]', '[{"ingredients":["3 dried shiitake mushrooms (, soaked in boiling water, finely chopped (Note 1))","350g/ 13oz pork mince (ground pork) (, fatty (Note 2))","3/4 tsp salt","2.5 tsp sugar","1 tsp light soy sauce (Note 4)","1.5 tbsp Chinese cooking wine (aka Shaoxing wine, sub Mirin or dry sherry) (Note 5)","150g/5oz prawns/shrimp (, peeled and deveined, chopped 0.5cm / 1/5\" (Note 3))","2 tbsp white part of green onions (, finely minced (Note 6))","20 - 25 wonton wrappers / egg wrappers (8cm/3.5\" squares or rounds (Note 7))"]},{"ingredients":["50g/1.5oz flying fish roe (Note 8 for alternatives)"],"purpose":"Garnish:"}]', '[{"description":"Place pork, salt, soy sauce, rice wine, sugar with the pork meat/mince in a large mixing bowl. Mix vigorously with a spoon or use your hands until it becomes pasty (initially it will be crumbly) - about 30 seconds.","images":[],"step":1},{"description":"Add mushrooms, prawns and green onions, mix until just dispersed (don''t crush the prawn meat).","images":[],"step":2},{"description":"Making Siu Mai (process steps and video helpful!):","images":[],"step":3},{"description":"Form an \"O\" with your forefinger and thumb.","images":[],"step":4},{"description":"Place a wonton wrapper over the \"O\". Push in 1 heaped teaspoon of Filling and push down into the \"O\" hole.","images":[],"step":5},{"description":"Use a butter knife to smear more Filling into until level with edge of wonton.","images":[],"step":6},{"description":"Place on work surface and push down to flatten base and use fingers to shape into a round.","images":[],"step":7},{"description":"Steaming Dumplings:","images":[],"step":8},{"description":"Line a 30cm/12\" bamboo steamer (or stove steamer) with baking paper with holes in it (Note 9)","images":[],"step":9},{"description":"Fill a wok big enough to hold steamer with about 2 cups of water (Note 10). Bring to rapid simmer over medium high heat.","images":[],"step":10},{"title":"Place Siu Mai in steamer (20","description":"25 fits). Place lid on, place on wok over simmering water.","images":[],"step":11},{"description":"Steam 8 minutes, or until internal temperature of dumplings is 75°C/165°F. (If yours are bigger due to larger wonton wrappers are bigger, they will take longer).","images":[],"step":12},{"description":"Remove steamer from wok. Remove lid and place a tiny bit of roe in the middle of each dumpling.","images":[],"step":13},{"description":"Serve immediate with dipping sauce!","images":[],"step":14},{"description":"Siu Mai Dipping Sauce:","images":[],"step":15},{"description":"Provide soy sauce, Chinese black vinegar or normal white vinegar, Chinese chilli paste (or Sriracha or other chilli). Let people mix their own to their taste (I do: 3 parts soy, 1 part vinegar, as much chilli as I think I can handle).","images":[],"step":16}]', '["egg","fish","gluten","shellfish","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["snack","dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","chinese-recipes","dumplings","iconic-dishes","modern-asian","yum-cha-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_14e5bd3dff07', 'en', 'US', 'Dan Dan Noodles', 'Recipe video above. The iconic spicy Sichuan Dan Dan Noodles, made at home! Am intensely flavoured spicy sesame chilli oil sauce tossed with noodles and pork. Don''t be daunted by the list and steps, there''s no need to rush. Cook and prepare all the parts except the noodles. Cook the noodles just before serving so they''re piping hot because the idea is to toss hot noodles with the pork and sauce so the heat warms everything else up. That''s the Dan Dan way!', 'https://www.recipetineats.com/tachyon/2020/02/Dan-Dan-Noodles_4-2.jpg', 15, 15, 30, 4, '[{"id": "ing_sesame_seeds", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_chilli", "quantity": {"value": 0.225, "unit": "pack of 100g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.24, "unit": "bottle of 250ml"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_chilli", "quantity": {"value": 0.225, "unit": "pack of 100g"}}, {"id": "ing_chicken", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_sui_mi_ya_cai", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_stems_choy_sum", "quantity": {"value": 16.0, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_peanuts", "quantity": {"value": 0.037, "unit": "jar"}}]', '[{"ingredients":["2 tbsp Chinese sesame paste (sub tahini, Note 1)","1.5 tbsp Chinese chilli paste in oil (, adjust spiciness (Note 2))","4 tbsp light soy sauce (Note 3)","2 garlic cloves (, minced)","3 tsp white sugar","1/2 tsp Chinese five spice powder (Note 4)","1 tsp Sichuan pepper powder (, preferably freshly ground (Note 5))","3 tbsp (or more!) chilli oil (, preferably Chinese (Note 6))","3/4 cup (185ml) chicken broth/stock (, hot, low sodium)"],"purpose":"Dan Dan Sauce:"},{"ingredients":["2 tsp Hoisin sauce","1 tsp dark soy sauce (Note 7)","1 tbsp Chinese cooking wine (sub 2 tbsp extra chicken stock)","1/2 tsp Chinese five spice powder (Note 4)","1 tbsp vegetable oil","250g/ 8oz pork mince (ground pork)"],"purpose":"Pork topping:"},{"ingredients":["1 tsp vegetable oil","30g (1/4 cup) Sui Mi Ya Cai (preserved mustard greens) (, finely chopped (Note 8))"],"purpose":"Sui mi ya cai (preserved mustard greens):"},{"ingredients":["500g/1lb white fresh noodles (, medium thickness (Note 9))","16 choy sum stems (, cut into 15cm pieces)","2 green onions (, finely sliced)","1 tbsp peanuts (, finely chopped (optional))"],"purpose":"To serve:"}]', '[{"description":"Mix all ingredients except oil and chicken stock. Then gently stir in oil and stock - oil should be sitting on surface. Set aside.","images":[],"step":1},{"description":"Mix together hoisin, soy, Chinese wine and five spice (\"Sauce\").","images":[],"step":2},{"description":"Heat oil in a skillet or wok over high heat. Add pork and cook, breaking it up as you, until it changes from pink to white. Add Sauce and cook for 1 minute, then transfer into a bowl.","duration":1,"images":[],"step":3},{"description":"Sui mi ya cai (preserved mustard greens):","images":[],"step":4},{"description":"Return skillet to stove, reduce to medium heat. Add oil into middle of skillet.","images":[],"step":5},{"description":"Add Sui mi ya cai and stir for 30 seconds, just to warm through. Set aside.","duration":0.5,"images":[],"step":6},{"description":"Noodles & choi sum:","images":[],"step":7},{"description":"Bring a large pot of water to the boil. Cook noodles per packet directions.","images":[],"step":8},{"description":"Add choi sum for last 1 minute of cooking.","images":[],"step":9},{"description":"Ladle 1/4 of Dan Dan Sauce into a bowl. Pile in noodles, top with pork and Sui mi ya cai. Place choi sum on side.","images":[],"step":10},{"description":"Sprinkle with peanuts and green onions and serve.","images":[],"step":11},{"description":"To eat, mix it all up to coat the noodles well with Sauce, then devour!","images":[],"step":12}]', '["gluten","mustard","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["American Chinese","Sichuan","Szechuan"],"categories":["asian-recipes","chinese-recipes","iconic-dishes","modern-asian","noodles"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0a43dbd28272', 'en', 'US', 'Saucy Vegetable Stir Fry', 'Recipe video above. Any vegetables are totally scoffable when they''re smothered in a tasty Chinese gravy! Use any veg you want - just add them according to the cook time (hard veg in first, leafy veg in last). For a quick hit of protein, toss in some cubes of firm tofu. For a chicken version, use this Chicken Stir Fry. Recipe works with Charlie - see Note 4.', 'https://www.recipetineats.com/tachyon/2020/01/Vegetable-Stir-Fry_9.jpg', 10, 5, 15, 4, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_buk_choy", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_mushroom", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 tbsp vegetable oil","2 garlic cloves (, finely chopped)","1 tbsp ginger (, finely sliced (optional))","1/2 onion (, peeled and sliced)","1 carrot (, large)","3 medium buk choy ( or other leafy greens of choice (Note 1))","1 cup mushrooms (, sliced 3mm / 1/8\" thick)","1 capsicum (, sliced 1/2cm / 1/5\" thick)"]},{"ingredients":["1 tbsp cornflour / corn starch","1 1/2 tbsp soy sauce (, light or all purpose (not dark soy) (Note 2))","2 tsp Oyster Sauce","1 tbsp Chinese Cooking Wine or Mirin (Note 3)","1/2 tsp sesame oil (optional)","Dash of white pepper (or black)","3/4 cup / 185 ml water"],"purpose":"Sauce (or use 4 tbsp Charlie, Note 4):"},{"ingredients":["Finely sliced green onions","Sesame seeds"],"purpose":"Garnishes, optional:"}]', '[{"description":"Vegetable Prep:","images":[],"step":1},{"title":"Carrot","description":"cut in half lengthwise then diagonally sliced 2mm / 1/10\" thick","images":[],"step":2},{"title":"Buk Choy (Note 1)","description":"Trim base off, then cut leaves off the stem. Cut the stem lengthwise into 1cm / 2/5\" wide pieces. Keep leaves separate from stems, they will be cooked at different times.","images":[],"step":3},{"title":"Sauce (Charlie","description":"Note 4):","images":[],"step":4},{"description":"Place cornflour and soy sauce in a bowl and mix until cornflour is dissolved, then mix in remaining Sauce ingredients.","images":[],"step":5},{"description":"Cooking:","images":[],"step":6},{"description":"Heat oil in a wok or large heavy based skillet over high heat.","images":[],"step":7},{"description":"Add garlic and ginger, stir for 10 seconds. Add onion, stir for 30 seconds.","duration":0.16666666666666666,"images":[],"step":8},{"title":"Add carrot, capsicum and stems of buk choy","description":"stir for 1 minute.","duration":1,"images":[],"step":9},{"description":"Add mushrooms, then stir for 2 to 3 minutes until the vegetables are almost cooked.","duration":2.5,"images":[],"step":10},{"description":"Add Sauce and toss for 1 minute until Sauce thickens and becomes glossy, coating all the vegetables. Don''t overcook so they become floppy and limp - they should be just cooked, \"crisp tender\".","duration":1,"images":[],"step":11},{"description":"Remove from stove and serve over rice (low carb option: cauliflower rice). Garnish with green onions and sesame seeds if using. A big dollop of chilli sauce wouldn''t go astray either!","images":[],"step":12}]', '["gluten","sesame","soy"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-greens","asian-recipes","asian-takeout","chinese-recipes","dietary","gluten-free-recipes","low-calorie-recipes","mains","quick-and-easy","side-dishes","stir-fries","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_43bd74ad9828', 'en', 'US', 'Vietnamese Pho recipe', 'Recipe video above. Experience the magic of one of the greatest soups in the world with this easy to follow traditional recipe! The depth of flavour in the broth will blow you away - it looks so clear and light but it''s packed with flavour.Getting enough flavour and light-richness into the soup broth calls for the right combination of meat AND bones. You can''t just use bones (even really meaty ones), the soup just lacks flavour. I tried multiple times. Use the leftover cooked brisket to make Caramelised Vietnamese Pulled Beef (it''s so good!) and see in post for more ways to use it.Next time - try Chicken Pho! It''s amazing, and quicker to make. :)', 'https://www.recipetineats.com/tachyon/2019/04/Beef-Pho_6.jpg', 20, 180, 200, 6, '[{"id": "ing_onion", "quantity": {"value": 2000.0, "unit": "pack of 1kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_star_anise", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_cinnamon_quill", "quantity": {"value": 4.0, "unit": "jar"}}, {"id": "ing_cardamon_pods", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_beef_brisket", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_marrow_bones_cut_to_reveal_marrow", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 3.5, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.04, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 50.0, "unit": "pack"}}, {"id": "ing_beef", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_brisket_slices", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_beansprouts_handful", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_sriracha", "quantity": {"value": 1.0, "unit": "bottle of 400ml"}}]', '[{"ingredients":["2 large onions (, halved)","150g / 5oz ginger (, sliced down the centre)"],"purpose":"Aromatics:"},{"ingredients":["10 star anise","4 cinnamon quills","4 cardamon pods","3 cloves (the spice cloves!)","1.5 tbsp coriander seeds"],"purpose":"Spices"},{"ingredients":["1.5kg / 3lb beef brisket","1kg / 2lb meaty beef bones","1kg / 2lb marrow bones ((leg, knuckle), cut to reveal marrow)","3.5 litres / 3.75 quarts water (15 cups)"],"purpose":"Beef bones (Note 1):"},{"ingredients":["2 tbsp white sugar","1 tbsp salt","40 ml / 3 tbsp fish sauce (Note 2)"],"purpose":"Seasoning:"},{"ingredients":["50g / 1.5 oz dried rice sticks (or 120g/4oz fresh) (Note 3)","30g / 1 oz beef tenderloin, raw, very thinly sliced (Note 4)","3 - 5 brisket slices (used for broth)"],"purpose":"Noodle Soup – PER BOWL:"},{"ingredients":["Beansprouts, handful","Thai basil, 3 - 5 sprigs","Coriander/cilantro, 3 - 5 sprigs (or more basil)","Lime wedges*","Finely sliced red chilli*","Hoisin sauce*","Sriracha* (for spiciness)"],"purpose":"Toppings:"}]', '[{"description":"Heat a heavy based skillet over high heat (no oil) until smoking.","images":[],"step":1},{"description":"Place onion and ginger in pan cut side down. Cook for a few minutes until it''s charred, then turn. Remove and set aside.","images":[],"step":2},{"description":"Toast Spices lightly in a dry skillet over medium high heat for 3 minutes.","duration":3,"images":[],"step":3},{"description":"Remove impurities:","images":[],"step":4},{"description":"Rinse bones & brisket then cover with water in large stock pot.","images":[],"step":5},{"description":"Boil for 5 minutes, then drain.","duration":5,"images":[],"step":6},{"description":"Rinse each bone and brisket under tap water.","images":[],"step":7},{"description":"Wipe pot clean, bring 3.5 litres / 3.75 quarts water to boil.","images":[],"step":8},{"description":"Add bones and brisket, onion, ginger, Spices","images":[],"step":9},{"title":"Add onion, ginger, Spices, sugar and salt","description":"water should just barely cover everything.","images":[],"step":10},{"description":"Cover with lid, simmer 3 hours.","images":[],"step":11},{"description":"Remove brisket (should be fall-apart tender), cool then refrigerate for later.","images":[],"step":12},{"description":"Simmer remaining soup UNCOVERED for 40 minutes.","duration":40,"images":[],"step":13},{"description":"Strain broth into another pot, discard bones and spices. Should be about 2.5 litres / 2.65 quarts (10 cups), if loads more, reduce.","images":[],"step":14},{"description":"Add fish sauce, adjust salt and sugar if needed. Broth should be beefy, fragrant with spices, savoury and barely sweet.","images":[],"step":15},{"description":"Prepare rice noodles per packet, just prior to serving.","images":[],"step":16},{"description":"Place noodles in bowl. Top with raw beef and brisket.","images":[],"step":17},{"title":"Ladle over about 400 / 14 oz hot broth","description":"will cook beef to medium rare.","images":[],"step":18},{"description":"Serve with Toppings on the side!","images":[],"step":19}]', '["fish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["asian-recipes","asian-soups","beef-recipes","iconic-dishes","soup-recipes","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a0e0746cfb8d', 'en', 'US', 'Pad Thai', 'Recipe video above. Here''s a Pad Thai recipe that really does taste just as good as takeout from good Thai restaurants, and you''ll find everything you need at the supermarket! I use chicken here but feel free to switch with any protein, even prawns/shrimp. If you''re after a truly authentic Pad Thai recipe, see here - but be warned that most people will find it a little too "real" for their palettes because Pad Thai in Thailand has stronger fish sauce/dried shrimp "funk". (Don''t misread that word! :))', 'https://www.recipetineats.com/tachyon/2018/05/Chicken-Pad-Thai_9.jpg', 20, 10, 30, 2, '[{"id": "ing_rice", "quantity": {"value": 125.0, "unit": "pack"}}, {"id": "ing_tamarind_puree", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 2.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_beansprouts", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_tofu", "quantity": {"value": 0.25, "unit": "pack of 300g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_peanuts", "quantity": {"value": 0.094, "unit": "jar"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_more_beansprouts", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["125 g / 4oz Chang''s Pad Thai dried rice sticks (Note 1)"]},{"ingredients":["1 1/2 tbsp tamarind puree (, NOT concentrate (Note 2))","3 tbsp (packed) brown sugar","2 tbsp fish sauce (Note 3)","1 1/2 tbsp oyster sauce (Note 4)"],"purpose":"Sauce:"},{"ingredients":["2 - 3 tbsp vegetable or canola oil","1/2 onion (, sliced (brown, yellow))","2 garlic cloves (, finely chopped)","150 g/5oz chicken breast (or thigh) (, thinly sliced)","2 eggs (, lightly whisked)","1 1/2 cups of beansprouts","1/2 cup firm tofu, cut into 3cm / 1 1/4\" batons (see photo)","1/4 cup garlic chives , cut into 3cm / 1 1/4\" pieces","1/4 cup finely chopped peanuts"],"purpose":"Stir Fry:"},{"ingredients":["Lime wedges (essential)","Ground chilli or cayenne pepper (optional)","More beansprouts"],"purpose":"For serving:"}]', '[{"description":"Place noodles in a large bowl, pour over plenty of boiling water. Soak for 5 minutes, then drain in a colander and quickly rinse under cold water. Don''t leave them sitting around for more than 5 - 10 minutes.","duration":5,"images":[],"step":1},{"description":"Mix Sauce in small bowl.","images":[],"step":2},{"description":"Heat 2 tbsp oil in a large non stick pan (or well seasoned skillet) over high heat. Add garlic and onion, cook for 30 seconds.","duration":0.5,"images":[],"step":3},{"description":"Add chicken and cook for 1 1/2 minutes until mostly cooked through.","images":[],"step":4},{"description":"Push to one side of the pan, pour egg in on the other side. Scramble using the wooden spoon (add touch of extra oil if pan is too dry), then mix into chicken.","images":[],"step":5},{"description":"Add bean sprouts, tofu, noodles then Sauce.","images":[],"step":6},{"description":"Toss gently for about 1 1/2 minutes until Sauce is absorbed by the noodles.","images":[],"step":7},{"description":"Add garlic chives and half the peanuts. Toss through quickly then remove from heat.","images":[],"step":8},{"description":"Serve immediately, sprinkled with remaining peanuts and lime wedges on the side, with a sprinkle of chilli and a handful of extra beansprouts on the side if desired (this is the Thai way!). Squeeze over lime juice to taste before eating.","images":[],"step":9}]', '["egg","fish","gluten","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","cuisines","noodles","quick-and-easy","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a24a8884f9ef', 'en', 'US', 'Lo Mein Noodles', 'Recipe video above. If you want lip smackingly delicious Lo Mein noodles just like takeout, you just need to get the SAUCE right! The noodle part is easy - you can literally use any noodles, even pasta (yep, seriously). Also, switch out the vegetables with 5 cups (packed) of any chopped vegetables of choice.', 'https://www.recipetineats.com/tachyon/2019/11/Lo-Mein_5.jpg', 8, 7, 15, 3, '[{"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 6.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.05, "unit": "pack of 400g"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 20.0, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.12, "unit": "bunch"}}]', '[{"ingredients":["1.5 tbsp vegetable or peanut oil","2 garlic cloves (, finely minced (Note 1))","1/2 onion (, finely sliced)","300g / 10oz chicken or other protein (, sliced 0.5cm / 1/5\" thick (Note 2))","2 medium carrots (, peeled and cut into 4 x 0.75cm / 1.75 x 1/3\" batons)","1 large red capsicum / bell pepper (, sliced (or 2 small))","6 green onions (, cut into 5 cm/2” lengths)","500g / 1lb Lo Mein, Hokkien or other medium thickness egg noodles, fresh, (, prepared per packet (Note 3 for dried))","1/4 cup (65ml) water"]},{"ingredients":["4 tsp cornflour / cornstarch","2 tbsp dark soy sauce (Note 4)","2 tbsp soy sauce or light soy sauce ( (Note 4))","1 tbsp Chinese cooking wine or Mirin (Note 5 subs)","1 tsp white sugar (omit if using Mirin)","1/2 tsp sesame oil (, toasted, optional (Note 6))","1/4 tsp white pepper (sub black)"],"purpose":"Sauce:"},{"ingredients":["Green onion (, finely sliced)"],"purpose":"Garnish (optional):"}]', '[{"title":"Sauce","description":"Mix cornflour and dark soy until lump free, then add remaining Sauce ingredients.","images":[],"step":1},{"title":"Season Chicken","description":"Transfer 2 tsp Sauce into bowl with chicken. Toss to coat.","images":[],"step":2},{"description":"Heat oil in a wok or large heavy based skillet over high heat until smoking.","images":[],"step":3},{"description":"Add onion and garlic, stir 30 seconds.","images":[],"step":4},{"description":"Add chicken, stir until white on the outside, still raw inside - 1 minute.","images":[],"step":5},{"description":"Add carrot and capsicum/bell peppers, cook 2 minutes or until chicken is cooked.","images":[],"step":6},{"description":"Add noodles, Sauce and water. Use 2 wooden spoons and toss for 30 seconds.","duration":0.5,"images":[],"step":7},{"description":"Add green onions, toss for another 1 minute until all the noodles are slick with sauce.","images":[],"step":8},{"description":"Serve immediately, garnished with extra green onions if using.","images":[],"step":9}]', '["egg","gluten","peanuts","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["American Chinese","Asian","Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dinner-tonight","main-dishes","noodles","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_69ddfa114ba2', 'en', 'US', 'Chicken Fried Rice', 'Recipe video above. A fully loaded, completely delicious Chicken Fried Rice! Serve it as a side - or have it as a main! (See here for a classic side dish Fried Rice).', 'https://www.recipetineats.com/tachyon/2019/09/Chicken-fried-rice-copy.jpg', 10, 10, 20, 4, '[{"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 112.5, "unit": "pack of 1kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.6, "unit": "pack of 200g"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_corn", "quantity": {"value": 0.188, "unit": "can of 400g"}}, {"id": "ing_frozen_peas", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_white_rice", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 2.25, "unit": "bunch"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.075, "unit": "bottle of 500ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["2 tbsp oil (, peanut, vegetable or canola)","2 eggs (, lightly whisked)","150g (5oz) chicken breast (, finely sliced into small pieces)","2 garlic cloves (, minced)","1/2 onion (, finely chopped)","120g (4oz) bacon (, excess fat trimmed, chopped (Note 1))","1 small carrot* (, peeled and diced 0.75cm / 1/3\")","1/2 cup frozen corn* (or can or fresh)","1/2 cup frozen peas*","2 cups (packed) cooked white rice (, day old (Note 2))","3/4 cup green onions (, finely sliced)"]},{"ingredients":["2.5 tbsp Chinese cooking wine or Mirin (Note 3)","1 tbsp oyster sauce (Note 4)","3 tbsp light soy sauce (Note 5)","1/2 tsp sesame oil (, optional)","1/4 tsp white pepper (, optional)"],"purpose":"SAUCE:"}]', '[{"title":"Sauce & chicken","description":"Mix Sauce in a bowl. Pour 2 tsp over chicken, toss to coat, then set aside for 10 minutes.","duration":10,"images":[],"step":1},{"title":"Egg","description":"Heat 1 tbsp oil in a wok or skillet over medium heat. Add egg and scramble until just cooked (still a touch wet) then remove.","images":[],"step":2},{"title":"Fried Rice","description":"Turn heat up to high, add remaining 1/2 tbsp oil and bacon into same skillet. Cook for 1 minute or so until fat starts to melt, then add onion and garlic.","duration":1,"images":[],"step":3},{"title":"Cook until bacon is light golden","description":"about 1 1/2 minutes.","images":[],"step":4},{"description":"Add vegetables (still frozen is fine). Cook for 1 minute.","duration":1,"images":[],"step":5},{"description":"Add chicken and cook until it changes from pink to white - about 1 1/2 minutes.","images":[],"step":6},{"description":"Add rice and Sauce ingredients. Cook for 1 1/2 minutes, stirring consantly.","images":[],"step":7},{"description":"Add egg and green onion, toss through to disperse then remove from heat.","images":[],"step":8},{"description":"Serve immediately!","images":[],"step":9}]', '["egg","gluten","peanuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","chinese-recipes","fried-rice","quick-and-easy","rice-recipes","rice-side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e1d3b895634b', 'en', 'US', 'Tom Yum Soup (Thai Soup)', 'Recipe video above! The famous Thai Soup, made at home, and it''s honestly the real deal!! See recipe notes for shortcut using frozen peeled prawns/shrimp. Also, CHOOSE from classic clear Tom Yum (Tom Yum Goong Nam Sa) or the creamy Tom Yum version (Tom Yum Goong Nam Khon)!', 'https://www.recipetineats.com/tachyon/2019/09/Tom-Yum-soup_2.jpg', 15, 20, 35, 2, '[{"id": "ing_shrimp", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_lemongrass", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_galangal", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_lime", "quantity": {"value": 5.0, "unit": "net of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_oyster_mushrooms", "quantity": {"value": 0.8, "unit": "pack of 150g"}}, {"id": "ing_tomato", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 5.0, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_milk", "quantity": {"value": 0.083, "unit": "L"}}]', '[{"ingredients":["300g / 10oz whole prawns / shrimp (with heads and shells on (Note 7))"]},{"ingredients":["3 cup (750 ml) water","1/2 cup (125 ml) chicken stock/broth (, low sodium)","2 stalks of lemongrass (, outer layers peeled(Note 1))","1.5 cm / 3/5\" piece of galangal (, cut into 4 slices (Note 2))","5 kaffir lime leaves (, torn roughly (Note 3))","2 Thai or birdseye chillies (Note 4)","3 garlic cloves"],"purpose":"Broth:"},{"ingredients":["120g / 4oz oyster mushrooms","1 roma tomato (, cut into wedges)","1/2 white onion ((medium sized), cut into wedges about 1 cm thick)","1 tsp sugar","3 tbsp fish sauce (Note 5)","3 tbsp lime juice","Coriander/cilantro (, for garnish)"],"purpose":"Soup Add Ins:"},{"ingredients":["1 1/2 tbsp Thai roasted chili sauce (Nam Prik Pa, Note 6)","1/3 cup (75 ml) evaporated milk"],"purpose":"Creamy Tom Yum Option:"}]', '[{"description":"Peel the prawns. Place heads and shell in pot, reserve meat.","images":[],"step":1},{"description":"Use a meat mallet or similar to bash the garlic, chilli and lemongrass so they burst open to release flavour. Add into pot.","images":[],"step":2},{"description":"Crush kaffir lime leaves with your hands. Add into pot.","images":[],"step":3},{"description":"Add galangal, stock and water. Bring to simmer on high heat, cover, then reduce to medium and simmer for 10 minutes.","duration":10,"images":[],"step":4},{"description":"Strain the broth, discard the prawn shells etc, then return broth into same pot over low heat.","images":[],"step":5},{"description":"Add onions and mushrooms, simmer 3 minutes. Add tomatoes, simmer for 1 minute.","duration":1,"images":[],"step":6},{"description":"Add prawns, simmer 2 minutes or until just cooked.","images":[],"step":7},{"description":"Stir in sugar and fish sauce, simmer for 1 minute.","duration":1,"images":[],"step":8},{"description":"Add lime juice, then taste. Adjust sweet (sugar), salt (fish sauce) and sour (lime) to your taste (trust me, you''ll know when you like it!).","images":[],"step":9},{"description":"Ladle into bowls and serve with fresh coriander and fresh chilli! This is the CLEAR version of Tom Yum.","images":[],"step":10},{"description":"Creamy Tom Yum:","images":[],"step":11},{"description":"When you add sugar, also add Thai Chilli Paste and evaporated milk.","images":[],"step":12},{"description":"Then continue with recipe!","images":[],"step":13},{"title":"Bonus","description":"Tom KHA!","images":[],"step":14},{"description":"Following Creamy Tom Yum steps but use coconut milk instead of evaporated milk.","images":[],"step":15}]', '["fish","milk","shellfish"]', '["gluten_free","high_protein","low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Thai"],"categories":["asian-recipes","asian-soups","cuisines","dietary","iconic-dishes","low-calorie-recipes","soup-recipes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b8d7cd238ad5', 'en', 'US', 'Sticky Chinese Chicken Wings', 'Recipe video above. My family recipe for the ultimate Sticky Chinese Wings, perfected over years with many heated debates! Many of the ingredients can be substituted and you''ll still get a similar flavour - refer to the notes. Spiciness: A hint of spicy from the chilli sauce, can be omitted.', 'https://www.recipetineats.com/tachyon/2014/06/Sticky-Chinese-Chicken-Wings_5.jpg', 10, 50, 60, 6, '[{"id": "ing_chicken", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_ketchup", "quantity": {"value": 0.075, "unit": "bottle of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_five_spice_powder", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}]', '[{"ingredients":["1.5 kg /3 lb chicken wings (, cut into drumettes and wingettes (Note 1))"]},{"ingredients":["1/2 tsp sesame oil (, toasted )","2 tbsp lemon juice","2 tbsp Chinese cooking wine (Shaoxing wine, sub Mirin, dry sherry)","2 tbsp soy sauce (, light or all purpose)","2 tbsp brown sugar or honey","1 1/2 tbsp hoisin sauce","1 1/2 tbsp oyster sauce","1/4 cup ketchup (or Aussie tomato sauce)","1 tbsp chilli garlic sauce (or sambal oelek (adjust spiciness to taste))","4 cloves garlic (, minced)","1 tbsp ginger (, finely grated)","1/2 tsp five spice powder"],"purpose":"Chicken Wing Marinade (Note 2 for substitutions)"},{"ingredients":["Finely sliced shallots/scallions","Sesame seeds","Coriander/cilantro leaves","Finely sliced fresh chili"],"purpose":"Garnishes (optional)"}]', '[{"description":"Mix Marinade ingredients.","images":[],"step":1},{"description":"Place wings in large bowl, pour over Marinade and toss well. Set aside for 10 minutes - do not marinate for longer than 1 hour. (Note 3)","duration":10,"images":[],"step":2},{"description":"Preheat the oven to 180C/350F.","images":[],"step":3},{"description":"Line baking tray with foil then greaseproof paper (you''ll thank me later).","images":[],"step":4},{"description":"Shake excess marinade off wings (but reserve the marinade) and spread on baking tray - can be fairly snug but not super squished (use 2 trays if needed).","images":[],"step":5},{"title":"Bake 45","description":"50 minutes, basting with a brush at 25 minutes and 35 minutes, using the reserved marinade and juieces on the tray.","images":[],"step":6},{"description":"The meat should be able to be pulled off the bones quite easily, they should be just starting to char on the edges and a sticky, dark red/golden colour all over.","images":[],"step":7},{"title":"Sprinkle with garnishes","description":"coriander/cilantro leaves, sesame seeds, chilli, sliced shallots/scallions - then serve!","images":[],"step":8}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["snack","dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","australia-day","chicken-recipes","chicken-wings","dinner-tonight","grilling-ideas-and-recipes","modern-asian","quick-and-easy","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_04b861d4f5dd', 'en', 'US', 'Tuna Poke Bowl', 'Recipe video above. The Dressing is what makes or breaks a Poke Bowl. This Ginger-Sesame one MAKES it!!! Mirin is the secret ingredient - it adds complexity and flavour that''s missing from usual Poke Bowl Dressings. It looks like a long list of ingredients and there are quite a few bits and pieces, but it''s actually a very leisurely recipe to make. (PS Dicing fish is great flavour carrier technique) GREAT HOT WEATHER FOOD!', 'https://www.recipetineats.com/tachyon/2019/08/Tuna-Poke-Bowls-main.jpg', 20, 15, 35, 4, '[{"id": "ing_rice", "quantity": {"value": 300.0, "unit": "pack"}}, {"id": "ing_water", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_mirin", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chilli", "quantity": {"value": 0.125, "unit": "pack of 100g"}}, {"id": "ing_ginger", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_sashimi_grade_tuna_0_7cm_1_4_dice", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_radishes", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_shelled_edamame", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["2 cups sushi rice (, rinsed (Note 1))","2 1/2 cups water"],"purpose":"Sushi Rice:"},{"ingredients":["1/4 cup rice vinegar (Note 2)","2 tsp sugar (, white)","1/4 tsp salt"],"purpose":"Sushi Rice Seasoning:"},{"ingredients":["1 1/2 tbsp light or all purpose soy sauce (Note 3)","2 tsp dark soy (Note 3)","2 1/2 tbsp toasted sesame oil (Note 4)","2 tbsp mirin (Note 5)","2 tbsp rice vinegar (Note 2)","2 1/2 tsp chilli paste or Sriracha","1 1/2 tsp grated ginger (, fresh)"],"purpose":"Ginger Marinade Dressing:"},{"ingredients":["350g / 12oz sashimi grade tuna (or salmon, trout or kingfish), diced 0.7cm / 1/4\" dice (Note 7)","1 small carrot (, finely julienned)","1 cucumber (, deseeded and finely diced (Note 7))","1 small avocado (, peeled and cut into 8 wedges (or dice))","6 red radish (, finely sliced)","1 cup shelled edamame (, boiled or steamed per packet (Note 8))","1 green onion (, finely sliced on the diagonal)","Black sesame seeds"],"purpose":"Poke Bowl:"}]', '[{"description":"Place water and rice in a large saucepan over medium high heat, no lid.","images":[],"step":1},{"description":"As soon as it comes to a boil (see video), lower heat to medium low, place lid on and leave for 18 - 20 minutes or until water is completely absorbed). DO NOT stir, DO NOT remove lid!","duration":19,"images":[],"step":2},{"description":"Remove from stove with lid still on and leave undisturbed for 15 minutes.","duration":15,"images":[],"step":3},{"description":"Sushi Rice Seasoning:","images":[],"step":4},{"description":"Mix Sushi Seasoning ingredients until sugar dissolves.","images":[],"step":5},{"description":"Spread rice out into large pan (23 x 33cm / 9 x 13\"), drizzle half Seasoning all over.","images":[],"step":6},{"description":"Using a rice paddle OR rubber spatula, cut through the rice and gently fold the rice over (see video!) to mix the Seasoning through.","images":[],"step":7},{"description":"After 1 minute of mixing, drizzle remaining Seasoning then cut/fold for 1 minute. Will look wet but will absorb in next step.","duration":1,"images":[],"step":8},{"description":"Leave rice to cool to warm or room temp (if you can stick it in front of a fan, that''s even better!) - about 20 minutes.","images":[],"step":9},{"description":"Poke Bowl Assembly:","images":[],"step":10},{"title":"Dressing","description":"Mix ingredients in a bowl.","images":[],"step":11},{"description":"Divide rice between bowls. Top with radish, carrot, edamame and avocado.","images":[],"step":12},{"description":"Place tuna in Dressing and toss (no need to marinate), then immediately transfer onto rice.","images":[],"step":13},{"description":"Sprinkle cucumber over the top (mainly on tuna), then green onion and sesame seeds.","images":[],"step":14},{"description":"Drizzle over remaining Dressing then serve!","images":[],"step":15}]', '["fish","gluten","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Hawaiian","Japanese(ish)","Western"],"categories":["asian-recipes","fish-recipes","rice-recipes","salad-recipes-main-course","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4264b86b0e37', 'en', 'US', 'Salmon Salad with Asian Ginger Sesame Dressing', 'Recipe video above. A mighty Salmon Salad that tastes even better than it looks! Vibrant flavours with a fabulous variety of textures - and the Asian Ginger Sesame Dressing gives this amazing flavours!', 'https://www.recipetineats.com/tachyon/2019/07/Salmon-Salad_1.jpg', 15, 10, 25, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_radishes", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_edamame", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.15, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["3 - 4 salmon fillets (, skinless)","3/4 tsp salt and pepper (, each)","1 tbsp oil","250g / 1.5 cups cherry tomatoes (, halved)","2 cucumber (, sliced (or 1 English/telegraph long cucumber))","1 large avocado (, cut into 1.5cm / 2/3\" pieces)","6 red radish (, sliced)","150g / 5 oz leafy crisp lettuce of choice (6 big handfuls)","1 cup edamame (, cooked per packet (Note 1))","1 green onion (, finely sliced on diagonal)","1/4 cup crispy fried shallots (Note 2)"]},{"ingredients":["2 tbsp soy sauce (light or all purpose)","2 1/2 tbsp rice vinegar (aka rice wine vinegar Note 3)","1 tbsp sesame oil (toasted, Note 4)","3 tbsp olive oil (or other neutral flavoured oil)","1.5 tsp sugar (, any type)","2 tsp fresh ginger (, grated)","1 garlic clove (, minced)","1/2 tsp black pepper"],"purpose":"Asian Ginger Sesame Dressing:"}]', '[{"description":"Place Dressing ingredients in a jar and shake well.","images":[],"step":1},{"description":"Sprinkle both sides of salmon with salt and pepper.","images":[],"step":2},{"description":"Heat oil in a non stick skillet over medium high heat.","images":[],"step":3},{"description":"Place salmon in upside down (ie skin side up), cook for 3 minutes or until deep golden.","duration":3,"images":[],"step":4},{"title":"Turn and cook for another 2","description":"3 minutes, or until cooked to your taste.","images":[],"step":5},{"description":"Remove onto plate and cool for 5 minutes.","duration":5,"images":[],"step":6},{"description":"Assemble Salad:","images":[],"step":7},{"description":"Place lettuce in a large bowl. Drizzle with a bit of dressing and toss.","images":[],"step":8},{"description":"Place lettuce in a large serving bowl (or individual plates). Top with salmon, then place tomato, cucumber, avocado, edamame and radish in piles around it.","images":[],"step":9},{"description":"Sprinkle with green onion and crispy shallots.","images":[],"step":10},{"description":"Just prior to serving, drizzle all over with remaining Dressing.","images":[],"step":11}]', '["fish","gluten","sesame","soy"]', '["high_protein"]', '{"mealType":["lunch","dinner"],"cuisine":["Asian influence"],"categories":["asian-recipes","fish-recipes","modern-asian","salad-recipes-main-course","salmon-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2252d8487ad7', 'en', 'US', 'Laksa Noodle Soup', 'Recipe video above. This is a recipe for a real Malaysian restaurant quality laksa made by sprucing up store bought laksa paste! You can''t just dump store bought laksa paste into coconut broth! The key is to freshen up the paste by sautéing it with garlic, ginger, chilli and lemongrass. Makes a world of difference! This makes 2 large bowls. Because large is the only way to go with Laksa!', 'https://www.recipetineats.com/tachyon/2016/09/Laksa.jpg', 15, 45, 60, 2, '[{"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_laksa_paste", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.1, "unit": "pack of 500g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.1, "unit": "pack of 500g"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 80.0, "unit": "bag of 250g"}}, {"id": "ing_tofu", "quantity": {"value": 0.267, "unit": "pack of 300g"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.03, "unit": "bottle of 250ml"}}, {"id": "ing_aksa_paste", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_sriracha", "quantity": {"value": 0.037, "unit": "bottle of 400ml"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}]', '[{"ingredients":["2 cups (500 ml) chicken stock / broth","1 cup (250 ml) water","3 chicken drumsticks (Note 1)"],"purpose":"Chicken Stock"},{"ingredients":["1 1/2 tbsp oil","2 garlic cloves (, minced)","2 cm / 4/5\" piece of ginger (, finely grated)","1 lemongrass (, white part grated, (Note 2))","2 birds eye chillis (, finely chopped (Note 3))","1/2 cup (135g) laksa paste (Note 4)","400ml can coconut milk (Note 5)","2 tsp fish sauce (sub soy)"],"purpose":"Laksa Broth"},{"ingredients":["50g / 1.5 oz vermicelli noodles (, dried)","100g / 3.5oz hokkien noodles (optional, Note 6)","80g / 2.5 oz bean sprouts","80g / 2.5 oz tofu puffs (, cut in half (Note 7))"],"purpose":"Noodles + Toppings"},{"ingredients":["1/2 tsp sugar (, white)","1 1/2 tsp soy sauce (, light or all purpose)","1/2 garlic clove (, minced)","1 1/2 tsp Laksa paste (Note 4)","1 tbsp Sriracha sauce (, or other chilli sauce)","1 tbsp chilli paste from jar (, or more Sriracha)","1 tbsp vegetable oil (any plain oil)"],"purpose":"Laksa Chilli Sauce (Note 8)"},{"ingredients":["Fresh coriander / cilantro (recommended)","Lime wedges (recommended)","Crispy fried shallots (, optional (Note 8))","Finely sliced red chilli (, optional )"],"purpose":"Garnishes"}]', '[{"description":"Place Chicken Stock ingredients in a medium saucepan over high heat. Bring to simmer, then reduce to medium high.","images":[],"step":1},{"description":"Cook for 25 minutes or until chicken flesh is falling off the bone and liquid reduces by about 1/3.","duration":25,"images":[],"step":2},{"description":"Discard skin, pull flesh off the bone and place in bowl, discard bone. Set broth aside.","images":[],"step":3},{"description":"Laksa Chilli Sauce","images":[],"step":4},{"description":"Mix ingredients together in a small bowl. Set aside for 20 minutes.","duration":20,"images":[],"step":5},{"description":"Heat oil in a large saucepan or small pot over medium low heat. Add garlic and ginger, sauté for 20 seconds, then add lemongrass and chillis. Cook for 1 minute.","duration":0.3333333333333333,"images":[],"step":6},{"description":"Add laksa paste. Turn heat up to medium and cook for 2 minutes, stirring constantly, or until fragrant.","duration":2,"images":[],"step":7},{"description":"Add chicken stock, coconut milk, fish sauce and 2 tsp of Laksa Chilli Sauce. Place lid on and simmer on for 10 minutes.","duration":10,"images":[],"step":8},{"description":"Adjust to taste using lime juice (for sour) and fish sauce (for saltiness). Add tofu puffs. Leave on turned off stove with lid on for 5 minutes.","duration":5,"images":[],"step":9},{"description":"Prepare noodles per packet directions.","images":[],"step":10},{"description":"Divide noodles between 2 bowls. Top with shredded chicken.","images":[],"step":11},{"description":"Pour broth over chicken. Top with beansprouts. Sprinkle with Garnishes you choose to use. Serve with Laksa Chilli Sauce on the side.","images":[],"step":12}]', '["fish","gluten","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Malaysian"],"categories":["asian-recipes","asian-soups","asian-takeout","chicken-breast-recipes","chicken-drumstick-recipes","chicken-recipes","curry-recipes","iconic-dishes","main-dishes","noodles","soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_daa08d39a60c', 'en', 'US', 'Nasi Goreng (Indonesian Fried Rice)', 'Recipe video above. A traditional Indonesian fried rice recipe which is often served with a fried egg for a protein boost to make it a meal, but I usually serve it as a side dish. The magic ingredient in this is kecap manis, a sweet soy sauce which is available in large supermarkets and of course in Asian stores. Feel free to swap out the chicken for other proteins! Shrimp/prawns, tofu, beef and pork are all great alternatives.', 'https://www.recipetineats.com/tachyon/2016/03/Nasi-Goreng_3-1.jpg', 10, 10, 20, 4, '[{"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.142, "unit": "kg"}}, {"id": "ing_kecap_mani", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_shrimp", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 4.0, "unit": "carton of 12"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["1 tbsp oil","5 oz / 150g chicken breast (, thinly sliced (or other protein))","1 tbsp kecap manis (sweet soy sauce, Note 1)"],"purpose":"Chicken"},{"ingredients":["1.5 tbsp oil","2 garlic cloves (, finely chopped)","1 tsp red chilli (, finely chopped (Note 2))","1 onion (, small, diced)","3 cups cooked white rice (, day old, cold (Note 3))","2 tbsp kecap manis (sweet soy sauce, Note 1)","2 tsp shrimp paste (, optional (Note 4))"],"purpose":"Rice"},{"ingredients":["4 eggs (, fried to taste)","1 green onion (, sliced)","Tomatos and cucumbers, (cut into wedges/chunks)","Fried shallots (, store bought (optional) (Note 3))","Lime wedges"],"purpose":"Garnishes / side servings (optional)"}]', '[{"description":"Heat oil in a large skillet or wok over high heat.","images":[],"step":1},{"description":"Add chilli and garlic, stir for 10 seconds.","duration":0.16666666666666666,"images":[],"step":2},{"description":"Add onion, cook for 1 minute.","duration":1,"images":[],"step":3},{"description":"Add chicken, cook until it mostly turns white, then add 1 tbsp kecap manis and cook for a further 1 minute or until chicken is mostly cooked through and a bit caramelised.","images":[],"step":4},{"description":"Add rice, 2 tbsp kecap manis and shrimp paste, if using. Cook, stirring constantly, for 2 minutes until sauce reduces down and rice grains start to caramelise (key for flavour!).","duration":2,"images":[],"step":5},{"description":"Serve, garnished with garnishes of choice (green onions, red chilli, fried shallots).","images":[],"step":6},{"description":"Serve as a side for Asian main dishes or as part of a large spread, Asian or not! :) See in post for suggestions.","images":[],"step":7},{"title":"Make it a meal","description":"traditional Indonesian style!: Serve with a fried egg sunny side up (runny yolk!), tomato wedges and slices of cucumber on the side.","images":[],"step":8}]', '["egg","gluten","shellfish","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Indonesian"],"categories":["asian-recipes","asian-takeout","dietary","dinner-tonight","fried-rice","gluten-free-recipes","main-dishes","quick-and-easy","rice-recipes","rice-side-dishes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_daa30431ea02', 'en', 'US', 'Bibimbap', 'Recipe VIDEO above. One of Korea''s most famous food exports! The key here is the Bibimbap Sauce - feel free to switch the veg and meat, whatever you use is going to be amazing once mixed up with that Sauce. There''s a lot of components here but there''s repeat ingredients and it''s an easy recipe - and it''s MEANT to be served at room temp so don''t rush!', 'https://www.recipetineats.com/tachyon/2019/05/Bibimbap_5.jpg', 40, 30, 70, 4, '[{"id": "ing_white_rice", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 4.0, "unit": "carton of 12"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_apples", "quantity": {"value": 0.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.03, "unit": "jar of 500g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_spinach", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_shiitake_mushrooms", "quantity": {"value": 8.0, "unit": "pack of 150g"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 4.0, "unit": "bag of 250g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.04, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_gochujang_paste", "quantity": {"value": 60.0, "unit": "bottle"}}, {"id": "ing_mirin", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}]', '[{"ingredients":["4 cups cooked white rice (, preferably short grain (Note 1))","4 eggs","2 tsp sesame seeds"]},{"ingredients":["250 g/8oz beef tenderloin or thick steak (, very finely sliced (subs, Note 2))","1/4 green apple (, grated using box grater (Note 3))","3 garlic cloves (, minced)","1 tsp minced ginger","1 tbsp soy sauce (, light or all purpose (Note 4))","1 tbsp honey (or brown sugar)","2 tsp sesame oil (, toasted (Note 9))"],"purpose":"Korean Beef & Marinade:"},{"ingredients":["2 carrots (, large, cut into 5 x 0.5cm/2 x 1/5\" batons)","2 zucchini (, large, cut into 5 x 0.5cm/2 x 1/5\" batons)","1 bunch of spinach (, cut into 5cm/2\" lengths)","8 dried shiitake mushrooms (, large (Note 5))","4 cups bean sprouts","2 tsp garlic (, minced (3 cloves))","8 tsp vegetable oil (, separated)","1/2 tsp salt","1.5 tsp soy sauce (, light or all purpose (Note 4))","1/4 tsp fish sauce (sub soy)","1/4 tsp white sugar","Sesame oil (, toasted (Note 9))"],"purpose":"Vegetables:"},{"ingredients":["4 tbsp gochujang paste (Note 6)","2 tbsp mirin (Note 7)","2 tbsp rice vinegar (Note 8)","1.5 tsp soy sauce (Note 4)","3 tsp white sugar","1 garlic clove (, finely grated)","2.5 tsp sesame oil (, toasted (Note 9))"],"purpose":"Bibimbap Sauce:"}]', '[{"description":"Bibimbap Sauce:","images":[],"step":1},{"description":"Mix ingredients until sugar is dissolved.","images":[],"step":2},{"description":"Marinated Beef:","images":[],"step":3},{"description":"Mix the marinade in a bowl, then add beef. Marinate for 30 minutes to overnight.","duration":30,"images":[],"step":4},{"description":"Heat 2 tsp oil in a large skillet over high heat. Let excess marinade drip off then add beef. Cook for 3 - 4 minutes until cooked and there''s some caramelised bits, then remove from skillet.","duration":3.5,"images":[],"step":5},{"description":"Keep warm until required or reheat to warm.","images":[],"step":6},{"description":"Prepare Vegetables:","images":[],"step":7},{"title":"Shiitake","description":"Soak mushrooms in a large bowl of boiling water for 30 minutes, or until rehydrated. Drain, squeeze out excess water, then slice.","duration":30,"images":[],"step":8},{"title":"Carrot and Zucchini salting (optional, Note 10)","description":"Place carrot and zucchini in separate bowls, sprinkle each with 1/4 tsp salt, toss, leave for 20 minutes then drain excess liquid.","duration":20,"images":[],"step":9},{"description":"Cook Vegetables:","images":[],"step":10},{"description":"Get 2 skillets going if you can!","images":[],"step":11},{"title":"Shiitake","description":"Heat 2 tsp oil oil in a skillet over medium high heat. Cook mushrooms for 2 minutes. Add 1.5 tsp soy, 1/4 tsp sugar, 1/2 tsp of garlic. Stir for 1 minute, then remove.","duration":2,"images":[],"step":12},{"title":"Carrot","description":"Add 2 tsp oil into the skillet, cook carrot until just tender (5 to 8 minutes), then remove.","images":[],"step":13},{"title":"Zucchini","description":"Cook as with carrot for 4 minutes.","duration":4,"images":[],"step":14},{"title":"Spinach","description":"Heat 2 tsp veg with a splash of sesame oil. Saute until starting to wilt. Add 1/2 tsp garlic, and salt to taste, stir, then remove. When cool, squeeze to drain out excess liquid.","images":[],"step":15},{"title":"Beansprouts","description":"Simmer in water for 5 min or steam in microwave for 3 min until floppy. Drain under cold water, then cool. Squeeze out excess liquid with hands, place in bowl. Mix with 2 tsp sesame oil, 1 tsp garlic, 1/4 tsp fish sauce.","duration":5,"images":[],"step":16},{"description":"Vegetables can cool, they are meant to be at room temp or slightly warm.","images":[],"step":17},{"description":"Fry eggs in a skillet to your taste (I like mine with runny yolks).","images":[],"step":18},{"description":"Place warm rice in bowls.","images":[],"step":19},{"description":"Top with vegetables and beef, as pictured in post, then lastly, the egg.","images":[],"step":20},{"description":"Sprinkle with sesame seeds, drizzled with sesame oil. Serve with Bibimbap Sauce!","images":[],"step":21}]', '["egg","fish","gluten","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Korean"],"categories":["asian-recipes","asian-takeout","beef-recipes","iconic-dishes","korean-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a3bad777ed77', 'en', 'US', 'Asian Mushroom Ramen Noodles', 'Recipe video above. A quick Asian ramen noodle side dish with caramelised garlic mushrooms with a hint of sesame! Don''t let this 4 ingredient sauce fool you - once it hits the pan, it completely transforms. 4 as a side, 2 as a main (add more veggies!)', 'https://www.recipetineats.com/tachyon/2019/03/Mushroom-Ramen-Noodles_3.jpg', 5, 10, 15, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.004, "unit": "pack of 500g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_mushroom", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_water", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}]', '[{"ingredients":["2 packets ramen or other instant noodles (, uncooked, discard seasoning (Note 1))","1.5 tbsp vegetable oil (or other neutral flavoured oil)","400g / 14 oz mushrooms (, sliced (any type))","2 garlic cloves (, minced)","2 tsp sesame oil (or more oil) (Note 2)","5 green onion stems (shallots/scallions)","1 1/4 cups (315 ml) water, plus more as needed"]},{"ingredients":["1 tbsp dark soy sauce (Note 3)","1 tbsp Oyster sauce (or Hoisin, Note 4)","2 tsp Hoisin sauce (or more Oyster sauce)","1 tbsp mirin (Note 5)"],"purpose":"SAUCE:"}]', '[{"description":"Mix Sauce ingredients in a small bowl.","images":[],"step":1},{"description":"Cut green onion into 5cm/2\" lengths. Separate white/pale green part from green part.","images":[],"step":2},{"description":"Heat oil in a large skillet over high heat. Add mushrooms and cook for 3 minutes.","duration":3,"images":[],"step":3},{"description":"Add the garlic and sesame oil, cook until mushrooms and garlic are golden.","images":[],"step":4},{"description":"Add Sauce, give it a quick stir. Add white part of green onions. Cook 1 minute until mushrooms are caramelised.","images":[],"step":5},{"description":"Push mushrooms to the side to make a big well in the centre.","images":[],"step":6},{"description":"Add water then squidge noodle cakes in.","images":[],"step":7},{"description":"Cook 45 seconds, then flip. Cook 30 seconds then break up the noodles.","images":[],"step":8},{"description":"Add green part of green onions and toss well, adding more water if needed to make it saucy.","images":[],"step":9},{"description":"Serve immediately!","images":[],"step":10}]', '["gluten","sesame","soy"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","dinner-tonight","emergency-recipes","mushroom-recipes","noodles","one-pot-recipes","quick-and-easy","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3196c7ccbf7b', 'en', 'US', 'Thai Chicken Satay with Peanut Sauce', 'Recipe video above. Thai Chicken Satay Skewers are tasty enough to eat plain but we''d never skip Thai Peanut Sauce for dipping! The essential ingredient for a really great peanut sauce is natural peanut butter with no added sugar or oil. But normal peanut butter will work fine too.', 'https://www.recipetineats.com/tachyon/2019/03/Thai-Satay-Chicken_8.jpg', 15, 15, 30, 15, '[{"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_skewers", "quantity": {"value": 13.0, "unit": "pack of 50"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_red_curry_paste", "quantity": {"value": 0.05, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.3, "unit": "jar of 375g"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_peanuts", "quantity": {"value": 0.075, "unit": "jar"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["400 g/14oz coconut milk ((1 can), full fat)","13-16 bamboo skewers (, 16cm / 6.5\" long (Note 1))"]},{"ingredients":["600 g / 1.2lb chicken thighs (, boneless skinless, cut into 2cm/4/5\" pieces (Note 2))","1 tbsp curry powder (Note 3)","1 tsp white sugar","2 tsp red curry paste (Note 4)","1 tsp cooking salt / kosher salt (sub 1/2 tsp table salt)"],"purpose":"Marinade:"},{"ingredients":["2 tbsp red curry paste (Note 4)","3/4 cup natural peanut butter, smooth (Note 5)","1/4 cup white sugar","2 tsp dark soy sauce (Note 6)","1 tsp cooking salt / kosher salt (sub 1/2 tsp table salt)","2 tbsp cider vinegar (Note 7)","3/4 cup water"],"purpose":"Thai Peanut Sauce:"},{"ingredients":["2 tbsp peanuts finely chopped","Lime wedges (optional)","Coriander / cilantro leaves and sliced red chilli (optional)"],"purpose":"Serving:"}]', '[{"description":"If cooking on a BBQ or over charcoal, soak skewers for 2 hours in water.","images":[],"step":1},{"description":"Thai Chicken Satay Skewers:","images":[],"step":2},{"description":"Mix together the chicken and Marinade with 1/4 cup of coconut milk, then set aside for at least 20 minutes, or overnight.","images":[],"step":3},{"title":"Thread onto skewers","description":"I do 4 to 5 pieces each.","images":[],"step":4},{"description":"Heat 1.5 tbsp oil in a large non stick pan over medium high heat.","images":[],"step":5},{"description":"Cook skewers in batches for 3 minutes on each side until golden.","duration":3,"images":[],"step":6},{"description":"Thai Peanut Sauce:","images":[],"step":7},{"description":"Place remaining coconut milk and Peanut Sauce ingredients in a saucepan over medium low heat.","images":[],"step":8},{"description":"Stir to combine then simmer, stirring every now and then, for 5 minutes.","duration":5,"images":[],"step":9},{"title":"Adjust consistency with water","description":"it should be a pourable but thickish sauce.","images":[],"step":10},{"description":"Cover with lid and keep warm while cooking skewers.","images":[],"step":11},{"description":"Pour some sauce into a bowl. Sprinkle with some peanuts - stir some through if you want.","images":[],"step":12},{"description":"Pile satay skewers onto a platter, sprinkle with remaining peanuts, coriander and chilli.","images":[],"step":13},{"description":"Serve with sauce on the side for dipping. Add a side of Jasmine Rice or Thai Fried Rice to complete the meal!","images":[],"step":14}]', '["gluten","peanuts","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Thai"],"categories":["asian-recipes","chicken-recipes","cuisines","iconic-dishes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b9bef2f0ca1d', 'en', 'US', 'Hot and Sour Soup', 'Recipe video above. A firm Chinese starter favourite! A glossy soup broth that''s savoury, sour and as spicy as you want it to be, filled with mushrooms, tofu and bamboo shoots. Skip the chicken to make it meat free, or add shrimp/prawns or fish pieces. Serves 6 - 8 as a starter, or 4 as a light meal.', 'https://www.recipetineats.com/tachyon/2019/02/Hot-and-Sour-Soup_1_6.jpg', 20, 20, 40, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.22, "unit": "kg"}}, {"id": "ing_shiitake_mushrooms", "quantity": {"value": 12.0, "unit": "pack of 150g"}}, {"id": "ing_mushroom", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_chicken", "quantity": {"value": 0.22, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_tofu", "quantity": {"value": 0.417, "unit": "pack of 300g"}}, {"id": "ing_bamboo_shoots", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.094, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["220 g / 7oz chicken breast","12 dried shiitake mushrooms (or 150g/5oz fresh) (Note 1)","1/2 cup wood ear mushrooms (, chopped 1.5cm/ 3/5\" pieces (Note 1))"]},{"ingredients":["1 tsp dried chilli / red pepper flakes (, adjust spice to taste (Note 2))","2 tsp dark soy sauce (Note 3)","1 tbsp light soy sauce (Note 3)","1 tsp ginger (, finely grated)","1/2 tsp white pepper (sub black)","6 cups (1.5L/1.5qt) chicken or veg stock/broth (, low sodium)","1 tsp sesame oil","1 tsp sugar","1/4 cup (65 ml) white vinegar (adjust to taste)"],"purpose":"Hot and sour soup broth:"},{"ingredients":["125 g / 4oz firm tofu (~ 1 cup) (, cut into 1.2cm / 0.5\" cubes (Note 4))","1/4 cup bamboo shoots (, thinly sliced (Note 5))","2 eggs (, whisked)","1/4 cup (40g) cornstarch/cornflour","1/4 cup (125 ml) water","Salt to taste","1 shallot/scallion (, finely sliced)"],"purpose":"Soup:"}]', '[{"description":"Cover shiitake mushrooms with plenty of boiling water. Stand 20 - 30 minutes until soft, drain, then slice thinly. (Discard or reserve liquid for other use)","images":[],"step":1},{"description":"Poached chicken:","images":[],"step":2},{"description":"Place chicken broth, ginger, soy sauces, chilli, sugar, pepper and sesame oil in a large pot over medium high heat.","images":[],"step":3},{"description":"Once simmering, add chicken, cover and reduce heat so it''s simmering.","images":[],"step":4},{"description":"Cook 10 minutes, remove chicken and shred.","images":[],"step":5},{"description":"Add vinegar, shiitake, wood ear mushrooms, bamboo shoots, tofu and shredded chicken into the soup.","images":[],"step":6},{"description":"Stir, simmer for 10 minutes.","duration":10,"images":[],"step":7},{"description":"Mix cornflour with water. While stirring soup at a medium pace, slowly pour the cornflour mixture in (ensures no lumps).","images":[],"step":8},{"description":"When it starts simmering again, stir constantly and slowly pour egg in a thin stream - this will create the signature \"egg ribbons\".","images":[],"step":9},{"title":"Taste","description":"add salt if desired, more chilli if you want.","images":[],"step":10},{"description":"Add shallots and serve!","images":[],"step":11}]', '["egg","gluten","sesame","soy"]', '["high_protein","low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-soups","asian-takeout","chinese-recipes","dietary","dinner-tonight","low-calorie-recipes","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7dc28d39aab0', 'en', 'US', 'How to Tenderise Chicken for Stir Fries (Chinese secret!)', 'Ever notice how the chicken in stir fries at your favourite Chinese restaurant is incredibly tender, and how it''s just never as good at home? It''s because the chicken breast is tenderised, a method called "velveting chicken". Use this for the juiciest chicken breast you''ll ever have in stir fries and noodles! SCALE recipe - click on servings and slide.', 'https://www.recipetineats.com/tachyon/2019/03/Tenderise-velvet-chicken-cover-photo-square.jpg', 5, 0, 5, 3, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.019, "unit": "tub of 200g"}}]', '[{"ingredients":["250 g / 8 oz chicken breast slices OR bite size pieces (not whole pieces, Note 1)","3/4 tsp baking soda (bi-carb/bi-carbonate)"]}]', '[{"description":"Place chicken in a bowl and sprinkle baking soda all over the surface.","images":[],"step":1},{"description":"Toss with fingers to coat as evenly as possible.","images":[],"step":2},{"description":"Refrigerate 20 minutes for slices, 30 minutes for bite size pieces.","images":[],"step":3},{"description":"Rinse well in colander to remove baking soda.","images":[],"step":4},{"description":"Shake off then pat away excess water (doesn''t need to be 100% dry).","images":[],"step":5},{"title":"Use as directed in chosen recipe","description":"stir fries and noodles (see in post for suggested recipes). Can be marinated, cooked on the stove, deep fried, simmered in broth.","images":[],"step":6}]', '[]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["American Chinese"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","good-to-know","stir-fries","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4fe0f880b8cf', 'en', 'US', 'How to tenderise beef (velveting beef)', 'Chinese restaurants tenderise economical cuts of beef so they are tender and juicy in stir fries. It''s also done for chicken. There''s a few methods - this baking soda way is the easiest, fastest and highly effective. Though I''m sharing this with beef stir fries in mind, don''t just limit yourself to Asian food. This beef can be used for any recipe calling for strips of beef to be cooked quickly, like Beef Stroganoff. Do not use this method for whole steaks (read Note 4).', 'https://www.recipetineats.com/tachyon/2015/03/How-to-Tenderise-Beef-Chinese-Method.jpg', 25, 0, 25, 2, '[{"id": "ing_beef", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.019, "unit": "tub of 200g"}}]', '[{"ingredients":["250 g / 8 oz stewing beef or other economical beef cuts (Note 1)","3/4 tsp baking soda / bi-carbonate soda (Note 2)"]}]', '[{"description":"Slice beef thinly against the grain. (Note 3)","images":[],"step":1},{"description":"Place in a bowl. Sprinkle over baking soda, toss with fingers to coat evenly.","images":[],"step":2},{"description":"Refrigerate for 30 to 40 minutes. (See Note 1 for different cuts)","duration":35,"images":[],"step":3},{"description":"Rinse beef well with tap water. Shake off excess water, then use paper towels to blot away excess water (doesn''t need to be 100% dry).","images":[],"step":4},{"description":"Proceed with recipe of choice. Beef can be marinated or seasoned before cooking, stir fried or deep fried, and it will be soft and tender, \"velvet\" like. Use for Stir Fries, Stir Fried Noodles, Beef Stroganoff and any other recipe calling for quick-cooked beef strips.","images":[],"step":5}]', '[]', '["gluten_free","high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["American Chinese","Chinese"],"categories":["asian-recipes","asian-takeout","beef-recipes","chinese-recipes","good-to-know","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2d254514e6f2', 'en', 'US', 'Egg Foo Young (Chinese omelette)', 'Recipe video above. This is how the Chinese do omelettes! Egg Foo Young was created as a recipe to use up leftovers, so make this your own using what you have - see Notes for the formula. Otherwise, use EITHER the prawn/shrimp or pork filling. Makes 4 small omelettes, serves 2 as meal with rice, or 4 as part of a banquet.', 'https://www.recipetineats.com/tachyon/2018/07/Egg-Foo-Yung-5.jpg', 10, 15, 25, 4, '[{"id": "ing_flour", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 6.0, "unit": "carton of 12"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 4.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_one_filling_of_choice_below", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_shrimp", "quantity": {"value": 100.0, "unit": "kg"}}, {"id": "ing_pork", "quantity": {"value": 0.11, "unit": "kg"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 4.0, "unit": "bunch"}}]', '[{"ingredients":["4 tsp cornflour / corn starch","1 1/2 tbsp light soy sauce (, or all purpose (Note 2))","2 tsp Oyster Sauce","1 tbsp Chinese Cooking Wine (shaoxing wine) OR Mirin (Note 3)","1/2 tsp sesame oil","1 cup / 250 ml water","Dash of white pepper"],"purpose":"Sauce (Note 1 for Charlie option):"},{"ingredients":["6 eggs","2 cups bean sprouts (just eyeball it)","4 shallots/green onions (, white part only, sliced)","Salt and white pepper","2 tbsp vegetable oil","1 tsp sesame oil","1 garlic clove (, finely chopped)","ONE Filling of Choice, below (Prawn or Pork)"],"purpose":"Omelette:"},{"ingredients":["100 - 120g/3.5 - 4 oz chopped raw small prawns/shrimp (, peeled and deveined (Note 4))"],"purpose":"Option 1: For Prawn /Shrimp Egg Foo Young"},{"ingredients":["100 - 120g/3.5 - 4 oz ground/mince pork (or chicken, turkey, beef or veal)","1/2 tsp EACH soy sauce and Oyster Sauce","1/4 tsp sugar","Dash of sesame oil"],"purpose":"Option 2: For Pork Egg Foo Young :"},{"ingredients":["Sesame seeds, sliced green onion"],"purpose":"Garnish (optional):"}]', '[{"description":"Mix cornflour and soy sauce. Then add remaining ingredients.","images":[],"step":1},{"description":"Pour into a saucepan over medium heat. Bring to simmer, stirring constantly. Simmer for 1 minute until sauce thickens to thin syrup consistency. Remove from stove, set aside.","duration":1,"images":[],"step":2},{"title":"MICROWAVE option","description":"Microwave on high for 1 1/2 minutes. Stir very well, microwave for another 1 1/2 minutes until thickened. Mix well again.","images":[],"step":3},{"description":"Place pork in a bowl, add remaining ingredients. Use fork to mix through.","images":[],"step":4},{"description":"Whisk eggs in a bowl.","images":[],"step":5},{"description":"Add beansprouts, green onions, pork or prawns, salt and pepper. If using pork, crumble the raw pork in with fingers (see video). Mix through.","images":[],"step":6},{"description":"Heat 1/2 tbsp vegetable oil and drizzle of sesame oil in a non stick skillet over medium heat. Add a bit of garlic and quickly saute (10 seconds) and push into centre of skillet.","images":[],"step":7},{"description":"Ladle in 1/4 of batter. Use spatular to push edges in to form a round(ish) shape.","images":[],"step":8},{"description":"Cook until the underside is light golden (about 1 1/2 minutes) then flip and cook the other side for 1 minute. The raw meat will cook through in this time. Repeat with remaining egg to make 4 omelettes (use 2 pans if you can!).","duration":1,"images":[],"step":9},{"description":"Slide omelette onto plate. Pour over sauce. Sprinkle with sesame seeds and green onions, if using.","images":[],"step":10},{"description":"Serve with a side of rice and steamed vegetables of choice. Double the sauce if you want enough to pour over the rice and veggies! (Click on Servings to scale recipe up).","images":[],"step":11}]', '["egg","gluten","sesame","shellfish","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["American Chinese"],"categories":["asian-recipes","chinese-recipes","dinner-tonight","egg-recipes","prawns-shrimp","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0a70c1e4ca66', 'en', 'US', 'Homemade Thai Green Curry Paste', 'Recipe video above. Usually, the main reason to make homemade curry paste is because you just can''t get the same intense, fresh flavour in a jar. And while that holds true for green curry paste, the other very big advantage is that you can control the spiciness without compromising flavour or the signature green colour.', 'https://www.recipetineats.com/tachyon/2019/02/Homemade-Thai-Green-Curry-Paste_3.jpg', 15, 0, 15, 5, '[{"id": "ing_cayenne_pepper", "quantity": {"value": 0.1, "unit": "jar of 40g"}}, {"id": "ing_chilli", "quantity": {"value": 6.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_lemongrass", "quantity": {"value": 40.0, "unit": "bunch"}}, {"id": "ing_galangal", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 8.333, "unit": "pack of 3 heads"}}, {"id": "ing_shrimp", "quantity": {"value": 0.013, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.08, "unit": "jar of 50g"}}, {"id": "ing_turmeric", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}]', '[{"ingredients":["4 green cayenne pepper chilis (, deseeded and chopped (Note 1))","6 Thai green chilis (, chopped (Note 1))","2 red shallots / eschallots (, chopped)","2 lemongrass stems (, trimmed and finely chopped (about 2.5 - 3 tbsp) (Note 2))","2 tbsp galangal (, grated (Note 3))","5 cloves garlic (, chopped)","2.5 tsp dried shrimp paste (Belacan) (Note 4)","2 tsp lime zest (, grated)","1 tsp ground coriander","1 tsp ground cumin","1/4 tsp white pepper","1/4 tsp turmeric","2 tbsp chopped coriander/cilantro root and stem (Note 5)","1/4 cup coriander / cilantro leaves (, loosely packed)","2 - 3 tbsp water (, as needed)"]}]', '[{"description":"Combine all ingredients except water in a powerful blender or food processor. I use my Vitamix because it makes the paste smoother.","images":[],"step":1},{"description":"Blend to a fine paste, scraping down the sides as you go. Add the water as required to help it blend (you may not need any as the herbs and chilis have moisture).","images":[],"step":2},{"description":"Use to make Thai Green Curry!","images":[],"step":3},{"description":"Best to use immediately. Otherwise, refrigerate for up to 2 days, or freeze for 1 month.","images":[],"step":4}]', '["shellfish"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","cuisines","curry-recipes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1b144c63090f', 'en', 'US', 'Chinese Crispy Pork Belly', 'Recipe video above. This is Chinese pork belly, just like you get from the Chinese BBQ meat shops! The best crackling in the world, with the signature bubbles, super crispy and golden. If pricking the skin is too daunting for you, use the Foolproof Easy Method (Note 7)', 'https://www.recipetineats.com/tachyon/2017/01/Crispy-Chinese-Pork-Belly-1.jpg', 20, 90, 110, 8, '[{"id": "ing_pork", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}]', '[{"ingredients":["1 pork belly, skin on (800 - 1.2kg / 1.6 - 2.4 lb) (Note 1)","1 1/2 tbsp Chinese cooking wine (Shaoxing wine) (Note 2)","1 tsp Chinese five spice powder (Note 3)","1 tsp white pepper (sub black pepper)","1/2 tsp salt","1 tbsp white vinegar (helps conduct heat evenly)","200 g / 7 oz rock salt (Note 4)"]}]', '[{"description":"Prepare Pork Belly","images":[],"step":1},{"description":"Use an ice pick, sharp metal skewer or another tool to prick tons and tons of holes in the skin. Avoid piercing int o the fat as best you can, and really ensure you do not pierce the flesh (Note 5)","images":[],"step":2},{"description":"Turn the pork belly upside down. Rub the flesh (not skin) with Chinese cooking wine, dribbling it on gradually. Sprinkle over five spice powder, salt and pepper. Rub all over flesh, including sides (not on skin).","images":[],"step":3},{"description":"Turn skin side up and place in a container. Dab skin dry with paper towels. Refrigerate uncovered for 12 hours (max 24 hrs, min 3 hrs).","images":[],"step":4},{"description":"Cook:","images":[],"step":5},{"description":"Preheat oven to 180C/350F (all oven types).","images":[],"step":6},{"description":"Remove pork from fridge. Place onto a large sheet of foil. Fold up sides of foil around the pork to enclose it snugly (see photos in post or video) with a 1.5cm / 2/5\" rim above the pork skin (to hold salt in).","images":[],"step":7},{"description":"Transfer pork to baking tray. Dab skin with paper towels.","images":[],"step":8},{"description":"Brush skin with vinegar.","images":[],"step":9},{"description":"Spread rock salt on the skin (the foil edges will stop it from falling down the sides).","images":[],"step":10},{"description":"Roast for 60 minutes.","duration":60,"images":[],"step":11},{"description":"Remove pork from oven and transfer onto work surface.","images":[],"step":12},{"description":"Switch to grill/broiler on medium high. Move shelf so it is at least 25cm/10\" from the heat source.","images":[],"step":13},{"description":"Fold down foil and scrape all the salt off the top and sides. Return pork only (i.e. discard foil) to baking tray.","images":[],"step":14},{"title":"Place under grill/broiler for 20","description":"25 minutes, rotating tray once, until skin is golden, crispy and puffed. (Note 6)","duration":22.5,"images":[],"step":15},{"description":"To Serve","images":[],"step":16},{"title":"Remove pork onto cutting board. Slice into 1","description":"1.5cm / 2/5 - 3/5\" thick slices, then into smaller slices like pictured in post.","images":[],"step":17},{"title":"Serve with ordinary yellow mustard","description":"or Hot English Mustard if you like spicy like me! Not Dijon, just ordinary American or other yellow mustard (yes really!). Sometimes it is served with white sugar on the side too. Add some fresh raw vegetables (I use cucumber and radish).","images":[],"step":18}]', '[]', '["gluten_free","high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dietary","gluten-free-recipes","iconic-dishes","main-dishes","modern-asian","pork-recipes","roasts","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_de3df7ab583a', 'en', 'US', 'Chinese Cashew Chicken', 'Recipe video above. The soft, creamy crunch of cashews is a perfect addition to this saucy chicken stir fry! Truly stacks up to your favourite take out - read the glowing reviews! If using breast, consider tenderising it the Chinese way ("Velveting Chicken")', 'https://www.recipetineats.com/tachyon/2015/10/Cashew-Chicken_6.jpg', 15, 6, 21, 4, '[{"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.09, "unit": "L"}}, {"id": "ing_roasted_cashews", "quantity": {"value": 112.5, "unit": "jar"}}]', '[{"ingredients":["1 tbsp cornstarch / cornflour","3 tbsp soy sauce (, all purpose or light (Note 1))","1 1/2 tbsp Chinese cooking wine or Mirin (Note 2)","3 tbsp oyster sauce","2 tsp sesame oil","Dash of white pepper (sub black)"],"purpose":"Sauce"},{"ingredients":["500g / 1 lb chicken thigh (, skinless boneless, cut into 2.5cm/1\" pieces (Note 3))","2 tbsp peanut oil (or vegetable oil)","2 garlic cloves (, minced)","1/2 onion (, chopped into 1.75 cm / 3/4\" pieces(yellow, brown or white))","1 green capsicum / bell pepper (, chopped into 2 cm / 0.8\" pieces)","6 tbsp water","3/4 cup roasted cashews (, unsalted)"],"purpose":"Stir Fry"}]', '[{"title":"Sauce","description":"Mix cornflour and soy sauce until there''s no lumps. Then add remaining Sauce ingredients and mix.","images":[],"step":1},{"title":"Marinate","description":"Transfer 2 tbsp Sauce to chicken, mix to coat. Set aside for 10 minutes+.","duration":10,"images":[],"step":2},{"title":"Cook","description":"Heat oil over high heat in a wok or heavy based skillet. Add the garlic and onion, cook for 1 minute.","duration":1,"images":[],"step":3},{"description":"Add chicken and cook for 2 minutes. Add capsicum and cook for 1 minute.","duration":2,"images":[],"step":4},{"description":"Add Sauce and water. Bring to simmer and cook, stirring, for 1 minute or until Sauce thickens.","duration":1,"images":[],"step":5},{"description":"Stir through cashews, remove from stove. Serve immediately with rice - or for a low carb, low cal option, try Cauliflower Rice!","images":[],"step":6}]', '["gluten","peanuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3da0bdd640da', 'en', 'US', 'Chicken Vegetable Ramen Noodles', 'Recipe video above. A great quick Asian ramen noodle recipe that''s jam packed with a surprising amount of vegetables! Caramelise the chicken well - makes all the difference. Switch veg as desired. Also see the ground beef / mince version - Asian Beef Ramen Noodles.', 'https://www.recipetineats.com/tachyon/2019/01/Chicken-Ramen-Noodles_4.jpg', 10, 8, 18, 3, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.004, "unit": "pack of 500g"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cabbage", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 packets ramen or other instant noodles (, discard seasoning (Note 1))","1 tbsp oil","2 garlic cloves (, minced)","1/2 onion (, sliced)","200g / 7oz chicken thighs, cut into bite size pieces (Note 2)","1 1/4 cups (315 ml) water, plus more as needed","1 carrot (, cut into matchsticks)","1 small red capsicum / bell pepper (, sliced )","2 cups cabbage (, finely sliced (any type))"]},{"ingredients":["1 tbsp dark soy sauce (Note 3)","1 tbsp Oyster sauce (or Hoisin, Note 4)","2 tsp Hoisin sauce (or more Oyster sauce)","1 tbsp Mirin (Note 5)"],"purpose":"Sauce:"},{"ingredients":["Finely sliced green onion / shallots"],"purpose":"Garnishes (optional):"}]', '[{"description":"Mix Sauce.","images":[],"step":1},{"description":"Heat oil in a large skillet over high heat. Add onion and garlic, cook for 1 1/2 minutes until starting to go golden.","images":[],"step":2},{"description":"Add chicken and cook just until the outside mostly changes from pink to white.","images":[],"step":3},{"description":"Add Sauce and cook for 1 minute until chicken is quite caramelised.","duration":1,"images":[],"step":4},{"description":"Add carrot and capsicum, cook for 1 minute (chicken should now be nicely caramelised, see video).","duration":1,"images":[],"step":5},{"description":"Push chicken and veg to the side to make enough space for the noodles. Add water, place noodles in water.","images":[],"step":6},{"description":"When the water starts simmering on the edges, leave noodles for 45 seconds then turn.","duration":0.75,"images":[],"step":7},{"description":"Leave for 30 seconds, then untangle the noodles, then toss through the chicken and veg.","duration":0.5,"images":[],"step":8},{"description":"Add cabbage, toss for 1 minute until sauce reduces to coat the noodles and the noodles are cooked. (Note 6)","duration":1,"images":[],"step":9},{"description":"Serve immediately, garnished with green onions.","images":[],"step":10}]', '["gluten","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","emergency-recipes","main-dishes","mains","noodles","one-pot-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_037ee287ff80', 'en', 'US', 'Thai Coconut Soup', 'Recipe video above. This amazing quick & easy Thai Coconut Soup is made from scratch!! Tastes like a Thai coconut curry, a cross between Tom Yum and Laksa soups. This recipe is all about the soup broth, so put whatever you want into the soup! This is the noodle soup version of this Poached Salmon in Coconut Lime Sauce.', 'https://www.recipetineats.com/tachyon/2018/10/Coconut-Noodle-Soup_3.jpg', 8, 12, 20, 2, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_shrimp", "quantity": {"value": 10.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.2, "unit": "jar of 50g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_lime", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp vegetable oil","10 prawns/shrimp (, peeled and deveined (Note 1))","2 garlic cloves (, finely grated)","2 tsp ginger (, finely grated)","1 lemongrass (, peeled, finely grated (Note 2))","1 tbsp brown sugar","1 1/2 tbsp fish sauce (or soy sauce)","2 tsp curry powder (Note 3)","1 tsp coriander powder","2 tsp chilli garlic paste or other chilli paste (, adjust to taste (Note 4))","400 g/14oz coconut milk (Note 5)","2 cups /500ml chicken broth (or vegetable)","2 tsp lime zest (1 lime)","200 g / 7 oz fresh egg noodles, (prepared per packet (other noodles Note 6))","Big handful bean sprouts"]},{"ingredients":["Lime wedges","Fresh coriander/cilantro leaves","Sliced red onion (or sliced green onion), Fried Asian shallots (Note 7), sliced red chilli, more chilli paste (optional)"],"purpose":"Toppings / for serving:"}]', '[{"description":"Heat oil in a large saucepan over high heat. Add prawns and sear both sides until light golden (doesn''t need to cook inside). Remove onto plate.","images":[],"step":1},{"description":"Turn heat down to medium. If pot is looking dry, add a touch of extra oil.","images":[],"step":2},{"description":"Add garlic, ginger and lemongrass. Saute for 20 seconds until garlic is golden.","duration":0.3333333333333333,"images":[],"step":3},{"description":"Add sugar and fish sauce. Stir and cook for 30 seconds - it should look like caramel.","duration":0.5,"images":[],"step":4},{"description":"Add chilli paste, coriander and curry powder. Stir and cook for 30 seconds.","duration":0.5,"images":[],"step":5},{"description":"Add chicken broth and coconut milk. Stir and bring to simmer.","images":[],"step":6},{"description":"Simmer for 2 minutes, then add lime zest and return prawns into broth.","duration":2,"images":[],"step":7},{"description":"Cook for 2 minutes just to reheat and finish cooking the prawns.","duration":2,"images":[],"step":8},{"description":"Place noodles in bowl. Ladle over soup.","images":[],"step":9},{"description":"Top with bean sprouts and coriander, plus toppings of choice (chilli, red onion, Asian fried shallots).","images":[],"step":10},{"description":"Squeeze over lime juice to taste. Slurp and be happy!","images":[],"step":11}]', '["egg","fish","gluten","shellfish","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian","Thai"],"categories":["asian-recipes","asian-soups","cuisines","dinner-tonight","main-dishes","prawns-shrimp","quick-and-easy","soup-recipes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c22559ce5ce4', 'en', 'US', 'Kung Pao Chicken', 'Recipe video above. Kung Pao chicken - done right! The flavour of this sauce is very similar to proper restaurant versions, with a great balance of savoury-sweet and sour with the numbing tingle from Sichuan pepper. Use whole Sichuan peppercorns if you have them, otherwise ground is fine (which is what I use).', 'https://www.recipetineats.com/tachyon/2018/09/Kung-Pao-Chicken.jpg', 15, 10, 25, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 2.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 6.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_whole_peanuts", "quantity": {"value": 112.5, "unit": "jar"}}]', '[{"ingredients":["1 lb / 500g chicken thigh (, cut into bite size pieces)"],"purpose":"Chicken"},{"ingredients":["2 tsp cornflour / cornstarch","1 tbsp light soy sauce (Note 2)","1.5 tbsp dark soy sauce (Note 3)","2 tbsp Chinese black vinegar (Note 4)","1 tbsp Chinese cooking wine (Note 5)","3 tbsp sugar (, any)","1/2 tsp sesame oil","1/3 cup water"],"purpose":"Sauce"},{"ingredients":["2 tbsp peanut oil (or other cooking oil)","2 garlic cloves (, minced)","1 tsp ginger (, finely chopped)","6 - 10 dried chillies (adjust to taste), cut into 2cm/ 3/4\" pieces, most seeds discarded (Note 7)","3 green onions (, cut into 2cm/ 3/4\" pieces, white parts separated from green)","1.5 tsp ground sichuan peppercorns (, adjust to taste (Note 6))","3/4 cup whole peanuts (or 1/2 cup halved) (, roasted unsalted)"],"purpose":"Stir Fry"}]', '[{"description":"Sauce & Marinade Chicken:","images":[],"step":1},{"description":"Mix cornflour and soy sauce in a small bowl until cornflour is dissolved. Then mix in remaining Sauce ingredients EXCEPT water.","images":[],"step":2},{"description":"Pour 1.5 tbsp Sauce over chicken. Toss to coat, set aside for 10 - 20 minutes.","duration":15,"images":[],"step":3},{"description":"Add water into remaining Sauce.","images":[],"step":4},{"description":"Heat oil in wok over high heat. Add garlic, ginger and chillies. Cook for 30 seconds or until fragrant.","duration":0.5,"images":[],"step":5},{"description":"Add chicken, cook until it turns white, then add the white part of the green onions. Cook until chicken is cooked through - about 2 minutes.","images":[],"step":6},{"description":"Add Sauce and Sichuan pepper. Bring to simmer, mixing constantly, until almost all the sauce reduces to a thick syrup.","images":[],"step":7},{"description":"Just before the end, mix through peanuts and green part of the green onions. Also check spiciness - add more Sichuan pepper if you can handle the heat!","images":[],"step":8},{"title":"Serve immediately with rice","description":"or for a low carb, low cal option, try Cauliflower Rice!","images":[],"step":9}]', '["gluten","peanuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","dinner-tonight","main-dishes","modern-asian","most-popular","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e49ada168e82', 'en', 'US', 'One Pot Chinese Chicken and Rice', 'Recipe video above. It''s like fried rice and Chinese chicken made in one pot! If you can''t find Chinese broccoli, see notes for how to make with other vegetable options. A terrific quick and easy dinner!', 'https://www.recipetineats.com/tachyon/2018/09/One-Pot-Chinese-Chicken-and-Rice_3.jpg', 10, 20, 30, 4, '[{"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 tbsp oil","2 garlic cloves (, minced)","1 tsp ginger (, grated)","1 onion (, finely chopped)","500g (1 lb) chicken thighs (, skinless boneless, halved (Note 1))","1 big bunch Chinese Broccoli with thick stems (Note 2)"]},{"ingredients":["1 cup (180g) uncooked white rice ( (Note 3))","1 1/2 cups (375 ml) chicken broth (, low salt)"],"purpose":"Rice:"},{"ingredients":["2 cloves garlic (, small, chopped)","2 tbsp Chinese cooking wine (or Mirin (Note 4))","3 tbsp oyster sauce (or sub with Hoisin)","1 1/2 tbsp dark soy sauce (Note 5)","1/4 tsp white pepper (or black)"],"purpose":"Sauce:"},{"ingredients":["green onion (, sliced)","Sesame seeds"],"purpose":"Garnish:"}]', '[{"description":"Mix Sauce in a large bowl. Add chicken and set aside to marinate for 10 minutes to overnight.","duration":10,"images":[],"step":1},{"description":"Cut Chinese broccoli stems cut into 2.5 cm/1\" pieces, leafy part 5cm/2.5cm pieces.","images":[],"step":2},{"description":"Heat oil in a large pot over medium high heat. Remove chicken from marinade, shaking off excess marinade - RESERVE marinade!","images":[],"step":3},{"title":"Cook both sides until golden","description":"about 90 seconds on each side, don''t let them burn! Remove chicken onto plate.","images":[],"step":4},{"description":"Add a touch of oil if pot is dry. Add onion, garlic and ginger, cook for 2 minutes until tinged with gold.","duration":2,"images":[],"step":5},{"description":"Add rice, stir to coat grains in oil. Add broth, reserved Marinade and Chinese broccoli stems. Stir.","images":[],"step":6},{"description":"Place chicken across the top, pour in juices pooled on plate. Cover, bring to simmer then lower heat to medium.","images":[],"step":7},{"description":"Cook for 12 -15 minutes or until liquid is absorbed (tilt pot to check).","duration":13.5,"images":[],"step":8},{"description":"Remove from heat. Working quickly, scatter Chinese broccoli leaves across surface, clamp lid back on.","images":[],"step":9},{"description":"Rest for 10 minutes. Remove lid, toss rice and serve, garnished with sesame seeds and green onions. A dollop of your favourite chilli paste wouldn''t go astray either!","duration":10,"images":[],"step":10}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","chicken","chicken-breast-recipes","chicken-recipes","chinese-recipes","dinner-tonight","main-dishes","mains","one-pot-recipes","quick-and-easy","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c69c2adb2b4d', 'en', 'US', 'Wonton Soup', 'Recipe VIDEO above. Homemade wontons are amazing! No fillers, just real ingredients in the filling. Terrific standby freezer meal!', 'https://www.recipetineats.com/tachyon/2016/09/Wontons_4.jpg', 20, 15, 35, 50, '[{"id": "ing_wonton_wrappers", "quantity": {"value": 50.0, "unit": "unit"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_shrimp", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_bok_choy", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 40.0, "unit": "pack of 500g"}}]', '[{"ingredients":["50 - 60 wonton wrappers (Note 1)"]},{"ingredients":["200 g / 7 oz lean pork mince (ground pork)","200 g / 7 oz peeled prawns / shrimp (, roughly chopped)","1 tbsp ginger (, finely grated (1.5\" / 3cm piece))","2 shallots / green onions (, finely chopped (5 tbsp))","1 tbsp light soy sauce (Note 2)","2 tbsp Chinese cooking wine (Shaoxing wine) (Note 3)","1/2 tsp salt","2 tbsp sesame oil, toasted (Note 4)"],"purpose":"Wonton Filling"},{"ingredients":["3 cups / 750 ml chicken broth (Note 5)","2 garlic cloves (, smashed (6))","⅓\" / 1 cm piece of ginger (, sliced (optional, but highly recommended))","1½ tbsp light soy sauce (Note 2)","2 tsp sugar (any)","1½ tbsp chinese cooking wine (Note 3)","¼ - ½ tsp sesame oil"],"purpose":"Broth (for 2 servings)"},{"ingredients":["Shallots / scallions (, finely chopped)","Bok choy (, quartered, or Chinese broccoli cut into 10cm /4\" lengths (optional))","40 - 50 g / 1.5 - 1.75 oz dried egg noodles per person (, (optional) (8))"],"purpose":"To Serve"}]', '[{"description":"Place Filling ingredients in a bowl. Use a potato masher to mash until fairly smooth - about 20 mashes. Don''t turn the prawn into a complete paste, small chunks are good.","images":[],"step":1},{"description":"Wrapping (See photos and video):","images":[],"step":2},{"description":"Use My Way (better Wonton Soup experience!) or the Asian Grocery Store Way (easier to pack for freezing).","images":[],"step":3},{"description":"Lay Wontons on work surface. Use 2 teaspoons to put the Filling on the wontons. Work in batches of 5 if starting out, up to 15 or 20 if confident. Brush 2 edges with water. Fold to seal, pressing out air. Brush water on one corner and bring corners together, pressing to seal.","images":[],"step":4},{"description":"Place wrapped wontons into a container with a lid as you work (so they don''t dry out).","images":[],"step":5},{"description":"Cooking/Freezing:","images":[],"step":6},{"title":"To cook","description":"bring a large pot of water to boil. Place wontons in water and cook for 4 minutes or until they float. Remove with slotted spoon straight into serving bowls. Ladle over broth.","duration":4,"images":[],"step":7},{"title":"To freeze","description":"Freeze uncooked in airtight containers. Cook from frozen for 6 to 8 minutes. IMPORTANT: Do not freeze if you made this with defrosted frozen prawns. (Note 11)","duration":7,"images":[],"step":8},{"description":"Place Broth ingredients in a saucepan over high heat. Add white ends of scallions/shallots if leftover from Wonton filling.","images":[],"step":9},{"description":"Place lid on, bring to simmer then reduce to medium high and simmer for 5 - 10 minutes to allow the flavours to infuse. Pick garlic and ginger out before using.","duration":7.5,"images":[],"step":10},{"description":"If using vegetables, blanch in the soup broth and place in serving bowl.","images":[],"step":11},{"description":"Prepare noodles according to packet directions (if using noodles). Place in serving bowl with cooked wontons and blanched vegetables.","images":[],"step":12},{"description":"Ladle over soup. Serve!","images":[],"step":13}]', '["egg","gluten","sesame","shellfish","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-soups","asian-takeout","chinese-recipes","dietary","dumplings","iconic-dishes","low-calorie-recipes","main-dishes","most-popular","noodles","soup-recipes","yum-cha-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2ae7b968998d', 'en', 'US', 'Poached Salmon in Coconut Lime Sauce', 'Recipe video above. Poached Salmon in a coconut lime sauce that tastes like a Thai coconut curry - except it''s super quick and easy to make! Even though the salmon is poached, it''s well worth searing lightly to brown for the extra flavour on both the salmon and in the sauce.', 'https://www.recipetineats.com/tachyon/2018/09/Poached-Salmon-in-Coconut-Lime-Sauce_2.jpg', 10, 15, 25, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_lime", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_steamed_asian_greens", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["4 salmon fillets (, 180g/6oz each preferably skinless (Note 1))","Salt and pepper","2 tbsp oil (, separated)","2 garlic cloves (, finely grated)","2 tsp ginger (, finely grated)","1 lemongrass (, peeled, finely grated (Note 2))","1 tbsp brown sugar","1 tsp chilli garlic paste (or other chilli paste, adjust to taste (Note 3))","400 g/14oz coconut milk (Note 2)","1 tbsp fish sauce (or soy sauce)","2 tsp lime zest (1 lime)","Lime juice (, to taste)"]},{"ingredients":["Fresh coriander/cilantro leaves (, finely chopped (recommended))","Finely sliced large red chillies (optional)","Vermicelli noodles OR (, soaked per packet, or rice)","Steamed jasmine rice","Steamed Asian greens"],"purpose":"Garnish/serving:"}]', '[{"description":"Sprinkle both sides of salmon with salt and pepper.","images":[],"step":1},{"description":"Heat 1 tbsp oil in a non stick pan or well seasoned skillet over medium high heat. Add salmon, skin side up, and sear for just 1 1/2 minutes until golden. Turn salmon and cook the other side just for 1 minute, then remove onto a plate (should still be raw inside).","duration":1,"images":[],"step":2},{"description":"Turn heat down to medium low and allow skillet to cool.","images":[],"step":3},{"description":"Heat remaining 1 tbsp oil. Add garlic, ginger and lemongrass. Cook until garlic is light golden ~ 1 minute.","images":[],"step":4},{"description":"Add sugar and cook for 20 seconds until it becomes a caramel (see video). Then stir in chilli paste.","duration":0.3333333333333333,"images":[],"step":5},{"description":"Add coconut milk and stir, scraping the bottom of the skillet to dissolve any bits stuck on the base into the sauce.","images":[],"step":6},{"description":"Stir in fish sauce, increase heat to medium. Simmer for 2 minutes.","duration":2,"images":[],"step":7},{"description":"Place salmon into the sauce, lower heat and simmer gently for 4 minutes, or until just cooked.","duration":4,"images":[],"step":8},{"description":"Remove salmon, stir in lime zest and juice to taste. Adjust salt to taste with fish sauce.","images":[],"step":9},{"description":"Serve salmon over noodles or rice. Spoon over sauce, garnish with coriander and chili if using.","images":[],"step":10}]', '["fish","gluten","soy"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Thai-ish"],"categories":["asian-recipes","cuisines","dinner-tonight","fish-recipes","quick-and-easy","salmon-recipes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ac4a42795f42', 'en', 'US', 'Massaman Curry', 'Recipe video above. Not the fastest recipe in the world, but worth it! Rich and beautifully fragrant with the signature hint of smokiness, this mild curry is one of the most popular Thai curries ever. While many restaurants tend to tone down the spices and substantially increase the sugar, this recipe is based on authentic versions by Thai food authorities including David Thompson and Sujet Saenkham of Spice I Am. Super easy to adapt to other proteins - see notes! STORE BOUGHT CURRY PASTE version - see bottom of recipe', 'https://www.recipetineats.com/tachyon/2018/08/Massaman-Curry_3.jpg', 30, 120, 150, 4, '[{"id": "ing_lemongrass", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 6.0, "unit": "pack of 100g"}}, {"id": "ing_onion", "quantity": {"value": 4.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 8.333, "unit": "pack of 3 heads"}}, {"id": "ing_galangal", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_water", "quantity": {"value": 4.0, "unit": "L"}}, {"id": "ing_round_clove", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_cumin", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_round_nutmeg", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 0.075, "unit": "bunch"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cinnamon", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_beef", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_cinnamon_quill", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_star_anise", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_tamarind_paste_puree", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_peanuts", "quantity": {"value": 0.113, "unit": "jar"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 lemongrass (Note 1)","6 dried red Asian chillis (not Thai! Note 2)","4 eschallots (, peeled (Note 3))","5 cloves garlic (, unpeeled)","3 cm / 2.25\" galangal piece (, peeled, cut into 3/4 cm / 1/2\" slices (Note 4))","4 - 6 tbsp water"],"purpose":"Spice Paste:"},{"ingredients":["1/2 tsp ground cloves","3/4 tsp cumin","1/8 tsp ground nutmeg","3/4 tsp coriander","1/2 tsp cardamom","1/2 tsp cinnamon"],"purpose":"Spice Paste Dried Spices:"},{"ingredients":["700 g / 1.4lb beef chuck (, cut into 4cm / 2.5\" cubes (Note 5))","500 ml / 2 cups beef broth (, low sodium)","2 bay leaves"],"purpose":"Beef:"},{"ingredients":["1/4 cup / 65 ml vegetable oil","400 ml / 14 oz coconut milk (full fat, 1 can)","1 cinnamon quill","1 star anise","1 tsp tamarind paste/puree (Note 6)","1 tbsp fish sauce","1 tbsp white sugar","2 medium-small potatoes (, peeled and cut into 2.5cm / 1\" pieces)"],"purpose":"Curry Sauce:"},{"ingredients":["3 tbsp peanuts (, roughly chopped)","Finely sliced red chilli (optional)","Asian fried shallots (optional, Note 7)","Steamed jasmine rice"],"purpose":"Garnish & serving:"}]', '[{"description":"Lemongrass (see video):","images":[],"step":1},{"description":"Remove reedy outer layers and trim lemongrass per Note 1.","images":[],"step":2},{"description":"Reserve all the trimmings (for beef). Finely chop the white part (for paste.","images":[],"step":3},{"description":"Place Beef ingredients in a medium saucepan. Liquid should almost cover beef but not completely - if not, add water.","images":[],"step":4},{"description":"Add lemongrass trimmings.","images":[],"step":5},{"description":"Bring to boil over high heat, then reduce heat and simmer gently for 1.5 - 2 hours until beef is fork tender.","images":[],"step":6},{"description":"Remove beef. If there''s much more than 1.5 cups liquid, simmer to reduce. Set liquid aside.","images":[],"step":7},{"description":"Char Aromatics (char = flavour!):","images":[],"step":8},{"description":"Place heavy based skillet over high heat until smoking (no oil).","images":[],"step":9},{"description":"Add eschalot, garlic and galangal in skillet. Get a nice char on them, then remove (~1.5 minutes).","images":[],"step":10},{"description":"Add dried chillies into skillet, char 10 seconds or so on each side until charred, then remove.","images":[],"step":11},{"title":"Once cool enough to handle","description":"Grate galangal. Peel garlic. Break chillies in half, shake out seeds and discard.","images":[],"step":12},{"description":"Spice Paste Dried Spices:","images":[],"step":13},{"description":"Wipe the skillet used above or use a clean one. Heat on medium heat, add Spice Paste Dried Spices. Toast for 30 seconds or until they start to smell fragrant - do not let them burn. Immediately transfer into bowl.","duration":0.5,"images":[],"step":14},{"description":"Place chillies in food processor. (Note 8) Blitz until finely chopped.","images":[],"step":15},{"description":"Add galangal, finely chopped lemongrass, the toasted Spice Paste Dried Spices, and remaining Spice Paste ingredients, starting with 4 tbsp water. Blitz until smooth - add more water if required.","images":[],"step":16},{"description":"Place oil in a pot or large skillet over medium high heat. Add curry paste and cook for 3 minutes until the liquid has cooked out and it''s thick and fragrant.","duration":3,"images":[],"step":17},{"description":"Add coconut milk, stir to incorporate.","images":[],"step":18},{"description":"Add cinnamon, star anise and reserved beef braising liquid. Reduce heat to medium and simmer for 3 minutes.","duration":3,"images":[],"step":19},{"description":"Stir in fish sauce, tamarind and sugar, stir.","images":[],"step":20},{"description":"Add potatoes and cook for 7 minutes or until potatoes are tender, turning as required.","duration":7,"images":[],"step":21},{"description":"Add beef and simmer for 2 minutes or until sauce has reduced and thickened.","duration":2,"images":[],"step":22},{"title":"Adjust","description":"saltiness with fish sauce, sour with tamarind and sweet with sugar. The taste should be sweet, salty and sour, with more emphasis on the sweet and sour notes. Top up with a little water if the curry seems too thick","images":[],"step":23},{"description":"Serve over jasmine rice, garnished with peanuts (essential!) plus optional crispy Asian shallots and fresh chillies.","images":[],"step":24}]', '["fish"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","beef-recipes","cuisines","curry-recipes","iconic-dishes","main-dishes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8c05ae3b1308', 'en', 'US', 'Char Kway Teow', 'Recipe video above. Epic Malaysian street food favourite - made at home! Use the Base Recipe if you''re a capable cook with a powerful gas stove and a good cast iron wok or large heavy based skillet. Otherwise, I recommend using the Easier Method.', 'https://www.recipetineats.com/tachyon/2018/07/Char-Kway-Teow_6.jpg', 15, 5, 20, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_lard", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_shrimp", "quantity": {"value": 10.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_sausages", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 2.5, "unit": "bag of 250g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.1, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.1, "unit": "bottle of 250ml"}}]', '[{"ingredients":["500 g / 1 lb fresh wide rice noodle (Note 1)","2 tbsp lard (, or vegetable oil (Note 2))","2 tbsp vegetable oil (, separated)","10 small prawns/shrimp (, shelled and deveined)","2 garlic cloves (, finely chopped)","1 Chinese sausage / Lup Chong Sausage (, sliced thinly on the diagonal (Note 3))","5 cm / 2\" piece of fried fish cake (, sliced thinly (Note 4))","20 stems garlic chives (, cut into 4 pieces (Note 5))","2 1/2 cups bean sprouts","2 eggs (, whisked)"]},{"ingredients":["5 tsp dark soy sauce (Note 6)","4 tsp light soy (Note 6)","2 tsp oyster sauce (Note 6)","4 tsp kecap manis / sweet soy sauce (Note 6)"],"purpose":"Sauce:"}]', '[{"description":"Mix Sauce together.","images":[],"step":1},{"description":"Do not attempt to pull noodles apart while cold and hard - they break.","images":[],"step":2},{"description":"Place whole packet in microwave, heat on high for 1 1/2 minutes - 2 minutes until warm and pliable, not hot, turning packet over as needed.","images":[],"step":3},{"description":"Handle carefully and measure out 500g/1 lb noodles into a heatproof bowl. Separate noodles stuck together.","images":[],"step":4},{"description":"If noodles become cold and brittle before cooking, cover with cling wrap and microwave for 30 seconds to make warm (not hot, just warm) to reduce breakage.","duration":0.5,"images":[],"step":5},{"description":"Cook using Base Recipe (capable cooks) or Easier Method.","images":[],"step":6},{"title":"Cooking","description":"BASE Recipe:","images":[],"step":7},{"description":"Heat lard and 1 tbsp oil in a wok or very large heavy based skillet over high heat. Swirl around the wok.","images":[],"step":8},{"description":"When it starts smoking, add prawns. Cook for 30 seconds.","duration":0.5,"images":[],"step":9},{"description":"Add garlic, stir for 10 seconds.","duration":0.16666666666666666,"images":[],"step":10},{"description":"Add noodles, then using both hands on the handle, toss 4 times until coated with oil (or gently fold using a spatula + wooden spoon, see video).","images":[],"step":11},{"description":"Add Chinese sausage and fish cake, toss or gently fold 4 times.","images":[],"step":12},{"description":"Add bean sprouts and garlic chives, toss or gently fold 6 times.","images":[],"step":13},{"description":"Push everything to one side, add remaining 1 tbsp oil. Add egg and cook, moving it around until mostly set - about 1 minute. Use wooden spoon to chop it up roughly.","images":[],"step":14},{"description":"Pour Sauce over noodles, then toss to disperse Sauce through the noodles. Pause between tosses to give the noodles a chance to caramelise on the edges.","images":[],"step":15},{"description":"Serve immediately!","images":[],"step":16},{"title":"Cooking","description":"EASIER Method:","images":[],"step":17},{"description":"Heat 1 tbsp oil in a large non stick skillet over high heat.","images":[],"step":18},{"description":"When heated, add shrimp and cook for 1 1/2 minutes until just cooked through, then remove into bowl","images":[],"step":19},{"description":"Add Chinese sausage and fish cake, and cook for 1 minute until sausage is caramelised, then add to bowl.","duration":1,"images":[],"step":20},{"description":"Add 1 tbsp oil then add egg and cook, pushing in the edges to make a thick omelette. Once set, chop it up roughly using a wooden spoon (see video), then add to bowl.","images":[],"step":21},{"description":"Add bean sprouts and cook for about 1 minute until just starting to wilt, then add to bowl.","images":[],"step":22},{"description":"Add lard. Once melted and starting to smoke, add garlic then immediately add noodles. Fold gently 4 times using a spatula + wooden spoon (see video) just to disperse oil through noodles.","images":[],"step":23},{"description":"Tip all the other ingredients back in plus the chives. Fold gently twice, then pour all the Sauce over.","images":[],"step":24},{"description":"Gently toss 4 to 6 times to disperse the sauce, pausing in between to allow the noodles to have a chance to caramelise on the edges a bit.","images":[],"step":25},{"description":"Remove from stove and serve immediately.","images":[],"step":26}]', '["egg","fish","gluten","shellfish","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Malaysian"],"categories":["asian-recipes","asian-takeout","iconic-dishes","noodles","prawns-shrimp"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bbdd82be973f', 'en', 'US', 'San Choy Bow (Chinese Lettuce Wraps)', 'Recipe video above. One of my favourite starters at Chinese restaurants, the ultimate (almost) carb free healthy dish of all time! It all comes down to the Sauce - with a great Sauce, you can change up the filling to your taste. I''ve copied the filling served by Chinese restaurants but feel free to substitute with other vegetables or make it entirely meat free (this is a great recipe to make vegetarian).', 'https://www.recipetineats.com/tachyon/2017/02/Lettuce-Wraps-2.jpg', 15, 5, 20, 3, '[{"id": "ing_cornstarch", "quantity": {"value": 0.016, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_corn", "quantity": {"value": 5.0, "unit": "can of 400g"}}, {"id": "ing_mushroom", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 160.0, "unit": "head"}}, {"id": "ing_peanuts", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 1/4 tsp cornflour / cornstarch","3 tbsp water, (separated)","1 1/2 tbsp light soy sauce (Note 1)","1 tsp dark soy sauce (Note 1)","2 tbsp oyster sauce","1 tsp sesame oil","2 tbsp Chinese cooking wine (or sub Mirin or dry sherry, Note 2)","1 tsp white sugar (can omit)"],"purpose":"Sauce"},{"ingredients":["1 tbsp peanut oil","1 clove large garlic, (minced)","1/2 tsp ginger, (minced)","300g / 10oz pork mince (ground pork) (Note 3)","1/2 onion, (finely chopped)","1 small carrot, (finely chopped)","100g/ 3.5oz canned water chestnuts, (drained and finely chopped (Note 4))","5 baby corn, (canned or fresh, finely chopped (Note 4))","5 mushrooms, (finely chopped(shiitake is best, I used Swiss Brown))"],"purpose":"Filling (Note 6)"},{"ingredients":["8 leaves large or 16 - 20 small lettuce, preferably soft (Note 5)","Crushed peanuts","Finely sliced scallions / shallots"],"purpose":"Serving"}]', '[{"description":"Mix cornflour with 1 tbsp water until lump free. Then add remaining Sauce ingredients and mix.","images":[],"step":1},{"description":"Heat oil in a wok or large skillet over high heat. Add garlic and ginger, give it a quick stir then add onion.","images":[],"step":2},{"description":"Cook for 1 minute then add pork. Cook pork until it turns white.","duration":1,"images":[],"step":3},{"description":"Add all the vegetables. Cook for 2 minutes until the carrot is softened and pork is cooked through.","duration":2,"images":[],"step":4},{"description":"Add Sauce and cook for 1 1/2 minutes or until it thickens and glossy, coating the Filling.","images":[],"step":5},{"description":"Transfer Filling into serving bowl. Lay out lettuce leaves, peanuts and scallions on the side.","images":[],"step":6},{"description":"To serve, spoon some Filling into a lettuce leaf. Top with peanuts and scallions, bundle it up and enjoy!","images":[],"step":7}]', '["gluten","peanuts","sesame","soy"]', '["low_calorie"]', '{"mealType":["snack","dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken-mince-recipes","chicken-recipes","chinese-recipes","dietary","dinner-tonight","low-calorie-recipes","main-dishes","pork-recipes","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_aeeea4463c87', 'en', 'US', 'Chinese dumplings (Potstickers!)', 'Recipe video above. Time to get your dumpling game on! Don''t fret about perfect pleats - if it''s all too hard, just press the seams together without pleating, plenty of Chinese restaurants do this. This recipe has a pork and cabbage filling, which is traditional and common. After a Vegetable filling? Here it is!', 'https://www.recipetineats.com/tachyon/2018/03/Potstickers_6a.jpg', 30, 25, 55, 30, '[{"id": "ing_shiitake_mushrooms", "quantity": {"value": 5.0, "unit": "pack of 150g"}}, {"id": "ing_cabbage", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_wine", "quantity": {"value": 0.01, "unit": "bottle of 750ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.002, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_round_dumpling_wrappers", "quantity": {"value": 30.0, "unit": "unit"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 4.0, "unit": "L"}}]', '[{"ingredients":["5 - 6 dried shiitake mushrooms (Note 1)","1 ½ cups finely chopped Chinese cabbage (Napa cabbage)","½ tsp salt","250 g / 0.5 lb fatty pork mince (20 - 30% fat ideal - Note 2)","¼ cup garlic chives (, finely chopped*)","2 tsp light soy sauce (light or dark soy also ok)","1 1/2 tsp Chinese wine (Note 4)","½ tsp sesame oil*","¼ tsp white pepper (black also ok)","1 garlic clove (, minced)","½ tsp grated fresh ginger*"]},{"ingredients":["30 - 35 round dumpling wrappers (Note 5)","1/2 cup water per batch","4 - 6 tsp vegetable oil"],"purpose":"To cook:"}]', '[{"title":"Shiitake Mushroom","description":"Place the mushrooms in a bowl and pour over plenty of boiled water. Leave for 20 minutes or until rehydrated. Squeeze out excess water, then finely chop.","duration":20,"images":[],"step":1},{"title":"Cabbage","description":"Place cabbage in a bowl with salt. Toss with fingers, then set aside for 15 minutes. Squeeze out excess liquid from cabbage using hands.","duration":15,"images":[],"step":2},{"title":"Filling","description":"Place cabbage, mushrooms and remaining Filling ingredients in a bowl. Mix with your hands until well combined.","images":[],"step":3},{"description":"Make Dumplings (watch video + see photos in post):","images":[],"step":4},{"description":"Peel one wrapper off and place on the palm of your left hand (if right handed). Dip your finger in water and run it along half the edge of the wrapper.","images":[],"step":5},{"description":"Place 1 heaped tablespoon of Filling in the centre. Fold wrapper over, then pleat to seal. Alternatively, just press together with no pleats.","images":[],"step":6},{"description":"Finish so the dumpling is curved slightly, see photos in post, with the pleats on the top.","images":[],"step":7},{"description":"Place on tray. Cover with cling wrap or wet tea towel (important). Repeat with remaining dumplings. Should make 30, if yours are extremely plump you may only make 25.","images":[],"step":8},{"description":"Cooking:","images":[],"step":9},{"description":"Make sure your pan has a lid that fits it half decently (Note 6).","images":[],"step":10},{"description":"Heat 2 tsp oil in a non stick pan over medium high heat. Add dumplings, pressing down firmly to flatten the base onto the pan. Cook around 8 to 10 per batch.","images":[],"step":11},{"description":"When the base is golden brown (check them), add 1/2 cup of water into the pan.","images":[],"step":12},{"description":"Immediately clamp the lid on, then leave for 7 minutes (any less and the pleats won''t be cooked through so if your water dries out, add a bit more).","duration":7,"images":[],"step":13},{"title":"Remove lid","description":"most of the water should be evaporated, the pleats should be cooked through. Leave the pan on the stove until the base dries and the underside of the dumplings are once again crisp.","images":[],"step":14},{"description":"Remove dumplings from pan and transfer to serving plate. Repeat with remaining Dumplings.","images":[],"step":15},{"description":"Serve with Dipping Sauces of choice. (Note 7)","images":[],"step":16}]', '["gluten","sesame","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dumplings","iconic-dishes","pork-recipes","yum-cha-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3d463492b257', 'en', 'US', 'Thai Red Curry with Chicken', 'Recipe VIDEO above. A Thai Red Curry with Chicken is one of the world''s most popular curries! Make this with store bought curry paste (we give it a freshness boost) OR homemade red curry paste (the fresh flavour can''t be beaten!). SPICE Level: Mild to hot BUT if using store bought paste, depends on what brand you use (Note 5).', 'https://www.recipetineats.com/tachyon/2018/02/Thai-Red-Curry-Chicken-1.jpg', 5, 20, 25, 4, '[{"id": "ing_thai_red_curry_paste", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_quantity_homemade_thai_red_curry_paste", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 666.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_lime", "quantity": {"value": 6.0, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_pumpkin", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_green_beans", "quantity": {"value": 120.0, "unit": "pack"}}, {"id": "ing_basil", "quantity": {"value": 12.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["5 - 6 tbsp Thai Red Curry Paste (store bought, Maesri best) (Note 1)","1 quantity homemade Thai Red Curry Paste"],"purpose":"Red Curry Paste – choose ONE:"},{"ingredients":["2 large garlic cloves (, minced)","2 tsp fresh ginger (, finely grated )","1 tbsp lemongrass paste (or finely chopped fresh (Note 3))"],"purpose":"Extras – only for jar curry paste (Note 2)"},{"ingredients":["3 tbsp vegetable oil (or canola or peanut)","1 cup (250 ml) chicken broth/stock (, low sodium)","400 ml / 14 oz coconut milk (full fat!)","6 kaffir lime leaves (Note 4)","1 tbsp sugar (white, brown or palm)","2 tsp fish sauce (, plus more to taste)","350g / 12 oz chicken thighs (boneless and skinless), cut into 0.75 / 1/3\" thick slices (Note 5)","150g / 5 oz pumpkin or butternut squash, ( cut into 1.5cm / 3/5\" cubes (~1 heaped cup))","120g / 4oz green beans (, trimmed and cut into 5cm/2\" pieces)","12 Thai basil leaves (Note 6)"],"purpose":"Thai Red Curry"},{"ingredients":["Fresh red chilli slices (small chilli - spicy, large = less spicy)","Fresh coriander / cilantro leaves","Steamed jasmine rice"],"purpose":"Garnishes (optional) & serving:"}]', '[{"description":"Heat oil in a large heavy based skillet over medium high heat.","images":[],"step":1},{"description":"Add curry paste and Extras (if using jar paste) and cook for about 2 minutes so it \"dries out\" (See video)","images":[],"step":2},{"description":"Add chicken broth and stir to dissolve paste. Simmer rapidly for 3 minutes or until liquid reduces by half.","duration":3,"images":[],"step":3},{"description":"Add coconut milk, lime leaves, sugar and fish sauce. Stir, then add chicken.","images":[],"step":4},{"description":"Spread chicken out, bring to simmer, then turn heat down to medium. Simmer for about 8- 10 minutes or until Sauce reduces, the chicken is cooked and the sauce is almost at the thickness you want.","images":[],"step":5},{"description":"Do a taste test. Add more fish sauce (or even shrimp paste) to add more saltiness, sugar for sweetness.","images":[],"step":6},{"description":"Add pumpkin and beans, stir. Cook for 3 minutes or until pumpkin is just cooked through and Sauce is thickened - see video for Sauce thickness.","duration":3,"images":[],"step":7},{"description":"Remove from heat. Stir through a handful of Thai basil leaves.","images":[],"step":8},{"description":"Serve over jasmine rice, garnished with fresh red chilli slices and fresh coriander/cilantro leaves, if desired.","images":[],"step":9}]', '["fish","peanuts"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","cuisines","curry-recipes","dietary","gluten-free-recipes","iconic-dishes","main-dishes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3001269a9630', 'en', 'US', 'Sesame Crusted Salmon', 'Recipe VIDEO above. Just roll salmon in sesame seeds and bake - you''ll be amazed how well it sticks! Served over soba and Asian greens with a fabulous Asian dressing, this is a great quick salmon recipe.', 'https://www.recipetineats.com/tachyon/2018/02/Sesame-Crusted-Salmon_3.jpg', 5, 15, 20, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.75, "unit": "pack of 100g"}}, {"id": "ing_oil", "quantity": {"value": 20.0, "unit": "bottle"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_es_baby_buk_choi", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}]', '[{"ingredients":["4 x 150-200g / 5-7 oz skinless boneless salmon or trout fillets (Note 1)","Salt and pepper","75g/ 1/2 cup white sesame seeds","4 tsp vegetable or canola oil (or other neutral oil, not olive oil)","Sliced shallots / scallions (, optional garnish)"]},{"ingredients":["250 g / 8 oz dried soba noodles (Note 2)","2 bunches baby buk choi (, or other greens of choice (Note 3))"],"purpose":"Soba and greens:"},{"ingredients":["1 1/2 tbsp soy sauce (, light or ordinary (Note 4))","2 1/2 tbsp vegetable or canola oil (or other neutral oil, not olive)","3 tbsp rice vinegar (Note 2)","1 tbsp Mirin (Note 2)","2 tsp sugar (any, I use white)","2 tsp fresh ginger (, minced)","1 clove garlic (, minced)"],"purpose":"Asian Dressing:"}]', '[{"description":"Take salmon out of fridge 20 minutes before cooking.","images":[],"step":1},{"description":"Preheat oven to 220C/430F (standard) or 200C/390F (fan). Place shelf about 20cm/8\" from the broiler heat source at the top of the oven.","images":[],"step":2},{"description":"Sprinkle both sides of the salmon with salt and pepper.","images":[],"step":3},{"description":"Place sesame in shallow dish. Press salmon into sesame seeds to coat on all sides. Place on tray.","images":[],"step":4},{"description":"Drizzle top with oil.","images":[],"step":5},{"title":"Bake for 10 minutes. Flick to broiler on high","description":"broil / grill for 3 minutes until the top is a bit golden (or bake for 5 minutes, but won''t be as golden). (Note 5)","duration":10,"images":[],"step":6},{"description":"Remove from oven, rest 3 minutes. Serve with soba and greens, garnished with scallions (optional) and drizzled with Dressing.","images":[],"step":7},{"description":"Soba and greens:","images":[],"step":8},{"description":"Bring a large pot of water to the boil.","images":[],"step":9},{"description":"Cook soba per packet directions. Add greens for the last 1 minute of cooking.","images":[],"step":10},{"description":"Drain then divide between bowls.","images":[],"step":11},{"description":"Place ingredients in jar and shake. Set aside for 5 minutes.","duration":5,"images":[],"step":12}]', '["fish","gluten","sesame","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian influence"],"categories":["asian-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_04c12d065cdc', 'en', 'US', 'Thai Chicken Salad', 'Recipe VIDEO above. A chicken salad with a fantastic Thai chilli lime dressing with a great tangy-sweet-salty-spicy balance that South East Asian food is known for. Using Chilli Garlic Sauce is a great way to thicken dressing as well as adding more layers of flavour. Serves 2 as a main, 4 as a side.', 'https://www.recipetineats.com/tachyon/2017/11/Thai-Chicken-Salad-1.jpg', 15, 20, 35, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 180.0, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_chilli", "quantity": {"value": 5.0, "unit": "pack of 100g"}}, {"id": "ing_roasted_cashews", "quantity": {"value": 75.0, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 5.0, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 2.5, "unit": "pack of 3 heads"}}, {"id": "ing_lime", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}]', '[{"ingredients":["180 - 220 g / 6 -7oz chicken breast"]},{"ingredients":["150 g / 5 oz mixed lettuce leaves (or other of choice)","1 cup cherry or grape tomatoes (, halved)","1 small cucumber (, sliced)","1/4 red onion (, finely sliced)","1/2 large red chilli (, deseeded and very finely sliced (Note 1))","1/2 cup roasted cashews (, unsalted preferred)","1/4 cup coriander / cilantro leaves"],"purpose":"Salad:"},{"ingredients":["1 tbsp finely chopped coriander/cilantro stems (see video)","1 1/2 tsp Chilli Garlic Sauce (Note 2)","1 small garlic (, minced)","1 1/2 tbsp fresh lime juice (or rice vinegar)","2 tsp fish sauce (Note 3)","1 tbsp canola oil (or vegetable, grapeseed or other neutral oil)","1 1/2 tsp sugar (any, I use white)"],"purpose":"Thai Chilli Lime Dressing:"}]', '[{"description":"Take the chicken out of the fridge 30 minutes before cooking.","images":[],"step":1},{"description":"Boil water in a saucepan. Add chicken, put the lid on, let the water come back up to a simmer, then remove from stove. Set aside for 20 minutes (even up to 45 min is fine). (Note 4)","duration":20,"images":[],"step":2},{"description":"Remove chicken from water and shred, then cool.","images":[],"step":3},{"description":"Place ingredients in a jar. Shake well. Taste and adjust as required. It should be a balance of tangy / sweet / salty / hint of spice. (Note 5)","images":[],"step":4},{"description":"Place Salad ingredients in a large bowl. Drizzle over most of the Dressing, toss. Serve immediately, drizzled with remaining Dressing.","images":[],"step":5}]', '["fish"]', '["gluten_free"]', '{"mealType":["dinner","lunch"],"cuisine":["Thai"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","cuisines","dietary","dinner-tonight","gluten-free-recipes","low-calorie-recipes","main-dishes","quick-and-easy","salad-recipes-main-course","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_47e0d48a8e4a', 'en', 'US', 'Thai Meatballs', 'Recipe video above. The beautiful, fresh Thai flavour in these meatballs are amazing! Truly like something you''d get at those posh Thai restaurants. These aren''t authentic Thai, as far as I know there really aren''t meatballs in Thai cuisine (at least, not like this, they have them in soups), but all the flavourings in this are real-deal-Thai.', 'https://www.recipetineats.com/tachyon/2017/10/Thai-Meatballs.jpg', 20, 25, 45, 4, '[{"id": "ing_pork_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_lime", "quantity": {"value": 3.0, "unit": "net of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 0.141, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_lime", "quantity": {"value": 3.0, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["500 g / 1 lb pork mince (ground pork, or chicken)","1 tbsp lemongrass paste (or finely chopped fresh) (Note 1)","1 tsp grated ginger","3 cloves garlic (, minced)","3 kaffir lime leaves, stem removed and very finely shredded, optional extra (Note 2)","3 Thai or birds eye chillies (, seeds removed and finely chopped (Note 3))","1/4 cup coriander/cilantro (, leaves and stem finely chopped (Note 4))","1 tsp sugar (any)","1 tbsp fish sauce (can sub with soy sauce if required)","3/4 cup panko breadcrumbs (+ extra 1/4 cup if needed)","1 small egg","Oil spray"],"purpose":"Meatballs:"},{"ingredients":["1/2 cup / 125 ml sweet chilli sauce (, store bought (Note 5))","1 garlic clove (, minced)","2 tbsp lime juice (, plus more to taste)"],"purpose":"Sweet Chilli Dipping Sauce:"},{"ingredients":["Coriander/cilantro leaves (, finely sliced large red chillies)","Steamed jasmine rice"],"purpose":"Optional garnishes & serving:"}]', '[{"description":"Preheat oven to 220C/430F (standard) or 200C/390F (fan / convection).","images":[],"step":1},{"description":"Place a rack on a tray (optional, rack keeps balls slightly rounder).","images":[],"step":2},{"description":"Place Meatball ingredients in a bowl (except oil spray), mix well with your hands. Only use extra breadcrumbs if necessary - sometimes, chicken mince can be quite wet. Scoop up 1 slightly heaped tablespoon and roll into a ball (about 3cm / 1.25\" diameter). (Note 6 for my way)","images":[],"step":3},{"description":"Spray rack well with oil and place the meatballs on the rack.","images":[],"step":4},{"description":"Spray meatballs generously with oil, then bake for 20 - 25 minutes or until a bit browned. They should be beautifully soft - see video!","duration":22.5,"images":[],"step":5},{"description":"Serve warm with Sauce, garnished with coriander and chillies if desired.","images":[],"step":6},{"description":"Place ingredients in a bowl and mix. Set aside for at least 10 minutes before using.","images":[],"step":7}]', '["egg","fish","gluten","soy"]', '[]', '{"mealType":["dinner","snack"],"cuisine":["Thai"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-mince-recipes","chicken-recipes","cuisines","finger-food","meatball-recipes","pork-recipes","super-bowl-party-food","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_20b1481b67eb', 'en', 'US', 'Vietnamese Coconut Caramel Chicken', 'The chicken version of the wildly popular Vietnamese Caramel Pork! It''s saucier and made with coconut milk so it has a gorgeous coconut fragrance. It''s sweet with savoury undertones, looks thoroughly unimpressive while cooking but then magically transforms in the last 5 minutes. Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2017/10/Vietnamese-Coconut-Caramel-Chicken.jpg', 5, 55, 60, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.15, "unit": "bottle of 250ml"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 10.0, "unit": "pack of 100g"}}]', '[{"ingredients":["4 large / 5 small chicken thighs (, bone in skin on (Note 1))","1/2 cup / 80 g brown sugar (, loosely packed)","1 tbsp water","400 g / 14 oz coconut milk (, low fat (1 can) (Note 2))","1 1/2 tbsp fish sauce (Note 3)","2 1/2 tbsp rice vinegar (or cider vinegar)","2 garlic cloves (, minced)","1 eschallot / French onion (, finely sliced (Note 4))","1/4 tsp white pepper (or black)"]},{"ingredients":["1 shallot (, finely sliced (green onion / scallion))","1 large red chilli (, finely sliced)"],"purpose":"Garnishes (optional):"}]', '[{"description":"Place sugar and water in a skillet over medium heat. Stir, then when it bubbles and the sugar is melted (it looks like caramel), add the rest of the ingredients except chicken.","images":[],"step":1},{"description":"Stir, then put the chicken in SKIN SIDE DOWN.","images":[],"step":2},{"description":"Adjust the heat so it is simmering energetically. Not rapidly, not a slow simmer (I use medium high heat on a weak stove, medium on a strong stove).","images":[],"step":3},{"description":"After 25 minutes, turn the chicken.","images":[],"step":4},{"description":"After another 25 minutes, the fat should separate from the sauce and turn a pale brown (see video).","images":[],"step":5},{"description":"Turn chicken so the skin side is down. Move it around so the sauce doesn''t catch on the bottom of the skillet and to brown the skin.","images":[],"step":6},{"description":"Once sauce and skin is brown, remove from heat.","images":[],"step":7},{"description":"Place chicken on serving plates, spoon over some sauce (don''t need much, chicken is infused with flavour + sauce is strong).","images":[],"step":8},{"description":"Garnish with shallots and chilli, if using. Serve with rice.","images":[],"step":9}]', '["fish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e4dad176b9ea', 'en', 'US', 'Vietnamese Caramel Pork', 'Recipe VIDEO above. "Thit Kho To" - Tender pork in a sweet savoury glaze that has quite an intense flavour. Though made using coconut water as the broth, but it doesn''t have a coconut flavour at all! It looks so unimpressive right up until the end when it magically transforms into sticky caramelised pork pieces!', 'https://www.recipetineats.com/tachyon/2017/10/Vietnamese-Caramel-Pork_-4.jpg', 10, 90, 100, 4, '[{"id": "ing_brown_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_pork_shoulder", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1/2 cup / 100g brown sugar, tightly packed","1 tbsp water","1 kg / 2 lb pork shoulder (butt) or boneless skinless pork belly, cut into 3 cm / 1.2\" pieces (Note 1a)","1.5 cups / 375 ml coconut water (Note 1b)","1 eschallot / shallot (, very finely sliced (Note 2))","2 garlic cloves (, minced)","1 1/2 tbsp fish sauce","1/4 tsp white pepper"]},{"ingredients":["Red chilli and finely sliced shallots/green onions"],"purpose":"Garnishes:"}]', '[{"description":"Place sugar and water in a large pot over medium heat. Stir, then when it bubbles and the sugar is melted (it looks like caramel), add the rest of the ingredients.","images":[],"step":1},{"description":"Stir, then adjust the heat so it is simmering fairly energetically. Not rapidly, not a slow simmer (I use medium heat on a weak stove, between medium and low on a strong stove).","images":[],"step":2},{"description":"Simmer for 1.5 hours, uncovered. Stir once or twice while cooking.","images":[],"step":3},{"description":"At around 1.5 hours, when the liquid has reduced down and the pork is tender, (see Note 3 if pork is not yet tender), the fat will separate (see video).","images":[],"step":4},{"description":"Stir and the pork will brown and caramelise in the fat.","images":[],"step":5},{"description":"Once the liquid is all gone and it''s now stuck on the pork pieces, it''s ready.","images":[],"step":6},{"description":"Serve over rice, garnished with fresh chilli and shallots. Simple pickled vegetables are ideal for a side because the fresh acidity pairs well with the rich pork.","images":[],"step":7}]', '["fish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["asian-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","pork-recipes","quick-and-easy","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_44febe8729e9', 'en', 'US', 'Quick Satay Peanut Stir Fry (any protein)', 'VIDEO below. A gem of a recipe given to me by a reader, this is a brilliant QUICK Satay Stir Fry that tastes like Chinese style satay that you get from Chinese restaurants here in Australia. Make this with your choice of protein - great with beef (pictured), chicken, pork, shrimp or tofu. Use shredded shaped vegetables - ideal for this sauce which is not the saucy type.', 'https://www.recipetineats.com/tachyon/2017/07/Quick-Satay-Stir-Fry.jpg', 10, 7, 17, 3, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.06, "unit": "jar of 375g"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_beef", "quantity": {"value": 300.0, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 75.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_peanuts", "quantity": {"value": 0.094, "unit": "jar"}}]', '[{"ingredients":["1 1/2 tbsp fish sauce (Note 1)","1 1/2 tsp sugar","2 tsp cornflour / cornstarch","1 garlic clove (, minced)","1 tsp grated ginger","1 tsp curry powder (any - I use hot!)","1 1/2 tbsp crunchy peanut butter (smooth also ok)","2 tbsp water"],"purpose":"Sauce:"},{"ingredients":["300 - 350 g / 10 - 12 oz beef (, chicken or pork thinly sliced (or peeled prawns/shrimp) (Note 2))","2 tbsp oil","1 garlic (, finely chopped (Note 3))","1 large onion (, sliced)","1 large carrot (, julienned (Note 4))","1 big handful bean sprouts (~1 1/2 cups packed)","1/2 cup finely sliced shallots / green onions (plus more for garnish)","1/4 cup crushed peanuts (, plus more for garnish (optional))"],"purpose":"Stir Fry:"}]', '[{"description":"Mix Sauce ingredients EXCEPT WATER together in a small bowl. Then mix in water (easier to combine).","images":[],"step":1},{"description":"Place beef in a bowl, add 1 tbsp Sauce. Mix, set aside 10 minutes.","images":[],"step":2},{"description":"Heat oil in a wok or large heavy based skillet over high heat. Add garlic and stir until golden (~10 sec) then add onion. Cook for 1 minute.","duration":1,"images":[],"step":3},{"description":"Add beef. Cook for 1 1/2 minutes or until it mostly turns brown (some red spots ok). If using pork, chicken or prawns, cook until almost cooked through.","images":[],"step":4},{"description":"Add carrots, bean sprouts and Sauce. Cook until veggies are wilted.","images":[],"step":5},{"description":"Add peanuts and shallots, stir.","images":[],"step":6},{"description":"Serve immediately with rice or noodles, garnished with extra shallots and peanuts if desired. (For a low carb, low cal option, try Cauliflower Rice!)","images":[],"step":7}]', '["fish","peanuts","shellfish"]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","beef-recipes","chicken-breast-recipes","chicken-recipes","chinese-recipes","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5a26e2bb87e7', 'en', 'US', 'Teriyaki Chicken Meatballs', 'Recipe video above. Soft, plump, juicy meatballs smothered in a homemade Teriyaki sauce! The sauce for this recipe is based my mother''s authentic Teriyaki Chicken recipe. Serve these as a meal or pass them around at a party.', 'https://www.recipetineats.com/tachyon/2017/07/Teriyaki-Chicken-Meatballs.jpg', 20, 15, 35, 4, '[{"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_cooking_sake", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_mirin", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.18, "unit": "L"}}, {"id": "ing_chicken_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_cooking_sake", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 tbsp cornflour / cornstarch","1/4 cup / 65ml soy sauce (, all purpose / ordinary (Note 1))","1/4 cup / 65ml cooking sake (, or sub with Chinese cooking wine or dry sherry (Note 2))","1/4 cup / 65ml Mirin (Note 2)","1 tbsp white sugar (brown also ok)","¾ cup / 180 ml water"],"purpose":"Teriyaki Sauce:"},{"ingredients":["500 g / 1 lb chicken mince (ground chicken) (or pork or turkey)","1 egg (preferably small 50g / 1.4 oz)","1 cup panko breadcrumbs (or ¾ cup normal breadcrumbs)","1 garlic clove (, minced)","1 ½ tsp cooking sake (, or sub with Chinese cooking wine or dry sherry (Note 2))","½ tsp salt"],"purpose":"Meatballs:"},{"ingredients":["1 tbsp oil","Sliced green onions / scallions (, for garnish (optional))","Sesame seeds (, for garnish (optional))"],"purpose":"Cooking:"}]', '[{"description":"Place Meatball ingredients in a bowl.","images":[],"step":1},{"description":"Place cornflour in a bowl with 1 tbsp of the water, then mix until lump free. Then add the soy sauce, sake, mirin and sugar, mix.","images":[],"step":2},{"description":"Add 2 tsp of Teriyaki Sauce into the Meatball bowl.","images":[],"step":3},{"description":"Add remaining water into the Sauce and mix. Set aside.","images":[],"step":4},{"description":"Mix Meatball mixture with your hands. Measure out 1 heaped tablespoon and roll into balls. See Note 3 for tips if mixture is too sticky.","images":[],"step":5},{"description":"Heat oil in a large skillet over medium high heat. Add all the meatballs and cook, rolling to brown all over, for 5 minutes. They will still be a bit raw inside.","duration":5,"images":[],"step":6},{"description":"Turn heat down. Give the Sauce a quick mix then add it into the pan. Bring to a simmer then cook for 2 - 3 minutes or until it thickens into a glossy sauce that coats the meatballs.","duration":2.5,"images":[],"step":7},{"description":"Serve over rice, garnished with green onions and sesame seeds if desired.","images":[],"step":8}]', '["egg","gluten","sesame","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian","Japanese","Western"],"categories":["asian-recipes","chicken-mince-recipes","chicken-recipes","dinner-tonight","main-dishes","meatball-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1769dff5dbb3', 'en', 'US', 'Chinese BBQ Chicken', 'The marinade for this chicken is based on the famous Chinese BBQ Pork (Char Siu), a very popular recipe on my blog! It’s sweet, savoury, sticky, laced with Chinese Five Spice. Add your own touch like ginger and chilli for a kick! The red food colouring is optional – it gives the chicken the reddish tinge that Char Siu is known for. Recipe VIDEO below, MARINATING TIME: 3 - 24 hrs.', 'https://www.recipetineats.com/tachyon/2017/06/Chinese-BBQ-Chicken-2.jpg', 5, 20, 25, 4, '[{"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_honey", "quantity": {"value": 0.045, "unit": "jar of 500g"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_few_drops_red_food_colouring", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_skewers", "quantity": {"value": 10.0, "unit": "pack of 50"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 garlic cloves (, minced)","2 tsp brown sugar","1 1/2 tbsp honey","1 1/2 tbsp hoisin sauce","2 tsp oyster sauce","1 ½ tbsp light soy sauce (or all purpose)","1/2 tsp Chinese five spice powder (Note 1)","1/2 tsp sesame oil (not critical)","Few drops red food colouring (, optional)"],"purpose":"Marinade:"},{"ingredients":["750 g / 1.5lb chicken thigh fillets (, skinless boneless (or breast))","1 tbsp vegetable oil","10 – 12 bamboo skewers (, soaked in water for 1 hour (optional))","Green onions / scallions (, finely sliced, for garnish (optional))"],"purpose":"Chicken:"}]', '[{"description":"Place Marinade ingredients in a ziplock bag or bowl and mix to combine.","images":[],"step":1},{"title":"Add chicken and mix to coat. Marinade for 3","description":"24 hours.","images":[],"step":2},{"title":"Optional","description":"Cut chicken into bite size or large pieces and thread onto skewers. Use 1 skewer for small pieces, 2 for large, like pictured in post.","images":[],"step":3},{"description":"Heat half the oil in a heavy based skillet over medium high heat, or BBQ on medium (if using grill side, brush oil on bars).","images":[],"step":4},{"description":"Remove chicken from marinade (RESERVE for basting) and place in the skillet - cook in 2 batches, don''t crowd the pan. Cook for 4 minutes then turn.","duration":4,"images":[],"step":5},{"description":"Use the Marinade to baste the cooked side of the chicken. After 3 minutes, turn the chicken over so the basted side is now cooking again - cook for 1 minute.","duration":1,"images":[],"step":6},{"description":"Baste the chicken, then turn again and cook for 45 sec - 1 min.","duration":0.75,"images":[],"step":7},{"description":"Transfer chicken to a plate, cover loosely with foil and rest for 5 minutes.","duration":5,"images":[],"step":8},{"description":"Serve, garnished with green onions / scallions if using!","images":[],"step":9}]', '["gluten","sesame","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","chinese-recipes","grilling-ideas-and-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b0e6e7ac26e5', 'en', 'US', 'Thai Coconut Marinated Chicken', 'Recipe video above. Chicken infused in a gorgeous Thai coconut marinade which infuses with flavour and adds buttery richness from the coconut milk. MARINATING TIME: 24 - 48 hours.', 'https://www.recipetineats.com/tachyon/2017/05/Thai-Coconut-Marinated-Chicken-4.jpg', 15, 10, 25, 5, '[{"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_lemongrass", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_turmeric", "quantity": {"value": 0.007, "unit": "jar"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.469, "unit": "can of 400ml"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.04, "unit": "jar of 375g"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_ime_juice", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 0.045, "unit": "net of 500g"}}]', '[{"ingredients":["1 tsp garlic (, minced)","1 tsp ginger (, minced)","1 tsp chilli (, finely chopped (or paste is fine), adjust quantity to taste (Note 2))","1 lemongrass (OR paste) (, white part only, finely chopped(Note 3))","1 1/2 tsp coriander powder","3/4 tsp tumeric powder","1/2 tsp curry powder (any is fine)","1 tbsp brown sugar","2 1/2 tbsp fish sauce (sub soy)","3/4 cup coconut milk (full fat please!)"],"purpose":"Marinade (Note 1):"},{"ingredients":["750 g - 1 kg / 1.5 - 2 lb chicken thigh fillets (, skinless and boneless (Note 4))","Oil for cooking"],"purpose":"Chicken:"},{"ingredients":["1/2 cup coconut milk","1 tbsp peanut butter, smooth","2 tbsp Hoisin Sauce","1 1/2 tbsp lime juice","1 garlic clove (, minced)","1/2 tsp chilli paste or fresh chilli (, adjust to taste)"],"purpose":"Coconut Peanut Sauce:"},{"ingredients":["Finely chopped coriander / cilantro and more chilli (, for garnish)","Lime wedges (highly recommended)"],"purpose":"Garnish (optional):"}]', '[{"description":"Mix marinade in a large bowl. Add chicken and mix. Cover with cling wrap and marinate in the fridge for 24 - 48 hours (can''t skip marinating for this recipe).","images":[],"step":1},{"description":"Brush BBQ with oil, or heat 1 tbsp in a skillet (I used a skillet). Use Medium heat - or Medium Low if your stove/BBQ runs hot (otherwise marinade may burn).","images":[],"step":2},{"description":"Remove chicken from marinade, shaking off excess. Cook the first side for around 5 minutes or until caramelised and golden. Turn then cook the other side for 4 minutes until caramelised.","duration":4,"images":[],"step":3},{"title":"BAKING","description":"See Note 4.","images":[],"step":4},{"description":"Transfer chicken to serving plate, cover loosely with foil and rest for 5 minutes. Garnish with coriander / chilli if desired, and serve with lime wedges and Sauce.","duration":5,"images":[],"step":5},{"description":"Place ingredients in a bowl and mix a bit. Microwave for 30 seconds, then mix until smooth. Bring to room temperature or serve warm (it thickens a bit when cooled).","duration":0.5,"images":[],"step":6}]', '["fish","peanuts","soy"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","cuisines","dietary","gluten-free-recipes","grilling-ideas-and-recipes","quick-and-easy","thai-recipes","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5a34a1ade631', 'en', 'US', 'Sticky Chicken Drumsticks in Chinese Plum Sauce', 'A fantastic one for midweek and a crowd pleaser! These sticky chicken drumsticks are baked in the oven until tender, and basted with an incredible Chinese plum sauce which is sweet with a touch of tang and the beautiful fragrance of plum. See notes for skipping the marinating time!', 'https://www.recipetineats.com/tachyon/2017/02/Sticky-Baked-Chicken-Drumsticks-in-Plum-Sauce-4.jpg', 5, 50, 55, 4, '[{"id": "ing_chicken", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_fountain_plum_sauce", "quantity": {"value": 112.5, "unit": "bottle"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1.2kg / 2.4lb large chicken drumsticks (8 drumsticks)"]},{"ingredients":["3/4 cup / 185ml Fountain Plum Sauce (Note 1)","1/3 cup brown sugar (can reduce to 1/4 cup)","1/4 cup soy sauce (all purpose or light, not dark soy sauce)","2 tbsp Hoisin Sauce","2 cloves garlic, (minced)","1/2 tsp ginger, (minced)","1/2 tsp Chinese Five Spice Powder (Note 2)"],"purpose":"Plum Marinade / Glaze"},{"ingredients":["Sesame seeds","Finely chopped scallions"],"purpose":"Garnish (optional)"}]', '[{"description":"Place Marinade ingredients in a ziplock bag (or bowl) and mix. Add chicken and massage to coat in the Marinade. Refrigerate for 1 hour (see Note 3 for skipping this).","images":[],"step":1},{"description":"Preheat oven to 180C/350F (all types).","images":[],"step":2},{"description":"Line a tray with baking paper / parchment paper (or foil then spray with oil).","images":[],"step":3},{"description":"Transfer chicken to tray, shaking off excess marinade. RESERVE Marinade.","images":[],"step":4},{"title":"Baking & Basting (Total bake time","description":"50 min)","images":[],"step":5},{"description":"Bake chicken for 20 minutes.","duration":20,"images":[],"step":6},{"description":"Remove from oven. Spoon / slather / brush with reserve marinade (generously!) (Note 4). Bake for 10 minutes.","duration":10,"images":[],"step":7},{"description":"Remove from oven and TURN chicken. Baste again using tray juices and reserved marinade. Bake for 10 minutes.","duration":10,"images":[],"step":8},{"description":"Remove from oven and baste again (very generously!) using tray juices and reserved marinade. Bake for 10 minutes.","duration":10,"images":[],"step":9},{"description":"Remove chicken from oven and scrape/brush tray juices onto chicken (don''t waste free flavour!).","images":[],"step":10},{"description":"Sprinkle with sesame seeds and shallots/scallions if using. I served it with rice and steamed broccolini.","images":[],"step":11}]', '["gluten","sesame","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian-esque"],"categories":["asian-recipes","chicken-drumstick-recipes","chicken-recipes","dinner-tonight","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_39ecd939f19a', 'en', 'US', 'Chinese Satay Chicken Stir Fry', '{Video below} My homemade copycat of the Chinese takeout favourite - chicken satay stir fry! The coconut and peanut flavour is not as intense as Malaysian and Thai satay sauce, and the satay seasoning flavour is stronger. The chicken is tenderised the way Chinese restaurants do - perfect to make breast nice and juicy. This step is optional, but I think it''s worth it for a true Chinese restaurant experience! MARINATING TIME: 20 minutes for tenderising, 10 minutes for seasoning, both optional.', 'https://www.recipetineats.com/tachyon/2017/02/Chicken-in-Satay-Sauce-3.jpg', 15, 5, 20, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.227, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.019, "unit": "tub of 200g"}}, {"id": "ing_coriander", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_chilli", "quantity": {"value": 0.013, "unit": "pack of 100g"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.06, "unit": "jar of 375g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_sriracha", "quantity": {"value": 0.025, "unit": "bottle of 400ml"}}, {"id": "ing_lemongrass", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.208, "unit": "can of 400ml"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["8 oz / 250g chicken breast","3/4 tsp baking soda (bi carb soda) (optional)"],"purpose":"Tenderised Chicken, optional (Note 5)"},{"ingredients":["1/2 tsp coriander powder","1/2 tsp cumin powder","1/4 tsp turmeric powder","1/4 tsp chilli powder (Not US Chilli powder! See Note 1)","1 1/2 tsp Curry Powder (Note 2)","1/2 tsp salt","1/4 tsp white pepper"],"purpose":"Satay Seasoning"},{"ingredients":["1 1/2 tbsp smooth peanut butter","2 tsp brown sugar","1 tsp light soy sauce (Note 3)","2 tsp rice vinegar","2 tsp Sriracha (or other hot sauce)","1/2 tsp lemongrass paste (Note 4)","1/3 cup coconut milk (full fat)","1/4 cup water"],"purpose":"Satay Sauce"},{"ingredients":["1 tbsp peanut oil (or other plain oil)","1 onion (, finely chopped)","2 garlic cloves (, minced)","Shallots/scallions (, sliced (optional garnish))"],"purpose":"Stir Fry"}]', '[{"description":"Tenderise Chicken (optional)","images":[],"step":1},{"description":"Cut chicken in half length wise then slice thinly. Place in a bowl with baking soda, use fingers to coat. Set aside for 20 minutes.","duration":20,"images":[],"step":2},{"description":"Rinse well, pat dry with paper towel then place in a bowl.","images":[],"step":3},{"description":"Seasoning","images":[],"step":4},{"description":"Mix together Seasoning.","images":[],"step":5},{"description":"Sprinkle 1 tsp of Seasoning over chicken. Mix to coat then set aside for 10 minutes (not critical, can skip this).","duration":10,"images":[],"step":6},{"description":"Place all ingredients except water in a bowl. Add remaining Seasoning. Mix, then add water and mix.","images":[],"step":7},{"description":"Heat oil in wok or skillet over high heat. Add onion and garlic, stir fry for 1 minute.","duration":1,"images":[],"step":8},{"description":"Add chicken and stir fry for 2 minutes until just cooked through and a bit browned.","duration":2,"images":[],"step":9},{"description":"Lower heat slightly, then add Sauce. Stir fry until it reduce down and becomes thicker - 1 to 1 1/2 minutes.","images":[],"step":10},{"title":"Serve immediately with rice","description":"or for a low carb, low cal option, try Cauliflower Rice! Garnish with sliced shallots/scallions if desired.","images":[],"step":11}]', '["gluten","peanuts","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","dinner-tonight","main-dishes","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bc482fdc5f3e', 'en', 'US', 'Chinese Steamed Fish with Ginger Shallot Sauce', 'Steamed Chinese Fish with a Ginger and Shallot Sauce! Love the drama as the hot oil is poured over the fresh ginger and shallots, cooking it and creating the gorgeous sauce. This recipe is one of those true treasures that are simple yet taste so incredible, and it''s healthy too! The fish can be steamed or baked - refer photos in post or video below recipe.', 'https://www.recipetineats.com/tachyon/2016/11/Chinese-Fish-Ginger-Shallot-Sauce-9.jpg', 5, 15, 20, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_japanese_cooking_sake", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_oil", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["2 x 350 - 400g / 12 - 13 oz bream or snapper fish (, gutted, scaled and cleaned (Note 1))","2 stems of shallots ((scallions / green onions), diagonally julienned to 5cm/2\" length)","4 x 3cm / 1 x 2\" piece of ginger julienned","2 tbsp Japanese cooking sake (Note 2)","2 pinches of salt","3 tsp soy sauce (Note 3)","2 tsp sesame oil","4 tbsp oil (vegetable, canola or peanut oil)"]},{"ingredients":["Red chilli julienned (Note 4)"],"purpose":"Garnish (optional)"}]', '[{"description":"Cut 2 slashes on each side of the fish. Cut through to the bone.","images":[],"step":1},{"description":"Drizzle 1 tbsp of sake onto each fish.","images":[],"step":2},{"description":"Steam fish using method of choice, or bake (see directions below).","images":[],"step":3},{"description":"Meanwhile, heat oil over medium high heat until hot.","images":[],"step":4},{"description":"Transfer fish onto serving plates. Top with shallots and ginger.","images":[],"step":5},{"description":"Sprinkle with salt, drizzle over soy sauce and sesame oil.","images":[],"step":6},{"title":"Pour oil over fish","description":"enjoy the drama as it bubbles!","images":[],"step":7},{"description":"Sprinkle with red chilli if using and serve with rice and steamed Asian Greens.","images":[],"step":8},{"description":"Bamboo steamers in wok (see video)","images":[],"step":9},{"description":"Place fish on a plate and put plate in bamboo steamer. Repeat with other fish. Stack bamboo steamers and put lid on.","images":[],"step":10},{"description":"Fill wok with water, ensuring it doesn''t touch the bottom of the steamer. Bring water to boil over high heat, then place bamboo steamer on wok.","images":[],"step":11},{"description":"Steam for 10 minutes. Carefully transfer fish onto serving places.","duration":10,"images":[],"step":12},{"description":"Wrap each fish in foil, place on tray. Bake at 180C/350F for 15 minutes. Open foil and carefully transfer fish onto serving plates.","duration":15,"images":[],"step":13},{"description":"Steamer fitted inside a large pot, or a microwave steamer.","images":[],"step":14}]', '["fish","gluten","peanuts","sesame","soy"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","chinese-recipes","dietary","dinner-tonight","fish-recipes","gluten-free-recipes","main-dishes","seafood-recipes","yum-cha-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d07ba27a9a33', 'en', 'US', 'Foolproof Poached Chicken with Ginger Shallot Sauce', 'A foolproof method for poaching chicken breast with guaranteed juicy chicken every single time. Served with a Ginger Shallot (Scallion) Sauce that is so good, you will want to put it on everything! Also accompanied with a quick chilli sauce (optional). This is like a (much) faster, healthier midweek version of the famous Hainanese Chicken & Rice. Also see cooking video below recipe - don''t miss the Dozer cameo at the end! HIGH ALTITUDE locations - please see note 4', 'https://www.recipetineats.com/tachyon/2016/10/Foolproof-Poached-Chicken-Ginger-Shallot-Sauce-2.jpg', 10, 25, 35, 3, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_sriracha", "quantity": {"value": 0.037, "unit": "bottle of 400ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}]', '[{"ingredients":["2 chicken breasts (, boneless skinless, 250g/8.5 oz each (Note 1))"]},{"ingredients":["3 - 4 shallots / scallions (, green and white part thinly sliced (1 heaped cup))","2 tbsp finely grated ginger","1/4 tsp salt","5 tbsp vegetable oil (or peanut or grapeseed oil)"],"purpose":"Ginger Shallot Sauce"},{"ingredients":["1 tbsp chilli paste","1 tbsp Sriracha","1 tsp soy sauce","1 tsp sugar","1 garlic clove","1 tsp grated ginger"],"purpose":"Quick Chilli Sauce"}]', '[{"description":"Take chicken out of the fridge 30 minutes before cooking.","images":[],"step":1},{"description":"Fill a saucepan with water so the chicken breast will be well submerged with at least 2\" / 5cm of water above it.","images":[],"step":2},{"description":"Bring water to boil. Place chicken breast in water, place lid on, bring back up to the boil. Remove saucepan from stove and set aside for 20 minutes (it''s fine up to 45 min, won''t overcook).","duration":20,"images":[],"step":3},{"description":"Remove chicken from water and slice. Serve with Sauces (below) and rice.","images":[],"step":4},{"description":"Ginger Shallot Sauce","images":[],"step":5},{"description":"Combine and mix ingredients in a bowl. Set side for 20 minutes. It will sweat and become more liquidy.","duration":20,"images":[],"step":6},{"description":"Mix ingredients in a bowl. Set aside for 15 minutes.","duration":15,"images":[],"step":7}]', '["gluten","peanuts","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","chinese-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f29906a3807d', 'en', 'US', 'Sweet and Sour Chicken Stir Fry', 'This bright and colourful stir fry is made with a classic Sweet & Sour Sauce which is truly like what you get at good Chinese restaurants. This is not made by deep frying the chicken - it''s tasty enough as it is without adding more calories!! Also see Baked version of the fried Sweet & Sour Chicken - recipe here. I know 1/2 cup of sugar sounds like a lot, but it works out at 1 1/2 tbsp per serving, which isn''t too bad!', 'https://www.recipetineats.com/tachyon/2016/09/Sweet-and-Sour-Chicken-Stir-Fry-8.jpg', 10, 10, 20, 4, '[{"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.167, "unit": "bottle of 500ml"}}, {"id": "ing_pineapple", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_ketchup", "quantity": {"value": 0.09, "unit": "bottle of 500g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_pineapple", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1/2 cup white sugar (Note 1)","1/3 cup apple cider vinegar","3 tbsp pineapple juice (from the canned pineapple pieces)","3 tbsp ketchup (Australia: tomato sauce)","1 tsp Worcestershire sauce (Note 2)","1 tsp soy sauce (, light or all purpose (Note 2))","1 tsp Oyster Sauce (Note 2)","1/4 tsp salt"],"purpose":"Sauce"},{"ingredients":["1 tbsp cornflour / corn starch + 2 tbsp water (, mixed together)"],"purpose":"Thickener"},{"ingredients":["1 1/2 tbsp peanut oil (or vegetable)","1 garlic clove (, minced or finely chopped)","1 onion (, halved and sliced (brown, yellow or white) (see photo in post))","400 g / 13 oz chicken thigh fillets (, cut into bite size pieces (Note 3))","1 red capsicum / bell pepper (, cut into bite size pieces)","1 green or yellow capsicum / bell pepper (, cut into bite size pieces)","1 can ((8oz/250g) canned pineapple pieces in natural juice. Separate pineapple from juice.)","Sliced shallots / scallions (, for garnish)"],"purpose":"Stir Fry"}]', '[{"description":"Mix together Sauce ingredients. Mix together Thickener in a separate small bowl.","images":[],"step":1},{"description":"Heat oil in a wok or skillet over high heat. Add garlic and onion, cook for 1 minute.","duration":1,"images":[],"step":2},{"description":"Add chicken and stir fry until it it is white all over but still pink inside.","images":[],"step":3},{"description":"Add capsicum and stir fry for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Add Sauce ingredients. Stir until sugar has dissolved and the sauce begins to bubble.","images":[],"step":5},{"description":"Add Thickener. Bring to simmer, stirring constantly. Then cook until it thickens to a syrup consistency - about 3 minutes.","images":[],"step":6},{"description":"Stir through pineapple pieces (just to warm) and remove from stove.","images":[],"step":7},{"title":"Serve immediately with rice","description":"or for a low carb, low cal option, try Cauliflower Rice! Garnish with shallots if desired.","images":[],"step":8}]', '["gluten","peanuts","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_242962313501', 'en', 'US', 'Asian Chicken (Asian marinade)', 'A great all rounder Asian Marinade that infuses chicken with sweet/savoury flavours. This Asian chicken can be grilled, baked or cooked on the stove! MINIMUM MARINADE TIME: 1 hour (or overnight)', 'https://www.recipetineats.com/tachyon/2016/06/Asian-Marinated-Chicken_Hero.jpg', 10, 10, 20, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.045, "unit": "bottle of 500ml"}}, {"id": "ing_sriracha", "quantity": {"value": 1.0, "unit": "bottle of 400ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 - 1.5 lb / 500 - 750g chicken thigh fillets (, skinless boneless)"]},{"ingredients":["3 cloves garlic (, minced)","2 tsp ginger (, freshly grated)","2 tbsp soy sauce","2 tbsp tomato ketchup","2 tbsp Oyster sauce","1 1/2 tbsp Chinese cooking wine OR Mirin (Note 1)","1 - 3 tbsp Sriracha (adjust spiciness to taste)","2 tbsp brown sugar","1 tsp sesame oil"],"purpose":"Asian Marinade (see notes for subs)"},{"ingredients":["2 tsp oil","Sesame seeds","Finely sliced shallots / green onions","Finely sliced red chilies"],"purpose":"Cooking / Garnishes (optional)"}]', '[{"description":"Mix Marinade ingredients together. Add chicken and mix to coat. Marinade in the fridge for a minimum of 1 hour or up to overnight.","images":[],"step":1},{"description":"Heat oil in a large non stick skillet or BBQ over medium high heat. (See notes for other cooking methods) Add chicken and cook until each side is dark golden brown and chicken is cooked through (about 3 minutes each side). Transfer to plate, cover loosely with foil and rest for 3 minutes.","duration":3,"images":[],"step":2},{"description":"Garnish with chillies, shallots and sesame seeds if desired. Serve with white rice and slices of cucumber.","images":[],"step":3}]', '["gluten","sesame","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b4e91c0f7a18', 'en', 'US', 'Chinese Fried Rice with Shrimp / Prawns', 'This is a simple, traditional Chinese Fried Rice recipe by Kylie Kwong, Australia''s most well known Chinese Chef. The key to an authentic tasting fried rice like you get at proper Chinese restaurants is the Sauce, using day old or cold fresh cooked rice and ensuring you don''t overcrowd the wok, causing the rice to stew instead of stir fry! Feel free to add more vegetables (not too much otherwise the sauce will thin out) or substitute the prawns with other proteins.', 'https://www.recipetineats.com/tachyon/2016/05/Chinese-Fried-Rice_2.jpg', 10, 10, 20, 3, '[{"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_bacon", "quantity": {"value": 0.562, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_shrimp", "quantity": {"value": 0.142, "unit": "kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}]', '[{"ingredients":["3 tbsp peanut oil ((or vegetable), separated)","2 eggs (, lightly beaten)","3/4 cup bacon (, excess fat trimmed, chopped (or 1/2 cup Chinese Sausage) (Note 1))","2 garlic cloves (, minced)","3 tsp ginger (, minced or very finely chopped)","1/2 onion (, finely chopped (about 3/4 cup) (brown, white or yellow))","1 tbsp Chinese cooking wine or dry sherry (or sake, Japanese cooking wine) (Note 2)","1/2 tsp sugar","5 oz/150g small shrimp/prawns (, cooked and peeled (Note 3))","3 cups cooked long grain white rice (, refrigerated overnight (Note 4))","3 scallions (, thinly sliced)"]},{"ingredients":["1 tbsp Oyster Sauce","1 1/2 tbsp soy sauce (all purpose or light) (Note 3)","1/2 tsp sesame oil (roasted - i.e. dark colour)"],"purpose":"Sauce"}]', '[{"description":"Mix together Sauce ingredients, set aside.","images":[],"step":1},{"description":"Heat 1 tbsp oil in a wok (or heavy based skillet/fry pan) over medium heat. Add eggs and cook until scrambled, then remove onto plate.","images":[],"step":2},{"description":"Increase heat to high and add bacon. Cook until golden, then remove onto plate with egg - about 2 minutes.","images":[],"step":3},{"description":"Drain off excess bacon fat.","images":[],"step":4},{"description":"Add remaining 2 tbsp oil, garlic and ginger. (Note 5) Return wok to stove on high heat. Stir fry as it comes up to heat, don’t let it burn. When garlic starts to sizzle, add onion and stir fry for 2 minutes until golden.","duration":2,"images":[],"step":5},{"description":"Add Chinese wine and sugar and let it simmer rapidly, stirring, for 20 seconds, until mostly evaporated.","duration":0.3333333333333333,"images":[],"step":6},{"description":"Add prawns/shrimp and stir fry for 1 minute to heat through (if pre-cooked, cook longer to cook if raw).","duration":1,"images":[],"step":7},{"description":"Add rice, Sauce, eggs, bacon and all but 2 tbsp of shallots/scallions. Stir fry for 2 minutes until rice is hot - around 2 minutes.","duration":2,"images":[],"step":8},{"description":"Transfer to serving plate, sprinkle with remaining scallions and serve.","images":[],"step":9}]', '["egg","gluten","peanuts","sesame","shellfish","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese"],"categories":["asian-recipes","asian-takeout","chinese-recipes","dietary","dinner-tonight","fried-rice","gluten-free-recipes","main-dishes","prawns-shrimp","quick-and-easy","rice-recipes","rice-side-dishes","side-dishes","yum-cha-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_01f73ac4f487', 'en', 'US', 'Thai Mango Chicken Curry', 'The secrets to making a GREAT curry using store bought curry paste are: saute the paste with onion, garlic and chilli, simmer the sauce with kaffir lime leaves (KEY TIP!) and using fish sauce for seasoning. This curry is made using mango puree which is a miracle way to make a thick saucy curry but with 1/3 less calories than just using coconut milk (mangoes have 1/5th of the calories of coconut milk!). Read more in Note 2. If you don''t have mangoes, you can make this with just coconut milk which is just as tasty but has more calories - see Note 3.', 'https://www.recipetineats.com/tachyon/2016/02/Mango-Thai-Red-Curry-with-Chicken_2.jpg', 15, 20, 35, 3, '[{"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.5, "unit": "pack of 100g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.544, "unit": "kg"}}, {"id": "ing_thai_red_curry_paste", "quantity": {"value": 4.0, "unit": "bottle"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.544, "unit": "kg"}}, {"id": "ing_mango", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.544, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 0.5, "unit": "pack of 100g"}}]', '[{"ingredients":["1 tbsp oil (vegetable, canola, grape seed)","3 garlic cloves (, minced)","1/2 tsp ginger (, minced (not critical))","1/2 - 1 tsp red chilli (, minced (Optional. I used 1 tsp.))","1 small onion (, sliced (brown, white, yellow) or 3 eschallots)","1.2 lb / 600g chicken thigh fillets ((or breast), cut into bite size pieces)","4 - 5 tbsp Thai Red Curry Paste (Note 1)","1 can (400ml/13oz) coconut milk (full fat is better but low fat is ok too)","3/4 cup chicken broth","1 cup mango puree (, preferably fresh (1 large mango) (Note 2))","1 tbsp fish sauce","2 kaffir lime leaves"]},{"ingredients":["Steamed jasmine rice","Coriander/cilantro leaves","Lime wedges","Fresh red chili (, sliced)"],"purpose":"To Serve"}]', '[{"description":"Heat oil in a skillet over medium high heat.","images":[],"step":1},{"description":"Add garlic, ginger, chilli (if using) and onion and saute until the onion is starting to soften.","images":[],"step":2},{"description":"Add chicken and cook until white all over but still raw inside.","images":[],"step":3},{"description":"Add curry paste and saute for 2 minutes until fragrant.","duration":2,"images":[],"step":4},{"description":"Add coconut milk and chicken broth. Bring to simmer, stirring to dissolve the curry paste into the liquid. Then add the mango, fish sauce and kaffir lime leaves.","images":[],"step":5},{"title":"Turn heat down to medium and simmer for 12","description":"15 minutes, stirring occasionally, until the sauce is thickened. Adjust saltiness using fish sauce.","duration":13.5,"images":[],"step":6},{"description":"Serve over jasmine rice, garnished with coriander/cilantro, wedges of lime and slices of red chilli, if desired.","images":[],"step":7}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","cuisines","curry-recipes","dietary","gluten-free-recipes","main-dishes","most-popular","thai-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8746b85a91e6', 'en', 'US', 'Easy Chinese Honey Sesame Chicken', 'Crispy oven baked chicken chicken with a sesame crust tossed in a sticky sauce. Really easy and absolutely irresistible! If you can''t find sesame paste or tahini, substitute with peanut butter. Seriously! (Refer to Note 2)', 'https://www.recipetineats.com/tachyon/2016/02/Chinese-Honey-Sesame-Chicken_3.jpg', 10, 20, 30, 3, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.225, "unit": "pack of 100g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.225, "unit": "pack of 100g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_honey", "quantity": {"value": 0.105, "unit": "jar of 500g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.225, "unit": "pack of 100g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.056, "unit": "pack of 400g"}}, {"id": "ing_oil", "quantity": {"value": 0.04, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 lb / 500g chicken thighs (, cut into 1.2cm/ 1/2\" slices (Note 1))","1/2 tsp salt","2 tsp sesame paste OR tahini (Note 2)","2 tsp soy sauce","1 1/2 tbsp sesame seeds (, toasted)","1/2 cup plain flour","Oil spray"],"purpose":"Chicken"},{"ingredients":["1 tbsp Chinese cooking wine (Shaoshing / Shaoxing wine) or sherry (or use chicken broth/stock)","3/4 cup chicken broth / stock","1 tsp rice wine vinegar or Chinese black vinegar (or ordinary white vinegar)","3 1/2 tbsp honey","1 1/2 tbsp soy sauce (, all purpose ordinary (Note 3))","2 tsp sesame oil"],"purpose":"Sauce"},{"ingredients":["1 1/2 tbsp cornstarch / cornflour mixed with 2 tbsp water"],"purpose":"Cornstarch"},{"ingredients":["2 tsp oil (vegetable, canola, peanut)","2 garlic cloves (, minced)"],"purpose":"To Cook"},{"ingredients":["1 scallion/shallot stem (, sliced)","1 1/2 tbsp sesame seeds (, toasted)"],"purpose":"Garnish"}]', '[{"description":"Preheat oven to 200C/430F with shelf placed on the highest level. Spray baking tray with oil.","images":[],"step":1},{"description":"Mix sesame paste and soy sauce in a bowl (to loosen it up, easier to coat chicken). Add chicken, salt and sesame seeds.","images":[],"step":2},{"description":"Place flour in a separate bowl and coat chicken in flour, shaking off excess. Place chicken on baking tray.","images":[],"step":3},{"description":"Bake for 12 minutes. Remove from oven.","duration":12,"images":[],"step":4},{"description":"Flick to broiler/grill as high as it will go with shelf about 15cm/6\" from the heat source.","images":[],"step":5},{"description":"Turn chicken. Broiler/grill for 5 minutes until golden and quite crispy (Note 4), then remove.","duration":5,"images":[],"step":6},{"description":"Meanwhile, mix together Sauce in one bowl and Cornstarch in another.","images":[],"step":7},{"description":"Heat oil in a wok or skillet (I used a skillet) over medium heat. Add garlic and cook for 30 seconds until fragrant but not browned.","duration":0.5,"images":[],"step":8},{"description":"Add Sauce and bring to bubble. Add Cornstarch and cook for 30 seconds until it thickens into a thick syrup.","duration":0.5,"images":[],"step":9},{"description":"Remove the Sauce immediately from the stove and pour over the chicken.","images":[],"step":10},{"description":"Toss chicken in Sauce then sprinkle over Sesame Seeds and Shallots/Scallions to serve. Serve with rice.","images":[],"step":11}]', '["gluten","peanuts","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","asian-takeout","chicken-breast-recipes","chicken-recipes","chinese-recipes","dinner-tonight","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c20ebf4893bf', 'en', 'US', 'Coconut Shrimp / Prawns with Spicy THAI Mango Sauce', 'Crunchy coconut shrimp / prawns with a spicy Thai inspired Mango Sauce! These are shallow fried, not deep fried and the prawns cook VERY fast. These reheat really well! Refer to Note 6 for make ahead instructions. I made the sauce using Keitt mangoes because I think the slight tang is perfect for this recipe, but you can use any mangoes you want.', 'https://www.recipetineats.com/tachyon/2016/02/Coconut-Shrimp-Mango-Sauce_2.jpg', 20, 10, 30, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}, {"id": "ing_desiccated_coconut", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_mango", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_onion", "quantity": {"value": 30.0, "unit": "pack of 1kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_sriracha", "quantity": {"value": 0.037, "unit": "bottle of 400ml"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 2.0, "unit": "can of 400ml"}}]', '[{"ingredients":["1 lb / 500 g whole prawns OR 12oz/350g peeled fresh prawns (Note 1)","1/4 tsp salt","Black pepper","1 egg","1/2 cup panko breadcrumbs","1/2 cup desiccated coconut (Note 2)","Oil (, for frying)"],"purpose":"Shrimp / Prawns"},{"ingredients":["1 cup (packed) fresh mango. roughly diced","2 tbsp cilantro/coriander (, leaves and stems, roughly chopped)","2 tbsp red onion or eschallots (, finely chopped)","1 tbsp fish sauce (or substitute with light or ordinary soy sauce)","1 tbsp sriracha (Note 3)","1 tsp red chilli (, finely chopped (adjust to taste))","2 - 3 tbsp coconut milk (adjust for desired sauce consistency)"],"purpose":"Mango Sauce"}]', '[{"title":"Mango Sauce","description":"Place ingredients in a small food processor (or blender or use a blender stick). Whizz until smooth. Adjust salt and spice to taste. Use coconut milk to adjust the consistency.","images":[],"step":1},{"description":"Peel and devein the shrimp / prawns. Sprinkle with salt and pepper.","images":[],"step":2},{"description":"Whisk egg in a small bowl. Mix panko and coconut in another bowl.","images":[],"step":3},{"description":"Dip a prawn in the egg mixture then coat with panko. Repeat with remaining prawns.","images":[],"step":4},{"description":"Heat oil in a skillet (Note 4) over medium high heat. Toss in a clotted lump of panko/egg to test for heat - if it sizzles right away and floats to the top, then the oil is hot enough.","images":[],"step":5},{"description":"Working in batches, carefully place prawns in the hot oil. Cook for just 45 seconds (Note 5) until golden brown - start counting when you slide the first prawn in and remove the prawns from the oil in the order that you put them in.","images":[],"step":6},{"description":"Remove onto a paper towel lined tray to drain.","images":[],"step":7},{"description":"Serve warm with Spicy Mango Dipping Sauce!","images":[],"step":8}]', '["egg","fish","gluten","soy"]', '[]', '{"mealType":["snack","dinner"],"cuisine":[],"categories":["asian-recipes","cuisines","deep-fried-recipes","finger-food","most-popular","prawns-shrimp","seafood-recipes","super-bowl-party-food","thai-recipes","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_485d509b3234', 'en', 'US', 'Satay Chicken Noodle Salad', 'Chicken satay tossed in a noodle salad loaded with plenty of veggies with a creamy peanut satay dressing! Serve this warm or at room temperature.', 'https://www.recipetineats.com/tachyon/2016/01/Satay-Chicken-Noodle-Salad_1.jpg', 15, 5, 20, 3, '[{"id": "ing_peanut_butter", "quantity": {"value": 0.003, "unit": "jar of 375g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_sriracha", "quantity": {"value": 0.056, "unit": "bottle of 400ml"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.225, "unit": "can of 400ml"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.567, "unit": "pack of 500g"}}, {"id": "ing_red_cabbage", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_cabbage", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 10.0, "unit": "pack of 100g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.34, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_peanuts", "quantity": {"value": 0.113, "unit": "jar"}}]', '[{"ingredients":["¼ cup peanut butter (preferably smooth)","1 garlic clove (, minced)","1 tbsp sesame oil","2 tbsp soy sauce","2 tsp brown sugar","1 1/2 tbsp sriracha (, or 2 tsp chili paste/sauce + 2 tsp vinegar)","2 tbsp lime juice","6 tbsp coconut milk (I used low fat)","2 tbsp water","1/4 tsp salt"],"purpose":"Dressing"},{"ingredients":["10 oz/300g fresh egg noodles (Note 1)","2 cups red cabbage (, shredded)","2 cups green cabbage (, shredded)","2 carrots (, finely chopped)","1/4 tsp salt","2 scallion/shallot stems (, finely sliced on the diagonal)","1 large red chilli (not very spicy), deseeded and finely sliced (Note 2)"],"purpose":"Salad"},{"ingredients":["12 oz / 350g chicken breast (, cut in half vertically and thinly sliced)","Salt and pepper","1 1/2 tsp curry powder","2 tsp sweet soy sauce/ kecap manis (Note 3)","1 tbsp cooking oil"],"purpose":"Satay Chicken"},{"ingredients":["3 tbsp peanuts (, roughly chopped)"],"purpose":"Garnish"}]', '[{"description":"Mix dressing ingredients in a bowl until smooth.","images":[],"step":1},{"description":"Prepare noodles according to packet instructions.","images":[],"step":2},{"description":"Place both cabbages and carrots in a bowl, add 1/4 tsp salt, toss to combine and set aside for 5-10 minutes to wilt lightly.","duration":7.5,"images":[],"step":3},{"description":"Place the Satay Chicken ingredients EXCEPT the oil in a bowl and toss to coat.","images":[],"step":4},{"description":"Heat oil in a non stick fry pan over high heat. Add the chicken and cook for 3 minutes until golden, then transfer to a plate.","duration":3,"images":[],"step":5},{"description":"Toss noodles and remaining salad ingredients with chicken and Dressing, then serve. Serve at room temperature or warm.","images":[],"step":6}]', '["egg","gluten","peanuts","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner","lunch"],"cuisine":[],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","most-popular","noodles"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d078b09c4553', 'en', 'US', 'Honey Sriracha Chicken Skewers', 'Spice Level: MediumJust 5 ingredients is all you need to make a marinade that doubles as a fantastic glaze for these skewers! Just 20 minutes of marinating time required. A great balance of sweet, spicy and savoury.', 'https://www.recipetineats.com/tachyon/2016/01/Honey-Sriracha-Glazed-Chicken-Skewers_1.jpg', 15, 10, 25, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_honey", "quantity": {"value": 0.167, "unit": "jar of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.15, "unit": "jar of 200g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.24, "unit": "bottle of 250ml"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_hot_sauce", "quantity": {"value": 2.0, "unit": "bottle of 150ml"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}]', '[{"ingredients":["1.5 lb / 750g lb / 750g chicken thigh fillets (Note 1)"]},{"ingredients":["1/3 cup honey","2 tbsp Dijon mustard (Note 2)","4 tbsp soy sauce","2 garlic cloves (, crushed)","2 - 3 tbsp sriracha OR any other hot sauce ((e.g. Frank''s), adjust amount to your taste)","1/4 tsp salt"],"purpose":"Marinade Glaze"},{"ingredients":["1 1/2 tbsp oil (I used vegetable)"],"purpose":"To cook"}]', '[{"description":"Cut the chicken into 2cm / 4/5\" cubes.","images":[],"step":1},{"description":"Mix Marinade ingredients together in a bowl until smooth.","images":[],"step":2},{"description":"Transfer 4 tablespoons of the Marinade into a small bowl (\"Reserved Marinade\", to use for basting).","images":[],"step":3},{"description":"Add chicken into the bowl with the remaining Marinade. Mix to coat and set aside for 20 minutes to marinade (up to overnight). (Note 3)","duration":20,"images":[],"step":4},{"description":"Thread chicken onto skewers, discard marinade in the bowl. I used 14 small ones about 18cm/7\" long, 4 pieces of chicken on each.","images":[],"step":5},{"description":"Heat oil on a BBQ or skillet over medium heat. Place skewers on the BBQ and cook the first side for 2 1/2 minutes, then turn the skewers.","images":[],"step":6},{"description":"Baste the COOKED side that is now facing up generously with the reserved Reserved Marinade. After 2 1/2 minutes, turn the skewers and quickly baste the other side generously with the Reserved Marinade. Turn immediately. Cook for just a few seconds, then transfer to a plate. (Note 4)","images":[],"step":7},{"description":"Baste the skewers on the plate one more time with the Reserved Marinade, then serve.","images":[],"step":8},{"description":"I served mine with Cilantro/Coriander Lime Rice (Note 5)","images":[],"step":9}]', '["gluten","mustard","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian-syle"],"categories":["asian-recipes","australia-day","chicken-breast-recipes","chicken-recipes","dinner-tonight","grilling-ideas-and-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0b9d90963e47', 'en', 'US', 'Japanese Miso Salmon Side (BBQ or bake)', 'Recipe video below. My mother''s recipe for Miso Marinated Salmon. The flavour infused in the salmon is incredible. An authentic Japanese recipe, make this on the barbecue or even in the oven! You can get all the ingredients for this at Woolworths supermarket in Australia, including the side of salmon.', 'https://www.recipetineats.com/tachyon/2015/12/Miso-Marinated-Salmon-Side_2a.jpg', 10, 5, 15, 5, '[{"id": "ing_salmon_fillets", "quantity": {"value": 1.6, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_miso_paste", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_sake", "quantity": {"value": 25.0, "unit": "bottle"}}, {"id": "ing_mirin", "quantity": {"value": 0.1, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1.6 - 2.4 lb / 0.8 - 1.2kg side of salmon (, skin on (Note 1))","Oil (, for barbecue)"]},{"ingredients":["5 tbsp miso paste (Note 2)","2 tbsp white sugar","1 2/3 tbsp sake (Japanese rice wine)","1 2/3 tbsp mirin (Japanese sweet rice wine)"],"purpose":"Marinade"},{"ingredients":["Sesame seeds","Scallions/shallots (, finely sliced)"],"purpose":"Garnishes"}]', '[{"description":"Mix together the marinade ingredients in a small bowl until smooth.","images":[],"step":1},{"description":"Place the salmon skin side up on a work surface and slather with just under half the marinade.","images":[],"step":2},{"description":"Turn the salmon so it is skin side down onto a large piece of cling wrap. Slather the remaining marinade on the flesh side.","images":[],"step":3},{"description":"Wrap the salmon in cling wrap. Marinade for 24 to 48 hours.","images":[],"step":4},{"description":"Scrape the marinade off (do not rinse with water) and leave the salmon to come to room temperature <- KEY for perfectly cooked salmon.","images":[],"step":5},{"description":"Preheat barbecue plate side on MEDIUM LOW. Leave it to heat up for a good 10 to 15 minutes - another tip for cooking salmon perfectly.","images":[],"step":6},{"description":"Add oil just before cooking. Place the salmon on the BBQ skin side down. Cook for 3 minutes, then use two spatulas to turn it. Cook the flesh side for 2 - 3 minutes or until caramelised, then flip it again so the skin side is down then transfer to a tray.","duration":3,"images":[],"step":7},{"description":"Cover loosely with foil to rest for 5 minutes before serving. It will continue cooking while resting.","duration":5,"images":[],"step":8},{"description":"Garnish with sesame seeds and finely sliced shallots.","images":[],"step":9}]', '["fish","sesame"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Japanese","Modern Asian"],"categories":["asian-recipes","australia-day","dietary","easter-mains-fish-seafood","fish-recipes","gluten-free-recipes","grilling-ideas-and-recipes","modern-asian","quick-and-easy","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a0a97af3fc6c', 'en', 'US', 'Asian Grilled Shrimp / Prawns', 'Whether you make these on your BBQ or in a fry pan, this is a simple but magical combination of ingredients that tastes like something you''d get at a fancy restaurant! Actually, this is a copy of a great dish I had at a restaurant in Sydney called Esther.The nutty flavour of the browned butter pairs perfectly with a drizzle of sweet soy sauce and the freshness of lime. Add a sprinkle of chili for heat! Keep some bread on hand to mop up the glorious juices.', 'https://www.recipetineats.com/tachyon/2015/12/Asian-Barbecue-Prawns_31.jpg', 10, 5, 15, 2, '[{"id": "ing_shrimp", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 0.333, "unit": "block of 250g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.75, "unit": "bottle of 250ml"}}, {"id": "ing_ime", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 lb / 500 g shrimp / prawns (fresh), peeled and deveined (Note 1)","2 garlic cloves (, crushed)","2 tbsp vegetable oil","1/3 cup salted butter (or 1/3 cup unsalted butter + big pinch of salt)","3/4 to 1 tsp tsp sweet soy sauce / kecap manis (Note 2)","1 lime (, large)"]},{"ingredients":["1 red birds eye chilli (, deseeded and finely sliced or chopped)","Cilantro / coriander leaves"],"purpose":"Garnishes (all optional)"}]', '[{"description":"Combine shrimp / prawns, garlic and oil in a small bowl, use your fingers to coat then set aside for 15 minutes.","duration":15,"images":[],"step":1},{"description":"Browned Butter","images":[],"step":2},{"description":"Meanwhile, melt butter in a small silver fry pan or saucepan over medium heat. (Note 3)","images":[],"step":3},{"description":"Heat until it starts to foam, then swirl the pan occasionally to distribute heat evenly.","images":[],"step":4},{"description":"Cook until the butter turns golden, smells nutty and there are brown specks at the bottom (you might need a teaspoon to push the foam aside).","images":[],"step":5},{"description":"Remove from heat immediately. Pour into a jug, leaving behind most of the bitter brown specks (I strained it - because I was making an effort!).","images":[],"step":6},{"description":"Set aside until required.","images":[],"step":7},{"description":"Prawns / Shrimp","images":[],"step":8},{"description":"Heat the BBQ or fry pan over high heat (no oil).","images":[],"step":9},{"description":"Add prawns / shrimp and cook until each side is lightly golden brown, but be sure not to overcook! (Note 4)","images":[],"step":10},{"description":"Serve","images":[],"step":11},{"description":"Place prawns in a bowl. Grate over the zest of a lime, then cut the lime in half and squeeze over about 1 tbsp of lime juice. Drizzle with 1 tbsp of browned butter, toss gently.","images":[],"step":12},{"description":"Transfer to a plate. Drizzle with 2 tbsp of browned butter then lastly, drizzle over kecap manis, using as thin a stream as you can.","images":[],"step":13},{"description":"Serve immediately, garnished with chilli and cilantro/coriander, if using.","images":[],"step":14}]', '["gluten","milk","shellfish","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","australia-day","dinner-tonight","grilling-ideas-and-recipes","main-dishes","modern-asian","most-popular","prawns-shrimp","quick-and-easy","seafood-recipes","side-dishes","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_198a454d0c8a', 'en', 'US', 'Pot Roasted Coconut Chicken', 'Chicken in a fragrant coconut broth with an intensity of flavour that belies the few ingredients this recipe uses! The broth is so good that you will want to drink it straight. And the chicken stays beautifully moist by roasting it in the broth/stock. This is a clean-eating recipe that you would never think of as "clean"!', 'https://www.recipetineats.com/tachyon/2015/11/Fragrant-Coconut-Pot-Roasted-Chicken_1_600px.jpg', 15, 75, 90, 5, '[{"id": "ing_chilli", "quantity": {"value": 20.0, "unit": "pack of 100g"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_chicken", "quantity": {"value": 1.361, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 1.361, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.992, "unit": "can of 400ml"}}, {"id": "ing_potato", "quantity": {"value": 0.8, "unit": "bag of 2kg"}}, {"id": "ing_ime", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}]', '[{"ingredients":["2 long red chilies (Note 1)","1 tsp freshly grated ginger","2 garlic cloves (, crushed)","1 tbsp coconut oil (or substitute with olive oil)","1/2 tsp salt","Black pepper","1 cup finely chopped cilantro/coriander leaves","3 lb /1.6kg whole chicken (, preferably organic/free range)","2 cups / 500 ml chicken broth/stock (preferably reduced salt)","1 lemongrass (, white part only, bruised (Note 2))","2 kaffir lime leaves (Note 3)","14 oz /400ml light coconut milk (1 can)","0.8 lb / 400g baby potatoes (, scrubbed clean)","1 lime","2 tsp coconut sugar (or substitute with brown sugar)","1 tbsp fish sauce"]}]', '[{"description":"Preheat oven to 390F/200C.","images":[],"step":1},{"description":"Finely mince ONE red chili (~1 tbsp). Combine chili, ginger, garlic, oil, 1/2 cup cilantro/coriander, salt and pepper in a small bowl and set aside.","images":[],"step":2},{"description":"Rinse and pat the chicken dry (inside and out) with paper towels. Starting from the neck end of the chicken, use a teaspoon upside down to loosen the skin from the meat across the surface of the chicken (i.e. not the legs or wings). Just go as far as you can.","images":[],"step":3},{"description":"Spoon the cilantro/mixture between the meat and the skin near neck. Use the spoon to spread it a bit, then to finish it off, use your finger/hands ON the skin to spread the mixture as far and evenly as you can. Doesn''t need to be perfect! :)","images":[],"step":4},{"description":"Place the chicken stock/broth, kaffir lime leaves, lemongrass and the whole red chili into a dutch oven or baking tray. (Note 4)","images":[],"step":5},{"description":"Place the chicken in the broth, cover with a lid and roast for 45 minutes. Remove the lid, add the coconut milk and potatoes then roast for a further 30 minutes, or until juices run clear when pierced.","duration":45,"images":[],"step":6},{"description":"Remove the chicken from the broth and cover loosely with foil to rest for 5 minutes.","duration":5,"images":[],"step":7},{"title":"Skim excess fat off the surface of the broth","description":"I usually get about 5 tbsp of fat off.","images":[],"step":8},{"description":"Add the juice from the lime, sugar and fish sauce. Stir until the sugar is dissolved. Add remaining cilantro/coriander.","images":[],"step":9},{"description":"Serve the chicken with the broth in a pouring jug, or cut up the chicken and serve it in the broth.","images":[],"step":10}]', '["fish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Modern Asian"],"categories":["asian-recipes","chicken-breast-recipes","chicken-recipes","dietary","easter-mains","easter-recipes","gluten-free-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ca14a5a12d86', 'en', 'US', 'Asian Glazed Salmon', 'Recipe video above. This salmon is marinated for just 30 minutes in a simple but super tasty Asian marinade and then broiled/grilled to produce a gorgeous caramelisation. Just a really fantastic, quick and delicious way to cook salmon using pantry staples.', 'https://www.recipetineats.com/tachyon/2015/10/Asian-Glazed-Salmon-take-3_4-2-1.jpg', 5, 10, 15, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_sweet_chili_sauce", "quantity": {"value": 0.08, "unit": "bottle of 375ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_steamed_asian_greens", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["2 x 180g / 6oz salmon fillets (, skinless (Note 1))","Oil spray (olive oil, canola oil etc)"]},{"ingredients":["1 tsp fresh ginger (, finely grated)","1 garlic clove (, crushed)","1 tbsp soy sauce","2 tbsp oyster sauce","2 tbsp sweet chili sauce (Note 2)"],"purpose":"Marinade"},{"ingredients":["Sesame seeds","Scallions/shallots (, finely sliced)","Steamed Asian Greens","Rice"],"purpose":"To Serve (optional)"}]', '[{"title":"Marinade salmon","description":"Combine the Marinade ingredients in a shallow bowl. Add salmon and turn to coat. Cover and marinate for 30 minutes or up to overnight.","duration":30,"images":[],"step":1},{"description":"Preheat grill/broiler on high. Place the rack 25 cm / 10\" from the heat source.","images":[],"step":2},{"title":"Glaze","description":"Place salmon on baking tray (no oil required, no paper - it will burn). Dab glaze onto the salmon, whatever will stick. Don''t pour excess glaze on, it will pool around the salmon and burn.","images":[],"step":3},{"title":"Cook","description":"Grill/broil for 7 minutes. Remove, spray the surface generously with oil. Grill/broil for another 1 to 3 minutes until the surface is caramelised at the salmon is cooked - the flesh should flake. (Internal temperature 50°C/122°F for medium rare - see Note 3) . Be careful not to overcook the salmon!","duration":7,"images":[],"step":4},{"description":"Serve salmon sprinkled with sesame seeds, scallions/shallots with rice and steamed Asian greens on the side.","images":[],"step":5}]', '["fish","gluten","sesame","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["asian-recipes","dinner-tonight","fish-recipes","main-dishes","modern-asian","most-popular","quick-and-easy","salmon-recipes","seafood-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e5df44e2a467', 'en', 'US', 'Korean Bulgogi Beef Stir Fry', 'This is a very classic, traditional dish from Korea. It is becoming increasingly popular in Western countries as more and more people are discovering not only how delicious it is, but how easy it is to make with ingredients you can get from the supermarket! The beef has a lovely balance of sweet and salty. The use of grated apple and onion is classic Korean and it makes all the difference! Bulgogi is traditionally cooked over charcoal or a tabletop BBQ, however, I''ve made this in stir fry form which is also a way it''s used.This recipe makes enough for 2 to 3 people, served with rice as a main.', 'https://www.recipetineats.com/tachyon/2015/08/Korean-Beef-Bowl_Featured-Image.jpg', 15, 5, 20, 2, '[{"id": "ing_beef", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_onion", "quantity": {"value": 500.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.075, "unit": "pack of 100g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_mirin", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.075, "unit": "pack of 100g"}}, {"id": "ing_onion", "quantity": {"value": 500.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_apples", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["14 oz / 400 g thinly sliced beef (, any good quality tender cut suitable for grilling (Note 1))","1 scallion/shallot stem (, green and white part separated, both finely sliced (Note 2))","1/2 large onion ((brown, yellow or white), peeled and thinly sliced)","1/2 medium carrot (, peeled, cut vertically then cut into thin slices on the diagonal)","1 tbsp cooking oil (I use peanut or vegetable oil)","1/2 tbsp sesame seeds"],"purpose":"Beef"},{"ingredients":["3 tbsp ordinary soy sauce (I use Kikkoman)","1 1/2 tbsp brown sugar","1 tbsp mirin (Note 3)","1/2 tbsp sesame oil","2 tbsp grated onion (brown, white or yellow)","2 cloves garlic (, minced)","3 tbsp grated red apple ((not green - they are too tart) OR nashi pears)","1/2 tsp minced ginger","Black pepper"],"purpose":"Marinade"}]', '[{"description":"Blot the beef dry using a paper towel then place into a bowl.","images":[],"step":1},{"description":"Mix together the Marinade ingredients in a small bowl, then add the beef. Stir gently to coat the beef, cover with cling wrap and set aside to marinate for at least 1 hour, preferably overnight. Because the meat is thin, you still get good flavour even with 1 hour of marinating.","images":[],"step":2},{"description":"Heat the oil in a wok or large fry pan over high heat.","images":[],"step":3},{"description":"Add the onion and white part of the scallion/shallots. Cook for 1 minute.","duration":1,"images":[],"step":4},{"description":"Then add the beef, including the Marinade, and carrots. Cook for around 3 to 5 minutes, stirring constantly, until the beef is just cooked.","images":[],"step":5},{"description":"Remove from heat, then toss through the sesame seeds.","images":[],"step":6},{"title":"Serve immediately with rice","description":"or for a low carb, low cal option, try Cauliflower Rice! Sprinkle with extra sesame seeds and the reserved green part of the scallions.","images":[],"step":7}]', '["gluten","peanuts","sesame","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Korean"],"categories":["asian-recipes","beef-recipes","dietary","dinner-tonight","gluten-free-recipes","korean-recipes","main-dishes","most-popular","quick-and-easy","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6304c26db9ab', 'en', 'US', 'Slow Cooker Beef and Broccoli', 'This slow cooker version of Beef & Broccoli is made using the same ingredients as the authentic way of making this but the quantities have been adjusted to make it suitable for slow cooking. Making this in a slow cooker means you can use a budget cut of beef and it makes it meltingly tender. AND it''s freezer friendly!', 'https://www.recipetineats.com/tachyon/2014/09/Slow-Cooker-Beef-Broccoli-2.jpg', 10, 180, 190, 4, '[{"id": "ing_beef_steak", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_broccoli", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_ginger", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.04, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 4.0, "unit": "jar of 50g"}}]', '[{"ingredients":["500 g / 16 oz chuck steak or other beef cut suitable for slow cooking","300 g / 16 oz broccoli florets (about 6 cups, 1 giant broccoli or 2 medium)","2 tbsp corn flour (corn starch)","1 cup water (see note 2)"]},{"ingredients":["2 tbsp oil","2 tbsp finely sliced fresh ginger (note 1)","3 tbsp soy sauce (normal dark soy sauce)","2 tbsp oyster sauce","4 tsp Chinese cooking wine (rice wine) or dry sherry (note 5)","1 tsp sesame oil (optional)","1 tsp sugar","4 dashes white pepper"],"purpose":"Sauce"}]', '[{"description":"Cut the beef into thin slices against the grain (which means at 90 degrees to the direction of the fibres in the meat).","images":[],"step":1},{"description":"Place beef in slow cooker.","images":[],"step":2},{"description":"Mix the corn flour with the water, then add to the slow cooker.","images":[],"step":3},{"description":"Add the Sauce ingredients to the slow cooker.","images":[],"step":4},{"description":"Cook on HIGH for 3 hours (or pressure cook on high for 40 minutes).","images":[],"step":5},{"description":"To Serve Immediately","images":[],"step":6},{"description":"Steam or boil broccoli until \"tender crisp\" (just cooked, still bright green and still crisp).","images":[],"step":7},{"description":"Add to beef and sauce, toss to combine. Serve over rice.","images":[],"step":8},{"description":"To Make Ahead to Freeze (2 months) or Refrigerate (2 days)","images":[],"step":9},{"description":"Let the beef and sauce cool.","images":[],"step":10},{"description":"Meanwhile, blanch the broccoli very briefly, then run under cold water or plunge into ice water to stop from cooking further.","images":[],"step":11},{"description":"Drain broccoli, then combine with the beef and sauce.","images":[],"step":12},{"description":"Place into ziplock bags or airtight containers and freeze or refrigerate.","images":[],"step":13},{"description":"To cook, thaw then reheat in the microwave, covered. Be careful not to heat for too long because otherwise the broccoli will overcook.","images":[],"step":14},{"description":"Serve with rice.","images":[],"step":15}]', '["gluten","sesame","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["asian-recipes","beef-recipes","broccoli-recipes","chinese-recipes","main-dishes","quick-and-easy","slow-cooker-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_38cbd41f053d', 'en', 'US', 'Momofuku Marinated Beef Skirt Steak Ssam', '"Ssam" refers to Korean dishes in which leafy vegetables, usually lettuce, are wrapped around meat. This is a recipe by the much celebrated chef David Chang, from his famous New York restaurant Momofuku. The marinade for the beef is a classic Korean marinade and infuses the meat with enough flavour that they can be eaten as is, without a sauce. The sauces are simple to make once you get your hands on the ingredients. Excluding the marinating time, this is really fast and easy to make.', 'https://www.recipetineats.com/tachyon/2014/07/Momofuku-Marinated-Skirt-Steak-Ssam-3.jpg', 20, 10, 30, 4, '[{"id": "ing_beef_steak", "quantity": {"value": 0.907, "unit": "kg"}}, {"id": "ing_apples", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 4.536, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_grapes", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 2.0, "unit": "bottle of 250ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.004, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_ssamjang", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_kochujang", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_lettuce", "quantity": {"value": 3.0, "unit": "head"}}]', '[{"ingredients":["2 lb / 1 kg skirt / flank / hanger steak (Note 1)","2 cups apple juice","½ cup light soy sauce","5 garlic cloves (, minced)","1/2 brown onion","1 tsp sesame oil","1 tsp freshly ground black pepper"],"purpose":"Beef and Marinade"},{"ingredients":["8 oz / 250 g shallots/scallions (, thinly sliced)","5 g fresh ginger (, finely chopped or minced)","4 tbsp grape seed oil (or another neutral oil)","1 1/2 tsp light soy sauce","3/4 tsp sherry vinegar","3/4 tsp salt (adjust to taste)"],"purpose":"Ginger Spring Onion Sauce"},{"ingredients":["1 tbsp ssamjang (Korean fermented bean-and- chili paste, available in many Asian stores)","1/2 tbsp kochujang (Korean chili paste, available in many Asian stores)","1/4 cup sherry vinegar","1/4 cup grape seed oil (or another neutral oil)"],"purpose":"Ssam Sauce"},{"ingredients":["3 small heads of Bib Lettuce (, leaves removed, washed and dried)"],"purpose":"To Serve"}]', '[{"description":"Combine Beef with Marinade and marinade at least overnight, up to 24 hours.","images":[],"step":1},{"description":"Remove beef from marinade. Preheat outdoor grill or heavy based skillet on stove on very high heat. You want it to be screaming hot. Cook the beef to your liking (see notes for guide).","images":[],"step":2},{"description":"When done, remove from heat, cover loosely with foil and let them rest for 5 to 10 minutes.","duration":7.5,"images":[],"step":3},{"description":"Make the Ginger Spring Onion Sauce by combining the ingredients and mixing to combine.","images":[],"step":4},{"description":"Make the Ssam Sauce by combining the ingredients and mixing well until smooth.","images":[],"step":5},{"description":"Slice the beef into 0.5cm / 0.2 inch thick slices, against the grain.","images":[],"step":6},{"description":"Serve with lettuce, Ginger Spring Onion Sauce and Ssam Sauce on the side.","images":[],"step":7},{"description":"To eat, place a piece of beef in a lettuce leaf, top with some of each sauce, then fold over lettuce, eat and be happy.","images":[],"step":8}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie","vegan","vegetarian"]', '{"mealType":["snack","dinner"],"cuisine":["Asian","Fusion","Korean"],"categories":["asian-recipes","australia-day","beef-recipes","grilling-ideas-and-recipes","korean-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3ce3afb0cf8b', 'en', 'US', 'Vietnamese Chicken Pho soup (Pho Ga)', 'Recipe video above. Chicken Pho (Pho Ga) - the little sister of famous Beef Pho, equally delicious but much easier to make! I call it the Vietnamese version of homemade chicken noodle soup made from scratch. Except - dare I say it - so much more exciting!You won''t use all the chicken, but it''s infused with lovely flavour so there''s loads of uses - see Note 7.', 'https://www.recipetineats.com/tachyon/2020/05/Chicken-Pho_2.jpg', 10, 90, 100, 4, '[{"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_ginger", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_star_anise_pods", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_s", "quantity": {"value": 4.0, "unit": "pack"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.04, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_rice_noodles", "quantity": {"value": 0.96, "unit": "pack of 375g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 3.0, "unit": "bag of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_imes", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_sriracha", "quantity": {"value": 1.0, "unit": "bottle of 400ml"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 tbsp oil (, vegetable or canola (or other plain oil))","2 onions (, halved (skin on fine))","5cm/ 2\" piece of ginger (, sliced 0.75cm / 1/3\" thick (unpeeled))"],"purpose":"Charred aromatics:"},{"ingredients":["2 litres / 2 quarts water","1.5 kg / 3 lb chicken thighs, bone in skin on (Note 1)","1 small bunch coriander/cilantro (Note 2)","5 star anise pods (was short in photo & video!)","1 cinnamon stick","4 cloves","2 tsp fennel seeds","2 tsp coriander seeds","8 tsp fish sauce","6 tsp white sugar","3/4 tsp salt (Cooking/kosher salt, or 1/2 tsp table salt)"],"purpose":"Pho Soup Broth:"},{"ingredients":["360g / 13 oz dried rice noodles (, thin flat (or 600g fresh))","2 green onions stems (, finely sliced)"],"purpose":"Noodle Bowls:"},{"ingredients":["3 cups bean sprouts (Note 3)","1 small bunch EACH Thai Basil, min, coriander/cilantro (Note 4)","2 limes (, cut into 4 wedges)","Hoisin sauce","Sriracha","Red chillies (, finely sliced (optional))"],"purpose":"Toppings – help yourself"}]', '[{"title":"Char onion & ginger","description":"Heat oil in a 6 litre / 6 quart pot (Note 5) over high heat. Place ginger and onion facedown, leave undisturbed for 2 minutes until they blacken. Turn and leave for another 2 minutes.","duration":2,"images":[],"step":1},{"title":"Put everything in pot","description":"Add water and remaining Broth ingredients EXCEPT salt. Bring it a simmer, then lower heat so it''s simmering VERY gently with the lid on, but open a crack (Note 6).","images":[],"step":2},{"description":"Simmer gently 1.5 hours. Scoop off scum (dirty foam) that rises to surface once or twice during the simmering.","images":[],"step":3},{"title":"Strain & measure","description":"Remove chicken, then strain broth into a clean pot - you should have 1.5 litres / 1.5 quarts. If you have more, simmer to reduce. If less, top it up with water.","images":[],"step":4},{"title":"Salt broth","description":"Add salt, bring broth to a gentle simmer. Broth should be slightly on the salty side - it dilutes when you add the noodles.","images":[],"step":5},{"description":"Keep broth warm until ready to serve","images":[],"step":6},{"description":"Shred chicken meat, discard bones and skin. (Note 6 Leftover Chicken ideas)","images":[],"step":7},{"description":"Place Toppings out on the table.","images":[],"step":8},{"description":"Reheat chicken (can briefly dunk in broth!).","images":[],"step":9},{"description":"Prepare noodles per packet directions, just prior to serving. Drain very well (excess water dilutes broth).","images":[],"step":10},{"description":"Place noodle in bowls. Top with chicken, ladle over 375ml / 1.5 cups broth. Sprinkle with green onion.","images":[],"step":11},{"description":"Pile on Toppings of choice, add a squeeze of lime into the broth. Consume immediately!","images":[],"step":12}]', '["fish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["asian-soups","iconic-dishes","soup-recipes","vietnamese-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_309a5dcc98d0', 'en', 'US', 'Chinese Orange Chicken', 'Recipe video above. This is a recipe for Chinese Orange Chicken that makes impressively crispy chicken pieces without deep frying. The sauce has great orange flavour, it''s not too sweet, and I love the background hint of ginger!The chicken does lose crispiness once tossed with sauce, but you''ll still get crispy bits. It''s not a flaw, it''s the way it is! More importantly though, the sauce really clings to the surface of the chicken so you get a good amount of that lovey orange sauce with every bite.Source: Loosely based on the Orange Chicken by Woks of Life, though I used my no-deep-fry method and tweaked the sauce to my taste.', 'https://www.recipetineats.com/tachyon/2026/06/Orange-chicken-0.jpg', 20, 15, 35, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_ginger", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.075, "unit": "pack of 400g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_oranges", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_oranges", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["600g/1.2 lb boneless skinless chicken thighs or breast (, cut into 2.5cm / 1\" pieces)","2 tbsp light soy sauce (, or all-purpose soy (not dark soy - Note 1))","1/2 tsp finely grated ginger (, optional)","1/8 tsp white pepper (substitute black pepper)","2 tbsp cornflour / cornstarch (- for mixing)","3/4 cup cornflour / cornstarch (- for crispy coating)","3/4 - 1 cup vegetable oil (, or other plain oil (1/2 cm / 0.2\" depth))"]},{"ingredients":["2 tsp orange zest (, from 1 orange)","1 cup orange juice (, either squeeze oranges or use fresh bottled OJ (or use the orange then top up with bottle))","1 1/2 tbsp cornflour / cornstarch","2 tbsp Chinese cooking wine (/Shaoxing wine (Note 2))","2 tbsp rice vinegar (substitute white vinegar)","1/3 cup + 2 tbsp white sugar","2 tbsp light soy sauce ( or all-purpose soy sauce (not dark soy - Note 1))","1/4 tsp cooking salt / kosher salt (halve for table salt, double for flakes)","1 tsp ginger (, finely grated)","2 garlic cloves (, finely minced with a knife)"],"purpose":"Orange sauce:"},{"ingredients":["White rice (, or other plain rice of choice)","1 green onion (, finely sliced - optional garnish)","White sesame seeds - optional garnish"],"purpose":"For serving:"}]', '[{"description":"Mix chicken with soy, ginger, pepper and 2 tbsp cornflour, then coat in remaining cornflour. Clench few pieces in fist, shake off excess cornflour in colander. Shallow-fry until deep golden. Remove oil, sauté garlic, simmer sauce 2 min until thickened. Add zest, toss chicken, serve!","images":[],"step":1},{"title":"Orange sauce","description":"Whisk the cornflour and soy sauce in a large jug or medium bowl until lump free. Then whisk in everything else except garlic and orange zest. Set aside.","images":[],"step":2},{"title":"Coat chicken","description":"Mix the chicken pieces with the soy sauce, ginger, pepper and the 2 tablespoons of cornflour in a large bowl. Mix well - the coating becomes a bit sticky and acts as a glue. Add the 3/4 cup cornflour and toss to coat each piece, separating as needed (they stick together a bit).","images":[],"step":3},{"title":"Press and shake off","description":"Pick up a few pieces and enclose in your fist, to really press the cornflour on. Place in a colander, then repeat with remaining chicken. Shake colander so excess cornflour falls through the holes. This press-and-shake method is highly effective crispy no-fry technique! (Note 3)","images":[],"step":4},{"title":"Shallow-fry until crispy","description":"Heat the oil on high heat in a large deep non-stick pan (mine is 30cm/12\"). The chicken should sizzle straight away when you dip it. Spread half the chicken out (or as much as you can, without crowding), and cook for 1 1/2 minutes on each side, using tongs to turn, until deep golden and crispy. Remove onto a paper towel lined tray and repeat with remaining chicken.","images":[],"step":5},{"title":"Sauté","description":"Pour out all but 2 tablespoons of the oil, and scrape out any loose crispy bits. Return the pan to medium high heat. Sauté garlic until light golden, about 20 - 30 seconds.","images":[],"step":6},{"title":"Thicken sauce","description":"Give the sauce a whisk (to mix cornflour settled on the base) then pour it in the pan. Simmer for 1 to 2 minutes until it thickens into a thick, glossy syrup (honey consistency). Stir in zest.","duration":1.5,"images":[],"step":7},{"title":"Toss","description":"Put the chicken back into the pan and toss quickly to coat in the sauce. Serve over rice, garnished with green onion.","images":[],"step":8}]', '["gluten","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Chinese","Chinese American"],"categories":["asian-takeout","chicken-recipes","chinese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a612eb324787', 'en', 'US', 'Greek Zucchini Tots', 'Recipe video above. These tasty bites are from the Greek Island of Alonnisos, adapted from the Courgette / Zucchini Rissoles recipe in The Food and Cooking of Greece cookbook. Such a great way to use the humble zucchini to make something fabulous that''s meal worthy and great to pass around at a party!Traditionally they''re deep fried but I like to make them in the oven (handy, healthier) and make them tater-tot (potato gem) shapes. But you can make them any shape you want!', 'https://www.recipetineats.com/tachyon/2015/10/Greek-zucchini-tots_0-1.jpg', 20, 30, 80, 30, '[{"id": "ing_zucchini", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_green_onion", "quantity": {"value": 2.25, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_cheese", "quantity": {"value": 0.5, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_mint", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["1 lb / 500 g zucchinis (courgettes)","1/4 tsp cooking salt / kosher salt"],"purpose":"Zucchini"},{"ingredients":["1/2 cup plain flour ((all-purpose flour), can sub gluten-free flour)","1 cup panko breadcrumbs ((Note 1), can sub gluten-free flour)","2 eggs","3/4 cup green onion (, finely sliced (white and pale green parts only))","1/2 cup parmesan cheese (, finely grated (I use store bought sandy type), can also use shredded cheddar or tasty cheese)","1 tbsp dried oregano (or 2 teaspoon other dried herbs)","2 garlic cloves (, minced)","1/4 tsp cooking salt / kosher salt","150 g / 5 oz Greek feta cheese (, crumbled)"],"purpose":"Batter"},{"ingredients":["Olive oil spray","Lemon wedges and oregano leaves (, optional garnishes)"],"purpose":"Cooking and serving"},{"ingredients":["3/4 cup plain Greek yoghurt (, or any plain unsweetened yogurt)","1 tbsp fresh mint (, finely chopped)","1/2 tbsp lemon juice","1/2 tbsp extra virgin olive oil (or more)","1/4 tsp each salt and pepper"],"purpose":"Minted Yoghurt (optional)"}]', '[{"description":"Preheat oven to 200°C/390°F (180°C fan-forced)","images":[],"step":1},{"title":"Sweat zucchini","description":"Grate the zucchini using a standard box grater. Place into a large colander, sprinkle with the salt, toss with your fingers and leave to sweat for 30 minutes.","duration":30,"images":[],"step":2},{"title":"Squeeze out liquid","description":"Working a handful at a time, squeeze out the excess water (as much as you can) and place the zucchini in a bowl.","images":[],"step":3},{"title":"Tots batter","description":"Add the Batter ingredients except the feta and mix well to combine. Add the feta and gently stir through.","images":[],"step":4},{"title":"Form tots","description":"Dollop heaped tablespoons 2 trays lined with baking paper / parchment paper (I get 29 in total). Then use your fingers to shape them into cylinder \"tater-tot / potato gem\" shapes.","images":[],"step":5},{"title":"Bake","description":"Spray generously with oil. Bake for 30 minutes, swapping the trays at around 20 minutes (for extra golden, spray again with oil), or until golden brown and a crunchy crust forms on the surface. The tray on the bottom might need a few extra minutes.","duration":30,"images":[],"step":6},{"description":"Serve with Minted Yogurt, lemon wedges and sprinkled with fresh oregano leaves if using.","images":[],"step":7},{"description":"Mix together ingredients and set aside for at least 10 minutes before serving.","images":[],"step":8}]', '["egg","gluten","milk"]', '["keto_friendly","low_calorie","vegetarian"]', '{"mealType":["snack","breakfast","dinner","lunch"],"cuisine":["Greek"],"categories":["australia-day","finger-food","fritters-tots-and-similar","greek-recipes","mediterranean-recipes","side-dishes","super-bowl-party-food","vegetarian-recipes","zucchini-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6a8ca80c1883', 'en', 'US', 'Nando''s Peri Peri Chicken Burgers', 'Recipe video above. This is my copycat of Nando''s famous Peri Peri Chicken Burgers! Chicken marinated in a homemade Peri Peri sauce, seared for an authentic char, piled onto warm buns and slathered with a homemade "Perinaise" (Peri Peri Mayonnaise sauce). This is moreish, burger perfection, better than take-out!Serve with French fries or wedges for a real-deal Nando''s experience at home. Excellent for gatherings - marinade large batches of chicken, cook on the BBQ, set up a DIY burger station!', 'https://www.recipetineats.com/tachyon/2015/11/Nandos-Peri-Peri-Chicken-Burger_9.jpg', 15, 15, 210, 4, '[{"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_vinegar", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.75, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_drops_red_food_colouring", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_peri_peri_sauce", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.188, "unit": "jar of 400g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.15, "unit": "tub of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_chicken_breast", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}]', '[{"ingredients":["1 - 3 birds eye red chilies (1 is very mild, 3 is mildly spicy) (Note 1)","1 medium red capsicum / bell pepper (, roughly cut into 1.5cm / 1/2\" pieces)","5 garlic cloves (, peeled, whole)","3 tbsp vegetable or canola oil (, or other plain flavoured oil)","4 tbsp malt vinegar (Note 2)","2 tbsp smoked paprika (substitute regular / sweet paprika)","1 tbsp dried oregano","2 tsp onion powder (substitute garlic powder)","1 1/2 tsp white sugar","1 1/2 tsp cooking salt / kosher salt","3 drops red food colouring (optional, Note 3)"],"purpose":"Peri Peri Sauce/Marinade"},{"ingredients":["3 tbsp Peri Peri Sauce (above)","1/2 cup whole egg mayonnaise (or other mayonnaise)","1/4 cup sour cream (or yoghurt)"],"purpose":"Perinaise"},{"ingredients":["2 tbsp olive oil","4 chicken breasts or chicken thigh fillets (, skinless boneless (each large enough for a burger))","4 soft rolls (, split and lightly toasted (if desired))","2 tomatoes (, sliced)","Lettuce of choice"],"purpose":"Burgers"}]', '[{"title":"Prepare chicken breast","description":"If using breast, pound to 1 cm / 0.4\" even thickness (cover with go-between or freezer bags, use a meat mallet or rolling pin). Then trim each chicken piece so it is a bit larger than the buns (factor in 20% shrinkage when it cooks).","images":[],"step":1},{"title":"Peri Peri Sauce","description":"Put the Per Peri Sauce ingredients in a jug and blitz until smooth using a stick blender, or other appliance of choice (food processor, blender, NutriBullet).","images":[],"step":2},{"title":"Marinade chicken","description":"Pour 1/2 cup of the sauce into a bowl or ziplock bag. Add the chicken and turn to coat. Marinate for at least 3 hours, or up to 24 hours, in the fridge.","images":[],"step":3},{"title":"Perinaise","description":"Mix together the Perinaise ingredients. Set aside.","images":[],"step":4},{"title":"Cook chicken","description":"Heat 1 tablespoon of olive oil in a fry pan over medium / medium-high heat, OR brush BBQ grill with oil then heat. Cook breast for 3 minutes on each side, thighs for 4 minutes (in batches, if they won''t fit in the pan), lowering the heat as needed if they are charring too much (char = legit!).","duration":3,"images":[],"step":5},{"title":"Rest","description":"Remove the chicken onto a plate, loosely cover with foil and rest for 5 minutes. (Meanwhile, toast the rolls)","duration":5,"images":[],"step":6},{"title":"Assemble","description":"To make the burgers, spread the base of a roll with Peri-naise. Top with lettuce, tomato then chicken, then top with more Peri-naise and extra Peri Peri sauce if desired!","images":[],"step":7}]', '["egg","milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Portuguese"],"categories":["australia-day","burger-recipes","chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","mediterranean-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2b84323b4311', 'en', 'US', 'Moroccan lamb backstrap', 'Recipe video above. Love lamb backstrap - beautifully tender with a relatively mild lamb flavour. Pairs 100% perfectly with a bold, earthy Moroccan Ras el hanout spice blend. Cook this lean, delicate meat gently - keep it blushing pink for optimum juiciness!Serve on a bed of Pearl couscous salad or traditional couscous for a fabulous share platter. Cook on the stove or BBQ on warm summer days!', 'https://www.recipetineats.com/tachyon/2023/01/Moroccan-lamb-backstraps_1-1.jpg', 10, 10, 20, 4, '[{"id": "ing_lamb", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_ginger", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.025, "unit": "bunch"}}, {"id": "ing_powder", "quantity": {"value": 3.75, "unit": "jar"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_paprika", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_pears", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_couscous", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_more_side_suggestions_in_post", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["2 x 250g/8oz lamb backstraps (Note 1)","1 tbsp extra virgin olive oil (rubbing)","1 1/2 tbsp extra virgin olive oil (cooking)"]},{"ingredients":["1 1/2 tsp cooking/kosher salt","3/4 tsp cumin powder","3/4 tsp ground ginger","3/4 tsp black pepper","1/2 tsp allspice powder","1/4 tsp cinnamon powder","1/4 tsp coriander powder","1/8 tsp clove powder"],"purpose":"Moroccan spice mix (ras el hanout, Note 2):"},{"ingredients":["3/4 cup Greek yoghurt","1 tbsp lemon juice","1 tbsp olive oil (, plus extra swish for drizzling)","1/4 tsp each salt and pepper","Pinch of sumac or paprika (, optional garnish)"],"purpose":"Yogurt sauce (for serving):"},{"ingredients":["Pearl couscous salad (pictured in post)","Classic couscous","More side suggestions in post"],"purpose":"Sides (optional):"}]', '[{"title":"Yogurt sauce","description":"Mix ingredients. Refrigerate until required.","images":[],"step":1},{"title":"Moroccan spice mix","description":"Mix the spices in a small bowl.","images":[],"step":2},{"title":"Coat backstrap","description":"Pat the backstraps dry with a paper towel then rub all over with 1 tbsp olive oil. Sprinkle the spice mix on the lamb backstraps - use it all! Set aside for 1 hour to marinate (if time permits, can skip).","images":[],"step":3},{"title":"Cook","description":"Heat 1 1/2 tablespoons olive oil in a large skillet over medium high heat. Cook the lamb backstops for 4 minutes on each side, or until the core temperature is 59°C/138°F.","duration":4,"images":[],"step":4},{"title":"Rest","description":"Transfer onto a rack set over a tray (or just a plate) to rest for 3 minutes. Cut into 0.75 - 1 cm / 1/4 - 1/3\" thick slices. Serve with yogurt sauce!","duration":3,"images":[],"step":5}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern","Moroccan"],"categories":["australia-day","easter-mains","easter-recipes","lamb","lamb-recipes","mains","moroccan"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eba234227723', 'en', 'US', 'Greek Butterflied Lamb Leg', 'Recipe video above. This is a terrific, bold Greek marinade for lamb that both tenderises and infuses it with garlicky, herby, lemon flavours. Butterflied lamb leg is a fantastic way to enjoy lamb because the flattened shape means it can be cooked relatively quickly compared to roasting a whole leg. In fact, I think that butterflied lamb leg is one of the best cuts of lamb for the BBQ!', 'https://www.recipetineats.com/tachyon/2021/01/Butterflied-Lamb-Leg_0.jpg', 5, 25, 30, 8, '[{"id": "ing_lamb", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1000.0, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 0.1, "unit": "net of 500g"}}, {"id": "ing_zest", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.1, "unit": "net of 500g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_greek_salad", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_tzatziki", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_more_ideas_listed_in_post", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1.5 - 1.8kg / 3 - 3.6 lb butterflied (ie. boneless) lamb leg (Note 1)"]},{"ingredients":["1 tbsp dried oregano","3 large garlic cloves (, minced using garlic press)","2 tsp salt","1 tsp black pepper","1/3 cup fresh lemon juice","1 tbsp zest (= zest of 1 lemon)","1/2 cup olive oil"],"purpose":"Marinade:"},{"ingredients":["1 tbsp oil (for brushing BBQ or for stove sear)"],"purpose":"For cooking:"},{"ingredients":["Lemon (, for garnish)","Oregano leaves (, optional garnish as pictured)","Flatbreads or store bought pita breads","Greek Salad","Flatbreads or store bought pita breads","More ideas listed in post"],"purpose":"Serving options:"}]', '[{"description":"Mix marinade ingredients in a large ziplock bag.","images":[],"step":1},{"description":"Add lamb, massage bag well to get the marinade into all the meat cracks and crevices.","images":[],"step":2},{"description":"Seal bag and marinate for 24 hours (3 hours minimum).","images":[],"step":3},{"description":"Remove lamb from the fridge 1 hour prior to cooking (to take fridge chill out for more even cooking).","images":[],"step":4},{"description":"Brush grates with oil then preheat BBQ until very hot. (Takes a good 15 minutes, lid closed, with my basic gas BBQ).","images":[],"step":5},{"description":"Remove lamb from marinade and place on the grill, fat side down.","images":[],"step":6},{"description":"Cook for 12 minutes, then turn and cook the flesh side for 8 minutes, or until the internal temperature in the thickest part registers 57°C / 135°F for medium-rare or desired pull temperature (see Note 3).","duration":12,"images":[],"step":7},{"description":"Loosely cover with foil, and rest for 10 minutes before serving.","duration":10,"images":[],"step":8},{"description":"Stove/Oven (Note 2):","images":[],"step":9},{"description":"Preheat oven to 180°C/350°F (all oven types). Place a rack on a tray.","images":[],"step":10},{"description":"Cut lamb into 2 or 3 large pieces so it fits in your skillet.","images":[],"step":11},{"description":"Heat oil in skillet over medium-high heat. Sear until golden brown on both sides, around 2 - 3 minutes each side. (Note: It will not colour much more in the oven)","images":[],"step":12},{"title":"Roast for 22","description":"25 minutes, or until the thickest part registers 57°C / 135°F for medium-rare or desired pull temperature (see Note 3).","duration":23.5,"images":[],"step":13},{"description":"Remove from oven, loosely cover with foil, and rest for 10 minutes before serving.","duration":10,"images":[],"step":14},{"description":"Either slice it at the table, or slice prior to serving and pile onto a platter. Fabulous served with Greek Salad, Tzatziki and flatbreads, as pictured in post.","images":[],"step":15},{"title":"More side suggestions","description":"Lemon Rice, Mediterranean Rice Salad, Greek Chickpea Salad, Lemon Orzo Salad.","images":[],"step":16}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["australia-day","easter-mains","easter-recipes","grilling-ideas-and-recipes","lamb","lamb-recipes","mains","roast-lamb","roasts"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b49cd69460b4', 'en', 'US', 'Homemade Rotisserie Doner Kebab Meat - beef or lamb!', 'Recipe video above. This is a homemade version of the giant punching bag size Doner kebab meats rotating on vertical rotisseries in kebab shops! It might be small, but what it lacks in size it makes up for in authenticity and flavour. Prepare to be amazed - it tastes JUST like the real deal (and your house will smell like a kebab shop!)Excellent food for gatherings - make ahead, wow factor, DIY wraps and economical.', 'https://www.recipetineats.com/tachyon/2020/07/Carving-Doner-Kebab-Meat-1.jpg', 20, 120, 140, 8, '[{"id": "ing_beef_mince", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cinnamon", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 8.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 6.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_hummus", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 6.0, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}]', '[{"ingredients":["1 kg / 2 lb lamb or beef mince (ground meat) (, preferably 15% fat (Note 1))","200g / 7oz streaky bacon (, roughly diced (Note 2))","1 onion (, diced (brown, yellow, white))","2 clove garlic (, roughly chopped)","1 tbsp vegetable oil (or olive oil (for frying))"]},{"ingredients":["1 tsp dried oregano","2 tsp ground cumin","2 tsp ground coriander","1/2 tsp cinnamon","3 tsp salt (, kosher/cooking salt (Note 3))","1 tsp black pepper"],"purpose":"Seasoning Spices:"},{"ingredients":["8 flatbreads (Lebanese bread authentic!)","1 iceberg lettuce (, finely shredded)","6 tomatoes (, halved and sliced)","2 red onions (, finely sliced)","Hummus","Yogurt sauce (, optional (recipe Note 8))","More Sauce options: chilli sauce/Sriracha (I use this), BBQ, sweet chilli, tomato sauce/ketchup","Extra options: tabbouleh, shredded cheese"],"purpose":"Doner Kebabs:"}]', '[{"title":"Mix beef or lamb with all the Spices","description":"mix well using your hands.","images":[],"step":1},{"description":"Cover and refrigerate 2 hours minimum, or up to 24 hours.","images":[],"step":2},{"description":"Preheat oven to 170°C/ 325°F (150°C fan).","images":[],"step":3},{"description":"Line baking pan with foil.","images":[],"step":4},{"description":"Check to ensure skewers are long enough to prop on the sides of the pan. (Note 5)","images":[],"step":5},{"description":"Place onion, bacon and garlic in a 8 cup/2L+ food processor. Blitz until it becomes a paste (video at 29 sec),~30 sec on high, scraping down sides as you go.","images":[],"step":6},{"description":"Add meat and blitz on low until it becomes a paste (video at 42 sec), scraping down sides (~1 min for powerful food processors, 2 min for less powerful). (Note 4)","images":[],"step":7},{"description":"Shape Doner Kebab Meat:","images":[],"step":8},{"description":"Turn meat out onto work surface. Wet hands with water, then shape into an even block 20cm/8\" long.","images":[],"step":9},{"description":"Place 2 x 60cm / 2 feet long pieces of foil overlapping each other by 1/3. (Note 6)","images":[],"step":10},{"description":"Place meat on the end of the foil, then roll it up, tightly wrapping it in the foil.","images":[],"step":11},{"description":"Twist the ends firmly to form a log 25cm/10\" long, then snip off excess foil. Roll into even log.","images":[],"step":12},{"description":"Thread skewers through the log.","images":[],"step":13},{"description":"Place log elevated in pan by propping skewers on the edge of the pan. (Note 7)","images":[],"step":14},{"description":"Cooking:","images":[],"step":15},{"description":"Cook for 1 1/2 hours, turning once after 1 hour, until the log reaches 70°C/160°F (up to 80°C/175°F is fine). The log is cooked at this point. (Note 9)","images":[],"step":16},{"description":"Remove foil from log but leave skewers in place.","images":[],"step":17},{"description":"Increase oven heat to 250°C/480°F, or as high as your oven can go if it can''t reach this.","images":[],"step":18},{"description":"Bake for 10 to 15 minutes, rotating once, until browned all over.","duration":12.5,"images":[],"step":19},{"description":"Shaving / pan frying (kebab shop style!):","images":[],"step":20},{"description":"Remove skewers then stand the meat upright.","images":[],"step":21},{"title":"Shave meat thinly","description":"carve as much as you intend to use.","images":[],"step":22},{"description":"Heat oil in a skillet over medium high heat. Cook shaved meat lightly coloured but still \"floppy\" (not crisped). Use immediately for Doner Kebabs!","images":[],"step":23},{"description":"Smear hummus on warmed flatbread. Top with lettuce, tomato, and onion.","images":[],"step":24},{"description":"Pile on Doner Kebab Meat. Drizzle with sauce(s) of choice.","images":[],"step":25},{"description":"Roll up tightly, wrap in foil if desired (to hold together). Grab and devour!","images":[],"step":26}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Turkish"],"categories":["australia-day","beef-mince-recipes","beef-recipes","cuisines","grilling-ideas-and-recipes","iconic-dishes","lamb-recipes","main-dishes","mains","middle-eastern-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8b91a54343e0', 'en', 'US', 'Greek Chicken Gyros with Tzaziki', 'Recipe video above. The marinade for the chicken is so sensational that I use it even when I''m not making Gyros! This is fantastic for entertaining because you can just lay it all out for guests to help themselves. The smell when the chicken is cooking is incredible - you can really smell the oregano and garlic!Recipe includes a Tzatziki, you can also use a Lemon Yogurt Sauce for a quicker option (make a double batch).', 'https://www.recipetineats.com/tachyon/2015/06/Greek-Chicken-Gyros_original-pics__8.jpg', 20, 6, 26, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.907, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1000.0, "unit": "pack of 3 heads"}}, {"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.375, "unit": "tub of 500g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.375, "unit": "tub of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1000.0, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}]', '[{"ingredients":["2 lb / 1 kg chicken thigh fillets (, boneless skinless)"]},{"ingredients":["3 large garlic cloves (, minced (~ 3 tsp))","1 tbsp white wine vinegar (or red wine or apple cider vinegar)","3 tbsp lemon juice","1 tbsp extra virgin olive oil","3 tbsp Greek yogurt (, preferably full fat)","1 1/2 tbsp dried oregano","1 tsp salt","Black pepper"],"purpose":"Marinade"},{"ingredients":["2 cucumbers (to make about 1/2 - 3/4 cup grated cucumber after squeezing out juice)","1 1/4 cups Greek yoghurt (, preferably full fat)","1 tbsp lemon juice","1 tbsp extra virgin olive oil (or more if you want richer)","1 garlic clove (, minced)","1/4 tsp salt","Black pepper"],"purpose":"Tzatziki"},{"ingredients":["3 tomatoes (, desseeded and diced)","3 cucumbers (, diced)","1/2 red spanish onion (, peeled and finely chopped)","1/4 cup fresh parsley leaves (optional)","Salt and pepper"],"purpose":"Salad"},{"ingredients":["4 to 6 pita breads or flat breads"],"purpose":"To Serve"}]', '[{"description":"Place the Marinade ingredients in a ziplock bag and massage to mix. Add the chicken into the ziplock bag and massage to cover all the chicken in the Marinade. Marinate for at least 2 hours, preferably 3 hours, ideally 12 hours and no longer than 24 hours.","images":[],"step":1},{"description":"Make the Tzatziki","images":[],"step":2},{"description":"Cut the cucumber in half lengthwise. Use a teaspoon to scrape the watery seeds out. Coarsely grate the cucumber using a box grater. Then wrap in paper towels or a tea towel and squeeze to remove excess liquid.","images":[],"step":3},{"description":"Place cucumber in a bowl. Add remaining ingredients then mix to combine. Set aside for at least 20 minutes for the flavours to meld.","images":[],"step":4},{"description":"Combine ingredients in a bowl.","images":[],"step":5},{"description":"Cook Chicken","images":[],"step":6},{"description":"Brush the outdoor grill with oil, then preheat on medium high. Or heat 1 tbsp of oil in a fry pan over medium high heat.","images":[],"step":7},{"description":"Remove chicken from Marinade. Cook the chicken for 2 to 3 minutes on each side, until golden brown and cooked through (cooking time depends on size of chicken).","duration":2.5,"images":[],"step":8},{"description":"Remove the chicken from the grill / fry pan onto a plate. Cover loosely with foil and allow to rest for 5 minutes before serving.","duration":5,"images":[],"step":9},{"description":"If your chicken thighs are large, you may need to cut them. Mine were small.","images":[],"step":10},{"description":"Get a pita bread or flatbread (preferably warmed) and place it on a piece of parchment (baking) paper (or you could use foil). Place some Salad down the middle of the bread, then top with chicken and Tzatziki.","images":[],"step":11},{"description":"Roll the wrap up, enclosing it with the parchment paper. Twist the end with the excess parchment paper to secure it and cut if desired.","images":[],"step":12},{"description":"I prefer to lay everything out on a table and let everyone help themselves.","images":[],"step":13}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner","lunch"],"cuisine":["Greek"],"categories":["australia-day","chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","greek-recipes","grilling-ideas-and-recipes","mediterranean-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_14689a674677', 'en', 'US', 'Oven Pork Ribs with Barbecue Sauce', 'Recipe video above. Barbecue pork ribs made in the oven! It''s easy, the ribs are meltingly tender and it''s packed full of flavour from the rub, braising the ribs in cider (see Note 1 for subs!) and the homemade barbecue sauce glaze! (Note: BBQ Sauce ingredients not consistet with the video!! Editing blunder - use ingredients listed in recipe below. Need to fix video!!)', 'https://www.recipetineats.com/tachyon/2016/01/Oven-Pork-Ribs-with-Barbecue-Sauce_4.jpg', 15, 135, 150, 6, '[{"id": "ing_paprika", "quantity": {"value": 0.312, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_apples", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.25, "unit": "bottle of 500ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_molasses", "quantity": {"value": 22.5, "unit": "jar"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}]', '[{"ingredients":["2.5 tsp paprika powder","2 tsp garlic powder (sub with onion powder)","1.5 tsp onion powder (sub with garlic powder)","1 tsp cayenne pepper (omit for not spicy)","1.5 tsp dried thyme","1.5 tsp dried oregano","1.5 tsp salt","0.5 tsp black pepper"],"purpose":"Barbecue Rub for Ribs:"},{"ingredients":["2 - 2.5kg / 4 - 5lb pork ribs (2 racks)","3/4 cup sweet alcoholic apple cider (hard cider) (, or apple juice (Note 2))","1 tbsp olive oil"],"purpose":"Ribs"},{"ingredients":["1/2 cup apple cider vinegar (Note 3)","1 1/2 cups tomato ketchup (or Aussie tomato sauce)","1/2 cup water (or use remaining apple cider!)","1 1/2 tbsp molasses (, orginal (not blackstrap, Note 4))","1/3 cup brown sugar","2 tsp mustard powder","1 1/2 tsp garlic powder","2 tsp Worcestershire sauce","1 tsp salt","1 tsp black pepper","1 tsp Tabasco or cayenne pepper (optional, for spiciness)"],"purpose":"Homemade Barbecue Sauce"}]', '[{"description":"Combine the Rub ingredients and rub onto both sides of the ribs (most on meaty side). Set aside to marinate for 20 minutes (or overnight).","duration":20,"images":[],"step":1},{"description":"Preheat oven to 160°C/320°F (all oven types).","images":[],"step":2},{"description":"Place ribs on a tray in a single layer. Pour apple cider underneath the ribs, cover with foil then bake for 1 hour 30 minutes or until the meat is pretty tender (Note 5).","images":[],"step":3},{"description":"Remove from oven, turn up to 180°C/350°F. Remove foil, drizzle with olive oil, then return ribs to oven for 15 minutes or until rub becomes nice and crusty.","duration":15,"images":[],"step":4},{"description":"Line a new tray with foil then baking / parchment paper (you''ll thank me later).","images":[],"step":5},{"description":"Remove ribs from oven, transfer to lined tray. Pour any juices from tray over the ribs.","images":[],"step":6},{"description":"Flip ribs so the bonier side is up. Slather with Barbecue Sauce, then bake 10 minutes.","images":[],"step":7},{"description":"Remove from oven, then turn ribs over so the meaty side is up. Slather with Barbecue Sauce, bake 5 minutes. Repeat 2 or 3 more times until you''ve got a thick glaze on the ribs.","images":[],"step":8},{"description":"Cut ribs into individual or multiple rib portions and serve with remaining Barbcue Sauce!","images":[],"step":9},{"description":"Place all ingredients in a saucepan and simmer over medium heat, stirring occasionally, for 45 minutes or until thickened.","duration":45,"images":[],"step":10},{"title":"Adjust to taste","description":"sweetness with brown sugar / honey, salt and sour with vinegar. Use for glazing ribs and as a sauce for serving.","images":[],"step":11}]', '["mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["American"],"categories":["australia-day","grilling-ideas-and-recipes","iconic-dishes","most-popular","pork-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ff3cad72a151', 'en', 'US', 'Aussie Meat Pie recipe', 'Recipe video above. The great Australian meat pie - made at home! Buttery shortcrust base filled with slow cooked fall apart chunky beef smothered in a rich gravy, topped with puff pastry. Legendary! {See notes for beef mince version}Also see the Family Size Meat Pie, mini Party Pies and Sausage Rolls!', 'https://www.recipetineats.com/tachyon/2019/04/Meat-Pies_3.jpg', 40, 220, 260, 6, '[{"id": "ing_batches_homemade_shortcrust_pastry", "quantity": {"value": 1.5, "unit": "pack"}}, {"id": "ing_frozen_shortcrust_pastry_sheets_thawed", "quantity": {"value": 3.0, "unit": "pack"}}, {"id": "ing_refrigerated_pie_crusts", "quantity": {"value": 2.0, "unit": "pack"}}, {"id": "ing_frozen_puff_pastry_sheets_just_thawed", "quantity": {"value": 3.0, "unit": "pack"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_beef", "quantity": {"value": 1.25, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.2, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.2, "unit": "jar of 50g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}]', '[{"ingredients":["1 1/2 batches homemade shortcrust pastry","3 frozen shortcrust pastry sheets, thawed (300g/10oz)","2 refrigerated pie crusts (US/Can)"],"purpose":"Pie Base – Choose ONE (Note 1):"},{"ingredients":["3 frozen puff pastry sheets, just thawed (300g/10oz) (Note 2)","1 egg (, lightly whisked)"],"purpose":"Pie Lid:"},{"ingredients":["1.25 kg / 2.5lb beef chuck (, 2.5cm/1\" cubes (Note 3))","1/2 tsp each salt & pepper","2 - 3 tbsp olive oil","1 onion (, diced)","4 garlic cloves (, minced)","5 tbsp flour (, plain/all purpose)","1 1/4 cups (315 ml) beef stock, low sodium (Note 4)","3 cups (750 ml) red wine (, dry full bodied (Note 5))","2 tbsp tomato paste","1 tsp Worcestershire sauce","2 tsp black pepper (, coarsely ground)","2 bay leaves"],"purpose":"Filling:"}]', '[{"description":"Sprinkle beef with 1/2 tsp salt and pepper.","images":[],"step":1},{"description":"Heat 1 tbsp oil in a large heavy based pot over high heat. Add 1/3 of the beef and brown aggressively all over, then remove. Repeat with remaining beef, adding more oil if needed.","images":[],"step":2},{"description":"Turn stove down to medium high. Add garlic and onion, cook 3 minutes.","images":[],"step":3},{"description":"Add flour, stir through.","images":[],"step":4},{"description":"Slowly add beef stock while stirring constantly. Once flour is dissolved, add wine, tomato paste, Worcestershire, pepper and bay leaves.","images":[],"step":5},{"description":"Return beef into pot, cover with lid, adjust heat so it''s simmering gently.","images":[],"step":6},{"description":"Simmer 1 hr 45 minutes. Remove lid, increase heat slightly and simmer 30 - 45 minutes, stirring regularly, or until beef is fork tender and liquid reduces down to a thickish gravy, just about covering beef (see video). Do not reduce liquid too much - thickens more as it cools & in pie.","images":[],"step":7},{"description":"Remove from stove, cover and cool filling (I usually leave overnight).","images":[],"step":8},{"description":"Preheat oven to 180C/350F.","images":[],"step":9},{"description":"Cut out 6 rounds from the shortcrust pastry, then drape pastry into pie tins - don''t stretch and pull pastry, causes shrinkage. (Notes 1 & 6)","images":[],"step":10},{"description":"Place pies on tray. Top each pie with large sheets of parchment / baking paper and fill with pie weights (Note 7).","images":[],"step":11},{"description":"Bake 20 minutes, remove, then use paper overhang to carefully remove pie weights.","images":[],"step":12},{"description":"Return crusts into oven for 5 minutes or until base is light golden and dry (can skip, Note 8). Remove from oven.","duration":5,"images":[],"step":13},{"description":"Fill pies with cooled filling, push down to fill. Should be slightly mounded.","images":[],"step":14},{"title":"Cut rounds from partially thawed puff pastry","description":"cut them slightly larger than the edge of the cooked pastry bases.","images":[],"step":15},{"description":"Brush edge of pie crusts with egg, then place lid on filling, pressing edges to seal puff pastry to the shortcrust pastry.","images":[],"step":16},{"description":"Brush lids with egg, then cut a 1cm / 0.5\" incision in the middle using a small knife.","images":[],"step":17},{"description":"Bake 30 minutes or until deep golden and puffed.","images":[],"step":18},{"description":"Devour hot and fresh, topped with tomato sauce or ketchup if desired!","images":[],"step":19}]', '["egg","gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Australian"],"categories":["australia-day","beef-recipes","iconic-dishes","quiches-tart-and-pie-recipes","slow-cooked-fall-apart"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8cbd643628e5', 'en', 'US', 'Prawn Mango Avocado Summer Salad with Lime Dressing', 'Recipe video above (useful tips for chopping mango and avo). Prawns, Mango and Avocado are a magical combination! This summer salad is fresh and healthy, yet satisfying to have as a meal or great for sharing! Make this with: rice, quinoa, risoni/orzo or pearl couscous.', 'https://www.recipetineats.com/tachyon/2019/01/Prawn-Avocado-Mango-Salad-with-Lime-Dressing_2.jpg', 15, 10, 25, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.75, "unit": "pack of 500g"}}, {"id": "ing_shrimp", "quantity": {"value": 300.0, "unit": "kg"}}, {"id": "ing_mango", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_rocket_arugula", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["2.5 cups cooked risoni/orzo or similar (Note 1)","300 – 400g / 10 – 12 oz cooked peeled prawns / shrimp (~750g unpeeled whole cooked)","1 large mango (, cut 1.5cm / ½” pieces)","1 large ripe avocado (, cut 1.5cm / ½” pieces )","75 g / 2.5 oz rocket / arugula (, roughly chopped (Note 2))","250 g / 8oz cherry tomatoes (, halved)","1/2 red onion (, finely sliced)","1/4 cup coriander / cilantro leaves (, finely chopped (Note 2))"],"purpose":"Salad:"},{"ingredients":["4 tbsp (60 ml) extra virgin olive oil","2 tbsp (30 ml) lime juice ((fresh), plus more to taste)","1 small garlic clove (, minced)","1/2 tsp salt","1/4 tsp black pepper"],"purpose":"Lime Dressing:"}]', '[{"description":"Shake Dressing in a jar.","images":[],"step":1},{"title":"Chop prawns into 1.75","description":"2 cm / 2/3” pieces.","images":[],"step":2},{"description":"Place all Salad Ingredients in a bowl, pour over dressing. Toss very gently using rubber spatula. Adjust to taste with more lime if desired. Serve immediately!","images":[],"step":3}]', '["shellfish"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["australia-day","dietary","dinner-tonight","easter-brunch-recipes","easter-sides-fresh-light","gluten-free-recipes","main-dishes","mains","no-cook-food","pasta-salads-and-rice-salads","prawns-shrimp","quick-and-easy","salad-recipes-main-course","seafood-recipes","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_36772bb70b27', 'en', 'US', 'Marinated Beef Kebabs', 'Recipe video above. Using a marinade infuses the beef with flavour as well as tenderising so you''ll have juicy steak pieces even if you opt for a more economical cut of beef. Use the reserved marinade to baste the kebabs as they cook for extra flavour! Buy the beef in a block so you can cut them into large cubes. Marinading time - 24 hours will give you the best results (most tender beef), though even 3 hours is better than not marinating at all. Makes 8 skewers.', 'https://www.recipetineats.com/tachyon/2018/07/Beef-Kabobs_2.jpg', 15, 8, 23, 8, '[{"id": "ing_beef_steak", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_mushroom", "quantity": {"value": 16.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.15, "unit": "bottle of 250ml"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_skewers", "quantity": {"value": 16.0, "unit": "pack of 50"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_pink_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}]', '[{"ingredients":["750g / 1.5 lb rump (picanha), beef tri-tip, sirloin steak or other steak cut (suitable for quick cooking (Note 1))","3 capsicum / bell peppers (red, yellow green)","1 large red onion","16 small mushrooms (, 3.25cm / 1.3\" wide)"]},{"ingredients":["1 tsp minced garlic (2 large garlic clove)","1 tsp onion powder (or sub with garlic powder)","2 1/2 tbsp soy sauce (Note 2)","2 tbsp Worcestershire sauce","2 tbsp balsamic vinegar","1 tbsp vegetable oil (or other neutral flavoured oil)","1/4 tsp black pepper"],"purpose":"Marinade:"},{"ingredients":["16 flat metal skewers (, 25 - 30cm / 10 - 12\" (Note 3))","Olive oil (, for drizzling and cooking)","Finely chopped parsley (, garnish (optional))"],"purpose":"Cooking:"},{"ingredients":["Pink sauce (, pictured in post - Note 4)","Lemon Yogurt Sauce (this goes well with the flavours here)"],"purpose":"Optional sauce:"}]', '[{"description":"Cut the beef into 3.25cm / 1.3\" wide cubes.","images":[],"step":1},{"title":"Marinade","description":"Mix Marinade in a bowl. Add beef. Marinate for 3 - 24 hours.","images":[],"step":2},{"description":"Making the kebab skewers","images":[],"step":3},{"description":"Cut capsicum and onion into 3.25cm / 1.3\" wide squares.","images":[],"step":4},{"description":"Thread beef (reserve Marinade), vegetables and mushrooms on each skewer. I use 2 pieces of vegetables between each piece of beef. Thread loosely - don''t smush together tightly (helps even cooking).","images":[],"step":5},{"description":"Brush kebabs lightly with Reserved Marinade (including vegetables), then drizzle with olive oil.","images":[],"step":6},{"title":"Cook and baste","description":"Heat BBQ or large skillet over high heat. Add 1 tbsp oil, then when smoking, cook kebabs in batches for 2 minutes on each side until slightly charred (4 sides = 8 minutes in total), basting with Reserved Marinade as you go.","duration":2,"images":[],"step":7},{"title":"Rest and serve","description":"Transfer to plate, cover loosely with foil and rest for 3 minutes before serving. Garnish with parsley if desired. See note for pictured Pink Dipping Sauce.","duration":3,"images":[],"step":8}]', '["gluten","milk","soy"]', '["high_protein","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mediterranean","Western"],"categories":["australia-day","beef","beef-recipes","grilling-ideas-and-recipes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b8ee823f83ca', 'en', 'US', 'Hamburger Recipe', 'Recipe video above. All you need for great beef hamburgers is decent beef and lots of salt and pepper. This is the way it''s done by all the grilling masters like Bobby Flay, and your favourite diners!', 'https://www.recipetineats.com/tachyon/2016/02/Beef-Hamburgers_7-2.jpg', 15, 20, 35, 4, '[{"id": "ing_beef", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.005, "unit": "jar of 200g"}}, {"id": "ing_french_fries", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["800g - 1kg / 1.6 - 2 lb ground beef (mince), 20%+ fat (Note 1)","Salt and pepper","3 onions, peeled and sliced into rings","2 tbsp oil","4 - 8 slices cheese of choice, I use Swiss (optional)"],"purpose":"Hamburger Pattie"},{"ingredients":["4 soft hamburger buns, lightly toasted","Lettuce, tomato slices","Ketchup, mustard, relish, sliced pickles"],"purpose":"Hamburger"},{"ingredients":["French fries","Baked potato wedges"],"purpose":"On the side"}]', '[{"description":"Separate beef into 4 equal portions. Use hands to lightly form into patties the size of your buns (mine are about 10 cm / 4\") - don''t press hard, light fingers = soft juicy patties (see video for how I do this).","images":[],"step":1},{"description":"Season generously with salt and pepper on both sides. Make a dent on one side (stop burger from become dome shape and shrinking when cooking).","images":[],"step":2},{"description":"Heat 1 tbsp oil in a heavy based skillet or BBQ over high heat. Add onion and cook until wilted and caramelised. Season with salt and pepper, then remove.","images":[],"step":3},{"description":"Heat 1 tbsp oil until smoking. Add patties and cook for 2 minutes until deep golden with a great crust. Do not press! Flip carefully, cook for 1 minute then top with cheese (if using). Cover with lid and cook for further 1 minute until cheese is melted.","duration":2,"images":[],"step":4},{"description":"Meanwhile, toast the cut side of the buns lightly.","images":[],"step":5},{"title":"To serve","description":"Spread base of buns with sauce / condiment of choice. Top with lettuce then tomato, then hamburger patty. Pile over onions, sliced pickles, then more sauce/condiments. Top with lid of bun. Serve immediately.","images":[],"step":6}]', '["milk","mustard"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["australia-day","beef-mince-recipes","beef-recipes","burger-recipes","dietary","dinner-tonight","gluten-free-recipes","grilling-ideas-and-recipes","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1ad0e830bdbe', 'en', 'US', 'Slow Cooker Beef Brisket with BBQ Sauce', 'Video above. Beef brisket slow cooked until tender, then finished in the oven to get that gorgeous caramelisation, basted with a homemade BBQ Sauce that the brisket is cooked in. Slice it and serve as part of a hearty Southern style supper or pile it up high on sliders!', 'https://www.recipetineats.com/tachyon/2017/07/Slow-Cooker-BBQ-Beef-Brisket-1-1.jpg', 15, 600, 615, 8, '[{"id": "ing_beef_brisket", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.019, "unit": "jar of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.25, "unit": "bottle of 500ml"}}, {"id": "ing_ketchup", "quantity": {"value": 0.45, "unit": "bottle of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}]', '[{"ingredients":["1.5 – 2 kg / 3 – 4 lb beef brisket (Note 1)","1 tbsp olive oil (or a neutral oil like vegetable, canola)"]},{"ingredients":["1 tbsp brown sugar","2 tsp paprika powder","1 tsp onion powder","1 tsp garlic powder","1/2 tsp cumin powder","3/4 tsp mustard powder","1 tsp salt","1/2 tsp black pepper"],"purpose":"Rub:"},{"ingredients":["2 garlic cloves (, minced)","1/2 cup / 125 ml apple cider vinegar","1 1/2 cups / 375 ml ketchup","1/2 cup / 110g brown sugar (, packed)","2 tsp EACH black pepper, onion powder, mustard powder","1 tsp cayenne pepper (adjust to taste re: spiciness)","1 tbsp Worcestershire sauce"],"purpose":"BBQ Sauce:"}]', '[{"description":"Mix Rub ingredients. Rub all over brisket. If time permits, leave for 30 minutes – 24 hours in the fridge, but I rarely do this.","duration":30,"images":[],"step":1},{"description":"Combine BBQ Sauce ingredients in a slow cooker. Mix then add the brisket – squish it in if needed, like I did (see video).","images":[],"step":2},{"description":"Slow cook in slow cooker for 8 hours (1.5 kg / 3 lb) to 10 hours (2 kg / 4 lb). (Note 2 for pressure cooker and click here for oven)","images":[],"step":3},{"description":"Remove brisket onto a tray.","images":[],"step":4},{"description":"Pour liquid in slow cooker into a saucepan. Bring to simmer over medium high heat and reduce until it thickens to a syrup consistency (it thickens more as it cools).","images":[],"step":5},{"description":"Meanwhile, drizzle brisket with oil then roast in a 200C/390F oven for 15 minutes until brown spots appear. Remove then baste generously with Sauce, then return to oven for 5 minutes. Remove and baste again, then return to oven for 5 – 10 minutes until it caramelises and looks like the photos. (See note for BBQ option)","duration":15,"images":[],"step":6},{"title":"TO SERVE","description":"Slice brisket thinly across the grain and serve with remaining BBQ Sauce. This is terrific served as a meal with sides or piled high onto rolls with Coleslaw as sliders. See Note 3 for more ideas.","images":[],"step":7}]', '["mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["American","Southern"],"categories":["australia-day","beef","beef-recipes","iconic-dishes","main-dishes","mains","quick-and-easy","sandwiches-and-sliders","slow-cooked-fall-apart","slow-cooker-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_37eb94fd3e20', 'en', 'US', 'Slow Cooked Lamb Shawarma', 'This meltingly tender Slow Cooked Shawarma is the stuff food dreams are made of!! Slathered in a deceptively simple shawarma spice rub then slow cooked until fall apart, the flavour and fragrance of this lamb is absolutely heavenly. Make this Middle Eastern speciality with lamb shoulder or lamb leg. Finishing on the BBQ is optional - ideal for reheating if making ahead / summer BBQ''s! SLOW COOKER directions added in notes. Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2018/01/Lamb-Shawarma_4.jpg', 10, 210, 220, 6, '[{"id": "ing_lamb", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cardamon", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}]', '[{"ingredients":["2kg / 4 lb lamb shoulder (bone in) or 1.7 kg / 3.5 lb butterflied lamb leg (Note 1)"]},{"ingredients":["3 garlic cloves (, minced)","1 tbsp ground coriander","1 tbsp ground cumin","1 tbsp ground cardamon","1 tsp cayenne pepper (1/2 tsp = not spicy)","2 tsp smoked paprika (ordinary also ok)","1 1/2 tsp salt","1/2 tsp black pepper","1/4 cup / 65 ml extra virgin olive oil","2 - 3 tbsp / 40 - 60 ml lemon juice"],"purpose":"Shawarma Paste:"},{"ingredients":["2 cups / 500 ml water"],"purpose":"Cooking:"}]', '[{"description":"Preheat oven to 180C/350F (standard) or 160C/320F (fan forced / convection).","images":[],"step":1},{"description":"Place Paste ingredients in a bowl, starting with 2 tbsp lemon juice, and mix. It should be a wet paste that can be slathered onto the lamb (see video).","images":[],"step":2},{"description":"Place lamb in a large roasting pan. Slather all over with paste. Optional: Marinate 24 hours (not mandatory, I usually skip).","images":[],"step":3},{"description":"Position the lamb with the fat side up. Pour water around, cover tightly with foil.","images":[],"step":4},{"title":"Roast 3 hours, removing from the oven 2","description":"3 times to spoon over pan juices (ie baste).","images":[],"step":5},{"title":"Remove foil. Meat should be tender","description":"check with 2 forks.","images":[],"step":6},{"description":"Baste again, then return to oven for 30 minutes to get a nice crust.","duration":30,"images":[],"step":7},{"title":"Remove lamb from roasting pan","description":"reserve juices.","images":[],"step":8},{"description":"Finish on BBQ, Optional (Note 2):","images":[],"step":9},{"description":"Cool the lamb for 20 minutes or so (so it firms up slightly, easier to handle).","duration":20,"images":[],"step":10},{"description":"If you used shoulder, pull the meat off the bone in 4 or 5 chunks (see video).","images":[],"step":11},{"description":"Preheat BBQ to medium and oil if required.","images":[],"step":12},{"description":"Coat lamb in pan juices. Sear on both sides until deep golden and a crust forms. Dab with pan juices on both sides.","images":[],"step":13},{"description":"Slice or shred lamb, as desired. Drizzle with plenty of juices.","images":[],"step":14},{"description":"Make Lamb Shawarma wraps by serving with shredded lettuce, tomatoes and minted yoghurt (Note 3) or pile over Lemon Herbed Couscous (Note 4) and garnish with pomegranate seeds and parsley or chopped coriander/cilantro (if desired). Both pictured in post.","images":[],"step":15}]', '[]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["australia-day","cuisines","dietary","easter-mains","easter-recipes","gluten-free-recipes","grilling-ideas-and-recipes","iconic-dishes","lamb-recipes","main-dishes","middle-eastern-recipes","quick-and-easy","roast-lamb","roasts","slow-cooked-fall-apart","slow-cooker-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9d63ee5aedd4', 'en', 'US', 'Doner Kebab recipe', 'Recipe VIDEO above. A homemade version of the chicken kebab rolls you get at your favourite kebab shop! It tastes remarkably similar to the kebab shop chicken meat. I oven bake it, but imagine it rotisserie style over the BBQ or charcoal! You will need 4 long metal skewers for this, around 30cm / 12" long.', 'https://www.recipetineats.com/tachyon/2017/11/Chicken-Doner-Kebab-1.jpg', 20, 55, 1515, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_hummus", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_tabbouleh", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 7.5, "unit": "pack of 1kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_mejadra_for_kebab_plate", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["1 kg / 2 lb chicken thighs (, skinless and boneless (Note 1))","Olive oil (, for drizzling)"]},{"ingredients":["1 cup plain yoghurt (, unsweetened (I use Greek))","3 garlic cloves minced","1 1/2 tsp coriander powder","2 tsp cumin powder","2 tsp paprika","1 tsp cayenne pepper (, optional)","1 1/2 tsp onion powder","1/2 tsp black pepper","2 1/2 tbsp tomato paste","1 1/2 tsp cooking salt / kosher salt","1 tbsp lemon juice (substitute apple cider vinegar)","2 tbsp olive oil"],"purpose":"Marinade:"},{"ingredients":["Lebanese bread / flatbreads / pita bread (, warmed)","Finely sliced iceberg lettuce","Tomato slices","Hummus (or Note 2 for simple Yoghurt Sauce)","Tabbouleh (optional, Note 3)","Red onion slices","Shredded cheese","Chilli Sauce (I use Sriracha, it''s perfect)","Mejadra ((Middle Eastern Rice with Lentils), for Kebab Plate)"],"purpose":"For Serving (choose):"}]', '[{"title":"Marinade","description":"Mix Marinade in a large bowl. Add chicken and mix to coat well. Cover and marinate in the fridge for a minimum of 3 hours, 24 hours is ideal. If only 3 hours, add an extra 1/2 tsp salt.","images":[],"step":1},{"description":"Preheat oven to 220°C / 430°F (200°C fan-forced).","images":[],"step":2},{"description":"Choose a pan of a size such that the skewers will stay propped up on the pan walls (see photos in post or video) and the chicken will be elevated off the base. Line with foil.","images":[],"step":3},{"title":"Thread onto skewers","description":"Remove chicken from fridge. Divide the chicken into 2 piles. Take one piece of chicken, fold in half then thread onto two skewers (see video). Repeat and push the chicken snugly up against each other. Repeat with other skewer.","images":[],"step":4},{"description":"Prop the 2 skewers on the edges of the baking pan. Drizzle surface with oil.","images":[],"step":5},{"description":"Bake for 35 minutes or until the surface is golden with some charred bits (char is good!). Spoon the pan juices over the chicken. Turn, drizzle with oil and bake for a further 20 minutes. If you want more colour, oven grill/broil for a few minutes on high (I don''t do this).","duration":35,"images":[],"step":6},{"title":"Rest 5 minutes","description":"Baste again with pan juices and stand for 5 minutes.","duration":5,"images":[],"step":7},{"title":"Carving","description":"Stand the skewers upright or on an angle, and slice meat fairly thinly. Use to make Doner Kebabs or Kebab Plates.","images":[],"step":8},{"description":"Making Doner Kebabs rolls:","images":[],"step":9},{"description":"Place a lebanese bread (or pita bread or other flatbread) on a piece of foil. Spread with a generous dollop of Hummus (or yoghurt sauce - Note 2). Top with shredded lettuce, slices of tomato, Tabbouleh (for a truly authentic experience! Note 3), cheese (I usually go this) and Chicken. Drizzle with chilli sauce if desired (I use Sriracha, it''s perfect).","images":[],"step":10},{"description":"Roll up tightly and wrap in foil. Consume and be happy!","images":[],"step":11},{"description":"Serve chicken with Mejadra (Middle Eastern Spiced Rice with Lentils), shredded lettuce, tomatoes, slices of red onion, tabbouleh, dollop of hummus. Optional to serve flatbread / lebanese bread on the side.","images":[],"step":12}]', '["gluten","milk"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Turkish"],"categories":["australia-day","chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","mediterranean-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e45e5e8ae8a5', 'en', 'US', 'Ripper Beef Nachos', 'The nachos cheese sauce takes 5 minutes to make and will take your nachos to the next level, ensuring even coverage of cheese goodness over every chip! You can substitute the homemade Nachos Seasoning with 1 packet store bought taco seasoning.', 'https://www.recipetineats.com/tachyon/2016/01/Beef-Nachos_2b.jpg', 20, 15, 35, 8, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_corn", "quantity": {"value": 0.992, "unit": "can of 400g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_quantity_proper_guacamole", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_quantity_pico_de_gallo", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves","1/2 onion (, finely chopped)","1 lb / 500g ground beef (mince)","2 tbsp tomato paste","2 tbsp water"],"purpose":"Beef"},{"ingredients":["1 tsp each onion powder ((Note 1), dried oregano, salt)","2 tsp each dried cumin powder (, paprika)","1/4 tsp cayenne pepper (, or to taste)"],"purpose":"Nachos Seasoning"},{"ingredients":["14 oz / 400g corn chips (, good quality (Note 2))","2 cups grated cheese (cheddar, tasty, gruyere, Monterey Jack)","1 quantity Nachos Cheese Sauce (, warm (Note 3))"],"purpose":"Nachos"},{"ingredients":["Sliced scallions / shallots","1 quantity Proper Guacamole (, Restaurant Style)","1 quantity Pico de Gallo (Note 4)","Sour cream"],"purpose":"Sides/Garnish"}]', '[{"title":"Beef","description":"Heat oil in a skillet over high heat. Add garlic and onion, cook until translucent. Add beef and cook, breaking it up as you go. Once beef is cooked, add Nachos Seasoning, tomato paste and water. Cook for a further 2 minutes, then set aside.","images":[],"step":1},{"description":"Preheat oven to 180C/350F.","images":[],"step":2},{"description":"Spread half the corn chips in a single layer on a baking tray. Drizzle over about 1 cup Nachos Cheese Sauce (see KEY TIPS in Note 3), top with 1/2 the Beef and 1/2 the grated cheese ensuring most of the Cheese Sauce is covered.","images":[],"step":3},{"description":"Spread over remaining corn chips, drizzle over remaining Nachos Cheese Sauce, Beef and grated cheese, again ensuring all the Cheese Sauce is covered.","images":[],"step":4},{"description":"Bake for 15 minutes or until cheese is melted.","duration":15,"images":[],"step":5},{"description":"Serve immediately, garnished with sliced scallions/shallots if using and with Guacamole, Pico de Galloand Sour Cream on the side.","images":[],"step":6}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Tex-Mex"],"categories":["australia-day","beef-mince-recipes","beef-recipes","dietary","gluten-free-recipes","mexican-recipes","nachos-recipes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_97f611fadbd2', 'en', 'US', 'Coconut Marinated Chicken (Grill or Stove)', 'Coconut milk is a fantastic marinade which tenderises the chicken and infuses it with rich flavour. The added bonus is that the marinade doubles as a scrumptious sauce! Cook this on your BBQ or stovetop.', 'https://www.recipetineats.com/tachyon/2015/08/Coconut-Marinated-Chicken_2-Featured.jpg', 10, 15, 25, 4, '[{"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_imes_all_the_zest_3_tbsp_of_juice", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_hot_sauce", "quantity": {"value": 0.2, "unit": "bottle of 150ml"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 can coconut milk (preferably full fat, but light is ok) (14oz/400g)","2 limes - all the zest + 3 tbsp of juice","1 tbsp mild curry powder","2 tsp paprika","1 tbsp fresh ginger (, finely grated)","3 garlic cloves (, crushed)","2 tbsp Frank''s classic hot sauce (, or other hot sauce of choice (adjust to taste) (Note 2))","3/4 tsp salt","Black pepper"],"purpose":"Marinade"},{"ingredients":["1.5 lb / 750g chicken thigh fillets (, skinless and boneless)","1 tbsp oil (for cooking)","3/4 cup water"],"purpose":"Chicken"},{"ingredients":["Fresh coriander leaves"],"purpose":"Garnish (optional)"}]', '[{"description":"Combine the Marinade ingredients in a ziplock bag. Add the chicken and set aside to marinate for at least 3 hours, preferably overnight.","images":[],"step":1},{"description":"Remove the chicken from the Marinade, shaking off the excess. Keep the Marinade for the Sauce (below).","images":[],"step":2},{"description":"Brush the BBQ with oil and heat to medium high, or heat the oil in a skillet over medium high heat.","images":[],"step":3},{"description":"Cook the chicken for around 7 minutes on the first side and 5 minutes on the second side, or until cooked through.","images":[],"step":4},{"description":"Transfer the chicken to a plate, cover loosely with foil and rest for 5 minutes.","duration":5,"images":[],"step":5},{"description":"Serve with Sauce and garnished with fresh cilantro leaves, if using.","images":[],"step":6},{"description":"Pour the marinade into a small saucepan over medium heat.","images":[],"step":7},{"description":"Add the water and bring to a simmer. Cook for at least 10 minutes, or until thickened to desired consistency. (Note 1) Transfer to a sauce bowl.","images":[],"step":8}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Tropical!"],"categories":["australia-day","chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","most-popular","quick-and-easy","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4ff74e7abbe8', 'en', 'US', 'Salmon Quiche', 'Recipe video above. The most amazing salmon quiche made with smoked salmon!! When cooked, it''s looks just like cooked normal salmon - but with better seasoning in every bite. This fills a deep dish quiche tin 23cm / 9″ diameter, 3.5 cm / 1.5″ deep. Scale down for smaller tins and prepared pie shells - see Note 1.', 'https://www.recipetineats.com/tachyon/2019/04/Salmon-Quiche_6.jpg', 20, 90, 110, 8, '[{"id": "ing_homemade_quiche_crust", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_sheets_frozen_shortcrust_pastry", "quantity": {"value": 2.0, "unit": "pack"}}, {"id": "ing_x_9_refrigerated_pie_crust", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_ready_made_pie_shell", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_butter", "quantity": {"value": 15.0, "unit": "block of 250g"}}, {"id": "ing_eek", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_pears", "quantity": {"value": 8.0, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 5.0, "unit": "carton of 12"}}, {"id": "ing_cream", "quantity": {"value": 1.5, "unit": "carton of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_dill", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_salmon_fillets", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_gruyere_cheese", "quantity": {"value": 0.75, "unit": "block of 200g"}}, {"id": "ing_salmon_fillets", "quantity": {"value": 0.2, "unit": "kg"}}]', '[{"ingredients":["1 homemade quiche crust (shortcrust pastry)","2 sheets frozen shortcrust pastry","1 x 9\" refrigerated pie crust (, fitted in a 9\" pie dish or tart tin)","1 ready made pie shell (23cm / 9\", fridge or frozen)"],"purpose":"Quiche Crust – choose one (Note 1):"},{"ingredients":["15g / 1 tbsp butter (, unsalted)","1 leek (, white part only halved and finely sliced (Note 2))","2 garlic cloves (, minced)","8 - 10 asparagus spears","5 eggs (~55 - 60g / 2oz each)","1 1/2 cups (375ml) cream (, full fat (Note 3))","1/4 tsp salt + pinch pepper","2 tbsp fresh dill (, roughly chopped (Note 4))","200g / 7 oz smoked salmon (, cut into 4cm / 1.7\" pieces (Note 5))","3/4 cup (75g) gruyere cheese (, grated (Note 6))"],"purpose":"Quiche Filling:"},{"ingredients":["Dill sprigs and extra smoked salmon"],"purpose":"Decorations (optional)"}]', '[{"description":"Quiche Crust (Note 1):","images":[],"step":1},{"title":"Homemade quiche crust or frozen shortcrust pastry","description":"prepare and bake the crust per Quiche Crust recipe.","images":[],"step":2},{"title":"Refrigerated pie crust","description":"unroll, fit into a 9\" pie dish or tart tin. Bake per packet directions.","images":[],"step":3},{"title":"Prepared pie shell (ie comes in foil dish)","description":"bake per packet directions, scale Filling down to 4 eggs (Note 1).","images":[],"step":4},{"description":"Preheat oven to 180C/350F (160C/320F fan forced).","images":[],"step":5},{"description":"Place cooked quiche crust on a tray.","images":[],"step":6},{"title":"Asparagus","description":"break woody ends off (Note 7). Cut into 3.5cm / 1.5\" pieces, separate tips from stems (tips for decorating).","images":[],"step":7},{"description":"Melt butter in a skillet over medium heat. Add leeks and garlic, saute for 2 minutes or until leeks are translucent, don''t let them go golden.","duration":2,"images":[],"step":8},{"description":"Stir in asparagus stems (don''t cook), then remove from stove.","images":[],"step":9},{"description":"Cool slightly then scatter across base of quiche crust.","images":[],"step":10},{"description":"Whisk together eggs, cream, dill, salt, pepper in a bowl.","images":[],"step":11},{"description":"Scatter 2/3 of the salmon across quiche, folding/twisting pieces rather than laying flat.","images":[],"step":12},{"description":"Top with cheese, pour over egg mixture.","images":[],"step":13},{"description":"Top with remaining salmon and asparagus tips.","images":[],"step":14},{"description":"Bake for 40 minutes or until top is light golden and centre is set but still slightly jiggly when you poke it.","duration":40,"images":[],"step":15},{"description":"Rest for 10 minutes before carefully removing from tin and slicing.","duration":10,"images":[],"step":16}]', '["egg","fish","milk"]', '["gluten_free"]', '{"mealType":["breakfast","dinner"],"cuisine":["Western"],"categories":["baking-recipes","easter-brunch-recipes","easter-recipes","egg-recipes","fish-recipes","quiches-tart-and-pie-recipes","salmon-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d6966578a8fb', 'en', 'US', 'Quiche Crust / Shortcrust Pastry for Pies', 'Recipe video above. This is a recipe for quiche and pie crusts, both of which are made using shortcrust pastry. This is a great, EASY classic quiche crust. Quiche crusts are just made with shortcrust pastry. Made using a food processor, very slightly adapted from this recipe by Emeril Lagasse.Inactive chill time: 1 hour. This is the recipe I''ve been using for years and years, and it has never failed me! Makes pastry for 1 x 23cm / 9" pie dish or tart tin (serves 8 - 12 people).', 'https://www.recipetineats.com/tachyon/2019/04/Quiche-Crust_4.jpg', 15, 35, 50, 8, '[{"id": "ing_flour", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}]', '[{"ingredients":["1 1/4 cups (185g / 5.6 oz) plain white flour (all purpose flour)","1/2 tsp salt","100g / 7 tbsp unsalted butter, cold, cut into 1cm/ 1/3\" cubes","3 tbsp ice cold water (+ more as required)"]}]', '[{"description":"Place flour, salt and butter in a food processor.","images":[],"step":1},{"description":"Pulse 10 times or until it looks like breadcrumbs.","images":[],"step":2},{"description":"With the motor running on low, pour 2.5 tbsp of water into the tube feeder.","images":[],"step":3},{"description":"Turn up to high and blitz for 30 seconds or until it turns into a ball of dough. Initially it will look like breadcrumbs, then it will turn into a ball of soft dough - some random escaped bits is fine. If it doesn''t look like its coming together at 20 seconds, add another 1/2 tbsp of water. Don''t blitz longer than 30 seconds at most.","duration":0.5,"images":[],"step":4},{"description":"Form a disc, wrap in cling wrap. If there are escaped crumble bits, that''s fine - just press them in. Refrigerate for 1 - 3 hours.","images":[],"step":5},{"description":"Preheat oven to 200C/390F (standard) or 180C/350F (fan forced)","images":[],"step":6},{"description":"Sprinkle work surface with flour, unwrap dough and place on the flour. Sprinkle top with flour, then roll out into a 27cm/11\" round.","images":[],"step":7},{"description":"Gently roll the pastry so it wraps around the rolling pin.","images":[],"step":8},{"title":"Unroll it over the quiche pan or pie dish","description":"23cm / 9\".","images":[],"step":9},{"description":"Press the pastry into the edges of the quiche pan, patching up edges if required (if pastry doesn''t quite reach top of rim).","images":[],"step":10},{"description":"Roll the rolling pin across the top to cut off the excess pastry.","images":[],"step":11},{"title":"Optional extra \"safe measure\" refrigeration","description":"15 minutes. See (Note 2).","images":[],"step":12},{"description":"Place a large piece of parchment paper over the pastry, then fill with baking beads or lots of rice or dried beans to weigh it down. (Note 3)","images":[],"step":13},{"description":"Bake for 20 minutes, then remove from oven.","duration":20,"images":[],"step":14},{"description":"Turn oven DOWN to 180C/350F (or 160C/320F fan).","images":[],"step":15},{"description":"Use excess paper to CAREFULLY remove hot beads, then return to oven for 10 minutes or until base is light golden.","duration":10,"images":[],"step":16},{"description":"Remove from oven and fill with chosen Quiche Filling. Quiche Lorraine, Salmon Quiche, Italian Sausage or your other filling of choice.","images":[],"step":17},{"description":"The pastry will not be 100% cooked, it finishes cooking with the filling. It''s cooked enough so the crust will not go soggy.","images":[],"step":18}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["baking-recipes","quiches-tart-and-pie-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7c446c04df7a', 'en', 'US', 'Crispy Pork Belly Banh Mi', 'Recipe video above. The crispy pork belly version of the famous Vietnamese sandwich, inspired by Ca Com in Melbourne, a famous banh mi shop. Hands down one of the best sandwiches I have ever made in my life, and my favourite type of banh mi (all my recipes here). Excellent food for sharing with friends and Sunday lunches.The Special Sauce is a copycat of the Ca Com sauce and it''s an excellent match for crispy pork - thicker so it clings and doesn''t soak and soften the skin or bread.PS The recipe for the crispy skin pork belly is based on the much-loved Crispy Pork Belly recipe. So you can have confidence that your pork WILL have perfect crispy crackling!', 'https://www.recipetineats.com/tachyon/2024/03/Crispy-pork-belly-banh-mi_3.jpg', 15, 180, 195, 5, '[{"id": "ing_pork", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_chinese_five_spice", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_hoisin_sauce", "quantity": {"value": 60.0, "unit": "bottle"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.113, "unit": "can of 400ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.01, "unit": "bottle of 250ml"}}, {"id": "ing_bread", "quantity": {"value": 5.0, "unit": "loaf"}}, {"id": "ing_chicken", "quantity": {"value": 0.12, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.225, "unit": "jar of 400g"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 1.2, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}]', '[{"ingredients":["1kg / 2 lb pork belly with skin on","1 1/2 tsp canola or vegetable oil (, divided)","1/2 tsp Chinese Five Spice (, optional (you won''t miss it))","1 tsp cooking/kosher salt (, divided)","1/4 tsp black pepper (or white pepper)"],"purpose":"Crispy pork belly for banh mi"},{"ingredients":["4 tbsp Hoisin sauce","3 tbsp coconut milk (, full fat)","1/2 tsp dark soy sauce (mainly for colour, sub light or regular soy)"],"purpose":"Special banh mi sauce (Ca Com copy!)"},{"ingredients":["5 crusty white rolls (lightly oven toast to crisp if crust is softened)","120g/ 4 oz chicken pate (Note 2)","6 tbsp whole-egg mayonnaise (or Kewpie)","1 batch Vietnamese pickled carrots and daikon ()","3 green onion stems (, cut to length of rolls (2 to 3 pieces per roll))","2 cucumbers (, finely sliced using vegetable peeled or knife)","2 cups coriander/cilantro leaves (and small sprigs)","3 Birds Eye or Thai chillis (, finely sliced)","8 tbsp crispy fried shallots (, store bought (Note 3))"],"purpose":"To make the banh mi (5 rolls)"}]', '[{"description":"Crispy pork belly for banh mi","images":[],"step":1},{"title":"Dry skin overnight","description":"Place pork belly on a plate. Pat skin dry with paper towels. Leave uncovered in fridge overnight to dry out the skin. (If you don''t have time, pat the skin dry as best you can).","images":[],"step":2},{"description":"Preheat oven to 140°C/285°F (both fan and standard ovens).","images":[],"step":3},{"title":"Season flesh","description":"Drizzle flesh side with 1 tsp oil. Sprinkle over 1/2 tsp salt, and all the pepper and Chinese five spice. Rub all over the flesh, including on the sides.","images":[],"step":4},{"title":"Foil boat","description":"Place 2 pieces of foil on a work surface. Put the belly in middle of foil, skin side up. Fold the sides in to enclose the belly, forming an open box, pinching corners to seal tightly and make it as snug as possible. Place meat on a tray.","images":[],"step":5},{"title":"Season skin","description":"Pat skin dry with paper towels. Rub with 1/2 tsp oil then sprinkle remaining 1/2 tsp salt evenly all over the skin surface, from edge to edge.","images":[],"step":6},{"title":"Slow roast 2 hours","description":"Place in the oven and roast for 2 hours, tightening the foil around the pork after 1 hour (the pork will shrink). This protects the flesh from drying out.","images":[],"step":7},{"title":"Increase heat","description":"Remove pork from oven, then increase heat to 240°C/465°F (all oven types).","images":[],"step":8},{"title":"Level pork","description":"Remove pork from foil, discard fat and foil. Place pork on a rack set over a tray. Use scrunched up balls of foil stuffed under pork to prop it up so the skin surface is as level and horizontal as possible (see photos in post).","images":[],"step":9},{"description":"30 minutes blast! Place the pork back in the oven for 30 minutes, rotating after 15 minutes as needed, until the crackling is deep golden, puffy and crispy all over. If some patches are browning faster, protect with foil patches.","duration":30,"images":[],"step":10},{"title":"Rest 10 minutes","description":"Remove pork from oven. Rest for 10 minutes before slicing.","duration":10,"images":[],"step":11},{"description":"Making the banh mi","images":[],"step":12},{"title":"Sauce","description":"Mix the ingredients in a bowl then set aside. This will keep for 5 days in the fridge .","images":[],"step":13},{"title":"Chop pork","description":"Cut the pork into 1 1/2 cm / 0.6\" thick slices, then each slide into 1 1/2 cm / 0.6\" chunks.","images":[],"step":14},{"title":"Split & spread","description":"Split the roll in half down the side, keeping the lid attached. Smear the base with 1 1/2 tbsp of pate, then 1 1/2 tbsp of mayonnaise (on top of the pate)","images":[],"step":15},{"title":"Stuff","description":"Pile about 1/3 cup pickled vegetables on the mayonnaise. Lay 2 slices of cucumber and 2 green onions against the lid. Pile pork on top. Drizzle pork with 1 tbsp of sauce. Stuff coriander/cilantro down the side, sprinkle with chilli then2 tablespoons of crispy shallots as you want (if using).","images":[],"step":16},{"title":"Serving","description":"Eat immediately! Banh mi is definitely one of those foods best eaten freshly made!","images":[],"step":17}]', '["egg","gluten","soy"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner","lunch"],"cuisine":["Vietnamese"],"categories":["banh-mi","iconic-dishes","modern-asian","sandwiches-and-sliders","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_db37fc0765e7', 'en', 'US', 'Charcoal Chicken Shop Chicken Skewers', 'Recipe video above. This is my copycat of those tasty Chicken Skewers sold at charcoal chicken shops all across Australia. They''re so heavily flavoured they are practically crusted with seasoning, in the best possible way! Great on the BBQ (also, you can cook them all in one go), but honestly just as good on the stove.You can cook them straight away though if you’ve got the time, an overnight marinade will take the flavour to another level.PS See Note 1 if you think this looks good but you''re feeling too lazy to skewer. :)', 'https://www.recipetineats.com/tachyon/2026/03/Kebab-shop-chicken-skewers_4.jpg', 15, 20, 35, 10, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.562, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_sauce_options", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_onion", "quantity": {"value": 15.0, "unit": "pack of 1kg"}}]', '[{"ingredients":["800g / 1.6 lb boneless chicken thighs (, cut into large 2.5cm / 1\" squares, I cut each thigh into ~6 to 8 pieces. (Note 1))","3 - 4 tbsp olive oil (, for cooking)"]},{"ingredients":["1 1/2 tbsp garlic powder (or 2 garlic cloves finely grated using microplane)","1 tbsp onion powder (or more garlic powder)","1 tbsp paprika (, regular/sweet (not spicy), smoked great too)","1 tsp mustard power (sub 1 tsp dijon or yellow mustard, not spicy)","1 tsp dried oregano (or thyme)","1/2 tsp curry powder *secret ingredient* (regular grocery stores ones, I use Clives)","1 1/4 tsp cooking salt / kosher salt (halve for table salt, +50% for flakes)","1/2 tsp black pepper","3 tbsp extra virgin olive oil","2 tbsp lemon juice (or white wine/red wine vinegar, or similar)"],"purpose":"Chicken marinade:"},{"ingredients":["Sauce options -","Flatbreads","Shredded lettuce, tomato slices (2 - 3 whole), finely sliced red onion","Shredded lettuce, tomato slices (2 - 3 whole), finely sliced red onion"],"purpose":"For serving – options"}]', '[{"title":"Mix marinade, marinate chicken 12","description":"24 hrs (if you can), skewer, cook 3 minutes on each side on medium high.","images":[],"step":1},{"title":"Marinade","description":"Mix the Marinade ingredients in a bowl, it should be like a paste. Add chicken pieces and toss well to coat every piece well.","images":[],"step":2},{"description":"Marinate for 12 to 24 hours (even 3 hours helps) though they are still tasty cooked straight away!","images":[],"step":3},{"title":"Skewer","description":"Thread the chicken pieces onto skewers. I usually do 10 to 12, with 3 to 4 pieces on each. (You could also skewer then leave skewered for marinating time, do it whichever way suits!)","images":[],"step":4},{"title":"Stove cook","description":"Heat a large non stick pan on medium high with enough oil to lightly coat the base. Cook the skewers in batches for 3 minutes on each side, controlling the heat as needed so the spices don''t burn. Transfer onto a plate, loosely cover with foil to keep warm. Wipe black bits out of the pan using a paper towel, add more oil and continue cooking.","duration":3,"images":[],"step":5},{"title":"BBQ option","description":"Brush the grills or flat plate lightly with oil. Heat on medium (or medium high, if your BBQ is not that strong). Cook skewers for 3 - 4 minutes on each side, adjusting the heat as needed so the spices don''t burn.","duration":3.5,"images":[],"step":6},{"description":"Serve the skewers with flatbreads or pita pockets, shredded lettuce, tomato and onion slices with sauce of choice (see ingredients section for options). Or make plates with a side of seasoned rice (see options above), a fresh Greek Salad and sauce of choice.","images":[],"step":7}]', '["mustard"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Aussie","Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","grilling-ideas-and-recipes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4592bdfe7ef9', 'en', 'US', 'Lamb Souvlaki', 'Recipe video above. The bold garlic-oregano Greek marinade works wonders to tenderise and infuse incredible flavour into the lamb! The flavour when this is cooking is out of this world. Eat them straight off the skewer while still hot or bundle up into warm pita bread with fixings.', 'https://www.recipetineats.com/tachyon/2023/11/Lamb-souvlaki_7.jpg', 20, 10, 30, 12, '[{"id": "ing_lamb", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_skewers", "quantity": {"value": 8.0, "unit": "pack of 50"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_vinegar", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_batch_tzatziki", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}]', '[{"ingredients":["1.2 kg/ 2.4 lb boneless lamb leg (, fat trimmed, cut into 2.5cm/1” cubes (~900g / 1.8lb after trimming) (Note 1))","1 tsp cooking / kosher salt","1/2 tsp black pepper","1 tbsp extra virgin olive oil","8 - 12 skewers (, wooden or bamboo)"]},{"ingredients":["5 garlic cloves (, finely minced)","5 tbsp lemon juice","2 tsp lemon zest","2 tsp dried oregano","3 fresh bay leaves (, crushed in hand (or 2 dried kept whole))","1/3 cup white wine vinegar","3 tbsp extra virgin olive oil","1 tsp cooking / kosher salt"],"purpose":"Lamb souvlaki marinade:"},{"ingredients":["4 - 6 pita bread","1 batch Tzatziki","Greek salad ((chop small for stuffing) or shredded lettuce and tomato slices)","Greek lemon rice (to make plates instead of wraps)"],"purpose":"To serve – stuffed or make plates:"}]', '[{"description":"Mix marinade ingredients in a bowl. Add lamb and toss to coat.","images":[],"step":1},{"title":"Marinate in fridge for 12","description":"24 hours.","images":[],"step":2},{"description":"Skewer & cook:","images":[],"step":3},{"title":"Skewer","description":"Remove meat from marinade and thread 3 to 4 pieces on each to make 12 skewers, or 5 to make 8 larger skewers (pictured in post).","images":[],"step":4},{"description":"Sprinkle the meat with the salt and pepper. (This really makes a difference to the finished dish, better than just in the marinade).","images":[],"step":5},{"title":"Cook","description":"Heat 1 tbsp olive oil in a large non-stick pan over high heat. Cook half the skewers for 3 minutes, turn then cook the other side for 3 minutes until nicely seared (target internal temp 60°C/140°F for medium rare, optimum juiciness).","duration":3,"images":[],"step":6},{"description":"Transfer to a plate and loosely cover with foil to keep warm while you cook the remaining skewers.","images":[],"step":7},{"description":"BBQ cooking (Note 2):","images":[],"step":8},{"title":"Soak skewers","description":"Soak wood/bamboo skewers in water for 30 minutes if planning to cook on the BBQ (prevents burning). My skewers are 18cm/7” which fit in a pan (stove cooking).","duration":30,"images":[],"step":9},{"description":"Preheat BBQ to medium high. Flat iron hot plate is safer for wooden skewers (so they don''t catch fire) else use metal skewers on the grill side.","images":[],"step":10},{"title":"Skewer, oil & season","description":"Skewer per above. Drizzle with the oil (so it doesn''t stick to the BBQ) then sprinkle both sides with the salt and pepper.","images":[],"step":11},{"description":"BBQ cook for 3 minutes on each side.","duration":3,"images":[],"step":12},{"description":"Serve:","images":[],"step":13},{"description":"Pile Souvlaki onto a serving platter for DIY wraps with tzatziki (from this recipe), toasted pita bread and Greek salad (chopped small), or shredded lettuce and tomato slices. Else, make plates with lemon rice and a Greek Salad!","images":[],"step":14}]', '["gluten"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["greek-recipes","grilling-ideas-and-recipes","lamb","lamb-recipes","mains","mediterranean-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_122983ed27af', 'en', 'US', 'Vietnamese Lemongrass Pork steaks (tenderised!)', 'Recipe video above. Pork infused with a Vietnamese lemongrass marinade, then cooked over high heat for an authentic char-grill like you get at Vietnamese street stalls! Economical pork shoulder is a tough cut of meat that''s tenderised using a touch of baking soda. Even if you overcook these pork steaks, they are still tender inside!Use to make the popular Vietnamese rice noodle salad, Bún thịt nướng, or serve with coconut or jasmine rice and Asian slaw for a lovely dinner.', 'https://www.recipetineats.com/tachyon/2023/04/Vietnamese-noodles-lemongrass-pork-1.jpg', 15, 6, 21, 4, '[{"id": "ing_pork_shoulder", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_lemongrass", "quantity": {"value": 40.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_lime", "quantity": {"value": 0.12, "unit": "net of 500g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.019, "unit": "tub of 200g"}}]', '[{"ingredients":["500g/1 lb pork shoulder (, skinless and boneless, or pork scotch (roast or steaks) (Note 1))","3 tbsp canola oil"]},{"ingredients":["2 lemongrass stalks (, white part only, bruised, cut into 1 cm / 0.4\" slices on angle (Note 2))","4 garlic cloves (, finely minced)","4 tbsp lime juice","3 tbsp fish sauce","1 tbsp soy sauce (all purpose or light, NOT dark soy, Note 3)","4 tbsp brown sugar (tightly packed tablespoons)","3 tbsp oil (canola, vegetable, peanut)","3/4 tsp baking soda/bi-carb (, for tenderising (Note 4))"],"purpose":"Marinade:"}]', '[{"title":"Cut pork","description":"Cut into 8 equal, thinnish slices of pork. I find it easiest using the knife on a 45° angle, but if you have the right shape piece you can just cut straight down.","images":[],"step":1},{"description":"Pound each steak to 5mm / 0.2\" thickness using the scary side of a meat mallet (jagged, not flat), using go-between (Note 5) or a freezer bag to avoid damaging the meat. (You can use baking paper for rolling pin or the flat side of the mallet.)","images":[],"step":2},{"title":"Marinade","description":"Mix the marinade ingredients in a bowl, it will fizz when the baking soda is added! Add pork then toss well to coat using tongs. Transfer to a ziplock bag and marinate for 24 hours.","images":[],"step":3},{"description":"Remove pork from the marinade and brush off the lemongrass pieces. Discard marinade - it''s done its job!","images":[],"step":4},{"title":"Cook","description":"Heat a cast iron skillet over high heat until you see wisps of smoke. Add 1 1/2 tbsp oil, then cook half the pork for 1 1/2 minutes on one side and 1 minute on the other side until nicely charred. Remove onto a plate. Scrape pan clean of loose black bits then cook the remaining pork.","images":[],"step":5},{"description":"Serve! Make Pork Noodle Bowls (bun thit nuong) or serve with rice and a side salad - see note 6 and in post for suggestions!","images":[],"step":6},{"title":"NOTE","description":"The thin pork steaks are beyond well done in 2 1/2 minutes but it doesn''t matter because the baking soda keeps them tender. It will be blushing pink inside due to the baking soda (same happens with beef). You could cook them for another 5 minutes and they will still be tender inside. Miracle!","images":[],"step":7}]', '["fish","gluten","peanuts","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["grilling-ideas-and-recipes","mains","pork","pork-recipes","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2cbbce58a9c1', 'en', 'US', 'Marinated Vegetarian Pasta Salad', 'Recipe video above! How do you make the best ever vegetable pasta salad? MARINATE the veggies. Roast or BBQ any veg you want, then toss in a marinade so they absorb the flavour while hot before mixing through pasta. This is a big, fat JUICY flavour loaded pasta salad that lasts for days and days - see PRO TIP for keeping pasta salads juicy!', 'https://www.recipetineats.com/tachyon/2019/07/Marinated-Vegetable-Pasta-Salad_6.jpg', 15, 30, 75, 8, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.8, "unit": "pack of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_feta_cheese", "quantity": {"value": 120.0, "unit": "block of 200g"}}, {"id": "ing_capsicum", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_asparagus", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 0.1, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.5, "unit": "pack of 100g"}}]', '[{"ingredients":["400g / 14oz curly pasta (, dried (or other of choice))","1/4 cup parsley (, roughly chopped (or chives))","120g / 4oz feta (, crumbled into big chunks)"]},{"ingredients":["2 capsicum/bell peppers ((1 red, 1 yellow), cut into 2.5cm / 1\" pieces)","1 red onion (, cut into wedges)","1 eggplant (, halved lengthwise, then 1.25cm/ 0.5\" thick semi circles)","2 zucchini (, cut into 1.5cm / 2/3\" chunks (see video))","200g/ 7oz button mushrooms (, halved (large ones quartered))","1 bunch asparagus (, ends trimmed, cut into 5cm/2\" lengths)"],"purpose":"Vegetables (Note 1):"},{"ingredients":["1/4 cup (65ml) extra virgin olive oil","1 tsp each salt and pepper","3 cloves garlic (, minced)"],"purpose":"Roasting:"},{"ingredients":["1/3 cup (85ml) lemon juice","1/3 cup (85ml) extra virgin olive oil","2 tsp white sugar","2 garlic cloves (, minced)","1/2 tsp each salt and pepper","1/2 tsp each dried basil, parsley, oregano, thyme (Note 2)","1/2 - 1 tsp chilli flakes (adjust spice to taste, Note 3)"],"purpose":"Marinade / Dressing:"}]', '[{"description":"Marinade/Dressing:","images":[],"step":1},{"description":"Place ingredients in a jar and shake well. Set aside 10 minutes+.","images":[],"step":2},{"description":"Roasted Vegetables:","images":[],"step":3},{"title":"Preheat oven to 250°C/480°F (230°F fan)","description":"super high heat replicates BBQ charred edges.","images":[],"step":4},{"title":"Toss veggies in oil","description":"Place all vegetables other than asparagus in a large bowl. Drizzle with oil, sprinkle with salt, pepper and garlic, toss.","images":[],"step":5},{"description":"Spread vegetables on 2 trays (fill one less than the other). Roast 25 minutes, tossing once.","images":[],"step":6},{"title":"Add asparagus","description":"Drizzle asparagus with oil and pinch of salt and pepper. Add into oven for last 5 minutes.","images":[],"step":7},{"title":"BBQ Option","description":"See Marinated BBQ Vegetables for directions.","images":[],"step":8},{"title":"Marinate veggies","description":"Transfer vegetables into large bowl, pour over 1/2 the Dressing. Toss, then leave to marinate for 30 minutes to 3 hours.","duration":30,"images":[],"step":9},{"title":"Cook pasta + 2 minutes","description":"In large pot of salted water, cook pasta per packet directions but ADD 2 minutes to the cook time (Note 5 for why). Drain and return pasta into pot.","images":[],"step":10},{"description":"Add vegetables, including veg juices, into the pasta pot. Add remaining Dressing and parsley, then toss. Set aside for 15 minutes to cool slightly.","duration":15,"images":[],"step":11},{"title":"Serve! Sprinkle with feta and serve! Keeps 4","description":"5 days, serve at room temp.","images":[],"step":12},{"description":"Make ahead PRO TIP (Note 4):","images":[],"step":13},{"description":"SCOOP OUT a mug of pasta cooking water just before draining. Add 3 tbsp water to reserved Dressing (after marinating veg), shake well. Use this Dressing per above, but reserve 3 tbsp to freshen up pasta salad on Day 2 onwards.","images":[],"step":14},{"title":"Freshen up pasta salad","description":"Bring to room temp or briefly microwave (cold pasta = dry) to warm gently. Toss with Reserved Dressing then serve.","images":[],"step":15}]', '["gluten"]', '["vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["grilling-ideas-and-recipes","pasta-recipes","pasta-salads-and-rice-salads","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9f489d640e96', 'en', 'US', 'Slow cooked Beef Ribs with barbecue sauce (beef short ribs)', 'Recipe video above. Beef ribs slow braised in a silky, shiny homemade barbecue sauce until the meat is fall apart and ridiculously juicy inside, and the outside is bronzed and sticky. Also known as beef short ribs, this is one of the best cuts for slow cooking, far superior to beef chuck because there''s more marbling. Beef chuck always has some dry patches!100% perfect for make ahead and freezing.', 'https://www.recipetineats.com/tachyon/2020/09/Beef-Short-Ribs.jpg', 15, 240, 255, 6, '[{"id": "ing_beef_steak", "quantity": {"value": 6.0, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.019, "unit": "jar of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.25, "unit": "bottle of 500ml"}}, {"id": "ing_ketchup", "quantity": {"value": 0.45, "unit": "bottle of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["6 x 300 - 350g / 10 - 12 oz beef ribs ((aka beef short ribs) (Note 1), patted dry)"]},{"ingredients":["1 tbsp brown sugar (sub white)","2 tsp paprika","1 tsp garlic powder (sub 1 tsp fresh garlic)","1 tsp onion powder (sub garlic powder)","1/2 tsp cumin powder","3/4 tsp mustard powder (Note 2)","1 tsp cooking salt / kosher salt (reduce by 25% for table salt, increase 50% for salt flakes)","1/2 tsp black pepper"],"purpose":"RUB:"},{"ingredients":["2 garlic cloves (, minced (sub 2 tsp powder))","1/2 cup apple cider vinegar (Note 2 subs)","1 1/2 cups ketchup (, or Aussie tomato sauce)","1/2 cup brown sugar (, loosely packed (ie don''t pack it tight)(sub white))","2 tsp EACH black pepper, onion powder, mustard powder (Note 2)","1 tsp cayenne pepper (adjust to taste re: spiciness)","1 tbsp Worcestershire sauce (sub soy sauce)","2 cups water"],"purpose":"Barbecue SAUCE:"},{"ingredients":["Parsley or chives (, chopped)"],"purpose":"Optional garnish:"}]', '[{"description":"Coat ribs in rub, mix sauce except water in pan, then add water. Bake ribs in sauce covered 3.5 hrs at 160°C/320°F, turn, then 30 min uncovered. Serve!","images":[],"step":1},{"description":"Preheat oven to 160°C/320°F (both fan & standard).","images":[],"step":2},{"title":"Rub","description":"Mix Rub in a small bowl large, enough to fit one rib. Press beef ribs into the rub, coating all sides. Shake off excess.","images":[],"step":3},{"title":"BBQ Sauce","description":"Mix Barbecue Sauce ingredients, except water, in a baking pan. Then mix in water.","images":[],"step":4},{"title":"Coat","description":"Place ribs in sauce, turning to coat. Arrange meat side down in the sauce, bone side exposed (sauce won''t cover completely, that''s ok).","images":[],"step":5},{"title":"Bake 3.5 hours","description":"Cover tightly with foil or lid, bake 3 1/2 hours. Remove from oven, remove foil. Turn ribs (some may have fall over, that''s ok, just turn them). Spoon over sauce.","images":[],"step":6},{"title":"Bake 30 min","description":"Bake 30 minutes uncovered, spooning over sauce again halfway through, until surface is caramelised and sticky. Check to ensure ribs are tender - pry a bit apart using two forks. (If not, cover and return to oven, but after 4 hrs they certainly should be!)","images":[],"step":7},{"title":"Serve","description":"Remove ribs onto serving plate (use a spoon as meat will barely be attached to bone, if at all). Mix sauce to bring together (Note 3 on adjustments). Serve with ribs! (See below for serving suggestions)","images":[],"step":8}]', '["gluten","mustard","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Southern","Western"],"categories":["beef","beef-recipes","grilling-ideas-and-recipes","mains","slow-cooked-fall-apart","slow-cooker-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d3952a77e07a', 'en', 'US', 'Spanish Paella', 'Recipe video above. The most famous Spanish dish of them all! Paella is meant to be a fun relaxed dish, so don''t get hung up about having the exact same seafood I''ve used - see Notes. And don''t be scared of making paella - it is actually very forgiving if you have the right liquid/rice ratios and follow the order in which I cook things!Note on Chorizo - NOT in traditional Spanish Paella recipes however, it''s widely used in Spanish restaurants outside of Spain. Australia would faint if I excluded it. So it''s in!', 'https://www.recipetineats.com/tachyon/2016/08/Paella-8.jpg', 15, 30, 45, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_chorizo", "quantity": {"value": 0.198, "unit": "kg"}}, {"id": "ing_squid", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 225.0, "unit": "pack"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_saffron_threads", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_shrimp", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_2_lbs_mussels", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 4.0, "unit": "net of 500g"}}]', '[{"ingredients":["1 - 2 tbsp olive oil","7 oz / 200g chorizo (2 pieces) (, sliced 1/2 cm / 1/5\" thick (Note 1))","200g / 6 oz squid (calamari) (, cut into 7mm / 1/4\" thick rings (Note 2))","1 onion (, diced (brown, white, yellow))","3 garlic cloves (, minced)","1 red capsicum / bell pepper (, diced)","1 1/2 cups paella rice (\"Bomba\", \"Valencia\" or \"Calasparra\" rice) (Note 3)","2 juicy ripe tomatoes, peeled and diced (OR 3/4 cup canned crushed tomato (Note 4))","300g / 10 oz chicken thigh fillets (, cut into 1.5\" / 3.5cm pieces)","3 1/2 cups chicken broth/stock (not low sodium) ( or homemade seafood broth (Note 5))","1 tsp saffron threads (or 1/4 tsp ground saffron, Note 6)","1 cup frozen peas","12- 16 medium / large prawns (, whole (shell on) (Note 7))","12 large mussels (, cleaned & check freshness (Note 8))"]},{"ingredients":["Fresh parsley (, chopped)","2 Lemons (, cut into wedges)"],"purpose":"Garnish"}]', '[{"title":"Chorizo","description":"Heat 1 tbsp oil in a 30cm / 10\" paella pan or large skillet over high heat (Note 9). Add chorizo and cook until browned on each side (~ 3 minutes). Remove with a slotted spoon and set aside.","images":[],"step":1},{"title":"Squid","description":"Add squid and cook for 45 seconds on each side, then remove and set aside.","duration":0.75,"images":[],"step":2},{"title":"Garlic, onion, capsicum","description":"Add remaining oil (if needed). Add garlic and onion, cook for 2 minutes. Add capsicum, cook for 1 minute.","duration":2,"images":[],"step":3},{"title":"Chicken","description":"Add chicken. Cook for 2 minutes until lightly browned but still raw inside.","duration":2,"images":[],"step":4},{"title":"Add Rice","description":"Add rice and mix until the grains are coated in oil.","images":[],"step":5},{"title":"Cooking broth","description":"Add in most of the chorizo (reserve 1/4 for garnish), chicken stock, fresh or crushed tomato and saffron. Stir.","images":[],"step":6},{"title":"Simmer 1","description":"Bring it to a simmer then adjust heat so it''s simmering fairly gently (not super rapidly, will burn rice). Simmer for 10 minutes - no stirring! At this stage, a bit of rice should be poking through to the surface but there should still be plenty of liquid.","duration":10,"images":[],"step":7},{"title":"Add peas, prawns and mussels","description":"Scatter over peas, squidge the prawns and mussels into the rice (partial submerge is fine).","images":[],"step":8},{"title":"Simmer 2","description":"Cook for 8 minutes (turn prawns halfway if you think it''s necessary) or until prawns are opaque, mussels are open, and most of the liquid has been absorbed but still a bit liquidy. Discard any mussels that do not open. Remove from stove.","duration":8,"images":[],"step":9},{"title":"Check rice","description":"Do a taste test to see if the rice is cooked - it should be firm but cooked. If it is too firm for your taste, no stress, just add a splash of hot water (not too much!) and keep cooking.","images":[],"step":10},{"title":"Rest","description":"Scatter over squid and reserved chorizo (residual heat will warm through), cover with lid then rest for 5 minutes (rice will absorb remainig liquid). Paella rice should now be tender but \"juicy\", not stodgy and thick (if it is, add splash of water to loosen it).","duration":5,"images":[],"step":11},{"title":"Garnish","description":"scatter with parsley and wedges of lemon. Take to table as is, then mix up rice with seafood before serving!","images":[],"step":12}]', '["shellfish"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Spanish"],"categories":["chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","iconic-dishes","mediterranean-recipes","prawns-shrimp","quick-and-easy","seafood-recipes","spanish-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e36e6d0302c9', 'en', 'US', 'Huli Huli Chicken (Tropical Hawaiian chicken)', 'Recipe video above. There''s just no chance you make this without doing a little hula dance… swish those hips!!! Traditional Hawaiian recipe with in-your-face tropical flavours. Sweet, savoury, very sticky! Best 24 - 48 hr marinade, but you can get away with 3 hrs but baste extra generously.IMPORTANT: Do not use pureed fresh pineapple or fresh, pure pineapple juice from the fridge - it will over tenderise chicken, see Note 2. Use any pineapple juice sold in the aisles, not fridge - can, bottle or vac packed.', 'https://www.recipetineats.com/tachyon/2020/07/Hawaiian-Huli-Huli-Chicken_1.jpg', 10, 12, 22, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_pineapple", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_ginger", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 7.5, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.5, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.125, "unit": "bottle of 500ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_sriracha", "quantity": {"value": 0.037, "unit": "bottle of 400ml"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_pineapple", "quantity": {"value": 0.75, "unit": "unit"}}]', '[{"ingredients":["1.5 kg / 3 lb chicken thighs (or breast, Note 1)","1 tbsp vegetable oil"]},{"ingredients":["3/4 cup pineapple juice, canned or bottled (NOT FRESH!) (, unsweetened (Note 2))","1 1/2 tbsp ginger (, freshly grated (Note 3))","1 1/2 tbsp garlic (, freshly grated (Note 3))","1/2 cup tomato ketchup (or Aussie tomato sauce)","1/2 cup soy sauce","1/4 cup sherry or Chinese cooking wine (Note 4)","1/4 cup brown sugar","1 tbsp Sriracha","2 tbsp rice vinegar (or cider vinegar)","1 tbsp sesame oil (, toasted)"],"purpose":"Marinade:"},{"ingredients":["Sliced green onion","Pineapple slices (, grilled for 3 minutes on each side for lines)"],"purpose":"Garnishes, optional:"}]', '[{"description":"Mix marinade, set aside 3/4 cup (185 ml) for basting.","images":[],"step":1},{"description":"Pour the rest over the chicken in a glass or ceramic container (not metal or plastic), coat chicken then marinade 24 - 48 hours.","images":[],"step":2},{"description":"Cooking:","images":[],"step":3},{"description":"Brush BBQ grills with oil then preheat to medium high, or heat oil in a skillet over medium high heat.","images":[],"step":4},{"description":"Drain excess marinade from chicken, place on BBQ/skillet.","images":[],"step":5},{"title":"Cook the first side for 2","description":"3 minutes until golden (adjust heat if browning too fast), then flip and cook for 2 minutes.","duration":2.5,"images":[],"step":6},{"description":"Baste (dab) generously with reserved marinade, then flip and cook for 1 minute.","duration":1,"images":[],"step":7},{"description":"Repeat this every minute or so for a total cook time of 10 minutes, or until internal temp in the thickest part registers 75°C/167°F (for thigh) or 65°C / 150°F (for breast).","images":[],"step":8},{"description":"Transfer chicken to a plate, loosely cover with foil and rest for 3 minutes before serving, garnished with green onion if desired.","duration":3,"images":[],"step":9}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Hawaiian","Tropical!"],"categories":["chicken-breast-recipes","chicken-recipes","grilling-ideas-and-recipes","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9bc75da5bbef', 'en', 'US', 'Honey Soy Chicken - Marinade and Sauce (excellent grilled!)', 'Recipe video above. This is my premium recipe for Honey Soy chicken, a step up from this quick Honey Garlic Chicken and easy Baked Honey Soy Chicken, neither of which call for marinating. One mixture is used as a marinade, for basting, and also to make a fabulous glossy sauce to drizzle over the chicken and everything on your plate. It''s especially good for grilling! (More BBQ recipes here) Pictured with Pineapple Fried Rice.Other chicken cuts - For wings, use the Honey Soy Wings recipe. For drumsticks and bone-in thighs, use the Honey Soy Baked Chicken recipe.', 'https://www.recipetineats.com/tachyon/2020/06/Honey-Soy-Chicken_4.jpg', 10, 20, 30, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.25, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.5, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.333, "unit": "jar of 500g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.125, "unit": "bottle of 500ml"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.03, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 7.5, "unit": "pack of 3 heads"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.019, "unit": "pack of 400g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1.25 - 1.5 kg/ 2.5 - 3 lb skinless boneless chicken thighs OR breast (Note 1)","1 tbsp vegetable oil (, for cooking)"]},{"ingredients":["1/2 cup soy sauce (, all purpose or light (not dark, Note 2))","2/3 cup honey (sub maple syrup)","1/3 cup cider vinegar (or rice vinegar)","1/4 cup Chinese cooking wine or dry sherry (key ingredient, Note 3)","1 tbsp sesame oil (, toasted (Note 4))","1 1/2 tbsp garlic (, finely minced)"],"purpose":"Honey Soy Marinade Sauce:"},{"ingredients":["1/3 cup water","1 1/2 tsp cornflour/cornstarch"],"purpose":"Serving Sauce:"},{"ingredients":["Green onion (, finely sliced)","Sesame seeds"],"purpose":"Garnishes (optional):"}]', '[{"description":"Marinade Sauce:","images":[],"step":1},{"description":"Place ingredients in a jug and mix well until honey is completely dissolved.","images":[],"step":2},{"description":"Reserve 1/4 cup for Basting, refrigerate. (Note 5)","images":[],"step":3},{"description":"Reserve 2/3 cup for Serving Sauce, refrigerate.","images":[],"step":4},{"title":"Marinade Chicken","description":"Pour remaining marinade over chicken in a container. Coat chicken thoroughly. Cover, refrigerate 24 to 48 hours (minimum 3 hrs).","images":[],"step":5},{"description":"Serving Sauce (Makes 1 cup):","images":[],"step":6},{"description":"Place reserved sauce in a small saucepan. Mix cornflour and water, then add into saucepan.","images":[],"step":7},{"description":"Simmer over medium for 5 minutes, stirring regularly, until it thickens to a syrupy consistency. Set aside and keep warm. (If it gets too thick, just add a bit more water)","duration":5,"images":[],"step":8},{"description":"Cook:","images":[],"step":9},{"description":"Brush BBQ plate or grills with oil and heat to medium high. Or heat oil in a large skillet over medium high heat.","images":[],"step":10},{"title":"THIGHS","description":"Place chicken on BBQ. Cook the first side for 2 minutes, then flip and dab with reserved Basting Sauce. Cook for 2 minutes, flip and baste. Then flip/baste every 1 minute for total cook time of ~ 10 minutes or until a thermometer reads 75°C/165°F.","duration":2,"images":[],"step":11},{"title":"BREAST","description":"Cook first side 2 minutes, flip, baste. Cook 2 minutes, then flip and baste every 45 sec or so for total cook time of ~8 minutes (internal temp 66°C / 151°F).","images":[],"step":12},{"title":"REST","description":"Transfer to serving plate, cover loosely with foil and rest for 5 minutes.","duration":5,"images":[],"step":13},{"description":"SERVE chicken garnished with sesame seeds and green onion, with sauce on the side so people can help themselves.","images":[],"step":14}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian-esque","Western"],"categories":["chicken-breast-recipes","chicken-recipes","grilling-ideas-and-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_946d7108572e', 'en', 'US', 'Sticky Grilled Chicken', 'Recipe video above. Sticky, savoury and sweet, this is the marinade I use for grilled chicken that I know is a guaranteed hit with everyone, kids and adults! It tastes like a country-style rub, and it''s finger licking'' good.', 'https://www.recipetineats.com/tachyon/2019/07/Sticky-Grilled-Chicken_7.jpg', 10, 10, 1460, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_ketchup", "quantity": {"value": 0.15, "unit": "bottle of 500g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 20.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}]', '[{"ingredients":["700g/ 1.4lb chicken thighs (, skinless boneless (Note 1))"]},{"ingredients":["1/2 cup ketchup","1/3 cup brown sugar (, packed)","1/4 cup soy sauce (, all purpose or light (NOT dark))","2 tbsp apple cider vinegar","2 tbsp olive oil","4 tsp Worcestershire Sauce","4 garlic cloves (, minced)"],"purpose":"Marinade / Glaze (Note 2 for subs):"}]', '[{"description":"Mix Marinade in a large bowl.","images":[],"step":1},{"description":"Scoop out 1/2 cup and reserve for basting (\"Glaze\").","images":[],"step":2},{"description":"Add chicken, turn to coat. Marinade overnight (minimum 3 hours, up to 48 hours, or freeze).","images":[],"step":3},{"description":"Brush BBQ with vegetable or canola oil, then preheat to medium.","images":[],"step":4},{"description":"Pick up chicken, allowing excess Marinade to drip off.","images":[],"step":5},{"description":"Place on BBQ, cook 4 minutes until nicely caramelised.","images":[],"step":6},{"description":"Turn chicken, then brush generously with Glaze. Cook 4 minutes.","images":[],"step":7},{"description":"Flip, brush with more Glaze, flip again and brush with Glaze.","images":[],"step":8},{"description":"Remove chicken onto plate, cover loosely with foil.","images":[],"step":9},{"description":"Rest 3 minutes before serving, sprinkled with parsley if using. Pictured in post with Macaroni Salad!","images":[],"step":10},{"title":"Stove","description":"follow up steps in a non stick pan, heated to medium high with 1 tbsp oil (cook in batches if needed).","images":[],"step":11},{"title":"Oven","description":"use this recipe: Sticky Baked Chicken","images":[],"step":12}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-recipes","grilling-ideas-and-recipes","main-dishes","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b0e8d796cad9', 'en', 'US', 'Beef Steak Marinade', 'Recipe video above. This is a marinade to transform good value steaks by making them juicier, more tender and adding a hint of flavour while not overpowering the flavour of the beef. With this marinade, you won''t need a sauce for the beef, though I can never resist some garlic butter!', 'https://www.recipetineats.com/tachyon/2016/07/Steak-Marinade_4.jpg', 5, 5, 730, 2, '[{"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2 steaks (, economical (Note 1))"]},{"ingredients":["1 tsp Dijon mustard","1/2 tsp minced garlic (1 large garlic clove)","1/2 tsp onion powder (or sub with garlic powder)","1 tbsp soy sauce (Note 2)","1 tbsp oil (I use olive oil, but any oil is fine)","1 tbsp Worcestershire sauce","1 tbsp balsamic vinegar","Black pepper"],"purpose":"Marinade"}]', '[{"description":"Mix together mustard, garlic and onion powder. Then mix in remaining ingredients.","images":[],"step":1},{"description":"Place beef in a ziplock bag with Marinade and marinade overnight (12 - 24 hours).","images":[],"step":2},{"description":"Remove from the fridge 30 minutes before cooking to bring to room temperature - key for even cooking of steaks. Shake off excess marinade.","images":[],"step":3},{"description":"Brush BBQ Grills with oil, then heat on high heat until is really hot - you should see wisps of smoke. Or heat a heavy based skillet on high until very hot, then add oil - it will heat almost instantly.","images":[],"step":4},{"description":"Add steaks. For 2cm / 3/4\" thick steaks, cook the first side for 2 minutes, then turn and cook the other side for 2 minutes (medium rare 52°C/125°F, chart below for other doneness temps). (Note 3)","duration":2,"images":[],"step":5},{"description":"Remove from skillet onto a WARM plate, cover loosely with foil and set aside for 5 minutes.","duration":5,"images":[],"step":6},{"title":"Serve! I couldn''t resist garlic butter","description":"see recipe in notes.","images":[],"step":7}]', '["gluten","mustard","soy"]', '["high_protein","keto_friendly","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a2cffd800f15', 'en', 'US', 'Fish Tacos', 'Recipe video above. Fish marinated in classic Mexican fresh flavours, seared until golden, are perfect for tacos. The lightly pickled red cabbage is a perfect accompanied for the soft fish, a great texture contrast. A wonderful recipe for white fish fillets, you will NOT miss deep fried fish!', 'https://www.recipetineats.com/tachyon/2016/05/Fish-Tacos_4-1.jpg', 15, 10, 45, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.544, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_chipotle", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_jalapeno", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_red_cabbage", "quantity": {"value": 12.0, "unit": "head"}}, {"id": "ing_green_onion", "quantity": {"value": 0.06, "unit": "bunch"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.45, "unit": "tub of 250g"}}, {"id": "ing_sriracha", "quantity": {"value": 2.0, "unit": "bottle of 400ml"}}, {"id": "ing_tortillas", "quantity": {"value": 12.0, "unit": "pack of 8"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}]', '[{"ingredients":["1.2 lb / 600g firm white fish fillets (Note 1)","Zest of 1 lime","3 tbsp lime juice","1 tbsp chipotle powder (Note 2)","1 tbsp canned jalapeno (, finely chopped)","1/4 cup cilantro / coriander (, finely chopped)","2 garlic cloves (, minced)","3 tbsp olive oil","Salt and pepper"],"purpose":"Fish Marinade"},{"ingredients":["4 cups red cabbage (, finely shredded)","3 green onion stems (, finely sliced on the diagonal)","2 tbsp red wine vinegar (or white wine vinegar, cider vinegar)","1/2 tsp salt"],"purpose":"Quick Pickled cabbage"},{"ingredients":["3/4 cup sour cream (or yogurt)","2 - 3 tbsp sriracha (, adjust to taste (Note 3))"],"purpose":"Pink Taco Sauce"},{"ingredients":["1 tbsp olive oil","12 small tortillas ((corn or flour), warmed)","lime wedges","coriander/cilantro leaves"],"purpose":"To Cook & Serve"}]', '[{"title":"Marinade fish","description":"Combine Fish Marinade ingredients in a ziplock bag. Set aside for 20 minutes to marinate - no longer than 1 hour.","duration":20,"images":[],"step":1},{"title":"Pickled Cabbage","description":"Place Pickled Cabbage ingredients in a bowl. Toss to combine and set aside for 30 minutes. Drain excess liquid, scrunch cabbage with your hands (to help soften). Set aside.","duration":30,"images":[],"step":2},{"title":"Pink Sauce","description":"Mix to combine.","images":[],"step":3},{"title":"Cook fish","description":"Heat oil in a skillet over high heat. Cook fish for 2 minutes on each side, or until golden and cooked.","duration":2,"images":[],"step":4},{"description":"Remove fish onto plate then flake into large pieces.","images":[],"step":5},{"description":"To assemble tacos, top with cabbage then fish, a dollop of sour cream and a squeeze of lime juice. Fold tortilla over and enjoy!","images":[],"step":6}]', '["fish","gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["dietary","fish-recipes","gluten-free-recipes","grilling-ideas-and-recipes","low-calorie-recipes","mexican-recipes","most-popular","quick-and-easy","seafood-recipes","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_38731e98ea9b', 'en', 'US', 'Avocado Chicken Burgers', 'Recipe video above. Ground chicken burgers can be so bland and boring. Not these! Parmesan, garlic and a hint of dried sage adds great savoury flavour, and you’ll love how these cook up beautifully golden with crispy edges!', 'https://www.recipetineats.com/tachyon/2019/08/Avocado-Chicken-Burgers_9.jpg', 15, 10, 25, 4, '[{"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_sage", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_lettuce", "quantity": {"value": 1.2, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.003, "unit": "jar of 400g"}}, {"id": "ing_french_fries", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["500g/ 1.2 lb ground chicken (mince) (Note 1)","1 cup panko breadcrumbs","1 egg","3/4 cup parmesan (, finely grated (Note 2))","1 cup green onion (, finely sliced (~2 stems))","2 garlic cloves (, minced)","1/2 tsp dried sage (Note 3)","1/2 tsp salt and pepper (, each)"],"purpose":"Chicken Burger Patties:"},{"ingredients":["2 tbsp olive oil","4 soft burger buns or brioche buns","1 avocado (big!) (or 2 medium)","60g / 2 oz rocket / arugula or other lettuce of choice","2 tomatoes (, sliced)","4 slices Swiss cheese (or other cheese)","Mayonnaise, relish, ketchup or tomato sauce (to smear lid)"],"purpose":"Burgers:"},{"ingredients":["French fries","Baked potato wedges"],"purpose":"On the side"}]', '[{"description":"Chicken Burger Patties","images":[],"step":1},{"description":"Place Pattie ingredients in bowl, mix well with hands.","images":[],"step":2},{"description":"Form 4 patties, 1.5cm / 3/5\" thick, slightly larger than the buns (shrinks slightly). If mixture is super sticky (Note 4), either refrigerate mixture for 30 minutes, or wet hands or lightly spray hands with oil (I do this).","duration":30,"images":[],"step":3},{"description":"Heat oil in skillet over medium high heat. Add patties, working in batches. Cook for 2 minutes or until deep golden, then flip.","duration":2,"images":[],"step":4},{"description":"After 1 minute, top with a piece of cheese and place lid on to melt cheese.","images":[],"step":5},{"description":"Once cheese is melted, remove patties from skillet.","images":[],"step":6},{"description":"Split buns and lightly toast in oven or under broiler/grill.","images":[],"step":7},{"description":"Cut avocado in half, scoop out a generous amount then \"smash\" it on the base of the bun with a fork. Sprinkle with salt and pepper.","images":[],"step":8},{"description":"Top with Chicken Pattie, then rocket/arugula and tomato.","images":[],"step":9},{"description":"Smear the top bun with mayonnaise (or relish, ketchup, other condiment of choice) and place lid on bun.","images":[],"step":10},{"description":"Devour and be happy!","images":[],"step":11}]', '["egg","milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["burger-recipes","chicken-mince-recipes","chicken-recipes","dinner-tonight","grilling-ideas-and-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8e1a22cf6ea9', 'en', 'US', 'Chimichurri Steak', 'Recipe video above. An essential part of Argentinian cuisine, Chimichurri Sauce is steadily growing in popularly throughout the rest of the world - with good reason! It''s fresh, zingy with a bit of a bite, and pairs so perfectly with a simple grilled steak. It''s also fantastic with fish, chicken and pork!', 'https://www.recipetineats.com/tachyon/2016/08/Steak-with-Chimichurri-Sauce_1.jpg', 5, 10, 15, 4, '[{"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 cup parsley leaves (, tightly packed)","1 tbsp oregano leaves (, tightly packed (still lovely without))","4 garlic cloves (, minced)","0 - 2 tsp red pepper flakes (optional - adjust to taste)","1/4 cup (65 ml) red wine vinegar (Note 1)","1/2 tsp salt","Black pepper","1/2 cup (125 ml) extra virgin olive oil"],"purpose":"Chimichurri Sauce"},{"ingredients":["700g / 1.4lb flat iron, flank, skirt steak (or other steak of choice, at room temperature (Note 3))","Salt and pepper"],"purpose":"Steak"}]', '[{"description":"Chimichurri Sauce","images":[],"step":1},{"description":"Place all ingredients except oil in a food processor. Whizz until parsley is finely chopped, but not pureed - see video or photos. Alternatively chop parsley by hand.","images":[],"step":2},{"description":"Transfer into a small bowl. Add oil, gently stir. Set aside for 1 hour before use, overnight is even better!","images":[],"step":3},{"description":"Store in an airtight container in the refrigerator and use within 3 days (Note 3). Makes 3/4 cup.","images":[],"step":4},{"description":"Take steak out of the fridge 30 minutes prior to cooking.","images":[],"step":5},{"description":"Heat BBQ or heavy based skillet with 1 tbsp vegetable or canola oil over high heat until smoking.","images":[],"step":6},{"description":"Sprinkle each side of steak generously with salt and pepper.","images":[],"step":7},{"description":"Add steak and cook to your liking.","images":[],"step":8},{"title":"Cook times","description":"for steak 2cm / 4/5” thick, 2 min on each side for medium rare (until internal temp is 52C/125F, will rise to 54C/130F after resting) OR 2 1/2 min each side for medium (internal temp 57C/135F, will rise to 60C/140F).","images":[],"step":9},{"description":"Transfer to a plate, cover loosely with foil and rest for 5 - 10 minutes.","duration":7.5,"images":[],"step":10},{"description":"Cut thin slices against the grain (see photo below) and serve with Chimichurri Sauce on the side so people can help themselves.","images":[],"step":11}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Argentinian"],"categories":["beef-recipes","dietary","dinner-tonight","gluten-free-recipes","grilling-ideas-and-recipes","main-dishes","quick-and-easy","roast-beef","south-american-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f02244be45ca', 'en', 'US', 'A great Chicken Marinade (great grilled or pan seared!)', 'Recipe video above. This is a great everyday Chicken Marinade, one you make with things you''ve already got with plenty of sub options (see notes). It will make any cut of chicken extra juicy, infuse it with savoury flavour that''s a touch of sweet, with a hint of herby goodness. Especially good for chicken breast, and terrific for grilling!', 'https://www.recipetineats.com/tachyon/2019/06/Grilled-Chicken-Marinades-Cover-Graphic.jpg', 5, 10, 15, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.3, "unit": "bottle of 250ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}]', '[{"ingredients":["700g / 1.4 lb chicken breast, tenderloins or thigh (Note 1)"]},{"ingredients":["2 tbsp honey OR brown sugar","1 tbsp olive oil (or any oil)","5 tbsp soy sauce","2 tbsp lemon juice","2 tsp Worcestershire sauce","4 garlic cloves (, minced)","1 tsp dried oregano (or rosemary, thyme, minced herbs)","1/2 tsp black pepper (, ground)"],"purpose":"Chicken marinade (subs Note 3):"},{"ingredients":["Finely chopped parsley","Lemon slices"],"purpose":"Garnishes (optional)"}]', '[{"title":"Recommended","description":"Pound breast to even thickness using a meat pounder, rolling pin, or fist. OR cut large ones in half horizontally to form 2 cutlets (steaks) for each.","images":[],"step":1},{"description":"Mix marinade in a ziplock bag (or container in which chicken fits snugly). Add chicken.","images":[],"step":2},{"description":"Marinate 3 hours to overnight, though even 30 minutes is effective. (Note 2)","images":[],"step":3},{"description":"Heat 1 tbsp olive oil in a large skillet over medium high heat, and cook chicken per times below until deep golden (see video). If browning too quickly, lower heat.","images":[],"step":4},{"description":"Transfer to serving plate, cover loosely with foil and rest for 3 minutes before serving, garnished with parsley and lemon slices if desired.","duration":3,"images":[],"step":5},{"description":"Cook times:","images":[],"step":6},{"title":"Whole breast and boneless thighs: 3","description":"4 minutes each side (internal temp 165F/75C)","images":[],"step":7},{"title":"Cutlets and tenderloin","description":"2 minutes each side","images":[],"step":8}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","grilling-ideas-and-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d7ea4ab4ac20', 'en', 'US', 'Crispy Grilled Shrimp (Prawns) with Lemon Butter Sauce', 'Recipe video above. Seasoned and CRISPY on the outside, juicy on the inside, drizzled with a simple-yet-incredible lemon butter sauce, you''ll love the little crispy little golden garlic bits in the sauce! This is a recipe made for the BBQ, but works great on the stove too (Note 4).', 'https://www.recipetineats.com/tachyon/2019/06/Crispy-Grilled-Shrimp-Lemon-Butter-Sauce_2.jpg', 5, 10, 15, 4, '[{"id": "ing_butter", "quantity": {"value": 90.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_shrimp", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["90g / 6 tbsp butter (, unsalted)","1/4 tsp salt","3 tsp garlic (, very finely chopped (do not use mincer, Note 1))","1.5 tbsp lemon juice (, plus more to taste)"],"purpose":"Lemon Garlic Butter:"},{"ingredients":["500g/ 1 lb large shrimp / prawns (, raw, peeled and deveined (Note 2))","1 tsp garlic powder","1 tsp smoked paprika (plain or sweet ok too)","1/4 tsp cayenne pepper","1 tbsp lemon juice (skip if using stove)","2 tbsp olive oil","1/2 tsp salt","1/4 tsp pepper"],"purpose":"Shrimp/Prawns:"},{"ingredients":["1 lemon (, halved, grilled if desired)","Lemon wedges or slices","2 tbsp finely chopped parsley"],"purpose":"Serving (optional):"}]', '[{"description":"Brush BBQ grills with oil, then preheat on high until very hot.","images":[],"step":1},{"description":"If shrimp are small and might fall through grills, skewer them (use 2 skewers, Note 3)","images":[],"step":2},{"description":"Melt butter in a small saucepan over medium high heat.","images":[],"step":3},{"description":"Add garlic and salt. Stir until garlic is LIGHT golden brown, then immediately remove from stove (residual heat will make garlic golden & crispy).","images":[],"step":4},{"description":"Stir through lemon.","images":[],"step":5},{"title":"Shrimp/Prawns (Stove","description":"Note 4):","images":[],"step":6},{"description":"Pat shrimp dry with paper towels (to ensure crispiness!)","images":[],"step":7},{"description":"Just prior to cooking, place in bowl, sprinkle/drizzle over remaining ingredients. Toss gently to coat.","images":[],"step":8},{"description":"Working quickly, place shrimp on BBQ and cook each side for 2 minutes until golden and crusty.","duration":2,"images":[],"step":9},{"description":"Immediately remove shrimp onto serving plate.","images":[],"step":10},{"description":"Drizzle over all the Lemon Garlic Butter, sprinkle with parsley and serve immediately with fresh lemon.","images":[],"step":11},{"description":"Crusty bread to mop up the crazy delish butter on the plate is essential!","images":[],"step":12}]', '["milk","shellfish"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["grilling-ideas-and-recipes","prawns-shrimp","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6764a38a414b', 'en', 'US', 'Marinated Grilled Salmon', 'Recipe VIDEO above. Make your next grilled salmon AMAZING with a simple yet incredible Salmon Marinade that will infuse the salmon with extra flavour! It''s savoury with a touch of sweet and hint of garlic, and does double duty as a sauce for serving!', 'https://www.recipetineats.com/tachyon/2019/06/Marinated-Grilled-Salmon_8.jpg', 5, 12, 17, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.333, "unit": "bottle of 250ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_honey", "quantity": {"value": 0.09, "unit": "jar of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}]', '[{"ingredients":["4 salmon fillets (, skin on best (150-180g/5-6oz each, Note 1))","Olive oil (, for cooking)"]},{"ingredients":["1/3 cup (85 ml) soy sauce (, low sodium)","2 tbsp lemon juice","3 tbsp honey","2 tbsp olive oil","2 garlic cloves (, minced)"],"purpose":"Marinade (Sauce)- Note 2:"},{"ingredients":["Parsley, chives or green onion (, finely chopped)","Lemon slices"],"purpose":"Serving (optional)"}]', '[{"description":"Place marinade in a ziplock bag and mix to combine.","images":[],"step":1},{"title":"Add salmon and massage to coat. Marinate for 3","description":"24 hours (1 hr minimum).","images":[],"step":2},{"description":"Take out of fridge 30 minutes prior to cooking.","images":[],"step":3},{"description":"Remove salmon onto plate, allowing excess marinade to drain off.","images":[],"step":4},{"description":"Sauce (basting + serving):","images":[],"step":5},{"description":"Pour remaining marinade into a small saucepan and simmer over medium high for 3 to 5 minutes until syrupy.","duration":4,"images":[],"step":6},{"description":"Pour into bowl/jug (some used for basting, some for serving).","images":[],"step":7},{"description":"Brush BBQ grills with oil. Then preheat to medium (or medium low for strong BBQ''s).","images":[],"step":8},{"description":"Drizzle salmon with oil, the place onto the BBQ flesh side down (skin side up).","images":[],"step":9},{"description":"Cook for 3 minutes or until golden, then use tongs to carefully turn.","duration":3,"images":[],"step":10},{"description":"Brush the flesh with Sauce, then close BBQ lid.","images":[],"step":11},{"title":"Cook for 3","description":"4 minutes, basting one more time halfway through, or until the internal temperature is 50C/120F(medium rare) or 55C/130F (medium).","duration":3.5,"images":[],"step":12},{"description":"Transfer salmon to plate and serve with remaining Sauce.","images":[],"step":13}]', '["fish","gluten","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","fish-recipes","grilling-ideas-and-recipes","quick-and-easy","salmon-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9ccf041ee881', 'en', 'US', 'A great Chicken Marinade (great grilled or pan seared!)', 'Recipe video above. This is a great everyday Chicken Marinade, one you make with things you''ve already got with plenty of sub options (see notes). It will make any cut of chicken extra juicy, infuse it with savoury flavour that''s a touch of sweet, with a hint of herby goodness. Especially good for chicken breast, and terrific for grilling!', 'https://www.recipetineats.com/tachyon/2019/05/Chicken-Marinade_8-1.jpg', 5, 10, 15, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.3, "unit": "bottle of 250ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}]', '[{"ingredients":["700g / 1.4 lb chicken breast, tenderloins or thigh (Note 1)"]},{"ingredients":["2 tbsp honey OR brown sugar","1 tbsp olive oil (or any oil)","5 tbsp soy sauce","2 tbsp lemon juice","2 tsp Worcestershire sauce","4 garlic cloves (, minced)","1 tsp dried oregano (or rosemary, thyme, minced herbs)","1/2 tsp black pepper (, ground)"],"purpose":"Chicken marinade (subs Note 3):"},{"ingredients":["Finely chopped parsley","Lemon slices"],"purpose":"Garnishes (optional)"}]', '[{"title":"Recommended","description":"Pound breast to even thickness using a meat pounder, rolling pin, or fist. OR cut large ones in half horizontally to form 2 cutlets (steaks) for each.","images":[],"step":1},{"description":"Mix marinade in a ziplock bag (or container in which chicken fits snugly). Add chicken.","images":[],"step":2},{"description":"Marinate 3 hours to overnight, though even 30 minutes is effective. (Note 2)","images":[],"step":3},{"description":"Heat 1 tbsp olive oil in a large skillet over medium high heat, and cook chicken per times below until deep golden (see video). If browning too quickly, lower heat.","images":[],"step":4},{"description":"Transfer to serving plate, cover loosely with foil and rest for 3 minutes before serving, garnished with parsley and lemon slices if desired.","duration":3,"images":[],"step":5},{"description":"Cook times:","images":[],"step":6},{"title":"Whole breast and boneless thighs: 3","description":"4 minutes each side (internal temp 165F/75C)","images":[],"step":7},{"title":"Cutlets and tenderloin","description":"2 minutes each side","images":[],"step":8}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","grilling-ideas-and-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9e9bc63f23ec', 'en', 'US', 'A Great Pork Chop Marinade', 'Recipe video above. This marinade will make any pork chops or steak extra juicy as well as infusing it with great savoury flavour and a touch of sweet. Soy sauce is the secret ingredient - it does not taste the least bit "Asiany" or soy saucey. MINIMUM MARINADE TIME: 1 hr+ for thin chops, 3 hrs+ for thick.', 'https://www.recipetineats.com/tachyon/2017/08/Marinated-Pork-Chops-3A.jpg', 5, 10, 15, 4, '[{"id": "ing_pork", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.333, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["4 bone in pork chops, 2 cm / 4/5\" thick about 280g/9 oz each (Note 1)","1 tbsp oil"]},{"ingredients":["1/3 cup (85 ml) soy sauce (light or all purpose, not dark)","2 tbsp brown sugar","2 tsp Worcestershire sauce","1 tsp Dijon mustard","2 garlic cloves (, minced)","¼ tsp black pepper"],"purpose":"Marinade:"}]', '[{"description":"Place Marinade ingredients in a ziplock bag. Massage to combine.","images":[],"step":1},{"description":"Add chops. Massage to coat in the Marinade. Marinate for 1 – 24 hours. (Note 2)","images":[],"step":2},{"description":"Take the chops out of the fridge 20 minutes before cooking.","images":[],"step":3},{"description":"Brush BBQ grill or drizzle oil in pan, heat on medium high. Add pork and cook for 4 minutes or until the underside is caramelised and the pork releases from the grill, then turn the chops and cook for 3 minutes (Note 2 for thin chops).","duration":4,"images":[],"step":4},{"description":"Baste both sides with residual marinade in ziplock bag, then cook the basted side for 30 seconds before serving. The chops should have a great crust","duration":0.5,"images":[],"step":5},{"description":"Transfer chops to a plate, cover loosely with foil. Rest for 3 minutes before serving.","duration":3,"images":[],"step":6}]', '["gluten","mustard","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dinner-tonight","grilling-ideas-and-recipes","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2b021325e6d0', 'en', 'US', 'Bun Cha - Vietnamese Meatballs', 'Recipe video above. Everything you know and love about Vietnamese food - fresh, healthy and full of flavour! Bun Cha in Vietnam is served slightly differently (read in post), but here I''ve made noodle bowls which are more familiar to those outside of Vietnam. See Notes for what this tastes like!', 'https://www.recipetineats.com/tachyon/2019/01/Vietnamese-Pork-Meatballs_6.jpg', 20, 10, 30, 2, '[{"id": "ing_pork_mince", "quantity": {"value": 250.0, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_lemongrass", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.2, "unit": "pack of 500g"}}, {"id": "ing_big_handful_beansprouts", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["250 - 300 g/8 - 10 oz pork mince (ground pork)(Note 1)","1 tbsp fish sauce (Note 2)","2 tsp white sugar","1/3 cup finely chopped green onions / scallions","1 clove garlic (, minced)","Pinch of white pepper and salt","2 tsp lemongrass paste or fresh finely chopped (, optional (Note 4))","1 1/2 tbsp oil (, for cooking)"],"purpose":"Meatballs:"},{"ingredients":["3 tbsp white sugar","3 tbsp fish sauce (Note 2)","2 tbsp rice wine vinegar","2 tbsp lime juice","1/3 cup water","1 birds eye chilli (, seeded and finely chopped (Note 3))","3 cloves garlic (, finely chopped)"],"purpose":"Nuoc Cham (Vietnamese Dressing / Sauce – Note 2):"},{"ingredients":["100 g / 3.5 oz vermicelli noodles (, dried)","Big handful beansprouts","Few lettuce leaves (, folded or shredded)","Julienned carrot and white radish (daikon), optional quick pickle (Note 5)","Handful of coriander/cilantro sprigs (, mint)","Sliced red chilli (, lime wedges (optional))"],"purpose":"Serving (Note 4):"}]', '[{"title":"Sauce","description":"Mix ingredients. Set aside 10 minutes+.","images":[],"step":1},{"title":"Noodles","description":"Pour over boiling water and soak per packet directions. Drain, set aside.","images":[],"step":2},{"description":"Mix all ingredients except oil until combined.","images":[],"step":3},{"description":"Shape into 6 mini hamburger patties with your hands.","images":[],"step":4},{"description":"Heat oil in a skillet over medium high heat. Add patties and cook for 2 1/2 minutes or until golden. Flip, cook 2 minutes then remove.","images":[],"step":5},{"description":"Assemble Bowls:","images":[],"step":6},{"description":"Place noodles in bowl. Top with a handful of beansprouts, wedge in lettuce, carrots and radish in.","images":[],"step":7},{"description":"Place meatballs on top, top with coriander and mint.","images":[],"step":8},{"description":"Spoon over a generous amount of Sauce (it''s supposed to be like a soup broth), eat and be happy!","images":[],"step":9}]', '["fish"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["dinner-tonight","grilling-ideas-and-recipes","iconic-dishes","meatball-recipes","pork-recipes","quick-and-easy","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eea72dc7c5d1', 'en', 'US', 'Lemon Garlic Marinated Grilled Pork Chops', 'Recipe VIDEO above. Nothing infuses pork chops with flavour like a good marinade! This one is ideal for grilling so the high heat sears the crust beautifully. But the pork chops can of course be cooked on the stove, or even bake them! Also use this marinade for the proteins - see notes.', 'https://www.recipetineats.com/tachyon/2018/01/Lemon-Garlic-Oregano-Pork-Chops-3.jpg', 5, 10, 15, 4, '[{"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.1, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.1, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_pork", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}]', '[{"ingredients":["3 garlic cloves (, minced)","1 tbsp dried oregano (or other herbs, Note 1)","Zest of 1 lemon","1/3 cup (85 ml) lemon juice (1 large or 2 medium lemons)","1/4 cup (65 ml) olive oil","3/4 tsp salt","1/4 tsp black pepper"],"purpose":"Marinade:"},{"ingredients":["4 pork chops bone in (, 2cm / 4/5\" thick about 280g/9 oz each (Note 2))","Oil (, for cooking)"],"purpose":"Pork:"}]', '[{"description":"Whisk Marinade ingredients in a bowl (or ziplock bag). Add pork. Marinade for 1 hr minimum, 3 hours ideal, 12 hours max (Note 3).","duration":60,"images":[],"step":1},{"description":"Take the pork out of the fridge 20 minutes before cooking.","images":[],"step":2},{"description":"Shake excess marinade off (but don''t wipe dry) and cook using preferred method. Pictured in post served with Minted Yoghurt - see notes!","images":[],"step":3},{"description":"Brush grills / plate with oil and heat on high until smoking.","images":[],"step":4},{"description":"Place pork on grills and cook the first side for 4 minutes until it is nicely charred. Turn and cook the other side for 3 minutes. Turn the porks on their side to briefly sear the fat side (see video). Transfer to plate, rest for 3 - 5 minutes then serve.","duration":4,"images":[],"step":5},{"description":"Heat skillet with about 1 tbsp oil over high heat. Add pork and cook for 1 minute, then turn DOWN slightly to medium high. Cook for another 3 minutes, then turn and cook the other side for 3 minutes. Turn the porks on their side to briefly sear the fat side (see video).","duration":1,"images":[],"step":6},{"title":"Transfer to plate, rest for 3","description":"5 minutes then serve.","duration":4,"images":[],"step":7},{"description":"Preheat oven to 200C / 390F (fan forced / convection) or 220C / 430F (standard oven).","images":[],"step":8},{"description":"Place oven shelf in top 1/3 of oven.","images":[],"step":9},{"description":"Place pork on tray. Bake for 15 minutes, then flick to grill/broiler and grill on high for 5 minutes until the surface is nicely browned.","duration":15,"images":[],"step":10},{"title":"Transfer to plate, rest for 3","description":"5 minutes then serve.","duration":4,"images":[],"step":11}]', '[]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","dinner-tonight","gluten-free-recipes","greek-recipes","grilling-ideas-and-recipes","main-dishes","mediterranean-recipes","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_15bee2208c90', 'en', 'US', 'Chicken Burger Recipe', 'Recipe video above. Crispy seasoned chicken breast, topped with a mandatory slice of melted cheese and piled onto soft rolls with onion, avocado, lettuce, tomato and garlic mayo. The key to juicy chicken is to cook it hard and fast! You can eyeball the Seasoning - it will be tasty as long as you use "around" the right amounts. :)Want to the chicken mince version? Here''s it is!', 'https://www.recipetineats.com/tachyon/2017/07/Chicken-Burgers-4.jpg', 15, 10, 25, 4, '[{"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_paprika", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 2000.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken_breast", "quantity": {"value": 400.0, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.003, "unit": "jar of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_french_fries", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["1/3 cup /80g flour (any white)","1 tsp salt","½ tsp black pepper","¾ tsp paprika","1 tsp thyme","½ tsp garlic powder","½ tsp onion powder"],"purpose":"Seasoning:"},{"ingredients":["2 tbsp olive oil","2 large onions (, halved them sliced (white, brown or yellow))","400 - 500g / 14 oz - 1 lb chicken breast (2 pieces) (, cut in half horizontally into 2 thin steaks)","4 – 8 slices Swiss or other melting cheese slices (Note 1)","4 soft rolls (I used brioche burger buns)","1 avocado","Lettuce","2 large tomatoes"],"purpose":"Burgers:"},{"ingredients":["½ cup mayonnaise (I use whole egg)","1 large garlic clove (, minced)"],"purpose":"Garlic Mayo:"},{"ingredients":["French fries","Baked potato wedges"],"purpose":"On the side"}]', '[{"description":"Mix Garlic Mayo ingredients in a small bowl, set aside for 20+ minutes.","images":[],"step":1},{"description":"Mix Seasoning in a flat bowl / dish.","images":[],"step":2},{"description":"If required, pound chicken to about 1 cm / 2/5” thick. If wanting to be exact, trim to shape of rolls BUT ensure it is about 15% larger (it shrinks) (Note 2).","images":[],"step":3},{"description":"Heat 1 tbsp oil in a skillet over high heat (if doing on BBQ, drizzle flat plate).","images":[],"step":4},{"description":"Add onion and cook, turning regularly, for 5 minutes until golden. Season with salt and pepper, toss, then remove.","duration":5,"images":[],"step":5},{"description":"While cooking the onions, preheat oven to 160C/320F. Split rolls, then lightly toast / warm the rolls (if using BBQ, just toast the cut side until crispy). Leave in turned off oven with door ajar while you cook chicken.","images":[],"step":6},{"description":"Heat 1 tbsp oil into the same skillet, still on high heat.","images":[],"step":7},{"description":"Dredge chicken in Seasoning, shake off excess, then place in skillet. Repeat.","images":[],"step":8},{"description":"Cook for 2 ½ minutes until golden, then flip.","images":[],"step":9},{"description":"Top with cheese then leave for 1 1/2 minutes. When the underside is golden, if the cheese is not yet melted, place lid on for 15 seconds (or tray or foil).","duration":0.25,"images":[],"step":10},{"description":"Remove chicken from skillet onto plate. Cover loosely with foil while you start assembling the burgers.","images":[],"step":11},{"description":"Smear base of roll with avocado, sprinkle with salt and pepper. Top with chicken, onion, lettuce then tomato.","images":[],"step":12},{"description":"Smear lid of roll with Garlic Mayo, place on burger. Enjoy!","images":[],"step":13}]', '["egg","gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["burger-recipes","chicken-breast-recipes","chicken-recipes","dinner-tonight","grilling-ideas-and-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5e23c18c020d', 'en', 'US', 'Creamy Garlic Prawns / Shrimp and Cheesy Potatoes Foil Packet Recipe', 'Recipe video above. Juicy, perfectly cooked prawns/shrimp bathed in a creamy garlic sauce piled on top of cheesy potatoes with a side of steamed asparagus, all cooked in a foil packet! Grill these on the BBQ, bake them in the oven or even cook these on the stove!', 'https://www.recipetineats.com/tachyon/2017/06/Creamy-Prawn-Cheesy-Potatoes-Foil-Pack_1.jpg', 10, 10, 20, 4, '[{"id": "ing_potato", "quantity": {"value": 600.0, "unit": "bag of 2kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_shrimp", "quantity": {"value": 20.0, "unit": "kg"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.75, "unit": "pack of 125g"}}, {"id": "ing_es_asparagus", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["600 g / 1.2 lb potatoes (, peeled and cut into 1.5cm cubes)","1 tsp dried thyme leaves (optional)","Salt and pepper","3/4 cup thickened / heavy cream","30 - 50 g / 2 - 3 tbsp butter (more = richer!)","1 garlic clove (, minced)","20 - 24 prawns/shrimp (, peeled and deveined, tail on or off)","3/4 - 1 cup mozzarella or other melting cheese of choice","2 - 3 bunches asparagus (, trimmed then cut in half, fat ones vertically cut in half (Note 1))","Finely chopped parsley"]}]', '[{"description":"Bring a large pot of water to the boil. Add potatoes and cook for 5 minutes or until just cooked.","duration":5,"images":[],"step":1},{"description":"Drain potatoes, then sprinkle with salt, pepper and thyme. Toss to coat.","images":[],"step":2},{"description":"Meanwhile, place the cream, butter and garlic in a heatproof bowl. Microwave 30 - 40 seconds on high, until butter melts when stirred. If time permits, cool (place in fridge to speed up). (Note 1)","images":[],"step":3},{"description":"Preheat oven to 200C/390F (standard) or 180C/350F (fan/convection) or BBQ on medium high with hood down.","images":[],"step":4},{"description":"Tear 4 x 45cm/18\" pieces of heavy duty foil (Note 2).","images":[],"step":5},{"description":"Divide potatoes among foil sheets. Top with cheese, then prawns and asparagus, then drizzle over cream sauce.","images":[],"step":6},{"description":"Sprinkle with salt, pepper and parsley.","images":[],"step":7},{"description":"Bring the long ends of the foil together over the prawns, then fold down to seal, then fold in the sides (watch video, it''s easy!)","images":[],"step":8},{"description":"Place on a baking tray or BBQ and cook for 10 minutes (small prawns) - 12 minutes (medium prawns). (Note 4)","duration":10,"images":[],"step":9},{"title":"Serve immediately","description":"do not leave them sitting around inside the unopened packet, the prawns and asparagus will overcook and leech water, making the sauce watery.","images":[],"step":10}]', '["milk","shellfish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","grilling-ideas-and-recipes","main-dishes","one-pot-recipes","prawns-shrimp","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_49339ac0168c', 'en', 'US', 'Carne Asada', 'The famous Latin American grilled beef! Marinated in a wicked Carne Asada marinade that infuses and tenderises the beef, this is beautiful made with any cut of beef suitable for quick grilling but is traditionally made with flank and skirt steak. Use for tacos, burritos or serve on rice, or try a salad! This recipe serves 5 - 6, because it''s sliced thinly a bit goes a long way.', 'https://www.recipetineats.com/tachyon/2017/06/Carne-Asada-4.jpg', 10, 8, 18, 6, '[{"id": "ing_garlic", "quantity": {"value": 6.667, "unit": "pack of 3 heads"}}, {"id": "ing_oranges", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_ime_juice", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.25, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_jalapeno", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_1_2kg_1_5_2_5lb_skirt_of_flank", "quantity": {"value": 750.0, "unit": "unit"}}, {"id": "ing_tortillas", "quantity": {"value": 1.0, "unit": "pack of 8"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 0.075, "unit": "net of 500g"}}]', '[{"ingredients":["4 cloves garlic (, minced)","1/2 cup / 125 ml orange juice","1/4 cup / 65 ml lime juice (about 2 limes)","1 cup finely chopped coriander / cilantro","1/2 teaspoon salt","1/4 teaspoon black pepper","1/4 cup / 65 ml olive oil","1 jalapeno ((fresh), finely minced)","2 tbsp white vinegar (any clear or clear-ish vinegar will be ok here e.g. white wine vinegar, cider vinegar)"],"purpose":"Marinade:"},{"ingredients":["Oil","750 g - 1.2kg / 1.5 - 2.5lb skirt of flank (I used a 900g/1.8lb skirt) (Note 1)"],"purpose":"Cooking:"},{"ingredients":["Tortillas","Avocado Slices","Pico De Gallo or Tomato","Coriander/cilantro leaves","Lime wedges"],"purpose":"To Serve as Carne Asada Tacos:"}]', '[{"description":"Place the Marinade ingredients in a large ziplock bag and mix. Add beef and massage through the bag to coat evenly. Seal then marinate for 1- 8 hours (12 hours max, otherwise meat gets over marinated and can be mushy).","images":[],"step":1},{"title":"Take the skirt steak out of the fridge 20","description":"30 minutes before cooking to bring to room temperature.","images":[],"step":2},{"description":"Brush BBQ with oil and heat on high until smoking (or use a large skillet over high heat and turn the fan on!).","images":[],"step":3},{"description":"Cook skirt steak for 3 minutes each side for rare, 4 minutes for medium rare. For flank, cook for 4 minutes each side for rare and 5 minutes for medium rare. Don''t cook beyond medium - chewy beef!","duration":3,"images":[],"step":4},{"description":"Remove onto a plate and cover loosely with foil. Rest for 5 minutes then slice thinly against the grain (Note 2).","duration":5,"images":[],"step":5},{"description":"Serve with tacos, in burritos or on rice!","images":[],"step":6}]', '[]', '["gluten_free","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["South American"],"categories":["beef-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","mexican-recipes","quick-and-easy","south-american-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_90eeed1c7626', 'en', 'US', 'Rosemary Garlic Grilled Lamb Chops', 'A tasty way to prepare economical cuts of lamb chops and steaks! Tenderise and infuse them with flavour with a delicious marinade then grill to perfection on the BBQ (or stove). Marinade for at least 2 hours, preferably overnight (no longer than 24 hours). Update: This is (was!) a tart marinade and following feedback from some readers by email and from a friend, I have tweaked the recipe slightly to take the edge off the vinegar. :) Resounding feedback all round!', 'https://www.recipetineats.com/tachyon/2016/12/Rosemary-Garlic-Marinated-Lamb-Chops-5.jpg', 5, 10, 15, 4, '[{"id": "ing_lamb", "quantity": {"value": 600.0, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_vinegar", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_honey", "quantity": {"value": 0.03, "unit": "jar of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 0.125, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["600 - 800 g / 1.2 - 1.6lb lamb chops (4 - 8, depending on size)","Oil (, for cooking, if required)"]},{"ingredients":["2 1/2 tbsp red wine vinegar","1 tbsp extra virgin olive oil","1 tbsp honey","3 garlic cloves (, minced)","1 1/4 tsp finely chopped fresh rosemary (or 1 tsp dried rosemary)","1/2 tsp dried thyme","3/4 - 1 tsp sea salt","Black pepper"],"purpose":"Marinade"}]', '[{"description":"Mix Marinade ingredients in a bowl until salt dissolves. Add lamb, mix to coat, then marinate at least 2 hours, preferably overnight, up to 24 hours.","images":[],"step":1},{"description":"Brush BBQ bars with oil if required (Note 1) and heat to medium high (or heat 1/2 tbsp oil in skillet on stove on medium high).","images":[],"step":2},{"description":"Cook lamb to your taste. I had 4 x 150g/5oz lamb loin chops about 2cm/3/4\" thick and 3 minutes on each side = medium. I also cooked smashed garlic cloves and rosemary sprigs for garnish.","images":[],"step":3},{"description":"Transfer lamb to plate, cover loosely with foil and rest for 5 minutes.","duration":5,"images":[],"step":4},{"description":"Serve with sides of choice!","images":[],"step":5}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","gluten-free-recipes","grilling-ideas-and-recipes","lamb-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_206b298a2d19', 'en', 'US', 'Chicken Souvlaki with Tzatziki', 'This Greek favourite is so easy to make at home! Loaded with classic Greek flavours of lemon, garlic and dried oregano. Fabulous for an outdoor BBQ!', 'https://www.recipetineats.com/tachyon/2016/07/Chicken-Souvlaki_1.jpg', 15, 10, 25, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.075, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.375, "unit": "tub of 500g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["1.5 lb / 750 g chicken thigh fillets ((or breast), cut into 1\"/2.5cm pieces)","2 tbsp olive oil","1/4 cup lemon juice","3 garlic cloves (, minced)","2 tbsp dried oregano","1/2 - 3/4 tsp salt","Black pepper"],"purpose":"Marinade"},{"ingredients":["1 tbsp olive oil","Flatbreads / wraps / pita bread","Lettuce","Tomato slices"],"purpose":"To Cook / Serve"},{"ingredients":["2 Lebanese cucumbers (to make about ½ cup grated cucumber after squeezing out juice)","1 1/4 cups / 300 g plain Greek yoghurt","2 tsp white wine vinegar (or red wine or apple cider vinegar)","1 tbsp lemon juice","1/2 garlic clove (, minced)","1 tbsp extra virgin olive oil (or more if you want richer)","1/2 tsp salt","Black pepper"],"purpose":"Tzatziki"}]', '[{"description":"Place chicken and Marinade into a bowl and set aside to marinate for at least 3 hours to overnight.","images":[],"step":1},{"description":"Thread chicken onto 8 skewers.","images":[],"step":2},{"description":"Heat oil in a large skillet over high heat (or BBQ). Cook skewers for 3 minutes on each side, or until cooked through.","duration":3,"images":[],"step":3},{"description":"Serve Chicken Souvlaki with tzatziki, flatbreads (make your own!), lettuce and tomato slices.","images":[],"step":4},{"description":"Cut the cucumber in half lengthwise. Use a teaspoon to scrape the watery seeds out. Coarsely grate the cucumber using a box grater. Then wrap in paper towels or a tea towel and squeeze to remove excess liquid.","images":[],"step":5},{"description":"Place cucumber in a bowl. Add remaining ingredients then mix to combine. Set aside for at least 20 minutes for the flavours to meld.","images":[],"step":6}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","greek-recipes","grilling-ideas-and-recipes","mediterranean-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3aca52194d76', 'en', 'US', 'Pineapple Coconut Hawaiian Chicken Skewers', 'This recipe is based on the marinade of the Hawaiian street food chicken you can get from roadside stalls throughout Hawaii, except I added coconut. Coconut is a brilliant base for marinades because it adds richness into the flesh as well as infusing it with sweetness and coconut flavours. I served this with a Coconut Lime Rice (it uses the balance of coconut milk leftover after this recipe from a standard 14oz/400g can). MARINATING TIME: 3 hrs - overnight recommended, but even 20 minutes is enough.', 'https://www.recipetineats.com/tachyon/2016/05/Coconut-Pineapple-Chicken-Skewers_4.jpg', 15, 10, 25, 8, '[{"id": "ing_coconut_milk", "quantity": {"value": 0.469, "unit": "can of 400ml"}}, {"id": "ing_pineapple", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.18, "unit": "bottle of 250ml"}}, {"id": "ing_lime", "quantity": {"value": 0.225, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.5, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_skewers", "quantity": {"value": 8.0, "unit": "pack of 50"}}]', '[{"ingredients":["3/4 cup coconut milk (from a 14oz/400g can, use leftovers for Coconut Lime Rice!)","1/2 cup pineapple juice (Note 1)","3 tbsp brown sugar","2 tbsp tomato sauce/ketchup","3 tbsp soy sauce","Zest and juice of 1 lime","2 garlic cloves (, minced)","1/2 tsp EACH onion powder (, cumin, paprika,)","1 tsp ginger powder (or 1/2 tsp grated fresh ginger)","1/2 - 1 tsp cayenne pepper (, optional)","1/2 tsp salt"],"purpose":"Marinade"},{"ingredients":["1.5 lb / 750g chicken thigh fillets (, cut into 1\"/2.5cm pieces)","1 tbsp olive or vegetable oil","8 skewers (, soaked in water for 30 minutes if cooking on outdoor BBQ)"],"purpose":"Skewers"}]', '[{"description":"Combine Marinade ingredients in a bowl. Remove 1/2 cup of Marinade (for basting) and set aside in fridge. Add chicken, cover and marinate in the fridge for at least 3 hours, preferably overnight. But even 20 minutes is enough - compensate with extra basting.","images":[],"step":1},{"description":"Drain and discard marinade. Thread chicken onto skewers.","images":[],"step":2},{"description":"Heat oil in a large skillet or on outdoor BBQ over medium high heat. Cook skewers, turning to cook all sides, and basting generously with reserved Marinade. (Note 1)","images":[],"step":3},{"description":"Serve with Coconut Lime Rice.","images":[],"step":4}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Hawaiian"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","most-popular","quick-and-easy","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e454613f7927', 'en', 'US', 'Mexican Grilled Chicken Tacos', 'Wonderfully authentic Mexican flavours, a homestyle version of Sinaloa chicken, a popular Mexican street food. Adapted from Bobby Flay''s "Mexican Red Chicken" recipe from his cookbook "Bobby Flay''s Barbecue Addiction". (Note 1)', 'https://www.recipetineats.com/tachyon/2016/04/Mexican-Grilled-Chicken-Tacos_1.jpg', 5, 10, 15, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_oranges", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_ime_juice", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_chipotle", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_tortillas", "quantity": {"value": 1.0, "unit": "pack of 8"}}, {"id": "ing_pico_de_gallo", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 0.045, "unit": "net of 500g"}}]', '[{"ingredients":["1 - 1.5 lb / 500 - 750g chicken thigh fillets (Note 2)","1 tbsp olive oil"]},{"ingredients":["4 tbsp orange juice","2 tbsp apple cider vinegar (or rice vinegar)","1 1/2 tbsp lime juice","3 garlic cloves (, minced)","1 1/2 tbsp chipotle or ancho chile powder (Note 3)","2 tsp dried oregano","2 tsp smoked paprika powder (Note 4)","1/8 tsp All Spice","1/4 tsp cinnamon powder","1/4 - 1/2 tsp cayenne pepper (optional - for spiciness)","1 tsp salt","Black pepper"],"purpose":"Marinade"},{"ingredients":["Tortillas or taco shells","Pico de Gallo (tomato salsa)","Sour cream","Avocado","Fresh coriander / cilantro","Lime wedges"],"purpose":"Taco Fixings"}]', '[{"description":"Place Marinade ingredients in a ziplock bag. Add chicken, massage to coat then refrigerate to marinate for at least 3 hours, preferably overnight.","images":[],"step":1},{"description":"Remove chicken from Marinade, discard Marinade.","images":[],"step":2},{"description":"Heat oil in a skillet over medium high heat (or even better, do this on the BBQ on medium high). Cook chicken for 4 minutes on each side, until dark golden brown.","duration":4,"images":[],"step":3},{"description":"Remove chicken onto plate, cover loosely with foil and rest for 3 minutes.","duration":3,"images":[],"step":4},{"description":"Cut into strips and use for tacos. (See Note 5 for more serving options)","images":[],"step":5}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","mexican-recipes","quick-and-easy","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4a3c120e6ed8', 'en', 'US', 'Beef Steak Fajitas', 'Recipe video above. Beef Fajitas made extra juicy and extra tasty with a wicked marinade that tenderises and flavours the beef! But if you don''t have time to marinade, see Note 7 for a faster version. Adapted from this recipe by Tyler Florence (mine is easier and I think it is just as tasty!)', 'https://www.recipetineats.com/tachyon/2016/03/Beef-Fajitas_4.jpg', 15, 15, 30, 4, '[{"id": "ing_beef_steak", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_oranges", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_chipotle", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 2.0, "unit": "bottle"}}, {"id": "ing_capsicum", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.5, "unit": "pack of 1kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_tortillas", "quantity": {"value": 12.0, "unit": "pack of 8"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 lb / 500g beef steak (rump and skirt are ideal) (Note 1)","4 tbsp / 1/4 cup orange juice (, fresh (1 orange))","2 tbsp lime juice","2 garlic cloves (, minced)","1/2 tsp cumin powder","1/2 tsp coriander powder","1/2 tsp onion powder (optional)","1 tsp chipotle powder (Note 2)","1/2 tsp salt","Black pepper"],"purpose":"Marinated Beef"},{"ingredients":["2 - 3 tbsp oil","2 bell peppers/capsicum (, sliced (Note 3))","1 large onion (, halved and sliced (brown, yellow, white))","Salt and pepper"],"purpose":"Fajitas"},{"ingredients":["12 tortillas (, small)","Avocado","Cilantro/coriander","Sour cream","Lime wedges","Tomatoes (, sliced, or Pico de gallo)"],"purpose":"Fixings"}]', '[{"description":"Place the Marinated Beef ingredients in a ziplock bag, massage to coat then refrigerate for 2 hour to overnight.","images":[],"step":1},{"description":"Remove beef from marinade 30 minutes prior to cooking (to bring to room temperature) and pat dry with paper towels. Discard marinade.","images":[],"step":2},{"description":"Drizzle 1/2 tbsp of oil on each side of the beef (1 tbsp in total).","images":[],"step":3},{"description":"Heat the BBQ or a skillet on high heat. Cook beef to your liking. (Note 4)","images":[],"step":4},{"description":"Remove beef onto a plate and cover loosely with foil.","images":[],"step":5},{"description":"Return skillet to stove, still on high heat, and heat 1/2 tbsp oil. Add onions, sprinkle with salt and pepper, and cook until soft and charred. Remove onto serving plate.","images":[],"step":6},{"description":"Heat remaining 1/2 tbsp oil in the skillet. Add bell pepper/capsicum, sprinkle with salt and pepper, and cook until charred. Remove onto plate.","images":[],"step":7},{"description":"Slice beef thinly against the grain (Note 5).","images":[],"step":8},{"description":"Serve with warmed tortillas and fixings of choice. (Note 6)","images":[],"step":9}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["beef-recipes","dietary","fajitas","gluten-free-recipes","grilling-ideas-and-recipes","low-calorie-recipes","mexican-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1ee599ec9dd5', 'en', 'US', 'Turkish Lamb Kofta Kebabs', 'A simple, exotic, fragrant midweek meal. 30 minutes, start to finish. Adapted from a recipe by Effendi restaurant in Balmain, Sydney, as shown in the Food Safari "Fire" TV series. See notes for changes made to the original recipe.', 'https://www.recipetineats.com/tachyon/2016/02/Turkish-Kebabs-1_3.jpg', 20, 10, 30, 4, '[{"id": "ing_lamb_mince", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_pistachio_nuts", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}]', '[{"ingredients":["1 lb / 500g lamb mince (ground lamb) (or substitute with beef)","1 small onion (, grated or minced using a food processor - about 1/4 cup (white, brown or yellow) (Note 1))","1 garlic clove (, minced)","1/4 cup pistachio nuts (, ground (Optional. I use my food processor) (Note 2))","3/4 tsp cooking salt / kosher salt (halve for table salt, +50% for salt flakes)","1 tsp black pepper","1 tbsp cumin powder","1 tbsp red pepper flakes","1 tbsp olive oil"],"purpose":"Kebabs"},{"ingredients":["3/4 cup plain yoghurt (I use Greek)","1 tbsp lemon juice","1/2 garlic clove (, minced)","Salt and pepper"],"purpose":"Yoghurt Sauce"},{"ingredients":["Pita bread or lebanese flat bread (, warmed)","Lettuce leaves of choice","Sliced tomato","Sliced red onion"],"purpose":"To Serve"}]', '[{"description":"Mix together Yoghurt Sauce ingredients and place in the refrigerator to allow the flavours to develop.","images":[],"step":1},{"description":"Place the Kebab ingredients except the oil in a bowl and use your hands to just combine (don''t over mix).","images":[],"step":2},{"description":"Divide into 8 portions and mould onto skewers.","images":[],"step":3},{"description":"Heat oil in a large skillet over medium high heat. Add skewers (I could fit all in, placing them in alternating directions) and cook for 8 minutes, turning to brown all sides.","duration":8,"images":[],"step":4},{"description":"Meanwhile, slice tomatoes and red onion.","images":[],"step":5},{"description":"Serve kebabs with pita bread, lettuce, tomatoes, red onion and yoghurt sauce on the side. Wedges of lemon are also a great accompaniment.","images":[],"step":6}]', '["gluten","milk","nuts"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Turkish"],"categories":["cuisines","dietary","dinner-tonight","gluten-free-recipes","grilling-ideas-and-recipes","lamb-recipes","main-dishes","middle-eastern-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_58ce4d3da4a7', 'en', 'US', 'Peruvian Chicken with Garlic Butter Rice', 'Known as Peruvian Blackened Chicken ("Pollo a la Brasa"), this chicken is traditionally made on a rotisserie. As with every ethnic dish, there are many many versions but the common ingredients in all are soy sauce, garlic and paprika. I served this with a garlic butter rice on the side. The rice recipe makes enough for around 6 servings and you''ll be thankful for this because it''s so yummy, you will want leftovers for the next day!', 'https://www.recipetineats.com/tachyon/2015/12/Peruvian-Roast-Chicken_1.jpg', 10, 45, 55, 4, '[{"id": "ing_chicken", "quantity": {"value": 1.134, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.24, "unit": "bottle of 250ml"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_rice", "quantity": {"value": 300.0, "unit": "pack"}}, {"id": "ing_chicken", "quantity": {"value": 1.134, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2.5 lb (1.2 kg) chicken pieces (Note 1)"]},{"ingredients":["1 tbsp garlic powder OR 3 garlic cloves (, minced)","2 tsp cumin powder","1 tbsp paprika powder (preferably smoked but plain is ok)","4 tbsp soy sauce (Note 2)","2 tbsp lime juice (, fresh (1 lime))","1 tbsp olive oil"],"purpose":"Marinade"},{"ingredients":["4 garlic cloves, minced","1/2 onion (, finely diced (white, brown, yellow))","1 tbsp olive oil","2 cups long grain rice (, uncooked)","2 cups chicken broth / stock","1 cup water","2 - 4 tbsp butter (Note 3)","Salt and pepper"],"purpose":"Garlic Butter Rice"}]', '[{"description":"Place the Marinade ingredients in a small bowl and mix until lump free.","images":[],"step":1},{"description":"Place the chicken in a ziplock bag (my preferred method) or non reactive bowl and coat with Marinade. Marinade for at least 3 hours, preferably overnight (24 hours) OR freeze it straight away, then it will marinade while it defrosts.","images":[],"step":2},{"description":"Preheat oven to 180C/350F. Place chicken in a baking dish, skin side up. Slather leftover marinade onto the skin. Roast for 45 minutes or until deep burnt-red golden brown in colour.","duration":45,"images":[],"step":3},{"description":"Rest for 5 minutes before serving with Garlic Butter Rice and a green salad.","duration":5,"images":[],"step":4},{"description":"Garlic Butter Rice","images":[],"step":5},{"description":"Heat oil in a saucepan over medium heat. Add garlic and onion and cook for 5 minutes until onion is translucent and sweet.","duration":5,"images":[],"step":6},{"description":"Add rice and stir so the rice becomes translucent. Add broth and water, then cover and turn heat down to medium low.","images":[],"step":7},{"description":"Cook for 12 to 15 minutes until the liquid has JUST evaporated, then remove from stove and allow to rest for 10 minutes.","duration":13.5,"images":[],"step":8},{"description":"After resting, add the butter and stir the rice to fluff it up and disperse the butter.","images":[],"step":9}]', '["gluten","milk","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Peruvian","South American"],"categories":["chicken-drumstick-recipes","chicken-recipes","dietary","gluten-free-recipes","grilling-ideas-and-recipes","quick-and-easy","rice-recipes","south-american-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_25c585b65bde', 'en', 'US', 'Blackened Fish Tacos', 'Fish cooked with a punchy spice rub of Cajun Flavours! Perfectly paired with a Avocado-Lime Slaw to make these irresistible tacos.', 'https://www.recipetineats.com/tachyon/2015/10/Blackened-Fish-Tacos1-Featured.jpg', 20, 6, 26, 8, '[{"id": "ing_greek_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_imes_zested_and_juiced", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_jalape_os", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_mint", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_red_cabbage", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_cabbage", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.094, "unit": "jar of 400g"}}, {"id": "ing_sriracha", "quantity": {"value": 0.013, "unit": "bottle of 400ml"}}, {"id": "ing_lime", "quantity": {"value": 4.0, "unit": "net of 500g"}}, {"id": "ing_paprika", "quantity": {"value": 0.75, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_tortillas", "quantity": {"value": 8.0, "unit": "pack of 8"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["½ cup greek yogurt","1 avocado","1 cup cilantro/coriander leaves","2 garlic cloves","2 limes zested and juiced","2 jalapeños","2 tbsp mint (, roughly chopped)","½ tsp Kosher salt","Freshly ground black pepper (, to taste)","1 cup red cabbage (, finely shredded*)","1 cup green cabbage (, finely shredded*)","2 carrots (, grated*)"],"purpose":"Avocado-Lime Slaw"},{"ingredients":["1/4 cup mayonnaise","1 tsp Sriracha","1 tbsp fresh lime juice"],"purpose":"Quick Sriracha Aioli"},{"ingredients":["2 tbsp paprika","2 tsp ground cumin","2 tsp onion powder","2 tsp garlic powder","2 tsp dried thyme","2 tsp dry mustard","1 1/4 tsp Kosher salt","1/4 tsp cayenne pepper","2 tbsp extra virgin olive oil","4 tilapia fillets"],"purpose":"Blackened Fish"},{"ingredients":["8 (6 inch) tortillas","2 jalapeños (, sliced)","1 small bunch cilantro"],"purpose":"To Serve"}]', '[{"description":"In the bowl of a food processor, add the yogurt, avocado, cilantro, garlic, lime zest, lime juice, jalapeños, mint, salt, and pepper. Puree until smooth and creamy. Taste and add more salt and pepper, if needed. Place the shredded cabbage and carrots in a large bowl. Add 1/2 a cup of the avocado-lime dressing from the food processor and stir to combine. Add more dressing if you would like a creamier slaw. If not, you can use the extra dressing to top the tacos later. Refrigerate until ready to use.","images":[],"step":1},{"description":"In a small bowl, combine the ingredients for the Sriracha Aioli. Refrigerate until ready to use.","images":[],"step":2},{"description":"If you would like to toast the tortillas (highly recommended if you are using corn tortillas)* heat a pan over medium-high heat. Once hot, warm each tortilla 1 to 2 minutes per side – you want to heat the tortillas just enough to slightly char and add a bit of crispness, but not so much that when you fold it, it cracks. Wrap the tortillas in a clean tea towel to keep warm and set aside.","images":[],"step":3},{"description":"On a large plate, combine all of the spices to make the blackened seasoning. Dredge both sides of each fish fillet in the spice mixture. In a large saute pan, heat the olive oil over medium-high heat. At the first wisp of smoke from the pan, add the fillets, working in batches if needed. Cook for 2 -3 minutes on each side. (Do not move the fish fillets around while they''re cooking. Leave them be until they''re ready to flip). Transfer the cooked fillets to a cutting board and slice each fillet in-half, vertically - making 8 pieces.","duration":2.5,"images":[],"step":4},{"description":"To serve, top each tortilla with the fish, avocado-lime slaw, jalapeños, cilantro, and drizzle with the Sriracha aioli. Serve with extra wedges of lime and enjoy!","images":[],"step":5}]', '["milk","mustard"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Fusion"],"categories":["dietary","dinner-tonight","fish-recipes","gluten-free-recipes","grilling-ideas-and-recipes","main-dishes","mexican-recipes","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5e4a72222a2c', 'en', 'US', 'One-pan baked sausage & lentils', 'Recipe video above. In this recipe where both lentils and sausages are baked together in the same pan, the lentils absorb the sausage juices as they cook, making the humble lentils tastier than you ever dreamed possible! The recipe starts on the stove sautéing aromatics right in the roasting pan. Any metal pan will work, and it doesn''t matter if your stove burner isn''t large enough for the roasting pan- mine certainly isn''t.Don''t skip the cumin seeds. It gives this a special touch!', 'https://www.recipetineats.com/tachyon/2023/03/Baked-sausage-with-lentils_9.jpg', 10, 50, 60, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 4.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_lentils", "quantity": {"value": 0.562, "unit": "can of 400g"}}, {"id": "ing_carrot", "quantity": {"value": 4.0, "unit": "pack of 1kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_sausages", "quantity": {"value": 8.0, "unit": "pack of 500g"}}]', '[{"ingredients":["3 tbsp extra virgin olive oil","4 eschallots/shallots (, peeled, halved, finely sliced (sub 1 large onion, Note 1))","3 garlic cloves (, finely minced)","1 tbsp cumin seeds (don''t skip this!)","1 1/2 cups puy lentils / French lentils (sub green/brown lentils, Note 3)","4 small carrots (, peeled, quartered, diced into 8mm/ 1/3\" cubes)","1 tsp cooking salt (kosher salt)","3/4 tsp black pepper","3 cups chicken broth/stock (, low sodium)","8 x 85g/3oz pork sausages (Note 3)"]}]', '[{"description":"Pre-heat oven to 200°C/400°F (180°C fan).","images":[],"step":1},{"title":"Cooking vessel","description":"Use a metal roasting pan ~23 x 33 cm / 9 x 13\". Fold a sheet of baking/parchment paper (large enough to cover pan) in half and cut 4 x ~10cm/4\" slits (steam vents! Note 4). Else, use foil - just tear steam vents.","images":[],"step":2},{"title":"Sauté aromatics","description":"Put the pan directly on the stove (really, it''s ok!) and heat the olive oil over medium high heat. Add eschallots and garlic, sauté for 3 minutes until soft. Add cumin seeds and stir for 1 minute.","duration":3,"images":[],"step":3},{"title":"Lentils & stock","description":"Add dried lentils, carrot, salt, pepper and stock. Bring to a simmer.","images":[],"step":4},{"title":"Sausages & paper","description":"Gently place the sausages on top (don''t press in). Cover with the paper, gently pressing so it \"sticks\" to the stock.","images":[],"step":5},{"description":"Bake for 25 minutes on the middle shelf. Remove paper and bake for 20 more minutes to brown the sausages.","duration":25,"images":[],"step":6},{"title":"Rest 5 min","description":"Remove from the oven. Rest for 5 minutes.","duration":5,"images":[],"step":7},{"description":"Serve the sausages with lentils. The flavour-loaded lentils are saucy so they act as the sauce for the sausages! Also pictured in post - baby spinach with Everyday Dressing.","images":[],"step":8}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","lentil-recipes","quick-and-easy","sausage-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b1885916fa7d', 'en', 'US', 'Greek Marinated Chickpea Salad', 'Recipe video above. Chickpea salads can be so bland... but not this one! We''re marinating the chickpeas so they absorb the flavour of the lovely Greek dressing. Mediterranean flavours, bright and fresh,this works as a starch + veg side dish, or main course served with crusty bread or flatbreads for scooping!Serves 4 as a main course or 8 as a side.', 'https://www.recipetineats.com/tachyon/2020/06/Chickpea-Salad_0.jpg', 10, 0, 10, 4, '[{"id": "ing_chickpeas", "quantity": {"value": 2.0, "unit": "can of 400g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_spinach", "quantity": {"value": 3.0, "unit": "bag of 250g"}}, {"id": "ing_feta_cheese", "quantity": {"value": 100.0, "unit": "block of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}]', '[{"ingredients":["800g/ 14oz (2 cans) chickpeas, (well drained (Note 1))"]},{"ingredients":["2 tbsp red wine vinegar (Note 2)","5 tbsp extra virgin olive oil","1 garlic clove (, minced using garlic press)","2 tsp dried oregano","1/2 tsp dijon mustard (or other non spicy smooth mustard)","3/4 tsp EACH salt and pepper"],"purpose":"Dressing / Marinade:"},{"ingredients":["1/2 red onion (, finely sliced)","1/2 cup red wine vinegar (Note 2)","1 tsp white sugar","1/2 tsp salt"],"purpose":"Quick pickled onion (pickling optional, Note 3):"},{"ingredients":["250g/ 8oz cherry or grape tomatoes (, halved (or 2 normal tomatoes))","3 cups (packed) spinach, (sliced 1/2 cm / 1/5\" thick (Note 4))","100g/ 3oz feta","3/4 cup chargrilled peppers (, drained and sliced 1cm / 1/3\" thick (optional, Note 5))"],"purpose":"Salad:"}]', '[{"description":"Shake Dressing in a jar.","images":[],"step":1},{"description":"Marinated chickpeas:","images":[],"step":2},{"description":"Place chickpeas in a microwaveable bowl. Toss with half the Dressing.","images":[],"step":3},{"description":"Microwave 1 1/2 minutes, stirring every 30 seconds, until warmed through.","images":[],"step":4},{"description":"Set aside 20 minutes to marinate (warm chickpeas = absorbs flavour).","images":[],"step":5},{"description":"Quick Pickled Onion:","images":[],"step":6},{"description":"Mix ingredients in a bowl, set aside 30 minutes until onion is wilted. Drain.","images":[],"step":7},{"title":"Speedy option","description":"microwave for 2 minutes until hot, cool 10 minutes then use.","duration":2,"images":[],"step":8},{"description":"Assemble salad:","images":[],"step":9},{"description":"Place spinach in a big bowl, add marinated chickpeas (including all residual Dressing in the bowl). Add tomatoes, pickled onion and peppers, if using.","images":[],"step":10},{"description":"Pour over remaining Dressing, toss well. Transfer to serving plate, crumble over feta, serve!","images":[],"step":11}]', '["mustard"]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner","lunch"],"cuisine":["Greek(ish)","Western"],"categories":["beans-lentils","lentil-recipes","quick-and-easy","salad-recipes-main-course","side-dishes","side-salads"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7687065f7be2', 'en', 'US', 'Creamy Tomato Bean Soup', 'Recipe video above. This is a white bean soup with a thick, creamy broth that''s full of savoury flavour with a hint of tomato. It''s a fast way to turn bland beans into a really filling soup that so simple to make, yet so, so good! The flavour trick - blitzing up the sautéed onion, carrot and garlic with just a bit of the beans. Keep it meat free or see notes for how to add ham, bacon, chicken or sausage! This is VERY filling - and keeps you full for ages (thank you beans!)', 'https://www.recipetineats.com/tachyon/2020/04/Creamy-Tomato-Bean-Soup_0.jpg', 5, 20, 25, 4, '[{"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_x_420g_cans_cannellini_or_any_white_beans_drained_rinsed", "quantity": {"value": 3.0, "unit": "pack"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 120.0, "unit": "bag of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}]', '[{"ingredients":["2 tbsp/ 30g butter (, unsalted)","1 onion (, finely chopped (brown, yellow, white))","2 garlic cloves (, finely chopped)","1 carrot (, large, peeled and finely chopped)","1 1/2 tsp Italian herb mix OR other dried herbs (oregano, thyme, parsley, basil, or mixed)","3/4 cup (170g) tomato paste (Note 1)","1/2 cup (125ml) dry white wine (, optional (can omit) )","4 cups (1 litre) stock/broth, chicken or veg (, low sodium)","3 x 420g/15oz cans cannellini or any white beans, drained & rinsed","1/2 cup (50g) parmesan (, grated)","1/2 tsp EACH salt and pepper","120g/4oz baby spinach (or 5 - 6 cups any other leafy greens OR 4 cups diced veg, Note 3)","3/4 cup (185ml) cream, heavy/thickened ((optional) OR more butter!)"]}]', '[{"description":"Melt butter in a pot over medium high heat. Cook garlic, onion and carrot for 5 minutes until carrot is soft and sweet.","duration":5,"images":[],"step":1},{"description":"About 3 minutes in, add the Italian herbs and cook with the onion (makes the herb flavour \"bloom\").","images":[],"step":2},{"description":"Turn heat up to high, add tomato paste. Cook for 2 minutes to remove the “raw” flavour.","duration":2,"images":[],"step":3},{"description":"Add white wine, cook for 3 minutes until the harsh “winey” smell is gone and mostly evaporates so you’re just left with tomato paste again.","duration":3,"images":[],"step":4},{"description":"Add 1/2 cup of beans (to thicken soup), stock, parmesan, salt and pepper. Stir, low heat, cover and simmer 3 minutes, stirring every now and then.","images":[],"step":5},{"description":"Use a stick blender to puree until smooth (or transfer to blender).","images":[],"step":6},{"description":"Add remaining beans, simmer 3 minutes. Stir in spinach until wilted, then stir in cream if using. Add more salt and pepper if needed (note: canned beans are already salted).","images":[],"step":7},{"description":"Serve with crusty bread for dunking!","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","gluten-free-recipes","lentil-recipes","quick-and-easy","soup-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9c910cef270e', 'en', 'US', 'Lentil Curry - mega flavour lentil recipe!', 'Recipe video above. This will be an eye opener for you - an incredible creamy coconut curry made with just TWO spices! Hugely economical, this is essentially a streamlined version of Indian Dahl, delivering a similar intoxicating curry flavour but a whole lot less complicated.', 'https://www.recipetineats.com/tachyon/2020/04/Lentil-Curry_9.jpg', 5, 55, 60, 5, '[{"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.6, "unit": "jar of 50g"}}, {"id": "ing_turmeric", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_lentils", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["50g (3 tbsp) butter (, unsalted (sub 2 tbsp neutral oil))","4 garlic cloves (, finely minced (Note 1))","1.5 tbsp ginger (, finely minced (Note 1))","1 onion (, finely chopped (white, yellow, brown))","2 tbsp curry powder (, mild or spicy (your choice!) (Note 2))","1/2 tsp tumeric powder","1/2 tsp cayenne pepper (, optional)","1 1/4 tsp salt","1/2 tsp black pepper","1 cup dried lentils (, green or brown (or any other dried lentils or split peas, Note 3))","400 ml / 14 oz coconut milk (, full fat)","400g/ 14 oz canned tomato (, crushed or diced)","3 cups (750 ml) water"]},{"ingredients":["1/2 cup coriander/cilantro (, finely chopped)","Yogurt (, optional)","Basmati rice (or other rice)"],"purpose":"Serving:"}]', '[{"title":"Saute onion","description":"Melt butter in a pot over medium heat. Add onion, garlic and ginger. Slowly cook, stirring every now and then, for 10 minutes until tinged with gold and the onion is sweet.","duration":10,"images":[],"step":1},{"title":"Cook off spices","description":"Turn heat up to high, add curry powder and turmeric, stir for 1 1/2 minutes.","images":[],"step":2},{"title":"Add everything else","description":"Add remaining ingredients and stir. Bring to simmer, then place lid on and adjust heat to low / medium low so it''s simmering gently.","images":[],"step":3},{"title":"Simmer","description":"Simmer for 30 minutes, then remove lid and simmer for a further 10 minutes to reduce the sauce. {Note 2 for cook times of other lentils}","duration":30,"images":[],"step":4},{"description":"Lentils should be soft, sauce should be thickened and creamy. Too thick, add water. Too thin, simmer with lid off - thickens quickly.","images":[],"step":5},{"title":"Coriander","description":"Stir through half the coriander, then taste and add more salt if needed.","images":[],"step":6},{"description":"Serve over basmati rice, sprinkled with more coriander and a dollop of yogurt. (Low carb option - cauliflower rice).","images":[],"step":7}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["coronavirus-food","curry-recipes","dinner-tonight","indian-recipes","lentil-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9f86eb812b83', 'en', 'US', 'Lentil Soup', 'Recipe VIDEO above. Don''t settle for a bland lentil soup. Make it right, and you''ll have everyone begging for seconds...and thirds! The touch of spices and finishing it off with lemon really lifts this soup to the next level.', 'https://www.recipetineats.com/tachyon/2017/03/Lentil-Soup-6.jpg', 10, 45, 55, 6, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_lentils", "quantity": {"value": 0.75, "unit": "can of 400g"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["2 tbsp olive oil","1 onion, chopped (white, brown, yellow)","2 garlic cloves, minced","1 large carrot (, chopped (about 1 1/4 cups))","2 celery ribs (, chopped (about 1 1/4 cups))","2 cups / 400g dried lentils (, green or brown, rinsed (Note 1))","400g / 14 oz crushed tomato","1.5 litres / 1.5 quarts (6 cups) vegetable or chicken (stock / broth, low sodium)","1/2 tsp each cumin and coriander powder","1 1/2 tsp paprika powder","2 dried bay leaves","1 lemon (zest + juice)","1/4 tsp salt and pepper, (each)"]},{"ingredients":["Chopped fresh parsley, for garnish","Warm bread, to serve"],"purpose":"To Serve"}]', '[{"description":"Heat oil in a large pot over medium heat. Add garlic and onion, cook for 2 minutes.","duration":2,"images":[],"step":1},{"title":"Add celery and carrot. Cook for 7","description":"10 minutes or until softened and the onion is sweet. Don''t rush this step, it is key to the flavour base of the soup.","duration":8.5,"images":[],"step":2},{"description":"Add all remaining ingredients except the lemon and salt. Stir.","images":[],"step":3},{"description":"Increase heat and bring to simmer. Scoop scum on the surface off and discard (do this again during cooking if required). Place lid on and turn heat down to medium low. Simmer for 35 - 40 minutes or until lentils are soft.","duration":37.5,"images":[],"step":4},{"description":"Remove bay leaves.","images":[],"step":5},{"title":"Thicken Soup","description":"Using a stick blender, do 2 or 3 quick whizzes to thicken the soup (see video below). Or transfer 2 cups to a blender, let it cool slightly, then hold lid with tea towel and blend then transfer back into pot.","images":[],"step":6},{"description":"Add a touch of water if you want to adjust soup consistency. Season to taste with salt and pepper. Grate over the zest of the lemon then add a squeeze of lemon juice just before serving. Garnish with parsley if desired and serve with warm crusty bread slathered liberally with butter!","images":[],"step":7}]', '["gluten"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["coronavirus-food","dinner-tonight","lentil-recipes","main-dishes","quick-and-easy","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d0c2f5002235', 'en', 'US', 'Brazilian Coconut Chickpea Curry', 'Recipe video above. A chickpea recipe that even carnivores think is worth making!! The sauce is from this traditional Brazilian Fish Stew. I call it a curry because it tastes distinctly curryish - except with a fraction of the ingredients!', 'https://www.recipetineats.com/tachyon/2020/02/Brazilian-Chickpea-Curry_2.jpg', 10, 15, 25, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_chickpeas", "quantity": {"value": 2.0, "unit": "can of 400g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.5, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 50.0, "unit": "bag of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["1.5 tbsp olive oil","1 onion (, finely chopped)","2 garlic cloves (, minced)","1 red capsicum/bell peppers (, cut into 3 x 0.75cm / 1.25 x 1/3\"\" strips)","2 cans chickpeas (, drained (Note 1))","400ml/14oz coconut milk (, full fat for best flavour (Note 2))","400ml/14oz can crushed tomato","1 cup (250ml) chicken or vegetable stock/broth (, low sodium)","1 tbsp paprika","1 tbsp cumin","1/2 - 1 tsp cayenne pepper (adjust spiciness to taste)","1.5 tsp sugar (any type)","0.5 tsp salt","50g / 2oz baby spinach leaves (or kale)"],"purpose":"Chickpea Curry:"},{"ingredients":["3 tbsp coriander/cilantro (, roughly chopped, plus more for serving (Note 3))","1 tbsp lime juice (, plus extra wedges for serving)","Yogurt (optional)","Rice - or something to soak up the sauce (Note 4)"],"purpose":"Finishing & Serving:"}]', '[{"description":"Heat oil in a pot or large deep skillet over high heat. Add garlic and onion, cook for 1 minute.","duration":1,"images":[],"step":1},{"description":"Add capsicum, cook for 2 minutes until onion is translucent and slightly golden on edges.","duration":2,"images":[],"step":2},{"description":"Add remaining Curry ingredients except baby spinach. Stir, bring to simmer then lower to medium low so it''s simmering gently.","images":[],"step":3},{"title":"Simmer 12","description":"15 minutes until it changes from pale pink to an orangey red colour.","images":[],"step":4},{"description":"Stir in spinach until just wilted, then stir in coriander and lime juice. Add more salt it needed.","images":[],"step":5},{"description":"Serve over rice with a dollop of yogurt, extra sprinkle of coriander and squeeze of lime (don''t go overboard, I often do and it''s too sour!)","images":[],"step":6}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Brazilian","South American"],"categories":["curry-recipes","dietary","gluten-free-recipes","lentil-recipes","main-dishes","quick-and-easy","south-american-recipes","stews","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2ebeddbe4e0a', 'en', 'US', 'Easy Chickpea Curry with Potato (Chana Aloo Curry)', 'Recipe video above. Say goodbye to boring chickpea recipes! This vegetarian curry called Channa Aloo Curry, is a really great authentic Chickpea Curry that packs serious flavour, is easy, and no need to hunt down unusual spices - everything is from the local grocery shop. It''s a Caribbean curry from Trinidad that tastes very similar to tomato based Indian curries. Spiciness: Medium, from the cayenne pepper most, and bit from white pepper. Can reduce or omit (Note 3).', 'https://www.recipetineats.com/tachyon/2016/01/Chickpea-Curry_7.jpg', 15, 25, 40, 5, '[{"id": "ing_curry_powder", "quantity": {"value": 0.6, "unit": "jar of 50g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_nutmeg_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 666.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_potato", "quantity": {"value": 1.5, "unit": "bag of 2kg"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.985, "unit": "can of 400g"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 tbsp curry powder (, mild - just regular grocery store brands like Clives, Keens(Note 2))","1 tsp All Spice powder","1 tsp nutmeg powder (or 1/2 tsp freshly grated)","1 1/2 tsp smoked paprika (or normal/sweet)","2 tsp dried thyme leaves (or 3 tsp fresh)","1 tsp cumin powder","3/4 tsp cayenne pepper (for spiciness - reduce or omit (Note 3))","1 tsp white pepper (or 1/2 tsp black pepper) (Note 3)"],"purpose":"Spices (Note 1):"},{"ingredients":["3 tbsp canola or coconut oil (any type) (, or any other oil for cooking)","2 large garlic cloves (, minced)","1 large onion (, diced (brown, white, yellow))","1 1/2 cups potatoes (, cut into 1.2cm / 1/2\" cubes (1 large, any type, peeled))","28 oz / 800g canned chickpeas (2 x 14oz/400g cans), drained (Note 3)","14 oz / 400g canned crushed tomatoes","2 cups vegetable or chicken broth/stock (, low sodium)","1 tsp cooking salt / kosher salt (, plus more to taste (halve for table salt))","2 green onion (, sliced (green & white part))","2 tbsp fresh parsley (, finely chopped (or coriander/cilantro) - optional)"],"purpose":"Curry"},{"ingredients":["1 tbsp coriander/cilantro leaves (, chopped - optional)","Dollop of yogurt (- recommended)","Basmati rice (OR)","White rice"],"purpose":"Serving – choose"}]', '[{"description":"Sauté garlic and onion, then toast Spices for 1 min. Stir in potatoes, then chickpeas, tomato, stock and salt. Simmer 15 min, stir in green onion and parsley, serve!","duration":1,"images":[],"step":1},{"title":"Sauté","description":"Heat oil in a large pot or very deep skillet over medium high heat. Add onion and garlic, cook for 3 minutes until onion is translucent.","duration":3,"images":[],"step":2},{"description":"Add Curry Spices and stir for 1 minute.","duration":1,"images":[],"step":3},{"description":"Add the potatoes and stir to coat in the Spices. If the spices start to stick to the bottom of the pot, add a tiny splash of water.","images":[],"step":4},{"title":"Simmer 15 minutes","description":"Add the chickpeas, tomatoes, veg or chicken broth and salt. Bring to simmer then turn down the heat to medium and simmer for 15 minutes, or until the potatoes are cooked and the sauce has thickened.","duration":15,"images":[],"step":5},{"title":"Adjust salt","description":"Taste and add more salt if needed. Stir through scallions/shallots and parsley.","images":[],"step":6},{"description":"Serve with rice with a dollop of yogurt and coriander/cilantro if desired. Basmati would be ideal, or Coconut Rice if you''re wanting to impress. To go all out, add some Easy Soft Flatbreads!","images":[],"step":7}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Caribbean","Trinidad"],"categories":["curry-recipes","dietary","dinner-tonight","gluten-free-recipes","indian-recipes","lentil-recipes","main-dishes","quick-and-easy","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_39547d7e90fb', 'en', 'US', 'Falafel', 'Recipe video above. Deep bronze and crispy on the outside, vivid green, moist and fluffy on the inside. Delicately spiced with a beautiful fresh herb flavour, these falafels are the perfect balance of flavour, texture and can''t-stop-eating-them delicious! Best served fresh out of the fryer. Recipe requires 12 hrs+ soaking time.', 'https://www.recipetineats.com/tachyon/2018/09/Falafel_4.jpg', 25, 10, 35, 20, '[{"id": "ing_chick_peas", "quantity": {"value": 225.0, "unit": "unit"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 6.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_flour", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_tahini", "quantity": {"value": 60.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_tabbouleh", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_hummus", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}]', '[{"ingredients":["225 g / 8 oz dried chick peas (Note 1)","1 cup parsley leaves (, roughly chopped)","1 cup coriander/cilantro leaves (, roughly chopped)","6 scallions/shallots (, white and light green part only finely chopped (Note 2))","2 cloves of garlic (, minced)","1 tsp cumin","1/2 tsp coriander","1 1/2 tsp salt","1/2 tsp baking powder (Note 3)","4 tsp flour ((plain/all purpose) OR chickpea flour)","5 tbsp water"],"purpose":"Falafels:"},{"ingredients":["500 ml / 2 cups+ vegetable oil (Note 4)"],"purpose":"For frying:"},{"ingredients":["4 tbsp tahini","2 tbsp lemon juice","4 tbsp water","1/4 tsp salt (adjust to taste)"],"purpose":"Tahini Sauce (Other Sauces Note 5):"},{"ingredients":["Pita bread or other flatbreads","Tabbouleh (recipe below)","Hummus (optional extra)","Shredded lettuce, tomato slices, sliced red or white onion"],"purpose":"Serving (Note 6):"}]', '[{"description":"Place chickpeas in a large bowl and pour over plenty of cold water. Leave to soak 12 + hours (even 2 days is fine).","images":[],"step":1},{"description":"Drain chickpeas well. Place in food processor, add remaining Falafel ingredients.","images":[],"step":2},{"description":"Blitz for 2 to 3 minutes on high, scraping down sides as necessary, until the chickpeas are very small grains. Mixture should look like smooth guacamole from the outside (see video).","duration":2.5,"images":[],"step":3},{"description":"Scoop up heaped tablespoons and shape into balls (or dome, disc or torpedo), place on a tray. Should make around 20, about 2.5cm / 1\" wide.","images":[],"step":4},{"description":"Refrigerate for 30 minutes.","duration":30,"images":[],"step":5},{"title":"Pour oil in a skillet or large pot","description":"at least 1.7 cm / 2/3\" depth (Note 4). Heat on medium high to 180 - 190C / 355F (or drop a bit in, should sizzle energetically).","images":[],"step":6},{"description":"Place a ball in a large spoon (or tongs) and slide ball in. Cook in batches for around 4 minutes, using 2 forks to roll, until deep golden and super crusty on the outside.","images":[],"step":7},{"description":"Drain on paper towels. Repeat with remaining falafel.","images":[],"step":8},{"description":"Serve fresh out of the fryer with Sauce of choice! Make falafel wraps or plates with tabbouleh, tomato, onion, and Sauces of choice. See Notes 5 and 6.","images":[],"step":9},{"description":"Combine tahini and lemon juice, and mix well. The mixture will stiffen.","images":[],"step":10},{"description":"Stir in the water 1 tbsp at a time and it will loosen again. The final consistency should be like a thick drizzle sauce (see video). Season to taste with salt.","images":[],"step":11}]', '["gluten"]', '["keto_friendly","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["cuisines","deep-fried-recipes","dietary","gluten-free-recipes","iconic-dishes","lentil-recipes","middle-eastern-recipes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b9129fe3a95f', 'en', 'US', 'Easy Coconut Curry Sauce', 'Recipe video above. This 30 minute recipe is all about the sauce that has beautiful depth of flavour, tastes like an Indian curry but not quite as intense. Specifically created this using spices you can get from everyday grocery stores, rather than having to find speciality Indian spices, but without sacrificing flavour. It''s utterly addictive! I really love lentils and pumpkin with this creamy sauce, but feel free to use whatever you want, including proteins - see notes. Spiciness: Low, as long as your Curry Powder and Garam Masala are not spicy.', 'https://www.recipetineats.com/tachyon/2018/04/Coconut-Curry-with-Lentils-and-Pumpkin_0.jpg', 15, 15, 30, 5, '[{"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_lentils", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_pumpkin", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_cashews", "quantity": {"value": 75.0, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garam_masala", "quantity": {"value": 15.0, "unit": "jar"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.6, "unit": "jar of 50g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}]', '[{"ingredients":["2 tbsp coconut oil, ghee or any regular cooking oil (canola, olive oil etc)","4 garlic cloves (, minced)","2 tsp fresh ginger (, finely grated)","1/2 onion (, finely chopped (brown or yellow))","400ml/14oz can coconut milk (full fat)","1 cup chicken broth","1/2 cup tomato passata (tomato puree) (Note 1)","400 g/14 oz can brown lentils (, drained)","250 g / 8 oz pumpkin (~3 cups) (, cut into 2cm / 4/5\" cubes)","2 cups (tightly packed) baby spinach","1/2 cup cashews (, unsalted (roasted or raw) (Note 2))","1/2 tsp each cooking/kosher salt + black pepper"]},{"ingredients":["1 tbsp garam masala (Note 3)","2 tbsp curry powder (mild or spicy, your choice, Note 4)","2 tsp cumin","1 tsp coriander powder","1 tsp paprika (sweet, or hot for spice!)","1/2 tsp turmeric powder"],"purpose":"Spices:"},{"ingredients":["Coriander/cilantro leaves (, whole or chopped)","Chopped cashews (optional)"],"purpose":"Serving garnishes:"}]', '[{"title":"Sauté aromatics","description":"Heat oil in a deep skillet or pot over medium high heat. Add onion, garlic and ginger, cook for 2 minutes until onion is a bit tinged with gold.","duration":2,"images":[],"step":1},{"title":"Cook off spices","description":"Add Spices and stir for 1 minute. Don''t worry if it looks a bit dried out.","duration":1,"images":[],"step":2},{"title":"Coconut sauce","description":"Add coconut milk, passata and broth. Stir until incorporated. Add lentils and pumpkin. Bring to simmer then adjust heat so it''s simmering energetically.","images":[],"step":3},{"description":"Simmer for 10 minutes or until pumpkin is tender but not mushy, and sauce has thickened.","duration":10,"images":[],"step":4},{"description":"Stir through baby spinach until wilted, then cashew nuts. Add salt and pepper last, adding more if needed.","images":[],"step":5},{"description":"Serve over rice, sprinkled with coriander and extra cashews, if using.","images":[],"step":6}]', '[]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["curry-recipes","dietary","dinner-tonight","gluten-free-recipes","lentil-recipes","main-dishes","pumpkin","quick-and-easy","sunday-supper","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_986a091f1ab0', 'en', 'US', 'Chickpea Lamb Shawarma Soup', 'No such thing as bland chickpea soups in my world! Exploding with the flavours of your favourite Chicken Shawarma, except it’s in SOUP form with lamb and chickpeas! This is not spicy, the small amount of cayenne pepper gives it a tiny warm hum, so if you want it spicier, just add more at the end. Deceptively veggie loaded and is quick to make! Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2017/12/Chickpea-Lamb-Shawarma-Soup-4.jpg', 10, 20, 30, 4, '[{"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cardamon", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_chickpeas", "quantity": {"value": 2.0, "unit": "can of 400g"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_spinach", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["2 tsp EACH cumin powder, coriander, paprika","1 tsp cardamon powder (can omit if you don’t have)","¼ tsp cinnamon powder","½ tsp cayenne pepper (adjust to taste)","1/2 tsp black pepper","1 tsp salt"],"purpose":"Spices:"},{"ingredients":["2 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped)","500 g / 1 lb lamb mince (ground lamb, or beef) (Note 1)","2 tbsp tomato paste","2 carrots (, peeled and chopped (about size of chickpeas))","600 g / 21 oz canned chickpeas (, drained and rinsed (1.5 standard cans, Note 2))","400 g / 14 oz can crushed tomato","3 cups / 750 ml chicken broth / stock","1 bunch spinach (, roughly chopped (about 4 packed cups) (wilts a lot))"],"purpose":"Soup:"},{"ingredients":["Plain yoghurt (or sour cream)","Chopped fresh coriander / cilantro"],"purpose":"Garnishes (highly recommended):"}]', '[{"description":"Heat oil in a large pot over high heat. Add garlic and onion, cook for 1 minute until starting to turn translucent.","duration":1,"images":[],"step":1},{"description":"Add lamb and cook, breaking it up as you go. When it has mostly turned from pink to light brown, add spices.","images":[],"step":2},{"description":"Cook for 1 minute, then add tomato paste and cook for another 1 minute. (It smells amazing!)","duration":1,"images":[],"step":3},{"description":"Add carrots, chickpeas, tomato and broth. Stir and bring to simmer.","images":[],"step":4},{"description":"Cover with lid, lower heat so it is bubbling energetically but not crazy rapidly. Cook for 10 minutes until carrot is tender but not super soft – I like it to have a bit of bite still, if you want super soft, keep cooking.","duration":10,"images":[],"step":5},{"description":"Stir through spinach. Once wilted, adjust salt, pepper and spiciness (cayenne) to taste, and water if you want more liquid.","images":[],"step":6},{"description":"Ladle into bowls, add a dollop of yoghurt and a generous sprinkling of coriander. Enjoy!","images":[],"step":7}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["cuisines","dietary","gluten-free-recipes","lamb-recipes","lentil-recipes","main-dishes","middle-eastern-recipes","quick-and-easy","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e1af99f04c95', 'en', 'US', 'Cauliflower and Chickpea Curry', 'This homestyle traditional Indian curry has all the familiar complex, spicy flavours of curries you know and love, but is much healthier and lighter than the usual suspects you get from restaurants. No hunting down hard to find ingredients! I really recommend serving this with yoghurt - adds a touch of creaminess to this healthy tomato based curry. Adding the garam masala towards the end is a great tip - adds a fresh burst of curry flavour', 'https://www.recipetineats.com/tachyon/2016/09/Cauliflower-Chickpea-Curry_6.jpg', 10, 20, 30, 4, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1000.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_turmeric", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_uncategorized", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_frozen_peas", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_garam_masala", "quantity": {"value": 15.0, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}]', '[{"ingredients":["4 tbsp vegetable oil","1 tbsp ginger (finely grated)","3 large garlic cloves (minced.)","1 large onion (chopped (brown, white, yellow))","3 tsp coriander powder","1/4 tsp tumeric powder","1 tsp cumin powder","2 tsp paprika","1 1/2 cups chicken stock","800 g / 28 oz can crushed tomato","300 g / 4 cups (packed cauliflower small florets (1 small / 1/2 large cauliflower))","400 g / 14 oz can chickpeas (drained)","Salt","1 tsp sugar - optional (Note 1)","3/4 cup frozen peas (75g)","3 tsp garam masala powder (Note 2)","1/4 cup coriander / cilantro leaves (chopped)","Yoghurt (to serve (highly recommended))"]}]', '[{"description":"Heat oil in a large deep skillet or pot over medium high heat. Add garlic and ginger, cook for 1 minute. Add onion and cook for 6 - 8 minutes or until golden and caramelised.","duration":1,"images":[],"step":1},{"description":"Add coriander, turmeric, cumin and paprika. Cook for 1 minute.","duration":1,"images":[],"step":2},{"description":"Add chicken stock and tomato. Stir to combine, bring to simmer and cook for 5 minutes.","duration":5,"images":[],"step":3},{"description":"Add cauliflower and chickpeas. Cook for 15 minutes or until cauliflower is soft and sauce has thickened. If sauce is thickening too quickly (Note 3), put the lid on. Adjust salt to taste, and add sugar if using.","duration":15,"images":[],"step":4},{"description":"Add peas and garam masala. Cook for 2 minutes, then remove from stove. Stir through most of the coriander.","duration":2,"images":[],"step":5},{"description":"Serve curry with basmati rice or plain white rice, garnished with reserved coriander and yoghurt on the side.","images":[],"step":6}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["curry-recipes","dietary","dinner-tonight","gluten-free-recipes","indian-recipes","lentil-recipes","main-dishes","most-popular","quick-and-easy","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_43603b3d94f8', 'en', 'US', 'Vegetarian Mexican Lasagna', 'Mexican flavours stacked in a lasagna-type form = Mexican Lasagna! Fresh, light and healthy yet packed full of flavour thanks to the gorgeous Enchilada sauce. The key is whizzing it up in a blender to get the punchy fresh flavours into the sauce! Feel free to swap out the veggies with whatever you want to use.', 'https://www.recipetineats.com/tachyon/2016/09/Vegetarian-Mexican-Casserole-Lasagna_2.jpg', 15, 30, 45, 5, '[{"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_beans", "quantity": {"value": 1.062, "unit": "can of 400g"}}, {"id": "ing_corn", "quantity": {"value": 0.562, "unit": "can of 400g"}}, {"id": "ing_tortillas", "quantity": {"value": 750.0, "unit": "pack of 8"}}, {"id": "ing_cheese", "quantity": {"value": 2.5, "unit": "block of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["800 g / 28oz crushed canned tomato","1 tbsp olive oil","1 clove garlic (, whole peeled)","1/2 red onion (, chopped)","1 cup fresh coriander / cilantro (, lightly packed)","1 tbsp EACH cumin (, oregano and paprika (any type))","1 tsp EACH salt (, garlic powder, cayenne pepper (optional) and sugar (any))","2 tsp coriander powder","Black pepper"],"purpose":"Enchilada Sauce"},{"ingredients":["1 tbsp olive oil","1 garlic clove (, minced)","1/2 red onion (, finely chopped)","1 large red capsicum / bell pepper (, chopped (~1 1/2 cups))","2 zucchinis (, chopped (~1 1/2 cups))"],"purpose":"Hot Filling"},{"ingredients":["425 g / 14 oz can black beans (, drained and rinsed)","1 1/2 cups frozen corn","6 large flour tortillas (approx 22 cm / 9\" wide) (2)","2 1/2 cups / 200g grated melting cheese (I used low fat cheddar)","Fresh coriander / cilantro leaves (, for garnish (optional))"],"purpose":"Assembling"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Place Enchilada Sauce ingredients in a blender and whizz until onion is whizzed in and no longer visible. (In my Vitamix, I started on 3 then cranked it to 8 and it took 15 seconds)","images":[],"step":2},{"description":"Heat oil in a large non stick skillet. Add garlic and onion, cook for 1 minute. Add capsicum, cook for 1 minute. Add zucchini and cook for 3 minutes until charred. Remove skillet from heat.","duration":1,"images":[],"step":3},{"description":"Smear a bit of Enchilada Sauce on the bottom of a casserole dish. Place 1 tortilla in the middle, then tear on in half and place on either side (see step photos or video).","images":[],"step":4},{"description":"Top with half the Hot Filling. Scatter over half the black beans, half the corn. Drizzle over 1 cup Enchilada Sauce and 3/4 cup grated cheese.","images":[],"step":5},{"description":"Repeat with another layer so you have 2 layers of filling. Then for the last layer, top with tortillas then cover 2 cups of Enchilada Sauce (Note 3) and scatter over remaining cheese.","images":[],"step":6},{"description":"Bake for 25 minutes or until cheese is bubbling and golden. Stand for 5 minutes, then garnish with fresh coriander and serve.","duration":25,"images":[],"step":7}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Tex-Mex"],"categories":["casseroles-and-cosy-bakes","dietary","gluten-free-recipes","lentil-recipes","low-calorie-recipes","quick-and-easy","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8099f73ff738', 'en', 'US', 'One Skillet Oven Baked Chicken Shawarma and Rice Pilaf', 'This combines two of my favourite Middle Eastern foods into one pot - Chicken Shawarma and Rice Pilaf. The Chicken Shawarma is the same recipe as the one I use for grilling (recipe here) with just quantities adjusted to suit using thigh cutlets cooked on the stove. The rice pilaf has been adapted from Yotam Ottolenghi''s Chicken with Cardamon Rice recipe from his cookbook "Jerusalem" (one of my all time favourite cookbooks!). Note that this is not an authentic way of preparing Chicken Shawarma! Real Shawarma is cooked on a rotisserie then shaved and served in a kebab. This is my one pot rice version - Shawarma flavours, made in one pot with rice!', 'https://www.recipetineats.com/tachyon/2015/08/One-Pot-Chicken-Shawarma-and-Rice_Hero.jpg', 15, 50, 65, 5, '[{"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_rice", "quantity": {"value": 225.0, "unit": "pack"}}, {"id": "ing_chicken", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_cardamon", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 2.0, "unit": "jar"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_raisins", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 large garlic clove (, minced (or 2 small cloves))","1 1/2 tsp ground coriander","1 1/2 tsp ground cumin","1 tsp ground cardamom","1 tsp smoked paprika (or ordinary is fine)","1 tsp cayenne pepper (optional)","1/2 tsp salt","Black pepper","3 tbsp lemon juice"],"purpose":"Spice Rub"},{"ingredients":["5 chicken thigh fillets (, bone in, skin on - about 2 lb / 1kg in total (Note 1))","1/2 tbsp olive oil","1 small onion (, finely diced)","2 garlic cloves (, minced)","1 1/2 cups long grain rice (, uncooked (Note 2))","1 1/2 cups chicken broth (or water)","2 cups water","3/4 - 1 tsp salt","Black pepper","1 1/2 tsp cardamon powder","2 cinnamon sticks (or 1/2 tsp cinnamon powder)","400g (14oz) can chickpeas (, drained (1 can))","1/4 cup raisins or sultanas (optional)"],"purpose":"Chicken and Rice"},{"ingredients":["Yoghurt (plain, unsweetened. Greek yoghurt is great)","Cilantro/coriander leaves (, roughly chopped)","Parsley leaves (, roughly chopped)"],"purpose":"Garnish (optional)"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Mix the Spice Rub ingredients together in a small bowl. Slather onto the chicken, covering both sides.","images":[],"step":2},{"title":"Optional","description":"Marinate for at least 1 hour, up to 24 hours. (Note 3)","images":[],"step":3},{"description":"Heat olive oil in a large skillet over medium high heat. Add the chicken, skin side down, and cook for 5 minutes on each side, or until light golden brown.","duration":5,"images":[],"step":4},{"description":"Remove chicken from skillet. Scrape off excess black bits stuck to the pan and discard, along with excess oil (but leave some to cook the onion).","images":[],"step":5},{"description":"Add garlic and onion. Cook for 2 minutes until translucent.","duration":2,"images":[],"step":6},{"description":"Add rice and stir so the grains are coated in oil and become a bit translucent.","images":[],"step":7},{"description":"Add remaining ingredients. Place the chicken on top - it should be half submerged with the skin above the surface. Pour in the juices from the plate as well.","images":[],"step":8},{"description":"Bring to simmer, then place a lid on (or cover with foil) and transfer to oven.","images":[],"step":9},{"description":"Bake for 35 minutes, then remove the lid and bake for a further 10 minutes.","duration":35,"images":[],"step":10},{"description":"Remove from the oven. Let it rest for 5 minutes.","duration":5,"images":[],"step":11},{"description":"Remove chicken from the rice and mix the rice quickly (to evenly distribute flavour).","images":[],"step":12},{"description":"Serve, garnished with cilantro/coriander and parsley if desired. I also like to serve it with a bit of plain yoghurt. (Note 4)","images":[],"step":13}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["chicken-recipes","cuisines","dietary","dinner-tonight","gluten-free-recipes","lentil-recipes","main-dishes","middle-eastern-recipes","most-popular","one-pot-recipes","quick-and-easy","rice-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_600b1b4235e2', 'en', 'US', 'Easy slow cooker BBQ pulled beef', 'Recipe video above. Make this when you want a big batch of succulent pulled beef smothered in an incredible homemade barbecue sauce, made using the convenience of a slow cooker. Pile into sliders, heap onto plates, stuff into baked potatoes. So many ways to enjoy it!Adapted from my Easy Slow Cooker BBQ pulled pork recipe. I don''t sear the pork before slow cooking, but it''s really worth searing the beef. I tried without and it was still great, but it''s noticeably better when you do. :)Easy to scale up - I can do a double batch in my slow cooker.', 'https://www.recipetineats.com/tachyon/2026/06/Easy-slow-cooker-BBQ-shredded-beef-8.jpg', 30, 620, 650, 8, '[{"id": "ing_beef", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.5, "unit": "bottle of 500ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_molasses", "quantity": {"value": 45.0, "unit": "jar"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 20.0, "unit": "bottle"}}, {"id": "ing_tabasco", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_green_onion", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["1.5 kg / 3 lb chuck beef (, cut into 4 thick steaks (Note 1))","1 cup beer (anything other than dark stouts like Guinness), or beef stock/broth, low sodium (Note 2)","3 tbsp olive oil (or other neutral oil, for searing)"]},{"ingredients":["3 tbsp (tightly packed) brown sugar","1 tbsp paprika powder (regular/sweet or smoked)","1 tbsp garlic powder","2 tsp onion powder","2 tsp mustard powder","1 tsp cumin powder","2 tsp cooking salt / kosher salt","1 tsp black pepper"],"purpose":"RUB:"},{"ingredients":["1 cup apple cider vinegar (Note 3)","3 cups tomato ketchup (or Aussie tomato sauce)","3 tbsp molasses (, orginal (not blackstrap, Note 4))","2/3 cup brown sugar","4 tsp mustard powder","3 tsp garlic powder","4 tsp Worcestershire sauce","2 tsp cooking salt / kosher salt","2 tsp black pepper","2 tsp Tabasco ( or cayenne pepper (optional, very faint background spiciness))"],"purpose":"BBQ Sauce:"},{"ingredients":["2 tbsp green onion (, finely sliced)"],"purpose":"Option garnish (for serving in bowl)"}]', '[{"description":"Mix BBQ sauce in slow cooker. Coat beef in Rub, sear. Deglaze pan with beer. Arrange beef in slow cooker, add beer, slow cook 10 hours. Shred, reduce BBQ sauce on stove, toss half with beef, serve rest on the side.","images":[],"step":1},{"title":"BBQ Sauce","description":"Put all the ingredients in a slow cooker and whisk to combine.","images":[],"step":2},{"title":"Season beef","description":"Mix the Rub together in a medium bowl. Dredge the steak in the Rub to coat on both sides.","images":[],"step":3},{"title":"Sear","description":"Heat half the oil in a large non stick pan over medium high heat. Brown 2 steaks for 1 - 1 1/2 minutes on each side until deep golden but take care not to burn the spice rub. Place in the slow cooker. Wipe the pan clean of black bits, heat the remaining oil and repeat with remaining 2 steaks.","images":[],"step":4},{"title":"Deglaze pan with beer","description":"Add the beer into the pan and let it simmer rapidly, scraping the base as you go, until it is reduced down to about 1/4 cup - about 3 minutes. Pour into the slow cooker.","images":[],"step":5},{"title":"Slow cook 10 hours","description":"Arrange the beef so each piece is as submerged as much as possible. Slow cook on low for 10 hours. The beef should be tender enough to easily shred.","images":[],"step":6},{"title":"Shred","description":"Remove the beef into a pan and shred with 2 forks.","images":[],"step":7},{"title":"Reduce sauce","description":"Pour the sauce from the slow cooker into a pot or large deep fry pan. Simmer on medium high for 15 to 20 minutes until thickened to a BBQ sauce consistency. Stir regularly towards the end and lower heat as needed if it starts to splutter aggressively.","duration":17.5,"images":[],"step":8},{"title":"Toss","description":"Pour about 1/3 to 1/2 the sauce over the beef and toss (use enough to moisten and flavour, but not make it soggy).","images":[],"step":9},{"description":"Serve the beef with remaining BBQ sauce. Use for sliders and sandwiches with Coleslaw for classic southern sliders (pictured), make plates with Corn bread, Mac and Cheese and corn on the cob on the side, stuff into baked potatoes. You just can''t go wrong however you serve it!","images":[],"step":10}]', '["mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["BBQ","Southern","Texas","Western"],"categories":["beef","beef-recipes","mains","sandwiches-and-sliders","slow-cooked-fall-apart","slow-cooker-recipes","stews"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_de90de965662', 'en', 'US', 'Beef Rump Cap Roast (Picanha)', 'Recipe video above. Rump cap is considered by many to be the best cut for roast beef - prime rib quality without the price tag! But cook it wrong and it’s a chewy disaster. This recipe uses a safe, straightforward method that ends with pure roast beef bliss - edge-to-edge medium rare and a golden, crackly fat cap. Bonus: two new steak sauce obsessions provided! Chimichurri Butter plus a Roasted Garlic Butter (links in ingredient list)', 'https://www.recipetineats.com/tachyon/2025/11/Rump-cap-roast-picanha_1.jpg', 10, 90, 100, 8, '[{"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.625, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_classic_chimichurri", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_bearnaise_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_cafe_de_paris", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_mushroom", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}]', '[{"ingredients":["2 kg/ 4 lb beef rump cap / picanha ((more names: sirloin cap, coulette), silver skin trimmed off)","5 tsp sea salt flakes (or 3 1/2 tsp cooking salt / kosher salt - Note 2)","1/2 tsp black pepper"]},{"ingredients":["Chimichurri butter (pictured, stellar!)","Roasted Garlic Butter (pictured, current obsession!)","Classic Chimichurri","Bearnaise sauce","Cowboy butter","Cafe de Paris","Creamy mushroom sauce","My favourite Blue Cheese Sauce (page 330 of Dinner)","Red wine sauce (page 327 of Dinner)","Dijon mustard, wholegrain mustard, horseradish cream (good ones!)"],"purpose":"Sauce options:"}]', '[{"description":"Score fat (cut right in), rub meat with 2 tsp salt, and 3 tsp on fat cap. Roast on rack at 140°C/285°F (120°C fan) until the internal temperature is 48°C / 118°F (~70 minutes - 1 1/2 hrs). Rest 30 minutes, brown fat cap quickly under very hot oven grill/broiler (3 min max). Serve immediately!","images":[],"step":1},{"description":"Preheat the oven to 140°C/285°F (120°C fan-forced).","images":[],"step":2},{"title":"Dry","description":"Pat excess moisture off the surface of the rump cap with paper towels.","images":[],"step":3},{"title":"Score the fat cap with 2.5cm / 1\" diamonds","description":"cut well into the fat but don''t cut into the meat. (But not a disaster if you do, unlike pork crackling!)","images":[],"step":4},{"title":"Rub salt","description":"Rub the meat surface with 2 teaspoons of the salt and half the pepper (ie underside and sides). Then rub the remaining 3 teaspoons of salt and pepper into the fat cap.","images":[],"step":5},{"title":"Meat thermometer","description":"Place the beef on a rack set on a tray. Insert an oven-safe meat thermometer into the middle of the thickest part of the beef, if using.","images":[],"step":6},{"title":"Slow-roast","description":"Roast until the internal temperature is 48°C / 118°F, between 70 to 90 minutes (it varies! Note 3)","images":[],"step":7},{"title":"Rest","description":"Remove from the oven and leave on the counter for 30 - 40 minutes to rest (do not cover). The internal temperature will climb to 56°C / 132.8°F which is perfect medium rare. (Note 4 for other doneness)","duration":35,"images":[],"step":8},{"description":"Brown fat cap:","images":[],"step":9},{"title":"Preheat","description":"Halfway through the resting time, preheat the oven grill / broiler as high as it will go. Arrange the shelf so the surface of the fat cap will be 12cm / 5\" from the heat element.","images":[],"step":10},{"title":"Brown","description":"Grill rump cap for 2 - 3 minutes until the fat cap is golden and a bit crisp. Keep a close eye on it, it can burn quickly, and remove after 3 minutes even if not golden enough else you risk a band of overcooked beef.","duration":2.5,"images":[],"step":11},{"title":"Ready! The beef is ready to serve","description":"there is no need to rest again.","images":[],"step":12},{"description":"Slicing to serve:","images":[],"step":13},{"description":"Cut the beef thinly into 8mm / 1/3\" slices and serve with sauce of choice (you can go up to 1.25cm / 1/2\" if you have wagyu). Don''t be tempted to cut thick slices, this beef cut is not suitable for that! (Note 5 about grain direction)","images":[],"step":14}]', '["milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef","beef-recipes","iconic-dishes","mains","roast-beef","roasts","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3c5b97ebc16f', 'en', 'US', 'Birria Tacos', 'Recipe video above. Birria Tacos - or Quesabirria - the legendary crispy red tacos stuffed with cheesy shredded beef dunked in rich consommé. This was a beast of a recipe to crack, so I’m thrilled we finally got there. What makes these special: specify chillies by weight not number, toss shredded beef in sauce, skim red-oil off to use for crisping tacos, and our consommé is not watery and thin, it''s a smidge thicker than usual so it clings better.These deliver big flavour with every single bite, the consommé is rich and full bodied with beefy chilli flavour, and wow the tacos are crisp! Important: Birria is very reliant on chillies for flavour. So if you don''t have scales for the chillies, deseed, chop, then measure using cups. Don''t rely on "2 anchos", they can vary so much in size.', 'https://www.recipetineats.com/tachyon/2025/09/Birria-tacos_4.jpg', 30, 180, 210, 22, '[{"id": "ing_chilli", "quantity": {"value": 0.25, "unit": "pack of 100g"}}, {"id": "ing_chilli", "quantity": {"value": 0.25, "unit": "pack of 100g"}}, {"id": "ing_chilli", "quantity": {"value": 0.25, "unit": "pack of 100g"}}, {"id": "ing_chilli", "quantity": {"value": 0.25, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_beef", "quantity": {"value": 1.3, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_bay_leaf", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.06, "unit": "bottle of 500ml"}}, {"id": "ing_salt", "quantity": {"value": 0.013, "unit": "kg"}}, {"id": "ing_tortillas", "quantity": {"value": 20.0, "unit": "pack of 8"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cheese", "quantity": {"value": 3.5, "unit": "block of 250g"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_hot_sauce", "quantity": {"value": 1.0, "unit": "bottle of 150ml"}}]', '[{"ingredients":["25 g (0.9 oz) guajillo chillies, dried (~4 pieces, heaped 3/4 cup once chopped) (Note 1)","45 g (1.6 oz) ancho chillies, dried (~2-3 pieces, 1 cup once chopped) (Note 1)","6 g (0.2 oz) chillies de arbol, dried (~6 pieces, 2 tbsp once chopped) (Note 1)","1/2 cup chilli soaking water (reserve after simmering)","5 garlic cloves (, peeled)","1 small onion (, roughly sliced (~tennis ball size))","1 medium tomato (, roughly sliced (180g))","2 tsp dried oregano","1 tsp ground cumin","1/8 tsp black pepper"],"purpose":"Birria adobo (paste):"},{"ingredients":["5 tbsp vegetable oil (or canola oil) (Note 2)","1.3 kg/2.6 lb chuck beef (, cut into 6 large pieces (or boneless beef short ribs - 1.8kg/3.6 lb bone-in) (Note 3))","2 cups beef stock / broth (, low sodium)","10 cloves (or 1/4 tsp ground cloves)","1 cinnamon stick (substitute 1/4 tsp powder, but it''s not quite the same)","3 bay leaves (, preferably fresh else dried)","2 tbsp apple cider vinegar (or regular white vinegar, red or white wine vinegar)","2 1/2 tsp cooking salt / kosher salt (halve for table salt, +30% for flakes)"],"purpose":"Birria braising:"},{"ingredients":["1/2 tsp cooking salt / kosher salt"],"purpose":"Beef seasoning:"},{"ingredients":["20 - 25 corn tortillas (14.5cm/6\" wide) (Note 4)","1 white onion (, diced (Note 5))","1/2 cup finely chopped coriander / cilantro leaves","3 1/2 cups (350g) shredded Colby, Monterey Jack or (Oaxaca cheese (if you can get it) (Note 6))","Lime wedges (, optional)","Your favorite salsa or hot sauce (, optional)"],"purpose":"Birria Tacos:"}]', '[{"description":"Simmer chopped chillies 10 min. Strain, blitz Adobo paste. Brown beef, cook off adobo paste, slow-cook beef 2 1/2 hrs (lid on). Remove meat, shred, skim fat off braising liquid (\"Birria Oil\"). Toss beef in skillet with 1 cup braising liquid (aka Consomme). Heat 1 tsp Birria oil over low heat, wipe pan with tortilla, remove, repeat x2 with 1/2 tsp oil each. Top tortilla with cheese, beef, onion, coriander, fold over, pan fry until crisp. Serve with Birria Consomme for dunking!","images":[],"step":1},{"description":"Prepare chillis:","images":[],"step":2},{"description":"Use gloves if you''re sensitive to working with chilli!","images":[],"step":3},{"title":"Deseed","description":"Trim and discard stems. Cut lengthwise, remove and discard the seeds. Roughly chop into 1 - 1.5cm / 1/4\" pieces.","images":[],"step":4},{"title":"Simmer","description":"Put chillis in a large saucepan of boiling water. Simmer rapidly for 10 minutes to soften, until flesh is mushy (skin stays intact but softens).","duration":10,"images":[],"step":5},{"description":"Reserve 1/2 cup of chilli-simmering water. Drain chilli in a sieve, lightly press out residual liquid.","images":[],"step":6},{"title":"Birria Adobo (paste)","description":"Place cooked chillies, reserved 1/2 cup chilli water and remaining Adobo ingredients in a tall jug large enough to fit the head of a stick blender. Blitz for 20 seconds until as smooth as possible (it''s not completely smooth, see video). You can also do this in a small food processor, NutriBullet or blender (Note 7).","duration":0.3333333333333333,"images":[],"step":7},{"title":"Sear beef","description":"Heat the oil in a large heavy based pot over high heat (I use my 24cm / 9.6\" dutch oven). Add half the beef and sear each side aggressively until it''s dark golden brown (about 1 - 1 1/2 minutes each side). Remove to a bowl and repeat with remaining beef.","images":[],"step":8},{"title":"Cook off Adobo","description":"Add the paste to same pan and stir for 2 minutes in oil (lower heat if spitting aggressively).","duration":2,"images":[],"step":9},{"title":"Slow cook 2 1/2 hours","description":"Add all Birria braising ingredients, stir, then add the beef. Bring to a boil then lower heat until it''s simmering very gently (small gentle bubbles every now and then). Cover with a lid and cook for 2 1/2 hours, or until beef shreds easily (short ribs take 3 - 3.5 hrs). (Note 8 for slow cooker)","images":[],"step":10},{"title":"Shred","description":"Remove the beef to a clean pan and shred well. Add the 1/2 teaspoon of salt and toss meat to distribute.","images":[],"step":11},{"title":"Birria oil","description":"Skim off as much of the red oil floating on braising liquid surface as possible (ideally 6 tbsp+) and place in a separate bowl (this is the \"Birria Oil\"). Precious stuff!","images":[],"step":12},{"title":"Soak beef","description":"Pour 1 cup of the braising liquid (\"Birria Consommé\") into a large non-stick pan over medium-high heat. Let it simmer for 15 seconds, then add all the beef and toss in the sauce until it''s all absorbed by the beef, there should be almost none pooled in the pan. Move beef back into the shredding pan, scraping the non-stick pan clean.","duration":0.25,"images":[],"step":13},{"title":"Birria Consommé","description":"Taste and check for salt, add more if needed. It should be on the slightly salty side (because it''s used for dipping) but not too salty to drink a small cup like soup. Keep warm to use for dipping once tacos are done.","images":[],"step":14},{"title":"Red tortillas","description":"Heat 1 teaspoon Birria Oil in the same non-stick pan over medium-low heat. Put a tortilla in and \"wipe\" around to make the underside red. Once the tortilla is soft (no need to flip) - about 10 seconds - remove to a work surface red side down. Repeat twice more, heating 1/2 teaspoon Birria Oil for each tortilla.","images":[],"step":15},{"title":"Stuff","description":"Spread cheese on half of each tortilla, top with beef, then onion and coriander/cilantro.","images":[],"step":16},{"description":"Crisp! Fold over then pan-fry 3 Birria Tacos at a time (in the same pan) over medium-high heat for 2 minutes on each side, until golden-red and crispy.","duration":2,"images":[],"step":17},{"title":"Serve","description":"Remove and serve while hot with the Birria Consommé for dunking! (Drink leftover consommé, it might be the best soup broth you have this year).","images":[],"step":18}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["beef","beef-recipes","iconic-dishes","mains","mexican-recipes","slow-cooked-fall-apart","slow-cooker-recipes","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f1acfebb1ff2', 'en', 'US', 'Tomahawk Steak', 'Recipe video above. Don’t cook a tomahawk steak entirely on the BBQ - you’ll end up with a thick, overcooked band! The best way is to use the reverse-sear method: oven first, then BBQ. It''s stress free and you''ll have blushing pink meat from edge to edge with a killer crust - steak perfection! All credit to J Kenji Lopez-Alt for popularising this now world renowned method which can be used for all thick cut steaks.No BBQ? See note 5 for the oven-only method.PS Please a meat thermometer to nail the doneness - this is not the time to guess.PPS Even if you overshoot to 60°C/140°F, it still eats like medium-rare. Also - see FAQ above for making stacks for a tomahawk party!', 'https://www.recipetineats.com/tachyon/2025/05/Tomahawk-steak-shoot-3_6-1.jpg', 5, 60, 80, 2, '[{"id": "ing_beef_steak", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_bearnaise_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_cafe_de_paris", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_mushroom", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chimichurri_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_mustard", "quantity": {"value": 0.005, "unit": "jar of 200g"}}]', '[{"ingredients":["1 tomahawk steak (1.2 - 1.5kg / 2.4 - 3lb) (Note 1)","2 tsp cooking salt/kosher salt","3/4 tsp black pepper","1 tbsp olive oil"],"purpose":"Tomahawk Steak"},{"ingredients":["Cowboy butter (pictured in post - Tomahawk worthy!)","Bearnaise sauce","Cafe de Paris","Creamy mushroom sauce","Chimichurri sauce","Blue cheese sauce (page 330 of Dinner)","Blue cheese sauce (page 330 of Dinner)","Dijon or seeded mustard"],"purpose":"Steak sauce options"}]', '[{"description":"Season, slow-roast on rack at 140°C/285°F (120°C fan) for 40-45 minutes to 50°C/122°F. Rest 10 minutes. Preheat BBQ until screaming hot, drizzle steak with oil, lower BBQ to low/med low and sear on hot BBQ 3 - 4 minutes on each side (temp 55°C (128°F)). Rest 3 minutes (temp rises to 57°C/135°F = perfect medium rare 🙌🏻). Slice, serve with Cowboy Butter!","duration":42.5,"images":[],"step":1},{"description":"Oven slow-roast:","images":[],"step":2},{"title":"De-chill","description":"Take the steak out of the fridge 1 hour prior to cooking. Remove from packaging and pat the surface dry. (Do not salt).","images":[],"step":3},{"description":"Preheat the oven to 140°C/285°F (120°C fan-forced).","images":[],"step":4},{"title":"Season","description":"Sprinkle the steak meat with salt and pepper, then use your hands to rub it in.","images":[],"step":5},{"title":"Slow(ish) roast","description":"Put the steak on a rack and set it on a baking tray. (Note 2) Bake for 40 to 45 minutes, or until the internal temperature is 50°C/122°F (for medium rare, see Note 3 for other doneness).","duration":42.5,"images":[],"step":6},{"title":"Rest","description":"Take the tray out of the oven and leave the steak on the counter for 10 minutes. (Internal temperature should rise by 3 degrees).","duration":10,"images":[],"step":7},{"description":"Preheat the BBQ on high until it''s screaming hot. Use the flat plate side if you''re not a confident BBQ''er, or the grill side if you''re a BBQ master. (Note 4)","images":[],"step":8},{"title":"Oil","description":"Drizzle the oil on the steak and lightly pat to spread (don''t rub off the salt), using most of the surface area of the meaty part.","images":[],"step":9},{"title":"Turn BBQ DOWN","description":"If using the grill side, reduce to low (if yours is strong, mine is) or medium low (for weaker ones). If using the flat plate side, lower to medium. Do this just before putting the tomahawk on.","images":[],"step":10},{"title":"Edges first","description":"Using tongs, hold the steak upright and sear the edges and bone first (only if you''ve got meat on it), rotating and moving every minute or so to achieve this all the way around. ⚠️Flare-ups – If searing on the grill side, don’t walk away - flare-ups are inevitable. See Note 4 for managing.","images":[],"step":11},{"title":"Steak crust","description":"Then place the steak down on the grill and cook for 3 to 4 minutes on each side, or until the internal temperature is 55°C / 131°F. For classic X grill lines, rotate once 45° partway through.","duration":3.5,"images":[],"step":12},{"title":"Rest the steak on a rack for 3 minutes","description":"the internal temperature will rise to 57°C/135°F which is perfect medium rare.","duration":3,"images":[],"step":13},{"title":"Serve","description":"Cut into 1 cm / 0.4\" thick slices. Serve with steak sauce of choice! (Pictured: Cowboy Butter, highly recommend!).","images":[],"step":14}]', '["milk","mustard"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef","beef-recipes","iconic-dishes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0e4199cee174', 'en', 'US', 'Beef in black bean sauce', 'Recipe video above. This incredible Beef in Black Bean Sauce recipe is from Hannah, a chef at our food bank RecipeTin Meals who was born and raised in China, and comes from a long line of chefs. I''ll wager this recipe beats any Chinese restaurant you’ve tried - even “fancy” city ones - and it is far, far cheaper. Made from scratch, it leaves jarred sauces in the dust. Shockingly easy!', 'https://www.recipetineats.com/tachyon/2025/04/Beef-in-black-bean-sauce_8.jpg', 20, 10, 90, 4, '[{"id": "ing_black_beans", "quantity": {"value": 0.188, "unit": "can of 400g"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_oil", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.02, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.006, "unit": "tub of 200g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1/2 cup (75g) preserved black beans (salted black beans, fermented black beans, Note 1)","400g/14 oz beef rump steak (US: top sirloin) (, thinly sliced 3mm / 0.1\" (Note 2))","1 brown onion (, medium size, cut into 2.5cm/1\" squares)","1 green capsicum ((bell pepper), medium size, cut into 2.5cm/1\" squares)","1 tbsp garlic (, finely minced with a knife ~ 4 cloves (Note 3))","1/2 cup peanut oil (or vegetable, canola) (Note 4)","1 tbsp Chinese cooking wine (shaoxing wine) (Note 5)"]},{"ingredients":["1 tbsp light soy sauce (Note 6)","1 tsp dark soy sauce (Note 6)","1 tbsp oyster sauce","2 tsp cornflour / cornstarch","1/4 tsp baking soda (bi-carbonate) (Note 7)","1 tbsp sesame oil (toasted ie brown, not untoasted which is yellow)"],"purpose":"Tenderising beef marinade:"},{"ingredients":["1 tbsp light soy sauce (Note 6)","2 tsp white sugar","2 tbsp cornflour/cornstarch (20g)","1 cup water"],"purpose":"Sauce:"},{"ingredients":["White rice"],"purpose":"Serving:"}]', '[{"description":"Abbreviated recipe:","images":[],"step":1},{"description":"Marinade beef 1 hour, soak beans, mix sauce. Shallow fry beef 30 seconds, remove. Discard all but 3 tbsp oil. Add and cook in this order: black beans 20 seconds, garlic 10 seconds, onion + capsicum 1 minute, beef 1 minute, cooking wine 30 seconds, sauce 1 minute or until thickened. Serve!","images":[],"step":2},{"description":"Mix the marinade ingredients EXCEPT sesame oil in a bowl. Add beef, mix to coat. Add sesame oil, mix again.","images":[],"step":3},{"title":"Marinade","description":"Refrigerate to marinade for 1 hour.","images":[],"step":4},{"title":"Soak beans","description":"Put the salted black beans in a medium bowl and cover with water. Set aside for 30 minutes to 1 hour to soak, then drain.","duration":30,"images":[],"step":5},{"title":"Mix sauce","description":"Put the cornflour, soy sauce and sugar in a jug or small bowl. Mix until lump free then mix in the water. Set aside.","images":[],"step":6},{"description":"Cooking:","images":[],"step":7},{"title":"Cook beef","description":"Heat the oil in a wok (or non stick pan) over high heat. Add the beef and cook, tossing, for 30 seconds until it changes from red to brown. Remove with a slotted spoon onto a plate.","duration":0.5,"images":[],"step":8},{"description":"Discard most of the oil in the wok, keep just 3 tablespoons.","images":[],"step":9},{"title":"Aromatics","description":"Return the wok to high heat. Add the black beans and stir for 20 seconds, then add the garlic and stir for 10 seconds. Add the capsicum and onion, cook for 1 minute.","duration":0.3333333333333333,"images":[],"step":10},{"title":"Beef","description":"Add beef and any juices pooled on the plate, toss for 1 minute. Pour the Chinese cooking wine around the sides of the wok so it runs down into the beef then toss for 30 seconds (Note 8)","duration":1,"images":[],"step":11},{"title":"Sauce","description":"Pour the sauce in, then stir and let it bubble for 1 minute or until the sauce thickens, is shiny and coats the beef beautifully.","duration":1,"images":[],"step":12},{"title":"Serve","description":"Pour into a serving bowl and serve with rice!","images":[],"step":13}]', '["gluten","peanuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Chinese"],"categories":["beef","beef-recipes","chef-hannahs-recipes","chinese-recipes","iconic-dishes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_31cea54aec7d', 'en', 'US', 'Thai Sweet Chilli Beef Bowls', 'Recipe video above. This quick dinner using beef mince channels Thai Chilli Basil stir fry vibes (but, no basil and not spicy) with poke bowl versatility (but, no pricey raw fish!). I use bottled sweet chilli sauce for simplicity instead of fresh chilli, garlic, sugar and thickener, and it works a treat. Plus, it''s more kid friendly because you can barely taste the spice.The key is the Sweet Chilli Drizzle Sauce! It adds flavor to the beef, rice, and veggies (raw or cooked). Jumble it all up and dig in!', 'https://www.recipetineats.com/tachyon/2024/12/Thai-sweet-chilli-beef-bowls_0.jpg', 13, 7, 20, 4, '[{"id": "ing_roasted_cashews", "quantity": {"value": 50.0, "unit": "jar"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_steamed_or_veg", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1/3 cup roasted cashews (, unsalted (or peanuts, Note 1))","1 tbsp canola oil (, or other plain cooking oil)","500 g / 1 lb beef mince (ground beef)","1 small onion (, finely chopped)","2 garlic cloves (, finely minced)","3 tbsp roughly chopped coriander/cilantro leaves (sub green onion)"]},{"ingredients":["2 tbsp sweet chilli sauce (I use Trident)","2 tbsp fish sauce (Note 2)","2 tbsp rice vinegar (sub cider vinegar)","1 tbsp oyster sauce (Note 3)","1 tbsp dark soy sauce (Note 3)"],"purpose":"Sweet chilli stir fry sauce:"},{"ingredients":["1 garlic clove (, minced using garlic crusher)","3 tbsp sweet chilli sauce","2 tbsp lime juice (sub rice vinegar when limes are crazy expensive)","2 tsp fish sauce (Note 2)"],"purpose":"Sweet chilli drizzle sauce:"},{"ingredients":["2 batches jasmine rice (or other plain rice of choice)","Steamed or fresh veg (Note 5) (pictured: chopped cucumber, coriander/cilantro, red onion finely sliced)"],"purpose":"Serving:"}]', '[{"description":"Abbreviated recipe","images":[],"step":1},{"description":"Mix each sauce. Toast cashews, sauté onion + garlic 1 min, then cook beef. Add sauce, cook until reduced/caramelised, serve over rice with veg on side. Spoon over drizzle sauce, top with cashews and coriander.","images":[],"step":2},{"title":"Drizzle sauce","description":"Mix the ingredients in a bowl, set aside.","images":[],"step":3},{"title":"Stir fry sauce","description":"Mix the ingredients in a separate bowl, set aside.","images":[],"step":4},{"title":"Toast cashews","description":"Heat a large non-stick pan over medium high heat. Add the cashews and toast for 2 minutes. Transfer to a cutting board then roughly chop once cool.","duration":2,"images":[],"step":5},{"title":"Cook beef","description":"Heat the oil in the same pan over high heat. Add the garlic and onion, cook for 1 minute. Add the beef and cook, breaking it up as you go, until you no longer see raw meat.","duration":1,"images":[],"step":6},{"description":"Sauce it! Add the cooking sauce and cook well, stirring, until it mostly reduces down so the sauce caramelises on the beef, about 3 - 4 minutes. (Don''t shortcut this step, it''s where the flavour is!)","images":[],"step":7},{"description":"Serve the beef over rice with a side of veg. Douse everything with the sauce, top with cashews and coriander (fresh chilli wouldn''t go astray either). To eat, jumble everything up then dig in!","images":[],"step":8}]', '["fish","gluten","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef","beef-mince-recipes","beef-recipes","dinner-tonight","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5732397bf16b', 'en', 'US', 'One Pot Cajun Beef Pasta with lots-of-veg', 'Recipe video above. A big bubbly beefy pasta in a Cajun flavoured tomato sauce, filled with lots of hidden vegetables, all made in one pot! Love that it''s a complete meal, and a great way to stretch 500g/1lb beef to serve more people with the bonus of a stack of "hidden" vegetables (carrot, zucchini ,zucchini, canned tomato and onion - yes, onion counts towards daily veg intake!).Leftovers are excellent! Fridge or freeze.', 'https://www.recipetineats.com/tachyon/2024/09/One-pot-Cajun-Beef-Pasta_0.jpg', 15, 25, 40, 7, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_kidney_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.562, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves (, finely minced)","1 onion (, chopped)","500g/ 1 lb beef mince (ground beef) (Note 1)","1 carrot (, medium, shredded using box grater (I keep skin on) )","1 zucchini (, medium, shredded using box grater (Note 2))","1 red capsicum (bell pepper), chopped (Note 2)","2 tbsp tomato paste","800g/ 28 oz canned crushed tomato","400g/ 14 oz kidney beans (, drained (or other beans of choice, can omit))","2 cups chicken stock/broth (, low sodium (sub beef stock))","2 cups water (just regular tap water!)","350g / 12 oz (3 cups) elbow pasta (macaroni) (, spirals, penne, ziti, small shells, rigatoni or similar size, uncooked (Note 3))","1 1/2 cups (tightly packed) colby cheese (or other melting cheese of choice, preferably freshly shredded (melts better))","1 green onion stem (, finely sliced (optional garnish))"],"purpose":"One-pot pasta:"},{"ingredients":["1 1/2 tsp dried thyme","1 1/2 tbsp paprika (sweet/regular, not smoked or spicy)","2 tsp garlic powder","2 tsp onion powder","1/2 tsp cayenne pepper (, optional (faintly spicy))","1/4 tsp black pepper","1 1/4 tsp cooking salt / kosher salt"],"purpose":"Cajun spices:"}]', '[{"description":"Heat the oil in a large heavy based pot with a lid over high heat.","images":[],"step":1},{"title":"Cook vegetables","description":"Cook the onion and garlic for 2 minutes. Add the beef and cook, breaking it up as you go, until you no longer see red meat. Add the carrot and zucchini, cook for 2 minutes until the water they release mostly evaporates. Add the capsicum and cook for 2 minutes.","duration":2,"images":[],"step":2},{"title":"Spices","description":"Add the tomato paste and Cajun Spices. Cook for 1 minute.","duration":1,"images":[],"step":3},{"title":"Pasta sauce","description":"Add the canned tomato, water (I swill the cans clean), stock and beans. Mix and bring to a simmer.","images":[],"step":4},{"description":"Add the pasta, stir, let it come back up to the simmer. Put the lid on and lower the heat slightly to medium so the liquid is simmering (not bubbling madly).","images":[],"step":5},{"description":"Cook for 15 minutes, stirring every few minutes so the base doesn''t catch. The pasta should be a bit firmer than you want in the middle, and still a bit soupy which is good! Liquid gets absorbed in the next step.","duration":15,"images":[],"step":6},{"title":"Melt cheese","description":"Give it a stir, smooth the surface, sprinkle with cheese. Put the lid on then turn the stove off (leave the pot on the stove). Leave for 3 minutes so the residual heat melts the cheese and the pasta finishes cooking.","duration":3,"images":[],"step":7},{"title":"Serve","description":"Remove from the stove, sprinkle with green onion if desired, then serve immediately while saucy and the cheese is gooey!","images":[],"step":8}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef","beef-mince-recipes","beef-recipes","mains","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ac5f1a0b1b90', 'en', 'US', 'Beef Tenderloin with Creamy Mushroom Sauce', 'Recipe video above. This recipe uses a simple but highly effective, low-risk slow-roasting technique for evenly cooked tenderloin that''s blushing pink from edge to edge. No thick overcooked band!A slather of garlic-thyme-butter gives the beef a tasty crust, and the drippings from roasting are used to make a magnificent creamy mushroom sauce. Marsala, an Italian fortified wine you can pick up cheaply, is the secret ingredient in the sauce for a luxurious edge of flavour. But if you need to be alcohol free, see recipe notes.Please get a meat thermometer to take the guess work out! It''s far cheaper than the beef. (Note 4)PRO TIP: Season the beef the night before for best results. (Note 5)', 'https://www.recipetineats.com/tachyon/2023/12/Beef-tenderloin-with-mushroom-sauce_3.jpg', 15, 60, 75, 4, '[{"id": "ing_beef", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_mushroom", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_marsala", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}]', '[{"ingredients":["1 - 1.25kg/ 2 - 2.5lb centre cut beef tenderloin (eye fillet), tied (Note 1)","1 1/2 tsp cooking / kosher salt","1/2 tsp black pepper","1 tbsp vegetable oil"],"purpose":"Beef:"},{"ingredients":["75g/ 5 tbsp unsalted butter (, softened)","1 tsp garlic (, finely grated or very finely minced with a knife)","1 tsp fresh thyme leaves (, finely chopped (Note 2))","1/4 tsp cooking/kosher salt","1/4 tsp black pepper"],"purpose":"Garlic-Thyme-Butter-Slather:"},{"ingredients":["150g/5 oz white mushrooms (, sliced 3mm thick)","1/2 tsp garlic (, finely minced)","1 thyme sprig (Note 2)","3/4 cup marsala (, Italian fortified wine (Note 3))","1/2 cup chicken stock (, low sodium)","3/4 cup thickened cream (heavy cream)","1/4 tsp black pepper"],"purpose":"Creamy mushroom sauce:"}]', '[{"title":"Prep beef","description":"Pat beef dry with paper towels, sprinkle with salt and pepper all over. Place the beef on a rack on a tray then refrigerate uncovered 12 to 24 hours. (Can skip, Note 5)","images":[],"step":1},{"title":"Butter Slather","description":"Mix Butter Slather ingredients in a bowl.","images":[],"step":2},{"title":"De-chill","description":"Remove the beef from the fridge 2 hours prior to cooking. This helps the beef cook evenly.","images":[],"step":3},{"title":"Sear","description":"Heat oil in an ovenproof heavy based pan over high heat until smoking. (Note 6) Brown the surface of the beef all over, aggressively and quickly. Then put the beef back on the rack to cool for 15 minutes (so the butter doesn''t instantly melt when you put it on).","duration":15,"images":[],"step":4},{"description":"Preheat oven to 120°C/250°F (both fan and standard ovens) (Note 7).","images":[],"step":5},{"title":"Butter","description":"Put beef back in cooled skillet. Slather 3/4 of the butter onto the beef - top and sides (not underside).","images":[],"step":6},{"title":"Roast 40","description":"50 minutes - Roast for 15 minutes. Remove, slather remaining butter onto the top and sides. Roast for a further 25 - 35 minutes or until the internal temperature is 53°C/127°F for medium rare (Note 8 for other levels of doneness).","duration":15,"images":[],"step":7},{"title":"Rest & serve","description":"Remove beef from the skillet onto a cutting board and rest for 10 minutes. The internal temperature will rise 56-58°C / 133-136°F (this is medium rare). Slice thickly and serve with Creamy Mushroom Sauce!","duration":10,"images":[],"step":8},{"description":"Creamy mushroom sauce","images":[],"step":9},{"title":"Roasting juices","description":"Pour all juices in skillet into a bowl or jug. The fat will rise to the surface. Pour off 1/4 cup (60ml) of the fat back into the skillet (reserve the rest for later).","images":[],"step":10},{"title":"Cook mushrooms","description":"Turn the stove onto high. Once the butter is hot, add mushrooms and cook until they start to sweat. Then add thyme and garlic, and cook for a further 2 minutes until the mushrooms are softened.","images":[],"step":11},{"title":"Sauce","description":"Add chicken stock/broth and reduce by half. Add marsala, cream, pepper and remaining reserved roasting juices. Simmer on medium / medium high for 5 minutes until it reduces by half and the sauce is thickened. Taste - it should be slightly on the salty side (which will seem just right with each mouthful of beef). Add more salt if needed. Serve with beef.","duration":5,"images":[],"step":12}]', '["fish","milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef","beef-recipes","mains","roast-beef","roasts","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_37e8be83e724', 'en', 'US', 'One pot creamy tomato beef pasta', 'Recipe video above. This is a beefy pasta cooked with Italian seasonings in a creamy tomato sauce. Epitome of homemade comfort food with the convenience of one-pot cooking! Love how the pasta absorbs the flavour of the sauce.For more, see the full One Pot Pasta recipe collection.', 'https://www.recipetineats.com/tachyon/2023/08/One-pot-creamy-tomato-beef-pasta_0.jpg', 10, 20, 30, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_italian_herbs", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 1/2 tbsp olive oil","2 garlic cloves (, finely minced)","1 onion (, finely chopped)","500g/ 1 lb beef mince / ground beef","2 tsp Italian herbs (Note 1)","2 tbsp tomato paste","400g/ 14 oz can crushed tomatoes (or tomato passata)","1/2 tsp red pepper flakes (chilli flakes, optional)","1 1/2 tsp cooking salt/kosher salt","1/2 tsp black pepper","4 cups (1 L) chicken stock/broth (, low sodium (Note 2))","350g/ 12oz fusilli, penne, elbow macaroni ( or other short pasta (Note 3))","3/4 cups thickened / heavy cream"]},{"ingredients":["Parmesan cheese (, finely grated)","Parsley (, finely chopped, optional)"],"purpose":"Serving:"}]', '[{"title":"Sauté","description":"Heat the oil on high heat in a large heavy-based pot. Cook garlic and onion for 1 1/2 minutes.","images":[],"step":1},{"title":"Cook beef & seasonings","description":"Add beef and cook, breaking it up as you go, until you can no longer see red meat. Add the Italian herbs and cook for 30 seconds, then add tomato paste and cook for 1 minute to cook out the raw flavour.","duration":0.5,"images":[],"step":2},{"title":"All in","description":"Add crushed tomato, chicken stock, salt, pepper and red pepper flakes, if using. Stir, then add the pasta.","images":[],"step":3},{"title":"Cook 15 min","description":"Bring the liquid to a simmer, then cook for 15 minutes, stirring every couple of minutes then more frequently towards the end (ensure pasta doesn''t stick to base) until the pasta is just about cooked.","duration":15,"images":[],"step":4},{"title":"Creamy","description":"Add cream, then simmer for a further 1 to 2 minutes. It will still be quite saucy - this is what you want! Pasta absorbs liquid quickly, so it will still be nice and oozy when you start eating.","images":[],"step":5},{"title":"Serve","description":"Remove from the stove. Give it a good stir then ladle into bowls. Serve with parmesan and parsley.","images":[],"step":6}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["beef","beef-mince-recipes","beef-recipes","dinner-tonight","mains","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5231f7ba1735', 'en', 'US', 'Crispy Lebanese Meat Stuffed Pita - Arayes', 'Recipe video above. Lebanese street food - pita bread stuffed with spiced kofta meat, pan fried until crispy! Think of these as Lebanese quesadillas or easy Gozleme. :) The unique method here is that it''s cooked with raw meat inside, so the tasty meat juices soaks into and flavours the pita bread as it cooks. It''s outrageously delicious. I bet you become as obsessed with these as I have!', 'https://www.recipetineats.com/tachyon/2023/07/Arayes_2-close-up.jpg', 15, 15, 30, 10, '[{"id": "ing_bread", "quantity": {"value": 5.0, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_tahini", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}]', '[{"ingredients":["5 pita bread (, the thin pocket type, ~15cm/6\" diameter (250g/8oz pack), cut in half (Note 1))","Olive oil spray (or brush with olive oil)"]},{"ingredients":["1/2 brown onion","500g/ 1 lb lamb or beef mince (ground meat) (Note 2)","2 garlic cloves (, finely grated)","1 tbsp finely chopped parsley (, optional)","3 tsp ground coriander","3 tsp ground cumin","1 1/2 tsp smoked paprika (sub plain paprika)","3/4 tsp ground allspice (sub mixed spice)","1/2 tsp cayenne pepper (reduce/omit for less spicy - Note 4)","1 1/4 tsp cooking/kosher salt"],"purpose":"Spiced meat filling:"},{"ingredients":["1 cup plain yogurt","2 tbsp tahini (or Chinese sesame paste - Note 5)","1 tbsp lemon juice","1 garlic clove (, finely grated)","1/2 tsp cooking/kosher salt"],"purpose":"Whipped tahini yogurt sauce:"}]', '[{"description":"Spiced meat filling:","images":[],"step":1},{"description":"Grate the onion in a bowl using a standard box grater. We want the juices and all! (Note 4)","images":[],"step":2},{"title":"Meat filling","description":"Add remaining meat filling ingredients. Mix well with your hands.","images":[],"step":3},{"description":"Divide stuffing in 10 (about 55 to 60g per portion, 1/4 cup). Flatten into a semi-circle shape slightly smaller than the pita bread half.","images":[],"step":4},{"title":"Stuff","description":"Gently open a pita then place the meat inside. Close, then press to spread to the edge and make it fairly evenly flat. (Is your pita tearing? See Note 5 for tip!)","images":[],"step":5},{"description":"Cooking Arayes:","images":[],"step":6},{"description":"Preheat oven to 50C/120F. Place a rack on a tray. (To keep cooked Arayes warm.)","images":[],"step":7},{"title":"Cook","description":"Heat a large frying pan over medium high heat. Spray both sides of the pita with olive oil then place 2 or 3 pieces in the pan (whatever you can fit). Cook for about 2 minutes on each side, pressing down lightly with a spatula, until golden and crispy. The meat is spread so thin it cooks really quickly! {Sandwich press - Note 7}","images":[],"step":8},{"title":"Keep warm","description":"Transfer cooked Arayes onto the rack and put in the oven to keep warm. Cook remaining pita.","images":[],"step":9},{"title":"Serve","description":"Cut in half if desired (sometimes I do, sometimes I don''t!). Pile Arayes onto a serving platter. Serve with Whipped Tahini sauce. Enjoy!","images":[],"step":10},{"description":"Whipped tahini sauce:","images":[],"step":11},{"description":"Place ingredients in a heatproof bowl and whisk to combine. Microwave for 15 seconds on high. Whisk again - it should resemble soft whipped cream. Use slightly warm or at room temperature.","duration":0.25,"images":[],"step":12}]', '["gluten","milk","sesame"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["lebanese","Middle Eastern"],"categories":["beef","beef-mince-recipes","beef-recipes","cuisines","lamb","mains","middle-eastern-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c74153ab432e', 'en', 'US', 'Saltimbocca', 'Recipe video above. This rustic Italian classic is fabulously quick to make thanks to thin slices of veal that cook in 2 1/2 minutes flat. Traditionally made with veal, Saltimbocca is also excellent with chicken or beef. The trick to a great Saltimbocca sauce is to slowly melt in cubes of cold butter by swirling the pan off the heat. This thickens the sauce and makes it luxuriously silky. It''s a stunner! Serve with mashed potato, cauliflower mash or mop your plate clean with bread.', 'https://www.recipetineats.com/tachyon/2022/09/Veal-saltimbocca_6.jpg', 7, 5, 12, 2, '[{"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_sage", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_prosciutto", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 x 80g / 3 oz thin veal steaks or boneless cutlets","1/4 tsp black pepper","4 large sage leaves","4 prosciutto slices (finely sliced, Note 2)","2 tbsp flour (plain/all-purpose)","2 tbsp olive oil"]},{"ingredients":["50 g / 3 tbsp COLD unsalted butter (, cut into 1cm / 1/3\" cubes (Note 3))","1/4 cup white wine (, pinot grigio or chardonnay (Note 4))","Small pinch of salt"],"purpose":"Saltimbocca Sauce:"}]', '[{"description":"Prepare saltimbocca:","images":[],"step":1},{"title":"Pound","description":"Place the veal between sheets of cling wrap or paper. Pound to an even 3mm thickness using a meat mallet (Note 5 for tips!) Cut each piece in half so you have 4 pieces in total, and sprinkle both sides with pepper.","images":[],"step":2},{"title":"Prosciutto and sage","description":"Fold a slice of prosciutto in half then place on one piece of veal (trim if needed so it''s not hanging off the sides too much). Place a sage leaf on top then secure with a toothpick, piercing from the underside (see step photos or video). Do the same with the other piece of veal.","images":[],"step":3},{"title":"Dust","description":"Spread flour on a plate. Press the non-prosciutto side of the veal into the flour, shaking off excess (do not flour the prosciutto side).","images":[],"step":4},{"description":"Cook:","images":[],"step":5},{"title":"First side 1 1/2 minutes","description":"Heat oil in a large fry pan over medium-high heat. Place veal slices in the pan, prosciutto-side down, and cook for 90 seconds until prosciutto is beautifully golden.","duration":1.5,"images":[],"step":6},{"description":"Other side 1 min:Turn veal and cook the other side for 1 minute. Remove to a warm plate.","duration":1,"images":[],"step":7},{"description":"Tip out excess oil (do not scrape pan clean however). Return skillet to stove, with heat still on.","images":[],"step":8},{"title":"Reduce wine","description":"Pour in wine (careful, it will be steamy!) plus pinch of salt. Bring to a simmer then let it cook for 20 to 30 seconds, stirring to scrape up the brown fond from the base of the pan, until wine is reduced by half.","duration":0.4166666666666667,"images":[],"step":9},{"title":"Swirl butter","description":"Keep the pan on the stove but turn the stove OFF. Scatter the butter in the pan then swirl (or stir) until it melts. The clear liquid will thicken magically into a luscious butter sauce!","images":[],"step":10},{"description":"Serve:","images":[],"step":11},{"description":"Divide veal between plates. Spoon over sauce. Devour! (Careful of the toothpick!)","images":[],"step":12}]', '["gluten","milk"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["beef","chicken-breast-recipes","italian-recipes","mains","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_009c06f39fc0', 'en', 'US', 'Family Meat Pie', 'Recipe video above. Aussies love a good meat pie. We love the hand-held ones because we get the whole thing to ourselves. But when you''ve got sharing vibes, this Family-size Meat Pie is the one you pull out. Shortcrust base, slow cooked fall-apart chunks of beef smothered in a rich gravy with a golden puff pastry lid.It''s knee-shatteringly good comfort food!Workflow - I usually make the filling the day before, then refrigerate overnight. Then I do everything else on the day of serving.', 'https://www.recipetineats.com/tachyon/2021/09/Meat-Pie-Family-Size_39-new.jpg', 20, 240, 440, 6, '[{"id": "ing_beef", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.625, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_guinness", "quantity": {"value": 330.0, "unit": "unit"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_quantity_shortcrust_pastry", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_sheet_puff_pastry", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["800g/ 1.6lb chuck beef (, 3.5cm/1.4\" cubes (Note 1))","3/4 tsp salt","1/2 tsp pepper","2 tbsp olive oil (, plus more as needed (or vegetable or canola))"],"purpose":"Beef:"},{"ingredients":["30g / 2tbsp unsalted butter","200g / 7 oz mushrooms (, smallish, halved (larger ones quartered))","125g / 4 oz streaky bacon (, cut into 1 x 1.5cm / 0.4 / 0.6\" cubes)","1 onion (, cut into 2cm / 0.8\" cubes)","2 garlic cloves (, minced)","1 celery (, cut into 1cm/0.4\" slices (split wide end of celery lengthwise, don’t want giant celery chunks))","1 carrot (, halved, 1cm/0.4\" slices (quarter very thick end if needed))","330ml / 11 oz Guinness (Note 2)","2 cups beef stock (, homemade or store bought low sodium (Note 3))","1 cup water","1/4 tsp salt","3/4 tsp coarsely crushed black pepper (, plus more as desired)"],"purpose":"Filling:"},{"ingredients":["4 tbsp flour","60g / 4 tbsp unsalted butter (, softened)"],"purpose":"Beurre Manié (sauce thickener, Note 4)"},{"ingredients":["1 quantity shortcrust pastry","1 sheet puff pastry (, for lid (Note 6))","1 egg (, lightly whisked)"],"purpose":"Pastry:"},{"ingredients":["Ketchup or Aussie Tomato Sauce (, for serving)"],"purpose":"Serving:"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":1},{"title":"Brown beef","description":"Sprinkle beef with 3/4 tsp salt and 1/2 tsp pepper. Heat oil in a large heavy based pot over high heat. Brown beef aggressively in 2 to 3 batches (do not crowd pot, else it gets watery instead of browning). Then remove beef into a big bowl.","images":[],"step":2},{"title":"Wipe down pot","description":"Wipe pot clean of burnt bits, if needed.","images":[],"step":3},{"title":"Cook bacon","description":"Cool pot, add bacon. Place pot back onto medium heat. When you see some fat starting to melt, turn heat up to medium high and cook bacon until golden. Then remove into bowl with beef.","images":[],"step":4},{"title":"Cook mushrooms","description":"Melt 30g/ 2tbsp butter in the pot. Cook mushrooms until golden with a pinch of salt and pepper. Remove into separate bowl with slotted spoon.","images":[],"step":5},{"title":"Cook other vegetables","description":"Add onion, garlic, carrot and celery then cook for 5 minutes until onion is soft and sweet, not too golden. Add oil if needed, but bacon fat + residual butter should be enough.","duration":5,"images":[],"step":6},{"title":"Oven slow cook","description":"Add beef, bacon, Guinness, water, stock, 1/4 tsp salt and 3/4 tsp pepper. Stir then bring to simmer. Cover with lid, then transfer to oven for 1 hour.","images":[],"step":7},{"description":"Add mushrooms, then continue cooking in the oven for a further 1 hour. Meat should be starting to be tender at this stage.","images":[],"step":8},{"description":"Thicken Sauce and Cool:","images":[],"step":9},{"title":"Stove reduce","description":"Remove pot from oven. Remove lid, then simmer on low heat for 20 minutes to reduce sauce. Meat should now be \"fall-apart-tender\" but just holding form (not disintegrating).","duration":20,"images":[],"step":10},{"title":"Sauce thickener (Beurre Manié","description":"Note 4): Mix together butter and flour until smooth.","images":[],"step":11},{"title":"Thicken sauce","description":"Stir Beurre Manié into sauce. Once melted, leave on the stove for another 2 minutes. Sauce should be thicker than a normal stew, like a honey consistency. Sauce will not thicken any more in oven, so make it exactly what you want - Note 7. Also, there will be more sauce than you expect for a pie - some gets absorbed by pastry (but won''t make it soggy).","images":[],"step":12},{"title":"Cool","description":"Cover pot with lid, then let it cool completely, preferably overnight. (Note 8)","images":[],"step":13},{"description":"Assemble and bake:","images":[],"step":14},{"title":"Shortcrust base","description":"Make and blind bake Shortcrust Pastry per that recipe using a 23cm/9” pie dish, whether using homemade or store bought. Then let it cool for at least 15 minutes (stays crispier).","images":[],"step":15},{"title":"Preheat oven","description":"Turn oven up to 200°C/390°F (180°C fan).","images":[],"step":16},{"title":"Fill pie","description":"Bring filling to room temp, do not use fridge cold. (Note 9) Fill pie with filling (use it all, pack it in a level surface or have slight mound).","images":[],"step":17},{"title":"Puff pastry lid","description":"Partially thaw puff pastry (do not cut). Brush lip of pie crust base with egg, then top with puff pastry sheet. Trim excess with scissors, press to adhere to edges. Then press the tip of a fork around the edge to make little crimps (to further adhere + decorative).","images":[],"step":18},{"title":"Egg wash","description":"Brush top with remaining whisked egg, then make a 2.5cm / 1\" X incision in middle to allow steam to escape (stops lid doming).","images":[],"step":19},{"title":"Bake: Bake 45","description":"50 minutes until top is super golden. Rest 5 minutes. Brag in comments below that you made this magnificent pie. Save Nagi a slice. Then serve remainder with ketchup or Aussie tomato sauce!","images":[],"step":20}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Australian"],"categories":["beef","beef-recipes","casseroles-and-cosy-bakes","mains","quiches-tart-and-pie-recipes","slow-cooked-fall-apart","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a7e5f4b903d8', 'en', 'US', 'Café de Paris - Steak butter sauce', 'Recipe video above. Café de Paris is a butter for steak flavoured with a mix of herbs, spices and savoury condiments. Despite the name, it originates from Switzerland, popularised by a restaurant called "Café de Paris". Now a staple steak sauce around the world (including in Paris!), slices of this compound butter are placed on hot steaks so they melt to form a butter sauce. It''s so simple, yet so incredibly good!Makes enough for 4 to 6 steaks, depending on how much butter you want on your steaks. Keeps for 2 months in the fridge, also excellent over seafood, poultry and hot steamed veg!', 'https://www.recipetineats.com/tachyon/2021/08/Cafe-de-Paris-butter-for-steak_19.jpg', 10, 0, 10, 4, '[{"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_tarragon", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}]', '[{"ingredients":["100g / 7 tbsp unsalted butter (, softened)","2 tbsp eschalot (small), very finely chopped (Note 1)","1 garlic (, finely minced)","3 anchovy fillets (, finely chopped (Note 2))","1 tsp lemon juice","1 tsp Worcestershire sauce","1 tsp Dijon mustard","1 tsp curry powder (mild, Note 3)","1/2 tsp paprika (plain or sweet, not smoked or spicy)","1 tsp kosher / cooking salt","2 tsp tarragon (, finely chopped (Note 4))","2 tsp parsley (, finely chopped)"]},{"ingredients":["Steaks of choice (Note 5)","1/2 tsp cooking/kosher salt per steak","1/4 tsp black pepper per steak","1 tbsp vegetable or canola oil"],"purpose":"Steak:"}]', '[{"description":"Café de Paris butter:","images":[],"step":1},{"description":"Place ingredients in a bowl and mix to combine.","images":[],"step":2},{"description":"Place on cling wrap and roughly shape into a 20cm / 8\" log using spatulas or butter knives.","images":[],"step":3},{"description":"Roll up, then twist ends tightly. As you tighten the ends, the butter will shape into a neat, firm log.","images":[],"step":4},{"description":"Tie ends if needed to keep the shape. Refrigerate for 3 hours or until firm.","images":[],"step":5},{"title":"To use","description":"Slice into 0.7cm (1/3\") slices, then let them soften to room temperature (so they melt easier). Place on hot steak so it melts - I use 2 slices each steak. Leftovers - fridge 3 days or freeze 2 months (pre sliced for ease of use).","images":[],"step":6},{"description":"Cooking Steak:","images":[],"step":7},{"description":"Cooking Steak:","images":[],"step":8},{"title":"Bring to room temp","description":"Take the steak out of the fridge 30 minutes prior to cooking.","images":[],"step":9},{"title":"Dry","description":"Pat steaks dry with paper towels.","images":[],"step":10},{"title":"Heat skillet","description":"Heat oil in a heavy based skillet over high heat until it is very hot - you should see smoke!","images":[],"step":11},{"title":"Season","description":"Sprinkle each side of the steak generously with salt and pepper, then immediately place in the skillet.","images":[],"step":12},{"title":"Cook steak to taste","description":"For 2cm (3/4\") thick steaks, cook the first side for 2 minutes, then turn and cook the other side for 2 minutes (medium rare 52°C/125°F, chart below for other doneness temps).","duration":2,"images":[],"step":13},{"title":"Rest","description":"Transfer steaks to a warm plate, cover loosely with foil and rest for 5 to 10 minutes, then serve.","duration":7.5,"images":[],"step":14},{"description":"Cooking Steak:","images":[],"step":15},{"title":"Leftovers","description":"fridge 3 days or freeze 2 months (pre sliced for ease of use).","images":[],"step":16}]', '["fish","milk","mustard"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["beef","beef-recipes","mains","quick-and-easy","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_751a5c03d295', 'en', 'US', 'Mexican Meatballs', 'Recipe video above. The best Mexican Meatballs are spiced with Mexican flavours and made with:1. crushed corn chips instead of breadcrumbs (more flavour!);2. a combination of beef AND pork (softer and tastier); and3. are browned in the oven then simmered in the chipotle tomato sauce for a winning flavour exchange: meatball juices leech into the sauce, and the meatballs absorb the sauce flavour. Win win!Spiciness: Chipotle powder and fresh jalapeno in meatballs gives it a warm buzz but definitely not spicy. Same for chipotle chilli in sauce. Feel free to reduce both and add a pinch of paprika in its place.', 'https://www.recipetineats.com/tachyon/2021/06/Mexican-Meatballs_5.jpg', 20, 25, 45, 4, '[{"id": "ing_beef_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_corn", "quantity": {"value": 0.125, "unit": "can of 400g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_coriander", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_jalape_o", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_cumin", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_chipotle", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_chipotle_from_a_can_of_chipotle_in_adobo", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_adobo_sauce_from_a_can_of_chipotle_in_adobo", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_guacamole", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["250g / 8oz beef mince (ground beef)","250g / 8oz pork mince (ground pork), or more beef (Note 1)","1/2 red onion (, grated using a standard box grater)","50g / 1.75 oz plain corn chips (, sub breadcrumbs + 1/4 tsp salt (Note 2))","1 egg","3 tbsp coriander/cilantro (, finely chopped (sub chives or parsley))","3 tbsp parsley (, finely chopped (optional))","2 tsp fresh jalapeño (, seeds removed and finely minced (reduce/omit for not spicy))","Oil spray (preferably olive oil)"],"purpose":"Meatballs:"},{"ingredients":["1 1/2 tsp ground cumin","1 tsp chipotle powder (, sub more smoked paprika, reduce for less spicy (Note 3))","1 tsp coriander powder","1 tsp garlic powder (sub 1/2 fresh garlic clove, finely grated)","1/2 tsp paprika (, hot for spicy or sweet for not (or sub more Chipotle powder))","1 tsp salt","1/2 tsp black pepper"],"purpose":"Meatball Mexican Spices:"},{"ingredients":["2 tbsp olive oil","2 cloves garlic (, finely minced)","1 chipotle from a can of Chipotle in Adobo (, finely chopped - add another for extra flavour! (Note 4))","1 tsp Adobo Sauce from a can of Chipotle in Adobo (Note 4)","800g / 24 oz crushed tomato","1 tsp sugar","1 tbsp coriander/cilantro (, roughly chopped)"],"purpose":"Chipotle Sauce:"},{"ingredients":["Coriander/cilantro leaves (, whole)","Shredded cheese","Sour cream","Guacamole (or just diced, sliced or mashed plain avocado)","Rice, for serving ((Note )"],"purpose":"Toppings & garnishes (pick & choose):"}]', '[{"description":"Preheat oven to 220°C/390°F (200°C fan). Place a rack over a tray. Spray rack with oil.","images":[],"step":1},{"title":"Blitz corn chips","description":"Place corn chips in a Nutribullet or food processor. Blitz until they become fine crumbs. (Else put in a ziplock bag and bash!)","images":[],"step":2},{"title":"Meatball mixture","description":"Place meatball ingredients and meatball Mexican spices in a bowl and mix well with your hands.","images":[],"step":3},{"title":"Roll meatballs: Roll into 3","description":"3.5cm / 1.2 - 1.4\" balls. Place on rack. Should make around 20 - 24 meatballs.","images":[],"step":4},{"title":"Bake 10 minutes","description":"Spray meatballs generously with oil. Bake 10 minutes until browned (they will still be raw inside, we finish cooking them in the sauce).","images":[],"step":5},{"description":"While the meatballs are in the oven, start the sauce.","images":[],"step":6},{"title":"Sauté garlic and chipotle","description":"Heat oil over medium high heat in a large skillet. Add garlic and cook for 30 seconds. Add chopped Adobo Chile and sauté for 20 seconds.","duration":0.5,"images":[],"step":7},{"title":"Simmer 5 minutes","description":"Add tomato, Adobo sauce and sugar. Bring to simmer, then turn heat down to low and cook, stirring every now and then, for 5 minutes.","duration":5,"images":[],"step":8},{"description":"Finish Meatballs:","images":[],"step":9},{"title":"Cook meatballs in sauce","description":"Remove meatballs from oven and transfer into sauce. Continue to cook the sauce for another 10 minutes, rolling meatballs every now and then, until the sauce is thickened and the meatballs are cooked.","images":[],"step":10},{"title":"Fresh coriander","description":"Sprinkle with chopped coriander/cilantro.","images":[],"step":11},{"title":"Serving","description":"Serve over rice or stuff into tortillas with toppings of choice!","images":[],"step":12}]', '["egg","milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Mexican","Tex-Mex"],"categories":["beef","beef-mince-recipes","beef-recipes","mains","meatball-recipes","mexican-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c72d597383e7', 'en', 'US', 'Beef Bourguignon (Beef Burgundy)', 'Recipe video above. Considered by many to be the mother of all stews, Beef Bourguignon is a French dish made with beef, bacon lardons, carrots, onions and mushrooms slow-cooked in a rich red wine sauce. For the most magnificent stew of your life, start this 2 days before you plan to serve it, do not shortcut pan roasting ingredients individually, and use homemade beef stock if you can!', 'https://www.recipetineats.com/tachyon/2021/02/Beef-Bourguignon_7.jpg', 40, 150, 190, 5, '[{"id": "ing_beef", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 2000.0, "unit": "pack of 1kg"}}, {"id": "ing_onion", "quantity": {"value": 16.0, "unit": "pack of 1kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["800g/ 1.6 lb chuck beef (, cut in 4-5 cm / 2” cubes (Note 1))","2 large carrots ((~300g/10oz), cut on an angle into 4-5 cm / 2” pieces)","16 pearl onions or small, round pickling onions (Note 2)","1 bay leaf (, fresh (sub: dried))","3 sprigs thyme","750ml/ 25 oz pinot noir or other red wine (Note 3)"],"purpose":"Beef marinade:"},{"ingredients":["3 tbsp oil (, olive, canola or vegetable)","3/4 tsp salt","1/2 tsp pepper"],"purpose":"Browning beef:"},{"ingredients":["200g/ 7oz mushrooms (, halved (quarters if large))","150g/ 5oz bacon piece (, cut into 1cm / 1/2” thick batons (Note 4))","50g/3 tbsp unsalted butter","3 garlic cloves (, minced)","2 tbsp tomato paste","6 tbsp flour (, plain/all purpose)","3 cups beef stock (low sodium)","1/4 tsp salt","2 tbsp chopped parsley (, for garnish)"],"purpose":"Stew:"}]', '[{"title":"Marinate beef","description":"Place the Beef Marinade ingredients in a large, non-reactive ceramic dish or ziplock bag. Marinate overnight in the fridge (minimum 12 hours, maximum 24 hours).","images":[],"step":1},{"description":"Strain liquid into a bowl, reserve marinade. Separate the beef, carrots and onion.","images":[],"step":2},{"title":"Reduce wine","description":"Pour red wine into a saucepan and bring to a boil over medium high heat. Simmer vigorously, skimming off any impurities that rise to the surface, until reduced by half. Set aside.","images":[],"step":3},{"description":"Brown beef and vegetables:","images":[],"step":4},{"description":"Preheat oven to 180°C / 350°F (160°C fan).","images":[],"step":5},{"title":"Dry beef","description":"Line a tray with paper towels, spread beef out, then pat dry with paper towels.","images":[],"step":6},{"title":"Season beef","description":"Sprinkle beef with 3/4 tsp salt and 1/2 tsp black pepper.","images":[],"step":7},{"title":"Brown beef","description":"Heat 2 tbsp oil in a large, heavy-based, oven-proof pot over high heat. Add 1/3 beef and brown aggressively all over. Remove into bowl, then repeat with remaining beef, adding more oil if needed.","images":[],"step":8},{"title":"Fry bacon","description":"Add bacon and cook for 3 minutes until golden. Add to bowl with beef.","duration":3,"images":[],"step":9},{"title":"Sauté mushrooms","description":"Add mushrooms and cook for 5 minutes, or until golden. Remove into a new bowl.","duration":5,"images":[],"step":10},{"title":"Sauté onion","description":"Add a bit of extra oil if needed, then cook onions for 5 minutes or until there are nice golden patches. Add to bowl with mushrooms.","duration":5,"images":[],"step":11},{"title":"Sauté carrot","description":"Add butter into pot. Once melted, add carrot and cook for 3 - 4 minutes until there are golden patches. Add garlic and cook for a further 1 minute.","duration":3.5,"images":[],"step":12},{"title":"Tomato paste","description":"Add tomato paste and cook for 2 minutes.","duration":2,"images":[],"step":13},{"title":"Flour","description":"Add flour and cook for 2 minutes.","duration":2,"images":[],"step":14},{"title":"Add wine and stock","description":"While stirring, slowly pour in beef stock – this helps the flour dissolve lump-free into the stock. Then add wine and mix until flour mixture is dissolved and mostly lump-free (Note 6).","images":[],"step":15},{"title":"Add beef into pot","description":"Add beef, bacon, thyme, bay leaf, 1/4 tsp salt and pepper into the pot, then stir well.","images":[],"step":16},{"description":"Slow-cook:","images":[],"step":17},{"title":"Oven 1 hour","description":"Bring to a simmer, then cover and transfer to oven for 1 hour. (Note 7)","images":[],"step":18},{"title":"Mushrooms and onion","description":"Remove from oven, stir in mushrooms and onion.","images":[],"step":19},{"title":"Oven 1½ hours","description":"Cover with lid and return to oven for 1½ hours, or until beef is \"fall-apart tender\".","images":[],"step":20},{"title":"Adjust salt","description":"Remove from oven, taste sauce and add salt if needed. (Note 8 - important!)","images":[],"step":21},{"title":"Leave overnight (recommended)","description":"If time permits, leave the stew overnight before serving because as with all stews, it gets better with time! Reheat gently on a low stove.","images":[],"step":22},{"title":"Serve over mashed potato","description":"Essential for mopping up every drop of that amazing sauce!","images":[],"step":23}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["beef","beef-recipes","iconic-dishes","mains","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8d6676aa595a', 'en', 'US', 'Caramelised Vietnamese Shredded Beef', 'Recipe video above. A very quick, very tasty way to use up leftover cooked beef used in things like broth (see notes to start from raw). Created to use up leftover brisket from making Vietnamese Pho. Cooked is tossed in a Vietnamese lemongrass marinade then pan fried until golden. It''s INSANELY delicious!', 'https://www.recipetineats.com/tachyon/2019/04/Vietnamese-Shredded-Beef_2.jpg', 14, 6, 20, 3, '[{"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_lemongrass", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["500g / 1lb (3 cups) leftover cooked brisket or other beef (, shredded or chopped (Note 1))","1 - 2 tbsp oil (, for cooking)"]},{"ingredients":["2 garlic cloves (, minced)","2 tbsp lime juice","2 tbsp fish sauce","1 tbsp soy sauce (, light or all purpose)","2.5 tbsp (packed) brown sugar","1 tbsp vegetable oil","1 tbsp lemongrass paste (Note 2)"],"purpose":"Marinade:"},{"ingredients":["Rice or noodles","Lime wedges OR Nuoc Cham (Note 3)","Fresh coriander/cilantro leaves (and/or finely sliced green onions)","Finely sliced red chilli, sliced cucumber, crushed peanuts*"],"purpose":"Serving:"}]', '[{"description":"Mix Marinade in a bowl.","images":[],"step":1},{"description":"Add shredded beef and mix. Set aside 5 minutes.","images":[],"step":2},{"description":"Heat oil in a large skillet over high heat. Add about half the beef and spread out in single layer.","images":[],"step":3},{"description":"Leave undisturbed until golden (about 1 minute). Flip then cook the other side just briefly (about 30 seconds) just to heat and get a touch of golden, then remove.","images":[],"step":4},{"description":"Repeat with remaining beef.","images":[],"step":5},{"description":"Serve over rice, using either limes or Nuoc Cham as the sauce, and garnishes of choice (I used them all in the photos!)","images":[],"step":6}]', '["fish","gluten","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Modern Vietnamese"],"categories":["beef","beef-recipes","dietary","gluten-free-recipes","mains","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f99b03cb0544', 'en', 'US', 'Beef Stroganoff', 'RECIPE VIDEO ABOVE. Juicy strips of beef smothered in a sour cream mushroom gravy - a quick dinner everyone will love! KEY STEPS: Sear beef super quickly for maximum juiciness and use a large skillet (for quick sear + fast sauce reduction). Stroganoff calls for good beef but if you only have a budget cut, use this easy Chinese method to tenderise the beef (it''s called "velveting"). It''s life changing - and perfect for Stroganoff.', 'https://www.recipetineats.com/tachyon/2018/01/Beef-Stroganoff_2-1-1.jpg', 15, 15, 30, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.6, "unit": "tub of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 250.0, "unit": "pack of 500g"}}, {"id": "ing_chives", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["600 g / 1.2 lb scotch fillet steak / boneless rib eye (Note 1)","2 tbsp vegetable oil (, divided)","1 large onion ((or 2 small onions), sliced)","300 g / 10 oz mushrooms (, sliced (not too thin))","40 g / 3 tbsp butter","2 tbsp flour (Note 2)","2 cups / 500 ml beef broth (, preferably salt reduced)","1 tbsp Dijon mustard","150 ml / 2/3 cup sour cream","Salt and pepper"]},{"ingredients":["250 - 300 g / 8 - 10 oz pasta or egg noodles of choice (Note 3)","Chopped chives (, for garnish (optional))"],"purpose":"Serving:"}]', '[{"description":"Use your fist (or rolling pin or mallet) to flatten the steaks to about 3/4cm / 1/3\" thick. Slice into 5mm / 1/5\" strips (cut long ones in half), discarding excess fat.","images":[],"step":1},{"description":"Sprinkle with a pinch of salt and pepper.","images":[],"step":2},{"description":"Heat 1 tbsp oil in a large skillet over high heat. Scatter half the beef in the skillet, QUICKLY spread it with tongs. Leave untouched for 30 seconds until browned. Turn beef quickly (as best you can!). Leave untouched for 30 seconds to brown. Immediately remove onto a plate. Don''t worry about pink bits and that it will be raw inside.","duration":0.5,"images":[],"step":3},{"description":"Add remaining 1 tbsp oil and repeat with remaining beef.","images":[],"step":4},{"description":"Turn heat down to medium high. Add butter, melt. Then add onions, cook for 1 minute, then add mushrooms.","duration":1,"images":[],"step":5},{"description":"Cook mushrooms until golden. Scrape bottom of fry pan to get all the golden bits off (this is flavour!).","images":[],"step":6},{"description":"Add flour, cook, stirring, for 1 minute.","duration":1,"images":[],"step":7},{"description":"Add half the broth while stirring. Once incorporated, add remaining broth.","images":[],"step":8},{"description":"Stir, then add sour cream and mustard. Stir until incorporated (don''t worry if it looks split, sour cream will \"melt\" as it heats).","images":[],"step":9},{"description":"Bring to simmer ,then reduce heat to medium low. Once it thickens to the consistency of pouring cream (3 - 5 minutes), adjust salt and pepper to taste.","images":[],"step":10},{"description":"Add beef back in (including plate juices). Simmer for 1 minute, then remove from stove immediately. (Note 4)","duration":1,"images":[],"step":11},{"description":"Serve over pasta or egg noodles, sprinkled with chives if desired.","images":[],"step":12}]', '["egg","fish","gluten","milk","mustard"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Russian","Western"],"categories":["beef","beef-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","mains","nagis-picks","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1ea0f9b2f17b', 'en', 'US', 'Sloppy Joes', 'Recipe video above. Everybody loves Sloppy Joes - and they''re easy to make from scratch! I like making it with crushed tomato and less ketchup, and skipping the flavoured canned tomato sauces. Ideal freezer food, and to scale up to make for gatherings. SWEETNESS: Sloppy Joes are typically quite sweet, this is less sweet than most. But if you want it with just a bit of sweetness, skip the brown sugar and add it in gradually towards the end, adjusting to taste.', 'https://www.recipetineats.com/tachyon/2018/10/Sloppy-Joes_3.jpg', 10, 40, 50, 5, '[{"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_ketchup", "quantity": {"value": 0.15, "unit": "bottle of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 5.0, "unit": "loaf"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_other_fixing_options_see_note_4", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1 tbsp /15g butter","2 garlic cloves (, minced)","1 onion (, finely chopped)","1 green capsicum/bell pepper (, diced)","500 g/1lb ground beef (mince) (Note 1)","1 tbsp Dijon mustard (OR 1 tsp dry mustard)","1.5 tbsp brown sugar","1/2 cup ketchup","400 g/14oz crushed tomato (, canned)","2 tsp Worcestershire sauce","1 tbsp tomato paste","1 beef bouillon cube (, crumbled (Note 2))","1/4 tsp black pepper"]},{"ingredients":["5 to 6 soft rolls (Note 3)","Cheese slices (optional)","Other fixing options - see Note 4"],"purpose":"To serve:"}]', '[{"description":"Melt butter in a large pot over high heat.","images":[],"step":1},{"description":"Ad garlic and onion, cook for 2 minutes until onion is almost translucent.","duration":2,"images":[],"step":2},{"description":"Add capsicum and cook for 2 minutes until softened.","duration":2,"images":[],"step":3},{"description":"Add beef and cook, breaking it up as you go, until it changes from red to brown.","images":[],"step":4},{"description":"Add remaining ingredients. Mix well, then turn heat down to medium low (or low for strong stoves).","images":[],"step":5},{"description":"Cover and cook for 30 minutes, stirring once or twice to make sure it doesn''t catch on the base. (If in rush, cook 15 minutes without lid)","duration":30,"images":[],"step":6},{"description":"Remove lid and give it a good stir for a minute. Mixture should be thick, not runny and saucy (see video). Adjust salt to taste.","images":[],"step":7},{"description":"Toast rolls. Butter if desired (I don''t).","images":[],"step":8},{"description":"Pile on lots of filling, immediately top with cheese (heat should semi melt, otherwise pop under broiler/grill). Top with lid and serve immediately!","images":[],"step":9}]', '["milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef","beef-mince-recipes","dinner-tonight","mains","quick-and-easy","sandwiches-and-sliders","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eee5a4909093', 'en', 'US', 'OSSO BUCO', 'Recipe VIDEO above. Meltingly tender veal shanks slow cooked in a tomato sauce, a classic Italian dish! This is traditionally served with Risotto Milanese (saffron risotto) but is also terrific over mashed potato, polenta and even pasta. Gremolata is also served with Osso Buco and it provides a fantastic freshness to contrast with the richness of this dish.', 'https://www.recipetineats.com/tachyon/2017/08/Osso-Buco-2.jpg', 15, 90, 105, 5, '[{"id": "ing_thick_veal_osso_bucco", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_kitchen_string", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}]', '[{"ingredients":["5 thick veal osso bucco (300 g / 10 oz each, 2.5cm / 1” thick) (or beef, Note 1)","Salt and pepper","Kitchen string (optional)","2 tbsp olive oil","1 small onion (, finely chopped)","3 garlic cloves (, minced)","1 small carrot (, finely chopped)","1 celery stick (, finely chopped)","800 g / 28 oz can crushed tomato","1 cup / 250 ml dry white wine ((not sweet, not fruity), or chicken broth)","1 cup / 250 ml chicken broth","1 chicken bouillon cube (optional, or use beef)","2 tbsp tomato paste","3 sprigs thyme or 1 ½ tsp dried thyme","2 bay leaves"]},{"ingredients":["1 cup parsley leaves (flat or curly), lightly packed","2 – 3 tsp lemon zest (, finely grated)","1 garlic clove (, minced)"],"purpose":"Gremolata:"},{"ingredients":["Risotto Milanese ((saffron risotto, recipe in notes), mashed potato or pasta)"],"purpose":"For Serving:"}]', '[{"description":"Sprinkle both sides of the veal very generously with salt and pepper.","images":[],"step":1},{"description":"Heat the oil in a large heavy based pot over high heat. Add beef and sear on both sides so it has a nice brown crust. Remove onto a plate, turn heat down to medium low.","images":[],"step":2},{"description":"If the pot is looking dry, add a splash of oil. Add garlic and onion, cook for 1 minute, then add carrot and celery. Cook on low heat for 8 minutes or until it is softened and sweet.","duration":1,"images":[],"step":3},{"title":"OPTIONAL","description":"Meanwhile, tie kitchen string around each piece of veal – holds it together for nice presentation (it falls apart once slow cooked).","images":[],"step":4},{"description":"Add tomato, wine, broth, bouillon cube (crumbled), tomato paste, thyme, and bay leaves. Mix, then return veal into pot, place lid on.","images":[],"step":5},{"title":"Adjust heat so the liquid is simmering gently","description":"about medium low. Cook until tender enough to be pried apart with forks – check at 1.5 hours then every 15 minutes after that.","images":[],"step":6},{"description":"Use slotted spoon to remove veal into bowl, cover to keep warm. Simmer liquid on medium for 5 – 15 minutes or until thickened to taste. Adjust salt & pepper at the end.","duration":10,"images":[],"step":7},{"description":"Traditionally served with Saffron Risotto (Risotto Milanese, recipe in notes), but is also terrific with mashed potato, creamy polenta or even pasta. Place a piece of Osso Buco on the serving plate, spoon over sauce, then top with Gremolata.","images":[],"step":8},{"description":"Place the parsley leaves on a cutting board. Top with garlic and lemon zest. Finely chop the parsley. Transfer to serving bowl and set aside for at least 20 minutes before use.","images":[],"step":9}]', '["gluten"]', '[]', '{"mealType":["dinner"],"cuisine":["American-Italian"],"categories":["beef","beef-recipes","dietary","gluten-free-recipes","italian-recipes","mains","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_42199f3a765f', 'en', 'US', 'One Pot Lasagna', 'Recipe video above. This is how to make an easy lasagna from scratch in one pan, complete with layers!! It''s such a great way to get a lasagna fix mid week when you don''t have the time to make a proper lasagna. Everyone will be so amazed when you tell them you made it in one pot! (Well, one pan...)This is a quick version so the meat sauce (essentially Spaghetti Bolognese) is cooked quickly, and you''ll love how we use one bottle of tomato passata for both the meat sauce and tomato topping. Make sure to use dried lasagna sheets, not fresh, which will be too soft here.Note: The carrot and celery are optional, as is the ricotta layer (but boy is it good when you use it!)', 'https://www.recipetineats.com/tachyon/2026/05/One-pot-lasagna-with-layers-5-1.jpg', 20, 50, 80, 5, '[{"id": "ing_tomato", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_ricotta", "quantity": {"value": 0.6, "unit": "tub of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_sheets_lasagna", "quantity": {"value": 8.0, "unit": "pack"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.5, "unit": "pack of 125g"}}, {"id": "ing_parsley", "quantity": {"value": 0.1, "unit": "bunch"}}]', '[{"ingredients":["24 oz / 700g (1 bottle) tomato passata ((pureed tomato - Note 1), used for both the meat sauce and sauce topping)"]},{"ingredients":["2 tbsp olive oil","3 garlic cloves (, finely minced)","1 small onion (, diced)","1 small carrot (optional) (, peeled and shredded using a box grater)","1 celery stick (optional) (, shredded using a box grater (discard stringy bits remaining))","1 lb / 500g beef mince (ground beef)","2 tbsp tomato paste","2 beef bouillon stock cubes (, crumbled)","2 tsp Worcestershire sauce","1/2 tsp white sugar (Note 2)","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper","1/2 cup water"],"purpose":"Meat sauce:"},{"ingredients":["1 tsp dried Italian herb mix (, or equal parts dried basil, oregano and parsley)","1/2 tsp garlic powder (or 1 crushed garlic clove)","1/4 tsp white sugar (Note 2)","1/2 tsp cooking salt / kosher salt","1/4 cup water"],"purpose":"Topping Sauce flavourings"},{"ingredients":["1 cup good ricotta (I like Paesanella) or smooth ricotta (Note 3)","1 tbsp milk (, as needed (probably won''t need for smooth ricotta))","1/4 tsp cooking salt / kosher salt"],"purpose":"Creamy ricotta dollops (faux bechamel!) – optional"},{"ingredients":["8 sheets (250g / 8oz) dried lasagna (US: no-boil \"oven-ready\" lasagna) (, not fresh (Note 4))","1 1/2 tightly packed cups mozzarella cheese (, shredded)","2 tsp parsley (, finely chopped (optional))"],"purpose":"Lasagna"}]', '[{"title":"Meat sauce","description":"Sauté onion, garlic, celery and carrot, cook beef. Add 2/3 bottle of passata + remaining Meat Sauce ingredients, simmer 10 min. Topping Sauce - add everything into remaining passata in bottle, shake. Creamy ricotta - vigorously whisk until it''s like whipped cream. Layer - Remove half meat sauce from pan. Slide lasagna sheets under Meat Sauce (break as needed), then do 2 more layers using reserved meat sauce. Dollop with ricotta, cover with cheese, bake 30 min at 180C/350F (160C). Stand 10 min before cutting.","images":[],"step":1},{"title":"Sauté","description":"Heat olive oil in a deep skillet/pan over medium high heat. (Mine is 26cm/10.5\" wide, 5cm/2\" deep) (Note 5) Add garlic, onion, carrot and celery. Sauté until onion is translucent - about 3 minutes.","images":[],"step":2},{"title":"Cook beef","description":"Turn up heat to high. Add beef and cook, breaking it up with the spatula, until you no longer see red.","images":[],"step":3},{"title":"Sauce","description":"Add about 2/3 of the passata (keep rest for Sauce), and remaining Meat Sauce ingredients. Bring to rapid simmer, then turn down to medium/medium low. Simmer gently for 10 minutes.","duration":10,"images":[],"step":4},{"description":"Preheat oven to 180°C/350°F (160°C fan-forced).","images":[],"step":5},{"title":"Make sauce","description":"Add Sauce Flavourings into the tomato passata bottle and shake to combine.","images":[],"step":6},{"title":"Creamy ricotta (optional)","description":"Put the ingredients in a bowl. Start softening the ricotta using smearing motions with the back of a spoon, then switch to a whisk and give it a vigorous whisk for 20 - 30 seconds until it resembles whipped cream. (If using smooth ricotta, you''ll barely need to do this).","duration":0.4166666666666667,"images":[],"step":7},{"description":"Assemble lasagna (in-post step photos and video are helpful)","images":[],"step":8},{"title":"Remove half filling","description":"Remove the pan from the stove. Remove half the Meat Sauce into a bowl.","images":[],"step":9},{"title":"Base layer","description":"Slide one lasagna sheet, starting from the side, under the Meat Sauce - this will be the base of the lasagna. Break up pieces of lasagne and slide them in under the Meat Sauce around the sides of the pan (to form the remainder of the bottom layer). There is no need to be accurate with coverage here, you can overlap and have gaps. We are making a rustic quick lasagna, remember! Spread the Meat Sauce to cover all the lasagna sheets.","images":[],"step":10},{"title":"Layer 2","description":"Top with another layer of dried lasagna sheets. Then spread over the Meat Sauce in the bowl.","images":[],"step":11},{"title":"Layer 3","description":"Cover with a 3rd layer of lasagna sheets.","images":[],"step":12},{"title":"Toppings","description":"Pour over the Sauce and spread over the top. Do 12 - 15 dollops of ricotta across the surface (if using). Sprinkle with cheese.","images":[],"step":13},{"title":"Bake and rest","description":"Bake for 30 minutes uncovered, then set aside for 10 minutes to stabilise a bit.","duration":30,"images":[],"step":14},{"title":"Serve","description":"Sprinkle with parsley (if using), then cut and serve! Enjoy with a simple Balsamic Rocket Salad and Garlic Bread on the side.","images":[],"step":15}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian-esque","Western"],"categories":["beef-mince-recipes","beef-recipes","casseroles-and-cosy-bakes","italian-recipes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_80025a6e18b0', 'en', 'US', 'Pastel de Choclo (Chilean Beef and Corn Casserole)', 'Recipe video above. Meet my new favourite way to turn beef mince and a big bag of frozen corn into dinner! This is Pastel de Choclo, a classic Chilean casserole with a spiced onion beef filling and a thick corn topping that bakes up lightly caramelised, with surprise pockets of olives, raisins and boiled egg tucked inside. It''s like South America''s answer to Cottage Pie! Hearty, comforting, something a little difference, I love the combination of the sweet corn pudding with the savoury beef filling. PS Frozen corn is super convenient but gosh, imagine making it with fresh summer corn?Recipe credits: Inspired by a visit to La Paula, a wonderful Chilean establishment in Fairfield, Sydney, and developed with reference to a number of recipes, listed in the blue box above the video.', 'https://www.recipetineats.com/tachyon/2026/05/Pastel-de-choclo-0.jpg', 20, 75, 110, 8, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_beef_mince", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 3000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 2000.0, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_cumin", "quantity": {"value": 0.562, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_corn", "quantity": {"value": 3.125, "unit": "can of 400g"}}, {"id": "ing_milk", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 12.0, "unit": "bunch"}}, {"id": "ing_corn", "quantity": {"value": 3.125, "unit": "can of 400g"}}, {"id": "ing_pitted_black_olives_else_kalamata_is_fine", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_raisins", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}]', '[{"ingredients":["2 tbsp olive oil","1 kg / 2 lb beef mince (ground beef)","3 large onions (, diced (4 - 5 medium ones))","6 large garlic cloves (, finely minced)","1/4 cup plain flour (all-purpose flour)","1 1/2 cups beef stock/broth (, low sodium)"],"purpose":"Beef filling:"},{"ingredients":["1 1/2 tbsp cumin powder","1 tbsp paprika (regular/sweet, not spicy or smoked)","1 1/2 tsp cooking salt / kosher salt","1/2 tsp black pepper"],"purpose":"Beef spice mix:"},{"ingredients":["50g/ 3 tbsp unsalted butter (or olive oil)","1.25 kg/ 2.5 lb frozen corn (, still frozen is fine, or kernels cut off corn cobs (8 cups) (Note 1 on canned corn))","1 1/2 tsp cooking salt / kosher salt","1/2 cup milk (any fat %, non-dairy is ok too)","12 - 15 large basil leaves (, optional (Note 2))","2 tbsp fine cornmeal (or semolina (Note 3))"],"purpose":"Corn layer:"},{"ingredients":["1/4 cup pitted black olives (roughly chopped, Chilean or South American (if you can) else Kalamata is fine)","2 soft boiled eggs (, quartered (8 minutes lowered into boiling water))","2 tbsp raisins (or sultanas)","1 tbsp regular sugar (granulated sugar) (, not caster sugar / superfine sugar (Note 4))","Pinch paprika"],"purpose":"Assembling / baking:"}]', '[{"description":"Preheat oven to 200°C/390°C (180°C fan-forced).","images":[],"step":1},{"title":"Cook beef","description":"Heat the oil in a large 30cm/12\" pan over high heat. Add the beef and cook, breaking it up as you go, until you no longer see red. Cook for another couple of minutes, breaking up the beef into fine pieces. Remove beef from the pan using a slotted spoon, leaving the fat and juices behind.","images":[],"step":2},{"title":"Cook onion","description":"To the same pan, add the onion and garlic. Cook for 5 minutes, stirring regularly, until the onion is translucent.","duration":5,"images":[],"step":3},{"title":"Simmer and reduce","description":"Add the beef and mix through. Stir in the spices. Add the flour and mix until you no longer see flour. Add the stock and stir - it will thicken into a gravy quite quickly, coating the beef. Lower heat to medium and cook for 5 minutes, stirring regularly so the base doesn''t catch, until the mixture is thick enough so you can draw a path across the base of the pan and it stays.","duration":5,"images":[],"step":4},{"description":"Remove from stove and spread in a 23 x 33 cm (9 x 13\") pan, then set aside and let it cool while you make the corn.","images":[],"step":5},{"title":"Sauté","description":"Melt the butter in a pot over medium high heat. Add corn (still frozen is fine) and cook for 5 minutes, stirring regularly.","duration":5,"images":[],"step":6},{"title":"Blitz","description":"Add milk, salt and basil. Stir, then use a stick blender to blitz ~ 30 seconds (moving it around) or until you no longer see whole corn kernels. It won''t be complete smooth which is what you want.","images":[],"step":7},{"title":"Thicken","description":"Stir in cornmeal. Lower heat to medium or medium low so it''s not spitting. Cook for 5 minutes, stirring regularly so the base doesn''t catch. It should be thick enough to mound in a heap on the spoon, and when you draw a path across the base it should stay in place.","duration":5,"images":[],"step":8},{"description":"Assemble and bake:","images":[],"step":9},{"title":"Assemble","description":"Press the eggs into the beef, scatter with olives and raisins.","images":[],"step":10},{"title":"Corn topping","description":"Dollop the corn mixture across the surface then spread and smooth the surface. Sprinkle all over with the sugar, then paprika (sprinkle from a height for light coverage).","images":[],"step":11},{"title":"Bake for 40","description":"45 minutes until the surface is golden. Cool 15 minutes to let it set a bit so you can cut neat(ish) slices, then cut like lasagna and serve!","duration":42.5,"images":[],"step":12}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Chilean","South American"],"categories":["beef-mince-recipes","casseroles-and-cosy-bakes","south-american-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_da0ac6dc0fd6', 'en', 'US', 'Moroccan Spiral Meatball Zucchini Bake', 'Recipe video above. I love recipes like this - everyday ingredients used in a different way to make something new and interesting! Moroccan-spiced lamb meatballs are baked in a striking spiral arrangement with zucchini and capsicum in a bubbly garlicky tomato sauce. You will be impressed at how soft the meatballs are, and how the deceptively simple tomato sauce gets so much flavour as it bakes!Serve straight from the pan with flatbreads, couscous or basmati rice.Inspired by Özlem Warren''s Baked Aubergine Kebab with Meatballs from Özlem''s Turkish Table.', 'https://www.recipetineats.com/tachyon/2025/08/Moroccan-Meatball-Zucchini-Spiral-Bake_7.jpg', 25, 35, 60, 4, '[{"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["1/2 cup panko breadcrumbs (use GF if needed, can substitute regular breadcrumbs)","1/2 onion (, grated with a standard box grater)","500g / 1 lb lamb mince (ground lamb), or beef (Note 1)","1 egg","2 garlic cloves (, finely minced using a garlic crusher or knife)","1/4 cup pretty finely chopped parsley (, plus extra for garnish)"],"purpose":"Meatballs:"},{"ingredients":["1 tsp cumin powder","1 tsp coriander power","1 tsp paprika (sweet / regular, or smoky - not spicy)","1/4 tsp cinnamon powder (don''t skip this! Magical :) )","1/4 tsp cayenne pepper ((or black pepper), tiny amount so doesn''t make it spicy)","3/4 tsp cooking salt / kosher salt"],"purpose":"Moroccan spice mix:"},{"ingredients":["2 fat zucchinis / courgettes (5cm/2\" wide, 22cm/9\" long is ideal), cut into ~20 x 1.2 cm / 0.5\" thick rounds (Note 2)","1 large or 1 1/2 regular red capsicum (bell pepper), cut into ~20 x large-ish chunks 5 x 2.5cm / 1 x 2\" (Note 3)","1/2 tbsp extra virgin olive oil (, plus extra for drizzling to bake)","1/4 tsp each salt and pepper"],"purpose":"Vegetables:"},{"ingredients":["2 garlic cloves (, crushed using garlic press)","2 1/2 tbsp tomato paste","2 tbsp extra virgin olive oil","1/2 cup warm tap water","1/8 tsp each salt and pepper"],"purpose":"Garlic tomato sauce:"},{"ingredients":["Plain yogurt (, thinned with a little water to make it drizzle-able)","Flatbreads (, rice(basmati recommended), couscous, mash)"],"purpose":"Serving"}]', '[{"description":"Toss Vegetables, mix Sauce. Make meatball mixture, roll and squish 16 meatballs, wedge between zucchini rounds, tuck capsicum in. Pour over sauce, bake 35 minutes at 200°C/375°F (180°C fan).","images":[],"step":1},{"description":"Preheat oven to 200°C/375°F (180°C fan-forced).","images":[],"step":2},{"description":"Toss capsicum and zucchini with the oil, salt and pepper in a bowl, and set aside.","images":[],"step":3},{"title":"Sauce","description":"Mix the sauce ingredients in a small jug or bowl.","images":[],"step":4},{"title":"Meatball mixture","description":"Put the breadcrumbs in a bowl and grate the onion over. Toss with fingertips to wet the breadcrumbs with the onion juices. Then add remaining meatball ingredients and the Moroccan spice mix. Mix well with your hands.","images":[],"step":5},{"title":"Roll & squish","description":"Roll the mixture into 16 balls then squish slightly to 1.5cm / 0.6\" thickness (~2.5 tbsp/45g each), about the size of (or slightly larger than) the zucchini rounds.","images":[],"step":6},{"description":"Stand upright with a zucchini round wedged and arrange in a 26cm/10.5\" round cast-iron pan (or baking dish of similar size). I do them in a ring then use the rest to fill in the middle. Arrange loosely because next we wedge the capsicum in between wherever you can. Fill the whole pan so everything holds each other up, and use as much capsicum & zucchini as you can (you might have leftover). There are NO RULES with arrangement here, make this your own delicious artwork! :)","images":[],"step":7},{"description":"Pour sauce over everything, aiming to pour some over everything as best you can. Drizzle all over with about 1 tbsp olive oil.","images":[],"step":8},{"description":"Bake for 35 minutes until the surface of the meatballs are nicely browned.","duration":35,"images":[],"step":9},{"description":"Serve with flatbreads or garlic rice, being sure to spoon plenty of the delicious sauce over everything!","images":[],"step":10}]', '["egg","gluten","milk"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["beef-mince-recipes","cuisines","dietary","gluten-free-recipes","lamb","mains","meatball-recipes","middle-eastern-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7d36cbdc7d5e', 'en', 'US', 'Smothered rissoles', 'Recipe video above. Rissoles are great. Smothered rissoles are AWESOME!!! Especially when it’s mushroom gravy doing the smothering. :)They''re the softest rissoles you''ve ever had because we cook them in the gravy as it thickens. They come out so much softer than regular rissoles!Serve over buttery mash for cosy comfort food you''ll crave week after week.', 'https://www.recipetineats.com/tachyon/2025/07/Smothered-rissoles-overhead.jpg', 20, 15, 35, 4, '[{"id": "ing_onion", "quantity": {"value": 500.0, "unit": "pack of 1kg"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 500.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.052, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["1/2 large onion (, grated using standard box grater (Note 1))","1/2 cup panko breadcrumbs (sub regular breadcrumbs, Note 2)","500g/ 1lb beef mince (ground beef)","1 small zucchini (, grated)","1 small carrot (, peeled and grated)","1 large egg","1 large garlic clove (, crushed using garlic press or finely grated)","1/2 tsp dried thyme (optional)","1/2 tsp oregano (optional)","1/4 tsp black pepper","3/4 tsp cooking salt / kosher salt (halve for table salt)","2 tsp Worcestershire sauce"],"purpose":"RISSOLES:"},{"ingredients":["2 tbsp olive oil (, for cooking)"],"purpose":"COOKING:"},{"ingredients":["30g/ 2 tbsp unsalted butter","1/2 onion (, sliced 5mm/0.2\" thick)","2 garlic cloves (, finely chopped)","200g/ 7 oz mushrooms (, sliced 5mm/0.2\" thick)","3 1/2 tbsp flour (plain / all-purpose)","2 cups beef stock / broth (, low sodium)","1/4 tsp cooking salt / kosher salt (halve for table salt)","1/4 tsp black pepper","1 tsp Worcestershire sauce"],"purpose":"MUSHROOM GRAVY"},{"ingredients":["Mashed potato (or other starchy vehicle of choice)"],"purpose":"TO SERVE"}]', '[{"description":"Mix rissole ingredients, form 12 patties, slightly indent one side. Cook in 2 batches until lightly browned but raw inside. Wipe pan clean, melt butter, cook onion, then mushrooms, add garlic towards end. Make roux then gravy. Cook rissoles in gravy as it thickens, 4 - 5 minutes, serve!","images":[],"step":1},{"description":"Grate the onion into a large bowl, add panko, toss to soak in the onion juices. Add remaining rissole ingredients and mix well with your hands.","images":[],"step":2},{"title":"Dented patties","description":"Form 12 patties (1/4 cup each) and make a slight indentation on one side (this prevents doming while cooking).","images":[],"step":3},{"title":"Lightly brown","description":"Heat 1 tablespoon of the oil in a large non-stick pan (30cm/12\") over medium high heat. Cook half the rissoles for 1 1/2 minutes on each side until lightly browned but still raw inside. Remove onto a plate. Add the remaining oil and repeat with remaining rissoles.","images":[],"step":4},{"description":"Mushroom gravy:","images":[],"step":5},{"title":"Clean pan","description":"Discard excess oil and give the pan a rough clean with paper towels, just to remove most of the black bits.","images":[],"step":6},{"title":"Cook mushrooms","description":"Melt the butter in the same pan, cook the onion for 1 minute, then add the mushrooms and cook for 3 - 4 minutes until they release water, soften, then become lightly browned. Add the garlic for the last 30 seconds.","duration":1,"images":[],"step":7},{"title":"Cook off flour","description":"Turn the heat down to medium, scatter flour across the surface and stir for 1 minute - it will be like a dry paste.","duration":1,"images":[],"step":8},{"title":"Half beef stock","description":"While stirring, pour in half the stock then keep mixing until the flour paste dissolves and thickens the liquid, and is lump free (about 30 seconds).","images":[],"step":9},{"title":"Simmer rissoles and thicken gravy","description":"Add remaining stock, Worcestershire sauce, salt and pepper. Stir, turn heat up slightly to medium high. When it starts simmering, gently place the rissoles in (including any juices pooled on the plate). Cook rissoles 4 - 5 minutes until the liquid thickens into a thin gravy (aim for thinner than you want, thickens as you serve).","images":[],"step":10},{"description":"Serve rissoles over mash with plenty of sauce! Add a sprinkle of parsley if you''re feeling fancy.","images":[],"step":11}]', '["egg","gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Aussie","Australian"],"categories":["beef-mince-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4e8dbcdfe4f9', 'en', 'US', 'Crispy oven baked beef quesadillas', 'Recipe video above. This is a super handy method to make 3, 4 or 8 quesadillas in the oven at the same time rather than cooking them one by one on the stove. They are impressively crispy (see photos and video for proof!) and very quick to make.Stuffed with my beef taco filling though you can switch with chicken, turkey, pork or lamb, or stuff with whatever your heart desires as long as it''s not too watery because this might affect how well the tortilla crisps in the oven.', 'https://www.recipetineats.com/tachyon/2024/07/Baked-Beef-Quasadillas-51259.jpg', 5, 20, 25, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.125, "unit": "can of 400g"}}, {"id": "ing_black_beans", "quantity": {"value": 0.125, "unit": "can of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_tortillas", "quantity": {"value": 4.0, "unit": "pack of 8"}}, {"id": "ing_cheese", "quantity": {"value": 1.25, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_pico_de_gallo", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_nothing", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["2 tsp olive oil","250g/ 8oz beef mince ((ground beef) - or chicken, turkey, pork, lamb)","1 tbsp tomato paste","1/3 cup corn kernels (canned, drain, or frozen)","1/3 cup black beans (caned, drained)","2 tbsp water"]},{"ingredients":["4 flour tortillas (20cm/8\"), Mission crisps best, Old El Paso the least (Note 1)","3 tsp olive oil","1 1/4 tightly packed cups shredded cheese ( - cheddar, colby, tasty cheese, Monterey jack (not mozzarella))"],"purpose":"Quesadillas:"},{"ingredients":["1/2 tsp EACH ground garlic (, onion, dried oregano)","1 tsp EACH cumin (, paprika powder)","1/8 tsp cayenne pepper (, optional)","1/4 tsp cooking salt / kosher salt"],"purpose":"Homemade taco seasoning:"},{"ingredients":["Avocado sauce ( or Guacamole)","Pico de Gallo","Sour cream","Nothing (I happily eat it plain!)"],"purpose":"Serving:"}]', '[{"title":"Filling","description":"Heat the oil in a non stick pan over high heat. Add the beef and cook, breaking it up as you go, until the red colour is mostly gone. Add the Taco Seasoning and cook for 1 minute. Add the tomato paste and cook for 30 seconds. Stir in the beans and corn, then add the water and stir. The filling should be juicy (not dry) but not watery (compromises crispiness!). Remove into a bowl and cool for at least 15 minutes.","duration":1,"images":[],"step":1},{"description":"Preheat the oven to 220°C / 425°F (200°C fan-forced). Grease a metal tray with 1 teaspoon of olive oil (I use my hand).","images":[],"step":2},{"title":"Assemble quesadillas","description":"Spread the filling on one side of the quesadilla. Top with cheese, fold to cover. Place on tray, repeat with remaining quesadillas.","images":[],"step":3},{"description":"Drizzle the top of each with 1/2 tsp olive oil then spread using your hands (top and sides, not underside). Press the quesadilla down to flatten the surface.","images":[],"step":4},{"description":"Bake for 8 minutes. Flip the quesadillas, bake for 5 minutes, flip again then bake for a further 2 minutes or until crispy. (Sometimes I spritz with oil to give it a helping hand)","duration":8,"images":[],"step":5},{"title":"Serve","description":"Cut each into half and serve immediately with dipping sauce/toppings of choice.","images":[],"step":6}]', '["gluten","milk"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["beef-mince-recipes","mexican-recipes","quesadillas","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a5b8c424a45a', 'en', 'US', 'Qeema Indian Curried Beef', 'An authentic Indian spiced ground (minced) beef recipe known as Qeema (or keema or kheema). This is a gem of a recipe because it tastes incredible but unlike many Indian dishes, there are no hard-to-find spices in the ingredients. And it''s super fast - on the table in 20 minutes! Serve over basmati rice. Great with plain yogurt, even better with Mint Yogurt.', 'https://www.recipetineats.com/tachyon/2016/04/Queema-Indian-Curried-Beef-Mince_3.jpg', 5, 15, 20, 4, '[{"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_ginger", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1666.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_aram_masala", "quantity": {"value": 1.25, "unit": "unit"}}, {"id": "ing_cumin", "quantity": {"value": 0.156, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.125, "unit": "bunch"}}, {"id": "ing_turmeric", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.125, "unit": "bunch"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.006, "unit": "tub of 500g"}}, {"id": "ing_mint", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["3 tbsp vegetable or canola oil (, or other neutral oil)","4 tsp ginger (, finely mince)","5 large garlic cloves (, minced (about 4 tsp))","1 large onion (, finely diced)","500g / 1 lb beef mince (ground beef)","3/4 tsp cooking salt / kosher salt","1 tsp cayenne pepper (or chilli powder (pure, not US chili powder spice mix), omit for not spicy)","1 1/4 tsp garam masala (Note 1)","1 1/4 tsp cumin powder","1 1/4 tsp coriander powder","1/2 tsp turmeric powder","1 cup water"]},{"ingredients":["1 green cayenne pepper (, deseeded, finely sliced)","Cilantro/coriander leaves","Plain yogurt or Mint yogurt (below)"],"purpose":"Garnish"},{"ingredients":["3/4 cup plain yogurt","1/2 cup (lightly packed) mint leaves","1/4 tsp cooking salt / kosher salt"],"purpose":"Mint yogurt (optional, pictured in post)"}]', '[{"title":"Sauté","description":"Heat oil in a skillet over high heat. Add ginger and garlic and saute for 30 seconds until golden, don''t let it burn! Add onion and cook for 1 minute until it is starting to turn translucent.","duration":0.5,"images":[],"step":1},{"description":"Add beef and cook, breaking it up as you go, until it changes from pink to light brown. Add remaining ingredients EXCEPT water. Cook for a further 2 minutes to let the spices bloom.","images":[],"step":2},{"title":"Cook 10 minutes","description":"Add water, give it a stir, then put a lid on (or cover with a baking tray). Turn heat down to medium and let it simmer for 10 minutes or until most of the water has evaporated.","duration":10,"images":[],"step":3},{"description":"Serve over with basmati rice or plain white rice, garnished with extra chilli and coriander/cilantro, and lots of Mint Yogurt. Naan or flatbreads would make it even better, though if time is not your friend, try frozen roti (pictured in post, Note 3).","images":[],"step":4},{"title":"Blitz then stir","description":"Put just 1/4 cup of the yogurt with the mint leaves and salt in a jug just big enough to fit the head of a stick blender. Blitz until mint is very finely chopped. Then stir in remaining yogurt. (Note 4) Refrigerate until required.","images":[],"step":5}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["beef-mince-recipes","beef-recipes","curry-recipes","dietary","dinner-tonight","gluten-free-recipes","indian-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_595f731dc716', 'en', 'US', 'Easy Moroccan Stuffed Eggplant (beef or lamb)', 'Recipe video above. A delicious, unique, EASY way to serve up eggplant and minced / ground beef or lamb! Think of this as a midweek take on traditional Arabic stuffed eggplant that''s usually hollowed out.Don''t worry if you don''t have every single spice. There''s so many in this spice mix, it will still be tasty even if you''re missing one...or two, even three!Serves 2 as a main with a small side salad, or 4 as a meal with a starch (flatbread, couscous) and a substantial side (like this Pumpkin Salad, roast veg, chickpea salad), or 4 as a generous starter.', 'https://www.recipetineats.com/tachyon/2016/03/Moroccan-baked-eggplant-halves-with-beef-or-lamb_0.jpg', 15, 45, 90, 2, '[{"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cinnamon", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_pinenuts", "quantity": {"value": 30.0, "unit": "jar"}}]', '[{"ingredients":["2 x 250g/8oz eggplants (aubergines), ~17cm/7\" long (Note 1)","3/4 tsp cooking salt / kosher salt","1 tbsp extra virgin olive oil","1 tbsp lemon juice (or more oil)"],"purpose":"Eggplant"},{"ingredients":["1 1/2 tsp EACH coriander, paprika","1 tsp cumin","3/4 tsp all spice powder","1/2 tsp EACH garlic powder, ginger, turmeric powder","1/4 tsp cinnamon","1/4 tsp cayenne pepper"],"purpose":"Chermoula spice mix (Note 2)"},{"ingredients":["1 tbsp olive oil","1 garlic clove (, finely minced)","1/2 onion (, finely chopped)","250g / 8oz beef or lamb mince (, lean if you can (chicken, turkey, pork also ok))","1/2 tsp cooking/kosher salt","2 tsp tomato paste (Note 3)","1/4 cup water"],"purpose":"Spiced beef or Lamb topping"},{"ingredients":["Yoghurt (, plain)","2 tbsp coriander/cilantro leaves (, roughly chopped (sub parsley))","2 tbsp pinenuts (, toasted (Note 4))"],"purpose":"To Serve"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":1},{"title":"Sweat eggplants (recommended, see Note 5 to skip)","description":"Cut eggplants in half then score with 2.5cm / 1\" diamonds. Rub surface with salt, getting some into the slits. Place face down in a colander and set aside for 30 minutes. Gently squeeze like a sponge to remove excess water, pat surface dry.","duration":30,"images":[],"step":2},{"description":"Mix Chermoula spice mix ingredients in a bowl. Remove 3 teaspoons for the meat and set aside. Add olive oil and lemon juice into the remaining spice mix and mix into a paste.","images":[],"step":3},{"title":"Roast eggplant","description":"Place eggplant on baking tray. Slather spice mix onto the surface. Roast for 45 minutes until softened.","duration":45,"images":[],"step":4},{"title":"Spiced topping","description":"Heat oil in a non stick skillet over medium high heat. Cook onion and garlic for 1 minute. Turn heat up to high, add lamb/beef and cook, breaking it up as you go, until you no longer see red. Add reserved spices and salt, then cook for a further 1 minute. Add tomato paste and cook for 1 minute. Stir in water, cook for 1 minute until it''s juicy but not watery.","duration":1,"images":[],"step":5},{"title":"Assemble","description":"Top eggplant with beef/lamb. Sprinkle over coriander, dollop with yogurt and pine nuts. Finish with an extra drizzle of extra virgin olive oil, if desired!","images":[],"step":6}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["beef-mince-recipes","beef-recipes","cuisines","dietary","dinner-tonight","gluten-free-recipes","lamb-recipes","low-calorie-recipes","main-dishes","middle-eastern-recipes","moroccan","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_12984a900bda', 'en', 'US', 'Beef fried rice', 'Recipe video above. GREAT quick dinner to make with beef mince, complete with veg, protein and starch! The trick is using a strong savoury sauce and caramelise the beef well for extra delicious flavour.Frozen cooked rice is a staple in my house. Don''t have day-old-cooked rice? Don''t try this recipe - you''ll be disappointed with gummy rice! Make Baked Fried Rice instead (starts with uncooked rice, and it''s awesome!). Use the beef to make Asian Beef and serve together.', 'https://www.recipetineats.com/tachyon/2023/02/Beef-fried-rice_4.jpg', 10, 10, 20, 4, '[{"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_chinese_cooking_wine", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 75.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 300.0, "unit": "pack of 1kg"}}, {"id": "ing_rice", "quantity": {"value": 450.0, "unit": "pack"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp dark soy sauce (Note 1)","2 tsp light soy sauce (Note 1)","2 tbsp oyster sauce (Note 2)","1 tbsp Chinese cooking wine (Note 3)","1/2 tsp white sugar","1/8 tsp white pepper (sub black)"],"purpose":"Sauce:"},{"ingredients":["1 tsp sesame oil","2 eggs (, lightly whisked)"],"purpose":"Scrambled eggs:"},{"ingredients":["2 tbsp oil (peanut, veg, canola or other neutral oil)","1/2 onion (, finely diced)","2 garlic cloves (, finely minced)","250g / 8 oz beef mince / ground beef (I use lean, Note 4)","2 cups frozen diced carrots, peas, corn ( (still frozen fine!) (or fresh diced veg))","3 cups day-old cooked rice (1c uncooked rice = 3c cooked, Note 5)","1/2 cup finely sliced green onions (1-2 stems)"],"purpose":"Fried rice:"}]', '[{"description":"Mix Sauce ingredients in a small bowl, then set aside.","images":[],"step":1},{"title":"Scramble eggs","description":"Heat sesame oil in a large wok or non-stick pan over medium high heat. Add egg and cook, stirring gently, so it is softly scrambled. Remove onto a plate.","images":[],"step":2},{"title":"Cook beef","description":"Heat vegetable oil in the same pan over high heat. Add onion and garlic, cook for 30 seconds. Add beef and cook, breaking it up as you go, for 2 minutes or until you no longer see raw beef. Add 2 tablespoons of sauce and cook for 1 minute.","duration":0.5,"images":[],"step":3},{"title":"Veg / caramelise beef","description":"Add frozen vegetables and cook for 2 minutes or until the beef gets nicely caramelised - this is the trick to great flavour so do not shortcut this!","duration":2,"images":[],"step":4},{"title":"Rice & sauce","description":"Add rice and remaining sauce. Toss for 2 minutes until the sauce is well dispersed throughout the rice and the rice grains start to caramelise a bit.","duration":2,"images":[],"step":5},{"title":"Egg & green onion","description":"Then add scrambled eggs and green onion, give it a quick toss to disperse then divide between bowls. EAT!","images":[],"step":6}]', '["egg","gluten","peanuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["beef-mince-recipes","fried-rice","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4f77c864ba2c', 'en', 'US', 'Cheeseburgers (double or single)', 'Recipe video above. This cheeseburger recipe assumes your bun is 10cm/4" wide. If it''s larger, you may want to scale up the beef so you don''t end up with wafer-thin patties or a burger patty that''s much smaller than your bun. Nobody likes biting into bread with no beef!!Slather with sauce of choice though for a really great burger experience, try my Special Burger Sauce (quick, no cook) or my Tomato Chutney for Burgers.', 'https://www.recipetineats.com/tachyon/2022/08/Stack-of-cheeseburgers.jpg', 10, 10, 20, 4, '[{"id": "ing_beef_mince", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 2.0, "unit": "bottle"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_lettuce", "quantity": {"value": 8.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_gherkins", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_special_burger_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_ketchup", "quantity": {"value": 1.0, "unit": "bottle of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.005, "unit": "jar of 200g"}}, {"id": "ing_french_fries", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["600 g / 1.2 lb beef mince (ground beef) (, at least 20% fat (Note 1 for quality))"],"purpose":"Single Cheeseburgers:"},{"ingredients":["1.2 kg / 2.4 lb beef mince (ground beef) (, at least 20% fat (Note 1 for quality))"],"purpose":"Mighty Double Cheeseburgers:"},{"ingredients":["1/8 tsp each salt and pepper PER burger","2 - 3 tbsp canola oil"],"purpose":"Cooking:"},{"ingredients":["4 soft burger buns or rolls (, around 10cm/4\" wide (Note 2))","4 - 8 slices burger cheese (American) or other cheese or choice (Note 3)","8 cos/romaine lettuce leaves (, torn to size (or shredded iceberg))","2 large tomatoes (, cut into eight 7mm/ 1/4\" slices)","1 red onion (, finely sliced into rings (Note 4))","2 large gherkins (, finely sliced (Note 5))"],"purpose":"Everything else you need:"},{"ingredients":["Special Burger Sauce (creamy orangey/pink one, quick no cook)","Tomato chutney for burgers","Ketchup","Mustard"],"purpose":"Sauce options:"},{"ingredients":["French fries (and it''s epic!)"],"purpose":"On the side:"}]', '[{"title":"Patties","description":"Separate the beef into 4 equal portions, or 8 if making double cheeseburgers (do it!). Gently roll each portion into balls then press down into round patties that are slightly larger than your bun to allow for shrinkage (12 cm / 4.7\" wide, 1 cm / 0.4\" thick for a 10cm / 4\" burger bun).","images":[],"step":1},{"title":"Prepare","description":"Get all your burger bits and pieces out and ready to use. Don''t salt your beef until just before cooking (it toughens the meat).","images":[],"step":2},{"title":"Toast buns","description":"Preheat the grill to high. Place the bread cut face up on a tray and toast for 3 to 5 minutes until light golden. (If using BBQ, place cut face down on the grill). Set aside.","duration":4,"images":[],"step":3},{"title":"Dent patty","description":"Sprinkle one side of patties with half the salt and pepper. Flip, then press a dent into the middle of each patty. (Prevents patties doming when cooking and reduces shrinkage!). Sprinkle this dented side with the remaining salt and pepper.","images":[],"step":4},{"description":"Preheat 1 tablespoon oil in a large cast iron skillet over high heat until very hot - smoking hot! (Note 6)","images":[],"step":5},{"title":"Cook","description":"Cook 2 to 4 patties (whatever fits in the pan) for 1 1/2 minutes. Press down lightly with a spatula (not too hard else the meat juices squeeze out!). Flip, then immediately top with a slice of cheese. Cook for another 1 1/2 minutes (cheese will melt by itself!) then transfer burgers to a tray to rest for 3 minutes.","duration":3,"images":[],"step":6},{"title":"Preheat","description":"If your BBQ hot plate/grill is well seasoned (ie oiled), there is no need to oil before cooking. If not, lightly brush with vegetable or canola oil (or use scrunched up paper towel). Then preheat your BBQ on high until very hot and you see wisps of smoke.","images":[],"step":7},{"description":"Cook the burgers per above directions for 1 1/2 minutes on each side, topping with cheese as soon as you flip, then resting for 3 minutes. (You can also toast the buns on the grill (face down on the grills, 2 - 3 minutes.)","duration":3,"images":[],"step":8},{"description":"Slather the base of the bun with your sauce of choice. My order of assembly: lettuce, tomato, burger (x 2 for double!), gherkins, onion, sauce on bun lid, jam it on top of the stack.","images":[],"step":9},{"description":"DEVOUR with French Fries on the side.","images":[],"step":10}]', '["milk","mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-mince-recipes","burger-recipes","dinner-tonight","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e6728afe4931', 'en', 'US', 'Beef & Lentil Soup with vegetables', 'Recipe video above. Here''s a different way to use beef mince - a hearty Beef & Lentil Soup loaded with vegetables! Flavoured with spices and low on effort thanks to the ground beef, lentil soups can be so boring - but not this one. :)Healthy, hearty, economical - it''s a complete dinner made in one pot. 100% perfect for freezing, use any veg you want and switch up the spicing to your taste!', 'https://www.recipetineats.com/tachyon/2020/11/Beef-and-Lentil-Soup_9.jpg', 10, 30, 40, 6, '[{"id": "ing_moroccan_spice_mix", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 37.5, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_lentils", "quantity": {"value": 0.469, "unit": "can of 400g"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_green_beans", "quantity": {"value": 100.0, "unit": "pack"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.75, "unit": "bunch"}}]', '[{"ingredients":["2 1/2 tbsp Moroccan spice mix (store-bought)","1 tsp allspice (mixed spice will work too)","2 tsp cumin powder","2 tsp paprika","3/4 tsp black pepper","1/2 tsp salt (Note 2)"],"purpose":"My Moroccan Spice Mix (or change it up! Note 1):"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, finely chopped)","1 onion (, finely chopped (brown, white, or yellow))","500g / 1lb beef mince (ground beef) (I use lean)","1 1/4 cups dried lentils (or 2 cans, drained, Note 3)","2 carrots (*, cut into 1cm / 1/3” dice)","2 celery stalks (*, chopped into 1cm / 1/3”pieces)","2 zucchinis (*(small, or 1 large), cut into 1cm / 1/3” dice)","100g / 4 oz green beans (*, trimmed, cut into 1.5cm / 1/2” pieces)","800g / 28 oz crushed canned tomato","4 cups / 1 litre beef stock (, low sodium (Note 4))","3 cups water"],"purpose":"Soup:"},{"ingredients":["Yogurt (plain or Greek)","1/4 cup Coriander/cilantro leaves, or sliced green onions"],"purpose":"Serving:"}]', '[{"description":"Mix spices in a small bowl.","images":[],"step":1},{"title":"Saute onion & garlic","description":"Heat oil in a large pot over medium high heat. Cook onion and garlic for 3 minutes until golden on the edges.","duration":3,"images":[],"step":2},{"title":"Brown & spice beef","description":"Turn heat up to high, add beef and cook until it''s no longer red, breaking it up as you go. Add 2 tablespoons of the Spice Mix and cook it for a further 2 minutes - it will smell so good!","images":[],"step":3},{"title":"Carrot & celery","description":"Add carrot and celery, then stir for 1 minute. (If using your own veg mix, add the veg in this step that will hold up to full 25 min simmer time)","duration":1,"images":[],"step":4},{"title":"Make broth","description":"Add water, beef stock, canned tomato, lentils and remaining Spice Mix too. Give it a stir, bring to simmer, then place lid on and reduce to medium low so it''s simmering gently. Lentils will take 25 - 30 minutes to cook until soft. Very old lentils can take 5 - 10 minutes longer.","images":[],"step":5},{"description":"Simmer 15 minutes then add zucchini & green beans.","images":[],"step":6},{"description":"Simmer 10 minutes longer or until lentils are soft (ie. 25 minutes total).","images":[],"step":7},{"description":"Serve! Taste and add more salt if desired. Ladle into bowls and serve with yogurt and coriander.","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Any flavour you want!","Western"],"categories":["beef-mince-recipes","beef-recipes","dietary","gluten-free-recipes","one-pot-recipes","quick-and-easy","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3a0f4afca90a', 'en', 'US', 'One Pot Pasta Bolognese', 'Recipe video above. For One-Pot-Pasta Cynics (and Italian cooking pursists), there''s a special message for you at the top of the post! :)This recipe is everything you love about Spaghetti Bolognese - the rich, thick tomato sauce, full flavoured (never bland!), made from scratch WITH the pasta in one pot! Excellent big batch cooking, keeps well. Tomato passata (aka tomato puree) is the key here for an instant thick, rich sauce rather than cooking down crushed tomato.Pasta types - long, short or tiny, but read recipe note 4 for adjustments.', 'https://www.recipetineats.com/tachyon/2020/09/One-Pot-Pasta-Bolognese_6.jpg', 10, 20, 30, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_italian_mixed_herbs", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.25, "unit": "jar of 50g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.25, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped)","500g / 1 lb beef mince (ground beef) (, I use lean)","700g / 24.5 oz tomato passata (tomato puree) (Note 1)","3 cups beef broth (or stock cubes + water, Note 2)","2 tsp Italian mixed herbs (options, see Note 3)","1/4 - 1/2 tsp chilli flakes (red pepper flakes) (, adjust to taste)","2 tsp Worcestershire Sauce","2 tbsp tomato paste","3/4 tsp each salt and pepper","350g / 12 oz spaghetti (, uncooked (other pasta - Note 4))"]},{"ingredients":["Parmesan"],"purpose":"For serving"}]', '[{"title":"Saute onion & garlic","description":"Heat oil in a large pot over high heat. Cook garlic and onion for 2 minutes until translucent.","duration":2,"images":[],"step":1},{"title":"Cook beef","description":"Add beef and cook, breaking it up as you go.","images":[],"step":2},{"title":"Add tomato","description":"Once beef has all changed from red to brown, add tomato passata.","images":[],"step":3},{"title":"Rinse out bottle","description":"Pour some beef stock into the empty bottle, shake, then pour into the pot.","images":[],"step":4},{"title":"Add everything else","description":"Add remaining beef stock and all remaining ingredients except spaghetti. Give it a good stir, then let it come up to the boil.","images":[],"step":5},{"title":"Add spaghetti","description":"Add pasta, fanning it out around the pot. Leave for 30 seconds to start softening, then start pushing it in under the liquid.","duration":0.5,"images":[],"step":6},{"title":"Cook pasta","description":"Once fully submerged, cook for 12 minutes, stirring every minute or so, and more towards the end. At about the 8 minute mark, lower the heat to medium otherwise the base might catch (but ensure it is still bubbling gently - you don''t want pasta just bloating in warm water).","duration":12,"images":[],"step":7},{"title":"Remove from stove, toss well","description":"Take it off the stove once the pasta is JUST cooked, the tiniest bit firmer than you want, and when still saucy. Toss it for about 30 seconds or so - the sauce will reduce further, the pasta will finish cooking.","images":[],"step":8},{"description":"Serve immediately, garnished with parmesan.","images":[],"step":9}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian-esque","Western"],"categories":["beef-mince-recipes","beef-recipes","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e42c79327ae1', 'en', 'US', 'Meatloaf recipe', 'Recipe video above. Meatloaf is so much more than a giant hunk of ground beef in a loaf shape. It should ooze with flavour, be moist and tender yet not crumble apart when sliced. And the caramelised glaze is the crowning glory!', 'https://www.recipetineats.com/tachyon/2019/10/Meatloaf_3a.jpg', 15, 75, 90, 8, '[{"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_beef", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}]', '[{"ingredients":["1 cup panko breadcrumbs (Note 1)","1 large onion (, grated (brown, yellow))","1 kg / 2 lb ground beef (mince) (, preferably not lean)","2 eggs","3 garlic cloves (, minced)","1 tsp Worcestershire Sauce","1/4 cup tomato ketchup","1/4 cup chopped parsley ((optional), or 2 tsp dried parsley or basil)","1 tsp dried thyme","2 beef bouillon cubes (, crumbled or 2 tsp beef powder (Note 2))","1 tsp black pepper"]},{"ingredients":["1/2 cup tomato ketchup","2 tbsp cider vinegar","1 tbsp brown sugar (, lightly packed)"],"purpose":"Meatloaf Glaze:"}]', '[{"description":"Preheat oven to 180C/350F. Oil or spray a loaf tin. (Note 3)","images":[],"step":1},{"title":"Glaze","description":"Mix together in a small bowl. Set aside.","images":[],"step":2},{"title":"Meatloaf","description":"Place breadcrumbs in a very large bowl. Grate over onion. Mix so the breadcrumbs are all wet. (Note 4)","images":[],"step":3},{"description":"Add remaining ingredients. Mix well using your hands. Form into a loaf shape, pinching together then smoothing over creases and cracks (helps prevent cracks during baking).","images":[],"step":4},{"description":"Transfer into loaf tin. Brush generously with glaze, using about 1/2.","images":[],"step":5},{"description":"Bake for 45 minutes. Remove from oven and brush with most of the remaining glaze. If there is excess fat pooling, scoop/pour it off.","duration":45,"images":[],"step":6},{"description":"Bake for a further 30 minutes. Remove from oven.","images":[],"step":7},{"description":"Stand for 10 minutes before turning out and cutting into thick slices. You will probably get a bit of crumbling just on the edges of the first couple of slices, this is normal and indicative of the tenderness of the meatloaf (zero crumble indicates firm packed harder meatloaf which isn''t as enjoyable!).","duration":10,"images":[],"step":8},{"description":"Ideal served with a dollop of ketchup, creamy mashed potatoes and steamed vegetables.","images":[],"step":9}]', '["egg"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-mince-recipes","beef-recipes","main-dishes","nagis-picks","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b632459db6e4', 'en', 'US', 'Cottage Pie', 'Recipe video above. One of the greatest comfort foods of all time! A ground beef (mince) filling in a tasty gravy, topped with mashed potato. Make it a Shepherd''s Pie simply by swapping the beef for lamb.', 'https://www.recipetineats.com/tachyon/2016/10/Cottage-Pie_5.jpg', 15, 75, 90, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_beef", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 1.2, "unit": "bag of 2kg"}}, {"id": "ing_milk", "quantity": {"value": 0.167, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}]', '[{"ingredients":["1 1/2 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped)","1 carrot (, finely chopped*)","1 celery (, finely chopped*)","750g / 1.5 lb beef mince (ground beef)","1/4 cup (40g) flour (plain / all purpose)","1/4 cup (55g) tomato paste","2 cups (500 ml) beef stock / broth (, low sodium)","1/2 cup (125 ml) red wine (or water)","1 beef bouillon cube (, crumbled (stock cube, or 1 tsp stock powder))","2 tbsp Worcestershire sauce","1 tsp dried thyme (or 3 sprigs fresh thyme)","2 dried bay leaves","3/4 tsp salt","1/2 tsp black pepper"]},{"ingredients":["1.2 kg / 2.5 lb potatoes (, peeled and cut into 2.5cm / 1\" cubes)","2/3 cup (165 ml) milk (, warmed)","2 tbsp (30g) butter"],"purpose":"Topping"},{"ingredients":["2 tbsp (30g) butter","2 tbsp (20g) parmesan, grated"],"purpose":"Parmesan Crust (optional)"}]', '[{"description":"Heat oil in a large skillet over medium high heat. Add onion and garlic, cook for 1 minute. Then add carrots and celery. Cook for 3 minutes or until softened and sweet.","duration":1,"images":[],"step":1},{"description":"Turn heat up to high. Add beef and cook, breaking it up as you go, until browned.","images":[],"step":2},{"description":"Add flour and mix in. Add tomato paste, broth, red wine, bouillon cube, Worcestershire sauce, thyme, bay leaves, salt and pepper.","images":[],"step":3},{"description":"Bring to simmer, then turn down heat so it is simmering rapidly - I have it on medium high. Cook for 30 minutes, stirring occasionally, until it reduces down to a gravy consistency (Note 1) (see video). Taste then add more salt if desired.","duration":30,"images":[],"step":4},{"description":"Transfer to 6 cup pie dish (1.5 litre / quart). Cover, cool if you have time (even overnight). Cool filling = easier to top with mash (Note 2)","images":[],"step":5},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":6},{"description":"Cook potatoes in boiling water for 15 minutes or until soft. Drain then return to pot on turned off stove. Shake briefly and allow to steam dry for 30 seconds or so (Note 3).","duration":15,"images":[],"step":7},{"description":"Add butter and mash until melted, then add milk and salt. Mash until smooth.","images":[],"step":8},{"description":"Spread onto pie, use a fork to rough up the surface (rougher surface = more golden bits). Sprinkle with paremsan, drizzle with butter (or skip this and just drizzle with olive oil)","images":[],"step":9},{"title":"Bake for 25","description":"30 minutes or until golden on top and bubbling on the edges. Stick a knife into the middle to ensure it is piping hot.","duration":27.5,"images":[],"step":10},{"description":"Stand for 5 minutes before serving, garnished with fresh thyme leaves if desired.","duration":5,"images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["English","South Western"],"categories":["beef-mince-recipes","beef-recipes","lamb-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a1a938a59fa0', 'en', 'US', 'Swedish Meatballs (homemade Ikea Meatballs)', 'Recipe video above. Juicy meatballs smothered in a beautiful creamy gravy, with a hint of spicing that Swedish Meatballs are known for. Made extra soft and extra tasty by soaking fresh bread in grated onion - tried and tested technique used in my most of my meatball recipes, highly approved by readers! (See Italian Meatball reviews as an example)', 'https://www.recipetineats.com/tachyon/2017/01/Swedish-Meatballs_8.jpg', 20, 30, 50, 5, '[{"id": "ing_bread", "quantity": {"value": 0.1, "unit": "loaf"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_pork", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_round_nutmeg", "quantity": {"value": 300.0, "unit": "jar"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}]', '[{"ingredients":["2 slices white sandwich bread (, crusts removed, chopped into small cubes (Note 1))","1 onion (, small (brown, white or yellow))","300g / 10 oz ground beef (mince)","300g / 10 oz ground pork (mince) (, or sub with more beef (Note 2))","1 egg","1/4 tsp ground nutmeg (, preferably freshly grated)","1/4 tsp All Spice powder (Note 3)","1/4 tsp black pepper","3/4 tsp salt","1 tbsp oil"],"purpose":"Meatballs"},{"ingredients":["40g / 3 tbsp butter (, unsalted)","3 tbsp flour","2 cups beef broth/stock ((salt reduced), or sub with chicken)","1/2 cup heavy / thickened cream (Note 4)"],"purpose":"Gravy"}]', '[{"description":"Grate onion using a standard box grater (see video).","images":[],"step":1},{"description":"Scrape onion and juices into bowl. Add bread and mix well - onion juice should make bread soggy (if not, add a tiny splash of milk). Set aside to soak for 1 minute.","duration":1,"images":[],"step":2},{"description":"Add remaining Meatball ingredients EXCEPT oil. Mix well.","images":[],"step":3},{"description":"Using a tablespoon measure and measure out a heaped tablespoon (or use ice cream scooper which is what I do), dollop on work surface. Repeat with remaining mixture: 25 - 30 meatballs. Then roll into shape.","images":[],"step":4},{"description":"Cooking","images":[],"step":5},{"description":"Heat 1 tbsp oil in a skillet over medium high heat. Add half the meatballs and brown all over (but raw inside still) - about 3 minutes. Remove onto plate, then brown the remaining batch.","images":[],"step":6},{"description":"If there is lots of oil, pour off excess and discard. Lower heat to medium.","images":[],"step":7},{"description":"Add butter into skillet and melt. Add flour and stir in. Cook for 1 minute.","duration":1,"images":[],"step":8},{"title":"While mixing, add about 1/4 of the beef broth","description":"it will thicken quickly. Then gradually add remaining beef broth, stirring as you go. Switch to whisk if required to make it lump free.","images":[],"step":9},{"description":"When the liquid is simmering, add meatball and juices pooled on plate.","images":[],"step":10},{"description":"Turn up heat slightly to keep it at a rapid simmer. Cook for 8 - 10 minutes or until the liquid thickens into a thin gravy, stirring occasionally.","duration":9,"images":[],"step":11},{"description":"Add cream, simmer for a further 2 minutes then remove from stove.","images":[],"step":12},{"description":"Serve over mashed potato (or Cauliflower Mash for low carb). For a truly authentic experience, add a dollop of ligonberry jam on the side!","images":[],"step":13}]', '["egg","gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["swedish"],"categories":["beef-mince-recipes","beef-recipes","meatball-recipes","mediterranean-recipes","pork-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c23684436d63', 'en', 'US', 'Baked Ziti', 'Recipe video above. A big, juicy pasta bake! It’s meaty, cheesy, and loaded with flavour from a healthy dose of seasonings. This great American classic may well be the mother of all pasta bakes....', 'https://www.recipetineats.com/tachyon/2018/10/Baked-Ziti_0.jpg', 10, 60, 70, 6, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_ricotta", "quantity": {"value": 0.6, "unit": "tub of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.5, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}]', '[{"ingredients":["300g / 10oz ziti or penne pasta ( (Note 1))","1 tbsp olive oil","3 garlic cloves (, minced)","1 small onion ((brown, white or yellow), finely chopped)","500g / 1 lb ground beef or pork (OR 50/50 combo (Note 2))","700g / 24 oz tomato passata (pureed tomato, Note 3)","1/2 cup water","1 tsp EACH dried basil, oregano, sugar","1 cup ricotta (, optional (Note 4))","1 cup grated mozzarella cheese (or other melting cheese)","1 cup parmesan (, freshly grated (optional))","Finely chopped parsley or basil (optional garnish)"]},{"ingredients":["2 tsp fennel seeds (optional, Note 5)","1 tbsp paprika (plain or sweet)","1/4 tsp cayenne pepper OR 3/4 tsp chilli flakes (adjust to taste)","2 tsp onion powder","1 tsp EACH salt and black pepper"],"purpose":"Seasonings:"}]', '[{"description":"Cook ziti for the recommended cooking time on the packet MINUS 2 minutes. (Note 5) Drain, then return to pot.","images":[],"step":1},{"description":"Preheat oven to 180C/350F.","images":[],"step":2},{"title":"Make Sauce","description":"Heat oil in a large skillet over high heat. Add onion and garlic and cook for 2 minutes or until onion is translucent.","duration":2,"images":[],"step":3},{"description":"Add meat and cook, breaking it up as you go. When it is just cooked, add Seasonings and cook for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Add passata, water, basil, oregano and sugar. Bring to simmer, reduce heat to low and cook for 10 minutes. Adjust salt and pepper to taste (remember it gets spread across lots of pasta).","duration":10,"images":[],"step":5},{"title":"Toss Ziti with Sauce","description":"Pour about 2 cups of sauce into the pot with the ziti. Toss.","images":[],"step":6},{"title":"Assemble","description":"Spread ziti into baking dish (23x33cm / 9x13\"). Dollop with ricotta. Pour over remaining sauce. Top with cheese and parmesan.","images":[],"step":7},{"title":"Bake","description":"Cover loosely with foil. Bake 20 minutes. Remove foil, bake further 10 to 15 minutes until cheese is golden.","images":[],"step":8},{"title":"Serve","description":"Sprinkle with parsley or basil if desired, then serve!","images":[],"step":9}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["American","Western"],"categories":["beef-mince-recipes","beef-recipes","casseroles-and-cosy-bakes","dinner-tonight","italian-recipes","main-dishes","most-popular","pasta-bakes","pasta-recipes","pork-recipes","quick-and-easy","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_52381cf58f4e', 'en', 'US', 'Spaghetti Bolognese', 'Recipe video above. My everyday Bolognese recipe I make over and over again. This Meat Sauce has terrific depth of flavour for such a quick recipe - though if you have the time, it''s stellar cooked slowly for a couple of hours. My 3 "secret" tips are: Worcestershire Sauce, Beef Bouillon Cubes and a touch of sugar.', 'https://www.recipetineats.com/tachyon/2018/07/Spaghetti-Bolognese.jpg', 10, 30, 40, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.8, "unit": "pack of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["1 1/2 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped (brown, yellow or white))","1 lb / 500g beef mince (ground beef) (OR half pork, half beef (Note 1))","1/2 cup (125 ml) dry red wine (sub water or beef broth/stock)","2 beef bouillon cubes (, crumbled OR granulated beef bouillon (Note 2))","800g / 28 oz can crushed tomato (or tomato passata)","2 tbsp tomato paste","2 tsp white sugar (, if needed (Note 3))","2 tsp Worcestershire sauce","2 dried bay leaves","2 sprigs fresh thyme (or 1/2 tsp dried thyme or oregano)","3/4 tsp cooking salt (kosher salt)","1/2 tsp black pepper"]},{"ingredients":["400 g / 13 oz spaghetti (, dried)","Parmesan cheese (and finely chopped parsley (optional))"],"purpose":"To Serve"}]', '[{"title":"Sauté","description":"Heat oil in a large pot or deep skillet over medium high heat. Add onion and garlic, cook for 3 minutes or until light golden and softened.","duration":3,"images":[],"step":1},{"title":"Cook beef","description":"Turn heat up to high and add beef. Cook, breaking it up as your go, until browned.","images":[],"step":2},{"title":"Reduce wine","description":"Add red wine. Bring to simmer and cook for 1 minute, scraping the bottom of the pot, until the alcohol smell is gone.","duration":1,"images":[],"step":3},{"title":"Simmer","description":"Add the remaining ingredients. Stir, bring to a simmer then turn down to medium so it bubbles gently. Cook for 20 - 30 minutes (no lid), adding water if the sauce gets too thick for your taste. Stir occasionally.","duration":25,"images":[],"step":4},{"title":"Slow simmer option","description":"really takes this to another level, if you have the time! Add 3/4 cup of water, cover with lid and simmer on very low for 2 - 2.5 hours, stirring every 30 minutes or so. (Note 5) Uncover, simmer 20 minutes to thicken sauce. (Note 6 for slow cooker)","images":[],"step":5},{"description":"Taste and add more salt it desired. Serve over spaghetti - though if you have the time, I recommend tossing the sauce and pasta per steps below.","images":[],"step":6},{"description":"Tossing Sauce and Spaghetti (optional, Note 4)","images":[],"step":7},{"description":"Bring a large pot of salted water to boil. Add pasta and cook per packet directions MINUS 1 minute.","images":[],"step":8},{"description":"Scoop out a mug of pasta cooking water and set aside, then drain the pasta.","images":[],"step":9},{"description":"Add pasta into the bolognese sauce with about 1/2 cup (125 ml) of reserved pasta water over medium heat. Toss gently for 1 1/2 - 2 minutes, or until the spaghetti turns red and the sauce thickens.","images":[],"step":10},{"description":"Divide between bowls. Garnish with parmesan and parsley if desired.","images":[],"step":11}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["beef-mince-recipes","beef-recipes","dinner-tonight","italian-recipes","main-dishes","pasta-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fa5b824fb3d6', 'en', 'US', 'Spinach Beef Cannelloni (Manicotti)', 'Recipe video above. You will love how flavourful the juicy beef filling and sauce is! Too many recipes disappoint by using plain canned tomato - the sauce needs flavour! It will seem like there''s a lot of sauce (and there is) and that it''s too thin (and it is!) BUT you need it because the cannelloni sucks up a lot when it''s cooking!!! Serves 4 very hungry people, 5 normal people.', 'https://www.recipetineats.com/tachyon/2019/11/Beef-Cannelloni_8.jpg', 30, 45, 75, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chilli", "quantity": {"value": 0.013, "unit": "pack of 100g"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_spinach", "quantity": {"value": 250.0, "unit": "bag of 250g"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_nelloni_tubes", "quantity": {"value": 21.0, "unit": "unit"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.6, "unit": "pack of 125g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1/2 onion (, finely chopped)","1 carrot (, small, finely chopped (optional))","1 celery rib (, finely chopped (optional))","800g / 28oz crushed tomato (, canned)","2 cups (500ml) chicken stock / broth (, low sodium (or vegetable))","1/2 tsp EACH thyme, oregano, salt, pepper","1/4 tsp chilli flakes (, optional)"],"purpose":"Cannelloni Sauce:"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1/2 onion (, finely chopped)","500g / 1lb beef mince (, lean)","250g / 8oz frozen spinach, chopped (, thawed, excess liquid squeezed out (Note 1))","1 beef bouillon cube (, crumbled (Note 2))","1/2 tsp pepper","1 tsp Worcestershire Sauce"],"purpose":"Spinach Beef Filling:"},{"ingredients":["21 - 24 cannelloni tubes (220g/7oz) (OR 10 Manicotti tubes (Note 3))","2 cups mozzarella cheese (, freshly grated (or other melting cheese))","Chopped parsley (, garnish (optional))"],"purpose":"Cannelloni:"}]', '[{"description":"Cannelloni Sauce:","images":[],"step":1},{"description":"Heat oil in a large saucepan or pot over medium high heat. Add garlic and onion, cook 2 minutes. Add carrot and celery, cook 5 minutes.","images":[],"step":2},{"description":"Add remaining Sauce ingredients then stir. Bring to simmer, lower heat to medium, cover with lid and simmer for 10 minutes.","duration":10,"images":[],"step":3},{"description":"Use a stick blender to blitz until smooth (or cool slightly and use blender or food processor). Set aside.","images":[],"step":4},{"description":"Spinach Beef Filling:","images":[],"step":5},{"description":"Heat oil in a large skillet over high heat. Add onion and garlic, cook 2 minutes.","images":[],"step":6},{"description":"Add beef and cook, breaking it up as you go, until it all changes from red to brown.","images":[],"step":7},{"description":"Stir in spinach, then add crumbled beef cube, Worcestershire sauce, pepper and 1 cup of Cannelloni Sauce. Stir, cook 2 minutes.","images":[],"step":8},{"description":"Remove and cool slightly.","images":[],"step":9},{"description":"Assembly and Baking:","images":[],"step":10},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":11},{"description":"Transfer Beef Filling into a piping bag with a wide nozzle. Stand cannelloni tubes upright in a container, then pipe filling in. (Or do this step with teaspoon/finger/dinner knife!).","images":[],"step":12},{"description":"Spread about 1 1/4 cups Sauce in a 23x33cm / 9x13\" dish. Lay the cannelloni on top, then pour over remaining Sauce.","images":[],"step":13},{"description":"Sprinkle with cheese, loosely cover with foil.","images":[],"step":14},{"description":"Bake 25 minutes, remove foil then bake a further 10 minutes until the cheese is bubbly with some golden spots.","images":[],"step":15},{"description":"Remove from oven, sprinkle with parsley if using then serve!","images":[],"step":16}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["American-Italian","Italian","Western"],"categories":["beef-mince-recipes","beef-recipes","italian-recipes","pasta-bakes","pasta-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a0e55a1c3079', 'en', 'US', 'One Pot Chili Mac and Cheese', 'Recipe video above. A homemade Chili with the addition of macaroni and cheese = Chili Mac ‘n Cheese! This is terrifically moorish and a fabulous one pot meal. Super quick too! The key with this recipe is to turn the stove off as soon as the pasta is just cooked - it will keep cooking in the residual heat. Spice level with 1/2 tsp cayenne pepper = warm hum. Dial up or down as you please!', 'https://www.recipetineats.com/tachyon/2017/10/Chilli-Mac_0.jpg', 10, 15, 25, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_kidney_beans", "quantity": {"value": 1.05, "unit": "can of 400g"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped)","1 red capsicum / bell pepper (, chopped)","500g / 1 lb ground beef (mince) (, I use lean)","800g / 28 oz crushed canned tomato","420g / 14 oz can red kidney beans (, drained)","2 1/2 cups (625 ml) beef broth (chicken broth also ok)","250g / 8 oz elbow macaroni pasta ((elbow pasta), uncooked)","2 cups (200g) shredded cheese (cheddar, Monterey Jack, tasty cheese)","1/4 cup coriander / cilantro ( finely chopped, for garnish)"]},{"ingredients":["1/2 tsp cayenne pepper ( or pure chilli powder (adjust spiciness to taste) (Note 1))","2 tsp paprika powder","2 tsp cumin powder","1 1/2 tsp onion powder (can sub garlic powder)","1 tsp dried oregano","1/2 tsp black pepper","1 1/4 tsp salt"],"purpose":"Spices (Homemade Chili Powder):"}]', '[{"description":"Heat oil in large pot over high heat. Add garlic and onion, cook for 1 minute. Then add capsicum and cook until onion is translucent.","duration":1,"images":[],"step":1},{"description":"Add beef and cook, breaking it up as you go.","images":[],"step":2},{"description":"Once the beef turns from red to brown, add remaining ingredients except cheese. Stir, bring to simmer, then turn the heat down to medium.","images":[],"step":3},{"description":"Cover and cook for 12 minutes or until the macaroni is al dente, meaning just cooked, still a tiny bit on the firm side. It should be saucy but not tons of liquid (see video).","duration":12,"images":[],"step":4},{"description":"Turn the stove OFF but leave the pot on the stove. Stir through half the cheese – it should be a bit saucy. Adjust salt and pepper to taste. Top with remaining cheese, put the lid back on and leave until the cheese melts - about 2 minutes (sauce will absorb further during this period).","images":[],"step":5},{"description":"Sprinkle with coriander, if desired, and serve immediately.","images":[],"step":6}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["American"],"categories":["beef-mince-recipes","beef-recipes","casseroles-and-cosy-bakes","dinner-tonight","main-dishes","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e28f756a4177', 'en', 'US', 'Mexican Ground Beef Casserole with Rice (Beef mince!)', 'Recipe video above. A big juicy pot of beef and rice loaded with Mexican flavours! The rice is tender and perfectly cooked, and the tomato sauce is generously flavoured with a Mexican Spice mix. A quick dinner made in one pot with not much prep!', 'https://www.recipetineats.com/tachyon/2019/09/Mexican-Ground-Beef-Casserole-with-Rice_0.jpg', 10, 20, 30, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 150.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.375, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_black_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}]', '[{"ingredients":["2 tbsp olive oil","1 onion (, finely chopped)","3 garlic cloves (, minced)","500g (1 lb) ground beef ((mince), lean)","1/3 cup tomato paste","1 1/4 cup long grain white rice (, uncooked (Note 1))","2.5 cups (625 ml) chicken broth/stock (, low sodium)","400g (14oz) can corn kernels (, drained (Note 2))","400g (14oz) can black beans (, drained (or other beans))","1 capsicum/bell pepper (, diced)","1 cup green onions/shallots","2 cups (200g) cheese (, shredded (anything that melts! Note 3))"]},{"ingredients":["0.5 tsp cayenne pepper (Note 4)","1.5 tbsp dried oregano","3 tsp cumin","3 tsp coriander","3 tsp onion powder","2 tsp paprika","1.5 tsp salt"],"purpose":"MEXICAN SPICES:"}]', '[{"description":"Heat oil in a large pot over high heat. Add garlic and onion, cook 1 1/2 minutes until onion is translucent.","images":[],"step":1},{"description":"Add beef and cook, breaking it up as you go, until you no longer see raw meat (about 2 minutes).","images":[],"step":2},{"description":"Add Mexican Spices and cook for 30 seconds.","duration":0.5,"images":[],"step":3},{"description":"Add capsicum and cook for 1 minute.","duration":1,"images":[],"step":4},{"description":"Add tomato paste and broth, stir to mix in.","images":[],"step":5},{"description":"Add rice, corn and black beans.","images":[],"step":6},{"description":"Stir, bring to simmer then cover and lower heat to medium low (simmering gently). Cook 15 minutes.","images":[],"step":7},{"description":"Remove lid, quickly stir through green onion and HALF the cheese.","images":[],"step":8},{"description":"Smooth top then sprinkle on remaining cheese. Cover and leave for 1 minute just to melt cheese.","duration":1,"images":[],"step":9},{"description":"Remove from stove and serve immediately, garnished with more green onion if desired.","images":[],"step":10}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Tex-Mex","Western"],"categories":["beef-mince-recipes","beef-recipes","casseroles-and-cosy-bakes","dinner-tonight","mexican-recipes","one-pot-recipes","quick-and-easy","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c1b7bdfa33cd', 'en', 'US', 'Beef Enchiladas', 'Recipe video above. Moreishly delish! These beef enchiladas are made extra tasty with a juicy filling made with beef, refried beans and a homemade Enchilada spice mix. The refried beans are excellent here - fills it out, makes the Filling juicy and adds flavour!', 'https://www.recipetineats.com/tachyon/2016/06/Beef-Enchiladas_main.jpg', 10, 35, 45, 4, '[{"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.5, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.5, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_refried_beans", "quantity": {"value": 400.0, "unit": "pack"}}, {"id": "ing_black_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_tortillas", "quantity": {"value": 8.0, "unit": "pack of 8"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 tsp each onion & garlic powder (Note 1)","1 tbsp each cumin powder, paprika and dried oregano","1/2 - 1 tsp cayenne pepper (optional, spiciness)"],"purpose":"Spice Mix"},{"ingredients":["2 tbsp olive oil","3 tbsp flour (, plain/all purpose)","2 cups (500ml) chicken stock / broth (, low sodium)","1 1/2 cups (375 ml) tomato passata OR US 1 can (8 oz) canned tomato sauce (eg Hunts) (Note 2)","1/4 tsp each salt and pepper"],"purpose":"Enchilada Sauce"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped (~1 cup))","1 lb / 500g ground beef (mince)","400g / 14oz refried beans (1 can, I use Old El Paso)","400g / 14oz black beans, drained (1 can, Note 3)"],"purpose":"Beef"},{"ingredients":["8 tortillas (or burrito wraps)","1.5 cups (150g) grated melting cheese, or more (I like Monterey Jack, tasty or cheddar cheese)","Cilantro/coriander leaves (, roughly chopped (optional garnish))"],"purpose":"Enchiladas"}]', '[{"description":"Mix together Spice Mix ingredients. Set aside.","images":[],"step":1},{"description":"Enchilada Sauce","images":[],"step":2},{"description":"Heat oil in a large saucepan over medium heat. Add flour and mix to combine into a paste. Cook for 1 minute, stirring constantly.","duration":1,"images":[],"step":3},{"description":"Add 1/2 cup chicken broth, whisk straight away then it will turn into a thick smooth paste quite quickly.","images":[],"step":4},{"description":"Add remaining chicken broth, passata, salt, pepper and 2 tablespoons of SPICE MIX. Whisk","images":[],"step":5},{"description":"Increase heat slightly to medium high. Cook for 3 to 5 minutes, whisking regularly, until the sauce thickens to the consistency of thick syrup (see video). Remove from stove.","duration":4,"images":[],"step":6},{"description":"Preheat oven to 180C/350F.","images":[],"step":7},{"description":"Heat oil in a skillet over high heat. Add garlic and onion, cook for 2 minutes.","duration":2,"images":[],"step":8},{"description":"Add beef and cook for 2 minutes, breaking it up as you go. Add remaining Spice Mix. Cook for a further 2 minutes or until completely brown.","duration":2,"images":[],"step":9},{"description":"Add refried beans, black beans, about 1/4 cup of Enchilada Sauce + salt & pepper. Mix (Note 4) and cook for 2 minutes then remove from stove (see video).","duration":2,"images":[],"step":10},{"description":"Smear a bit of Sauce on the bottom of a baking dish (stops sliding).","images":[],"step":11},{"description":"Place filling on the lower third of a tortilla. Roll up then place in the baking dish, seam side down. Repeat with remaining Filling & Tortillas.","images":[],"step":12},{"description":"Pour Sauce over the Enchiladas, top with cheese, bake for 10 minutes covered (Note 5) then 10 minutes uncovered. Serve hot!","duration":10,"images":[],"step":13}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["beef-mince-recipes","beef-recipes","dinner-tonight","enchiladas","main-dishes","mexican-recipes","most-popular","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1efdb2577c3a', 'en', 'US', 'Mexican Stuffed Peppers', 'Recipe video above. That moment when you cut into these Mexican Stuffed Peppers and the cheesy, flavour loaded juicy beef and rice filling comes oozing out.....THEN you find out it''s only 387 calories for a giant stuffed capsicum?? It''s a little food miracle, right there. 🙌🏼', 'https://www.recipetineats.com/tachyon/2019/08/Mexican-Stuffed-Peppers_3.jpg', 20, 90, 110, 5, '[{"id": "ing_capsicum", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 150.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_beef", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 75.0, "unit": "pack"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.2, "unit": "pack of 125g"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_guacamole", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["5 capsicum / peppers (, large about 12cm/4.5\" tall (Note 1))","1 tbsp olive oil","1 onion (, chopped (brown, white, yellow))","3 garlic cloves (, minced)","350g (12oz) ground beef ((mince), lean)","1/4 cup tomato paste","1 1/4 cups (315 ml) chicken broth/stock (, low sodium)","1/2 cup long or medium grain rice (, uncooked (Note 2))","1 cup corn kernels (Note 3)","1 cup green onions (, finely sliced (or red onion))","1 1/2 cups (150g) mozzarella (, shredded)","1/2 cup (125 ml) water"]},{"ingredients":["1/2 tsp cayenne pepper","1 tbsp dried oregano","2 tsp cumin","2 tsp coriander","1.5 tsp onion powder","3/4 tsp salt"],"purpose":"Mexican Spices:"},{"ingredients":["Guacamole (Note 5 Quick Guac)","Sour Cream","1 tbsp fresh coriander/cilantro (, finely chopped)"],"purpose":"For serving (optional):"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Hollow Peppers:","images":[],"step":2},{"description":"Using a small knife, cut around the top of the capsicum at downwards 45 degree angle. Remove top, empty seeds. If capsicum bottoms aren''t quite level, cut so they''ll sit flat. (Be careful to cut off as little as possible so you don'''' accidentally cut a hole in the bottom.)","images":[],"step":3},{"description":"Place capsicums in a baking dish that will fit them snugly (Note 4)","images":[],"step":4},{"description":"Heat oil in a large skillet over high heat,","images":[],"step":5},{"description":"Add onion and garlic, cook for 2 minutes.","duration":2,"images":[],"step":6},{"description":"Add beef and cook, breaking it up as you go, until it''s all changed from pink to brown.","images":[],"step":7},{"description":"Add Spices, stir through. Then add Tomato paste and cook for 1 minute.","duration":1,"images":[],"step":8},{"description":"Add rice, corn and chicken broth. Stir, bring to simmer, place lid on and lower heat to medium low.","images":[],"step":9},{"title":"Cook for 13","description":"15 minutes until rice is JUST cooked - mixture should be fairly loose still at this stage, not thick and stodgy (see video).","duration":14,"images":[],"step":10},{"description":"Stir in green onion.","images":[],"step":11},{"description":"Spoon half the filling into the prepared capsicums.","images":[],"step":12},{"description":"Top with half the cheese, then fill to top with remaining beef rice.","images":[],"step":13},{"description":"Place capsicum lids back on, pour 1/2 cup water into the pan.","images":[],"step":14},{"description":"Cover tightly with foil, bake 45 minutes.","images":[],"step":15},{"description":"Remove foil and capsicum lids. Top with remaining cheese. Bake further 5 to 10 minutes, just until cheese is melted.","images":[],"step":16},{"title":"Serve with sour cream and Guacamole! Quick Guac","description":"Note 5.","images":[],"step":17}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican","Western"],"categories":["beef-mince-recipes","dietary","low-calorie-recipes","mexican-recipes","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_84fd03d8fe70', 'en', 'US', 'Baked Spaghetti', 'Recipe video above. It''s your favourite Bolognese - in the form of a juicy pasta bake! Do a quick simmer - or go all out and slow cook for a couple of hours for a richer sauce and melt-in-your-mouth beef. **FREEZER BEAUTY!** Can even bake from frozen (see notes).', 'https://www.recipetineats.com/tachyon/2019/07/Baked-Spaghetti_1.jpg', 15, 90, 105, 10, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_beef", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.25, "unit": "bottle of 750ml"}}, {"id": "ing_beef", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_bay_leaf", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_cheese", "quantity": {"value": 8.0, "unit": "block of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.6, "unit": "pack of 125g"}}]', '[{"ingredients":["2 tbsp olive oil","3 garlic cloves (, minced)","1 onion (, finely chopped)","1 carrot (, finely diced (optional))","1 stick celery (, finely diced (optional))","750g / 1.5lb ground beef (mince)","3/4 cup (185ml) dry red wine (or sub with water or beef broth/stock)","3 beef bouillon cubes (, crumbled (Note 1))","1.2kg / 2.4 lb crushed tomato (, canned)","1/4 cup tomato paste","1 - 3 tsp white sugar (, if needed (Note 2))","2 tsp Worcestershire sauce","3 dried bay leaves","2 sprigs fresh thyme (or 1/2 tsp dried thyme or oregano)","Salt and pepper"],"purpose":"Bolognese Sauce:"},{"ingredients":["500g/ 1lb spaghetti","8 - 10 slices Swiss cheese ((or other type), enough for a layer)","2 cups (200g) mozzarella cheese, shredded"],"purpose":"Spaghetti Bake:"}]', '[{"description":"Heat oil in a large, heavy based pot over medium high heat.","images":[],"step":1},{"description":"Add garlic and onion, cook 2 minutes.","images":[],"step":2},{"description":"Add celery and carrot, cook 3 minutes.","images":[],"step":3},{"description":"Turn heat up to high, add beef and cook, breaking it up as you go.","images":[],"step":4},{"description":"Once beef is brown, add wine. Simmer rapidly for 2 minutes.","duration":2,"images":[],"step":5},{"description":"Add remaining Sauce ingredients, stir.","images":[],"step":6},{"description":"Bring to simmer, lower heat, cover with lid. Simmer for 45 minutes (minimum) or 1.5 - 2 hours (best!).","duration":45,"images":[],"step":7},{"title":"If liquid evaporates too much, add water","description":"should be saucy (see video/pics). Adjust salt and pepper to taste.","images":[],"step":8},{"description":"Assemble & Bake:","images":[],"step":9},{"description":"Preheat oven to 180C/350F.","images":[],"step":10},{"description":"Cook pasta per packet directions, minus 1 minute.","images":[],"step":11},{"description":"Drain, then return into pot.","images":[],"step":12},{"description":"Add just over half the Sauce, toss.","images":[],"step":13},{"description":"Spread half the pasta in a casserole pan, spread with half remaining Sauce.","images":[],"step":14},{"description":"Top with cheese slices, then remaining pasta, remaining Sauce, finish with mozzarella.","images":[],"step":15},{"description":"Cover loosely with foil (so cheese doesn''t stick), bake 25 minutes.","images":[],"step":16},{"description":"Remove foil (reserve), bake further 10 minutes than remove.","images":[],"step":17},{"title":"Cover loosely with foil, stand 10","description":"15 minutes. Then cut slices with a knife and use a spatula to serve pieces like lasagna!","images":[],"step":18}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-mince-recipes","casseroles-and-cosy-bakes","pasta-bakes","pasta-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_34a71665f297', 'en', 'US', 'Moussaka (Greek Eggplant Lasagna)', 'Recipe video above. A traditional recipe for an iconic Greek dish from a wonderful cookbook called The Food And Cooking Of Greece by Sara Nassopoulos. Layers of soft eggplant, rich beef or lamb filling lightly spiced with oregano and cinnamon, topped with a thick layer of bechamel sauce. It looks like a lot of steps but the recipe has a nice flow to it - I''ve popped prompts in the steps. 🙂', 'https://www.recipetineats.com/tachyon/2019/03/Greek-Moussaka_3-re-edited-SQ.jpg', 40, 30, 70, 6, '[{"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_lamb", "quantity": {"value": 0.635, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.635, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.635, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cinnamon", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_nutmeg", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.006, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 0.062, "unit": "loaf"}}]', '[{"ingredients":["1 kg / 2 lb eggplant (aubergines) (, 0.75cm / 0.3\" thick slices)","1 tsp salt","2 - 3 tbsp olive oil"],"purpose":"Eggplant"},{"ingredients":["1 tbsp olive oil","1 onion (, diced (brown, white, yellow))","3 garlic cloves (, minced)","1.4 lb / 700 g ground beef or lamb (mince) (Note 1)","1/2 cup red wine (, dry (optional))","14 oz /400g crushed tomatoes","3 tbsp tomato paste","1 cup beef broth/stock (Note 2)","1 beef bouillon cube (, crumbled (or 1 tsp powder))","2 bay leaves","1.5 tsp sugar (any)","2 tsp dried oregano","1/2 tsp cinnamon (or 1 stick, use whole)","3/4 tsp salt"],"purpose":"Filling"},{"ingredients":["4 tbsp (60g) butter","5 tbsp plain flour","2 1/2 cups milk (any fat %)","1/4 tsp nutmeg, freshly grated (optional)","1/2 cup parmesan cheese, grated (or Kefalotiri Cheese) (Note 3)","1 egg","1 egg yolk","1 1/4 tsp Vegeta, vegetable or chicken stock powder (or salt) (Note 4)","1/4 tsp pepper"],"purpose":"Bechamel Sauce"},{"ingredients":["1/3 cup panko breadcrumbs (Note 5)"],"purpose":"Topping"}]', '[{"description":"Eggplant (Note 6)","images":[],"step":1},{"description":"Place eggplant slightly overlapping in a large colander. Sprinkle with some salt. Repeat with remaining eggplant.","images":[],"step":2},{"description":"Leave to sweat for 30 minutes. Meanwhile, make Meat Sauce and Béchamel Sauce.","duration":30,"images":[],"step":3},{"description":"Preheat oven to 240C/450F.","images":[],"step":4},{"title":"Pat eggplant dry","description":"make sure to do this well, otherwise it''s too salty. Lay on parchment paper lined trays (you might need 3 trays, work in batches), brush with oil.","images":[],"step":5},{"title":"Bake 15","description":"20 minutes or until lightly browned and softened . Remove and set aside to cool slightly.","images":[],"step":6},{"description":"Heat olive oil in a large skillet or pot over high heat, then cook the garlic and onion for 2 minutes.","duration":2,"images":[],"step":7},{"description":"Add the beef or lamb and cook until it changes from pink to brown, breaking it up as you go.","images":[],"step":8},{"description":"Add wine, cook for 1.5 minutes or until alcohol smell is gone.","images":[],"step":9},{"description":"Add remaining ingredients and stir to combine. Bring to a simmer, then lower heat to medium low and cook for 15 minutes, or until reduced to a thick sauce.","duration":15,"images":[],"step":10},{"description":"Melt butter in a pan over medium heat. Add flour and cook for 1 minute, stirring constantly.","duration":1,"images":[],"step":11},{"description":"Stirring constantly, slowly add the milk. Then stir regularly for 3 to 5 minutes or until it thickens so that it thickly coats the back of a wooden spoon (see video / step photos).","duration":4,"images":[],"step":12},{"description":"Remove from the stove and whisk in cheese, nutmeg, Vegeta/stock powder (or salt) and pepper.","images":[],"step":13},{"description":"Allow to cool for 5 minutes, then whisk the eggs in. Cover with lid until required.","duration":5,"images":[],"step":14},{"description":"Lower oven to 180C/350F (all oven types).","images":[],"step":15},{"description":"Place half the eggplant in the bottom of a baking dish (I used my 26cm/9\" Lodge skillet), then top with all the Filling.","images":[],"step":16},{"description":"Top with remaining eggplant, then pour over the Béchamel Sauce, sprinkle with breadcrumbs.","images":[],"step":17},{"title":"Bake for 30","description":"40 minutes or until golden brown. Allow to stand for 10 minutes before serving.","duration":35,"images":[],"step":18}]', '["egg","gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["beef-mince-recipes","beef-recipes","casseroles-and-cosy-bakes","greek-recipes","mediterranean-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c9b653ea691c', 'en', 'US', 'Cheeseburger Casserole (Homemade Hamburger Helper)', 'Recipe video above. It''s beefy, cheesy and saucy. If you love Cheeseburgers and Mac and Cheese, then you will LOVE this Cheeseburger Casserole! A homemade version of Hamburger Helper, the boxed pasta. One pot, 30 minutes start to finish!', 'https://www.recipetineats.com/tachyon/2016/08/Cheeseburger-Casserole_Hamburger-Helper_0.jpg', 10, 20, 30, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.68, "unit": "pack of 500g"}}, {"id": "ing_corn", "quantity": {"value": 0.188, "unit": "can of 400g"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_hot_sauce", "quantity": {"value": 0.1, "unit": "bottle of 150ml"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1 onion, chopped","1 small carrot * (, chopped (optional))","1 celery stalk * (, chopped (optional))","500 g/ 1 lb ground beef (mince) (, preferably lean)","12 oz / 340g dried macaroni (, uncooked)","1/2 cup frozen corn * (, optional)","2 cups chicken broth/stock, low sodium","1 tbsp hot sauce or Sriracha sauce (, adjust to taste)","1 tsp American chili powder (Note 1)","1 tsp dried oregano","1 tsp garlic powder (, or sub onion powder)","800 g / 28 oz crushed tomato","2 tbsp tomato paste","1 1/4 tsp salt","1/2 tsp black pepper","1.5 - 2 cups (150 - 200g) cheddar or tasty cheese, shredded (Note 3)","1 cup (100g) mozzarella cheese (, for topping)"]},{"ingredients":["1 green onion (, sliced)"],"purpose":"Garnish (optional)"}]', '[{"description":"Heat oil in a dutch oven or large deep skillet over medium high heat.","images":[],"step":1},{"description":"Add onion and garlic, cook 1 minute.","images":[],"step":2},{"description":"Add celery and carrot, cook 3 minutes until soft.","images":[],"step":3},{"description":"Increase heat to high and add beef. Cook, breaking it up as you go, until no longer pink - 3 minutes.","images":[],"step":4},{"description":"Add remaining ingredients EXCEPT cheese. Stir to combine, add macaroni, then turn down to medium or medium low so it''s simmering gently.","images":[],"step":5},{"description":"Cover, cook 8 minutes. Pasta should be just about cooked, and still nice and saucy.","images":[],"step":6},{"description":"Add cheddar cheese, stir. Top with mozzarella cheese.","images":[],"step":7},{"description":"Cover with lid, cook for a further 2 minutes.","images":[],"step":8},{"title":"Remove from stove. The pasta should now be cooked","description":"tender but firm, not mushy, slick with sauce, not dried out.","images":[],"step":9},{"description":"Serve immediately, garnished with green onions, if using.","images":[],"step":10}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["American","Western"],"categories":["beef-mince-recipes","beef-recipes","casseroles-and-cosy-bakes","dinner-tonight","main-dishes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7d3ada56b5c4', 'en', 'US', 'Beef Burritos', 'Recipe video above. Simple, super tasty everyday beef burritos made with a homemade beef mince filling (ground beef), rice and your choice of fillings. One of the best freezer meals ever!', 'https://www.recipetineats.com/tachyon/2017/06/Beef-Burritos.jpg', 15, 20, 35, 6, '[{"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_tortillas", "quantity": {"value": 6.0, "unit": "pack of 8"}}, {"id": "ing_rice", "quantity": {"value": 450.0, "unit": "pack"}}, {"id": "ing_cabbage", "quantity": {"value": 9.0, "unit": "head"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_black_beans", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}]', '[{"ingredients":["1 tsp each onion powder (, dried oregano, salt)","2 tsp each dried cumin powder (, paprika)","1/4 tsp black pepper","¼ tsp cayenne pepper (, or to taste (optional))"],"purpose":"Burrito Seasoning:"},{"ingredients":["1/2 tbsp olive oil","2 garlic cloves","½ onion (, finely chopped)","500g / 1 lb beef mince (ground beef), I use lean","2 tbsp tomato paste","3 tbsp water"],"purpose":"Beef:"},{"ingredients":["6 - 8 large soft flour tortillas or round wraps (~25cm/10”+) (Note 1)","3 cups cooked rice (, warm not piping hot (I use white long grain))","3 cups iceberg lettuce or cabbage (, finely sliced (use cabbage if freezing))","1 cup corn kernels (I use canned, drained)","1 cup black beans (I use canned, drained)","3 tomatoes, deseeded and diced","1/2 red onion (, finely chopped)","Finely chopped coriander / cilantro (optional)","1 1/2 cups / 150g shredded cheese of choice (melting kind)"],"purpose":"Burritos:"}]', '[{"description":"Heat oil in a skillet over high heat. Add garlic and onion, cook for 2 minutes until onion is lightly browned. Add beef and cook, breaking it up as you go, until it turns from red to brown.","duration":2,"images":[],"step":1},{"description":"Add Taco Seasoning (or use 1 packet store bought) and cook for 1 minute. Then add tomato paste and water, cook for 3 minutes until the water is mostly evaporated but the beef is still juicy, not dried out. Set aside to cool for 10 minutes – piping hot filling will steam the burrito, making the tortilla soggy.","duration":1,"images":[],"step":2},{"title":"Optional","description":"If not warming rolled burrito, warm the tortillas before rolling (per packet directions).","images":[],"step":3},{"title":"Place a burrito on a work surface. Place 1/4","description":"1/3 cup of rice just below the centre. Top with 1/4 - 1/3 cup beef, then some lettuce, corn, black beans, tomato, a sprinkle of red onion, coriander and cheese.","images":[],"step":4},{"description":"Fold up the bottom to cover the filling then fold the edges in (video helpful to see how to do this). Roll up tightly, then wrap in foil. Serve as is or heat per below.","images":[],"step":5},{"title":"HEATING","description":"To warm through, pan fry (dry pan) in the foil over medium high heat for a few minutes on each side to slightly crisp and warm the outside. Or for 10+ minutes on a medium low heat if you want to melt the cheese. Or they can be baked at 180C/350F for 20 minutes in the foil – this will warm them all the way through and crisp up the tortilla slightly. If they are straight from the fridge, they will take around 30 minutes to warm through.","duration":20,"images":[],"step":6},{"description":"Burritos are best served with something to dollop/dip - sour cream (or yoghurt) and some sort of chilli sauce are my usual because it''s easy. When I''m making more of an effort, I use Restaurant Style Salsa or Guacamole.","images":[],"step":7}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Mexican","Tex-Mex"],"categories":["beef-mince-recipes","beef-recipes","burritos","dinner-tonight","main-dishes","mexican-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a35df47910fa', 'en', 'US', 'Easy Taco Soup', 'Recipe video above. All the fixings of a taco - in soup form! Don''t skip the toppings - they totally make it! At least cheese and sour cream or yoghurt are essential.', 'https://www.recipetineats.com/tachyon/2017/02/Taco-Soup-5-1.jpg', 10, 20, 30, 4, '[{"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.312, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_chilli", "quantity": {"value": 1.2, "unit": "pack of 100g"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1 tsp EACH garlic powder, onion powder and cayenne pepper","2 tsp EACH dried oregano and paprika","2 1/2 tsp cumin powder","3/4 tsp salt","1/2 tsp black pepper"],"purpose":"Homemade Taco Seasoning (Note 1)"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped (brown or yellow))","500 g / 1 lb ground beef ((mince), lean)","400 g/ 14 oz can black beans (1 can) (, drained and rinsed (Note 2))","400g / 14oz can corn kernels (1 can) (, drained and rinsed)","120 g / 4.5 oz canned green chili (Note 3)","800 g / 28 oz canned crushed tomato","2 cups beef broth"],"purpose":"Soup"},{"ingredients":["Shredded cheese (essential!)","Sour cream (or yoghurt (essential!))","Fresh coriander/cilantro leaves or shallots/scallions (, finely sliced)","Corn chips","Other options: diced avocado, squeeze of lime juice"],"purpose":"Toppings (Don’t skip these!)"}]', '[{"description":"Heat oil in a pot over medium high heat. Add garlic and onion, cook until softened (3 min).","images":[],"step":1},{"description":"Add beef and turn up the heat to high. Cook, breaking it up as you go, until it all changes from pink to brown.","images":[],"step":2},{"description":"Add remaining Soup ingredients and Taco Seasoning. Bring to a simmer then turn heat down to medium.","images":[],"step":3},{"description":"Simmer for 10 minutes to bring the flavours together. Adjust thickness with water if desired.","duration":10,"images":[],"step":4},{"title":"This is how I like to serve it","description":"place a handful of corn chips in the bowl. Ladle in soup. Top with sour cream, cheese, coriander and a few crushed corn chips. For a healthier option, skip the corn chips in the bowl and/or serve more on the top / side of the soup.","images":[],"step":5}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Tex-Mex"],"categories":["beef-mince-recipes","beef-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","mexican-recipes","quick-and-easy","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1dd67641236b', 'en', 'US', 'Chilli Con Carne', 'Recipe video above. Everybody''s favourite Chili, nice and saucy! Made with a from-scratch Chili Powder rather than a store bought mix - it''s so much more reliable and you just need pantry staples. Don''t skip the beef bouillon cubes (stock cube) - it adds so much more flavour into the sauce than using just salt, or even liquid beef stock.Make a quick midweek version though when you''ve got the time, it''s well worth slow cooking. See notes for Serving and Topping options!', 'https://www.recipetineats.com/tachyon/2016/06/Chili-Con-Carne_8.jpg', 10, 30, 40, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_kidney_beans", "quantity": {"value": 0.992, "unit": "can of 400g"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 1.0, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.5, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.625, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_tortillas", "quantity": {"value": 1.0, "unit": "pack of 8"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}]', '[{"ingredients":["1 tbsp olive oil","3 garlic cloves (, minced)","1 onion (, diced (brown, white, yellow))","1 red capsicum ((bell pepper), diced)","1 lb / 500g beef mince / ground beef","3 tbsp tomato paste","800g / 28 oz can crushed tomato","14 oz / 420g can red kidney beans (, drained (or other beans))","2 beef bouillon cubes (stock cubes), crumbled (Note 1)","1 1/2 tsp sugar (any type)","1/2 - 1 1/2 cups water"]},{"ingredients":["1 - 2 tsp cayenne pepper (adjust to taste) (Note 2)","4 tsp paprika powder","5 tsp cumin powder","2 tsp garlic powder (or onion powder)","2 tsp onion powder","2 tsp oregano","1 1/2 tsp cooking salt / kosher salt"],"purpose":"Chili Spice Mix:"},{"ingredients":["Rice, corn chips, tortillas (Note 5 for more)","Sour cream, yoghurt, grated cheese, coriander./cilantro (Note 6 for more)"],"purpose":"To Serve"}]', '[{"description":"Heat oil in a large skillet over medium high heat. Add garlic and onion, cook for 1 minute, then add capsicum and cook for 2 minutes until onion is translucent.","duration":1,"images":[],"step":1},{"description":"Turn heat up to high and add beef. Cook, breaking it up as you go, until mostly browned.","images":[],"step":2},{"description":"Add Chili Spice Mix. Cook until beef is browned all over. (This step helps release extra flavour from the spices)","images":[],"step":3},{"description":"Add remaining ingredients, with 1/2 cup of water for Quick Cook or 1 1/2 cups for Slow Cook. Bring to simmer, then adjust heat per step below:","images":[],"step":4},{"title":"Quick Cook","description":"20 to 40 minutes, uncovered, on medium low heat so it''s bubbling gently; OR","images":[],"step":5},{"title":"Slow Cook","description":"1.5 hours to 2 hours, covered, on low heat so it''s bubbling very gently. (Note 3 Slow Cooker)","images":[],"step":6},{"description":"Adjust salt to taste just before serving.","images":[],"step":7},{"description":"Serve over rice, or ladle into bowls and serve with corn chips or warm tortillas on the side with Toppings of choice (Note 6). See Note 7 for more serving options. My usual: Either over rice or with corn chips, always with sour cream, cheese and coriander.","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Tex-Mex"],"categories":["beef-mince-recipes","beef-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy","slow-cooker-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f436429c6149', 'en', 'US', 'Beef and Rice with Veggies', 'Recipe video above. Ground beef cooked with seasoned rice and plenty of veggies - kind of like a pilaf or fried rice! This dish is not spicy - the cayenne pepper just adds a touch of warmth, not spiciness.', 'https://www.recipetineats.com/tachyon/2018/02/Beef-Rice_7.jpg', 5, 20, 25, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_white_rice", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 33.333, "unit": "carton of 12"}}, {"id": "ing_baby_spinach", "quantity": {"value": 3.0, "unit": "bag of 250g"}}]', '[{"ingredients":["2 tbsp olive oil","1 onion (, diced (any type))","1 red capsicum / bell pepper (, diced (large))","2 garlic cloves (, minced)","500g (1 lb) ground beef (mince) (, lean)","2 1/2 tbsp tomato paste","1 1/4 tsp salt","1/2 tsp EACH cumin, black pepper","1 tsp each onion powder, dried oregano (or other herb of choice)","1/4 tsp cayenne pepper (optional)","1 dried bay leaf","1 1/4 cups (225g) long grain white rice (, uncooked (Note 1))","2 cups (500 ml) beef broth (, low sodium)","2 cups (300g) diced frozen veggies (, I used corn, pea, carrot mix (Note 2))","3 big handfuls baby spinach (~ 90g/3 oz) (, or other leafy greens (Note 3))"]}]', '[{"description":"Heat oil in large pot over high heat. Add onion, capsicum and garlic. Cook for 1 minute.","duration":1,"images":[],"step":1},{"description":"Add beef, cook until brown, breaking it up as you go.","images":[],"step":2},{"description":"Add tomato paste, salt, pepper, onion powder, oregano, cumin and cayenne pepper. Cook for 1 minute.","duration":1,"images":[],"step":3},{"description":"Turn heat down to medium. Add rice and beef broth, mix well. Add frozen veggies and bay leaf, then stir.","images":[],"step":4},{"description":"Place lid on, lower heat to medium low so it''s simmering gently. Cook for 12 - 15 minutes (might even take longer) until all liquid is absorbed (tilt pot to check). The rice should be just cooked, but will be wet.","duration":13.5,"images":[],"step":5},{"description":"Remove from heat. Quickly toss spinach on top of the rice and put the lid back on. Leave to rest for 10 minutes.","duration":10,"images":[],"step":6},{"description":"Fluff rice and mix through wilted spinach with a fork. Adjust salt if desired. Serve!","images":[],"step":7}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-mince-recipes","beef-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","one-pot-recipes","quick-and-easy","rice-recipes","rice-side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_40339b8e866e', 'en', 'US', 'Salisbury Steak with Mushroom Gravy', 'Recipe VIDEO above. Salisbury steak is a totally scrumptious way to transform the humble ground beef / mince into something amazing! The onion grating / soaking breadcrumbs will make your patties extra tasty and tender, and the Mushroom Gravy is made extra delicious by cooking the Salisbury Steaks IN the gravy.And next time - try Salisbury Steak Meatballs!', 'https://www.recipetineats.com/tachyon/2015/12/Salisbury-Steak-2.jpg', 15, 15, 30, 5, '[{"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_ketchup", "quantity": {"value": 0.06, "unit": "bottle of 500g"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 2.5, "unit": "bottle"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_mushroom", "quantity": {"value": 0.142, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1/2 onion (white, brown or yellow)","1/2 cup panko breadcrumbs (or 1/3 cup ordinary breadcrumbs)","1 lb/500g ground beef (mince)","1 garlic clove (, minced)","1 egg","2 tbsp ketchup","1 beef bouillon cube (, crumbled)","1/2 tsp Worcestershire sauce","3 tsp dijon mustard (OR 2 tsp dry mustard powder)"],"purpose":"Salisbury Steak"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1/2 onion (, finely chopped)","5 oz/150g mushrooms (, sliced)","30g / 2 tbsp unsalted butter","3 tbsp flour (all purpose / plain)","2 cups beef broth / stock (, low sodium)","1/2 cup water","2 tsp dijon mustard","2 tsp Worcestershire sauce","Salt and pepper"],"purpose":"Gravy"}]', '[{"description":"Salisbury Steaks","images":[],"step":1},{"title":"Onion grating","description":"Place breadcrumbs in a bowl. Use a box grater and grate the onion over the breadcrumbs. Mix with fingers, leave to soak for a few minutes.","images":[],"step":2},{"title":"Mix","description":"Add remaining Salisbury Steak ingredients into the large bowl. Use your hands to mix until just combined. Mix well for a couple of minutes until the mixture becomes a bit \"pasty\" which will ensure your patties hold together well.","images":[],"step":3},{"title":"Form patties","description":"Divide into 5 and pat very firmly into oval patties around 3/4\" / 1 2/3 cm thick.","images":[],"step":4},{"description":"Cooking and Gravy","images":[],"step":5},{"title":"Brown patties","description":"Heat oil in a skillet over high heat. Add the steaks and cook the first side for 1 minute or until browned, then gently flip and brown the other side (they will still be raw inside). Remove onto plate.","duration":1,"images":[],"step":6},{"title":"Cook aromatics","description":"If skillet is looking dry, add a touch more oil. Add chopped onion and garlic and cook for 2 minute until onions are a bit translucent.","duration":2,"images":[],"step":7},{"title":"Cook mushrooms","description":"Add the mushrooms into the skillet and cook for 2 - 3 minutes until golden.","duration":2.5,"images":[],"step":8},{"title":"Make gravy roux","description":"Turn heat down to medium. Add butter. Once melted, add flour and cook for 30 seconds, stirring constantly.","duration":0.5,"images":[],"step":9},{"title":"Gravy","description":"Gradually add in beef broth, stirring as you go. Once mostly lump free, whisk in remaining Gravy ingredients.","images":[],"step":10},{"title":"Finish cooking steaks","description":"Add steaks along with the juices on the plate. Cook for 5 - 7 minutes, or until gravy is thickened, stirring occasionally around the steaks. If the gravy thickens too quickly, add more water.","duration":6,"images":[],"step":11},{"title":"Season gravy","description":"Remove steaks onto a plate. Taste gravy and adjust salt and pepper to taste.","images":[],"step":12},{"description":"Serve salisbury steaks topped with the mushroom gravy - over mashed potato is ideal! Sprinkle with a bit of parsley if desired.","images":[],"step":13}]', '["egg","gluten","milk","mustard"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-mince-recipes","beef-recipes","dinner-tonight","main-dishes","most-popular","mushroom-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5d01e8557124', 'en', 'US', 'Rissoles!', 'Recipe video above. Plump, extra juicy, extra tasty rissoles - an Aussie favourite! I usually make Beef Rissoles but these can be made with lamb, pork, chicken or turkey. Makes 10 - 12 rissoles. (PS For those who are unfamiliar with rissoles, they are basically squashed meatballs. A classic Aussie family favourite :) )', 'https://www.recipetineats.com/tachyon/2017/09/Beef-Rissoles-1_-2.jpg', 15, 15, 30, 4, '[{"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 small brown onion","1/2 cup panko breadcrumbs (or normal)","500 g / 1 lb beef mince (ground beef) (Note 1)","1 small zucchini","1 small carrot","1 egg","1 large garlic clove (, minced)","1/2 tsp dried thyme","1/2 tsp oregano (or sub with other favourite herbs)","1/2 tsp each salt and pepper","2 tsp Worcestershire Sauce"],"purpose":"Rissoles:"},{"ingredients":["1 - 2 tbsp oil"],"purpose":"Cooking:"},{"ingredients":["Tomato Ketchup!"],"purpose":"Serving:"}]', '[{"description":"Grate the onion into a large bowl using a box grater (see video). Add panko, mix briefly to coat in the onion juices.","images":[],"step":1},{"description":"Grate zucchini and carrot into the bowl. Add remaining Rissoles ingredients. Mix well. Scoop up about 1/4 cup of mixture, form a 1.7cm / 2/3\" thick pattie. Indent the middle slightly (Note 2, see photos in post). Repeat with remaining mixture - you should make 10 - 12.","images":[],"step":2},{"description":"Heat oil in a skillet over medium heat. Add half the patties and cook for 4 minutes or until dark golden. Press LIGHTLY with spatula, if you press hard, you''ll press the juices out!","duration":4,"images":[],"step":3},{"title":"Flip and cook the other side for 3","description":"4 minutes until golden.","duration":3.5,"images":[],"step":4},{"description":"Transfer to plate, repeat with remaining rissoles.","images":[],"step":5},{"description":"Serve with tomato ketchup!","images":[],"step":6}]', '["egg"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Australian","Western"],"categories":["beef-mince-recipes","beef-recipes","dinner-tonight","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a87cd55d2a4f', 'en', 'US', 'Lasagna', 'Recipe video above. One of my signature recipes! This is a lasagna made the traditional Italian way, with a slow cooked ragu and a béchamel sauce ("Besciamella"). No ricotta - that''s the American-Italian version. Though it requires patience to make, it is worth every minute. The ragu bolognese is melt-in-you-mouth tender and the sauce is rich and thick. Makes 8 giant or 10 normal servings. This lasagna has 4 layers of lasagna sheets with 3 layers of meat and cheese sauce, then finished with a cheese sauce topping. You could stretch it to 4 ragu layers. If making 5 layers, scale up the recipe by 25% (click on servings and slide) and use a very deep pan!', 'https://www.recipetineats.com/tachyon/2025/03/Lasagna_6-1.jpg', 20, 240, 260, 10, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_beef_mince", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.333, "unit": "bottle of 750ml"}}, {"id": "ing_beef", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_sugar", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_gruyere_cheese", "quantity": {"value": 2.0, "unit": "block of 200g"}}, {"id": "ing_pinch_nutmeg", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_sheets_lasagna", "quantity": {"value": 350.0, "unit": "pack"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.2, "unit": "pack of 125g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp olive oil","1 onion (, finely chopped (white, yellow or brown))","1 medium carrot (, peeled and very finely diced)","1 celery stick (, very finely diced)","2 garlic cloves (, minced)","1 kg / 2 lb beef mince (ground beef) (Note 1)","800g / 28 oz canned crushed tomato","1/4 cup tomato paste","1 cup pinot noir red wine (, or other dry red wine (Note 2))","3 beef bouillon cubes (, crumbled)","2 bay leaves (, dried or fresh)","1/2 tsp EACH dried thyme and oregano","2 tsp Worcestershire Sauce","1 - 2 tsp sugar (if needed - Note 3)","1/2 tsp salt and black pepper"],"purpose":"Ragu Bolognese:"},{"ingredients":["60g / 4 tbsp butter","1/2 cup flour","4 cups milk (, preferably full fat but low fat ok)","2 cups gruyere or Colby cheese (, shred yourself (or cheddar, Monterey Jack, OR 1 cup / 100g shredded parmesan) (Note 4))","Pinch of freshly ground nutmeg","Salt and pepper"],"purpose":"Cheese Sauce (Besciamella):"},{"ingredients":["350g/ 12 oz fresh lasagna sheets (or 250g/8oz dried) (Note 5)","1 1/2 cups (tightly packed) mozzarella cheese (, shred yourself (Note 4))","Finely chopped basil or parsley (, for garnish (optional))"],"purpose":"Lasagna:"}]', '[{"description":"Heat oil in a large heavy based pot over medium heat. Add garlic, onion, celery and carrots. Cook for 10 minutes until softened and sweet - they should not brown (if they do, turn heat down).","duration":10,"images":[],"step":1},{"description":"Add beef, turn heat up and cook the beef, breaking it up as you go.","images":[],"step":2},{"description":"Once the beef has all turned brown, add the remaining Ragu ingredients EXCEPT the sugar.","images":[],"step":3},{"description":"Stir then adjust the heat so it is bubbling very gently. Place the lid on and cook for 1.5 - 2 hours, stirring every now and then, then remove the lid and simmer for 30 minutes.","duration":30,"images":[],"step":4},{"description":"The ragu is ready when the meat is really tender and the sauce has thickened and is rich - see video for consistency (Note 6). Adjust salt and pepper to taste, and add sugar if required (Note 3)","images":[],"step":5},{"title":"Warm milk up in a saucepan (optional","description":"just makes sauce thicken faster).","images":[],"step":6},{"description":"In a large saucepan, melt butter over medium low heat. Add flour and mix constantly for 1 minute.","duration":1,"images":[],"step":7},{"description":"Pour about 1 cup of the milk in, mixing as you go to incorporate into the flour mixture. Once mostly lump free, add remaining milk. Use a whisk if needed to make it lump free.","images":[],"step":8},{"description":"Turn heat up to medium high. Stir occasionally at first then regularly after a few minutes until sauce thickens - about 5 - 8 minutes. It should coat the back of the wooden spoon.","images":[],"step":9},{"description":"Remove from heat, add cheese, nutmeg, salt and pepper. Mix until the cheese is melted. The Sauce should be thick but still easily pourable - the consistency of heavy cream (you need to be able to drizzle it over the Ragu when layering - see video). If it''s too thick, add a splash of water or milk.","images":[],"step":10},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":11},{"description":"Use a 33 x 22 x 7 cm / 13 x 9 x 2.5\" baking dish.","images":[],"step":12},{"description":"Smear a bit of Ragu on the base, then cover with lasagna sheets. Tear sheets to fit.","images":[],"step":13},{"description":"Spread over 2 1/2 cups of Ragu (enough to cover sheets), then drizzle over 1 cup of Cheese Sauce.","images":[],"step":14},{"description":"Top with lasagna sheets (Note 7). Spread with another 2 1/2 cups of Ragu, then 1 cup of Cheese Sauce. Top with lasagna sheets then repeat 1 more time.","images":[],"step":15},{"description":"Top with a 4th layer of lasagna sheets, then pour over the remaining Cheese Sauce.","images":[],"step":16},{"description":"Sprinkle with Mozzarella, then bake for 25 minutes or until golden and bubbling.","duration":25,"images":[],"step":17},{"description":"Stand for 5 to 10 minutes before cutting and serving, garnished with basil or parsley if desired.","duration":7.5,"images":[],"step":18}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["beef-mince-recipes","beef-recipes","casseroles-and-cosy-bakes","iconic-dishes","italian-recipes","pasta-bakes","pasta-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_652e35409965', 'en', 'US', 'Greek Meatballs', 'Juicy Greek Meatballs (Keftedes), beautifully flavoured with red onion, parsley, a hint of mint and dried oregano with a slightly crispy surface. See recipe video below.', 'https://www.recipetineats.com/tachyon/2017/03/Greek-Meatballs-6-hero.jpg', 20, 12, 32, 5, '[{"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_mint", "quantity": {"value": 120.0, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}]', '[{"ingredients":["1 red onion, grated","500g / 1 lb beef mince (ground beef) (or lamb!)","200g / 6.5oz pork mince (ground pork), or more beef","2 garlic cloves, minced","1 cup / 60g panko breadcrumbs (or use normal)","1 egg","1/4 cup fresh parsley, finely chopped","6 large mint leaves, finely chopped (spearmint if you can, it''s authentic)","1/2 tsp dried oregano","1 tbsp extra virgin olive oil","3/4 tsp salt","Black pepper"],"purpose":"Meatballs:"},{"ingredients":["1/2 cup flour (any white)","3 tbsp olive oil","Finely chopped parsley (optional, for garnish)","Tzatziki (Note 5) or Greek yoghurt"],"purpose":"Cooking / Serving:"}]', '[{"description":"Grate the onion straight into a large bowl, then add remaining Meatball ingredients. Use your hands to mix well for a few minutes until the mixture is quite smooth and very well combined.","images":[],"step":1},{"title":"Optional: Refrigerate for 1 hour","description":"makes them easier to roll + retains round shape when cooking.","images":[],"step":2},{"description":"Measure out heaped tablespoons and dollop onto a work surface - should make around 32 - 35. Then roll into balls.","images":[],"step":3},{"description":"Heat most of the oil in a large skillet over medium high heat (medium if you have a strong gas stove). Use enough oil to cover the surface of the skillet.","images":[],"step":4},{"title":"Cook in 2 to 3 batches","description":"Dredge meatballs lightly in flour, shaking off excess, then place in the skillet. Roll them around and cook for 5 - 6 minutes, until nicely browned all over. Remove onto plate, cover to keep warm and repeat with remaining meatballs.","duration":5.5,"images":[],"step":5},{"title":"BAKING","description":"Alternatively, spray generously with oil (preferably olive oil) then bake at 180C/350F for 20 minutes or until browned. The pan frying method is the traditional way and the meatballs are slightly juicier.","duration":20,"images":[],"step":6},{"description":"Serve as a starter as part of a mezze platter with pita bread and tzatziki, or make dinner plates by adding a salad like a Greek Salad!","images":[],"step":7}]', '["egg","gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["beef-mince-recipes","beef-recipes","finger-food","greek-recipes","meatball-recipes","mediterranean-recipes","quick-and-easy","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1e11cde4fa1a', 'en', 'US', 'Italian Meatball Soup', 'My Classic Italian Meatballs are one of the most popular recipes on my site. They''re extra soft and juicy, and extra tasty thanks to just a couple of little but key extra steps - using bread soaked in grated onion, and using a mix of ground beef and pork (mince). And now by popular demand, here is my Meatball Soup made using my Classic Italian Meatballs! This soup is really thick and hearty, and the tomato broth is extra tasty thanks to the meatballs!', 'https://www.recipetineats.com/tachyon/2016/04/Meatball-Soup_4.jpg', 25, 30, 55, 5, '[{"id": "ing_bread", "quantity": {"value": 1.25, "unit": "loaf"}}, {"id": "ing_onion", "quantity": {"value": 75.0, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 75.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_italian_mixed_herbs", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.454, "unit": "pack of 500g"}}, {"id": "ing_basil", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.5, "unit": "pack of 125g"}}]', '[{"ingredients":["1 lightly packed cup of sliced white sandwich bread (, torn into small pieces, crusts removed (Note 1))","1/2 cup grated onion (brown, white or yellow)","14 oz / 400 g ground beef (beef mince)","3 oz / 100g ground pork (mince) or more ground beef (Note 2)","1 egg","1/4 cup fresh parsley (, finely chopped (Note 3))","2 garlic cloves (, minced)","1/4 cup Parmigiano-Reggiano ((or parmesan), freshly grated)","3/4 tsp salt","1/4 tsp black pepper"],"purpose":"Meatballs"},{"ingredients":["1 1/2 tbsp olive oil","1 cup onion (, finely chopped (white, brown or yellow))","2 garlic cloves (, minced)","2 cups chicken broth / stock (or water)","1 cup water","24 oz / 700g passata (pureed tomato) (Note 4)","28 oz / 800g canned tomato","1 tbsp Italian mixed herbs (Note 5)","2 tsp garlic powder (or onion powder)","1 - 2 tsp red pepper / chilli flakes (optional)","8 oz / 250g spaghetti (dried, not fresh or cooked)"],"purpose":"Soup"},{"ingredients":["1/4 cup fresh basil leaves (, torn)","1/2 - 3/4 cup shredded mozzarella cheese","Parmigiano-Reggiano ((or parmesan), freshly grated)"],"purpose":"Garnish (optional)"}]', '[{"description":"Place the bread and onion in a large bowl. Mix to combine so the onion juice soaks the bread.","images":[],"step":1},{"description":"Add all the remaining Meatball ingredients. Use you hands to mix well.","images":[],"step":2},{"description":"Roll a slightly heaped tablespoon of mixture into a ball. Repeat with remaining mixture. Should make around 24. (Note 6) Refrigerate meatballs for 30 minutes (Note 7)","duration":30,"images":[],"step":3},{"description":"Heat 1 1/2 tbsp olive oil in a large pot over medium high heat. Add the meatballs in a single layer and brown all over (still raw inside) - I do this in 2 batches. Remove meatballs onto a plate and set aside.","images":[],"step":4},{"description":"If the pot is looking dry, add a touch more olive oil. Add onion and garlic and cook for 2 minutes.","duration":2,"images":[],"step":5},{"description":"Add chicken broth, bring to simmer and scrape the bottom of the pot to mix the brown bits into the liquid.","images":[],"step":6},{"description":"Add remaining Soup ingredients except spaghetti. Bring to simmer, turn heat down to medium and cook for 5 minutes, stirring occasionally, scraping the bottom of the pot.","duration":5,"images":[],"step":7},{"description":"Take the lid off and add spaghetti. Use tongs to push it all under the liquid as it starts to soften. Once the spaghetti is submerged, add the meatballs. Cook for around 12 minutes, or until spaghetti is just cooked but still firm (al dente). Remove from stove.","images":[],"step":8},{"description":"If using cheese, sprinkle on the surface of the soup after you take it off the stove, put the lid back on and let the heat melt the cheese (~2 minutes).","images":[],"step":9},{"description":"Ladle soup, spaghetti and meatballs into bowls. Garnish with basil leaves and serve with Parmigiano-Reggiano, if using.","images":[],"step":10}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["beef-mince-recipes","beef-recipes","italian-recipes","main-dishes","meatball-recipes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e3d8e83202bc', 'en', 'US', 'Italian Meatloaf with Marinara Sauce', 'My Italian meatloaf is made extra juicy by soaking bread in grated onion instead of using breadcrumbs. The seasonings for the meatloaf are the same as what is used for homemade Italian sausages, so this really tastes like an Italian meatloaf! And the sauce is made extra tasty by adding the loaf pan juices and cooking the meatloaf IN the sauce for part of the time.', 'https://www.recipetineats.com/tachyon/2015/12/Italian-Meatloaf_4.jpg', 15, 60, 75, 6, '[{"id": "ing_capsicum", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 0.375, "unit": "loaf"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_cream", "quantity": {"value": 0.12, "unit": "carton of 250ml"}}, {"id": "ing_pork", "quantity": {"value": 0.369, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.726, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 12.5, "unit": "jar"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.009, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 4.5, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_canned_tomatoes", "quantity": {"value": 1.588, "unit": "can of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_mixed_italian_herbs", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 4.5, "unit": "jar of 50g"}}, {"id": "ing_black_pepper", "quantity": {"value": 4.5, "unit": "jar of 50g"}}]', '[{"ingredients":["1 1/2 cups diced red bell pepper / capsicum (1 large)","1 tbsp olive oil","2 cups stale white bread (, crusts removed, roughly diced (about 3 slices))","1 small onion","2 tbsp cream (or milk)","13 oz / 400 g ground pork (mince)","1.6lb / 800 g ground beef (mince)","2 eggs","2 1/2 tsp fennel seeds","3 tsp paprika (sweet or smoked)","1 3/4 tsp salt","Pepper"]},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1/2 onion (, finely chopped (brown, white, yellow))","1.4 lb / 700 g tomato passata or crushed tinned tomatoes (Note 1)","3/4 cup water","2 tsp dried Mixed Italian Herbs","1 - 3 tsp red pepper flakes (optional)","Salt and pepper"],"purpose":"Sauce"}]', '[{"description":"Preheat oven to 180C/350F. Spray a 28cm/11\" loaf pan, then line with parchment / baking paper, leaving overhang (Note 2).","images":[],"step":1},{"description":"Heat oil over high heat. Add capsicum, leave for 1 minute without stirring so it starts to char (burn) then stir and continue cooking to char it more (about 2 minutes in total). Remove and set aside.","duration":1,"images":[],"step":2},{"description":"Place bread in a large bowl. Grate onion into the bowl, using a normal box cutter (Note 3). Add cream, then use your hands to squidge the mixture together so the bread is completely soaked and starts to disintegrate.","images":[],"step":3},{"description":"Add remaining meatloaf ingredients, including capsicum. Use your hands to mix it together until JUST combined. Do not over mix otherwise it will become dense.","images":[],"step":4},{"description":"Press into the loaf pan (Note 4). Drizzle with olive oil then bake for 30 minutes. Meanwhile, make the Sauce.","duration":30,"images":[],"step":5},{"description":"Take the meatloaf out of the oven. Carefully lift the meatloaf out of the loaf pan (using the paper overhang) onto a work surface. Then transfer the meatloaf into the skillet with the Sauce.","images":[],"step":6},{"description":"Pour juices in the loaf pan into the skillet. Return to the oven for a further 30 to 40 minutes, or until cooked to your liking.","images":[],"step":7},{"description":"Take it out of the oven and let it rest for 5 minutes before slicing. Serve the meatloaf with the Sauce, garnished with parmesan if desired.","duration":5,"images":[],"step":8},{"description":"I like to serve this with mashed potatoes but it is also lovely with pasta.","images":[],"step":9},{"description":"Heat oil in a ovenproof skillet over medium heat. Add onion and garlic and cook for 3 minutes until translucent.","duration":3,"images":[],"step":10},{"description":"Add remaining ingredients. Bring to a simmer and cook for 5 minutes on the stove, adjusting salt and pepper to taste.","duration":5,"images":[],"step":11},{"description":"Take it off the stove. Follow the steps above to place the meatloaf in and bake it.","images":[],"step":12}]', '["egg","gluten","milk"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["beef-mince-recipes","beef-recipes","dinner-tonight","italian-recipes","main-dishes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_211a911cd221', 'en', 'US', 'Nachos Pie', 'Nachos - in lasagne form! This is how to get your midweek Nachos fix with far less guilt! You can substitute the spices for a packet Nachos mix if you prefer. The Pico De Gallo adds freshness but is not essential! It is still scrumptious without it. You could make this even healthier by reducing the beef in this and adding more vegetables, like corn, diced zucchini and bell peppers (capsicum).', 'https://www.recipetineats.com/tachyon/2015/07/Nacos-Pie_600px_2a_Featured.jpg', 10, 40, 50, 6, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_beef", "quantity": {"value": 0.369, "unit": "kg"}}, {"id": "ing_packet_taco_seasoning_or_make_your_own_see_note_1", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_kidney_beans", "quantity": {"value": 0.992, "unit": "can of 400g"}}, {"id": "ing_tortillas", "quantity": {"value": 3.0, "unit": "pack of 8"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_corn", "quantity": {"value": 3.0, "unit": "can of 400g"}}, {"id": "ing_avocado", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}]', '[{"ingredients":["1 tbsp olive oil","1 onion (, diced (brown, yellow, white))","2 garlic cloves","13 oz / 400 g ground/mince beef (use lean!)","1 oz / 28 g packet Taco Seasoning OR make your own - see Note 1","1/2 tsp black pepper","700 g / 24oz tomato passata or pureed canned tomatoes (Note 2)","1/2 cup water","14 oz / 400 g canned red kidney beans ((or any other beans), drained)","3 - 4 soft tortillas ((flour or corn) - for layering)","1 cup grated cheese (I used mozzarella, but any melting cheese is fine)","2 oz / 70 g corn chips"]},{"ingredients":["1/2 avocado (, diced)","1 large tomato (, deseeded and diced (Note 3))","1/4 spanish ((red) onion, diced)","2 tbsp lime juice (fresh or bottled)","3 tbsp fresh coriander leaves","1/2 tbsp olive oil","Salt and pepper"],"purpose":"Pico de Gallo (optional)"},{"ingredients":["Sour cream"],"purpose":"To serve"}]', '[{"description":"Preheat the over to 350F/180C.","images":[],"step":1},{"description":"Heat the oil in a large skillet over high heat.","images":[],"step":2},{"description":"Add the garlic and onion, and cook until translucent.","images":[],"step":3},{"description":"Add the beef and cook, breaking up into pieces, until browned. Add the Taco Seasoning and pepper about halfway through browning the beef.","images":[],"step":4},{"description":"Add the tomato passata, water and beans. Cook for 5 minutes, stirring occasionally until thickened but still very saucy. Remove from heat.","duration":5,"images":[],"step":5},{"description":"Assemble & Bake","images":[],"step":6},{"description":"Lay a tortilla in a pie dish (24 cm / 9 inch diameter). Use a slotted spoon to top with just under 1/2 the meat. Try to avoid using too much sauce so sort of \"shake\" each spoonful to drain out sauce.","images":[],"step":7},{"description":"Top with another tortilla + torn/cut pieces of another tortilla to cover completely.","images":[],"step":8},{"description":"Top with the remaining meat, again avoiding the sauce.","images":[],"step":9},{"description":"Top with remaining tortillas, then pour over all the sauce (and any residual meat).","images":[],"step":10},{"description":"Place in the oven and bake for 20 minutes. If you''re worried about overspill, place it on a baking tray.","duration":20,"images":[],"step":11},{"description":"Remove from the oven, cover with corn chips then scatter with cheese. Bake until the chips are a bit golden and the cheese is melted - 10 to 15 minutes.","images":[],"step":12},{"description":"Serve, topped with Pico De Gallo and Sour Cream on the side, if using.","images":[],"step":13},{"description":"Combine ingredients in a bowl. Toss and adjust salt/pepper to taste.","images":[],"step":14}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican-esque"],"categories":["beef-mince-recipes","beef-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","mexican-recipes","nachos-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_94aae0a6fbf0', 'en', 'US', 'One Pot Orzo / Risoni Bolognaise', 'Dinner all made in one pot in just 20 minutes! A yummy bolognaise sauce made with orzo/risoni instead of spaghetti. Great couch food - and for kids too, less mess!', 'https://www.recipetineats.com/tachyon/2015/06/One-Pot-Bolognaise-Orzo-Risoni_680px_1.jpg', 3, 18, 21, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_italian_herbs", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_beef", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.45, "unit": "pack of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp olive oil","2 cloves of garlic (, minced)","1 small onion (, peeled and diced (brown, white or yellow))","1 lb / 500g ground beef (mince)","24 oz / 700g tomato passata (Note 3)","2 tsp Worcestershire sauce","2 tsp dried Italian Herbs (, or any combination of dried parsley, oregano, basil)","2 beef bouillon cubes (Note 1)","1/2 to 1 tsp salt (to taste)","Black pepper","3 cups water","1 1/2 cups dried orzo / risoni"]},{"ingredients":["Freshly grated parmesan cheese","Finely chopped parsley"],"purpose":"To serve (optional)"}]', '[{"description":"Heat the oil in a large skillet/fry pan (or pot) over medium high heat. Add the onion and garlic and cook for 3 minutes or until translucent.","duration":3,"images":[],"step":1},{"description":"Add the mince and turn the heat up to high. Cook the mince, breaking it up as you go.","images":[],"step":2},{"description":"When the mince is browned, add the remaining ingredients except the orzo. When the liquid comes to a simmer (it might bubble and spit slightly) add the orzo/risoni.","images":[],"step":3},{"description":"Give it a quick stir then turn the heat down to medium low.","images":[],"step":4},{"description":"Cook for 10 minutes, stirring frequently towards the end to ensure the orzo/risoni doesn''t stick to the bottom of the pan. If your liquid is evaporating too quickly, just add a slosh of hot water (tap or boiling).","duration":10,"images":[],"step":5},{"description":"Remove the risoni from the heat. The risoni should be a teeny bit hard still and it should be very saucy when you take it off the stove. (Note 2)","images":[],"step":6},{"description":"Check for seasoning (salt), then give it a good stir.","images":[],"step":7},{"description":"Serve immediately, while it''s piping hot and nice and saucy, garnished with freshly grated parmesan and parsley, if desired.","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Italian-esque"],"categories":["beef-mince-recipes","beef-recipes","dinner-tonight","italian-recipes","main-dishes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_98fb4edc94a6', 'en', 'US', 'Meatloaf Cupcakes With Mashed Potato', 'Everything tastes better in miniature form! These Meatloaf Cupcakes are made extra irresistible by piling on mashed potato. These freeze very well. They are also great for hiding vegetables. I only added grated carrot, but you can mix in whatever vegetables you want. Finely chopped spinach or cabbage would blend in well, as would grated zucchini.', 'https://www.recipetineats.com/tachyon/2014/10/Meatloaf-Cupcakes-2.jpg', 15, 25, 40, 8, '[{"id": "ing_beef_mince", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_panko", "quantity": {"value": 150.0, "unit": "jar"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 lb / 500g beef mince (ground beef)","1 onion (, grated (brown, white or yellow))","2 small carrots (, grated)","2 eggs","1/4 cup grated parmesan cheese","1/4 cup tomato ketchup (or tomato sauce)","1 cup panko (or breadcrumbs)","1 tsp garlic powder","1 tsp dried oregano","1 tsp dried thyme","1 tsp salt","Pepper"],"purpose":"Meatloaf Cupcakes"},{"ingredients":["2 large or 3 medium potatoes","1 tbsp butter (optional)","1/2 - 1 cup milk"],"purpose":"Mashed Potato"},{"ingredients":["Tomato ketchup or sauce","Parsley (, finely chopped (optional))"],"purpose":"Garnish"}]', '[{"description":"Meatloaf Cupcakes","images":[],"step":1},{"description":"Preheat oven to 180C/350F.","images":[],"step":2},{"description":"Spray 8 holes of a muffin tin.","images":[],"step":3},{"description":"Grate the onion and carrot straight into a large bowl.","images":[],"step":4},{"description":"Add remaining meatloaf ingredients and use your hands to mix and combine well.","images":[],"step":5},{"description":"Scoop up 1/2 cup of mince and use your hands to form a rough ball shape. Press into the muffin tin. The surface should be a slight dome shape.","images":[],"step":6},{"description":"Repeat with remaining mince. It should make about 8.","images":[],"step":7},{"title":"Bake for 20","description":"25 minutes until browned on top. Remove from oven.","duration":22.5,"images":[],"step":8},{"description":"Peel and dice the potato. Steam or boil until soft but not waterlogged.","images":[],"step":9},{"description":"Drain, then add butter and 1/2 cup of milk. Mash using a potato masher until smooth or to your liking. Add extra milk if you need it. The mash needs to be creamy but stiff enough to hold its shape when piped or piled onto the Meatloaf Cupcakes.","images":[],"step":10},{"description":"Smear a dollop of tomato ketchup on the Meatloaf Cupcakes.","images":[],"step":11},{"description":"Top with mashed potato, either by piping it or just dolloping it on with a spoon.","images":[],"step":12},{"description":"Serve with a sprinkle of parsley, if using.","images":[],"step":13}]', '["egg","milk"]', '["gluten_free","high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["beef-mince-recipes","beef-recipes","dietary","gluten-free-recipes","most-popular","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d37889fcde81', 'en', 'US', 'Shepherd''s Pie Potato Skins', 'Don''t save the potato you scoop out for another dish - mash it and pile it on top to make these irresistible Shepherd''s Pie Potato Skins!', 'https://www.recipetineats.com/tachyon/2014/09/Shepherds-Pie-Potato-Skins-1.jpg', 5, 10, 15, 4, '[{"id": "ing_beef_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_frozen_mixed_vegetables", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 4.0, "unit": "bag of 2kg"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["250 g / 8 oz lamb or beef mince (ground meat)","1 tbsp olive oil","½ onion ((brown, white or yellow), diced)","1 clove garlic (, minced)","1 1/2 cups frozen mixed vegetables (pea, corn, carrots) (or fresh)","2 tbsp flour","1 cup beef stock/broth (or 1 stock / bouillon cube dissolved in hot water)","½ cup water","½ tsp salt","½ tsp dried thyme","½ tsp dried oregano","Black pepper"]},{"ingredients":["4 large potatoes (, scrubbed clean (about 400g/13oz each))","½ to 1 cup milk (full or low fat)","2 tbsp butter (optional – but highly recommended)","Salt to taste"],"purpose":"Potatoes and Mash"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Prepare the Potatoes and Mash","images":[],"step":2},{"description":"Prick the potatoes with a fork (about 6 times on each potato) and microwave on high for 5 minutes. Then turn and microwave for a further 5 minutes. Pierce with a knife to check if they are cooked.","duration":5,"images":[],"step":3},{"description":"Remove from microwave (use a dish cloth). Cut off the tops and scoop out the center using a spoon, leaving a fairly thin skin (about 0.5 cm / 0.2”).","images":[],"step":4},{"description":"Place the potato scooped out in a bowl. Add milk, butter and salt and mash with a potato masher until smooth, or to your liking.","images":[],"step":5},{"description":"If you want to pipe the filling, place the mashed potato into a piping back with a large star tip nozzle.","images":[],"step":6},{"description":"Meanwhile, make the filling. Heat the olive oil in a large fry pan over medium high heat.","images":[],"step":7},{"description":"Add onion and garlic, sauté for 2 minutes until softened.","duration":2,"images":[],"step":8},{"description":"Turn up heat to high. Add mince beef (ground beef) and cook, breaking up the mince as you go, until nicely browned and cooked – about 3 minutes.","images":[],"step":9},{"description":"Sprinkle over flour and stir to combine.","images":[],"step":10},{"description":"Add remaining ingredients and stir to combine. Bring to simmer and continue to stir until the sauce is thick and glossy – around 2 minutes.","images":[],"step":11},{"description":"Remove from heat.","images":[],"step":12},{"description":"Assemble Potatoes","images":[],"step":13},{"description":"Fill each potato with the Filling so it is slightly heaped. Push down lightly to pack the filling in well.","images":[],"step":14},{"description":"Pipe over the mashed potato, or scoop it on with a spoon then fluff it up with a fork. You probably won’t use all of it – save the remainder or serve it on the side.","images":[],"step":15},{"description":"Place in the oven and bake for 15 to 20 minutes until the mashed potato is starting to brown on the ridges.","duration":17.5,"images":[],"step":16},{"description":"Serve immediately!","images":[],"step":17}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["beef-mince-recipes","beef-recipes","dietary","gluten-free-recipes","most-popular","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0b052606b4c6', 'en', 'US', 'Goulash (Hungarian beef stew)', 'Recipe video above. The national dish of Hungary! Boldly flavoured with stacks of paprika, lots of onion, garlic and capsicum/bell peppers, with fall apart hunks of beef. It''s sort of a stew, sort of a soup. The broth is not supposed to be as thick as typical stews. It''s naturally thickened slightly using fresh tomatoes that break down into the sauce.Serve like soup in bowls with bread for dunking. (Try cheese bread. Obsessed!).', 'https://www.recipetineats.com/tachyon/2023/06/Hungarian-Goulash-_7.jpg', 15, 140, 155, 5, '[{"id": "ing_beef", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.009, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.938, "unit": "jar of 40g"}}, {"id": "ing_caraway_seeds", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_beef_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["1 kg/2 lb beef chuck (, cut in 3.5cm / 1.5\" cubes (Note 1))","1 3/4 tsp cooking salt / kosher salt","1 tsp black pepper","1 tbsp extra virgin olive oil","2 tbsp/ 30g unsalted butter","2 brown onions (, cut into 1cm / 1/2\" squares)","5 garlic cloves (, finely minced)","2 capsicum/bell peppers ((1 red + 1 yellow), cut into 2 cm / 0.8\" squares)","2 tomatoes (, cut into 8 wedges then in half)","1/4 cup Hungarian-style paprika (sub ordinary paprika, Note 2)","1 tsp caraway seeds (, optional (Note 3))","1 bay leaf","1 litre / 4 cups beef stock/broth (, low-sodium)","2 carrots (, peeled, cut in quarters lengthwise then into 1cm / 0.4\" pieces)","2 potatoes (, cut into 1.2cm / 1/2\" cubes)","1 tbsp finely chopped parsley (, optional garnish)"]}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan), though you can use your slow cooker or stove instead (oven easiest! Note 4).","images":[],"step":1},{"title":"Season beef","description":"Toss the beef with half the salt and pepper.","images":[],"step":2},{"title":"Cook onion","description":"Heat the oil and melt the butter in a large oven-proof dutch oven over high heat. Cook onion for 6 minutes until the edges are light golden.","duration":6,"images":[],"step":3},{"title":"Cook beef","description":"Add the beef and stir until the outside changes from red to brown, about 2 minutes. It won''t go golden brown, it''s not supposed to.","images":[],"step":4},{"title":"Add vegetables","description":"Add garlic, capsicum and tomato. Stir for 3 minutes - the tomato will mostly breakdown.","duration":3,"images":[],"step":5},{"description":"Add paprika, caraway and bay leaf. Stir for 30 seconds.","duration":0.5,"images":[],"step":6},{"title":"Slow cook","description":"Add beef stock, stir, bring to simmer. Cover with a lid and transfer to the oven for 1 1/2 hours.","images":[],"step":7},{"title":"Add potato","description":"The beef should be pretty tender but not quite \"fall-apart\". Stir in carrot and potatoes. Return to oven, covered, for another 30 minutes. Beef should now be \"fall-apart\" - if not, return to the oven for 10 minutes at a time.","duration":10,"images":[],"step":8},{"title":"Serve","description":"Ladle goulash into bowls and sprinkle with parsley. Eat as is, with optional bread for dunking! (Pictured with cheese bread)","images":[],"step":9}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["European","Hungarian"],"categories":["beef-recipes","slow-cooked-fall-apart","soup-recipes","stews","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_46a7ff96a1d0', 'en', 'US', 'Beef Standing Rib Roast (Prime Rib)', 'Recipe video above. The juiciest, tastiest, BEST roast beef in the world is Prime Rib!! Also known as Standing Rib Roast, this is slathered in a herb and garlic butter, then roasted to juicy perfection. By using a lower but not super low oven temperature, we can be assured of a beautiful even cook throughout the whole roast, yet still have it on the table in a couple of hours. Bonus: lower temp = more forgiving! Meat thermometer is a MUST!', 'https://www.recipetineats.com/tachyon/2018/11/Standing-Rib-Roast_Prime-Rib_0.jpg', 10, 120, 130, 6, '[{"id": "ing_standing_rib_roast_prime_rib", "quantity": {"value": 2.5, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_butter", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_beef", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.833, "unit": "bottle of 750ml"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}]', '[{"ingredients":["2.5 kg / 5 lb standing rib roast / prime rib (, bone in (Note 1))","1 onion (, unpeeled, quartered (brown, yellow, white))","1 head of garlic (, unpeeled, halved horizontally)","5 sprigs thyme","3 sprigs rosemary"]},{"ingredients":["150g/ 10 tbsp unsalted butter (, softened)","5 garlic cloves (, minced)","2 tsp finely chopped fresh rosemary (or 1 tsp dried)","2 tsp finely chopped fresh thyme (or 1 tsp dried)","2 tsp salt","1 tsp black pepper"],"purpose":"Garlic Herb Butter:"},{"ingredients":["1 1/2 cups beef broth/stock (, low salt)","2 1/2 cups dry red wine (Note 2)","1 tbsp cornflour/cornstarch (optional, Note 3)"],"purpose":"Red Wine Sauce:"}]', '[{"title":"Bring Beef to room temp","description":"Take beef out of the fridge 2 - 3 hours before cooking to bring to room temp (key tip for even cooking). Pat dry with paper towel.","images":[],"step":1},{"description":"Preheat oven to 240°C/460°F (220°C fan). Adjust shelf so beef will be sitting in the middle of the oven.","images":[],"step":2},{"title":"Garlic Herb Butter","description":"Mix together.","images":[],"step":3},{"title":"Roasting bed","description":"Place onion, garlic and herbs in a heavy based oven proof skillet (or use a roasting pan).","images":[],"step":4},{"title":"Slather 1","description":"Spread a thin layer of butter on the underside of the beef (ie the bone side). Place beef on onion etc, butter side down. Spread about 2/3 of the butter on the top and sides (reserve some for Slather 2).","images":[],"step":5},{"title":"Hot oven","description":"Roast 20 minutes.","images":[],"step":6},{"title":"Slather 2","description":"Remove, spread over remaining butter. Turn oven down to 120°C/250°F (100°C fan).","images":[],"step":7},{"title":"Slow roast","description":"Roast for a further 1 1/2 hours, basting every 30 minutes with the juices in the pan, until the internal temperature is 51°C / 123.8°F in the centre (for medium rare, Note 4). Start checking the internal temp early.","images":[],"step":8},{"title":"Rest","description":"Transfer beef to plate. Cover loosely with foil and rest for 20 - 30 minutes. Internal temperature will rise to 56-58°C / 133-136.4°F (which is medium rare).","duration":25,"images":[],"step":9},{"description":"Slice beef and serve with Sauce! For a classic high-end Steakhouse experience, serve with Paris Mash and Garlic Sautéed Spinach.","images":[],"step":10},{"description":"Red Wine Sauce:","images":[],"step":11},{"description":"Place skillet with onion and garlic left in it on the stove over high heat. Add wine and beef stock, rapidly simmer for 10 minutes until it reduces by 2/3 or so, down to 1 1/2 cups or liquid.","duration":10,"images":[],"step":12},{"description":"Lower heat to medium. Mix cornflour with 2 tbsp water. Drizzle in half and stir. Sauce will thicken in 1 minute or so. Add more cornflour water mixture if you want it thicker.","images":[],"step":13},{"description":"Strain into bowl, pour into sauce jug.","images":[],"step":14}]', '["milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-recipes","iconic-dishes","main-dishes","roast-beef","roasts","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9cf1897bf5c6', 'en', 'US', 'Beef and Guinness Stew', 'RECIPE VIDEO ABOVE. The iconic Irish Beef and Guinness Stew is easy to make but requires patience while it slow cooks! The Guinness Beer is the secret weapon ingredient in this, creating a sauce that has wonderful deep complex flavours.', 'https://www.recipetineats.com/tachyon/2019/03/Irish-Beef-Guinness-Stew_6.jpg', 10, 180, 190, 6, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_beef", "quantity": {"value": 1.134, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.851, "unit": "pack of 200g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_beer", "quantity": {"value": 1.333, "unit": "bottle of 330ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_carrot", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 40.0, "unit": "head"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.12, "unit": "bunch"}}]', '[{"ingredients":["2 tbsp olive oil","2.5 lb / 1.25 kg beef chuck (, boneless short rib or any other slow cooking beef (no bone))","3/4 tsp each salt and black pepper","3 garlic cloves (, minced)","2 onions (, chopped (brown, white or yellow))","6 oz / 180g bacon (, speck or pancetta, diced)","3 tbsp flour (all purpose/plain, Note 3 for GF)","440ml / 14.9 oz Guinness Beer (Note 1)","4 tbsp tomato paste","3 cups (750 ml) chicken stock/broth (or beef broth - Note 4)","3 carrots (, peeled and cut into 1.25 cm / 1/2\" thick pieces)","2 large celery stalks (, cut into 2cm / 1\" pieces)","2 bay leaves","3 sprigs thyme (or sub with 1 tsp dried thyme leaves)"]}]', '[{"description":"Cut the beef into 5cm/2\" chunks. Pat dry then sprinkle with salt and pepper.","images":[],"step":1},{"description":"Heat oil in a heavy based pot over high heat. Add beef in batches and brown well all over. Remove onto plate. Repeat with remaining beef.","images":[],"step":2},{"description":"Lower heat to medium. If the pot is looking dry, add oil.","images":[],"step":3},{"description":"Cook garlic and onion for 3 minutes until softening, then add bacon.","duration":3,"images":[],"step":4},{"description":"Cook until bacon is browned, then stir through carrot and celery.","images":[],"step":5},{"description":"Add flour, and stir for 1 minute to cook off the flour.","duration":1,"images":[],"step":6},{"description":"Add Guinness, chicken broth/stock and tomato paste. Mix well (to ensure flour dissolves well), add bay leaves and thyme.","images":[],"step":7},{"description":"Return beef into the pot (including any juices). Liquid level should just cover - see video or photos.","images":[],"step":8},{"description":"Cover, lower heat so it is bubbling gently. Cook for 2 hours - the beef should be pretty tender by now. Remove lid then simmer for a further 30 - 45 minutes or until the beef falls apart at a touch, the sauce has reduced and thickened slightly.","images":[],"step":9},{"description":"Skim off fat on surface, if desired. Adjust salt and pepper to taste. Remove bay leaves and thyme.","images":[],"step":10},{"description":"Serve with creamy mashed potatoes!!","images":[],"step":11}]', '["gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Irish"],"categories":["beef-recipes","iconic-dishes","main-dishes","most-popular","slow-cooked-fall-apart","slow-cooker-recipes","stews","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4030ba105eb5', 'en', 'US', 'Slow Cooker Beef Stroganoff', 'Recipe video above. The slow cooked version of Beef Stroganoff! Fall apart beef smothered in a creamy Stroganoff sauce with buttery garlic mushrooms, it''s made with economical stewing beef yet tastes like a million dollars! 3 cook methods provided: stove, slow cooker or pressure cooker/instant pot* Recipe update: pursuant to some readers having difficulties with flour lumps, the steps have been updated to make it easier!', 'https://www.recipetineats.com/tachyon/2020/02/Slow-Cooked-Beef-Stroganoff-Stew_9.jpg', 15, 510, 525, 6, '[{"id": "ing_beef", "quantity": {"value": 1.75, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 20.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.105, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.3, "unit": "jar of 200g"}}, {"id": "ing_beef_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.9, "unit": "tub of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_chives_for_garnish", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1.75kg/ 3.5lb beef chuck or other stewing beef (, cut in 4cm / 1.5” cube (Note 1))","1.5 tsp each salt and pepper","2 tbsp oil","20 g/ 1 tbsp butter (, unsalted)","1 large onion (, halved then sliced into 1 cm / 2/5\" slices)","4 garlic cloves (, minced)","7 tbsp flour (, plain / all purpose)","4 tbsp Dijon Mustard","1 litre / 1 quart beef stock/broth (, reduced salt)","1 1/2 cups sour cream (, full fat best)"]},{"ingredients":["3 tbsp/ 45 g butter (, unsalted)","700 g / 1.2 lb mushrooms (, sliced into 0.5cm thick slices)","3 garlic cloves (, finely minced)","1/2 tsp salt and pepper"],"purpose":"Garlic Butter Mushrooms:"},{"ingredients":["Pasta, wide egg noodles, mashed potato","Chives for garnish"],"purpose":"Serving:"}]', '[{"title":"Season beef","description":"Pat beef dry then sprinkle with all the salt and pepper.","images":[],"step":1},{"title":"Brown beef","description":"Heat 1 tbsp oil in a large heavy based pot or skillet* over high heat. Add beef in a single layer (not squished) and brown aggressively all over - 4 minutes or so. Remove and repeat with rest of beef, adding more oil as needed.","images":[],"step":2},{"title":"Sauté aromatics","description":"Let the pot cool down a bit then return to stove. Melt half the butter, then cook garlic and onion for 3 minutes until softened.","duration":3,"images":[],"step":3},{"title":"Add flour","description":"Sprinkle the flour across the surface, then stir. Add the mustard, and stir - it will look gluey, that''s ok, it will dissolve.","images":[],"step":4},{"title":"Add stock","description":"While stirring, pour in about half the beef stock then mix so the flour mixture dissolves into the liquid. It will thicken quite quickly into a gravy-like consistency .Switch to a whisk if needed, to make it lump free. Then add remaining stock, stir well, scraping the bottom of the pot, and bring to simmer. Cook using chosen method below.","images":[],"step":5},{"title":"SLOW COOKING","description":"choose method:","images":[],"step":6},{"title":"Slow cooker","description":"Transfer all liquid into slow cooker. Add beef, then slow cook 8 hours on LOW or 5 hours on HIGH.","images":[],"step":7},{"title":"Stove","description":"Add beef into pot. Cover with lid and adjust heat to low/medium low so the it''s simmering gently. Simmer 2 hrs (check at 1.5 hrs) until beef beef falls apart easily.","images":[],"step":8},{"title":"Instant pot","description":"SKIP FLOUR, follow Note 5 Gluten Free option. 40 minutes on high, same method as slow cooker.","images":[],"step":9},{"title":"Other pressure cookers","description":"40 minutes on high, same method as slow cooker.","images":[],"step":10},{"description":"Melt half the butter in a large skillet over high heat. Add half the mushrooms and cook until almost golden (~3 minutes). Add half the garlic, salt and pepper, cook until golden. Remove, repeat with remaining butter, mushrooms and garlic.","images":[],"step":11},{"description":"Mix sour cream with 1.5 cups of liquid from slow cooker (Note 2), then gently stir into stew - careful, the beef is delicate!","images":[],"step":12},{"description":"Gently stir in mushrooms.","images":[],"step":13},{"description":"Serve over noodles, pasta or mashed potato, sprinkled with chives!","images":[],"step":14}]', '["egg","gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Russian(ish)","Western"],"categories":["beef-recipes","slow-cooked-fall-apart","slow-cooker-recipes","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ca60c453049b', 'en', 'US', 'Pot Roast', 'Recipe VIDEO above. The ultimate one-pot family meal! Meltingly tender slow cooker beef and vegetables smothered in a gravy like sauce - because it''s so much tastier than just a watery broth! I like to make this in my slow cooker but I''ve also added directions for pressure cooker, stove and oven.', 'https://www.recipetineats.com/tachyon/2018/09/Slow-Cooker-Beef-Pot-Roast-4.jpg', 15, 500, 515, 8, '[{"id": "ing_bread", "quantity": {"value": 2.0, "unit": "loaf"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_wine", "quantity": {"value": 0.333, "unit": "bottle of 750ml"}}, {"id": "ing_beef", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_rosemary", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_potato", "quantity": {"value": 750.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["2 kg / 4 lb beef chuck roast , rolled (Note 1)","1 tsp each salt and pepper","2 tbsp olive oil","1 onion ((large), cut into large dice)","5 garlic cloves (, peeled and smashed (Note 2a))","5 carrots (, peeled and cut into 2.5cm/1\" pieces)","3 celery stalks (, cut into 4 cm / 1.5\" pieces)","1 cup (250ml) dry red wine (sub with beef broth)","3 cups (750ml) beef broth (, salt reduced)","1/3 cup (50g) flour (plain / all purpose) (GF - Note 2b)","1 tsp dried rosemary","1 1/2 tsp dried thyme","750g / 1.5 lb potatoes (, peeled and cut into 2.5 cm / 1\" pieces)"]}]', '[{"description":"Pat beef dry with paper towels. Sprinkle generously with salt and pepper all over.","images":[],"step":1},{"description":"Heat oil in a skillet over high heat. Brown aggressively all over - a deep dark brown crust is essential for flavour base! Should take about 7 minutes.","images":[],"step":2},{"description":"Transfer beef to slow cooker.","images":[],"step":3},{"description":"In the same skillet, add onion and garlic. Cook for 2 minutes until onion is browned.","duration":2,"images":[],"step":4},{"description":"Add wine, reduce by half. Transfer to slow cooker.","images":[],"step":5},{"description":"Mix together flour and about 1 cup of the broth. Lumps is fine. Pour into slow cooker.","images":[],"step":6},{"description":"Add remaining broth, carrots, celery, rosemary and thyme into slow cooker.","images":[],"step":7},{"description":"Cover and slow cook on LOW for 5 hours. (45 min pressure cook on HIGH, Note 3a for Oven and Stove)","images":[],"step":8},{"description":"Add potato, slow cook on LOW for 3 hours. (10 min pressure cooker on HIGH, Note 3b)","images":[],"step":9},{"description":"Remove beef. Rest for 5 minutes, then slice thickly.","duration":5,"images":[],"step":10},{"description":"Adjust salt and pepper of Sauce to taste.","images":[],"step":11},{"description":"Serve beef with vegetables and plenty of sauce! Bread also terrific for mopping up sauce - try these No Knead Dinner Rolls, No Yeast Irish Soda Bread or these fabulous Cheese Muffins.","images":[],"step":12}]', '["gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-recipes","main-dishes","nagis-picks","one-pot-recipes","slow-cooker-recipes","stews","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_39a03d526671', 'en', 'US', 'How to cook steak - like a chef!', 'Recipe video above. Here''s a cheffy way to cook steak that really makes the most of a good steak - or fancies up economical steaks! Basting with garlic-thyme infused butter as the steak is cooking adds flavour and luxury to the steak. You''ll feel like a total pro cooking it and it''ll rival the best steakhouse in town!', 'https://www.recipetineats.com/tachyon/2019/07/Cheffy-Garlic-Butter-Steak_9.jpg', 5, 6, 11, 1, '[{"id": "ing_fish_fillets", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_rosemary", "quantity": {"value": 0.24, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}]', '[{"ingredients":["1 - 2 boneless ribeye or scotch fillet (, 2.5 cm / 1\" thick, approx 300g/10 oz each (Note 1))","1 tbsp vegetable oil","Salt and pepper","75g / 5 tbsp unsalted butter (, cut into 1.25cm / 1/2\" cubes (Note 2))","6 sprigs fresh thyme or 3 sprigs rosemary","5 garlic cloves (, peeled and smashed to split (Note 3))"]}]', '[{"title":"Bring to room temp","description":"Take the steak out of the fridge 30 minutes prior to bring to room temperature.","images":[],"step":1},{"title":"Dry steaks","description":"Pat dry with paper towels.","images":[],"step":2},{"title":"Heat skillet","description":"Heat oil in a heavy based skillet over high heat until it is very hot - you should see smoke!","images":[],"step":3},{"title":"Season","description":"Sprinkle each side of the steak generously with salt and pepper, then immediately place in the skillet.","images":[],"step":4},{"title":"Sear Side 1: Cook for 2","description":"2.5 minutes until you get a great crust, then turn.","images":[],"step":5},{"title":"Garlic Butter","description":"Leave for 1 minute, then push steaks to one side and toss in butter, garlic and thyme. BE CAREFUL - the thyme will sputter!","duration":1,"images":[],"step":6},{"title":"Baste","description":"As soon as the butter is melted, continuously spoon the butter over the steak until it''s cooked to your liking - 2 minutes in total for the 2nd side for medium rare (52C/125F, chart below for other doneness temps)","images":[],"step":7},{"title":"Basting also renders fat on the side of the steak","description":"use tongs to sear the edges at the end if you want it browned more.","images":[],"step":8},{"title":"Rest","description":"Transfer steak to a plate and cover loosely with foil, rest for 5 to 10 minutes.","duration":7.5,"images":[],"step":9},{"description":"Serve steak with a bit of the butter from the skillet drizzled on top. Pictured in post with Crispy Smashed Potatoes.","images":[],"step":10}]', '["fish","milk"]', '["gluten_free","high_protein","keto_friendly","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-recipes","dinner-tonight","iconic-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c2328cd05d7d', 'en', 'US', 'Mexican Shredded Beef (and Tacos)', 'Recipe video above. This is how I make Mexican Shredded Beef. The sauce is rich, thick and full of flavor, and the beef is very tender and juicy. I use this shredded beef for tacos, burritos, enchiladas, quesadillas and even to make sliders - see in post for list of ideas and directions!', 'https://www.recipetineats.com/tachyon/2015/09/Mexican-Shredded-Beef_1.jpg', 20, 180, 200, 20, '[{"id": "ing_chipotle", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_beef", "quantity": {"value": 1.361, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 10.0, "unit": "pack of 1kg"}}, {"id": "ing_oranges", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}]', '[{"ingredients":["1 1/2 tbsp chipotle powder (, adjust spiciness to taste (Note 5))","1 tbsp paprika","1 tbsp dried oregano","1 tsp All Spice powder (ground All Spice)","1 tsp coriander powder","2 tsp onion powder or garlic powder (OR 1 tsp of each)","1 tsp salt and pepper (, each)"],"purpose":"Spice Mix"},{"ingredients":["1 - 2 tbsp olive oil","3 lb / 1.5kg beef chuck or brisket ((or gravy or any other slow cooking beef) cut into 4 pieces)","5 garlic cloves, minced","1 onion (, diced (yellow, brown or white))","3/4 cup (185 ml) orange juice","2 tbsp lime juice","14 oz / 400g can crushed tomatoes","2 cups (500 ml) beef or chicken broth/stock","1/2 cup (125ml) water","Salt and pepper"],"purpose":"Beef"}]', '[{"description":"Combine the Spice Mix ingredients in a bowl. Sprinkle 4 teaspoons over the beef and pat so it sticks.","images":[],"step":1},{"description":"Heat the olive oil in a large heavy based pot over high heat. Add the beef (in batches if necessary) and brown well on all sides. Remove onto a plate.","images":[],"step":2},{"description":"Turn the stove down to medium. If the pot looks dry, add more olive oil.","images":[],"step":3},{"description":"Add the garlic and onion and cook for 3 minutes until soft.","duration":3,"images":[],"step":4},{"description":"Add the orange juice and lime juice, and scrape the bottom of the pot so the brown bits mix into the liquid.","images":[],"step":5},{"description":"Add tomato, beef stock, water and remaining spice mix. Mix, then return beef into pot.","images":[],"step":6},{"description":"Put the lid on, bring to a simmer then turn the stove down so it is bubbling gently, not rapidly.","images":[],"step":7},{"description":"Cook for 2 hours, then remove lid and simmer for another 30 minutes until beef is tender enough to shred. (Note 2 other cook methods).","images":[],"step":8},{"description":"Remove the beef from sauce, shred with 2 forks.","images":[],"step":9},{"description":"Leave the sauce to simmer with the lid off for 10 to 15 minutes to reduce and thicken to your taste. Adjust salt to taste. Optional: puree with stick blender to make it smooth (I do this for company)","duration":12.5,"images":[],"step":10},{"description":"Toss beef back into the sauce (can reserve some Sauce for drizzling on tacos if you want, there''s plenty).","images":[],"step":11},{"description":"Transfer beef into large dish and serve. See notes for suggestions.","images":[],"step":12},{"description":"To make tacos, serve the beef with warmed small tortillas, avocado slices, Pico de Gallo, shredded cheese, sour cream, lime wedges and extra cilantro/coriander leaves.","images":[],"step":13}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["beef-recipes","dietary","gluten-free-recipes","main-dishes","mexican-recipes","quick-and-easy","slow-cooker-recipes","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b81fef89157c', 'en', 'US', 'Marinated Roast Beef', 'Recipe video above. Use this marinade to transform economical roast beef into something special! It will infuse with flavour, add juiciness and make the beef tender. KEY TIP: internal temp of beef rises by 8C/14F while resting, so must take out of oven BEFORE desired internal temp, see Note 4. Marinade 2 - 3 days.', 'https://www.recipetineats.com/tachyon/2019/05/Marinated-Roast-Beef_7-1.jpg', 10, 70, 80, 6, '[{"id": "ing_bolar_blade_top_blade_roast_eye_of_round_roast_oyster_blade_roast", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_mustard", "quantity": {"value": 0.15, "unit": "jar of 200g"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.15, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.5, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_potato", "quantity": {"value": 3.0, "unit": "bag of 2kg"}}, {"id": "ing_carrot", "quantity": {"value": 4.0, "unit": "pack of 1kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.375, "unit": "kg"}}]', '[{"ingredients":["1.5kg / 3 lb Bolar Blade (pictured in post), Top Blade Roast, Eye of Round Roast, Oyster Blade Roast","1 tbsp olive oil"]},{"ingredients":["3 garlic cloves (, minced (2.5 tsp jar))","1 tbsp Worcestershire Sauce","2 tbsp dijon mustard","2 1/2 tbsp balsamic vinegar","1/2 cup soy sauce","1/4 cup olive oil","1 tbsp white sugar","2 tsp onion powder","1 tsp black pepper","2 tsp dried thyme","1 tsp dried rosemary"],"purpose":"Marinade (Note 2):"},{"ingredients":["3 potatoes (, cut into 5cm/2\" chunks)","4 carrots (, peeled cut into 4cm/1.7\" pieces)","Salt and pepper"],"purpose":"Vegetables (optional):"},{"ingredients":["1/4 cup flour","2 1/2 cups beef broth ((stock), low sodium)","3/4 tsp black pepper (, coarsely ground)"],"purpose":"Gravy (optional, Note 4)"}]', '[{"description":"Mix Marinade ingredients in a large ziplock bag.","images":[],"step":1},{"description":"Add beef, marinade for 2 days (24 hrs min, 3 days max).","images":[],"step":2},{"description":"Cooking:","images":[],"step":3},{"title":"De-chill","description":"Take beef out of fridge 1 hour prior.","images":[],"step":4},{"description":"Preheat oven to 240C/450F (both fan and regular ovens).","images":[],"step":5},{"title":"Toss vegetables","description":"Put the vegetables in an ovenproof skillet. Remove beef from marinade. Pour all the marinade onto the vegetables and toss. Top with the beef.","images":[],"step":6},{"title":"High temp roast","description":"Drizzle beef with oil, roast 20 minutes.","images":[],"step":7},{"title":"Keep roasting","description":"Turn oven down to 180C/350F (160C fan-forced), roast for a further 35 - 40 minutes or until a meat thermometer inserted into the centre registers 44°C / 111°F for medium rare (Note 3 for other doneness). Note - thinner and smaller pieces than pictured / per ingredients will cook faster, so check earlier!","images":[],"step":8},{"title":"Rest","description":"Remove beef onto plate, cover loosely in foil and rest for 20 - 30 minutes (internal temp will rise to 52°C / 125°F which is perfect medium rare!).","duration":25,"images":[],"step":9},{"title":"Brown vegetables","description":"Return vegetables to oven to brown a bit, if needed.","images":[],"step":10},{"description":"To serve, slice beef thinly. Serve roast veg and juices in the skillet OR make gravy (below)!","images":[],"step":11},{"description":"Gravy (optional)","images":[],"step":12},{"description":"Remove vegetables, leave juices in skillet. Skim excess off fat from surface, leave behind 2 tbsp.","images":[],"step":13},{"title":"Flour","description":"Place on medium high heat on stove. Add flour and stir for 1 minute.","duration":1,"images":[],"step":14},{"title":"Stock","description":"Slowly add beef stock while stirring. If needed, use whisk to remove lumps.","images":[],"step":15},{"title":"Thicken","description":"Bring to simmer for 2 minutes until thickens to gravy consistency. Stir in pepper and salt, if needed (taste to check). Serve with beef.","duration":2,"images":[],"step":16}]', '["gluten","mustard","shellfish","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["beef-recipes","iconic-dishes","roast-beef","roasts","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1203f6abcbd2', 'en', 'US', 'Schnitzel!', 'Recipe VIDEO above. Golden brown and extra crunchy schnitzel. No need to deep fry, just shallow fry it. Make schnitzel with pork, chicken, veal, beef or turkey! These are quite big - about 22 cm/ 9" long, but they are thin.', 'https://www.recipetineats.com/tachyon/2017/08/Schnitzel-11.jpg', 10, 15, 25, 4, '[{"id": "ing_pork", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_turkey_breast_cutlets", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 0.281, "unit": "loaf"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["600g / 1.2 lb boneless pork (4 steaks / boneless chops, about 150 g/5 oz each)","600g / 1.2 lb large chicken breasts (2 pieces,300g / 10 oz each)","600g / 1.2 lb veal or beef steaks (4 pieces, 150g / 5 oz each)","600g / 1.2 lb turkey breast cutlets (4 pre sliced pieces, 150g / 5 oz each)"],"purpose":"Choose ONE of these:"},{"ingredients":["Salt and pepper","3/4 cup flour","2 eggs","1 1/2 cups panko breadcrumbs (Note 1)","Oil for frying (canola, vegetable)"],"purpose":"Schnitzel:"}]', '[{"title":"Chicken breast prep","description":"cut in half horizontally to create two steaks.","images":[],"step":1},{"description":"Place the protein of choice on a work surface and cover with a sheet of baking paper or cling wrap. Use a rolling pin to pound to even thickness about 0.8 cm / 1/3\" thick (don''t pound too thin, hard to handle / might tear).","images":[],"step":2},{"description":"Sprinkle both sides of meat with salt and pepper.","images":[],"step":3},{"description":"Place flour in one dish, panko in another (or use a large tray for both like I did, see photos), and whisk eggs in a bowl.","images":[],"step":4},{"description":"Coat meat in flour, shake off excess. Dip into egg, shake off excess. Press into breadcrumbs, and turn, pressing to adhere, then transfer to plate. Repeat.","images":[],"step":5},{"description":"Heat 1.5cm / 3/5\" oil in a heavy based deep skillet over medium high heat.","images":[],"step":6},{"description":"Dip the end of a schnitzel in to check if the oil is hot enough - it should sizzle straight away (see video).","images":[],"step":7},{"description":"Carefully place 2 schnitzels in the oil and cook for 3 minutes until deep golden, turn then cook the other side for 3 minutes.","duration":3,"images":[],"step":8},{"description":"Transfer to a paper towel lined plate to drain excess oil. Repeat with remaining schnitzel.","images":[],"step":9},{"title":"Serve with lemon wedges","description":"I usually serve schnitzel plain like this. Or see note for Mushroom Gravy recipe. Also see note for potato rosti, pictured in post.","images":[],"step":10}]', '["egg","gluten"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Austrian","German","Western"],"categories":["beef-recipes","chicken-breast-recipes","chicken-recipes","deep-fried-recipes","dinner-tonight","main-dishes","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a62f6300e01c', 'en', 'US', 'Braised Beef Short Ribs in Red Wine Sauce', 'Recipe video above. This is the sort of food you''ll pay top dollar for at fine dining restaurants but is actually very easy to make at home. Wine provides complexity and depth of flavour so you only need a few ingredients! Oven is best but stove/slow cooker/pressure cooker/IP also work, directions in notes.', 'https://www.recipetineats.com/tachyon/2019/02/Slow-Cooked-Braised-Beef-Short-Ribs_3.jpg', 15, 180, 195, 5, '[{"id": "ing_beef_steak", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.667, "unit": "bottle of 750ml"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}]', '[{"ingredients":["5 - 6 beef short ribs (, 300-400g/10-14oz each (Note 1))","1.5 tsp each salt and pepper","2 tbsp olive oil","3 garlic cloves (, crushed)","1 large onion (, chopped (brown, yellow or white))","2 celery ribs (, chopped)","2 carrots (, chopped)","2 tbsp tomato paste","2 cups (500ml) dry red wine (Note 2)","2 cups (500ml) beef stock/broth, low sodium","2 sprigs thyme (optional)","2 bay leaves"]}]', '[{"description":"Preheat oven to 160°C/325°F.","images":[],"step":1},{"description":"Sprinkle beef all over with salt and pepper.","images":[],"step":2},{"description":"Heat oil in a large ovenproof pot over high heat. Add half the ribs and brown aggressively all over (~5 - 7 min in total). Remove and repeat with remaining ribs, then remove.","images":[],"step":3},{"description":"Turn heat down to medium. Add onion and garlic into the same pot and cook for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Add carrot and celery, cook for 5 minutes until carrot is softened and sweet.","duration":5,"images":[],"step":5},{"description":"Add tomato paste and cook for 1 minute.","duration":1,"images":[],"step":6},{"description":"Add wine, broth, thyme and bay leaves. Stir until tomato paste is dissolved.","images":[],"step":7},{"description":"Return beef into liquid, arranging them so they are submerged (Note 3).","images":[],"step":8},{"description":"Cover with lid and transfer to oven for 3 hours, or until the meat can easily be pried apart with forks. (Note 4 Other cook methods)","images":[],"step":9},{"description":"Remove beef carefully, keeping the meat on the bone. (Note 4) Cover to keep warm.","images":[],"step":10},{"description":"Strain all liquid in the pot, pressing juices out of the onion, carrot etc. (Optional - can skip if you don''t mind chunky sauce) Return sauce into pot, bring to simmer and stir. Adjust as necessary - simmer to reduce/thicken, add water to thin, season with salt and pepper if needed.","images":[],"step":11},{"description":"Place beef on serving plate, spoon over sauce. Serve!","images":[],"step":12}]', '[]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":[],"categories":["beef-recipes","iconic-dishes","slow-cooker-recipes","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0fc950cea8d9', 'en', 'US', 'Beef Stew', 'Recipe VIDEO above. Just a great, classic beef stew with meltingly tender beef smothered in a rich sauce. Be sure to brown the beef well - it''s key for the deep rich colour and flavour of the sauce! Great on the day, but even better the next day so make ahead if you can. Stove, oven, slow cooker or pressure cooker.', 'https://www.recipetineats.com/tachyon/2018/04/Beef-Stew_0.jpg', 15, 160, 165, 6, '[{"id": "ing_beef", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.667, "unit": "bottle of 750ml"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.16, "unit": "bunch"}}, {"id": "ing_potato", "quantity": {"value": 400.0, "unit": "bag of 2kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}]', '[{"ingredients":["1.2 kg / 2.4lb chuck beef (, cut into 3.5 cm / 1.5\" cubes (Note 1))","1 tsp each salt and pepper","3 tbsp olive oil (, divided)","1 large onion (, halved then cut into 1 cm / 2/5\" slices)","4 garlic cloves (, minced)","3 carrots (, cut into 2.5cm / 1\" pieces on the diagonal)","2 celery stalks (, cut into 2.5 cm / 1\" pieces)","1/3 cup / 50g flour","3 cups / 750ml beef broth / stock (, salt reduced)","2 cups / 500 ml red wine (, bold and dry (Cab Sauv, Burgundy, Merlot) (Note 2))","2 tsp Worcestershire Sauce","2 tbsp tomato paste","2 bay leaves (, fresh or dried)","4 sprigs thyme","400 g / 14 oz baby potatoes (, halved)","More salt and pepper (, to taste.)"]}]', '[{"description":"Sprinkle beef with salt and pepper.","images":[],"step":1},{"description":"Heat 1 1/2 tbsp oil in a large, heavy based casserole pot over high heat until just starting to smoke.","images":[],"step":2},{"description":"Add 1/3 of the beef and brown aggressively all over - about 4 minutes. Remove to bowl, repeat with remaining beef, adding more oil if required.","images":[],"step":3},{"description":"Turn down heat to medium high. Add 1 tbsp oil if required. Add onion and garlic, cook for 2 minutes until onion is softened slightly and golden on the edge.","duration":2,"images":[],"step":4},{"description":"Add carrot and celery, stir for 1 minute to coat in flavours.","duration":1,"images":[],"step":5},{"description":"Sprinkle flour evenly across surface, then stir to coat.","images":[],"step":6},{"description":"Add broth, red wine, tomato paste and Worcestershire sauce. Stir to dissolve tomato paste and flour into liquid.","images":[],"step":7},{"description":"Add cooked beef (including any juices), thyme, bay leaf and potato. Stir. Water level should almost fully cover everything (see video), if not, add a touch of water.","images":[],"step":8},{"description":"Bring to simmer, then adjust heat to low / medium low so it''s simmering gently. (Note 3 for other cooking methods)","images":[],"step":9},{"description":"Cover and cook for 1 hour 45 minutes or until beef is pretty tender (check with 2 forks at 1.5 hrs).","images":[],"step":10},{"description":"Remove lid and simmer for further 30 minutes or until sauce reduces slightly. It should be like a thin gravy (see video) and beef should now be very tender.","images":[],"step":11},{"description":"Season to taste with salt and pepper.","images":[],"step":12},{"description":"Serve over creamy mashed potato with a sprig of fresh thyme for decoration or a sprinkle of parsley (Note 4).","images":[],"step":13}]', '["gluten"]', '[]', '{"mealType":["dinner"],"cuisine":[],"categories":["beef-recipes","dinner-tonight","main-dishes","one-pot-recipes","quick-and-easy","slow-cooked-fall-apart","slow-cooker-recipes","stews","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d2c740108b09', 'en', 'US', 'Homemade Pastrami Without a Smoker', 'Recipe video above. This is an easy homemade Pastrami for all the poor sods like myself who don''t live around the corner from a New York Jewish deli. Tender, juicy and with the signature pastrami spice crust, this is astonishingly straight forward to make - and is outrageously good!ALSO - use the pastrami to make homemade Rebuen sandwiches!', 'https://www.recipetineats.com/tachyon/2014/05/Homemade-Pastrami-slices.jpg', 20, 660, 680, 6, '[{"id": "ing_beef", "quantity": {"value": 1.814, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.2, "unit": "jar of 50g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_mustard", "quantity": {"value": 0.037, "unit": "jar of 200g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_liquid_smoke", "quantity": {"value": 2.0, "unit": "unit"}}]', '[{"ingredients":["4 lbs / 2kg good corned beef, with a thick fat cap (Note 1)"]},{"ingredients":["4 tbsp fresh coarsely ground black pepper","2 tbsp coriander powder","1 1/2 tsp mustard powder","1 tbsp brown sugar","1 tbsp smoked paprika","2 tsp garlic powder","2 tsp onion powder","2 tbsp liquid smoke (optional)"],"purpose":"Spice Mix:"}]', '[{"description":"Mix Spice Mix and spread out on a tray. Pat beef dry then roll in Spice Mix, coating well all over. Sprinkle with liquid smoke it using (I rarely use this).","images":[],"step":1},{"description":"Place beef fat cap side down and wrap in a large sheet of foil. Repeat again with another sheet of foil and flip the beef so the fat cap is on the top.","images":[],"step":2},{"description":"Place rack in slow cooker (Note 2), place beef on rack. Slow cook for 10 hours on low or electric pressure cook for 1 hour 40 minutes (see notes for oven).","images":[],"step":3},{"description":"Remove beef, cool then refrigerate for 6 hours +. Reserve juices in slow cooker.","images":[],"step":4},{"description":"Unwrap beef. Place rack on tray, place beef on rack. Bake 30 minutes at 180C/350F until spice crust is set.","images":[],"step":5},{"title":"Remove from oven, slice thinly","description":"pastrami will be tender. Place some pastrami in a dish, spoon over a bit of reserved juices. Cover and microwave to warm (I like to add a slice of Swiss cheese).","images":[],"step":6},{"title":"New York Deli style Pastrami Sandwich","description":"Pile high on toasted rye bread slathered with plenty of mustard of choice. Serve with pickles on the side! Plus plain potato crisps (for the full deli experience!)","images":[],"step":7},{"title":"Rebuen sandwiches","description":"see this recipe.","images":[],"step":8}]', '["mustard"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["American"],"categories":["beef-recipes","iconic-dishes","main-dishes","quick-and-easy","sandwiches-and-sliders","slow-cooker-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_46e230f6c472', 'en', 'US', 'Epic Chunky Beef and Mushroom Pie', 'Tender, fall apart chunks of beef with mushrooms in the most incredible gravy ever. The secret ingredient - Dried Porcini Mushrooms! They add a savoury earthiness that can''t be replicated and takes this pie to the next level.', 'https://www.recipetineats.com/tachyon/2017/06/Beef-Mushroom-Pie-6.jpg', 15, 150, 165, 6, '[{"id": "ing_mushroom", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_beef", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_dark_ale", "quantity": {"value": 300.0, "unit": "unit"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.3, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_bacon", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_sheet_puff_pastry", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}]', '[{"ingredients":["20 g / 0.7 oz dried porcini mushrooms (slices, whole or chopped) (Note 1)","1 ¼ cups / 312 ml boiled water","1 kg / 2 lb chuck beef (, cut into 2.5cm/1” cubes (Note 2))","1 - 2 tbsp vegetable oil","2 garlic cloves (, minced)","1 onion (, finely chopped)","1 celery (, finely chopped)","1 carrot (, finely chopped)","3 carrots (, halved lengthwise then cut into 1.5cm/ 3/5” chunks)","1/3 cup flour (any)","300 ml / 10 oz dark ale (or substitute with red wine, Guinness or more beef stock)","2 cups / 500 ml beef stock","3 sprigs thyme or 1 tsp dried thyme leaves","2 bay leaves (, fresh or dried)","200 g / 7 oz bacon (, diced)","300 - 400g / 10 – 13 oz Swiss brown mushrooms (, larger ones halved)","1 – 2 sheets puff pastry (enough to cover pie)","1 egg yolk"]}]', '[{"description":"Place porcini in a bowl and add hot water. Leave to soak for at least 30 minutes. Strain mushrooms and reserve soaking liquid. Roughly chop porcini.","images":[],"step":1},{"description":"Sprinkle beef with salt and pepper.","images":[],"step":2},{"description":"Heat 1 tbsp oil in a large heavy based pot. Add half the beef and brown all over, then remove and repeat with remaining beef. Set beef aside.","images":[],"step":3},{"description":"Turn stove down to medium low. If the pot is looking dry, add more oil. Add onion and garlic, cook for 2 minutes. Add finely chopped carrots and celery, cook for 6 minutes or until softened and sweet (taste test!). Add carrot chunks and cook for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Add flour and stir through.","images":[],"step":5},{"description":"Add ale, beef stock, and stir to dissolve the flour.","images":[],"step":6},{"description":"Add thyme, bay leaves, porcini, reserved porcini soaking liquid (don’t tip in gritty bits settled at bottom) and cooked beef. Turn heat up slightly, mix, bring to simmer, then cover. Adjust heat so it is simmering gently, not energetically.","images":[],"step":7},{"description":"Cook for 1 hr 45 minutes or until beef is tender. (See video)","duration":60,"images":[],"step":8},{"description":"Meanwhile, cook bacon in a skillet over high heat until golden. Remove and reserve bacon drippings in pan. Add mushrooms and cook for 5 minutes until golden all over. Return bacon into skillet, toss to coat mushrooms, then stir through stew.","duration":5,"images":[],"step":9},{"description":"Simmer stew, uncovered, for 15 minutes until mushrooms are tender. Then remove from stove and cool.","duration":15,"images":[],"step":10},{"description":"To cook:","images":[],"step":11},{"description":"Preheat oven to 200C/390F.","images":[],"step":12},{"description":"Pour stew into a pie dish, even out surface. Pictured pie dish is 24 x 20 x 4.5 cm / 10 x 8 x 1.8\" (1.5L / 1.5 Qt) - see Notes for more conversions.","images":[],"step":13},{"description":"Top with puff pastry (if too big, just fold the ends in), brush with egg yolk. Cut a few slits in the surface then bake for 30 – 35 minutes until deep golden and the filling is piping hot in the middle (stick a knife in to check).","duration":32.5,"images":[],"step":14},{"description":"Rest for 5 minutes before serving!","duration":5,"images":[],"step":15}]', '["egg","gluten"]', '[]', '{"mealType":["dinner"],"cuisine":[],"categories":["beef-recipes","iconic-dishes","main-dishes","mushroom-recipes","slow-cooked-fall-apart","slow-cooker-recipes","stews","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eea747ed0c94', 'en', 'US', 'Shredded Beef Burritos', 'Crispy burritos filled with juicy Mexican Shredded Beef with a rich sauce, Mexican red rice and cheese. These are MADE for freezing - perfect standby meal! This recipe is for 8 burritos. However, 1 batch of Mexican Shredded Beef makes enough for around 15 burritos. If you aren''t freezing the burritos, feel free to add other things inside such as avocado, fresh salsa, pico de gallo, lettuce and tomato! (These are not suitable for freezing which is why I don''t use them)', 'https://www.recipetineats.com/tachyon/2015/09/Beef-Burritos_600px_1-Featured.jpg', 15, 10, 25, 8, '[{"id": "ing_tortillas", "quantity": {"value": 1000.0, "unit": "pack of 8"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_beef", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 300.0, "unit": "pack"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_black_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}]', '[{"ingredients":["8 large extra soft flour tortillas (10\"/26cm)","1 1/2 to 2 cups shredded cheese (I used Monterey Jack)","3 to 4 cups Mexican Shredded Beef plus sauce (, tossed or separated (Note 1))","2 cups Mexican Red Rice","400g/14oz can corn kernels (, drained)","400g/14oz can black beans (, drained)"]}]', '[{"description":"Microwave half the tortillas very briefly to warm them up (15 seconds or so). This ensures they don''t crack when you roll them.","images":[],"step":1},{"title":"Place 1 tortilla on a workbench","description":"cover the rest with a tea towel to keep them warm.","images":[],"step":2},{"description":"Place cheese down the middle of the tortilla, then top with 1/3 cup of beef, some corn, beans, then 1/4 cup rice.","images":[],"step":3},{"description":"Roll the burrito up. (Note 2) Wrap in foil to hold it together.","images":[],"step":4},{"description":"If you are serving it immediately, heat a skillet over medium heat. Cook the burritos for around 4 to 5 minutes on each side to make the tortilla brown and heat the inside through.","images":[],"step":5},{"description":"If freezing, place in the freezer. To reheat, you can either bake from frozen (with foil on) at 350F/180C for about 40 to 45 minutes, or thaw and cook in the skillet per above. You could microwave it (remove the foil) but I like my burritos a bit crispy!","images":[],"step":6}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["beef-recipes","burritos","dietary","gluten-free-recipes","mexican-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_763a53d45d79', 'en', 'US', 'Pide - Turkish Flat Bread / Pizza', 'Recipe video above. It''s hard to get great pide outside of Turkey. It''s hit and miss, even at many Turkish places. Solution: make it yourself! Pide is easier than you think, and it will tick all your pide boxes: pillowy soft bread inside with a crispy base, generous on the toppings. SO GOOD!Makes 2 pide around 40cm / 16" long. A generous meal for 2 people, normal meal for 3 people!TOPPINGS – Choose only 1. Each batch is enough to top 2 pides.', 'https://www.recipetineats.com/tachyon/2021/05/Platter-of-pide.jpg', 30, 30, 60, 2, '[{"id": "ing_yeast", "quantity": {"value": 1.0, "unit": "pack of 5 sachets"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 0.375, "unit": "loaf"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.2, "unit": "pack of 125g"}}, {"id": "ing_semolina", "quantity": {"value": 2.5, "unit": "pack"}}, {"id": "ing_topping_of_choice", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_sprinkling_finishes_of_choice", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 280.0, "unit": "bag of 250g"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_sausages", "quantity": {"value": 0.25, "unit": "pack of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_baharat_spice_mix", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_capsicum", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_cheese", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_sumac", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}]', '[{"ingredients":["1 tsp rapid rise / instant yeast (sub active dry yeast, Note 1)","1/2 tsp white sugar","2 tbsp + 2/3 cups very warm water (, (~40℃ /104℉, Note 2))","2 cups bread flour (sub all purpose/plain flour, Note 3)","3/4 tsp salt","1 1/2 tsp olive oil"],"purpose":"Dough (Makes 2 pide):"},{"ingredients":["150g / 5oz Turkish kasar cheese or mozzarella (Note 4)","1/2 tsp semolina (, optional (Note 10))","1 Topping of choice (each makes enough for 2 pides)","1 egg (optional, Note 13)","Sprinkling finishes of choice (listed below)"],"purpose":"Pide Assembling:"},{"ingredients":["2 tsp olive oil","1/2 onion (, finely diced)","280g / 10oz baby spinach","1/2 tsp cumin","1/2 tsp pepper","1/4 tsp salt (kosher / cooking salt)"],"purpose":"Spinach Topping:"},{"ingredients":["125g / 4oz Turkish sujuk sausage (sub chorizo, Note 5)"],"purpose":"Turkish Sausage Topping (Sujuk):"},{"ingredients":["1 tbsp olive oil","1/2 onion (, finely diced)","1 garlic cloves (, finely minced)","250g / 8oz lamb mince (or beef)","1 tsp tomato paste","1 tsp baharat spice mix (Note 6)","1/2 tsp cumin","1/8 tsp each salt and pepper","1/2 red capsicum / bell pepper (, finely diced)","1/2 tomato (, finely chopped)","1 tsp lemon juice"],"purpose":"Lamb Topping:"},{"ingredients":["4 tbsp Turkish tulum cheese or feta (, crumbled (Note 7))","Dried oregano","Sesame seeds (, toasted)","Sumac","Fresh coriander/cilantro leaves","Extra virgin olive oil"],"purpose":"Sprinkling Finishes – Choose (Note 11):"}]', '[{"title":"Bloom yeast","description":"Mix yeast with 2 tbsp warm water and sugar in a small bowl. Cover with cling wrap, leave for 10 minutes until foamy.","duration":10,"images":[],"step":1},{"title":"Make dough","description":"Mix together flour and salt in a large bowl or stand mixer bowl. Add the yeast mixture, olive oil and remaining 2/3 cups water. Mix together with a wooden spoon. Once the flour is mostly incorporated, switch to your hands and bring it together into a dough.","images":[],"step":2},{"title":"Knead","description":"Sprinkle work surface with 1 tbsp flour, then knead for 8 to 10 minutes by hand OR 3 minutes on speed 6 of a stand mixer. Dough is kneaded enough when it''s smooth and does not break when stretched - see photos video for before/after comparison. (Note 8)","duration":9,"images":[],"step":3},{"title":"Rise 1","description":"Shape into a ball. Smear inside of used bowl with a bit of olive oil, place dough inside. Cover with cling wrap and rise in warm place for 1.5 hours, or until doubled in size. (Note 9)","images":[],"step":4},{"title":"Rise 2","description":"Punch dough down to fully deflate, then divide into 2 equal pieces. Pull the sides down and tuck underneath so the top is smooth, underside is bunched up. Shape into ball and place on a lightly floured tray, smooth side up. Sprinkle surface with flour, then cover with damp tea towel. Rise 1 hour until doubled in size.","images":[],"step":5},{"description":"Assembling & Baking Pide:","images":[],"step":6},{"description":"Preheat oven to 240°C/465°F (220°C fan). Place shelf on the top and middle.","images":[],"step":7},{"title":"Roll","description":"Roll dough out on a lightly floured surface into an oval shape 40cm/16\" long and 20cm/8\" wide (widest point).","images":[],"step":8},{"title":"Prepare 2 trays","description":"Sprinkle 1/4 tsp semolina on each tray, 40cm/16\" long and 15cm/6\" wide. (Note 10)","images":[],"step":9},{"title":"Top Pide","description":"Place a rolled out dough on the semolina. Sprinkle with cheese, then sprinkle chosen Topping evenly across the surface, leaving a 2cm / 4/5\" border all around.","images":[],"step":10},{"title":"Fold dough","description":"Brush the ends with water. Pinch ends together to seal then fold the sides of the pide in.","images":[],"step":11},{"title":"Bake","description":"Bake 15 minutes, switching trays halfway, until the crust is golden.","images":[],"step":12},{"title":"Egg option","description":"Bake pide for 10 minutes, then crack the egg on top and return to oven for 5 minutes. This applies to all Pide - egg can be added for any of them!","duration":10,"images":[],"step":13},{"title":"Top & Serve","description":"Sprinkle with toppings of choice. (Note 11 for combos I used). Cut into 3cm / 1.3\" slices and serve!","images":[],"step":14},{"description":"Spinach Topping:","images":[],"step":15},{"description":"Heat oil in a skillet over medium heat. Cook onion for 3 minutes until translucent. Add spinach, cook until just wilted (add in batches if necessary). Stir in cumin, salt & pepper. Cool before using.","duration":3,"images":[],"step":16},{"description":"Turkish Sausage Topping:","images":[],"step":17},{"description":"Roughly chop, then turn the sausage into mince (ground meat) by using a Nutribullet or food processor.","images":[],"step":18},{"description":"Heat oil in a skillet over medium high heat. Cook garlic and onion for 3 minutes until soft. Add lamb and cook until it changes from pink to brown. Add tomato paste, Baharat, cumin, salt, pepper and cook for 3 minutes.","duration":3,"images":[],"step":19},{"description":"Add capsicum, tomato and lemon juice, then cook over medium heat until most of the liquid evaporates (a couple of minutes usually, though depends on juiciness of tomato). Cool before using.","images":[],"step":20}]', '["egg","gluten","milk","sesame"]', '["high_protein"]', '{"mealType":["dinner","snack"],"cuisine":["Middle Eastern","Turkish"],"categories":["breads","iconic-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9bbbfe4c3804', 'en', 'US', 'Homemade sausage patties', 'Recipe video above. This is your favourite pork sausage in patty form. It''s so easy - just pork mince (ground pork) mixed with a spice blend. Great to make ahead and freeze, then cook up on demand.Serve for dinner with garlic rice and steamed green beans tossed with French Dressing. O make burgers! Also great for breakfast with scrambled eggs on toast. (I''d still use ketchup :) )', 'https://www.recipetineats.com/tachyon/2023/09/Homemade-pork-sausage-patties_1.jpg', 10, 10, 20, 8, '[{"id": "ing_pork_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_sage", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_ketchup", "quantity": {"value": 1.0, "unit": "bottle of 500g"}}]', '[{"ingredients":["500g/ 1 lb pork mince (ground pork) (sub chicken, turkey)","1 tsp dried ground sage (secret ingredient! Note 1)","1/2 tsp dried thyme (, crushed with fingers (Note 2))","1 tsp onion powder (sub more garlic powder)","1/2 tsp garlic powder (sub more onion powder)","1 tsp black pepper","3/4 tsp cooking / kosher salt (or 1/2 tsp table salt)","1/2 tsp sugar (optional)"],"purpose":"Sausage patties:"},{"ingredients":["2 tbsp olive oil","Ketchup for serving"],"purpose":"Cooking & serving:"}]', '[{"title":"Make patties","description":"Place sausage pattie ingredients in a bowl and mix well with your hands. Divide into 8 and form 1 cm / 0.4\" thick patties. Make a shallow dent in the middle of the surface - this prevents the patties from doming as they cook.","images":[],"step":1},{"title":"Cook 4 minutes","description":"Heat 1 tablespoon of oil in a large non stick pan over medium high heat. Cook half the patties for 2 minutes on each side until golden. Transfer to a paper towel lined plate. Heat remaining oil and cook remaining patties.","duration":2,"images":[],"step":2},{"description":"Serve with ketchup! (See recipe card intro for serving ideas)","images":[],"step":3}]', '[]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["breakfast","dinner"],"cuisine":["Western"],"categories":["breakfast-recipes","mains","pork","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9ac49af702b7', 'en', 'US', 'Extra Crispy Corn Fritters', 'Recipe video above. Sweet pops of fresh corn on the inside, very crispy on the outside. These heavenly fritters are light on batter, heavy on the corn – just the way they should be! Makes a lovely meal for 2 with a leafy green salad on the side, or a starter for 4.', 'https://www.recipetineats.com/tachyon/2020/05/Crispy-Corn-Fritters_0-copy.jpg', 10, 20, 30, 8, '[{"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.094, "unit": "pack of 400g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.006, "unit": "tub of 200g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_corn", "quantity": {"value": 0.75, "unit": "can of 400g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_green_onion", "quantity": {"value": 2.25, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}]', '[{"ingredients":["1/4 cup flour (, plain / all purpose)","1/4 cup cornflour / cornstarch","1/4 tsp baking soda (or 3/4 tsp baking powder)","1 egg","2 tbsp milk (any type)","2 cups fresh corn kernels (, raw (2 cobs) (canned or frozen also fine - Note 1))","1/2 cup parmesan (, finely grated)","3/4 cup green onions (, sliced)","1/2 cup coriander/cilantro (, roughly chopped (sub more green onion))"]},{"ingredients":["1/2 cup vegetable oil","Oil spray"],"purpose":"For cooking:"},{"ingredients":["Avocado sauce","Sour cream, ketchup (don’t judge until you’ve tried it!)"],"purpose":"Serving – choose:"}]', '[{"description":"Preheat oven to 120°C / 250°F and set a wire rack on a baking tray.","images":[],"step":1},{"description":"Place flour, cornflour and baking soda in a bowl, mix to combine.","images":[],"step":2},{"description":"Add egg and milk, mix until incorporated (batter will be lumpy and thick).","images":[],"step":3},{"description":"Add corn, parmesan, green onions and coriander. Mix until all the corn is evenly coated in batter.","images":[],"step":4},{"description":"Add enough oil into the skillet so it just covers the base. Heat over medium high heat.","images":[],"step":5},{"description":"Spray the underside of a spatula with oil (so batter won’t stick when you flatten).","images":[],"step":6},{"description":"Place 1/4 cup batter into skillet (ice cream scooper with lever is handy), then flatten to 1cm thick. Repeat with 2 or 3 more, but don’t crowd the skillet.","images":[],"step":7},{"description":"Cook 3 minutes until deep golden and crisp, then flip and cook the other side for 2 – 3 minutes.","duration":2.5,"images":[],"step":8},{"description":"Transfer to rack and keep warm in oven. Repeat with remaining fritters, using more oil as necessary.","images":[],"step":9},{"description":"Serve with sauce of choice for dunking!","images":[],"step":10}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["breakfast","dinner","snack"],"cuisine":["Western"],"categories":["breakfast-recipes","fritters-tots-and-similar","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_082af9008802', 'en', 'US', 'Really Quick Broccoli Pasta', 'Recipe video above. This is a great emergency meal OR carb + veg side for all those times when your cupboards are bare except for broccoli, pasta, and some kind of cheese. It''s saucy without using tons of oil, and there''s loads of sub options. Quick and utterly scrumptious - loaded with tons of broccoli!', 'https://www.recipetineats.com/tachyon/2019/04/Broccoli-Pasta_5.jpg', 5, 10, 15, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_broccoli", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_mixed_herbs", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}]', '[{"ingredients":["350g / 12 oz dried short pasta (I used small shells)","2 broccoli heads (BIG!)","1 cup shredded cheese (or more!)"]},{"ingredients":["2 tsp lemon zest","2 tbsp lemon juice (or more!)","5 tbsp extra virgin olive oil","1/3 cup parmesan (, finely grated)","2 garlic cloves (, minced)","1 tsp mixed dried herbs (or fresh!)","1/2 tsp+ red pepper flakes (add more if you want spicy!)","1 tsp sugar","3/4 tsp salt","1/2 tsp pepper"],"purpose":"Pasta Sauce (Notes for subs):"},{"ingredients":["More parmesan"],"purpose":"Serving:"}]', '[{"title":"Cook pasta","description":"Boil a large pot of water with 2 tsp salt, add pasta.","images":[],"step":1},{"description":"While pasta is cooking:","images":[],"step":2},{"title":"Chop broccoli","description":"Chop broccoli into small florets.","images":[],"step":3},{"title":"Cook broccoli: Add broccoli into water 1","description":"2 minutes before pasta is cooked.","images":[],"step":4},{"title":"Sauce ingredients in jar","description":"Place Sauce ingredients in a jar with lid.","images":[],"step":5},{"title":"Reserve pasta water","description":"SCOOP OUT 1 cup pasta cooking water just before draining. Then drain and return pasta back into same pot on turned off stove.","images":[],"step":6},{"title":"Add pasta water into Sauce","description":"Add 1/2 cup pasta water to Pasta Sauce jar, shake well.","images":[],"step":7},{"title":"Add Sauce & Cheese to pasta","description":"Pour Sauce and add cheese into pot with pasta.","images":[],"step":8},{"description":"Stir then serve! Stir vigorously, adding more pasta water if required. Add more salt and pepper if required. Serve immediately, garnished with parmesan.","images":[],"step":9}]', '["gluten","milk"]', '["high_protein","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["broccoli-recipes","dinner-tonight","emergency-recipes","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy","side-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8986b538e293', 'en', 'US', 'Broccoli Chicken Fritters', 'Recipe video above. This combination of juicy chicken pieces and tender broccoli inside a fritter with a crispy golden crust is seriously delicious! For a version made with ground chicken (mince), try these Baked Chicken Broccoli Patties.', 'https://www.recipetineats.com/tachyon/2019/04/Broccoli-Chicken-Fritters_1.jpg', 10, 20, 30, 16, '[{"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.2, "unit": "tub of 500g"}}, {"id": "ing_ketchup", "quantity": {"value": 0.06, "unit": "bottle of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["1 large head broccoli (, cut into florets)","500g / 1lb chicken breast or thigh (, cut into 0.8cm / 1/3\" pieces)","1/2 cup (75g) flour (any type)","1/2 cup (50g) parmesan cheese (, grated or shredded)","2 eggs","2 garlic cloves (, minced)","3/4 tsp salt","Pepper"],"purpose":"Fritters:"},{"ingredients":["3 - 4 tbsp olive oil"],"purpose":"Cooking:"},{"ingredients":["2/3 cup (165g) sour cream or Greek yogurt","2 tbsp ketchup","Squeeze of lemon (, plus more for serving (optional))"],"purpose":"Pink Sauce – mix:"}]', '[{"description":"Preheat oven to 100C/210F.","images":[],"step":1},{"description":"Steam broccoli until tender, then roughly chop. (Note 1)","images":[],"step":2},{"description":"Add broccoli and remaining Fritter ingredients in a bowl and mix well.","images":[],"step":3},{"description":"Add enough oil in skillet to cover base. Heat to medium high.","images":[],"step":4},{"description":"Dollop 1/4 cup mixture into skillet, then pat down. (Note 2)","images":[],"step":5},{"description":"Cook 2.5 minutes until deep golden, then flip and cook for 2 minutes.","duration":2,"images":[],"step":6},{"description":"Transfer to rack, keep warm in oven.","images":[],"step":7},{"description":"Serve with Pink Sauce!","images":[],"step":8}]', '["egg","gluten","milk"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["broccoli-recipes","chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","fritters-tots-and-similar","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6f18a4b4bf95', 'en', 'US', 'One Pot Broccoli, Chicken and Rice Casserole', 'Recipe VIDEO above. Made from scratch, this tastes like a risotto but is so much more straight forward to make! A complete meal in one pot.', 'https://www.recipetineats.com/tachyon/2018/01/One-Pot-Chicken-Broccoli-Rice_7.jpg', 10, 20, 30, 5, '[{"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.6, "unit": "pack of 125g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 tbsp (30g ) unsalted butter","1 tbsp olive oil","1 onion (, finely chopped)","2 garlic cloves (, minced)","500g (1 lb) chicken thigh (, cut into bite size pieces (Note 1))","2.5 tbsp flour (or 1 ½ tbsp. cornflour / cornstarch)","2 cups (500 ml) milk (any, I use low fat)","2 cups (500 ml) chicken broth","1 1/4 cups (225g) long grain white rice (, uncooked (Note 2))","1 tsp dried thyme (or other herb of choice)","Salt and pepper","1 large head of broccoli, broken / cut into small florets (~400 - 500g / 14 oz - 1 lb) (Note 3)","2 cups (200g) shredded mozzarella or cheddar (or other cheese of choice) (Note 4)","Finely chopped parsley (, optional garnish)"]}]', '[{"description":"Melt butter and heat oil in a pot over high heat. Add onion and garlic, cook for 1 minute. Add chicken and cook until it changes from pink to white. (Note 5)","duration":1,"images":[],"step":1},{"description":"Turn stove DOWN to medium. Add flour and stir for 1 minute.","duration":1,"images":[],"step":2},{"description":"Add half the milk, stirring as you go, and once incorporated into the flour add the rest of the milk and stir.","images":[],"step":3},{"description":"Add broth, rice, thyme and a just pinch of salt and pepper.","images":[],"step":4},{"description":"Stir, bring to simmer, then cover. Turn down to medium low and cook for 12 minutes.","duration":12,"images":[],"step":5},{"title":"Remove lid","description":"there should still be liquid on the surface. Working quickly, add broccoli, push down so it’s partly submerged, cover and cook for a further 3 minutes until broccoli is just cooked.","images":[],"step":6},{"description":"Preheat grill/broiler. Remove lid and stir through half the cheese – don’t worry if it looks a bit too saucy, excess liquid gets sucked up in minutes (see video). Smooth surface, top with remaining cheese. Grill/broil until melted (or just put lid on and allow to melt with residual heat on turned off stove).","images":[],"step":7},{"description":"Serve immediately, garnished with parsley if desired.","images":[],"step":8}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["broccoli-recipes","casseroles-and-cosy-bakes","chicken-breast-recipes","chicken-recipes","dinner-tonight","one-pot-recipes","quick-and-easy","rice-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f93451a7e231', 'en', 'US', 'Cheesy Chicken Mince Fritters with Broccoli', 'Recipe video above. It''s hard to believe these fritters made with chicken mince are BAKED not FRIED! With almost an entire head of broccoli in them, these are juicy, cheesy and so irresistible. This makes 15 fritters about 6 cm / 2.25" wide, 1cm / 2/5" thick. Trying making burgers or meatballs!', 'https://www.recipetineats.com/tachyon/2017/08/Cheesy-Broccoli-Chicken-Fritters-6.jpg', 15, 25, 40, 4, '[{"id": "ing_chicken_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_broccoli", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.5, "unit": "pack of 125g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_yogurt", "quantity": {"value": 0.2, "unit": "tub of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.013, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["500 g / 1 lb chicken mince (ground chicken) (, or turkey or pork (Note 1))","1 garlic clove, (minced)","1 egg","¾ cup panko breadcrumbs","2 packed cups broccoli (, soft cooked & finely chopped (1 head)(Note 2))","¾ cup finely chopped shallots","1 1/2 - 2 cups shredded mozzarella (or other cheese of choice)","3/4 tsp salt (reduce to 1/2 tsp if using a flavoured cheese)(Note 3)","Black pepper"],"purpose":"Fritters:"},{"ingredients":["Oil spray"],"purpose":"Cooking:"},{"ingredients":["2/3 cup plain yoghurt","1/8 tsp EACH dried dill, parsley and chives","¼ tsp onion powder","½ garlic clove, minced","1 - 2 tsp extra virgin olive oil","Squeeze of lemon juice, (optional)"],"purpose":"Yoghurt Ranch Sauce (optional):"}]', '[{"description":"Preheat oven to 200C/390F. Line a baking tray with baking paper (or spray with oil).","images":[],"step":1},{"description":"Place Fritter ingredients in a bowl, mix to combine.","images":[],"step":2},{"description":"Measure out about ¼ cup of mixture and pat into fritter shapes about 6 cm / 2.25\" wide, 1cm / 2/5\" thick (they shrink a bit and become thicker).","images":[],"step":3},{"description":"Place on tray. Spray the top (generously) with oil.","images":[],"step":4},{"description":"Bake for 15 minutes, flip, spray with oil again then bake for a further 8 - 10 minutes until golden on top. Serve immediately with Sauce.","duration":15,"images":[],"step":5},{"title":"Sauce","description":"Mix ingredients together. Add salt and pepper to taste. Set aside for 20+ minutes.","images":[],"step":6}]', '["egg","milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["broccoli-recipes","chicken-mince-recipes","chicken-recipes","dinner-tonight","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_09f462259731', 'en', 'US', 'Ultra Lazy Creamy Chicken and Broccoli Pasta Bake', 'Recipe video above. One for all those busy nights - a complete HEALTHY meal all made in one baking dish. 5 minutes prep, pop it in the oven, then out comes perfectly cooked chicken and broccoli pasta bake smothered in a creamy sauce. Serves 4 - 5.', 'https://www.recipetineats.com/tachyon/2017/07/Ultra-Lazy-Creamy-Chicken-Pasta-Bake-2.jpg', 10, 35, 45, 5, '[{"id": "ing_chicken", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}]', '[{"ingredients":["400g / 14 oz chicken tenderloin (raw) (, breast or thigh, cut into 1.5cm / 3/5\" pieces)","Salt and pepper","1 tsp dried thyme (or other herbs and/or spices of choice)","250g / 8 oz spiral pasta, uncooked (See Note 1 for other shapes)","1/4 cup flour (all purpose / plain)","1 1/2 cups chicken broth/stock (, warmed)","2 cups milk (, warmed (any fat %))","1 large garlic clove (, minced)","2 tbsp / 30g unsalted butter (, recommended but optional)","1 large broccoli ( or 2 medium broccoli or cauliflower, broken into small to medium florets (Note 2 for subs))","1 1/2 cups (tightly packed) shredded cheddar or colby cheese (or tasty cheese, pizza mix etc, Note 3)"]}]', '[{"description":"Preheat oven to 200°C/390°F (180°C fan-forced).","images":[],"step":1},{"description":"Sprinkle chicken with salt (be generous), pepper and thyme, toss to coat.","images":[],"step":2},{"description":"Spread pasta in a 23 x 33cm / 9 x 13\" baking dish. Sprinkle flour all across the surface (don''t dump in clump else it won''t dissolve). Pour over milk and broth, add garlic and butter. Stir.","images":[],"step":3},{"description":"Spread chicken over the top, then broccoli.","images":[],"step":4},{"description":"Cover with foil, bake for 15 minutes (or 20 minutes if milk & broth were cold).","duration":15,"images":[],"step":5},{"description":"Remove foil, STIR WELL. Add most of the cheese, then STIR WELL again. Top with remaining cheese.","images":[],"step":6},{"title":"Return to oven. Bake for 15","description":"20 minutes until top is golden and sauce is thickened (See note 4 for troubleshooting).","duration":17.5,"images":[],"step":7},{"description":"Stand for a few minutes then serve immediately!","images":[],"step":8}]', '["gluten","milk"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["broccoli-recipes","casseroles-and-cosy-bakes","chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","emergency-recipes","low-calorie-recipes","main-dishes","one-pot-pasta-recipes","one-pot-recipes","pasta-bakes","pasta-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1a81fbb46188', 'en', 'US', 'Baked Macaroni Cheese with Chicken & BROCCOLI', 'EASY baked Mac and Cheese loaded with chicken and broccoli - a COMPLETE meal all made in one pot! This recipe requires the specific ratio of water, milk and macaroni that I''ve specified in the recipe. Don''t be alarmed at how much liquid there is when you take it out of the oven before broiling/grilling the top. You will be surprised how quickly the liquid evaporates into a thick sauce. Watch the VIDEO to see how easy this is to make!', 'https://www.recipetineats.com/tachyon/2016/02/Baked-Macaroni-Cheese-Chicken-Broccoli_1.jpg', 15, 30, 45, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_panko", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}]', '[{"ingredients":["1 tbsp olive oil","1 lb / 500g skinless chicken breast or thigh fillets (, cut into bite size pieces)"]},{"ingredients":["3 tbsp butter","2 garlic cloves (, minced)","1 small onion (, finely chopped)","4 tbsp plain flour","2 1/2 cups milk (, low fat)","1 cup water","1 tsp salt","Black pepper","2 cups macaroni / elbow pasta (Note 1)","1 large head of broccoli (, broken into florets (or 1 1/2 smaller ones))","1 1/2 - 2 cups grated cheese (cheddar, tasty or gruyere)"],"purpose":"Mac N Cheese"},{"ingredients":["1/4 cup panko (or ordinary breadcrumbs)","2 tbsp parmesan cheese"],"purpose":"Topping"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Heat oil in a deep heavy based skillet or dutch oven over high heat. Add chicken and cook until just cooked - it''s fine if it''s still raw inside. Remove chicken into a bowl. (Note 2)","images":[],"step":2},{"description":"Reduce heat to medium and melt butter. Add garlic and onion and saute for 5 minutes until onion is translucent. Add flour and cook for 1 minute.","duration":5,"images":[],"step":3},{"description":"Pour in half the milk and whisk it in so the flour butter mixture melts. It should thicken quite quickly - around 30 seconds. Pour the remaining milk in, whisking constantly, then add the water, salt and pepper.","images":[],"step":4},{"description":"Turn the heat up to medium high and cook, whisking occasionally, for around 3 to 5 minutes until you start seeing steam rising from the white sauce when you whisk it.","images":[],"step":5},{"description":"Add the macaroni and chicken, stir, then top with broccoli.","images":[],"step":6},{"description":"Place the lid on and bake for 20 minutes.","duration":20,"images":[],"step":7},{"description":"Remove from the oven, switch oven to broiler/grill on high.","images":[],"step":8},{"description":"Remove lid (Note 3), stir through cheese, then sprinkle over panko and parmesan. (Will still look bit watery at this stage).","images":[],"step":9},{"description":"Place pot under the broiler/grill for 5 minutes, or until top is golden.","duration":5,"images":[],"step":10},{"description":"Remove, then let it stand for 5 minutes before serving (sauce thickens quickly).","duration":5,"images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["broccoli-recipes","casseroles-and-cosy-bakes","chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-bakes","pasta-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ce2d27eb46ee', 'en', 'US', 'Creamy Bacon, Chicken and Broccoli Strata (Bread Bake)', 'A creamy chicken and broccoli bake made from scratch topped with bread and panko to make it extra crunchy! It''s like a pasta bake / strata (savoury bread pudding), just as filling but with a lot less carbs.', 'https://www.recipetineats.com/tachyon/2014/08/Creamy-Bacon-Chicken-Broccoli-Bake-1.jpg', 15, 40, 55, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 2.0, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_broccoli", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 0.5, "unit": "block of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 3.0, "unit": "loaf"}}, {"id": "ing_panko", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["250 g / 8 oz chicken breast fillet (, cut into small bite size pieces)","2 bacon rashers (, diced)","1 small brown onion ((or 1/2 large), diced)","4 packed cups (300g/10oz) broccoli florets","1 garlic clove (, minced)","1/2 tbsp olive oil"]},{"ingredients":["40 g / 1.3 oz / 3 tbsp butter","1/2 cup flour","1/2 cup grated cheese (tasty, cheddar, gruyere or any other good melting cheese)","3 cups low fat milk","1 tsp garlic powder","1/2 tsp salt","Black pepper"],"purpose":"Béchamel Sauce"},{"ingredients":["3 to 4 slices of thick slice white sandwich bread (, cut into 1cm / 1/3\" cubes (note 1))","1/4 cup panko (or breadcrumbs)","2 tbsp parmesan cheese (, grated)","Fresh parsley (, finely chopped, to garnish (optional))"],"purpose":"Topping"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Chicken Mixture","images":[],"step":2},{"description":"Heat olive oil in a deep non stick fry pan over high heat. Add onion, minced garlic and bacon. Saute for 2 to 3 minutes until onion is translucent and bacon is starting to brown.","duration":2.5,"images":[],"step":3},{"description":"Add chicken and cook just until the outside of the chicken turns white (do not cook through). By this time, the onion should be caramelised and bacon should be crisp.","images":[],"step":4},{"description":"Remove from pan onto paper towel to drain.","images":[],"step":5},{"description":"Make the Béchamel Sauce (see notes for tips)","images":[],"step":6},{"description":"Lower heat to medium. Wipe pan clean and return to heat.","images":[],"step":7},{"description":"Melt butter, then add flour and whisk constantly for 1 1/2 minutes.","images":[],"step":8},{"description":"Add 1 1/2 cups of milk, whisking constantly, until it is well combined and lump free. It should be very thick.","images":[],"step":9},{"description":"Add remaining milk and whisk to combine well. Cook for 2 minutes or so, whisking constantly, until it thickens to the consistency of pouring cream (not whipped cream).","duration":2,"images":[],"step":10},{"description":"Remove from heat and add garlic powder, cheese, salt and pepper. Whisk until the cheese is melted and the sauce is smooth. Do a taste test and add more salt if you want.","images":[],"step":11},{"description":"Assemble and Bake","images":[],"step":12},{"description":"Place broccoli in baking dish (see notes for size), then top with chicken onion mixture. Pour over half the béchamel sauce.","images":[],"step":13},{"description":"Top with bread cubes, then drizzle over the remaining béchamel sauce as evenly as possible over the bread cubes. Use an egg flip to squash the bread cubes down - this helps disperse the béchamel sauce throughout the bake.","images":[],"step":14},{"description":"Sprinkle over panko and parmesan cheese.","images":[],"step":15},{"description":"Place in oven and bake for 20 to 25 minutes, until golden brown.","duration":22.5,"images":[],"step":16},{"description":"To Serve","images":[],"step":17},{"description":"Let stand for 5 minutes before serving. Garnish with finely chopped parsley, if desired.","duration":5,"images":[],"step":18}]', '["fish","gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["broccoli-recipes","casseroles-and-cosy-bakes","chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5a9b826ec5de', 'en', 'US', 'Crispy Prawn Burgers (Shrimp)', 'Recipe video above.', 'https://www.recipetineats.com/tachyon/2025/09/Prawn-burgers_5.jpg', 16, 4, 20, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 0.75, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 4.5, "unit": "head"}}, {"id": "ing_gherkins", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_bang_bang_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["400g / 14oz fresh OR 500g/1lb frozen raw peeled prawns (shrimp) (Note 1)","1 garlic (, minced)","1/4 cup green onion (, finely sliced)","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Prawn patties"},{"ingredients":["1 egg (, lightly whisked with a fork)","1/2 cup plain flour (all-purpose flour)","1 1/4 cups panko breadcrumbs","1/2 cup olive oil (, or any neutral flavoured oil (vegetable, canola etc))"],"purpose":"Crumbing:"},{"ingredients":["4 brioche buns (10-12cm / 4-5\" wide) (or other soft white buns, lightly toasted)","1 1/2 cups shredded iceberg lettuce (or cos lettuce (romaine))","Gherkins (, finely sliced)","1 1/2 cups shredded iceberg lettuce (or cos lettuce (romaine))"],"purpose":"Burgers:"}]', '[{"description":"Blitz half prawns and garlic, mix with rest of pattie ingredients. Roll into balls, dredge in flour, egg, then flatten into patty in panko, flip to coat. Fry 4 minutes until golden, assemble burgers.","images":[],"step":1},{"title":"Thaw","description":"If using frozen prawns, thaw thoroughly and discard excess water (you lose ~20% in weight in water), then chop into 8mm / 1/3\" pieces.","images":[],"step":2},{"title":"Blitz","description":"Put half the prawns and garlic in a jug large enough to fit the head of a stick blender. Blitz until it becomes a paste (no need to puree 100% perfectly).","images":[],"step":3},{"title":"Prawn patties mixture","description":"Scrape into a bowl. Mix in the chopped prawns green onion, salt and pepper. The mix will be sloppy, but don’t worry - it firms up as it cooks, and the shaping method handles the softness. :)","images":[],"step":4},{"title":"Dredging station","description":"Put the egg and flour in separate shallow bowls, and the panko on a plate (need squishing space).","images":[],"step":5},{"title":"Crumb","description":"Using slightly wet hands, roll mixture into 4 balls. Coat ball in flour, then egg (let the excess drip off), then press down into a patty in the panko. Make it a smidge larger than the size of your bun (it shrinks a wee bit). Flip using a spatula, press down to adhere panko and make sure to coat the sides. Remove with a spatula onto a plate, repeat with remaining balls.","images":[],"step":6},{"title":"Cook","description":"Heat the oil in a large non-stick pan over medium high heat. Cook patties for 2 minutes on each side until golden, then remove onto a paper towel lined tray.","duration":2,"images":[],"step":7},{"title":"Assemble burgers as follows","description":"smear base with sauce. Top with prawn patty, cover with gherkins, pile on lettuce. Smear lid with sauce, place on top, EAT! (Homemade fries on the side are the ultimate sidekick but were out of reach today, so I used frozen).","images":[],"step":8}]', '["egg","gluten","shellfish"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Australian","Western"],"categories":["burger-recipes","prawns-shrimp","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cf4281819efc', 'en', 'US', 'Ultra Crunchy Fried Chicken Burger', 'Recipe video above. KFC, eat your heart out! Our Fried Chicken Burger is way crunchier than yours, the chicken is way juicier and it tastes way better! The trick is to mix a bit of marinade into the flour coating - this creates lumps that fries up into an awesome ultra crunchy crust. See my Fried Chicken recipe for ravings and musings about this method. (Thanks Kenji!)', 'https://www.recipetineats.com/tachyon/2023/09/Crispy-fried-chicken-burgers_5.jpg', 15, 15, 210, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 0.75, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_herkins_dill_pickles", "quantity": {"value": 0.002, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.25, "unit": "jar of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 1.25, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.094, "unit": "pack of 400g"}}, {"id": "ing_celery", "quantity": {"value": 0.025, "unit": "head"}}, {"id": "ing_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.006, "unit": "jar of 200g"}}, {"id": "ing_ginger", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.75, "unit": "L"}}]', '[{"ingredients":["2 x 250g/8oz chicken breast (I use this)","4 boneless thigh fillets"],"purpose":"Chicken choices:"},{"ingredients":["3/4 cup buttermilk (Note 1 for sub)","1 1/2 tsp cooking / kosher salt","1 large egg"],"purpose":"Marinade:"},{"ingredients":["4 soft buns (, split and lightly toasted (mine are 10cm/4\"))","2 - 3 cups iceberg lettuce (, finely sliced (or other leafy greens of choice))","2 tomatoes (, sliced (optional, sometimes I do))","2 gherkins / dill pickles (, sliced on an angle)"],"purpose":"Burgers:"},{"ingredients":["2/3 cup mayonnaise (, preferably whole egg)","3/4 tsp garlic (, finely grated (1 clove))"],"purpose":"Garlic mayo:"},{"ingredients":["3/4 cup flour (, plain / all purpose)","1/4 cup corn flour / cornstarch"],"purpose":"Crunchy coating:"},{"ingredients":["1/4 tsp celery salt (or heaped 1/8 tsp celery seed)","1/2 tsp sweet paprika","1/8 tsp cayenne pepper (inc to 1/2 tsp for spicy ZINGER burger!)","1/2 tsp onion powder","1 tsp garlic powder","1/4 tsp mustard powder","1/4 tsp ginger powder","1/2 tsp dried thyme","1/2 tsp dried oregano","1/2 tsp cooking salt / kosher salt","1 1/2 tsp black pepper"],"purpose":"Fried chicken seasoning:"},{"ingredients":["3 cups vegetable oil (or canola or peanut) (2.5cm/1\" depth in cooking vessel)"],"purpose":"To fry:"}]', '[{"description":"Shortform recipe:","images":[],"step":1},{"description":"Pound chicken to 1cm / 0.4\" thickness, trim, marinade 3 - 24 hrs. Mix coating and seasoning, mix in 2 tbsp marinade. Coat chicken, fry at 180°C/350°F for 4 min (don''t touch for first 90 sec). Assemble!","duration":4,"images":[],"step":2},{"description":"Full instructions:","images":[],"step":3},{"title":"Chicken","description":"Cover the chicken with a freezer bag or plastic sheet and pound to 1cm / 0.4\" even thickness. Trim to just a touch larger than the size of your bun. Save off-cuts for another use (stir fry - or Dozer, in my case!).","images":[],"step":4},{"title":"Marinade","description":"Whisk Marinade ingredients in a bowl. Add chicken, toss. Marinate in the fridge for 3 hours minimum, to overnight (don''t go beyond 24 hrs).","images":[],"step":5},{"title":"Garlic mayo","description":"Mix in a small bowl and refrigerate until required.","images":[],"step":6},{"title":"Prepare crunchy coating","description":"Mix flour, cornflour and Seasoning ingredients in a bowl. Drizzle over 2 tablespoons of the marinade, then use fingers to mix through to form lumps - when this sticks to the chicken, it fries up into awesome crunchy bits!!","images":[],"step":7},{"description":"Heat oil in a large heavy based pot over medium high heat to 180°C/350°F (Note 2).","images":[],"step":8},{"title":"Coat chicken","description":"Pick up a piece of chicken and allow excess marinade to drip off. Press to coat in flour coating. Shake off excess, then fry for 2 minutes on each side until golden. DO NOT TOUCH for the first 90 seconds to allow the coating to adhere. I fry 2 at a time. Drain on paper towels, cook remaining chicken.","duration":2,"images":[],"step":9},{"title":"Assemble","description":"Smear garlic mayo on the top and bottom of the buns. Pile lettuce on the base, top with tomato if using. Then chicken, gherkins and put the lid on. Sink your teeth into it immediately and enjoy!","images":[],"step":10}]', '["egg","gluten","mustard","peanuts"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["burger-recipes","chicken","chicken-breast-recipes","chicken-recipes","deep-fried-recipes","iconic-dishes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e2cec46ff1a0', 'en', 'US', 'Homemade Filet-O-Fish Burger (BAKED!)', 'Recipe video above. Tastes remarkably similar to McDonald''s with the added bonus that it''s bigger, it''s healthier and you know exactly what goes in it! Toasting the breadcrumbs guarantees beautiful golden, truly crunchy fish fillets even though these are baked. Fry option - follow the dredge / crumbing / fry steps in this Schnitzel recipe.', 'https://www.recipetineats.com/tachyon/2018/08/Homemade-Filet-O-Fish_3.jpg', 15, 20, 35, 4, '[{"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_fish_fillets", "quantity": {"value": 400.0, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.037, "unit": "jar of 400g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_corn", "quantity": {"value": 0.037, "unit": "can of 400g"}}, {"id": "ing_parsley", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_capers", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 cups panko breadcrumbs (Note 1)","400 - 500 g / 0.8 - 1 lb white fish fillets (, flat / thin (I used Ling, Note 2))","4 soft buns (, brioche recommended (Note 3))","4 slices processed cheese (Note 4)","Oil spray (I use olive oil)"]},{"ingredients":["1 egg","1 tbsp mayonnaise","1 tbsp dijon mustard (or other mustard)","1 tbsp flour","1/2 tsp salt","Black pepper"],"purpose":"Dredge Batter (Note 5):"},{"ingredients":["1 cup / 220g mayonnaise","1 tbsp dill pickle / gherkin/ cornichon (, very finely chopped)","1 tsp fresh parsley (, chopped*)","1 tsp capers (, drained and finely chopped*)","1.5 tbsp lemon juice (, fresh (or cider vinegar))","1 tsp white sugar","1/4 tsp salt"],"purpose":"Tartare Sauce:"}]', '[{"description":"Mix ingredients in a bowl. Set aside for 10 minutes+.","duration":10,"images":[],"step":1},{"description":"Toast Breadcrumbs:","images":[],"step":2},{"description":"Preheat oven to 180C/350F.","images":[],"step":3},{"description":"Spread breadcrumbs on a tray. Spray with oil directly down, not from side.","images":[],"step":4},{"title":"Bake for 3","description":"5 minutes until golden. Immediately transfer to bowl.","duration":4,"images":[],"step":5},{"description":"Brush tray clean, spray with oil.","images":[],"step":6},{"description":"Crumbing / baking:","images":[],"step":7},{"description":"Cut fish fillets into square-ish shapes slightly larger than the buns (they shrink when cooked).","images":[],"step":8},{"description":"Mix Batter ingredients in a bowl.","images":[],"step":9},{"description":"Carefully coat fish in batter (handle with care, fish fillets can be delicate).","images":[],"step":10},{"description":"Place in breadcrumbs. Use other hand to cover top and sides with breadcrumbs, pressing to adhere. Transfer to tray. Repeat with remaining fish.","images":[],"step":11},{"title":"Bake 12","description":"15 minutes until fish is cooked through. Immediately top with cheese - allow residual heat to make it semi melt (do not oven melt processed cheese, you get a plasticy film!).","images":[],"step":12},{"description":"Cut buns in half, microwave for 20 seconds to warm through (microwave = stays soft).","duration":0.3333333333333333,"images":[],"step":13},{"description":"Top with fish and cheese, dollop with tartare sauce. Devour!","images":[],"step":14}]', '["egg","fish","gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["burger-recipes","dinner-tonight","fish-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c25cefd99053', 'en', 'US', 'Veggie Burgers', 'Recipe video above. A Veggie Burger created by a carnivore, for carnivores. It is not a vegetarian burger pretending to be a meat burger, packed with obscure ingredients. This is just a flavour packed, juicy vegetarian burger that''s satisfyingly meaty! Chilling time: 1 hour', 'https://www.recipetineats.com/tachyon/2018/04/Veggie-Burgers_9a.jpg', 20, 35, 30, 4, '[{"id": "ing_mushroom", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_cannellini_beans_drained", "quantity": {"value": 400.0, "unit": "pack"}}, {"id": "ing_carrot", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_cashews", "quantity": {"value": 75.0, "unit": "jar"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.075, "unit": "jar of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_rice", "quantity": {"value": 112.5, "unit": "pack"}}, {"id": "ing_green_onion", "quantity": {"value": 2.25, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_french_fries", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["250g/8oz mushrooms, sliced","2 tsp olive oil","400g / 14 oz can cannellini beans, drained (Note 1)","1 large carrot , grated"],"purpose":"Beans and Veggies:"},{"ingredients":["1/2 cup (70g) cashews, raw unsalted (Note 2)","1/2 cup (55g) panko breadcrumbs (Note 3)","1/2 cup (50g) grated parmesan","1 egg","2 tbsp mayonnaise","1 garlic clove (, minced)","1/2 tsp each paprika, salt and pepper","3/4 cup (150g) cooked brown rice (Note 4)","3/4 cup green onions (, sliced)"],"purpose":"Patties:"},{"ingredients":["2 - 3 tbsp olive oil (or other)","Soft buns, lettuce, tomato, cheese, pickles, sauces, avocado, beetroot"],"purpose":"Burger:"},{"ingredients":["French fries","Baked potato wedges"],"purpose":"On the side"}]', '[{"description":"Beans and Veggies:","images":[],"step":1},{"description":"Preheat oven to 180C/350F (standard) or 160C/320F (fan/convection).","images":[],"step":2},{"description":"Pile mushrooms on a baking tray. Drizzle over oil, toss, then spread on the tray.","images":[],"step":3},{"description":"Spread beans on another tray, sprinkle carrots all over.","images":[],"step":4},{"description":"Put beans on top shelf and mushrooms on the shelf underneath.","images":[],"step":5},{"description":"Bake for 15 minutes or until surface of beans is dried out and splitting and they look thoroughly unappetising, and the carrots around the edge of the tray are a bit golden. (Note 5) Remove tray with beans from oven.","duration":15,"images":[],"step":6},{"description":"Move mushrooms to top shelf, bake for further 10 minutes until dried out and wrinkly. Remove from oven, cool.","images":[],"step":7},{"description":"Patties:","images":[],"step":8},{"description":"Place cashews in food processor. Blitz until they are breadcrumb size, don''t blitz to powder.","images":[],"step":9},{"description":"Add beans, mushrooms and carrot. Blitz on high for 10 seconds or until chopped to large crumb size (see video and photos).","duration":0.16666666666666666,"images":[],"step":10},{"description":"Add breadcrumbs, egg, parmesan, garlic, paprika, mayonnaise, salt and pepper. Blitz for 15 - 30 seconds until it comes together like meat burger mixture but you can still see bits in it. (Note 6)","duration":0.375,"images":[],"step":11},{"description":"Add rice and shallots, blitz for 2 seconds until just dispersed (over blitzed rice = gluey).","duration":0.03333333333333333,"images":[],"step":12},{"description":"Mixture should hold together well to form patties, but not stick to hands. If too wet, add breadcrumbs. If too crumbly, blitz more.","images":[],"step":13},{"title":"Shape into 4","description":"6 patties, between 1.5 - 1.8cm / 0.6 - 0.7\" thick and 10cm / 4\" wide (Note 7). Refrigerate for at least 1 hour.","images":[],"step":14},{"title":"To Cook","description":"Stove:","images":[],"step":15},{"description":"Cook burgers cold, straight from the fridge.","images":[],"step":16},{"title":"Heat 2","description":"3 tbsp olive oil skillet on the stove over medium to medium-high heat.","images":[],"step":17},{"title":"Add 3","description":"4 patties and cook until deep golden and crispy, 4 minutes. Carefully flip then cook the other side for 4 minutes until golden, then transfer to paper towel lined plate to drain.","duration":4,"images":[],"step":18},{"description":"Cook cold, straight from fridge. Brush BBQ and Veggie patties with oil. Heat BBQ to medium high. Cook 4 minutes each side until a nice dark crust forms.","images":[],"step":19},{"description":"Toast buns, spread top bun with relish or sauce of choice. Top with your choice of burger fillings and the Veggie Burger, then more sauce if desired.","images":[],"step":20}]', '["egg","milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["burger-recipes","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_19f53b412df9', 'en', 'US', 'Chicken Burrito', 'Recipe video above. This is a chicken burrito stuffed with a juicy seasoned chicken filling, refried beans, corn, cheese and Mexican Red Rice. The refried beans makes it juicy inside without being soggy, adds flavour and holds it all together so the filling doesn''t come tumbling out when you pick it up!', 'https://www.recipetineats.com/tachyon/2020/02/Chicken-Burritos_2.jpg', 15, 15, 30, 5, '[{"id": "ing_tortillas", "quantity": {"value": 5.0, "unit": "pack of 8"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_refried_beans", "quantity": {"value": 400.0, "unit": "pack"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_white_rice", "quantity": {"value": 0.375, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 375.0, "unit": "pack"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_salsa", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["5 tortillas (, flour (approx 20cm/8\" wide))"]},{"ingredients":["1 tsp each onion powder, dried oregano, salt","2 tsp each dried cumin powder, paprika","1/4 tsp black pepper","3/4 tsp cayenne pepper (optional, adjust to taste)"],"purpose":"Burrito Seasoning:"},{"ingredients":["600g / 1.2 lb chicken breast (, sliced in half horizontally (Note 1))","2 tbsp olive oil (, separated)","1/2 onion (, chopped)","2 garlic cloves (, finely minced)","1 red capsicum/bell pepper (, diced)","400g/14oz refried beans (, canned (Note 2))","1/4 cup water"],"purpose":"Chicken Filling:"},{"ingredients":["2.5 cups white rice (, plain (cooked, Note 3))","2.5 cups Mexican Red Rice (the best for Burritos!)"],"purpose":"Rice – CHOOSE one:"},{"ingredients":["400g/14oz canned corn (, drained (or 280g/9oz frozen thawed))","1.5 cups (150g) cheese (, shredded (Mexican blend, cheddar, tasty, Montery Jack))","1/4 cup coriander/cilantro (, finely chopped)"],"purpose":"Other Stuffings:"},{"ingredients":["Avocado sauce","Sour cream","Salsa (restaurant style, smooth)"],"purpose":"Sauce for dunking – choose:"}]', '[{"title":"Burrito Seasoning","description":"Mix Seasoning ingredients. Drizzle 1 tbsp oil over chicken, mix to coat. Sprinkle with Seasoning, toss to coat.","images":[],"step":1},{"title":"Cook chicken","description":"Heat 1 tbsp oil in a large skillet over high heat. Add chicken, cook 2 minutes. Turn and cook 1.5 minutes. Remove, rest 2 minutes then chop.","images":[],"step":2},{"title":"Saute onion","description":"In the same skillet, add onion and garlic, cook 1 minute. Add capsicum, cook 2 minutes until onion is translucent.","images":[],"step":3},{"title":"Finish Filling","description":"Add refried beans, diced chicken and water. Stir and cook for 2 minutes until reduces slightly. Should be thick and juicy, not watery and not dry/stodgy! Let cool 5 minutes - will thicken.","duration":2,"images":[],"step":4},{"description":"Assemble burritos:","images":[],"step":5},{"description":"Gently warm tortillas in microwave (makes them pliable), lay on work surface.","images":[],"step":6},{"description":"Place rice on lower third, top with Chicken Filling, corn, cheese then sprinkle with coriander. Fold up, burrito style.","images":[],"step":7},{"title":"Toasting","description":"Either pan fry over medium high heat (no oil) for 2 minutes each side to make tortilla crispy and melt cheese a bit OR wrap tightly in foil and bake in oven 10 minutes at 180°C/350°F.","duration":2,"images":[],"step":8},{"description":"Dunk in sauce(s) of choice or douse with hot sauce of choice, and devour! Suggestions: Avocado Sauce, Guacamole, sour cream, Restaurant Style Salsa, Queso, Nacho Cheese Dip.","images":[],"step":9},{"description":"Freezer friendly! Note 4 for directions.","images":[],"step":10}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Mexican","Tex-Mex"],"categories":["burritos","chicken-breast-recipes","chicken-recipes","main-dishes","mexican-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2317689a85d3', 'en', 'US', 'Taco Slaw', 'A slaw designed for use in tacos. A limey sour cream dressing that does so well with Mexican flavours, bit of crunch from the cabbage with signature slaw “juiciness” which acts like a sauce so you don''t need to bother with a salsa or taco sauce.Ideal for things like Crunchy Chicken Taco Fingers, Fish Tacos, Chipotle Prawn Tacos, Baja Fish Tacos, Grilled Chicken for Tacos (ie pieces of protein) rather than things that are shredded and saucy (too same-same). You can also serve it as a side salad, like regular slaw!', 'https://www.recipetineats.com/tachyon/2025/01/Taco-slaw_8.jpg', 15, 0, 15, 12, '[{"id": "ing_cabbage", "quantity": {"value": 6.0, "unit": "head"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.075, "unit": "jar of 400g"}}, {"id": "ing_lime", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_lime", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}]', '[{"ingredients":["6 tightly packed cups green cabbage (, finely shredded (about 1/4 head))","1 cup green onion (, finely sliced on the diagonal)","1/2 cup finely chopped coriander/cilantro leaves"]},{"ingredients":["1/2 cup sour cream (sub plain yogurt)","2 tbsp mayonnaise (OR 1 tbsp olive oil (ie halve amount))","2 tsp lime zest","1 tbsp lime juice","1/2 tsp cooking salt / kosher salt (halve for table salt)"],"purpose":"Taco Slaw Dressing:"}]', '[{"description":"Mix the dressing ingredients in a large bowl.","images":[],"step":1},{"title":"Toss","description":"Add the Slaw ingredients then toss well with hands or tongs.","images":[],"step":2},{"description":"Set aside for at least 1 hour until the cabbage becomes wilted and floppy. Toss again then use in tacos!","images":[],"step":3}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["cabbage","mexican-recipes","side-salads","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8a0a9eb1cc38', 'en', 'US', 'The most amazing canned tuna pasta!', 'Recipe video above. One of the pantry-pasta greats. I love this recipe because it really showcases what great food you can make using canned tuna! Fabulous flavour beyond just canned tuna thanks to the anchovies, the freshness of lemon and tangy capers. The oil from the can of tuna is used as the sauce so don''t be tempted to use tuna in brine!', 'https://www.recipetineats.com/tachyon/2023/04/Canned-tuna-pasta_0-copy.jpg', 10, 15, 25, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 285.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_baby_capers", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["200g / 7oz spaghetti (, or other thin long pasta)","1 tbsp cooking salt (, for cooking pasta)"]},{"ingredients":["285g/ 10 oz (approx) canned tuna in oil (, drained, oil reserved (I use 3 x 95g/3.5oz cans, Note 1))","2 clove garlic (, finely minced)","2 anchovy fillets (, minced (Note 2))","1/2 tsp chilli flakes / red pepper flakes (can skip, Note 3)","2 tsp baby capers (or finely chopped pickles)","1 tbsp parsley (, finely chopped (ok to skip))","1 tsp lemon zest","2 tbsp lemon juice (sub 1 tbsp apple cider or sherry vinegar)","1/4 tsp cooking/kosher salt","1/4 tsp black pepper"],"purpose":"Tuna sauce:"}]', '[{"title":"Cook pasta","description":"Bring 3 litres / 3 quarts of water to the boil with the 1 tablespoon of salt. Cook pasta per the packet time minus 1 minute. Just before draining, scoop out ~1 cup pasta cooking water, then drain the pasta.","images":[],"step":1},{"title":"Sauté aromatics","description":"In the same pot, heat the reserved oil from the tuna cans over medium heat. Add the garlic, anchovies and chilli flakes. Cook and stir for 1 minute.","duration":1,"images":[],"step":2},{"title":"Toss pasta","description":"Add the pasta, capers and 1/3 cup of reserved pasta water. Toss using 2 spatulas for 2 minutes.","duration":2,"images":[],"step":3},{"title":"Add tuna","description":"Turn off the heat. Add tuna, parsley, lemon zest, juice, salt and pepper. Toss gently to mix through - try to keep some tuna chunks.","images":[],"step":4},{"description":"Serve immediately!","images":[],"step":5}]', '["fish","gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["canned-tuna","dinner-tonight","emergency-recipes","fish-recipes","mains","other","pasta-recipes","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1bed0cbe1403', 'en', 'US', 'Tuna Mornay (Creamy Tuna Casserole Pasta Bake)', 'Recipe video above. Tuna Mornay is how you elevate canned tuna above a glum pantry staple into a delish family meal! It’s a tuna casserole pasta bake with a creamy sauce, sweet pops of corn and crunchy topping, baked until golden and bubbly. Simple to make, economical and oh-so-delish!', 'https://www.recipetineats.com/tachyon/2019/11/Tuna-Mornay_6.jpg', 10, 35, 45, 5, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_tuna", "quantity": {"value": 0.425, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["350g / 12oz penne pasta (or other short pasta)","40g / 3 tbsp butter","3 garlic cloves (, finely minced)","4 tbsp (50g) flour (, plain/all purpose)","4 cups (1 litre) milk (, any fat %, dairy or non dairy (1 quart))","2 tsp Vegeta, or chicken or veg stock powder/granulated bouillon (Note 1)","1/2 cup (50g) parmesan (, finely shredded)","1/2 tsp each mustard powder, onion and garlic powder (Note 2)","425g / 15 oz canned tuna (, preferably in oil, drained (sub salmon))","400g / 14 oz canned corn (, drained (or other veg, Note 3))"]},{"ingredients":["25g / 1.5 tbsp butter (, melted)","1/2 cup (60g) panko breadcrumbs","1/4g (25g) parmesan (, finely grated)","1/4 tsp salt","Chives or parsley (, optional garnish)"],"purpose":"Crunchy Topping:"}]', '[{"description":"Preheat oven to 180°C/350°F.","images":[],"step":1},{"title":"Crunchy Topping","description":"Mix together.","images":[],"step":2},{"description":"Cook pasta per packet directions MINUS 1 minute. Drain then allow to cool slightly, then return into pot.","images":[],"step":3},{"title":"White Sauce","description":"Melt butter in a large pot over medium heat. Add garlic and cook for 30 seconds.","duration":0.5,"images":[],"step":4},{"description":"Add flour and stir into melted butter. While whisking, gradually pour in about 1/3 of the milk. Once the flour-butter mixture is incorporated into the milk, pour in remaining milk and whisk.","images":[],"step":5},{"description":"Add Vegeta, mustard, onion and garlic powder, whisk.","images":[],"step":6},{"description":"When the milk starts to heat up, whisk constantly to make sure the white sauce doesn’t catch on the base.","images":[],"step":7},{"title":"After 4","description":"5 minutes, the sauce should be thick enough that you can draw a path across the back of a spoon (see video). Remove from stove and stir in parmesan.","images":[],"step":8},{"title":"Assemble & Bake","description":"Add tuna into pasta and flake into large chunks with fork (not too much, don''t want it to turn to mush when stirred). Add corn, pour over sauce, then gently stir.","images":[],"step":9},{"description":"Scrape into baking dish, top with Crunchy Topping.","images":[],"step":10},{"description":"Bake 25 minutes until top is golden and edges are bubbling. Sprinkle with chives if desired then serve!","images":[],"step":11}]', '["fish","gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["canned-tuna","casseroles-and-cosy-bakes","pasta-bakes","pasta-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eabda0665deb', 'en', 'US', 'Tuna Pasta Bake', 'Recipe video above. When the cupboards are bare, and all you have is canned tuna, pasta and canned tomato, you can still make a wickedly delicious dinner! Customise to your hearts content - add vegetables, fresh herbs, chilli flakes, stir through cheese, olives, capers, sun dried tomatoes - get creative! See note 9 for a lower cal version, and Tuna Mornay for a CREAMY version!', 'https://www.recipetineats.com/tachyon/2017/06/Tuna-Pasta-Bake-2.jpg', 10, 30, 40, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_italian_mixed_herbs", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_can_chunk_tuna_drained", "quantity": {"value": 0.425, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.2, "unit": "pack of 125g"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1 small onion (, finely diced)","800g / 28 oz crushed tomato (Note 1)","1 tbsp tomato paste (optional, thickens sauce slightly)","3/4 cup (185ml) water (Note 2)","1 tbsp Italian mixed herbs (, or other dried herbs of choice)","1 tsp salt","1/2 tsp black pepper","425g / 15 oz can chunk tuna (preferably in oil), drained (Note 3)","200g / 7 oz spiral pasta (or other pasta of choice)","1 1/2 cups (150g) shredded mozzarella cheese (Note 4)","Olive Oil (, for drizzling)"]}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Cook pasta per packet directions, minus 1 minute. Drain, rinse under tap water to stop it sticking together, set aside.","images":[],"step":2},{"description":"Meanwhile, make the sauce. Heat an ovenproof skillet over medium high heat. Add garlic and onion, cook for 3 minutes until golden.","duration":3,"images":[],"step":3},{"description":"Add tomato, water, herbs, salt and pepper and tomato paste if using. Stir, bring to simmer, lower heat to medium and simmer energetically for 5 minutes (stir every now and then) until it thickens.","duration":5,"images":[],"step":4},{"description":"Adjust salt to taste. Also add a touch of sugar if it tastes a bit sour (depends on quality of tomato).","images":[],"step":5},{"description":"Turn the stove off, add pasta, stir in.","images":[],"step":6},{"title":"Add tuna and GENTLY stir it in","description":"don''t break up the tuna so it disintegrates into mush. Leave some chunks on the surface (nice when it is golden).","images":[],"step":7},{"description":"Drizzle with oil, top with cheese then bake for 20 minutes until golden and you get those nice crusty bits you see in the photos.","duration":20,"images":[],"step":8},{"description":"Stand for 3 minutes then serve!","duration":3,"images":[],"step":9}]', '["fish","gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Australia","Western"],"categories":["canned-tuna","casseroles-and-cosy-bakes","pasta-bakes","pasta-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4633d5dffedc', 'en', 'US', 'Chicken Mushroom Pie with Duchess Potato lid', 'Recipe video above. I want to rave about the rich, savoury filling but all anyone can talk about is the Duchess Potato topping.....😅 Fluffy and buttery inside with crispy parmesan crusted ridges, I want to pick them off one by one and eat them all by myself!As for the filling - think, rich Guinness Stew, but with chicken, and 2 hours faster to make. Guinness beer adds instant depth of flavour, and beef rather than chicken broth has a richer flavour and makes the sauce an enticing deep brown colour.Make one big pie as I''ve done, or single serve size. Excellent for making ahead to bake later! (See note 6 if you don''t have a piping bag for star tip)', 'https://www.recipetineats.com/tachyon/2025/07/Duchess-potato-chicken-pie_9.jpg', 20, 60, 80, 6, '[{"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.5, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 1.5, "unit": "pack of 1kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_beer", "quantity": {"value": 0.568, "unit": "bottle of 330ml"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_milk", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["60 g / (4 tbsp) unsalted butter (, approximately divided into 4 (no need to be accurate))","4 garlic cloves (, finely minced)","1 1/2 tsp cooking salt / kosher salt (, divided (Note 1))","1 tsp black pepper (, divided)"]},{"ingredients":["750 g / 1.5 lb chicken thighs (, boneless skinless (Note 2))","500 g/1 lb button mushrooms - very small ones whole (, larger ones halved or quartered)","100 g / 3.5 oz thick cut streaky bacon (, cut into 2.5cm/1\" squares)","1 1/2 onions (, cut into 2cm/1\" square or thick wedges)","2 sprigs fresh thyme (or 1/2 tsp dried thyme)","1/4 cup plain flour (all-purpose flour)","3/4 cup Guinness beer (Note 3)","1 1/2 cups beef stock / broth (, low sodium)","3/4 cup water","1 tbsp tomato paste"],"purpose":"Pie filling:"},{"ingredients":["1 kg / 2 lb starchy potatoes (, peeled, cut into 2.5cm / 1\" cubes (Note 4))","30g / 2 tbsp unsalted butter (, cut into 1.5 cm / 1/2\" pieces)","1/3 cup milk (, hot)","1/8 tsp white pepper (sub black)"],"purpose":"Mashed potato topping:"},{"ingredients":["30g / 2 tbsp unsalted butter (, melted (or olive oil spray))","2 tbsp grated parmesan (, sandy store bought type works best or grate your own)","2 tsp finely chopped parsley for garnish (, optional)"],"purpose":"Topping:"}]', '[{"description":"Brown mushrooms, remove, sear chicken (aggressively!) in same pan, cut into large pieces. Sauté bacon, onion and garlic, deglaze with Guinness, make roux, add stock, simmer with mushrooms to thicken (~10 min). Add chicken towards end. Pour into a baking dish, pipe on mashed potato, finish with butter and parmesan, bake 30 min.","images":[],"step":1},{"title":"Garlic butter mushrooms","description":"Melt 1/4 of the butter in a large 30cm/12\" non stick pan over high heat. Add mushrooms, toss for 3 - 4 minutes until you get some browning on the surface. Add another 1/4 of the butter, melt, toss to coat. Add 1/4 tsp each salt and pepper and half the garlic, toss 30 seconds until garlic is golden - mushrooms will still be hard inside, they finish cooking later. Remove into bowl (make sure you scrape out all garlic bits).","duration":3.5,"images":[],"step":2},{"title":"Sear chicken","description":"Sprinkle the chicken with 1/2 tsp salt and 1/4 tsp pepper. In the same pan, melt another 1/4 of the butter until hot and foamy. Sear chicken 2 minutes on each side until nicely golden but inside is still raw (if they don''t fit in a single layer, do in batches). Remove onto plate, once cool enough to handle cut into 2.5cm (1\") pieces.","images":[],"step":3},{"title":"Bacon and onion","description":"In the same pan, add bacon and stir for 15 seconds, then add the onion (there should be enough fat from the chicken). Cook for 2 minutes until the onion edges are golden and starting to soften. Add remaining garlic and stir 20 seconds.","duration":0.25,"images":[],"step":4},{"title":"Deglaze with Guinness","description":"Add Guinness and let it simmer rapidly, scraping the base of the pan to loosen any golden bits into the liquid (“fond” = free flavour!), until the Guinness is reduced down by 75%.","images":[],"step":5},{"title":"Sauce","description":"Lower heat to medium and add remaining butter. Once melted, sprinkle flour all across the surface and stir for 1 minute - it will look pasty. While stirring, pour in half the stock. Keep stirring until the flour paste dissolves into the stock, for lump-free sauce (yay!). Then add remaining stock, water, tomato paste, 1/4 tsp salt and 1/2 tsp pepper, stir well.","duration":1,"images":[],"step":6},{"title":"Simmer","description":"Add the mushrooms plus all mushroom juices accumulated in the bowl into the pan. Simmer for 10 minutes or until the liquid reduces down into a fairly thick gravy and the mushrooms become soft. (Meanwhile, start the mash)","duration":10,"images":[],"step":7},{"title":"Thicken sauce","description":"Add the chicken (plus all juices) and simmer for another 2 to 3 minutes until the gravy is quite thick and you can draw a path on the base of the pan. (Sauce thickness now = sauce thickness once baked). Taste - add more salt if needed (I don’t).","images":[],"step":8},{"title":"Assemble","description":"Pour into a 1.5 - 2 L (6 - 8 cup) baking pan and smooth the surface. (Note 5 for other pan sizes)","images":[],"step":9},{"description":"Preheat oven to 200°C / 390°F (180°C fan-forced).","images":[],"step":10},{"title":"Duchess potato topping","description":"Pipe mounds of mashed potato swirls on the surface. My swirls have a 4.5cm base (1.6\"), about 4cm tall (1.4\"), then I fill gaps with small swirls/blobs. I use all the mash! Drizzle with melted butter, sprinkle with parmesan. (Note 6 for no piping bag)","images":[],"step":11},{"description":"Bake for 30 minutes, rotating the pan at the 20 minute mark.","duration":30,"images":[],"step":12},{"title":"Serve","description":"Rest for 10 minutes, sprinkle with parsley if using. Attack!","duration":10,"images":[],"step":13},{"title":"Make mash","description":"Put the potatoes into a large pot of cold tap water. Bring to a boil over high heat then cook for 15 minutes until soft. Drain, pass through a potato ricer (smoother) or mash well with a potato masher in the now empty pot. Add butter, milk, 1/2 tsp salt and 1/8 tsp white pepper, stir through - it should be creamy but not loose (so it holds its form when piped).","duration":15,"images":[],"step":14},{"title":"Piping bag","description":"Transfer mash into a piping bag fitted with a star tip. (Note 6 for no piping bag)","images":[],"step":15}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["casseroles-and-cosy-bakes","chicken","chicken-recipes","mains","quiches-tart-and-pie-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_15961522cbb1', 'en', 'US', 'Chicken Cacciatore', 'Recipe video above. I love this chicken stew, made with simple ingredients that''s so cosy and comforting. Also known as Hunter''s Stew, this is made with a tomato sauce that''s rich with red wine, herbs, and Kalamata olives. While there are various regional variations, capsicum (bell peppers) and mushrooms are typical vegetable inclusions though I''ve also seen varieties using fennel which is so distinctly Italian too (finely slice and sauté). Serve over mash or polenta for the perfect cosy evening meal.', 'https://www.recipetineats.com/tachyon/2024/06/Chicken-Cacciatore-50813.jpg', 15, 55, 70, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_rosemary", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_pinot_noir", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_whole_kalamata_olives", "quantity": {"value": 16.0, "unit": "bottle"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4 bone in chicken thighs large (1 kg / 2 lb)","4 chicken drumsticks","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper","1 tbsp olive oil"],"purpose":"Chicken (Note 1):"},{"ingredients":["1 onion (, halved, finely sliced)","2 rosemary sprigs ((about 15 cm/6\" long), or 1 tsp dried rosemary)","2 bay leaves (, preferably fresh else dried)","3 garlic cloves (, finely minced)","3 anchovy fillets (or 1 tsp anchovy paste), optional (Note 2)","250g / 8 oz mushrooms (, sliced)","2 red capsicum (, sliced 8 mm thick (medium, not giant))","1/3 cup tomato paste","3/4 cup pinot noir (or other dry red wine (Note 3))","2 cups chicken stock/broth (, low sodium)","400g/14 oz canned crushed tomato","16 whole kalamata olives (, pitted, drained)","1/4 tsp cooking/kosher salt","1/4 tsp black pepper","1 tsp dried oregano"],"purpose":"Cacciatore:"},{"ingredients":["Mashed potato ( or polenta)","Finely chopped parsley (, for sprinkling (optional))"],"purpose":"Serving"}]', '[{"title":"Season","description":"Spread the chicken out on a tray. Sprinkle both sides with the salt and pepper.","images":[],"step":1},{"title":"Brown skin","description":"Heat the oil over high heat in a large, deep, heavy based pan, preferably one with a lid (Note 4). Place the chicken thighs in the pan, skin side down, and cook until the skin is golden brown, around 6 minutes. Turn and cook the flesh side for just 1 minute, then remove the chicken onto the same tray. Then add the drumsticks and brown each side as best you can, about 1 1/2 minutes on each side (the shape makes it awkward). Remove onto the tray.","images":[],"step":2},{"title":"Onion","description":"Pour off and discard all but about 2 tablespoons of fat. Turn the heat down to medium and let the pan cool slightly. Add the onion, rosemary leaves, bay leaves and dried oregano. Cook for 3 minutes until the onion is starting to soften.","duration":3,"images":[],"step":3},{"title":"Garlic and anchovies","description":"Clear a space in the middle of the pan. Add the anchovies and garlic, cooking, mashing up the anchovies, until the garlic is light golden, then stir it into the onion.","images":[],"step":4},{"title":"Vegetables & tomato paste","description":"Turn the heat back up to high. Add the mushroom and capsicum. Stir until softened - about 5 minutes (the mushrooms will go watery then the water will evaporate). Add the tomato paste and cook for 2 minutes to cook out the sour flavour - do not shortcut this.","duration":2,"images":[],"step":5},{"title":"Sauce","description":"Add the wine. Stir, bring to simmer then allow to reduce by around 75%. Add the stock, canned tomato, salt and pepper. Stir, bring to a simmer.","images":[],"step":6},{"title":"Simmer","description":"Then carefully place the chicken into the sauce (skin side up) and pour any juices on the tray in as well. When the liquid returns to a simmer, cover, reduce the heat to medium then simmer energetically for 20 minutes. Remove lid, add olives, simmer for a further 10 minutes (no lid). This will reduce and thicken the sauce.","duration":20,"images":[],"step":7},{"title":"Serve","description":"Serve the chicken with plenty of sauce over mashed potato or polenta, sprinkled with parsley if desired.","images":[],"step":8}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["casseroles-and-cosy-bakes","chicken","chicken-drumstick-recipes","chicken-recipes","mains","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9d3a5c00a721', 'en', 'US', 'Chicken pasta bake', 'Recipe video above. Everything a chicken pasta bake should be - big, juicy, bubbly, cosy, with loads of extra tasty sauce, sizzling seasoned chicken, bacon and plenty of cheese. Nice change from the usual creamy pasta bakes!This is a complete meal with starch, protein and veg so you won''t need a side salad for this. Love the juicy chunks of tomato!', 'https://www.recipetineats.com/tachyon/2023/05/Chicken-pasta-bake_7.jpg', 15, 45, 60, 6, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_rigatoni", "quantity": {"value": 300.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.6, "unit": "pack of 125g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}]', '[{"ingredients":["500g / 1 lb chicken thighs (, cut into small bite size pieces (Note 1))","1/2 tsp cooking/kosher salt","1/4 tsp black pepper","1/2 tsp garlic powder","2 tsp Italian herb mix (, any store bought type)"],"purpose":"Seasoned Chicken"},{"ingredients":["300g/10oz rigatoni (or penne, elbow macaroni, shells or similar)","2 tsp salt (, for cooking pasta)","5 slices streaky bacon","1/2 onion (, finely chopped)","2 garlic cloves (, minced)","1 1/2 tsp dried oregano","1/2 tsp chilli flakes / red pepper flakes","1/2 cup chardonnay or other dry white wine (Note 2)","2 tbsp tomato paste","700g / 24oz tomato passata (Note 3)","1/2 cup water","1 tsp cooking/kosher salt","1/2 tsp black pepper","3 tomatoes (, cut into 8 wedges then halved)","2 big handfuls baby spinach (or bite size kale)","2 cups mozzarella, (shredded)","1/2 cup (tightly packed) parmesan, (finely shredded)"],"purpose":"Pasta bake"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":1},{"description":"Cook pasta per packet directions, using boiling water seasoned with the 2 teaspoons of salt. Drain, rinse briefly under tap water, then set aside to cool while making the sauce.","images":[],"step":2},{"title":"Season chicken","description":"Toss together Seasoned Chicken ingredients in a bowl.","images":[],"step":3},{"title":"Crisp bacon","description":"Put bacon in an unheated very large non-stick pan (Note 2). Turn stove on medium high. The fat will melt so the bacon cooks in its own fat. Cook until light golden, remove onto paper towels, leaving fat in the pan. Once cool, cut into 1cm / 1/3\" pieces.","images":[],"step":4},{"title":"Sizzle chicken","description":"Top up bacon fat with olive oil if you don’t have at least 1 tbsp. Increase heat to high. Cook chicken for 3 minutes until light golden on the outside but still raw inside. Remove into a bowl with a slotted spoon.","duration":3,"images":[],"step":5},{"title":"Sauce","description":"In the same pan, cook garlic and onion for 1 minute, then add chilli flakes and oregano. Cook for 2 minutes until onion is translucent. Add wine and rapidly simmer for 1 to 2 minutes until mostly evaporated. Add tomato paste and cook for 1 minute to concentrate and improve flavour. Add passata, then use the water to rinse out the bottle. Add salt, pepper, chicken (including all juices on the plate). Mix, then simmer for 5 minutes on medium.","duration":1,"images":[],"step":6},{"title":"Toss","description":"Add baby spinach, tomato, pasta and bacon. Toss well.","images":[],"step":7},{"title":"Assemble","description":"Transfer to 23 x 33cm/9 x 13\" pan. Top with mozzarella then parmesan. Bake 25 minutes until melted with some golden spots.","images":[],"step":8},{"title":"Serve","description":"Stand for 5 minutes then serve!","duration":5,"images":[],"step":9}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian-esque","Western"],"categories":["casseroles-and-cosy-bakes","chicken","chicken-recipes","mains","pasta-bakes","pasta-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_21c841bde5ba', 'en', 'US', 'Spinach Ricotta Stuffed Shells (Conchiglioni)', 'Recipe VIDEO above. There''s no need to mess around stuffing hot floppy shells. Just stuff uncooked jumbo pasta shells and bake in loads of sauce! Bonus: The shells absorb the flavour of the sauce, and there''s plenty of tasty sauce for serving. Because nobody likes dry pasta shells!', 'https://www.recipetineats.com/tachyon/2023/03/Spinach-ricotta-stuffed-shells_4.jpg', 25, 105, 60, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.033, "unit": "jar of 50g"}}, {"id": "ing_spinach", "quantity": {"value": 250.0, "unit": "bag of 250g"}}, {"id": "ing_ricotta", "quantity": {"value": 2.0, "unit": "tub of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_nutmeg", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}]', '[{"ingredients":["2 tbsp olive oil","2 eschallots/shallots or 1 small onion (, finely chopped (Note 1))","4 garlic cloves (, finely minced)","1 bay leaf (, fresh (sub dried))","1/2 tsp each dried thyme and oregano","1/3 cup tomato paste","700g / 25 oz tomato passata (US: tomato sauce) (Note 2)","1/3 cup Chardonnay or other dry white wine (sub more stock)","4 cups vegetable stock/broth (, low sodium)","3/4 tsp salt","1 1/2 tsp white sugar","1/3 tsp black pepper"],"purpose":"Sauce (you need LOTS!):"},{"ingredients":["250g / 8 oz frozen chopped spinach (, thawed (Note 3))","500g / 1 lb ricotta (, full fat please (Note 4))","1/2 cup parmesan (, finely shredded)","1 cup shredded cheese (Mozzarella, Colby, Cheddar, Tasty, Gruyere, Swiss, anything!)","1 egg","1 large garlic clove (, minced)","Grated fresh nutmeg (just a sprinkling) ( or 1/8 tsp nutmeg powder (optional))","3/4 tsp cooking / kosher salt","1/2 tsp black pepper"],"purpose":"Filling:"},{"ingredients":["250g / 8 oz jumbo pasta shells (conchiglioni) (Note 3)","1 1/2 cups shredded mozzarella","1/2 cup parmesan (, shredded)","Fresh basil and parmesan (, for garnish (optional))"],"purpose":"Stuffed shells"}]', '[{"title":"Sauté","description":"Heat oil in a small pot over medium high heat. Add garlic, onion, bay leaf, thyme and oregano. Cook for 3 - 4 minutes until the onion is translucent. Add tomato paste and cook for 1 minute.","duration":3.5,"images":[],"step":1},{"title":"Reduce wine","description":"Add wine, increase heat to high and let it simmer rapidly until mostly evaporated (about 2 minutes).","images":[],"step":2},{"title":"Simmer","description":"Add passata, stock, sugar, salt and pepper. Stir then simmer on low *(uncovered) for 20 minutes. Use while hot.","duration":20,"images":[],"step":3},{"title":"Squeeze spinach","description":"Grab handfuls of spinach and squeeze out excess water.","images":[],"step":4},{"title":"Mix filling","description":"Place spinach in a bowl with remaining Filling ingredients. Mix well.","images":[],"step":5},{"description":"Assemble & Bake:","images":[],"step":6},{"description":"Preheat oven to 200°C/400°F (180°C fan).","images":[],"step":7},{"title":"Stuff","description":"Stuff UNCOOKED shells with spinach ricotta filling. Stuff them full!","images":[],"step":8},{"title":"Assemble","description":"Pour the hot tomato sauce in a 23 x 33 cm / 9 x 13\" baking dish. Gently place the stuffed shells in - most will be submerged, some may poke above surface.","images":[],"step":9},{"title":"Bake","description":"Cover with a baking tray (or foil) then bake for 70 minutes.","duration":70,"images":[],"step":10},{"title":"Cheese it! Check the shells","description":"they should be al dente! (If not, return to oven, covered). Sprinkle with mozzarella then parmesan. Bake 15 minutes until melted.","images":[],"step":11},{"description":"Serve, garnished with extra parmesan and basil if desired!","images":[],"step":12}]', '["egg","gluten","milk"]', '["high_protein","vegetarian"]', '{"mealType":["dinner"],"cuisine":["American-Italian","Italian","Western"],"categories":["casseroles-and-cosy-bakes","cosy-desserts","italian-recipes","pasta-bakes","pasta-recipes","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c0bed5d30664', 'en', 'US', 'Chorizo chickpea stew (fast)', 'Recipe video above. This is a great, hearty, full flavoured Spanish-inspired stew that''s quick to make. Chorizo is the shortcut here, adds a ton of flavour into the sauce!Serve this as a chunky soup with crusty bread for mopping, flatbreads for dunking, or like stew over a bed of couscous, small pasta (like orzo/risoni, orecchiette), mashed potato or cauliflower puree. For an extra hit of protein, top with a fried egg. YUM!Serves 2 hearty appetites, or 3 normal appetites.', 'https://www.recipetineats.com/tachyon/2023/01/Chorizo-chickpea-stew_0.jpg', 7, 20, 27, 2, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_chorizo", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["1 1/2 tbsp olive oil","250g / 8 oz chorizo (2 pieces) (, cut into 8mm / 1/3\" slices (Note 1))","2 garlic cloves (, minced)","1/2 tsp dried thyme","1/2 tsp smoked paprika (sub normal paprika)","1 bay leaf (, preferably fresh, otherwise dried)","400g / 14oz can crushed tomato","400g/14 oz can chickpeas (, drained (or other beans of choice))","1 cup chicken stock/broth (, low sodium)","1/4 tsp cooking/kosher salt","1/4 tsp black pepper"]}]', '[{"title":"Sauté chorizo","description":"Heat olive oil in a large saucepan or small pot over medium high heat. Add chorizo and cook for 3 minutes or until golden.","duration":3,"images":[],"step":1},{"title":"Sauté aromatics","description":"Add garlic, thyme, paprika and bay leaf, then stir for 1 minute.","duration":1,"images":[],"step":2},{"title":"Add everything else","description":"Add tomato, chickpeas, chicken stock, salt and pepper. Stir, bring to a simmer then lower the heat down to medium low so it is simmering very gently.","images":[],"step":3},{"description":"Cook for 15 minutes (no lid), stirring regularly to ensure the base does not catch, until the sauce has reduced and thickened.","duration":15,"images":[],"step":4},{"title":"Serve","description":"Discard bay leaf and serve. I love this with hot crusty bread (slathered with butter!).","images":[],"step":5}]', '[]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Spanish","Spanish Style","Western"],"categories":["casseroles-and-cosy-bakes","dinner-tonight","quick-and-easy","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_99df5f43dfdc', 'en', 'US', 'Chicken Tagine', 'Recipe video above. Browned chicken braised in a spiced sauce, the secret to a great Moroccan Chicken Tagine is a well-balanced spice blend! Best made with bone-in chicken thighs, which stay juicy for the required sauce simmering time. Drumsticks work well too. Some versions are made with olives, others use dried fruit, and some even use both. I''ve opted for fruit because it''s one of the few dishes I love fruit with meat! See note 7 for the olive option (it''s delish too). Note: Crushed tomato isn''t typically used in traditional tagines but I love how it thickens the sauce so it clings to the couscous better. Without, the sauce is watery.', 'https://www.recipetineats.com/tachyon/2022/05/Chicken-tagine_5.jpg', 15, 40, 55, 6, '[{"id": "ing_apricots", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 6.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_ginger", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.025, "unit": "bunch"}}, {"id": "ing_powder", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_couscous_plain_or_with_fruit_and_or_nuts", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.025, "unit": "bunch"}}, {"id": "ing_kalamata_olives", "quantity": {"value": 150.0, "unit": "bottle"}}, {"id": "ing_almonds", "quantity": {"value": 0.2, "unit": "pack of 250g"}}]', '[{"ingredients":["1 cup dried apricot, halved (Note 1)","6 x 220g / 7 oz chicken thighs (, bone-in skin-on (Note 2))","3/4 tsp salt (cooking/kosher salt)","2 tbsp olive oil","1 onion ((brown/yellow), cut into 0.3 cm/ 1/8\" slices)","2 garlic cloves (, finely minced)","1 cinnamon stick (sub 1/2 tsp powder)","400 g / 14 oz crushed tomato (1 can)","400g / 14 oz canned chickpeas (, drained (Note 10))","1 tbsp preserved lemon skin (, finely minced (Note 3))","2 1/2 cups chicken stock, low-sodium ( (or homemade))"]},{"ingredients":["1 tsp cooking salt","3/4 tsp ground cumin","3/4 tsp ground ginger","3/4 tsp black pepper","1/2 tsp allspice powder","1/4 tsp cinnamon powder","1/4 tsp coriander powder","1/8 tsp clove powder"],"purpose":"Ras el hanout spice blend (Note 4):"},{"ingredients":["Couscous - plain or with fruit and/or nuts (recipe here)","2 tbsp fresh coriander (, roughly chopped)"],"purpose":"For serving:"},{"ingredients":["1 cup kalamata olives (instead of apricots) (Note 7)","1/3 cup slivered almonds (, lightly toasted, for garnish (Note 8))"],"purpose":"Alternative add in options"}]', '[{"title":"Plump apricots","description":"Soak the dried apricots in a bowl of boiling water for 30 minutes, then drain (this plumps them up).","duration":30,"images":[],"step":1},{"title":"Season chicken","description":"Sprinkle both sides of the chicken with the salt.","images":[],"step":2},{"title":"Brown chicken","description":"Heat oil the oil in a large, deep skillet or pot (Note 5) over high heat. Place chicken in the skillet skin side down and cook for 8 to 10 minutes until deep golden. Turn and cook the flesh side for 1 minute then remove to a plate.","duration":9,"images":[],"step":3},{"title":"Sauté aromatics & spices","description":"Discard all but 2 tablespoons of fat in the skillet. Reduce heat to medium. Add onions and cook for 3 minutes. Add garlic and cook for 1 minute. Add the Ras el hanout and stir for 30 seconds.","duration":3,"images":[],"step":4},{"title":"Tagine sauce","description":"Add the cinnamon stick, tomato, chickpeas, plumped apricots, stock and preserved lemon, then stir. Place the chicken on top, skin side up.","images":[],"step":5},{"title":"Simmer covered 5 minutes","description":"Bring the liquid to a simmer then cover with a lid (Note 6). Cook for 5 minutes, adjusting the heat as needed so the liquid is simmering (but not too rapidly else base may catch).","duration":5,"images":[],"step":6},{"title":"Simmer uncovered 20 minutes","description":"Remove lid then cook for a further 20 minutes or until the internal temperature of the chicken is at least 70°C/158°F (Note 6).","images":[],"step":7},{"title":"Serve","description":"Remove from stove and rest for 5 minutes. Serve over couscous (Note 9), sprinkled with fresh coriander.","duration":5,"images":[],"step":8}]', '["gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Moroccan"],"categories":["casseroles-and-cosy-bakes","chicken","chicken-recipes","cuisines","mains","middle-eastern-recipes","moroccan","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cf5a8dcf7b6a', 'en', 'US', 'Eggplant Parmigiana (Parmigiana di Melanzane)', 'Recipe video above. There''s a little labour involved in this. But you''ll be rewarded with one of the all-time greatest vegetarian comfort foods known to mankind!Assemble ahead, then pop in the oven to bake when you''re ready!', 'https://www.recipetineats.com/tachyon/2021/05/Eggplant-Parmigiana_1.jpg', 40, 60, 100, 8, '[{"id": "ing_egg", "quantity": {"value": 1.8, "unit": "carton of 12"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.833, "unit": "pack of 200g"}}, {"id": "ing_basil", "quantity": {"value": 1.2, "unit": "bunch"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.2, "unit": "pack of 125g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["1.8kg / 4 lbs large eggplants (aubergines) - about 5 (, sliced lengthways 8mm (1/3\")-thick (skin on, Note 1))","1/4 cup olive oil (for brushing)"],"purpose":"Baked Eggplant Slices:"},{"ingredients":["1 2/3 cups parmesan (, finely grated)","2 cups basil leaves ((loosely packed), stalks reserved)","1 1/2 cups mozzarella (, shredded (for topping) (Note 2))"],"purpose":"Layers:"},{"ingredients":["2 tbsp extra virgin olive oil","1 onion (, finely diced)","5 garlic cloves (, finely minced)","600ml / 20oz tomato passata (Note 3)","400g/ 14oz canned tomatoes (, crushed or finely chopped (Note 4))","1 1/2 tsp white sugar","1 1/2 tbsp fresh oregano (, finely chopped (or 1/2 tsp dried oregano, or 1 sprig fresh basil))","1 cup water","3/4 tsp salt","1/4 tsp black pepper"],"purpose":"Sugo (tomato sauce):"}]', '[{"description":"Baking eggplant:","images":[],"step":1},{"description":"Preheat oven to 220°C / 430°F (200°C fan).","images":[],"step":2},{"title":"Line three trays","description":"Line three large trays with baking / parchment paper.","images":[],"step":3},{"title":"Brush eggplant with oil","description":"Brush eggplant slices on each side with oil.","images":[],"step":4},{"title":"Bake 35 minutes","description":"Arrange eggplant in a single layer on the trays and bake for about 35 - 45 mins or until browning and tender, turning the eggplant halfway. I put the trays on the top shelf, in the middle, then I put one tray on the floor of the oven. As each tray finishes, I remove the tray and move the others up.","images":[],"step":5},{"title":"Cool","description":"Remove from oven, leave on trays to cool.","images":[],"step":6},{"description":"Tomato sauce (sugo):","images":[],"step":7},{"title":"Sauté onions and garlic","description":"Heat olive oil in a large skillet over medium-high heat. Sauté onions and garlic for 3 minutes until softened and just about to colour on the edges.","duration":3,"images":[],"step":8},{"title":"Add remaining ingredients","description":"Pour in the passata , canned tomatoes, water, oregano and sugar. Stir and bring to a simmer.","images":[],"step":9},{"title":"Simmer 30 minutes: Simmer uncovered for about 30","description":"40 minutes, stirring occasionally, until thickened, adding the basil stalks halfway through cooking (so they don’t lose their flavour).","images":[],"step":10},{"description":"The final consistency should be slightly thicker than a pasta sauce so it’s spreadable and not leaching liquid, but not too pasty either. Add extra water a little at a time if required during cooking if it gets too thick. Remove the basil stalks and discard.","images":[],"step":11},{"title":"Season","description":"Stir in salt and pepper. (Remember, we get salt from the parmesan too, so no need to go overboard here)","images":[],"step":12},{"description":"Assembling and baking:","images":[],"step":13},{"description":"Reduce oven to 180°C / 350°F (160°C fan).","images":[],"step":14},{"description":"Smear a little tomato sauce in the bottom of baking dish, 23 x 33cm / 9 x 13\" (or thereabouts).","images":[],"step":15},{"title":"Layer 1","description":"Lay one third of the eggplant so it covers the base (some overlap is OK when layering eggplant). Spread 1/3 of the remaining sugo over eggplant. Drizzle with a little olive oil. Sprinkle with 1/3 of the parmesan, and 1/3 of basil leaves.","images":[],"step":16},{"title":"Layer 2","description":"Repeat another 1/3 each of eggplant, tomato sauce, olive oil, basil and parmesan.","images":[],"step":17},{"title":"Layer 3 (top layer)","description":"Repeat again with remaining eggplant, tomato sauce and some olive oil. Do not put basil on top layer (we will garnish after baking). Scatter with remaining parmesan, then all the mozzarella.","images":[],"step":18},{"description":"Bake for 25 mins until bubbling and golden.","duration":25,"images":[],"step":19},{"title":"Rest","description":"Let it rest for 5 to 10 minutes (easier to slice neatly). Scatter over remaining fresh basil leaves. Cut like lasagna and serve! (Optional: sprinkle with extra parmesan).","duration":7.5,"images":[],"step":20}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["American-Italian","Italian"],"categories":["casseroles-and-cosy-bakes","dietary","gluten-free-recipes","italian-recipes","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6399a0413b12', 'en', 'US', 'Pastitsio (Greek Pasta Bake)', 'Recipe video above. Greece''s answer to Italian Lasagna! This traditional Greek dish is made with layers of pasta topped with a rich meat sauce perfumed with a hint of cinnamon and clove, topped with a thick layer of cheese sauce.For the neat layers pictured, arrange the pasta so they''re all going in one direction, and rest the baked Pastitsio for 15 minutes before slicing. Excellent for making ahead (keeps for 4 to 5 days in the fridge) and freezes very well!', 'https://www.recipetineats.com/tachyon/2021/02/Pastitsio-_4.jpg', 15, 120, 135, 8, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.25, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_round_clove", "quantity": {"value": 1000.0, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_nutmeg", "quantity": {"value": 0.625, "unit": "jar"}}, {"id": "ing_cheese", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 2.0, "unit": "pack of 500g"}}, {"id": "ing_feta_cheese", "quantity": {"value": 120.0, "unit": "block of 200g"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}]', '[{"ingredients":["2 tbsp olive oil","3 garlic cloves (, finely minced)","2 red onions (, finely chopped (sub yellow or brown onions))","1 kg / 2 lb beef mince (ground beef)","3/4 cup red wine (, dry (Note 1))","800g / 28 oz canned crushed tomato","2 beef bouillon cubes (, crumbled (stock cubes))","2 tbsp tomato paste","1 tsp white sugar","1 bay leaf","1/2 tsp cinnamon powder","1 cinnamon stick (or extra 1/2 tsp cinnamon powder)","1/4 tsp ground cloves","3/4 tsp salt","1 tsp black pepper"],"purpose":"Meat Sauce:"},{"ingredients":["100g / 7 tbsp butter (, unsalted)","3/4 cup flour (, plain/all purpose)","1 litre / 4 cups milk (, whole/full fat best but low fat ok)","1/8 tsp nutmeg (, preferably freshly grated)","1/2 tsp salt","100g / 3 oz Kefalotyri Greek cheese (sub Parmesan or Romano) (, finely shredded (Note 2))","2 egg yolks (egg whites are used in the pasta)"],"purpose":"Greek Bechamel:"},{"ingredients":["400g / 14 oz Pastitsio No. 2 pasta / Greek bucatini (sub small ziti, penne or normal bucatini, Note 3)","120g / 4 oz feta (, crumbled)","2 egg whites (yolks used in Béchamel)"],"purpose":"Pasta:"},{"ingredients":["75g / 3 oz Kefalotyri Greek cheese (sub parmesan or Romano) (, finely grated (Note 2))"],"purpose":"Topping:"}]', '[{"description":"Heat in a large pot over high heat. Add garlic and onion, cook for 2 - 3 minutes until onion is softened. Add beef and cook, breaking it up as you go, until it changes from red to brown.","duration":2.5,"images":[],"step":1},{"description":"Add wine and and cook until the wine has mostly evaporated - about 3 minutes.","images":[],"step":2},{"description":"Add remaining Meat Sauce ingredients. Stir well, bring to simmer, then reduce heat to medium / medium low so it''s simmering gently. Cook for 45 min to 1 hour until liquid is mostly gone, stirring every now and then. It should be a thick mixture with little liquid, not saucy like Spaghetti Bolognese (Note 4).","duration":45,"images":[],"step":3},{"description":"Remove from stove and cool. Preferably to room temperature, otherwise for at least 30 minutes before assembling (lid off).","images":[],"step":4},{"description":"Greek Béchamel (Note 5):","images":[],"step":5},{"description":"Melt butter in a large saucepan over medium heat. Add flour and stir for 1 minute.","duration":1,"images":[],"step":6},{"description":"While stirring, slowly pour half the milk in. It should turn into a wet paste. Then again, while stirring, pour in remaining milk - the paste should easily dissolve so it''s lump-free. If not, just whisk vigorously.","images":[],"step":7},{"description":"Cook, stirring so the base doesn''t catch, for 5 minutes or until thick enough so it coats the back of a wooden spoon thickly and you can draw a path across it with your finger.","duration":5,"images":[],"step":8},{"description":"Remove from stove. Stir in nutmeg, cheese and salt.","images":[],"step":9},{"description":"Leave to cool for 5 minutes. Then whisk in egg yolks quickly. Place lid on and set aside. If sauce cools and gets too thick to pour, just reheat on a low stove until pourable.","duration":5,"images":[],"step":10},{"description":"Pasta (Note 6):","images":[],"step":11},{"description":"When you''re ready to assemble, cook the pasta per packet instructions, minus 1 minute.","images":[],"step":12},{"description":"Drain, then return to the pot. Leave to cool for 3 minutes, then stir through egg whites. Gently stir through crumbled feta.","duration":3,"images":[],"step":13},{"description":"Assemble and bake:","images":[],"step":14},{"description":"Preheat oven to 180°C/350°F (all oven types).","images":[],"step":15},{"description":"Place pasta in a baking dish (33 x 22 x 7 cm / 9 x 13 x 2.75\"), arranging them so they are all going in the same direction as best you can (for visual effect when sliced). Make the surface as level as you can.","images":[],"step":16},{"description":"Top with Meat Sauce, then smooth the surface.","images":[],"step":17},{"description":"Pour over Béchamel Sauce, then sprinkle over the cheese.","images":[],"step":18},{"description":"Bake 30 min or until crust turns golden.","images":[],"step":19},{"description":"Cool for at least 10 minutes so you can cut neat slices with the layers neatly visible. Serve!","images":[],"step":20}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["casseroles-and-cosy-bakes","greek-recipes","mediterranean-recipes","pasta-bakes","pasta-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a839b8dac309', 'en', 'US', 'Chicken Tetrazzini (creamy chicken mushroom pasta bake)', 'Recipe video above. A big, creamy pasta bake with juicy chicken and mushrooms. Cheesy, hot and completely delicioius! Rumoured to be named after an Italian opera star Luisa Tetrazzini when an American Chef created this dish for her. So it''s not authentic Italian - but it doesn''t make this any less delicious!!', 'https://www.recipetineats.com/tachyon/2020/08/Chicken-Tetrazzini_0.jpg', 15, 60, 75, 8, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}]', '[{"ingredients":["500g / 1lb spaghetti or other long pasta, cooked per packet (penne, macaroni, ziti ok too) (Note 1)"]},{"ingredients":["2 tbsp (30g) butter","500g / 1lb chicken thighs (, skinless boneless (Note 2))"],"purpose":"Chicken"},{"ingredients":["4 tbsp (60g) butter (, unsalted)","500g / 1lb mushrooms (, sliced 1/2 cm / 1/5\" thick)","2 garlic cloves (, minced)","1 onion (, finely chopped)","4 tbsp flour","2 cups milk (, any fat, any type)","1 cup cream (, heavy / thickened (sub more milk))","2 cups chicken stock/broth (, low sodium (or water + 2 stock cubes))","1/2 tsp black pepper","1 tsp salt","2 cups cheese (, shredded (cheddar, jack, colby - not mozz))"],"purpose":"Creamy Sauce"}]', '[{"description":"Melt 2 tbsp butter in a large pot over high heat. Add chicken, sprinkle with pinch of salt and pepper. Cook 1 1/2 minutes until golden.","images":[],"step":1},{"description":"Turn chicken, sprinkle with salt and pepper. Cook 1 minute until golden then remove onto plate - doesn''t need to be fully cooked (will cook more in oven).","images":[],"step":2},{"description":"Rest 5 minutes, then chop into small pieces, or shred.","images":[],"step":3},{"description":"Preheat oven to 160°C / 325°F.","images":[],"step":4},{"title":"Cook mushrooms","description":"Melt 4 tbsp butter over high heat in the same pot. Add mushrooms and cook for 4 minutes until starting to go floppy but not yet golden.","duration":4,"images":[],"step":5},{"title":"Add onion","description":"Add garlic and onion, cook for 3 minutes until mushrooms are golden. Add a pinch of salt and pepper halfway through.","duration":3,"images":[],"step":6},{"title":"Add flour & milk","description":"Turn heat down to medium. Add flour. Stir for 30 seconds. Add milk and stir for 10 seconds or until it thickens (see video at 52 sec).","duration":0.5,"images":[],"step":7},{"title":"Add cream and broth","description":"Add chicken stock, cream, 1 tsp salt and 1/2 tsp pepper. Stir, then let the mixture heat up, stirring every now and then so it doesn''t catch on the base, and cook until the sauce thickens enough so you can draw a path on the back of the spoon (video at 1.04). Do not make it very thick - it gets thicker in next steps.","images":[],"step":8},{"title":"Add cheese & pasta","description":"Turn stove off. Stir through half the cheese (will melt in oven), then add pasta and chicken. Toss to mix, taste and add more salt if needed.","images":[],"step":9},{"title":"Bake","description":"Pour into 23 x 33cm / 9 x 13\" pan, smooth surface. Top with remaining cheese. Bake 25 minutes until golden and bubbly. Serve immediately!","images":[],"step":10}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["casseroles-and-cosy-bakes","chicken-breast-recipes","chicken-recipes","italian-recipes","pasta-bakes","pasta-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2e596835d0b8', 'en', 'US', 'Baked Spinach and Ricotta Rotolo', 'Recipe video above. Rotolo is a lessor known Italian pasta dish where a filling is rolled up in pasta sheets then rolled like a roulade, poached, sliced then served. It is so tasty, but quite technical and time consuming to make. This is my version - a baked version which is made more like cannelloni. Much easier, just as tasty and best of all, you get crunchy brown bits you don''t get with the traditional rotolo!Want a meat filling? Use the filling from this Spinach & Beef Cannelloni - scale up by 50% (or use extra spinach), cool (will thicken) then roll!', 'https://www.recipetineats.com/tachyon/2014/07/Spinach-Ricotta-Rotolo-09.jpg', 30, 45, 75, 5, '[{"id": "ing_lasagne_sheets", "quantity": {"value": 8.0, "unit": "unit"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_spinach", "quantity": {"value": 500.0, "unit": "bag of 250g"}}, {"id": "ing_ricotta", "quantity": {"value": 2.0, "unit": "tub of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_nutmeg", "quantity": {"value": 0.625, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["8 - 10 fresh lasagne sheets (15 x 11 cm/6 x 4.5\") (Note 1)","1 cup mozarella cheese (, shredded)","1 tbsp olive oil (for drizzling later)"]},{"ingredients":["500g / 1 lb frozen spinach (pre chopped) (, thawed and excess water squeezed out (Note 2))","500 g / 1 lb ricotta cheese (NOT smooth, whipped or spreadable in tubs, Note 3)","1 cup mozzarella cheese (, shredded)","1 egg","1/2 cup parmesan cheese (, shredded)","1 garlic clove (, pressed using garlic crusher or finely grated)","1/8 tsp finely grated nutmeg (substitute nutmeg powder)","3/4 tsp salt","1/2 tsp Black pepper"],"purpose":"Filling"},{"ingredients":["2 tbsp olive oil","2 cloves garlic (, minced)","1/2 onion (, finely diced (brown, yellow, white))","3/4 tsp salt","1/2 tsp black pepper","700 g / 24 oz tomato passata (US: Tomato puree) (Note 5)","1 1/2 cups water","Handful basil leaves (optional)"],"purpose":"Tomato Sauce"}]', '[{"description":"Heat oil in a 25cm/10\" ovenproof skillet over medium high heat. (Note 6)","images":[],"step":1},{"description":"Add garlic and sauté for 10 seconds then add onion.","duration":0.16666666666666666,"images":[],"step":2},{"description":"Cook onion until translucent and starting to turn golden, then passata, water, chilli flakes (if using), salt and pepper.","images":[],"step":3},{"description":"Simmer for 5 minutes on medium low, then stir through basil. Should be quite thin - the lasagna sheets will absorb water while in the oven so sauce thickens alot in oven.","duration":5,"images":[],"step":4},{"description":"Scoop out 1 cup of the Tomato Sauce which will be used to drizzle over the dish at the end. Keep sauce warm.","images":[],"step":5},{"description":"Filling & Assembling:","images":[],"step":6},{"description":"Preheat oven to 180°C/350CF (all oven types)","images":[],"step":7},{"description":"Place Filling ingredients in a bowl. Mix well with wooden spoon.","images":[],"step":8},{"description":"As per the photo & video, lay out the lasagne sheet with the shorter end in front of you.","images":[],"step":9},{"description":"Place 1/3 cup (packed) of filling onto the lasagne sheet. Dab some water on the end furthest away from you (to seal the roll), then roll up starting from the end closest to you. Finish with the seal down.","images":[],"step":10},{"description":"Cut rolls into 3 (so each piece is 3.5cm/1.5\" wide). Place the rolls into the tomato sauce with the filling facing up.","images":[],"step":11},{"description":"Repeat with remaining lasagna sheets until all the Filling is used up.","images":[],"step":12},{"description":"Drizzle the reserved Tomato Sauce over (don''t cover completely, leave some exposed).","images":[],"step":13},{"description":"Cover loosely with foil, bake 30 minutes.","images":[],"step":14},{"description":"Remove from oven, remove foil. Drizzle with oil, top with mozzarella.","images":[],"step":15},{"description":"Bake 15 minutes or until the cheese is bubbly and golden and you''ve got some crunchy golden bits on the edges. Serve!","images":[],"step":16}]', '["egg","milk"]', '["gluten_free","high_protein","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["casseroles-and-cosy-bakes","italian-recipes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-bakes","pasta-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_00a5320dffe7', 'en', 'US', 'Creamy Pasta Bake "formula" - make this with ANYTHING!', 'Recipe video above. This is a "formula" using a creamy white sauce to make a pasta bake using anything you''ve got. Add in literally any meat, raw or cooked, any vegetable (frozen, canned, dried, fresh, pickled). Canned tuna or salmon, bacon, ham, chorizo. You''re only limited by your imagination! (Eer - and what''s in your pantry 😂) If using raw meat and veg that needs to be cooked, cook them first then make the sauce in the same pot. If using add ins like canned salmon and corn that do not need pre cooking, just make the sauce and mix it up with the pasta, then bake until bubbly and golden! See above in post for combination suggestions.', 'https://www.recipetineats.com/tachyon/2020/03/Creamy-pasta-bake-make-with-anything-1.jpg', 15, 40, 55, 8, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 1.25, "unit": "L"}}, {"id": "ing_stock_bouillon_cube_or_powder", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}]', '[{"ingredients":["500g / 1lb pasta (any short or long except risoni/orzo) (Note 1)","1 tbsp salt (for water)"]},{"ingredients":["4 tbsp (60g) butter (, unsalted)","2 garlic cloves (, minced (optional, sub 1 tsp powder))","5 tbsp flour (, any (GF option Note 2))","5 cups (1.25 litres) milk (, any fat, any type)","2 tsp stock / bouillon cube or powder (, chicken or veg)","3/4 cup (75g) parmesan","1/2 tsp black pepper"],"purpose":"Creamy Sauce (Note 2 for subs)"},{"ingredients":["1 tsp EACH thyme and parsley (, or any other dried herbs)","1/2 tsp EACH mustard, garlic, onion powder"],"purpose":"Choose ONE flavouring (optional)"},{"ingredients":["8 cups Add Ins - raw or cooked meats, bacon, ham, diced vegetabes (frozen, canned, fresh), canned or fresh fish (Note 3)"],"purpose":"Add Ins"},{"ingredients":["1 tbsp olive oil","Salt and pepper"],"purpose":"For Cooking RAW Add Ins (like raw chicken, mushrooms, zucchini)"},{"ingredients":["2 cups (200g) cheese (, shredded (Note 4))"],"purpose":"Cheesy Topping"}]', '[{"description":"Preheat oven to 180°C/350°F.","images":[],"step":1},{"title":"Pasta","description":"Boil water with 1 tbsp salt. Add pasta, bring back up to boil then cook per packet directions MINUS 2 minutes. Should be just cooked, still slightly firm in middle. Drain, return to pot.","images":[],"step":2},{"description":"Cooking RAW Meat & Vegetables","images":[],"step":3},{"description":"Heat half butter & 1 tbsp oil in a large pot over high heat. Stir in garlic for 10 seconds, then cook your raw meat and vegetables with a sprinkle of salt and pepper. Meat must be fully cooked - will not cook further in oven.","duration":0.16666666666666666,"images":[],"step":4},{"description":"Add remaining butter, melt. Mix in flour, then follow Creamy Sauce step 2 onwards.","images":[],"step":5},{"description":"Start here if you have NO COOK Add Ins (like canned tuna): Melt butter in large saucepan over medium heat. Add garlic and stir for 10 seconds, then stir in flour.","duration":0.16666666666666666,"images":[],"step":6},{"description":"While mixing, gradually pour in about 1/3 of the milk. Once the flour-butter mixture is incorporated into the milk, pour in remaining milk and mix.","images":[],"step":7},{"description":"Add remaining milk, stock powder, parmesan, pepper and herbs (if using) and mix. When the milk starts to heat up, mix constantly to make sure the white sauce doesn’t catch on the base.","images":[],"step":8},{"title":"After 4","description":"5 minutes, the sauce should be thick enough that you can draw a path across the back of a spoon (see video).","images":[],"step":9},{"description":"Assemble & Bake","images":[],"step":10},{"description":"Return cooked pasta into pot. Mix with sauce and no-cook Add Ins.","images":[],"step":11},{"description":"Spread in large casserole dish, top with cheese and bake 25 minutes until golden and bubbly. Serve!","images":[],"step":12}]', '["fish","gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["casseroles-and-cosy-bakes","coronavirus-food","pasta-bakes","pasta-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d80d8f8b199f', 'en', 'US', 'Emergency Chicken Rice Casserole', 'Recipe video above. Dump-and-bake creamy chicken rice casserole made FROM SCRATCH! Perfectly cooked rice, creamy cheesy sauce, juicy seasoned chicken. Unusually high liquid-to-rice ratio because 1) baked uncovered (brown chicken); and 2) creamy rice (rather than stodgy!). See Note 7 re: SCALING recipe!', 'https://www.recipetineats.com/tachyon/2019/08/Ultra-Lazy-Chicken-Rice-Casserole_6.jpg', 10, 45, 55, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.003, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_white_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_broccoli", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}]', '[{"ingredients":["500g (1 lb) chicken thighs or tenders (tenderloin) (, cut into 1.5cm / 2/3\" pieces (Note 1))","1/2 tsp dried thyme","1 tsp garlic powder","1/2 tsp pepper","1/2 tsp vegetable or chicken stock powder (granulated bouillon) (Note 2)","1 tbsp olive oil"],"purpose":"Chicken:"},{"ingredients":["2 1/2 cups (625 ml) chicken broth/stock (, low sodium)","2 1/2 cups (625 ml) milk (, any fat %)","1 1/2 cups long grain white rice (, uncooked (Note 3))","1/4 cup (35g) flour (, plain / all purpose)","1 tsp vegetable or chicken stock powder (granulated bouillon) (Note 2)","2 cloves garlic (, minced)","2 tbsp (30g) unsalted butter","2 broccoli heads (large!), cut into florets (Note 4)","2 cups (200g) shredded cheese"],"purpose":"Rice:"},{"ingredients":["2 green onions (, finely sliced)"],"purpose":"Garnish:"}]', '[{"description":"Preheat oven to 190°C/375°F (180°C/350°F fan/convection).","images":[],"step":1},{"description":"Mix Chicken Ingredients.","images":[],"step":2},{"description":"Heat chicken broth and milk until hot using any method (stove, microwave). Can combine together in saucepan. (Note 5)","images":[],"step":3},{"description":"Spread rice in 23 x 33cm / 9 x 13\" ceramic or glass baking dish. (Note 6)","images":[],"step":4},{"description":"Sprinkle with flour, stock powder and garlic.","images":[],"step":5},{"description":"Add the hot chicken broth, stir until flour dissolved (some small lumps ok).","images":[],"step":6},{"description":"Add milk, swish rice to spread out evenly.","images":[],"step":7},{"description":"Spread broccoli on top, then chicken, then plonk butter on (anywhere).","images":[],"step":8},{"description":"Bake uncovered for 40 minutes. (Might get some browned skin on surface, that''s ok)","duration":40,"images":[],"step":9},{"title":"CHECK rice before stirring","description":"should be JUST cooked (Note 7).","images":[],"step":10},{"description":"Add half the cheese, stir through, being sure to get rice in the corners and edges of pan. Should be creamy and quite loose (see video).","images":[],"step":11},{"description":"Top with cheese, return to oven for 5 minutes until just melted.","duration":5,"images":[],"step":12},{"description":"Sprinkle with green onion, if using, then serve!","images":[],"step":13}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["casseroles-and-cosy-bakes","chicken-recipes","dinner-tonight","emergency-recipes","quick-and-easy","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a5140d9f013b', 'en', 'US', 'Vegetable Lasagna', 'Recipe VIDEO above. Layered with roasted vegetables, spinach and ricotta, a homemade sauce and as much cheese as you see fit, this big batch vegetarian lasagna reheats brilliantly. Epic meat-free food for carnivores!', 'https://www.recipetineats.com/tachyon/2019/02/Vegetable-Lasagna_10.jpg', 25, 50, 75, 8, '[{"id": "ing_pumpkin", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_spinach", "quantity": {"value": 250.0, "unit": "bag of 250g"}}, {"id": "ing_ricotta", "quantity": {"value": 2.0, "unit": "tub of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_rated_nutmeg_optional", "quantity": {"value": 75.0, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.075, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.825, "unit": "jar of 50g"}}, {"id": "ing_lasagne_sheets", "quantity": {"value": 375.0, "unit": "unit"}}, {"id": "ing_mozzarella", "quantity": {"value": 2.4, "unit": "pack of 125g"}}]', '[{"ingredients":["500 g / 1 lb pumpkin (, 2cm / 4/5\" cubes)","2 large zucchinis (, cut into 2cm / 4/5\" chunks)","2 onions (any type) (, cut into wedges)","2 tbsp olive oil","1 garlic clove (, minced)","Salt and pepper"],"purpose":"Roasted Vegetables (Note 1):"},{"ingredients":["250 g / 8 oz frozen chopped spinach (, thawed)","500 g / 1 lb ricotta (Note 2)","1/2 cup / 50 g grated parmesan (or 3/4 cup shredded cheese)","1 egg","1 garlic clove (, minced)","1/8 tsp grated nutmeg, optional (fresh or powder)","1/2 tsp each Salt and pepper"],"purpose":"Spinach Ricotta:"},{"ingredients":["1 tbsp olive oil","1 garlic clove","1 small onion (, finely chopped (any, I use brown))","700 g / 24 oz tomato passata (Note 3)","400 g / 14 oz crushed tomato","1/2 cup / 125 ml water","3/4 tsp each dried thyme and oregano (or basil, parsley)","1/2 tsp dried chilli flakes (can omit / adjust to taste)","Salt and pepper"],"purpose":"Sauce:"},{"ingredients":["330g / 11 oz jar roasted red pepper strips, drained (Note 4)","375 g / 13 oz fresh lasagne sheets (Note 5)","300 g / 3 cups shredded mozzarella (or MORE!)"],"purpose":"Lasagna:"}]', '[{"description":"Roasted Vegetables:","images":[],"step":1},{"description":"Preheat oven to 200C/390F.","images":[],"step":2},{"description":"Place vegetables on the tray, drizzle with oil, sprinkle with garlic, salt and pepper. Toss.","images":[],"step":3},{"description":"Roast for 25 minutes, turning at 15 minutes, until tender and browned.","duration":25,"images":[],"step":4},{"description":"Remove from oven, loosen from tray with spatula while warm (can stick when cools).","images":[],"step":5},{"description":"Heat oil in a skillet over medium high heat. Add garlic and onion, cook for 3 minutes until golden.","duration":3,"images":[],"step":6},{"description":"Add passata, crushed tomato, water, dried herbs, chilli, salt and pepper. Stir. Simmer on medium low heat for 20 minutes. Adjust salt at the end. *Add a teeny touch of sugar if it''s a bit sour, depends on quality of tomatoes used.*","duration":20,"images":[],"step":7},{"description":"Remove from stove and let cool for 5 minutes before using.","duration":5,"images":[],"step":8},{"description":"Ricotta Mixture:","images":[],"step":9},{"description":"Place ingredients in a bowl and mix until combined.","images":[],"step":10},{"description":"Preheat oven to 160C/320F.","images":[],"step":11},{"description":"Spread a ladle of tomato sauce on the base of a large baking dish (Note 5).","images":[],"step":12},{"description":"Cover with lasagna sheets, tearing as required to fit.","images":[],"step":13},{"description":"Top with roasted vegetables, scatter over red peppers. Spoon over 2 1/2 cups of Sauce, then sprinkle with half the cheese.","images":[],"step":14},{"description":"Cover with lasagna sheets. Spread over Ricotta mixture.","images":[],"step":15},{"description":"Cover with lasagna sheets. Pour over remaining sauce and sprinkle with remaining cheese.","images":[],"step":16},{"title":"Bake for 25","description":"30 minutes or until the cheese is golden. If using dried lasagna sheets, stick a knife in the middle to ensure it''s cooked - if it needs longer, cover and stick it back in the oven.","duration":27.5,"images":[],"step":17},{"description":"Rest for 5 minutes before cutting and serving. Store leftovers per notes - brilliant reheated!","duration":5,"images":[],"step":18}]', '["egg","milk"]', '["gluten_free","high_protein","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["casseroles-and-cosy-bakes","pasta-bakes","pumpkin","sunday-supper","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_27b2c3b8bbe3', 'en', 'US', 'Spinach Ricotta Cannelloni', 'Recipe VIDEO above. Juicy, perfectly seasoned spinach and ricotta filling inside cannelloni pasta tubes, topped with a simple, tasty tomato sauce and melted cheese. Great for freezing!First published in September 2017, this reader favourite recipe is included by popular demand in my debut cookbook Dinner. I took the opportunity to make it even better by increasing the volume and thinning the thickness of the sauce so there''s plenty of liquid to cook the cannelloni but it''s still saucy when you serve it up. It was great before, it''s AMAZING now!', 'https://www.recipetineats.com/tachyon/2017/09/Spinach-Ricotta-Cannelloni-1-copy-1.jpg', 25, 35, 60, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_tomato", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.033, "unit": "jar of 50g"}}, {"id": "ing_basil", "quantity": {"value": 0.4, "unit": "bunch"}}, {"id": "ing_spinach", "quantity": {"value": 250.0, "unit": "bag of 250g"}}, {"id": "ing_ricotta", "quantity": {"value": 2.0, "unit": "tub of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_nutmeg", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_cannelloni_tubes", "quantity": {"value": 18.0, "unit": "unit"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}]', '[{"ingredients":["2 tbsp olive oil","1 onion (, finely chopped)","4 garlic clove (, minced)","1 bay leaf (, fresh (sub dried))","1/2 tsp each dried thyme and oregano","1/3 cup tomato paste","800 g / 28 oz canned crushed tomato","4 cups vegetable or chicken stock/broth (, low sodium)","1/3 cup Chardonnay or other dry white wine (sub more stock)","3/4 tsp salt","1 1/2 tsp sugar","1/3 tsp black pepper","2/3 cup basil leaves (, roughly torn (recommended but not critical))"],"purpose":"Sauce (you need LOTS!):"},{"ingredients":["250 g / 8 oz frozen chopped spinach (, thawed (Note 1))","500 g / 1 lb ricotta (, full fat please (Note 2))","1/3 cup parmesan (, finely shredded)","1 cup shredded cheese (Mozzarella, Colby, Cheddar, Tasty, Gruyere, Swiss)","1 egg","1 large garlic clove (, minced)","Grated fresh nutmeg (just a sprinkling) ( or 1/8 tsp nutmeg powder (optional))","3/4 tsp cooking / kosher salt","1/2 tsp black pepper"],"purpose":"Filling:"},{"ingredients":["18 - 22 dried cannelloni tubes (250g pack) (or 14 manicotti tubes (8.8 oz) (Note 3))","1/3 cup parmesan (, finely shredded)","1 1/4 cups shredded Mozzarella","More basil and parmesan (, for garnish (optional))"],"purpose":"Cannelloni"}]', '[{"title":"Sauté","description":"Heat oil in a small pot over medium high heat. Add garlic, onion, bay leaf, thyme and oregano. Cook for 3 - 4 minutes until the onion is translucent. Add tomato paste and cook for 1 minute.","duration":3.5,"images":[],"step":1},{"title":"Reduce wine","description":"Add wine, increase heat to high and let it simmer rapidly until mostly evaporated (about 2 minutes).","images":[],"step":2},{"title":"Simmer","description":"Add tomatoes, stock, sugar, salt and pepper. Stir then simmer on medium low for 20 minutes.","duration":20,"images":[],"step":3},{"title":"Blitz","description":"Remove bay leaf then blitz with a stick blender until smooth. Simmer for 1 more minute then remove from the stove","images":[],"step":4},{"title":"Basil","description":"Stir in basil then cover to keep warm until required.","images":[],"step":5},{"title":"Squeeze spinach","description":"Place spinach in a colander and press out most of the liquid (don''t need to thoroughly squeeze dry).","images":[],"step":6},{"title":"Mix filling","description":"Place Spinach in bowl with remaining Filling ingredients. Mix, taste, adjust salt and pepper to taste (different cheeses have different saltiness).","images":[],"step":7},{"description":"Assemble & Bake:","images":[],"step":8},{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":9},{"title":"Pan","description":"Choose a baking pan which will comfortably fit about 20 cannelloni - mine is 21 x 26 cm / 8.5 x 10.5\".","images":[],"step":10},{"title":"Smear","description":"Spread 1 cup of Sauce on the base (stops cannelloni from sliding around).","images":[],"step":11},{"title":"Fill tubes","description":"Transfer Filling to a piping bag with a large nozzle (that fits in the tubes), or use a strong ziplock bag. Or do this step using a knife (it''s a bit tedious though!). Pipe the filling into the tubes.","images":[],"step":12},{"title":"Assemble","description":"Place cannelloni in baking dish. Pour over remaining Sauce, covering all the tubes.","images":[],"step":13},{"title":"Bake covered (but naked)","description":"Cover with foil, then bake for 30 minutes.","duration":30,"images":[],"step":14},{"description":"Cheese it! Remove foil, scatter over parmesan then mozzarella. Return to oven for 15 minutes until cheese is melted.","duration":15,"images":[],"step":15},{"description":"Serve, garnished with extra parmesan and basil if desired.","images":[],"step":16}]', '["egg","milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["American-Italian","Western"],"categories":["casseroles-and-cosy-bakes","dinner-tonight","italian-recipes","main-dishes","pasta-bakes","pasta-recipes","sunday-supper","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_925a38cdaefc', 'en', 'US', 'Creamy Seafood Pasta Bake', 'Pasta baked with mixed seafood in a creamy white béchamel sauce. It''s like a gratin made with pasta - which is why I describe this as French-ish! The key to getting gorgeous flavour in the sauce is searing the seafood in the skillet first, then making the sauce in the same skillet to soak up all those seafood flavours!', 'https://www.recipetineats.com/tachyon/2016/06/Seafood-Gratin-Pasta_10.jpg', 5, 30, 35, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.397, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_mixed_seafood", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_eek", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_panko", "quantity": {"value": 112.5, "unit": "jar"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["7 oz / 200 g macaroni or other pasta of choice","1 1/2 tbsp olive oil (, separated)","1 lb / 500 g mixed raw seafood (Marinara seafood mix) (Note 1)","2 leeks (, white and pale green part only finely sliced)","2 garlic cloves (, minced)"]},{"ingredients":["3 tbsp butter","3 tbsp flour","2 1/2 cups milk","1 chicken bouillon cube ((or 1 1/2 tsp chicken stock powder) OR 1/2 cup grated parmesan cheese)"],"purpose":"White Sauce"},{"ingredients":["3/4 cup panko","1/4 cup grated parmesan cheese (high recommended)","Finely chopped fresh parsley (optional)"],"purpose":"Topping"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Cook pasta according to packet directions. Drain and pour into baking dish.","images":[],"step":2},{"description":"Heat 1 tbsp oil in a skillet over very high heat. Add seafood and sear for 30 seconds, turn then sear the other side for 30 seconds (should still be raw inside). Remove into baking dish.","duration":0.5,"images":[],"step":3},{"description":"Return pan to stove, add remaining 1/2 tbsp oil and turn down to medium. Cook leeks and garlic for 3 minutes or until soft. Add to baking dish.","duration":3,"images":[],"step":4},{"description":"Mix pasta, seafood and leeks together in the baking dish.","images":[],"step":5},{"description":"Melt butter in the skillet. Add flour and mix into the butter. Cook for 1 minute,","duration":1,"images":[],"step":6},{"title":"Add 1 cup of milk and use a whisk to combine","description":"it will thicken quickly. Add remaining milk and bouillon cube (crumbled) and whisk to combine. Cook, whisking occasionally at first then constantly as it thickens, for around 5 minutes or until the sauce is thick enough to coat the back of a wooden spoon (see photo in post). Season with salt and pepper.","images":[],"step":7},{"description":"Pour into the baking dish. Top with panko and parmesan.","images":[],"step":8},{"title":"Bake for 20","description":"25 minutes, or until the top is golden.","duration":22.5,"images":[],"step":9},{"description":"Rest for 5 minutes before serving, garnished with fresh parsley if desired.","duration":5,"images":[],"step":10},{"description":"I served this with garlic spinach (Note 2).","images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["French-ish"],"categories":["casseroles-and-cosy-bakes","dinner-tonight","easter-mains-fish-seafood","main-dishes","pasta-bakes","prawns-shrimp","seafood-recipes","sunday-supper","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3b649b6d9511', 'en', 'US', 'One Pot Chicken Enchilada Rice Casserole', 'Everything you know and love about the flavour of Chicken Enchiladas.....but in the form of a rice casserole! And all made in ONE POT on the stove! I like the flow of this recipe because you don''t need to measure everything out in advance. After cooking the bell pepper (capsicum) add the passata and chicken broth, then while that comes to a simmer you can gather all the spices. Saves time! This recipe makes a LOT. Because it is carb heavy, I think it is enough to feed 6.', 'https://www.recipetineats.com/tachyon/2015/10/Mexican-Chicken-Enchilada-Rice-Casserole_600px.jpg', 15, 25, 40, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.562, "unit": "can of 400g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.0, "unit": "jar of 50g"}}, {"id": "ing_white_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp olive oil","400g (13oz) chicken breast, about 1/3\"/1cm thick, sliced horizontally into thin steaks (Note 1)","1 small onion, diced","3 cloves garlic, crushed","1 red bell pepper/capsicum, diced","680g (24oz) tomato passata or crushed canned tomatoes* (Note 2)","3 cups chicken broth or water (750ml)","1 1/2 cups frozen corn (250g)","1/2 tsp cayenne pepper* (spicy - adjust to taste)","1 tbsp dried oregano*","2 tsp cumin*","1 1/2 tsp coriander*","2 tsp onion powder*","1 tbsp brown sugar*","Salt and pepper","1 1/2 cups (270g) white rice (short, medium or long grain (, uncooked (Note 4))","1 - 1 1/2 cups grated cheese (about 125 - 150 g)"]},{"ingredients":["Chopped cilantro/coriander (optional)"],"purpose":"To Serve"}]', '[{"description":"Heat olive oil over medium high heat in large skillet.","images":[],"step":1},{"description":"Add chicken and cook each side for 2 minutes or until cooked, then remove onto a plate.","duration":2,"images":[],"step":2},{"description":"Add extra oil if the skillet is looking dry. Add onion and garlic, cook for 1 1/2 minutes until starting to soften.","images":[],"step":3},{"description":"Add bell peppers and cook for a further 2 minutes.","images":[],"step":4},{"description":"Add remaining ingredients except rice and cheese. Bring to simmer, then add rice.","images":[],"step":5},{"description":"Stir, cover with a lid and turn down heat to medium low. Cover and cook until rice is cooked but not mushy and most of the liquid is absorbed - about 15 to 18 minutes. (Note 3). Do not stir while it cooks.","images":[],"step":6},{"description":"Meanwhile, shred or roughly chop chicken.","images":[],"step":7},{"description":"When rice is cooked, quickly stir chicken through, sprinkle with cheese then pop under broil / grill until golden and bubbly.","images":[],"step":8},{"description":"Serve, garnished with fresh cilantro/coriander if desired.","images":[],"step":9}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Tex-Mex"],"categories":["casseroles-and-cosy-bakes","chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","mexican-recipes","most-popular","one-pot-recipes","quick-and-easy","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f16048e380e6', 'en', 'US', 'One Pot Creamy Tomato Chicken Pasta Bake (no cream)', 'A pasta bake, cooked entirely in one pot! The sauce is creamy and tomatoey but is made without a drop of cream, making this a great midweek meal.', 'https://www.recipetineats.com/tachyon/2015/04/One-Pot-Creamy-Tomato-Pasta-Bake_action_680px1.jpg', 5, 30, 35, 6, '[{"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.09, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.9, "unit": "pack of 500g"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.6, "unit": "pack of 125g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["4 tbsp unsalted butter","1 small onion (, diced)","2 garlic cloves (, minced)","6 tbsp / 1/2 cup plain flour","2 cups milk (500ml)","2 cups tomato passata (500ml) (Note 1)","1 cup water (or chicken or vegetable broth) (250ml)","2 tsp salt","Black pepper","3 cups dried ziti / penne pasta (uncooked)","2 cups shredded cooked chicken","1 cup shredded cheddar cheese","3/4 cup shredded mozzarella cheese","Pepper"]},{"ingredients":["Fresh basil leaves","Freshly grated parmesan"],"purpose":"Garnish (optional)"}]', '[{"description":"Preheat oven to 350F/180C.","images":[],"step":1},{"description":"Melt butter in a deep fry pan or skillet (Note 2) over medium heat. Add the onion and garlic and sauté for 5 minutes until translucent. Add the flour and stir to combine, then cook for 2 minutes.","duration":5,"images":[],"step":2},{"description":"Add the milk and whisk for 1 minute, in small circles around the fry pan, until it starts to thicken. Then add the tomato passata, water, salt and pepper. Increase the heat to medium high and cook for around 5 minutes or until thick enough to coat the back of a metal spoon (see photo below). Whisk occasionally for the first 3 minutes, then whisk constantly for the last 2 minutes.","duration":1,"images":[],"step":3},{"description":"Do a taste test and add 1 to 2 tsp of sugar if it is a bit sour (depends on quality of passata you use).","images":[],"step":4},{"description":"Add the ziti/penne, chicken and cheddar cheese and mix through. Leave it to cook for around 1 minute on the stove, then take it off the stove.","images":[],"step":5},{"description":"Scatter with mozzarella cheese. Cover with a lid or foil (Note 3) and bake for 10 minutes. Remove the lid/foil and bake for a further 5 minutes. Rest for 5 minutes before serving, garnished with fresh basil leaves and grated parmesan, if desired.","duration":10,"images":[],"step":6}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["casseroles-and-cosy-bakes","chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","pasta-bakes","pasta-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_99a6e56f28ad', 'en', 'US', 'Chinese eggplant and minced pork - Sichuan Fish Fragrant Eggplant', 'Recipe video above. Tried making this iconic Sichuan dish before and been underwhelmed? This one’s the real deal! Called Yu Xiang Qie Zi, this is straight from our RTM Chef Hannah, born and raised in the Sichuan province of China, a family of chefs at that! Even her chef father gave this recipe his rare stamp of approval.🙌🏻For full authenticity, grab broad bean sauce and pickled chilli from an Asian store. That said, our supermarket-sub version is so good, we’d have happily shared it - if we hadn’t already tasted the OG!Traditionally, the eggplant is deep fried (and yes, that’s why it’s so melt-in-your-mouth good). But see Note 1 for a fantastic no-fry pan-steamed option! Spiciness - Low mild. There''s not that much chilli in it!', 'https://www.recipetineats.com/tachyon/2025/05/Chinese-eggplant-with-minced-pork_7.jpg', 10, 20, 30, 4, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_pork_mince", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 7.5, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_broad_bean_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.019, "unit": "pack of 400g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.01, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_honey", "quantity": {"value": 0.01, "unit": "jar of 500g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.018, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 cup vegetable oil (, or canola, sunflower oil (Note 1 for no-fry version))","1 large eggplant or 2 medium/small (450 to 500g), cut into 7 x 1.5cm batons (2.7 x 0.6\"), skin on (Note 2)","100g / 3.5 oz pork mince / ground pork (Note 3)","1 tbsp ginger (, finely minced)","1 1/2 tbsp garlic (, finely minced)","1 green onion (, finely sliced, white & pale green part (for cooking) separated from the green part (garnish))","1 tsp pickled red chilli (, or any pickled spicy peppers (Note 4))","1 tbsp broad bean sauce (, we use Pixian doubanjiang, the spicy Sichuan version(Note 5))"]},{"ingredients":["1 1/2 tsp cornflour / cornstarch","1 tbsp light soy sauce (Note 7)","1/2 tsp dark soy sauce (Note 7)","1 1/2 tbsp sugar","1 tsp honey","3 1/2 tsp black vinegar (Note 8)","1/2 cup water"],"purpose":"Sauce:"},{"ingredients":["White rice"],"purpose":"Serving:"}]', '[{"title":"ABBREVIATED","description":"Mix sauce. Fry eggplant until soft. Keep 2T oil. Cook pork 2 min, then garlic, ginger and white part green onion for 30 sec. Cook chilli + broad bean sauce 1 min. Add eggplant and sauce in 2 batches, once thickened, serve!","duration":0.5,"images":[],"step":1},{"title":"Sauce","description":"Mix the cornflour and light soy in a jug until lump free. Add the remaining Sauce ingredients and mix to combine. Set aside.","images":[],"step":2},{"title":"Fry eggplant","description":"Heat oil in a wok on high heat until hot - 180°C/350°F. Add half of the eggplant and fry for around 4 minutes, stirring and turning gently a few times, until soft all the way through and a bit browned on the surface. Remove with a slotted spoon onto a paper towel lined tray. Repeat with remaining eggplant.","images":[],"step":3},{"title":"Remove oil","description":"Carefully remove the leftover oil from the wok except 2 tablespoons, for cooking.","images":[],"step":4},{"title":"Stir fry","description":"Cool the wok slightly then return to high heat. Add the pork and cook for 1 - 2 minutes, breaking it up as you go, until you no longer see pink. Add garlic, ginger, white part of the green onion. Stir fry for 30 seconds. Add pickled red chilli and broad bean sauce. Cook for 1 minute.","duration":1.5,"images":[],"step":5},{"title":"Add sauce","description":"Give the Sauce a quick mix (to dissolve settled cornflour). Add eggplant, then add half the Sauce into the wok, toss gently until the sauce starts thickening - about 30 to 45 seconds. Add remaining Sauce, toss gently for 45 seconds until it thickens (goal: between maple syrup and honey).","duration":0.75,"images":[],"step":6},{"title":"Serve","description":"Turn off heat. Pour into a serving bowl, sprinkle with green onion. Serve with rice!","images":[],"step":7},{"description":"Healthier pan-steamed eggplant option:","images":[],"step":8},{"title":"Brown eggplant","description":"Heat 2 tbsp oil in a large non-stick pan (with lid) over medium high heat. Pan fry eggplant for 1 1/2 minutes on each side until lightly browned.","images":[],"step":9},{"title":"Steam","description":"Carefully add 1/3 cup water around the eggplant (it will steam, so be careful). Immediately cover with a lid to trap the steam. Steam for 2 minutes or until the water has evaporated and the eggplant is soft all the way through (if needed, add more water and keep steaming).","duration":2,"images":[],"step":10},{"title":"Proceed","description":"Transfer eggplant to a plate. Proceed with recipe using the large non stick pan rather than wok.","images":[],"step":11}]', '["gluten","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Chinese","Sichuan"],"categories":["chef-hannahs-recipes","chinese-recipes","iconic-dishes","mains","pork","pork-recipes","stir-fries"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6be9bb6dd6de', 'en', 'US', 'Tuscan Chicken Stew', 'Recipe video above. This is a 30 minute creamy white stew filled with seared Italian-seasoned chicken, sun dried tomatoes, burst-in-your-mouth cherry tomatoes, meaty white beans and swirls of spinach in a garlicky parmesan sauce. It''s not authentic Italian but I think it channels Tuscan vibes with the bright colours of Italy, in a bowl!', 'https://www.recipetineats.com/tachyon/2026/06/Tuscan-chicken-stew-5.jpg', 13, 22, 35, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 100.0, "unit": "bag of 250g"}}]', '[{"ingredients":["600g / 1.2 lb chicken thighs (, boneless skinless (or breast), cut into large bite size pieces 3 - 4 cm / 1.2 - 1.4\" (Note 1))"]},{"ingredients":["1 1/2 tsp Italian herb mix (store bought mix, or see Note 2)","1/2 tsp garlic powder","1/2 tsp cooking salt / kosher salt (halve for table salt, +50% for flakes)","1/4 tsp black pepper"],"purpose":"Chicken seasoning:"},{"ingredients":["1 1/2 tbsp olive oil","1 onion (, halved and sliced into 1cm / 0.4\" wedges)","3 garlic cloves (, finely minced)","1/2 cup (100 g) sun dried tomatoes (, cut into 0.5cm / 0.2\" slices (Note 3))","200g (1 1/4 cups) cherry or grape tomatoes (1 punnet)","2 x 400g/14oz cans butter beans (large lima beans), drained - or cannellini, Great Northern or other white beans (Note 4)","1/3 cup Chardonnay or other dry white wine (, substitute chicken stock/broth (Note 5))","1/3 cup plain flour / all-purpose flour (Note 6 for gluten-free)","3 cups chicken stock / broth (, low sodium)","3/4 cup thickened cream / heavy cream (, or any full fat cream ~35% fat)","1/2 cup parmesan (, finely grated or store bought sandy-type - substitute with cheddar, tasty or other sharp cheese)","100g / 3.5oz baby spinach (, or a few big handfuls torn kale)"],"purpose":"Stew:"}]', '[{"description":"Season chicken, sear. Sauté onion and garlic. Deglaze with wine, stir in flour, then stock. Add beans and sun dried tomato, simmer 7 minutes. Add cream, parmesan and cherry tomatoes, simmer 8 minutes. Stir in spinach, serve!","images":[],"step":1},{"title":"Season and sear chicken","description":"Sprinkle chicken with the seasoning and toss to coat. Heat the oil on high in a 30 cm / 12\" non stick pan until very hot. (Note 7 re: cooking vessel) Add the chicken, spread it out, then leave it for 30 seconds or so until golden. Then start stirring, leaving it for 20 seconds every now and then to get colour on the pieces, until most of the pieces are light golden.","duration":0.5,"images":[],"step":2},{"title":"Sauté onion","description":"Lower heat to medium high. Add onion and garlic then cook for around 2 minutes until the onion is wilted.","images":[],"step":3},{"title":"Deglaze and add flour","description":"Turn the heat back up to high. Add the wine and let it simmer for 1 - 2 minutes until reduced by half. Add flour and stir until it is mixed in.","duration":1.5,"images":[],"step":4},{"title":"Make sauce","description":"Slow pour in a third of the stock, mixing as you go. The flour will make the liquid turn into a thick sauce quite quickly. Then add the rest of the stock, beans and sun dried tomato, and stir well.","images":[],"step":5},{"title":"First simmer 7 minutes","description":"Bring to a simmer. Lower heat to medium or medium high so it''s simmering, not too rapidly. Simmer 7 minutes, stirring every now and then.","images":[],"step":6},{"title":"Second simmer 8 minutes","description":"Add cherry tomatoes, cream and parmesan. Mix and simmer for 8 minutes. The sauce should be reduced and thicken into a gravy consistency.","duration":8,"images":[],"step":7},{"title":"Wilt spinach","description":"Stir spinach in to make it wile (~ 30 seconds). Ladle into bowls, garnish with extra parmesan and chilli flakes if desired. Serve with warm crusty bread for dunking!","images":[],"step":8}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian-esque","Western"],"categories":["chicken","chicken-recipes","mains","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_894df79de4d0', 'en', 'US', 'Coconut Chicken Curry - quick and easy', 'Recipe video above. This Coconut Chicken Curry proves you don’t need a long list of spices or a jar of curry paste to make a truly Indian-tasting curry - just 3 simple spices and very little effort. Tastes like a coconut-y Rogan Josh! I love that it''s made from scratch rather than using a jar of paste. I''ve used chickpeas to fill this out and add a nice nutty crunch just by opening a can, but you could use diced potatoes instead. Stirring in a handful of spinach at the end wouldn''t go astray either.Bonus - It makes a good amount so there''s enough for lunch tomorrow.Spice level - None. Feel free to add some with cayenne pepper or using a HOT curry powder!', 'https://www.recipetineats.com/tachyon/2026/04/Coconut-chicken-curry-quick-easy_7.jpg', 15, 20, 35, 5, '[{"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 7.5, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.75, "unit": "jar of 50g"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.6, "unit": "carton of 250ml"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_naan", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["2 tbsp unrefined coconut oil (virgin), ie coconut flavoured, or butter, ghee, or any cooking oil you want (Note 1)","500 g/1lb boneless chicken thighs (, cut into ~2cm / 0.8\" pieces (Note 2))","1 large onion (, diced)","1 1/2 tbsp garlic (, finely grated using a microplane (~6 large cloves))","1 1/2 tbsp ginger (, finely grated using a microplane)","2 1/2 tbsp curry powder (, mild - just regular ones like Clives, Keens (feel free to use HOT for spicy!))","1 tsp cumin powder","1 tsp turmeric powder","1/4 cup tomato paste","1 1/2 cups chicken stock/broth (, low sodium)","400g / 14oz coconut cream (substitute coconut milk), full fat (Note 3)","400g / 14oz can chickpeas (, drained)","1 1/4 tsp cooking salt / kosher salt (halve for table salt, double for flakes)"]},{"ingredients":["Plain yogurt (, slightly thinned with water to make it drizzle-able)","Coriander leaves (cilantro) (, roughly chopped, recommended)","Basmati rice ((you''ll need to cook 3 cups rice grains to make enough) or other rice of choice)","Naan (, optional)"],"purpose":"Serving:"}]', '[{"description":"Melt oil, sauté onion, then garlic and ginger. Toast spices, then tomato paste, coat chicken. Reduce chicken stock by half (5 min), then add coconut, chickpeas and salt. Simmer rapidly 8 min, stand 5 min then serve over rice.","images":[],"step":1},{"title":"Sauté","description":"Melt the coconut oil in a large pot over medium high heat (or a large deep skillet). Add the onion and cook for 2 minutes, until translucent. Add the garlic and ginger, stir constantly for 30 seconds (scrape base if it starts to stick).","duration":2,"images":[],"step":2},{"title":"Toast spices","description":"Add the curry powder, turmeric and cumin. Stir for 15 seconds, taking care to make sure it doesn''t stick and burn on base (if it does, add splash of water).","duration":0.25,"images":[],"step":3},{"title":"Coat chicken","description":"Add tomato paste and stir to coat all the onion, then add the chicken and stir to coat.","images":[],"step":4},{"title":"Reduce chicken stock 5 minutes","description":"Add the chicken stock, stir well, then once it starts bubbling, simmer rapidly for 5 minutes to reduce the liquid, stirring once in a while (adjust heat as needed, we want rapid bubbles - this is a speedy recipe remember!).","duration":5,"images":[],"step":5},{"title":"Simmer 8 minutes","description":"Add the coconut cream, chickpeas and salt. Stir well, bring back up to a simmer then simmer rapidly for 8 minutes, stirring every now and then. The sauce should be creamy but a little thinner than you''d expect.","duration":8,"images":[],"step":6},{"title":"Serve","description":"Remove the pot from the stove and leave to cool for 5 minutes, during which time the sauce will thicken a bit more. Serve over basmati rice with a drizzle of yogurt and sprinkle of fresh coriander. I wouldn''t say not to a warm naan or flatbread either. :)","duration":5,"images":[],"step":7}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Indian","Western"],"categories":["chicken-recipes","curry-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_28036739f338', 'en', 'US', 'JB''s Chicken au Poivre (Creamy Peppercorn Sauce)', 'Recipe above video. Inspired by Steak with Creamy Peppercorn Sauce (Steak au Poivre), one of my all-time favourites. This recipe has the same creamy pepper sauce with brandy and cream, just swapped for golden chicken. “Chicken au Poivre” is a perfect quick mid-week dinner with a French accent!', 'https://www.recipetineats.com/tachyon/2026/02/Chicken-Au-Poivre_4-copy.jpg', 8, 20, 28, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.2, "unit": "jar of 50g"}}, {"id": "ing_brandy", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}]', '[{"ingredients":["2 large chicken breasts (, skinless & boneless (250–300g / 8–10oz each) (Note 1))","3/4 tsp cooking salt / kosher salt","2 tbsp vegetable oil (, or any other neutral flavoured oil)"]},{"ingredients":["2 tsp whole black peppercorns (, coarsely crushed (Note 2))","1/3 cup brandy or cognac (, or masala (Note 3))","1 1/2 cups beef stock / broth (, low sodium (Note 4))","3/4 cup thickened / heavy cream (, or any other full fat cream)"],"purpose":"SAUCE AU POIVRE"}]', '[{"description":"Season chicken with salt. Sear in oil until golden. Remove. Deglaze with cognac. Add beef stock, simmer for 4 minutes . Pour cream, add pepper and simmer for 5 minutes. Return chicken, cook for 3 minutes while basting. Serve immediately.","duration":4,"images":[],"step":1},{"title":"Prepare the chicken","description":"Cut each chicken breast in half horizontally to make 4 thin steaks and sprinkle both sides with salt (If you’re wondering why I don’t season the chicken with pepper it’s because once combined with the sauce, it would make the dish too peppery.)","images":[],"step":2},{"title":"Sear the chicken","description":"Heat oil in a large pan (28cm / 11\") over high heat. Add chicken and cook 2–3 minutes per side until golden. Remove to a plate and rest (don’t cover). If you think your chicken is still a little bit under after resting, don’t worry it will finish cooking later in the sauce.","images":[],"step":3},{"title":"Deglaze with brandy","description":"TURN THE STOVE OFF to avoid the brandy catching fire (unless you want to flambé). Then carefully pour the brandy in. Be careful, it will sizzle hard, that’s normal. Let it bubble for 20-30 seconds to let alcohol burn off, reduce by about 2/3 (turn the stove on if needed). Scrape the fond at the base of the pan well to release all that flavour. (Note 5 & 6)","duration":0.4166666666666667,"images":[],"step":4},{"title":"Beef stock","description":"Turn the heat back on high. Add beef stock. Simmer rapidly for 4 minutes, until reduced by half.","duration":4,"images":[],"step":5},{"title":"Cream","description":"Stir in cream and crushed pepper. Lower the heat to medium high. Simmer for 3-4 minutes, to reduce the sauce until it thickens enough to lightly coat the back of a spoon. Stir and scrape the sides of the pan as it reduces. Keep in mind that some stoves run stronger than others. If the heat is gentler, the sauce may take a little longer to reduce, so just allow a bit of extra time.","duration":3.5,"images":[],"step":6},{"title":"Simmer","description":"Turn heat down to medium. Return chicken and resting juices to the pan. Cook 2–3 minutes, spooning the sauce over the chicken, until it is warmed through and the sauce darkens in colour and thickens a little more. When you drag a spoon through the pan, the sauce should slowly flow back together. If it thickens too much, add a splash of cream or water to loosen.","images":[],"step":7},{"title":"Serve","description":"This dish is best served straight away. If it sits, the sauce can become too thick and the chicken be overcooked.","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","jbs-recipes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_60c11623ffdd', 'en', 'US', 'Kalimera''s Famous Greek Chicken Gyros', 'Recipe video above. This Chicken Gyros recipe was given to me by Thomas Deliopoulos, the owner of Kalimera Souvlaki Art which is a wildly popular gyros bar in Melbourne. It''s ridiculously, unbelievably, eye-rollingly good that has top chefs like Australia''s Ben Shrewry and New York Times food critic Sam Sifton raving!Thomas’s secret is a touch of curry powder in the marinade. Yes, really!At Kalimera, the chicken is cooked on a vertical spit layered with fat, but even on the BBQ or stove, it’s ridiculously good. I''ve made it for many people now, and everyone is nuts for it!', 'https://www.recipetineats.com/tachyon/2025/10/Kalimera-Greek-Chicken-Gyros_8.jpg', 20, 10, 1470, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.25, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_thick_cut_chips", "quantity": {"value": 400.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.113, "unit": "jar of 400g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 9.0, "unit": "head"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_bread", "quantity": {"value": 5.0, "unit": "loaf"}}]', '[{"ingredients":["1.25 kg / 2.5 lb chicken thighs, skinless boneless"]},{"ingredients":["1 tbsp sweet paprika (ie regular paprika, not smoked not spicy)","1 tbsp mustard powder (substitute with Dijon mustard)","1 tbsp dried oregano (Greek, if you''ve got it)","1/2 tbsp curry powder (, mild not spicy *secret ingredient!* (Note 2))","1 1/2 tsp cooking salt / kosher salt (halve if using table salt, +50% if using flakes)","1/2 tsp black pepper","1/3 cup extra virgin olive oil"],"purpose":"Kalimera''s chicken gyros marinade"},{"ingredients":["400g / 14oz thick-cut chips (, frozen - optional (Note 3))","Pinch table salt (, for the chips (or chicken salt))"],"purpose":"Hot chips"},{"ingredients":["1 cup plain yoghurt (, preferably Greek or Greek-style)","3 tbsp whole-egg mayonnaise (, substitute regular mayonnaise)","3 tbsp extra virgin olive oil","2 tbsp yellow American mustard ((yes, really!) - substitute with Dijon mustard, not hot English mustard, too spicy)","2 tsp garlic powder","2 tsp sweet paprika","1/2 tsp cooking salt / kosher salt"],"purpose":"Kalimera gyros sauce:"},{"ingredients":["2 tomatoes (, halved and sliced)","3 cups cos lettuce (romaine) (, finely sliced (5mm / 0.2\"))","1/2 small red onion (, diced (5mm / 0.2\" squares))","5 x 20cm / 8\" pita breads, (the slightly bready kind if you can (Note 5))"],"purpose":"To serve"}]', '[{"description":"Marinate chicken overnight (minimum 3 hours). Mix sauce, make chips. Cook chicken, rest 3 minutes, assemble gyros as follows: Sauce, chicken, lettuce, tomato, onion, chips, sauce. Fold, devour!","images":[],"step":1},{"title":"Marinate chicken","description":"Mix the marinade ingredients in a large bowl. Add the chicken and mix well to coat. Marinate in the fridge for 24 hours (absolute minimum 3 hours!)","images":[],"step":2},{"description":"Before cooking:","images":[],"step":3},{"title":"Sauce first","description":"Mix the ingredients in a bowl and set aside for at least 20 minutes to let the flavours meld.","images":[],"step":4},{"title":"Chips next","description":"If using hot chips, make them before cooking the chicken using whatever method suits - baked, fry, air fry. (I bake for convenience and fry to impress.) Season with salt to taste (sorry, you''re going to have to eat one!) Keep them warm in a 100°C/200°F oven while you cook the chicken.","images":[],"step":5},{"description":"Cooking the chicken gyros","images":[],"step":6},{"title":"BBQ option (recommended!)","description":"Preheat the BBQ on medium high (the grill side preferred, flat iron also works). No need to oil the grills. Cook the chicken for 3 - 4 minutes on each side until deep golden with slightly charred edges.","duration":3.5,"images":[],"step":7},{"title":"Stove cook","description":"Heat a large non stick pan over medium high heat (no oil required). Cook the chicken in batches for 3 - 4 minutes on each side until deep golden and cooked through (internal temperature 72°C/162°F). Give the pan a quick wipe with paper towels between batches, to remove excess black bits.","duration":3.5,"images":[],"step":8},{"title":"Remove & rest","description":"Remove chicken onto a tray. Loosely cover with foil and rest for 3 minutes, then slice into 1 cm / 0.4\" pieces.","duration":3,"images":[],"step":9},{"description":"Heat the pita bread until warm and pliable. Honestly, microwave is so easy (stack on plate, 45 sec - 1 1/2 minutes on high). For stove, brush each side with water then heat in lightly oiled non-stick pan for 1 minute on each side (medium high), don''t let it go crispy else it will crack when folded.","duration":1,"images":[],"step":10},{"title":"Wrapping","description":"Spread 3 tablespoons of the sauce down the middle. Pile the chicken onto the sauce, add lettuce and tomato on one side. Sprinkle with red onion, pile chips on top, drizzle with more sauce. Fold to enclose, wrap in foil to keep everything in place.","images":[],"step":11},{"description":"Serve gyros with extra sauce for dunking!","images":[],"step":12}]', '["egg","milk","mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["chicken-recipes","greek-recipes","mediterranean-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4827ac1b72ac', 'en', 'US', 'JB''s Chicken Chasseur', 'Recipe video above. Chicken Chasseur (chasseur is French for “hunter”) is a classic French dish made with pieces of chicken cooked in a rich mushroom and tomato sauce with a gentle touch of brandy, finished with fresh tarragon. It’s rustic and cosy, and it was the first recipe I learned to master at cooking school back in France. - JB', 'https://www.recipetineats.com/tachyon/2025/10/Chicken-Chasseur-JB_7.jpg', 15, 45, 60, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_brandy", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_tarragon", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["4 chicken thighs, bone-in, skin on (~250g/8oz each) (Note 1)","4 chicken drumsticks (Note 1)","3/4 tsp cooking salt / kosher salt","1/2 tsp black pepper","3 tbsp plain flour (all-purpose flour)","2 tbsp vegetable oil (or any other neutral flavoured oil)","30g / 2 tbsp unsalted butter"]},{"ingredients":["400g / 14oz white mushrooms (, sliced 6mm/0.2”)","2 onions (, brown or yellow, halved then sliced 6mm/0.2” thick)","3 garlic cloves (, finely minced)","1/4 cup brandy (Note 2)","1/2 cup chardonnay or other dry white wine (Note 3)","3 tbsp tomato paste","2 1/2 cups beef stock (, low-sodium (note 4))","3/4 tsp cooking salt/kosher salt","1/4 tsp black pepper","30g / 2 tbsp unsalted butter (, COLD and cubed (KEEP REFRIGERATED until required) )","1 tbsp fresh tarragon (, finely chopped (Note 5))"],"purpose":"Sauce Chasseur"},{"ingredients":["Creamy mashed potato (or rice or small pasta)"],"purpose":"For serving"}]', '[{"description":"Abbreviated Recipe","images":[],"step":1},{"description":"Season and flour the chicken, then brown in oil and butter. Remove. Sauté mushrooms and onion, add garlic briefly, then pour in brandy and wine to reduce. Stir in tomato paste for 1 minute, then stock, salt, and pepper. Return chicken, simmer covered 10 minutes then uncovered for 20 minutes until tender. Finish with cold butter and fresh tarragon.","duration":1,"images":[],"step":2},{"title":"Season the chicken","description":"Pat the chicken dry thoroughly with paper towels. This removes surface moisture, allowing the skin to brown properly and avoiding splatter. Season with salt and pepper on all sides. Coat in flour, shaking off excess. This helps develop a golden crust and also thickens the sauce later.","images":[],"step":3},{"title":"Brown the Chicken","description":"Heat vegetable oil in a large (30cm/12\") skillet (with lid) over medium-high heat. Add butter, once melted and foaming, place thighs skin-side down. Sear for 5 minutes until golden and crispy. Flip and cook the other side for 1 minute. Transfer to a plate. Add the drumsticks and brown them on 3 sides, about 2 minutes per side. Don’t rush this step – browning adds depth of flavour. Transfer drumsticks to the plate with the thighs. ⚠️ Be mindful when searing skin-on chicken pieces, the skin can pop and hot oil may splash.","duration":5,"images":[],"step":4},{"title":"Onion, mushrooms and garlic","description":"In the same pan, increase the heat to high and add the mushrooms and onions. Cook for 5 minutes, stirring occasionally, until the mushrooms start to wilt. Add the garlic and cook for 30 seconds until fragrant.","duration":5,"images":[],"step":5},{"title":"Brandy and wine","description":"Pour in the brandy. Carefully flambé (ignite) if desired - let it burn until the flame dies out by itself (~10 seconds). Flambéing intensifies the aroma - and puts on a show! Or simply let it bubble for 20–30 seconds until the alcohol burns off. Add the white wine. Let it simmer rapidly to reduce by half. Use a wooden spoon to scrape up the fond (the browned bits stuck to the bottom), which is a crucial ingredient to the creation of our sauce. It will make it rich and complex.","duration":0.4166666666666667,"images":[],"step":6},{"title":"Tomato and stock","description":"Stir in the tomato paste, cook for 1 minute. Then add the stock, salt, and pepper.","duration":1,"images":[],"step":7},{"description":"Cooking","images":[],"step":8},{"title":"Simmer","description":"Return the chicken to the pan skin-side up, nestling them into the stock. Bring the sauce to a simmer, then reduce the heat to medium (bubbling constantly but not rapidly). Cover with a lid and simmer for 10 minutes. Then remove the lid and simmer uncovered for a further 20 minutes. This allows the sauce to reduce and concentrate while the chicken finishes cooking.","duration":10,"images":[],"step":9},{"title":"Reduce sauce slightly","description":"Transfer the cooked chicken to a plate. Turn the heat to medium-high, and simmer the sauce for 3 minutes to reduce slightly.","duration":3,"images":[],"step":10},{"title":"Finish the sauce","description":"Turn off the heat. Scatter half of the COLD butter cubes in then stir until melted. Scatter the rest of the butter cubes in then stir again until melted. This is a classic emulsification technique that gives the sauce a silky, glossy finish (monter au beurre) as well as thickening it slightly. (Note 6)","images":[],"step":11},{"title":"Serve","description":"Bring the sauce to a gentle simmer again. Return the chicken to the sauce and sprinkle over the fresh tarragon. Take it to the table and serve out of the pan with creamy mashed potato.","images":[],"step":12}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["chicken","chicken-drumstick-recipes","chicken-recipes","jbs-recipes","mains","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d838ea82fee0', 'en', 'US', 'Nando''s Portuguese chicken and rice - one pot recipe', 'Recipe video above. My friend calls this Portuguese biryani. I know there''s 1 billion Indians crying right now, but it describes this perfectly! A Nando''s* inspired recipe with Peri Peri rub sprinkled on chicken then cooked in the same pot with a Nando''s copycat spicy rice. Essentially a one pot version of Nando''s paella! It''s seriously good, the rice alone puts Nando''s to shame. Don''t skip the Peri-naise. :-)* Portuguese chicken restaurant chain, bit of a cult following. Do you have it where you are?UPDATE: A few readers left feedback saying they thought it was bland, if you use chicken stock/broth, the spices and the amount of salt specified in the ingredients, this just isn''t possible! :) Please make sure you''re using the right amount of salt!', 'https://www.recipetineats.com/tachyon/2025/09/Portuguese-chicken-and-rice-one-pot_9.jpg', 15, 25, 40, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.025, "unit": "bunch"}}, {"id": "ing_cayenne", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.015, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.0, "unit": "jar of 50g"}}, {"id": "ing_turmeric", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.562, "unit": "L"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_perinaise_pink_sauce_or_any_of_the_other_sauce_suggestions_listed_in_post", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["500g/1 lb chicken thighs (, boneless, skinless, cut into bite size pieces (Note 1))"]},{"ingredients":["2 tsp paprika (regular/sweet, not spicy)","1 tsp garlic powder (substitute large garlic clove, minced)","1 tsp dried oregano","1/4 tsp coriander","1/4 tsp cayenne (can omit for zero spicy)","1 tbsp brown sugar","1 tsp cooking salt / kosher salt (+50% for flakes, halve for table salt)","1 tbsp extra virgin olive oil","1/2 tbsp lemon juice (substitute apple cider vinegar)"],"purpose":"Portuguese chicken seasoning:"},{"ingredients":["2 tbsp extra virgin olive oil","2 garlic cloves (, finely minced)","1 small onion (, diced)","1 red capsicum ((bell pepper), deseeded, chopped into 1cm/0.4\" squares)","1 1/2 cups basmati rice (or long grain rice or medium grain rice) (Note 2)","1/4 tsp chilli flakes / red pepper flakes (omit for not spicy)","2 tsp turmeric powder","2 1/4 cups chicken stock/broth (, low sodium)","1 cup frozen peas (still frozen)","1/2 tsp cooking salt / kosher salt (+50% for flakes, halve for table salt)"],"purpose":"Nando’s copycat spicy rice (or not):"},{"ingredients":["Perinaise ((I use the quick dry spices version), Pink Sauce (Note 4) or any of the other sauce suggestions listed in post)","Green onion (, finely sliced)"],"purpose":"Garnishes:"}]', '[{"description":"Toss chicken with seasoning, sear, remove. Sauté onion and garlic, then capsicum, stir in rice, add everything else + chicken. Steam 15 minutes covered, rest 10 minutes. Serve!","images":[],"step":1},{"title":"Season chicken","description":"Mix the Portuguese Chicken Seasoning ingredients in a bowl. Add chicken and toss to coat. Set aside while you prepare the rest of the ingredients, or overnight if you want (though not necessary).","images":[],"step":2},{"title":"Sear","description":"Heat the 2 tablespoons of oil in a large heavy based pot over high heat. Add the chicken and cook until the outside is sealed and gets a bit of colour (it won''t go golden). Remove with a slotted spoon into a bowl, leaving oil behind in the pot.","images":[],"step":3},{"title":"Sauté","description":"Add garlic and onion into the pot, cook for 1 minute. Add capsicum and cook for 1 1/2 minutes or until onion is translucent.","duration":1,"images":[],"step":4},{"title":"All in","description":"Add rice and stir to coat in the tasty oil. Add remaining rice ingredients, then scatter the chicken evenly across the surface. Also add any juices accumulated in the bowl. Stir, bring to a simmer, then put the lid on and lower heat to medium low so it''s simmering gently. (Note 3)","images":[],"step":5},{"title":"Cook 15 minutes","description":"Cook for 15 minutes, no peeking, no stirring! Liquid should be absorbed - tilt pot and lift lid for quick peek.","duration":15,"images":[],"step":6},{"title":"Rest 10 minutes","description":"Remove pot from the stove and leave to rest for 10 minutes with the lid still on.","duration":10,"images":[],"step":7},{"title":"Fluff & serve","description":"Remove lid, gently toss the rice. Spoon into bowls, drizzle over Peri-naise, sprinkle with green onions and serve!","images":[],"step":8}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Portuguese inspired"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","mains","one-pot-recipes","quick-and-easy","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f375a37487ed', 'en', 'US', 'My go-to Chicken Breast recipe', 'Recipe video above. Ready in 12 minutes, this is my current go-to chicken breast recipe. AKA Pan-Seared Country Seasoned Chicken Breast with Butter Sauce, it''s fast, simple, not-boring and you can make it anytime with pantry staples!Simple country-inspired seasoning tossed with the tiniest amount of flour so the chicken gets a lovely crust on it, served with a butter sauce made in the same pan so it gets flavour from the residual seasoning.Mix and match magic: Skip the sauce and just serve the seasoned chicken, or skip the spices and let the butter sauce shine with a simple salt-and-pepper seared chicken.', 'https://www.recipetineats.com/tachyon/2025/07/Anytime-Chicken-Breast-in-white-wine-sauce_5.jpg', 5, 7, 12, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 20.0, "unit": "block of 250g"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 20.0, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["2 large chicken breasts (250 - 300g/8 - 10 oz each), each cut in half horizontally to form 4 steaks, no need to pound (Note 1)","20g/ 1 1/2 tbsp unsalted butter (or 1 1/2 tbsp olive oil)"]},{"ingredients":["1 tsp paprika (, regular/sweet (or smoky))","1/2 tsp onion powder (or more garlic)","1/2 tsp garlic powder (or more onion)","1/4 tsp cumin (sub coriander, thyme leaves crushed between fingers, or omit)","3/4 tsp cooking salt / kosher salt (halve for table salt, +50% for flakes)","1/8 tsp black pepper","1 1/2 tbsp flour (, plain/all-purpose, GF (Note 2))"],"purpose":"Savoury Seasoned Crust:"},{"ingredients":["1/3 cup dry white wine ( or chicken stock (low sodium), sub water (Note 3))","30g/ 2 tbsp unsalted butter","1 tbsp roughly chopped parsley (, optional but recommended)"],"purpose":"Butter sauce:"}]', '[{"description":"Dust chicken with Seasoning, pan fry in the butter, remove. Deglaze with wine, melt in butter, serve sauce on chicken.","images":[],"step":1},{"title":"Season","description":"Mix the Seasoning ingredients in a bowl. Sprinkle on each side of the chicken, spreading with fingertips to coat evenly, then shake off excess.","images":[],"step":2},{"title":"Sear","description":"Melt the butter in a large non-stick pan over high heat. Cook chicken for 2 1/2 minutes on each side until deep golden, or until the internal temperature reaches 67C/153F. Remove onto a plate.","images":[],"step":3},{"title":"Pan sauce","description":"Lower then heat to medium high. Add the wine and simmer rapidly for 1 - 1 1/2 minutes, scraping the pan with a rubber spatula to loosen the golden bits into the sauce, until it''s reduced by half. Add the butter and let it melt, mixing well to combine. (Note 4 on sauce amount)","images":[],"step":4},{"title":"Serve","description":"Serve chicken with sauce and sprinkled with parsley. Enjoy!","images":[],"step":5}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3c418264c155', 'en', 'US', 'Whipped ricotta one pot chicken pasta', 'Recipe video above. Meet your new favourite one-pot recipe! I''m sharing this as a guest-worthy dish based on a simple mid-week recipe. It''s quite amazing how just a little dollop of creamy ricotta can transform a regular bowl of pasta into something you''d expect to get at a rustic trattoria! Love how it melts into a flood of creamy goodness on your hot bowl of pasta - thicker than cream, and much lower fat.', 'https://www.recipetineats.com/tachyon/2025/04/One-pot-whipped-ricotta-chicken-pasta-with-sun-dried-tomatoes_6a.jpg', 10, 20, 30, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_tomato", "quantity": {"value": 0.22, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 220.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.22, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.22, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_ricotta", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_milk", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}]', '[{"ingredients":["500g/1 lb chicken thigh fillets (, cut into small bite size pieces (or breast or tenderloin))","1/2 tsp cooking salt/kosher salt","1/4 tsp black pepper"],"purpose":"Chicken:"},{"ingredients":["220g/ 7 oz jar sun-dried tomato stripes in oil (, drained (RESERVE OIL) (Note 1))","3 tbsp oil (from the sun dried tomato jar)","1 small onion (, finely diced)","2 garlic cloves (, finely minced)","1 tbsp tomato paste (ok if you don''t have)","1/4 cup dry white wine (, optional (Note 2))","400g/14 oz canned crushed tomato","350g / 12oz fusilli pasta (spirals) (, penne, ziti, macaroni, small shells or similar, uncooked)","1 litre / 4 cups chicken stock/broth (, low sodium (sub water plus 1/2 tsp salt))","1/4 tsp cooking salt/kosher salt","1/4 tsp black pepper","1 cup basil leaves (, roughly chopped (can survive without), plus extra for garnish)"],"purpose":"Pasta:"},{"ingredients":["1/2 cup ricotta ((Paesanella is my preferred brand), full fat)","4 tbsp milk (, preferably full fat)","1/4 cup (packed) finely grated parmesan (, sub pinch of salt)"],"purpose":"Whipped ricotta:"}]', '[{"title":"Whipped ricotta","description":"Put the ingredients in a bowl. Whisk vigorously for 10 to 15 seconds until it becomes the texture of softly whipped cream. Add milk to loosen, if needed.","duration":0.20833333333333334,"images":[],"step":1},{"title":"Seal chicken","description":"Heat sun dried tomato oil in a large heavy based pot over high heat. Add the chicken. sprinkle with salt and pepper. Cook for 3 minutes until the outside is sealed but the inside is still raw. Remove with slotted spoon into a bowl.","duration":3,"images":[],"step":2},{"title":"Sauté","description":"In the same pot, add the onion and garlic. Cook for 3 minutes until the onion is translucent. Add the tomato paste and oil drained sun dried tomatoes (reserve any remaining oil for another use). Cook for 1 minute.","duration":3,"images":[],"step":3},{"title":"Deglaze","description":"Add white wine and let it simmer rapidly for 1 - 2 minutes, stirring regularly, until mostly evaporated.","duration":1.5,"images":[],"step":4},{"title":"Cooking liquid","description":"Add pasta and cooked chicken along with any juices accumulated in the bowl. Stir to coat in all the tasty flavours. Add the stock, canned tomato, salt and pepper.","images":[],"step":5},{"title":"Cook 15 minutes","description":"Give it a good stir, let it come to a boil then lower the heat to medium high so it''s simmering rapidly but not boiling like crazy. Cook for 15 minutes (no lid), stirring every 2 minutes or so at first then more regularly towards the end, so the base doesn''t catch. Lower the heat a touch towards the end, if needed.","duration":15,"images":[],"step":6},{"title":"How to tell it''s done","description":"Most of the liquid should be absorbed and the pasta should be just cooked (al dente), though still a little soupy (that''s good, it gets absorbed quickly while serving). Stir in the basil.","images":[],"step":7},{"title":"Serve","description":"Transfer into a serving bowl or divide between bowls. Dollop the whipped ricotta on top then randomly smear (or let everyone do that themselves), it will get all melty. Dig in!","images":[],"step":8}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-recipes","dinner-tonight","mains","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_81e9be2d7579', 'en', 'US', 'Lebanese Lemon Garlic Chicken - Al Aseel copycat', 'Recipe video above. A copycat of a signature dish at Al Aseel, a popular Lebanese restaurant in Sydney! Chicken is marinated in a bold lemon-garlic yogurt mix, then smothered in a garlicky lemon yogurt sauce. Warm yogurt may sound unusual, but one bite will win you over! Serve with pita bread and Fattoush.PS. Please measure the garlic - too much is harsh, too little is sad.PPS. The salt might seem a lot, but please trust, it''s not salty!', 'https://www.recipetineats.com/tachyon/2025/04/Lebanese-lemon-garlic-chicken-Al-Aseel_2.jpg', 15, 10, 25, 3, '[{"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.12, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_extra_virgin_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["500g/ 1lb chicken tenderloin (or breast), cut into 4cm / 1.5\" squares, large vein cut out (Note 1)"]},{"ingredients":["4 tbsp Greek or plain yogurt","3 tbsp lemon juice","1 tbsp garlic (, finely grated or crushed using garlic press (~4 big cloves))","1 tbsp olive oil","1 tsp cooking salt / kosher salt (1/2 tsp table salt, 1 1/4 tsp flakes)"],"purpose":"Lemon garlic marinade:"},{"ingredients":["1 cup Greek or plain yogurt (, full fat essential here!)","3/4 tsp garlic (, finely grated or crushed using garlic press (~1 clove))","2 tbsp extra virgin olive oil","1 tbsp lemon juice","1 tbsp tahini (hulled), or extra 1 tbsp olive oil (Note 3)","1 tbsp+ water","1 tsp cooking salt / kosher salt (1/2 tsp table salt, 1 1/4 tsp flakes)"],"purpose":"Lemon garlic yogurt sauce:"},{"ingredients":["2 tbsp olive oil (, for cooking)","1 tsp parsley (, roughly chopped (or equal amounts mint and parsley))","Lemon wedges and extra virgin olive oil (, for garnish)","Lebanese bread (for sauce mopping (recommended))"],"purpose":"Cooking & serving:"}]', '[{"title":"Marinade chicken 12","description":"24 hrs. Cook in 2 batches. Whisk sauce, rest 1 hr, warm just before serving. Smother chicken, serve!","images":[],"step":1},{"title":"Marinade","description":"Mix the marinade ingredients in a bowl. Add the chicken, toss to coat then refrigerate to marinate for 12 - 24 hours (Note 2).","images":[],"step":2},{"title":"Sauce","description":"Put the sauce ingredients in a microwaveable bowl and whisk to combine. Set aside for 1 hour + to let the garlic flavour meld. (Note 4)","images":[],"step":3},{"title":"Cook chicken","description":"Drain off excess marinade from the chicken. Heat 1 tbsp oil in a large non stick pan over high heat. Place half the chicken in and cook for 1 1/2 - 2 minutes on each side until golden. Remove onto a plate.","images":[],"step":4},{"title":"Repeat","description":"Scrape out / roughly wipe loose black bits out of the pan. Reheat remaining oil and cook remaining chicken. Rest for 2 minutes.","duration":2,"images":[],"step":5},{"title":"Warm sauce","description":"While the chicken is resting, microwave for 40 seconds to warm (but not hot) then give it a good whisk. Taste and add more lemon for tangier, or more water to loosen (some yogurts are thicker than others).","duration":0.6666666666666666,"images":[],"step":6},{"title":"Serving","description":"Spread half the sauce in a shallow bowl. Use a spatula to transfer the chicken onto the yogurt. Spoon over remaining sauce, finish with a swish of olive oil and sprinkle of parsley. Serve!","images":[],"step":7}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["lebanese"],"categories":["chicken-breast-recipes","chicken-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_371c245bc354', 'en', 'US', 'Chicken and Leek Pie', 'Recipe video above. Tender bites of chicken and slippery pieces of sweet leek smothered in a creamy white-wine thyme infused sauce, bubbling under a golden puff pastry crust. Chicken and Leek Pie is comfort food we dream about!I cut my leeks in a specific way. I like larger pieces rather than thinly sliced rings which get too soggy-stringy for my taste. Also, if you don''t like / can''t get puff pastry, cover this pie in mash (like Cottage Pie!) or use a homemade shortcrust pastry.Make one big pie like I''ve done, or ramekins (makes 4 large, 5 regular). For a pie with a base, replace the filling in my Family Meat Pie (there will be leftover filling) or individual meat pies. See the FAQ above for the gluten-free option.', 'https://www.recipetineats.com/tachyon/2024/09/Chicken-and-Leek-Pie_9.jpg', 25, 60, 145, 5, '[{"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_bacon", "quantity": {"value": 0.4, "unit": "pack of 200g"}}, {"id": "ing_eek", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_thyme", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}]', '[{"ingredients":["50g/ 3 1/2 tbsp unsalted butter (, divided)","750g/ 1.5lb chicken thighs (, skinless, boneless, cut into 1.8 cm / 3/4\" bite size pieces (Note 1))","1/4 tsp each black pepper and cooking salt (kosher salt)"]},{"ingredients":["80g / 3 oz streaky bacon (, chopped into 1cm / 0.4\" squares (Note 2))","2 leeks (Note 3)","2 celery stems (, sliced 4 mm / 0.2\" thick (cut thick end in half lengthways first))","2 garlic cloves (, finely minced)","1/3 cup chardonnay (or other dry white wine (Note 4))","1/4 cup flour (plain / all-purpose)","1 tbsp dijon mustard (Note 5)","2 thyme sprigs (or 1/2 tsp dried thyme)","2 bay leaves (preferably fresh, else dried)","1 cup chicken stock / broth (, low sodium)","1 cup thickened / heavy cream (or any full-fat cream, or sub milk for lower fat)","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Pie filling:"},{"ingredients":["2 x 20cm / 8\" frozen butter puff pastry sheets (, or single sheet large enough to cover baking dish, 360g / 12 oz (Note 6))","1 egg (, yolk and whites separated, lightly whisked)"],"purpose":"Pie:"}]', '[{"description":"Sear surface of chicken in half butter, remove. Cook bacon 1 minute, then leek, celery and garlic 5 minutes. Deglaze with wine, melt remaining butter, then cook flour 1 minute. Add stock, then remaining Filling ingredients. Add chicken, thicken sauce (~5 minutes).","images":[],"step":1},{"description":"Cool filling 1 hour, assemble pie with double layer puff on rim, brush lid with yolk, bake 45 minutes 200°C/375°F (180°C fan).","images":[],"step":2},{"description":"Cut leek (step photos above helpful):","images":[],"step":3},{"description":"Trim the reedy dark green ends and root off, then cut in half. Cut each piece in half lengthways. Remove the outer 5 to 6 layers (keep them together), lay them flat, cut in half lengthways then into 1.8cm / 3/4\" squares. Cut the inner core into 2cm / 0.8\" pieces.","images":[],"step":4},{"title":"Chicken","description":"Melt half the butter in a large pan over high heat. Add the chicken, salt and pepper. Cook until the surface changes from pink to white (inside still raw), then remove into a bowl using a slotted spoon. Leave residual butter and chicken juices in the pan.","images":[],"step":5},{"title":"Sauté","description":"In the same pan, cook the bacon for 1 minute. Add the leek, celery and garlic. Cook for 5 minutes until the celery is softened. Don''t let the leek brown - lower the heat if needed.","duration":1,"images":[],"step":6},{"title":"Deglaze","description":"Add the wine and simmer rapidly on high heat, stirring, until it is mostly evaporated.","images":[],"step":7},{"title":"Roux","description":"Lower the heat to medium. Add the remaining butter. Once it melts, sprinkle the flour across the surface (don''t dump in one place) and stir for 1 minute.","duration":1,"images":[],"step":8},{"title":"Creamy sauce","description":"While stirring, slowly pour the stock in. The mixture will thicken into a thick sauce once combined. Then add the mustard, cream, thyme, bay leaves, salt and pepper. Stir to combine, then add the chicken including all the juices accumulated in the bowl.","images":[],"step":9},{"title":"Simmer","description":"Increase the heat, stir to combine. Once it comes to a simmer, reduce the heat to medium high. Simmer for 5 minutes, stirring regularly, or until the sauce is a thick creamy consistency you want in the finished pie (ie sauce thickness now = thickness in the baked pie, see Note 7).","duration":5,"images":[],"step":10},{"title":"Cool","description":"Remove the pan from the stove and cool for 1 hour. (You can also store in fridge for 3 - 4 days).","images":[],"step":11},{"description":"Assembling and baking:","images":[],"step":12},{"description":"Preheat the oven to 200°C/375°F (180°C fan-forced). Use a 1.5 litre / 1.5 quart baking pan (Note 9) or 4 to 5 x ~350ml / 12 oz ramekins.","images":[],"step":13},{"title":"Connect puff pastry sheets (if needed)","description":"Semi-thaw the puff pastry (Note 6). Brush the edge of one sheet with egg white, then overlap 0.5cm / 0.2\" with the other sheet to connect them. Use the back of a spoon to \"smear\" the pastry to hide the seam and firmly connect.","images":[],"step":14},{"description":"Cut out the pie lid (I use the dish as a cutting guide).","images":[],"step":15},{"title":"Optional strips for extra puffy edges (Note 8)","description":"Cut strips using the residual pastry to line the rim of the dish (if your dish has a thick rim, like mine) and place on the rim of the dish.","images":[],"step":16},{"description":"Fill the pie dish with the cooled filling and smooth the surface. Brush the pastry strips on the rim with egg white (if not using strips, don''t do this step) then cover with the puff pastry lid.","images":[],"step":17},{"description":"Brush the lid with egg yolk. Cut a small X in the middle.","images":[],"step":18},{"description":"Bake 45 minutes or until the surface is a deep golden brown. Rest 5 minutes then serve!","images":[],"step":19}]', '["egg","gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-recipes","mains","quiches-tart-and-pie-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_98c0c9ef9775', 'en', 'US', 'One pot chicken risoni with crispy salami (orzo)', 'Recipe video above. Risoni - also known as orzo - in a creamy tomato parmesan sauce with juicy slices of seasoned chicken and lots of awesome crispy bits of golden salami! The better bacon - bolder flavour, and it doesn''t spit when you''re cooking it. :) The addition of chickpeas adds a soft nutty crunch and another layer of texture to this one-pan wonder that''s a cosy bowl of deliciousness! Total crowd pleaser.', 'https://www.recipetineats.com/tachyon/2024/01/One-pan-chicken-creamy-tomato-risoni-with-crispy-salami-2.jpg', 15, 0, 15, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_salami_stick", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_sage", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.375, "unit": "pack of 500g"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 150.0, "unit": "bag of 250g"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["1/2 tbsp olive oil","100g/ 3 oz salami stick (, cut into 3mm / 1/8\" thick rounds then chopped into small batons (Note 1))","2 x 250g / 8 oz chicken breasts ( (large), each cut in half horizontally to form 4 thin steaks (Note 2))"]},{"ingredients":["1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper","1/2 tsp garlic powder","3/4 tsp paprika","1/4 tsp sage powder (optional)"],"purpose":"Chicken spice mix:"},{"ingredients":["2 garlic cloves (, finely minced)","1/2 onion (, finely chopped)","1/4 cup chardonnay or other dry white wine (, optional (Note 3))","1/4 cup tomato paste","1 1/4 cups risoni/orzo (, uncooked (Note 4))","400g / 14 oz canned chickpeas (, drained (or other beans))","3 cups chicken stock (, low sodium (or veg stock))","1/2 tsp cooking / kosher salt","1/4 tsp black pepper","3/4 cup thickened / heavy cream (low-fat ok)","1/3 cup parmesan (, finely grated (I use store bought sandy type))","150g/ 5 oz baby spinach (or 4 cups kale pieces)","1/3 cup sun dried tomato (, chopped (optional) (Note 5))"],"purpose":"Creamy tomato parmesan risoni (orzo):"},{"ingredients":["2 tbsp roughly chopped basil (optional) (Note 5)"],"purpose":"Optional garnish"}]', '[{"title":"Spice Mix","description":"Mix the ingredients in a small bowl then sprinkle both sides of the chicken.","images":[],"step":1},{"title":"Crispy salami","description":"Heat the oil in a large non-stick pan over medium high heat. Cook the salami for 2 minutes, stirring constantly, until crispy and golden. Remove into a paper towel lined bowl using a slotted spoon, leaving the tasty salami fat in the pan.","duration":2,"images":[],"step":2},{"title":"Cook chicken","description":"In the same pan, cook the chicken for 3 minutes on each side until dark golden and just cooked through (internal temperature 67°C/153°F). Remove onto a plate and cover loosely with foil to keep warm.","duration":3,"images":[],"step":3},{"title":"Sauté","description":"Still on medium high, cook the garlic and onion for 1 1/2 minutes until the onion is translucent. Add the wine and let it simmer rapidly for a couple of minutes until mostly evaporated, stirring to dissolve the fond (gold bits) on the base of the pan into the wine.","images":[],"step":4},{"title":"Risoni (orzo)","description":"Add the tomato paste and stir for 1 minute to cook out the sour raw flavour. Add the risoni and stir to coat in the tomato paste. Add the chickpeas, chicken stock, salt, pepper.","duration":1,"images":[],"step":5},{"title":"Simmer","description":"Bring to a simmer, then cook for 8 minutes, stirring every minute or so, until the risoni is just about cooked. Lower the heat to medium as it gets thicker so the base doesn''t catch.","duration":8,"images":[],"step":6},{"title":"Cream & spinach","description":"Add the cream, parmesan, spinach and sun dried tomatoes (if using). Stir until the spinach is wilted then remove from the heat. The risoni should be oozy and tender. (Still firm? Note 6)","images":[],"step":7},{"title":"Finish","description":"Cut the chicken into thick slices. (Bit cool? Note 7) Spoon risoni into bowls. Top with the chicken, sprinkle with lots of crispy salami, parmesan and basil (if using). Dig in!","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","mains","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a2fe549aa309', 'en', 'US', 'One-pan Baked Butter Chicken', 'Recipe video above. The miraculous, easy way to make butter chicken in the oven! Just put everything in a pan and pop it in the oven. That sauce is to-die for! Just like the real-thing, with a fraction of the effort.This doesn''t even need to be marinated because the flesh gets infused with flavour as it bakes. Not spicy at all, so this one for everyone!', 'https://www.recipetineats.com/tachyon/2023/11/One-pan-baked-butter-chicken_9.jpg', 10, 45, 55, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.15, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_turmeric", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_garam_masala", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_tomato", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_naan", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["1.2 kg/ 2.4lb (6 pieces) bone-in chicken thighs (, skin removed (Note 1))"]},{"ingredients":["1/2 cup plain yoghurt (, full fat)","1 tbsp lemon juice","1 tbsp ginger (, finely grated)","2 cloves garlic (, finely grated or crushed)","1 tsp turmeric powder","2 tsp garam masala (Note 2)","1/2 tsp chilli powder ((pure, not US blend) or cayenne pepper powder)","1 tsp ground cumin","1/2 tsp cooking salt / kosher salt"],"purpose":"Butter chicken marinade:"},{"ingredients":["2 tbsp/ 30g melted ghee or butter (Note 3)","1 cup tomato passata (US: tomato puree) (Note 4)","3/4 cup heavy / thickened cream (or regular cream, or coconut milk)","1 1/2 tsp white sugar","3/4 tsp cooking salt / kosher salt"],"purpose":"Butter chicken curry sauce:"},{"ingredients":["1/2 cup coriander leaves (cilantro) (, for garnish (optional))","Basmati rice (or other plain rice)","Naan (easy - no kneading required!)"],"purpose":"Serving:"}]', '[{"description":"Preheat oven to 200°C / 400°F (180°C fan-forced).","images":[],"step":1},{"title":"Coat chicken","description":"Mix the marinade ingredients in a bowl, then add the chicken and toss to coat.","images":[],"step":2},{"title":"Optional marinade","description":"overnight. (Note 5)","images":[],"step":3},{"title":"Assemble","description":"Mix Sauce ingredients in a 23 x 33cm / 9 x 13\" baking dish. Place chicken in, smooth side up. Scrape residual marinade out of bowl and dab onto chicken surface.","images":[],"step":4},{"description":"Bake 45 minutes, basting with sauce at the 30 minute and 40 minute mark. The sauce will change from pink to orangey-red (Note 6 for sauce thickening).","images":[],"step":5},{"title":"Serve","description":"Rest for 5 minutes. Then serve over basmati rice, garnished with coriander if desired! Naan for mopping would make everyone extra happy. :)","duration":5,"images":[],"step":6}]', '["milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["chicken","chicken-recipes","indian-recipes","mains","one-pot-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0feced2927c4', 'en', 'US', 'African coconut chicken curry - Kuku Paka', 'Recipe video above. Are you ready to discover the world''s easiest curry?? As in, a real one, made from scratch. Introducing - Kuku Paka! This chicken curry in a tomato coconut spiced sauce tastes like an Indian curry. Except it''s African, and you can get everything you need from your regular grocery store. For a strictly traditional version, sear the chicken over charcoal for chargrilled flavour before adding into the sauce. To make this Monday-night-friendly, I''ve just pan-seared. Serves 4 hearty appetites or 5 to 6 regular servings.', 'https://www.recipetineats.com/tachyon/2023/10/African-coconut-chicken-curry_3.jpg', 15, 45, 60, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 7.5, "unit": "jar"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["4 chicken thigh fillets (, skin-on and bone-in (~250g/8oz each) (Note 2))","4 chicken drumsticks (~150g / 5oz each) (Note 2)","3/4 tsp cooking / kosher salt","1/2 tsp black pepper"],"purpose":"Seasoned chicken:"},{"ingredients":["2 tbsp coconut oil (or vegetable, canola or other plain oil) (Note 1)","1 onion (, finely diced)","3 garlic cloves (, finely minced)","2 tsp ginger (, finely minced)","1 tbsp coriander powder","1/2 tbsp cumin powder","1/2 tbsp turmeric powder","1 tsp pure chilli powder or cayenne pepper (, reduce or omit to taste (Note 3))","400g / 14 oz coconut milk (, full-fat (Note 4))","400g / 14 oz crushed canned tomato","1 1/4 tsp cooking / kosher salt","2 tbsp lemon juice (sub apple cider vinegar)","1/2 cup (lightly packed) coriander/cilantro leaves (sub parsley or baby spinach, or omit)"],"purpose":"The curry:"},{"ingredients":["Basmati rice"],"purpose":"Serving:"}]', '[{"title":"Season chicken","description":"Pat chicken dry using paper towels then sprinkle with the salt and pepper.","images":[],"step":1},{"title":"Brown chicken","description":"Heat oil in a large heavy based pot over high heat. Add the thighs, skin-side down, and cook for 4-5 minutes until golden brown. Turn and cook the other side for 1 minute. Transfer to a plate (it will still be raw inside). Then brown the drumsticks as best you can. I do 3 sides, 2 minutes each side. Transfer to the plate.","duration":4.5,"images":[],"step":2},{"title":"Sauté aromatics","description":"Turn heat down to medium high. Add the onion and cook for 1 minute until softened. Add garlic and ginger, cook for 30 seconds. Add the coriander, cumin, turmeric and chilli. Stir for 30 seconds.","duration":1,"images":[],"step":3},{"title":"Sauce","description":"Add coconut milk, tomato and salt. Stir, then return chicken into the pot (including juices on the plate). Submerge chicken as best you can.","images":[],"step":4},{"title":"Simmer 30 min","description":"Once the sauce comes to a simmer, reduce the heat so it’s bubbling gently. Cover and cook for 10 minutes. Remove the lid and simmer for a further 20 minutes, stirring occasionally to ensure the base doesn''t catch.","duration":10,"images":[],"step":5},{"title":"Finish & serve","description":"Stir in lemon and half of the coriander. Lade into bowls and serve garnished with the rest of the coriander!","images":[],"step":6}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["african"],"categories":["chicken","chicken-drumstick-recipes","chicken-recipes","curry-recipes","mains","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0035a9fc479f', 'en', 'US', 'Chicken Francese', 'Recipe video above. Lightly battered pan-fried chicken breast with an elegant white wine lemon sauce. It''s like Chicken Piccata, but a thicker sauce, more of it, no capers, with subtle lemon flavour. It''s got a terrific crust that soaks up the sauce! Lovely restaurant dish that''s simple to make at home.Doesn''t taste winey because the alcohol is cooked out, leaving behind magical flavour only wine can bring to sauces.', 'https://www.recipetineats.com/tachyon/2023/10/Chicken-Francese_4.jpg', 10, 15, 25, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["2 large chicken breasts (, skinless boneless (250-300g / 8-10oz each))","1/4 cup flour (, plain / all-purpose)","1 tsp cooking salt / kosher salt","1 tsp black pepper","2 large eggs","1 tbsp milk ( (any fat %))"],"purpose":"Chicken & coating:"},{"ingredients":["3 tbsp extra virgin olive oil","1 lemon (, thinly sliced 0.3cm / 1/8\")","50g / 3 tbsp unsalted butter","2 tbsp flour (, plain / all-purpose)","2 cups chicken stock/broth (, low sodium)","1/3 cup Chardonnay or other dry white wine (Note 1)","1/2 tsp cooking salt / kosher salt (no pepper!)","1 tbsp finely chopped parsley (, for garnish (optional))"],"purpose":"Cooking & sauce:"}]', '[{"description":"Cut each breast in half horizontally to form 4 thin steaks in total.","images":[],"step":1},{"description":"Whisk eggs and milk in a small bowl. Set aside.","images":[],"step":2},{"title":"Flour coating","description":"Mix flour, salt and pepper on a plate (I use my fingertips). Coat the chicken in the flour, shaking off excess, then set aside on a plate.","images":[],"step":3},{"description":"Heat the oil in a large nonstick pan over medium-high heat.","images":[],"step":4},{"title":"Cook chicken","description":"Dip the chicken in the egg, allow excess to drip off, then put into the pan. Cook for 3 minutes until golden. Flip, lower heat to medium, then cook for 4 minutes until the chicken is golden (internal temp 68°C/155°F). Remove onto a plate.","duration":3,"images":[],"step":5},{"title":"Lemon","description":"Add the lemon slices to the pan. Cook for a minute or until the lemons go soft / brown, then turn and cook the other side for 30 seconds. Remove onto a plate. (Note 2)","duration":0.5,"images":[],"step":6},{"description":"Wipe the pan clean using paper towels.","images":[],"step":7},{"title":"White wine sauce","description":"Still on medium heat, melt the butter in the pan. Add flour and stir for 1 minute using a wooden spoon. While stirring, slowly pour in half the stock. Once the flour is dissolved into the liquid, stir in remaining stock, then the wine and salt. (See Note 3 for lumps tip)","duration":1,"images":[],"step":8},{"title":"Thicken sauce","description":"Turn the heat up slightly then simmer for 3 - 4 minutes or until the sauce thickens into a syrupy consistency.","duration":3.5,"images":[],"step":9},{"description":"Sauce it! Return the chicken and lemon slices to the pan, then spoon the sauce all over the chicken. Sprinkle with parsley then serve the chicken with the sauce (use it ALL!).","images":[],"step":10}]', '["egg","gluten","milk"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b4a9348ac3d5', 'en', 'US', 'Golden coconut chicken curry', 'Recipe video above. This Golden Coconut Chicken Curry blows me away every time I make it - and I''ve been making it a lot lately! Such a beautiful spice blend, Thai vibes with a whisper of Indian, like a less shrimpy version of Thai Yellow Curry with a hint of Massaman. Don''t skip the star anise and cinnamon stick, and really try to use fresh turmeric rather than dried, for max flavour and yellow colour. All credit to JB for this one, his invention. :)*UPDATE: If you skip fresh turmeric and sub other spices and you''re using rather old spices (which lose flavour), the recipe won''t be as good as the rave reviews below and will make me sad*', 'https://www.recipetineats.com/tachyon/2023/09/Chicken-broccoli-coconut-curry_3.jpg', 10, 20, 30, 4, '[{"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_star_anise", "quantity": {"value": 3.0, "unit": "jar"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_turmeric", "quantity": {"value": 15.0, "unit": "jar"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.6, "unit": "carton of 250ml"}}, {"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_aram_masala", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_fennel", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["3 tbsp coconut oil (, vegetable or canola oil (Note 1))","3 star anise","1 cinnamon stick","1 onion (, finely diced)","500g / 1lb chicken thigh fillets (, cut into small 1cm / 1/3\" slices (Note 2 options!))","1 tsp garlic (, finely grated)","1 tsp ginger (, finely grated)","3 tsp turmeric (, finely grated (sub 1 1/2 tsp powder, Note 3))","2 cups chicken stock/broth (, low sodium)","400g / 14 oz coconut cream (, unsweetened (sub coconut milk, Note 4))","1 large head broccoli (, florets cut small (can use stem too - peel & dice), or other veg (4 heaped cups))","1 cup coriander/cilantro leaves (, lightly packed, plus extra for garnish (I''d still make without this))"]},{"ingredients":["1 1/2 tsp cooking/kosher salt","1 1/2 tsp garam masala (Note 5)","1 1/2 tsp coriander powder","1/2 tsp cumin powder","1/2 tsp fennel powder (sub more garam masala)"],"purpose":"Spice mix:"},{"ingredients":["Crispy fried shallots (, store bought, for garnish (Note 6))","1 large head broccoli (, florets cut small (can use stem too - peel & dice), or other veg (4 heaped cups))"],"purpose":"Serving"}]', '[{"title":"Spice mix","description":"Mix the spices in a small bowl.","images":[],"step":1},{"title":"Toast","description":"Heat the oil in a large heavy based pot over medium high heat. Toast the star anise and cinnamon for 2 minutes.","duration":2,"images":[],"step":2},{"description":"Add onion, cook for 2 minutes.","duration":2,"images":[],"step":3},{"description":"Add chicken, cook for 3 minutes or it''s no longer pink on the outside (still raw inside).","duration":3,"images":[],"step":4},{"title":"Add aromatics","description":"Add garlic, ginger and turmeric. Cook for 1 minute.","duration":1,"images":[],"step":5},{"description":"Add spice mix and stir for 30 seconds.","duration":0.5,"images":[],"step":6},{"title":"Simmer 12 minutes","description":"Add stock and coconut cream. Stir and bring to an energetic simmer. Cook for 12 minutes (no need to stir) so the sauce thickens slightly.","duration":12,"images":[],"step":7},{"description":"Add broccoli florets. Bring back to a simmer and cook for 3 minutes or until softened.","duration":3,"images":[],"step":8},{"title":"Serve","description":"Cool for 5 minutes, this will allow the sauce to thicken slightly. Then stir in coriander and serve with rice (basmati or jasmine especially nice). Garnish with extra coriander and crispy fried shallots.","duration":5,"images":[],"step":9}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Indian"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","cuisines","curry-recipes","mains","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_391d4f388a0f', 'en', 'US', 'Herb & Garlic Butter Chicken Marylands (chicken leg quarters)', 'Recipe video above. Chicken marylands - such an under utilised cut of chicken! Cheap, juicy, flavourful, hard to stuff up. I tell people it''s like roast chicken: without the mess of carving up a whole chicken. Slather in herb & garlic butter then bake until golden. Don''t waste a drop of the pan juices - it''s liquid gold!Serve with potato gratin or creamy mash with garlic sautéed green beans for the perfect meal!', 'https://www.recipetineats.com/tachyon/2023/06/Herb-Garlic-Chicken-Marylands_8.jpg', 10, 50, 60, 4, '[{"id": "ing_chicken", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["4 pieces (~1.5 kg/3 lb) chicken marylands (US: leg quarters) ( or 8 bone-in, skin-on thighs (Note 1))","1/2 tsp cooking/kosher salt","1/3 cup chardonnay or other dry white wine (sub low-sodium chicken stock/broth)"]},{"ingredients":["100g/7 tbsp unsalted butter (, softened)","4 garlic cloves (, minced using a garlic press (Note 2))","2 tsp fresh rosemary leaves (, finely chopped (Note 3 for dried))","2 tsp thyme leaves (, finely chopped (Note 3 for dried))","3/4 tsp cooking/kosher salt","1/4 tsp black pepper"],"purpose":"Herb & garlic butter:"}]', '[{"description":"Preheat oven to 220°C/425°F (200°C fan).","images":[],"step":1},{"description":"Mix Herb & Garlic Butter ingredients until combined.","images":[],"step":2},{"title":"Butter chicken","description":"Use an upside down tablespoon to loosen the chicken skin from the flesh on the thigh and most of the leg (Note 4). Smear 80% of the butter under the skin, just a small amount (~5%) on the underside (flesh side) then the remainder on top of the skin. (The flesh side gets lots of flavour from the pan juices).","images":[],"step":3},{"description":"Put chicken in roasting pan, skin side up. Sprinkle skin with the 1/2 tsp salt. Pour wine around chicken.","images":[],"step":4},{"title":"Roast 50 minutes","description":"Roast 10 minutes to get the skin going. Then reduce the heat to 200°C /400°F (180°C fan) and roast for a further 40 minutes, basting every 10 minutes from the 20 minute mark onwards.","images":[],"step":5},{"title":"Rest & serve","description":"Remove from oven. Rest 10 minutes then serve with the garlic-herb-butter pan juices as the sauce!","images":[],"step":6}]', '["milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_179548403868', 'en', 'US', 'Chicken Marsala', 'Recipe video above. A beloved Italian-American classic comprised of a crispy golden chicken cutlet smothered in a rich Marsala wine flavoured mushroom sauce. A restaurant favourite that''s easy to make at home, one bite and you''ll be hooked for life like I was!The key flavour here is Marsala wine so if you can''t consume alcohol or don''t have it, make Chicken in Creamy Mushroom Sauce instead! Also, this dish uses more alcohol than my usual "just a splash of wine" so it''s not recommended for kids. :)', 'https://www.recipetineats.com/tachyon/2023/06/Chicken-Marsala_0b.jpg', 10, 15, 25, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_eschalots", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.333, "unit": "bottle of 750ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["2 large chicken breasts (300g/10oz each), cut in half horizontally (or 4 thighs, Note 1)","1/2 tsp cooking salt / kosher salt","1/2 tsp black pepper","1/4 cup flour (, plain/all-purpose)"],"purpose":"Golden crusted chicken:"},{"ingredients":["2 tbsp extra virgin olive oil","2 tbsp / 30g unsalted butter","2 eschalots (US: shallots), peeled and cut into 1cm / 1/3\" squares (Note 2)","1 garlic (, finely minced)","2 cups white mushrooms (, sliced 0.5cm / 1/5\" thick)","1 cup dry marsala wine (Note 3)","1/2 cup chicken stock/broth (, low sodium)","1/2 cup thickened / heavy cream ( (Note 4))","1/4 tsp cooking salt / kosher salt","1/8 tsp black pepper","1 tbsp finely chopped parsley (, for garnish (optional))"],"purpose":"Marsala sauce:"}]', '[{"description":"Chicken escalopes:","images":[],"step":1},{"title":"Pound","description":"Cut each breast in half to form 2 thin steaks. Cover with a freezer bag or Go-Between (Note 5) and pound to 1 cm / 0.4″ thickness using a meat mallet or rolling pin. This tenderises and ensures even cooking of the chicken.","images":[],"step":2},{"title":"Dust","description":"Sprinkle the surface with half the salt, pepper then flour. Lightly rub flour across surface, turn and repeat with remaining salt, pepper and flour. Shake excess flour off each piece just before cooking.","images":[],"step":3},{"title":"Cook","description":"Put half the butter and oil in a large non-stick pan over medium high heat. Once the butter is melted and foamy, place chicken in, then cook for 3 to 4 minutes until it''s gorgeously golden and crispy. Turn and cook the other side for 2 minutes. Remove onto a plate.","duration":3.5,"images":[],"step":4},{"description":"Creamy marsala sauce:","images":[],"step":5},{"title":"Sauté aromatics","description":"In the same pan, add remaining butter and oil. Once butter is melted, add eschalots and garlic. Cook for 1 minute.","duration":1,"images":[],"step":6},{"title":"Cook mushrooms","description":"Add mushrooms. Cook for 3 minutes, stirring regularly.","duration":3,"images":[],"step":7},{"title":"Reduce marsala","description":"Add marsala, turn up heat to high and boil for 3 minutes or until reduced by half.","duration":3,"images":[],"step":8},{"title":"Thicken sauce","description":"Add chicken stock, cream, salt and pepper. Stir, then lower heat so it''s simmering (not boiling rapidly) and simmer for 3 to 5 minutes until the sauce thickens to a cream consistency (not too thick, will thicken more).","duration":4,"images":[],"step":9},{"title":"Rewarm chicken","description":"Nestle chicken into sauce and leave for 30 seconds to reheat.","duration":0.5,"images":[],"step":10},{"description":"Serve! Take off the stove. Sprinkle with parsley, serve over starchy vehicle of choice (I chose mash. Rice, small pasta, polenta or bread for plate mopping also work well!).","images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian","Italian-American"],"categories":["chicken-breast-recipes","chicken-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8d75575a9ea4', 'en', 'US', 'Crunchy crumbed chicken drumsticks', 'Recipe video above. Super crunchy baked drumsticks that are generously seasoned with an addictive zingy kick from black pepper and cayenne. It''s not blow-your-head off but it has a very warm buzz! Just omit the cayenne and reduce the pepper to make it kid friendly. It''s so seasoned you don''t need a sauce for dunking but if you want something quick but great, use my honey mustard or pink sauce - both recipes in the notes.', 'https://www.recipetineats.com/tachyon/2023/05/Crunchy-crumbed-chicken-drumsticks_8.jpg', 15, 45, 60, 4, '[{"id": "ing_chicken", "quantity": {"value": 8.0, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 250.0, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_basil", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.2, "unit": "jar of 50g"}}]', '[{"ingredients":["8 chicken drumsticks","1/2 cup flour (, plain/all purpose)","3 large eggs (, beaten)","1 cup panko breadcrumbs (Note 1)","Canola oil spray (or other oil)"]},{"ingredients":["1 tbsp dried oregano","1 tbsp dried basil","1 tsp garlic powder","1 1/2 tsp smoked paprika","1 1/2 tsp cayenne pepper or pure chilli powder (- Note 2 (omit for kid-friendly))","1 1/2 tsp cooking salt","2 tsp black pepper (reduce to 1/2 tsp for kid-friendly)"],"purpose":"Seasoning:"}]', '[{"description":"Preheat oven to 200°C/400°F (180°C fan). Place a rack on a foil lined tray. Spray rack with oil.","images":[],"step":1},{"title":"Crumbing bowls","description":"Place the flour, whisked eggs and panko in 3 separate medium bowls (bear in mind shape to fit the drumsticks!).","images":[],"step":2},{"description":"Mix Seasoning in a small bowl. Put 1 tablespoon into the flour and the rest in the panko, then mix.","images":[],"step":3},{"title":"Crumb","description":"Pat drumsticks dry with paper towels. Coat in flour (shake off excess), then egg (let excess drip off). Place in panko and rotate, pressing to adhere all over, including the handle. (Note 3 for mess-free hands technique!)","images":[],"step":4},{"title":"Spray","description":"Place drumstick on the rack. Repeat with remaining chicken. Spray very generously with oil.","images":[],"step":5},{"description":"Bake 25 minutes. Turn drumsticks, spray again with oil. Bake a further 20 minutes until golden brown and super crunchy!","images":[],"step":6},{"description":"Serve Eat and enjoy the CRUNCH!","images":[],"step":7}]', '["egg","gluten"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-drumstick-recipes","chicken-recipes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b20ecad7f571', 'en', 'US', 'Thai red curry pot roast chicken', 'Recipe video above. Such a spectacular way to cook a whole chicken! Cooked in a Thai red curry sauce with potatoes and beans, the pot-roasting method keeps the chicken ultra juicy. Plus, we can get away with store bought curry paste here because the chicken juices add a stack of money-can''t-buy flavour into the sauce.Easy enough for midweek, definitely impressive enough for company!', 'https://www.recipetineats.com/tachyon/2023/04/Thai-Red-Curry-Pot-Roast-Chicken_3a.jpg', 10, 75, 155, 5, '[{"id": "ing_chicken", "quantity": {"value": 1.8, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_thai_red_curry_paste", "quantity": {"value": 115.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 666.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.6, "unit": "carton of 250ml"}}, {"id": "ing_lime", "quantity": {"value": 6.0, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 600.0, "unit": "bag of 2kg"}}, {"id": "ing_green_beans", "quantity": {"value": 120.0, "unit": "pack"}}, {"id": "ing_basil", "quantity": {"value": 15.0, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1.8 kg/ 3.6 lb whole chicken","1 tsp cooking/kosher salt","3 tbsp vegetable oil","115g/ 4 oz (1/2 cup) Thai red curry paste ( (Maesri recommended, Note 1))","2 large garlic cloves (, finely grated (Note 2))","2 tsp fresh ginger (, finely grated (Note 2))","2 tsp fresh lemongrass (, finely grated, white / pale green part only (Note 2))","1 cup chicken stock/broth (, low sodium)","400 ml/ 14 oz coconut cream (Note 3)","6 kaffir lime leaves (, crushed in hand (Note 4))","1 tbsp white sugar","2 tsp fish sauce","600g/ 1.2lb small potatoes (12 or so), (skin on (Note 5))","120g/ 4oz green beans (, trimmed and cut in half)","15 Thai basil leaves (, or more! (sub ordinary Italian basil, Note 6))"]},{"ingredients":["Jasmine rice","Red chilli (, finely sliced)","Coriander / cilantro leaves"],"purpose":"Serving + optional garnishes:"}]', '[{"title":"De-chill & salt chicken","description":"Take the chicken out of the fridge 1 hour prior. Pat dry then sprinkle with the salt.","images":[],"step":1},{"description":"Preheat oven to 200°C/400°F (180°C fan).","images":[],"step":2},{"title":"Sauté curry paste","description":"Use a large, oven-proof pot with a lid. Heat oil on medium high heat. Cook curry paste, garlic, ginger and lemongrass for 2 minutes. This step substantially improves the flavour of store bought curry paste.","duration":2,"images":[],"step":3},{"title":"Sauce","description":"Add chicken stock, stir, then simmer rapidly for 3 minutes to reduce by half. Stir in coconut cream, hand-crushed kaffir lime leaves, sugar and fish sauce.","duration":3,"images":[],"step":4},{"description":"Place chicken into the sauce. Spoon over sauce. Surround with potatoes.","images":[],"step":5},{"title":"Bake 1 hour","description":"Place the lid on and bake for 40 minutes. Remove lid spoon sauce over chicken (ie. baste). Turn the oven up to 220°C/425°F (200°C fan). Bake uncovered for 10 minutes, baste, bake another 10 minutes.","duration":40,"images":[],"step":6},{"title":"Beans, then bake 10 minutes","description":"Push beans into the sauce (wherever they fit!). Baste again then bake for a final 10 minutes (no lid).","images":[],"step":7},{"title":"Rest 10 minutes","description":"Remove chicken onto a plate (Note 7). Rest 10 minutes. Put lid on pot to keep sauce warm.","images":[],"step":8},{"title":"Serving","description":"Carve chicken, place on platter. Stir basil leaves into sauce. Pour/spoon sauce, potatoes and beans over chicken. Garnish with chilli and coriander, if desired. Serve with jasmine rice!","images":[],"step":9}]', '["fish"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Thai-ish"],"categories":["chicken-recipes","cuisines","one-pot-recipes","thai-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_89bf2e1811c6', 'en', 'US', 'Jalapeño popper stuffed chicken', 'Recipe video above. I love a stuffed chicken - and this is my (current) favourite. Think - Jalapeño popper, stuffed inside chicken. Warm, cheesy, spicy. Fabulous, easy way to make chicken breast a whole lot more exciting! Adore the jalapeño flavour in this.Spice level - not too spicy at all! The spiciness of fresh jalapeños gets dialled down a LOT when baked in the cream cheese. It will surprise you. Reader feedback - Sue says "My husband does not like spicy and said it was delicious. A definite “make again”." - 30 Mar 2023', 'https://www.recipetineats.com/tachyon/2023/03/Jalapeno-popper-stuffed-chicken_4.jpg', 15, 20, 35, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_cream_cheese", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.4, "unit": "pack of 125g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_jalape_os", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["2 x 220g/7oz chicken breast, (skinless, boneless)","1/4 tsp cooking/kosher salt","1/2 tsp smoked paprika (or ordinary paprika)","1 tbsp extra-virgin olive oil"]},{"ingredients":["60g/ 2 oz cream cheese","1/2 cup mozzarella cheese (, shredded (or other cheese))","1/4 cup parmesan (, finely shredded)","2 jalapeños (, deseeded and finely diced (Note 1))","1/2 tsp garlic powder","1/2 tsp black pepper","1/2 tsp cooking / kosher salt"],"purpose":"Jalapeño Popper Stuffing :"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":1},{"description":"Cut pockets into each chicken breast (Note 2), taking care not to cut all the way through. Cut on the side with the fold in the meat, to keep the smooth side intact.","images":[],"step":2},{"title":"Stuffing","description":"Microwave the cream cheese for 30 seconds to soften. Mix together with remaining jalapeño popper stuffing ingredients.","duration":0.5,"images":[],"step":3},{"title":"Stuff & seal","description":"Stuff inside the chicken pockets, stuffing it all the way in! Then seal each chicken with 2 or 3 toothpicks. If some stuffing is oozing out, that’s a bonus - it’s the best part when it crisps in the pan! Sprinkle both sides of the chicken with the paprika and salt.","images":[],"step":4},{"title":"Sear","description":"Heat the oil in an oven-proof skillet over medium-high heat. Place the breast smooth-side down, sear for 2 minutes until golden (it won''t colour more in the oven). Flip and sear the other side for another 2 minutes.","duration":2,"images":[],"step":5},{"title":"Bake 15 min","description":"Transfer the pan to the oven and bake for 15 minutes, or until the internal temperature of the chicken reaches 67°C/155°F.","duration":15,"images":[],"step":6},{"title":"Rest and serve","description":"Remove the chicken to a plate and rest for 5 minutes, then serve!","duration":5,"images":[],"step":7}]', '["milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_48859ff3efa2', 'en', 'US', 'One Pot Chicken Risoni', 'Recipe video above. A great one-pot meal for midweek, tastes like risotto but so much easier to make! Lemon garlic chicken, surprising amount of hidden vegetables, oozy tomato risoni (orzo), loaded with Greek flavours! The list of ingredients is looks long, but there''s actually a lot of repeat ingredients. :)', 'https://www.recipetineats.com/tachyon/2016/01/One-Pot-Greek-Risoni_7.jpg', 15, 35, 50, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.015, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.015, "unit": "net of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.45, "unit": "pack of 500g"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 0.9, "unit": "punnet of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 0.5, "unit": "block of 250g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["1 lb / 500g chicken thighs (, boneless skinless (or breast), cut into 2 cm / 1\" pieces)","2 garlic cloves (, finely minced)","1 tbsp dried oregano","1 tbsp olive oil","1/2 tbsp lemon juice","1 tsp lemon zest","1/2 tsp each salt and pepper"],"purpose":"Lemon Garlic Chicken"},{"ingredients":["2 tbsp olive oil","2 garlic cloves (, minced)","1 small onion (, finely chopped)","2 zucchini (medium, or 1 large) (, cut into 1cm / 1/3\" cubes (Note 1))","1 red bell pepper/capsicum (, cut into 1cm / 1/3\" cubes (Note 1))","1 tbsp dried oregano","2 1/2 cups chicken broth/stock (, low sodium)","14 oz / 400g canned crushed tomatoes","1 tbsp tomato paste","1 1/2 cups orzo/risoni (Note 2)","1 1/2 cups cherry tomatoes (1 Australian punnet)","1 tsp cooking salt (kosher salt)","1/2 tsp black pepper"],"purpose":"Orzo/Risoni"},{"ingredients":["2 tbsp lemon juice (, drizzling at end)","1/2 cup (100g) Greek feta cheese (, crumbled (not optional))","Fresh oregano leaves (optional)"],"purpose":"Garnish (semi-optional)"}]', '[{"title":"Marinade chicken","description":"Combine Marinated Chicken ingredients in a bowl and set aside for marinate for 20 minutes. (Skip if in hurry, can also do overnight)","duration":20,"images":[],"step":1},{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":2},{"title":"Brown chicken (raw inside)","description":"Heat 1 tablespoon olive oil in a a large oven proof skillet or pot over high heat (Note 3). Cook chicken until lightly browned but still pink inside. Remove from skillet.","images":[],"step":3},{"title":"Sauté vegetables","description":"Add 1 tbsp olive oil, garlic and onion. Saute for 1 minute, then add zucchini and bell peppers/capsicum. Cook for 2 minutes.","duration":1,"images":[],"step":4},{"title":"Add everything else","description":"Add risoni, oregano, chicken broth, tomato, tomato paste, salt and pepper.","images":[],"step":5},{"description":"Scatter chicken and cherry tomatoes across the surface (don''t stir in).","images":[],"step":6},{"title":"Bake 15 minutes","description":"Once the liquid comes to a simmer, transfer to the oven (no lid) and bake for 15 minutes (or until risoni is just cooked, tender but still firm). There may be liquid on the surface still - that''s good!","duration":15,"images":[],"step":7},{"title":"Drizzle with lemon","description":"Remove from oven, drizzle with lemon juice. Garnish with feta and fresh oregano leaves, if desired, then serve.","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Greek(ish)"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","greek-recipes","main-dishes","mediterranean-recipes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7cf0a5b018f6', 'en', 'US', 'One Pot Mexican Chicken and Rice', 'Recipe video above. Chicken seared with Fajita flavours then baked with seasoned Mexican red rice. This is a flavour explosion in one pot! People love that it''s finished in the oven. No need to worry about a scorched base!Makes more rice than you''ll need because it is difficult to make less using this method of cooking. Nobody complains, cause it''s so good!', 'https://www.recipetineats.com/tachyon/2014/12/One-Pot-mexican-chicken-and-rice_3.jpg', 15, 50, 55, 5, '[{"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.009, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_lime", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_black_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_ime", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2 tsp garlic powder (or 2 garlic cloves, minced)","2 tsp paprika","2 tsp cumin powder","1 3/4 tsp salt","1/2 tsp cayenne pepper ((Note 1), optional)","Black pepper"],"purpose":"Mexican Spice Mix"},{"ingredients":["5 chicken thighs, bone-in, skin on ( (Notes 2 and 3))","2 tbsp olive oil","1 tbsp lime juice"],"purpose":"Chicken"},{"ingredients":["1 small onion (, peeled and diced (or 1/2 large))","1 garlic clove (, minced)","1 red capsicum ((bell pepper), diced or sliced)","1 cup long grain rice (, uncooked (Note 4))","1 cup chicken stock/broth (, low sodium (or vegetable stock))","3/4 cup tomato passata (US: tomato puree) (Note 5)","1 cup frozen corn kernels (or canned - drained)","1 can (400g/16oz) black beans (, drained and rinsed (sub red kidney beans))"],"purpose":"Rice"},{"ingredients":["1 lime (, plus extra to serve)","Coriander/cilantro","Sliced jalapeño peppers (optional)"],"purpose":"Garnish"}]', '[{"description":"Preheat oven to 180°C/350°F (160° fan).","images":[],"step":1},{"title":"Mexican spice mix","description":"Mix the ingredients in a small bowl.","images":[],"step":2},{"title":"Rub Chicken","description":"Place 1 1/2 tablespoons of the Mexican Spice Mix in a large bowl (reserve rest for rice) with 1 tablespoon olive oil and lime juice. Mix to form a paste then add the chicken and toss to coat the chicken.","images":[],"step":3},{"title":"Marinate (optional)","description":"Marinate chicken for 1 hour, or even overnight, if you have the time. Otherwise, it''s fine to proceed with the recipe!","images":[],"step":4},{"title":"Sear chicken","description":"Using a large deep skillet preferably with a lid (Note 6), heat the remaining 1 tbsp olive oil over medium high heat. Sear the skin side of the chicken for 4 minutes until light golden, then sear the flesh side for 1 1/2 minutes (will still be raw inside). Remove onto a plate.","duration":4,"images":[],"step":5},{"title":"Sauté aromatics","description":"If you''ve got a lot of burnt spices on the base, scrape off and discard some of it. Then in the same skillet, still over medium high heat, add the onion, garlic and capsicum (bell peppers). Sauté for 3 minutes until the onion softens.","duration":3,"images":[],"step":6},{"title":"Rice & liquid","description":"Add the rice and stir. Add chicken stock, tomato passata, corn, beans and remaining Mexican Spice Mix. Stir to combine.","images":[],"step":7},{"title":"Top with chicken","description":"Place chicken on top of the rice, skin side up. It will be partially submerged but most of the skin should be above the liquid.","images":[],"step":8},{"title":"Bake covered 25 min","description":"Bring to simmer, then cover skillet with a lid or foil and place in the oven for 25 minutes.","duration":25,"images":[],"step":9},{"title":"Bake uncovered 15 min","description":"Remove the lid/foil and bake for a further 15 minutes until only small puddles of liquid remain on the surface of the rice.","images":[],"step":10},{"title":"Rest 10 minutes","description":"Remove from the oven and allow to rest for 10 minutes (uncovered). Any remaining liquid will evaporate in this step.","duration":10,"images":[],"step":11},{"title":"Serve","description":"Squeeze the juice of 1 lime over the chicken and rice. Remove chicken or push to the side then fluff the rice. Serve, garnished with coriander/cilantro leaves, extra lime wedges and sliced jalapeños, if desired. Sour cream also goes well with this, or a dollop of guacamole or avocado sauce!","images":[],"step":12}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","mexican-recipes","most-popular","one-pot-recipes","quick-and-easy","rice-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bc52387c7145', 'en', 'US', 'Honey Soy Wings', 'Recipe video above. The easiest, no-fuss way to make sticky Honey Soy Wings in the oven. Don''t you hate it when you''re promised sticky wings but the sauce stays watery and never thickens?? Trick is to just pour off chicken juices partway through cooking. Easy!Serve with fried rice or Vermicelli Noodle Salad for a great quick midweek meal.', 'https://www.recipetineats.com/tachyon/2022/11/Honey-Soy-Wings_7.jpg', 5, 60, 65, 4, '[{"id": "ing_chicken", "quantity": {"value": 1.25, "unit": "kg"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_honey", "quantity": {"value": 0.12, "unit": "jar of 500g"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.3, "unit": "bottle of 250ml"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.09, "unit": "bottle of 500ml"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_oil", "quantity": {"value": 7.5, "unit": "bottle"}}]', '[{"ingredients":["1.25 kg / 2.5 lb chicken wings (wingettes/drumettes), or cut up whole wings (Note 1 for whole wings)","1 tsp white sesame seeds","1 green onion stem (, finely sliced)"]},{"ingredients":["4 tbsp honey","5 tbsp light soy sauce (Note 2)","1 tbsp dark soy sauce (Note 2)","3 tbsp apple cider vinegar (or other clear vinegar)","1 large garlic clove (, crushed using garlic press (or finely minced or grated))","1/2 tbsp canola oil"],"purpose":"Honey soy marinade:"}]', '[{"description":"Mix marinade in a bowl until honey is dissolved. Pour over the wings in a ziplock bag. (Note 3)","images":[],"step":1},{"description":"Marinade for 30 minutes. You can do overnight but it doesn''t noticeably improve flavour in the flesh.","duration":30,"images":[],"step":2},{"description":"Preheat oven to 200°C/400°F (180°C fan). Line a large tray with foil then paper.","images":[],"step":3},{"title":"Bake","description":"Spread wings out on the tray, skin side up. Reserve marinade. Bake 30 minutes.","images":[],"step":4},{"description":"Drain off juices on the tray and discard. (Key step to ensure sauce thickens).","images":[],"step":5},{"title":"Sauce","description":"Pour reserved marinade over wings. Toss to coat then spread the wings out, skin side up.","images":[],"step":6},{"title":"Bake & baste","description":"Turn oven down to 180°C/350°F (160°C fan). Bake wings for 30 minutes, basting with tray juices every 10 minutes (3 times). Rearrange wings as needed if cooking unevenly, you can even turn them upside down if they brown too quickly. Sauce should be syrupy by the end so you can glaze well. (Note 4 if sauce still watery).","duration":30,"images":[],"step":7},{"title":"Serve","description":"Transfer wings into a serving bowl. Pour over syrup on tray, sprinkle with sesame seeds and green onion. Serve!","images":[],"step":8}]', '["gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Asian-esque","Western"],"categories":["chicken-recipes","chicken-wings","finger-food","quick-and-easy","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2544a6f1bff9', 'en', 'US', 'Chicken in Creamy Mustard Sauce', 'Recipe video above. Here''s a really quick way to cook chicken thighs or breast in a simple yet elegant creamy mustard sauce. Mustard adds flavour as well as thickening the sauce while tarragon infuses the sauce with elegant aniseed notes, giving it a very restaurant-y flavour. But even if you don''t have fresh tarragon or don''t like it, this is absolutely still worth making. In fact, I''ve probably made it as often without tarragon as I have with!', 'https://www.recipetineats.com/tachyon/2022/11/Chicken-in-creamy-mustard-sauce_3.jpg', 5, 10, 15, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_tarragon", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["700g / 1.4 lb chicken thigh fillets (, skinless boneless (4 - 6 pieces, Note 1))","1 1/2 tbsp olive oil","1/2 tsp cooking/kosher salt","1/4 tsp black pepper"]},{"ingredients":["1/2 cup thickened/heavy cream","1 tbsp Dijon mustard","1 tbsp whole grain mustard","1/4 tsp cooking/kosher salt","1/4 tsp black pepper","1-2 tbsp water (, as needed)"],"purpose":"Creamy mustard sauce:"},{"ingredients":["2 tsp fresh tarragon (, finely chopped (Note 2))","2 tsp parsley (, finely chopped)"],"purpose":"Optional herbs:"}]', '[{"description":"Season chicken with the salt and pepper.","images":[],"step":1},{"title":"Sear chicken thighs","description":"Heat oil in a large pan that is not non-stick over medium-high heat. (Note 3) Place chicken in pan smooth side-down and cook for 4 minutes or until deep golden. Turn and cook the other side for 3 minutes until cooked through (internal temperature 72°C/162°F, Note 4). Remove to a plate.","duration":4,"images":[],"step":2},{"title":"Breast","description":"If using breast (prepared per Note 1), sear on high for 2 minutes on each side, target temp 67°C/153°F.)","duration":2,"images":[],"step":3},{"title":"Clean pan","description":"Scrape any loose black bits out of the pan and discard.","images":[],"step":4},{"title":"Make sauce","description":"Return the pan to medium heat. Add cream and both mustards. Mix with a wooden spoon until mustard dissolves, scraping up any brown bits stuck to the pan. Once sauce is hot but not simmering, stir in salt, pepper and herbs (if using). If getting too thick loosen with a touch of water.","images":[],"step":5},{"title":"Serve","description":"Place chicken on serving plates. Spoon over sauce. Enjoy!","images":[],"step":6}]', '["milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9c345eb01285', 'en', 'US', 'Chicken Rissoles', 'Recipe video above. The chicken version of the beloved Aussie beef rissoles! You''ll love the oozy little pockets of cheese.Makes 14 to 16 rissoles. Serves 4 to 5 as a meal, or one Dozer.', 'https://www.recipetineats.com/tachyon/2022/09/Chicken-Rissoles_4.jpg', 15, 20, 35, 16, '[{"id": "ing_chicken_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_bread", "quantity": {"value": 0.141, "unit": "loaf"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_ketchup", "quantity": {"value": 1.0, "unit": "bottle of 500g"}}]', '[{"ingredients":["500g / 1 lb chicken mince (ground chicken), excess liquid drained and discarded (Note 1)","1 carrot, medium (, grated on a shallow angle (Note 2))","1 zucchini, medium (, grated on a shallow angle (Note 2))","1 egg","1 1/2 cup Colby cheese, shredded (or cheddar, tasty, Monterey Jack - see Note 3)","3/4 cup panko breadcrumbs (Note 4)","1 tbsp finely chopped parsley (, optional)","1 tsp cooking/kosher salt","1/2 tsp black pepper"],"purpose":"Rissoles:"},{"ingredients":["2 tbsp canola oil","Ketchup - for dipping"],"purpose":"Cooking & serving:"}]', '[{"description":"Pre-heat oven to 100°C/210°F (all oven types), to keep cooked rissoles warm. Place a rack over a tray.","images":[],"step":1},{"title":"Rissole mixture","description":"Mix all ingredients together in a bowl using a wooden spoon.","images":[],"step":2},{"title":"Form patties","description":"Wet your hands (stops the mixture sticking all over your hands). Measure out just shy of 1/4 cup and shape into a 6 cm wide x 1.5cm thick pattie (2.4\" x 0.6\" thick). See Note 1 if your mixture is too loose.","images":[],"step":3},{"title":"Cook","description":"Heat 1 tablespoon oil in a large non-stick pan over medium high heat. Cook 5 - 6 rissoles at the time, 3 to 4 minutes on each side, until beautifully golden (as pictured). (Note 5 for baking)","images":[],"step":4},{"title":"Keep warm","description":"Transfer to the rack on the tray and keep warm in the oven. Add more oil as needed and cook remaining rissoles.","images":[],"step":5},{"description":"Serve straight away with ketchup for dipping!","images":[],"step":6}]', '["egg","milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-mince-recipes","chicken-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_25cd81634cc8', 'en', 'US', 'Crispy Baked Chicken Drumsticks', 'Recipe video above. This is just a great, simple chicken drumsticks recipe you can get in the oven quickly. Tossed in a 3-ingredient, barbecue rub-like seasoning, they''re beautifully crispy thanks to a touch of baking powder, a tried and proven secret ingredient in my Truly Crispy Baked Chicken Wings recipe!', 'https://www.recipetineats.com/tachyon/2022/07/Crispy-Baked-Chicken-Drumsticks_5.jpg', 10, 45, 55, 5, '[{"id": "ing_chicken", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.625, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.2, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.068, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.1, "unit": "tub of 150g"}}]', '[{"ingredients":["12 chicken drumsticks (Note 1)","2 tbsp extra virgin olive oil","Oil spray"]},{"ingredients":["3 tsp garlic powder","3 tsp onion powder","5 tsp smoked paprika","2 tsp black pepper","1 1/2 tsp cooking/kosher salt","4 1/2 tbsp plain/all-purpose flour","3 tsp baking powder (makes them crispier, DO NOT confuse with baking soda / bi-carb) (Note 3)"],"purpose":"Seasoning (Note 2):"}]', '[{"title":"Preparation","description":"Preheat the oven to 200°C/390°F (180°C fan-forced). Line a tray with foil then place a rack on the tray (makes the underside of the drumsticks crispier, Note 4).","images":[],"step":1},{"title":"Seasoning","description":"Mix the Seasoning ingredients in a shallow bowl.","images":[],"step":2},{"title":"Coat in oil","description":"Toss the drumsticks in the olive oil. Stretch and pull the skin on each drumsticks to cover as much of the flesh as possible.","images":[],"step":3},{"title":"Coat in seasoning","description":"Coat a drumstick in the Seasoning then shake the excess off well. Place on the rack. Repeat with remaining drumsticks.","images":[],"step":4},{"title":"Spray with oil","description":"Spray the legs generously with oil.","images":[],"step":5},{"description":"Bake for 30 minutes, rotating the tray halfway through. Increase the oven to 220°C / 430°F (200°C fan) then bake for a further 15 minutes or until the skin is crispy. Enjoy!","duration":30,"images":[],"step":6}]', '["gluten"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-drumstick-recipes","chicken-recipes","dinner-tonight","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7b601609467c', 'en', 'US', 'Chicken Fricassée (French creamy chicken stew)', 'Recipe video above. A recipe from our chef JB (yes, he''s French!), this traditional French dish is essentially a quick chicken stew with a creamy white mushroom sauce. It''s a bit like a white sauce version of the famous French Coq au Vin – but it''s much faster to make!This is a wonderful rustic family meal that''s quick enough for midweek, or to elevate to restaurant level by using homemade chicken stock.', 'https://www.recipetineats.com/tachyon/2021/09/Chicken-Fricasse_03-SQ.jpg', 20, 60, 80, 4, '[{"id": "ing_chicken", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_cream", "quantity": {"value": 0.667, "unit": "carton of 250ml"}}]', '[{"ingredients":["4 chicken drumsticks (~150g/5oz each, Note 1)","4 chicken thighs (, skin-on and bone-in (~250g/8oz each, Note 1))","1 tsp salt (cooking / kosher salt)","1/2 tsp black pepper","4 tbsp / 60g unsalted butter"],"purpose":"Chicken"},{"ingredients":["300g / 10oz white mushrooms (, halved if small, or cut in 4 to 6 if large)","2 medium brown onions (, sliced 0.6cm (1/2in) wide)","2 garlic cloves (, finely minced)","1 bay leaf (, fresh (sub dried))","3 thyme sprigs (or 1/2 tsp dried thyme)","3 tbsp flour (, plain / all-purpose)","1/2 cup white wine (, preferably chardonnay (Note 2))","3 cups chicken stock (, low sodium (preferably homemade!))","1/4 tsp salt (cooking / kosher salt)","1/4 tsp black pepper","2 tbsp parsley (, chopped)","2/3 cup thickened/heavy cream"],"purpose":"Stew ingredients"}]', '[{"title":"Season chicken","description":"Pat chicken dry with paper towels then sprinkle with salt and pepper.","images":[],"step":1},{"title":"Brown thighs","description":"Melt butter over medium-high heat in a large skillet or heavy based pot with a lid. Add chicken thighs, skin side down, and cook for 4 to 5 minutes until golden brown. Turn and cook the other side for 1 minute then remove to a plate.","duration":4.5,"images":[],"step":2},{"title":"Brown drumsticks","description":"Then brown the drumsticks, as best you can. I do 3 sides, about 2 minutes each. Then remove from skillet.","images":[],"step":3},{"title":"Sauté mushrooms and onion","description":"Add mushrooms, onion, bay leave and thyme. Cook for 5 minutes until mushroom is lightly golden - they won''t go deep golden brown.","duration":5,"images":[],"step":4},{"title":"Garlic and flour","description":"Add garlic and stir for 30 seconds. Add flour and cook for 1 minute.","duration":0.5,"images":[],"step":5},{"title":"Wine and chicken stock","description":"Add wine, chicken stock, salt and pepper. Stir, scraping the base of the pot to dissolve the brown residue stuck to the pan (\"fond\") into the sauce.","images":[],"step":6},{"title":"Return chicken to sauce","description":"Return chicken back into the sauce with the skin side up.","images":[],"step":7},{"title":"Simmer covered 10 minutes","description":"Once it comes to a simmer, adjust heat so it''s bubbling constantly but not rapidly (see video) - medium-low on my stove. Cover with lid and simmer 10 minutes.","images":[],"step":8},{"title":"Uncover 20 minutes","description":"Remove lid and let it simmer for a further 20 minutes. Chicken will be cooked - internal temperature 75°C/167°F or slightly higher.","images":[],"step":9},{"title":"Creamy sauce","description":"Remove chicken to a plate. Add cream and stir. Once it comes up to a simmer, taste sauce (I know, big ask!), and add more salt if desired..","images":[],"step":10},{"description":"Serve! Return chicken into the sauce then remove from the stove. Sprinkle with parsley and serve! Traditionally served over mashed potato or rice. Also ideal with short pasta like penne, ziti or macaroni.","images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["chicken","chicken-drumstick-recipes","chicken-recipes","mains","quick-and-easy","stews"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ffff10b2a364', 'en', 'US', 'Coq au Vin', 'Recipe video above. Coq au Vin – a true French classic from a true French chef, our very own JB! Chicken pieces are braised in a luscious, glossy red wine sauce with bacon, mushroom and onions that tastes utterly luxurious. Like Beef Bourguignon, the beauty of this dish lies in its simplicity: remarkably few ingredients and simple process with results fit for a king – or queen! For the best results, start this 2 days before serving: 12 - 24 hour marinade for the chicken (essential), then rest the finished stew overnight to let the flavours develop even further (recommended but not essential).', 'https://www.recipetineats.com/tachyon/2016/09/Coq-au-Vin_00.jpg', 15, 90, 105, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 16.0, "unit": "pack of 1kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_wine", "quantity": {"value": 1.0, "unit": "bottle of 750ml"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.105, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["4 chicken thighs (, bone-in, skin on (~220g / 7 oz each) (Note 1))","4 chicken drumsticks (Note 1)","16 pearl onions or picking onions (Note 2)","1 bay leaf (, fresh (dry also ok))","3 thyme sprigs (sub 1 tsp dried thyme)","750 ml / 3 cups pinot noir red wine (, or other dry red wine (Note 3))"],"purpose":"Red Wine Chicken Marinade:"},{"ingredients":["3 - 4 tbsp vegetable oil (or canola oil)","3/4 tsp salt (cooking/kosher salt, or 1/2 tsp table salt)","1/2 tsp pepper"],"purpose":"Browning Chicken:"},{"ingredients":["400g / 14oz white mushrooms (, halved (quartered if large) (Note 4))","150g / 5oz bacon piece (, (speck) cut into 1 x 2.5cm / 0.4 x 1\" batons (Note 5))","60g / 4 tbsp unsalted butter","3 garlic cloves (, finely minced (with knife))","2 tbsp tomato paste","7 tbsp flour (, plain / all purpose)","750 ml / 3 cups beef stock","1/4 tsp salt (cooking/kosher salt, or 1/8 tsp table salt) (Note 7)","1/4 tsp black pepper"],"purpose":"Coq au Vin Stew:"},{"ingredients":["2 tbsp parsley (, chopped)","Mashed potato (or tagliatelle)"],"purpose":"Garnish and serving:"}]', '[{"description":"Marinate chicken:","images":[],"step":1},{"title":"Marinate chicken","description":"Place the Chicken Marinade ingredients in a large glass or ceramic bowl or dish. Marinate overnight in the fridge (minimum 12 hours, maximum 24 hours).","images":[],"step":2},{"description":"Strain wine into a bowl. Reserve herbs and wine. Separate the chicken and onion.","images":[],"step":3},{"title":"Dry chicken","description":"Spread chicken out on a try lined with paper towels, then pat dry with paper towels.","images":[],"step":4},{"title":"Reduce wine","description":"Pour red wine into a saucepan and bring to a boil over medium high heat. Simmer vigorously, skimming off any impurities that rise to the surface, until reduced by half. Set aside.","images":[],"step":5},{"description":"Brown chicken and vegetables:","images":[],"step":6},{"description":"Preheat oven to 180°C / 350°F (160°C fan).","images":[],"step":7},{"title":"Season chicken","description":"Sprinkle chicken with 3/4 tsp salt and 1/2 tsp black pepper.","images":[],"step":8},{"title":"Brown chicken","description":"Heat 3 tbsp oil in a large, heavy-based, oven-proof pot over medium-high heat. Add chicken thighs skin side down and cook for 2 - 3 minutes until nicely browned (it will be darker than usual because of the red wine). Flip thighs and cook the other side for another minute to kiss it with a little colour. Remove to a tray. Pull at skin of drumsticks to cover flesh as best as possible, then brown (I do 3 to 4 sides, ~5 minutes in total). Remove and set aside.","duration":2.5,"images":[],"step":9},{"title":"Fry bacon","description":"Remove any loose black burnt bits. Add a bit of extra oil if needed, then cook bacon for 3 minutes until golden. Add to tray with chicken.","duration":3,"images":[],"step":10},{"title":"Sauté mushrooms","description":"Add mushrooms and cook for 5 minutes, or until golden. Remove into a separate bowl.","duration":5,"images":[],"step":11},{"title":"Sauté onion","description":"Add a bit of extra oil if needed, then cook onions for 5 minutes or until there are nice golden patches.","duration":5,"images":[],"step":12},{"title":"Butter and flour","description":"Add butter into pot. Once melted, add garlic and cook for a further 1 minute. Add tomato paste and cook for 2 minutes. Add flour and cook for 2 minutes.","duration":2,"images":[],"step":13},{"title":"Add wine and stock","description":"While stirring, slowly pour in beef stock – this helps the flour dissolve lump-free into the stock. Then add the reduced wine and mix until flour mixture is dissolved and mostly lump-free. (Note 8)","images":[],"step":14},{"title":"Add everything back in","description":"Add chicken, bacon, mushroom, thyme, bay leaf, salt and pepper into the pot, then stir.","images":[],"step":15},{"title":"Oven 45 minutes","description":"Bring to a simmer, then cover and transfer to oven for 45 minutes. Chicken will be very tender - but not \"falling apart\". (Note 9)","duration":45,"images":[],"step":16},{"title":"Adjust salt","description":"Remove from oven, taste sauce and add salt if needed.","images":[],"step":17},{"title":"Leave overnight (recommended, Note 11)","description":"If time permits, leave the stew overnight before serving because as with all stews, it gets better with time! Reheat gently on a low stove in a covered pot, ensuring that chicken is fully heated through. Add water if needed to loosen sauce.","images":[],"step":18},{"description":"Serve over mashed potato or tagliatelle, sprinkled with fresh parsley! For the ultimate experience, mop the plate clean with homemade brioche (surprisingly straight forward to make). See in post for side salad and dessert options.","images":[],"step":19}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["chicken-drumstick-recipes","chicken-recipes","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_248ab261c994', 'en', 'US', 'Mushroom Stuffed Chicken Breast', 'Recipe video above. These juicy chicken breasts are stuffed with garlicky mushrooms, spinach leaves and a blanket of oozing melted cheese. Simple to make with just a few ingredients, this is how to transform chicken breast from ho-hum into "ohhh yum!"After this one, try Sun Dried Tomato Stuffed Chicken!', 'https://www.recipetineats.com/tachyon/2021/07/Mushroom-Stuffed-Chicken-Breast_14.jpg', 15, 30, 45, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_baby_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.64, "unit": "pack of 125g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}]', '[{"ingredients":["2 x 220g / 7oz chicken breast (, skinless boneless (Note 1))","3/4 tsp salt","1/4 tsp pepper","30g / 2 tbsp unsalted butter","200g / 7 oz mushrooms (, sliced 3mm (1/8″) thick (~2 heaped cups))","2 garlic cloves (, finely minced)","1/2 tsp thyme leaves (Note 2)","2 cups baby spinach (Note 3)","80 g / 3oz mozzarella (, sliced (or other melting cheese))","1 tbsp olive oil"]}]', '[{"description":"Preheat oven to 200°C/390°F (180°F fan).","images":[],"step":1},{"description":"Cut pockets into each chicken breast, being sure not to cut all the way through (see photos in post). Cut on the side with the fold in the meat, to keep the smooth side intact.","images":[],"step":2},{"description":"Season the inside and outside of the chicken with half the salt and pepper.","images":[],"step":3},{"title":"Mushroom filling","description":"Melt butter in a heavy based oven proof skillet over high heat. Add mushrooms and cook for 3 minutes until they start to turn pretty golden. Then add garlic, thyme, remaining salt and pepper and continue cooking for a further 2 minutes until mushrooms are nice and golden.","duration":3,"images":[],"step":4},{"title":"Add spinach","description":"Add baby spinach and stir until wilted - about 30 seconds.","images":[],"step":5},{"description":"Stuff mushroom mixture into the pocket of each chicken, then top with cheese.","images":[],"step":6},{"title":"Seal with toothpicks as best you can","description":"it doesn’t need to be fully sealed like we do with Chicken Kiev. Just mostly sealed.","images":[],"step":7},{"title":"Sear chicken","description":"Give the pan a quick wipe with paper towels. Heat oil over medium high heat. Sear each side of the chicken breast for 1 1/2 minutes until golden.","images":[],"step":8},{"title":"Bake 15 minutes","description":"Transfer the skillet to the oven and bake for 15 minutes, or until the internal temperature of the chicken is 65°C/149°F (chicken flesh, not the mushroom filling).","duration":15,"images":[],"step":9},{"title":"Rest 5 minutes","description":"Remove from tray onto a plate, loosely cover with foil and rest for 5 minutes. Serve! Pictured in post with easy creamy Baked Lemon Herb Risotto and baby spinach with Balsamic Dressing.","duration":5,"images":[],"step":10}]', '["milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8b10b7260e13', 'en', 'US', 'Chicken Kiev', 'Recipe video above. The trick to ensuring the melted butter stays firmly sealed inside Chicken Kiev? Partially freezing the chicken. Stops the chicken from moving as you handle it for coating / cooking which ensures the chicken remains sealed and keeps the molten river of garlic butter inside!For a real Kiev experience, you do need to deep fry. BUT for the very best healthier baked option, see Note 6.', 'https://www.recipetineats.com/tachyon/2021/05/Chicken-Kiev_2-1.jpg', 30, 30, 60, 2, '[{"id": "ing_butter", "quantity": {"value": 6.0, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_oil", "quantity": {"value": 1000.0, "unit": "bottle"}}]', '[{"ingredients":["6 tbsp / 90g unsalted butter (, softened (or salted butter))","2 tsp parsley (, finely chopped)","2 garlic cloves (, very finely minced (2 tsp))","1/4 tsp salt (skip if using salted butter)"],"purpose":"Garlic Butter Stuffing:"},{"ingredients":["2 x 220 - 250g (7 - 8oz) chicken breast (, skinless and boneless (Note 1))","1/2 tsp salt","1/4 tsp pepper","1 egg (, lightly whisked)","1/4 cup flour","1 cup panko breadcrumbs (Note 2)","Oil for frying (, canola or vegetable oil (~4 cups / 1 litre))"],"purpose":"Chicken:"},{"ingredients":["Parsley (, finely chopped (garnish))"],"purpose":"Serving:"}]', '[{"title":"Garlic butter filling","description":"Place ingredients in a bowl and mix until combined.","images":[],"step":1},{"title":"Shape and chill butter","description":"Scrape butter on to a small sheet of baking / parchment paper and roughly shape into 10 x 6cm / 4 x 2.4\" rectangle. Refrigerate until firm, then cut in half lengthwise to form two batons.","images":[],"step":2},{"title":"Pound chicken","description":"Place chicken smooth side down between two freezer bags or paper (Note 3). Pound to an even 0.5 cm / 0.2\" thickness using a meat mallet (Note 4 for tips!)","images":[],"step":3},{"title":"Season","description":"Sprinkle each side of the chicken with salt and pepper.","images":[],"step":4},{"title":"Stuff and roll up chicken","description":"Place a baton of butter in the middle. Trim edges if needed, then add trimmings into the centre. Fold sides in over the butter, then roll the chicken up starting from the bottom, finishing with the seam side down.","images":[],"step":5},{"title":"Wrap and partially freeze","description":"Wrap the chicken log in cling wrap, twisting the ends tightly to create a firm log shape. Place in the freezer for 30 minutes until the surface is fairly firm to touch, but not frozen solid. (Note 5)","duration":30,"images":[],"step":6},{"title":"Crumb","description":"Place egg, flour and breadcrumbs in separate bowls. Coat chicken in flour, shaking off excess. Coat in egg, drip off excess. Then coat in breadcrumbs, pressing to adhere.","images":[],"step":7},{"title":"Partial freeze","description":"Place crumbed chicken in the freezer for 30 minutes until fairly firm to handle (but not frozen solid).","duration":30,"images":[],"step":8},{"description":"Preheat oven to 180°C / 350°F. Place a rack on a tray.","images":[],"step":9},{"title":"Fry","description":"Heat oil in a heavy based pot to 190°C / 375°F. Carefully place chicken in the oil and cook, turning once or twice, until golden (2 - 3 minutes). It will still be raw inside.","images":[],"step":10},{"title":"Bake","description":"Place chicken on a rack and bake for 15 minutes or until the internal temperature of the chicken is 65°C / 150°F. Pierce the top so you don''t cause butter leakage!","duration":15,"images":[],"step":11},{"description":"Rest for 2 minutes, then serve, sprinkled with a pinch of parsley if desired!","duration":2,"images":[],"step":12}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Russian"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","deep-fried-recipes","mains","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0992d206c899', 'en', 'US', 'Chicken Piccata (Lemon Chicken with Capers)', 'Recipe video above. If, like me, you find the sauce of other Chicken Piccata recipes too sour, and the chicken kind of bland, I think you''ll love this version! The lemon tang in the sauce is pleasant rather than lip-puckering, and the flavour of the chicken is boosted with a little parmesan in the flour coating.', 'https://www.recipetineats.com/tachyon/2021/05/Chicken-Piccata_0.jpg', 10, 0, 10, 3, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.188, "unit": "pack of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_wine", "quantity": {"value": 0.222, "unit": "bottle of 750ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_capers_in_brine", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}]', '[{"ingredients":["450g / 16oz chicken breast (2 large pieces), skinless boneless (Note 1)","4 tbsp flour (sub cornflour/cornstarch for GF)","2 1/2 tbsp parmesan (, finely grated (Note 2))","1/2 tsp salt","1/4 tsp pepper","2 1/2 tbsp olive oil","1 tbsp / 15g unsalted butter"]},{"ingredients":["2 tbsp / 30g unsalted butter (, cut into 1.5cm / 1/2\" cubes)","2/3 cup dry white wine (Note 3)","2 tbsp lemon juice (, fresh)","3 tbsp capers in brine (, drained (Note 4))","1 1/2 tsp parsley (, finely chopped, plus more for garnish)"],"purpose":"Lemon Sauce:"}]', '[{"description":"Crispy Parmesan Chicken:","images":[],"step":1},{"description":"Cut each breast into 3 pieces. Then place between 2 pieces of cling wrap or paper and pound to 1/2 cm / 0.2\" thickness.","images":[],"step":2},{"description":"Drizzle chicken with 1/2 tbsp olive oil and spread with your fingers on both sides.","images":[],"step":3},{"description":"Mix flour, parmesan, salt and pepper in a shallow dish. Coat chicken, pressing to adhere, then shaking off excess.","images":[],"step":4},{"description":"Heat olive oil in a large skillet over medium high heat. Then add butter and let it melt.","images":[],"step":5},{"title":"Place 3 pieces of chicken in the skillet. Cook 3","description":"4 minutes until golden, then turn and cook the other side for 1 minute. Remove onto plate, repeat with remaining chicken.","duration":1,"images":[],"step":6},{"description":"Chicken Piccata Sauce:","images":[],"step":7},{"description":"Pour out and discard excess fat in skillet, then give it a quick wipe with paper towels (no need to clean thoroughly).","images":[],"step":8},{"description":"Still on medium high heat, add wine. Let it simmer rapidly until it reduces by half - around 3 minutes.","images":[],"step":9},{"description":"Add lemon and simmer 1 minute.","images":[],"step":10},{"description":"Reduce heat to low. Add cubed butter and swirl pan to make it melt but not go foamy. Sauce should be glossy, translucent and slightly thickened.","images":[],"step":11},{"description":"Stir in capers and parsley. Serve chicken with Sauce, sprinkled with extra parsley if desired!","images":[],"step":12}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["American-Italian","Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a24c6cbb0774', 'en', 'US', 'Sticky Glazed Christmas Chicken', 'Recipe video above. Everybody loves the glaze on a Christmas ham. So one year, I used it for chicken instead and people went mad over it! Easier and cheaper than ham, with a much higher ratio of glaze to meat, this is so good I''ve actually had people tell me they love this more than Christmas ham!!It''s ultra-sticky on the outside, and smells and tastes like Christmas. The meat is super tender – we''ve practically slow cooked the chicken!', 'https://www.recipetineats.com/tachyon/2020/12/Sticky-Glazed-Christmas-Chicken_1.jpg', 10, 60, 70, 6, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_oranges", "quantity": {"value": 0.025, "unit": "kg"}}, {"id": "ing_oranges", "quantity": {"value": 0.025, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.15, "unit": "jar of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_cinnamon", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_whole_star_anise", "quantity": {"value": 2.0, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_oranges", "quantity": {"value": 0.025, "unit": "kg"}}, {"id": "ing_good_value_leafy_greens", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_oranges", "quantity": {"value": 0.025, "unit": "kg"}}]', '[{"ingredients":["1.2 kg / 2.4 lb chicken thighs, skin on, bone in ( (Note 1))","800g / 1.6 lb chicken drumsticks (, or more thighs (Note 1))"]},{"ingredients":["5 tsp orange zest (2 oranges)","1/2 cup orange juice (from the zested oranges)","1/4 cup cider vinegar (sub white wine, sherry or champagne vinegar)","1/2 cup brown sugar (, lightly packed)","2 tbsp Dijon mustard","1 tbsp olive oil","2 tsp ground cinnamon","1 1/2 tsp allspice","1 tsp ground ginger","2 whole star anise","2 tsp salt","1/2 tsp black pepper"],"purpose":"Marinade"},{"ingredients":["2 oranges (, cut into wedges or halved then sliced)","good value leafy greens (- like endive, watercress, for the bed)","orange zest curls (Note 3)"],"purpose":"Serving and garnishes"}]', '[{"description":"Marinate Chicken","images":[],"step":1},{"description":"Mix Marinade ingredients in a jug. Pour over chicken in a large ziplock bag (Note 2). Massage to coat, then marinate chicken for ideally 24 hours (bare minimum is 3 hrs, 12 hrs is ok).","images":[],"step":2},{"description":"Cook","images":[],"step":3},{"description":"Preheat oven to 200°C/390°F (180°C fan).","images":[],"step":4},{"description":"Line 2 trays with foil then parchment/baking paper (you''ll thank me later).","images":[],"step":5},{"description":"Distribute chicken on trays, then pour the marinade over. Roast 30 minutes.","images":[],"step":6},{"description":"Roast for a further 20 minutes, basting with pan juices 2 or 3 more times until the chicken is deep golden and sticky. At first, the juices will be watery but in the final 10 minutes or so, they will thicken and darken. Once this happens, baste more frequently and heavily. (Note 4)","images":[],"step":7},{"description":"When the top tray is almost ready, switch the tray positions (ie move bottom tray up and put the top tray undenerath) so they finish at the same time. GOAL: Deep golden and sticky chicken!","images":[],"step":8},{"description":"Before plating up, baste again with the sticky juices.","images":[],"step":9},{"title":"Serving suggestion","description":"Spread leafy greens on a platter, pile on sticky chicken. Decorate with orange slices or wedges.","images":[],"step":10}]', '["mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Christmas","Holiday","Western"],"categories":["chicken","chicken-drumstick-recipes","chicken-recipes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_498c3fdc6fa7', 'en', 'US', 'Leftover Turkey Pot Pie', 'Recipe video above. Leftover turkey is quite dry, given it''s a lean meat. So smothering it in a creamy sauce for a Turkey Pot Pie is the ideal way to repurpose perfectly good leftovers! This is like a cross between Chicken Pot Pie and Cheesy Garlic Bread. While the filling is delicious, that buttery garlicky cheesy topping steals the show. I just love how it gets soaked with the creamy white sauce!!Use whatever veggies you want. And of course, chicken is a straight up simple substitute for turkey if that''s what you have.', 'https://www.recipetineats.com/tachyon/2020/11/Leftover-Turkey-Pot-Pie_1.jpg', 15, 40, 55, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_mushroom", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 5.0, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}]', '[{"ingredients":["1 tbsp olive oil","150g / 5 oz mushrooms (, sliced 1/2cm / 1/5\" thick)","50g / 4 tbsp butter","1 onion (, finely chopped (brown, white, yellow))","2 garlic cloves (, minced)","1 carrot (, peeled, chopped into 1cm/ 1/3\" pieces)","4 tbsp flour (plain/all purpose)","2 1/2 cups milk (any fat % fine)","4 cups (600g) cooked chopped turkey or chicken","1 1/2 cups frozen peas","1 tsp chicken or vegetable stock powder (or 1 cube. I use Vegeta powder)","1/4 tsp salt","1/2 tsp black pepper"]},{"ingredients":["50g / 4 tbsp salted butter","2 garlic cloves (, minced using garlic press)","5 packed cups bread chunks ~2.5cm/1\" cubes (Note 1)","2 tbsp parmesan cheese (, grated (optional))","1 cup mozzarella or other melting cheese, shredded or sliced (or enough slices to cover most of top)"],"purpose":"Garlic Bread Topping"}]', '[{"description":"Preheat oven to 180°C/350°F (all oven types)","images":[],"step":1},{"title":"Topping","description":"Stir together melted butter and garlic. Place bread chunks in a bowl, drizzle over butter, toss. Set aside.","images":[],"step":2},{"title":"Brown mushrooms","description":"Heat oil in an oven-proof skillet over high heat. (Note 3) Add mushrooms and cook until browned - about 4 minutes. Remove.","images":[],"step":3},{"title":"Sauté garlic & onion","description":"Lower heat to medium high. Melt butter in same skillet. Add onion and garlic, cook for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Add carrot then cook for 1 minute.","duration":1,"images":[],"step":5},{"description":"Add flour, cook for 1 minute. You''ll have a pasty mix. Don''t worry if it looks dry (depends how sweaty your onions get).","duration":1,"images":[],"step":6},{"title":"Make roux","description":"While stirring, add half the milk and mix quickly to dissolve the paste into the liquid (this happens quite quickly). Add remaining liquid and stir. Add stock powder, salt and pepper, stir.","images":[],"step":7},{"title":"Thicken sauce: Cook for 2","description":"3 minutes, stirring regularly. It should start steaming and bubbling a bit, and the sauce will thicken. Thickness test: coat back of wooden spoon, you should be able to draw a line across it (see video, Note 3)","duration":2.5,"images":[],"step":8},{"description":"Add turkey, peas and mushrooms, and mix into sauce.","images":[],"step":9},{"description":"Top with bread, spread to cover surface. Grate over parmesan if using, top with melting cheese.","images":[],"step":10},{"title":"Bake: Bake for 12","description":"15 minutes or until the cheese gets some brown spots. Tent foil over so it doesn''t stick to the cheese, then bake for a further 10 minutes.","duration":13.5,"images":[],"step":11},{"title":"Serve","description":"Sprinkle with additional parmesan if desired, then serve!","images":[],"step":12}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["American","Western"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","turkey-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1881ba70a6f1', 'en', 'US', 'Chicken with Creamy Mushroom Sauce', 'Recipe video above. The creamy mushroom sauce here is a cut above the usual basic recipes, thanks to the additions of wine, parmesan and chicken stock. It turns this quick chicken dinner into a meal that''s both worthy and elegant enough to serve to company!It''s an excellent sauce to serve with chicken breast, which is very lean and doesn''t actually have very much flavour. Also, the lightly-floured crust on the chicken makes it nice and crispy, giving the sauce something to cling on to. So don’t skip it!', 'https://www.recipetineats.com/tachyon/2020/10/Chicken-in-Creamy-Mushroom-Sauce_7.jpg', 5, 15, 20, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 15.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["2 chicken breasts, large (boneless skinless, ~600-700g / 1.2 - 1.4 lb total, Note 1)","1/2 tsp salt","black pepper","1/4 cup flour","15g / 1 tbsp unsalted butter"],"purpose":"CRISPY CHICKEN"},{"ingredients":["30g / 2 tbsp unsalted butter","300g / 10 oz mushrooms (, sliced (button or Swiss brown))","2 garlic cloves (, minced)","1/4 cup dry white wine (sub more chicken stock, Note 2)","1/2 cup chicken or vegetable stock (, low sodium)","1 cup thickened / heavy cream (, full fat (Note 3))","1/2 cup parmesan (, finely and freshly grated (Note 4))"],"purpose":"Mushroom Sauce"},{"ingredients":["2 tbsp chives (, finely sliced (optional) – sub parsley, green onions, or omit)"],"purpose":"For serving"}]', '[{"title":"Split breast","description":"Cut each breast in half horizontally to form 4 thin steaks in total.","images":[],"step":1},{"title":"Dust with flour","description":"Sprinkle each side with salt and pepper, then sprinkle with flour and use your fingers to spread it all over the surface.","images":[],"step":2},{"title":"Cook chicken","description":"Melt 15g butter in a large non-stick frying pan over medium high heat. Add chicken and cook each side for 2 1/2 minutes until golden brown and just cooked through. Remove from pan, cover and keep warm.","images":[],"step":3},{"title":"Cook mushrooms","description":"In the same frying pan, add remaining butter and increase heat to high. Add mushrooms and cook for 4 minutes, until starting to turn golden brown on the edges.","duration":4,"images":[],"step":4},{"title":"Add garlic later","description":"Then add garlic and a pinch of salt and pepper, and continue cooking for another minute until both garlic and mushrooms are golden.","images":[],"step":5},{"title":"Deglaze skillet: Add white wine","description":"it will bubble and be steamy! Cook for 30 seconds, scraping the bottom of the pan, until wine is mostly evaporated and the alcohol smell is gone.","duration":0.5,"images":[],"step":6},{"title":"Make creamy sauce","description":"Add chicken stock, cook vigorously for 1 minute so it mostly evaporates. Then add cream, lower heat to medium and simmer for 2 minutes until it reduces and thickens slightly.","duration":1,"images":[],"step":7},{"title":"Add parmesan","description":"Stir in parmesan, taste and add more salt and pepper if needed.","images":[],"step":8},{"title":"Finish chicken in sauce","description":"Return chicken to sauce for 30 seconds (to warm through slightly.) Garnish with chives and serve as-is in the pan, for people to help themselves (or transfer to serving platter, if you prefer). Alternatively, serve a portion of chicken onto each plate, spoon sauce over and garnish with more chives.","duration":0.5,"images":[],"step":9},{"title":"Sides: Ideal served with mashed potato or rice","description":"something to soak in that amazing sauce! See Note 5 for suggestions.","images":[],"step":10}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","main-dishes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dd094ddfce27', 'en', 'US', 'Chicken Parmigiana', 'Recipe video above. Known as Chicken Parmesan in the US, the three key things that makes this the best Parmi you''ll ever have in your life are: layers upon layers on seasoning, dry brining for the most juicy chicken ever, and extra crispy chicken. Because I''ll never understand why you''d go to the trouble of making crispy crumbed chicken if the whole thing goes soggy when smothered in tomato sauce!Bonus baked option in Note 10. So golden and crunchy it will blow your mind!', 'https://www.recipetineats.com/tachyon/2020/09/Chicken-Parmigiana_7.jpg', 20, 40, 60, 6, '[{"id": "ing_chicken_breast", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_italian_mixed_herbs", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 0.281, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 37.5, "unit": "pack of 1kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 10.0, "unit": "bunch"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.6, "unit": "pack of 125g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.5, "unit": "L"}}]', '[{"ingredients":["3 chicken breasts (300g/10z each) (, halved horizontally to form 6 pieces (Note 2))","1 tsp salt (, cooking / kosher (or 3/4 tsp table salt, Note 3))","1/2 tsp black pepper","1/2 tsp Italian mixed herbs (Note 4)"],"purpose":"Brined Chicken Marinade (Note 1):"},{"ingredients":["1/3 cup flour (, plain/all purpose)"],"purpose":"Flour dusting:"},{"ingredients":["2 eggs","1 garlic clove (, minced using garlic press)","1/4 tsp each salt and pepper","1/4 tsp Italian mixed herbs (Note 4)"],"purpose":"Egg Dredge:"},{"ingredients":["1 1/2 cups panko breadcrumbs (sub normal, Note 5)","1/2 cup parmesan (, finely grated (store bought sand-like is best) (Note 6))","1/2 tsp salt","1/4 tsp black pepper"],"purpose":"Parmigiana Bread Crumbing:"},{"ingredients":["2 cups olive oil (or vegetable or canola)"],"purpose":"Frying:"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, finely minced)","1/4 cup onion or eschallots (, very finely chopped (Note 7))","1/4 tsp red pepper flakes ((chilli flakes), optional)","1/4 tsp Italian mixed herbs (Note 4)","1/4 cup white wine (, anything (optional, Note 10))","400g / 14 oz tomato passata (aka tomato puree) (Note 8)","1/2 cup chicken stock/broth (or water)","1/4 tsp each salt and pepper"],"purpose":"Parmigiana Pasta Sauce:"},{"ingredients":["10 basil leaves (, roughly chopped (sub pinch of dried - or omit))","2 cups mozzarella cheese (, shredded (or enough slices to cover))","3/4 cup parmesan (, finely grated (best to grate your own, Note 6))","1 tbsp extra virgin olive oil"],"purpose":"Layering:"},{"ingredients":["5 basil leaves (, roughly chopped)"],"purpose":"Garnish (optional)"}]', '[{"description":"Dry Brine Chicken:","images":[],"step":1},{"description":"Sprinkle both sides of chicken with salt, pepper and Italian herbs. Refrigerate for 30 minutes.","duration":30,"images":[],"step":2},{"description":"Parmigiana Tomato Sauce:","images":[],"step":3},{"description":"Heat oil in a saucepan over medium heat. Add garlic and onion, cook for 3 minutes until onion is translucent.","duration":3,"images":[],"step":4},{"description":"Add red pepper flakes and herbs, stir for 15 seconds. Add wine, turn up heat and let it simmer rapidly until mostly evaporated and winey smell is gone.","duration":0.25,"images":[],"step":5},{"description":"Add tomato, chicken stock, salt and pepper. Cover, then simmer 10 minutes on low until thickened. Cover and keep warm.","images":[],"step":6},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":7},{"title":"Crumbing set up","description":"Spread flour out in a shallow bowl. Whisk Egg Dredge in a separate shallow bowl. Mix Crumbing ingredients in a third shallow bowl or pan.","images":[],"step":8},{"title":"Dredge & crumb","description":"Press both sides of chicken into flour, then shake off excess. Coat in egg, letting excess drip off, then place in Crumbing, pressing to adhere.","images":[],"step":9},{"description":"Transfer to plate and repeat with remaining chicken.","images":[],"step":10},{"description":"Frying (Note 10 for baked option):","images":[],"step":11},{"description":"Line a tray with paper towels and place rack on tray.","images":[],"step":12},{"title":"Heat 1.5","description":"2cm / 2/3\" oil in a skillet over medium high heat to 180°C/350°F (Note 9).","images":[],"step":13},{"description":"Carefully place 2 or 3 pieces of chicken in. Cook 2 minutes until underside is golden, then carefully turn and cook the other side for 1 1/2 minutes.","images":[],"step":14},{"description":"Transfer to rack, then repeat with remaining chicken. (Note 12 - oil clean and reuse)","images":[],"step":15},{"description":"Assembling & baking:","images":[],"step":16},{"description":"Place chicken on a tray. Spoon 1/3 cup sauce over the chicken - cover around 80% of the chicken, leave the ends crispy.","images":[],"step":17},{"description":"Sprinkle sauce with basil, then mozzarella cheese (pile it on in mounds to use it all up), then sprinkle with parmesan. Drizzle oil over parmesan.","images":[],"step":18},{"description":"Bake 15 minutes until cheese is melted and there''s a few brown spots - no longer, otherwise chicken will overcook.","images":[],"step":19},{"description":"Remove from oven, sprinkle with extra basil if desired. Serve immediately (with leftover Tomato Sauce, if you''d like!)","images":[],"step":20}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","deep-fried-recipes","iconic-dishes","main-dishes","mains","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8a2b5a3fc447', 'en', 'US', 'Gravy Baked Chicken (thighs & drumsticks) - 5 min prep!', 'Recipe video above. Crispy baked chicken thighs and drumsticks that magically makes its own gravy - all in one pan! Terrific last minute chicken dinner that takes minutes to prepare and is zero maintenance to cook. The flavour in the gravy is phenomenal because it''s flavoured with the chicken juices!', 'https://www.recipetineats.com/tachyon/2020/07/Gravy-Baked-Chicken.jpg', 5, 50, 55, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.25, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.375, "unit": "L"}}]', '[{"ingredients":["1.25 kg/ 3 lb bone in, skin on chicken thighs and/or drumsticks (all of one, or mix, Note 1)","2 tsp olive oil (or other oil)"]},{"ingredients":["1 tsp paprika powder","1 tsp dried thyme","1 tsp onion powder (or garlic powder)","1 tsp salt","1/2 tsp black pepper"],"purpose":"Chicken seasoning:"},{"ingredients":["4 tbsp flour (, plain/all purpose (Note 2 for GF))","1 1/2 cups beef stock/broth (yes, beef, not chicken! Note 3)","1/2 tsp black pepper"],"purpose":"Gravy:"}]', '[{"description":"Preheat oven to 200°C/390°F (180°C fan).","images":[],"step":1},{"title":"Seasoning","description":"mix in a small bowl.","images":[],"step":2},{"title":"Season chicken","description":"Place chicken in a 23 x 33cm / 9 x 13\" baking pan. Drizzle with oil then rub all over Sprinkle & rub in the Seasoning, using most on the skin side.","images":[],"step":3},{"description":"Arrange chicken skin side up in the pan.","images":[],"step":4},{"title":"Gravy mixture","description":"Whisk flour with about 1/2 cup of stock until lump free, then whisk in remaining stock and pepper (forgot in video!). Pour into the pan around the chicken.","images":[],"step":5},{"description":"Bake uncovered for 50 minutes, or until chicken is crispy and golden.","duration":50,"images":[],"step":6},{"title":"Whisk gravy","description":"Remove chicken onto a plate, then give the gravy a good whisk to make it smooth. Adjust Gravy thickness if required - Note 4. Taste and add salt and pepper, if needed.","images":[],"step":7},{"title":"Serve","description":"Pour gravy into a jug. Serve alongside chicken!","images":[],"step":8}]', '["gluten"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-drumstick-recipes","chicken-recipes","emergency-recipes","main-dishes","one-pot-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_39f510179260', 'en', 'US', 'Chicken Salad - quick, easy, BIG!', 'Recipe video above. Here''s a speedy main course size salad that''s filled with all my favourite vegetables. I like this because it''s filled, colourful, interesting enough to serve to friends, but quick enough for a fast lunch, filling enough for dinner.', 'https://www.recipetineats.com/tachyon/2020/06/Quick-Chicken-Salad_6.jpg', 15, 0, 15, 4, '[{"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 36.0, "unit": "head"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_avocado", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.09, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_mixed_herbs", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["3 cups store bought roast chicken (, shredded (Note 1))","12 cups cos / romaine lettuce (2 medium, 1 giant) (, chopped into bite size pieces (or other leafy greens))","1 cup corn kernels (can, drained - about 2/3 can)","1/2 red onion (, finely sliced)","300g/ 10oz cherry or grape tomatoes (or 2 normal tomatoes chopped)","2 cucumbers (, halved lengthwise then sliced 1cm / 1/3\" (or 1 long English/telegraph cucumber))","2 avocados (, cut into bite size chunks (or 1 giant one))","150g/ 5oz bacon (, cooked until crisp then chopped (optional))"]},{"ingredients":["2 1/2 tbsp cider vinegar (Note 2)","6 tbsp extra virgin olive oil","1 garlic clove (, minced using garlic press (~1 tsp))","1 tsp Dijon Mustard (or any smooth, non spicy mustard, optional)","2 tsp dried mixed herbs (Note 3 for subs)","1 tsp sugar (, optional (Note 4))","3/4 tsp salt","1/2 tsp black pepper"],"purpose":"Dressing:"}]', '[{"title":"Dressing","description":"Place ingredients in a jar, shake, set aside for at least 10 minutes to let flavours meld.","images":[],"step":1},{"title":"Salad","description":"Place all ingredients except bacon in a big bowl. Drizzle over most of the Dressing, then toss well.","images":[],"step":2},{"description":"Transfer to serving bowl, drizzle with remaining Dressing. Sprinkle with bacon. Serve immediately!","images":[],"step":3}]', '["mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-recipes","salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ce4b1beecdc2', 'en', 'US', 'Oven Baked BBQ Chicken - with quick homemade barbecue sauce', 'Recipe video above. This is how I make BBQ Chicken in the oven when I''m craving sticky chicken but don''t want to fire up the BBQ! Made with a quick homemade BBQ sauce, the chicken is braised in the sauce which is loaded with extra flavour from the juices of the chicken. Fabulous sticky glaze, juicy inside!', 'https://www.recipetineats.com/tachyon/2016/10/Baked-BBQ-Chicken-with-Barbecue-Sauce_2.jpg', 10, 50, 60, 5, '[{"id": "ing_ketchup", "quantity": {"value": 0.3, "unit": "bottle of 500g"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.125, "unit": "bottle of 500ml"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 cup ketchup (or Australian/UK tomato sauce)","1/4 cup apple cider vinegar","2 tsp Worcestershire Sauce","4 tbsp brown sugar","2 tsp mustard powder","2 tsp onion powder","1/2 tsp salt","1/2 tsp fresh black pepper","1 cup water"],"purpose":"Sauce (Note 1)"},{"ingredients":["1.5 kg / 3 lb chicken thighs (bone in skin on), drumsticks or wings (Note 2)","Fresh parsley, chives or finely chopped green onions (, for garnish)"],"purpose":"Chicken"}]', '[{"description":"Preheat oven to 200°C/390°F.","images":[],"step":1},{"title":"Sauce","description":"Mix all Sauce ingredients in a ceramic/glass baking dish (Note 3), then mix in water.","images":[],"step":2},{"description":"Add chicken and turn to coat. Place chicken skin side down.","images":[],"step":3},{"description":"Bake for 20 minutes. Remove from oven, turn chicken, spoon over Sauce.","duration":20,"images":[],"step":4},{"description":"Bake for a further 30 minutes, then remove and spoon over Sauce.","images":[],"step":5},{"title":"Skim off fat (optional)","description":"Tilt pan and spoon or drain off excess fat.","images":[],"step":6},{"title":"Broil/grill","description":"Change to broiler/grill on high. Spoon sauce over chicken generously, then place under grill / broiler for 2 to 3 minutes to caramelise the chicken and the sauce to thicken more. Do not walk away - this can happen quickly!","duration":2.5,"images":[],"step":7},{"description":"Serve chicken, garnished with parsley or green onions, if using. Pictured in post with Mashed Potato and Green Bean Salad (minus feta).","images":[],"step":8},{"description":"Classic Side Dishes for BBQ Chicken","images":[],"step":9},{"description":"Cornbread, Coleslaw, Potato Salad (or try this no mayo Lemon Potato Salad), Southern Baked Beans, big leafy salad with classic Vinaigrette, steamed corn with butter, bread rolls, creamy mashed potato (or Creamy Cauliflower Mash for low carb emergency!), or Potato & Gravy.","images":[],"step":10}]', '["mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-recipes","dinner-tonight","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9df5f1a1dfd1', 'en', 'US', 'Oven Baked Chicken and Rice', 'Recipe VIDEO above. Made entirely in the oven (no stove!), the rice in this recipe is outrageously delicious! It''s buttery and garlicky, tender but not mushy. The secret tip is to briefly bake onion with garlic and butter before adding the rice, liquids and chicken - it adds a great flavour base!', 'https://www.recipetineats.com/tachyon/2018/06/Oven-Baked-Chicken-and-Rice_0.jpg', 10, 70, 80, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_white_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["5 bone in chicken thigh fillets, peel skin OFF (, (Note 1))","1 onion (, chopped (brown, white or yellow))","2 cloves garlic (large) (, minced)","2 tbsp (30g) butter (or olive oil)","1 1/2 cups (270g) uncooked white rice (Note 3)","1 1/2 cups (375 ml) chicken broth/stock (, hot (I microwave))","1 1/4 cups (315 ml) water (, hot (tap is fine))"]},{"ingredients":["1 tsp paprika powder","1 tsp dried thyme","1/2 tsp garlic powder","1/2 tsp onion powder","3/4 tsp salt","Black pepper"],"purpose":"Chicken Rub (Note 2):"},{"ingredients":["Oil spray","Fresh thyme leaves or finely chopped parsley"],"purpose":"Optional garnish:"}]', '[{"description":"Preheat oven to 180°C/350°F.","images":[],"step":1},{"description":"Scatter onion and garlic in a baking dish (about 10 x 15\" / 25 x 35 cm), then place butter in the centre. Bake for 15 minutes (check at 12 minutes, mix if some bits are browning too much).","duration":15,"images":[],"step":2},{"description":"Meanwhile, mix together Chicken Rub. Sprinkle on both sides of the chicken.","images":[],"step":3},{"description":"Remove baking dish from the oven. Add rice then mix.","images":[],"step":4},{"description":"Place chicken on rice. Then pour chicken broth and water around the chicken.","images":[],"step":5},{"description":"Cover with foil, then bake for 30 minutes. Remove foil, spray chicken with oil (optional, gives chicken nicer finish), then bake for a further 20 minutes until liquid is absorbed.","duration":30,"images":[],"step":6},{"description":"Stand for 5 minutes, then remove chicken and fluff up rice. Garnish with parsley or thyme if desired, serve and enjoy!","duration":5,"images":[],"step":7},{"description":"Dish is flavoured enough to serve without sauce, but if you want to take it over the top, make this quick Gravy in 4 minutes flat (pictured in video).","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dietary","emergency-recipes","gluten-free-recipes","mains","one-pot-recipes","quick-and-easy","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6b970abcff5b', 'en', 'US', 'Chicken Enchiladas', 'Recipe video above. If you like your enchiladas plump, juicy, saucy and full of flavour, this is the recipe for you! Homemade from scratch, the foundation of this recipe is a double duty Enchilada Spice mix.', 'https://www.recipetineats.com/tachyon/2020/03/Chicken-Enchiladas_4.jpg', 20, 45, 65, 8, '[{"id": "ing_tortillas", "quantity": {"value": 8.0, "unit": "pack of 8"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 8.0, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_refried_beans", "quantity": {"value": 400.0, "unit": "pack"}}, {"id": "ing_corn", "quantity": {"value": 8.0, "unit": "can of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["8 tortillas (, flour or corn (about 20cm/8\" wide, Note 1))"]},{"ingredients":["1 tsp EACH onion powder, garlic powder, salt","1 tbsp EACH dried cumin powder, paprika, dried oregano","1/4 tsp black pepper","3/4 tsp cayenne pepper (optional, adjust to taste)"],"purpose":"Enchilada Seasoning:"},{"ingredients":["2 tbsp olive oil","3 tbsp flour (, plain/all purpose)","2 cups (500ml) chicken stock/broth (, low sodium)","1.5 cups (375ml) tomato passata or US puree (Note 4 sub)"],"purpose":"Enchilada Sauce"},{"ingredients":["600g / 1.2lb chicken breast (, sliced in half horizontally (or boneless thigh) (Note 2))","2 tbsp olive oil (, separated)","1/2 onion (, chopped)","2 garlic cloves (, finely minced)","1 red capsicum/bell pepper (, diced)","400g / 14oz refried beans (Note 3)","400g/14oz canned corn (, drained (sub frozen 1 3/4 cups))","1/4 cup (65ml) water","1 cup (100g) cheese (shredded (Mexican cheese blend, Monterey Jack, cheddar))"],"purpose":"Chicken Filling:"},{"ingredients":["1.5 cups (150g) cheese (, shredded)","2 tbsp coriander/cilantro (, roughly chopped)"],"purpose":"Topping"}]', '[{"title":"Enchilada Seasoning","description":"Mix Enchilada Seasoning Spices. To be used for Filling and Sauce.","images":[],"step":1},{"description":"Enchilada Sauce","images":[],"step":2},{"title":"Make roux","description":"Heat oil in saucepan over medium heat. Add flour and stir 20 seconds.","images":[],"step":3},{"title":"Add other ingredients","description":"Add 2 tbsp Enchilada Seasoning, broth and tomato. Stir to combine.","images":[],"step":4},{"title":"Simmer to thicken","description":"Increase heat slightly to medium high. Cook for 4 minutes, whisking regularly, until the sauce thickens to the consistency of thick syrup (see video). Remove from stove.","duration":4,"images":[],"step":5},{"description":"Chicken Filling","images":[],"step":6},{"title":"Coat chicken","description":"Drizzle 1 tbsp oil over chicken, mix to coat. Sprinkle with Seasoning, toss to coat.","images":[],"step":7},{"title":"Cook chicken","description":"Heat remaining 1 tbsp oil in a large skillet over high heat. Add chicken, cook 2 minutes. Turn and cook 1.5 minutes. Remove, rest 2 minutes then chop.","images":[],"step":8},{"title":"Saute onion","description":"In the same skillet, add onion and garlic, cook 1 minute. Add capsicum, cook 2 minutes until onion is translucent.","images":[],"step":9},{"title":"Add everything else","description":"Add refried beans, diced chicken, corn and water. Stir and cook for 2 minutes until reduces slightly. Should be thick and juicy, not watery.","duration":2,"images":[],"step":10},{"description":"Assemble and bake:","images":[],"step":11},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":12},{"title":"Roll","description":"Lay tortilla on work surface. Spread 2/3 cup Filling on lower third, sprinkle with cheese then roll up, finishing with the seam side down (to hold it closed). Repeat to make 8.","images":[],"step":13},{"description":"Smear a scoop of Enchilada Sauce across base of 22 x 33cm /9 x 13\" pan. Place Enchiladas in, pour over remaining Sauce, sprinkle with cheese.","images":[],"step":14},{"title":"Bake 20","description":"25 minutes or until cheese is melted and golden. Serve immediately, sprinkled with coriander!","images":[],"step":15}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["chicken-recipes","enchiladas","main-dishes","mexican-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b186d4aa6e30', 'en', 'US', 'Mediterranean Chicken Dinner', 'Recipe video above. Infused with classic Mediterranean flavours of garlic, lemon, oregano and paprika, this is a terrific quick dinner idea. The sauce is the star of this and marinating is optional! I made this with drumsticks but you can make this with bone-in chicken thigh fillets too.', 'https://www.recipetineats.com/tachyon/2015/11/Lemon-Garlic-Chicken-Potato-Bake_7-copy.jpg', 10, 55, 55, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 10.0, "unit": "pack of 3 heads"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 5.0, "unit": "bag of 2kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}]', '[{"ingredients":["1kg / 2lb bone in, skin on chicken thighs and drumsticks (Note 1)","1/2 cup (125 ml) lemon juice","6 cloves garlic (, minced)","2 tsp Dijon mustard (Optional - Note 2)","2 tbsp honey or 1 tbsp sugar (or maple or other sweetener)","1 tbsp dried oregano","1.5 tsp paprika","1 tbsp olive oil","1/2 tsp EACH salt and pepper"],"purpose":"Marinade / Sauce"},{"ingredients":["5 smallish potatoes (7.5cm/3\" wide) (, quartered (Note 3))","2 red onions (, quartered)","1 cup (250ml) chicken broth/stock (, low sodium)","250g/8oz cherry tomatoes (whole)","1/2 tsp EACH salt and pepper","1 tbsp Olive oil (or oil spray)","Fresh oregano (, for garnish (optional))"],"purpose":"Bake"}]', '[{"description":"Mix Marinade ingredients in a bowl, then add chicken and toss to coat. If time permits, marinate for 24 hours, otherwise proceed to next step.","images":[],"step":1},{"description":"Preheat oven to 180C/350F.","images":[],"step":2},{"description":"Place potatoes and onion in baking pan, top with chicken. Pour over the chicken stock then marinade from the bowl.","images":[],"step":3},{"description":"Bake for 20 minutes, then remove from oven.","duration":20,"images":[],"step":4},{"description":"Scatter over cherry tomatoes, drizzle everything with 1 tbsp olive oil, sprinkle with salt and pepper. Bake for a further 30 - 35 minutes until chicken is golden and potatoes are cooked.","images":[],"step":5},{"description":"Remove from oven, garnish with fresh oregano if using and serve!","images":[],"step":6}]', '["mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mediterranean","Western"],"categories":["chicken-drumstick-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","mediterranean-recipes","most-popular","one-pot-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_23566a2a247a', 'en', 'US', 'Fried Chicken - ultra craggy crispy crust!', 'Recipe video above. This is a fried chicken recipe that''s made using a technique that yields an incredible super crunchy, really craggy crust with loads of nubbly bits that get extra crunchy! Seasoned with a KFC copycat 11 Secret Herbs and Spices - but better than KFC, there''s no trace of soggy bits at all! Flesh is juicy all the way through thanks to a classic Southern buttermilk marinade (read in post why there''s no spices in the marinade!).Serve with French fries and potato with gravy for an epic homemade KFC experience at home.', 'https://www.recipetineats.com/tachyon/2020/01/Fried-Chicken_2.jpg', 15, 30, 45, 10, '[{"id": "ing_bone_in_skin_on_small_thighs_drumsticks_whole_wings_breast", "quantity": {"value": 1.8, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.338, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.281, "unit": "pack of 400g"}}, {"id": "ing_celery", "quantity": {"value": 0.075, "unit": "head"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.45, "unit": "jar of 50g"}}, {"id": "ing_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_ginger", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 1.5, "unit": "L"}}]', '[{"ingredients":["1.8 kg/ 3.6lb bone in, skin on small thighs (< 200g/7oz), drumsticks, whole wings, breast (< 200g/7oz) (Note 1)"]},{"ingredients":["1 cup buttermilk (Note 2 for sub)","1 tbsp salt","1 egg"],"purpose":"Buttermilk marinade:"},{"ingredients":["2 1/4 cups flour (, plain / all purpose)","3/4 cup corn flour / cornstarch"],"purpose":"Fried Chicken Breading (Note 9):"},{"ingredients":["3 tsp salt","3/4 tsp celery salt","1.5 tbsp black pepper (Note 2)","1.5 tsp sweet paprika (ie. not hot or smoked)","1/2 tsp cayenne pepper (, optional)","1.5 tsp onion powder","3 tsp garlic powder","1 tsp mustard powder","3/4 tsp ginger powder","1.5 tsp dried thyme","1.5 tsp dried oregano"],"purpose":"KFC 11 Secret Herbs and Spices (Note 9):"},{"ingredients":["1.5 - 2 litres / quarts vegetable oil (or canola or peanut, Note 8 for re-use)"],"purpose":"To fry:"}]', '[{"description":"Buttermilk Marinade Chicken:","images":[],"step":1},{"description":"Mix Marinade in a bowl until salt dissolves.","images":[],"step":2},{"description":"Pour over chicken in ziplock bag, massage to coat chicken. Press out excess air, seal, refrigerate 12 to 24 hours, turning once or twice.","images":[],"step":3},{"description":"Pour chicken and marinade into large bowl.","images":[],"step":4},{"description":"Breading mixture:","images":[],"step":5},{"description":"Whisk together Breading and all KFC Secret Herbs & Spices.","images":[],"step":6},{"description":"Drizzle 4.5 tablespoons of Marinade into flour mixture. Use fingers to rub in so you get lots of pea sized lumpy bits all throughout (this creates extra super crunchy craggy bits).","images":[],"step":7},{"description":"Spread out in a shallow dish or pan (easier to work with).","images":[],"step":8},{"description":"Prepare to cook (work in specified order of steps):","images":[],"step":9},{"title":"Preheat oven to 80°C/175°F and place rack on tray","description":"to keep chicken warm. (Note 3)","images":[],"step":10},{"description":"Add oil to a wide, heavy based pot to a depth of 6 cm / 2.5 \" (my 26cm/10.5\" cast iron pot = 1.75L/quarts oil, Note 4)","images":[],"step":11},{"description":"Heat oil over medium to medium high heat to 180°C/350°F - maintain temp as best you can (Note 5).","images":[],"step":12},{"title":"Cooking order","description":"Start with thighs and drumsticks, wings next and cook breast last. (Note 6).","images":[],"step":13},{"description":"Squidge a piece of chicken in remaining marinade, place in flour.","images":[],"step":14},{"description":"Coat well, pressing very firmly to adhere. Transfer to plate.","images":[],"step":15},{"title":"Coat 2 or 3 more pieces","description":"just for one cooking batch, covering oil surface in single layer. (Note 7)","images":[],"step":16},{"title":"Carefully place chicken in oil","description":"it will bubble energetically but it will not spit.","images":[],"step":17},{"description":"Once chicken is in, oil temperature should drop to 150°C/300°C - adjust heat to target this.","images":[],"step":18},{"title":"DO NOT TOUCH chicken for 2 minutes","description":"to let the crust bond with the chicken skin. After this, you can move them around but oil should be deep enough that you do not need to flip (but you can if you want!).","duration":2,"images":[],"step":19},{"title":"Thighs and drumsticks","description":"cook for 8 minutes (wings for 5 minutes), or until deep golden brown and internal temperature at thickest part is 75°C / 167°F.","duration":8,"images":[],"step":20},{"title":"Breast","description":"fry for 6 minutes or until internal temperature at thickest part is 65°C / 150°F (time depends on size).","duration":6,"images":[],"step":21},{"description":"Place onto rack and keep warm in oven. Repeat with remaining chicken, coating each batch just prior to cooking.","images":[],"step":22},{"description":"Serve immediately!","images":[],"step":23},{"title":"Classic sides","description":"Coleslaw, KFC copycat potato and gravy, steamed or grilled corn, cornbread or soft rolls, fries, potato salad, Southern Baked Beans!","images":[],"step":24}]', '["egg","gluten","mustard","peanuts"]', '["high_protein","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Southern","Western"],"categories":["chicken-drumstick-recipes","chicken-recipes","deep-fried-recipes","iconic-dishes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_96ca396a836b', 'en', 'US', 'Poached Chicken - Foolproof, perfect, AMAZINGLY juicy breast', 'Recipe video above. Forget every other method you''ve used. This recipe GUARANTEES the juiciest chicken breast you''ve ever made in your life. No special equipment, no fancy gadgets. It''s dead easy and foolproof. Use for anything that calls for cooked chicken. Slice it, dice it, shred it, pile onto sandwhiches. HIGH ALTITUDE locations - please see note 4', 'https://www.recipetineats.com/tachyon/2020/01/Poached-Chicken_8.jpg', 10, 25, 35, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}]', '[{"ingredients":["2 chicken breasts (, boneless skinless, 250g/8.5 oz each (Note 1))"]},{"ingredients":["1 lemon (, quartered)","1 bay leaf (, dried or fresh)","2 garlic cloves (, minced)"],"purpose":"Optional flavourings (Note 2)"}]', '[{"description":"Take chicken out of the fridge 30 minutes before cooking.","images":[],"step":1},{"description":"Fill a saucepan with water so the chicken breast will be well submerged with at least 2\" / 5cm of water above it in a single layer (can be snug but do not stack).","images":[],"step":2},{"description":"Add Flavourings, if using (squeeze in lemon juice, add used lemon).","images":[],"step":3},{"description":"Bring water to boil.","images":[],"step":4},{"description":"Place chicken breast in water, place lid on, bring back up to the boil. IMMEDIATELY remove saucepan from stove and set aside for 20 minutes (it''s fine up to 45 min to 1 hr, won''t overcook).","duration":20,"images":[],"step":5},{"description":"Remove chicken from water. Slice and be amazed how perfectly juicy and tender the breast is!! Or chop/shred and use as desired.","images":[],"step":6},{"description":"If reserving for later use, cover loosely to cool then refrigerate whole - see Note 6.","images":[],"step":7}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","good-to-know","low-calorie-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_49cb8ba13215', 'en', 'US', 'Crispy Herb Baked Chicken with Gravy', 'Recipe video above. This is a fantastic, easy way to make "roast chicken" for loads of people without the fuss of man handling a whole chicken! Quick to prepare, no advance marinating or brining, the idea here is high temp cooking which really seals in the juices, creating crispy skin and meat that''s so juicy, it''s ideal for reheating to serve (which is what we did for a 40 guest Christmas lunch last weekend). Bonus mess-free way of making gravy with outrageously delicious flavour.', 'https://www.recipetineats.com/tachyon/2019/12/Herb-Baked-Chicken-and-Gravy_4-HERO.jpg', 5, 35, 40, 6, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 1.8, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 1.8, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_sage", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_marjoram", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.015, "unit": "bottle of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["1 tbsp vegetable oil (or canola or peanut oil, NOT butter or olive oil, Note 1)"]},{"ingredients":["1.8 kg / 3.6 lb whole chicken, butterflied / spatchcocked","1.8 kg / 3.6 lb large chicken thighs with bone in, skin on AND drumsticks (mix)"],"purpose":"Choose ONE chicken (Note 2):"},{"ingredients":["1 tsp dried oregano","1 tsp dried rosemary","1 tsp dried thyme","1 tsp dried sage (or 1/2 tsp ground sage)","3/4 tsp dried marjoram","1 tsp salt (coarse / kosher salt, OR 1 3/4 tsp sea salt flakes)","1/2 tsp black pepper"],"purpose":"Herb rub (Note 3):"},{"ingredients":["3 tbsp flour","1 1/2 cups (375ml) chicken stock/broth (, low sodium)","3/4 tsp dark soy sauce or gravy browner liquid","Salt and pepper to taste"],"purpose":"Gravy"}]', '[{"description":"Fridge dry skin (optional, for extra crispy skin):","images":[],"step":1},{"description":"Pat chicken skin dry with paper towels. Leave chicken in fridge overnight, uncovered, to dry skin out.","images":[],"step":2},{"description":"Cooking:","images":[],"step":3},{"description":"Preheat oven to 240°C/ 465°F (220°C fan).","images":[],"step":4},{"description":"Line tray with foil then baking / parchment paper, place rack on tray (Note 4)","images":[],"step":5},{"description":"Mix Rub in a bowl.","images":[],"step":6},{"description":"Pat chicken skin dry with paper towel.","images":[],"step":7},{"description":"Drizzle with oil and rub all over, then sprinkle with Rub. Use hands to rub herbs all over the chicken, getting right into all the cracks and crevices. Place on rack.","images":[],"step":8},{"title":"Thigh + drumsticks","description":"Arrange thigh pieces skin side up, and for drumsticks the side with the most skin up.","images":[],"step":9},{"title":"Butterflied/spatchcocked","description":"Arrange breast side up with tail end of chicken pointed back towards back of oven, neck end closest to door.","images":[],"step":10},{"title":"Thighs + drumsticks","description":"roast for 35 minutes or until internal temperature is 75°C/165°F, or juices run clear when pierced in the middle.","duration":35,"images":[],"step":11},{"title":"Butterflied/spatchcocked","description":"roast for 45 minutes, or until internal temperature is: 66°C / 151°F for the breast AND 75°C/165°F when inserted into the joint between the leg and the thigh.","duration":45,"images":[],"step":12},{"title":"Extra browning","description":"if skin isn''t browned/crispy enough, flick grill/broiler on high for 1 - 3 minutes. CAREFUL - browns super quick!","duration":2,"images":[],"step":13},{"description":"Tent VERY loosely with foil (to preserve crispy skin) for 5 minutes.","duration":5,"images":[],"step":14},{"description":"Scrape every bit of juice, fat and all the brown stuff off the tray into a saucepan.","images":[],"step":15},{"description":"Turn stove onto medium. Once juices are bubbling, add flour and whisk to combine.","images":[],"step":16},{"description":"Slowly pour in broth, whisking as you go.","images":[],"step":17},{"description":"Add soy sauce or gravy browner and pepper.","images":[],"step":18},{"title":"Continue stirring for 3 to 5 minutes","description":"as it becomes steamy, gravy will thicken.","duration":4,"images":[],"step":19},{"description":"Once it becomes a syrupy consistency (see video), remove from stove. Adjust salt to taste right at end, then pour into jug.","images":[],"step":20},{"description":"Carve up the chicken as you would a roast chicken. Cut breast into 3 or 4 pieces. Cut thighs in half along the bone.","images":[],"step":21},{"description":"Pile it all up onto a plate, garnish with parsley or other fresh herbs. Serve with gravy!","images":[],"step":22}]', '["gluten","milk","peanuts","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-drumstick-recipes","chicken-recipes","roasts","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d2a4fa114cd7', 'en', 'US', 'Chicken Brine', 'Recipe video above. BRINING is the secret to the most succulent, tender roast chicken you will EVER have in your life! Adapted from a recipe by Thomas Keller, one of the great masters of the culinary world. The flesh is seasoned all the way through with a hint of the brine flavourings (herbs, lemon, garlic).', 'https://www.recipetineats.com/tachyon/2014/05/Chicken-Brine_3.jpg', 15, 60, 1515, 5, '[{"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 4.0, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.4, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.28, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_honey", "quantity": {"value": 0.125, "unit": "jar of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_chicken", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.3, "unit": "jar of 50g"}}]', '[{"ingredients":["2 litres / 2 quarts water (, cold tap water)","1/3 cup kosher or cooking salt, NOT table salt (Note 1)","2 lemons (, quartered)","10 sprigs parsley (, fresh )","7 sprigs thyme","2 sprigs rosemary","5 bay leaves, fresh (or 3 dried)","1/4 cup honey","6 garlic cloves, (smashed (Note 3))","1 tbsp black peppercorns"],"purpose":"Brine"},{"ingredients":["1.5 - 2 kg / 3-4lb chicken (, whole)","3 tbsp / 40g butter (, melted)","Salt and pepper to season"],"purpose":"Roast Chicken"}]', '[{"description":"Pour about 1/3 of the water into a large pot (large enough for the brine and submerged chicken) with remaining Brine ingredients. Bring to boil boil 1 minute, stir to dissolve salt.","images":[],"step":1},{"description":"Remove from heat, pour in remaining water. Cool completely before using (I cool about 30 min then refrigerate 1 1/2 hours). DO NOT put chicken in before full cool, this is a health hazard (Note 4).","images":[],"step":2},{"description":"Flip chicken upside down (so legs and breast are on underside. Submerge chicken in brine, cover and refrigerate for 12 - 24 hours (Note 5). Don''t worry if underside of chicken doesn''t stay under water - the the breast side is, that is what matters.","images":[],"step":3},{"description":"Roasting Brined Chicken:","images":[],"step":4},{"description":"Remove chicken from brine and pat dry to remove excess moisture.","images":[],"step":5},{"description":"Tie legs with string (if desired), tuck wings under. Drizzle/brush with most of the butter all over, including underside (butter will firm up on contact).","images":[],"step":6},{"description":"Sprinkle with pepper and the TINIEST pinch of salt, place chicken on a rack in a heavy based roasting tray. Set aside for 20 minutes.","duration":20,"images":[],"step":7},{"description":"Preheat fan forced oven to 220°C/430°F.","images":[],"step":8},{"description":"Turn down the oven to 180°C/350°F, then roast chicken for 50 minutes to 1 hour (Note 7) or until the internal temperature at the joint between the leg and thigh is 75°C/165°F, or until juices run clear.","duration":50,"images":[],"step":9},{"description":"Check at 45 minutes, rotate the pan if not browning evenly, and brush top with remaining melted butter.","images":[],"step":10},{"description":"Remove chicken from the roasting tray, cover loosely with foil and rest for 10 to 15 minutes.","duration":12.5,"images":[],"step":11},{"description":"Chicken is so juicy, it needs little more than a tiny drizzle of the juices in the pan (go easy, it''s salty). Otherwise, make a gravy while the chicken is resting - see Note 8.","images":[],"step":12}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","good-to-know","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_88d0e49e9d93', 'en', 'US', 'Sicilian Chicken Spaghetti', 'Recipe video above. A quick tomato chicken spaghetti with olives, artichokes and a kick of spice if you so choose! Very little prep - nothing to chop except garlic!', 'https://www.recipetineats.com/tachyon/2019/09/Sicilian-Chicken-Pasta_9.jpg', 5, 15, 20, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.64, "unit": "pack of 500g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_black_olives", "quantity": {"value": 150.0, "unit": "bottle"}}, {"id": "ing_artichokes_drained", "quantity": {"value": 0.17, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.009, "unit": "jar of 50g"}}, {"id": "ing_basil", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["320g / 11oz spaghetti (or other long pasta)","2 chicken breasts (, each halved horizontally to form 2 thin steaks)","2 tbsp olive oil","Salt and pepper","3 garlic cloves (, minced)","1/2 cup (125 ml) white wine (Note 1)","800g / 28oz can crushed tomato","1/2 cup (125 ml) water (about 1/3 empty tomato can)","1 cup (100g) sliced black olives (Note 2)","170g / 6 oz artichokes (marinated in can or jar), drained (Note 2)","1/2 - 1 tsp red pepper flakes (spiciness - adjust to taste!)","1/2 tsp salt and pepper (, each)","1 cup basil leaves (, optional (or sub baby spinach))"]},{"ingredients":["Parmesan cheese (, freshly grated)"],"purpose":"Serving"}]', '[{"description":"Cook pasta in a large pot of salted boiling water per packet directions, MINUS 1 minute. Drain. (Do this while sauce is simmering)","images":[],"step":1},{"title":"Cook chicken","description":"Sprinkle both sides of chicken with salt and pepper. Heat 1 tbsp oil in a large skillet over high heat. Sear chicken 1 1/2 minutes on each side until golden, then remove from skillet. Shred while sauce is simmering.","images":[],"step":2},{"description":"Add remaining 1 tbsp oil. Add garlic and sauté for 15 seconds.","duration":0.25,"images":[],"step":3},{"description":"Add wine and let it simmer rapidly for 1 minute, stirring to dissolve brown bits on bottom of skillet into the wine, until mostly evaporated.","duration":1,"images":[],"step":4},{"description":"Add tomato, water, olives, artichoke, red pepper flakes, salt and pepper. Stir, simmer on medium for 5 minutes.","duration":5,"images":[],"step":5},{"description":"Stir shredded chicken into sauce.","images":[],"step":6},{"description":"Add pasta into sauce, still on the stove. Toss well for 1 minute or until sauce reduces more and is clinging to pasta strands, rather than pooled in the skillet.","duration":1,"images":[],"step":7},{"description":"Just before serving, toss through fresh basil.","images":[],"step":8},{"description":"Serve immediately with parmesan!","images":[],"step":9}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["American-Italian","Italian"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","italian-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c91eff732ca4', 'en', 'US', 'White Chicken Lasagna', 'Recipe video above. Tender shredded chicken and golden, garlicky mushrooms smothered in a cheesy Alfredo sauce, layered up with lasagna sheets. It''s a WHITE chicken lasagna - and it''s amazing!', 'https://www.recipetineats.com/tachyon/2019/08/White-Chicken-Lasagna_2.jpg', 15, 75, 90, 8, '[{"id": "ing_chicken_breast", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_vegeta", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_mushroom", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_sheets_lasagna", "quantity": {"value": 375.0, "unit": "pack"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.6, "unit": "pack of 125g"}}]', '[{"ingredients":["1 kg/ 2lb chicken breast ( or boneless skinless thigh)","4 cups (1L) milk (, any fat %)","2 cups (500ml) chicken broth (/ stock)","2 bay leaves (, dried)","3 sprigs thyme (or 1 tsp dried thyme)","2 tsp Vegeta (or chicken stock powder/granulated bouillon, Note 1)","1/2 tsp black pepper"],"purpose":"Chicken & semi-homemade stock:"},{"ingredients":["2 tbsp (30g) butter (, separated)","2 tbsp olive oil (, separated)","500g / 1lb mushrooms (, quartered)","2 garlic cloves (, minced)","1/2 tsp salt and pepper (, each)"],"purpose":"Mushrooms:"},{"ingredients":["50g / 4tbsp butter","2 garlic cloves (, minced)","3/4 cup (110g) flour (, plain / all purpose)","2 cups (200g) cheddar cheese (, shredded (Note 2))"],"purpose":"White sauce:"},{"ingredients":["375g (13 oz) lasagna sheets (, fresh (or 250g/8oz dried) (Note 3))","2 cups (200g) mozzarella cheese (, shredded)"],"purpose":"Lasagna:"}]', '[{"description":"Place milk, broth and stock powder in a large saucepan. Bring to a very gentle simmer over medium heat, add chicken, pepper, bay leaves and thyme.","images":[],"step":1},{"description":"Place lid on, simmer gently on medium low for 15 minutes (do not boil, can make milk split).","duration":15,"images":[],"step":2},{"description":"Remove chicken and shred. Cover pot and set poaching liquid aside.","images":[],"step":3},{"description":"Heat half the oil and butter in a very large, deep skillet over high heat (or use large pot). Add half the mushrooms with half the garlic, salt and pepper.","images":[],"step":4},{"description":"Cook for 5 minutes, stirring leisurely, until golden. Transfer to bowl and repeat with remaining mushrooms.","duration":5,"images":[],"step":5},{"description":"Lower heat down to medium.","images":[],"step":6},{"description":"Melt butter in skillet, then add garlic. Stir until golden.","images":[],"step":7},{"description":"Add flour. Stir constantly for 1 minute.","duration":1,"images":[],"step":8},{"description":"Gradually pour in 2 cups of reserved poaching liquid while stirring constantly, it should turn into a thick paste.","images":[],"step":9},{"description":"Mix in another cup of liquid, then add remaining liquid and stir well to dissolve. Use whisk if necessary to make lump free.","images":[],"step":10},{"description":"Stir constantly for 1 to 2 minutes until it thickens - you should be able to draw a path across a spoon (see video).","duration":1.5,"images":[],"step":11},{"description":"Remove from heat, stir in cheese until melted. Taste and add more salt & peppers, if needed.","images":[],"step":12},{"description":"REMOVE 2 1/2 cups (625ml) of sauce (save for topping). Then stir in chicken and mushrooms into remaining sauce.","images":[],"step":13},{"description":"Assemble & Bake:","images":[],"step":14},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":15},{"description":"Smear some sauce on the base of a 23 x 33 cm / 9 x 13\" baking dish. Cover base with lasagna sheets.","images":[],"step":16},{"description":"Top with half chicken mixture, then lasagna sheets, remaining chicken mixture then more lasagna sheets.","images":[],"step":17},{"description":"Pour over reserved White Sauce, sprinkle with mozzarella. Cover loosely with foil or use upside down baking tray (ensure it''s not touching cheese).","images":[],"step":18},{"description":"Bake for 25 minutes. Remove foil, bake further 10 minutes until golden and bubbly.","duration":25,"images":[],"step":19},{"description":"Stand 10 minutes, garnish with parsley if desired then cut to serve!","images":[],"step":20}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","iconic-dishes","main-dishes","pasta-bakes","pasta-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0298973ad088', 'en', 'US', 'Chicken with Creamy Sun Dried Tomato Sauce', 'Recipe video above. Dinner on the table in 20 minutes! The sauce is ridiculously addictive - I''m tempted to double it!', 'https://www.recipetineats.com/tachyon/2015/07/Chicken-with-Creamy-Sun-Dried-Tomato-Sauce_2.jpg', 10, 10, 20, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_basil", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["750g / 1.5lb chicken thighs OR chicken breast (, skinless and boneless)","1/2 tsp salt","Black pepper","1/2 cup sun dried tomatoes (, strips, drained of oil (Note 1))","2 tbsp oil from sun dried tomatoes jar (Note 1)","2 garlic cloves (, minced)","1/2 cup (125 ml) white wine (sub chicken broth)","3/4 cup (185 ml) chicken broth/stock (, low sodium)","3/4 cup (185 ml) thickened / heavy cream","1/3 cup (30g) parmesan, very finely shredded (Note 2)","2 tsp Dijon mustard (Note 3)","1 cup basil leaves (, packed (optional))"]}]', '[{"title":"Breast","description":"Cut chicken in half horiztonally to form 2 thin steaks.","images":[],"step":1},{"description":"Sprinkle chicken with salt and pepper. Heat oil from sun dried tomat jar in a large skillet over high heat.","images":[],"step":2},{"description":"Add the chicken and cook until golden brown on both sides - 6 minutes total for thigh or 4 minutes for breast. Remove onto a plate, keep warm.","images":[],"step":3},{"description":"Add the garlic and cook for 15 seconds until light golden.","duration":0.25,"images":[],"step":4},{"description":"Add wine. Bring to simmer and scrape the bottom of the skillet to mix all the brown bits into the wine.","images":[],"step":5},{"description":"Let the wine simmer for 1 minute or so until the smell of alcohol is gone which means it has evaporated.","duration":1,"images":[],"step":6},{"description":"Mix in mustard, then add the chicken broth, cream, parmesan and sun dried tomatoes.","images":[],"step":7},{"description":"Bring to simmer, then reduce heat to medium and simmer for 2 to 3 minutes until thickened. Stir regularly to dissolve parmesan cheese.","duration":2.5,"images":[],"step":8},{"description":"Taste sauce and add more salt and pepper if needed.","images":[],"step":9},{"description":"Stir through basil leaves, then return chicken into pan. Spoon sauce over and simmer 1 minute.","images":[],"step":10},{"description":"Serve immediately! Great served over mashed potato, Creamy Mashed Cauliflower or pasta. Or serve with bread on the side to mop up sauce!","images":[],"step":11}]', '["milk","mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1383e8914ce8', 'en', 'US', 'Chicken Nachos', 'Recipe video above. Crispy chips loaded with juicy Mexican shredded chicken, plenty of melted cheese and toppings of choice. Your new favourite way with nachos! This chicken is a terrific all-purpose Mexican chicken, especially great in Tacos.', 'https://www.recipetineats.com/tachyon/2019/06/Chicken-Nachos_3.jpg', 15, 10, 25, 4, '[{"id": "ing_tortillas", "quantity": {"value": 31.25, "unit": "pack of 8"}}, {"id": "ing_chicken", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 250.0, "unit": "block of 250g"}}, {"id": "ing_quick_guacamole", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_avocado", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 3.0, "unit": "bunch"}}]', '[{"ingredients":["250g / 8 oz tortilla or plain corn chips (Note 1)","Shredded chicken for nachos (, recipe follows)","250g / 8 oz (2.5 cups) shredded cheddar or Monterey Jack cheese (Note 2)","Quick guacamole (, recipe follows)","Toppings: Sour cream, Coriander / cilantro leaves, Jalapeno (, sliced or chopped)"],"purpose":"Nachos"},{"ingredients":["700 g / 1.2 lb chicken thighs or breast (, skinless boneless (Note 3))","1.5 tbsp olive oil","2 tbsp tomato paste","2 tsp sugar","1 cup (250ml) chicken broth, separated (liquid stock)"],"purpose":"Chicken for Nachos"},{"ingredients":["3 tbsp lime juice (Note 4)","1 tbsp olive oil","2 garlic cloves (, minced)","2 tsp EACH garlic powder, onion powder, dried oregano","3 tsp EACH cumin powder, paprika","1/2 tsp cayenne pepper (optional)","1/2 tsp salt and pepper (, each)"],"purpose":"Homemade Nachos Meat Seasoning"},{"ingredients":["2 avocados (, medium)","3 tbsp coriander/cilantro (, roughly chopped)","2 tbsp lime juice (1 large)"],"purpose":"Quick Guacamole"}]', '[{"description":"Chicken for Nachos","images":[],"step":1},{"description":"Place Nachos Seasoning ingredients in a bowl. Add 2 tbsp of the chicken broth and mix to form a loose paste.","images":[],"step":2},{"description":"Add chicken, turn to coat in paste.","images":[],"step":3},{"description":"Heat oil in a large skillet over medium high heat. Cook chicken for 3 minutes on each side (reserve paste left in bowl). Remove chicken into a shallow dish.","duration":3,"images":[],"step":4},{"description":"Return skillet to stove. Add remaining chicken broth, tomato paste, sugar and scrape in any paste left in the bowl. Mix to dissolve, scraping base of pan, and bring to simmer.","images":[],"step":5},{"description":"Meanwhile, shred chicken with forks, or chop (don''t worry if raw inside).","images":[],"step":6},{"description":"Return chicken into sauce, toss and simmer for 3 minutes until sauce reduces down to a thick sauce. Adjust salt to taste. Keep warm.","duration":3,"images":[],"step":7},{"description":"Quick Guacamole:","images":[],"step":8},{"description":"Place ingredients in a bowl. Use potato masher to mash to desired consistency. Adjust salt and pepper to taste.","images":[],"step":9},{"description":"Preheat oven to 180C/350F.","images":[],"step":10},{"description":"Place half the corn chips slightly overlapping on a tray. Top with half the (warm) chicken and cheese.","images":[],"step":11},{"description":"Top with remaining chips and cheese. Bake 7 minutes or until cheese is melted and bubbly.","images":[],"step":12},{"description":"Garnish with coriander/cilantro and jalapeño. Serve immaterial with quick Guacamole and sour cream.","images":[],"step":13}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Mexican","Tex-Mex"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","mexican-recipes","nachos-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2810a48f904f', 'en', 'US', 'Jambalaya Recipe (easy)', 'Recipe VIDEO above. Many people consider this to be the world''s best one pot rice meal.... you won''t hear any arguments from me!! Filled with big, punchy New Orleans flavours, a homemade Creole/Cajun spice delivers top notch flavour with consistency results for everyone, no matter where you live in this big wide world. This Jambalaya is started on the stove then finished in the oven - exactly the same outcome as cooking the whole thing on the stove (the traditional way), but far less risk of uneven cooked rice and mushy gluey rice from over stirring. And it''s just easier - entirely hands off time! :)', 'https://www.recipetineats.com/tachyon/2019/06/Jambalaya_0.jpg', 20, 50, 70, 5, '[{"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_bacon", "quantity": {"value": 0.9, "unit": "pack of 200g"}}, {"id": "ing_sausages", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_shrimp", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 150.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.002, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 187.5, "unit": "pack"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.5, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}]', '[{"ingredients":["1 tbsp vegetable oil","180g (6oz) bacon (, preferably SMOKED, chopped)","200g (7oz) andouille or smoked sausage (, sliced 0.5cm / 1/5\" thick (Note 1))","300g (10oz) chicken thigh (, skinless boneless, cut into 2.5cm /1\" pieces)","12 prawns/shrimp (, raw, large, (peeled, with or without tails))","4 garlic cloves (, minced)","1 tbsp (15g) butter","1 onion (, large, cut into 1.5 cm / 0.5\" pieces)","2 celery ribs (, cut into 1.5 cm / 0.5\" pieces)","2 green capsicum / bell pepper (, medium, cut into 1.5 cm / 0.5\" pieces)","1.25 cups long grain rice (, uncooked (Note 2))","2.5 cups (625ml) low-sodium chicken broth / stock (Note 3)","200g (6.5oz) crushed canned tomato","2 tbsp tomato paste","1 cup green onions (, sliced, plus more for serving)"]},{"ingredients":["2 tsp chopped fresh thyme (or 1 tsp dried thyme)","4 tsp sweet paprika","1 tsp garlic powder","1 tsp onion powder","1/2 tsp cayenne powder (adjust spice to taste)","1/2 tsp black pepper","1/2 tsp salt"],"purpose":"Creole Seasoning Mix:"}]', '[{"description":"Preheat oven to 180C/350F (all types).","images":[],"step":1},{"description":"Heat oil in a very large skillet or dutch oven over medium high heat. (Note 4)","images":[],"step":2},{"description":"Add bacon, cook for 30 seconds (to start fat melting), then add sausages. Cook until sausages are golden - about 3 minutes - then remove into bowl.","duration":0.5,"images":[],"step":3},{"description":"Add chicken into the pan and cook until golden (doesn''t need to cook inside), then add to bowl with bacon.","images":[],"step":4},{"description":"Sear prawns in the pan for 1.5 minutes on each side, then transfer to a separate bowl (reserve until later).","images":[],"step":5},{"description":"Add butter, then garlic, onion, celery and capsicum. Cook for 3 to 4 minutes or until slightly softened.","duration":3.5,"images":[],"step":6},{"description":"Add rice, stir to coat grains in oil.","images":[],"step":7},{"description":"Add chicken broth, tomato paste, canned tomato, thyme and Seasoning Mix.","images":[],"step":8},{"description":"Stir well, then add chicken, sausages and bacon (including all liquid).","images":[],"step":9},{"description":"When you see bubbles across most of the surface, stir well once more. Ensure all rice is submerged, cover with lid, and transfer to oven. (See video)","images":[],"step":10},{"description":"Bake 20 minutes. Remove lid and check rice by eating a few grains (careful, very hot!) If the rice is just about done (Note 5 for the correct consistency), go to next step. If rice grains are still firm in the centre, continue to cook, checking rice every 5 mins - most ovens take about 30 mins total cooking (see Note 7).","images":[],"step":11},{"description":"Add prawns/shrimp and green onions, QUICKLY (but gently!) stir through, cover with lid, and return to oven for just 3 minutes (just to heat prawns).","images":[],"step":12},{"description":"Remove from oven (see video for finished consistency), stir gently to fluff, then serve, garnished with more green onions if desired.","images":[],"step":13}]', '["milk","shellfish"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Cajun","Louisiana","New Orleans"],"categories":["chicken-recipes","iconic-dishes","one-pot-recipes","rice-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9dbb9e5c6ab2', 'en', 'US', 'Chicken Pasta recipe of your dreams!', 'Recipe VIDEO above. The creamy chicken pasta recipe of your dreams! A creamy chicken Alfredo with sun dried tomato, spinach and bacon, you''ll love how the shredded chicken acts like a mop for the luxurious Alfredo sauce!', 'https://www.recipetineats.com/tachyon/2019/05/Chicken-Alfredo_8.jpg', 5, 15, 20, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.25, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 70.0, "unit": "bag of 250g"}}, {"id": "ing_tomato", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.6, "unit": "pack of 200g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["300g / 10 oz fettuccine (Note 1)","30g / 2 tbsp butter (, separated)","2 chicken breasts (, cut in half horizontally)","1/2 tsp each salt and pepper","2 garlic cloves (, minced)","1/2 cup (125ml) dry white wine (sub more chicken broth)","1/2 cup (125ml) chicken stock / broth (, low sodium)","1 1/4 cups (315ml) cream (, thickened / heavy (Note 2))","3/4 cup (75g) parmesan (, finely shredded (Note 3))","70g / 2.5oz baby spinach","100 g / 3oz sun dried tomato strips (Note 4)"]},{"ingredients":["120g / 4oz bacon (, cooked and crumbled)","More parmesan","Parsley (, for garnish (optional))"],"purpose":"Serving:"}]', '[{"description":"Cook pasta in a large pot of salted boiling water for time per packet minus 1 1/2 minutes.","images":[],"step":1},{"description":"Just before draining, scoop out a mugful of pasta cooking water. Then drain pasta.","images":[],"step":2},{"description":"Sprinkle both sides of chicken with salt and pepper.","images":[],"step":3},{"description":"Melt half the butter in a large skillet over hig heat.","images":[],"step":4},{"description":"Add chicken and cook for 2 minutes on each side until deep golden.","duration":2,"images":[],"step":5},{"description":"Remove chicken onto plate, rest for a few minutes then shred with 2 forks.","images":[],"step":6},{"description":"Turn down heat to medium high. In the same skillet, add remaining butter and garlic.","images":[],"step":7},{"description":"Cook garlic for 30 seconds until golden, then add wine.","duration":0.5,"images":[],"step":8},{"description":"Simmer rapidly, stirring to scrape the brown bits off the bottom of the pan. Once mostly evaporated, add chicken broth, cream, parmesan and sun dried tomato.","images":[],"step":9},{"title":"Simmer on medium for 3","description":"5 minutes, stirring leisurely, until it reduces and thickens.","duration":4,"images":[],"step":10},{"description":"Essential Tossing:","images":[],"step":11},{"description":"Add spinach, chicken and cooked pasta.","images":[],"step":12},{"title":"Toss for 1 1/2","description":"2 minutes on the stove, until sauce thickens and coats the pasta strands (see VIDEO). Use pasta cooking water if needed if it gets too thick.","images":[],"step":13},{"description":"Serve immediately with parmesan, crumbled bacon and parsley (if desired).","images":[],"step":14}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f1365b686cc7', 'en', 'US', 'Quick Chicken Tacos - WITH sauce!', 'Recipe video above. A 2-in-1 chicken taco filling: shredded chicken AND sauce made in the same pan using the same seasoning mix! Because it''s so juicy and packed with tons of flavour, the toppings can be kept simple and there''s not need to make an extra sauce. No marinating required.', 'https://www.recipetineats.com/tachyon/2019/03/Chicken-Tacos_3.jpg', 15, 10, 25, 12, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_tortillas", "quantity": {"value": 1.0, "unit": "pack of 8"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}]', '[{"ingredients":["700 g / 1.2 lb chicken thighs (, skinless boneless (or breast))","1.5 tbsp olive oil","2 tbsp tomato paste","2 tsp sugar","1 cup (250ml) chicken broth, separated (liquid stock)"]},{"ingredients":["3 tbsp lime juice (Note 1)","1 tbsp olive oil","2 garlic cloves (, minced)","2 tsp EACH garlic powder, onion powder, dried oregano","3 tsp EACH cumin powder, paprika","1/2 tsp cayenne pepper (adjust spiciness to taste, can skip)","1 tsp salt","1/2 tsp black pepper"],"purpose":"HOMEMADE TACO SEASONING:"},{"ingredients":["Taco shells or tortillas (, warmed per packet directions)","Diced tomato (, onion, avocado, coriander/cilantro leaves)","Shredded lettuce","Shredded cheese","Sour cream"],"purpose":"To serve:"}]', '[{"description":"Place Taco Seasoning ingredients in a bowl. Add 2 tbsp of the chicken broth and mix to form a loose paste.","images":[],"step":1},{"description":"Add chicken, turn to coat.","images":[],"step":2},{"description":"Heat oil in a large skillet over medium high heat. Cook chicken for 3 minutes on each side until lightly seared. (Reserve marinade dregs in bowl)","duration":3,"images":[],"step":3},{"description":"Remove chicken into a shallow dish.","images":[],"step":4},{"description":"Return skillet to stove, reduce to medium. Add remaining chicken broth, tomato paste, sugar and scrape in any marinade left in the bowl. Mix to dissolve, scraping base of pan, and bring to simmer","images":[],"step":5},{"description":"Meanwhile, shred chicken with forks, or chop (don''t worry if raw inside).","images":[],"step":6},{"description":"Return chicken into sauce, toss and simmer for 2 to 3 minutes until sauce reduces to a thin syrup consistency (add water if reduces too fast). Adjust salt to taste.","duration":2.5,"images":[],"step":7},{"description":"Transfer chicken and all sauce to serving bowl.","images":[],"step":8},{"description":"Warm taco shells or tortillas.","images":[],"step":9},{"description":"Stuff with chicken, making sure it''s soaked with the sauce.","images":[],"step":10},{"description":"Top with tomato, avocado, onion, coriander, lettuce and sour cream. Devour!","images":[],"step":11}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican","Tex-Mex"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","mains","mexican-recipes","quick-and-easy","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ae28d9c6e414', 'en', 'US', 'Easy Chicken Curry', 'Recipe video above. This is a Western style curry, and it''s the easiest chicken curry I know how to make with the least ingredients possible without sacrificing tastiness! Very mild, not spicy at all (assuming curry powder is mild).', 'https://www.recipetineats.com/tachyon/2019/03/Best-easy-Chicken-Curry_5.jpg', 8, 20, 28, 4, '[{"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.75, "unit": "jar of 50g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.675, "unit": "can of 400ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_frozen_peas", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}]', '[{"ingredients":["1.5 tbsp oil (vegetable, canola)","2 garlic cloves (, minced)","2 tsp ginger (, grated)","1/2 onion (, finely chopped)","500g / 1lb chicken thighs, sliced (Note 1)","2.5 tbsp curry powder (Note 2)","270 ml / 1.25 cups coconut milk (, full fat (9 oz) (Note 3))","1.5 cups (375 ml) chicken stock low sodium","1/2 tsp salt","3/4 cup frozen peas","1/4 cup coriander / cilantro leaves (, chopped)"]}]', '[{"description":"Heat oil in a skillet over medium high heat. Cook garlic, ginger and onion for 3 minutes until onion is translucent.","duration":3,"images":[],"step":1},{"description":"Add chicken and cook until it it changes from pink to white.","images":[],"step":2},{"description":"Add curry powder and cook for 2 minutes.","duration":2,"images":[],"step":3},{"description":"Add coconut milk and chicken stock. Stir, lower heat to medium and cook, simmering rapidly, for 10 minutes until sauce reduces and thickens.","duration":10,"images":[],"step":4},{"description":"Add peas and salt. Cook for a further 2 minutes, then taste to see if it needs more salt. Garnish with coriander.","images":[],"step":5},{"description":"Serve over rice, noodles or mashed potato!","images":[],"step":6}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken","chicken-recipes","curry-recipes","dietary","dinner-tonight","gluten-free-recipes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_434fc8348836', 'en', 'US', 'Oven Baked Chicken Breast', 'Recipe VIDEO above. My tips for a truly juicy, Oven Baked Chicken Breast: a touch of brown sugar in the seasoning which makes the chicken sweat while it bakes so it creates a semi "sauce", and cooking fast on a high temp! Go by the colour of the crust to know when it''s cooked through.', 'https://www.recipetineats.com/tachyon/2018/05/Oven-Baked-Chicken-Breast_-with-Garlic-Butter-Kale-Rice.jpg', 5, 18, 23, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4 chicken breasts (, 150 - 180g / 5 - 6 oz each (Note 1))","2 tsp olive oil"]},{"ingredients":["1 1/2 tbsp brown sugar","1 tsp paprika","1 tsp dried oregano or thyme (, or other herb of choice)","1/4 tsp garlic powder","1/2 tsp each salt and pepper"],"purpose":"Seasoning:"},{"ingredients":["Finely chopped parsley"],"purpose":"Garnish, optional:"}]', '[{"description":"Preheat oven to 425°F/220°C (200°C fan).","images":[],"step":1},{"description":"Pound chicken to 1.5cm / 0.6\" at the thickest part - using a rolling pin, meat mallet or even your fist (key tip for even cooking + tender chicken).","images":[],"step":2},{"description":"Mix Seasoning.","images":[],"step":3},{"description":"Line tray with foil and baking / parchment paper. Place chicken upside down on tray. Drizzle chicken with about 1 tsp oil. Rub over with fingers. Sprinkle with Seasoning.","images":[],"step":4},{"description":"Flip chicken. Drizzle with 1 tsp oil, rub with fingers, sprinkle with Seasoning, covering as much of the surface area as you can.","images":[],"step":5},{"description":"Bake 18 minutes, or until surface is golden per photos and video, or internal temperature is 165°F/75°C using a meat thermometer.","images":[],"step":6},{"description":"Remove from oven and immediately transfer chicken to serving plates.","images":[],"step":7},{"title":"Wait 3","description":"5 minutes before serving, garnished with freshly chopped parsley if desired. Pictured with a side of Garlic Butter Rice with Kale.","images":[],"step":8}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","emergency-recipes","gluten-free-recipes","low-calorie-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ee33234a0baa', 'en', 'US', 'Chicken Stew', 'Recipe video above. Slow cooked chicken with ultra tender flesh and outrageous crispy skin smothered in a gravy-like sauce that''s lip smackingly delicious. Carrots, celery, onion and potato make this a filling meal so you won''t need a side - except perhaps some crusty bread to dunk in the sauce! Make this in a large oven proof pot, or see notes if you don''t have one.', 'https://www.recipetineats.com/tachyon/2018/05/Chicken-Stew_5.jpg', 10, 90, 100, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 3000.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 4.0, "unit": "head"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_worscestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_thyme", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 600.0, "unit": "bag of 2kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["1 tbsp olive oil","1.5 kg / 3lb bone in, skin on chicken thighs and drumsticks (6 to 8 pieces)","Salt and pepper","2 onions (, halved and cut into wedges)","2 garlic cloves (, minced)","3 large carrots (, cut thick end into 1.5cm / 3/5\" pieces, thin end 2.5cm/1\")","4 celery stalks (, cut into 2cm / 4/5\" chunks)","1/2 cup (125 ml) white wine (or water)","3 tbsp (35g) flour","3 cups (750 ml) chicken broth (, low low sodium)","2 tbsp tomato paste","2 tsp Worscestershire sauce","3 sprigs thyme (, or 1 tsp dried thyme (or other herb))","2 bay leaves (dried or fresh)","600 g / 1.2lb baby potatoes (, halved (quarter large ones))"]},{"ingredients":["Fresh thyme or parsley (chopped)","Warm crusty bread"],"purpose":"Serving (optional):"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Heat oil in a large pot over high heat. Brown chicken on both sides until light golden, sprinkling with salt and pepper. Remove from pot. (Do in 2 batches if pot not big enough).","images":[],"step":2},{"description":"If there''s too much oil in the pot, discard some. Add onion and garlic. Cook for 2 minutes until onion is translucent.","duration":2,"images":[],"step":3},{"description":"Add carrots and celery, cook for 1 minute.","duration":1,"images":[],"step":4},{"description":"Add wine. Stir, scraping the bottom of the pan to dissolve the brown bits into the liquid. Cook for 1 minute until liquid is mostly gone.","duration":1,"images":[],"step":5},{"description":"Sprinkle flour across surface, stir.","images":[],"step":6},{"description":"Add broth, tomato paste, Worcestershire sauce, thyme and bay leaves. Stir to dissolve tomato paste.","images":[],"step":7},{"description":"Place chicken on top, keeping the skin above the liquid level as much as you can.","images":[],"step":8},{"description":"Bring to simmer then cover. Bake for 45 minutes.","duration":45,"images":[],"step":9},{"description":"Remove from oven, remove lid. Add potatoes, pushing them into the liquid and rearranging chicken so they sit on top (for lovely crispy skin).","images":[],"step":10},{"description":"Return to oven without the lid for a further 40 minutes until the chicken skin is deep golden and super crispy, the potatoes are soft and the sauce is thickened.","images":[],"step":11},{"description":"Taste sauce and adjust salt and pepper to taste.","images":[],"step":12},{"description":"Serve with warm crusty bread on the side to dunk in the sauce - or go all the way with Garlic Bread! Optional: garnish with extra fresh thyme leaves or parsley.","images":[],"step":13}]', '["gluten"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","quick-and-easy","stews","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cb93471958e8', 'en', 'US', 'Honey Mustard Baked Chicken Drumsticks', 'Recipe video above. A terrifically easy baked chicken drumsticks with a magical 4 ingredient Honey Mustard sauce. Plus, option to add crispy smashed potatoes for an effortless dinner on one tray!', 'https://www.recipetineats.com/tachyon/2018/04/Honey-Mustard-Baked-Chicken-Drumsticks-with-Crispy-Smashed-Potatoes_0.jpg', 11, 60, 71, 4, '[{"id": "ing_potato", "quantity": {"value": 4.0, "unit": "bag of 2kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 8.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.15, "unit": "jar of 200g"}}, {"id": "ing_mustard", "quantity": {"value": 0.15, "unit": "jar of 200g"}}, {"id": "ing_honey", "quantity": {"value": 0.125, "unit": "jar of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.013, "unit": "pack of 400g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_broccoli", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["4 x 150g/5oz potatoes (Note 1)","2 tbsp / 30 g olive oil or melted butter"],"purpose":"Smashed Potatoes (optional):"},{"ingredients":["8 chicken legs (about 1 kg / 2 lb) (Note 2)","2 tsp olive oil"],"purpose":"Chicken:"},{"ingredients":["2 tbsp Dijon mustard (Note 3)","1 tbsp wholegrain mustard (or use more Dijon)","1/4 cup honey","1 garlic clove (, minced)","1 tsp cornflour/cornstarch (Note 4)","Pinch of salt and pepper"],"purpose":"Sauce:"},{"ingredients":["Fresh thyme leaves or chopped parsley","Steamed broccolini"],"purpose":"For serving (optional):"}]', '[{"description":"Smashed Potatoes option:","images":[],"step":1},{"description":"Microwave potatoes for 10 minutes on high or until cooked. (Note 5)","duration":10,"images":[],"step":2},{"description":"Place on one side of tray. Squish using potato masher (Note 6) to about 1.7cm / 2/3\" thickness. Drizzle with oil, sprinkle with salt and pepper.","images":[],"step":3},{"description":"If making smashed potatoes, fold up the edges of the foil the drumsticks are on","images":[],"step":4},{"description":"Sticky Baked Drumsticks:","images":[],"step":5},{"description":"Preheat oven to 180C/350F.","images":[],"step":6},{"description":"Mix Sauce ingredients together with a good pinch of salt and pepper.","images":[],"step":7},{"description":"Line tray with foil, then top with parchment paper.","images":[],"step":8},{"description":"Place drumsticks on paper. If making smashed potatoes, fold up the edges of the foil so the sauce won''t leak into the potatoes (doesn''t need to be high - even 1cm / 2/5\" is enough, video useful).","images":[],"step":9},{"description":"Spoon Sauce over drumsticks. Drizzle chicken with olive oil.","images":[],"step":10},{"description":"Bake for 30 minutes. Turn drumsticks (not potatoes), spoon juices over drumsticks.","duration":30,"images":[],"step":11},{"description":"Bake for a further 20 minutes, turn, spoon over juices. Bake for 10 - 15 minutes until sauce reduces and the drumsticks are golden and sticky.","duration":12.5,"images":[],"step":12},{"description":"Remove from oven. Squidge the drumsticks around in what should now be a syrupy sauce. (Note 7) Serve drumsticks with sauce, with crispy smashed potatoes and steamed broccolini on the side. Sprinkle with fresh thyme leaves if using.","images":[],"step":13}]', '["milk","mustard"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-drumstick-recipes","chicken-recipes","dinner-tonight","main-dishes","one-pot-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dc19ad410cb3', 'en', 'US', 'Sticky Baked Chicken Thighs', 'Recipe video above. This is what you make if you''ve got boneless skinless chicken thighs and haven''t planned anything for dinner. You''ve probably got everything required for the glaze - and if you don''t, there''s plenty of sub options. Savoury and sweet, the sauce is great drizzled over everything!', 'https://www.recipetineats.com/tachyon/2019/02/Sticky-Baked-Chicken-Thighs_5.jpg', 5, 25, 30, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_ketchup", "quantity": {"value": 0.075, "unit": "bottle of 500g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.03, "unit": "bottle of 500ml"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}]', '[{"ingredients":["700g / 1.4lb chicken thighs (, skinless boneless (5-7 pieces), Note 1)"]},{"ingredients":["1/4 cup ketchup","3 tbsp brown sugar (, lightly packed)","1.5 tbsp soy sauce (, all purpose or light (NOT dark))","1 tbsp apple cider vinegar","1 tbsp olive oil","2 tsp Worcestershire Sauce","2 clove garlics (, minced)"],"purpose":"Glaze (Note 2 for subs):"}]', '[{"description":"Preheat oven to 220°C/420°F (200°C fan).","images":[],"step":1},{"title":"Pan","description":"Use a pan large enough to fit the thighs lying flat (not bunched up/folded). Line pan with foil (you''ll thank me later), place thighs in pan.","images":[],"step":2},{"title":"Glaze 1","description":"Mix Glaze ingredients together. Spoon over about 2/3 of the Glaze on the surface of each (not underside), reserve rest.","images":[],"step":3},{"description":"Bake 15 minutes, remove pan.","images":[],"step":4},{"description":"Flick to grill/broiler on high, adjust shelf to be 20cm/8\" from heat source.","images":[],"step":5},{"title":"Glaze 2","description":"Spoon pan juices over chicken. Then spoon/dab remaining Glaze onto chicken.","images":[],"step":6},{"description":"Broil chicken for 8 to 10 minutes until surface is nicely caramelised.","duration":9,"images":[],"step":7},{"title":"Rest","description":"Remove and stand for a few minutes (uncovered) before serving with pan juices.","images":[],"step":8}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-recipes","dinner-tonight","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fe3ff2c848fd', 'en', 'US', 'Easy Chicken Cordon Bleu', 'Recipe video above. My midweek version of Chicken Cordon Bleu. All the flavour, all the crunch, much faster to make, and it''s better for you because it''s baked! Choose your method for crumbing the chicken - Super Easy or Quick Dredge (see photos for difference). Super Easy coats the top and sides of the chicken, but is faster than the Dredging Method. Served with a gorgeous traditional Dijon Cream Sauce!', 'https://www.recipetineats.com/tachyon/2015/10/Easy-Chicken-Cordon-Bleu-2.jpg', 15, 30, 45, 2, '[{"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_ham", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.113, "unit": "jar of 400g"}}, {"id": "ing_mustard", "quantity": {"value": 0.113, "unit": "jar of 200g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.225, "unit": "pack of 200g"}}]', '[{"ingredients":["Panko breadcrumbs - 1/2 cup for Super Easy or 1 cup for Quick Dredge","Oil spray"],"purpose":"Breadcrumbs"},{"ingredients":["2 small chicken breasts, (around 6-7oz/180-210g each)","Salt and pepper","4 slices swiss cheese (Note 1)","4 to 6 slices of ham, (about 2.5oz/75g (Note 2))"],"purpose":"Chicken"},{"ingredients":["3 tbsp mayonnaise","1 1/2 tbsp Dijon mustard"],"purpose":"Method 1: Super Easy"},{"ingredients":["1 egg","2 tsp plain flour"],"purpose":"Method 2: Quick Dredge"},{"ingredients":["1 1/2 tbsp butter","1 1/2 tbsp flour","1 1/4 cups milk (Note 3)","2 tbsp Dijon mustard","3 tbsp parmesan cheese, finely grated"],"purpose":"Dijon Cream Sauce (makes 1 cup)"}]', '[{"description":"Preheat oven to 200C/390F (standard) or 180C/350F (fan).","images":[],"step":1},{"description":"Spread panko breadcrumbs on a baking tray and spray with oil. Bake for 3 minutes or until light golden. Remove and scrape into bowl straight away.","duration":3,"images":[],"step":2},{"description":"Cut a pocket into each chicken breast, as per the photo below.","images":[],"step":3},{"description":"Fold the cheese in half and place 2 pieces inside each pocket. Do the same with the ham. Close the pocket, seal with 2 toothpicks. Sprinkle with salt and pepper.","images":[],"step":4},{"description":"Super Easy Method","images":[],"step":5},{"description":"Mix the mayonnaise, mustard, salt and pepper in a bowl. Spread onto the top and sides of the chicken (not underside).","images":[],"step":6},{"description":"Sprinkle panko over the chicken, using your other hand to press the breadcrumbs onto the side of the chicken. Spray with oil.","images":[],"step":7},{"description":"Quick Dredge Method","images":[],"step":8},{"description":"Whisk egg and flour. Dip chicken into egg mixture, then into the panko breadcrumbs. Transfer to tray, spray with oil.","images":[],"step":9},{"description":"Bake for 25 to 30 minutes, or until golden brown and just cooked through. Remove toothpicks, serve with the Dijon Cream Sauce.","duration":27.5,"images":[],"step":10},{"description":"Dijon Cream Sauce","images":[],"step":11},{"description":"Melt butter over medium heat in a small saucepan. Add flour and cook for 1 minute.","duration":1,"images":[],"step":12},{"description":"Add half the milk and whisk until the flour mixture is blended in.","images":[],"step":13},{"description":"Add remaining milk, mustard and cheese. Cook for 3 minutes, whisking constantly, until thickened. It will thicken as it cools.","duration":3,"images":[],"step":14},{"description":"Remove from heat, add salt and pepper to taste. Serve with chicken.","images":[],"step":15}]', '["egg","gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["French(ish)"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","mains","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bc3d0c16ae60', 'en', 'US', 'Roast Chicken', 'RECIPE VIDEO ABOVE. Slathered with a garlic-herb-lemon butter, this roast chicken is juicy on the inside with crispy golden skin on the outside. An all round flavour bomb with the most incredible liquid gold pan juices to use as the sauce! See notes for gravy option and cook times for other chicken sizes.', 'https://www.recipetineats.com/tachyon/2016/05/Roast-Chicken_6a.jpg', 15, 90, 105, 5, '[{"id": "ing_chicken", "quantity": {"value": 1.75, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_rosemary", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_sage", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_rosemary", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_wine", "quantity": {"value": 0.333, "unit": "bottle of 750ml"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}]', '[{"ingredients":["1.75 - 2 kg / 3.5 - 4lb whole chicken (, patted dry)","Salt and pepper","2 tsp olive oil","1 lemon, quartered","3 rosemary sprigs"]},{"ingredients":["100 g / 1 stick unsalted butter (, melted)","3 garlic cloves (, minced)","1 tbsp sage (, finely chopped (Note 1))","2 tsp rosemary (, finely chopped (Note 1))","1 tbsp parsley (, finely chopped (Note 1))","1/2 tsp each salt and black pepper"],"purpose":"Butter:"},{"ingredients":["1 cup / 250 ml dry white wine (, or low sodium chicken broth)","1 onion (, quartered (Note 2))","1 garlic bulb (, halved horizontally (Note 2))"],"purpose":"Under Chook:"}]', '[{"description":"Take the chicken out of the fridge 30 minutes before cooking.","images":[],"step":1},{"description":"Preheat oven to 220C/450F (standard) or 200C/430F (fan/convection). Put shelf in the middle.","images":[],"step":2},{"description":"Mix together Butter ingredients. Add juice from 2 wedges of lemon.","images":[],"step":3},{"description":"Place chicken in a roasting pan. Use a dessert spoon to loosen skin from chicken (see video). Do the top (the breast) and the drumsticks – not the underside.","images":[],"step":4},{"description":"Prop chicken upright, drizzle butter under skin, using most of the garlic/herb sludge, but saving a bit of butter for the skin (Note 3).","images":[],"step":5},{"description":"Drizzle / smear remaining butter all over surface of the chicken. Squeeze over juice of 2 lemon wedges.","images":[],"step":6},{"description":"Stuff used lemon wedges and rosemary inside chicken.","images":[],"step":7},{"description":"Tie drumstick ends with string and tuck wing tips under the chicken.","images":[],"step":8},{"description":"Sprinkle all over with salt and pepper.","images":[],"step":9},{"description":"Place onion and garlic in the pan, place chicken on top. Pour wine around, drizzle chicken with oil.","images":[],"step":10},{"description":"Transfer to oven. Roast for 10 minutes, then turn oven down to 180C/350F (all oven types). Roast for a further 1 hr 15 minutes, or until the internal temperature is 75C/165F or until juices run clear when pierced at the join between the drumstick and the body. Baste twice (30 min then at 1 hr), spooning pan juices over skin.","duration":10,"images":[],"step":11},{"title":"Rest for 15 minutes","description":"don’t cover, skin becomes wet.","duration":15,"images":[],"step":12},{"description":"Serve with pan juices (see video for how to carve). I discard onion but use the garlic in the pan. See notes for side suggestions & how to use carcass for incredible homemade broth!","images":[],"step":13}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-recipes","dietary","easter-mains","easter-recipes","gluten-free-recipes","iconic-dishes","main-dishes","roasts","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ca72e08ec8df', 'en', 'US', 'Chicken Stroganoff', 'Recipe video above. You love Beef Stroganoff...now try CHICKEN! Golden seared chicken with a creamy mushroom Stroganoff gravy, I like making this with whole chicken thighs so I can brown it nicely which leaves brown bits in the pan that makes an incredible flavour base for the sauce!', 'https://www.recipetineats.com/tachyon/2018/11/Chicken-Stroganoff_8.jpg', 5, 15, 20, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.4, "unit": "tub of 250g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 250.0, "unit": "pack of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["600g / 1.2 lb chicken thighs (4 - 5) (, boneless skinless (or breast or tenderloin, Note 1))","1 tsp garlic powder","Salt and pepper","1 tbsp olive oil"],"purpose":"Chicken:"},{"ingredients":["1 large onion (, chopped)","300g / 10oz mushrooms (, sliced (not too thin))","40g / 3 tbsp butter","2 tbsp flour (Note 2)","2 cups / 500 ml beef broth/stock (, salt reduced)","1 tbsp Dijon mustard","2/3 cup (150g) sour cream (or yogurt)"],"purpose":"Gravy:"},{"ingredients":["250 - 300 g / 8 - 10 oz pasta or egg noodles of choice (Note 3)","Chopped parsley or chives (, for garnish (optional))"],"purpose":"Serving:"}]', '[{"description":"Sprinkle chicken with garlic powder, salt and pepper on both sides.","images":[],"step":1},{"description":"Heat oil in a large skillet over medium heat. Place chicken in skillet smooth side down.","images":[],"step":2},{"description":"Press down lightly with with spatula. Cook for 4 minutes until golden.","duration":4,"images":[],"step":3},{"description":"Turn and press lightly with spatula. Cook for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Remove chicken onto a plate.","images":[],"step":5},{"description":"Turn heat up to medium high. Add butter, melt. Then add onions, cook for 1 minute, then add mushrooms.","duration":1,"images":[],"step":6},{"description":"Cook mushrooms until golden. Scrape bottom of fry pan to get all the golden bits off (this is flavour!).","images":[],"step":7},{"description":"Add flour, cook, stirring, for 1 minute.","duration":1,"images":[],"step":8},{"description":"Add half the broth while stirring. Once incorporated, add remaining broth.","images":[],"step":9},{"description":"Stir, then add sour cream and mustard. Stir until incorporated (don''t worry if it looks split, sour cream will \"melt\" as it heats).","images":[],"step":10},{"description":"Bring to simmer ,then reduce heat to medium low. Once it thickens to the consistency of pouring cream (3 minutes), adjust salt and pepper to taste.","images":[],"step":11},{"description":"Add chicken back in (including plate juices). Simmer for 1 minute, then remove from stove.","duration":1,"images":[],"step":12},{"description":"Serve over pasta or egg noodles, sprinkled with parsley or chives if desired.","images":[],"step":13}]', '["egg","gluten","milk","mustard"]', '["high_protein","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","mains","mushroom-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fcceea8f8ac8', 'en', 'US', 'Juicy Roast Turkey', 'Recipe video above. This is still the only way I roast a whole turkey - dry brined with a seasoned salt. Start it in a hot oven upside down, then finish in a lower oven right side up. Brush with lots of butter, but only add minced garlic and fresh herbs towards the end else it burns. The turkey flesh is juicy, the skin is crisply golden, it''s simple, practical and foolproof. No buckets of liquid brine! You can even start it while the turkey is still partially frozen - it will brine as it thaws. Dry brined meats also cook faster - a 5kg/10lb turkey takes under 2 hours. Useful, when there''s lots of oven demand!Start this recipe two days before cooking. You can brine up to 3 days, but 4 days doesn''t add anything and I worry about food safety. Use the RECIPE SCALER to change ingredients to the weight of your turkey (click/tap on servings and slide!).', 'https://www.recipetineats.com/tachyon/2018/11/Juicy-Roast-Turkey_Dry-Brined_2.jpg', 20, 120, 140, 10, '[{"id": "ing_whole_turkey", "quantity": {"value": 4.536, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_mixed_herbs", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_butter", "quantity": {"value": 10.0, "unit": "block of 250g"}}, {"id": "ing_rosemary", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.5, "unit": "bottle of 750ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chicken", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["10 lb / 5kg whole turkey (, thawed (plain not pre brined) (Note 1))"]},{"ingredients":["2 1/2 tbsp kosher salt / cooking salt (Note 2)","2 tsp dried thyme (, or other herb of choice)","1 tsp paprika (, sweet or ordinary)","1 tsp garlic powder (optional)","1/2 tsp black pepper"],"purpose":"Dry Brine Salt Rub:"},{"ingredients":["2 heads of garlic (, halved horizontally (ie 4 halves))","1 onion (, halved - skin on is fine (brown, yellow, white))","2 small bunch mixed herbs (, sage, rosemary, thyme, parsley (optional, Note 3))","10 tbsp (150g) unsalted butter (, melted)","1 tbsp (in total) sage, rosemary and thyme (, finely chopped - equal amounts of each (Note 3))","3 garlic cloves (, minced)","1 1/2 cups dry white wine (, or water (Note 4))","Salt & pepper"],"purpose":"For Roasting"},{"ingredients":["4 cups chicken broth / stock (, low sodium)","5 tbsp flour (, plain / all purpose)","Salt and pepper"],"purpose":"Gravy (~ 4 cups/1L)"}]', '[{"description":"Rub turkey with the Salt Rub, wrap mummy-like in cling wrap. Fridge 48 hrs, flipping halfway. Stuff, roast upside down 30min in hot 220°C/425°F (200°C fan) oven, flip, garlic-herb-butter baste, finish roasting in lower oven 165°C/325°F (150°C fan).","images":[],"step":1},{"description":"Dry Brining Preparation","images":[],"step":2},{"title":"Salt Rub","description":"Mix together the Rub ingredients.","images":[],"step":3},{"title":"Prep Turkey","description":"Pat the turkey dry with paper towels, inside and out. Remove giblets or anything else inside the turkey. (Note 5)","images":[],"step":4},{"title":"Sprinkle","description":"Sprinkle 1 teaspoon of the Salt Rub inside the turkey and use you hand to spread it (roughly is fine). Turn the turkey upside down, then rub 1 teaspoon of the Salt Rub on the underside.","images":[],"step":5},{"description":"Turn the turkey upright and rub the remaining Salt Rub on the turkey, using most on the breast - even some under the skin if you can.","images":[],"step":6},{"description":"Wrap turkey mummy-like in lots of cling wrap (works best, I find) or place the turkey in a sealable plastic bag (Note 6).","images":[],"step":7},{"description":"Brining (Note 7):","images":[],"step":8},{"description":"Place turkey upside down in baking pan. Refrigerate 2 days (minimum) up to 3 days (4 days adds nothing, I find).","images":[],"step":9},{"title":"24 hours later","description":"Flip turkey so it''s right side up.","images":[],"step":10},{"title":"24 (to 48 hours) later","description":"unwrap turkey. The skin should be moist but not wet. If wet, pat dry. Leave out for 30 min before roasting.","duration":30,"images":[],"step":11},{"description":"Prepare for roasting:","images":[],"step":12},{"description":"Preheat oven to 220°C/425°F (200°C fan-forced)","images":[],"step":13},{"title":"Prep for roasting","description":"Place the onions and garlic in a roasting pan. Place a roasting rack on top - if you have one (Note 8 for sub).","images":[],"step":14},{"description":"Stuff bunch of herbs + 2 garlic halves + 3 tbsp butter (45g) inside the turkey. Tie drumsticks together with kitchen twine (optional).","images":[],"step":15},{"description":"Place turkey UPSIDE DOWN on the rack. Twist the wings so they are on top - see video. Brush with a bit of melted butter. Sprinkle with a tiny bit of salt and pepper.","images":[],"step":16},{"title":"Wine","description":"Pour wine in roasting pan.","images":[],"step":17},{"description":"Roast for 30 minutes.","duration":30,"images":[],"step":18},{"title":"Flip & brush","description":"Use a tea towel to turn the turkey over so it''s right side up. Brush with butter, sprinkle with a tiny bit of salt and pepper.","images":[],"step":19},{"description":"Turn oven down to 165°C/325°F (150°C fan).","images":[],"step":20},{"description":"Roast turkey 45 minutes.","images":[],"step":21},{"title":"Garlic herb butter","description":"Mix remaining butter with garlic and herbs. Brush turkey generously with butter.","images":[],"step":22},{"description":"Roast turkey for a further 30 minutes or until a) the thermometer that comes with the turkey pops up; or b) a thermometer inserted between the breast and leg reads 165°F/75°C. (Notes 9, 10). Cover loosely with foil if browning too much.","images":[],"step":23},{"title":"Rest","description":"Remove turkey onto serving plate, cover loosely with foil and rest for 30 minutes before transferring to platter for presentation and carving (see in post for styling idea).","duration":30,"images":[],"step":24},{"description":"Serve turkey with gravy and/or Cranberry Sauce.","images":[],"step":25},{"description":"Place roasting pan (with garlic, onion etc still in it) on the stove over medium high heat. Add flour and cook for 2 minutes.","duration":2,"images":[],"step":26},{"description":"Add broth and use a potato masher to mash the onion and garlic into the mixture. Use a wooden spoon to scrap the bottom of the pan. Cook for 3 to 5 minutes or until thickened.","duration":4,"images":[],"step":27},{"description":"Strain into a bowl, pressing down to extract all the flavour out of the onion and garlic. Transfer to gravy boat.","images":[],"step":28}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-recipes","dietary","gluten-free-recipes","iconic-dishes","main-dishes","roasts","turkey-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_004c57a252d8', 'en', 'US', 'Chicken Pot Pie', 'Recipe video above. Everybody''s favourite Chicken Pot Pie! A creamy chicken and vegetable filling with a hint of thyme, topped with puff pastry. The smell when this is baking is SO GOOD! Makes 4 large, 6 medium or 1 large pie. Brilliant freezer standby meal.', 'https://www.recipetineats.com/tachyon/2018/10/Chicken-Pot-Pie_2.jpg', 15, 60, 75, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 2000.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sheet_puff_pastry", "quantity": {"value": 2.0, "unit": "pack"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}]', '[{"ingredients":["600 g/1.2lb chicken breast (or boneless thighs)","2 cups milk (, any fat % (Note 1))","1 cup chicken broth (stock)","2 tsp chicken or vegetable stock powder (Note 2)","2 sprigs thyme (, optional)"],"purpose":"Chicken & broth:"},{"ingredients":["1 large onion (, chopped)","2 large carrots ((3 small). chopped)","3 celery ribs (, chopped)","2 garlic cloves (, minced)","50g / 3 tbsp butter","1 tsp dried thyme","1/3 cup white wine (sub more chicken stock)","1/3 cup flour","1/2 cup grated parmesan","1/2 tsp black pepper","1 cup frozen peas (, no need to thaw)","2 sheets puff pastry (enough to cover pots, with drape)","1 egg (, lightly whisked)"],"purpose":"Chicken Pot Pie:"}]', '[{"description":"Place milk, broth and stock powder in a large saucepan. Bring to a very gentle simmer over medium heat, add chicken and thyme.","images":[],"step":1},{"description":"Place lid on, simmer gently on medium low for 15 minutes (do not boil, can make milk split).","duration":15,"images":[],"step":2},{"description":"Remove chicken, shred or dice (don''t worry if inside a bit uncooked). Cover pot and set poaching liquid aside.","images":[],"step":3},{"description":"Chicken Pot Pie:","images":[],"step":4},{"description":"Melt butter in a large pot over medium high heat. Add garlic and onion, cook for 2 minutes. Add thyme, carrot and celery, cook for 3 minutes or until carrot is softened.","duration":2,"images":[],"step":5},{"description":"Add wine. Stir, scraping the bottom of the pot, and cook for 1 1/2 minutes or until wine is mostly evaporated.","images":[],"step":6},{"description":"Add flour and stir for 1 minute.","duration":1,"images":[],"step":7},{"description":"Add about half the reserved poaching liquid and stir until all flour is incorporated - it will be a thick sludge.","images":[],"step":8},{"description":"Add remaining milk broth, parmesan, pepper. Stir.","images":[],"step":9},{"description":"Add chicken and peas, stir.","images":[],"step":10},{"description":"Once mixture is heated (you''ll see steam), cook for 3 minutes to thicken the sauce, stirring regularly. (Note 3)","duration":3,"images":[],"step":11},{"title":"Remove from heat. Spoon into oven proof pots","description":"4 large or 6 small (Note 4). Cool in fridge at least 30 minutes. (Note 5)","images":[],"step":12},{"description":"Assembly & Baking:","images":[],"step":13},{"description":"Meanwhile, remove puff pastry from freezer to partially thaw. Then use a bowl as a guide to cut rounds from the pastry about 2.5cm / 1\" wider (all the way around) than the pots - be generous!","images":[],"step":14},{"description":"Preheat oven to 180C/350F.","images":[],"step":15},{"description":"Brush edge of pots with egg. Top with puff pastry, folding down the edges.","images":[],"step":16},{"description":"Brush pastry with egg. Cut a 2cm / 2/3\" slide in the middle with a small knife.","images":[],"step":17},{"title":"Bake 35","description":"40 minutes until deep golden.","images":[],"step":18},{"description":"Serve immediately!","images":[],"step":19}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2aeecf3c299e', 'en', 'US', 'Greek Chicken', 'Recipe video above. Yogurt is a magical marinade! This chicken is golden on the outside, beautifully tenderised on the inside and infused with terrific garlic-oregano flavours. Serve this with a Greek Salad and flatbread - or see in post for a full Greek Feast menu! Marinade time: Overnight, min 3 hrs.', 'https://www.recipetineats.com/tachyon/2018/09/Greek-Feast_3.jpg', 8, 50, 58, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.25, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.45, "unit": "bunch"}}]', '[{"ingredients":["1.25 kg / 2.5 lb drumsticks and chicken thighs (, bone in skin on (Note 1))"]},{"ingredients":["6 garlic cloves (, minced (~ 2 tbsp))","2 tbsp white wine vinegar (or red wine or apple cider vinegar)","1/2 cup / 125 ml lemon juice","2 tbsp extra virgin olive oil","3/4 cup Greek yogurt (I use Farmers Union)","1 1/2 tbsp dried oregano","1 tsp salt","1/2 tsp black pepper"],"purpose":"Marinade:"},{"ingredients":["Plain Greek yogurt or Tzatziki","Fresh oregano leaves (optional)"],"purpose":"Serving (optional):"}]', '[{"description":"Mix Marinade ingredients in a large bowl.","images":[],"step":1},{"description":"Add chicken and coat well. Marinade for 24 hours (3 hours minimum).","images":[],"step":2},{"description":"Preheat oven to 180C.350F.","images":[],"step":3},{"description":"Line a tray with foil (trust me), place rack on tray (optional).","images":[],"step":4},{"description":"Place chicken on rack (reserve marinade), skin side up. Bake 30 minutes,","images":[],"step":5},{"title":"Remove from oven. Brush with marinade","description":"do not flip.","images":[],"step":6},{"description":"Return to oven for 20 minutes or until golden and a bit crispy. Give it a spray of olive oil just before it''s done if you want an extra crispy, shiny coat.","duration":20,"images":[],"step":7},{"description":"Rest for a few minutes before serving. Juicy and tasty enough to serve plain but extra great with tzatziki or even some plain yogurt.","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["chicken-breast-recipes","chicken-recipes","greek-recipes","main-dishes","mediterranean-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9b5847dc52c1', 'en', 'US', 'Chicken Fajitas', 'Recipe video above. The secret ingredient in this Fajita marinade is orange juice. It injects flavour as well as brining, and makes the chicken caramelise beautifully when cooked. It doesn’t taste like oranges at all once cooked. Use any coloured peppers you want – though seeing a kaleidoscope of colours on a platter will bring a smile to anyone’s face!', 'https://www.recipetineats.com/tachyon/2017/04/Chicken-Fajitas_8.jpg', 15, 15, 30, 4, '[{"id": "ing_ime_juice", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_oranges", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_tortillas", "quantity": {"value": 8.0, "unit": "pack of 8"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_lime", "quantity": {"value": 0.075, "unit": "net of 500g"}}]', '[{"ingredients":["1/4 cup / 65 ml lime juice","1/4 cup / 65 ml orange juice (Note 1 for subs)","2 tbsp olive oil","2 garlic cloves (, minced)","1 tsp cumin powder","1 tsp salt","1/2 tsp black pepper"],"purpose":"Marinade:"},{"ingredients":["700g / 1.2 lb skinless chicken thighs or 2 large chicken breasts (, halved horizontally (Note 2))","2 tbsp olive oil","3 capsicums / bell peppers (, deseeded and sliced (red, yellow or green))","1 large onion (, halved and sliced thickly (brown, yellow, white or red))"],"purpose":"Fajitas:"},{"ingredients":["8– 12 small tortillas","1 large avocado (, halved and sliced)","Sour cream","Fresh lime wedges"],"purpose":"To Serve:"}]', '[{"description":"Place Marinade ingredients in a large bowl and mix. Add chicken, toss well to coat. Marinade for 1 hour to 24 hours (or freeze immediately then defrost overnight).","images":[],"step":1},{"description":"Use 2 skillets to cook the chicken and vegetables at the same time, if you can.","images":[],"step":2},{"description":"Heat 1 tbsp oil in a heavy based skillet over high heat until smoking. Add vegetables to cover the base of the pan in a single layer without too much overlapping (I cook in 3 batches). Spread out, leave for 45 seconds (to char it).","duration":0.75,"images":[],"step":3},{"description":"Toss quickly then spread out. Sprinkle with salt and pepper. Leave 45 seconds, toss then spread out, then leave 45 seconds. Remove onto platter and repeat with remaining Vegetables.","images":[],"step":4},{"description":"Heat 1 tbsp oil in a large skillet over medium high heat. Add chicken and cook for 3 to 4 minutes until caramelised. Turn and cook the other side for 3 – 4 minutes.","duration":3.5,"images":[],"step":5},{"description":"Remove onto a plate, cover loosely with foil. Rest for 3 minutes then slice.","duration":3,"images":[],"step":6},{"description":"To Serve:","images":[],"step":7},{"description":"Warm tortillas using chosen method.","images":[],"step":8},{"description":"Pile peppers and onion onto tortilla. Top with chicken, drizzle with sour cream, squeeze over lime juice. Fold, devour and be happy.","images":[],"step":9}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["chicken","chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","fajitas","gluten-free-recipes","main-dishes","mains","mexican-recipes","quick-and-easy","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ec1393e00f2e', 'en', 'US', 'Lemon Chicken Salad', 'Recipe video above. A substantial salad with a lemon marinated chicken, dressed with a dill lemon dressing with a touch of honey. You''ll love how the dressing does double duty as the marinade! Bacon is optional - totally delicious without, but always fabulous with. Serves 2 as a meal, 4 as a side.', 'https://www.recipetineats.com/tachyon/2018/07/Lemon-Chicken-Salad-1a.jpg', 15, 8, 23, 2, '[{"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_honey", "quantity": {"value": 0.03, "unit": "jar of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_dill", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 24.0, "unit": "head"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 0.6, "unit": "punnet of 250g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_corn", "quantity": {"value": 0.281, "unit": "can of 400g"}}, {"id": "ing_bacon", "quantity": {"value": 0.6, "unit": "pack of 200g"}}]', '[{"ingredients":["2 tsp lemon zest","2 tbsp lemon juice","1 tbsp honey","1 tsp Dijon mustard","3 tbsp extra virgin olive oil","1 large garlic clove (, minced)","1/2 tsp salt + 1/4 tsp black pepper"],"purpose":"Dressing/Marinade:"},{"ingredients":["1 large chicken breast (, halved horizontally* OR 2 boneless skinless chicken thighs)","1 tbsp lemon juice (, extra)","Salt and pepper","1/2 tbsp olive oil"],"purpose":"Chicken:"},{"ingredients":["2 tbsp finely chopped dill","8 cups cos/romaine lettuce (, chopped (or other lettuce of choice, Note 2))","1 cup cherry tomatoes (, halved)","1 medium avocado (, quartered and sliced thickly)","1/2 red onion (, small, finely sliced)","3/4 cup corn kernels (, fresh or canned drained)","120g/ 4 oz bacon (, cooked then chopped (optional))"],"purpose":"Salad:"}]', '[{"description":"Place Dressing ingredients in a jar. Shake well.","images":[],"step":1},{"description":"Place chicken in a bowl. Add 2 tbsp Dressing, 1 tbsp extra lemon juice, plus a pinch of salt and pepper. Mix well. Marinate minimum 20 minutes up to 24 hours.","images":[],"step":2},{"description":"Heat oil in a non stick skillet over medium high heat (or use bacon fat if you use bacon in this!). Add chicken and cook. Halved breasts: 2 minutes each side. Thigh: 4 minutes each side.","images":[],"step":3},{"description":"Transfer to plate, cover loosely with foil for 3 minutes. Slice.","duration":3,"images":[],"step":4},{"description":"Add dill into remaining dressing. Shake.","images":[],"step":5},{"description":"Place remaining salad ingredients in a bowl. Top with chicken.","images":[],"step":6},{"description":"Drizzle dressing all over. Crumble over bacon if using. Serve immediately!","images":[],"step":7}]', '["mustard"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","quick-and-easy","salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_902ae41fc7cd', 'en', 'US', 'Mexican Avocado Chicken Salad', 'Recipe video above (see how I scoop out avocado!) A fully loaded salad, satisfying to have as a meal! Crunchy lettuce, creamy avocado corn and tomato salsa, marinated Mexican chicken drizzled with a lime dressing. Makes 2 meal size servings or 3 normal servings. Marinate 30 min.', 'https://www.recipetineats.com/tachyon/2017/05/Mexican-Chicken-Salad-4.jpg', 15, 8, 23, 3, '[{"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_honey", "quantity": {"value": 0.03, "unit": "jar of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 0.6, "unit": "punnet of 250g"}}, {"id": "ing_corn", "quantity": {"value": 0.003, "unit": "can of 400g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_lettuce", "quantity": {"value": 5.0, "unit": "head"}}]', '[{"ingredients":["2 tbsp lime juice","1 tbsp honey","1/4 cup olive oil (65ml)","1 garlic clove, minced","½ tsp salt + black pepper"],"purpose":"Lime Dressing / Marinade:"},{"ingredients":["2 small chicken breasts, 400g/14oz (pound or split if thicker than 2cm / 4/5”)","1/2 tsp EACH chipotle powder (Note 1) and oregano","1/4 tsp cumin powder","Salt & pepper","1/2 tbsp olive oil"],"purpose":"Chicken:"},{"ingredients":["1 avocado, chunky dice (watch video to see how I do this)","1 cup cherry tomatoes, halved","¾ cup corn kernels (canned, drained)","½ red onion, finely chopped"],"purpose":"Avocado Salsa:"},{"ingredients":["1/4 cup coriander / cilantro, finely chopped","5 heaped cups cos / romaine lettuce, cut into bite size pieces"],"purpose":"Salad:"}]', '[{"description":"Place Lime Dressing ingredients in a jar, shake well.","images":[],"step":1},{"description":"Put 2 tablespoons of Dressing in a ziplock bag. Add chipotle, oregano, cumin, salt and pepper, mix/squidge bag. Add chicken, seal and massage to coat. Marinate 30 min – overnight.","images":[],"step":2},{"description":"Heat 1 tbsp olive oil in skillet over medium low, cook chicken to taste (2cm / 4/5” takes around 8 minutes), getting a nice brown crust on it. Rest 5 min then slice.","images":[],"step":3},{"description":"Add 2 tablespoons of coriander into Dressing, shake.","images":[],"step":4},{"description":"Place avocado, corn, tomato and onion in a bowl. Add remaining coriander, drizzle with a bit of Dressing, toss gently.","images":[],"step":5},{"description":"Place lettuce in a bowl, drizzle with a bit of Dressing, toss.","images":[],"step":6},{"title":"Assemble Salad","description":"Place lettuce on a serving platter. Top with Salsa and sliced chicken. Drizzle with remaining Dressing. Serve.","images":[],"step":7}]', '[]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["chicken-breast-recipes","chicken-recipes","mexican-recipes","quick-and-easy","salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_aa81cb546061', 'en', 'US', 'Chicken Tikka Masala', 'Recipe VIDEO above. Make this iconic curry at home!!! It''s a stunner - and although there''s an extensive looking list of ingredients, it''s astonishingly straight forward. Far better than paste in a jar, less oily than restaurants, and you can get everything you need from supermarkets!Spice level: Low. Marinating time: 3 - 24 hours', 'https://www.recipetineats.com/tachyon/2018/04/Chicken-Tikka-Masala_0.jpg', 15, 45, 60, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.15, "unit": "tub of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 10.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garam_masala", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_turmeric", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_tomato", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.417, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.4, "unit": "carton of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["600g/ 1.2lb chicken thigh (boneless, skinless), cut into 3cm / 2.2\" cubes (Note 1)","1/2 cup plain yoghurt, ( full fat best (Greek is fine))","6 cloves garlic (, minced (~1.5 tbsp))","1 tbsp fresh ginger (, grated)","1 tsp garam masala (Note 2)","1 tsp each salt, cumin, ground coriander, paprika (sweet, normal or smokey)","1 tbsp vegetable oil","1/8 tsp cayenne pepper (optional)","Pinch black pepper","2 tsp lemon juice"],"purpose":"Chicken Tikka Marinade:"},{"ingredients":["1 - 2 tbsp oil (Note 3)"],"purpose":"Cooking Chicken:"},{"ingredients":["2 tsp turmeric","1 tbsp garam masala (Note 2)","2 tsp coriander","1 tsp cumin","1/8 tsp cardamom powder","1/8 tsp cayenne pepper"],"purpose":"Curry Sauce Spices:"},{"ingredients":["3 tbsp (65ml) vegetable oil (Note 3)","30g / 2 tbsp unsalted butter OR ghee","1 onion, finely chopped (brown, white or yellow)","1 tsp salt","2 tbsp fresh ginger (, grated)","6 cloves garlic (, crushed or grated)","1 tbsp paprika (not smoked)","1 2/3 cups (400ml) tomato passata (tomato puree)","1 2/3 cups (400ml) water","100 ml (1/3 cup + 1 tbsp) cream (thickened or pure is fine)","1 tsp sugar","50g / 3 tbsp unsalted butter OR ghee"],"purpose":"Curry Sauce:"},{"ingredients":["Basmati rice"],"purpose":"Serving"}]', '[{"description":"Combine all ingredients except chicken in a bowl and mix. Add chicken and turn well to coat.","images":[],"step":1},{"description":"Cover with cling wrap and leave in fridge to marinate overnight (3 hours minimum).","images":[],"step":2},{"description":"Heat 1 tbsp oil in a non stick pan over high heat until smoking. Add half the chicken and spread out. Leave for 2 minutes or until charred. Turn each piece and cook the other side until charred - don''t worry if not cooked inside. (Note 4, also Video helpful here) Remove into bowl.","duration":2,"images":[],"step":3},{"description":"Scrape out charred bits left in pan and discard. Add more oil if required and cook remaining chicken.","images":[],"step":4},{"description":"Wipe skillet with paper towels (or do this part in a pot as you need a lid). Turn heat down to medium high.","images":[],"step":5},{"description":"Add oil and butter. When butter is melted, add onions, ginger and salt.","images":[],"step":6},{"description":"Cook, stirring constantly to ensure it doesn''t burn, until the ginger is starting to turn golden and the onions smell sweet, about 5 - 7 minutes.","images":[],"step":7},{"description":"Reduce the heat to medium. Add the garlic and paprika, and cook for 2 minutes.","duration":2,"images":[],"step":8},{"description":"Add the Curry Sauce Spices, and cook a further 2 minutes, stirring.","images":[],"step":9},{"description":"Add tomato passata and water, and mix. Bring to a simmer, then cover and reduce heat to low.","images":[],"step":10},{"description":"Simmer for 15 minutes, stirring occasionally.","duration":15,"images":[],"step":11},{"description":"Pour curry into a bowl, then use a stick blender to puree until smooth (Note 5).","images":[],"step":12},{"description":"Return sauce to skillet. Add cream, sugar and butter. Stir to melt the butter.","images":[],"step":13},{"description":"Add chicken, stir. Simmer for a few minutes until the chicken is cooked through.","images":[],"step":14},{"title":"Optional","description":"Sprinkle with a pinch of extra garam masala at the end.","images":[],"step":15},{"description":"Serve over basmati rice, sprinkled with coriander/cilantro if desired. Try this No Yeast Flatbread as a quick naan!","images":[],"step":16}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["chicken-breast-recipes","chicken-recipes","curry-recipes","dietary","gluten-free-recipes","iconic-dishes","indian-recipes","main-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_94039338708c', 'en', 'US', 'Oven Baked Chicken with Rice Pilaf (Cranberry, Walnut and Apple)', 'The RICE PILAF in this recipe is sensational. Tastes savoury but with a touch of apple sweetness, herby fragrance, combined with plump cranberries, warm crunch of walnuts, and with fresh apple providing a fabulous finishing touch. The chicken is sticky from the jam (great shortcut trick) and savoury from the seasoning spices. The key step that makes a real difference is "oven sautéing" onion and garlic first. Festive inspired midweek meal to have all year round! Recipe VIDEO below.', 'https://www.recipetineats.com/tachyon/2017/12/Baked-Chicken-with-Rice-Pilaf-2.jpg', 15, 65, 80, 5, '[{"id": "ing_chicken_thigh", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_white_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_apples", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_cranberries", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_walnuts", "quantity": {"value": 150.0, "unit": "jar"}}, {"id": "ing_apples", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_rosemary", "quantity": {"value": 0.075, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_jam", "quantity": {"value": 0.135, "unit": "jar of 370g"}}, {"id": "ing_mustard", "quantity": {"value": 0.188, "unit": "jar of 200g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 50.0, "unit": "bottle"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["5 chicken thigh fillets (, bone in (about 220g / 7oz each) (Note 1))"]},{"ingredients":["1 small onion (, finely chopped)","1 garlic clove (, minced)","50g (3.5 tbsp) unsalted butter (or sub with oil of choice)","1 1/2 cups (270g) long grain white rice (, uncooked (Note 2))","1 1/4 cups (315 ml) apple juice","1 1/2 cups (375 ml) chicken broth","1 cup (120g) dried cranberries (or other dried fruit of choice)","1 cup (125g) walnuts , roughly chopped (or other nuts of choice)","1 red apple (, cut into small dice)"],"purpose":"Rice:"},{"ingredients":["3/4 tsp dried rosemary","1 tsp dried thyme","3/4 tsp salt","1/2 tsp pepper"],"purpose":"Rice Herbs:"},{"ingredients":["1/3 cup (100g) apricot jam (or other jam - Note 3)","2 1/2 tbsp Dijon mustard","1/2 tsp garlic powder","1/2 tsp All Spice","1/4 tsp paprika","3/4 tsp salt","1/4 tsp black pepper"],"purpose":"Sticky Chicken Glaze:"},{"ingredients":["Oil spray","Fresh parsley (, finely chopped)"],"purpose":"Garnish (optional):"}]', '[{"description":"Preheat oven to 200C/390F (standard) or 180C/350F (fan/convection).","images":[],"step":1},{"description":"Use a baking dish about 22 x 33cm / 9 x 13\".","images":[],"step":2},{"description":"Scatter onion and garlic in baking dish, dollop butter over. Bake for 15 minutes, then remove.","duration":15,"images":[],"step":3},{"description":"If your chicken has skin on it, remove it (just pull it off). Otherwise, the rice will be too greasy.","images":[],"step":4},{"description":"Whisk together Sticky Chicken Glaze. Add chicken, turn to coat.","images":[],"step":5},{"description":"Add rice, apple juice, chicken broth and Rice Herbs into the pan with the onion. Stir.","images":[],"step":6},{"description":"Add cranberries and walnuts. Stir.","images":[],"step":7},{"title":"Top with chicken","description":"it will be partly submerged. Save glaze in bowl.","images":[],"step":8},{"title":"Cover with foil. Bake 20 minutes. Remove foil","description":"don''t worry if there''s still liquid (Note 4).","images":[],"step":9},{"title":"Spoon all remaining Glaze onto chicken. Optional","description":"spray with oil (gives chicken a slightly nicer finish). Bake for another 30 - 35 minutes until chicken is browned.","images":[],"step":10},{"description":"Remove pan from oven. Rest 5 minutes. Remove chicken, add apple, then use fork to fluff rice.","images":[],"step":11},{"description":"Serve chicken with rice pilaf, garnished with fresh parsley if desired.","images":[],"step":12}]', '["milk","mustard"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","one-pot-recipes","quick-and-easy","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_968c3ab634e5', 'en', 'US', 'Garlic Herb Butter Roasted Turkey Breast', 'RECIPE VIDEO above. An incredible way to roast turkey breast! The garlic herb butter smeared under the skin bastes the breast while it roasts, and creates a butter pan sauce to serve on the side. A meat thermometer will ensure your turkey comes out beautifully juicy. Truly worth using fresh herbs for this recipe, but see notes for dried options.', 'https://www.recipetineats.com/tachyon/2017/11/Herb-Garlic-Butter-Roast-Turkey-Breast-4.jpg', 20, 90, 110, 6, '[{"id": "ing_5_6_lb_single_turkey_breast", "quantity": {"value": 2.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_rosemary", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 4.0, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 4.0, "unit": "pack of 3 heads"}}, {"id": "ing_sage", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_rosemary", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["2.5 - 3 kg / 5-6 lb single turkey breast (, skin on, bone in (Note 1), NOT BRINED)","1/2 tsp salt","Black pepper","Small bunch of fresh herbs - 4 rosemary sprigs (, 8 sprigs sage, 10 thyme sprigs)","12 garlic cloves (, smashed with side of knife (see video))"]},{"ingredients":["150 g / 5 oz (10 tbsp) unsalted butter, softened","1 1/4 tsp table salt or 1 1/2 tsp kosher salt","1/2 tsp black pepper","4 large garlic cloves (, minced)","1 tbsp finely chopped sage (, fresh)","1 tbsp finely chopped rosemary (, fresh)","1 tbsp fresh thyme leaves (, fresh)","1 tbsp finely chopped parsley leaves (, fresh)"],"purpose":"Butter:"}]', '[{"title":"Remove fridge chill","description":"Take turkey out of the fridge 45 minutes before cooking (or 30 minutes if it''s super hot where you are).","images":[],"step":1},{"description":"Preheat oven to 200C / 390F (all oven types). Put rack in the lower middle position. (Note 3)","images":[],"step":2},{"description":"Place garlic and bunch of herbs in the middle of a baking dish. (Note 4)","images":[],"step":3},{"title":"Butter","description":"Mix Butter ingredients together.","images":[],"step":4},{"title":"Loosen skin","description":"Use an upside teaspoon to help loosen the skin from the turkey flesh (easiest to go under the paper thin layer under the surface skin). Video helpful here.","images":[],"step":5},{"title":"Smear butter under skin","description":"Use about 2/3 of the butter, and smear it under the skin on the top half of the breast. Best to smear using hands under the skin (not on surface), to ensure it spreads as evenly as possible.","images":[],"step":6},{"description":"Turn turkey upside down. Reserve about 2 tbsp butter for the surface, smear the rest on the underside.","images":[],"step":7},{"description":"Place turkey in pan on the herbs, skin side up. Now smear skin with remaining butter - you don''t want much on the skin because the herb bits burn.","images":[],"step":8},{"title":"STOP HERE for make ahead option","description":"the turkey can be left like this for up to 24 hours. Remove from fridge 45 minutes before serving then proceed.","images":[],"step":9},{"description":"Sprinkle top and sides of breast with salt and pepper all over. Place turkey in oven, turn DOWN to 180C/350F.","images":[],"step":10},{"description":"Roast for 1 hr 30 minutes, basting all over every 30 minutes. (Note 5)","duration":60,"images":[],"step":11},{"title":"COOK TIME / INTERNAL TEMPERATURE","description":"The turkey is cooked when the meat thermometer inserted at the thickest part is 74C/165F. I check in several places. Allow 15 minutes per 500g/1 lb of turkey. My 2.8 kg / 5.5lb bone in turkey took 1 hr 40 minutes.","images":[],"step":12},{"description":"COVER turkey with foil when it becomes golden to your taste, at any point during the cook time (1 hr 15 minutes for me).","images":[],"step":13},{"title":"Rest","description":"Remove turkey from pan and place on serving plate. Cover loosely with foil and rest for 15 to 20 minutes before carving.","duration":17.5,"images":[],"step":14},{"description":"Butter Sauce (Note 6):","images":[],"step":15},{"description":"The pan will have melted butter and roasting juices. Remove herbs and garlic, squeezing out juices. Pour sauce into jug, serve with turkey.","images":[],"step":16},{"title":"Gravy option","description":"see Note 11. I personally love using the butter, but I understand if you feel the need for gravy!","images":[],"step":17}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-recipes","dietary","gluten-free-recipes","main-dishes","roasts","turkey-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_303938c20540', 'en', 'US', 'BAKED Chicken Meatballs with Spaghetti', 'Recipe VIDEO above. Golden brown on the outside, soft and juicy on the inside, these Baked Chicken Meatballs are lip smackingly delicious! Pass them around with ketchup at a gathering or make Spaghetti and Meatballs!', 'https://www.recipetineats.com/tachyon/2017/09/Baked-Chicken-Meatballs-2.jpg', 20, 25, 45, 4, '[{"id": "ing_chicken_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_basil", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}]', '[{"ingredients":["500 g/1lb chicken mince (ground chicken), or turkey or pork (Note 1)","1/4 small white onion (, grated into the bowl)","1/2 cup panko breadcrumbs","1/3 cup grated parmesan","1 large garlic clove (, minced)","1/4 cup finely chopped parsley (or 2 tsp dried parsley or basil)","1 egg","1/4 tsp salt","1/2 tsp pepper","Olive oil spray (or olive oil)"],"purpose":"Meatballs:"},{"ingredients":["1 tbsp olive oil","1 garlic clove (, finely chopped)","3/4 small onion , finely chopped","800 g / 28 oz crushed tomato","1 cup / 250 ml water (swirl in tomato can to clean out)","Handful basil leaves (, torn, or 1 tsp dried herbs (e.g. Italian mix, oregano, thyme, basil))"],"purpose":"Pasta Sauce:"},{"ingredients":["250 g/ 1/2 lb spaghetti or other long strand pasta of choice (, cooked per packet)","Fresh basil (, optional)","Parmesan cheese"],"purpose":"Serving:"}]', '[{"description":"Preheat oven to 200C/390F (standard) or 180C/350F (fan/convection).","images":[],"step":1},{"description":"Place a rack on a tray, and spray the rack with oil.","images":[],"step":2},{"description":"Place Meatball ingredients in a bowl, mix well. Scoop up a heaped tablespoon, roll into a ball and place on the rack. Repeat with remaining mixture - should make 25 - 30. Tip: spray hands with oil or wet lightly with water.","images":[],"step":3},{"description":"Spray each ball well with oil, then bake for 25 minutes until golden brown. Give ''em a squeeze and you''ll see how soft they are!","duration":25,"images":[],"step":4},{"description":"Heat oil in a large skillet over medium high heat. Add garlic and onion, cook for 2 - 3 minutes until translucent. Add tomato and water, stir then turn heat down to medium. Simmer for 5 - 10 minutes, then season to taste with salt and pepper and stir through basil (or use dried herbs).","duration":2.5,"images":[],"step":5},{"description":"Cook pasta in a large pot of boiling water. Drain then return pasta to the same pot.","images":[],"step":6},{"description":"Add Sauce and meatballs, toss.","images":[],"step":7},{"description":"Serve, garnished with fresh basil and parmesan.","images":[],"step":8}]', '["egg","gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-mince-recipes","chicken-recipes","dinner-tonight","italian-recipes","main-dishes","meatball-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0ce59a76942f', 'en', 'US', 'Baked Balsamic Chicken', 'Recipe video above! No marinating required, just mix together a simple sauce, pour it over the chicken and bake. You will be amazed how incredible it tastes - and how sticky they are! PS If using the recipe scaler (hover over Servings), please read notes.', 'https://www.recipetineats.com/tachyon/2017/04/Balsamic-Baked-Chicken-4.jpg', 5, 50, 55, 4, '[{"id": "ing_chicken_thigh", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.25, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.15, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.125, "unit": "jar of 500g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}]', '[{"ingredients":["1 kg / 2 lb chicken thighs (5 pieces, bone in, skin on), or drumsticks or wings (any combination) (Note 1)"]},{"ingredients":["1/4 cup (65 ml) balsamic vinegar","2 1/2 tbsp / 50 ml soy sauce (, all purpose or light (not dark soy sauce))","1/4 cup (85 g / 65 ml) honey","1/4 cup (45g) brown sugar (, loosely packed (Note 2))","2 garlic cloves, minced (or 1 1/2 tsp garlic paste from jar)"],"purpose":"Sauce:"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Line a baking dish with foil and baking / parchment paper.","images":[],"step":2},{"description":"Mix together Sauce in a bowl.","images":[],"step":3},{"description":"Place chicken in baking dish, skin side down for thighs and wings. Make sure the pan is big enough so the chicken is squished up next to each other (sauce may not reduce enough), but not so large that there is more than 4\"/10 cm between every piece of chicken (sauce may reduce too much).","images":[],"step":4},{"description":"Pour over Sauce. Bake 30 minutes. Turn chicken over, spoon over sauce.","images":[],"step":5},{"description":"Bake 20 minutes or until chicken is cooked through. The Sauce should have thickened.","images":[],"step":6},{"description":"Stand for 5 minutes, then spoon Sauce over chicken and serve.","duration":5,"images":[],"step":7}]', '["gluten","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_edc77abe1b6b', 'en', 'US', 'One Pot Italian Chicken & Orzo / Risoni Pasta', 'RECIPE VIDEO ABOVE. A super tasty and quick meal all made in one pot! Chicken infused with Italian flavours and a rich tomato basil orzo / risoni pasta. Refer to the notes for how to skip the marinating time and also how to cook the chicken WITH the risoni. Feel free to add or substitute the capsicum / bell peppers in this!', 'https://www.recipetineats.com/tachyon/2017/01/One-Pot-Italian-Chicken-and-Tomato-Basil-Risoni.jpg', 10, 25, 35, 4, '[{"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.45, "unit": "pack of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_basil", "quantity": {"value": 0.1, "unit": "bunch"}}]', '[{"ingredients":["2 tbsp white wine vinegar","1 tbsp olive oil","1 tsp Dijon mustard","1 tsp Italian herb mix (or make your own with basil, parsley, oregano)","1 garlic clove (, minced)","1/2 tsp salt + black pepper"],"purpose":"Marinade"},{"ingredients":["1 tbsp olive oil","4 x 110 - 120g/4oz chicken breasts (, skinless and boneless (Note 1))"],"purpose":"Chicken"},{"ingredients":["1/2 tbsp olive oil (if required)","1 small onion (, finely chopped (brown, white, yellow))","1 garlic clove (, minced)","1 red capsicum / bell pepper (, chopped)","1 1/2 cups risoni / orzo pasta (Note 2)","400 g / 14 oz can crushed tomato","3 cups chicken stock / broth","1 tsp Italian herb mix","Pinch of red pepper flakes (chilli flakes) (optional)","Salt and pepper","1/4 cup (3 tbsp) grated parmesan cheese (optional)","1 cup basil leaves"],"purpose":"Risoni"}]', '[{"description":"Mix Marinade ingredients together in a large bowl. Add chicken and mix to coat. Marinate for 1 hour - 24 hours (See Note 3 to skip marinating).","images":[],"step":1},{"description":"Heat oil in skillet over medium heat. Add chicken and cook for 4 minutes on each side, or until cooked. Transfer to a plate and cover with foil to keep warm while resting.","duration":4,"images":[],"step":2},{"description":"Turn heat up to medium high. Add oil if required.","images":[],"step":3},{"description":"Add onion and garlic, cook for 2 minutes. Add capsicum and cook for 1 minute or until onion is translucent.","duration":2,"images":[],"step":4},{"description":"Add risoni, tomato, chicken stock, Italian herbs, red pepper flakes, salt and pepper. Mix and bring to simmer, then lower heat to medium low or so it simmers gently.","images":[],"step":5},{"title":"Cook for 9","description":"10 minutes, stirring frequently (otherwise it will stick).","duration":9.5,"images":[],"step":6},{"description":"Take it off the stove when the risoni is just cooked (touch under is ok, finishes cooking in residual heat very quickly). It should still be saucy (see video).","images":[],"step":7},{"title":"Stir through parmesan and basil","description":"excess liquid will evaporate in this step.","images":[],"step":8},{"description":"Spoon risoni into serving bowls, top with chicken. Serve with extra parmesan and basil.","images":[],"step":9}]', '["gluten","milk","mustard"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["chicken-breast-recipes","chicken-recipes","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_31dcc08f179e', 'en', 'US', 'Oven Baked Chicken Quesadillas', 'This is how to make multiple Quesadillas in one batch, rather than making them one by one on the stove! They are crispy and stuffed with Fajita flavoured chicken, onion, capsicum/bell peppers and of course cheese. Use this technique to make quesadillas with anything you want - just ensure you cool the filling. See recipe VIDEO below the recipe to see how crispy these are!', 'https://www.recipetineats.com/tachyon/2016/12/Baked-Chicken-Quesadillas-7.jpg', 15, 16, 31, 4, '[{"id": "ing_chicken", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_tortillas", "quantity": {"value": 4.0, "unit": "pack of 8"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}]', '[{"ingredients":["400 g / 14 oz chicken (, cut into small bite size pieces (thigh, breast or tenderloin))","1 tsp cumin powder","1 tsp garlic powder (or sub with onion powder)","1/2 tsp cayenne pepper (or adjust to taste)","1 tsp paprika powder","1/2 tsp salt + black pepper","1 tbsp olive oil"],"purpose":"Chicken"},{"ingredients":["1 tbsp olive oil","1/2 small onion (, diced (brown, white, yellow))","1 garlic clove (, minced)","1 red capsicum / bell pepper (, diced)","1 green capsicum / bell pepper (, diced)"],"purpose":"Filling"},{"ingredients":["4 flour tortillas (20cm/8\")","Olive oil spray","1 cups grated cheese, or more to taste (tasty, cheddar, Monterey Jack, Pepper Jack or other melting cheese of choice) (Note 1)"],"purpose":"Quesadillas"}]', '[{"description":"Place Chicken ingredients in a bowl and mix to coat chicken.","images":[],"step":1},{"description":"Heat oil in skillet over high heat. Add onion and garlic, cook for 1 minute. Then add capsicum and cook for 2 minutes until starting to soften. Transfer into bowl.","duration":1,"images":[],"step":2},{"description":"Return skillet to the stove. Add chicken and cook until browned. Add to same bowl. Set aside until the filling cools (to speed it up, cover and refrigerate, and/or spread out on plate).","images":[],"step":3},{"description":"Preheat oven to 220C / 430F (standard) or 200C/390F (fan / convection).","images":[],"step":4},{"description":"Spray baking tray lightly with olive oil. Heat in the oven while you assemble the quesadillas.","images":[],"step":5},{"description":"Divide the filling between the tortillas, covering half the surface. Top with cheese. Fold in half and press down gently but firmly.","images":[],"step":6},{"description":"Remove baking tray from oven. Transfer quesadillas onto tray (you should hear a soft sizzle).","images":[],"step":7},{"description":"Bake for 8 minutes. Then turn the quesadillas (over the folded edge) then press down with the egg flip. Bake for a further 8 minutes or until the surface is crispy.","duration":8,"images":[],"step":8},{"description":"Remove from oven and serve immediately!","images":[],"step":9}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Tex-Mex"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","mexican-recipes","most-popular","quesadillas","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1b53ba108fe9', 'en', 'US', 'Creamy Chicken and Bacon Pasta', 'Recipe video above. This is for those days when you just need a really, really great creamy pasta but you want to keep it simple. The pops of bacon in this is sooo good, and the sauce is utterly luxurious and unapologetically rich, saucier than a classic Alfredo.But, for those days when you want to go all out, make the Creamy Chicken Pasta of My Dreams (it''s more loaded, and name-worthy!).', 'https://www.recipetineats.com/tachyon/2016/12/Creamy-Chicken-Bacon-Pasta-4.jpg', 5, 15, 20, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.34, "unit": "pack of 500g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.34, "unit": "pack of 500g"}}, {"id": "ing_bacon", "quantity": {"value": 5.0, "unit": "pack of 200g"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.17, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}]', '[{"ingredients":["6 oz / 180 g fettuccine (or other long strand pasta)","3/4 cup pasta cooking water (, scoop out just before draining)","5 -7 oz / 150 - 200 g bacon (, chopped)","6 oz / 180g chicken breast (, cut in half horizontally (1 large))","1/4 tsp each salt and pepper (, for seasoning chicken)"]},{"ingredients":["1 tbsp (15 g) unsalted butter","2 garlic cloves (, finely minced)","1/2 small onion (, finely chopped (brown, white or yellow))","3/4 cup heavy cream / thickened cream (or any full fat cream)","1/4 tsp each salt and pepper (, for sauce)","1/2 cup finely shredded parmesan (or 1/4 cup store bought grated) (Note 2)"],"purpose":"Creamy pasta sauce"},{"ingredients":["Fresh parsley","Parmesan"],"purpose":"To Serve"}]', '[{"description":"Cook pasta per packet minus 2 minutes, reserve 1 cup pasta water before draining. Cook bacon, then chicken, sauté garlic and onion, simmer with cream, 3/4 cup pasta water, parmesan, salt and pepper. Toss with pasta 1 1/2 minutes, TASTE to check for salt. Serve with parmesan.","images":[],"step":1},{"title":"Cook pasta","description":"Bring a large pot of salted water to boil. Add pasta and cook for time per packet MINUS 2 minutes (finishes cooking in Sauce).","images":[],"step":2},{"title":"RESERVE water (important!)","description":"SCOOP OUT 1 cup (250ml) of pasta cooking water, then drain.","images":[],"step":3},{"title":"Cook bacon","description":"Meanwhile, heat the oil in a non-stick pan and cook bacon until golden. Remove and drain on paper towels, reserve bacon fat in pan.","images":[],"step":4},{"title":"Cook chicken","description":"Season chicken on both sides with the salt and pepper. Cook in the bacon fat for 2 minutes on each side. Remove, then cut into thick slices when cool enough to handle (do this while sauce is simmering).","duration":2,"images":[],"step":5},{"description":"Wipe pan (optional) using paper towels to keep sauce pretty and white, and for a buttery clean tasting sauce rather than very bacon-y (Note 3).","images":[],"step":6},{"title":"Sauté onion","description":"Over medium heat using the same pan, melt the butter. Add garlic and onion, cook for 3 - 4 minutes until onion is light golden and soft.","duration":3.5,"images":[],"step":7},{"title":"Make sauce","description":"Add cream, about 3/4 cup pasta water, parmesan, salt and pepper. Stir, then simmer for 2 minutes until it reduces slightly - the sauce will still be a too thin, don''t worry, it thickens in the next step.","duration":2,"images":[],"step":8},{"description":"Add pasta and toss gently in the sauce for about 1 1/2 minutes, still on the stove. The sauce will thicken and coat the pasta rather than pooling in the pan. Do this step until you get the sauce consistency you want. If your sauce gets too thick, add a splash of pasta water.","images":[],"step":9},{"title":"Toss and taste","description":"Toss through bacon and chicken. Taste and add more salt if needed (depends on bacon saltiness).","images":[],"step":10},{"title":"Serve","description":"Serve immediately, garnished with parmesan and parsley!","images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d510a78a7505', 'en', 'US', 'Honey Mustard Chicken', 'This is a homemade version of the popular Honey Mustard simmer sauces sold at supermarkets. The Honey Mustard Sauce is slightly tangy, sweet and beautifully creamy. Great for chicken, pork, turkey and fish. **ADJUST SERVINGS by using the slider!**', 'https://www.recipetineats.com/tachyon/2016/08/Honey-Mustard-Chicken_2.jpg', 7, 10, 17, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.037, "unit": "jar of 400g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.013, "unit": "pack of 400g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_chicken", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.188, "unit": "jar of 200g"}}, {"id": "ing_honey", "quantity": {"value": 0.125, "unit": "jar of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.188, "unit": "jar of 200g"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["700 g / 1.4 lb chicken tenderloin or chicken breast cut into thick strips (Note 1)","Salt and pepper"]},{"ingredients":["2 tbsp flour","1 tsp garlic powder"],"purpose":"Seasoning (optional – Note 2)"},{"ingredients":["1 tbsp mayonnaise (Note 3)","1 tsp cornstarch / cornflour or 2 tsp flour"],"purpose":"Thickener"},{"ingredients":["1 1/2 tbsp + 1/2 tbsp olive oil","2 cloves garlic (minced)","1 cup chicken broth / stock (250ml)","1/4 cup Dijon mustard (70g)","1/4 cup honey (85g)"],"purpose":"Sauce"},{"ingredients":["1 - 2 tbsp wholegrain mustard, adjust to taste","2 tsp sprigs thyme or 1/2 dried thyme (Note 4)","Fresh parsley, finely chopped"],"purpose":"Optional Extras (I used these)"}]', '[{"description":"Sprinkle chicken with salt and pepper, then toss with Seasoning if using.","images":[],"step":1},{"title":"Thickener","description":"In a small bowl, mix together the mayonnaise and flour.","images":[],"step":2},{"description":"Heat 1 1/2 tbsp oil in a skillet over medium high heat. Add chicken and cook for 2 minutes on each side or until golden. Remove onto a plate.","duration":2,"images":[],"step":3},{"description":"Reduce heat to medium. Add remaining oil in the middle of the skillet and put garlic straight onto the puddle of oil. Sauté for 20 seconds or until golden (don''t let it burn).","duration":0.3333333333333333,"images":[],"step":4},{"description":"Add chicken broth, bring to simmer, scraping the bottom of the fry pan.","images":[],"step":5},{"description":"Whisk in Dijon Mustard and honey, then whisk in Thickener (make sure you scrape it all in).","images":[],"step":6},{"description":"Add thyme and wholegrain mustard, if using.","images":[],"step":7},{"title":"Cook for 1","description":"2 minutes or until starting to thicken. Adjust salt and pepper to taste.","duration":1.5,"images":[],"step":8},{"description":"Return chicken and any juices pooled on the plate into the sauce. Turn to coat and reheat through - about 1 1/2 minutes - or until sauce is thickened to your taste.","images":[],"step":9},{"description":"Serve on mashed potato, garnished with parsley, with a simple side salad.","images":[],"step":10}]', '["gluten","mustard"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_74fb2f46ddf5', 'en', 'US', 'Chicken & Mushroom Risotto', 'The new way to make risotto that comes out just as creamy as the traditional method: no heating up the broth, no need to add it gradually and no need to stir constantly! The bacon garnish is optional but honestly, it is so worth the effort. Also, I use the bacon fat in the pot to cook the chicken and mushrooms. Why waste the free flavour? :)', 'https://www.recipetineats.com/tachyon/2016/08/Chicken-Mushroom-Risotto_4.jpg', 10, 40, 50, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_bacon", "quantity": {"value": 0.354, "unit": "pack of 200g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.34, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.369, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_arborio_rice", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.34, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 tsp - 1 tbsp olive oil","2.5 oz / 75 g bacon (preferably streaky / fatty) (optional)","12 oz / 350 g chicken thigh fillets (, cut into bite size pieces)","13 oz / 400 g mushrooms (, sliced (I use Swiss brown))","2 tbsp / 30 g unsalted butter","2 garlic cloves (, minced)","1 onion (, finely diced (brown, white, yellow))","1/2 cup / 125 ml white wine (optional - sub with water or chicken broth)","1 1/4 cups / 250 g arborio risotto rice (, uncooked (Note 1))","4 cups / 1 litre chicken broth/stock"]},{"ingredients":["1/2 cup / 35 g freshly grated parmesan cheese","1 - 3 tbsp / 15 - 50 g unsalted butter","Freshly chopped parsley"],"purpose":"Finishing"}]', '[{"description":"Heat 1 tsp oil in a pot or skillet (Note 2) over high heat. Add bacon and cook until golden. Transfer to small microwave-proof bowl.","images":[],"step":1},{"title":"Leave about 1 tbsp bacon fat in pot","description":"discard excess. Add chicken* and cook until browned and cooked through. Transfer to separate bowl.","images":[],"step":2},{"description":"Add mushrooms* and cook until light golden. Add to bowl with chicken.","images":[],"step":3},{"description":"Turn heat down to medium and return pot to the stove. Add butter, and melt. Add garlic and onion. Sauté for 3 minutes or until softened.","duration":3,"images":[],"step":4},{"description":"Turn heat up to high, add rice and stir until the grains become partially translucent - no longer than 1 minute. (Note 3)","images":[],"step":5},{"description":"Add wine and cook, scraping the bottom of the pot (to get any brown bits), until the alcohol smell evaporates ~ 2 minutes.","images":[],"step":6},{"description":"Turn heat down to medium low. Add about 3 cups of stock. Then leave it, uncovered, stirring just once or twice, until most of the liquid has been absorbed.","images":[],"step":7},{"description":"Check firmness of rice and add 1/2 cup of stock at a time, stirring in between until absorbed, until the rice is cooked to your taste. (Note 4)","images":[],"step":8},{"description":"Add chicken and mushrooms back into the risotto towards the end, just to heat through.","images":[],"step":9},{"description":"Right at the end when the risotto is ready, add a splash of chicken broth to make the risotto to make it slightly soupy, then take it off the stove.","images":[],"step":10},{"title":"KEY STEP","description":"Add butter (the more the better!) and parmesan, then stir vigorously (activates the starch and makes it super creamy). The excess liquid will evaporate quickly, so add more if you want a soupier risotto, like what you get at posh restaurants.","images":[],"step":11},{"description":"Serve IMMEDIATELY!! (Note5) Garnish with reheated bacon, and extra parmesan and parsley if desired.","images":[],"step":12}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","italian-recipes","main-dishes","mushroom-recipes","quick-and-easy","risotto-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d4d8f52d5211', 'en', 'US', 'Bacon Wrapped Chicken', 'Juicy chicken wrapped in bacon, baked to golden perfection and slathered in gorgeous bacon juices! The brown sugar makes the bacon extra tasty and the Seasoning gives the chicken even more flavour. Simple and ridiculously delicious!', 'https://www.recipetineats.com/tachyon/2016/08/Bacon-Wrapped-Chicken_2.jpg', 15, 25, 40, 4, '[{"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.6, "unit": "pack of 200g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}]', '[{"ingredients":["1 tsp garlic powder","1 tsp paprika","1/2 tsp cayenne pepper (or sub with more paprika)","1 tbsp flour","1/2 tsp salt","Black pepper"],"purpose":"Seasoning"},{"ingredients":["4 large chicken thigh fillets (about 5oz / 150g each), cut in half (Note 1)","8 pieces bacon (, streaky (Note 2))","2 tbsp brown sugar","1 tsp olive oil (optional)"],"purpose":"Chicken"}]', '[{"description":"Preheat oven to 200C/390F (fan forced / convection) (Note 3)","images":[],"step":1},{"description":"Line tray with baking paper.","images":[],"step":2},{"description":"Combine Seasoning in a small bowl. Place brown sugar in a separate bowl.","images":[],"step":3},{"description":"Coat chicken in Seasoning, shaking off excess. Place on one end of bacon and roll up, finishing with the seam side down. Repeat with remaining chicken.","images":[],"step":4},{"title":"Coat chicken in sugar","description":"use your fingers to rub it on if required. Place on baking tray.","images":[],"step":5},{"description":"Drizzle with olive oil (helps make it brown faster, optional)","images":[],"step":6},{"description":"Bake for 25 minutes. If the bacon is not golden enough for your taste, switch on the broiler for a few minutes.","duration":25,"images":[],"step":7},{"description":"Brush the juices on the tray onto the bacon to make it glossy and juicy. Serve on mashed potatoes, drizzled with extra pan juices if desired!","images":[],"step":8}]', '["gluten"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c02f2a8030e5', 'en', 'US', 'Chicken in White Wine Cream Sauce', 'Chicken in a creamy white wine sauce - comfort food and it''s finest! So simple to make, the key to this recipe is the white wine which transforms into an incredible broth by braising the chicken slowly in it so the chicken is incredibly tender. This is very French-country-chic! :)', 'https://www.recipetineats.com/tachyon/2016/07/Chicken-with-Bacon-White-Wine-Cream-Sauce_6.jpg', 10, 75, 85, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 1.134, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.709, "unit": "pack of 200g"}}, {"id": "ing_wine", "quantity": {"value": 0.667, "unit": "bottle of 750ml"}}, {"id": "ing_chicken", "quantity": {"value": 1.134, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 tbsp olive oil","2.5 lb / 1.2 kg chicken pieces (, bone in thigh & drumsticks are ideal (Note 1))","1 tbsp / 15g / 0.5 oz butter","3 garlic cloves (, crushed)","1 onion (brown, white, yellow), finely chopped (~1 cup)","5 oz / 150 g bacon (, diced)","2 cups / 500 ml dry white wine (Note 2)","1 cup / 250 ml chicken broth / stock or water","2 tsp fresh thyme leaves (or 1 tsp dried)","3/4 cup / 185 ml cream (pouring or heavy cream, but not low fat cream)"]},{"ingredients":["Finely chopped parsley"],"purpose":"Garnish"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Season chicken with salt and pepper. Heat oil in an ovenproof skillet (with lid) over high heat. Add chicken skin side down and cook until golden brown, then turn and cook the other side for 1 minute. Remove chicken from skillet. Drain excess fat from skillet (do not wipe).","duration":1,"images":[],"step":2},{"description":"Reduce heat to medium high. Melt butter then add garlic and onion. Cook for 3 minutes until softened, then add bacon. Cook until golden.","duration":3,"images":[],"step":3},{"description":"Add wine. Bring to simmer, scraping the bottom of the skillet to mix the brown bits into the liquid. Simmer for 2 minutes.","duration":2,"images":[],"step":4},{"description":"Add chicken broth, thyme and return chicken to the skillet, skin side up. Cover with lid or foil, then transfer to the oven. Bake for 60 minutes, covered, then remove the lid and bake for a further 15 minutes to recrisp the skin. The chicken should be very tender.","duration":60,"images":[],"step":5},{"description":"Remove chicken or move to side. Stir cream into sauce and season with salt and pepper to taste.","images":[],"step":6},{"description":"Garnish with plenty of parsley. Serve with creamy mashed potatoes. Mine are pictured with Glazed Carrots.","images":[],"step":7}]', '["milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["French-style"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","main-dishes","one-pot-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fcc52bc66bbc', 'en', 'US', 'Sun Dried Tomato, Spinach & Cheese Stuffed Chicken Breast', 'Chicken breast slathered with an Italian dressing then stuffed with sun dried tomato, spinach and cheese. The chicken breast stays beautifully juicy because it cooks faster than whole chicken breast, even though this is stuffed. Also the juices from the sun dried tomato, cheese and Italian dressing baste the chicken as it roasts!', 'https://www.recipetineats.com/tachyon/2016/06/Sun-Dried-Tomato-Stuffed-Chicken-Breast_5.jpg', 5, 20, 25, 2, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.17, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.28, "unit": "pack of 125g"}}, {"id": "ing_spinach", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["6oz/180g small chicken breasts (2 pieces), boneless and skinless","1/2 cup sun dried tomato (oil packed. Use enough to cover the chicken, cut into strips)","4 slices mozzarella cheese (or other melting cheese of choice)","leaves Handful of spinach","2 tsp olive oil"]},{"ingredients":["1 tbsp Dijon Mustard","1 tbsp white wine vinegar or lemon juice","1/2 tsp sugar, any","2 tsp olive oil","1/2 tsp EACH Italian mixed herbs and red pepper flakes (Note 1)","Salt & pepper"],"purpose":"Italian Dressing"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Whisk together the Italian Dressing ingredients in a bowl. It will be thicker than salad dressing.","images":[],"step":2},{"description":"Cut a pocket into each chicken breast, taking care not to cut all the way though.","images":[],"step":3},{"description":"Coat the chicken (inside and out) with the Italian Dressing.","images":[],"step":4},{"description":"Place chicken on work surface. Stuff with sun dried tomato, top with cheese then finish with spinach leaves. Just stuff in as much as you can.","images":[],"step":5},{"description":"Seal with toothpicks (just stick them in on the diagonal - see photo in post).","images":[],"step":6},{"description":"Heat oil in an ovenproof skillet over high heat. Add chicken and cook for 1 1/2 minutes on each side, or until golden.","images":[],"step":7},{"description":"Transfer to oven and cook for 15 minutes, or until cheese is melted and bubbly and chicken is cooked through. Rest for 3 minutes before serving, drizzled with the juices in the skillet.","duration":15,"images":[],"step":8}]', '["milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ace302a5f57e', 'en', 'US', 'Hawaiian Chicken Salad', 'A giant salad loaded with the tropical flavours of Hawaii! This recipe is based on the marinade for these Hawaiian Chicken Skewers I shared a few weeks ago - see note 1 for how to REUSE the marinade for this recipe. This recipe also uses leftover Coconut Lime Cilantro/Coriander Rice that I shared as a side for the skewers.', 'https://www.recipetineats.com/tachyon/2016/06/Hawaiian-Chicken-Salad-Lime-Dressing_3.jpg', 15, 10, 25, 2, '[{"id": "ing_marinade", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.208, "unit": "can of 400ml"}}, {"id": "ing_pineapple", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_chicken", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_chicken_breast", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.188, "unit": "can of 400g"}}, {"id": "ing_pineapple", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_lettuce", "quantity": {"value": 4.0, "unit": "head"}}, {"id": "ing_avocado", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 1.25, "unit": "pack of 1kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 0.3, "unit": "punnet of 250g"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_dressing", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_ime_juice", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["Marinade ((Note 1):)","1/3 cup coconut milk (from a can)","1/4 cup pineapple juice (from can, save pineapple pieces)","1 tbsp tomato sauce/ketchup","1 tbsp soy sauce","Zest of 1 lime","2 garlic cloves (, minced)","1/4 tsp EACH onion powder (, cumin, paprika, ginger powder, salt)","Chicken & Salad:","1/2 tbsp olive oil","1 large chicken breast (, halved horizontally)","1/2 cup corn","1/2 - 3/4 cup pineapple pieces (from can)","4 - 6 cups chopped lettuce","1/2 avocado (, cut into wedges)","1/2 red onion (, finely sliced)","1/2 cup cherry tomatoes (, halved)","1 small carrot, finely shredded","1 - 1 1/2 cups Coconut Lime Cilantro / Coriander Rice (Note 2)","Dressing:","1 1/2 tbsp lime juice","2 1/2 tbsp olive oil","2 tbsp finely chopped cilantro/coriander","1/2 garlic minced","1/2 tsp sugar or honey","1/4 tsp salt","Black pepper"]}]', '[{"description":"Mix together Marinade ingredients, marinate chicken for minimum 3 hours, preferably overnight.","images":[],"step":1},{"description":"Shake Dressing ingredients together in a jar, set aside for at least 15 minutes.","images":[],"step":2},{"description":"Heat oil in a non stick skillet over high heat (or BBQ). Add chicken and cook each side for 3 minutes or until golden. Remove and cover loosely with foil for 5 minutes, then slice thickly.","duration":3,"images":[],"step":3},{"description":"Sear 1/2 cup pineapple pieces and corn in the skillet until golden.","images":[],"step":4},{"description":"Pile salad ingredients on a platter and top with sliced chicken. Drizzle over Dressing. Serve and pretend you''re in Hawaii!","images":[],"step":5}]', '["gluten","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner","lunch"],"cuisine":["Hawaiian"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","gluten-free-recipes","most-popular","salad-recipes-main-course","tropical"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1accca9710b5', 'en', 'US', 'Oven Fried Parmesan Baked Chicken Tenders', 'These oven fried chicken tenders TRULY come out just like they''ve been fried! They are a beautiful golden brown all over and super crunchy. Make these with chicken tenderloins or cut chicken breast into tenderloin length strips! This is the parmesan flavoured version of these Truly Golden Crunchy Baked Chicken Tenders I shared last year.', 'https://www.recipetineats.com/tachyon/2016/06/Parmesan-Baked-Chicken-Tenders_3.jpg', 15, 15, 30, 3, '[{"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.037, "unit": "jar of 400g"}}, {"id": "ing_mustard", "quantity": {"value": 1.0, "unit": "jar of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["1 cup panko breadcrumbs (Note 1)","Olive oil spray","1/2 cup grated parmesan cheese (, store bought (Note 2))"],"purpose":"Breadcrumb"},{"ingredients":["1 egg","1 tbsp mayonnaise* (I use whole egg mayonnaise)","1½ tbsp dijon mustard* (or any other mustard of choice)","1 garlic clove (, minced*)","2 tbsp plain flour","Salt & pepper"],"purpose":"Batter"},{"ingredients":["500 g /1 lb chicken tenderloins (or chicken breast cut into ⅔\" / 1.5cm thick slices, lengthwise)","Oil spray"],"purpose":"Chicken"}]', '[{"description":"Preheat oven to 200C/390F.","images":[],"step":1},{"description":"Spread panko breadcrumbs on a baking tray. Spray lightly with oil. Bake for 3 to 5 minutes or until LIGHT golden.","duration":4,"images":[],"step":2},{"description":"Scrape into a bowl. Add parmesan and mix.","images":[],"step":3},{"description":"In a separate bowl, whisk together Batter ingredients with a fork. Add chicken and mix to coat.","images":[],"step":4},{"title":"Optional","description":"Place a rack on the baking tray (Note 3)","images":[],"step":5},{"description":"Pick up chicken with left hand and place in breadcrumbs. Use right hand to sprinkle with breadcrumbs, press to adhere. Use right hand to transfer to baking tray. Repeat with remaining chicken. Spray lightly with oil.","images":[],"step":6},{"description":"Bake for 15 minutes for small tenders, 18 minutes for large ones. No longer than 20 minutes, otherwise they will begin to lose juiciness.","duration":15,"images":[],"step":7},{"description":"Serve immediately with Ranch or Honey Mustard Dip if desired (Note 4).","images":[],"step":8}]', '["egg","gluten","milk","mustard"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","low-calorie-recipes","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1066f3c9c080', 'en', 'US', '5 Ingredient Sticky Stove Top Balsamic Drumsticks', 'Sticky chicken drumsticks that are cooked on the stove in half the time it takes to bake! Don''t let the short list of ingredients fool you - the glaze tastes like it has a lot more in it. Adapted from this Sticky Stove Top Chicken recipe from Sparks People. This recipe is NOT suited for scaling up because the glaze will not thicken. Watch the cooking video (in post) to see exactly how this is made - in particular, watch the braising liquid transform into the sticky glaze!', 'https://www.recipetineats.com/tachyon/2015/04/Sticky-Balsamic-Drumsticks_4.jpg', 5, 25, 30, 4, '[{"id": "ing_chicken", "quantity": {"value": 8.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 0.5, "unit": "bottle of 250ml"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.333, "unit": "bottle of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.6, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["8 chicken drumsticks (2 lb / 1 kg) (Note 1)","1 cup water","1/2 cup balsamic vinegar","1/3 cup soy sauce (all purpose or light, not dark)","3 tbsp sugar (brown)","3 garlic cloves (, minced)"]},{"ingredients":["2 tsp fresh grated ginger","2 tbsp Sriracha or 1 tsp red pepper flakes (Note 2)"],"purpose":"Extra Flavourings (Optional)"},{"ingredients":["Parsley or shallots/scallions (, finely sliced)"],"purpose":"Garnishes (optional)"}]', '[{"description":"Combine all ingredients (including Extra Flavourings, if using) in a large skillet/fry pan or pot (Note 3) over medium high heat. The chicken should be in a single layer.","images":[],"step":1},{"description":"Bring to boil, turn chicken, then turn down to medium so it simmers energetically but not rapidly. DO NOT cover the pan with a lid.","images":[],"step":2},{"description":"Cook for 20 minutes, turning the chicken at 10 minutes.","duration":20,"images":[],"step":3},{"description":"At 20 minutes, the chicken should be cooked. Move the chicken to the side of the skillet, propping and stacking them up on the edges of the skillet to clear the surface of the liquid as much as possible so it can reduce.","images":[],"step":4},{"description":"Simmer for 5 minutes or until the liquid thickens (consistency of thick pouring cream) and coats the chicken. Keep an eye on the sauce, once it starts to thicken it will reduce quickly, don''t let it go too far. Roll the chicken in the glaze.","duration":5,"images":[],"step":5},{"description":"Remove the skillet from the stove and stand for 5 minutes - the sauce will thicken slightly more. Roll the chicken in the glaze again, then serve, garnished with parsley or scallions if desired.","duration":5,"images":[],"step":6},{"description":"Serve, garnished with scallions/shallots if using.","images":[],"step":7}]', '["gluten","soy"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-drumstick-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d6addde9f9b4', 'en', 'US', 'Mexican Shredded Chicken', '5 minutes prep is all that''s required for this shredded chicken tossed in a smokey, mildly spicy red sauce that''s loaded with flavour. Make this in your slow cooker, pressure cooker or on the stove - directions provided for all!', 'https://www.recipetineats.com/tachyon/2016/03/Slow-Cooker-Mexican-Chicken_1.jpg', 10, 240, 250, 5, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.68, "unit": "kg"}}, {"id": "ing_chipotles_in_adobo_sauce", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}]', '[{"ingredients":["1.5 lb / 750g chicken breast (, skinless boneless (~3 halves))","1/2 cup Chipotles in Adobo Sauce (4 chillies + sauce) (Note 1)","14 oz / 400g can crushed tomatoes","2 garlic cloves (, crushed)","1 tsp EACH dried oregano, cumin powder and onion powder (or garlic powder)","2 tsp sugar (any)","3/4 tsp salt (Note 2)","Pepper"],"purpose":"Chicken & Sauce"},{"ingredients":["3 tbsp olive oil (Note 3)","2 tbsp lime juice"],"purpose":"To Finish"}]', '[{"description":"Cook Chicken","images":[],"step":1},{"title":"Slow Cooker","description":"Place Chicken & Sauce ingredients in the slow cooker and cook for 4 hours on low. The chicken is ready when it can be shredded easily with 2 forks but it should NOT be mushy (i.e. overcooked).","images":[],"step":2},{"title":"Pressure cooker","description":"35 minutes on high.","images":[],"step":3},{"title":"Stove","description":"Place Chicken & Sauce ingredients in a medium saucepan and add 1 cup water. Simmer covered on medium low for 40 - 50 minutes, turning chicken occasionally, until chicken can be shredded with 2 forks.","duration":45,"images":[],"step":4},{"description":"Remove chicken and shred. Set aside.","images":[],"step":5},{"description":"Add lime juice (to taste) and 1 tbsp olive oil to the sauce. Use a stick blender (or transfer to blender) to puree the sauce. Adjust salt and pepper to taste. You should have about 2 cups of sauce.","images":[],"step":6},{"description":"Brown Chicken","images":[],"step":7},{"description":"Heat 1 tbsp oil in a large skillet over high heat. Add 1/3 to 1/2 the chicken and fry until dark golden brown on one side, flip and cook the other side very briefly (don''t brown), then remove. Use 1 tbsp oil for each batch you fry.","images":[],"step":8},{"description":"To Serve","images":[],"step":9},{"description":"Toss chicken in the sauce OR serve it on the side.","images":[],"step":10},{"description":"Use for tacos (guacamole and Pico de Gallo, enchiladas, burritos, on green Mexican rice, quesadillas, sliders, on tostadas.","images":[],"step":11}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["chicken-breast-recipes","chicken-recipes","main-dishes","mexican-recipes","most-popular","quick-and-easy","slow-cooker-recipes","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0a1591af3a72', 'en', 'US', 'KFC Oven Baked "Fried" Chicken Tenders', 'Crunchy and perfectly seasoned, it really does taste like KFC! It is a mash up of my own recipe, the "11 Secret Herbs and Spices" from the Homemade KFC recipe by Every Nook & Cranny, and the coating recipe from this Best Baked "Fried" Chicken by Carlsbad Cravings.. Marinating makes the chicken extra juicy but if you don''t have time to marinate, this is still worth making! (See Note 3) PS I know it looks like a lot of salt but it''s not overly salty, it''s KFC level salty. Reduce salt and/or celery salt if desired.', 'https://www.recipetineats.com/tachyon/2015/09/KFC-Copycat-Oven-Baked-Fried-Chicken-Tenders_680px_2.jpg', 15, 25, 40, 4, '[{"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_celery", "quantity": {"value": 0.3, "unit": "head"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_basil", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_paprika", "quantity": {"value": 0.75, "unit": "jar of 40g"}}, {"id": "ing_ginger", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_chicken", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_corn", "quantity": {"value": 0.094, "unit": "can of 400g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}]', '[{"ingredients":["1/2 tsp salt","1 tbsp celery salt (Note 1)","2 tsp garlic powder","1/2 tsp dried thyme","1/2 tsp dried basil","1/2 tsp dried oregano","1/2 tbsp coarsely ground black pepper","1 tbsp mustard powder","2 tbsp paprika (not smoked, use sweet or plain)","1 tsp ground ginger","1 tsp cayenne pepper or ground pure chili (optional - for KFC \"Zinger\" flavour!)"],"purpose":"KFC Spice Mix"},{"ingredients":["1.2 - 1.4 lb / 600 - 700 g chicken tenderloin (10 - 12 pieces) (Note 2)","1 cup buttermilk OR 1/3 cup plain yoghurt + 2/3 cup milk (Note 3)","1 cup flour","1 cup panko breadcrumbs","1/4 cup cornmeal (Note 4)","2 tbsp butter (unsalted)","1 tbsp vegetable or canola oil","Oil spray"],"purpose":"Chicken"}]', '[{"description":"Combine the Spice Mix in a bowl.","images":[],"step":1},{"description":"Place 1 tbsp of Spice Mix in a ziplock bag with the chicken and buttermilk. Set aside to marinate for at least 2 hours, preferably 3 but ideally overnight.","images":[],"step":2},{"description":"To Cook","images":[],"step":3},{"description":"Preheat oven to 400F/200C.","images":[],"step":4},{"description":"Place the butter and oil on a large rimmed baking tray. Place in the oven for a few minutes until the butter is just melted. Remove and tip the tray to spread the oil and butter all over.","images":[],"step":5},{"description":"Combine the remaining Spice Mix, flour, panko and cornmeal in a bowl and mix. Place half in a large ziplock bag.","images":[],"step":6},{"description":"Drain the chicken of excess marinade using a colander.","images":[],"step":7},{"description":"Transfer half the chicken into the ziplock bag, seal in air so it is puffed like a balloon, then shake to coat the chicken in the seasoning. Press through the bag so the coating is firmly stuck onto the chicken. Place the chicken onto the baking tray.","images":[],"step":8},{"description":"Place the remaining coating into the ziplock bag and repeat with remaining chicken.","images":[],"step":9},{"description":"Spray the top with oil and place in the oven. Bake for 12 minutes, then turn, spray and bake for a further 8 to 10 minutes or until golden. Don''t bake more than 25 minutes, otherwise the chicken will dry out!","duration":12,"images":[],"step":10},{"description":"Serve with your favourite dipping sauce. I used Honey Mustard Sauce (Note 7).","images":[],"step":11}]', '["gluten","milk","mustard"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-recipes","dinner-tonight","main-dishes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fd20cfe1d1d5', 'en', 'US', 'Chicken Meatloaf Wellington with Sun Dried Tomatoes', 'A fresh take on meatloaf! Made with chicken, scattered with sun dried tomatoes and the fresh burst of basil. Encase in puff pastry to create a cross between the British classic Beef Wellington and meatloaf (but made with chicken!).', 'https://www.recipetineats.com/tachyon/2015/09/Chicken-Meatloaf-Wellington_1-Featured.jpg', 15, 40, 55, 5, '[{"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 0.141, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_basil", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_tomato", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sheet_puff_pastry", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["1 small onion (, grated (about 1/2 cup))","1 lb / 500 g ground chicken (mince) (Note 1)","3/4 cup panko breadcrumbs","1/4 cup parmesan cheese (, finely grated)","1 egg","1/3 cup fresh basil (, roughly chopped (Note 2))","3/4 cup roughly chopped sun dried tomatoes","1 tsp salt","Black pepper"],"purpose":"Filling"},{"ingredients":["1 sheet puff pastry (, thawed)","1 egg (, lightly beaten (optional) (Note 3))"],"purpose":"Pastry"}]', '[{"description":"Preheat oven to 180C/350F. Line a baking tray with parchment paper.","images":[],"step":1},{"description":"Place the Filling ingredients in a bowl and use your hands to mix together. It should be quite soft and wet, not dry and crumbly.","images":[],"step":2},{"description":"Place the filling onto the puff pastry. Shape into a loaf and roll the puff pastry up, ending with the seam side down.","images":[],"step":3},{"description":"Transfer to baking tray. Cut a few diagonal slashes across the top.","images":[],"step":4},{"description":"Brush with egg wash and bake for 35 to 40 minutes, or until the pastry is deep golden brown. Turn the tray at around 25 minutes for even browning.","duration":37.5,"images":[],"step":5},{"description":"Remove from the oven. Rest for 5 minutes before serving.","duration":5,"images":[],"step":6}]', '["egg","milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-mince-recipes","chicken-recipes","dinner-tonight","main-dishes","most-popular"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4473cf255160', 'en', 'US', 'White Chicken Enchiladas', 'This white sauce version of Enchiladas gives the classic a serious run for its money!', 'https://www.recipetineats.com/tachyon/2015/08/White-Enchiladas_Plated-Featured.jpg', 15, 25, 40, 4, '[{"id": "ing_butter", "quantity": {"value": 2.5, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_chilli", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_rtillas", "quantity": {"value": 8.0, "unit": "unit"}}]', '[{"ingredients":["2 1/2 tbsp butter","3 tbsp flour","1 cup milk","1/2 cup light sour cream","1 cup chicken broth","1/2 tsp cumin powder","2 tbsp finely chopped jalapeños OR canned green chilies (Note 2)","1/2 tsp salt + pepper"],"purpose":"White Sauce"},{"ingredients":["2 1/2 cups shredded cooked chicken (I used poached chicken breast)","1 cup frozen corn","1/2 cup sliced scallions","Salt and pepper","2 cups grated cheese (Note 1)","8 to rtillas (flour or corn)"],"purpose":"Enchiladas"}]', '[{"description":"Melt butter over medium heat in a skillet. Add flour and cook for 1 minute.","duration":1,"images":[],"step":1},{"title":"Add milk, whisk until thickened","description":"about 30 seconds to 1 minute. Add sour cream and chicken broth. Whisk and cook for 2 minutes - it should thicken slightly. Stir through cumin, jalapeños, salt and pepper. Remove from heat and set aside.","duration":2,"images":[],"step":2},{"description":"Preheat oven to 180C/350F.","images":[],"step":3},{"description":"Mix together 1/4 cup White Sauce, chicken, corn, scallions, 1 cup of grated cheese, salt and pepper.","images":[],"step":4},{"description":"Pop the tortillas in the microwave for 15 seconds to warm through (so they don''t crack when rolled up).","duration":0.25,"images":[],"step":5},{"description":"Divide filling between tortillas, and roll them up like a cigar.","images":[],"step":6},{"description":"Smear 2 tbsp of White Sauce in baking dish. Place enchiladas in the dish, seam side down. Pour over remaining White Sauce, scatter with remaining cheese.","images":[],"step":7},{"description":"Bake for 25 minutes, until bubbly and golden. Serve hot!","duration":25,"images":[],"step":8},{"title":"Optional","description":"Serve Pico de Gallo to top it or serve it on the side. I added avocado to my base Pico de Gallo Recipe.","images":[],"step":9}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["chicken-breast-recipes","chicken-recipes","dinner-tonight","enchiladas","main-dishes","mexican-recipes","most-popular","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_52d01eac228e', 'en', 'US', 'Prosciutto Wrapped Chicken and Scalloped Potatoes (One Pan!)', 'This is one of those recipes that is easy enough for midweek but elegant enough for company - at least, in my opinion! By baking the chicken on top of the potato, the juices mingles with the salty prosciutto then drips down onto the potato, adding extra (serious) flavour oomph!', 'https://www.recipetineats.com/tachyon/2015/08/One-Pan-Prosciutto-Chicken-Potatoes_Featured.jpg', 15, 45, 60, 4, '[{"id": "ing_ricotta", "quantity": {"value": 0.4, "unit": "tub of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 4.0, "unit": "net of 500g"}}, {"id": "ing_sage", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_ong_or_8_small_thin_slices_of_prosciutto", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 1.5, "unit": "bag of 2kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2/3 cup ricotta","Zest of 1 small lemon (, or 1/2 large lemon)","1 1/2 tsp finely sliced fresh sage leaves (Note 1)","1/4 tsp salt","Pepper"],"purpose":"Ricotta Filling"},{"ingredients":["4 chicken thigh fillets (, skinless and boneless (about 5 - 7 oz / 150 - 200g each))","4 long or 8 small thin slices of prosciutto","1.5 lb / 750 g potatoes (, peeled and cut into thin slices)","1 garlic clove (, crushed (optional))","1 1/2 tbsp olive oil + 1/2 tbsp extra olive oil","1 tsp dried thyme leaves","1/4 cup freshly grated parmesan","Salt and pepper"],"purpose":"Prosciutto Chicken & Potatoes"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Mix together the Ricotta Filling ingredients in a small bowl.","images":[],"step":2},{"description":"Lay out the prosciutto on a work surface. Place chicken lengthwise at the bottom of each strip.","images":[],"step":3},{"description":"Divide Ricotta Filling between the chicken, placing it at the bottom (closest to you).","images":[],"step":4},{"description":"Roll up the chicken, wrapping it in the prosciutto, finishing with the seam side down. Not too tightly otherwise the ricotta will ooze out!","images":[],"step":5},{"description":"Use toothpicks to seal the ends. (Note 2)","images":[],"step":6},{"description":"Spread the potato slices on the base of a roasting dish or large ovenproof skillet. Fan them out so they are overlapping slightly.","images":[],"step":7},{"description":"Mix together 1 1/2 tbsp olive oil and garlic then pour over the potatoes, using a teaspoon or brush to spread it out. Sprinkle with salt and pepper and thyme leaves.","images":[],"step":8},{"description":"Place chicken on top of the potato, drizzle the chicken with 1/2 tbsp olive oil and bake for 40 minutes.","duration":40,"images":[],"step":9},{"description":"Remove chicken onto a plate to rest, covered loosely with foil.","images":[],"step":10},{"description":"Sprinkle the potatoes with parmesan cheese, then return just the potatoes back into the oven and turn up the oven to maximum. Bake for 5 minutes.","duration":5,"images":[],"step":11},{"description":"Remove potatoes from the oven. Place chicken back on top.","images":[],"step":12},{"description":"Serve asap!","images":[],"step":13}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","one-pot-recipes","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a474fbff15c1', 'en', 'US', 'Shredded Sweet Soy Chicken Breast', 'A simple, fast, very tasty way to prepare chicken. Chicken breast is perfect for shredding. Because it''s so lean, it is especially great combined with a jammy intense flavoured sauce that is sweet and sour. Add a kick of chili if you want! Great served on rice, or use the sauce as the flavouring for a fried rice!', 'https://www.recipetineats.com/tachyon/2015/07/Sweet-Soy-Shredded-Chicken_600px_1_Featured-Image.jpg', 10, 60, 70, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_oil", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.333, "unit": "bottle of 250ml"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_jam", "quantity": {"value": 0.122, "unit": "jar of 370g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}]', '[{"ingredients":["1 lb / 500g chicken breast (skinless, boneless pieces)","2 cloves of garlic (, minced)","1/2 onion (, finely diced)","1 tbsp oil (vegetable, canola, olive oil or grapeseed oil)","1/3 cup soy sauce (ordinary soy sauce)","1/3 cup white vinegar (or substitute with other vinegar except balsamic)","3 tbsp jam (Note 1)","1 tbsp black peppercorns or 1/2 tbsp ground black pepper (Note 2)","3/4 cups water"],"purpose":"Shredded Chicken"},{"ingredients":["2 tsp cornstarch / cornflour","3 tsp water"],"purpose":"Sauce Thickening"}]', '[{"title":"Slow Cooker","description":"Place all the Shredded Chicken ingredients in the slow cooker and cook on low for 5 hours (or 2 1/2 hours on high).","images":[],"step":1},{"title":"Pressure Cooker","description":"Place all the Shredded Chicken ingredients in the pressure cooker. Cook for 35 minutes on high.","duration":35,"images":[],"step":2},{"title":"Stove","description":"Place all the Shredded Chicken ingredients in a saucepan large enough for the chicken to fit snugly in one layer. Add 1/2 cup extra water so the chicken is mostly, but not completely submerged. Cover and simmer for about 50 to 60 minutes, turning once or twice.","images":[],"step":3},{"description":"The chicken is ready when it can be easily shredded with two forks. Remove the chicken from the liquid and shred it while it is warm. Set aside and cover to keep warm.","images":[],"step":4},{"description":"Transfer the liquid from the slow cooker / pressure cooker to a saucepan and bring to simmer. (Note 3) Reduce to around1 1/4 cups - it should only take a few minutes.","images":[],"step":5},{"description":"Mix together the Sauce Thickening ingredients and add to the saucepan. Simmer until it it thickens to a syrup consistency.","images":[],"step":6},{"description":"Toss the chicken in the sauce and serve over rice. (Note 4)","images":[],"step":7}]', '["gluten","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","low-calorie-recipes","main-dishes","most-popular","quick-and-easy","slow-cooker-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1936d88c97f7', 'en', 'US', 'One Pot Creamy Parmesan Garlic Risotto with Lemon Pepper Chicken', 'Two dishes made in one pot! Creamy, dreamy risotto with yummy garlic parmesan flavours topped with crispy roast chicken. Cooking the chicken on top of the rice is like making rice with triple strength stock!', 'https://www.recipetineats.com/tachyon/2015/06/One-Pot-Creamy-Risotto-Lemon-Pepper-Chicken-4.jpg', 10, 50, 60, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.907, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.094, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_rice", "quantity": {"value": 225.0, "unit": "pack"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.907, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.5, "unit": "pack of 200g"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1/2 tbsp olive oil","2 lb / 1 kg chicken thighs (, skin on and bone in (5 pieces) (Note 1))","2 - 3 tbsp Lemon Pepper Seasoning (Note 2)"],"purpose":"Chicken"},{"ingredients":["2 tbsp butter","4 garlic cloves (, minced)","1 onion (, finely diced)","1 1/2 cups risotto rice (arborio)","1/2 cup white wine (, any (or stock or water))","4 cups chicken broth (stock)","1 cup milk (I use low fat)","1/2 tsp salt","Black pepper"],"purpose":"Risotto"},{"ingredients":["1 cup freshly grated parmesan (lightly packed)","2 tbsp butter","1/2 to 1 cup milk (preferably warmed)","Fresh thyme leaves (, or finely chopped parsley, chives or oregano (optional))"],"purpose":"Risotto Finishes"}]', '[{"description":"Preheat oven to 180C/350F (fan forced) / 200C/390F (conventional).","images":[],"step":1},{"description":"Coat chicken with Lemon Pepper Seasoning, using most of it on the skin.","images":[],"step":2},{"description":"Heat olive oil over medium heat in a large oven proof fry pan (Note 3).","images":[],"step":3},{"description":"Place the chicken in the pan skin side down. Cook for 3 minutes then turn the heat up to medium high and cook for a further 2 minutes or until browned. Turn and cook for 3 minutes. (Note 4)","duration":3,"images":[],"step":4},{"description":"Remove chicken onto a plate. Discard excess oil in the pan and wipe the pan with a paper towel.","images":[],"step":5},{"description":"Return the pan to the stove, still on medium high.","images":[],"step":6},{"description":"Melt butter in the pan. Add garlic and onion and cook for 2 minutes or until onion is translucent.","duration":2,"images":[],"step":7},{"description":"Add rice and stir until the grains turn from white to translucent. Add wine and cook for 1 to 2 minutes, or until the wine is mostly evaporated.","duration":1.5,"images":[],"step":8},{"description":"Add chicken broth, milk, salt and pepper. Bring to a simmer on the stove. Give it a quick stir then place the chicken on top of the rice (pour juices on the plate in too). Then place a lid (or foil) on the pan and transfer to the oven.","images":[],"step":9},{"description":"Bake for 20 minutes with the lid on. Remove the lid and return to the oven for another 10 minutes, or until the rice is firm but just cooked (not mushy!) and the chicken is crispy.","duration":20,"images":[],"step":10},{"description":"Remove the chicken from the rice. Stir through Risotto Finishes, using the milk to get the risotto to a creamy consistency.","images":[],"step":11},{"description":"Return chicken on top. Serve immediately, with fresh thyme leaves and extra parmesan, if desired.","images":[],"step":12}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["chicken-breast-recipes","chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","italian-recipes","main-dishes","most-popular","one-pot-recipes","quick-and-easy","risotto-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eb1ac84490df', 'en', 'US', 'Jamie Oliver''s Chicken in Milk {Seriously Delish}', 'Though the ingredients list might seem odd, this is actually one of the best chicken dishes I have ever had. Possibly the best roast chicken I''ve ever had. It''s incredibly easy to make and produces a very tender chicken with crispy skin on top. The braising liquid reduces to a fabulous sauce that has a hint of freshness from the lemon and muskiness from the sage and cinnamon. The whole cloves of garlic cook in the skin so they are soft and mushy (mild garlic flavour, much more sweet), perfect for popping out of the skin and eating with the chicken, or spread it on toast! The milk dissolves into bits of curd which remind me of bocconcini and taste like little bursts of creaminess.', 'https://www.recipetineats.com/tachyon/2014/12/Chicken-in-Milk-1445.jpg', 5, 100, 105, 4, '[{"id": "ing_chicken", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_stick_cinnamon", "quantity": {"value": 0.5, "unit": "jar"}}, {"id": "ing_oosely_packed_sage_leaves", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_emons", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 16.667, "unit": "pack of 3 heads"}}, {"id": "ing_milk", "quantity": {"value": 0.562, "unit": "L"}}]', '[{"ingredients":["3 - 3.5 lb / 1.5 - 1.8 kg whole chicken","2 tsp salt (plus more to taste)","Black pepper","2 tbsp olive oil","1/2 stick cinnamon","1/4 cup loosely packed fresh sage leaves","2 lemons (, zest only (avoid grating the pith which is bitter))","10 cloves of garlic (, whole, skin on)","2 1/4 cups milk (I used low fat)"]}]', '[{"description":"Preheat oven to 190C/375F.","images":[],"step":1},{"description":"Wash the chicken under water and pat dry with paper towels.","images":[],"step":2},{"description":"Sprinkle over the salt and 5 grinds of black pepper and pat all over the chicken, concentrating on the top and sides.","images":[],"step":3},{"description":"Heat oil in a heavy based pot over high heat. (Note 1)","images":[],"step":4},{"description":"Brown the chicken all over as best you can. I find the easiest way to do this (and minimising skin tearing) is with tongs stuck in the rear of the chicken and a wooden spoon to lift and leverage the chicken. Tilt the chicken as required to brown as much of the skin as you can. (Note 2)","images":[],"step":5},{"description":"If you can manage it (or if you have a helper), pour the excess fat out of the pot with the chicken still in it. If you can''t, remove the chicken onto a plate, then drain the fat.","images":[],"step":6},{"description":"Add the remaining ingredients into the pot (return the chicken to the pot if you removed it).","images":[],"step":7},{"description":"Bake covered for 40 minutes, then bake uncovered for 50 minutes (1.5 hrs in total).","duration":40,"images":[],"step":8},{"description":"Let stand for 5 minutes or so before removing the chicken from the pot onto a serving plate. Serve the sauce on the side. I prefer not to strain it because I want the bits of curd and garlic on my chicken, as well as bits of sage.","duration":5,"images":[],"step":9}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":[],"categories":["chicken-recipes","dietary","dinner-tonight","gluten-free-recipes","main-dishes","most-popular","one-pot-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5a818b0da846', 'en', 'US', 'Syrian Chicken', 'This is a simple but exotic dish of chicken with a spiced crispy skin baked with a rich tomato broth. It is served with Giant Couscous (also known as Moghrabieh, Israeli or Pearl Couscous) which can be substituted with ordinary couscous, pasta (risoni/orzo), rice, polenta or even mashed potato.', 'https://www.recipetineats.com/tachyon/2014/10/Syrian-Chicken-with-Giant-Couscous-12-Version-4.jpg', 15, 30, 45, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.907, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_ginger", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 0.397, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_saffron_powder", "quantity": {"value": 0.625, "unit": "jar"}}, {"id": "ing_thyme", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_currants", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_giant_couscous", "quantity": {"value": 226.8, "unit": "pack"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}]', '[{"ingredients":["2 tbsp olive oil","2 lb / 1 kg chicken thigh fillets (, bone in and skin on (4 to 5 pieces) (see notes))"]},{"ingredients":["1 tsp cumin powder","1 tsp cinnamon powder","1 tsp salt","Black pepper"],"purpose":"Chicken Spices"},{"ingredients":["1 1/2 tbsp fresh ginger (, finely chopped)","3 garlic cloves (, minced)","1 onion (, halved and finely sliced)","2 birds eye chilis (, finely chopped (or to taste) (see notes))","1/4 cup (combined) mint and coriander leaves, roughly chopped","2 tbsp lemon juice","14 oz / 400 g canned crushed tomato","1 cup chicken stock / broth","1/8 tsp saffron powder (see notes)","1/2 tsp cumin powder","3 sprigs of thyme or 1 tsp dried thyme leaves","1/4 cup dried currants or sultanas (optional) (see notes)"],"purpose":"Sauce"},{"ingredients":["8 oz / 250 g giant couscous (Israeli or Pearl Couscous)","Yoghurt (optional)"],"purpose":"To Serve"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Place chicken on a plate or in a large bowl. Sprinkle with Chicken Spices and use your hands to coat the chicken.","images":[],"step":2},{"description":"Heat olive oil in a large, oven proof fry pan over high heat.","images":[],"step":3},{"description":"Add chicken, skin side down, and sear until the skin is nicely browned. Turn chicken over and cook the other side until browned. Remove chicken from pan. Drain pan of excess oil.","images":[],"step":4},{"description":"Add onion, garlic, ginger and chili into the pan. Saute for 2 minutes until the onion is translucent and starting to brown.","duration":2,"images":[],"step":5},{"description":"Add canned tomato, chicken stock/broth, saffron powder, cumin powder and thyme. Bring to simmer, then turn the stove off. Nestle the chicken into the tomato broth, then cover with foil (or lid) and place into the oven. Bake for 25 to 35 minutes.","duration":30,"images":[],"step":6},{"description":"Meanwhile, cook the Giant Couscous according to packet instructions. Usually it just needs to be boiled in salted water for around 4 minutes, then drain it.","images":[],"step":7},{"description":"When the chicken is dark golden brown and cooked, remove from oven. Stir through dried currents (if using), lemon juice and half the mint and coriander. Then sprinkle over remaining mint and coriander.","images":[],"step":8},{"description":"Serve on Giant Couscous with a dollop of yoghurt, if using.","images":[],"step":9}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Mediterranean","Middle Eastern","Syrian"],"categories":["chicken-recipes","dinner-tonight","main-dishes","mediterranean-recipes","most-popular","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c764a49c0479', 'en', 'US', 'Cobb Salad', 'Recipe video above. The mighty Cobb Salad! Don''t skip the blue cheese. It''s what makes this a Cobb Salad, and not just another chicken salad. :) Love the presentation on a big platter with the ingredients in neat rows. Serve Dressing on the side for everyone to help themselves (better than tossing each item individually).', 'https://www.recipetineats.com/tachyon/2023/08/Cobb-Salad_0.jpg', 15, 20, 35, 4, '[{"id": "ing_chicken_breast", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_bacon", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 4.0, "unit": "carton of 12"}}, {"id": "ing_lettuce", "quantity": {"value": 36.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_avocado", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_gorgonzola_dolce_or_roquefort", "quantity": {"value": 200.0, "unit": "unit"}}, {"id": "ing_chives", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.15, "unit": "bottle of 500ml"}}, {"id": "ing_green_onion", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}]', '[{"ingredients":["400g/14 oz chicken breast (2 pieces)","1/4 tsp cooking/kosher salt","1/4 tsp black pepper"],"purpose":"Chicken:"},{"ingredients":["200g/7oz streaky bacon strips","4 x 9 minute boiled eggs (, quartered)","12 cups cos / romaine lettuce (1 large head, 2 small), chopped (or other crispy lettuce)","2 large tomatoes (, cut into 8 wedges then halved (or 250g/8oz cherry tomatoes halved))","2 avocados (, cut into large pieces)","200g/7oz gorgonzola dolce (my favourite) or roquefort (traditional), ( crumbled (or other blue cheese - Note 1))","2 tbsp chives (, finely chopped)"],"purpose":"Cobb Salad:"},{"ingredients":["1 tbsp dijon mustard","5 tbsp extra virgin olive oil","5 tbsp apple cider vinegar (sub white wine or red wine vinegar)","3/4 tsp cooking/kosher salt","1/4 tsp black pepper","2 tbsp eschallot ((US: shallot), very finely minced)","1/2 tsp white sugar"],"purpose":"Dressing:"}]', '[{"title":"Dressing","description":"Shake ingredients in a jar.","images":[],"step":1},{"title":"Flavour chicken","description":"Poach chicken using this method (20 minute foolproof-guaranteed-juicy). Cool to room temperature then cut into 2cm / 0.75” cubes. Toss with salt, pepper and 2 tablespoons of Dressing. Set aside.","images":[],"step":2},{"title":"Crisp bacon","description":"Place bacon strips in a non-stick pan (not heated, no oil). Turn heat onto medium high - as the pan heats up, the fat will begin to melt. Cook for 2 minutes until golden, turn and cook the other side for 1 1/2 minutes until golden. Drain on paper towels. Once cool and crisp, chop into 1.5cm / 0.6\" pieces.","duration":2,"images":[],"step":3},{"title":"Assemble","description":"Spread lettuce on a large platter. Arrange the ingredients on top in the Cobb Salad signature neat rows: egg, bacon, avocado, tomato and chicken. Crumble blue cheese across the top, sprinkle with chives. Pour dressing into a jug.","images":[],"step":4},{"title":"Serving","description":"Let everybody help themselves to the salad and Dressing!","images":[],"step":5}]', '["egg","milk","mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner","lunch"],"cuisine":["American","Western"],"categories":["chicken","chicken-breast-recipes","mains","no-cook-food","salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_abcdc991d0d4', 'en', 'US', 'Duck Confit - French slow roasted duck legs', 'Recipe video above. A traditional recipe for Duck Confit from a French chef! Called Confit de Canard in French, duck legs are slow-cooked in duck fat until the meat is meltingly tender, then the skin crisped to golden perfection. This Duck Confit recipe is low-effort and DOESN''T require buckets of duck fat! Simple, yet a lusciously indulgent dish worthy of gracing restaurant tables. This might just be the ultimate dish for a low-stress dinner party or treating your loved ones!Recipe courtesy of our resident French Chef Jean-Baptiste Alexandre. Meet Chef "JB" here.', 'https://www.recipetineats.com/tachyon/2021/06/Duck-Confit-photo-_8.jpg', 15, 530, 545, 4, '[{"id": "ing_x_250g_duck_legs", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_duck_fat", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sage", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_rosemary", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 10.0, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_star_anise", "quantity": {"value": 8.0, "unit": "jar"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_juniper_berries", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_s", "quantity": {"value": 8.0, "unit": "pack"}}]', '[{"ingredients":["4 x 250g / 8oz duck legs (, skin on, bone in (aka maryland); (Note 1))","750 ml / 25 oz duck fat (Note 2)"],"purpose":"Duck:"},{"ingredients":["4 tsp cooking/kosher salt (Note 4)","1/3 cup thyme sprigs (, lightly packed)","1/3 cup sage sprigs (, lightly packed)","1/3 cup rosemary sprigs (, lightly packed)","1/3 cup oregano sprigs (, lightly packed)","6 cloves garlic (, smashed with skin on)","1 eschalot ((US: shallot), peeled and sliced 0.7cm (1/3\") thick)","1 tbsp black peppercorns","1 tbsp coriander seeds","8 star anise","2 bay leaves","2 tbsp juniper berries","8 cloves"],"purpose":"Dry cure (Note 3):"}]', '[{"title":"Coat duck with dry cure","description":"Place duck legs and all the Dry Cure ingredients in a large bowl. Toss well with your hands.","images":[],"step":1},{"title":"Cure 12","description":"24 hrs: Transfer to a ceramic or glass dish large enough so the duck fits in a single layer but snugly. Cover and refrigerate for 12 - 24 hours (no longer is necessary).","images":[],"step":2},{"title":"Rinse","description":"Brush off cure and rinse duck under tap water to clean them (remove all salt and black bits). Pat dry with paper towels.","images":[],"step":3},{"description":"Slow cooking (confit):","images":[],"step":4},{"description":"Preheat oven to 100°C/210°F (80°C fan) with a shelf positioned in the middle of the oven.","images":[],"step":5},{"title":"Roasting pan","description":"Place duck in a small metal roasting pan with high sides. They should fit snugly, touching each other, but in a single layer. (Note 5)","images":[],"step":6},{"title":"Cover with duck fat","description":"Pour fat over duck. It should pretty much cover the legs. (Note 6)","images":[],"step":7},{"title":"Heat fat in pan","description":"Place pan on the stove over medium-high heat. Heat fat until bubbling energetically all across the surface (ie not just around the edges).","images":[],"step":8},{"title":"Cover with paper","description":"Turn off stove. Cover surface with baking / parchment paper, cut to size so it sits on the surface of the fat over the duck. Gently push down to remove air bubbles. Cover pan tightly with a double layer of foil.","images":[],"step":9},{"title":"Slow cook","description":"Carefully transfer to the oven. Cook for 8 hours.","images":[],"step":10},{"title":"Check flesh","description":"Remove one duck leg (gently). Turn over to check the flesh side – meat should be fall-apart tender. Leg should also give easily when pressure is applied to the joint (see video).","images":[],"step":11},{"description":"Storing cooked Duck Confit (optional):","images":[],"step":12},{"description":"Duck can be stored submerged in fat at this stage. The meat juice should be strained off first.","images":[],"step":13},{"description":"Remove duck to a non-reactive container in which they fit snugly. (Note 7) Pour over cooled duck fat, leaving juice sediment behind. Ensure it fully covers the duck (push duck under while warm and pliable as needed, using tongs).","images":[],"step":14},{"description":"Once fully cool, cover with lid and place in fridge (5 days) or freezer (3 months). Fat will solidify.","images":[],"step":15},{"description":"To cook, heat duck gently in a container in microwave to melt the fat. Proceed with recipe.","images":[],"step":16},{"description":"Crisping skin and finishing Duck:","images":[],"step":17},{"description":"Preheat oven to 240°C/465°F (220°C fan). Place a rack over a deep roasting pan.","images":[],"step":18},{"title":"Remove duck from fat","description":"Remove duck from fat, allowing excess oil to drip off. Pat excess oil off with paper towels.","images":[],"step":19},{"title":"Prepare for roasting","description":"Pour 2.5cm / 1\" of boiling water water into the roasting pan (steam keeps flesh moist). Place duck on rack, skin side up.","images":[],"step":20},{"title":"Crisp skin","description":"Roast duck for 40 minutes until the skin is a deep golden and crispy. Rotate pan as needed for even colour. (You won''t have problems with fat smoking as it drips into the water)","duration":40,"images":[],"step":21},{"title":"Serve","description":"Rest briefly to cool, and serve! A classic French side dish for Duck Confit is Lentil Ragout. (pictured in post)","images":[],"step":22}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["chicken","duck","iconic-dishes","mains","roasts","slow-cooked-fall-apart"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e3c19280c16c', 'en', 'US', 'Thai Glass Noodle Stir Fry (Pad Woon Sen)', 'Recipe video above. A big, family-size home-style Thai noodle stir fry using glass noodles, those thin clear noodles you probably bought by accident instead of rice vermicelli noodles and forgot about in the pantry - that''s me! Classic Thai flavours, savoury with a touch of sweet, with a nice hit of garlicky goodness. I chose vegetables that make this fast to make, but feel free to use what you want, just keep it to about 5 cups total. Soy sauce works fine if you don’t have MAGGI seasoning (every Thai household will have this though!). Adapted from this Pad Woon Sen on Hot Thai Kitchen. My recipe is scaled up, add-ins streamlined and sauce strength slightly tweaked to my palette.', 'https://www.recipetineats.com/tachyon/2026/03/Thai-Glass-Noodles-Pad-Woon-See_5.jpg', 15, 10, 25, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_maggi_seasoning", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["250g / 8 oz dried bean thread noodles (glass noodles), prepared per packet (Note 1)","2 tbsp canola oil (, or other neutral oil suitable for stir fries)","1/2 onion (, cut into thin wedges)","4 garlic cloves (, finely minced (knife or crusher is fine))","1 big bunch Chinese broccoli (gai lan), or choi sum","3 eggs (, whisked)"],"purpose":"Glass noodle stir fry:"},{"ingredients":["350g / 12 oz chicken thighs (, boneless and skinless, sliced into small 5mm / 0.2\" thin strips (Note 3))","2 tsp MAGGI seasoning (or light soy sauce (Note 4))","Pinch white pepper (substitute black pepper)"],"purpose":"Chicken:"},{"ingredients":["2 tbsp oyster sauce (or vegetarian oyster sauce)","1 tbsp fish sauce","1 tbsp MAGGI seasoning (, substitute light or all-purpose soy sauce (Note 4))","1 tbsp canola oil (, or other plain flavoured oil)","1 tsp white sugar","1/8 tsp white pepper (substitute black pepper)"],"purpose":"Sauce:"}]', '[{"description":"Mix sauce, toss chicken in Maggi. In 30cm/12\" pan, cook onion 15 sec, cook chicken ~ 2 min, adding Chinese broccoli stems and garlic towards end. Push everything to side, drizzle oil, scramble eggs, mix everything together. Add Chinese broccoli leaves, noodles, sauce, toss well. Serve!","images":[],"step":1},{"description":"Toss chicken with MAGGI and pepper. Set aside while you finish preparing everything else.","images":[],"step":2},{"description":"Mix the sauce ingredients in a small bowl. (It won''t seem enough for the volume of noodles but trust the process! It packs a ton of flavour.)","images":[],"step":3},{"title":"Cook chicken and onion","description":"Heat 2 tablespoons of the oil in a large 30cm/12\" non-stick pan over high heat until very hot (see Note 5 if your pan is smaller). Add onion and stir for 15 seconds. Add chicken and stir for 2 minutes until almost cooked through.","duration":0.25,"images":[],"step":4},{"description":"Add garlic and Chinese broccoli stems. Stir for 1 minute or until chicken is cooked.","duration":1,"images":[],"step":5},{"title":"Scramble eggs","description":"Push everything to one side of the pan, drizzle 1/2 tablespoon oil in the cleared space. Pour the eggs in and gently stir to scramble. When it''s almost cooked, toss through the chicken.","images":[],"step":6},{"title":"Leaves, noodles and sauce","description":"Add the Chinese broccoli leaves, noodles (on top, to weigh down) then pour the sauce all over the noodles. Use two spatulas to toss until the noodles are all stained with sauce and there''s no water in the pan.","images":[],"step":7},{"description":"Serve immediately!","images":[],"step":8}]', '["egg","fish","gluten","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["cuisines","noodles","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_631884abba0c', 'en', 'US', 'Layered Golden Rice Bake with Spiced Meat', 'Recipe video above. This is essentially a streamlined version of Tachin, the iconic Middle Eastern saffron rice cake with its signature crispy crust, baked, then inverted like a pie. Here, I skip the flipping, use ingredients you can find at regular stores, and it''s a large format that serves 10 yet takes little more effort than Bolognese.The top gets crispy, the meat layered inside is fragrant with Middle Eastern spices, and the rice is vibrant yellow with the distinct perfume of saffron. If saffron threads are out of reach, use imitation powder instead. Though it won''t smell the same, you’ll still get vibrant yellow colour!PS. DO NOT SKIP THE LEMON YOGURT SAUCE! (Please, please🥰) See Note 5.', 'https://www.recipetineats.com/tachyon/2026/03/Golden-Saffron-Rice-Bake-with-Baharat-Spiced-Lamb_2.jpg', 30, 70, 100, 8, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_baharat_spice_mix", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_cayenne", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_saffron_threads", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.45, "unit": "tub of 500g"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_pine_nuts", "quantity": {"value": 0.375, "unit": "pack of 100g"}}, {"id": "ing_sour_cream", "quantity": {"value": 3.0, "unit": "tub of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_pine_nuts", "quantity": {"value": 0.375, "unit": "pack of 100g"}}]', '[{"ingredients":["1 1/2 tbsp olive oil","4 garlic cloves (, finely minced)","1 onion (, finely diced)","750g / 1 1/2 lb lamb mince (first choice), or beef (Note 1)","2 1/2 tbsp baharat spice mix (- store bought or make your own (Note 3))","2 tsp cumin powder","2 tsp cooking salt / kosher salt","1/2 tsp cayenne powder (, optional, for very subtle warmth)","3 tbsp tomato paste","1 small eggplant (, skin on, cut into 1cm / 0.4\" cubes, ~2 heaped cups (Note 2))","1 1/2 cups water"],"purpose":"Persian spiced meat filling:"},{"ingredients":["3 cups basmati rice (, uncooked)","1 tbsp cooking salt / kosher salt (, for rice cooking water)","1/2 tsp saffron threads (Note 4 for imitation powder, more cost effective)","2 tbsp boiling water","1 1/2 cups plain unsweetened yogurt (, full fat (regular, Greek or Greek-style))","2 large eggs (~55g/2oz each in-shell)","1/4 cup extra virgin olive oil","1 tsp cooking salt / kosher salt"],"purpose":"Golden rice:"},{"ingredients":["1/4 cup pine nuts (slivered or flaked almonds also great)","2 - 3 tbsp extra virgin olive oil (, for drizzling)"],"purpose":"Layering:"},{"ingredients":["3 batches Lemon Yogurt Sauce (YES 3 BATCHES!), or even plain yogurt or sour cream (Note 5)","2 tbsp coriander / cilantro roughly chopped (, optional garnish)","1 tbsp roughly chopped toasted pine nuts (, optional garnish)"],"purpose":"Serving:"}]', '[{"title":"Filling","description":"sauté onion and garlic, then cook lamb. Add spices, tomato paste then eggplant and water. Simmer 8 min until filling thickens. Saffron rice: grind saffron, soak in hot water. Mix with yogurt, oil, eggs and salt, mix in par boiled rice. Layer in pan with lamb, drizzle, bake 50 min until top is crispy. Slice and serve!","images":[],"step":1},{"description":"Preheat oven to 200°C/400°F (180°C fan-forced).","images":[],"step":2},{"title":"Toast pine nuts","description":"Heat a large non-stick pan (30cm/12\") over medium heat. Add pine nuts and toast for 1 minute, stirring constantly, until they have golden brown spots. Remove into a bowl and set aside.","duration":1,"images":[],"step":3},{"description":"Spiced lamb filling:","images":[],"step":4},{"title":"Cook meat","description":"In the same pan, heat the oil over high heat. Cook the onion and garlic for 1 1/2 minutes. Add lamb and cook, breaking it up as you go, for 5 minutes until you no longer see red.","duration":5,"images":[],"step":5},{"title":"Spices","description":"Add the baharat, cumin and salt. Cook for 1 minute, then stir in tomato paste. Add the eggplant and stir to coat in the flavours until you no longer see any white eggplant flesh.","duration":1,"images":[],"step":6},{"title":"Simmer","description":"Add the water and bring it to a rapid simmer. Lower heat to medium high, then simmer for 8 minutes, stirring regularly, until the filling is thick enough that you can draw a path across the pan and it holds in place. The eggplant should be mostly cooked through (cooks more in oven). It''s now ready for use (can use hot or or cool).","duration":8,"images":[],"step":7},{"title":"Soak saffron","description":"Grind the saffron mostly into a powder in a mortar and pestle (Note 4). Add hot water and leave for 5 minutes+ to soak.","duration":5,"images":[],"step":8},{"title":"Parboil rice","description":"Bring a large pot of water to the boil with the 1 tablespoon of salt. Add rice and boil for 5 minutes, stirring every now and then. Drain well in a colander. (The rice is only partially cooked, it finishes cooking in the oven).","duration":5,"images":[],"step":9},{"title":"Yogurt mixture","description":"Whisk together the yogurt, saffron water, oil, eggs and salt in a large bowl (or used rice boiling pot). Add rice and mix to combine - it will be pale yellow (becomes brighter once baked).","images":[],"step":10},{"description":"Assemble and bake:","images":[],"step":11},{"title":"Assemble","description":"Spread half the rice in a 23 x 33cm / 9 x 13\" dish. Spread over all the lamb mixture then sprinkle with pine nuts. Dollop remaining rice across the surface then spread.","images":[],"step":12},{"title":"Bake","description":"Drizzle over the extra virgin olive oil. Bake 50 minutes until the top is golden around the edges.","images":[],"step":13},{"description":"Rest 10 minutes in the pan then cut. Serve with Lemon Yogurt Sauce.","images":[],"step":14}]', '["egg","milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern","Persian"],"categories":["cuisines","dietary","gluten-free-recipes","middle-eastern-recipes","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2cbcdaa90dec', 'en', 'US', 'Thai red duck curry', 'Recipe video above. There''s something magical about the combination of rich duck meat and Thai red curry! This duck curry recipe features duck breast with golden skin that''s thickly sliced and served in a coconut red curry sauce. Add lychees or pineapples for a very special dish that''s to die for!Note: the duck skin doesn''t stay super crispy given the saucy environment it ends up in. I like to serve the duck with most of the skin above the sauce line so it doesn''t go completely soggy, though if that doesn''t bother you it''s also nice to stir the duck slices throughout the sauce. Your choice!', 'https://www.recipetineats.com/tachyon/2025/01/Thai-red-duck-curry_8.jpg', 15, 30, 45, 4, '[{"id": "ing_duck_breast", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_thai_red_curry_paste", "quantity": {"value": 115.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 666.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_lime", "quantity": {"value": 6.0, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_green_beans", "quantity": {"value": 120.0, "unit": "pack"}}, {"id": "ing_basil", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_ychees", "quantity": {"value": 8.0, "unit": "unit"}}, {"id": "ing_pineapple", "quantity": {"value": 1.25, "unit": "unit"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_lime", "quantity": {"value": 6.0, "unit": "net of 500g"}}]', '[{"ingredients":["500g/ 1 lb duck breasts (, boneless, skin on (3 pieces) (Note 1))","1/4 tsp cooking salt / kosher salt","1/4 tsp white pepper (sub finely ground black pepper)"],"purpose":"Crispy skin duck:"},{"ingredients":["115g/ 4 oz (1/2 cup) Thai red curry paste","2 large garlic cloves (, finely grated (Note 3))","2 tsp fresh ginger (, finely grated (Note 3))","1 cup chicken stock/broth (, low sodium)","400ml/ 14 oz coconut milk (, full fat (Note 4))","6 - 8 makrut lime leaves (, crushed in hand (Note 5))","2 tsp white sugar","2 tsp fish sauce","120g/ 4oz green beans (, trimmed and cut in half)","1 lightly packed cup Thai basil leaves (sub regular basil, Note 6)"],"purpose":"Thai red curry:"},{"ingredients":["8 - 12 lychees (, whole, peeled, seed removed. Fresh best, canned ok too! (Note 7))","1 1/4 cups pineapple pieces (, preferably fresh, canned ok (Note 7))"],"purpose":"Lychees or pineapple – CHOOSE ONE:"},{"ingredients":["Jasmine rice (cook 2 cups of raw rice)","Thai basil leaves (, extra)","Coriander/cilantro leaves/small sprigs (, optional)","Large red chilli (, finely sliced (optional))","Lime wedges (, recommended)"],"purpose":"For serving / garnish:"}]', '[{"description":"Slash duck skin, season. Cold pan, no oil, 10 min medium low (weigh down duck) until golden. Reserve 3 tbsp fat. Finish in oven 8 min (target 60°C/140°F, medium), rest. Sauté curry paste in duck fat with garlic and ginger, add stock, reduce by half, add coconut, fish sauce, sugar, lime leaves, simmer 2 min. Add beans, simmer 3 min, add lychees or pineapple, simmer 2 min. Slice duck, serve!","images":[],"step":1},{"description":"Crispy golden duck breast:","images":[],"step":2},{"description":"Preheat the oven to 180°C/350°F (160°C fan-forced).","images":[],"step":3},{"title":"Score","description":"Sprinkle half the salt and pepper on the flesh of the duck. Turn. Use a sharp knife to make 5 or 6 diagonal scores on the skin of the breast. Don''t pierce the flesh and don''t cut all the way to the edge of the skin (Note 8). Pat the skin dry with paper towels, sprinkle with remaining salt and pepper.","images":[],"step":4},{"title":"Cold pan, no oil","description":"Don''t turn the stove on yet. Use an oven-proof pan (any type). Place the duck skin side down in the cold pan, no oil required. Place another pan on top to lightly weigh the duck down (keeps skin flat).","images":[],"step":5},{"title":"Cook 10 minutes","description":"Turn the stove onto medium low. Cook for 10 minutes or until the skin is golden and crispy. Fat will melt out of the duck skin and it will cook in its own fat. (Note 8)","duration":10,"images":[],"step":6},{"title":"Reserve duck fat","description":"Pour off 2 to 3 tablespoons of the duck fat into the pan you will use to make the curry sauce.","images":[],"step":7},{"title":"Oven 8 minutes","description":"Once the skin is crispy, turn and cook the flesh side for 1 minute. Then transfer the pan to the oven for 8 minutes or until the internal temperature is 60°C/140°F (medium, Note 9)","duration":1,"images":[],"step":8},{"title":"Rest","description":"Transfer to a rack or plate and rest for 5 minutes until ready to assemble the curry.","duration":5,"images":[],"step":9},{"description":"Thai red curry sauce:","images":[],"step":10},{"title":"Sauté curry paste","description":"Heat the duck fat (from step 6 above) on medium heat in a deep skillet. Cook the curry paste, garlic and ginger for 4 to 5 minutes. It will dry out and darken in colour, and substantially improves the flavour (especially store bought, but even homemade).","duration":4.5,"images":[],"step":11},{"title":"Sauce","description":"Add chicken stock, stir, then simmer rapidly to reduce by half (2 -3 minutes). Stir in coconut milk, hand-crushed kaffir lime leaves, sugar and fish sauce. Simmer gently on medium for 2 minutes.","duration":2,"images":[],"step":12},{"title":"Add ins","description":"Add the beans, simmer for 3 minutes until just cooked. Add the lychees or pineapple, simmer 1 minute. Taste and add a tad extra fish sauce if it needs salt.","duration":3,"images":[],"step":13},{"description":"Spoon some sauce in to cover the base of a large deep platter or wide bowl.","images":[],"step":14},{"description":"Slice duck breast, just shy of 5mm / 0.2\" thick. Place on the sauce, fanning it out slightly to expose the pink flesh.","images":[],"step":15},{"title":"Remaining sauce","description":"Spoon the remaining sauce, lychees etc around the duck, avoiding the duck skin.","images":[],"step":16},{"description":"Garnish with Thai basil leaves, coriander, chilli and lime wedges.","images":[],"step":17},{"title":"Serve","description":"Take to the table with flourish and serve with jasmine rice!","images":[],"step":18}]', '["fish"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["cuisines","curry-recipes","duck","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e9697f3f5416', 'en', 'US', 'Fall-apart massaman lamb shoulder', 'Recipe video above. Fall-apart succulent lamb smothered in a rich massaman curry sauce with melt-in-your-mouth potatoes that will take you 5 minutes to prepare. This larger-format version of Lamb Shanks Massaman Curry is made for groups: make up to 4 shoulders at once (serves 25 - 30!), reheats 110% perfectly (unlike lamb leg!), it looks impressive and a crowd pleaser. Plus it''s kid friendly because Massaman Curry isn''t spicy!', 'https://www.recipetineats.com/tachyon/2024/10/Massaman-lamb-shoulder_9a.jpg', 5, 270, 275, 6, '[{"id": "ing_lamb", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_maesri_massaman_curry_paste", "quantity": {"value": 114.0, "unit": "bottle"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 2.0, "unit": "jar"}}, {"id": "ing_star_anise", "quantity": {"value": 2.0, "unit": "jar"}}, {"id": "ing_potato", "quantity": {"value": 600.0, "unit": "bag of 2kg"}}, {"id": "ing_chilli", "quantity": {"value": 20.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2-2.25kg/ 4 - 4.5 lb lamb shoulder (, bone in, excess fat trimmed (but leave thin fat layer on (Note 1))","114g/ 4oz (1/2 cup) Maesri Massaman curry paste (1 can) (, or other brand (Note 2))","400g/ 14 oz can coconut milk (, full fat (Note 3))","3 cups chicken stock/broth (, low sodium)","1 onion (, halved then cut into 1 cm / 1/2\" thick wedges)","2 cinnamon sticks (or 1/2 tsp powder)","2 star anise (won''t ruin if you don''t have this)","600g/ 1.2 lb small baby potatoes (, whole (don''t cut cubes, Note 4))"]},{"ingredients":["2 large red chillis (, finely sliced diagonally (optional))","1 cup (lightly packed) coriander leaves & sprigs (cilantro) (, highly recommended)","Jasmine rice (basmati also excellent)"],"purpose":"Garnishes / serving:"}]', '[{"description":"Abbreviated recipe:","images":[],"step":1},{"description":"Whisk curry, coconut and stock, put lamb in upside down. Add spices and potatoes, foil cover, roast 1 hour at 220°C/425°F (200°C fan), 3 hours 180°C/350°F (160°C fan) or until fall-apart. Uncover, turn lamb, 30 minutes. Garnish, serve!","images":[],"step":2},{"description":"Full recipe steps:","images":[],"step":3},{"description":"Preheat the oven to 220°C/425°F (200°C fan-forced).","images":[],"step":4},{"description":"Whisk the curry paste, coconut milk and chicken stock in a pan until lump free. Put lamb shoulder in, turn to coat in the sauce then place it so it''s upside down (ie meaty / fat side down).","images":[],"step":5},{"description":"Place the onion, cinnamon sticks, star anise and potatoes around the lamb. Cover with foil.","images":[],"step":6},{"title":"Slow-cook","description":"Roast for 1 hour. LOWER the oven to 180°C/350°F (160°C fan) then roast for a further 3 hours. (Note 5)","images":[],"step":7},{"title":"Check","description":"Remove foil and use forks to check the meat is virtually “fall-apart-tender”, it should be by this time. If not, cover and keep cooking.","images":[],"step":8},{"title":"Brown","description":"Turn the lamb over, spoon over sauce. Bake uncovered 30 minutes or until deep golden. (Note 6 for sauce adjustments)","images":[],"step":9},{"title":"Serve","description":"Rest for 10 - 15 minutes. Spoon off as much or as little excess fat off surface, discard. Mix sauce well (it''s quite runny, if it was thicker it''d be too rich). Transfer to a serving dish, if you like, sprinkle with chilli and coriander. Serve! (Note 7 for serving styles)","duration":12.5,"images":[],"step":10}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Thai-ish"],"categories":["cuisines","curry-recipes","iconic-dishes","lamb-recipes","main-dishes","mains","roast-lamb","roasts","stews","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_713940c7c1c2', 'en', 'US', 'Tray bake dinner: lamb kofta meatballs', 'Recipe video above. This easy sheet pan dinner combines beautifully spiced lamb kofta meatballs with colourful roast vegetables for a Middle Eastern dinner that''s as versatile as it is delicious. Stuff into warm flatbreads, serve with couscous or rice bowls, or add a side of roasted cauliflower for a substantial low-carb dinner.Less messy and healthier than pan frying - less oil! Tip: make meatballs on the large side so they don''t dry out in the oven.', 'https://www.recipetineats.com/tachyon/2024/03/Baked-lamb-kofta-meatballs_2.jpg', 20, 20, 40, 4, '[{"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_round_cinnamon", "quantity": {"value": 500.0, "unit": "jar"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.5, "unit": "jar of 50g"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.5, "unit": "jar of 50g"}}, {"id": "ing_quantity_tahini_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_yogurt", "quantity": {"value": 1.0, "unit": "tub of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 9.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["1/2 onion (, grated using a box grater)","500 g / 1 lb lamb mince ((ground lamb), or beef)","1/4 cup panko breadcrumbs (sub regular breadcrumbs)","2 cloves garlic (, finely minced)","2 tbsp coriander/cilantro (, finely chopped)"],"purpose":"KOFTAS"},{"ingredients":["2 tsp cumin","2 tsp coriander","2 tsp paprika (plain, sub smoked)","1 1/2 tsp ground cinnamon","3/4 tsp cayenne pepper (a bit spicy, reduce to taste or leave out)","3/4 tsp cooking salt / kosher salt","1/2 black pepper"],"purpose":"KOFTA SPICES"},{"ingredients":["1 large red capsicum (, deseeded, sliced into 1 cm thick slices)","1 large yellow capsicum (, deseeded, sliced into 1 cm thick slices)","1 red onion (, cut into thin wedges)","1 tbsp extra virgin olive oil","1/4 tsp each cooking/kosher salt and pepper"],"purpose":"VEGETABLES"},{"ingredients":["1 quantity Tahini sauce","1 quantity Lemon Yogurt Sauce (or even just plain yogurt)"],"purpose":"SAUCE OPTIONS (Choose one):"},{"ingredients":["Olive oil spray (for the meatballs)","4 flatbreads (or rice, couscous or cauliflower rice)","3 cups shredded iceberg lettuce (or other leafy greens)","2 tomatoes (, halved, cut into thin slices)","1 tbsp coriander/cilantro leaves (, finely chopped, optional (for sprinkling))"],"purpose":"SERVING (wraps option)"}]', '[{"description":"Preheat oven to 200°C/400°F (180°C fan-forced).","images":[],"step":1},{"title":"Kofta meatballs","description":"Place the Kofta ingredients and spices in a bowl. Use your hands to combine thoroughly then roll 16 large-ish meatballs (I scoop all mixture onto a tray, then roll into balls). Spread them out on a large tray.","images":[],"step":2},{"title":"Vegetables","description":"Toss the vegetables with the oil, salt and pepper. Scatter around the meatballs.","images":[],"step":3},{"title":"Bake","description":"Spray the meatballs with oil. Bake for 15 minutes then switch the oven to the grill/broiler on high. Cook for a further 5 minutes to get some colour on the surface.","duration":15,"images":[],"step":4},{"title":"Serve","description":"Sprinkle with the chopped coriander then serve! To make wraps, stuff with lettuce, tomato, meatballs, and the cook capsicum and onion. Drizzle with lots of tahini sauce or Lemon Yogurt Sauce then tuck in! Other ideas: rice or couscous bowls or big salads - see below.","images":[],"step":5}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["cuisines","lamb-recipes","meatball-recipes","middle-eastern-recipes","one-pot-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1431fc0ca79d', 'en', 'US', 'Panang Curry - real, from scratch', 'Recipe video above. This is a stunning Panang Curry made entirely from scratch. It''s for people who adore real Thai food, can handle the heat and understand that you just can''t replicate the fresh flavour of a real Penang Curry using paste from a jar! Not even using my favourite Maesri curry paste that I''ll happily use for Thai Red and Green Curry.It calls for a trip to the Asian store but once you have the ingredients, it''s straightforward to make. See SPICINESS note in notes section below - yep, it''s spicy, and it can''t be avoided!', 'https://www.recipetineats.com/tachyon/2023/08/Panang-curry-prawn_8-close-up.jpg', 30, 30, 60, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_roasted_peanuts", "quantity": {"value": 45.0, "unit": "jar"}}, {"id": "ing_lemongrass", "quantity": {"value": 40.0, "unit": "bunch"}}, {"id": "ing_eschalots", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_galangal_note_5", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_shrimp", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_cream", "quantity": {"value": 1.25, "unit": "carton of 250ml"}}, {"id": "ing_sugar", "quantity": {"value": 0.018, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_green_beans", "quantity": {"value": 200.0, "unit": "pack"}}, {"id": "ing_basil", "quantity": {"value": 12.0, "unit": "bunch"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_peanuts", "quantity": {"value": 0.113, "unit": "jar"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}]', '[{"ingredients":["700g/ 1.4 lb whole raw prawns/shrimp ((ie shell on), medium ~8cm / 3\"long - Note 1)","350g / 12 oz boneless, skinless chicken thighs (, cut into 7mm/ 1/3\" slices)"],"purpose":"Protein – choose ONE:"},{"ingredients":["1 1/2 cups chicken stock/broth (, low-sodium (not fish/seafood - Note 2))"],"purpose":"For prawn stock (shrimp):"},{"ingredients":["2/3 cup dried Chinese chillies (not Thai!) ((24 x 6cm/2.5\" long, 1/2 cup (15g) once deseeded chopped) - Note 3)","3 tbsp roasted peanuts unsalted","2 lemongrass stems (, finely grated (2 x 20cm/8\" lengths) - Note 4)","2 eschalots (, roughly chopped (1/2 cup))","1 tbsp galangal, finely grated ((~1.5cm / 0.6\" piece) - Note 5)","5 garlic cloves (, finely minced)","1 1/2 tbsp shrimp paste in bean oil ( - Note 6)","1/2 tsp each ground coriander, cumin, nutmeg","1 tbsp (packed) finely sliced kaffir lime leaves ( (~ 6 leaves) - Note 7)"],"purpose":"Curry paste:"},{"ingredients":["3 tbsp canola oil","1 1/4 cups coconut cream (, full-fat (standard Aus 270ml small can ok))","3 1/2 tsp white sugar","4 1/2 tsp fish sauce","1/4 tsp cooking/kosher salt","200g/7oz green beans (, trimmed, cut in half (~1 1/2 cups))","12 Thai basil leaves ( - Note 8)"],"purpose":"Curry:"},{"ingredients":["Jasmin rice","2 tbsp unsalted peanuts (, finely chopped)","Red cayenne peppers (, finely sliced (optional))","Thai basil leaves (, 3 leaves per serving - Note 8)"],"purpose":"SERVING and GARNISHES"}]', '[{"title":"Simmer","description":"Peel and devein prawns, reserving heads and shells. Bring chicken stock to a simmer in a small pot on high heat. Add prawn heads & shells, bring back to a simmer, then reduce to low heat. Simmer uncovered for 15 minutes, periodically crushing the heads lightly with a potato masher and skimming off any orange scum.","duration":15,"images":[],"step":1},{"description":"Strain into a jug, discarding heads. You should have just over 300 ml (1 1/4 cups) of stock. Leave undisturbed to let the sediment settle (~ 5min+).","images":[],"step":2},{"description":"Cut chillies in half then tap / squeeze out seeds (use a chopstick if needed for stubborn seeds). Discard seeds (spicy!). Chop chilli.","images":[],"step":3},{"description":"Soak dried chillis in 2 cups of boiling water for 30 minutes. Drain in a colander, reserve soaking liquid.","duration":30,"images":[],"step":4},{"title":"Peanuts","description":"Put peanuts in a tall jar that comfortably fits the head of a stick blender (or use a small blender). Cover the jar opening with your hand and pulse until finely ground.","images":[],"step":5},{"title":"Blitz paste","description":"Add drained chillis and remaining Curry Paste ingredients, along with 1/4 cup of the reserved chilli soaking liquid. Blend, scraping down the sides as you go, for about 30 seconds until smooth, using extra chilli water only if needed to help blend.","images":[],"step":6},{"description":"Cooking:","images":[],"step":7},{"title":"Cook curry paste","description":"Heat oil in a large deep frying pan over medium-low heat. Cook curry paste for 5 minutes, stirring constantly. The paste should be drier, darker, smelling aromatic and no longer raw.","duration":5,"images":[],"step":8},{"title":"Sauce","description":"Add 1 cup (250 ml) prawn stock, being careful to pour off just the clearer liquid and leaving the sediment behind. Stir in the coconut cream, sugar, fish sauce and salt. Mix in the green beans.","images":[],"step":9},{"description":"Simmer for 2 minutes until the sauce thickens and the beans are half cooked.","duration":2,"images":[],"step":10},{"description":"Add prawns, stir, then simmer for another 2 minutes until the prawns are cooked. Stir in the Thai basil leaves. The final taste should lean mostly savoury and sweet, and medium spiciness.","images":[],"step":11},{"description":"Serve over jasmine rice garnished with chopped peanuts, chilli and more Thai basil leaves!","images":[],"step":12}]', '["fish","shellfish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["cuisines","curry-recipes","iconic-dishes","prawns-shrimp","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_640c9bf238ad', 'en', 'US', 'Moroccan Lamb Meatballs', 'Recipe video above. The fragrance when these meatballs are cooking is outrageous! These meatballs are based on my fan-favourite Lamb Koftas, flavoured with a special blend of spices that smells so exotic but are everyday pantry staples!The Minted Yoghurt is fabulous - pairs so well with the flavour of these meatballs. See notes for suggestions for more sides - pictured in post stuffed in pita pockets.', 'https://www.recipetineats.com/tachyon/2017/07/Moroccan-lamb-meatballs_2.jpg', 25, 10, 30, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_mint", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 15.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_red_cabbage", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_coriander", "quantity": {"value": 0.15, "unit": "bunch"}}]', '[{"ingredients":["1 1/2 tbsp olive oil (for cooking)"]},{"ingredients":["500 g / 1 lb lamb mince (ground lamb) (Note 1)","1 small onion (, grated using box grater (~1/2 cup, including juices, Note 2))","1/2 cup panko breadcrumbs (sub ordinary)","1 egg","2 cloves garlic, crushed","1/4 cup coriander/cilantro leaves (, finely chopped)","1 1/2 tsp EACH cumin, coriander, paprika (any, but I like smoked paprika)","1/2 tsp EACH cinnamon, cayenne pepper (add more for spicy)","1 tsp cooking/kosher salt","1/4 tsp black pepper"],"purpose":"Meatballs:"},{"ingredients":["3/4 cup plain yoghurt (I use Greek)","1/2 cup (tightly packed) mint leaves","2 tsp lemon juice","1/4 tsp cooking/kosher salt"],"purpose":"Minted Yoghurt Sauce (Note 3):"},{"ingredients":["4 pita pockets (, Lebanese or pita bread)","5 cups shredded lettuce (iceberg, cost/romaine)","2 tomatoes (, halved, thinly sliced)","1 red onion (, halved, finely sliced)","OR Shredded Red Cabbage, Carrot and Mint Salad (instead of lettuce, tomato and onion)","Extra coriander/cilantro leaves, (finely chopped (optional))"],"purpose":"To Serve as pockets:"}]', '[{"title":"Mint yogurt sauce","description":"Set aside 1/2 cup yogurt. Place all other ingredients in a jug that fits the head of a stick blender. Blitz until it turns green - it will be runny. Stir in reserved yogurt (this thickens it again). Refrigerate until required.","images":[],"step":1},{"title":"Meatballs","description":"Place all Meatball ingredients in a bowl. Mix well with your hands. Measure out 1 heaped tablespoon, then roll into balls. Repeat with remaining mixture - should have 20 - 24 meatballs.","images":[],"step":2},{"title":"Cook","description":"Heat oil in a large non stick pan over medium heat. Add half the meatballs and cook, turning to brown all over, for 8 minutes, or until cooked through. Transfer to plate. (Oven option - Note 4)","duration":8,"images":[],"step":3},{"title":"Serving","description":"Cut pita pockets in half, warm for 10 seconds in the microwave, then pry it open. Stuff with lettuce, tomato, onion, then meatballs (I do 2 per half pocket). Drizzle with Mint Yogurt Sauce and fresh coriander.","duration":0.16666666666666666,"images":[],"step":4}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern","Moroccan"],"categories":["cuisines","dinner-tonight","lamb-recipes","main-dishes","meatball-recipes","middle-eastern-recipes","moroccan","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7b181e442b60', 'en', 'US', 'Thai Yellow Curry (from scratch!)', 'Recipe video above. Thai curries are famous for the sublime aromatic flavours balancing sweet, tart, savoury and spiciness. Thai Yellow Curry is one such magnificent example, with its rich yellow colour, incredible depth of flavour and a heady combination of both fresh and ground herbs and spices.This is made from scratch with a homemade Yellow Curry Paste. There are quite a few ingredients involved but if you truly want the best, it''s worth it!This is a creation the RecipeTin Team is proud to call our own - we worked damn hard on it! (Then we celebrated by making another 100 as the first meals we donated through RecipeTin Meals ❤️)SPICINESS: Adjust by varying fresh chilli. Use 1 for extremely mild, 2 for quite mild, 4 for spicy (but not blow-your-head off).', 'https://www.recipetineats.com/tachyon/2021/08/Thai-Yellow-Curry_26a.jpg', 30, 30, 60, 4, '[{"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_lemongrass", "quantity": {"value": 40.0, "unit": "bunch"}}, {"id": "ing_eschalots", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_turmeric", "quantity": {"value": 30.0, "unit": "jar"}}, {"id": "ing_galangal", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 13.333, "unit": "pack of 3 heads"}}, {"id": "ing_shrimp", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_fenugreek_powder", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.2, "unit": "carton of 250ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.025, "unit": "kg"}}, {"id": "ing_tamarind_puree", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_shrimp", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_bamboo_shoots", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 16.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["10 dried red chillis (~6cm/2.5\" long), chopped into 1cm / 0.5\" pieces (Note 1)","1 - 4 fresh birds eye chillis (, deseeded, roughly (1 for extremely mild, 4 for fairly spicy, Note 2))","2 lemongrass stems (Note 3)","1 large or 2 small eschalots (, roughly chopped (~ 1/2 cup) (Note 4))","2 tbsp fresh turmeric (, finely grated (about 2cm / 0.8\" piece) (Note 5))","2 tbsp galangal (, finely grated (about 2cm / 0.8\" piece) (Note 6))","8 cloves garlic (, roughly chopped)","1 1/2 tbsp Thai shrimp paste in bean oil (Note 7)","1 tsp ground coriander","1 tsp ground cumin","1/4 tsp ground cardamom","1/2 tsp fenugreek powder (Note 8)","1/8 tsp white pepper (sub black)"],"purpose":"Thai Yellow Curry Paste:"},{"ingredients":["3 tbsp vegetable oil (or canola or peanut oil)","1 medium potato (, peeled, cut into 2.5cm / 1\" pieces x 1cm/ 0.4\" thick (Note 9))","1 small carrot (, peeled, sliced into 5mm / 0.2\" slices on the diagonal)","1 cup chicken stock (, low sodium)","300 ml / 10oz coconut cream (Note 10)","4 tsp fish sauce (, plus more to taste (Note 11))","5 tsp white sugar","2 tsp tamarind puree (Note 12)","350g / 12oz prawns/shrimp (, medium, peeled, tail on optional (700g/1.4lb unpeeled) (Note 13))","1/2 cup bamboo shoots (, canned, drained, loosely packed (Note 14))"],"purpose":"Curry:"},{"ingredients":["16 Thai basil leaves (highly recommended, Note 15)","1 Red chilli (, finely sliced (optional, use large for not spicy))","2 tbsp Crispy fried shallots (optional, store bought, Note 16)","Jasmine rice"],"purpose":"Garnishes & serving:"}]', '[{"title":"Soak dried chillis","description":"Roughly chop chillies and transfer to bowl, leaving behind seeds. Cover with boiling water and soak for 30 minutes then drain (reserve soaking water).","duration":30,"images":[],"step":1},{"title":"Check spiciness","description":"Have a nibble of soaked chilli, should not be that spicy. If it is spicy, only use 1/3 to 1/2 of the amount (Note 1).","images":[],"step":2},{"title":"Prepare lemongrass","description":"Remove woody top half and outer layers of lemongrass. Grate with microplane. (See in post or video for preparation demo)","images":[],"step":3},{"title":"Make curry paste","description":"Place chillis, lemongrass and all remaining curry paste ingredients in a jar just wide enough to fit a stick blender. Add 3 tablespoons chilli soaking water. Blitz with stick blender until smooth so there''s no hard grit - rub between your fingers to check - about 15 seconds on high. (Or use small food processor or Nutribullet, scraping down sides well).","images":[],"step":4},{"title":"Cook off curry paste","description":"Heat oil in a medium heavy based skillet over medium heat. (Mine is a 26cm / 10.5\" Lodget cast iron) Add curry paste and cook for 3 to 4 minutes until it dries out a bit a smells fragrant.","duration":3.5,"images":[],"step":5},{"title":"Reduce stock","description":"Add chicken stock, stir to dissolve paste, then simmer for 1 minute.","duration":1,"images":[],"step":6},{"description":"Cook curry:","images":[],"step":7},{"title":"Add remaining curry sauce ingredients","description":"Reduce heat to medium low. Add tamarind, fish sauce and sugar. Stir until tamarind is dissolved. Then stir in coconut, carrot and potato.","images":[],"step":8},{"title":"Simmer","description":"Bring to simmer, then simmer gently for 15 minutes or until potato is almost fully soft. Pierce with knife to check, it might take 20 minutes.","duration":15,"images":[],"step":9},{"title":"Prawns and bamboo shoots","description":"Add prawns and bamboo shoots. Stir, then cook for 3 minutes until prawns are just cooked.","duration":3,"images":[],"step":10},{"title":"ADJUST sauce","description":"Taste and adjust the curry sauce at this point. Thin sauce with stock or water, add salt, fish sauce or sugar if needed. See Note 17.","images":[],"step":11},{"description":"Serve! Transfer curry to serving bowl. Garnish with Thai Basil, fresh chilli and crispy shallots. Serve with jasmine rice.","images":[],"step":12}]', '["fish","peanuts","shellfish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["cuisines","curry-recipes","iconic-dishes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3f949117e775', 'en', 'US', 'Vegetable Tagine', 'Recipe video above. A vegetarian Moroccan stew loaded with heady and warm spices, filled with tender vegetables. Make this with any veg you have - just don''t skimp on the spices!!Pan-roasting each vegetable to get a bit of colour on them before simmering is worth the effort to get the most flavour out of the vegetables. Because colour = flavour! Serve with couscous.', 'https://www.recipetineats.com/tachyon/2021/01/Vegetable-Tagine_3.jpg', 30, 60, 90, 8, '[{"id": "ing_cardamom_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_round_fennel_seeds_fennel_powder", "quantity": {"value": 7.5, "unit": "jar"}}, {"id": "ing_cayenne", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_turmeric", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_round_clove", "quantity": {"value": 7.5, "unit": "jar"}}, {"id": "ing_ginger", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.075, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_pumpkin", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_cauliflower", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.875, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chickpeas", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_60z_green_beans", "quantity": {"value": 200.0, "unit": "pack"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_almonds", "quantity": {"value": 0.3, "unit": "pack of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.003, "unit": "jar of 40g"}}]', '[{"ingredients":["1 tbsp cardamom powder","1 tbsp coriander powder","1 tbsp cumin powder","1 1/2 tsp ground fennel seeds / fennel powder","1 tsp cayenne (omit for non-spicy)","2 tsp turmeric","1/4 tsp ground cloves","1/4 tsp ground ginger"],"purpose":"Tagine spice mix:"},{"ingredients":["5 tbsp olive oil","1/2 red onion (sliced; (sub any type of onion))","1 garlic clove (, finely minced)","800g/1.6lb butternut pumpkin / squash ((1/2 a small), peeled, cut into 2.5cm / 1\" cubes)","1 small eggplant (, cut into 2.5cm / 1/2\" cubes)","1/2 cauliflower head (, small, cut into bite size florets)","1 capsicum / bell pepper (, cut into 2.5cm / 1\" pieces (red or yellow))","2 tomatoes (, seeds removed, cut into 1cm / 1/3\" dice)","3 1/2 cups water","2 tsp salt","1/2 tsp black pepper","400g/ 14oz canned chickpeas (, drained)","200g / 60z green beans (, cut into 3.5cm / 1.5\" pieces (~2 cups cut))","Zest of 1 lemon","2 tbsp lemon juice"],"purpose":"Tagine (Note 1):"},{"ingredients":["1/2 cup slivered almonds (, toasted)","1/4 cup coriander / cilantro (, roughly chopped)","Plain yogurt","Pinch of paprika or cayenne pepper"],"purpose":"Garnishes / for serving:"}]', '[{"description":"Combine Tagine Spice Mix ingredients.","images":[],"step":1},{"description":"Preheat oven to 180°C/350°F.","images":[],"step":2},{"description":"Heat 1 tbsp oil in a large, heavy-based pot over medium high heat. Add garlic and onion, cook until onion is wilted (~ 1 1/2 minutes), then remove to a large bowl. Scrape out any remaining garlic bits from pan (so they don''t burn).","images":[],"step":3},{"description":"Add pumpkin / squash and cook, stirring, for 3 minutes or until lightly golden on most sides. Remove to same bowl.","duration":3,"images":[],"step":4},{"description":"Add 2 tbsp olive oil. Cook eggplant for 3 minutes until tinged with gold on most sides, remove to same bowl.","duration":3,"images":[],"step":5},{"description":"Add 1 tbsp oil if pot is looking dry. Add capsicum and cauliflower, cook for 2 minutes until the cauliflower is a bit golden on the edges. Remove into bowl.","duration":2,"images":[],"step":6},{"description":"Add tomato and cook for 1 minute. Add Spice Mix, stir for 1 minute.","duration":1,"images":[],"step":7},{"description":"Add all vegetables back to pot. Add water (it should just about cover the vegetables, they will sink), salt and pepper. Stir, bring to simmer on stove, then transfer to oven for 30 minutes. (Alternatively simmer on low stove, but stir gently otherwise veg may breakdown too much.)","duration":30,"images":[],"step":8},{"description":"Remove from oven, add beans and chickpeas. Simmer for 15 minutes uncovered on stove on medium-low to cook the beans and reduce the sauce.","duration":15,"images":[],"step":9},{"description":"Stir through lemon juice and zest. The idea here is that some of the veg (butternut, cauliflower) breaks down a bit to slightly thicken the sauce. It also gets thicker left overnight.","images":[],"step":10},{"description":"For a traditional experience, serve over couscous. Otherwise, try white, brown, or basmati rice, or quinoa. Or, serve just as is like a chunky stew. For a low-carb option try cauliflower rice! I like to top mine with a dollop of yogurt, a sprinkle of almonds, coriander/cilantro and a pinch of paprika or cayenne.","images":[],"step":11}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern","Moroccan"],"categories":["cuisines","dietary","gluten-free-recipes","low-calorie-recipes","middle-eastern-recipes","moroccan","stews","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5a8ea660f762', 'en', 'US', 'Lamb Shanks Massaman Curry', 'Recipe video above. Epic combination - fall apart lamb shanks in a rich massaman curry sauce, a wildy popular dish at upscale Thai restaurants! The coconut and spice infused flavour of the curry sauce is a dead set perfect match with the flavour of lamb meat. Don''t be fooled by the simplicty of this recipe - hours in the oven works magic. (Read in post if you are dubious!)SPICINESS - mild! Massaman curry is one of the mildest curries in Thai cuisine.', 'https://www.recipetineats.com/tachyon/2020/06/Lamb-Shanks-Massaman-Curry_0.jpg', 5, 180, 185, 5, '[{"id": "ing_lamb", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_maesri_massaman_curry_paste", "quantity": {"value": 114.0, "unit": "bottle"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_potato", "quantity": {"value": 400.0, "unit": "bag of 2kg"}}, {"id": "ing_star_anise", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1.5kg/ 3 lb lamb shanks (5 small, 4 medium, 2 - 3 large) (Note 1)","114g/ 4oz Maesri Massaman curry paste (1 can) (, or other brand (Note 2))","400ml/ 14oz coconut milk (, full fat (Ayam brand is best, Note 3))","2 cups chicken stock/broth (, low sodium (Note 4))","1 onion (, halved then sliced 1cm / 1/3\" thick (brown, white, yellow))","400g/ 14oz small potatoes (2.5cm/1\" wide, halve if bigger)","1 star anise","1 cinnamon stick"]},{"ingredients":["Red chilli (, finely sliced (small = spicy, large = less spicy))","Coriander/cilantro","Steamed jasmine rice"],"purpose":"Garnishes:"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":1},{"description":"Mix curry paste, coconut milk and stock in a 22 x 33cm / 9 x 13\" baking dish, preferably glass or ceramic (Note 5). Add onion, potato, star anise, cinnamon and lamb.","images":[],"step":2},{"description":"Turn shanks to coat in sauce, then cover with foil.","images":[],"step":3},{"description":"Bake in oven for 2 hours. Remove foil, bake for a further 1 hour (small shanks) or 1.5 hrs (medium to large shanks), turning lamb twice to brown evenly, until meat is so tender it can easily be teased apart with 2 forks.","images":[],"step":4},{"description":"Remove lamb onto plate. Carefully skim off excess fat off the surface (tilt dish, it''s easier) - I get about 1/3 cup. Mix sauce in baking dish - it should be reduced down to a syrupy thickness (Note 6).","images":[],"step":5},{"description":"Serve lamb with sauce over jasmine rice, garnished with chilli and coriander. For a larger banquet, put the curry out on a platter to share!","images":[],"step":6}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Modern Asian","Thai"],"categories":["cuisines","curry-recipes","iconic-dishes","lamb-recipes","lamb-shanks","slow-cooked-fall-apart","stews","sunday-supper","thai-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b357ff850d2b', 'en', 'US', 'Thai Green Curry', 'Recipe video above. This is how to make a really great QUICK green curry by pimping up curry in a jar, OR using a homemade green curry paste! Don''t skip frying off the curry paste, this makes all the difference. See Spiciness info in Note 1 (remember, Green Curry is supposed to be spicy!)', 'https://www.recipetineats.com/tachyon/2019/02/Thai-Green-Curry_5.jpg', 15, 20, 35, 4, '[{"id": "ing_thai_red_curry_paste", "quantity": {"value": 4.0, "unit": "bottle"}}, {"id": "ing_quantity_homemade_green_curry_paste", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 666.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_lemongrass", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 6.0, "unit": "net of 500g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 0.167, "unit": "carton of 12"}}, {"id": "ing_snow_peas", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_basil", "quantity": {"value": 16.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 6.0, "unit": "net of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_jasmine_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["4 - 6 tbsp Thai Green Curry Paste (Maesri best) OR (Note 1)","1 quantity homemade green curry paste (Note 1)"],"purpose":"Curry – use ONE:"},{"ingredients":["2 large garlic cloves (, minced)","2 tsp fresh ginger (, finely grated)","1 tbsp lemongrass paste (Note 2)"],"purpose":"Extras – for jar curry paste (Note 2):"},{"ingredients":["2 tbsp vegetable oil","1 cup (250ml) chicken or vegetable broth, low sodium","400 g/14oz coconut milk (, full fat (Note 4))","1 - 3 tsp fish sauce *","1 - 3 tsp white sugar *","1/8 tsp salt *","6 kaffir lime leaves (, torn in half (Note 5))","350 g/12 oz chicken thigh (, skinless boneless, sliced (Note 6))","2 Japanese eggplants, (, small, 1cm / 2/5\" slices (Note 7))","1 1/2 cups snow peas (, small, trimmed)","16 Thai basil leaves (Note 8)","Juice of 1/2 lime (, to taste)"],"purpose":"Green Curry:"},{"ingredients":["Crispy fried Asian shallots (, high recommended (Note 9))","Thai basil or cilantro/coriander (, recommended)","Green or red chillies slices (, optional)","Steamed jasmine rice"],"purpose":"Garnishes:"}]', '[{"description":"Heat oil in a heavy based skillet or pot over medium high heat.","images":[],"step":1},{"description":"Add curry paste (and garlic, ginger and lemongrass Extras, if using) and cook for 2 to 3 minutes until it mostly \"dries out\" - see video. Don''t breath in the fumes!!","duration":2.5,"images":[],"step":2},{"description":"Add chicken broth and coconut milk, mix to dissolve paste.","images":[],"step":3},{"title":"Curry in a jar seasonings","description":"Add 1 tsp fish sauce, 1 tsp sugar, no salt.","images":[],"step":4},{"title":"Homemade curry paste seasonings","description":"Add 3 tsp fish sauce, 3 tsp sugar, 1/8 tsp salt.","images":[],"step":5},{"description":"Add kaffir lime leaves. Mix then bring to simmer.","images":[],"step":6},{"description":"Add chicken, stir then lower heat to medium so it''s bubbling gently. Cook 7 minutes.","images":[],"step":7},{"description":"Add eggplants, cook 5 minutes until soft.","images":[],"step":8},{"description":"Taste sauce. Add fish sauce or salt for more saltiness, sugar for sweetness.","images":[],"step":9},{"description":"Add snow peas, cook 2 minutes until a bit softened, then stir through basil and lime juice. Sauce should have reduced but will still be a be on the thin side, not thick - that''s how it''s should be. DO NOT keep simmering - sauce will darken.","images":[],"step":10},{"description":"Serve curry over jasmine rice with garnishes of choice.","images":[],"step":11}]', '["fish"]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Thai"],"categories":["cuisines","curry-recipes","iconic-dishes","thai-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_911abc5e0cf9', 'en', 'US', 'Middle Eastern Shredded Lamb', 'I can''t say with certainty that this is authentic because it''s a recipe I created. But it uses classic Middle Eastern ingredients, so possibly it is! The lamb is really juicy because it''s made with lamb shoulder, a cut that is made for slow cooking. The pan frying step to get the crunchy brown bits is not optional - it''s key! ! ! As with any shredded meat recipe, a little goes a long way. This makes around 8 cups of shredded lamb which I think is enough to serve 8 people as a main (with rice). See separate recipe below for Chickpea Pilaf (Rice).', 'https://www.recipetineats.com/tachyon/2015/05/Middle-Eastern-Shredded-Lamb-Chickpea-Pilaf-Rice-1.jpg', 10, 210, 220, 8, '[{"id": "ing_cumin", "quantity": {"value": 0.005, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_paprika", "quantity": {"value": 0.005, "unit": "jar of 40g"}}, {"id": "ing_cardamon", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.068, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.006, "unit": "pack of 3 heads"}}, {"id": "ing_lamb", "quantity": {"value": 1.75, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}]', '[]', '[{"description":"Preheat oven to 150C/300F.","images":[],"step":1},{"description":"Combine the Spice Mix ingredients in a small bowl. Set aside 1 1/2 tbsp of the Spice Mix for later (to pan fry the lamb).","images":[],"step":2},{"description":"Add the olive oil and garlic into the Spice Mix, then rub all over the lamb.","images":[],"step":3},{"description":"Place the lamb on a roasting rack set in a roasting dish (Note 1). Pour the water in the base of the dish. Cover with a lid or double layer of foil.","images":[],"step":4},{"description":"Roast for 3 1/2 hours or until the meat is tender enough to pull off with a fork.","images":[],"step":5},{"description":"Remove the lid. Turn the oven up as high as it will go and roast for 15 - 20 minutes until the lamb is browned.","duration":17.5,"images":[],"step":6},{"description":"Remove the lamb from the oven. Allow to rest for 20 minutes, then shred coarsely with two forks.","duration":20,"images":[],"step":7},{"description":"Skim excess fat off the juices in the roasting dish then set aside. (Note 2)","images":[],"step":8},{"description":"Browning the Shredded Lamb","images":[],"step":9},{"description":"Toss the shredded lamb with the reserved Spice Mix (from Step 2 above).","images":[],"step":10},{"description":"Heat 1 tbsp of oil in a heavy based pan over high heat. Add some lamb (don''t crowd the pan) and drizzle over about 3 tbsp of the pan juices. Cook until the underside is dark golden brown and crispy - about 1 to 1 1/2 minutes (the juices you poured over will evaporate).","images":[],"step":11},{"description":"If the lamb is cold, flip to warm the other side but do not brown too much (retains juiciness).","images":[],"step":12},{"description":"Remove lamb from the fry pan, and repeat with remaining lamb, adding extra oil if required.","images":[],"step":13},{"description":"To serve, drizzle with a squeeze of lemon juice (this makes a big difference) and top with fresh coriander, plus yoghurt (if using). Serve on Chickpea Pilaf (Rice).","images":[],"step":14}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Middle Easter / Moroccan"],"categories":["cuisines","dietary","gluten-free-recipes","lamb-recipes","main-dishes","middle-eastern-recipes","rice-recipes","side-dishes","slow-cooker-recipes","sunday-supper","uncategorized","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_76db1d8792e7', 'en', 'US', 'Melting Afghan chickpea curry', 'Recipe video above. I never knew chickpeas could be so meltingly creamy by adding a smidge of baking soda! I also love how the sauce is thickened by cooking lentils until they breakdown, two neat tricks picked up from this Pakistani Lahori Chanay by Sugar Spice & More. Combined with an Afghan spice mix from the chickpea curry in Parwana, a wonderful Afghan cookbook by Durkhanai Ayubi, adapted in pursuit of recreating the chickpea curry I had from Afghan Sufra in Lakemba, an area of Sydney known for its wonderful Middle Eastern and sub-continental food scene. I’m obsessed!', 'https://www.recipetineats.com/tachyon/2025/05/Afghani-Chickpea-Curry_0.jpg', 15, 45, 60, 5, '[{"id": "ing_ghee", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 2.0, "unit": "jar"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 7.5, "unit": "pack of 3 heads"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_lentils", "quantity": {"value": 0.188, "unit": "can of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_chickpeas", "quantity": {"value": 3.0, "unit": "can of 400g"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.006, "unit": "tub of 200g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 7.5, "unit": "jar"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_round_clove", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["3 tbsp ghee (, substitute unsalted butter or coconut oil (for vegan))","2 cinnamon sticks (sub 1/2 tsp powder, add with other spices)","1 onion (, finely chopped)","1 1/2 tbsp grated ginger","1 1/2 tbsp grated garlic","2 bay leaves (, preferably fresh else dried)","1/2 cup dried red split lentils (Note 1)","1 cup water","1 litre vegetable stock (, low sodium)","1/2 tsp cooking / kosher salt","3 x 400g/14oz cans chickpeas (, drained (Note 2))","1/4 tsp baking soda / bi-carbonate soda (makes chickpeas creamy, optional)"]},{"ingredients":["1 tbsp coriander powder","1 tbsp cumin powder","1 1/2 tsp turmeric powder","3/4 tsp cardamom powder","1/4 tsp ground cloves"],"purpose":"Spices (Note 3):"},{"ingredients":["Basmati rice (and/or Afghan bread (Note 4), or other flatbread)","Yogurt (I like to slightly thin with water so it can be drizzled)","Fresh coriander / cilantro leaves (, roughly chopped)"],"purpose":"Serving:"}]', '[{"title":"Sauté","description":"Melt the ghee in a large pot over medium high heat. Add the cinnamon and toast for 30 seconds. Add the onion, ginger, garlic and bay leaves. Cook for 3 minutes until the onion is translucent (stir regularly so the garlic & ginger don''t catch).","duration":0.5,"images":[],"step":1},{"title":"Spices and lentils","description":"Add the Spices and stir for 30 seconds. Add the lentils and stir to coat in the spices.","duration":0.5,"images":[],"step":2},{"title":"Simmer lentils","description":"Add the stock and salt. Stir, bring to a simmer. Lower the head to medium, put the lid on and simmer for 15 minutes.","duration":15,"images":[],"step":3},{"title":"Simmer chickpeas","description":"Add the chickpeas, water and baking soda. Increase the heat to make it simmer again. Then lower the stove slightly and leave to simmer gently for 30 minutes without a lid or until the lentils mostly broken down to make a thin gravy (you can cook an extra 10 minutes to thicken more if you want).","duration":30,"images":[],"step":4},{"description":"Serve with rice on the side and Afghan or other flatbreads for dunking, drizzled with yogurt and sprinkled with fresh coriander if you want (I do).","images":[],"step":5}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["Afghan","Middle Eastern"],"categories":["curry-recipes","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e669ddde7782', 'en', 'US', 'Lamb korma curry', 'Recipe video above. In stark contrast to bold spicy curries like Vindaloo, Lamb Korma is creamy, nutty and gently spiced. It''s easy to love and so family-friendly, I call it the "other butter chicken"! Slow cooked until the meat is fall-apart tender, I particularly love the subtle cashew flavour in the sauce from the pureed cashews, and the distinct flavour that lamb adds to sauce.* Oven method yields the best flavour but see note 8 for slow cooker, instant pot and pressure cooker methods. Super handy, and I was very happy with it!', 'https://www.recipetineats.com/tachyon/2024/05/Lamb-korma_main.jpg', 20, 150, 170, 4, '[{"id": "ing_onion", "quantity": {"value": 2000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 2666.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_cashews", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_ghee", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_lamb", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_round_turmeric", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_ginger", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_aram_marsala", "quantity": {"value": 5.5, "unit": "unit"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 10.0, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 2.0, "unit": "jar"}}, {"id": "ing_sugar", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_naan", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 large onions (, cut into 1cm/1/2\" squares (brown or yellow))","8 large garlic cloves (, peeled, halved)","4cm/ 1.5\" piece ginger (, peeled, sliced 3mm/0.2\" thick)"],"purpose":"Onion paste:"},{"ingredients":["1/4 cup cashews (, roasted, unsalted (~20 cashews))","1/3 cup water"],"purpose":"Cashew puree:"},{"ingredients":["3 tbsp ghee ((Note 1), or unsalted butter)","800g / 1.6 lb lamb shoulder ((Note 2), trimmed off excess fat, cut into 4-5 cm / 2\" cubes)","1/2 tsp ground turmeric","2 1/2 tsp ground ginger","5 1/2 tsp garam marsala (Note 3)","1 tsp kashmiri chilli powder (or smoked paprika + cayenne - Note 4)","2 cups chicken stock/broth (, low-sodium)","10 cardamom pods (green), lightly crushed, wrapped and tied in muslin or cheesecloth (Note 5)","2 cinnamon sticks","4 tsp white sugar","1 1/2 tsp cooking salt / kosher salt","1/2 cup coconut cream (, full-fat (Note 6))","1/2 cup cream (, full-fat (any type - thickened/heavy, pure etc)(Note 6))"],"purpose":"Lamb korma"},{"ingredients":["Basmati rice (or other plain white rice of choice)","Naan (, for dunking! (optional))","Cashews finely chopped (optional sprinkle)","Coriander/cilantro leaves (, roughly chopped (optional garnish))"],"purpose":"SERVING"}]', '[{"title":"Onion puree","description":"Place the onion, garlic and ginger into a tall container that fits the head of a stick blender. Blitz until smooth – about 5 to 10 seconds. Scrape into a bowl, set aside.","images":[],"step":1},{"title":"Cashew puree","description":"In the same jar, while covering the mouth of the jar with your hand (to prevent flying cashew comets), blitz the cashews and water with the stick blender until smooth, about 10 seconds. , Set aside.","images":[],"step":2},{"description":"Preheat the oven to 180°C/350°F (160°C fan-forced).","images":[],"step":3},{"title":"Reduce onion puree","description":"Melt and heat ghee in a ~24 cm/ 10\" oven-proof pot over high-heat. Cook the onion puree, stirring regularly, for 8 minutes until it has reduced by half. Don’t let it caramelise.","duration":8,"images":[],"step":4},{"description":"Add lamb, reduce to medium-high heat then stir until the meat changes from red to light brown. Don’t try to brown the meat (it won''t happen).","images":[],"step":5},{"title":"Sauce","description":"Add turmeric, ground ginger, garam marsala and kashmiri chilli, then stir through. Pour in the stock (the liquid should just barely cover the meat). Add cardamom pod sachet and cinnamon sticks, then stir. Bring to a simmer, cover with a lid then transfer to the oven.","images":[],"step":6},{"title":"Slow cook","description":"Cook for 1 1/2 hours. Stir in Cashew Puree, put the lid back on then return to the oven for another 30 minutes. The sauce should have thickened to a creamy consistency and lamb should be tender end to pull apart with forks with no effort. (Note 6)","images":[],"step":7},{"title":"Creamy sauce","description":"Place the pot on a low heat. Add the sugar, salt, coconut cream and cream, then stir. Simmer for 2 minutes, then you’re done!","duration":2,"images":[],"step":8},{"description":"Serve over basmati rice with a sprinkle of cashew nuts and coriander, if desired. Naan for dunking highly recommended!","images":[],"step":9}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["curry-recipes","indian-recipes","stews"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_48fe9b3f9de7', 'en', 'US', 'Vindaloo', 'Recipe video above. Vindaloo is a traditional Indian curry that''s not for the faint hearted! Big, bold curry flavours. Deep, vibrant red colour. Chunks of beef slow cooked to fall apart perfection. And yep, it''s spicy! For serious curry lovers, it''s hard to top this. As with all curries, use fresh spices for the best results (yes, spices fade in flavour over time). And no, unfortunately this won''t work in a slow cooker, pressure cooker or instant pot (Note 7).Serve with naan for mopping and yogurt for cooling. ** SPICE WARNING!!! Read Spiciness note below. **', 'https://www.recipetineats.com/tachyon/2021/07/Beef-Vindaloo_1.jpg', 20, 150, 170, 4, '[{"id": "ing_beef", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.9, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_s", "quantity": {"value": 4.0, "unit": "pack"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 4.0, "unit": "jar of 40g"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_ginger", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_fenugreek_seeds", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_turmeric", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.105, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_ghee", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_mustard", "quantity": {"value": 0.037, "unit": "jar of 200g"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_curry_leaves", "quantity": {"value": 10.0, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["800g / 1.6 lb beef chuck (, cut into 3cm / 1.2\" cubes (Note 1))","1 1/2 tsp salt"]},{"ingredients":["6 tbsp Kashmiri chilli powder - TEST spiciness before using! (Note 2)","2 tsp coriander seeds","3 tsp cumin seeds","4 cloves","4 cardamom pods (green)","2 tsp cinnamon powder","1/2 tsp black peppercorns","2 tbsp fresh ginger (, roughly chopped)","10 garlic cloves (yes, 10!)","1 tsp brown sugar","1 tsp fenugreek seeds (Note 3)","1/4 tsp turmeric powder","7 tbsp white vinegar","2 cups water"],"purpose":"Curry paste:"},{"ingredients":["50g / 3 tbsp ghee or unsalted butter (Note 4)","1 onion (, finely chopped (brown, yellow, white))","2 tsp ginger (, finely grated)","4 garlic cloves (, finely minced)","1 1/2 tsp black mustard seeds (Note 5)","2 tbsp tomato paste","10 curry leaves (, fresh (Note 6))","2 cups beef stock (, low sodium (if using homemade, add 1/2 tsp salt))"],"purpose":"Curry sauce:"},{"ingredients":["2 tbsp coriander/cilantro leaves (, roughly chopped)"],"purpose":"Garnish:"}]', '[{"title":"Salt beef","description":"Toss beef in salt.","images":[],"step":1},{"description":"Check spiciness of kashmiri chilli powder and adjust if desired. See Spiciness Note below.","images":[],"step":2},{"title":"Curry Paste","description":"Place Curry Paste ingredients in a Nutribullet or small food processor with 1 cup of the water. Blitz until smooth. Pour over beef. Pour remaining 1 cup water into Nutribullet, shake (to clean out remaining curry paste), then pour/scrape over beef.","images":[],"step":3},{"title":"Marinate beef","description":"Mix beef in curry paste, cover, then marinate 2 hours. (Note: marinade is fairly thin - the water cooks down during slow cooking.)","images":[],"step":4},{"description":"Preheat oven to 190°C/375°F (170°C fan).","images":[],"step":5},{"title":"Curry sauce","description":"Melt ghee over medium high. Cook onion, ginger and garlic until they become translucent - about 3 minutes.","images":[],"step":6},{"title":"Mustard seeds","description":"Add black mustard seeds then cook until onion is tinged with gold. Stir in tomato paste, cook 1 minute.","images":[],"step":7},{"title":"Puree sauce","description":"Add beef stock, stir. Transfer into a jug then use a stick blender to puree until smooth. Pour back into the pot.","images":[],"step":8},{"title":"Add beef","description":"Add beef and curry leaves, stir then bring to boil.","images":[],"step":9},{"title":"Slow cook","description":"Cover with a lid, then place in the oven for 2 hours or until beef is fall apart tender and the sauce has darkened in colour and thickened. (See Note 7 if sauce hasn''t reduced enough).","images":[],"step":10},{"title":"Serve","description":"Garnish with coriander, then serve over basmati rice with a side of naan!","images":[],"step":11}]', '["milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["curry-recipes","indian-recipes","slow-cooked-fall-apart","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_92e4271893a8', 'en', 'US', 'Palak Paneer – Indian Spinach Curry with Homemade Fresh Cheese', 'Recipe video above. A dish this iconic demands to be made properly – from scratch, with lots of fresh spinach and homemade paneer (Indian fresh cheese!) This is a magnificent vegetarian curry, packed with an extraordinary amount of nutrition and goodness!', 'https://www.recipetineats.com/tachyon/2021/02/Indian-Palak-Paneer_4.jpg', 45, 25, 70, 6, '[{"id": "ing_batch_homemade_paneer", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_ghee", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.5, "unit": "pack of 1kg"}}, {"id": "ing_fenugreek_seeds", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.01, "unit": "pack of 100g"}}, {"id": "ing_spinach", "quantity": {"value": 700.0, "unit": "bag of 250g"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.333, "unit": "carton of 250ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}]', '[{"ingredients":["1 batch homemade Paneer (Indian fresh cheese; recipe linked below)","30g / 2 tbsp ghee or unsalted butter (for pan frying, Note 2)"],"purpose":"Homemade Paneer (Note 1):"},{"ingredients":["30g/2 tbsp ghee or unsalted butter (Note 2)","1 1/2 onions (, finely chopped (brown or yellow))","1 tsp fenugreek seeds (whole) (Note 3)","1 tsp ground cumin","1 tsp ground coriander","3/4 tsp salt (, kosher/cooking salt (if using table salt, reduce by 1/4 tsp))","1/4 tsp black pepper","2 garlic cloves (, finely chopped)","2 tsp ginger (, finely grated (20g))","2 tomatoes (, peeled, seeded and diced (Note 4))","1 green chilli (, finely sliced (cayenne, Note 5))","700g/ 1.4lb fresh spinach leaves (English spinach) (, thoroughly washed and roughly chopped (~9 cups very tightly packed) (Note 6))","1/4 cup water","1/3 cup + 1 tbsp cream (pure, heavy or thickened)","1 tbsp lemon juice"],"purpose":"Palak Paneer:"}]', '[{"title":"Saute onion & spices","description":"Melt butter in a large pot over medium heat. Add onion, fenugreek, cumin, coriander, salt and pepper. Cook for 3 minutes until onion is softened but not golden.","duration":3,"images":[],"step":1},{"description":"Add garlic and ginger, cook for 2 minutes.","duration":2,"images":[],"step":2},{"description":"Add the tomato and chilli, cook for 3 minutes on a medium heat.","duration":3,"images":[],"step":3},{"title":"Add spinach: Add about 1/3 of the spinach","description":"or as much as you can handle in the pot (!) – and stir until wilted. Then add more spinach along with the water, cook again until wilted. Repeat until all the spinach is wilted.","images":[],"step":4},{"title":"Cook 10 minutes","description":"Cook, stirring every now and then, for 10 minutes still on a medium heat.","duration":10,"images":[],"step":5},{"title":"Cream & lemon","description":"Add the cream and lemon juice. Cook, stirring gently, for 3 minutes.","duration":3,"images":[],"step":6},{"title":"Puree half spinach","description":"Remove half the spinach into a tall container and blend it to a puree using a stick blender. Pour pureed spinach back into the pot, and stir to combine.","images":[],"step":7},{"title":"Add Pan Fried Paneer","description":"Gently stir in golden pan-fried paneer (see below). Stir gently to mix through.","images":[],"step":8},{"description":"Serve over basmati rice with fluffy, chewy homemade naan on the side!","images":[],"step":9},{"description":"Golden Pan-Fried Paneer (Note 8):","images":[],"step":10},{"description":"Cut paneer into 1.25cm / ½\" thick slices. Then cut each slice into 2.5cm x 2 x 1.25cm thick pieces / 1 x ⅘\" x ½\" pieces – approximately!","images":[],"step":11},{"description":"Melt half the ghee or butter in a non-stick pan over medium-high heat.","images":[],"step":12},{"title":"Place half the paneer in the pan and cook for 1","description":"1 1/2 minutes until light golden - I tend to make it deep golden because colour = more flavour, but traditional is just a hint of gold Turn, then cook the other side until light golden.","images":[],"step":13},{"description":"Remove onto paper towel-lined plate. Repeat with remaining butter and paneer. Use per recipe.","images":[],"step":14}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["curry-recipes","iconic-dishes","indian-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0c5641317a17', 'en', 'US', 'Goan Fish Curry', 'Recipe video above. This famous Goan fish curry comes to you from Goa, a little pocket of Indian paradise that''s all about the sun, surf, sand and excellent seafood! Deeply aromatic with a tomato and coconut based sauce, this recipe has a few more spices and steps than the more home-style recipes you''ll find online because this aims to replicate the richer sauce and layers of flavour you get at (good) Indian restaurants.Once you''ve made this with fish, try it with prawns/shrimp - it''s also excellent!SPICINESS: Quite spicy as written, but not blow-your-head-off! I thoroughly enjoy it as written, not suffering. See Spice Note below for adjustment to reduce / eliminate spiciness.', 'https://www.recipetineats.com/tachyon/2020/10/Goan-Fish-Curry_6.jpg', 15, 20, 35, 4, '[{"id": "ing_chilli", "quantity": {"value": 20.0, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_fenugreek_powder", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_round_clove", "quantity": {"value": 1.875, "unit": "jar"}}, {"id": "ing_garlic", "quantity": {"value": 10.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_tamarind_puree", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_water", "quantity": {"value": 0.09, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_coconut_milk", "quantity": {"value": 1.0, "unit": "can of 400ml"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 20.0, "unit": "pack of 100g"}}, {"id": "ing_chilli", "quantity": {"value": 20.0, "unit": "pack of 100g"}}, {"id": "ing_tomato", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 20.0, "unit": "pack of 100g"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 1/2 tbsp Kashmiri chilli powder (Note 1)","1 tbsp coriander","2 tsp cumin","1 tsp turmeric","1/2 tsp fenugreek powder (Note 2)","3/8 tsp ground cloves","6 cloves garlic (, minced)","1 tbsp fresh ginger (, finely grated)","2 tbsp tamarind puree (Note 3)","1/2 red onion (, chopped)","6 tbsp water (plus more, as needed)"],"purpose":"Curry paste:"},{"ingredients":["3 tbsp vegetable oil","1/2 tsp black mustard seeds (Note 4)","1/2 red onion (, cut in half again (like a quartered orange) and thinly sliced)","1 tbsp tomato paste","2/3 cup canned tomato pulp/polp (Mutti), OR tomato passata or crushed tomato, Note 5)","2/3 cup water","400ml/ 14oz coconut milk (, full fat (Note 6))","1 1/4 tsp salt (, cooking/kosher (or 3/4 tsp fine table salt))","1 1/2 tsp sugar","1/4 tsp chilli powder (pure chilli, not US Chili Powder which is a mix, Note 7)","2 long green chillies (, cut into half lengthwise and deseeded, optional (Note 8))","1 tomato (, cut into 8 wedges then into 2.5cm / 1\" chunks)","600g / 1.2 lb firm-fleshed white fish (, cut into 3cm / 1.25\" cubes (Note 9))"],"purpose":"Curry:"},{"ingredients":["1/4 cup fresh coriander/cilantro leaves","Finely sliced green chillies (, optional)","Basmati rice"],"purpose":"Garnishes / serving:"}]', '[{"description":"Place Curry Paste ingredients in a tall jug or milkshake container (something that fits the head of a blender stick) then blitz on high for 5 to 10 seconds until the onion is pureed. Add more water if needed to make it puree.","duration":0.125,"images":[],"step":1},{"title":"Sizzle black mustard seeds","description":"Heat oil over medium heat in a large pot. Add black mustard seeds and let them sizzle for 30 seconds - careful, they might pop!","duration":0.5,"images":[],"step":2},{"title":"Saute onion","description":"Add red onion and cook for 3 minutes until edges start to tinge with gold.","duration":3,"images":[],"step":3},{"title":"Cook off curry paste","description":"Add curry paste and cook for 3 minutes - to evaporate water, make spices bloom and cook garlic & ginger.","duration":3,"images":[],"step":4},{"title":"Cook off tomato","description":"Turn heat up to medium high. Add tomato paste and tomato pulp, cook for 2 minutes.","duration":2,"images":[],"step":5},{"title":"Coconut milk","description":"Add water, coconut milk, sugar, salt and chilli powder if using. Stir, then bring to simmer, low heat so it''s bubbling gently.","images":[],"step":6},{"title":"Simmer 2 minutes, add tomato & green chilli","description":"Simmer for 2 minutes, add tomato and green chilli.","duration":2,"images":[],"step":7},{"title":"Simmer 3 minutes","description":"Simmer for another 3 minutes, stirring every now and then - sauce should be thickened (not watery), it gets looser again when fish is added (because fish will drop some juices = even more flavour!).","images":[],"step":8},{"title":"Add fish","description":"Add fish, stir, cook for 3 to 4 minutes until fish easily flakes.","duration":3.5,"images":[],"step":9},{"title":"Garnish & serve","description":"Remove from stove and transfer to serving bowl. Garnish with coriander/cilantro and fresh green chillies if desired. Serve with basmati rice!","images":[],"step":10}]', '["fish","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["curry-recipes","fish-recipes","indian-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_92c0519c1b52', 'en', 'US', 'Rogan Josh (Indian Lamb Curry)', 'Recipe video above. An Indian lamb curry to die for! A heady combination of intense spices in a creamy tomato curry sauce, the lamb is fall apart tender and packs a serious flavour punch. While this recipe calls for a lengthy list of spices, you won''t need to take a trip to an Indian store to get them - they''re even sold at my local grocery store!', 'https://www.recipetineats.com/tachyon/2020/02/Rogan-Josh_4.jpg', 20, 150, 170, 4, '[{"id": "ing_hee", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.15, "unit": "jar of 40g"}}, {"id": "ing_s", "quantity": {"value": 4.0, "unit": "pack"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_lamb", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_paprika", "quantity": {"value": 0.75, "unit": "jar of 40g"}}, {"id": "ing_chilli", "quantity": {"value": 0.037, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.4, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.5, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_nutmeg_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_garam_marsala", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_fennel", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.15, "unit": "tub of 500g"}}, {"id": "ing_garam_masala", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_fennel", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.4, "unit": "bunch"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["3 1/2 tbsp ghee (, substitute butter (Note 1))","1 cinnamon stick","6 green cardamom pods (, lightly bruised)","4 cloves","1 large onion (, finely chopped)","3 cloves garlic (, finely minced)","1 tbsp ginger (, finely grated)","5 tbsp tomato passata (US: tomato puree/sauce, Note 5)","1 tsp cooking salt / kosher salt (halve for table salt, double for flakes)","750g/1.5lb boneless lamb shoulder (, cut into 3cm/1.2\" cubes (Note 6))","1 1/2 cups chicken stock (, salt reduced (broth))"]},{"ingredients":["2 tbsp paprika (, normal or sweet)","3/4 tsp chilli powder (or to taste, Note 2)","4 tsp ground coriander","4 tsp ground cumin","2 tsp turmeric powder","1/4 tsp nutmeg powder","1 tsp garam marsala (Note 3)","1/2 tsp fennel powder (Note 4)"],"purpose":"SPICES:"},{"ingredients":["1/2 cup plain yoghurt (Greek yogurt fine)","1/2 tsp extra garam masala (Note 3)","1/2 tsp extra fennel powder"],"purpose":"FINISHES"},{"ingredients":["Chopped coriander leaves, finely shredded ginger, yogurt","Basmati rice"],"purpose":"SERVING/GARNISH"}]', '[{"description":"Toast whole spices in ghee, then sauté onion, garlic and ginger. Toast ground spices 30 seconds, add tomato, salt, stock and lamb. Simmer gently covered 1 hr 45 min until lamb fork-tender, simmer with lid off 15 min to reduce. Stir in Finishes, serve!","images":[],"step":1},{"title":"Toast whole spices","description":"Melt ghee over medium heat in large heavy based pot. Add cinnamon, cardamom and cloves and cook for one minute.","images":[],"step":2},{"title":"Sauté","description":"Add onion and cook for 7 minutes, stirring frequently, until pieces are golden and starting the brown on the edges. Add the garlic and ginger, cook for another minute.","duration":7,"images":[],"step":3},{"title":"Toast spices","description":"Stir in the Spices, cook for 30 seconds.","duration":0.5,"images":[],"step":4},{"title":"Sauce and lamb","description":"Mix in the tomato puree and salt, then add stock and mix. Add lamb, stir, bring to simmer.","images":[],"step":5},{"title":"Simmer 1 h 45 min","description":"Place lid on and adjust heat to low or medium low so it''s simmering gently. Cook 1 hour 45 minutes, giving it an occasional stir, until lamb is quite tender - use 2 forks to check, it should pry apart pretty easily.","images":[],"step":6},{"title":"Reduce","description":"Remove lid, and continue cooking for another 15 minutes (to reduce sauce slightly) - lamb should be very tender by this stage.","images":[],"step":7},{"title":"Finish","description":"Stir in the Yogurt, the Extra garam marsala and fennel. Cook for another few minutes.","images":[],"step":8},{"description":"Serve with basmati rice, sprinkled with fresh coriander leaves and other garnishes if desired. More sides (pictured): Cucumber salad (Note 7) and Easy naan - No Yeast Flatbread","images":[],"step":9}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["curry-recipes","indian-recipes","lamb-recipes","main-dishes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e4a089c7c802', 'en', 'US', 'Curried Sausages', 'Recipe video above. A retro classic! Browned sausages smothered in a curry flavoured gravy with onions, carrots and peas. Skip the old school method of boiling sauces - that''s throwing away free flavour! Browning sausages in the same skillet used to make the curried gravy makes a MUCH tastier sauce. I promise!', 'https://www.recipetineats.com/tachyon/2019/04/Curried-Sausages_2.jpg', 5, 15, 20, 4, '[{"id": "ing_oil", "quantity": {"value": 7.5, "unit": "bottle"}}, {"id": "ing_sausages", "quantity": {"value": 1.2, "unit": "pack of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_peas", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["0.5 tbsp oil","600g / 1.2lb sausages (, of choice (Note 1))","2 garlic cloves (, minced)","1 onion (, halved and sliced)","1 carrot (, peeled, sliced on the diagonal)","1 tbsp curry powder (, or more (Note 2))","3 tbsp flour (, any type (Note 3 for GF))","2 cups (500ml) chicken stock/broth (, low sodium)","1 tsp sugar","1/2 tsp salt (, plus more to taste)","1/2 tsp black pepper","1 cup peas (, frozen)"]}]', '[{"description":"Heat oil in a large skillet over medium high heat.","images":[],"step":1},{"description":"Cook sausages, turning to brown all over then remove. Optional: slice sausages into pieces on the diagonal.","images":[],"step":2},{"description":"In the same skillet, add garlic and onion. Cook for 2 minutes until translucent.","duration":2,"images":[],"step":3},{"description":"Add curry powder and stir for 30 seconds.","duration":0.5,"images":[],"step":4},{"description":"Add flour and mix for 30 seconds.","duration":0.5,"images":[],"step":5},{"description":"Gradually pour in chicken stock, mixing constantly.","images":[],"step":6},{"description":"Add carrots, sugar, salt and pepper, stir well.","images":[],"step":7},{"description":"Add sausages and peas, bring to simmer and cook for 3 minutes or until sauce thickens.","duration":3,"images":[],"step":8},{"description":"Serve over mashed potato, rice, pasta or noodles. For low carb, try mashed cauliflower!","images":[],"step":9}]', '["gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["curry-recipes","dinner-tonight","quick-and-easy","sausage-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_81a2e1367367', 'en', 'US', 'Chicken Biryani', 'Recipe video above. Curried chicken cooked in a pot buried under a mount of fragrant, fluffy rice. Biryani is a celebration of all that we love about Indian food! Make this with other proteins or vegetables - see notes. There''s a load of spices in this - and it''s worth it! (Plus you''ll find everything at every day supermarkets). Spiciness: moderate low.', 'https://www.recipetineats.com/tachyon/2018/08/Chicken-Biryani_1-1.jpg', 20, 60, 80, 8, '[{"id": "ing_chicken_thigh", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.2, "unit": "tub of 500g"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_round_turmeric", "quantity": {"value": 0.625, "unit": "jar"}}, {"id": "ing_cinnamon", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_cayenne", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garam_marsala", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.75, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.009, "unit": "kg"}}, {"id": "ing_s", "quantity": {"value": 10.0, "unit": "pack"}}, {"id": "ing_bay_leaf", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_star_anise", "quantity": {"value": 1.0, "unit": "jar"}}, {"id": "ing_cardamon_pods", "quantity": {"value": 6.0, "unit": "unit"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.338, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_saffron_threads", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_butter", "quantity": {"value": 0.25, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}]', '[{"ingredients":["750g (1.5 lb) chicken thighs (, skin on, bone in, halved along bone (Note 1))"]},{"ingredients":["2/3 cup (150 ml) yoghurt (, plain)","1/2 cup (125 ml) water","2 tbsp vegetable oil (or other plain oil)","6 garlic cloves (, minced)","2 tsp finely grated fresh ginger","1/8 tsp ground turmeric","1/4 tsp cinnamon","1/2 tsp cayenne (adjust spiciness to taste)","1/2 tsp ground cardamom","2 tsp garam marsala (Note 2)","2 tsp coriander","1 tbsp cumin","2 tbsp paprika (, sweet / ordinary (not smoked))","1 3/4 tsp salt"],"purpose":"Marinade:"},{"ingredients":["2 tbsp salt","10 cloves","5 dried bay leaves","1 star anise","6 green cardamon pods","2 1/4 cups (450g) uncooked basmati rice (Note 3)"],"purpose":"Par Boiled Rice:"},{"ingredients":["2 medium onions (yellow, brown) (, halved and finely sliced)","1 cup (250 ml) oil (, for frying)"],"purpose":"Crispy Onions (Note 4):"},{"ingredients":["1 tsp saffron threads (loosely packed) (Note 5)","2 tbsp warm water"],"purpose":"Saffron:"},{"ingredients":["1 cup coriander / cilantro (, chopped)","1/4 cup (60g) ghee or unsalted butter (, melted (Note 6))"],"purpose":"Biryani:"},{"ingredients":["Crispy onions (above)","Chopped coriander / cilantro","Yoghurt (Note 7)"],"purpose":"Garnish:"}]', '[{"description":"Mix Marinade in a large pot (about 26cm / 11\" diameter). Add chicken and coat well. Marinade 20 minutes to overnight.","images":[],"step":1},{"description":"Par Boiled Rice:","images":[],"step":2},{"description":"Bring 3 litres / 3 quarts water to the boil, add salt and spices.","images":[],"step":3},{"description":"Add rice, bring back up to the boil then cook for 4 minutes, or until rice is just cooked still a bit firm in the middle. Rice will taste salty at this stage, disappears in next stage of cooking.","duration":4,"images":[],"step":4},{"title":"Drain immediately. Set aside. (Note 10 re","description":"leaving whole spices in)","images":[],"step":5},{"description":"Heat oil in a large saucepan over medium high heat. Cook onion, in batches, for 3 to 4 minutes, until golden brown. Don''t burn - they become bitter.","duration":3.5,"images":[],"step":6},{"description":"Remove onto paper towel lined plate. Repeat with remaining onion.","images":[],"step":7},{"description":"Place in a bowl, leave for 10 minutes+.","duration":10,"images":[],"step":8},{"description":"Place pot with chicken in it onto a stove over medium heat. Cover and cook for 5 minutes.","duration":5,"images":[],"step":9},{"description":"Remove lid. Cook for 5 minutes, turning chicken twice.","duration":5,"images":[],"step":10},{"description":"Remove from heat.","images":[],"step":11},{"title":"Turn chicken so skin side is down","description":"it should cover most of the base of the pot.","images":[],"step":12},{"description":"Scatter over half the onion then half the coriander.","images":[],"step":13},{"description":"Top with all the rice. Gently pat down and flatten surface.","images":[],"step":14},{"description":"Drizzle saffron across rice surface in random pattern, then drizzle over ghee.","images":[],"step":15},{"description":"Place lid on. Return to stove over medium heat.","images":[],"step":16},{"description":"As soon as you see steam, turn down to low then cook for 25 minutes.","duration":25,"images":[],"step":17},{"description":"Remove from stove, rest with lid on for 10 minutes.","duration":10,"images":[],"step":18},{"description":"To Serve:","images":[],"step":19},{"description":"Aim to serve it so you get nice patches of yellow rice, white rice, the curry stained rice + chicken (rather than all mixed up). To do this, use a large spoon and dig deep into the pot, and try to scoop up as much as you can in one scoop.","images":[],"step":20},{"title":"Turn out into bowl","description":"or onto platter. Garnish with remaining onion and coriander with yoghurt on the side (see Note 7 for Minted Yoghurt)","images":[],"step":21}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["curry-recipes","dietary","gluten-free-recipes","iconic-dishes","indian-recipes","main-dishes","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c07e19c1c759', 'en', 'US', 'Vegetable Curry', 'This packs a serious flavour punch and is loaded with vegetables! I used plenty of variety, but feel free to use less. Just substitute based on volume rather than weight (because vegetable weight/density differs), and adjust the chilli and cayenne pepper to control spiciness, as well as using either mild or hot curry powder.', 'https://www.recipetineats.com/tachyon/2017/07/Vegetable-Curry.jpg', 15, 25, 40, 5, '[{"id": "ing_curry_powder", "quantity": {"value": 0.6, "unit": "jar of 50g"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_nutmeg_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_garlic", "quantity": {"value": 666.667, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_sweet_potato", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_cauliflower", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_frozen_peas", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_baby_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_basmati_rice", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_white_rice", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 tbsp curry powder (, mild or hot (Note 1))","1 tsp All Spice powder","1 tsp nutmeg powder (or 1/2 tsp freshly grated nutmeg)","1 1/2 tsp smoked paprika (sub with sweet or ordinary paprika)","2 tsp dried thyme leaves (or 3 tsp fresh thyme leaves)","1 tsp cumin powder","3/4 tsp cayenne pepper (adjust to taste)","1 tsp pepper (white or black)"],"purpose":"Spice Mix:"},{"ingredients":["3 tbsp cooking oil","1 large onion (, diced (brown, white, yellow))","1 large red chilli / cayenne pepper (, deseeded and finely sliced)","2 large garlic cloves (, minced)","1 large red capsicum / bell pepper * (, chopped into 1.7cm / 2/3\" pieces (~1.5 cups))","800g/ 28 oz canned crushed tomato","2 cups (500 ml) vegetable or chicken broth","1 zucchini (, diced (~1 cup) *)","2 cups sweet potato * (, 1.5cm / 3/5\" cubes (~225g/7.5oz))","2 cups cauliflower florets * (, small / medium (~180g/6oz))","3/4 cup frozen peas *","2 handfuls baby spinach (, optional (Note 2))","1/2 cup finely chopped coriander/cilantro ((leaves and stems), plus more for garnish)","Salt and pepper","Yoghurt (plain or Greek)"],"purpose":"Curry:"},{"ingredients":["Basmati rice","White rice"],"purpose":"Serving – choose:"}]', '[{"description":"Heat oil in a large pot over medium high heat. Add garlic and onion, cook for 2 minutes. Add cayenne and cook until onion is translucent.","duration":2,"images":[],"step":1},{"description":"Add Spice Mix and cook, stirring constantly, for 1 - 2 minutes until the spice is fragrant and wet. If too dry, add a tiny touch of water or oil.","duration":1.5,"images":[],"step":2},{"description":"Add capsicum and zucchini, cook for 1 minute.","duration":1,"images":[],"step":3},{"description":"Add tomato, broth, potato and cauliflower. Mix well, bring to simmer, cover, lower heat to medium.","images":[],"step":4},{"description":"Simmer for 15 minutes or until potato is pretty soft, then remove lid and simmer for another 10 minutes+ until sauce is slightly thickened and potato is soft.","duration":15,"images":[],"step":5},{"description":"Add peas, stir, cook for 2 minutes. Add coriander and spinach, stir until wilted.","duration":2,"images":[],"step":6},{"description":"Season to taste until salt and pepper. Serve over basmati rice or plain white rice. Garnish with yoghurt and more coriander.","images":[],"step":7}]', '["milk"]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Caribbean"],"categories":["curry-recipes","dietary","dinner-tonight","gluten-free-recipes","indian-recipes","main-dishes","quick-and-easy","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9f629f547dae', 'en', 'US', 'Country harvest root vegetable soup', 'Recipe video above. I don''t harvest and I don''t live in the country. I just didn''t think "Root Vegetable Soup" did this recipe justice - so I got creative to get your attention!😅 Root veg are great for naturally creamy soups thanks to the higher starch content, though we give this a luxe boost with a scant 1/2 cup of cream. Nourishing, never boring, and flexible too - in case your harvest basket is missing items! Love that it''s made with water not stock - curry powder adds a flavour boost so it doesn''t taste flat. Bonus - LOW CAL!', 'https://www.recipetineats.com/tachyon/2025/05/Creamy-root-vegetable-soup_1.jpg', 20, 30, 50, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_water", "quantity": {"value": 1.5, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_sweet_potato", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_medium_parsnip_cut_into_1_5cm_0_5_pieces", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_celeriac_cut_into_1_5cm_0_5_pieces", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.3, "unit": "jar of 50g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["2 tbsp extra virgin olive oil","1 tbsp (15g) unsalted butter","1 onion (, chopped into large dice)","3 garlic cloves (, chopped)","1 tbsp curry powder (I like Clive, but any will do, Note 1)","1 tsp dried thyme leaves (Note 2)","1 1/2 litre (6 cups) water","2 tsp cooking salt/kosher salt (halve for table salt)","1/2 tsp black pepper","1/2 cup thickened cream (heavy cream, or regular), plus extra for garnish (Note 3)"]},{"ingredients":["1 large potato ((~300g/10oz), peeled, cut into 2.5cm/1\" cubes)","1 medium sweet potato ((350g/12oz), peeled, cut into 2.5cm/1\" cubes)","2 medium carrots (, peeled, cut into 1.5cm/0.5\" pieces)","1 small/medium parsnip ((150g/5oz), peeled, cut into 1.5cm/0.5\" pieces)","1 small celeriac (600g/1.2 lb), peeled, cut into 1.5cm/0.5\" pieces (~2 heaped cups)"],"purpose":"Root vegetables (Note 4):"},{"ingredients":["Warm crusty bread","Parsley (, finely chopped)","Pinch extra curry powder","Pinch black pepper"],"purpose":"Serving/garnish (optional):"}]', '[{"title":"Sauté","description":"Put the olive oil and butter in a large heavy-based pot over medium-high heat. Once the butter is melted, cook the onion and garlic for 2 minutes until the onion is softened.","duration":2,"images":[],"step":1},{"description":"Add root vegetables, thyme and curry powder. Cook for three minutes stirring regularly, until the outside of the vegetables starts to soften.","images":[],"step":2},{"title":"Simmer 15 minutes","description":"Turn stove up to high. Add water, salt and pepper. Stir, then once it comes to a simmer, lower heat to medium high and simmer rapidly for 15 minutes (no lid) until all the vegetables are soft (check with knife).","duration":15,"images":[],"step":3},{"description":"Stir in cream, simmer for 1 minute.","duration":1,"images":[],"step":4},{"title":"Blitz","description":"Remove from heat and use a stick blender to blitz until smooth. (Note 5 for blender) Adjust to taste - water to thin, salt and pepper if needed, extra cream for more indulgent.","images":[],"step":5},{"description":"Serve in bowls. Drizzle with cream, pinch of curry powder, parsley and pepper. Serve with warm crusty bread!","images":[],"step":6}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner","snack"],"cuisine":["Western"],"categories":["dietary","gluten-free-recipes","low-calorie-recipes","soup-recipes","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2c559c7f6dc4', 'en', 'US', 'Puttanesca Fish Tray Bake', 'Recipe video above. Baked fish dinners can be so dull. Not this one! Think - spaghetti puttanesca flavours in the form of a one pan fish dinner. It''s a Puttanesca fish tray bake! Good for you, easy to make, fabulously delicious.Note: If you only have fine table salt, halve the salt quantities else it will be too salty.', 'https://www.recipetineats.com/tachyon/2025/05/Puttanesca-fish-tray-bake-shoot-1_3.jpg', 15, 45, 60, 4, '[{"id": "ing_potato", "quantity": {"value": 600.0, "unit": "bag of 2kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_fennel", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_pitted_kalamata_olives", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_baby_capers", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_organo", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 20.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["600g/1.2 lb baby potatoes (, smaller ones up to 3.5cm/1.5\" halved, larger ones quartered (Note 1))","1 1/2 tbsp extra virgin olive oil","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Roasted potatoes:"},{"ingredients":["1 medium fennel (, fronds reserved for garnish, halved, cut into 0.5cm / 0.2\" half moon shapes (Note 2))","1 1/2 cups (200g) cherry or grape tomatoes (1 punnet)","1/2 cup pitted kalamata olives","3 garlic cloves (, finely minced (can use garlic crusher))","3 tbsp baby capers (or regular, roughly chopped)","3 anchovy fillets (, finely minced - can reduce to 1 (Note 3))","400g/ 14oz canned tomato (, crushed or diced)","1/2 tsp chilli flakes ((red pepper flakes), mild spiciness, can reduce or omit)","1 tsp dried organo","1/4 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Puttanesca sauce:"},{"ingredients":["4 x 160 - 180g / 6oz barramundi fillets (, skinless, or other firm fish fillets about 2.5/3cm/1\" thick (Note 4))","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper","1 1/2 tbsp extra virgin olive oil"],"purpose":"Fish:"},{"ingredients":["1 loosely packed cup basil leaves (, roughly chopped (recommended but can live without or sub with 2 tbsp roughly chopped parsley))","Warm crusty bread (, for mopping)"],"purpose":"Finishing / serving:"}]', '[{"description":"Preheat oven to 220°C/390°F (200°C fan-forced).","images":[],"step":1},{"title":"Roast potatoes","description":"In a large mixing bowl, toss the potatoes with the oil, salt and pepper. Spread on a baking tray with a rim at least 2cm/0.8\" high (or 23x33cm / 9x13\" pan). Roast for 20 minutes.","duration":20,"images":[],"step":2},{"title":"Puttanesca sauce","description":"Meanwhile, mix all the sauce ingredients together (use the potato bowl, no need to clean). Add to the tray, toss with the potatoes, return to the oven for 10 minutes.","duration":10,"images":[],"step":3},{"title":"Season fish","description":"Pat the fish dry with paper towels. Sprinkle each side with the salt and pepper.","images":[],"step":4},{"title":"Bake fish","description":"Place fish on top of puttanesca sauce. Drizzle all over with the 1 1/2 tablespoons of oil. Bake 15 minutes or until fish is just cooked through (it should flake easily).","images":[],"step":5},{"title":"Serve","description":"Remove from the oven. Drizzle with a bit more olive oil, scatter with basil and reserved fennel fronds. Serve with warm, crusty bread!","images":[],"step":6}]', '["fish","gluten"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","fish-recipes","gluten-free-recipes","mains","one-pot-recipes","other","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d1115e64f3d8', 'en', 'US', 'Vietnamese Peanut Sauce Lettuce Wraps', 'Recipe video above. Such a great DIY summer spread, a regular all through summer in my circles! It''s essentially a lower-cal version of Vietnamese rice paper rolls. The fresh herbs and the peanut sauce are key here! Everything else you can switch: prawns for shredded chicken, pan fried salmon or other fish (flake into big chunks) or even tofu (I pan fry batons). Use whatever shreddable veg you want. Emergency version: store bought roast chicken (shredded) + packet shredded coleslaw veg + peanut sauce + noodles. SO GOOD.', 'https://www.recipetineats.com/tachyon/2024/01/Vietnamese-lettuce-wraps-with-peanut-sauce_8.jpg', 20, 0, 20, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.15, "unit": "pack of 500g"}}, {"id": "ing_lettuce", "quantity": {"value": 240.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_beansprouts", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_mint", "quantity": {"value": 1.2, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 1.2, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 3.0, "unit": "pack of 100g"}}, {"id": "ing_roasted_peanuts", "quantity": {"value": 37.5, "unit": "jar"}}, {"id": "ing_peanut_butter", "quantity": {"value": 0.08, "unit": "jar of 375g"}}, {"id": "ing_hoisin", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_coconut_milk", "quantity": {"value": 0.208, "unit": "can of 400ml"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_sambal_oelak_can_omit", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_dark_soy", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_radishes", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_vinegar", "quantity": {"value": 1.0, "unit": "L"}}]', '[{"ingredients":["300g / 10 oz peeled whole cooked prawns/shrimp (, medium (600g/1.2lb unpeeled whole prawns - this is what I use) - Note 1)","75g / 2.5 oz dried vermicelli noodles (or glass noodles or rice)","12 large or 16 -20 small lettuce leaves ((I used baby cos/romaine), eg iceberg, butter lettuce)"],"purpose":"The lettuce cups:"},{"ingredients":["1 batch quick pickled carrots and daikon (, below *recommended* OR 2 carrots finely julienned (use plain))","2 cups beansprouts","2 cucumbers (, julienned)","2 cups mint leaves","2 cups coriander/cilantro sprigs (sub with chives + extra mint)","3 birds eye red chilli (, finely sliced (optional))","1/4 cup roasted peanuts (, finely chopped (recommended))"],"purpose":"Veg and herbs:"},{"ingredients":["2 tbsp natural peanut butter (, smooth (ie not sweetened) - Note 2)","2 tbsp hoisin","1 - 2 tbsp lime juice (, sub rice vinegar)","1/3 cup LOW FAT coconut milk (Note 3)","1 large garlic clove (, finely grated)","1 tsp+ sambal oelak (or other chilli sauce/paste of choice), can omit (adj to taste)","1 tsp dark soy (Note 4)","1 tsp white sugar","1/2 tsp cooking salt / kosher salt"],"purpose":"Vietnamese Peanut Sauce:"},{"ingredients":["2 medium carrots (, peeled cut into 2 mm / 1/10″ batons)","1/2 large white radish (daikon) (, peeled, cut the same as carrots)","1 1/2 cups boiling water","1/2 cup white sugar","4 tsp cooking salt / kosher salt","3/4 cup rice wine vinegar (sub apple cider vinegar)"],"purpose":"Quick pickled vegetables"}]', '[{"title":"Pickle first","description":"Put the boiling water, salt and sugar in a bowl. Mix to to dissolve, then add vinegar. Submerge vegetables and leave for 2 hours. Drain then use per recipe (or store in fridge submerged in liquid).","images":[],"step":1},{"title":"Peanut sauce","description":"Mix the peanut sauce ingredients and set aside for the flavours to meld while you prepare the platter. Start with 1 tbsp lime juice and add more if you want tarter.","images":[],"step":2},{"title":"Prawns (shrimp)","description":"Cut the prawns in half horizontally and remove the vein.","images":[],"step":3},{"title":"Noodles","description":"Soak the noodles in boiling water per packet directions. Rinse under cold water (to prevent stickiness) then drain very well.","images":[],"step":4},{"title":"Lay it all out","description":"Pile everything onto a giant platter or put things in little bowls, then let everybody help themselves!","images":[],"step":5},{"title":"Assemble","description":"Here''s my order: lettuce leaf, noodles first, then veg* (carrots, bean sprouts etc), prawns, stuff herbs down the side, drizzle with sauce, sprinkle with peanuts and chilli. Bundle and bite!","images":[],"step":6}]', '["milk","peanuts","shellfish","soy"]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["dietary","gluten-free-recipes","low-calorie-recipes","no-cook-food","prawns-shrimp","summer","vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_880b53615e1c', 'en', 'US', 'Almost no-oil Pan Fried Eggplant', 'Recipe video above. This is a recipe for how to cook eggplant on the stove with virtually no oil - less than 1/2 teaspoon for a whole eggplant! I use a highly effective, simple pan-steaming method used for Asian dumplings like gyoza! Eat it as is, or see in post for a list of toppings and sauces to serve with this pan fried eggplant. Which one is your favourite??', 'https://www.recipetineats.com/tachyon/2023/10/Pan-fried-eggplant-with-little-oil_3.jpg', 3, 10, 13, 2, '[{"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_see_in_post_for_ideas_and_links_to_recipes_for_sauces_etc", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["1 large eggplant (aubergine), around 20cm/8” (~400g/14 oz) (Note 1)","Olive oil spray (or other oil spray) (Note 2)","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper","1/4 cup water"]},{"ingredients":["See in post for ideas and links to recipes for sauces etc!"],"purpose":"Sauces and toppings for serving:"}]', '[{"description":"Cut the eggplant into 2cm / 0.8” rounds.","images":[],"step":1},{"description":"Spray each side generously with oil and sprinkle with salt and pepper.","images":[],"step":2},{"title":"Brown","description":"Heat a large non-stick pan with a lid over medium high heat, no oil. (Note 3) Add the eggplant slices and pan fry for 1 1/2 to 2 minutes on each side or until you get some nice browning on it. As much or as little as you want!","images":[],"step":3},{"title":"Pan steam","description":"Carefully add water around the eggplant (it will bubble and steam, so do this carefully). Then immediately cover with a lid to trap the steam in. Steam for 2 minutes or until the water has evaporated.","duration":2,"images":[],"step":4},{"title":"Check","description":"Use a butter knife to check to ensure the eggplant is cooked through. If not, add a bit more water and steam again!","images":[],"step":5},{"title":"Serve","description":"Transfer to a serving plate and serve! Great as is, or to dress it up a tiny bit, add a swish of olive oil, squeeze of lemon juice and parsley leaves, or a smear of chilli crisp! See in post for more ways to serve.","images":[],"step":6}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","eggplant","how-to","low-calorie-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d103e1d2cd8e', 'en', 'US', 'Roast Lamb Leg with Gravy', 'Recipe video above. I love a roast lamb leg! My top tip is to use a meat thermometer. There''s no way to guarantee perfect blushing pink roast lamb without one, even if it''s a cheap one!Rubbed with rosemary garlic and accompanied with a killer gravy for lamb. Serve with peas, buttered steamed carrots and crunchy roast potatoes (either classic or ultra crunchy duck fat potatoes).', 'https://www.recipetineats.com/tachyon/2016/10/Roast-lamb-leg_2.jpg', 5, 100, 15, 6, '[{"id": "ing_lamb", "quantity": {"value": 2.75, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_rosemary", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.375, "unit": "kg"}}]', '[{"ingredients":["2.75 - 3 kg / 5.5 - 6 lb lamb leg (, bone-in (Note 1))","1 1/2 tsp cooking salt","1/2 tsp black pepper"]},{"ingredients":["1 1/2 tbsp fresh rosemary leaves (, finely chopped)","3 garlic cloves (, finely minced)","2 tbsp olive oil"],"purpose":"Rub"},{"ingredients":["2 whole heads of garlic (, halved horizontally (Note 2))","Few sprigs rosemary (optional)"],"purpose":"Base"},{"ingredients":["4 tbsp flour (, plain/all purpose)","2 1/2 cups beef broth / stock (, low sodium (Note 3))"],"purpose":"Gravy"}]', '[{"description":"Take lamb out of fridge at least 1 hour before roasting. (Note 4)","images":[],"step":1},{"description":"Preheat oven to 240°C/475°F (220°C fan) with oven shelf in the middle.","images":[],"step":2},{"title":"Rub","description":"Mix rosemary, garlic and olive oil.","images":[],"step":3},{"title":"Prepare lamb","description":"Place lamb leg in a roasting pan. Coat with the rub using your hands, the sprinkle with the salt and pepper. Place garlic and rosemary sprigs underneath the lamb, garlic cut face up.","images":[],"step":4},{"description":"Roast lamb leg for 20 minutes. Turn the oven down to 200°C/400°F (180°C fan) and roast for a further 1 hour or until the internal temperature reaches 53°C/127°F for medium rare (Note 5 other doneness). Check first at 45 minutes - everyone''s oven is different!","duration":20,"images":[],"step":5},{"title":"Rest","description":"Remove lamb from oven. Transfer lamb to plate, loosely cover with foil and rest for 20 minutes to 1 hour (it will still be warm enough for serving!). The internal temperature will rise to 62°C/144°F (medium rare). Make gravy while lamb is resting - below.","duration":20,"images":[],"step":6},{"description":"Serve lamb with gravy, duck fat or classic crunchy roast potatoes, peas and steamed carrots tossed with butter and parsley.","images":[],"step":7},{"description":"Gravy for roast lamb leg","images":[],"step":8},{"title":"Drippings in pan","description":"Discard rosemary sprigs. You should have around 4 - 5 tbsp of fat (drippings). If less, add butter. If much more, discard a bit.","images":[],"step":9},{"title":"Add flour","description":"Place roasting pan on stove over medium heat. When the fat starts to bubble, then add flour. Mix flour in and cook for 1 minute.","duration":1,"images":[],"step":10},{"title":"Stock","description":"Pour in half the beef stock and mix to dissolve sludge in, then add remaining beef stock and mix.","images":[],"step":11},{"title":"Garlic squidging","description":"Use a potato masher (if you''re really keen like me) to mush the garlic to squeeze out the flavour (also helps flour caught in garlic to dissolve).","images":[],"step":12},{"title":"Taste","description":"Check salt and pepper (I don''t add more).","images":[],"step":13},{"title":"Thicken","description":"Simmer for a couple of minutes, stirring, until it starts to thicken. Take it off the stove BEFORE the gravy is the thickness you want because it will keep thickening.","images":[],"step":14},{"description":"Strain into a bowl, mushing garlic to squeeze all the liquid out. Then pour into gravy jug and serve with lamb!","images":[],"step":15}]', '["gluten"]', '["high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Aussie","British","New Zealand"],"categories":["dietary","easter-mains","easter-recipes","gluten-free-recipes","lamb-recipes","main-dishes","most-popular","roast-lamb","roasts","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_681954c5523d', 'en', 'US', 'Gazpacho', 'Recipe video above. If the thought of this chilled Spanish soup conjures up visions of watery, bland, pureed vegetables, think again! Fabulous refreshing and full of flavour. Marinating isn''t traditional but does improve flavour. So it''s recommended, especially if you use economical vinegar or if your tomatoes aren''t farm-fresh-ripe-and-sweet (ie typical tomatoes from everyday grocery stores....)This version has no bread in it - it''s thick enough as is, I find. Serve with crusty bread on the side, for dunking. Fabulous meal for a hot summer day!Serves 3 hearty appetites, 4 normal appetites (with bread for dunking).', 'https://www.recipetineats.com/tachyon/2023/01/Gazpacho_2.jpg', 15, 0, 15, 3, '[{"id": "ing_tomato", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 37.5, "unit": "pack of 1kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_vinegar", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["1 kg / 2 lb ripe tomatoes ((~7), cut into 8 wedges, core removed)","1 cucumber (20cm/8\" long) (, peeled and diced into 1cm / 1/2\" cubes)","1 red capsicum/bell pepper (, cut into 1.5 cm / 1/2\" cubes)","2 garlic cloves (, chopped)","1/4 cup red onion (, finely diced (Note 1))","1/4 cup extra virgin olive oil (, + extra for serving)","1 1/2 tbsp sherry vinegar (sub white wine or champagne vinegar)","3/4 tsp cooking/kosher salt","1/2 tsp black pepper"],"purpose":"Gazpacho:"},{"ingredients":["Crusty bread","Cucumber (, cut into small cubes (optional))"],"purpose":"Serving:"}]', '[{"title":"Marinate","description":"Toss all the gazpacho ingredients together in a large bowl. Cover then set aside to marinate, preferably 12 to 24 hours, or at least 3 hours. (Note 3)","images":[],"step":1},{"title":"Blitz","description":"Transfer everything into a blender and blitz on high until smooth. (Or use a tall jug with a hand blender). For 100% perfectly smooth, pass through a fine mesh strainer or food mill and discard solids (Note 2)","images":[],"step":2},{"title":"Serve","description":"Pour into a bowl. Rest for 15 minutes to let the bubbles subside. Stir, then ladle into bowls.","duration":15,"images":[],"step":3},{"title":"Garnish","description":"Top with diced cucumber, if using, and a swish of olive oil. Serve with crusty bread!","images":[],"step":4}]', '["gluten"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Spanish"],"categories":["dietary","low-calorie-recipes","no-cook-food","soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c93e7300e836', 'en', 'US', 'Immunity Boosting Green Goddess Soup', 'Recipe video above. A feel-good soup packed full of nutrition created to cure winter colds! While you could switch out the veg with whatever you’ve got, I’ve tried various combinations and this is my favourite for best flavour so it doesn’t taste like you’re eating a bowl of hot grass.Don’t skip the spices. Doesn’t look like much but it really makes a difference!', 'https://www.recipetineats.com/tachyon/2022/07/Immunity-Boosting-Green-Goddess-Soup-1.jpg', 15, 0, 15, 8, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_fennel", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_broccoli", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.013, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 1.75, "unit": "L"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_kale", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_baby_spinach", "quantity": {"value": 5.0, "unit": "bag of 250g"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_cup_sunflower_seeds", "quantity": {"value": 30.0, "unit": "jar"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["2 tbsp olive oil","1 onion (, diced (Note 1))","1 leek (white part only) or another onion (, diced (Note 1))","1 medium fennel (, chopped (Note 2))","2 celery stems (, roughly chopped)","5 garlic cloves (, roughly minced)","3/4 tsp all spice powder (sub mixed spice)","3/4 tsp cumin powder (sub coriander)","1 medium potato ((any type), peeled, 1.5 cm cubes )","1 head broccoli (, florets (peel and chop stalk too))","2 1/2 tsp cooking / kosher salt","3/4 tsp black pepper","1.75 litres / quarts water (Note 3)","1 cup frozen peas (Note 4)","5 cups (tightly packed) kale leaves (, roughly chopped (1 small bunch, Note 5))","5 cups (tightly packed) baby spinach (Note 6)","3/4 cup thickened cream (Note 7)"]},{"ingredients":["2 tbsp sunflower seeds, toasted (or croutons or other toasted nuts, Note 8)","Cream and/or olive oil for drizzling"],"purpose":"Garnishes"}]', '[{"title":"Sauté aromatics","description":"Heat oil in a very large pot (6L/qt) over medium high heat. Cook onion, leek, celery, garlic and fennel for 5 minutes until softened.","duration":5,"images":[],"step":1},{"title":"Cook spices","description":"Add all spice and cumin, and cook for 1 minute.","duration":1,"images":[],"step":2},{"description":"Add water, potatoes, broccoli, salt and pepper. Stir, bring to simmer, and simmer for 7 minutes (no lid) until the broccoli is tender.","duration":7,"images":[],"step":3},{"title":"Add peas","description":"Add peas, simmer for 1 minute.","duration":1,"images":[],"step":4},{"title":"Blitz in kale","description":"Remove pot off the stove. Add kale, push it under the liquid, then blitz with a stick blender until mostly smooth. Add spinach, push under the liquid then blitz again until smooth as possible (approx 3 to 5 mins). This will result in a smooth soup but with little green bits in it - I like this for a little texture.","images":[],"step":5},{"title":"Serve","description":"Stir in cream. Ladle into bowls, drizzle with extra cream and/or olive oil and finish with a sprinkle of sunflower seeds. Eat and feel great!","images":[],"step":6}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","low-calorie-recipes","soup-recipes","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1b5556e564bb', 'en', 'US', 'Fish Seasoning - for any fish', 'Recipe video above. This is a great spice seasoning for fish that makes for a quick and easy way to add flavour to fish. Based on Old Bay Seasoning, it''s a combination of spices that works really well together. I''ve used flathead fillets today, but it can be used for any fish suitable for pan-frying. Don''t worry if you don''t have all the spices, there''s plenty of subs. Allow ~180g/6oz fish per person.', 'https://www.recipetineats.com/tachyon/2021/06/Fish-Seasoning-Flathead-_6.jpg', 5, 10, 15, 4, '[{"id": "ing_celery", "quantity": {"value": 0.1, "unit": "head"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}, {"id": "ing_mace", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_round_clove", "quantity": {"value": 0.625, "unit": "jar"}}, {"id": "ing_ginger", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.016, "unit": "jar of 40g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 45.0, "unit": "block of 250g"}}, {"id": "ing_butter", "quantity": {"value": 45.0, "unit": "block of 250g"}}]', '[{"ingredients":["1 tsp celery salt ((or 3/4 tsp salt])","1/4 tsp black pepper","1 tsp smoked paprika","1/2 tsp mustard powder","1/4 tsp mace","1/4 tsp allspice","1/8 tsp ground clove","1/8 tsp ginger powder","1/8 tsp cayenne pepper (or pure chilli powder)","1/8 tsp ground cardamom"],"purpose":"Fish Seasoning (Note 1 for subs):"},{"ingredients":["750g / 1.5lb fish fillets (, skinless, boneless (I used flathead, Note 2))","45g / 3 tbsp unsalted butter","30g / 2 tbsp Extra unsalted butter – for drizzling (optional)"],"purpose":"Fish:"}]', '[{"title":"Fish Seasoning","description":"Place ingredients in a bowl and mix to combine. It will keep for months in an airtight container. This quantity is enough for 750g / 1.5lb fish (serves 4 people)","images":[],"step":1},{"description":"Seasoning and cooking fish:","images":[],"step":2},{"title":"Season fish","description":"Sprinkle Seasoning on both sides of fish. Lightly rub to spread Seasoning.","images":[],"step":3},{"title":"Cook fish in two batches","description":"Melt 30g / 2tbsp butter in large non-stick skillet over medium high heat. Cook fish until golden on each side (see Cook times below). Remove to a plate.","images":[],"step":4},{"title":"Cook remaining fish","description":"Melt remaining butter in skillet and cook remaining fish.","images":[],"step":5},{"title":"Rest","description":"Rest fish for 3 minutes before serving with extra butter sauce (see next step).","duration":3,"images":[],"step":6},{"title":"Extra butter sauce (optional)","description":"Add extra butter into pan over medium heat and melt until foaming. Drizzle over fish when serving.","images":[],"step":7}]', '["fish","milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","fish-recipes","low-calorie-recipes","mains","other","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8e573b3148f8', 'en', 'US', 'Tuna Steak', 'Recipe video above. The perfect tuna steak is seared on the outside and deliciously rare on the inside. It takes 2 1/2 minutes flat - fastest fish recipe ever! Tuna loin is lean so best served raw or rare if cooked, to enjoy the tender, almost creamy flesh. There''s a reason why tuna is a darling of the fine dining scene! Best served just slightly warm or at room temperature. Pictured with Sauce Vierge, a summery, simple French salsa / vinaigerette sauce that pairs perfectly with fish!', 'https://www.recipetineats.com/tachyon/2021/05/Tuna-Steak-Main_2.jpg', 5, 3, 8, 2, '[{"id": "ing_x_180_200g_tuna_2_5_3cm_1_1_2_thick", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_sauce_vierge", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_chervil", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["2 x 180 - 200g (6.5 - 7oz) tuna (skinless, boneless). 2.5-3cm / 1-1.2\" thick (Note 1)","1 tsp olive oil","1/4 tsp sea salt","1/8 tsp black pepper"]},{"ingredients":["2 tsp olive oil (, or oil spray)"],"purpose":"Cooking:"},{"ingredients":["Sauce Vierge (French salsa / vinaigrette for fish)","Chervil sprigs (substitute small flat leaf or curly parsley leaves) or small edible flowers (optional)"],"purpose":"Serving suggestion (Note 2):"}]', '[{"title":"Prepare resting tray","description":"Place a rack on a tray. (Note 3)","images":[],"step":1},{"title":"Oil and season tuna","description":"Drizzle half the oil over the tuna. Smear over one side, then sprinkle with half the salt and pepper. Flip and repeat.","images":[],"step":2},{"title":"Heat skillet","description":"Heat skillet (preferably a skillet with grille lines) over high heat until smoking hot. The hotter, the better!","images":[],"step":3},{"title":"Oil skillet (if required)","description":"If your skillet is not well-seasoned, brush skillet with olive oil or take pan off stove and spray with any oil (SAFETY WARNING! Note 4)","images":[],"step":4},{"title":"Cook first side","description":"Place tuna steak in the skillet (I do one at a time for best results, Note 5) and cook for 45 seconds.","duration":0.75,"images":[],"step":5},{"title":"Rotate for grill lines","description":"Turn steak 45 degree. Continue cooking another 45 seconds.","images":[],"step":6},{"title":"Cook other side","description":"Flip tuna carefully, then leave for 1 minute or until the internal temperature in the middle reads 48°C / 118°F (Note 6).","duration":1,"images":[],"step":7},{"title":"Rest","description":"Remove tuna from skillet and place on rack. Rest for 5 minutes – it will cool down almost to room temperature. This is desirable for easier slicing and better eating (Note 7) Serve! See Note 2 for sauce options.","duration":5,"images":[],"step":8},{"title":"Plating up","description":"with Sauce Vierge option (pictured):","images":[],"step":9},{"title":"Slice, if desired (Note 7)","description":"Place tuna on a board with criss-crossing grill lines facing up. Slice the tuna into 4 or 5 thick slices, holding the edges with your fingers as needed to ensure the seared surface doesn''t crumble. Transfer to serving plate and separate the slices slightly so they insides are just visible, or on an a slightly angle, overlapping each other.","images":[],"step":10},{"title":"Sauce Vierge","description":"Spoon the Sauce Vierge over steaks, leaving small piles of tomato here and there on the tuna slices, and a few on the plate. Other sauce options: See Note 2.","images":[],"step":11},{"title":"Finishing","description":"Drizzle with a bit of olive oil. It looks beautiful as it is, but if you want to raise the bar even higher, add a few small sprigs of chervil and some edible flowers!","images":[],"step":12}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Universal","Western"],"categories":["dietary","easter-mains-fish-seafood","fish-recipes","gluten-free-recipes","low-calorie-recipes","mains","other","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4d684710170c', 'en', 'US', 'Whole Baked Fish – Herb-stuffed with Garlic & Dill Butter Sauce', 'Recipe video above. For anyone who''s wondered how to cook a whole fish, the best and easiest way is to bake it whole. The flesh is at its juiciest and most tender, and it''s completely effortless! Roasting fish this way is easy enough for midweek meals, but still makes an impressive centrepiece for occasions! I''m using a whole snapper today, but this recipe will work for virtually any fish. See Note 1 for other fish ideal to cook whole.', 'https://www.recipetineats.com/tachyon/2021/04/Whole-Baked-Fish_7.jpg', 10, 20, 30, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_dill_sprigs_packed", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_butter", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_dill", "quantity": {"value": 0.075, "unit": "kg"}}]', '[{"ingredients":["2 x 800g / 1.6 lb whole snapper or other whole fish (, scaled, gutted and cleaned (Note 1))","1 1/2 tsp salt (, kosher/cooking (not table salt))","1/2 tsp black pepper","2 tbsp extra virgin olive oil"]},{"ingredients":["1/2 cup fresh dill sprigs, packed","1/2 cup parsley leaves, packed","4 garlic cloves (, finely sliced)","1 lemon (, sliced (8 slices each lemon))"],"purpose":"Stuffing:"},{"ingredients":["150g / 10 tbsp unsalted butter (, cut into cubes)","2 tsp garlic (, finely minced)","1 tbsp fresh dill (, finely chopped)"],"purpose":"Dill Garlic Butter:"}]', '[{"description":"Preheat oven to 220°C/430°F (200°C fan). Line a tray with parchment/baking paper.","images":[],"step":1},{"title":"Trim fins","description":"Cut all fins off the fish using scissors – both fins on the side, and the fins on the back and underside of the fish (but not the tail).","images":[],"step":2},{"title":"Slash flesh","description":"Cut 3 slashes on each side of the fish, cutting through flesh down to the bone (see photos in post and/or video, helpful!).","images":[],"step":3},{"title":"Stuff fish (Note 2)","description":"Sprinkle a bit of salt and pepper inside the cavity of the fish. Scatter the cavity with garlic slices, then stuff with parsley and dill. Layer lemons on top of herbs.","images":[],"step":4},{"title":"Tie fish (Note 3)","description":"Using kitchen string make 3 ties to hold fish together.","images":[],"step":5},{"title":"Season skin","description":"Sprinkle remaining salt and pepper on the skin (both sides), including a bit on the head of the fish. Then drizzle with olive oil. Rub all over the fish, including in the slashes.","images":[],"step":6},{"title":"Bake 20 minutes (Note 4)","description":"Place fish on prepared tray. Bake for 20 minutes or until the internal temperature is 55°C/131°F (insert thermometer in the thickest part of the fish, not against the bone). Alternatively, use a small knife at one of the cut slits in the fish to prise a bit of meat gently away from the spine. If it flakes away from the bone without resistance, it''s done.","duration":20,"images":[],"step":7},{"title":"Rest","description":"Remove from oven, transfer to serving platter and leave it to rest for 5 minutes. The internal temperature will rise to 58°C / 136.5F (\"medium\", ie. just-cooked and not raw at all, very juicy and moist).","duration":5,"images":[],"step":8},{"description":"Serve with Garlic & Dill Butter Sauce on the side. Either pour over the butter just prior to serving the fish, or let everyone help themselves. See this video by Serious Eats for a concise tutorial for how to carve and serve a whole roasted fish.","images":[],"step":9},{"description":"Garlic & Dill Butter Sauce:","images":[],"step":10},{"title":"Melted butter","description":"Place butter in a saucepan over medium-high heat. Once melted, add garlic and cook, stirring, for 45 seconds to 1 minute until it smells ridiculously good and you''re salivating!","duration":0.75,"images":[],"step":11},{"title":"Add dill","description":"Remove from heat. Stir in dill. Use per recipe.","images":[],"step":12}]', '["fish","milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","easter-mains-fish-seafood","fish-recipes","gluten-free-recipes","mains","other","seafood-recipes","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_82881b115ad1', 'en', 'US', 'Slow-Roasted Crispy Pork Belly', 'Recipe video above. This is a pork belly that''s slow-roasted so the fat renders and cooks the belly confit-style in its own fat. The result? Ridiculously juicy, impossibly tender yet still-sliceable meat, crowned with the most amazing crispy crackling of your life. It comes down to three simple, game-changing techniques: 1. Do NOT score the skin; 2. Low heat followed by high heat; 3. Keep the pork level using balls of foil.Perfect meat, perfect crackling ... Every. Single. Time! (Read the post for all the details on how to do it right!)Bonus: Excellent for make ahead, reheats 99% perfectly the next day. See notes.', 'https://www.recipetineats.com/tachyon/2021/04/Overhead-slow-roasted-pork-belly.jpg', 5, 180, 185, 4, '[{"id": "ing_pork", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_fennel_powder_fennel_seeds", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_apples", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_vermouth_jus", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cauliflower", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_see_in_post_for_more_sauce_options", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["1kg / 2 lb pork belly with skin on","1 1/2 tsp olive oil (, divided)","1/2 tsp fennel powder / ground fennel seeds (, optional, Note 3)","1 tsp salt (, cooking/kosher salt (or 7/8 tsp table salt), divided)","1/4 tsp black pepper"]},{"ingredients":["Apple Sauce ()","Vermouth Jus ()","Cauliflower Puree (, (Note 2))","See in post for more Sauce options"],"purpose":"For serving (as pictured in post):"}]', '[{"title":"Dry skin overnight","description":"Place pork belly on a plate. Pat skin dry with paper towels. Leave uncovered in fridge overnight to dry out the skin. (If you don''t have time, pat the skin dry as best you can).","images":[],"step":1},{"description":"Preheat oven to 140°C/285°F (120°C fan).","images":[],"step":2},{"title":"Season flesh","description":"Drizzle flesh (only) with 1 tsp oil. Sprinkle over 1/2 tsp salt, the pepper and fennel powder. Rub all over the flesh, including on the sides, being sure you get right into all the cracks and crevices.","images":[],"step":3},{"title":"Wrap in foil","description":"Place 2 pieces of foil on a work surface. Put the belly in middle of foil, skin side up. Fold the sides in to enclose the belly, forming an open box, pinching corners to seal tightly and make it as snug as possible. Place meat on a tray.","images":[],"step":4},{"title":"Season skin","description":"Pat skin dry with paper towels. Rub with 1/2 tsp oil then sprinkle remaining 1/2 tsp salt evenly all over the skin surface, from edge to edge.","images":[],"step":5},{"title":"Slow roast 2 1/2 hours","description":"Place in the oven and roast for 2 1/2 hours. After 1 1/2 hours, remove and tighten the foil (pork will have shrunk), and continue cooking. This keeps the pork fat level up as high as possible, and the flesh protected so it stays moist.","images":[],"step":6},{"title":"Increase heat","description":"Remove pork from oven, then increase heat to 240°C/465°F (all oven types).","images":[],"step":7},{"title":"Level pork","description":"Remove pork from foil and place on a rack set over a tray (using rack is best, but optional). Use scrunched up balls of foil stuffed under pork to prop up so the skin surface is as level and horizontal as possible (see photos in post).","images":[],"step":8},{"description":"30 minutes on high heat! Place the pork back in the oven for 30 minutes, rotating after 15 minutes as needed, until the crackling is deep golden, puffy and crispy all over. If some patches are browning faster, protect with foil patches. ⚠️ Open oven with care as it will be smokey - open your windows!","duration":30,"images":[],"step":9},{"title":"Rest 10 minutes","description":"Remove pork from oven. Rest for 10 minutes before slicing.","duration":10,"images":[],"step":10},{"title":"Serving","description":"Slice into 2cm / ⅘\"-thick slices using a serrated knife. Pictured in post with Apple Sauce and Vermouth Jus, with a side of Cauliflower Puree (Note 2)! See directions in post for how to plate it up as pictured (fine dining style!), as well as a list of more sauce options.","images":[],"step":11}]', '[]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","gluten-free-recipes","iconic-dishes","mains","pork","pork-recipes","roasts","slow-cooked-fall-apart"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c6510f43ab62', 'en', 'US', 'Garlic Butter Salmon recipe', 'Recipe video above. This is a simple-yet-luxurious, cheffy way to cook salmon. By basting continuously with foaming garlic butter, it seeps into every crack and crevice of the salmon and gives it the ultimate buttery crust.It may seem like a lot of butter for one recipe, but you need it to ensure good basting coverage. You do not have to use all of it for serving. Save leftover butter (even if just a smear!) and pan fry bread with it tomorrow, see post for photos. It''s Amazing – with a capital A!', 'https://www.recipetineats.com/tachyon/2021/03/Garlic-Butter-Salmon_9.jpg', 5, 8, 13, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 90.0, "unit": "block of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["4 salmon fillets ((180g/6oz each), skinless and boneless)","1/2 tsp salt (, cooking / kosher)","1/4 tsp black pepper","1 1/2 tbsp olive oil","1 tbsp garlic (~2 cloves) (, finely minced by hand (don''t use a garlic press))","90g / 6 tbsp salted butter (, cut into cubes (or unsalted + 1/4 tsp salt))","1 tsp lemon juice (, plus more to taste)","2 tsp parsley (, finely chopped)"]}]', '[{"title":"Season salmon","description":"Take salmon out of fridge 30 minutes prior to cooking. Sprinkle both sides with salt and pepper.","images":[],"step":1},{"title":"Sear salmon 3 mins","description":"Heat oil in large non stick skillet over medium-high heat. Add salmon, presentation side (ie. curved side) down, and cook for 3 minutes until golden.","duration":3,"images":[],"step":2},{"title":"Turn, cook 1 min, then add butter","description":"Turn salmon and cook the other side for 1 minute. THEN put the butter in.","duration":1,"images":[],"step":3},{"title":"Baste 1 1/2 minutes","description":"Once butter is melted and foaming, add garlic and immediately start spooning the bubbling butter continuously over the salmon for 1 1/2 minutes. To do this, tilt the pan slightly so the butter pools on one side. Use a large spoon to scoop the butter up and spoon it over the salmon.","images":[],"step":4},{"title":"Remove salmon from stove","description":"Check Internal temperature of salmon. It should be 50°C/122°F for medium-rare (optimum juiciness pull temp). Remove salmon to a plate. Rest for 3 minutes – it will rise to 53°C/127°F. (See Note 2 for internal temperatures)","duration":3,"images":[],"step":5},{"title":"Add lemon juice to butter","description":"Put pan back on unlit stove to keep butter hot. Add lemon juice.","images":[],"step":6},{"title":"Serve","description":"Place salmon on serving plates. Spoon over butter (be judicious, it''s rich!), garnish with a sprinkle of parsley. Pictured in the post with Cauliflower Mash and leafy greens with French Vinaigrette.","images":[],"step":7}]', '["fish","milk"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","fish-recipes","gluten-free-recipes","mains","other","quick-and-easy","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3a94444db743', 'en', 'US', 'Slow Roast Leg of Lamb', 'Recipe video above. A very forgiving, very easy way to roast a leg of lamb, where the meat is slow-cooked until it''s tender enough to pull it off the bone with tongs. It is not the blushing pink flesh carving sort (use this traditional Roast Lamb recipe if that''s what you''re after). Lamb leg is lean, so to slow cook it''s best to partially submerge in a flavoured liquid which keeps the flesh moist plus infuses with flavour. I''m using garlic and rosemary in this recipe - classic lamb flavours!**IMPORTANT** Lamb leg is lean so it should only be cooked for 1.5 hours until blushing pink & juicy (per this traditional Roast Lamb recipe) or slow cooked for 4.5 hrs until fall apart (this recipe). Anything in between is tough and not nice! For more roast lamb recipes, browse the recipe collection or take my Roast Lamb Matchmaker to find your perfect recipe!', 'https://www.recipetineats.com/tachyon/2020/04/Slow-Roasted-Lamb-Leg-featured-image.jpg', 15, 315, 330, 6, '[{"id": "ing_lamb", "quantity": {"value": 2.25, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_rosemary", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["2.25 kg / 4.5 lb leg of lamb (, bone in (or shoulder) (Note 1))","1 1/2 tsp cooking salt / kosher salt (double for flakes)","1/2 tsp black pepper","1 1/2 tbsp olive oil","1 whole garlic head (, unpeeled, cut in half horizontally)","1 onion (, quartered (unpeeled is fine))","2 rosemary sprigs (2 = whisper of rosemary flavour, 4 sprigs = stronger flavour)","3 cups beef stock/broth (, low sodium (or homemade))","2 cups water"]},{"ingredients":["4 tbsp plain flour (all-purpose flour)","1 cup water","Salt and pepper (, to taste)"],"purpose":"Gravy:"}]', '[{"description":"Season leg with salt and pepper, place upside down on garlic, onion and rosemary. Pour liquids in, drizzle with oil, cover with foil. Roast 4 1/2 hours at 170°C/335°F (150°C fan) until meat is pull-apart tender. Flip, return to oven 20 - 30 minutes at 200°C/390°F (180° fan) until well browned. Make gravy while resting.","images":[],"step":1},{"description":"Preheat oven to 170°C/335°F (150°C fan-forced).","images":[],"step":2},{"description":"Place garlic, onion and rosemary in a metal roasting pan.","images":[],"step":3},{"title":"Season lamb","description":"Place lamb leg right side up in the pan. (Note 2) Sprinkle the surface with half the salt and pepper and rub it in.","images":[],"step":4},{"description":"Turn lamb over and place it so it mostly sits on the garlic and onion. Sprinkle with remaining salt and pepper, rub it in. (Video helpful here)","images":[],"step":5},{"title":"Add liquids and cover","description":"Drizzle lamb with olive oil. Pour broth and water around the lamb - it won''t cover it, that''s ok, the lamb sinks into it. Cover with foil (don''t use a lid, you want a bit of liquid to steam out).","images":[],"step":6},{"title":"Slow roast","description":"Place in the oven and roast for 4 1/2 hours. (See Notes for roasting time table)","images":[],"step":7},{"title":"Check meat","description":"Remove from the oven, remove foil. Turn lamb over. Check it to ensure the meat is tender enough to pry a bit off easily with a fork. If not, return, covered, to oven.","images":[],"step":8},{"title":"Brown lamb","description":"Return uncovered lamb to the oven and roast for a further 40 minutes or until well browned all over. (Don''t increase the temperature as then it doesn''t brown as evenly)","images":[],"step":9},{"title":"Rest","description":"Remove lamb, spoon over pan juices generously. Transfer to serving platter, cover loosely with foil while you make the gravy (stays warm for 1 - 1 1/2 hours).","images":[],"step":10},{"title":"Skim fat","description":"Use a large spoon to skim off and discard some of the fat from the surface of the liquid.","images":[],"step":11},{"title":"Add flour","description":"Place pan on the stove on medium high. When the liquid bubbles, add flour. Use a whisk to mix it in - this may take a few minutes as the liquid reduces.","images":[],"step":12},{"title":"Add water","description":"Once it looks like sludge (see video), whisk in 1/2 - 1 cup of water until it becomes a gravy consistency to your taste. Adjust salt and pepper to taste - I rarely add extra salt.","images":[],"step":13},{"description":"Strain gravy into a bowl, pressing juices out of the onion etc. Pour gravy into jug.","images":[],"step":14},{"description":"The meat is tender so you will only need tongs to tear the meat off. Serve with gravy!","images":[],"step":15}]', '["gluten"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","easter-mains","easter-recipes","gluten-free-recipes","iconic-dishes","lamb-recipes","main-dishes","roast-lamb","roasts","slow-cooked-fall-apart","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e90cafbc9909', 'en', 'US', 'Garlic Prawns (Shrimp!)', 'Recipe video above. Hands down, my favourite way to cook fresh prawns! Simple and fabulous, the 3 tips for top notch garlic prawns is to chop rather than use a mincer for the garlic (it splatters and burns on high heat), add the garlic partway through cooking (else it burns), and a splash of wine gives this a flavour edge as well as stopping the garlic from burning. Serves 2 - 3 as a main, 4 - 5 as a starter.', 'https://www.recipetineats.com/tachyon/2017/05/Garlic-Prawns_6.jpg', 10, 6, 16, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 40.0, "unit": "block of 250g"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["500g / 1lb prawns (shrimp) (, peeled and deveined, tail on (unpeeled weight 1kg/2lb, Note 1))","1/2 tsp cooking/koshfer salt","1/2 tsp black pepper","3 tbsp extra virgin olive oil (separated)","3 tsp finely minced garlic cloves (~ 4 cloves) (use knife, not crusher/mincer)"]},{"ingredients":["40g / 3 tbsp unsalted butter (, cut into 1.5cm / 1/2\" cubes (Note 2))","1/4 cup chardonnay or other dry white wine (Note 3)","1 tbsp lemon juice","1 tbsp parsley, finely chopped (garnish)"],"purpose":"Garlic butter sauce"},{"ingredients":["Lemon wedges","Bread for mopping!"],"purpose":"Serving"}]', '[{"title":"Marinade","description":"Place the prawns, 1 tablespoon olive oil and pepper in bowl. Gently toss then set aside for 20 minutes (no longer else the prawns will sweat from the salt),.","duration":20,"images":[],"step":1},{"description":"Cooking","images":[],"step":2},{"title":"Sear in batches","description":"Heat 1 tablespoon olive oil in a large non-stick frying pan over high heat. Place half the prawns in the pan then sear each side for just 45 seconds, using tongs to turn.","images":[],"step":3},{"title":"Remove & repeat","description":"Remove prawns onto a plate, heat the last 1 tablespoon of oil and cook each side for 45 seconds.","duration":0.75,"images":[],"step":4},{"description":"Return first batch of prawns back into pan.","images":[],"step":5},{"title":"Garlic","description":"Add garlic then stir for 30 seconds.","duration":0.5,"images":[],"step":6},{"title":"Add wine","description":"it will sizzle and be steamy! Stir, scraping the bottom of the pan, until wine mostly evaporates - around 30 seconds.","images":[],"step":7},{"title":"Butter & lemon","description":"Scatter butter across pan, add lemon juice. Swirl butter around the pan until it melts, then toss through the parsley.","images":[],"step":8},{"title":"Serve","description":"Transfer the prawns and all the butter sauce onto a serving plate. Serve with extra lemon wedges. Bread for mopping is essential - try this simple Crusty Artisan Bread!","images":[],"step":9}]', '["gluten","milk","shellfish"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","easter-mains-fish-seafood","gluten-free-recipes","main-dishes","prawns-shrimp","quick-and-easy","seafood-recipes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_83ce9102cb6e', 'en', 'US', '45 Cal Creamy HEALTHY Soup!', 'Recipe video above. {Low Cal, GF, low carb} My secret method to make a really low calorie creamy soup that is seriously delicious! Using boiled PEELED zucchini, simmer until soft then blitz into what looks like everybody''s favourite calorie-laden creamy broths.....but it''s guilt free. Zucchini is ideal - purees smooth, neutral flavour that''s easily disguisable. It doesn''t taste like zucchini - just a savoury creamy soup. I''ve used it to make a healthy version of homemade Cream of Chicken Soup. But imagine the possibilies - use it in place of any soup that has a creamy white broth!', 'https://www.recipetineats.com/tachyon/2020/01/Super-Skinny-Cream-of-Chicken-Soup_6.jpg', 10, 20, 30, 5, '[{"id": "ing_zucchini", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 500.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 500.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 225.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 4.5, "unit": "head"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_chicken_breast", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_frozen_peas", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["700g/ 1.2 lb zucchinis ((4 largish), peeled and cut into 1.5cm / 3/5\" slices)","1/2 large onion (, roughly chopped (brown, white, yellow))","2 garlic cloves (, whole)","2 cups (500 ml) chicken broth (or veg broth)","2 cups (500 ml) water","1/2 tsp each garlic and onion powder (or 1 tsp of one of them)","1/4 tsp black pepper","1 cup (250 ml) 0% fat milk (or other milk of choice)"],"purpose":"Healthy Creamy Soup Broth:"},{"ingredients":["1 tbsp (15g) butter or olive oil","2 garlic cloves (, minced)","1/2 large onion (, finely chopped)","1.5 cups carrot (, peeled and finely diced)","1.5 cups celery (, finely chopped)","1 small red capsicum/bell pepper (, finely chopped)","1.5 cups cooked chicken breast (, diced)","3/4 cup frozen peas"],"purpose":"Soup Add Ins:"},{"ingredients":["Fresh thyme (high recommended, or sub chives)"],"purpose":"Garnish:"}]', '[{"description":"Healthy Creamy Broth:","images":[],"step":1},{"description":"Place all Broth ingredients EXCEPT milk into a pot, cover with lid and bring to energetic simmer over medium high heat.","images":[],"step":2},{"description":"Lower to medium and simmer for 15 minutes until zucchinis is very soft.","duration":15,"images":[],"step":3},{"description":"Remove from heat, add milk. Use a handheld blender to blitz until smooth. Add salt to taste. Marvel at creamy broth with so few calories!","images":[],"step":4},{"description":"Healthy Cream of Chicken Soup:","images":[],"step":5},{"description":"Melt butter in a pot or large saucepan over medium heat.","images":[],"step":6},{"description":"Add garlic, onion, carrot and celery. Cook for 3 minutes, then add capsicum. Cook for another 2 minutes until onion is translucent and sweet.","duration":3,"images":[],"step":7},{"description":"Add Broth, chicken and peas. Bring to gentle simmer for just 2 to 3 minutes or until peas are cooked.","images":[],"step":8},{"description":"Taste and adjust salt and pepper.","images":[],"step":9},{"description":"Ladle into bowls, sprinkle with a pinch of fresh thyme leaves. Devour, and marvel at how such a creamy, totally delicious bowl of soup has so few calories!!","images":[],"step":10}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","gluten-free-recipes","low-calorie-recipes","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_31e4a72ef630', 'en', 'US', 'Fish Fingers', 'Recipe video above. Fish Fingers so perfectly golden and crunchy it''s hard to believe they''re BAKED rather than fried! Toasting the breadcrumbs makes all the difference because fish cooks in the oven so much faster than it takes to brown the breadcrumbs. BONUS: This is a mess free breading technique!', 'https://www.recipetineats.com/tachyon/2020/01/Fish-Fingers_5.jpg', 15, 15, 30, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_bread", "quantity": {"value": 0.281, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.037, "unit": "jar of 400g"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_tartare_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["600g / 1.2lb white fish fillets (, patted dry (Note 1))","Oil spray (olive oil or any plain)"]},{"ingredients":["1 1/2 cups (75g) panko breadcrumbs (Note 2)","1/4 cup (25g) parmesan","2 tsp paprika (, optional)","1/2 tsp salt and pepper (, each)"],"purpose":"Crumb"},{"ingredients":["1 egg","1 tbsp mayonnaise","2 tbsp flour","1/4 tsp salt and pepper (, each)"],"purpose":"Batter"},{"ingredients":["Tartare sauce or other seafood dipping sauce","Lemon wedges","Finely chopped chives or parsley (, garnish (optional))"],"purpose":"Serving"}]', '[{"description":"Preheat oven to 180°C / 350°F.","images":[],"step":1},{"title":"Toast breadcrumbs","description":"Spread breadcrumbs on tray. Spray with oil, bake 4 minutes until golden. Transfer toasted breadcrumbs into bowl, add remaining Crumb ingredients and mix.","images":[],"step":2},{"description":"Increase oven to 220°C / 425°F (fan 200°C). Spray used tray with oil.","images":[],"step":3},{"title":"Batter","description":"Mix Batter ingredients in a separate bowl.","images":[],"step":4},{"description":"Cut the fish into strips 1.5 x 11 cm / 3/5 x 4.5\" (they shink 30% in length).","images":[],"step":5},{"description":"Place fish in Batter, gently mix with rubber spatula to coat. Do not leave sitting around (will become watery), coat immediately.","images":[],"step":6},{"title":"Breading","description":"Pick up fish with tongs, place in breadcrumbs. Spoon over crumb, use fingers to press to adhere.","images":[],"step":7},{"title":"Baking","description":"Transfer to baking tray. Spray with oil, bake 13 minutes or until crispy on the outside.","images":[],"step":8},{"description":"Serve immediately with lemon wedges, Tartare Sauce or other Sauce of choice - see here for recipes, any of these great for fish fingers! Also Note 3 for few quick sauce options.","images":[],"step":9}]', '["egg","fish","gluten","milk"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","fish-recipes","low-calorie-recipes","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2112cd9cfad7', 'en', 'US', 'Pizza Stuffed Mushrooms', 'Recipe video above. This is the sort of recipe that you can absolutely make your own with your favourite pizza toppings! TIP: avoid watery filling by cutting a small cross in the cap of the mushroom to let excess water drain out as it bakes. Serve as a light meal, or serve 2 as a main meal.', 'https://www.recipetineats.com/tachyon/2019/07/Pizza-Stuffed-Mushrooms_0.jpg', 10, 20, 30, 5, '[{"id": "ing_mushroom", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_pizza_sauce", "quantity": {"value": 100.0, "unit": "bottle"}}, {"id": "ing_salami", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_black_olive_slices", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}]', '[{"ingredients":["5 large mushrooms (, 10cm/4\" wide (portobello, flat mushrooms etc, Note 1))","2 tbsp olive oil","Salt and pepper","2/3 cup pizza sauce (I use store bought)","100g/ 3.5 oz salami slices (, chopped)","1/4 red onion (, finely chopped)","1/3 cup black olive slices","1 cup (100g) mozzarella cheese (, shredded )"]}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Carefully break or cut the stems off the mushrooms.","images":[],"step":2},{"description":"Chop stems (will use as filling).","images":[],"step":3},{"description":"Place mushrooms cap side up. Using a small, sharp, THIN knife, cut a small cross in the mushroom, taking great care not to split the mushroom (to drain excess water, Note 2)","images":[],"step":4},{"description":"Brush the tops with oil, then quickly sprinkle on salt and pepper (be fast so it sticks!)","images":[],"step":5},{"description":"Flip then lightly dab the inside with remaining oil, sprinkle with salt and pepper.","images":[],"step":6},{"description":"Fill mushrooms with pizza sauce, sprinkle with chopped mushroom, onion, half salami and half olives.","images":[],"step":7},{"title":"Bake 1","description":"Bake 10 minutes, remove from oven.","images":[],"step":8},{"description":"Top with cheese, remaining salami and olives.","images":[],"step":9},{"title":"Bake 2","description":"Bake further 10 minutes until cheese is melted. Serve immediately!","images":[],"step":10},{"description":"Preheat BBQ to medium high.","images":[],"step":11},{"title":"Follow above steps in closed BBQ","description":"10 minutes for Bake 1, then 5 - 8 minutes for Bake 2.","images":[],"step":12}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","low-calorie-recipes","mushroom-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a5413fbde8c0', 'en', 'US', 'Oven Baked Sausages with Potatoes, Vegetable AND Gravy!', 'Recipe VIDEO above. Cooking sausages in the oven with vegetables and gravy is a terrific quick dinner idea that takes mere minutes to assemble! The sausages get nicely browned, the vegetables tender, and a flavour packed gravy. Kind of like making a stew!', 'https://www.recipetineats.com/tachyon/2018/03/Sausage-Bake_4-1.jpg', 15, 45, 60, 4, '[{"id": "ing_potato", "quantity": {"value": 700.0, "unit": "bag of 2kg"}}, {"id": "ing_carrot", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_sausages", "quantity": {"value": 8.0, "unit": "pack of 500g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.3, "unit": "kg"}}]', '[{"ingredients":["700g / 1.4 lb baby potatoes (, halved)","3 carrots (, peeled and cut into 2\"/5cm pieces)","2 red onions (, each cut into 8 wedges)","2 garlic cloves, minced","2 tbsp olive oil","2 tsp dried thyme","1 tsp dried oregano","Salt and pepper"],"purpose":"Vegetables"},{"ingredients":["8 - 10 sausages (500-700g / 1-1.4lb) (Note 2)","Oil spray (optional)"],"purpose":"Sausages"},{"ingredients":["2 tbsp / 30g melted butter, unsalted","2 1/2 tbsp flour (plain / all purpose)","2 cups / 500 ml beef broth (or chicken) ( (Note 3))","Fresh thyme (, for garnish (optional))"],"purpose":"Gravy"}]', '[{"description":"Preheat oven to 200C/390F (standard) or 180C/350F (fan / convection).","images":[],"step":1},{"description":"Place Vegetable ingredients in a large bowl. Toss well to coat.","images":[],"step":2},{"description":"Add sausages and toss briefly.","images":[],"step":3},{"description":"Transfer into roasting pan. Pan should be of a size so the vegetables are stacked about 2 deep - see photos and video. Rearrange sausages so they are on top.","images":[],"step":4},{"description":"In the same bowl used for the vegetables, add butter and flour. Whisk.","images":[],"step":5},{"description":"Add a bit of beef broth and whisk, then whisk in remaining broth. (Don''t worry if you end up with some floating butter bits)","images":[],"step":6},{"description":"Pour down the side of the pan (don''t pour over the sausages or veggies).","images":[],"step":7},{"title":"Optional: Spray sausages with oil","description":"browns slightly better (especially lean sausages).","images":[],"step":8},{"description":"Bake 25 minutes. Turn sausages. Spray again with oil (optional) then bake for a further 25 minutes or until sausages are browned and potatoes are soft.","images":[],"step":9},{"description":"Serve Sausages and Vegetables with Gravy on top, garnished with fresh thyme leaves if desired. (See notes for Gravy thickness adjustment)","images":[],"step":10}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","gluten-free-recipes","main-dishes","one-pot-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b76c889202ce', 'en', 'US', 'Creamy Vegetable Soup with Noodles (No cream!)', 'Recipe video above. A cream cream-less soup with lots and lots of fresh veggies, plus noodles! Use 7 - 8 cups of diced vegetables of choice, including onion. If making ahead or you know you''ll have leftovers, cook the pasta separately and place in the bowl, then ladle over soup (because noodles left in soup becomes bloated and overly soft). Make it Gluten Free by using GF pasta and cornflour sub to thicken soup (Note 2).', 'https://www.recipetineats.com/tachyon/2018/09/Cream-of-Vegetable-Soup-with-Noodles_1a.jpg', 10, 20, 30, 4, '[{"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_vegeta", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}]', '[{"ingredients":["50g (3 tbsp) butter (, unsalted)","2 garlic cloves (, minced)","1/2 onion (, finely chopped)","1 tsp dried thyme","1/3 cup (70g) flour (Note 2 cornflour/cornstarch GF)","3 cups (750 ml) milk (, any (I use low fat))","2 cups (500 ml) vegetable or chicken broth (, low sodium)","1 cup (250 ml) water","3 tsp Vegeta or other stock powder (Note 1)","200g / 7oz linguine or other pasta (, broken into 4 pieces)","Salt and pepper to taste"]},{"ingredients":["2 carrots (, diced)","2 celery ribs (, diced)","1 red capsicum/bell pepper (, diced)","1 cup corn kernels (, frozen or canned drained)","1 cup frozen peas"],"purpose":"Vegetables (sub 8 cups any diced veg):"},{"ingredients":["Fresh thyme leaves"],"purpose":"Optional garnish:"}]', '[{"description":"Melt butter in a large pot over medium high heat. Add garlic and onion, cook for 2 minutes. Then add carrot and celery. Cook for a further 2 minutes, then add capsicum and cook for another 1 minute.","duration":2,"images":[],"step":1},{"description":"Add flour and mix, cook for 1 minute.","duration":1,"images":[],"step":2},{"description":"Add about half the broth and mix. Once flour is incorporated into the broth, add remaining broth, milk, water, dried thyme, Vegeta and pepper. Mix, then add corn and peas.","images":[],"step":3},{"description":"Bring to simmer then lower heat slightly.","images":[],"step":4},{"description":"Break pasta into 4 pieces and add into pot. Cook for 10 minutes or until pasta is just cooked. Adjust salt and pepper to taste.","duration":10,"images":[],"step":5},{"description":"Ladle into bowls and serve, garnished with a tiny sprinkle of fresh thyme leaves if desired.","images":[],"step":6}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","gluten-free-recipes","main-dishes","quick-and-easy","soup-recipes","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9a05a24052e5', 'en', 'US', 'Vegetable Pasta - One Pot!', 'Recipe video above. A quick healthy dinner with more veg and less pasta, all made in one pot! For a lower cal option, skip the cheese and serve with parmesan sprinkled on top. Workflow: Get the onion cooking while you prep the other ingredients.', 'https://www.recipetineats.com/tachyon/2018/09/One-Pot-Vegetable-Pasta_3.jpg', 5, 15, 20, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_broccoli", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped)","2 zucchinis* (, halved lengthwise and cut into sliced 0.8cm / 1/3\" slices)","1 red capsicum/bell pepper* (, halved and sliced)","1 cup corn* (frozen or canned)","1 broccoli* (, broken into bite size florets)","250g/ 0.5lb ziti/penne (, or other short pasta (Note 1))","800 g / 28 oz crushed tomato","1.5 cups / 375 ml vegetable or chicken broth","2 tbsp tomato paste","1 tbsp Italian herb mix (or other dried herbs)","1 tsp garlic powder","1/2 tsp red pepper flakes (chilli flakes, adjust spiciness to taste)","1.5 tsp salt","0.5 tsp black pepper"]},{"ingredients":["1.5 cups shredded cheese of choice (Cheddar, tasty, Monterey Jack etc)"],"purpose":"Optional:"},{"ingredients":["Finely chopped parsley (optional)","Parmesan (if not using cheese)"],"purpose":"To serve:"}]', '[{"description":"Heat oil in a large pot over medium. Add garlic and onion - cook slowly for 3 to 4 minutes until onion is translucent and sweet.","duration":3.5,"images":[],"step":1},{"description":"Turn heat up to medium high, add zucchini and capsicum. Cook 1 1/2 minutes.","images":[],"step":2},{"description":"Add remaining ingredients EXCEPT pasta and broccoli. Stir until tomato paste dissolves.","images":[],"step":3},{"description":"When liquid starts bubbling, lower heat to medium, add pasta and stir. Top with broccoli, push in.","images":[],"step":4},{"description":"Place lid on and cook for 5 minutes.","duration":5,"images":[],"step":5},{"description":"Remove lid. Cook for another 3 to 4 minutes, stirring frequently, until pasta is almost cooked through and most of the liquid has been absorbed by the pasta.","images":[],"step":6},{"description":"Stir through half the cheese (if using). Adjust salt and pepper to taste.","images":[],"step":7},{"description":"Top with remaining cheese, put lid on. Leave for 1 minute until cheese is melted and pasta is perfectly cooked.","duration":1,"images":[],"step":8},{"description":"Garnish with parsley and serve immediately. Don''t leave leftovers in the pot, residual heat will overcook the pasta so transfer into a serving dish.","images":[],"step":9}]', '["gluten","milk"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","low-calorie-recipes","main-dishes","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6a84414fab73', 'en', 'US', 'Prawn Risotto (Shrimp)', 'This is a great everyday prawn risotto that’s a cut above basic risottos. Searing the prawn (shrimp) makes a terrific flavour base that compensates for not using a homemade seafood stock. And as long as you use a large pot, you don’t need to stand at the stove for 20 minutes to stir constantly and add hot broth a ladle at a time for ultra creamy risotto – read more in post. Recipe video below.', 'https://www.recipetineats.com/tachyon/2018/05/Prawn-Risotto_0.jpg', 10, 25, 35, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_shrimp", "quantity": {"value": 400.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.111, "unit": "bottle of 750ml"}}, {"id": "ing_arborio_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 – 2 tbsp olive oil","400 – 500g (14oz – 1 lb) prawns/shrimp, raw, peeled (Note 1)","Salt and pepper","1 1/2 tbsp (20g) butter","1/2 onion (, finely chopped)","2 garlic cloves (, minced)","1/3 cup (85 ml) dry white wine (or water)","1 1/2 cups (270g) Arborio rice (, uncooked (Note 2))","3 cups (750ml) chicken broth (, low sodium, at room temp)","1 cup (250 ml) milk (, room temp (full or low fat))","1 cup (150g) frozen peas (, thawed)","1/3 cup (40g) grated parmesan"]},{"ingredients":["1 – 2 tbsp (15 – 30g) Extra Butter","Grated parmesan","Finely chopped parsley (optional)"],"purpose":"Finishing / serving:"}]', '[{"description":"Heat 1 tbsp oil in a large heavy based pot over medium high heat. Spread half the prawns in a single layer, sprinkle with salt and pepper. Cook for 1 ½ minutes, then turn and cook the other side for 1 minute. Remove into bowl.","duration":1,"images":[],"step":1},{"description":"Add a touch more oil and repeat with remaining prawns. Set aside and keep warm.","images":[],"step":2},{"description":"Turn heat down to medium. Melt butter in pot then add onion and garlic. Cook for 2 minutes until translucent.","duration":2,"images":[],"step":3},{"description":"Add wine, and stir, scraping the bottom of the pot to mix the brown bits from the prawn into the liquid. Bring to simmer and cook for 2 minutes until harsh alcohol smell is gone.","duration":2,"images":[],"step":4},{"description":"Add rice and stir for 30 seconds until rice is translucent on edges.","duration":0.5,"images":[],"step":5},{"description":"Add about 2/3 of the chicken broth. Stir, bring to simmer. Adjust heat so it’s simmering gently.","images":[],"step":6},{"description":"Simmer for 5 minutes. Stir, then simmer for a further 2 minutes until broth is mostly absorbed and rice is visible on the surface (see video and photos).","duration":5,"images":[],"step":7},{"description":"Add remaining broth and milk. Stir, simmer for 3 minutes. Stir, simmer for 2 minutes.","duration":3,"images":[],"step":8},{"description":"Risotto should be soupy and rice still a tiny bit undercooked.","images":[],"step":9},{"description":"Add peas and parmesan, quickly stir.","images":[],"step":10},{"description":"Taste, then add salt and pepper, then quickly stir.","images":[],"step":11},{"description":"Add Extra Butter, then stir vigorously for 10 seconds (this is the step that makes it very creamy).","duration":0.16666666666666666,"images":[],"step":12},{"description":"Lastly, gently stir through prawns (tip in any juices too).","images":[],"step":13},{"description":"Remove risotto from heat, it should be porridge-like. (Note 3, see video) To loosen, add hot tap water 2 tbsp at time and stir through.","images":[],"step":14},{"description":"Give it a good final stir just before serving. Then ladle into bowls (it should ooze a bit, not be sticky lump). Garnish with parmesan and parsley if desired.","images":[],"step":15}]', '["milk","shellfish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","dinner-tonight","gluten-free-recipes","italian-recipes","main-dishes","prawns-shrimp","quick-and-easy","rice-recipes","risotto-recipes","seafood-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cd31ed7ba9a4', 'en', 'US', 'Oven Baked Rice and Vegetables', 'Recipe video above. Fluffy seasoned rice AND oven roasted veggies, all baked in ONE PAN! Imagine the possibilities!', 'https://www.recipetineats.com/tachyon/2017/09/Oven-Baked-Vegetables-and-Rice.jpg', 10, 50, 60, 5, '[{"id": "ing_jasmine_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cauliflower", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_zucchini", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 2.0, "unit": "can of 400g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 1.0, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["1 1/2 cups basmati or jasmine rice (, uncooked (Note 1 for other rice types))","1 1/2 cups (375ml) chicken or vegetable broth (I use chicken)","1 1/4 cups (315ml) water","2 garlic cloves (, minced)","2 medium carrots (, cut into 1 cm thick slices, larger pieces halved)","30g (2 tbsp) unsalted butter (optional)"],"purpose":"Rice:"},{"ingredients":["1 red onion (, halved and cut into wedges)","1 capsicum / bell pepper (, cut into 2.5cm / 1\" pieces)","1/2 small cauliflower (, broken into florets)","2 zucchini (, cut into 2cm / 4/5\" chunks)","2 corn cobs (, each cut into 3 (6 small cobs))","1/4 cup olive oil (, plus more for drizzling)"],"purpose":"Roasting Vegetables (Note 2):"},{"ingredients":["1 1/2 tsp paprika","1 1/2 tsp thyme or other dried herb of choice","1 tsp garlic powder (or onion powder)","1 tsp salt (Note 3 for low sodium)","1 tsp pepper (, plus extra)"],"purpose":"Spice Mix:"},{"ingredients":["Finely chopped parsley"],"purpose":"Garnish (optional):"}]', '[{"description":"Preheat oven to 200C/390F (standard) / 180C/350F (fan / convection).","images":[],"step":1},{"description":"Mix Spice Mix in a small bowl.","images":[],"step":2},{"description":"Place Rice ingredients in a baking dish (including the carrots), about 23 x 30 cm / 9 x 13\". Add 1 1/2 tsp Spice Mix. Stir, cover with foil, bake for 20 minutes.","duration":20,"images":[],"step":3},{"description":"Meanwhile, place Roasting Vegetable ingredients in a large bowl, drizzle with 1/4 cup olive oil. Sprinkle over remaining Spice Mix. Mix well - hands are best for this.","images":[],"step":4},{"description":"Remove rice from oven.","images":[],"step":5},{"description":"Turn oven UP to 220C/430F (standard) / 200C/390F (fan / convection).","images":[],"step":6},{"description":"Take off foil. Spread the Roasting Vegetables on top of the rice. Make sure there''s a bit of each type of vegetable on the surface. Push corn mostly under.","images":[],"step":7},{"description":"Drizzle with more oil (optional), sprinkle with more pepper.","images":[],"step":8},{"title":"Bake for 30 minutes. Remove from oven, rest for 5","description":"10 minutes.","duration":30,"images":[],"step":9},{"description":"Sprinkle with parsley if desired. Push vegetables aside, fluff rice and toss it through the vegetables a bit (rice gets more flavour). Serve!","images":[],"step":10}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","easter-sides-warm-hearty","gluten-free-recipes","one-pot-recipes","quick-and-easy","rice-recipes","rice-side-dishes","side-dishes","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3c29732007fd', 'en', 'US', 'Spanish Healthy Vegetable Soup', 'Recipe video above. This is my version of the famous Zero Weight Watchers Points vegetable soup. Mine has 0.4 WW points but is much MUCH tastier! Spanish flavours inspired by the seasoning for homemade Chorizo (yes, really!), the broth of this soup is MUCh tastier than the Zero WW soup!!!', 'https://www.recipetineats.com/tachyon/2017/07/Healthy-Vegetable-Soup.jpg', 15, 30, 45, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 20.0, "unit": "head"}}, {"id": "ing_capsicum", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_cabbage", "quantity": {"value": 15.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 tsp olive oil","1 onion (, finely chopped)","2 garlic cloves (, minced)","1 tbsp dried oregano","2 tsp fennel seeds (optional)","2 medium carrots (, finely chopped)","1 large celery stalk/rib (, finely chopped)","2 red capsicums / bell peppers (, cut into 2 cm / 4/5” pieces)","5 cups cabbage (, cut into 3 cm / 1.2” pieces (about 400g/14oz))","800g / 28 oz crushed tomato","3 cups (750 ml) vegetable or chicken broth (low fat!)","1 tbsp smoked paprika (or any paprika)","1 tsp cayenne pepper (adjust spiciness to taste)"],"purpose":"Soup:"},{"ingredients":["Salt and pepper to taste","1 lemon – zest + juice to taste","Finely chopped parsley"],"purpose":"Finishes (not optional!):"}]', '[{"description":"Heat oil in a large pot over medium heat. Add garlic and onion, cook for 30 seconds or so.","duration":0.5,"images":[],"step":1},{"description":"Add oregano and fennel seeds, cook for 2 minutes (lets flavour “bloom”).","duration":2,"images":[],"step":2},{"description":"Turn heat down to medium low. Add carrots and celery, cook, stirring regularly, for 8 minutes until onion is sweet (not browned). This step is key to the flavour base of this soup.","duration":8,"images":[],"step":3},{"description":"Add capsicum, turn heat up to high and cook for 2 minutes, stirring constantly.","duration":2,"images":[],"step":4},{"description":"Add remaining Soup ingredients, bring to simmer then place lid on. Turn heat down to medium low, simmer for 25 minutes.","duration":25,"images":[],"step":5},{"description":"Remove lid, adjust salt and pepper to taste.","images":[],"step":6},{"description":"Ladle soup into bowls. Grate over lemon zest, squeeze of lemon juice and sprinkle with parsley. Serve!","images":[],"step":7}]', '[]', '["gluten_free","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Spanish Style","Western"],"categories":["dietary","dinner-tonight","gluten-free-recipes","low-calorie-recipes","main-dishes","mediterranean-recipes","quick-and-easy","soup-recipes","vegan-lifestyle","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_92db19b9d29d', 'en', 'US', 'Port Braised Lamb Shanks', 'These lamb shanks are just like what you get at high end restaurants! Port and red wine is the key to the incredible sauce that these lamb shanks are braised in. Get discount bottles - no need to splurge on expense wine for this!', 'https://www.recipetineats.com/tachyon/2016/09/Lamb-Shanks-Port-Braised_4.jpg', 15, 180, 195, 4, '[{"id": "ing_amb_shanks", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_port", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_wine", "quantity": {"value": 0.5, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_parsley", "quantity": {"value": 4.0, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 4.0, "unit": "bunch"}}]', '[{"ingredients":["4 lamb shanks (, approx 400g/13oz each (Note 1))","Salt and pepper","2 tbsp olive oil (, separated)","2 garlic cloves (, minced)","1 onion (, finely chopped (white, brown, yellow))","1 celery stalk (, finely chopped (optional, but recommended))","1 carrot (, finely chopped (optional, but recommended))","3 tbsp / 1/4 cup flour (35g)","2 cups / 500 ml beef broth (liquid beef stock) (or sub with chicken broth)","3 cups / 750 ml port (Note 2)","1 1/2 cups / 375ml red wine (, or more beef broth (Note 3))","3 tbsp / 1/4 cup tomato paste","5 sprigs thyme or 2 tsp dried thyme","3 dried bay leaves (or 5 fresh)","4 stalks fresh parsley (optional)"]},{"ingredients":["Fresh parsley (, finely chopped)"],"purpose":"To Serve"}]', '[{"description":"Season lamb with salt and pepper.","images":[],"step":1},{"description":"Heat 1 tbsp oil in a dutch oven or large heavy based pot over high heat. Add 2 lamb shanks and cook, turning, until browned (see photo). Remove then repeat with remaining lamb.","images":[],"step":2},{"description":"Turn heat down to medium. Add remaining 1 tbsp oil, garlic, onion, carrot and celery. Sauté for 5 minutes until onion is softened.","duration":5,"images":[],"step":3},{"description":"Add flour. Mix into onion mixture.","images":[],"step":4},{"title":"Add remaining ingredients. Mix","description":"lumps are ok, they will dissolve while cooking.","images":[],"step":5},{"title":"Add lamb back in","description":"the meat should be mostly submerged. Bring to simmer, then turn heat down to medium low and cover with lid.","images":[],"step":6},{"description":"Simmer for 2 hours (Note 4) then remove lid and simmer for 30 minutes.","images":[],"step":7},{"description":"Remove lamb into a bowl.","images":[],"step":8},{"title":"Optional","description":"Strain sauce in dutch oven into a bowl. Use spoon to press into onion etc to squeeze out all the flavourful liquid. Pour sauce into dutch oven. (Note 5)","images":[],"step":9},{"description":"Skim excess fat off sauce.","images":[],"step":10},{"description":"Increase heat to medium high and reduce liquid by half or until it thickens to a syrup consistency.","images":[],"step":11},{"description":"Return lamb shanks and juices pooled in the bowl into sauce to reheat, then serve with creamy mashed potato, garnished with parsley.","images":[],"step":12}]', '["gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","gluten-free-recipes","lamb-shanks","main-dishes","slow-cooked-fall-apart","slow-cooker-recipes","stews","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3afa1e590bac', 'en', 'US', 'Balsamic Pork Chops', 'Super simple, yet serious flavour!! The Balsamic sauce is tangy and sweet, and this will go fantastically with any protein - chicken, beef, pork and even lamb! The flavour of this syrup is quite intense so you do not need much for each serving - just spoon a couple of tablespoons over each pork. While the total cook time may seem long, it is mostly hands off time because the balsamic syrup doesn''t need to be watched over as it reduces.', 'https://www.recipetineats.com/tachyon/2016/07/Balsamic-Pork-Chops_5.jpg', 5, 25, 30, 4, '[{"id": "ing_pork", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_balsamic_vinegar", "quantity": {"value": 1.0, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4 pork chops (, 2.5cm / 1\" thick, about 200-250g/7-8oz each (excluding any bone) (Note 1))","1 - 2 tbsp olive oil","1 garlic clove (, minced)","1 onion (, finely sliced (~1 cup of onion, brown, yellow or white))","1 cup balsamic vinegar","1/3 cup / 60g brown sugar (Note 2)","Salt and pepper"]},{"ingredients":["Crumbled goats cheese or feta","Fresh parsley or thyme"],"purpose":"Garnish (optional)"}]', '[{"description":"Sprinkle both sides of pork with salt and pepper.","images":[],"step":1},{"description":"Heat 1 tbsp oil in a large skillet over medium high heat. Cook the first side for 4 minutes until it has a lovely dark gold crust, then turn and cook the other side for 3 minutes. (Note 3)","duration":4,"images":[],"step":2},{"description":"Transfer to a plate, cover loosely with foil.","images":[],"step":3},{"description":"Add 1 tbsp oil to the skillet, still on medium high. Add garlic and onion, cook until translucent - around 3 minutes.","images":[],"step":4},{"description":"Add balsamic vinegar and brown sugar. Stir until the sugar is melted. When it comes to a simmer, adjust the heat so it is bubbling gently, not rapidly.","images":[],"step":5},{"description":"Simmer for ~5 to 8 minutes or until it reduces by almost half and is a THIN syrup. Then add the pork back into the skillet, including all the juices on the plate. Simmer, turning pork to reheat, for 2 minutes or until the the sauce becomes syrupy (to your taste) and pork is reheated. (Note 4)","duration":2,"images":[],"step":6},{"description":"Serve, garnished with crumbled goats cheese if desired.","images":[],"step":7}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","gluten-free-recipes","main-dishes","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_aa2bb99d5e87', 'en', 'US', 'Chorizo & Kale Risotto', 'Risotto in a rich Chorizo flavoured tomato broth! I used kale to add greens and a pop of colour, but you can substitute with spinach, or even leave it out!', 'https://www.recipetineats.com/tachyon/2016/04/Chorizo-Risotto_1.jpg', 10, 25, 35, 4, '[{"id": "ing_chicken", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_chorizo", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_arborio_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_kale", "quantity": {"value": 5.0, "unit": "unit"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["3 cups chicken broth/stock (, salt reduced)","2 tbsp tomato paste","2 cups tomato passata (Note 1)"],"purpose":"Stock"},{"ingredients":["1/2 tbsp olive oil","350g (12oz) chorizo (, some sliced and the remainder finely chopped (Note 7))","1 onion (, finely chopped (brown, white or yellow))","2 garlic cloves (, minced)","1 1/2 cups arborio rice (risotto rice), uncooked (Note 2)","1/2 cup white wine (sub with chicken broth or water)"],"purpose":"Risotto"},{"ingredients":["5 cups kale leaves (, removed from stalk, torn into bite size pieces (packed) (Note 3))","2 - 4 + tbsp butter","Freshly grated parmesan cheese (optional)"],"purpose":"To Finish"}]', '[{"description":"Whisk together Stock ingredients in a small saucepan over medium low heat. Once heated, turn down to low and keep warm. (Note 4)","images":[],"step":1},{"description":"Heat oil in a pot or large skillet over high heat. Add chorizo and cook until golden brown. Remove into a bowl and set aside.","images":[],"step":2},{"description":"There should be some red oil in the skillet from the chorizo. If not, add a bit of oil.","images":[],"step":3},{"description":"Turn heat down to medium. Cook onion and garlic for 5 minutes until translucent.","duration":5,"images":[],"step":4},{"description":"Add rice and stir to coat grains in oil until translucent.","images":[],"step":5},{"description":"Add wine, turn up the heat to medium high and simmer, stirring, until most of the wine has evaporated.","images":[],"step":6},{"description":"Turn heat down to medium low and add 1 cup of stock. Stir leisurely until mostly absorbed into the rice, then add another cup of stock. Continue 1 cup at a time until the risotto is just cooked - squeeze a grain, it should still be firm but cooked through - about 15 minutes. Make the risotto as saucy (or not) as you want - liquid will absorb in the next step so lean towards saucier than what you want.","images":[],"step":7},{"description":"When the risotto is done (Note 5), remove it from the stove.","images":[],"step":8},{"description":"Add butter (the more the better!) and stir energetically - this will activate the starch and make it creamy. Stir chorizo in then partially stir kale through the risotto. Plonk the lid on and let it rest for 3 minutes (kale will wilt in this step).","duration":3,"images":[],"step":9},{"description":"Adjust salt and pepper to taste. Serve immediately! (Note 6)","images":[],"step":10}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","gluten-free-recipes","italian-recipes","main-dishes","quick-and-easy","risotto-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_87663ec90e4a', 'en', 'US', 'Brown Sugar Broiled Salmon', 'Really great quick way to cook salmon - a brown sugar glaze smeared on salmon fillets, optional addition of veggies, then broil it. Terrific caramelisation, really quick delicious dinner.', 'https://www.recipetineats.com/tachyon/2016/04/One-Tray-Brown-Sugar-Salmon_5.jpg', 4, 8, 12, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_es_asparagus", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_broccoli", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 0.6, "unit": "punnet of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.037, "unit": "jar of 400g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}]', '[{"ingredients":["4 x 5-8 oz/ 150-180g salmon fillets (, skin on or off (I use on))","2 bunches asparagus (Note 1)","1 bunch broccolini (Note 1)","1 cup cherry tomatoes","1 tbsp olive oil","Salt and pepper"]},{"ingredients":["1 tbsp Dijon mustard","1 tbsp mayonnaise (I use whole egg mayonnaise)","2 tbsp brown sugar","1/4 tsp cayenne pepper"],"purpose":"Glaze (Note 2)"}]', '[{"description":"Preheat broiler/griller on high. Place the oven shelf 6\"/15cm from the heat source.","images":[],"step":1},{"description":"Spray a baking tray with oil (I use olive oil, any is fine).","images":[],"step":2},{"description":"Pile asparagus, broccolini and cherry tomatoes on the baking tray. Drizzle with olive oil and sprinkle with salt and pepper. Toss with hands then spread out on the tray, mostly on one layer.","images":[],"step":3},{"description":"Wedge salmon pieces on the tray between the vegetables. Sprinkle with salt and pepper.","images":[],"step":4},{"description":"Mix Glaze ingredients together. Slather on the salmon - tops and sides.","images":[],"step":5},{"title":"Grill/broil for 8 minutes","description":"don''t flip. The salmon should be caramelised and the inside should be blushing pink.","duration":8,"images":[],"step":6},{"description":"Rest for 2 minutes then serve with crusty bread rolls.","duration":2,"images":[],"step":7}]', '["egg","fish","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","dinner-tonight","fish-recipes","gluten-free-recipes","low-calorie-recipes","main-dishes","one-pot-recipes","quick-and-easy","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_56520156fdc2', 'en', 'US', 'Greek Slow Roasted Leg of Lamb', 'This is the Greek way of roasting lamb - slow roasted until tender enough to pull apart, braised in a lemon garlic thyme broth that infuses the flesh with flavour and reduces into a lemony, herby jus rather than having to fuss with making a gravy. Easier and more foolproof than traditional roast lamb leg (the carving sort with pink meat) because there’s no worry about overcooking. There’s also a rosemary garlic version of this slow cooked leg (with gravy!) and plenty of other roast lamb recipes - take the Roast Lamb Matchmaker to find your perfect one!This recipe takes 7 1/2 hours to cook (7 hours in oven plus 30 minutes resting time) and is best served freshly made, so start late morning to serve for dinner, or get up VERY early to serve for lunch!Source: adapted from this Slow Roasted Leg of Lamb by Kalofagas', 'https://www.recipetineats.com/tachyon/2016/03/Greek-Slow-Roast-Lamb_7.jpg', 15, 420, 465, 8, '[{"id": "ing_garlic", "quantity": {"value": 20.0, "unit": "pack of 3 heads"}}, {"id": "ing_lamb", "quantity": {"value": 3.175, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 2000.0, "unit": "pack of 1kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.4, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_bayleaves", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_lemon", "quantity": {"value": 0.15, "unit": "net of 500g"}}, {"id": "ing_wine", "quantity": {"value": 0.5, "unit": "bottle of 750ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.225, "unit": "kg"}}]', '[{"ingredients":["12 cloves of garlic, peeled","7 lb / 3.5 kg leg of lamb (, bone-in (Note 1 & Note 3 for roasting times for larger/smaller))","1 1/2 tsp cooking salt / kosher salt (double for flakes or flaky salt)","1/2 tsp black pepper","3 tsp paprika powder (regular / sweet, not spicy or smoked)","3 tsp garlic powder (or sub with onion powder)","2 tbsp olive oil","2 large onions (, quartered (white, brown, yellow, red))","10 sprigs of thyme","3 sprigs rosemary","3 tsp dried oregano","3 dried bayleaves (or 5 fresh)","1/2 cup lemon juice ((2 - 3 lemons), plus more to taste)","1 1/2 cups white wine (or sub with chicken broth/stock, low salt)","2 cups chicken broth/stock (, low sodium)"]}]', '[{"description":"Stuff incisions with garlic, season, roast leg uncovered 30 min at 240°C/465°F (220°C fan). Lower to 180°C/350°F (160°C fan). Put everything else in pan, flip leg upside down, fill with hot water 1/4 way up, roast covered 3 1/2 hours. Flip lamb, roast covered another 2 1/2 hours, then brown uncovered 30 minutes. Strain pan juices, serve!","images":[],"step":1},{"description":"Preheat oven to 240°C/465°F (220°C fan-forced). (Note 2)","images":[],"step":2},{"title":"Garlic incisions","description":"Use a small knife to make around 25 incisions all over the lamb, with most on the top. Cut around 6 cloves into slivers and stuff them into the incisions.","images":[],"step":3},{"title":"Season","description":"Sprinkle the lamb generously all over with salt, pepper, paprika and garlic powder. Drizzle with olive oil and rub all over the lamb.","images":[],"step":4},{"title":"30 minute browning","description":"Place the lamb in a roasting pan and roast for 30 minutes or until it has a nice brown crust.","duration":30,"images":[],"step":5},{"title":"Prepare for slow-roasting","description":"Remove from the oven. Turn the oven down to 180°C/350°F (160°C fan-forced). Turn the lamb upside down. Pour / place all the remaining ingredients in the pan around the lamb (including remaining garlic cloves). Fill the roasting pan with hot water so it comes up about 1/4 - 1/3 of the way up the height of the lamb.","images":[],"step":6},{"title":"Slow roast part 1 (3 1/2 hours)","description":"Cover with lid or with baking/parchment paper then 2 layers of foil. Roast for 3 1/2 hours. Top up water if it dries out (e.g. Might happen if your foil is loose) ** See Note 3 for larger/smaller leg roasting times **","images":[],"step":7},{"title":"Slow roast part 2 (2 1/2 hours)","description":"Remove the roast from the oven and remove the lid/foil. Turn the lamb over so it is the right side up. Cover again and roast for a further 2 1/2 hours, or until you can pull meat apart easily with forks.","images":[],"step":8},{"title":"Finish browning","description":"Remove cover and roast for a further 20 - 30 minutes (to brown).","images":[],"step":9},{"title":"Rest","description":"Remove from the oven and transfer lamb to serving platter. Cover loosely with foil and rest for 30 - 40 minutes.","duration":35,"images":[],"step":10},{"title":"Sauce","description":"Strain liquid into a clear jug. The fat will rise to the top. Scoop/pour most of it off and discard (I get 3/4 - 1 cup). There should be 2 - 3 cups of Sauce left. Adjust salt, pepper and lemon to taste.","images":[],"step":11},{"description":"Serve lamb with the Sauce on the side and Truly Crunchy Roast Potatoes* or Greek Lemon Potatoes. The lamb will stay warm enough for 1 hour so you can roast / prep other sides during this time.","images":[],"step":12}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["dietary","easter-mains","easter-recipes","gluten-free-recipes","greek-recipes","lamb-recipes","main-dishes","mediterranean-recipes","roast-lamb","roasts","slow-cooked-fall-apart","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6aab0fa959bd', 'en', 'US', 'Apple Cider Glazed Pork Tenderloin', 'Apple cider is the secret to a marinade that makes pork tenderloin incredibly moist with a gorgeous glaze! The marinade also does double duty as the sauce. You will be amazed at the incredible flavour in this with so few ingredients! I used Rochdale Apple Cider for this recipe - a New Zealand cider that is available at all major liquor outlets in Australia including Dan Murphy''s and Liquorland.', 'https://www.recipetineats.com/tachyon/2016/01/Apple-Cider-Glazed-Pork-Tenderloin_6.jpg', 5, 30, 35, 4, '[{"id": "ing_pork", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_apples", "quantity": {"value": 0.312, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_honey", "quantity": {"value": 0.06, "unit": "jar of 500g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 lb/500g pork tenderloin"]},{"ingredients":["11 oz/330ml sweet apple cider (alcoholic aka \"hard cider\") - I used Rochdale Apple Cider (Note 1)","1 bay leaf (, dried (or 2 fresh))","2 tbsp honey","2 tbsp brown sugar","2 garlic cloves (, minced)","1/2 tsp salt","Black Pepper"],"purpose":"Marinade"},{"ingredients":["1 tbsp olive oil"],"purpose":"To Cook"},{"ingredients":["1 1/2 tbsp butter","1 tbsp dijon mustard","Salt and pepper"],"purpose":"Sauce"}]', '[{"description":"Mix the Marinade ingredients in a bowl.","images":[],"step":1},{"description":"Place Marinade and pork in a large ziplock bag and marinate in the refrigerator overnight, up to 24 hours.","images":[],"step":2},{"description":"To Cook","images":[],"step":3},{"description":"Remove pork in the marinade from the refrigerator 30 minutes prior to cooking (to bring to room temperature).","images":[],"step":4},{"description":"Preheat oven to 180C/350F.","images":[],"step":5},{"description":"Heat olive oil in a skillet over medium high heat. Remove pork from marinade (reserve marinade) and place in pan. Sear until golden brown all over - don''t let it burn (Note 2).","images":[],"step":6},{"description":"Transfer skillet to the oven and roast for 15 to 20 minutes, or until the internal temperature using a meat thermometer reads 145F/62C. (Note 3)","duration":17.5,"images":[],"step":7},{"description":"Remove pork from skillet onto a plate and cover loosely with foil to rest while you make the sauce.","images":[],"step":8},{"description":"Place skillet on the stove over high heat with butter. When the butter is melted, add reserved Marinade and mustard. Whisk until smooth.","images":[],"step":9},{"description":"Bring to boil, then turn heat down so it is simmering VERY rapidly, and cook until the liquid becomes syrupy - about 4 to 5 minutes. Adjust salt to taste.","images":[],"step":10},{"description":"Remove skillet from the stove, roll pork in the sauce, then remove and slice. Pour remaining sauce in the skillet into a jug and serve on the side.","images":[],"step":11},{"description":"I served this with a fennel apple salad on the side. (Note 4)","images":[],"step":12}]', '["milk","mustard"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dietary","gluten-free-recipes","pork-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8eb5ae9eb3cd', 'en', 'US', 'One Tray Oven Baked Honey Chili Lime Salmon with Potatoes and Beans', 'Easy midweek cooking without compromising on flavour! Golden crunchy roasted potatoes with salmon glazed with chili, lime and honey and a side of greens to make it a complete meal. If you use smaller salmon, you can most certainly make this for 4.', 'https://www.recipetineats.com/tachyon/2015/06/Chili-Lime-Salmon-Overhead.jpg', 15, 35, 50, 3, '[{"id": "ing_salmon_fillets", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_honey", "quantity": {"value": 0.045, "unit": "jar of 500g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_potato", "quantity": {"value": 14.0, "unit": "bag of 2kg"}}, {"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_green_beans", "quantity": {"value": 226.8, "unit": "pack"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_ime", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["3 pieces of salmon (5 - 7 oz / 150 - 200g each, skin on or off)"]},{"ingredients":["1 large lime ((or 2 small ones) - 1 1/2 tsp zest + 3 tbsp lime juice)","1 1/2 tbsp honey","1 tbsp soy sauce (or fish sauce)","2 garlic cloves (, minced)"],"purpose":"Marinade"},{"ingredients":["14 oz / 450 g baby potatoes (, halved (Note 1))","1 1/2 tbsp melted butter (or olive oil)","1/8 tsp salt","1 garlic clove (, minced (optional))"],"purpose":"Roast Potatoes"},{"ingredients":["8 oz / 250 g green beans (, trimmed)","1 tsp olive oil"],"purpose":"Beans"},{"ingredients":["1/2 tsp salt","Black pepper","1 birds eye chili (, frozen whole (or finely chopped unfrozen chili))","1 lime"],"purpose":"Garnish and seasoning"}]', '[{"description":"Preheat oven to 180C/350F and place a large rimmed baking tray in the oven.","images":[],"step":1},{"description":"Combine the Marinade ingredients in a bowl or ziplock bag. Add the salmon and set aside to marinate for 20 minutes (while the potatoes are roasting). (Note 2)","duration":20,"images":[],"step":2},{"description":"Toss the Roast Potato ingredients in a bowl. Remove the tray from the oven and pour the potatoes onto the tray. Place in the oven and roast for 20 minutes. (Note 3)","duration":20,"images":[],"step":3},{"description":"Combine the Beans ingredients into bowl you used for the potatoes (so residual butter sticks to beans) and toss.","images":[],"step":4},{"description":"Remove salmon from the Marinade, reserving the Marinade.","images":[],"step":5},{"description":"Remove tray from the oven. Move the potatoes to one side and place the salmon in the middle, skin side down. Pile the beans into one corn of the tray (don''t spread them out, they will overcook).","images":[],"step":6},{"description":"Sprinkle over the salt and pepper all over everything on the tray.","images":[],"step":7},{"description":"Drizzle some Marinade on each salmon, then place the tray into the oven and bake for 4 minutes per 1/2 inch / 5 minutes per 1.5 cm of thickness (thickest part of the salmon). My salmon was 1.25 inches / 3 cm thick so I baked it for 10 minutes. (Note 4)","duration":4,"images":[],"step":8},{"description":"Turn the grill/broiler onto maximum. (Note 5) Drizzle the remaining Marinade onto the salmon and grill for 2 minutes or until light golden on top.","duration":2,"images":[],"step":9},{"description":"Rest for 3 minutes. Use a grater to grate frozen chili and lime zest over the salmon. Serve with lime wedges on the side.","duration":3,"images":[],"step":10}]', '["fish","gluten","milk","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dietary","dinner-tonight","fish-recipes","gluten-free-recipes","low-calorie-recipes","main-dishes","most-popular","one-pot-recipes","quick-and-easy","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ea484fd10fc8', 'en', 'US', 'Tzatziki', 'Recipe video above. Nobody makes Tzatziki as good as your yiayia, but just in case you want to make one using actual measurements (rather than a little bit of this and a slosh of that!), here is my recipe. Use as a dip for vegetable sticks and warm pita bread, as a sauce for Gyros, Doner kebabs and chicken skewers, and dolloping on Greek baked chicken pieces.', 'https://www.recipetineats.com/tachyon/2026/03/Tzatziki_7.jpg', 20, 6, 26, 1, '[{"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.375, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_dill_optional_see_note", "quantity": {"value": 0.03, "unit": "kg"}}]', '[{"ingredients":["2 Lebanese cucumbers (Persian cucumbers)","1 1/4 cups Greek yoghurt (or Greek-style yogurt, preferably full fat)","1 tbsp lemon juice","1 tbsp extra virgin olive oil (or more if you want richer)","1 garlic clove (, minced)","1/4 heaped teaspoon cooking salt / kosher salt (halve for table salt, +50% for flakes)","Pinch of black pepper","2 tbsp finely chopped dill ((or mint), OPTIONAL - see note)"]}]', '[{"title":"Deseed, shred and squeeze","description":"Cut the cucumber in half lengthwise. Use a teaspoon to scrape the watery seeds out. Coarsely grate the cucumber using a box grater. Then wrap in a tea towel and squeeze to remove excess liquid.","images":[],"step":1},{"title":"Mix","description":"Place cucumber in a bowl. Add remaining ingredients then mix to combine.","images":[],"step":2},{"description":"Set aside for at least 20 minutes for the flavours to meld.","images":[],"step":3},{"description":"Use immediately or keep in an airtight container in the fridge for 3 days.","images":[],"step":4}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner","lunch"],"cuisine":["Greek"],"categories":["dip-recipes","greek-recipes","quick-and-easy","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b570a1d6bb5c', 'en', 'US', 'How to cook crispy skin duck breast', 'Recipe video above. The trick to cooking duck breast is to start the skin in a cold pan with no oil, then cook it on low heat to let the fat render (melt) which allows the skin to go crispy. Then finish it off in the oven - best way to ensure the flesh is perfectly cooked from edge to edge, for tender, rich, perfect duck slices!As for doneness inside - treat duck like steak rather than chicken breast: it is more tender and juicy if it is medium rare rather than well done (whereas chicken is chewy if still pink!). Though I personally think duck is still enjoyable if well done (eg Chinese BBQ duck is well done and it''s not dry!).You can use this recipe for as many duck breasts as can fit in a pan without crowding it.', 'https://www.recipetineats.com/tachyon/2025/01/Crispy-skin-duck-breast_4.jpg', 2, 20, 22, 1, '[{"id": "ing_duck_breast", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 duck breast (, boneless, skin on (Note 1))","1/8 tsp cooking salt / kosher salt","Pinch white pepper (sub finely ground black pepper)"],"purpose":"Crispy skin duck:"}]', '[{"description":"Preheat the oven to 180°C/350°F (160°C fan-forced).","images":[],"step":1},{"title":"Score","description":"Sprinkle half the salt and pepper on the flesh of the duck. Turn. Use a sharp knife to make 5 or 6 diagonal scores on the skin of the breast. Don''t pierce the flesh and don''t cut all the way to the edge of the skin (Note 2). Pat the skin dry with paper towels, sprinkle with remaining salt and pepper.","images":[],"step":2},{"title":"Cold pan, no oil","description":"Don''t turn the stove on yet. Use an oven-proof pan (any type). Place the duck skin side down in the cold pan, no oil required. Place another pan on top to lightly weigh the duck down (keeps skin flat). (Note 3)","images":[],"step":3},{"title":"Cook 10 minutes","description":"Turn the stove onto medium low. Cook for 10 minutes or until the skin is golden and crispy. Fat will melt out of the duck skin and it will cook in its own fat. (Note 4)","duration":10,"images":[],"step":4},{"title":"Oven 8 minutes","description":"Once the skin is crispy, turn and cook the flesh side for 1 minute. Then transfer the pan to the oven for 6 minutes for medium rare (internal temperature 54°C/130°F, restaurant default) or 8 minutes for medium (60°C/140°F, my preferred).","duration":1,"images":[],"step":5},{"title":"Rest","description":"Transfer to a rack or plate and rest for 5 minutes before serving. Serve whole or slice!","duration":5,"images":[],"step":6}]', '[]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["duck"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_68312a6b532d', 'en', 'US', 'Pierogi Ruskies - Polish Dumplings', 'Recipe video above. Pierogi Ruskie''s are Polish dumplings filled with cheesy, creamy mashed potatoes served with an onion butter sauce. They are even more delicious than they sound! Traditionally made with quark which is an European fresh cheese which isn''t easily found in Australia, so I''ve used cheddar because I want this recipe to be as accessible as possible to many people to experience the greatness that is Pieorgis!!! More in Note 2.Excellent weekend project – eat some today and freeze some for later (they cook from frozen). Makes a nice big batch of 30 pierogis. For more dumplings of the world - head here!', 'https://www.recipetineats.com/tachyon/2023/10/Pierogi-ruskies_5.jpg', 45, 40, 115, 30, '[{"id": "ing_flour", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_potato", "quantity": {"value": 500.0, "unit": "bag of 2kg"}}, {"id": "ing_cheddar_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 cups flour (, plain/all-purpose)","1 tsp cooking/kosher salt","50g / 3 tbsp unsalted butter","1/2 cup water","1 large egg (, whisked (55-60g/2oz))"],"purpose":"Pierogi dough:"},{"ingredients":["500g / 1 lb potatoes (, peeled and sliced 1cm / 1/2\" thick (2 medium, Note 1))","1 tbsp cooking/kosher salt ( - for cooking potatoes)","30g / 2 tbsp unsalted butter","1 cup shredded cheddar cheese (, tightly packed cup (Note 2))","1/4 tsp cooking/kosher salt","1/2 tsp black pepper"],"purpose":"Pierogi filling:"},{"ingredients":["30g/ 2 tbsp unsalted butter","1 onion (, finely diced)","1/2 tsp cooking/kosher salt"],"purpose":"Onion Butter:"},{"ingredients":["1 tbsp cooking/kosher salt (- for boiling water)","25g/ 1 1/2 tbsp unsalted butter (, per 8 - 10 pierogis (Note 3))","Sour cream (, for serving)","Parsley or chives (, finely chopped - just a pinch)"],"purpose":"Cooking and serving:"}]', '[{"title":"Boil potatoes","description":"Put potato and 1 tbsp salt in a large saucepan. Add cold tap water so it''s 3cm/1 inch above potatoes. Bring to a boil on high heat then reduce heat to medium high and simmer for 15 minutes or until potatoes are soft.","duration":15,"images":[],"step":1},{"title":"Mash","description":"Drain, then pass the potatoes through a potato ricer into a bowl (or use potato masher)","images":[],"step":2},{"title":"Cheese it","description":"Immediately add butter, cheese, salt and pepper. Mix with a wooden spoon until fully combined.","images":[],"step":3},{"title":"Cool","description":"Spread out ~1cm / 1/2\" thick on a tray. Cover with cling wrap, pressing so it is fully in contact. Cool on the counter (~30 min) then refrigerate until cold (1 hour+).","images":[],"step":4},{"title":"Melt butter","description":"Heat up the water and butter in a small saucepan over medium heat just until butter is melted, do not boil water. (Or do this in the microwave). Turn off heat.","images":[],"step":5},{"title":"Mix dough","description":"Whisk the flour and salt in a mixing bowl. Make a well in the centre and then add the butter water plus egg. Mix to combine into a shaggy dough.","images":[],"step":6},{"title":"Knead","description":"Scrape out onto a lightly floured work surface. Knead for 5 minutes until the dough becomes smooth (Note 3). You could also use your stand mixer.","duration":5,"images":[],"step":7},{"title":"Rest","description":"Wrap with cling wrap and leave on the counter for 30 minutes.","duration":30,"images":[],"step":8},{"description":"Wrapping pierogis:","images":[],"step":9},{"title":"Roll & cut","description":"On a lightly floured surface, roll out the dough to 3mm / 1/8\" thickness. Cut out rounds using a 7.5 cm / 3\" cutter. Do as many as you can, then gather surplus dough into a ball, wrap with cling wrap and set aside for later.","images":[],"step":10},{"title":"Fill & wrap","description":"Place 1 tablespoon of cheesy potato filling in the middle of a round. Dip finger with water and run along edge of half the circle. Fold dough over to enclose the filling and press to seal, making slight indents (no pleats).","images":[],"step":11},{"title":"Wrap remaining","description":"Place them on a lightly floured tray and continue to wrap remaining Pierogi (including rolling out the remaining dough). You should get ~30 pierogis.","images":[],"step":12},{"description":"Onion butter sauce:","images":[],"step":13},{"description":"In a non stick skillet, melt the butter until foamy over medium heat. Add onion and salt, then cook, stirring regularly, for 10 to 15 minutes until golden on the edges. Scrape out into a bowl, then set aside (OK to cool).","duration":12.5,"images":[],"step":14},{"description":"Cooking & serving pierogis:","images":[],"step":15},{"title":"Batch cooking","description":"Directions below are for cooking and serving 10. Boil pierogis in batches of 10 to 12 max, they need space to bounce around in the water, and you need space to toss them in the butter. (Note 4 for big batch cooking)","images":[],"step":16},{"title":"Boil 5 minutes","description":"Bring ~3 litres/quarts of water to the boil with 1 tbsp salt. Lower 10 piergosi into the water. Cook for 5 minutes - they should be floating on the surface.","duration":5,"images":[],"step":17},{"title":"Reserve water & drain","description":"Dip a jug into the water and scoop out ~1 cup water. Then use a slotted spoon to transfer pierogi into a bowl (or drain, if not cooking more).","images":[],"step":18},{"title":"Butter sauce","description":"Melt butter in a large skillet over medium heat. Add 1/3 of the onion butter plus the cooked pierogis with 2 tablespoons of the reserved cooking water. Toss for 1 minute, still on the stove, until the pierogis are coated in the butter. (Note 4 on scaling up)","duration":1,"images":[],"step":19},{"title":"Serve","description":"Slide onto a serving plate, scraping out every drop of butter. Sprinkle with parsley, add a dollop of sour cream. Eat and be happy!","images":[],"step":20}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["European","polish"],"categories":["dumplings","iconic-dishes","potato-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_878bc7d71be6', 'en', 'US', 'Malfatti (Italian Spinach Ricotta Dumplings in Napoli Sauce)', 'Recipe video above. Malfatti means “badly formed” in Italian. These irregular spinach ricotta gnocchi-like dumplings may look a bit wonky, but they taste incredible!Like gnudi except with the addition of spinach, this traditional Italian dish can be served straight after boiling them. But it''s really worth a quick 15 minute bake to get a light golden crust on the Malfatti as well as caramelisation on the edges of the Napoli sauce. It really takes it in a deliciously different direction!Servings: This will serve 4 very hungry people, or 5 standard servings.', 'https://www.recipetineats.com/tachyon/2021/06/Malfatti-Spinach-Ricotta-Dumplings_8.jpg', 25, 45, 70, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 300.0, "unit": "bag of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.5, "unit": "bunch"}}, {"id": "ing_ricotta", "quantity": {"value": 2.0, "unit": "tub of 250g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_parmesan", "quantity": {"value": 0.5, "unit": "pack of 200g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}]', '[{"ingredients":["2 tbsp olive oil","2 garlic cloves (, finely minced)","1/2 onion (, very finely diced)","800g / 24 oz crushed tomato (or diced)","1 tbsp tomato paste","1/2 cup water","1 basil stem (leaves kept for the Malfatti)","1/2 tsp white sugar","3/4 tsp salt","1/2 tsp black pepper"],"purpose":"Napoli Sauce:"},{"ingredients":["300g / 10oz baby spinach (~6 tightly packed cups, Note 4)","1/2 tsp salt"],"purpose":"Spinach for Malfatti:"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, finely minced)","1 eschallot (large), finely chopped (or 1/2 red onion)","500g / 1 lb ricotta (must be dry type, not wet and spreadable, Note 1)","1/4 cup (lightly packed) basil leaves, finely sliced (use stem for sauce)","1 egg (Note 2)","1 egg yolk (Note 2)","1 cup parmesan (, finely grated)","1/2 cup flour (, plain / all-purpose)","1/2 tsp salt","1/2 tsp black pepper"],"purpose":"Malfatti:"},{"ingredients":["1/4 cup parmesan (, finely grated)","Basil leaves (, small (optional))"],"purpose":"Serving:"}]', '[{"title":"Saute garlic and onion","description":"Heat oil in a small pot or large skillet over medium heat. Add garlic and onion and cook for 3 minutes until onion is softened.","duration":3,"images":[],"step":1},{"title":"Simmer sauce","description":"Add remaining ingredients plus the stem of basil. Bring to a simmer, then reduce stove to low and cook, stirring every now and then, for 20 minutes. It should be fairly thick rather than a loose runny sauce.","duration":20,"images":[],"step":2},{"title":"Drain ricotta, if needed","description":"The ricotta should be the dry and fairly crumbly type rather than wet, soft and almost spreadable. If it''s wet, see Note 1 for removing excess water (wet ricotta makes Malfatti hard to shape and cook!)","images":[],"step":3},{"title":"Sweat spinach","description":"Toss spinach with 1/2 tsp salt in large colander. Leave for 20 minutes. Roll up in tea towel and squeeze tightly to remove excess liquid. Roughly chop.","duration":20,"images":[],"step":4},{"title":"Sauté garlic, eschalot and spinach","description":"Heat oil in a skillet over medium high heat. Add garlic and eschalot, cook for 1 minute until translucent. Add spinach and cook until just wilted. Transfer to large bowl, allow to cool.","duration":1,"images":[],"step":5},{"title":"Malfatti mixture","description":"Add ricotta and all remaining Malfatti ingredients into the bowl. Mix well to combine. It should be too wet to roll with hands without sticking, but still firm enough to shape into dumplings.","images":[],"step":6},{"title":"Form dumplings","description":"Using 2 dessert spoons, scoop up about 1 1/2 tablespoons of mixture then shape into a football (quenelle) using the two spoons. Place on a paper-lined tray. You should get about 24-30.","images":[],"step":7},{"title":"Boil dumplings","description":"Bring a large pot of water to the boil, then carefully put 6 dumplings in. Cook for 2 minutes, they should float to the surface. Remove with slotted spoon on to paper towel lined tray. Repeat for remaining Malfatti.","duration":2,"images":[],"step":8},{"description":"Preheat oven to 180°C / 350°F.","images":[],"step":9},{"title":"Assemble","description":"Pour Napoli Sauce into a baking dish, then top with Malfatti. Drizzle with extra virgin olive oil.","images":[],"step":10},{"description":"Bake 15 minutes or until the Malfatti has a faint blush of gold on the surface (Note 3).","images":[],"step":11},{"description":"Serve! Sprinkle baked Malfatti with parmesan and basil leaves (tear large leaves). Spoon into bowls and served as-is. No starchy side is required, think of these as like gnocchi. Just add a leafy green salad with Italian Dressing or Balsamic Dressing!","images":[],"step":12}]', '["egg","gluten","milk"]', '["high_protein","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["dumplings","italian-recipes","pasta-bakes","pasta-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5b79b5f1ce7c', 'en', 'US', 'French Fish Pie', 'Recipe video above. This is a homestyle fish pie I like to make for Easter, one of my mother used to make for us. Chunks of white fish fillets slowly poached in creamy béchamel with fennel, leek and fresh dill then topped with mashed potato and baked until golden. Don''t be surprised that it doesn’t call for a homemade fish stock, you’ll still get plenty of flavour from the fish itself and the fresh herbs.', 'https://www.recipetineats.com/tachyon/2026/03/French-Fish-Pie_3.jpg', 30, 60, 100, 6, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_fennel", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_eek_halved_lengthwise_then_cut_into_2cm_0_8_pieces", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_milk", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_dill", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}]', '[{"ingredients":["1 leek (, (white and pale green parts only), halved lengthwise, then cut into 2cm / 0.8\" pieces)","1/2 tsp cooking salt / kosher salt (half for table salt, +50% for flakes)"]},{"ingredients":["1 tbsp extra virgin olive oil","2 tbsp (30g) unsalted butter","1 brown / yellow onion (, diced 0.6cm / 0.2\")","1/2 fennel (stalks cut off) (, diced 0.6cm / 0.2\" (Note 2))","1 leek (, (white and pale green parts only), halved lengthwise, then cut into 2cm / 0.8\" pieces)","3 garlic cloves (, finely minced)","1/2 cup plain flour / all-purpose flour (, (Note 3))","1/2 cup dry white wine (, any type (Note 4))","1 1/2 cups HOT milk, full fat preferred (, but works with lite milk too)","1 cup HOT thickened cream / heavy cream","1 tbsp fresh dill (, finely chopped (substitute with parsley or 1/2 tbsp tarragon))","3/4 tsp cooking salt / kosher salt (, half for table salt)","1/4 tsp black pepper"],"purpose":"Fish pie sauce"},{"ingredients":["1kg / 2lbs starchy potatoes","2 tbsp (30g) unsalted butter (, cold, cut in small cubes)","1/3 cup hot milk, full fat preferred (, but works with lite milk too)","3/4 tsp cooking salt / kosher salt (, half for table salt)","1/8 tsp ground white pepper (, or black pepper)","olive oil spray (optional)"],"purpose":"Mash potato topping"}]', '[{"description":"Sauté onion, fennel, leek and garlic, add flour, wine, milk, cream, salt and pepper to make the sauce, stir in dill and add fish. Pipe on mashed potato. Spray olive oil. Bake for 35 minutes until golden. Rest 5 minutes, then serve.","duration":35,"images":[],"step":1},{"description":"First place potatoes in a large saucepan, cover with cold water. Bring to a boil, then simmer 25 minutes until very soft. You can start making the sauce while the potatoes are cooking.","images":[],"step":2},{"description":"Preheat oven to 200°C / 390°F (180°C fan). I highly recommend placing a baking tray lined with foil at the bottom of your oven to catch any bubbling filling that may leak during baking. Easier to clean!","images":[],"step":3},{"title":"Season fish","description":"Pat fish pieces dry with paper towels and sprinkle all sides with salt. Set aside.","images":[],"step":4},{"title":"Sauté vegetables","description":"Heat oil and butter in a 26cm / 10\" cast-iron skillet over medium-high heat. Add onion, fennel, leek and garlic. Cook 5 minutes until softened and light golden. Stirring regularly. (Note 5)","images":[],"step":5},{"title":"Make sauce","description":"Add flour, stir for 30 seconds. Pour in white wine. It will simmer rapidly at first, then mix it in, it will look pasty. Slowly pour in the HOT milk and cream while stirring. Add salt and pepper. Bring to a simmer, cook 1 minute until thickened. The sauce should be quite thick, fully coating the back of the spoon then gently run down it. Set aside.","duration":0.5,"images":[],"step":6},{"title":"Finish mashed potato","description":"(see instructions below).","images":[],"step":7},{"title":"Finish filling","description":"Stir in dill. Add the fish pieces to the sauce, gently nestling them in so they’re mostly submerged. Then, using a spatula, carefully stir and move them around just enough to coat them in the sauce. Smooth the surface.","images":[],"step":8},{"title":"Potato topping","description":"Pipe mounds of mashed potato swirls on the surface. My swirls have a 4.5cm base (1.6\"), about 4cm tall (1.4\"), then I fill gaps with small swirls/blobs. Make sure to use all the mash! Spray lightly with olive oil. (Note 6)","images":[],"step":9},{"title":"Bake","description":"Bake 35 minutes, rotating halfway, until golden on top. If it''s not golden enough, place it under the grill for a few minutes.","images":[],"step":10},{"title":"Serve","description":"Rest for 10 minutes before serving to cool slightly and let the sauce thicken a bit more.","duration":10,"images":[],"step":11},{"title":"Finish mash","description":"Drain well. Pass through a potato ricer or return to the pot and mash well with a potato masher. Do not use a stick blender, it will overwork the starch, turning the mash gluey instead of fluffy. Add butter, salt and white pepper, stir until combined then add hot milk. Stir until smooth. It should be creamy but not loose (so it holds its shape when piped).","images":[],"step":12},{"title":"Piping bag","description":"Transfer into a piping bag fitted with a star tip. (Note 7)","images":[],"step":13}]', '["fish","gluten","milk"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["French","Western"],"categories":["easter-mains-fish-seafood","easter-recipes","fish-recipes","jbs-recipes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c20b75a13838', 'en', 'US', 'Slow-roast Easter stuffed lamb', 'Recipe video above. Make this to impress! Lamb shoulder slow-cooked until fork-tender but still slices like a dream to show off that herby, nutty stuffing, a stunner with the rich lamb meat. You''ll love the impressive stuffing-to-meat ratio, confit-style melting potatoes, and lush gravy. PS. Yes the rolling/tying part can be fiddly if you''re new to it. But don''t be intimidated, watch the video and look at the step photos, it''s infinitely doable even for first timers. And don’t worry if your lamb comes out a little rustic - eg wonky, or filling burstage. Once it’s on the platter, no one will notice, but the flavour will be all there!Recipe credit: Our very own Chef JB!', 'https://www.recipetineats.com/tachyon/2025/04/Easter-stuffed-lamb-shoot-2_2.jpg', 40, 180, 400, 5, '[{"id": "ing_lamb", "quantity": {"value": 1.35, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_eschalots", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_skinless_hazelnuts", "quantity": {"value": 45.0, "unit": "jar"}}, {"id": "ing_pistachios", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_parsley", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.005, "unit": "bottle of 250ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_rosemary", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_saut_ed_green_beans", "quantity": {"value": 1.0, "unit": "pack"}}]', '[{"ingredients":["1.35 - 1.5 kg/ 2.7 - 3 lb deboned lamb shoulder (Note 1)","1 1/2 tsp cooking salt / kosher salt (, divided)","1 tsp black pepper (, divided)","2 tsp extra virgin olive oil"]},{"ingredients":["1 tbsp / 20g unsalted butter","2 eschalots (, finely diced (US: shallots, sub 1 small onion) (Note 2))","3 garlic cloves (, finely minced)","300g/ 10 oz mushrooms (, button/white (Note 3))","2 tightly packed cups baby spinach (, roughly chopped 100g)","3 tbsp skinless hazelnuts (Note 4)","3 tbsp pistachios (, roughly chopped (Note 4))","1 1/2 tbsp parsley (, finely chopped (ok to omit))","1 1/2 tsp rosemary (, fresh, finely chopped (sub fresh thyme, or 1 tsp dried))","1 tbsp lemon zest (divine touch, don''t skip this!)","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"The fabulous herb & nut stuffing:"},{"ingredients":["1 kg/ 2 lb baby potatoes (, cut in half (4 if large) (Note 5))","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper","1 tbsp extra virgin olive oil"],"purpose":"Melting potatoes:"},{"ingredients":["2 tbsp flour (plain / all-purpose)","1 1/4 cups beef stock/broth (, low sodium)","1/4 tsp dark soy sauce (optional, for deeper colour) (Note 6)","Salt and pepper (, if needed (I don''t add any more))"],"purpose":"Gravy:"},{"ingredients":["1 tbsp pistachios (, roughly chopped (optional garnish))","Rosemary sprigs (, optional garnish)","Sautéed green beans (pictured - vegetable side, splash of colour)"],"purpose":"Serving:"}]', '[{"title":"Roast hazelnuts","description":"Preheat oven to 180°C/350°F (160°C fan-forced). Roast the hazelnuts for 8 minutes. Cool, then roughly chop.","duration":8,"images":[],"step":1},{"description":"Blitz the mushrooms in a food processor, scraping down the sides as needed, until the mushrooms are chopped into little 3mm/0.1\" pieces.","images":[],"step":2},{"title":"Duxelle","description":"Melt the butter in a non-stick pan over high heat. Add eschalots, garlic and mushrooms. Cook, stirring regularly, for 5 minutes or until the liquid that comes out of the mushrooms mostly evaporates. Add spinach and cook until wilted.","duration":5,"images":[],"step":3},{"title":"Cool","description":"Transfer the filling into a bowl. Cool for 20 minutes then stir in remaining ingredients.","duration":20,"images":[],"step":4},{"title":"Stuffing log","description":"Pile the stuffing on a piece of cling wrap. Use your hands to roughly shape it into a 35cm / 13.5\" long log. Tightly roll up with cling wrap. Place in the freezer for 3 hours (up to 3 days) until it is firm. (Note 7)","images":[],"step":5},{"description":"Pound and roll lamb:","images":[],"step":6},{"title":"Pound","description":"Place the lamb shoulder fat-side down. Cover with plastic wrap (I use go between) or baking paper. Then use a rolling pin or meat mallet to pound the meat (hard!) into a 40 x 22cm rectangle (15.5 x 8.5\"). Aim for even thickness ~1.75cm (2/3\"). Trim and patch as needed to make your rectangle - see video, I cut & rearrange 2 large flappy bits that stick out.","images":[],"step":7},{"title":"Roll","description":"Sprinkle the surface of the lamb with half the salt and pepper. Unwrap the frozen stuffing log then roll it up tightly, finishing with the seam side down.","images":[],"step":8},{"title":"Tie","description":"Secure with kitchen twine tied every 2cm / 0.8\". (See video for tips)","images":[],"step":9},{"description":"Preheat oven to 220°C/425°F (200°C fan-forced).","images":[],"step":10},{"title":"Season","description":"Rub the lamb roll all over with the olive oil, then sprinkle with the remaining salt and pepper.","images":[],"step":11},{"title":"Potatoes","description":"Toss the potatoes with the salt, pepper and olive oil in a large roasting pan (not a baking tray). Put the lamb on top of the potato, on the diagonal if needed to fit.","images":[],"step":12},{"title":"Short high temp roast","description":"Roast for 30 minutes (renders some fat and gives the colour a head start).","duration":30,"images":[],"step":13},{"title":"Slow roast","description":"Turn the oven down to 160°C/320°F (140°C fan). Cook for 2 1/2 hours, or until the internal temperature is 98°C/208°F or the meat can be fairly easily teased apart using two fork (check in a discreet spot).","images":[],"step":14},{"title":"Rest","description":"Remove lamb and potato to a tray and loosely cover with foil while you make the gravy.","images":[],"step":15},{"title":"Drippings","description":"The roasting pan will have meat juices and fat. Tilt the pan so you can scoop off and discard all but 3 tablespoons of fat (the clear liquid that rises to the surface). Make sure you keep the dark brown juices in the pan. If you''re short of fat, add butter.","images":[],"step":16},{"title":"Heat fat","description":"Put the pan directly on the stove over medium heat. Once the fat is hot, sprinkle the flour over and stir for 1 minute.","duration":1,"images":[],"step":17},{"title":"Thicken","description":"While stirring, slowly pour in the stock. Add soy sauce, then keep stirring as it bubbles gently until it thickens into a maple syrup consistency.","images":[],"step":18},{"description":"Taste and add more salt and pepper if desired (I don''t need more). Pour into a jug (strain, if needed).","images":[],"step":19},{"description":"Cut the string off the lamb then slice into 2cm / 0.8\" thick slices.","images":[],"step":20},{"description":"Plate on a platter, surround with the potatoes. Serve with gravy, sprinkled with extra chopped pistachios if desired! (Shown in the video with sautéed green beans).","images":[],"step":21}]', '["gluten","milk","soy"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["easter-mains","easter-recipes","easter-sides-warm-hearty","lamb","lamb-recipes","mains","roast-lamb"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_74a959c34823', 'en', 'US', 'Ultimate slow-roasted lamb: 12-hour Lamb Shoulder', 'Recipe video above. A 3-hour lamb shoulder is great. A 12-hour lamb shoulder is better! The meat is even more succulent because a lower cooking temperature means less moisture loss, and better flavour infusion from the rub. The sauce is a Lamb Jus made using the braising juices so it has phenomenal flavour. Don''t be intimidated, it''s simple and no more difficult to make than gravy!This is an excellent make-ahead recipe for gatherings. Why? Because you can make up to 4 shoulders in one standard oven. And the room for error is also almost nil; it''s almost entirely hands-off cooking that magically takes care of itself overnight. Most importantly, the meat is so juicy it reheats 100% perfectly. I cook it overnight and reheat to serve that evening.About scaling up: 2 shoulders can be cooked in one large pan with no change to cook time. 4 shoulders (2 lambs in 2 pans, on 2 shelves) takes about 14 to 15 hours.', 'https://www.recipetineats.com/tachyon/2021/10/12-Hour-Greek-Slow-Roasted-Lamb-Shoulder_4.jpg', 10, 780, 790, 5, '[{"id": "ing_lamb", "quantity": {"value": 1.6, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_rosemary", "quantity": {"value": 0.25, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.013, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}]', '[{"ingredients":["1.6 - 2.2kg / 3.2 - 4.4lb lamb shoulder (, bone-in (Note 1))","2 cups water (Note 2)","1 brown onion (unpeeled), cut into 6 wedges (Note 3)"]},{"ingredients":["2 1/2 tsp fresh rosemary (, chopped (finely))","1 tbsp dried oregano","2 garlic cloves (big!) (, finely chopped)","1 tsp salt (, kosher or cooking salt (or 3/4 tsp table salt))","1/2 tsp black pepper","1/4 cup extra virgin olive oil"],"purpose":"Marinade"},{"ingredients":["1 tsp cornflour / cornstarch","1/4 cup water","1/4 tsp salt"],"purpose":"Jus, for serving"}]', '[{"description":"Preheat oven to 230°C / 450°F (210°C fan).","images":[],"step":1},{"title":"Marinade/rub","description":"Mix the Marinade ingredients in a small bowl. Rub all over the lamb surface, getting it right into all the cracks and crevices!","images":[],"step":2},{"title":"Marinate 2","description":"24 hrs: If time permits, marinate for 2 hours on the counter in a roasting pan, or up to 24 hours in the fridge. I skip this step more often than not, however. (Note 4)","images":[],"step":3},{"title":"Prepare roasting pan","description":"Scatter onion in the base of the roasting pan. Place lamb shoulder on top . Pour water into pan.","images":[],"step":4},{"description":"Roast uncovered for 45 minutes.","duration":45,"images":[],"step":5},{"title":"Slow-roast 12 hours","description":"Turn oven down to 100°C/210°F (both fan and standard, Note 5). Cover lamb with baking paper, then a double layer of foil and seal very tightly to avoid water evaporation. Roast for 12 hours (I always do overnight!).","images":[],"step":6},{"title":"Check meat","description":"Test side of lamb with two forks. The meat should be fall-apart tender. If not, cover and return to oven.","images":[],"step":7},{"title":"Remove lamb","description":"There will (should!) be a lot of liquid pooled under the lamb in the roasting pan. Remove lamb to a large dish. Cover loosely with foil to keep warm. It will stay warm for 2 to 3 hours. See Note for reheating / making ahead.","images":[],"step":8},{"title":"Reduce liquid","description":"Strain all the liquid in the roasting pan into a saucepan (Note 2). Bring to a boil then simmer rapidly on medium-high until it reduces down to 1 cup (250ml).","images":[],"step":9},{"title":"Thicken","description":"Mix cornflour with water. Pour into jus in a thin stream while stirring continuously. Continue to cook for a minute or two over medium heat, stirring every now and then, until it thickens to a syrup consistency. Add salt and pepper to taste.","images":[],"step":10},{"description":"Serve:","images":[],"step":11},{"description":"Serve Slow Roasted Lamb with Jus. Use tongs for tearing meat off - no knife for carving needed! Pictured in post with Greek Lemon Roasted Potatoes, a perfect match for this Greek-ish flavoured lamb. Roasted Vegetables would also be ideal.","images":[],"step":12}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Australian","Western"],"categories":["easter-mains","easter-recipes","iconic-dishes","lamb","lamb-recipes","mains","roast-lamb","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_74648aa2183d', 'en', 'US', 'Rack of Lamb with Rosemary Garlic Marinade (Oven Roasted)', 'Recipe video above. Here is a wonderful, classic way to cook a rack of lamb that makes the most of this premium cut of meat! Infused with the flavours of rosemary and garlic from a marinade, then roasted to perfection, it''s served with Salsa Verde for a deliciously fresh accompaniment that plays beautifully against the rich lamb.Allow 3 to 4 cutlets per person.', 'https://www.recipetineats.com/tachyon/2021/03/Lamb-Rack-Main.jpg', 10, 25, 35, 4, '[{"id": "ing_lamb", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_quantity_salsa_verde", "quantity": {"value": 1.0, "unit": "bottle"}}]', '[{"ingredients":["2 x 800g / 1.3lb racks of lamb (, frenched (Note 1))"]},{"ingredients":["4 garlic cloves (, minced)","1 tbsp fresh rosemary (, finely chopped)","4 tbsp extra virgin olive oil","1/2 tsp salt (, cooking/kosher salt)","1/4 tsp black pepper"],"purpose":"Marinade:"},{"ingredients":["2 tbsp olive oil - for searing (1 tbsp each rack)"],"purpose":"Cooking:"},{"ingredients":["30g / 2 tbsp butter (, cut into 1cm / ½\" cubes)","2 garlic cloves (, smashed (use side of knife))","1 sprig rosemary"],"purpose":"Basting finish:"},{"ingredients":["1 quantity Salsa Verde (see separate recipe)"],"purpose":"Serving:"}]', '[{"title":"Marinate lamb","description":"Mix marinade ingredients in a ziplock bag (Note 2). Place lamb in bag, massage to coat, then seal and marinate for at least 24 hours and up to 48 hours.","images":[],"step":1},{"description":"Remove lamb from fridge 1 hour prior to cooking, to ensure even cooking.","images":[],"step":2},{"title":"Wrap bones in foil (optional)","description":"Wrap each bone with a small piece of foil. This keeps the bones white and looks prettier.","images":[],"step":3},{"title":"Preheat oven","description":"Preheat oven to 200°C/390°F (180°C fan).","images":[],"step":4},{"title":"Sear","description":"Heat 1 tbsp oil in a cast iron skillet (or other oven-proof, heavy-based skillet) over high heat. Sear one lamb rack on all sides until golden brown, including the ends. Remove and repeat with other lamb rack.","images":[],"step":5},{"title":"Roast","description":"Place both racks in the skillet and roast for 15 minutes, or until the internal temperature is 57°C/135°F (for medium-rare). Remove pan from oven.","duration":15,"images":[],"step":6},{"title":"Baste","description":"Add butter, smashed garlic and rosemary to pan. The residual heat of the pan will melt the butter. Spoon the butter over the lamb continuously for 30 seconds.","duration":0.5,"images":[],"step":7},{"title":"Rest","description":"Remove lamb from skillet and place on a rack set over a tray. Pour butter remaining in the skillet over lamb. Cover loosely with foil and rest for 5 minutes.","duration":5,"images":[],"step":8},{"description":"Carve and serve! Cut lamb into individual cutlets or several cutlets per slice. Serve with Salsa Verde!","images":[],"step":9},{"title":"Sides","description":"Pictured in post with a Spring Salad and individual Mini Potato Gratin Stacks.","images":[],"step":10}]', '["milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["easter-mains","easter-recipes","easter-sides-warm-hearty","lamb-recipes","roast-lamb","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_498329e6e8d1', 'en', 'US', 'Pork Roast with Crispy Pork Crackling', 'Recipe video above. This is how to make a pork roast with tender juicy flesh, with a crazy-crispy crackling! The crackle is bubbly and puffy from edge to edge as it should be, rather than an impenetratable rock hard flat sheet of skin or worse still, littered with rubbery patches.And the gravy is to die for, thanks to the flavour loaded roasting pan juices!KEY STEPS: Use pork shoulder, dry skin, no need to score (but if it''s already scored, that''s ok), salt the skin evenly, slow roast low uncovered, keep the skin surface level using foil balls, and blast it for crispy skin! Read the post for extra tips, step photos, and why this recipe works!', 'https://www.recipetineats.com/tachyon/2018/04/Pork-Roast-Crispy-Crackling_0.jpg', 15, 200, 215, 10, '[{"id": "ing_pork_shoulder", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.125, "unit": "jar of 50g"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_cider", "quantity": {"value": 1.515, "unit": "bottle of 330ml"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.125, "unit": "jar of 50g"}}]', '[{"ingredients":["3 kg/ 6 lb boneless skin on pork shoulder, NOT scored (, unrolled / netting removed (Note 1 & 6))","3 tsp cooking / kosher salt (NOT salt flakes or table salt, Note 7)","1 1/4 tsp black pepper","2 tsp fennel seeds (or other herb/spice of choice)","1 tbsp+ 1 tsp olive oil","1 garlic bulb (, halved horizontally)","2 onions (, halved (brown, white, red))","2 cups dry white wine, or alcoholic or non-alcoholic cider (Note 2)"]},{"ingredients":["1/4 cup flour (Note 5)","2 cups chicken broth/stock (, low sodium)","Salt and pepper"],"purpose":"Gravy:"}]', '[{"title":"Dry skin","description":"Pat the skin dry with paper towels. If time permits, leave in the fridge uncovered overnight (even 1 hr helps). If not, pat extra well.","images":[],"step":1},{"description":"Preheat oven to 220°C/430°F (200°C fan).","images":[],"step":2},{"title":"Season flesh","description":"Sprinkle pork flesh with 1 1/2 tsp salt, all the pepper and all fennel seeds and 1 tbsp olive oil. Rub into flesh, right into all the crevices and cracks.","images":[],"step":3},{"title":"Salt skin","description":"Flip pork, drizzle skin with 1 tsp oil, then rub all over with fingers. Sprinkle all over with remaining 1 1/2 tsp salt, taking care to get even coverage. Un-salted patches will not become bubbly crackling, it will be a hard flat sheet.","images":[],"step":4},{"title":"Garlic & onion bed","description":"Place halved garlic bulbs and onion in roasting pan. Place pork skin side up on top of them.","images":[],"step":5},{"title":"Wine","description":"Carefully pour wine into the pan, being sure not to wet the skin. Transfer to oven.","images":[],"step":6},{"title":"Lower oven","description":"Immediately turn oven down to 160°C/320°F (140°C fan).","images":[],"step":7},{"title":"Slow roast","description":"Roast for 2 1/2 hours.","images":[],"step":8},{"title":"Level at 1 1/2 hours","description":"Check pork after 1 1/2 hours to see if the pork is warped and the skin''s overall surface is significantly unlevelled. If so, adjust to make the skin surface as level as possible using balls of foil and moving large dislodged pork pieces to the side (key tip for crispy crackling, Note 3). Then return to oven for the remaining 1 hour.","images":[],"step":9},{"title":"Check pan & salt on skin","description":"If pan is drying out, add some water. If there are bald patches on the skin without salt (eg it fell off), spray lightly with oil spray (or brush lightly with oil) then sprinkle with salt. (Remember, salt = bubbly skin!)","images":[],"step":10},{"title":"Increase heat","description":"Turn oven up to 250°C/485°F (all oven types), or as high as it will go if your oven won''t go this high.","images":[],"step":11},{"title":"Make skin crisp","description":"Return pork to oven for 30 minutes, rotating pan as needed, until skin is crisp and bubbly all over. If needed, use foil patches, secured with water soaked toothpicks, to cover parts that are done and keep crisping up remaining patches.","duration":30,"images":[],"step":12},{"title":"Rest","description":"Transfer pork to serving platter, tent loosely with foil (don''t worry, crackling stays super-crisp) and rest for 20 minutes (stays warm up to 1 hour). Then slice using a serrated knife.","duration":20,"images":[],"step":13},{"title":"Serve with gravy. Don''t pour gravy over crackling","description":"pour it off to the side! See note for reheating.","images":[],"step":14},{"title":"Transfer fat to saucepan","description":"Skim off 3 tablespoons of fat from the roasting pan and put in a saucepan.","images":[],"step":15},{"title":"Strain pan juices","description":"Place strainer over bowl and scrape in all the remaining pan juices (including onion and garlic). Press out juices, then discard onion & garlic. Skim off excess fat from surface and discard - no need to be exact here!","images":[],"step":16},{"title":"Gravy roux","description":"Heat the saucepan with the fat over medium heat. Add flour and cook for 1 minute.","duration":1,"images":[],"step":17},{"title":"Add liquids","description":"Pour stock in while whisking so it''s lump free. Then pour in strained pan juies.","images":[],"step":18},{"title":"Thicken","description":"Simmer until thickened to syrup consistency - about 3 minutes - it will thicken more as it cools a little while serving. (Note 4 for colour tip)","images":[],"step":19},{"title":"Season","description":"Adjust salt and pepper to taste. Pour into serving jug. Serve with pork.","images":[],"step":20}]', '["gluten"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["easter-mains","easter-recipes","iconic-dishes","main-dishes","pork-recipes","roasts","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_49924032080d', 'en', 'US', 'Rosemary Crumbed Rack of Lamb', 'Recipe video above. This is a recipe that really makes the most lamb racks which are a pricey cut of meat! Adding a crunchy rosemary-garlic crumb not only adds extra flavour but is also a great textural contrast to the soft and tender lamb meat. To stop the crumb falling off lamb racks, just add a touch of egg into the mustard spread. Egg is after all the ultimate natural food glue!Serve straight up (lamb cutlets are sooo juicy and tender, most people think no sauce is necessary!), with a Creamy White Wine & Mustard Sauce or else a Pea Puree (great colour and is as good as a sauce).', 'https://www.recipetineats.com/tachyon/2020/12/Crumbed-rack-of-lamb_5.jpg', 20, 45, 65, 3, '[{"id": "ing_lamb", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 1.25, "unit": "carton of 12"}}, {"id": "ing_mustard", "quantity": {"value": 0.225, "unit": "jar of 200g"}}, {"id": "ing_rosemary", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.15, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_wine", "quantity": {"value": 0.333, "unit": "bottle of 750ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}]', '[{"ingredients":["1 rack of lamb (6 to 9 bones) (, your choice Frenched or not (Note 1))","1 1/4 tsp salt","3/4 tsp black pepper","2 tbsp olive oil"]},{"ingredients":["3 tsp egg (, lightly whisked (Note 2))","3 tbsp Dijon mustard","1 tbsp fresh rosemary leaves (, finely chopped)","1 small garlic clove (, minced)"],"purpose":"Dijon Mustard “Glue”:"},{"ingredients":["1 cup Panko breadcrumbs (Note 3)","2 tbsp parmesan (, finely grated)","1 garlic clove (, finely minced (knife, not garlic press))","1/4 tsp each salt and pepper","2 tbsp fresh rosemary leaves (, finely chopped)","30g / 2 tbsp butter (, melted)"],"purpose":"Garlic Parmesan Crumb:"},{"ingredients":["1 cup dry white wine (sauvignon blanc, pinto gris, semillon, or any blend)","1 cup chicken stock (, low sodium)","1 cup heavy/thickened cream","1 tbsp dijon mustard","1/8 tsp each salt and pepper"],"purpose":"Creamy White Wine & Mustard Sauce (Optional, Note 5):"}]', '[{"description":"Preheat oven to 200°C/390°F (all oven types). Place shelf in the middle of the oven.","images":[],"step":1},{"title":"Season","description":"Sprinkle lamb rack with salt and pepper.","images":[],"step":2},{"title":"Sear","description":"Heat 1 tbsp oil in a heavy based skillet over high heat. Sear lamb rack all over until nicely browned - including each short end - about 1 1/2 minutes on each side. It will be fully raw inside, but that''s OK. Transfer to plate and let cool for 5 minutes, uncovered.","duration":5,"images":[],"step":3},{"title":"Mustard Spread","description":"Mix dijon, rosemary and garlic in a small bowl. Then add 3 teaspoons of egg, and mix again.","images":[],"step":4},{"title":"Making the crumb","description":"Mix Crumb ingredients EXCEPT butter in a bowl. Then use a fork to stir through butter. Spread on a dinner plate (large enough that fits lamb).","images":[],"step":5},{"title":"Crumbing the lamb","description":"Spread the underside of the rack with mustard mix. Press into breadcrumb mixture, then spread mustard mix over the other side as well as each end. Then press those sides into the breadcrumb mixture.","images":[],"step":6},{"description":"Transfer lamb to rack set on a tray. Surround with parboiled vegetables if using - but don''t crowd the lamb.","images":[],"step":7},{"title":"Roast","description":"Frenched racks for 20 minutes, or untrimmed racks for 30 - 35 minutes, or until internal temperature registers 60°C/140°F (for medium rare).","duration":20,"images":[],"step":8},{"title":"Rest meat","description":"Transfer lamb to a cutting board, loosely cover with foil. (If you roasted veg, leave in tray or pan and keep warm in turned off oven).","images":[],"step":9},{"title":"Carve","description":"Rest 5 minutes then slice carefully using your hands to hold the crumb gently in place where you are cutting using a very sharp knife. If your service allows it, it''s best to cut 2 or 3 bones together (ie. a double/triple cutlet portion), because the crumb stays on better. Slicing single cutlets is super hard (sadly)!","images":[],"step":10},{"description":"Serve as-is (no sauce), with Creamy White Wine & Mustard Sauce, or Pea Puree.","images":[],"step":11},{"description":"Creamy White Wine & Mustard Sauce","images":[],"step":12},{"description":"Boil wine and chicken stock together until reduced by 3/4, then whisk in cream and mustard and simmer for 3 - 5 minutes until thickened. The consistency should be a thin pouring sauce. We don''t want to coat the lamb too thickly as the sauce flavour will be overpowering.","duration":4,"images":[],"step":13}]', '["egg","milk","mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["easter-mains","easter-recipes","lamb-recipes","main-dishes","mains","roast-lamb"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_72ecde8a7363', 'en', 'US', 'Lamb Chops with Rosemary Gravy (Loin chops, forequarter, cutlets)', 'Recipe video above. Rosemary and lamb is a classic combination. So we''re doubling up on rosemary here - marinading with garlic and rosemary first, then smothering in rosemary gravy!', 'https://www.recipetineats.com/tachyon/2020/06/Lamb-Chops-with-Rosemary-Gravy_6-copy.jpg', 10, 15, 25, 4, '[{"id": "ing_lamb", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_rosemary", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["750g/ 1.5lb lamb chops (loin chops, forequarter, cutlets) (Note 1)"]},{"ingredients":["1/4 cup extra virgin olive oil","3 garlic cloves (, finely minced)","1 tbsp rosemary leaves (, finely chopped (Note 2))","1 tsp each salt and pepper"],"purpose":"Lamb Chop Marinade:"},{"ingredients":["2 cups beef stock (, low sodium)","3 tbsp flour (, plain/all purpose (Note 3 for GF))","1 tbsp rosemary leaves (, finely chopped (Note 2))","2 rosemary sprigs (, optional)"],"purpose":"Gravy:"}]', '[{"title":"Marinade","description":"Mix Marinade ingredients together, then pour over chops. Turn to coat and leave to marinade for at least 1 hour, preferably 3 hours or overnight.","images":[],"step":1},{"description":"Cooking:","images":[],"step":2},{"description":"Take lamb out of fridge 30 minutes prior to cooking (to bring to room temp).","images":[],"step":3},{"description":"Heat a large skillet over high heat (no oil needed).","images":[],"step":4},{"description":"Pick up a chop, scrape off excess bits of garlic (it burns) and let excess oil drip off. Place in skillet. Once all chops are in, turn heat down to medium high.","images":[],"step":5},{"description":"Cook times for medium rare (internal temp 62°C/145°F):","images":[],"step":6},{"title":"Loin chops & forequarter chops","description":"4 minutes each side, or until internal temp is 62°C/145°F for medium rare (Note 4 other doneness)","images":[],"step":7},{"title":"Cutlets & thin leg steaks","description":"3 minutes on the first side then 2 minutes on the second side.","images":[],"step":8},{"title":"Rest","description":"Remove lamb from skillet and place on a plater. Loosely cover with foil and rest for 3 minutes while you make the gravy.","duration":3,"images":[],"step":9},{"description":"Pour off all but about 3 tbsp oil (if you''re short, add butter), return skillet to medium heat.","images":[],"step":10},{"description":"Add flour and stir for 30 seconds.","duration":0.5,"images":[],"step":11},{"description":"Pour in beef stock while stirring constantly to dissolve flour mixture in. If you have lumps, use a whisk.","images":[],"step":12},{"description":"Add chopped rosemary and sprig.","images":[],"step":13},{"title":"Simmer, stirring regularly, for 2","description":"3 minutes until it thickens in a gravy consistency.","duration":2.5,"images":[],"step":14},{"description":"Serve lamb chops with gravy over creamy mashed potato and a side of peas!","images":[],"step":15}]', '["gluten"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Australian","Western"],"categories":["easter-mains","easter-recipes","lamb","lamb-recipes","main-dishes","mains","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0aa249fafde6', 'en', 'US', 'Brown Sugar Glazed Ham', 'Recipe video above. It''s truly incredible how such a simple Brown Sugar Ham Glaze can transform into the most incredibly sticky, caramelised ham! See Notes for handy make ahead tips.New to glazed ham? Start here -> How to Make Glazed Ham. Want to try my signature clove studded Maple Glazed Ham? Here it is!', 'https://www.recipetineats.com/tachyon/2018/12/Brown-Sugar-Glazed-Ham_0-SQ.jpg', 15, 90, 105, 20, '[{"id": "ing_ham", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_honey", "quantity": {"value": 0.125, "unit": "jar of 500g"}}, {"id": "ing_mustard", "quantity": {"value": 0.188, "unit": "jar of 200g"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.125, "unit": "bottle of 500ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cinnamon", "quantity": {"value": 3.75, "unit": "jar"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.188, "unit": "jar of 200g"}}, {"id": "ing_ribbon", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_rosemary", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4-6 kg / 8-12 lb bone in ham, rind and fat on (Note 1)","2 cups water (Note 2)"]},{"ingredients":["3/4 cup brown sugar","1/4 cup honey (or maple)","1/4 cup Dijon mustard","1/4 cup apple cider vinegar (Note 3)","1/2 tsp black pepper"],"purpose":"Brown Sugar Ham Glaze:"},{"ingredients":["3/4 tsp cinnamon*","1/2 tsp All Spice*","3/4 tsp mustard powder * (ordinary, not hot)"],"purpose":"Spices (Note 4):"},{"ingredients":["Ribbon","Few sprigs of rosemary (or other herb / leaves)"],"purpose":"Presentation (optional):"}]', '[{"description":"Take ham out of the fridge 1 hour prior.","images":[],"step":1},{"description":"Preheat oven to 160C / 320F (standard) or 140C / 285F (fan). Arrange shelf in lower third so the ham will be sitting in the centre of the oven (not right at the top of the oven, this causes more uneven cooking on surface).","images":[],"step":2},{"description":"Remove rind & scoring:","images":[],"step":3},{"description":"Remove the rind (skin) of the ham, ensuring you leave the fat on (Note 5 for steps, photos in post and video above)","images":[],"step":4},{"title":"Scoring","description":"Cut 2.5cm / 1\" diamonds into the fat (don''t cut into flesh).","images":[],"step":5},{"description":"Brown Sugar Ham Glaze:","images":[],"step":6},{"description":"Place brown sugar, honey, mustard, cider vinegar, pepper and Spices into saucepan over medium high heat. Simmer and stir until sugar is dissolved.","images":[],"step":7},{"description":"Baste & Cook:","images":[],"step":8},{"description":"Place rack in a baking pan and place ham on rack.","images":[],"step":9},{"description":"Baste all over with the glaze (except the handle), including underside and the cut face. Reserve remaining glaze for basting.","images":[],"step":10},{"description":"Bake for 1.5 hours, basting every 20 minutes with reserved glaze (Note 6) and pan juices, until caramelised and the internal temperature is 60C/140F. (Note 7)","images":[],"step":11},{"description":"Stick bits of foil on parts that are browning too quickly, and you can even lower the oven temp. (Note 8)","images":[],"step":12},{"description":"Rest ham for 15 to 30 minutes+, basting generously with the pan drippings - use it like paint to make your ham beautifully bronzed all over with a thick glaze. (Note 9)","duration":22.5,"images":[],"step":13},{"description":"Sauce (Note 10):","images":[],"step":14},{"description":"Whisk water into pan juices until it''s a thick honey-like pouring consistency.","images":[],"step":15},{"description":"Presentation & Serving:","images":[],"step":16},{"description":"Wrap handle with baking paper, secure in place with ribbon. Stick in rosemary sprigs.","images":[],"step":17},{"description":"Place ham on table as centrepiece with Sauce on the side. Lovely served warm or at room temp!","images":[],"step":18},{"description":"Once everyone has oohed and aahed over it, nominate someone to be the Ham Carver! Slice thinly and serve with sauce.","images":[],"step":19},{"title":"Leftovers","description":"See list in post for recipe using leftover ham and ham bone!","images":[],"step":20},{"title":"Storing","description":"Will keep for at least a week in the fridge if properly stored using a water-vinegar soaked ham bag or pillowcase. Otherwise freeze - don''t forget the bone! See How to Store Glazed Ham for directions.","images":[],"step":21}]', '["mustard"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["easter-mains","easter-recipes","iconic-dishes","mains"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_31ccacae3b5c', 'en', 'US', 'Slow Cooker Pork Loin Roast OR Pork Shoulder', 'Recipe video above. Pork loin OR shoulder slow cooked in an incredible Honey Butter sauce! I love the way the pork soaks up the flavour of the sauce - and how it only requires 5 ingredients!', 'https://www.recipetineats.com/tachyon/2018/09/Slow-Cooker-Honey-Garlic-Pork-Roast_9-2.jpg', 10, 600, 610, 8, '[{"id": "ing_pork", "quantity": {"value": 1.75, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_honey", "quantity": {"value": 0.375, "unit": "jar of 500g"}}, {"id": "ing_butter", "quantity": {"value": 125.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_vinegar", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.037, "unit": "pack of 400g"}}]', '[{"ingredients":["1.75 - 2.5 kg / 3.5 - 5lb pork loin OR shoulder/boston butt ( ,or scotch fillet, skinless (Note 1))","1.5 tbsp olive oil (, separated)"]},{"ingredients":["2 tsp EACH paprika, thyme","1 tsp EACH garlic powder, onion powder","1/2 tsp cayenne pepper (, optional)","1/2 tsp pepper","2 tsp salt"],"purpose":"Spice Rub:"},{"ingredients":["3/4 cup honey","125g / 1/2 cup butter (, unsalted)","5 cloves garlic (, minced)","1/4 cup cider vinegar","1/2 tsp salt and pepper (, each)"],"purpose":"Honey Butter Sauce:"},{"ingredients":["3 tsp cornflour/cornstarch mixed with splash of water"],"purpose":"Thickener:"}]', '[{"title":"Spice Rub","description":"Rub pork with about 1 tsp oil. Mix Rub together then sprinkle over pork. Pat to adhere all over.","images":[],"step":1},{"title":"Brown","description":"Heat 1 tbsp oil in a large skillet over medium heat. Add pork and sear all around until deep golden brown (don''t let spices burn). Place pork in slow cooker.","images":[],"step":2},{"title":"Honey Butter Sauce","description":"Wipe pan. Add butter and melt. Add garlic and cook for 1 minute until golden. Add remaining Sauce ingredients, mix, simmer rapidly for 30 seconds.","duration":1,"images":[],"step":3},{"description":"Slow Cook:","images":[],"step":4},{"description":"Pour Sauce over pork. Cover slow cooker.","images":[],"step":5},{"title":"Pork loin","description":"Cook on LOW for 4 to 5 hours (see Note 2 for cook times for different sizes)","images":[],"step":6},{"title":"Pork Shoulder","description":"Cook on LOW for 10 hours (see Note 2 for cook times for different sizes, and Note 4 for oven, InstantPot and pressure cooker methods).","images":[],"step":7},{"description":"Remove pork onto serving platter, cover loosely with foil (10 - 20 minutes rest). (See Note 6 on Doneness)","images":[],"step":8},{"description":"Pour all juices in slow cooker into large saucepan. Add cornflour water mixture, mix.","images":[],"step":9},{"title":"Thicken Sauce","description":"Simmer on medium high for 5 minutes or until it reduces down to a syrupy consistency (Note 3).","duration":5,"images":[],"step":10},{"title":"Slice pork into thick slices (1.5","description":"2 cm / 3/5 - 4/5\" thick). Serve with PLENTY of Honey Butter Sauce!","images":[],"step":11}]', '["fish","milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","easter-mains","easter-recipes","main-dishes","mains","pork","pork-recipes","quick-and-easy","roasts","slow-cooker-recipes","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3e9f49e09873', 'en', 'US', 'Fish Pie', 'Recipe VIDEO above. A grand Fish Pie, fit for a king yet economical to make! Chunks of fish flakes smothered in a creamy white sauce, topped with mashed potato then baked until golden. Use a combination of both smoked and raw unsmoked fish for optimum flavour and texture. Fresh tarragon is also optional - it gives an extra edge to the flavour that people can''t quite put their finger on!', 'https://www.recipetineats.com/tachyon/2018/03/Fish-Pie_2.jpg', 15, 60, 75, 6, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_uncategorized", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_tarragon", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 750.0, "unit": "bag of 2kg"}}, {"id": "ing_milk", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_egg", "quantity": {"value": 4.0, "unit": "carton of 12"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}]', '[{"ingredients":["400 g / 14 oz smoked fish of choice (Note 1)","400 g / 14 oz raw unsmoked fish of choice (, I used Perch (Note 2))","3 cups / 750 ml milk (, low fat or full fat)","1 brown onion (, quartered (Note 3))","4 cloves (, optional (Note 4))"],"purpose":"Fish:"},{"ingredients":["50 g / 3 tbsp unsalted butter","2 garlic cloves (, minced)","1/2 small onion (, finely chopped)","1 small carrot (, finely chopped)","1 small celery stick (, finely chopped)","1/3 cup / 50g plain flour (all purpose flour, Note 11 for GF)","1 tbsp fresh tarragon (, finely chopped (optional))","2 tbsp parsley (, finely chopped)","Salt and pepper"],"purpose":"White Sauce:"},{"ingredients":["750 g / 1.5 lb floury potatoes (, peeled and cut into 2.5cm / 1\" pieces (Note 5))","30 g / 2 tbsp+ unsalted butter","1/2 cup / 125 ml milk, any fat %"],"purpose":"Potato Topping:"},{"ingredients":["1 cup frozen peas","4 hard boiled eggs (, quartered (optional) (Note 6))","30 g / 2 tbsp butter (, melted)","1/4 cup / 15g grated parmesan cheese (, optional)","Finely chopped parsley (, for garnish (optional))"],"purpose":"Pie:"}]', '[{"description":"Push a clove into the skin of each onion. Place in a pot or large skillet, add milk, turn stove onto medium high heat.","images":[],"step":1},{"title":"When milk is barely simmering, add fish","description":"don''t worry if it''s not entirely covered, it can be turned / moved around.","images":[],"step":2},{"description":"Poach fish for 7 minutes, then use a slotted spoon to transfer fish straight into a medium baking dish (Note 8).","duration":7,"images":[],"step":3},{"description":"Flake into chunks using forks. Remove bones if you see any.","images":[],"step":4},{"description":"Use slotted spoon to remove onion and cloves from milk, discard. RESERVE milk.","images":[],"step":5},{"description":"Preheat oven to 180C/350F. Boil water for potatoes.","images":[],"step":6},{"description":"Melt butter in a large, deep skillet or pot over medium high heat. Add onion and garlic, cook for 1 minute. Then add celery and carrot, cook for 5 minutes until carrot is soft.","duration":1,"images":[],"step":7},{"title":"Turn heat down to medium low. Add flour, mix in","description":"it will look gluey.","images":[],"step":8},{"description":"Add half the milk and quickly start mixing. Once incorporated, the mixture will thicken quickly. Add remaining milk and stir. (Video helpful here)","images":[],"step":9},{"description":"Turn heat up to medium and keep stirring until the mixture thickens to the consistency of honey - about 3 minutes. (Note 7)","images":[],"step":10},{"description":"Take it off the heat, stir through tarragon and parsley. Adjust salt and pepper to taste.","images":[],"step":11},{"description":"Scatter top of flaked fish with peas, then pour over the Sauce. GENTLY stir through (don''t want fish to turn into mush!).*","images":[],"step":12},{"description":"Smooth top, then nestle egg in all over the pie.","images":[],"step":13},{"description":"Bring a large pot of water to the boil. Add potatoes and cook for 15 minutes or until soft. (Do this while making the Sauce).","duration":15,"images":[],"step":14},{"description":"Drain potato, add butter, milk, salt and pepper. Mash until creamy - add more milk if required.","images":[],"step":15},{"description":"Immediately dollop then spread onto pie (cold mash = hard to spread).","images":[],"step":16},{"description":"Use fork to draw squiggles on surface (rough surface = better golden bits).","images":[],"step":17},{"description":"Drizzle surface with melted butter, sprinkle with parmesan.","images":[],"step":18},{"description":"Bake for 35 minutes or until top is deep golden.","duration":35,"images":[],"step":19},{"description":"Stand for 5 minutes before serving, garnished with parsley if desired. See notes for reheating and make ahead.","duration":5,"images":[],"step":20}]', '["egg","fish","gluten","milk"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["British","Western"],"categories":["easter-mains","easter-mains-fish-seafood","easter-recipes","fish-recipes","seafood-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a078e9455b91', 'en', 'US', 'Slow Cooker Roast Lamb Leg with Gravy', 'Recipe video above. The easiest, most succulent roast lamb you''ll ever have! This is not the carving sort of lamb, you can just tear the meat off using tongs.', 'https://www.recipetineats.com/tachyon/2017/04/Slow-Cooker-Roast-Lamb-7.jpg', 5, 600, 605, 5, '[{"id": "ing_lamb", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 666.667, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_rosemary", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_braising_liquid_from_slow_cooker", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["2.0 kg / 4 lb lamb leg, bone in (Note 1)","1 tsp salt","black pepper","2 large garlic cloves (, minced)","1 1/2 tsp dried thyme OR rosemary (or 2.5 tsp finely chopped fresh)","1 tbsp olive oil","2 cups / 500ml beef stock (or chicken) (Note 2)","1 sprig rosemary (, optional)"]},{"ingredients":["50 g / 3 tbsp butter","3 tbsp / 40 g flour (any white)","2 cups / 500 ml braising liquid from slow cooker (, strained)","Salt and pepper"],"purpose":"Gravy:"}]', '[{"description":"Place lamb in slow cooker or on work surface. Sprinkle with salt, pepper, thyme or rosemary and garlic. Drizzle over oil, then rub on both sides.","images":[],"step":1},{"description":"Pour beef stock into slow cooker, add sprig of rosemary (if using).","images":[],"step":2},{"description":"SLOW COOK on low for 10 hours, or pressure cook on high for 1 hour 40 minutes. (See oven version here)","images":[],"step":3},{"description":"The lamb should be tender enough to pull off with tongs, but still holding together (just!). Carefully remove lamb from slow cooker and transfer to tray.","images":[],"step":4},{"description":"Drizzle lightly with oil (any). Bake at 200C/390F for 20 minutes or until browned. Remove and rest for 10 minutes before serving with gravy.","duration":20,"images":[],"step":5},{"title":"Strain liquid in slow cooker into a bowl","description":"you will have more than the 2 cups of broth you added, I usually have over 3 cups. Measure out 2 cups of liquid, reserve remaining liquid just in case.","images":[],"step":6},{"description":"Melt butter in a saucepan over medium heat. Add flour and cook for 1 minute.","duration":1,"images":[],"step":7},{"description":"Add a bit of liquid, mixing as you go so it dissolves. Then add remaining liquid. Whisk if there are lumps.","images":[],"step":8},{"description":"Increase to medium high heat and cook, stirring regularly, until thickened to your taste. Use remaining liquid to thin if required.","images":[],"step":9}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["easter-mains","easter-recipes","lamb-recipes","main-dishes","quick-and-easy","roast-lamb","roasts","slow-cooked-fall-apart","slow-cooker-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e9f2798e0ade', 'en', 'US', 'Baked Parmesan Crusted Salmon with Lemon Cream Sauce', 'A simple showstopper salmon recipe! Fantastic centrepiece for a special occasion yet easy enough for midweek. Don''t skip the sauce! It makes all the difference to this dish because the salmon is not marinated. Though made with cream, it is not rich, it''s quite tangy - perfect pairing with rich salmon.', 'https://www.recipetineats.com/tachyon/2016/11/Parmesan-Crusted-Salmon-6.jpg', 10, 30, 40, 6, '[{"id": "ing_salmon_fillets", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_mustard", "quantity": {"value": 3.0, "unit": "jar of 200g"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_dill", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_wine", "quantity": {"value": 0.417, "unit": "bottle of 750ml"}}, {"id": "ing_cream", "quantity": {"value": 1.5, "unit": "carton of 250ml"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}]', '[{"ingredients":["1 (1 - 1.4 kg / 2 - 2.8 lb) side of salmon ( (Note 1))","3- 4 tbsp Dijon mustard"]},{"ingredients":["1 cup panko breadcrumbs (50g) (Note 2)","Oil spray","50g / 3 tbsp butter (, melted)","1/3 cup grated parmesan (, store bought (1/2 cup fresh grated) (Note 3))","2 tbsp finely chopped fresh parsley","2 tbsp finely chopped fresh dill","Zest of 1 lemon","1/2 tsp salt","Pepper"],"purpose":"Parmesan Crumb"},{"ingredients":["30g / 2tbsp butter","1 eschallot / finely chopped (Note 4)","1 1/4 cups dry white wine (Note 5)","1 1/2 cups heavy cream / thickened cream","1 tbsp Dijon mustard","2 1/2 tbsp lemon juice (plus more to taste)","1/2 tsp sugar","Salt and pepper"],"purpose":"Lemon Cream Sauce"},{"ingredients":["Watercress","Lemon wedges","Fresh dill"],"purpose":"Serving"}]', '[{"description":"Take salmon out of the fridge to bring to room temperature.","images":[],"step":1},{"description":"Preheat oven to 200°C / 390°F (180°C fan).","images":[],"step":2},{"description":"Spread panko on baking tray, spray generously with oil then bake for 3 to 5 minutes until light golden brown. (Note 6) Scrape into bowl immediately.","duration":4,"images":[],"step":3},{"description":"Add butter and stir, then add remaining Parmesan Crumb ingredients.","images":[],"step":4},{"description":"Line same tray with foil. Place salmon on foil.","images":[],"step":5},{"description":"Spread Dijon on salmon using a butter knife. Just a thin coating - like buttering toast.","images":[],"step":6},{"description":"Sprinkle Crumb all over.","images":[],"step":7},{"description":"Bake for 20 minutes for just cooked juicy perfection, or to taste. (Note 7)","duration":20,"images":[],"step":8},{"description":"Remove from oven. Loosen salmon from foil using egg flip or butter knife - skin will hopefully be stuck to foil.","images":[],"step":9},{"description":"Plate watercress on serving platter.","images":[],"step":10},{"description":"Use foil to lift salmon onto watercress on serving plate, then slide out the foil from under it (see video under recipe). Serve with Lemon Cream Sauce and lemon wedges on the side.","images":[],"step":11},{"description":"Lemon Cream Sauce","images":[],"step":12},{"description":"Melt butter in a saucepan over medium high heat. Add eschalots and cook for 2 minutes. Add wine and bring to boil. Leave to boil rapidly for 5 minutes or until reduced by 3/4 or so.","duration":2,"images":[],"step":13},{"description":"Turn heat down to medium. Add cream, sugar, salt and pepper. Stir, then add lemon juice and mustard. Stir again. Simmer for 2 to 3 minutes or until thickened (see video). Adjust salt, pepper and lemon to taste. Be generous with the salt - remember the salmon is not marinated, the only salt is in the topping.","duration":2.5,"images":[],"step":14},{"title":"Optional","description":"strain. I don''t bother.","images":[],"step":15},{"description":"Allow to cool for 10 minutes or so. It will thicken as it cools. It can be served warm or at room temperature.","duration":10,"images":[],"step":16}]', '["fish","milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dinner-tonight","easter-mains","easter-mains-fish-seafood","easter-recipes","fish-recipes","iconic-dishes","main-dishes","most-popular","quick-and-easy","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a788c343ff02', 'en', 'US', 'Stovetop Macaroni and Cheese', 'Recipe video above. This classic Macaroni and Cheese just happens to be made in one pot! Though made with the usual ingredients, the sauce is extra silky and glossy, and it clings to the macaroni without having to make make the sauce super thick because the pasta is cooked in the sauce. So there''s no risk of gluggy Mac N Cheese or overcooked pasta.', 'https://www.recipetineats.com/tachyon/2016/11/Mac-and-Cheese-Stovetop_-1.jpg', 3, 15, 18, 5, '[{"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.6, "unit": "pack of 125g"}}, {"id": "ing_cheese", "quantity": {"value": 0.75, "unit": "block of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.013, "unit": "jar of 200g"}}]', '[{"ingredients":["50 g / 3 1/2 tbsp butter","3 tbsp flour","2 cups milk (full fat preferred but low fat is ok)","2 1/2 cups water","250 g / 2 1/2 cups elbow macaroni (, uncooked)","3/4 cup mozzarella cheese (, shredded)","1 1/2 cups cheese (Cheddar, Colby, Gruyere) (, shredded (Note 1))","Salt and pepper"]},{"ingredients":["1 tsp garlic powder","1/2 tsp onion powder","1/2 tsp mustard powder"],"purpose":"Seasonings (optional)"}]', '[{"description":"Melt butter in a medium pot or large saucepan over medium heat. Add flour and cook for 1 minute.","duration":1,"images":[],"step":1},{"description":"Add about 3/4 cup of milk and mix into butter mixture - it will become a slurry pretty quickly.","images":[],"step":2},{"description":"Add remaining milk and mix so the slurry mixes in. Then add water and Seasonings.","images":[],"step":3},{"description":"Add macaroni and mix. Stir occasionally as it comes to heat. When you see wisps of steam as you stir, lower the heat down to medium low.","images":[],"step":4},{"title":"Stir regularly as it cooks for 9","description":"10 minutes (it will bubble gently), or until the sauce thickens and the macaroni is just cooked - tender but still firm. It should still be saucey at this stage and thinner than you want.","duration":9.5,"images":[],"step":5},{"description":"Take it off the stove and stir the cheese in quickly. Adjust salt and pepper to taste. <- In this step, the sauce thickens and reduces considerably.","images":[],"step":6},{"description":"Serve immediately!!","images":[],"step":7}]', '["gluten","milk","mustard"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","easter-recipes","easter-sides-warm-hearty","main-dishes","most-popular","one-pot-pasta-recipes","one-pot-recipes","pasta-recipes","quick-and-easy","side-dishes","vegetarian-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_96589e38feda', 'en', 'US', 'JB''s Cheese Soufflé - Soufflé au Fromage', 'Recipe video above. Cheese Soufflé is a traditional French dish that combines simple pantry staples into something truly special. It rises beautifully in the oven, with a golden top and soft, airy centre. Don’t be intimidated by the name, it’s easier than you think to make it at home. I promise! I still remember my restaurant days, total chaos every time a soufflé came out of the oven. Someone would shout “Soufflé!!” and hope the wait staff appeared instantly, because one thing’s for sure: Soufflé doesn’t wait.', 'https://www.recipetineats.com/tachyon/2025/10/Cheese-souffle_6.jpg', 15, 30, 45, 4, '[{"id": "ing_milk", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 2.0, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_cream", "quantity": {"value": 0.01, "unit": "carton of 250ml"}}]', '[{"ingredients":["2 cups full fat milk (, but works with lite milk too)","75 g (5 tbsp) unsalted butter","1/2 cup plain flour (all-purpose)","1/2 tsp cooking salt / kosher salt (halve for table salt, + 50% for flakes)","2 pinches ground white pepper (substitute black pepper)","150 g (1 1/2 cups) Gruyère cheese (, shredded using a standard box grater (tightly packed if using cups) (Note 2 for other cheeses))","3 egg yolks (from large eggs (55g/2oz each in shell), at room temperature (Note 1))","4 egg whites (from large eggs, at room temperature (total egg whites ~ 120g/4.2oz, Note1))","1/2 tsp cream of tartar (, sifted if lumpy (Note 3))","15 g (1 tbsp) unsalted butter (, melted (to grease the ramekins))"]}]', '[{"description":"Melt butter, cook flour 2 minutes, whisk in warm milk in 3 batches. Add salt and pepper, turn off heat, whisk in yolks one at a time, then melt through gruyere over low heat. Beat egg whites and cream of tartar to firm peaks, starting on medium for 2 minutes, then increasing to high. Whisk 1/4 of the whites into Mornay Sauce, then fold through remainder in 3 batches. Fill butter brushed ramekins to 1cm/0.4” from rim, clean inside of rim. Bake at 200°C/400°F (180°C fan) for 20 minutes. No peeking! Serve immediately.","duration":2,"images":[],"step":1},{"description":"Preheat oven to 200°C / 400°F (180°C fan-forced). A properly hot oven is crucial, it''s what gives the soufflé its famous lift. A cold oven = a sad soufflé.","images":[],"step":2},{"title":"Prepare the ramekins (Note 4)","description":"Brush the insides of 4 (325ml / 1 1/3 cups) ramekins generously with melted butter (use all the butter). No need to brush upwards (see post for why). Set on a baking tray.","images":[],"step":3},{"description":"Make Mornay sauce (cheese sauce)","images":[],"step":4},{"title":"Heat the milk","description":"Place the milk in a small saucepan over medium heat. Warm it until it’s steaming but not boiling. Set aside.","images":[],"step":5},{"title":"Make the roux","description":"While the milk is heating, let’s start our roux. In a large saucepan, melt the butter over medium heat. Once melted, add the flour. Whisk it gently, it will be thick and pasty at first like a wet sand. Cook, whisking constantly, for about 2 minutes. It will thin up and become smooth and glossy. Make sure to use the whisk to get into the corners of the pot and don’t let it brown. Reduce heat if you think it’s too high.","images":[],"step":6},{"title":"Make Béchamel","description":"Add a third of the hot milk to the roux while whisking vigorously, it will thicken very quickly. Add half of the leftover milk, whisk until smooth and then pour the rest of it along with the salt and pepper. Keep whisking for 30 seconds to a minute until thickened and smooth, lumps will go away. It will be thick enough so you can draw a path with a spatula in the middle, it should hold its shape for a moment before slowly sinking back.","duration":0.5,"images":[],"step":7},{"title":"Turn it into a Mornay sauce","description":"Turn off the heat and whisk in the egg yolks, one at a time, until fully combined (don''t worry the egg yolks won''t cook). Then, turn the heat back on to medium and whisk in the grated Gruyère until melted through. Scrape down the sides and cover with a lid. Set aside.","images":[],"step":8},{"description":"Folding in the Egg Whites and Baking","images":[],"step":9},{"title":"Beat the egg whites, gently at first","description":"Add egg whites and the cream of tartar in a large bowl. Using a hand mixer or a stand mixer fitted with a whisk attachment, beat the egg whites on medium speed for 2 minutes then high speed for 30 seconds until you get firm peaks. Starting slowly helps the protein structure to develop properly. Rush it and you risk unstable, foamy whites that collapse when folded in.","duration":2,"images":[],"step":10},{"title":"Fold gently","description":"Give the Mornay a quick whisk to make it smooth again then add in a quarter of the egg whites and whisk it in to loosen it. Then gently fold a third of the remaining egg whites in using a rubber spatula until mostly incorporated. Use slow, sweeping motions from the bottom of the pot, you want to keep as much air in as possible. (See video at 2.15 minutes) Rough folding = flat soufflé. Few lumps are ok. Repeat twice more with the rest of the egg whites.","images":[],"step":11},{"title":"Fill the ramekins","description":"Pour the mixture evenly into the ramekins using a ladle or a large serving spoon, filling to about 1cm / 0.4\" below the rim. Smooth the tops with the back of a teaspoon dipped in water, no need to be 100% meticulous here, just get rid of big bumps. Run your thumb around the inside rim of each ramekin to clean it, this gives the soufflé a clean edge to rise against.","images":[],"step":12},{"title":"Bake","description":"Place the ramekins on a baking tray and bake for 20 minutes until tall and golden. Do not open the oven door while it''s baking, the sudden drop in heat will make them sink. When it''s cooked, the soufflés should jiggle a bit when you shake the ramekin.","duration":20,"images":[],"step":13},{"title":"Serve immediately","description":"As soon as they’re out, serve straight away. Soufflés don''t wait. So make sure all your family/guest are seated so they can enjoy the show!","images":[],"step":14}]', '["egg","gluten","milk"]', '["vegetarian"]', '{"mealType":["dinner","lunch","snack"],"cuisine":["French"],"categories":["easter-brunch-recipes","egg-recipes","iconic-dishes","jbs-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_882560a6a52e', 'en', 'US', 'Pearl Couscous Salad', 'Recipe video above. I adore the bright Mediterranean flavours in this salad! Great one to take to gatherings for something a little different that everyone always loves. Serve as a side (6 to 8) or a meal in itself (serves 4).Also known as Israeli and gourmet Couscous, pearl couscous is the big brother version of the more common small couscous. Texture and taste like pasta – soft but a bit chewy, but has a pearly, slippery surface (hence the name).', 'https://www.recipetineats.com/tachyon/2017/07/Israeli-Couscous-Salad-3.jpg', 15, 15, 30, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_pears", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 3.0, "unit": "bag of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_dill", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["2 tsp olive oil","1 garlic clove (, minced)","½ small onion (, finely chopped)","1 1/2 cups (250g/ 8oz) pearl couscous (aka gourmet or Israeli couscous, Note 1)","1 1/2 cups vegetable or chicken broth (, low sodium)","1 cup water"],"purpose":"Couscous:"},{"ingredients":["2 cucumbers (, diced (about 2 cups))","250g / 8 oz cherry tomatoes (, halved (about 2 cups))","3 cups baby spinach (, finely sliced (Note 2))","¼ cup coriander / cilantro (, finely chopped (or sub with parsley))","¼ cup dill (, finely chopped)"],"purpose":"Salad:"},{"ingredients":["2 tsp lemon zest","2 tbsp lemon juice","1/4 cup extra virgin olive oil","1 tsp Dijon mustard","1 garlic clove (, minced)","1 tsp sugar (, optional)","3/4 tsp cooking / kosher salt","1/2 tsp black pepper"],"purpose":"Lemon Dressing (Note 3):"}]', '[{"title":"Sauté onion & garlic","description":"Heat oil in a large saucepan or small pot over medium high heat. Add garlic and onion, saute until the onion is translucent and starting to brown.","images":[],"step":1},{"title":"Couscous & broth","description":"Add couscous and stir, cooking for 1 minute. Add broth and water, bring to a simmer. Then place the lid on and turn the heat down to medium low so it is simmering gently.","duration":1,"images":[],"step":2},{"description":"Cook for 10 minutes until the liquid is absorbed and the couscous is cooked through but still firm. Use a fork to separate the couscous, then transfer into a large bowl to cool. (It will form a sticky block but don''t worry, it will separate when tossed with Dressing).","duration":10,"images":[],"step":3},{"title":"Dressing","description":"Place Dressing ingredients in a jar and shake well.","images":[],"step":4},{"description":"Toss! Add Salad ingredients into the bowl, pour over Dressing and toss. Serve at room temperature.","images":[],"step":5}]', '["gluten","mustard"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["easter-brunch-recipes","easter-sides-fresh-light","mediterranean-recipes","pasta-recipes","pasta-salads-and-rice-salads","quick-and-easy","salad-recipes-main-course","side-salads","vegan-lifestyle","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c6fa390416b4', 'en', 'US', 'Christmas Baked Salmon', 'Recipe video above. Have you ever seen a Baked Salmon that looks so festive? What''s more, it''s DEAD EASY! Featuring a honey butter-glazed side of salmon baked in foil, slathered with creamy dill sauce and finally topped with a glittering Holiday "Tapenade", this Salmon Tarator inspired dish pays extremely high dividends for very little work.See notes for alternatives for many of the ingredients - even the salmon!', 'https://www.recipetineats.com/tachyon/2020/12/Christmas-Baked-Salmon_5.jpg', 20, 30, 50, 12, '[{"id": "ing_salmon_fillets", "quantity": {"value": 1.2, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.011, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_honey", "quantity": {"value": 0.25, "unit": "jar of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.9, "unit": "tub of 250g"}}, {"id": "ing_dill", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.5, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 4.0, "unit": "net of 500g"}}, {"id": "ing_cranberries", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_oranges", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_almonds", "quantity": {"value": 0.6, "unit": "pack of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_pomegranate", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 4.0, "unit": "net of 500g"}}, {"id": "ing_emons", "quantity": {"value": 2.0, "unit": "unit"}}]', '[{"ingredients":["1.2 - 1.5 kg / 2.4 - 3lb salmon side (skin on, bones removed, Note 1)","2 1/4 tsp salt (, cooking/kosher (Note 2))","1 tsp black pepper"],"purpose":"Salmon:"},{"ingredients":["150g / 5oz butter (, unsalted)","1/2 cup honey","3 garlic cloves (, finely minced (garlic press or knife))"],"purpose":"Honey Butter Glaze:"},{"ingredients":["1 1/2 cups sour cream (, full fat (low fat is too watery))","1/2 cup fresh dill (, finely chopped (lightly packed cup))","1/2 eschallot (French onion) (, finely grated)","1 1/2 tbsp lemon zest","1/2 tsp salt (, cooking/kosher (Note 2))"],"purpose":"Creamy Dill Sauce:"},{"ingredients":["1 cup dried cranberries","1 cup orange juice","1 cup slivered almonds (, toasted (Note 3))","1/3 cup parsley (, roughly chopped)","1/4 tsp each salt and pepper","1 tbsp extra virgin olive oil"],"purpose":"Holiday \"Tapenade\":"},{"ingredients":["1 pomegranate (, only the seeds)","1/4 cup parsley (, roughly chopped)","3 tbsp lemon juice","2 lemons, extra (, cut in 6 pieces each (for serving, don''t skip this))"],"purpose":"Finishing:"}]', '[{"description":"Creamy Dill Sauce","images":[],"step":1},{"description":"Mix ingredients in a bowl until smooth. Keep refrigerated until required.","images":[],"step":2},{"description":"Holiday Tapenade","images":[],"step":3},{"title":"Plump cranberries","description":"Heat orange juice in a saucepan over high heat until hot. Turn stove off, add cranberries, cover. Stand 15 minutes, then drain in a colander (discard liquid). Cool.","images":[],"step":4},{"title":"Mix","description":"Mix cranberries, toasted almonds (see Note 3), parsley, salt and olive oil in bowl. Use at room temp.","images":[],"step":5},{"description":"Cooking salmon","images":[],"step":6},{"description":"Preheat oven to 180°C/350°F (all oven types).","images":[],"step":7},{"title":"Prepare salmon","description":"Place a large sheet of foil on a tray (double layer for safety is recommended), then top with baking/parchment paper. Place salmon on paper, then fold up the foil sides a bit to cup them so glaze won''t run onto tray.","images":[],"step":8},{"title":"Glaze","description":"Place ingredients in a saucepan over medium high heat. Once it started foaming, turn down to medium, let it foam for 2 minutes then remove and pour straight over the salmon.","duration":2,"images":[],"step":9},{"title":"Season","description":"Sprinkle salmon with salt and pepper, putting most of the salt on the thicker part of the salmon.","images":[],"step":10},{"title":"Wrap","description":"Cover salmon with a smaller piece of paper, then foil. Fold and seal up sides to enclose salmon in a parcel - it doesn''t need to be 100% tightly sealed.","images":[],"step":11},{"description":"Bake 15 minutes. Remove salmon from oven.","images":[],"step":12},{"title":"Uncover / fold excess paper","description":"Remove paper and foil and paper cover. Fold/scrunch paper and foil sides down to expose salmon surface. Tucking paper down also ensures it won''t catch fire when broiling.","images":[],"step":13},{"title":"Grill/broil to brown","description":"Switch oven to grill/broiler on high. Place salmon on middle shelf in the oven and broil 7 to 10 minutes until you get caramelisation mostly on the edges, a bit on top. Don''t put it too close to the heat element otherwise paper might catch on fire! Check to ensure salmon is cooked - either pry open in middle to check or use a probe to check internal temperatures (Note 4).","images":[],"step":14},{"title":"Transfer to plate","description":"Use foil overhang to transfer salmon onto serving platter straight away (otherwise it keeps cooking). Slide the foil then paper out from under the salmon (see video at 1 min 24s or step photos in post), allowing juices to pool on platter (it''s gold stuff!).","images":[],"step":15},{"title":"Cool","description":"Loosely cover with foil, then leave to cool for at least 15 minutes, up to 1 hour or longer (for room temp serving - Note 6 for serving notes).","images":[],"step":16},{"description":"Assembly and serving","images":[],"step":17},{"description":"Dollop then thickly spread with Creamy Dill Sauce (~0.8cm / 1/3\" thick layer).","images":[],"step":18},{"description":"Pile over Holiday Tapenade, scatter generously with pomegranate seeds, and then remaining parsley. Squeeze over lemon juice.","images":[],"step":19},{"title":"Serving","description":"Serve with extra lemon wedges so people can add more to taste. Cut into pieces - I use a cake cutter for serving. Encourage people to slop up some of the honey-butter sauce that will be mixed with semi melted Creamy Dill Sauce - it''s so good! This dish is best served slightly warm, not piping hot, also excellent at room temp.","images":[],"step":20}]', '["fish","milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["easter-mains","easter-mains-fish-seafood","fish-recipes","mains","other","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2d8e8d49a951', 'en', 'US', 'Spanakopita', 'Recipe video above. Spanakopita - the iconic traditional Greek Spinach Pie with layers upon layers of golden buttery flaky filo pastry. For the best Spanakopita of your life, use raw rather than cooked spinach, and layer the phyllo pastry with finely shredded Greek cheese so it sticks together rather than flying everywhere when you cut it!This pie is a perfect thickness with a good ratio of Spinach Feta filling to pastry. It will serve 4 to 5 people as a main dish.', 'https://www.recipetineats.com/tachyon/2021/03/Spanakopita_0-1-1.jpg', 40, 25, 65, 4, '[{"id": "ing_spinach", "quantity": {"value": 300.0, "unit": "bag of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_feta_cheese", "quantity": {"value": 175.0, "unit": "block of 200g"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.15, "unit": "tub of 500g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_mint", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_dill", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.005, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.005, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_nutmeg", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_sheets_filo_pastry", "quantity": {"value": 16.0, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 120.0, "unit": "block of 250g"}}, {"id": "ing_cheese", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}]', '[{"ingredients":["300g/10oz English spinach leaves","1/2 tsp salt"],"purpose":"Spinach:"},{"ingredients":["175g/6oz Greek feta (, crumbled)","1/2 cup Greek yoghurt","2 green onions / scallions (, finely sliced)","1 egg","2 tbsp mint (, finely chopped)","1 tbsp dill (, finely chopped)","1/2 tsp lemon zest","1/2 tbsp lemon juice","2 garlic cloves (, finely chopped)","1/2 tsp nutmeg (, freshly grated)","1/4 tsp black pepper","1/4 tsp salt","1/4 tsp cayenne pepper"],"purpose":"Filling:"},{"ingredients":["16 sheets filo pastry (Note 2)","120g/ 8 tbsp butter (, melted)","60g / 2/3 cup Greek Kefalotyri cheese (, finely grated (sub parmesan, Note 3))","1/2 tsp white sesame seeds (or more black)","1/2 tsp black sesame seeds (or more white)"],"purpose":"Filo pastry:"}]', '[{"description":"Preheat oven to 220°C/430°F (200°C fan). Line a tray with baking paper / parchment paper.","images":[],"step":1},{"title":"Sweat spinach","description":"Place spinach in a large colander or bowl. Sprinkle with salt, toss through. Leave for 10 minutes to sweat.","duration":10,"images":[],"step":2},{"title":"Wring out water","description":"Place a handful of spinach in a tea towel, then wring out tightly to remove excess water.","images":[],"step":3},{"title":"Filling","description":"Place spinach in a bowl with remaining Filling ingredients. Mix well to combine.","images":[],"step":4},{"title":"Trim filo","description":"Cut 16 sheets of filo pastry into 32 x 25cm / 13 x 10\" (pictured) or 26cm / 10.5\" square.","images":[],"step":5},{"title":"8 base layers","description":"Layer 8 sheets of filo pastry on the tray, brushing each layer with melted butter.","images":[],"step":6},{"title":"Filling","description":"Spread filling on filo pastry. Smooth surface and leave a 2.5cm / 1\" border.","images":[],"step":7},{"title":"8 Filo topping layers (Note 4)","description":"Cover spinach with a sheet of filo pastry. Brush with butter, sprinkle with Kefalotyri. Repeat for Sheets #2 to #5. Then cover with filo sheets #6 to #8, brushing with butter in between, but do NOT sprinkle with cheese (neater finish).","images":[],"step":8},{"title":"Seal","description":"Press edges down to seal. Crimp and trim if desired (see process steps in post or video) or just leave the edges flat on the tray.","images":[],"step":9},{"title":"Sesame seeds","description":"Brush the top with butter, sprinkle with sesame seeds.","images":[],"step":10},{"title":"Bake","description":"Bake 25 minutes, or until golden brown on the surface.","images":[],"step":11},{"description":"Serve! Serve immediately! It is at its absolute prime fresh out of the oven, though still good as long as its hot (~15 min or so). The base does lose crispiness as it cools.","images":[],"step":12}]', '["egg","milk","sesame"]', '["gluten_free","high_protein","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["easter-mains","greek-recipes","iconic-dishes","mediterranean-recipes","quiches-tart-and-pie-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c0d8526319a5', 'en', 'US', 'Fish koftas', 'Recipe video above. These fish koftas are like your favourite Middle Eastern lamb koftas - except made with fish. Adore the spicing! Serve with Jewelled rice pilaf for a stunning platter of food.Makes 10 to 12 koftas, serves 4 to 5.', 'https://www.recipetineats.com/tachyon/2023/04/Fish-koftas_4.jpg', 20, 10, 35, 10, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_cinnamon_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_feta_cheese", "quantity": {"value": 70.0, "unit": "block of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_mint", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_rice", "quantity": {"value": 75.0, "unit": "pack"}}]', '[{"ingredients":["500g/1 lb white fish fillets (,skinless, cut in pieces (Note 1))","1 egg white (add leftover yolk to scrambled eggs!)","1/2 red onion (, grated using a box grater (keeps koftas soft!))","2 garlic (, finely minced)","1 tsp cumin powder","1 tsp coriander powder","1/4 tsp cinnamon powder","1/4 tsp cardamom powder","1 tsp cooking salt (kosher salt)","1/2 cup rice flour (sub cornflour/cornstarch)","2 tbsp chopped parsley","70g/ 2.5 oz danish feta (, plus extra for optional garnish (Note 2))","2 tbsp extra virgin olive oil"]},{"ingredients":["3/4 cup plain yogurt (, unsweetened)","1/2 cup (tightly packed) mint leaves","2 tsp lemon juice","1/4 tsp cooking / kosher salt"],"purpose":"Minted yogurt"},{"ingredients":["Parsley or coriander (, roughly chopped)","Persian Jewelled Rice (or plain basmati rice)"],"purpose":"Serving (optional, pictured)"}]', '[{"title":"Fish & egg blitz","description":"Place fish and egg white in a food processor. Blitz on high until smooth. (30 sec to 1 minute) A stick blender also works but it will take a bit longer.","images":[],"step":1},{"title":"Kofta mixture","description":"Add onion, garlic, all the spices, salt, rice flour and parsley. Blitz on high until smooth (1 minute). Consistency should be like a paste. (Note","images":[],"step":2},{"title":"Feta","description":"Remove the blade, then crumble the feta in. Aim for chunks. Mix delicately (so the feta doesn''t disintegrate).","images":[],"step":3},{"title":"Form koftas","description":"Use wet hands so the mixture doesn''t stick. Portion the mixture into 10 - 12 (70g / 1/3 cup each), and shape into a 10cm / 4\" cylinder. Thread onto skewers then slightly flatten to 1.75cm / 2/3\" thick. (Note 3)","images":[],"step":4},{"title":"Cook","description":"Heat olive oil over medium high heat in a large non-stick pan. Cook half the koftas for 2 minutes on each side until golden, or until the internal temperature reaches 50°C/122°F.","duration":2,"images":[],"step":5},{"title":"Rest","description":"Remove onto a plate and cook the remaining koftas. (Internal temperature of cooked koftas will rise to 55°C/131°F).","images":[],"step":6},{"description":"Serve with Minted Yogurt and Jewelled rice pilaf for a stunning platter of food!","images":[],"step":7},{"description":"Blitz all ingredients in a tall jug just large enough to fit a stick blender. Keep refrigerated until required.","images":[],"step":8}]', '["egg","fish","gluten","milk"]', '["keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern","Persian"],"categories":["easter-mains-fish-seafood","fish-recipes","mains","other","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b43d6353d607', 'en', 'US', 'Singapore Chilli Crab', 'Recipe video above. Here''s arguably the most famous crab recipe in the world: Singapore Chilli Crab! For the pinnacle of the experience, make this using fresh, live mud crab that you clean and cut yourself, or ask the fish shop to cut the crab for you (make sure they save the tomalley "crab mustard", Note 8). Be prepared to get messy eating it (half the fun!) – and to be surprised at how quick it is to make! Flavour: The sauce is a bit spicy but not excessively (Note 2 for adjustment). It is supposed to be a bit sweet, vinegary and intensely savoury. It gets massive flavour from the combination of crab juices, tomalley ("crab mustard", Note 8), belachan shrimp paste, and the soy bean paste! The traditional sauce has bits of egg ribbson in it, and includes ketchup - yes, really!Serves 3 - 4 as a meal with rice and some vegetables.', 'https://www.recipetineats.com/tachyon/2021/07/Singapore-Chilli-Crab_4.jpg', 20, 20, 40, 3, '[{"id": "ing_live_mud_crab_or_other_large_crab", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 5.0, "unit": "pack of 100g"}}, {"id": "ing_taucu_paste", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_eschalots", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_shrimp", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 5.0, "unit": "pack of 100g"}}, {"id": "ing_ketchup", "quantity": {"value": 0.06, "unit": "bottle of 500g"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_green_onion", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["1.5 kg / 3lb live mud crab or other large, fresh crab"]},{"ingredients":["5 red cayenne chilli (, seeds left in, roughly chopped (Note 2))","2 tbsp taucu paste (fermeted soy paste, sub miso Note 3)","6 garlic cloves ((small), roughly chopped)","2 eschalots (small), roughly chopped (Note 4)","3 tbsp ginger (, roughly chopped (~7.5cm / 3\" piece))"],"purpose":"Chilli paste:"},{"ingredients":["1/4 cup canola oil","1 tbsp belachan dried shrimp paste (, chopped (sub shrimp paste, Note 5))","1 cup tomato passata (Note 6)","1/2 cup sweet chilli sauce","2 tbsp ketchup","2 cups water","1 egg (, lightly whisked)","3 tbsp white vinegar"],"purpose":"Singapore Chilli Crab Sauce:"},{"ingredients":["Fresh coriander (, leaves whole or roughly chopped)","2 tbsp green onion (, finely sliced (or 1/4 cup finely sliced on angle, ice water 3 minutes for slight curl))","Golden mantou buns (Note 7)"],"purpose":"Garnishes/serving:"}]', '[{"title":"Prepare crab","description":"See separate tutorial for how to clean and cut a whole crab. You will end up with: 1) Crab pieces; and 2) Reserved tomalley (\"crab mustard\", Note 8) and crab juices in a separate bowl. This is a key \"secret ingredient\" used to flavour the sauce.","images":[],"step":1},{"title":"Chilli paste","description":"Place ingredients in a small food processor or Nutribullet. Blitz until it''s a fairly smooth paste.","images":[],"step":2},{"title":"Sauté belachan","description":"Heat oil in a large pot over medium-high heat. Add belachan and cook for 2 minutes, stirring constantly. It will smell pungent (to put it mildly), but have faith! It will mellow and transform!","duration":2,"images":[],"step":3},{"title":"Cook off chilli paste","description":"Add chilli paste and cook, stirring, for 3 minutes.","duration":3,"images":[],"step":4},{"title":"Add tomato passata","description":"Add tomato passata and cook, stirring regularly, for 4 minutes.","duration":4,"images":[],"step":5},{"title":"Add remaining sauce ingredients","description":"Add sweet chilli sauce, ketchup, water and stir to combine.","images":[],"step":6},{"title":"Add claws","description":"Add the crab claws first (they take longer to cook), stir to coat in sauce. Bring to a boil, then reduce heat to simmer. Cover with a lid and cook 3 minutes.","images":[],"step":7},{"title":"Add \"crab mustard\" and juices","description":"Add the reserved tomalley (\"crab mustard\") along with all the crab juices.","images":[],"step":8},{"title":"Add remaining crab pieces","description":"Remove lid, add remaining crab pieces and any juices that have collected in this bowl. Stir pieces to coat, put the lid back on and cook for 7 minutes.","duration":7,"images":[],"step":9},{"title":"Remove crab","description":"Use tongs to remove crab pieces into a bowl.","images":[],"step":10},{"title":"Egg ribbons","description":"With the sauce still on the stove, and while stirring in a circular motion, pour the egg in a thin stream into the middle of the pot. This will create little ribbons of egg in the sauce that is traditional and look lovely.","images":[],"step":11},{"title":"Vinegar","description":"Stir in vinegar.","images":[],"step":12},{"title":"Return crab","description":"Return the crab pieces into the pot, gently stir to coat in the sauce.","images":[],"step":13},{"description":"Plating up and serving:","images":[],"step":14},{"description":"Transfer crab pieces into a large serving plate or shallow dish. Pour over all the sauce from the pot. Garnish with coriander and green onion.","images":[],"step":15},{"description":"Serve with golden mantou buns (steamed and fried Chinese buns, traditional - Note 7), or homemade brioche (ultimate sub!), baguette, crusty bread or dinner rolls. Alternatively serve with rice on the side.","images":[],"step":16},{"title":"How to eat","description":"Be prepared to get messy! Dive in for the claw (the prime piece!). Use crab or nut crackers to break the shell (or a meat tenderiser or hammer - anything to get to that meat!!) and reveal hunks of sweet juicy crab meat. Dunk generously in sauce and devour.","images":[],"step":17},{"title":"Leftover Sauce","description":"You will have leftover sauce. It''s loaded with flavour so save it, it''s precious! See in post for ideas for how to use.","images":[],"step":18}]', '["egg","shellfish","soy"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Singapore"],"categories":["easter-mains-fish-seafood","iconic-dishes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a590753dfec0', 'en', 'US', '"Poor Man''s Lobster" – Monkfish with Herb Browned Butter', 'Recipe video above. With sweet, meaty shellfish-like flesh, monkfish is affectionately known as "poor man''s lobster". But there''s certainly nothing "poor" about this dish!If you''re new to cooking monkfish, this is a good recipe to try. It''s easy and showcases just how good monkfish is. There''s a reason it''s a firm favourite with upmarket restaurants!Other names: Stargazer is another name for monkfish in Australia.Allow around 150 - 180g / 5 - 6oz monkfish per serving.', 'https://www.recipetineats.com/tachyon/2021/06/Monkfish_1.jpg', 10, 8, 18, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_chives", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_chervil", "quantity": {"value": 0.5, "unit": "unit"}}]', '[{"ingredients":["300g / 10oz monkfish fillets (, skinless and boneless (Note 1))","1 1/2 tbsp extra virgin olive oil","1/4 tsp salt","1/8 tsp black pepper (, finely ground)","2 tbsp/ 30g unsalted butter (, cut into 1cm (1/2\") cubes)","2 garlic cloves (, smashed (Note 2))","2 sprigs thyme"]},{"ingredients":["1/2 tsp parsley (, finely chopped)","1/2 tsp chives (, finely chopped)","1/2 tsp chervil (, finely chopped)"],"purpose":"Fresh herbs (Note 3):"}]', '[{"title":"Cut fillets","description":"Cut each monkfish into 3 or 4 even size pieces. (Note 1)","images":[],"step":1},{"title":"Season","description":"Sprinkle both sides of fish with salt and pepper.","images":[],"step":2},{"title":"Rack for resting","description":"Place a rack over a tray (optional, for resting fish, Note 5)","images":[],"step":3},{"description":"Cooking monkfish (Note 2):","images":[],"step":4},{"title":"Heat oil","description":"Heat oil in non-stick pan over medium heat (medium-high for weak stoves).","images":[],"step":5},{"title":"Sear first side, then turn","description":"Place thickest pieces of fish in the pan first. Leave for 1 minute then add the thinner pieces. (Note 4). Cook for a further 2 minutes, then flip fish.","duration":1,"images":[],"step":6},{"title":"Add butter and baste","description":"Add butter to pan. After it starts melting, add garlic and thyme. When the butter starts foaming, tilt the pan and start spooning the butter over the fish. Do this for 2 minutes or until the internal temperature is 55°C/131°F (Note 6), or the flesh flakes easily. Butter will begin to smell nutty - it''s now brown butter!","duration":2,"images":[],"step":7},{"title":"Rest","description":"Transfer fish onto the rack and rest for 3 minutes.","duration":3,"images":[],"step":8},{"title":"Add herbs","description":"Add herbs to butter remaining in pan. Serve this Herb Brown Butter with monkfish.","images":[],"step":9},{"description":"Optional plating up, fine dining style!","images":[],"step":10},{"description":"Slice monkfish into 2.5cm / 1\" pieces. Place on pea puree, then drizzle with Herb Brown Butter. Optional garnish with any combination of dill, parsley, chervil.","images":[],"step":11}]', '["milk"]', '["gluten_free","high_protein","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","easter-mains-fish-seafood","fish-recipes","mains","other","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8037edf11742', 'en', 'US', 'Acqua Pazza - Italian Poached Fish', 'Recipe video above. This is a recipe that showcases Italian cooking at its best: a handful of simple ingredients to create something magical! Fish is half poached, half steamed in a tomato-white wine based sauce, then served over crispy garlic crostini.The literal translation of this dish is "fish in crazy water". Maybe because who would think that fish poached in water could be so delicious? That''s crazy! :)', 'https://www.recipetineats.com/tachyon/2021/02/Acqua-Pazza_0.jpg', 10, 40, 50, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 0.25, "unit": "pack of 1kg"}}, {"id": "ing_fennel", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_chilli", "quantity": {"value": 5.0, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 15.0, "unit": "punnet of 250g"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 15.0, "unit": "punnet of 250g"}}, {"id": "ing_chardonnay", "quantity": {"value": 0.75, "unit": "unit"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}]', '[{"ingredients":["2 x 180g/6oz snapper fillets, or other white fish, (, skin on, bones and scales removed (Note 1))","1/4 tsp salt"]},{"ingredients":["2 tbsp extra virgin olive oil","1/4 red onion (, sliced 1cm / 1/3\" thick)","1/2 fennel (medium) (, sliced sliced 1cm / 1/3\" thick)","1/2 large red chilli (cayenne pepper) (, seeds removed and finely chopped (Note 2))","2 garlic cloves (, finely minced)","15 red cherry tomatoes (, halved)","10 yellow cherry tomatoes (, halved (or more red))","3/4 cup chardonnay (not too woody) (, or other dry white wine (Note 3))","2 cups water","1/4 tsp salt","1 tbsp basil (, finely sliced (keep stems), plus more for garnish)","1 tbsp parsley (, finely chopped (keep stems))"],"purpose":"Sauce:"},{"ingredients":["1 crusty baguette (, cut 4 to 6 slices on a diagonal, 1cm / 1/3\" thick)","1/4 tsp salt","1 - 2 tbsp extra virgin olive oil","1 garlic clove (, halved (for rubbing))"],"purpose":"Garlic Crostini:"}]', '[{"title":"Sauté fennel and onion","description":"Heat oil in a non-stick skillet over medium heat. Add fennel and onion, cook 4 minutes until softened but not golden.","images":[],"step":1},{"title":"Garlic and chilli","description":"Add garlic and chilli, cook for 1 minute until garlic is softened.","duration":1,"images":[],"step":2},{"title":"Tomatoes","description":"Add cherry tomatoes, cook for 4 minutes.","duration":4,"images":[],"step":3},{"title":"Reduce wine","description":"Turn stove up to high, add wine and simmer rapidly for 2 - 3 minutes until reduced by half.","duration":2.5,"images":[],"step":4},{"title":"Simmer sauce","description":"Add water and salt, and the basil & parsley stems if you kept them. Bring to boil, then lower stove to medium and simmer for 20 - 25 minutes until sauce reduces by about 2/3 (it will thicken from tomatoes breaking down).","duration":22.5,"images":[],"step":5},{"title":"Cook fish","description":"Sprinkle flesh side of fish with salt, then place on sauce skin side down (it will mostly sit above sauce). Cover with lid (or foil or tray) and cook for 6 minutes or until internal temperature registers 55°C/131°F (for medium, no rare/raw left with optimum juiciness).","duration":6,"images":[],"step":6},{"title":"Remove fish","description":"Remove lid, transfer fish to plate.","images":[],"step":7},{"title":"Add herbs","description":"Remove basil and parsley stems. Stir basil and parsley into sauce. Taste sauce, add more salt if required.","images":[],"step":8},{"description":"To serve:","images":[],"step":9},{"description":"Place 2 crostini in a shallow bowl. Spoon over a bit of the chunky sauce, top with fish. Spoon remaining sauce around.","images":[],"step":10},{"description":"Garnish with extra basil and a drizzle of olive oil. Serve immediately.","images":[],"step":11},{"description":"Garlic crostini:","images":[],"step":12},{"description":"Preheat oven to 180°C/350°F (all types).","images":[],"step":13},{"description":"Brush olive oil on bread, sprinkle with a bit of salt. Flip and repeat. Bake 10 minutes, turning halfway, or until fully crispy.","images":[],"step":14},{"description":"Rub bread lightly on one side with cut face of garlic. Use warm or at room temperature.","images":[],"step":15}]', '["fish"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["easter-mains-fish-seafood","fish-recipes","italian-recipes","mains","other","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_040012ed299e', 'en', 'US', 'Seafood Spaghetti Marinara', 'A classic seafood pasta made with a pre-made seafood marinara mix. This is really simple to make, and the key to this recipe is the step where the pasta is finished cooking in the sauce. This is called "emulsifying", and it''s an essential Italian cooking technique where the starch in the pasta cooking water reacts with the oil in the sauce and makes the sauce thick and luscious so it coats every strand of pasta.', 'https://www.recipetineats.com/tachyon/2016/06/Seafood-Marinara-Spaghetti_2.jpg', 5, 15, 20, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.34, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_seafood_marinara_mix", "quantity": {"value": 10.0, "unit": "unit"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["6 oz / 180g dried spaghetti pasta (or other long pasta of choice)","2 1/2 tbsp olive oil (, separated)","10 oz / 300g seafood Marinara mix (, or make your own (Note 1))","2 garlic cloves (, minced)","1/2 onion (, finely chopped (~1/2 cup))","1/2 cup white wine (any) (Note 2)","2 cups tomato passata/tomato puree ((Note 3) OR 600g/20oz canned crushed tomato + 1/2 cup water)","1/2 tsp sugar","2 tbsp finely chopped fresh parsley"]}]', '[{"description":"Bring a large pot of salted water to boil. Cook pasta according to packet directions, but reduce the cooking time by 1 minute (because the pasta will finish cooking in the sauce). RESERVE 1 mug of pasta water, then drain the pasta.","images":[],"step":1},{"description":"Separate the seafood mix based on cook time. Longest cook time: fish and medium / large prawns, medium cook time: small prawns, shortest cook time: calamari.","images":[],"step":2},{"description":"Heat 1 1/2 tbsp oil in a large skillet over high heat. Add fish and large prawns first, cook for 30 seconds. Add small prawns, cook for 30 seconds. Add calamari, cook for 1 minute. Immediately transfer everything to a bowl.","duration":0.5,"images":[],"step":3},{"description":"Reduce heat to medium high. Heat remaining 1 tbsp oil, then add garlic and onion. Cook for 3 minutes until onion is translucent.","duration":3,"images":[],"step":4},{"description":"Add wine and bring to simmer, scraping the bottom of the skillet to mix the brown bits into the liquid. Simmer for 1 minute or until alcohol smell has evaporated.","duration":1,"images":[],"step":5},{"description":"Add tomato passata, sugar, salt & pepper. Low heat to medium high, bring to simmer and cook for 2 minutes. Adjust salt and pepper to taste.","duration":2,"images":[],"step":6},{"description":"Add pasta, seafood, around 1/2 cup of reserved pasta cooking water into the sauce. Toss gently and cook for 1 to 2 minutes or until the sauce has thickened and coats the pasta.","duration":1.5,"images":[],"step":7},{"description":"Serve, garnished with fresh parsley. (See Note 4 re: parmesan cheese)","images":[],"step":8}]', '["gluten"]', '["vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["dinner-tonight","easter-mains-fish-seafood","italian-recipes","main-dishes","pasta-recipes","prawns-shrimp","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_182ebe92bda0', 'en', 'US', 'Italian Pasta Salad with Homemade Italian Dressing', 'Recipe video above. If you''re going to make a giant pasta, make it RIGHT with a beautiful homemade Italian Dressing!', 'https://www.recipetineats.com/tachyon/2017/03/Italian-Pasta-Salad-2.jpg', 15, 10, 25, 8, '[{"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_vinegar", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.113, "unit": "pack of 200g"}}, {"id": "ing_sugar", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.025, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_thick_salami_cut_into_2_5cm_1_batons", "quantity": {"value": 0.18, "unit": "kg"}}, {"id": "ing_baby_bocconcini", "quantity": {"value": 200.0, "unit": "unit"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_whole_olives", "quantity": {"value": 250.0, "unit": "bottle"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.2, "unit": "punnet of 250g"}}, {"id": "ing_basil", "quantity": {"value": 0.05, "unit": "bunch"}}]', '[{"ingredients":["1/2 cup extra virgin olive oil","1/4 cup red or white wine vinegar (I like using red)","1 1/2 tbsp freshly grated parmesan cheese (Note 1)","1 tbsp sugar (any)","1 large garlic clove, minced","1/2 tsp each dried basil and oregano","1/4 tsp dried parsley","1/2 tsp dried chilli flakes (red pepper flakes) (optional)","3/4 tsp salt","1/2 tsp black pepper"],"purpose":"Italian Dressing"},{"ingredients":["300g/10oz spiral pasta, or other pasta of choice","180g/6oz thick sliced salami, cut into 2.5cm/1\" batons (see photo in post or videos) (I use spicy salami)","200g/7oz baby bocconcini, halved (Note 2)","1 red capsicum/bell pepper, cut into 3cm/2.2cm strips","250g/8oz whole olives (I used Sicilian and pitted black) (Note 3)","2 cups cherry tomatoes, halved (~1.5 Australian punnets)","1 cup (tightly packed) fresh basil leaves"],"purpose":"Pasta Salad"}]', '[{"description":"Place Dressing ingredients in a jar and shake well.","images":[],"step":1},{"description":"Cook pasta according to packet directions minus 1 minute. Drain in a colander and rinse under cold water to stop it cooking further. Shake excess water off well then transfer into large bowl.","images":[],"step":2},{"description":"Place remaining Pasta Salad ingredients in the bowl. Drizzle over Dressing and toss. Serve at room temperature.","images":[],"step":3},{"description":"Make ahead PRO TIP (Note 4):","images":[],"step":4},{"description":"SCOOP OUT a mug of pasta cooking water just before draining. Add 3 tbsp water to Dressing, shake well. Use this Dressing per above, but reserve 3 tbsp to freshen up pasta salad on Day 2 onwards.","images":[],"step":5},{"title":"Freshen up pasta salad","description":"Bring to room temp or briefly microwave (cold pasta = dry) to warm gently. Toss with Reserved Dressing then serve.","images":[],"step":6}]', '["gluten","milk"]', '[]', '{"mealType":["dinner","lunch"],"cuisine":["Italian"],"categories":["dinner-tonight","easter-sides-fresh-light","italian-recipes","no-cook-food","pasta-recipes","pasta-salads-and-rice-salads","quick-and-easy","salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d0fe3651165a', 'en', 'US', 'JB''s Pommes Anna', 'Recipe video above. Introducing Pommes Anna - the ultimate French potato cake. Thinly sliced potato, lots of butter, crispy edges, soft centre, and a big “wow” moment when you flip it out. We’ve had quite a few of those in the process of developing it! When simple ingredients make beautiful result.', 'https://www.recipetineats.com/tachyon/2025/11/Pommes-Anna_9-1.jpg', 30, 100, 140, 8, '[{"id": "ing_potato", "quantity": {"value": 1.6, "unit": "bag of 2kg"}}, {"id": "ing_butter", "quantity": {"value": 160.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 1.0, "unit": "jar of 40g"}}]', '[{"ingredients":["1.6 kg / 3.5 lb medium starchy potato","160g / 5.6 oz unsalted butter (makes 1/2 cup clarified butter) (Note 2)","1 tsp cooking salt / kosher salt","1/4 tsp white pepper powder"]},{"ingredients":["1 sprinkle sea salt flakes (, if you want (I did!))"],"purpose":"Optional"}]', '[{"description":"Build 3 layers of thinly sliced potatoes (1.5mm / 0.06\") in a spiral pattern brushing with clarified butter and seasoning as you go. Bake 70 minutes at 200°C / 400°F (180°C fan) covered with cartouche then 30 minutes uncovered. Rest 10 minutes, flip, and enjoy!","images":[],"step":1},{"description":"How to make Clarified Butter:","images":[],"step":2},{"description":"Melt the butter in a saucepan or microwave. Set aside for 5 minutes until the milk solids settle on the bottom (white stuff). Scrape off the foam, then slowly pour the clear golden butter through a small sieve into a jug while leaving the milk solids behind (discard it). That clear golden butter is your clarified butter.","duration":5,"images":[],"step":3},{"description":"How to make Pommes Anna:","images":[],"step":4},{"title":"Prep pan","description":"Preheat oven to 200°C / 400°F (180°C fan-forced). Brush the base of a 26cm / 10\" cast-iron skillet with 2 tablespoons of clarified butter. (Note 3)","images":[],"step":5},{"title":"Slice potatoes","description":"Peel potatoes and using a mandolin, slice 2 or 3 potatoes 1.5mm / 0.6\" thick. Quickly sort the slices into small, medium and large sizes. Do not put them in water. (Note 4 + 5)","images":[],"step":6},{"title":"Build the first layer","description":"Using the medium size slices, put one slice in the middle, then build a spiral around it, overlapping each slice by about 3/4. Then, using the larger slices, make a second spiral around the first one until the whole base is fully and evenly covered. If you have medium slices left, you can use them here too. The second spiral should slightly overlap the first to keep the final shape tidy and firm. Tuck some small slices inside the tiny gap in the centre, do this for every layer to keep the middle neat.","images":[],"step":7},{"description":"Brush / dab generously with clarified butter, taking care not to disturb or lift the slices. Season with a third of the salt and white pepper.","images":[],"step":8},{"title":"Build two more layers","description":"Repeat the same spiral pattern for 2 more layers, brushing with clarified butter and seasoning each layer.","images":[],"step":9},{"title":"Cartouche","description":"Place a cartouche (circle of baking paper / parchment paper) on top. (Note 6)","images":[],"step":10},{"description":"Bake for 70 minutes. Remove the cartouche, then bake another 30 minutes until the top and edges are deep golden and crispy.","duration":70,"images":[],"step":11},{"title":"Rest + flip","description":"Rest for 10 minutes on the counter. Flip onto a plate and lift the pan to reveal your beautiful Pommes Anna. Serve immediately, happiness does not wait 😊","duration":10,"images":[],"step":12}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["easter-sides-warm-hearty","jbs-recipes","potato-recipes","potatoes","side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_44a8ab2a6886', 'en', 'US', 'Carbonara (real)', 'Recipe video above. These days, so many carbonara recipes cheat with cream which is a shame. The traditional method uses raw egg which is mixed vigorously with hot pasta and parmigiana reggiano cheese which transforms into a silky, creamy, luxurious sauce unlike anything you''ve ever had before. Arguably the best pasta dish in the whole world!This is a pasta that must be eaten straight away to truly experience its magnificence. Serve in warm bowls!', 'https://www.recipetineats.com/tachyon/2023/01/Carbonara_6a.jpg', 5, 15, 20, 4, '[{"id": "ing_guanciale", "quantity": {"value": 0.175, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 166.667, "unit": "carton of 12"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.8, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.8, "unit": "pack of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["175g/6 oz guanciale (pancetta or block bacon), ( weight after skin removed (Note 1))","2 large eggs (Note 2)","2 egg yolks (Note 2)","100g/3.5 oz parmigiano reggiano (, finely shredded (or pecorino romano, sub parmesan, Note 3))","1/4 tsp black pepper","400g/14 oz spaghetti","1 tbsp cooking/kosher salt (for cooking pasta)","1/2 cup pasta cooking water","1 garlic clove (, finely minced (optional, Note 4))"]},{"ingredients":["Parsley (, finely chopped)","Parmigiano reggiano"],"purpose":"Garnish (optional):"}]', '[{"title":"Guanciale","description":"Cut into 0.5cm / 1/5\" thick slices then into batons.","images":[],"step":1},{"title":"Carbonara sauce","description":"Place eggs and yolks in a large bowl. Whisk to combine. Then stir in the parmesan and pepper.","images":[],"step":2},{"title":"Cook pasta","description":"Bring 4 litres (4 quarts) of water to the boil with the salt. Add pasta and cook per the packet directions.","images":[],"step":3},{"title":"Reserve pasta water","description":"Just before draining, scoop out 1 cup of pasta cooking water, then drain the pasta.","images":[],"step":4},{"title":"Cook guanciale","description":"While the pasta is cooking, place guanciale in a non stick pan over medium high heat. Cook for 4 to 5 minutes until golden. No oil needed - as the guanciale heats up, the fat will melt so it fries in its own fat. If using garlic, add it in the last minute.","duration":4.5,"images":[],"step":5},{"title":"Pasta in pan","description":"Tip the hot pasta into the pan and toss to coat in guanciale fat.","images":[],"step":6},{"title":"Mix pasta in sauce","description":"Transfer the pasta and any residual fat in the pan into the bowl with the egg. Add 1/2 cup (125 ml) pasta cooking water. Stir vigorously using the handle of a wooden spoon for 1 minute and watch as the sauce transforms from watery to creamy and clings to the pasta strands!","duration":1,"images":[],"step":7},{"title":"Serve","description":"Transfer into warm bowls. Serve immediately, garnished with a little extra parmigiana reggiano if desired, and a pinch of black pepper and finely chopped parsley.","images":[],"step":8}]', '["egg","gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["egg-recipes","egg-yolk-recipes","iconic-dishes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f9aa619a366e', 'en', 'US', 'Béarnaise Sauce - Fast, easy, foolproof method', 'Recipe video above. Béarnaise Sauce, considered by many to be one of the finest steak sauces in the world, and a classic spin on Hollandaise sauce, one of the 5 French “mother sauces.” It''s notoriously difficult to make by hand. This recipe uses a foolproof stick blender method that yields exactly the same results in 2 minutes flat - and has the tick of approval from our resident French Chef JB!Serve over steak or pan seared salmon for a fine dining restaurant experience at home.Makes enough to (very) generously sauce 3 large steaks, or 4 sensible portions.', 'https://www.recipetineats.com/tachyon/2021/02/Spooning-Bearnaise-Sauce-on-Steak_5.jpg', 10, 2, 12, 4, '[{"id": "ing_wine", "quantity": {"value": 0.03, "unit": "bottle of 750ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_tarragon", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 225.0, "unit": "block of 250g"}}, {"id": "ing_tarragon", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_chervil", "quantity": {"value": 0.5, "unit": "unit"}}]', '[{"ingredients":["1 1/2 tbsp white wine (, dry, not too fruity, sweet or woody (Note 1))","1 1/2 tbsp white wine vinegar (Note 2)","1/4 tsp black pepper (, coarsely crushed)","1 eschallot (small), peeled and finely sliced (Note 3)","2 sprigs tarragon (Note 6)"],"purpose":"Infused Vinegar :"},{"ingredients":["3 egg yolks (, at room temperature (Note 4))","1/4 tsp salt (, kosher/cooking salt)","225g / 16 tbsp unsalted butter (, cut into 1cm / 1\" cubes - 2 US sticks (Note 5))","1/2 tbsp tarragon leaves (, finely chopped (Note 6))","1/2 tbsp chervil (, finely chopped (Note 6))"],"purpose":"Béarnaise Sauce:"}]', '[{"description":"Infused Vinegar:","images":[],"step":1},{"description":"Place Infused Vinegar ingredients in a small saucepan over medium low heat.","images":[],"step":2},{"description":"Simmer for 2 minutes, then remove from stove and let it stand for 5 minutes to infuse.","duration":2,"images":[],"step":3},{"description":"Strain, pressing to extract as much liquid as possible. You should have around 1 tbsp of liquid. Cool 5 minutes before use.","images":[],"step":4},{"description":"Quick Clarified Butter:","images":[],"step":5},{"description":"Place butter in a jug and microwave until melted (1 - 1½ minutes on high, but watch it carefully so it doesn''t explode!).","images":[],"step":6},{"description":"Stand for 30 seconds until the milky whites settle at the bottom (this is the milk solids) and clarified butter (golden part) sits above it.","duration":0.5,"images":[],"step":7},{"description":"Pour off 175g / 3/4 cup of the clarified butter, discard the milky whites remaining. Use in this recipe while hot.","images":[],"step":8},{"title":"Alternative","description":"Just melt 175g / 3/4 cup ghee, which is the same thing as clarified butter.","images":[],"step":9},{"description":"Béarnaise Sauce:","images":[],"step":10},{"description":"Place egg yolks, infused vinegar and salt in a tall, narrow container that the blender stick fits in all the way to the base. Blitz briefly to combine.","images":[],"step":11},{"description":"With the stick blender going on high, slowly drizzle the butter in over about a minute. Important: The butter must still be hot! If it has cooled, reheat until hot.","images":[],"step":12},{"description":"After all the butter is in, blitz for a further 10 seconds, moving the stick up and down.","images":[],"step":13},{"title":"Thickness","description":"Add 1 tablespoon water, then blitz to incorporate. Add more water as needed, 1 teaspoon at a time, until the Bearnaise Sauce is a thick sauce but loose enough to ooze across a steak, coating it thickly.","images":[],"step":14},{"title":"Fresh herbs","description":"Stir in tarragon and chervil.","images":[],"step":15},{"title":"Using","description":"Use immediately, or keep warm until required. I use a thermos – a good one will keep it warm for at least 1 hour. Use warm or at room temperature. See note for storing and reheating.","images":[],"step":16}]', '["egg","milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["egg-yolk-recipes","roast-beef"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7be39f3c2fa0', 'en', 'US', 'Crispy pea fritters - great emergency meal!', 'Recipe video above. This is a super handy recipe for when your fridge is looking a little bare, because who doesn’t have some frozen peas lurking in the back of your freezer? Grab them and a bag of pre-shredded cheese, and you’ll have a stack of these crispy golden fritters on the table in 20 minutes flat! PS The more rustic they are, the better. Because rustic = ragged edges = more crispy cheesy edges. OBSESSED.', 'https://www.recipetineats.com/tachyon/2024/07/Crispy-pea-fritters_4-3.jpg', 10, 10, 20, 9, '[{"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.094, "unit": "pack of 400g"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_frozen_peas", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 2.25, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_yogurt", "quantity": {"value": 0.15, "unit": "tub of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.02, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["1/4 cup flour ((plain/all-purpose) - Note 4 gluten free)","1/4 cup cornflour / cornstarch (, or more flour (Note 1))","1/2 tsp baking powder","1/2 tsp garlic powder","1/2 tsp cooking salt ((kosher salt), or 1/4 tsp table salt)","1/4 tsp black pepper","1 large egg (~55g/2 oz)","2 tbsp milk ((any type, any fat %), or water)"],"purpose":"Batter:"},{"ingredients":["2 cups frozen peas (, still frozen (break up large clumps) (Note 2))","1 cup shredded cheese ((cheddar, tasty, colby - anything that melts, Note 3), packet shredded is fine)","3/4 cup finely sliced green onion (ok to omit)"],"purpose":"Add-ins:"},{"ingredients":["1/4 cup olive oil (, for cooking)"],"purpose":"For cooking:"},{"ingredients":["1/2 cup plain yogurt","2 tsp lemon juice","2 tsp extra virgin olive oil","1/8 tsp finely grated garlic (, optional)","Pinch each salt and pepper"],"purpose":"Lemon Yoghurt Dipping Sauce:"}]', '[{"description":"Abbreviated recipe","images":[],"step":1},{"description":"Mix the Batter ingredients. Stir in the Add-ins. Scoop, flatten, cook 1 1/2 minutes each side. Eat!","images":[],"step":2},{"description":"Full instructions","images":[],"step":3},{"title":"Lemon Yogurt Dipping Sauce","description":"Mix the ingredients together in a bowl and set aside while you cook the fritters to let the flavours meld.","images":[],"step":4},{"title":"Fritter batter","description":"Mix the Batter ingredients until combined. Add the Add-ins, then mix until the batter coats all the peas. It will look like waaaay too much peas for batter, but have faith! The batter will set as it cooks.","images":[],"step":5},{"title":"Measure & flatten","description":"Heat enough oil to cover the base of a pan on medium high (~2 1/2 tbsp). Pack a 3 tbsp cookie scoop (#20) or 1/4 cup measure firmly with the mixture. Place mound in the pan, then flatten to 1.25 / 0.5\" thick. Repeat to to fill the pan (I do 4 - 5 at a time)","images":[],"step":6},{"title":"Cook","description":"Cook for 1 1/2 minutes until the underside is golden, then turn and cook the other side for 1 1/2 minutes until golden and crispy. Transfer onto a paper towel lined tray. Repeat with remaining batter to make 9 -10 in total.","images":[],"step":7},{"description":"Serve with Lemon Yogurt Dipping Sauce!","images":[],"step":8}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner","snack"],"cuisine":["Western"],"categories":["emergency-recipes","fritters-tots-and-similar","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_29409440487b', 'en', 'US', 'Swiss Mushroom Burgers', 'Recipe video above. Big, juicy Swiss Mushrooms Burgers are a mighty vegetarian burger that at first glance, looks like a beef burger! Large mushrooms are roasted with garlic butter, topped with Swiss cheese then stuffed into fully loaded soft rolls.Only got small mushrooms? No worries, read the recipe notes!Desperate for meat? Add a meat burger pattie (beef, chicken mince/ground, or chicken breast/thigh), or even bacon and egg!Fully loaded veggie burger - add a vegetarian burger pattie (one of my signature recipes!).', 'https://www.recipetineats.com/tachyon/2020/08/Easy-Swiss-Mushroom-Burgers_7.jpg', 10, 40, 50, 4, '[{"id": "ing_mushroom", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.25, "unit": "jar of 400g"}}, {"id": "ing_ketchup", "quantity": {"value": 0.06, "unit": "bottle of 500g"}}, {"id": "ing_sriracha", "quantity": {"value": 1.0, "unit": "bottle of 400ml"}}, {"id": "ing_bread", "quantity": {"value": 4.0, "unit": "loaf"}}, {"id": "ing_lettuce", "quantity": {"value": 8.0, "unit": "head"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_french_fries", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["4+ BIG mushrooms - like portobello, BBQ flat mushrooms (20% larger than buns, or buy multiple per burger) (Note 1)","30g / 2 tbsp unsalted butter","2 garlic cloves (, finely minced)","1/2 tsp each salt and pepper","1/2 tbsp olive oil","4 slices swiss cheese (or any other cheese slice of choice)"]},{"ingredients":["3 onions (, cut into 0.7cm / 1/3\" rings)","1 tbsp olive oil","1/4 tsp each salt and pepper"],"purpose":"Onions (or use raw red onions)"},{"ingredients":["2/3 cup mayonnaise (or sour cream + pinch of salt)","2 tbsp ketchup","1 - 3 tsp Sriracha (adjust spiciness to taste)"],"purpose":"Pink Burger Sauce"},{"ingredients":["4 buns or rolls (I like brioche)","8 - 12 lettuce leaves","2 tomatoes"],"purpose":"Burgers (Note 2 for more options)"},{"ingredients":["French fries","Baked potato wedges"],"purpose":"On the side"}]', '[{"description":"Preheat oven to 220°C/450°F (200°F fan).","images":[],"step":1},{"title":"Garlic butter","description":"Place butter, garlic, salt and pepper in a heatproof jug. Microwave to melt butter, then stir.","images":[],"step":2},{"title":"Brush with butter","description":"Brush the mushroom cap with butter (smooth side), then place on a tray gills side up (ie stalk facing up). Brush remaining butter onto the rims and gills, being sure to scrape up all the garlic in the jug.","images":[],"step":3},{"title":"Olive oil","description":"Drizzle with olive oil.","images":[],"step":4},{"description":"Roast 25 minutes, then flip mushrooms. Brush with tay juices, roast a further 10 minutes or until the centre of the mushrooms are tender. {Meanwhile, cook onion, mix Sauce)","images":[],"step":5},{"title":"Top with cheese","description":"Place a slice of cheese on each mushroom, return to oven for 3 minutes just to melt the cheese.","duration":3,"images":[],"step":6},{"title":"Toast buns","description":"Place split buns in the oven at the same time - to lightly toast.","images":[],"step":7},{"description":"Assemble burgers","images":[],"step":8},{"description":"Spread base of bun with a dollop of Pink Sauce. Top with lettuce, then tomato, then mushroom, then onion. Spread lid with a lesser smear of Pink Sauce, then place on burger. Devour!","images":[],"step":9},{"description":"Mix together, use per recipe.","images":[],"step":10},{"description":"Heat oil in a large skillet over high heat. Cook onion for 5 to 7 minutes until tinged with gold and floppy. Season with a pinch of salt and pepper.","duration":6,"images":[],"step":11}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","emergency-recipes","main-dishes","mushroom-recipes","quick-and-easy","sandwiches-and-sliders","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8f047e5cdfeb', 'en', 'US', 'An excellent No Yeast Pizza Dough - quick easy homemade pizza!', 'Recipe video above. Meet your new best friend - a no yeast pizza dough that makes a quick and easy homemade pizza, fresh out of the oven in 20 minutes flat! This pizza crust without yeast is not just a sad substitute for the real deal made with yeast. It''s truly great, yet takes a fraction of the time and effort.Spread with pizza sauce, choose your favourite toppings then bake for a pizza night in!', 'https://www.recipetineats.com/tachyon/2020/05/No-Yeast-Pizza_0-1-2.jpg', 7, 13, 20, 1, '[{"id": "ing_bread", "quantity": {"value": 0.25, "unit": "loaf"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.067, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.01, "unit": "L"}}]', '[{"ingredients":["1 1/3 cups bread flour (or plain / all purpose flour, Note 2)","2 tsp baking powder","3/4 tsp salt","3/4 tsp sugar"],"purpose":"Dry ingredients:"},{"ingredients":["2 tsp olive oil (or any other oil)","1/2 cup water (cold tap water)"],"purpose":"Wet ingredients:"},{"ingredients":["1 tbsp Extra Flour (, for dusting)","2 tsp vegetable oil (optional) (, for brushing crust (or canola or other neutral oil) (Note 3))"],"purpose":"Other"}]', '[{"description":"Preheat oven to 250°C / 480°F (230°C fan) (Note 4.) Place shelf in the top quarter of the oven.","images":[],"step":1},{"description":"Spray pizza pan or baking tray lightly with oil.","images":[],"step":2},{"description":"Prepare pizza sauce and toppings. Keep shredded mozzarella in the fridge (Note 5).","images":[],"step":3},{"description":"Food processor option (40 sec):","images":[],"step":4},{"title":"Blitz","description":"Using the standard S blade, add Dry Ingredients and pulse twice. Add water and olive oil. Blitz on low for 40 seconds - it will come together into a shaggy ball (video 33 sec).","duration":0.6666666666666666,"images":[],"step":5},{"title":"Shape","description":"Sprinkle work surface with half Extra Flour, scrape dough out. Sprinkle with remaining Extra Flour and firmly shape into a ball. Proceed with rolling out steps below.","images":[],"step":6},{"description":"Hand Kneading option (3 min):","images":[],"step":7},{"title":"Mix","description":"Place Dry ingredients in a bowl, mix to combine with a rubber spatula. Add water and olive oil, mix until flour is incorporated as best you can.","images":[],"step":8},{"title":"Knead","description":"Sprinkle work surface with half Extra Flour, dip dough out. Sprinkle with remaining Extra Flour then knead for 3 to 4 minutes until it''s pretty smooth (video 38 sec), using more flour only if needed. Shape into a ball. Proceed with rolling out steps below.","duration":3.5,"images":[],"step":9},{"description":"Rolling out dough:","images":[],"step":10},{"title":"Goal dough texture","description":"Your dough should be soft and elastic, and not stick to your hands. It will not be completely smooth like yeast dough (video 38 sec)(Note 6).","images":[],"step":11},{"description":"Roll out your dough ball into a 30cm/12\" round.","images":[],"step":12},{"title":"Stretch","description":"Transfer to pizza pan, preferably with holes (for crispier base), or a baking tray (Note 7 pizza stone). Use your fingers to pull from the centre to fill the pan to the edge - avoid pinching the edges (to ensure puffy crust!).","images":[],"step":13},{"description":"Top with 1/4 cup pizza sauce and toppings of choice.","images":[],"step":14},{"description":"Brush the crust edge (just exposed edge with no toppings on it) with oil.","images":[],"step":15},{"description":"Bake 12 minutes, until the edges are crispy and golden. Cut and serve immediately!","images":[],"step":16}]', '["gluten"]', '["low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["emergency-recipes","good-to-know","pizza-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_06b5e3fcec32', 'en', 'US', 'Emergency Corn Chowder Soup', 'Recipe video above. Emergency corn chowder is a soup recipe that involves little more than popping open cans of corn and USING THE EMPTIED CANS to measure the liquids to add into the soup! Tastes just like your favourite creamy corn chowder - but faster to make!', 'https://www.recipetineats.com/tachyon/2019/09/Emergency-Corn-Chowder__1.jpg', 3, 12, 15, 3, '[{"id": "ing_oil", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_bacon", "quantity": {"value": 0.4, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_cream", "quantity": {"value": 1.6, "unit": "carton of 250ml"}}, {"id": "ing_corn", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.417, "unit": "L"}}, {"id": "ing_milk", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.02, "unit": "bunch"}}, {"id": "ing_flour", "quantity": {"value": 0.022, "unit": "kg"}}]', '[{"ingredients":["1 tsp oil ( or butter)","2 slices bacon (, streaky!)","2 garlic cloves (, minced)","400g/14oz can creamed corn (1 can)","400g/14oz can corn kernels (, drained (1 can))","1 2/3 cups (400ml) chicken stock ( / broth (1 empty can*))","3/4 cup (200ml) milk (, any fat % (1/2 empty can*))","1 potato (, diced into 1.5 cm/ 1/2\" small cubes)","1/2 tsp each salt and pepper","1 green onion (, finely sliced)"]},{"ingredients":["1/2 cup (125 ml) milk (, any fat % (1/4 empty can*))","1 1/2 tbsp cornflour / corn starch"],"purpose":"Soup thickener:"}]', '[{"description":"Place oil then bacon in pot. Turn stove onto medium high heat then cook until bacon is golden on both sides.","images":[],"step":1},{"description":"Remove bacon and chop once cooled.","images":[],"step":2},{"description":"If there''s loads of excess fat in the pot, drain some.","images":[],"step":3},{"description":"Add garlic and stir for 20 seconds. Add creamed corn, kernels, chicken stock, milk, potato, salt and pepper.","duration":0.3333333333333333,"images":[],"step":4},{"description":"Stir, bring to simmer then adjust to medium. Simmer 5 minutes until potato is just tender.","images":[],"step":5},{"title":"Soup Thickener","description":"Mix together milk and cornflour, then pour into soup.","images":[],"step":6},{"description":"Stir and simmer for 1 minute until it thickens into a creamy soup (see video for thickness).","duration":1,"images":[],"step":7},{"description":"Add more salt if needed.","images":[],"step":8},{"description":"Ladle into bowls, top with green onion and bacon. Devour!","images":[],"step":9}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","emergency-recipes","quick-and-easy","soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7282f7fd574c', 'en', 'US', '12 Minute Baked Salmon Fajitas', 'Recipe video above. Here is a big Fajita dinner spread that''s all cooked in the oven at the same time! Caramelised cubes of salmon heavily seasoned with a Fajita spice blend, colourful fajita vegetables and a pile of steamy warm tortillas, just add sliced avocado and make a simple taco sauce while they''re in the oven. I used my new Creamy Jalapeño Sauce but if that''s out of reach or you''re worried about spiciness (it''s got a little zing), either use my Instant Pink Taco Sauce or just plain sour cream.', 'https://www.recipetineats.com/tachyon/2026/05/Tray-bake-salmon-fajitas-7.jpg', 18, 12, 30, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_capsicum", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_cream", "quantity": {"value": 0.004, "unit": "carton of 250ml"}}, {"id": "ing_pink_taco_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_tortillas", "quantity": {"value": 12.0, "unit": "pack of 8"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["600g / 1.2lb skinless salmon fillets (, cut into 2.5cm/1\" cubes (Note 1))"]},{"ingredients":["1 1/2 tbsp extra virgin olive oil","2 tsp smoked paprika (or regular paprika)","1 tsp EACH garlic, onion, cumin powder","1/2 tsp dried oregano","3/4 tsp cooking salt / kosher salt (halve for cooking salt, double for flakes)","1 tsp (tightly packed) brown sugar (helps the salmon brown!)","1/4 tsp cayenne pepper ((optional), for small spiciness)"],"purpose":"Fajita seasoning:"},{"ingredients":["3 capsicums (1 each red, yellow, green) (, deseeded, cut into 0.75cm / 1/3\" strips)","1 red onion (, cut into 0.75cm / 1/3\"wedges)","1 1/2 tbsp extra virgin olive oil","1 garlic clove (, minced using garlic press or knife)","1/2 tsp cooking salt / kosher salt"],"purpose":"Fajita Vegetables:"},{"ingredients":["Creamy Jalapeno Sauce","Pink Taco Sauce (2 ingredients!)","Sour cream"],"purpose":"CHOOSE a fajita sauce:"},{"ingredients":["12 - 16 taco-size tortillas (, corn or flour (3 to 4 per person, depending on size), wrapped in foil (make 2 parcels))","1 avocado (, sliced)","2 tbsp roughly chopped coriander ((cilantro), optional but recommended)","Lime wedges (, optional)"],"purpose":"Serving:"}]', '[{"description":"Toss Vegetable ingredients on a tray. Toss salmon with Fajita Seasoning, spread on separate tray lined with wrinkled foil. Bake 12 minutes at 240°C/465°F (220°C fan) along with foil wrapped tortillas. Make sauce. Serve!","images":[],"step":1},{"description":"Preheat oven to 240°C/465°F (220°C fan-forced).","images":[],"step":2},{"title":"Crinkled foil trick for baking fish","description":"Lightly scrunch up foil, then gently unfold it so it stays wrinkled. Lots of little pointing bits = good! The wrinkles lift the fish slightly, preventing sticking and soggy undersides – clever Japanese fish-cooking trick (thanks mum!). Place on one side of the tray and fold the edges over the rim to secure. Repeat with another sheet to cover the whole tray.","images":[],"step":3},{"title":"Fajita flavour fish","description":"Mix the Fajita seasoning ingredients in a bowl, it should be like a thin paste. Add fish and toss to coat. Spread out on the foil so the salmon is not touching each other.","images":[],"step":4},{"title":"Toss veg","description":"On a separate large tray, toss capsicum and onion with the oil, garlic and salt. Spread it out in a single layer.","images":[],"step":5},{"description":"Wrap stack of tortillas in foil (make 2 parcels).","images":[],"step":6},{"title":"Bake everything","description":"Put the salmon on the top shelf, vegetables on the middle shelf and tortillas into the oven (I put them on the floor of the oven but don’t do this if your heat element is there, mine comes from the back). Bake 12 minutes, or until the salmon flakes (don''t turn or toss).","images":[],"step":7},{"title":"Sauce","description":"Meanwhile, put the sauce ingredients in a small jug and blitz with stick blender until smooth.","images":[],"step":8},{"title":"Lay everything out","description":"Transfer the salmon and vegetable onto a serving platter, pour all tray juices over. Place warmed tortillas, sauce, avocado, lime wedges and coriander on the side.","images":[],"step":9},{"title":"Making a fajita","description":"Take a warm tortilla. Stuff with a little vegetables, place 2 pieces of salmon on then flake into large chucks. Tuck in avocado, drizzle with sauce, lime juice, sprinkle with coriander, devour!","images":[],"step":10}]', '["fish","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Mexican","Tex-Mex"],"categories":["fajitas","mains","mexican-recipes","one-pot-recipes","other","salmon-recipes","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3b17e816fe02', 'en', 'US', 'Crispy Salt & Pepper Squid', 'Recipe video above. It only took us 3 years to crack the ultimate, truly crispy Salt and Pepper Squid! Hand on heart, this is crispier than any squid I''ve had in a restaurant, ever. The fry batter is light, super crunchy and not greasy at all. In fact, it''s so crispy it stays crispy even when it''s stone cold!After eliminating rice flour, potato flour and tapioca, we found the perfect ratio of flour to cornflour (cornstarch) that fries up crunchy in mere minutes, before the squid can overcook. But the final key was refrigerating the batter for 30 minutes. This allowed the gluten to develop so the batter clings to the slippery squid better and doesn''t fry up chewy or greasy.', 'https://www.recipetineats.com/tachyon/2024/02/Salt-and-pepper-squid-in-a-bowl.jpg', 15, 0, 15, 3, '[{"id": "ing_whole_baby_squid", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_squid_tubes", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.25, "unit": "pack of 400g"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 0.017, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_water", "quantity": {"value": 0.167, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 3.0, "unit": "bottle"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.188, "unit": "jar of 400g"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}]', '[{"ingredients":["700 g / 1.4 lb medium whole baby squid","500 g / 1 lb squid tubes (, already cleaned)"],"purpose":"Squid – choose (Note 1):"},{"ingredients":["2/3 cup cornflour / cornstarch","1/3 cup plain / all-purpose flour","1/2 tsp baking powder","1/2 tsp cooking / kosher salt","1/4 tsp white pepper powder","2/3 cup cold tap water"],"purpose":"Batter (Note 2):"},{"ingredients":["3 – 4 cups vegetable or canola oil (~4cm / 1.5\" depth in a pot)","Cooking / kosher salt ( - just a pinch!)","White pepper powder"],"purpose":"Cooking / seasoning:"},{"ingredients":["1/2 cup whole egg mayonnaise ( or kewpie)","1/2 tsp finely grated garlic"],"purpose":"Easy aioli (garlic mayonnaise):"}]', '[{"description":"Preparing squid:","images":[],"step":1},{"description":"Cut one side of the squid tube to lay it out in one flat piece. Pat both sides dry with a paper towel.","images":[],"step":2},{"description":"Lightly score the inside with a small sharp knife in 1.5 cm / 0.6\" diamonds (don''t cut all the way through). (Note 3)","images":[],"step":3},{"description":"Cut the squid into pieces 5 x 2cm (2 x 1\") rectangles (approximately).","images":[],"step":4},{"description":"Mix the ingredients together in a bowl and set aside for at least 20 minutes (up to 24 hours).","images":[],"step":5},{"title":"Batter","description":"Whisk the flour, cornflour, baking powder and salt in a bowl. Then whisk in water until smooth. Refrigerate for 30 minutes. (Note 4)","duration":30,"images":[],"step":6},{"title":"Heat oil","description":"Fill small heavy based pot or large saucepan with 4cm / 1.5\" of oil. Heat to 160°C/320°F on medium high heat. (I use a Thermapen to check the temp)","images":[],"step":7},{"description":"Give the batter a quick whisk then add all the squid in a toss to coat. (Including tentacles if using baby squid - it''s the crunchiest!)","images":[],"step":8},{"title":"Batter","description":"Cook the squid in 3 batches. Pick up some squid and let the excess batter to drip off. Careful place in the oil. Use chopsticks to seperate the pieces that stick together.","images":[],"step":9},{"description":"Fry baby squid for 2 minutes or the regular squid tubes for 3 minutes until light golden. Use a spider or slotted spoon to remove the squid on a paper towel lined tray.","duration":2,"images":[],"step":10},{"title":"Repeat","description":"Fry remaining squid, making sure the oil comes back to temperature before cooking batches 2 and 3.","images":[],"step":11},{"title":"Fry 2","description":"crisp it!","images":[],"step":12},{"title":"Increase oil temp","description":"Increase the stove to high and bring the the oil up to 200°C/390°F.","images":[],"step":13},{"title":"Bowl","description":"Line a large mixing bowl with double layer of paper towels.","images":[],"step":14},{"title":"Fry","description":"Place half of the squid in the oil (it''s ok to crowd the pot). Cook for 1 1/2 minutes, until it becomes deep golden and crispy. Remove into the bowl. Bring the oil back up to 200°C/390°F then fry the remaining squid.","images":[],"step":15},{"title":"Season","description":"Remove paper towel. Taste first then sprinkle lightly with as much salt and pepper as you want (the batter has salt in it already). Toss well.","images":[],"step":16},{"description":"Serve:","images":[],"step":17},{"description":"Pour into a serving bowl and serve with aioli! This batter is so good, it will stay crispy even once the squid has gone cold.","images":[],"step":18}]', '["egg","gluten","shellfish"]', '[]', '{"mealType":["snack","dinner"],"cuisine":["Western"],"categories":["deep-fried-recipes","finger-food","iconic-dishes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_484b53b23b59', 'en', 'US', 'Cajun Baked Salmon Bites', 'Recipe video above. Cajun Baked Salmon Bites is just a really tasty, no-fuss way to cook salmon, fast (12 minutes!). Cut into cubes so the Cajun flavour hits every bite, then bake in a hot oven so it browns without overcooking the inside. No stove splatter, yay!You''ll love the crinkled foil tray lining used here - it''s a nifty Japanese fish-baking tip. Crinkled foil = no sticking, no soggy underside on the salmon, plus less washing up (no rack). YAY!Serve with whatever your heart desires - stuffed into tacos, make rice bowls, add to salads, eat off the tray. You just can''t go wrong!', 'https://www.recipetineats.com/tachyon/2025/11/Cajun-baked-salmon_5.jpg', 7, 12, 19, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.025, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.013, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}]', '[{"ingredients":["4 salmon fillets (, skinless, cut into 2.5cm / 1\" cubes (~600 - 700g / 1.2 - 1.4lb total))"]},{"ingredients":["2 tsp paprika (regular/sweet, smoked also lovely)","3/4 tsp cooking salt / kosher salt (halve for table salt, +50% for flakes)","1 tsp onion powder","1 tsp garlic powder (don''t sub with fresh garlic, will burn)","1/4 tsp dried thyme","1/4 tsp black pepper","1/4 tsp cayenne pepper (, optional for slight spiciness)","2 1/2 tsp brown sugar (, tightly pack the teaspoons)","2 tbsp olive oil"],"purpose":"Cajun spice mix (Note 1):"}]', '[{"description":"Coat salmon with Cajun seasoning, bake on crumpled foil 12 minutes at 240°C/460°F (220°C fan-forced) until lightly browned. Enjoy!","images":[],"step":1},{"description":"Preheat the oven to 240°C/460°F (220°C fan-forced).","images":[],"step":2},{"title":"Crinkled foil trick","description":"Lightly scrunch up foil, then gently unfold it so it stays wrinkled. Lots of little pointy bits = good!.Place on the tray and fold the edges to secure, repeat with another sheet to cover the whole tray. The wrinkles lift the fish slightly, preventing sticking and soggy undersides - clever Japanese fish-cooking trick!","images":[],"step":3},{"title":"Coat salmon","description":"Put the Cajun Spice mix ingredients in a bowl and mix. Add salmon and toss to coat. Spread on the foil (the more spaced out they are, the better they colour).","images":[],"step":4},{"description":"Bake 12 minutes (don''t turn). Remove salmon from the tray (so they don''t keep cooking) then enjoy!","images":[],"step":5},{"description":"For Cajun Salmon Rice Bowls pictured:","images":[],"step":6},{"title":"Photos in post","description":"rice, lettuce, tomato, radish, avocado, Cajun salmon bites.","images":[],"step":7},{"title":"Video","description":"Rice, Cajun salmon bites, roasted corn avocado salsa - made at the same time as the salmon (Note 2).","images":[],"step":8},{"title":"Sauces and garnishes for both bowls","description":"Peri-naise or leftover pink Gyros sauce (or just kewpie/regular mayo mixed with sriracha or ketchup), chopped coriander or green onion.","images":[],"step":9}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Cajun","Western"],"categories":["fish-recipes","mains","other","quick-and-easy","salmon-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8b39192909dd', 'en', 'US', 'Seafood Chowder', 'Recipe video above. This is a seafood soup so good, it''s hard to believe it''s made with cheap ''n cheerful marinara mix and store-bought stock. Using chicken rather than store-bought fish stock (awful stuff!), a cheeky dash of fish sauce rather than salt and bacon are some of the flavour enhancers we deploy here!Of course, if you use homemade fish stock and a hand-picked mix of fresh seafood, it will be upmarket-restaurant-worthy. :) Also see FAQ for more vegetable options.', 'https://www.recipetineats.com/tachyon/2025/09/Seafood-chowder_9.jpg', 20, 20, 40, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.65, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_bacon", "quantity": {"value": 0.5, "unit": "pack of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_chardonnay", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.65, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parsley", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["650g/ 1.3lb seafood marinara mix or mixed fresh seafood - fish (, squid, prawns, cooked mussel meat (Note 1))","50g (3 tbsp) unsalted butter","100g/ 4oz streaky bacon (, chopped into 1.5cm / 1/2\" squares)","2 cloves garlic (, finely minced)","1/2 cup chardonnay (or other dry white wine (can skip))","1/3 cup flour (, plain/all-purpose (Note 3 for gluten-free))","1 litre (4 cups) chicken stock/broth, low sodium OR homemade fish stock (avoid store-bought fish stock) (Note 2)","2 medium carrots (, peeled, cut into 7mm / 1/3\" pieces (~1 1/2 cups))","2 large potatoes (any type fine), peeled, cut into 1cm / 0.2\" cubes (~2 1/2 cups)","1 cup thickened cream / heavy cream (sub milk for lighter option)","1 cup corn (frozen or canned, drained)","2 tsp fish sauce","Pinch white pepper (substitute black pepper)"]},{"ingredients":["3 tbsp chives or parsley (, finely chopped, for garnish)","Crusty bread ( or better yet, garlic bread!)"],"purpose":"SERVING"}]', '[{"description":"Cook bacon in butter, remove. Sauté garlic, deglaze with white wine, make roux. Add stock, simmer potato, carrots and bacon 10 min. Add cream, corn, fish sauce, pepper, raw seafood - simmer 3 min. Stir in cooked seafood, taste for salt. Serve!","images":[],"step":1},{"title":"Marinara mix","description":"Separate cooked seafood (usually mussels, sometimes prawns/shrimp) from raw seafood. We put them in at different times.","images":[],"step":2},{"description":"Cut any large pieces of fish into 2.5cm / 1\" cubes.","images":[],"step":3},{"title":"Bacon","description":"In a heavy-based pot, melt the butter over medium heat. Add bacon and cook for 3 - 4 minutes until the edges are light golden. Use a slotted spoon to remove into bowl, leaving fat in the pot.","duration":3.5,"images":[],"step":4},{"title":"Deglaze","description":"Add the garlic and cook for 10 seconds (don''t let it brown). Add the wine, simmer rapidly on high for 3 minutes, scraping the base to loosen any golden bacon bits, until the wine is mostly evaporated.","duration":0.16666666666666666,"images":[],"step":5},{"title":"Roux","description":"Reduce heat down to medium, add the flour and mix for 1 minute (\"roux\").","duration":1,"images":[],"step":6},{"title":"Broth","description":"While stirring, pour in about 1 cup of the stock and mix to dissolve the roux - it will thicken into a paste. Add the remaining stock and stir well until lump free (use a whisk if needed).","images":[],"step":7},{"title":"Simmer 10 minutes","description":"Increase heat to high, bring to the boil, add the carrots, potatoes and bacon. Lower heat to medium and simmer for 10 - 12 minutes, or until the carrots are just about done.","duration":11,"images":[],"step":8},{"title":"Simmer raw seafood 3 minutes","description":"Add the cream, fish sauce, pepper, corn and raw seafood. Simmer for 3 minutes until the fish is just cooked (test - flesh should flake).","duration":3,"images":[],"step":9},{"title":"Cooked seafood","description":"Stir in cooked seafood, taste and add more salt if needed (I don''t).","images":[],"step":10},{"title":"Serve","description":"Ladle into bowls, sprinkle with chives. Serve with warm crusty bread for dunking!","images":[],"step":11}]', '["fish","gluten","milk","shellfish"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["fish-recipes","mains","other","seafood-recipes","soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_070cb433311d', 'en', 'US', 'Lemon garlic salmon tray bake - easy & healthy!', 'Recipe video above. A tasty salmon tray bake recipe that''s as simple as it is healthy. Salmon infused with an assertive lemon garlic marinade cooks in just 11 minutes alongside parmesan asparagus and blistered cherry tomatoes. No stove splatter - yay! Green beans would also work great, or thin broccolini stems (and the florets go crunchy!). Shower with parmesan and squeeze of lemon for an easy finishing touch.', 'https://www.recipetineats.com/tachyon/2024/02/Lemon-garlic-salmon-tray-bake_1.jpg', 10, 11, 21, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.025, "unit": "jar of 200g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_es_asparagus", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 0.8, "unit": "punnet of 250g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["4 x 180g/6 oz salmon fillets (, skin on or off, doesn''t matter (Note 1))"]},{"ingredients":["1 tsp lemon zest (1 lemon)","1 tbsp lemon juice","2 tbsp extra virgin olive oil","1 tsp dijon mustard (Note 2)","2 garlic cloves (, grated using microplane (Note 3))","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Marinade slather:"},{"ingredients":["3 bunches asparagus (, woody ends snapped or trimmed off (Note 4))","200g/ 7 oz cherry tomatoes (or grape tomatoes, 1 Aussie punnet)","2 tsp extra virgin olive oil","1/4 tsp each salt and pepper"],"purpose":"Vegetables (optional):"},{"ingredients":["Olive oil spray","Parmesan (, finely grated)","Lemon wedges or slices (, optional)","Parsley (, finely chopped, optional)","Crusty bread or toast (, for serving)"],"purpose":"Cooking & serving:"}]', '[{"title":"Lemon garlic paste","description":"Mix the marinade ingredients in a small bowl. Slather onto the top and sides of the salmon. If time permits, marinade for 1 hour. Otherwise, proceed with recipe.","images":[],"step":1},{"description":"Preheat oven grill / broiler to 280°C/525°F or as high as yours goes. Place the oven shelf 20 cm /8\" from the heat source.","images":[],"step":2},{"title":"Prepare tray","description":"Toss the asparagus and cherry tomatoes with the olive oil, salt and pepper. Spread out on a large tray then clear space for the salmon. Place salmon on the tray leaving a bit of space between each. Spray surface of salmon with oil.","images":[],"step":3},{"title":"Cook","description":"Grill/broil for 11 minutes or until the salmon is done - the flesh should flake, the internal temperature should be 50°C/122°F (Note 5).","duration":11,"images":[],"step":4},{"title":"Serve","description":"Transfer salmon and vegetables to plate. Grate parmesan over the vegetables. Squeeze lemon juice over the salmon, sprinkle with parsley. Eat!","images":[],"step":5}]', '["fish","gluten","milk","mustard"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","fish-recipes","mains","one-pot-recipes","other","quick-and-easy","salmon-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9f3589a5e9ed', 'en', 'US', 'Calabrian Fish Ragu', 'Recipe video above. This is a fish pasta in a richly spiced fish ragu pasta sauce. The spice mix is based on njuda, the bold flavoured spreadable Calabrian salami paste that''s rising in popularity in the restaurant scene! It''s a great way to make fish stretch further, cooked in a unique way that''s outrageously delicious with big, bold Southern Italian flavours.No stale bread? Use panko instead. See notes. 3 servings? I know it''s a little odd, but the spice mix didn''t scale down neatly to make pasta for 2! (3/8 tsp nutmeg?!). Leftovers are always delicious. :)', 'https://www.recipetineats.com/tachyon/2023/10/Calabrian-fish-ragu-pasta_6-1.jpg', 10, 25, 35, 3, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_nutmeg_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}]', '[{"ingredients":["250g/ 8 oz firm white fish fillets (, skinless, boneless, cut into 2 cm / 0.8\" cubes (barramundi, snapper, cod - Note 1))","3/4 tsp black peppercorns (Note 2 for ground option)","1 tsp fennel seeds (Note 2 for ground option)","1 tbsp smoked paprika (sub ordinary paprika)","1/2 tsp red chilli flakes ((red pepper flakes), feel free to reduce/omit)","1/2 tsp nutmeg powder","1/2 tsp caster / superfine sugar","3/4 tsp cooking / kosher salt","3 tbsp extra virgin olive oil","2 tbsp tomato paste"],"purpose":"Calabrian spiced fish:"},{"ingredients":["250g/8 oz linguine pasta (or fettuccine, spaghetti)","1 tbsp cooking / kosher salt (, for pasta water)","1 1/2 tbsp extra virgin olive oil","3 garlic cloves (, finely minced)","3/4 cup tomato passata (US: tomato puree, Note 3)"],"purpose":"Pasta:"},{"ingredients":["1 tbsp finely chopped parsley","Parmesan cheese (, finely grated, for serving)"],"purpose":"Garnish:"},{"ingredients":["1 cup stale bread like sourdough, ciabatta (, crusts removed, torn/chopped into irregular 1cm/0.4\" pieces (Note 4))","2 tsp extra virgin olive oil","1 pinch cooking / kosher salt"],"purpose":"Pangrattato"}]', '[{"title":"Toast & grind","description":"Preheat a large deep skillet or pot over medium heat (Note 5), no oil. Toast black peppercorn and fennel for 1 1/2 to 2 minutes until it smells fragrant and the fennel is lightly browned. Transfer to a mortar and use a pestle and grind to a powder while still hot.","images":[],"step":1},{"title":"Coat fish","description":"Transfer to a medium bowl with remaining Calabrian spiced fish ingredients. Stir well with a spatula until combined. Set aside.","images":[],"step":2},{"title":"Cook pasta","description":"Boil 3 litres of water with the cooking salt. Cook pasta per packet directions minus 1 minute. Just before draining, scoop out 1 1/2 cups pasta cooking water. Then drain in a colander and leave until ready to use.","images":[],"step":3},{"title":"Calabrian fish ragu","description":"While the pasta is cooking, heat olive oil in the same skillet you used to toast the fennel on medium high. Add garlic and cook for 1 minute. Add the fish. Cook for 2 minutes, stirring regularly. Add tomato passata. Simmer for 5 minutes, stirring occasionally. Add 1 cup of the reserved pasta cooking water and simmer for 2 minutes.","duration":1,"images":[],"step":4},{"title":"Toss pasta","description":"Add pasta and 3/4 of the parsley. Toss for 1 minute to coat the pasta with the sauce. Most of the fish will break up into flakes but some will remain in larger chunks - this is good! We don''t want disintegrated mush, nor giant chunks. Once the pasta turns red and the sauce and fish bits are clinging to the pasta straws, remove from heat and divide between bowls immediately.","duration":1,"images":[],"step":5},{"title":"Serve","description":"Sprinkle with pasta, pangrattato and parmesan. Eat immediately!","images":[],"step":6},{"description":"Preheat oven to 180°C / 350°F (160°C fan-forced).","images":[],"step":7},{"description":"Toss bread, oil and salt in a small bowl. Spread on a tray and bake for 10 minutes, tossing at the 5 minute mark, or until light golden and fully crisp.","duration":10,"images":[],"step":8}]', '["fish","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian-esque"],"categories":["fish-recipes","italian-recipes","mains","other","pasta-recipes","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_b262f1b1519c', 'en', 'US', 'Creamy fish on potato gratin', 'Recipe video above. This is a one-pan meal with fish baked on top of a potato gratin in a creamy sauce with a golden crunchy topping. It''s a cross between a casserole, gratin and a pie. The idea is that the panko acts like a lid, keeping the fish succulent as it bubbles away in the cream while the gratin soaks up the tasty fish juices.This is a fabulous cosy, rustic oven baked fish recipe that''s effortless yet company worthy!', 'https://www.recipetineats.com/tachyon/2023/05/Creamy-baked-fish-on-potato-gratin_7.jpg', 10, 45, 55, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_leeks", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_bread", "quantity": {"value": 0.141, "unit": "loaf"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}]', '[{"ingredients":["4 x 160g/5oz white fish fillets (, ~2cm / 0.8\" thick, skinless (barramundi, snapper, tilapia, cod, salmon - Note 1))","1/2 tsp cooking/kosher salt","1/4 tsp black pepper"]},{"ingredients":["3 tbsp / 50g unsalted butter","2 large leeks (, white and pale green part only, washed, cut in half lengthways, sliced 5mm / 0.2\" thick OR 2 onions (Note 2))","3 garlic cloves (, minced)","2 medium starchy potatoes (250g / 8oz each), peeled (Note 3)","3/4 tsp cooking/kosher salt","1/2 tsp black pepper","1/2 cup dry white wine (, any type, sub more veg stock (Note 4))","1/2 cup vegetable stock/broth (, low sodium)","1 cup thickened/heavy cream"],"purpose":"Potato gratin:"},{"ingredients":["3/4 cup panko breadcrumbs","2 tbsp extra virgin olive oil","1/4 cup parmesan (, finely shredded)"],"purpose":"Crunchy topping:"}]', '[{"description":"Preheat the oven to 180°C/350°F (160°C fan) with a shelf in the middle.","images":[],"step":1},{"title":"Potatoes","description":"Cut the potatoes into quarters, then sliced 4mm / 1/6\" thick. Place cut potato in a large bowl of water (prevents from going brown, removes excess starch so it cooks quicker). Drain before use.","images":[],"step":2},{"title":"Crunchy topping","description":"Mix panko and olive oil in a bowl. Then stir in parmesan.","images":[],"step":3},{"title":"Season fish","description":"Sprinkle salt and pepper on both sides of the fish fillets. Set aside.","images":[],"step":4},{"title":"Sauté","description":"Melt butter in a large oven-proof skillet (30cm/12\") over high heat until foamy. Add leek and garlic, then cook for 3 minutes.","duration":3,"images":[],"step":5},{"title":"Sauté potatoes","description":"Add potato, salt and pepper. Cook for 6 minutes, stirring regularly. The potatoes should be half cooked at this stage.","duration":6,"images":[],"step":6},{"title":"Reduce wine and stock","description":"Pour in white wine. Simmer rapidly until it is mostly evaporated - about 1 minute. Pour in stock, then simmer for 1 1/2 minutes or until reduced by half.","images":[],"step":7},{"title":"Top with fish","description":"Turn the stove off. Place fish on top of the potatoes, presentation side up. (Note 1) Pour cream all over, aiming for full coverage. Sprinkle with panko breadcrumbs.","images":[],"step":8},{"title":"Bake for 30 minutes","description":"I know this sounds like a long time but the fish stays succulent!","duration":30,"images":[],"step":9},{"title":"Colour topping","description":"Switch to the oven grill (broiler) on high and move the skillet up to the top shelf. Grill/broil 4 minutes or until golden.","images":[],"step":10},{"title":"Rest","description":"Remove and rest for 5 minutes, then serve! Eat the fish and gratin together with each mouthful for maximum eating pleasure!!","duration":5,"images":[],"step":11}]', '["fish","milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["French-style","Western"],"categories":["fish-recipes","mains","one-pot-recipes","other","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a9d95f30fe20', 'en', 'US', 'Kedgeree - British curried rice and fish', 'Recipe video above. Traditional English smoked fish and rice dish - think of it as an English biryani! Smoked haddock or cod tossed through a butter spiced rice studded with eggs, this is true fusion food at its best.', 'https://www.recipetineats.com/tachyon/2023/04/Kedgeree_3.jpg', 15, 30, 45, 5, '[{"id": "ing_chicken_stock", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_smoked_haddock_or_cod", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_rice", "quantity": {"value": 337.5, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_curry_leaves", "quantity": {"value": 15.0, "unit": "kg"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.15, "unit": "jar of 40g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.2, "unit": "jar of 50g"}}, {"id": "ing_turmeric", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 3.0, "unit": "carton of 12"}}]', '[{"ingredients":["4 cups/ 1 litre chicken stock/broth (, low-sodium (Note 5))","500g/1 lb smoked haddock or cod (, skin-on (or other smoked fish, Note 1))","2 1/4 cups long grain rice (, uncooked)","75g / 5 tbsp unsalted butter","15 curry leaves (optional, Note 2)","6 green cardamom pods (, lightly crushed (Note 3))","1 brown onion (, diced)","2 garlic cloves (, finely minced)","2 tsp curry powder (anything! Use spicy if you want, I use mild)","1/2 tsp turmeric powder","1 cup frozen peas (, thawed)","1/2 cup coriander/cilantro leaves (, roughly chopped (sub green onion or parsley))","3 hard boiled eggs (, halved or quartered (9 minute cook))"]}]', '[{"title":"Poach fish","description":"Bring chicken stock to a boil in a large saucepan or small pot. Place fish in (it should all be just about submerged, Note 4) and adjust heat so the stock is barely rippling. Poach it gently for 8 minutes or until the fish flakes apart. Remove fish onto a large plate.","duration":8,"images":[],"step":1},{"title":"Flake fish","description":"When cool enough to handle, discard skin (gently scrape with a butter knife) and flake fish into large pieces, checking for any bones.","images":[],"step":2},{"title":"Reserve stock","description":"Measure out 1/2 cup of the poaching liquid and set aside for later (drizzle on at end to juice up the rice).","images":[],"step":3},{"title":"Cook rice 13 min","description":"Add rice into the poaching liquid in the saucepan. Bring to a simmer over high heat. Cover with lid then reduce heat to low. Cook for 13 minutes.","duration":13,"images":[],"step":4},{"title":"Rest rice 10 min","description":"Remove the saucepan from the stove with the lid on and rest for 10 minutes. Fluff rice using a rubber spatula.","duration":10,"images":[],"step":5},{"title":"Curried butter","description":"While the rice is resting, melt the butter in a very large (30cm/12\") non stick skillet or pot, over medium-high heat. Add the cardamom pods and curry leaves and stir for 30 seconds. Add the onions, garlic and sauté for 5 minutes until browning at the edges, stirring regularly.","duration":0.5,"images":[],"step":6},{"title":"Toss rice","description":"Lower heat to medium. Stir in the curry powder and turmeric, and then the rice. Toss the rice in the spiced butter until well coated and uniformly yellow. Pour over the reserved 1/2 cup of fish poaching stock, and toss to mix through (it moistens the rice).","images":[],"step":7},{"title":"Season with salt if required","description":"Check the rice for seasoning. If you used store-bought packet stock, you should find there''s enough natural saltiness already. Otherwise season to taste and mix rice well.","images":[],"step":8},{"title":"Peas & fish","description":"Stir through the peas and most of the coriander (hold some back for garnish). Then gently fold through the fish, taking care to keep some pieces in large chunks.","images":[],"step":9},{"title":"Serve","description":"Spoon out rice onto one large platter or individual plates to serve. Top with boiled egg halves, and garnish with the remaining coriander. EAT!","images":[],"step":10}]', '["egg","fish","milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["British","English"],"categories":["fish-recipes","mains","other","quick-and-easy","rice-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5a76b93cf025', 'en', 'US', 'Chilli Lime Fish', 'Recipe video above. Pan-seared chunks of white fish are coated in a syrupy, spicy lime sauce in this dish loosely based on pla tort sahm rot, a traditional Thai street stall favourite. It tastes a bit like a fish version of everybody''s favourite Chilli Garlic Prawns. Very quick to make, it''s loaded with big flavours!Spice level: fairly spicy but not blow-your-head-off. See Note 4 for how to control the spiciness.', 'https://www.recipetineats.com/tachyon/2022/10/Chilli-Lime-Fish-cookbook-reference-photo_5.jpg', 10, 8, 18, 2, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.33, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_sriracha", "quantity": {"value": 0.075, "unit": "bottle of 400ml"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_lime", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_rice", "quantity": {"value": 37.5, "unit": "pack"}}, {"id": "ing_steamed_asian_greens", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["330g / 11 oz thin white fish fillets (~1cm / 0.4\" thick) (, skinless, cut into 6cm / 2.5\" (or so) squares pieces (Note 1))","1/4 tsp cooking/kosher salt","1/4 cup rice flour or ordinary flour (Note 2)","2 tbsp canola oil"],"purpose":"Fish:"},{"ingredients":["2 tsp sesame oil","2 garlic cloves (, finely minced with a knife (Note 3))","2 tsp ginger (, finely minced with a knife (Note 3))","1 tsp chilli flakes / red pepper flakes (Note 4)","2 tbsp sriracha (Note 4)","2 tsp light soy sauce or fish sauce (Note 5)","3 tbsp brown sugar","1/2 cup water","2 tbsp lime juice"],"purpose":"Sauce:"},{"ingredients":["2 tbsp coriander/cilantro leaves","1 tbsp large red chilli (, finely sliced)","Lime wedges"],"purpose":"Garnishes (optional):"},{"ingredients":["Rice of choice","Steamed Asian greens"],"purpose":"Serve with:"}]', '[{"title":"Dust fish","description":"Sprinkle with salt, dust with rice flour, shake off excess.","images":[],"step":1},{"title":"Cook fish","description":"In a non-stick skillet, heat oil over medium-high heat. Cook the fish until golden on each side then remove to a plate.","images":[],"step":2},{"title":"Fish cooking times","description":"Thin fillets 1 cm / 2/5\" thick: 1 1/2 minutes each side; thicker fillets 1.5 - 1.75cm / 0.6 - 0.75\" thick 2 minutes each side) or until the internal temperature is 55°C / 130°F. Remove fish to a plate and set aside.","images":[],"step":3},{"title":"Sauté aromatics","description":"In the same pan, add sesame oil on medium heat. Cook garlic, chilli and ginger until golden - about 20 seconds.","images":[],"step":4},{"title":"Sauce","description":"Add everything else except lime juice. Stir, simmer, then reduce until syrupy - about 2 minutes. Add lime juice and stir. (If sauce gets too thick, add water)","images":[],"step":5},{"title":"Coat fish","description":"Return fish into sauce, turning to coat in the sauce.","images":[],"step":6},{"description":"Serve over rice, with garnishes of choice! Pictured with steamed baby pak choy tossed with Asian Sesame Dressing.","images":[],"step":7}]', '["fish","gluten","sesame","soy"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Modern Asian","Thai-ish"],"categories":["fish-recipes","mains","other","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9a562a1e1042', 'en', 'US', 'Italian Crusted Sardines', 'Recipe video above. Here''s the perfect recipe for the sardine-shy: coat filleted sardines with an assertive Italian crust then pan fry until crispy. It''s an explosion of flavour and texture cooked in 2 1/2 minutes flat, making it one of the fastest fish recipes around!Excellent recipe for the sardine wary or first timers - no bones to worry about, and the intense Italian flavours balance out any concerns about the fishy flavour of sardines.Serve on crostini with a fresh salad on the side.', 'https://www.recipetineats.com/tachyon/2021/09/Mediterranea-Crusted-Sardines_4-Square.jpg', 10, 5, 15, 2, '[{"id": "ing_butter", "quantity": {"value": 8.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 0.094, "unit": "loaf"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_pinenuts", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_fish_fillets", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_baby_capers", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.3, "unit": "pack of 200g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_onion", "quantity": {"value": 20.0, "unit": "pack of 1kg"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["8 butterflied sardines (20g each = 160g total, Note 1)","1/4 tsp salt","1/8 tsp pepper","1/4 tsp smoked paprika (sub normal or sweet)","3 tbsp extra virgin olive oil"],"purpose":"Sardines:"},{"ingredients":["1/2 cup panko breadcrumbs (Note 2)","1 garlic clove (, finely minced)","2 tsp toasted pinenuts (, finely chopped (Note 3))","2 anchovies fillets (, finely minced (sub 3/4 tsp paste, Note 4))","1 tsp baby capers (, drained, finely chopped (Note 5))","1 tsp lemon zest","4 tbsp pecorino cheese (, finely grated (or parmesan))","2 tsp fresh oregano (, chopped (sub 1/2 tsp dried))","1 tbsp extra virgin olive oil"],"purpose":"Italian Crust:"},{"ingredients":["4 tsp red onion, finely chopped (~1/4 small onion)","1 tsp large red chilli, finely chopped (, deseeded)","2 tsp parsley (, finely chopped)"],"purpose":"Topping:"}]', '[{"title":"Mix Crust","description":"Mix the Italian Crust ingredients in a bowl. Spread on a small plate.","images":[],"step":1},{"title":"Mix Topping","description":"Mix the Topping together in another small bowl.","images":[],"step":2},{"description":"Crust sardines:","images":[],"step":3},{"title":"Prepare sardines","description":"Pat sardines dry with paper towel. Sprinkle both sides of each sardine with the salt and pepper. Sprinkle the skin side only with the paprika.","images":[],"step":4},{"title":"Crust flesh side","description":"Press flesh side only firmly into the breadcrumbs - it won''t completely cover, that''s what we want (Note 6). Place on plate, breadcrumb side up. Repeat with remaining sardines.","images":[],"step":5},{"description":"Cooking sardines:","images":[],"step":6},{"title":"Pan fry sardines","description":"Heat oil in a large non stick skillet over medium high heat. Place sardines in, skin side down. Cook for 60 seconds, then carefully turn. Cook the crust side for 90 seconds or until golden and crispy.","duration":1,"images":[],"step":7},{"title":"Topping & oil drizzle","description":"Remove sardines onto plate, crust side up. Sprinkle with Topping. Pour remaining hot oil over sardines - enjoy the sizzle!","images":[],"step":8},{"description":"Serve immediately! Ideal served with crostini for the ultimate sardines on toast. See in post for side salad pairings.","images":[],"step":9}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["dinner-tonight","fish-recipes","italian-recipes","mains","other","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_eff49e4638ee', 'en', 'US', 'Fish with White Wine Sauce', 'Recipe video above. This is a beautiful, elegant white wine sauce that will go with virtually any fish. The simple restaurant trick we deploy here is to mix in cold cubes of butter which makes the sauce glossy and satiny. It''s a classic French technique called monter au beurre.Don''t try this sauce with baked fish (make this Baked Fish with Lemon Cream Sauce instead). You need to pan fry because the fond left in the pan after pan frying dissolves into the sauce and adds flavour.', 'https://www.recipetineats.com/tachyon/2021/08/Fish-in-white-wine-cream-sauce_95.jpg', 5, 12, 17, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_wine", "quantity": {"value": 0.417, "unit": "bottle of 750ml"}}, {"id": "ing_lemon", "quantity": {"value": 0.01, "unit": "net of 500g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["4 x 150g / 5oz white fish fillets (, skinless, boneless (I used snapper, Note 1))","1/2 tsp salt","1/4 tsp pepper","2 tbsp extra virgin olive oil"],"purpose":"Pan seared fish:"},{"ingredients":["1 eschalot (, small, finely chopped (~1 1/2 tbs, Note 2))","1 1/4 cups white wine (, dry, not sweet or too woody (chardonnay is especially good, Note 3))","1 tsp lemon juice (sub white wine vinegar)","1 tsp white wine vinegar (sub more lemon)","1/8 tsp salt","1 pinch pepper","1 pinch white sugar","1 cup thickened/heavy cream","30g / 2 tbsp unsalted butter (, cold, cut into 1cm / 1/3\" cubes)"],"purpose":"White wine sauce:"},{"ingredients":["2 tsp finely chopped parsley (or chives)"],"purpose":"Garnish, optional:"}]', '[{"description":"Cook fish:","images":[],"step":1},{"description":"Preheat oven to 50°C/120°F. Place rack over a tray.","images":[],"step":2},{"title":"Season fish","description":"Sprinkle fish with salt and pepper.","images":[],"step":3},{"title":"Cook fish","description":"Heat oil in a large non stick skillet over medium high heat. Cook fish in two batches until golden, 2 minutes on each side, or until the internal temperature is 55°C/131°F. (Note 4)","images":[],"step":4},{"title":"Keep warm","description":"Place fish on rack, and place in the oven to keep warm.","images":[],"step":5},{"description":"White wine sauce:","images":[],"step":6},{"title":"Discard oil","description":"Tip out excess oil from the skillet but don''t wipe clean.","images":[],"step":7},{"title":"Reduce wine","description":"Add eschalot, white wine, lemon juice, vinegar, salt, pepper, sugar to the pan. Bring to simmer (still on medium high) and reduce by half (~3 minutes).","images":[],"step":8},{"title":"Simmer cream","description":"Add cream, simmer for 2 minutes.","duration":2,"images":[],"step":9},{"title":"Finish with COLD butter","description":"Turn heat to low and add cold butter one cube at a time while mixing with wooden spoon. Once all the butter is incorporated, the sauce should be thickened, satiny and beautifully glossy.","images":[],"step":10},{"title":"Optional strain","description":"Strain the sauce through a sieve (discard eschalot), then pour it back into the pan.","images":[],"step":11},{"title":"Fish in sauce","description":"Place fish back into the pan in the sauce. Spoon some sauce over the fish, leave for 30 seconds.","duration":0.5,"images":[],"step":12},{"title":"Serve","description":"Transfer fish onto serving plates. Spoon sauce over each fish, sprinkled with parsley if desired. Pictured with a side of pea puree (great colour splash!).","images":[],"step":13}]', '["fish","milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["French-ish","Western"],"categories":["dinner-tonight","fish-recipes","mains","other","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0ffa15dca2f8', 'en', 'US', 'Really good Fish Cakes', 'Recipe video above. You''ll find plenty of fish cake recipes floating around. But there are good fish cakes and then there are great fish cakes! The trick is to keep the potato chunky and the fish in big flakes rather than letting it all turn into a mush. Meanwhile, adding garlic, chilli, green onion and thyme to the mix keeps these fish cakes full of flavour!Pan fry then bake for best results. Pan fry golden, then bake to heat all the way through (because I like my fish cakes chunky!) and reheat the first batch you pan fried.', 'https://www.recipetineats.com/tachyon/2021/07/Fish-Cakes_96.jpg', 30, 95, 125, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 60.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 800.0, "unit": "bag of 2kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 1.5, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 20.0, "unit": "pack of 100g"}}, {"id": "ing_thyme", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 0.234, "unit": "loaf"}}, {"id": "ing_oil", "quantity": {"value": 150.0, "unit": "bottle"}}]', '[{"ingredients":["500g / 1 lb white fish fillets (, skinless boneless, cut into 3cm / 1.2\" pieces (Note 1))","60g / 4 tbsp unsalted butter","1/2 tsp salt","1/4 tsp black pepper"],"purpose":"Fish:"},{"ingredients":["800g / 1.6 lb potatoes ( – Sebago (Aus), Russet (US), Maris Piper / King Edwards (UK) (Note 2) (makes 500g flesh))","2 garlic cloves (, finely minced)","1/2 cup green onion (, finely sliced (~1 large stem))","2 large red chillis (, deseeded and finely chopped (can omit))","1 tbsp thyme leaves (, chopped)","1 tbsp parsley (, finely chopped)","3/4 tsp salt"],"purpose":"Fish cakes:"},{"ingredients":["1 cup flour","2 eggs (, lightly whisked)","1 1/4 cups panko breadcrumbs (sub ordinary breadcrumbs)","1 cup vegetable or canola oil (, for frying (~ 1cm / 0.4\" depth))"],"purpose":"Crumbing and cooking:"}]', '[{"description":"Bake potatoes in a 220°C / 430°F (200°C fan) oven for 75 minutes or until they can be pierced with a knife with no resistance. Cut in half and scoop flesh out into a large bowl.","duration":75,"images":[],"step":1},{"title":"Turn oven down to 200°C / 390°F (180°C fan)","description":"fish cakes are finished in the oven.","images":[],"step":2},{"description":"Cook fish (while baking potatoes):","images":[],"step":3},{"description":"Set a rack over a tray. Sprinkle fish with salt and pepper.","images":[],"step":4},{"description":"Melt butter in a large non-stick skillet over medium high heat. Add half the fish and cook, turning, for 4 minutes in total. It should be just cooked inside (ie. flakes easily) but not golden.","duration":4,"images":[],"step":5},{"description":"Transfer to rack to cool. Repeat with remaining fish.","images":[],"step":6},{"description":"Fish Cake Mixture:","images":[],"step":7},{"title":"Sauté garlic","description":"In the same skillet, add garlic, chilli ,thyme and green onion into the leftover butter. Cook for 1 minute until garlic is golden, then pour over the potato, being sure to scrape out every drop of butter!","duration":1,"images":[],"step":8},{"title":"Roughly mash potato","description":"Add parsley and salt, then use a wooden spoon to roughly mash the potato. Don''t use a potato masher, we want some chunks, not smooth mashed potato.","images":[],"step":9},{"title":"Mix in fish","description":"Add fish then gently stir through, breaking it up a bit so you have some nice flakes mixed throughout the potato. Don''t mash the fish up too enthusiastically - we want fish chunks!","images":[],"step":10},{"title":"Form fish cakes","description":"Scoop out 1/4 cup of mixture. Pack it in firmly, pop out onto hand and shape firmly into a 1.75cm / 2/3\" thick cake. The potato will make it hold together, if you press firmly. You should make 13 to 15.","images":[],"step":11},{"description":"Crumb and cook:","images":[],"step":12},{"title":"Crumb","description":"Coat in flour (shake off excess), dip in egg (let excess drip off) then coat in breadcrumbs, pressing to adhere.","images":[],"step":13},{"title":"Pan fry 3 minutes","description":"Heat oil in skillet over medium high heat. Cook fish cakes in batches for 1 1/2 minutes on each side until golden, then transfer to a paper towel-lined tray. If you''re pedantic like me, stand them on their side and roll slowly to cook and make the sides golden too.","images":[],"step":14},{"title":"Bake 10 minutes","description":"Remove paper towel from under the fish cakes. Bake for 10 minutes (this heats all the fish cakes all the way through into the middle + reheats the first batch cooked).","duration":10,"images":[],"step":15},{"description":"Serve with lemon wedges, tartare sauce, plain mayonnaise (Kewpie!), sour cream, ketchup or tomato sauce.","images":[],"step":16}]', '["egg","fish","gluten","milk"]', '["low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["fish-recipes","mains","other","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6afecd3fc001', 'en', 'US', 'Salmon with Herb & Garlic Cream Sauce', 'Recipe video above. This quick, creamy Salmon Sauce gets a fine dining touch with the addition of fresh tarragon and chervil. It''s simply an excellent, easy salmon recipe for all those times when you want a touch of luxury with minimal effort!', 'https://www.recipetineats.com/tachyon/2021/01/Salmon-in-Creamy-Herb-Garlic-Sauce_6.jpg', 5, 15, 20, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 15.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_tarragon", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_chervil", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["4 salmon fillets (, skinless (~180g/6oz each) (Note 1))","1/2 tsp black pepper","1/2 tsp salt","1 tbsp olive oil","15g / 1 tbsp butter (, unsalted)"],"purpose":"Salmon"},{"ingredients":["2 garlic cloves (, finely minced)","1/2 cup dry white wine (or more chicken stock) (Note 2)","1/2 cup chicken or vegetable stock/broth (, low sodium)","1 cup cream (, heavy/thickened )","1/2 cup parmesan (, finely grated (grate your own, Note 3))","2 tsp tarragon leaves* (, finely chopped)","2 tsp chervil* (, finely chopped)","2 tsp parsley* (, finely chopped, plus more for garnish)"],"purpose":"Creamy garlic sauce:"}]', '[{"title":"Season","description":"Pat salmon dry, then sprinkle with salt and pepper.","images":[],"step":1},{"title":"Pan-sear","description":"Heat oil in a large non stick skillet over medium high heat. Add salmon, presentation side down, and cook for 3 minutes until golden brown.","duration":3,"images":[],"step":2},{"title":"Flip","description":"Turn salmon and cook the other side for another 2 minutes, until the internal temperature registers 49°C / 120°F (for medium-rare, recommended) or until cooked to your taste (Note 5).","images":[],"step":3},{"title":"Butter baste","description":"When it''s almost cooked, add the butter. Melt, then spoon over the salmon a few times.","images":[],"step":4},{"title":"Rest","description":"Remove salmon onto plate, and cover loosely with foil to keep warm.","images":[],"step":5},{"description":"Creamy Salmon Sauce:","images":[],"step":6},{"title":"Sauté garlic","description":"Add garlic and stir for 20 seconds or until light golden.","duration":0.3333333333333333,"images":[],"step":7},{"title":"Reduce wine","description":"Add white wine, turn up heat to high. Bring to simmer while stirring base of the pan to dissolve all the golden bits into the sauce. Cook 1 minute or until it most evaporates and the wine-y smell is gone.","images":[],"step":8},{"title":"Thicken cream & stock","description":"Add cream and chicken stock, then simmer on medium heat for 2 - 3 minutes until reduced and slightly thickened.","duration":2.5,"images":[],"step":9},{"title":"Add parmesan & herbs","description":"Stir through parmesan (this will thicken sauce more), then the herbs. Taste sauce and see if more salt and pepper is needed.","images":[],"step":10},{"title":"Serve","description":"Serve salmon with Creamy Sauce, ensuring there''s something on the plate to soak up all that amazing sauce! Mashed Potato rates highly. See above video for list of suggestions (including side salads).","images":[],"step":11}]', '["fish","milk"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner","snack"],"cuisine":["Western"],"categories":["dinner-tonight","fish-recipes","mains","other","quick-and-easy","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_9f1d25fd5a17', 'en', 'US', 'Crispy Beer Battered Fish', 'Recipe video above. This makes a light, crispy fish batter like you''ve never had before! Stays crispy for a good 15 - 20 min, though my fish disappears long before that.The yeast and carbonation in beer makes the batter puffy just like you get at good fish ''n chip shops. Meanwhile the rice flour + shock of ice cold batter hitting the hot oil makes it super crispy. Normal wheat flour doesn''t cut it – the batter goes soggy within minutes!You can''t taste the beer at all, and the alcohol gets cooked out. Serve with ultra crispy French fries for the ultimate homemade Fish & Chips experience.', 'https://www.recipetineats.com/tachyon/2021/01/Beer-Battered-Fish_8.jpg', 10, 12, 22, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_baking_powder", "quantity": {"value": 1.0, "unit": "tub of 150g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_beer", "quantity": {"value": 0.758, "unit": "bottle of 330ml"}}, {"id": "ing_oil", "quantity": {"value": 4.0, "unit": "bottle"}}, {"id": "ing_tartare_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_homemade_crispy_french_fries", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}]', '[{"ingredients":["700g/ 1.4lb white fish fillets (, like flathead, snapper, whiting, cod, tilapia, flathead (skinless, boneless, Note 1))"],"purpose":"Fish:"},{"ingredients":["¼ cup rice flour (Note 2)"],"purpose":"Dusting:"},{"ingredients":["¾ cup plain/all purpose flour","¼ cup rice flour (makes it super crispy, Note 2)","1¼ tsp baking powder","¼ tsp salt","1 cup very cold beer (, anything other than dark beers like stout, porter etc (Note 3))"],"purpose":"Crispy Fish Batter:"},{"ingredients":["4 - 5 cups peanut oil (or vegetable, canola or cottonseed oil)"],"purpose":"Cooking:"},{"ingredients":["Tartare Sauce","Lemon Wedges","Homemade Crispy French fries","Baked Potato Wedges"],"purpose":"Serving:"}]', '[{"title":"Dry & cut fish","description":"Pat fish dry using paper towels or a tea towel. Cut into 7 x 3cm / 3 x 1¼\" batons, or larger fillets if you prefer. If you have very thick fillets, cut in half horizontally (Note 1)","images":[],"step":1},{"title":"Dusting bowl","description":"Place ¼ cup rice flour in a shallow bowl.","images":[],"step":2},{"title":"Heat oil: Heat 6cm / 2\"","description":"3\" oil in a large heavy based pot over medium high heat to 190°C/375°F.","images":[],"step":3},{"title":"Salt & dust","description":"While oil is heating, sprinkle 3 or 4 pieces of fish with a pinch of salt, then coat in rice flour and shake off excess. You can leave them like this for up to 10 minutes.","images":[],"step":4},{"title":"Cold batter","description":"Just before cooking, whisk together the flour, rice flour, baking powder and salt. Add very cold beer into the batter and whisk just until incorporated evenly into the flour. Do not over-mix, do not worry about flour lumps (Note 4). It should be a fairly thin batter but fully coat the back of a spoon. If too thick, add beer 1 tsp at a time.","images":[],"step":5},{"title":"Dredge fish","description":"Dunk a piece of fish in the batter, the let the excess drip off very briefly.","images":[],"step":6},{"title":"Fry 3 minutes","description":"Carefully lower into oil, dropping it in away from you, one piece at a time. Don''t crowd the pot; fry in batches. Fry for 3 minutes, flipping after about 2 minutes, until deep golden.","duration":3,"images":[],"step":7},{"title":"Drain","description":"Drain on paper towels. Repeat with remaining fish. Serve hot! However it will stay crisp for 15 - 20 minutes. (Note 5 for larger batch cooking).","duration":17.5,"images":[],"step":8},{"description":"Serve with Tartare Sauce, lemon wedges and a leafy green salad on the side dressed with a classic vinaigrette. Serve with Crispy French Fries or oven baked wedges!","images":[],"step":9}]', '["fish","gluten","peanuts"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["deep-fried-recipes","fish-recipes","iconic-dishes","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d680e7dad1cf', 'en', 'US', 'Crispy Skin Salmon', 'Recipe video above. Cooking salmon so the skin is evenly crispy from end to end is simple if you follow two key tips: Firstly, ensuring the skin is dry. Secondly, using enough oil to cover the base of the skillet so the skin fries properly and goes golden and crispy rather than just burning in patches. Easy!Pictured with a creamy Lemon & Herb Risotto (ultra easy hands-free baked method!).', 'https://www.recipetineats.com/tachyon/2020/11/Crispy-Salmon-in-skillet.jpg', 3, 10, 13, 4, '[{"id": "ing_fish_fillets", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["4 salmon fillets (, skin-on (Note 1))","1 tsp olive oil (or other cooking oil)","1 tsp salt (, cooking/kosher (3/4 tsp table salt, Note 2))","1/2 tsp black pepper"]},{"ingredients":["2 tbsp olive oil (or vegetable oil)"],"purpose":"Cooking:"},{"ingredients":["lemon wedges"],"purpose":"Serving:"}]', '[{"title":"Dry skin","description":"Pat the skin of the salmon very well with a paper towel until dry. If time permits, place the salmon skin side up in the fridge for 1 hour (uncovered,) to dry it out even more.","images":[],"step":1},{"title":"Season","description":"Drizzle flesh side with half the oil (just a tiny bit) and rub over skin. Sprinkle with half the salt and pepper. Turn fillet over and repeat. Do not do this step until just before cooking.","images":[],"step":2},{"title":"Heat oil","description":"Put enough oil in a large non stick skillet so it fully covers the base. Heat on medium high until it shimmers (but not smoking).","images":[],"step":3},{"title":"Skin side down","description":"Place salmon in the skillet skin side down, then immediately turn the head down to medium.","images":[],"step":4},{"title":"Press down","description":"Using a spatula or something similar, press down on each salmon for 10 seconds so the skin is pushed flat against the skillet and \"sets\" its form. If you can do at least two at a time that is ideal.","duration":0.16666666666666666,"images":[],"step":5},{"title":"Cook 7 minutes","description":"Cook for 7 minutes, or until the salmon is cooked 3/4 of the way through (you will see the colour changing up the side of the salmon) and the skin is crispy.","duration":7,"images":[],"step":6},{"title":"90 sec on flesh side","description":"Flip the salmon to skin side is up and cook for a further 90 seconds.","images":[],"step":7},{"description":"Final skin blast! (My secret tip) Flip the salmon again to skin side down, turn the heat up to medium high and cook the skin side again for 60 seconds, just to give it a final blast of heat to reinforce crispiness!","duration":1,"images":[],"step":8},{"description":"Serve skin side UP to protect the crispy skin. Fish skin will only stay crispy while it''s hot, so serve immediately! Pictured in post with creamy Lemon & Herb Risotto which acts as a side dish and semi-sauce (super easy no-stir recipe!).","images":[],"step":9}]', '["fish"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["fish-recipes","mains","other","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a6130927a800', 'en', 'US', 'Celebration Salmon Salad with Yoghurt Ranch Dressing', 'Recipe VIDEO above. A show off salad for gatherings! Hot smoked salmon adds a touch of special to this salad that''s loaded with fabulous flavours and textures. You''ll love the dressing! Recipe written for 5 servings, double batch pictured in post, shown as a main dish for a buffet.', 'https://www.recipetineats.com/tachyon/2019/12/Celebration-Salmon-Salad_3.jpg', 30, 5, 35, 5, '[{"id": "ing_salmon_fillets", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.5, "unit": "bottle of 500ml"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_greek_yogurt", "quantity": {"value": 0.6, "unit": "tub of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_chives", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_dill", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_lemon", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_kale", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_peaches", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_lettuce", "quantity": {"value": 30.0, "unit": "head"}}, {"id": "ing_fennel", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_snow_pea_sprouts", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}]', '[{"ingredients":["500g / 1 lb hot smoked salmon (, store bought, any flavour (Note 1))"]},{"ingredients":["1 small red onion (, halved then finely sliced)","1 cup (250 ml) apple cider vinegar ((enough to just cover onion), sub white wine vinegar)","1 tsp salt","2 tsp white sugar"],"purpose":"Quick Pickled Onion:"},{"ingredients":["2 cups Greek yoghurt (, full fat recommended)","3 tbsp extra virgin olive oil","1 garlic clove (, minced)","1/4 cup fresh chives, finely chopped","1/4 cup fresh dill, finely chopped","1/2 tsp EACH onion powder, garlic powder, salt, black pepper","1 1/2 tsp white sugar","3 tbsp lemon juice"],"purpose":"Yoghurt Ranch Dressing:"},{"ingredients":["4 cups (packed) kale (, torn into bite size pieces (Note 2))","2 tsp extra virgin olive oil","Pinch of salt"],"purpose":"Marinated Kale:"},{"ingredients":["2 pieces fruit - nectarines, peaches, grapefruit or blood oranges (get whatever''s ripe and juicy, or sub normal oranges)","10 cups cos lettuce / romaine (torn or cut into bite size pieces (Note 3))","1 small fennel (, shaved (0.5 mm / 1/5\" thickness) or finely sliced)","1 handful snow pea sprouts (can omit)","3/4 cup (75g) parmesan (, shredded (Note 4))"],"purpose":"Salad:"}]', '[{"title":"Flake salmon","description":"Use two forks to flake salmon into large chunks.","images":[],"step":1},{"title":"Dressing","description":"Mix the Yoghurt Ranch Dressing ingredients in a bowl. Adjust olive oil + lemon juice to taste. Leave 20 minutes.","images":[],"step":2},{"title":"Pickle Onions","description":"Place ingredients in a bowl, toss to coat. Set aside for 1 hour+ or until onion is softened (if in a rush, make sure the onion is finely sliced = faster pickle). Drain.","images":[],"step":3},{"title":"Marinated Kale","description":"Place kale in a large bowl, drizzle with oil then sprinkle with salt. Use your fingers to massage the oil onto the leaves - you want to ensure every part of the kale is coated in oil. Set aside for 30 minutes or until kale is softened.","duration":30,"images":[],"step":4},{"description":"Nectarines/peaches option- halve then finely slice.","images":[],"step":5},{"title":"Grapefruit/blood orange option","description":"segment per video. Squeeze all remaining juice out of the membrane after segmenting, mix into dressing.","images":[],"step":6},{"description":"Place lettuce, kale, fennel, 1/2 cup onion in bowl. Drizzle with about 1 cup dressing and 1/3 cup parmesan. Toss well to coat. Taste, add more parmesan or salt if you want, or more dressing.","images":[],"step":7},{"description":"Pile half dressed lettuce onto serving platter. Flake over half the salmon and half the fruit. Scatter with more red onion.","images":[],"step":8},{"description":"Top with remaining lettuce, salmon, fruit and onion (might not use all onion).","images":[],"step":9},{"description":"Drizzle with some dressing (might not use all, serve remainder on side). Scatter over snow pea sprouts, sprinkle with remaining parmesan. Place on table and let everyone help themselves!","images":[],"step":10}]', '["fish","milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["fish-recipes","salad-recipes-main-course","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1d58f936c9a7', 'en', 'US', 'Salmon Patties', 'Recipe VIDEO above. Made with either fresh salmon OR canned salmon, these are so moreish! Golden crispy on the outside, savoury and juicy on the inside, these are baked, not fried, so they''re healthier and there''s less cleaning up. Makes 12 patties.', 'https://www.recipetineats.com/tachyon/2018/02/Salmon-Patties_8.jpg', 15, 20, 35, 4, '[{"id": "ing_bread", "quantity": {"value": 0.188, "unit": "loaf"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_salmon_fillets", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_dill", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}]', '[{"ingredients":["1 cup Panko breadcrumbs (Note 1 for subs)","1 small onion ((or 1/2 large), grated)","1 garlic clove (, finely minced)","400 g/ 14 oz cooked fresh salmon OR canned red or pink salmon (, drained (Note 2))","2 shallots / scallions / green onions (, finely sliced)","1/3 cup fresh dill (, roughly chopped (or 1 tsp dried herbs of choice))","2 eggs","1/2 cup parmesan (, grated or shredded)","1/4 tsp each salt and pepper"]},{"ingredients":["2 tbsp vegetable oil","Oil spray"],"purpose":"Cooking:"}]', '[{"description":"Preheat oven to 220C/430F standard (200C fan)","images":[],"step":1},{"description":"Place breadcrumbs in a bowl. Grate over onion, including juices. Mix onion into breadcrumbs, ensuring all breadcrumbs are soaked. (Note 3)","images":[],"step":2},{"description":"Add remaining ingredients except salmon. Mix well.","images":[],"step":3},{"description":"Add salmon. Stir through gently, leaving flakes of salmon (rather than vigorously mixing salmon into tiny pieces).","images":[],"step":4},{"description":"Scoop up 1/4 cup mixture (level, packed standard ice cream scoop, see Video). Form round patties about 1.5 cm/ 2/3\" thick and set aside.","images":[],"step":5},{"description":"Drizzle oil all over tray. Place in oven for 2 minutes until hot - oil will spread over tray. Tilt tray to spread if needed.","duration":2,"images":[],"step":6},{"title":"Place patties on tray","description":"DO NOT press down (makes them stick on tray). Spray surface with oil spray.","images":[],"step":7},{"description":"Bake 15 minutes. Flip, spray surface with oil spray, bake 5 minutes.","images":[],"step":8},{"description":"Serve with sour cream or yoghurt on the side for dipping / dolloping, and extra fresh dill if desired.","images":[],"step":9},{"description":"I served mine with cauliflower puree and Yoghurt Slaw - healthy side options! (Note 3)","images":[],"step":10}]', '["egg","fish","milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","fish-recipes","main-dishes","quick-and-easy","salmon-recipes","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_70e10b2bd897', 'en', 'US', 'Salmon Alfredo Pasta', 'A creamy Alfredo pasta tossed with flakes of hot smoked salmon (or plain cooked salmon). Make sure you follow the steps to toss the sauce and pasta with some of the pasta cooking water - it makes all the difference to create a luscious creamy sauce using only 1/2 cup of cream!', 'https://www.recipetineats.com/tachyon/2016/01/Salmon-Alfredo_7.jpg', 10, 15, 25, 3, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.454, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.925, "unit": "pack of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_fish_fillets", "quantity": {"value": 6.0, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}]', '[{"ingredients":["8 oz / 250g dried fettuccine","3 tbsp / 50g unsalted butter","1 small shallot (US) / eschallot (Australia), very finely minced (Note 1)","½ cup / 125 ml heavy cream (Note 2)","¾ cup / 185 ml freshly grated Parmigiano Reggiano or parmesan (Notes 3 and 4)","¼ teaspoon salt","Good grind of black pepper","6-7 oz / 180 - 200g hot smoked salmon fillet (, flaked (Note 5))"]},{"ingredients":["Fresh parsley (optional)","Extra Parmigiano Reggiano"],"purpose":"Garnish"}]', '[{"description":"Bring a large pot of salted water to boil. Add the fettuccine and cook until al dente (still firm but just cooked through). (Note 6)","images":[],"step":1},{"description":"Meanwhile, melt the butter in a deep fry pan over medium high heat. (Note 7)","images":[],"step":2},{"description":"Add the shallots and sauté for 2 minutes or until tender.","duration":2,"images":[],"step":3},{"description":"Add the cream and bring to boil. Turn heat down to medium low and simmer for 3 minutes.","duration":3,"images":[],"step":4},{"description":"Remove the fry pan from the heat and stir through the Parmigiano Reggiano, salt and pepper until the sauce is smooth.","images":[],"step":5},{"description":"TAKE OUT 1/2 cup of pasta water PLUS scoop out an extra mug (extra, just in case). Then drain the pasta in a colander.","images":[],"step":6},{"description":"Transfer the pasta and 1/2 cup of reserved pasta water into the fry pan with the sauce. Add salmon. Return the fry pan to the stove over medium heat. Toss very gently to coat the pasta in the sauce and allow the sauce to emulsify (Note 6) for 1 1/2 - 2 minutes, until the sauce coats the pasta - there should be no sauce pooled at the bottom of the skillet. (Note 7)","images":[],"step":7},{"description":"Remove from the stove and serve immediately, garnished with extra Parmigiano Reggiano and fresh parsley, if using.","images":[],"step":8}]', '["fish","milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["dinner-tonight","fish-recipes","italian-recipes","main-dishes","pasta-recipes","quick-and-easy","salmon-recipes","seafood-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d2b5e5e07c97', 'en', 'US', '"Sizzling Beef" Steak Fried Rice', 'Recipe video above. This is a bit special because it''s rare to see fried rice made with juicy bites of steak! With marinated, tenderised beef pieces "sizzled" until golden (aka - your favourite Chinese restaurant Sizzling Beef!), this is an excellent recipe to make with economical cuts like sizzle steak, minute steak, and pre-cut stir fry strips. The beef is caramelised on the outside, and tenderised so it doesn''t overcook. It''s so soft and velvety, you will be shocked!', 'https://www.recipetineats.com/tachyon/2024/09/Sizzling-Beef-Fried-Rice-54326a.jpg', 15, 10, 85, 4, '[{"id": "ing_beef_steak", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.01, "unit": "bottle of 250ml"}}, {"id": "ing_oyster_sauce", "quantity": {"value": 0.04, "unit": "bottle of 250ml"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_sugar", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_baking_soda", "quantity": {"value": 0.009, "unit": "tub of 200g"}}, {"id": "ing_oil", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_green_onion", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_white_rice", "quantity": {"value": 0.52, "unit": "kg"}}, {"id": "ing_green_beans", "quantity": {"value": 200.0, "unit": "pack"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["300g/ 10 oz rump beef steak (US: top sirloin)"]},{"ingredients":["1/2 tsp dark soy sauce (Note 2)","2 tsp oyster sauce (Note 3)","2 tbsp water","1 garlic clove","1/4 tsp sugar (any)","3/8 tsp baking soda (bi-carbonate soda) (ie 1/4 teaspoon HEAPED, Note 4)"],"purpose":"Tenderising beef marinade:"},{"ingredients":["2 1/2 tbsp canola or peanut oil (, separated)","4 green onion stems (, cut into 1.25 cm / 1/2\" lengths, white part separated from green part)","2 garlic cloves (, finely minced)","520g/ 1 lb (4 cups) cooked, day-old long grain white rice, (or other plain rice), refrigerated overnight (Note 5)","200g/7 oz green beans (, cut into 1.25 cm pieces (~ 2 heaped cups) (Note 6))"],"purpose":"Fried rice:"},{"ingredients":["2 tbsp fish sauce (Note 7)","1 1/2 tbsp oyster sauce (Note 3)","1/2 tsp sugar (any type)"],"purpose":"Fried rice sauce:"},{"ingredients":["2 eggs","1/2 tsp sesame oil","Pinch of salt and pepper (preferably white, but black ok)"],"purpose":"Scrambled egg:"}]', '[{"description":"Marinate beef 1 hour. Cook beef in 2 tbsp oil on high in a large pan until lightly seared, add white part of green onion and beans, cook until beef is caramelised, adding garlic towards the end. Add rice and sauce, toss well. Scramble egg on side of pan, toss through green part of green onion. Eat!","images":[],"step":1},{"title":"Marinade & tenderise beef","description":"Mix the marinade ingredients in a bowl then add the beef and toss well. Set aside for 1 hour (up to 24 hours), or the time specified in Note 1.","images":[],"step":2},{"title":"Sauce","description":"Mix the Sauce ingredients. Set aside.","images":[],"step":3},{"description":"Whisk the Scrambled Egg ingredients. Set aside.","images":[],"step":4},{"title":"Sizzle beef","description":"Heat 2 tablespoons of oil in a large non-stick pan over high heat (mine is 30cm/12\", see Note 8 for why no wok). Add the beef and cook for 2 minutes until the surface is sealed. Add the garlic, white part of the green onion and beans. Cook for another 1 minute until the beef is caramelised, stirring constantly so it doesn''t catch and burn.","duration":2,"images":[],"step":5},{"title":"Rice and sauce","description":"Add the rice and sauce. Toss for a good 1 1/2 - 2 minutes to give the rice a chance to get toasty.","images":[],"step":6},{"title":"Scramble egg","description":"shove all the rice to one side and shif the pan so the empty space is set over the flame. Add the remaining 1/2 tablespoon oil and spread. Pour the egg, swirl, give it 10 seconds to partially set then do lazy swirls with your spatula to scramble it softly. Once mostly cooked, quickly (but gently!) toss it though the rice.","images":[],"step":7},{"title":"Serve","description":"Add the green part of the green onion and toss through. Divide between bowls and enjoy!","images":[],"step":8}]', '["egg","fish","gluten","peanuts","sesame","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian","Chinese","Thai-ish"],"categories":["fried-rice","quick-and-easy","rice-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0263f552bf04', 'en', 'US', 'German Pork Knuckle (Schweinshaxe) - Slow Roasted with Crispy crackling!', 'Recipe video above. Realistically, one knuckle will serve 2. But for wow factor, serve one per person!!!While producing tender Pork Knuckle flesh is straightforward enough, very few recipes truly nail the crispy crackling. So here is a recipe that finally does! The skin is crispy all over and fabulously bubbly, shattering into a thousand porky shards when you bite instead of breaking your teeth on hard, leathery patches!Meanwhile, the flesh is seasoned with traditional flavourings and the Pork Knuckle is served with an authentic, dark and malty German beer gravy. It''s every carnivore''s dream come true!', 'https://www.recipetineats.com/tachyon/2021/05/German-Pork-Knuckle_7-main-1.jpg', 20, 180, 200, 2, '[{"id": "ing_pork", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_white_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_juniper_berries", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_caraway_seeds", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_beer", "quantity": {"value": 1.515, "unit": "bottle of 330ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_cornstarch", "quantity": {"value": 0.025, "unit": "pack of 400g"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["1 x 1.25kg / 2.5lb pork knuckle (Note 1)","2 tbsp white vinegar (Note 2)","3 garlic cloves (, cut into 4 - 6 slivers (Note 3))"]},{"ingredients":["2 tsp salt (, kosher / cooking salt NOT table salt (Note 4))","1 tsp black pepper","1 tsp juniper berries (Note 5)","1 tsp caraway seeds","1 tsp fennel seeds"],"purpose":"Marinade Rub:"},{"ingredients":["2 cups dark German beer (Note 6)","2 cups chicken stock / broth (, low sodium)","1 carrot (, unpeeled, sliced 2cm / 0.8\" thick)","1 onion (, unpeeled, halved, cut into 1.25cm / 1/2\" thick slices)","1 head garlic (, cut in two halves horizontally)","5 juniper berries (Note 5)","2 bay leaves (, preferably fresh otherwise dried)"],"purpose":"Beer Gravy:"},{"ingredients":["2 tsp cornflour/cornstarch","1/2 cup water","1 tsp white sugar","1/4 - 1/2 tsp salt (, kosher / cooking salt NOT table salt (Note 4))"],"purpose":"Gravy thickening and seasoning:"}]', '[{"description":"Preparation and seasoning:","images":[],"step":1},{"title":"Prick skin","description":"Poke lots of small holes all over the pork knuckle’s skin, using a small sharp knife or even a pin (eg. safety pin, sewing pin). Take care not to pierce through the fat into the flesh (Note 7).","images":[],"step":2},{"title":"Vinegar","description":"Brush (or rub) 1 tbsp of the vinegar on the pork flesh only, including inside cracks / crevices and meat under the skin where it meets the flesh (but do not peel skin back). Avoid getting vinegar on the skin.","images":[],"step":3},{"title":"Stud with garlic","description":"Make shallow incisions in the pork flesh (only) with a small knife then stuff with the garlic slivers.","images":[],"step":4},{"title":"Seasoning rub","description":"Pound the rub ingredients in a mortar and pestle until it''s a coarse powder (or use a Nutribullet, spice grinder or similar).","images":[],"step":5},{"title":"Rub seasoning on pork","description":"Rub pork skin with olive oil. Then rub the seasoning mix all over the pork – on the flesh, skin, and getting into all the cracks and crevices.","images":[],"step":6},{"title":"Skewer skin (secret for crispy skin! Note 8)","description":"Pull the skin down to stretch it tight so there''s no creases. Then thread through 2 metal skewers in a \"X\" formation near the base of the knuckle. Pierce through skin 2cm / 0.8\" from the base of the pork knuckle to hold the stretched skin in place.","images":[],"step":7},{"title":"\"Marinate\" overnight","description":"Place pork standing on a plate, then leave uncovered in the fridge overnight (Note 9).","images":[],"step":8},{"description":"Preheat oven to 180°C / 350°F (160°C fan).","images":[],"step":9},{"title":"Beer gravy","description":"Put all beer gravy ingredients in a roasting pan (deep enough to hold all liquids and vegetables).","images":[],"step":10},{"title":"Rack on pan","description":"Place a rack over the pan. Place pork knuckle on rack, sitting upright. (Note 10)","images":[],"step":11},{"title":"Slow roast","description":"Roast for 2 hours 10 minutes, rotating tray half way. (If the liquid in the pan is getting too low and in danger of drying out, top with 1/2 cup of water at a time.) Roast until the internal temperature in the thickest part of meat reaches 85°C / 185°F.","images":[],"step":12},{"description":"Make crispy Pork Knuckle crackling!","images":[],"step":13},{"description":"Remove knuckle from oven, transfer knuckle to a tray.","images":[],"step":14},{"title":"Increase oven","description":"Increase oven to 260°C / 500°F (240°C fan) (Note 11)","images":[],"step":15},{"title":"Brush skin with vinegar","description":"Brush skin with 1/2 the remaining 1 tbsp of vinegar. Place in oven for 30 minutes, rotating tray halfway and brushing with remaining vinegar.","duration":30,"images":[],"step":16},{"description":"Skin should be crispy, dip golden and mostly bubbly.","images":[],"step":17},{"title":"Rest","description":"Rest 15 minutes before serving with German Beer Gravy!","images":[],"step":18},{"description":"German beer gravy:","images":[],"step":19},{"title":"Strain liquid","description":"Strain roasting pan juices into a saucepan. Ideally you should have around 1.5 - 2 cups.","images":[],"step":20},{"title":"Thicken","description":"Bring liquid to a simmer. Mix cornflour and water, then pour into liquid while stirring. Add sugar and salt to taste.","images":[],"step":21},{"title":"Simmer","description":"Simmer for 2 minutes or until it becomes a thin syrup consistency (German beer gravy should not be as thick as normal gravy, but quite runny). If it''s too thick, add a touch of water. Too thin, simmer to reduce - it will thicken. Serve with pork knuckle!","duration":2,"images":[],"step":22}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Bavarian","German"],"categories":["german-food","iconic-dishes","mains","pork","pork-recipes","roasts"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_220052dbd26b', 'en', 'US', 'Pizza Dough recipe', 'Recipe video above. This pizza dough can be made by hand with 5 minutes of kneading, or in 40 seconds flat using a food processor (see 2nd recipe card below). It makes a pizza crust like you get at Italian wood fired pizzerias - puffy edges with a chewy crumb, enough structure so you can pick up slices rather than being a sloppy mess. But not dry and stiff like a thin cracker! Best to use weights provided, if you can. Makes 3 pizzas.', 'https://www.recipetineats.com/tachyon/2020/05/Ball-of-pizza-dough.jpg', 30, 30, 60, 3, '[{"id": "ing_bread", "quantity": {"value": 600.0, "unit": "loaf"}}, {"id": "ing_yeast", "quantity": {"value": 0.02, "unit": "pack of 5 sachets"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.06, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.33, "unit": "L"}}, {"id": "ing_flour", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.04, "unit": "pack of 125g"}}, {"id": "ing_pizza_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_topping_of_choice", "quantity": {"value": 1.0, "unit": "unit"}}]', '[]', '[{"title":"Mix dry","description":"Place flour, yeast, sugar and salt in a large bowl. Mix with a wooden spoon.","images":[],"step":1},{"title":"Add wet","description":"Make a well in the centre. Pour in oil and water. Mix to bring together so it comes away from the side of the bowl.","images":[],"step":2},{"title":"Knead 5 minutes","description":"Sprinkle work surface with 1/2 the Extra Flour. Scrape dough out of bowl. Bring together into a ball then knead for 5 minutes until pretty smooth (see video for Before v After, Note 5). Shape dough into a ball.","duration":5,"images":[],"step":3},{"description":"Drizzle large bowl with Extra Olive Oil (can use same bowl).","images":[],"step":4},{"description":"Place dough in, turn over and rub top with oil.","images":[],"step":5},{"description":"Cover with cling wrap, then put in a warm place for 1 - 2 hours until it doubles in size. (Rise #1)","images":[],"step":6},{"title":"Optional fridge","description":"flavour development:","images":[],"step":7},{"description":"After rising, refrigerate bowl with dough for up to 5 days (do not punch down). Flavour gets better with time. (Note 7)","images":[],"step":8},{"description":"Form small balls, Rise #2:","images":[],"step":9},{"description":"Scrape dough out of bowl on work surface lightly dusted with flour. Shape into log, fully deflating dough in the process.","images":[],"step":10},{"title":"Cut into 3 equal portions (330g / 11.6 oz each)","description":"one for each pizza base.","images":[],"step":11},{"description":"For each dough portion, shape into a ball, tuck the sides under, money-bag style, so you have a smooth surface.","images":[],"step":12},{"title":"Place balls, smooth side up, on a large tray","description":"5cm / 2\" from edge of tray, 10cm / 4\" from each other.","images":[],"step":13},{"description":"Sprinkle balls with a touch of flour and lightly rub to coat surface (so they don''t stick to tea towel). Cover balls with lightly damp tea towel. Alternatively, cover loosely with a sheet of baking paper then seal tray with cling wrap, ensuring the dough balls have plenty of space to rise under the cling wrap.","images":[],"step":14},{"description":"Leave in warm place 1 hour until almost double in size. (If fridge-cold, this will take 3 - 4 hours).","images":[],"step":15},{"description":"Stretch pizza base:","images":[],"step":16},{"description":"Preheat oven to 275°C / 530°F, or as high as it will go. Put shelf in top third of oven.","images":[],"step":17},{"description":"Sprinkle work surface with 1/2 tbsp flour. Place one dough ball on top.","images":[],"step":18},{"description":"Without touching the edges, use finger tips and back of fingers to deflate dough gently and spread out into a 20cm/8\" round. Then use your fingers and palms to stretch the dough, working around the circle, until it''s almost the size of a 30cm / 12\" pizza pan.","images":[],"step":19},{"description":"Drag onto the pizza pan (or paddle if cooking on pizza stone, Note 8). Then finish stretching it to fill the pan. Neaten up the shape so it''s as perfectly round and uniform as possible – the shape you have now is the shape it will bake to! Leave 1 cm / 1/3\" of the edge untouched as much as possible (for puffy crusts!).","images":[],"step":20},{"description":"Topping / Cooking (work quickly!):","images":[],"step":21},{"description":"Spread with 1/4 cup pizza sauce, 130g / 1 1/3 cups freshly grated mozzarella, then toppings of choice (see Topping recipes here).","images":[],"step":22},{"description":"Bake 10 minutes, rotating at 4 minutes and checking at 8 minutes, until cheese is melted and has some golden spots.","images":[],"step":23},{"description":"Cut into wedges, serve immediately!!","images":[],"step":24},{"description":"Repeat process for remaining balls to make two more pizzas.","images":[],"step":25}]', '["gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["good-to-know","main-dishes","pizza-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_38fba5c4f685', 'en', 'US', 'Pizza toppings', 'Here are our top 12 favourite pizza toppings! This list will continue to grow, at which point I''ll start creating separate recipes for each pizza. For now, enjoy this handy 12-in-1 list! Also see - homemade pizza dough (dough and cooking) and pizza sauce recipe. No yeast? No worries! Make this Magic No Yeast Pizza Dough.', 'https://www.recipetineats.com/tachyon/2020/05/Pizza-Toppings.jpg', 10, 10, 20, 1, '[{"id": "ing_pizza_base", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_pizza_sauce", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.067, "unit": "pack of 125g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.75, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 50.0, "unit": "pack of 1kg"}}, {"id": "ing_bacon", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_capsicum", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_black_olives", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_ham_batons", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_pineapple", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_barbecue_sauce", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.75, "unit": "jar of 50g"}}, {"id": "ing_cabanossi_pieces", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_shrimp", "quantity": {"value": 12.0, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 25.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_chilli", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_baby_rocket", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_sausages", "quantity": {"value": 0.225, "unit": "pack of 500g"}}, {"id": "ing_kale", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.067, "unit": "pack of 125g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_basil", "quantity": {"value": 12.0, "unit": "bunch"}}, {"id": "ing_capricciosa_recipe", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.067, "unit": "pack of 125g"}}, {"id": "ing_cheese", "quantity": {"value": 1.333, "unit": "block of 250g"}}, {"id": "ing_cheese", "quantity": {"value": 1.333, "unit": "block of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.225, "unit": "pack of 200g"}}, {"id": "ing_prosciutto", "quantity": {"value": 8.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_potato", "quantity": {"value": 1.25, "unit": "bag of 2kg"}}, {"id": "ing_rosemary", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["1 pizza base (28cm / 11\" base, see separate recipe)","1/4 cup pizza sauce (see separate recipe)"]},{"ingredients":["1 1/3 cups mozzarella cheese (, freshly grated)","20 slices pepperoni (, cut 3mm / 1/8” thick)"],"purpose":"Pepperoni"},{"ingredients":["1 1/3 cups mozzarella cheese (, freshly grated)","1/3 cup onion (, cut 0.5cm (1/4”) thick)","1/3 cup bacon (, cut into 1 x 3cm (1/2 x 2”) pieces)","1/2 cup capsicum (, sliced 0.5cm (1/4”) thick)","12 slices pepperoni (, cut 3mm / 1/8” thick)","1/3 cup beef mince (ground beef) (, formed into 1cm (1/2”) balls)","1/3 cup button mushrooms (, cut 3mm (1/8”) thick)","1/4 cup black olives (, sliced)"],"purpose":"Supreme"},{"ingredients":["1 1/3 cups mozzarella cheese (, freshly grated)","2/3 cup ham (, cut into 2 x 0.5cm (1 x 1/4\") batons)","1/2 cup pineapple (, cut into small chunks)"],"purpose":"Ham & Pineapple"},{"ingredients":["3 tbsp barbecue sauce (instead of pizza sauce)","1 1/4 cups mozzarella cheese (, freshly grated)","10 slices pepperoni (, cut 3mm (1/8”) thick)","1/3 cup bacon (, cut into 1 x 3cm (1/2 x 2”) pieces)","1/3 cup cabanossi (, cut into 5mm (1/4”) pieces)","1/3 cup beef mince (ground beef) (, formed into 1cm (1/2”) balls)","1/3 cup ham (, cut into 2 x 0.5cm (1 x 1/4\") batons)"],"purpose":"BBQ Meatlovers"},{"ingredients":["1 1/3 cups mozzarella cheese (, freshly grated)","12 medium raw prawns/shrimp (, shelled and deveined)","25g / 1 1/2 tbsp butter (, unsalted)","1/4 tsp salt","1 tbsp garlic (, chopped)","1/2 cup capsicum (, sliced 0.5cm (1/4”) thick)","1/2 cup onion (, sliced 0.5cm (1/4”) thick)","2 tsp long red chillis (, sliced finely)","1 cup baby rocket (, loosely packed)"],"purpose":"Garlic Butter Prawns & Chilli"},{"ingredients":["1 1/3 cups mozzarella cheese (, freshly grated)","3/4 cup pork sausage (, skin removed, torn into 12 or so little balls (raw))","1 1/2 cups kale (, stems removed, torn into pieces (raw))","2 tsp olive oil"],"purpose":"Sausage & Kale"},{"ingredients":["125g / 4.4oz fresh buffalo mozzarella (, very well drained)","2 tbsp extra virgin olive oil","12 basil leaves"],"purpose":"Margherita"},{"ingredients":["Capricciosa recipe (separate recipe with video tutorial)"],"purpose":"Capricciosa"},{"ingredients":["1 heaped cup mozzarella cheese (, freshly grated)","1/2 cup sliced provolone cheese (, torn into pieces)","1/3 cup blue cheese (, broken into 1.5cm (1/2”) pieces)","3 tbsp parmesan cheese (, grated)"],"purpose":"Quattro Formaggio (Four Cheese Pizza)"},{"ingredients":["1 1/3 cup mozzarella cheese (, freshly grated)","1 tbsp olive oil (, plus extra for drizzling)","8 - 10 slices prosciutto","1 cup baby rocket (, loosely packed)"],"purpose":"Prosciutto & Rocket"},{"ingredients":["Cheese and garlic pizza (separate recipe)"],"purpose":"Cheese garlic pizza"},{"ingredients":["1 1/3 cups mozzarella cheese (, freshly grated)","1 1/4 cups potato (waxy variety) (, 2mm (1/12\") slices)","1 tbsp fresh rosemary leaves (picked, loosely packed)","1/4 tsp salt","1 1/2 tbsp extra virgin olive oil"],"purpose":"Potato & Rosemary"}]', '[{"description":"Preheat oven to 275°C/530°F, or as high as it will go. Place oven shelf in top third of oven.","images":[],"step":1},{"description":"Stretch dough to form pizza base and slide onto baking pan.","images":[],"step":2},{"description":"Follow topping directions below, then place in oven.","images":[],"step":3},{"description":"Turn pizza at 4 minutes so it cooks evenly, and check at 8 minutes (even if recipe says 10 minutes). Take out early if cheese gets too brown.","images":[],"step":4},{"description":"Spread pizza sauce over base, followed by cheese.","images":[],"step":5},{"description":"Distribute pepperoni over pizza, and bake.","images":[],"step":6},{"description":"Spread pizza sauce over base, followed by cheese.","images":[],"step":7},{"description":"Scatter remaining ingredients over pizza, and bake.","images":[],"step":8},{"description":"Ham & Pineapple","images":[],"step":9},{"description":"Spread pizza sauce over base, followed by cheese.","images":[],"step":10},{"description":"Scatter remaining ingredients over pizza, and bake.","images":[],"step":11},{"description":"Spread barbecue sauce over base, followed by cheese.","images":[],"step":12},{"description":"Scatter remaining ingredients over pizza, and bake.","images":[],"step":13},{"description":"Garlic Butter Prawns & Chilli","images":[],"step":14},{"description":"Toss prawns/shrimp with salt.","images":[],"step":15},{"description":"Heat butter over medium heat in a skillet or heavy frying pan until frothing. Add garlic and cook for another 30 seconds.","images":[],"step":16},{"description":"Cook prawns for 1 minute on one side until just starting to brown. Flip prawns, cook 1 minute more and remove. Reserve garlic butter.","duration":1,"images":[],"step":17},{"description":"Spread pizza sauce over base, followed by cheese.","images":[],"step":18},{"description":"Scatter remaining ingredients except rocket over pizza, top with prawns. Bake until done.","images":[],"step":19},{"description":"Drizzle reserved garlic butter over prawns and scatter with rocket.","images":[],"step":20},{"description":"Spread pizza sauce over base, followed by cheese.","images":[],"step":21},{"description":"Scatter remaining ingredients over pizza, and bake. (Note 2)","images":[],"step":22},{"description":"Spread pizza sauce over base. Drizzle 1 tbsp of oil over base, and bake.","images":[],"step":23},{"description":"After 5 minutes, remove pizza from oven. Tear buffalo mozzarella into 10 pieces and distribute over pizza. Continue baking until pizza is done.","images":[],"step":24},{"description":"Drizzle with remaining olive oil, and scatter with basil leaves.","images":[],"step":25},{"description":"See recipe directions in the separate recipe here.","images":[],"step":26},{"description":"Quattro Formaggio (Four Cheese Pizza)","images":[],"step":27},{"description":"Spread mozzarella cheese over base. Scatter provolone, parmesan and finally blue cheese over pizza. Bake.","images":[],"step":28},{"description":"Prosciutto & Rocket","images":[],"step":29},{"description":"Spread pizza sauce over base, followed by cheese. Drizzle 1 tbsp oil over pizza and bake.","images":[],"step":30},{"description":"2 minutes before the pizza is done, remove from oven. Drape prosciutto casually around the pizza.","images":[],"step":31},{"description":"Continue baking until done. Scatter rocket over pizza and drizzle with a little more olive oil.","images":[],"step":32},{"description":"Cheese & Garlic","images":[],"step":33},{"description":"See recipe directions in the separate recipe here.","images":[],"step":34},{"description":"Potato & Rosemary","images":[],"step":35},{"description":"Spread mozzarella cheese over base.","images":[],"step":36},{"description":"Arrange potato slices over pizza, each slice overlapping no more than 1/3 so it will cook through properly.","images":[],"step":37},{"description":"Sprinkle over the rosemary and salt, and drizzle with the olive oil. Bake for the standard cooking time given. Check with a fork or skewer that the potato is tender. If not fully cooked, cook another 2 minutes.","images":[],"step":38}]', '["milk","shellfish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["good-to-know","leftover-ham-recipes","pizza-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0bea77e2f7c6', 'en', 'US', 'Pizza Sauces', 'Pick the one that suits your needs to make homemade pizza! (No Yeast pizza dough here)Instant Pizza Sauce - An intense flavour with the signature tang of tomato paste which compliments rich / intense flavoured pizza toppings. Tastes like Leggos pizza sauce sold at the stores. I use this the most often - personal taste and sheer convenience.Fresh and Bright - A lighter, fresher pizza sauce thanks to the addition of passata. Ideal for more delicate toppings like margherita, vegetable pizzas and most classic Italian pizzas.New York Pizza Sauce - A richly flavoured New York-style pizza sauce. Based on this recipe from Serious Eats.', 'https://www.recipetineats.com/tachyon/2020/05/Spreading-pizza-sauce-on-homemade-pizza-crust.jpg', 5, 0, 5, 4, '[{"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}]', '[{"ingredients":["1 cup tomato paste (, unsalted (Note 1))","1 tsp salt (Note 1)","2 tsp white sugar","2 tsp olive oil","2 tsp garlic (, finely minced (optional))","2 tbsp water","1/2 tsp EACH dried parsley (, basil and oregano (optional))"],"purpose":"Instant Pizza Sauce:"},{"ingredients":["1 cup tomato passata (Note 2)","1 tbsp tomato paste","1/2 tsp salt","1 tsp sugar","1 tbsp olive oil"],"purpose":"Fresh and Bright Pizza Sauce:"},{"ingredients":["2 tbsp olive oil","1 onion ((small), finely chopped)","2 cloves garlic grated or finely chopped","800g / 28 oz canned crushed tomatoes","1 tsp dried oregano","3/4 tsp salt","1 tsp sugar"],"purpose":"New York Pizza Sauce:"}]', '[{"description":"Instant Pizza Sauce:","images":[],"step":1},{"description":"Combine ingredients and mix well.","images":[],"step":2},{"description":"Fresh and Bright Pizza Sauce:","images":[],"step":3},{"description":"Combine ingredients and mix well","images":[],"step":4},{"description":"New York Pizza Sauce:","images":[],"step":5},{"description":"Heat oil in a heavy-based, medium saucepan over medium heat. Add onion and garlic, and sautee until onions are soft but not coloured.","images":[],"step":6},{"description":"Add tomatoes, oregano, salt and sugar. Bring to a simmer. Reduce heat to low, and cook, stirring occasionally, until reduced by half (about 1 hour). You will need to stir more frequently towards the end to stop the sauce catching","images":[],"step":7},{"description":"Leave to cool before using.","images":[],"step":8},{"description":"Using pizza sauce:","images":[],"step":9},{"description":"Use 1/4 cup of pizza sauce for each pizza (30cm/12\" wide).","images":[],"step":10},{"description":"Place raw pizza crust on a pizza pan (preferably with holes). Spread sauce evenly using the back of a spoon, leaving a 1cm / 1/2\" border for the crust.","images":[],"step":11},{"description":"Cover with toppings of choice (less is more!). Standard pizza - sprinkle with 130g / 4.5 oz freshly shredded mozzarella cheese, then 1 cup toppings such as sliced pepperoni. (See this post for pizza topping recipes)","images":[],"step":12},{"description":"Bake in preheated 275°C / 530°F oven on top shelf for 10 minutes, rotating at 4 minutes, until cheese has golden specks and crust is crisp. (See this homemade pizza recipe for full cooking directions, or this NO YEAST Pizza Dough recipe)","duration":10,"images":[],"step":13}]', '[]', '["gluten_free","low_calorie","vegan","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["good-to-know","pizza-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_618b3c79806f', 'en', 'US', 'Greek Kofta Kebabs', 'Recipe video above. This Greek Kofta kebab features a secret spice mix from a well known Melbourne souvlaki shop called Kalimera Souvlaki Art. The owner gave me his chicken gyros recipe for a story I did for Good Food. I used the same blend for lamb mince koftas - it''s spectacular! The secret ingredient is a hint of curry powder, which adds warmth and depth without a curry taste. Genius!Served with my version of his Secret Souvlaki Sauce, crafted from clues he gave me. It''s so good, I use it to dunk crackers, veggie sticks and hot chips.', 'https://www.recipetineats.com/tachyon/2024/08/Greek-lamb-kofta-kebabs_5.jpg', 15, 10, 25, 4, '[{"id": "ing_lamb_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1000.0, "unit": "pack of 3 heads"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.15, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_skewers", "quantity": {"value": 8.0, "unit": "pack of 50"}}, {"id": "ing_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.075, "unit": "jar of 400g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_bread", "quantity": {"value": 0.005, "unit": "loaf"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}]', '[{"ingredients":["500g/ 1 lb lamb mince (or beef, or 50/50 beef/lamb, Note 1)","3 large garlic cloves (, crushed using garlic press or finely grated)","2 tsp paprika (regular/sweet, not smoked)","2 tsp mustard powder","4 1/2 tsp dried oregano","1 1/2 tsp curry powder (, not spicy, any brand fine (Kalimera secret ingredient! Note 2))","3/4 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Kofta kebab:"},{"ingredients":["1 tbsp olive oil","8 skewers (, optional (I use 18cm/7.5\"))"],"purpose":"For cooking:"},{"ingredients":["3/4 cup plain yogurt (, preferably Greek (full-fat best))","2 tbsp mayonnaise (, preferably whole-egg)","2 tbsp extra virgin olive oil","1 tbsp American yellow mustard (ie the bright yellow American stuff!)","1 1/2 tsp garlic powder","1 1/2 tsp paprika (sweet/regular, not smoked or spicy)","1/2 tsp cooking salt / kosher salt"],"purpose":"Secret Sauce (Note 3):"},{"ingredients":["4 Greek pita bread (, pockets or flatbreads, warmed (TIPS - Note 4!))","2 tomatoes (, halved and sliced)","1/2 red onion (, finely sliced or chopped)","Iceberg lettuce (, finely sliced (or other leafy greens))"],"purpose":"Serving:"}]', '[{"title":"Sauce","description":"Mix the ingredients in a bowl and set aside to let the flavours meld while you make the kofta kebabs.","images":[],"step":1},{"title":"Kofta kebabs","description":"Put all the ingredients in a bowl and mix well with your hands until the spices are mixed through. Divide into 8, shape into 13cm/5\" logs. Thread onto skewers then flatten slightly to about 1.25cm / 0.5\" thick (Note 5).","images":[],"step":2},{"title":"Cook","description":"Heat 1 tbsp oil in a large non stick pan over medium high heat. Cook half the koftas for 2 minutes on each side until golden, then about 30 seconds on each short edge (just for a bit of colour). Reduce the heat if they''re browning too fast. Transfer to a serving plate, loosely cover with foil to keep warm. Cook the remaining koftas. (Scrape out loose burnt bits, if any. You shouldn''t need extra oil.)","duration":2,"images":[],"step":3},{"description":"Serve and assemble! Pile the lettuce, tomato and onion on the plate and put the sauce in a bowl. To assemble, take a warm pita bread and smear some sauce down the middle. Top with lettuce and 1 or 2 koftas (removed from the skewers), tuck tomato down the side and sprinkle with onion. Fold and EAT!","images":[],"step":4}]', '["egg","gluten","milk","mustard"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Greek"],"categories":["greek-recipes","lamb","lamb-recipes","mains","mediterranean-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3f3c383198de', 'en', 'US', 'Porchetta - Dozer''s last recipe', 'Recipe video above. Most porchetta recipes promise epic crackling, but few deliver that properly blistered crispness all the way around. You might get bubbles on top, but the sides and underside are flat and hard skin, or worse, rubbery.This one works. It has incredible crispy crackling ALL over - top, sides and even underneath - with insanely juicy meat. See the video for proof! The keys are a 1 - 2 day fridge dry, slow roasting on low then a hot blast, salting just before roasting, and using a rack on a tray, not a roasting pan.This is the last recipe developed under Dozer''s watchful eye, so it will always hold a special place in my heart. It was a big one - but he was at my feet, cheering me on every step of the way. ❤️', 'https://www.recipetineats.com/tachyon/2026/02/Porchetta-overhead-take-2.jpg', 60, 270, 3210, 8, '[{"id": "ing_pork", "quantity": {"value": 2.5, "unit": "kg"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 30.0, "unit": "jar"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.013, "unit": "kg"}}, {"id": "ing_rosemary", "quantity": {"value": 0.9, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.1, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 2000.0, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_pork", "quantity": {"value": 2.5, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.013, "unit": "kg"}}]', '[{"ingredients":["2.5 kg / 5lb pork belly with skin on (, NOT SCORED (Note 1))"]},{"ingredients":["2 tbsp fennel seeds (Note 1)","2 tsp black peppercorns (Note 1)","2 1/2 tsp cooking salt / kosher salt (halve for table salt, +50% for salt flakes)","3 tbsp finely chopped rosemary leaves - about 1/4 cup leaves (Note 3 for dried)","2 tsp red chilli flakes (red pepper flakes)","6 large garlic cloves (, finely grated with a microplane or garlic crusher)"],"purpose":"Rub:"},{"ingredients":["2 1/2 tsp cooking salt / kosher salt (halve for table salt, +50% for salt flakes)","2 tbsp olive oil (, divided)"],"purpose":"For skin:"},{"ingredients":["3 tbsp pork belly fat (reserved from roasting)","1/4 cup plain flour / all-purpose flour","2 cups water","1/4 tsp freshly ground black pepper","Salt (, if needed (I usually don''t need))"],"purpose":"Gravy:"}]', '[{"title":"Score pork, rub, roll, tie, fridge dry on rack 24","description":"48 hours. Oil and salt skin, slow roast 110°C /215°F for 3 1/2 hours, transfer to new rack, drizzle with oil, crackle at 240°C//465°F for 30 - 40 minutes. Make gravy using tray drippings.","duration":35,"images":[],"step":1},{"title":"Marinate 1","description":"2 days","images":[],"step":2},{"title":"Toast spices","description":"Preheat a small pan over medium heat (no oil). Toast fennel seeds and black peppercorns, tossing regularly, for 1 1/2 to 2 minutes until the fennel seeds are lightly browned.","images":[],"step":3},{"title":"Porchetta rub","description":"Crush fennel and peppercorns into a coarse powder using a mortar and pestle, or spice grinder. Add remaining Rub ingredients and mix with a spoon - it will be like a thick wet paste.","images":[],"step":4},{"title":"Trim excess meat","description":"Pat the pork skin dry with paper towels. Cut off about ~3cm / 2.2\" meat along one long edge (leave the skin) so the pork rolls neatly. Do a mock roll-up to see how much to cut off - it''s ideal if the skin fully encloses the meat, but usually this isn''t possible. (Note 4 for tips). Reserve the trimmed meat - we be rolling it up insi","images":[],"step":5},{"description":"Score 3cm / 1.2\" diamonds into the flesh, taking care not to cut through the meat (~1 cm/0.4\" deep).","images":[],"step":6},{"title":"Rub","description":"Use your hands to spread the Rub into the flesh side, being sure to get into the cuts you made. Also rub the extra piece of pork you trimmed off.","images":[],"step":7},{"title":"Tie","description":"Place the trimmed piece of pork in the middle. Roll firmly then tie at 2.5cm/1\" intervals, starting at the centre then the ends, then working in towards. I do 8 equidistant ties on the skin (26cm / 10.5\" log, one end has meat oozing out so can’t be tied).","images":[],"step":8},{"title":"Fridge 1","description":"2 days - Place on a rack on a tray and refrigerate uncovered for 48 hours (24 hours is ok) to let the rub infuse the flesh and the skin dry so it crackles really well. 12 hours is my bare minimum!","images":[],"step":9},{"description":"Preheat oven to 130°C/265°F (120°C fan-forced) with the shelf in the middle. (Note 5)","images":[],"step":10},{"title":"Oil and salt skin","description":"Remove the rack from under the pork and wipe the tray clean. Working on the tray, rub the pork skin with 1 tablespoon of the oil, then sprinkle and rub the salt in. Salt will catch on the ties - try to spread it out evenly all over the skin, and roll the pork on the salt that falls on the tray. No need to bring pork to room temp before roasting, it can go in the oven cold.","images":[],"step":11},{"title":"Slow roast","description":"Put the pork on the rack again on a clean tray. Slow roast for 3 1/2 hours. The flesh should be pretty tender (use 2 forks to check ends) but not “fall apart” (not our goal). The skin should still be soft - this is what we want at this stage.","images":[],"step":12},{"title":"Oil and increase heat","description":"Remove the pork from the oven and turn it up to 240°C/465°F. Working quickly, transfer the pork still on the rack to a clean tray. (Keep the used tray for gravy drippings). Drizzle with the remaining 1 tablespoon of oil (don’t rub with fingers) then put it back in the oven - you want it in there as it is heating up.","images":[],"step":13},{"title":"Crackle skin","description":"Roast for 30 to 40 minutes, rotating at the 15 - 20 minute mark, until the skin is all puffy and crispy all over (top and sides).","duration":35,"images":[],"step":14},{"title":"Rest and carve","description":"Remove from the oven and leave it to rest for at least 30 minutes (up to 1 hour) before cutting the strings and slicing with a serrated knife. To keep it warm for longer, put it in a low 50°C/125°F oven after resting. Serve with gravy!","images":[],"step":15},{"title":"Reserve fat","description":"Pour all the fat off the slow-roasting tray from step 4 into a jug (don’t scrape, just pour).","images":[],"step":16},{"title":"Deglaze tray","description":"Pour 1/2 cup of water onto the tray set on a stove on medium. When the water starts simmering, use a rubber spatula to loosen all the bits stuck on the tray. (If you have an induction stove, use boiling water - that should be enough to delegate, or if needed, pop the tray in the oven).","images":[],"step":17},{"title":"Make gravy","description":"Measure out 3 tablespoons fat (from step 1) and put into a large saucepan. Heat on medium high, then add flour and stir for 1 minute. Whisk in water from deglazing tray, remains water and pepper. Simmer for 2 minutes or until it thickens. Taste, add salt if needed (I don’t). Serve with pork.","duration":1,"images":[],"step":18}]', '["gluten"]', '[]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["iconic-dishes","italian-recipes","mains","pork","pork-recipes","roasts"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2e090f03c9b0', 'en', 'US', 'Beef Empanadas', 'Recipe video above. This dough is easy to work with and comes together in seconds using a good processor. While I really encourage you to make the dough, you''ll still get an excellent empanada fix making this with store-bought puff pastry or shortcrust pastry.Empanada dough adapted from Kevin Is Cooking and the filling is based on the New York Times Cooking Beef Empanadas recipe (I found the flavour a bit mild and too dry, so I tweaked).', 'https://www.recipetineats.com/tachyon/2023/04/Beef-empanadas_7.jpg', 45, 50, 95, 10, '[{"id": "ing_flour", "quantity": {"value": 0.375, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 175.0, "unit": "block of 250g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_milk", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_chorizo", "quantity": {"value": 0.12, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 150.0, "unit": "bag of 2kg"}}, {"id": "ing_green_onion", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_olives", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_empanada_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_other_options", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["2 1/2 cups plain/all-purpose flour","175g/ 12 tbsp cold unsalted butter (, cut into 1 cm / 1/2\" cubes)","1 tsp cooking/kosher salt","1 egg yolk","1/2 cup warm milk (, full fat (30 sec microwave))"],"purpose":"Empanada shortcrust pastry:"},{"ingredients":["1 1/2 tbsp olive oil","1/2 onion (, finely chopped)","1 garlic cloves (, minced)","300g/10 oz beef mince (ground beef)","120g/4 oz chorizo","2 tsp tomato paste","1 tsp fresh thyme (, finely chopped)","1/2 tsp EACH dried oregano, cumin, paprika","1/4 tsp cayenne pepper","1/4 tsp cooking/kosher salt","3/4 cup chicken stock/broth (, low sodium)","1/2 cup tomato passata (sub US tomato sauce or crushed tomato)","150g/5oz potato (, peeled, cut into 8mm/ 1/3\" cubes (~1 cup))","1/3 cup green onion (, finely sliced)"],"purpose":"Empanada Filling:"},{"ingredients":["2 hard boiled eggs (9 minutes using this method)","1/4 cup green olives (, roughly chopped)","2 eggs (, separated, yolks whisked (for sealing and brushing pastry))"],"purpose":"Other:"},{"ingredients":["Empanada sauce","Other options (- ketchup, ketchup + sriracha, pink sauce, taco sauce, salsa dip)"],"purpose":"Dipping sauces:"}]', '[{"description":"Empanada Filling:","images":[],"step":1},{"title":"Blitz chorizo","description":"Roughly chop chorizo into 1.5cm / 1/2\" pieces. Blitz using a stick blender until it becomes a paste (Note 1)","images":[],"step":2},{"title":"Sauté aromatics","description":"Heat oil in a large non stick pan over high heat. Cook onion and garlic for 2 minutes.","duration":2,"images":[],"step":3},{"title":"Cook meat","description":"Add chorizo and cook for 2 minutes. Add beef and cook until you no longer see raw beef. Add tomato paste and cook for 1 minute. Then add everything else except green onion, then stir.","duration":2,"images":[],"step":4},{"title":"Cook 15 min","description":"Bring to a simmer then lower heat so it''s simmering gently. Cook for 15 minutes, stirring every now and then. Goal - juicy but not watery filling, with cooked potato.","duration":15,"images":[],"step":5},{"title":"Cool","description":"Stir through green onion. Transfer to bowl and fully cool before using (~ 2 hours).","images":[],"step":6},{"description":"Empanada shortcrust pastry:","images":[],"step":7},{"title":"Blitz dough","description":"Whisk milk and yolk in a small jug. Pulse flour, salt and butter in a food processor until the butter becomes fine crumbs - largest lumps no bigger than peas (~ 4 to 6 times). Add egg-milk mixture, then blitz on low until it comes together into a ball of dough - about 10 seconds. (Note 2 for hand method)","images":[],"step":8},{"title":"Chill 30 min","description":"Turn out onto a lightly floured work surface, then bring together into a smooth log ~20cm/8\" long. Cut in half, shape into 2cm / 0/8\" thick round discs. Wrap in cling wrap then refrigerate 30 minutes (or overnight - Note 3).","images":[],"step":9},{"title":"Cut rounds","description":"Place one chilled disc on a lightly floured work surface. Roll out to 3 mm / 0.1\" thickness. Cut 15 cm/6\" rounds (I use a bowl), or other size as desired (Note 3). Keep covered in the fridge, stacked on paper, as you continue to roll and cut. You should get 10 or 11 rounds.","images":[],"step":10},{"description":"Make empanadas:","images":[],"step":11},{"description":"Preheat oven to 220°C/425°F (200°C fan).","images":[],"step":12},{"title":"Filling","description":"Filling should be cold but spreadable (Note 4). Place 3 tablespoons (55g) of filling on the top half of a round of pastry. Spread flat in a half-moon shape, leaving a 1.5cm / 0.6\" border. Sprinkle with olive and egg.","images":[],"step":13},{"title":"Seal","description":"Brush edge with egg white, fold to enclose, pressing out air and sealing the edge. Optional: Do empanada pleats - see step photos in post or video at 3 min 30 sec. Alternatively, crimp with fork or leave plain.","images":[],"step":14},{"title":"Bake 20 min","description":"Place empanadas on 2 baking trays. Brush with egg yolk. Bake 20 minutes or until golden brown all over and crispy on the base.","images":[],"step":15},{"title":"Serve hot with dipping sauce of choice","description":"my favourite is the homemade Empanada Sauce!","images":[],"step":16}]', '["egg","gluten","milk"]', '[]', '{"mealType":["snack","dinner"],"cuisine":["Brazilian","South American"],"categories":["iconic-dishes","quiches-tart-and-pie-recipes","snacks","south-american-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c52c7aca968a', 'en', 'US', 'Toad in the hole', 'Recipe video above. The great British classic! Sausages nestled in a giant Yorkshire pudding, in all its puffed up glory, with delightfully crispy edges. The trick for stability is a dab of mayonnaise! Taught to me by an English chef, learned from his days working in pubs and restaurants in the UK. (See note 4)Some recipes will have you just bake the sausages from raw, but your gravy will be much tastier if you start with sausage drippings. So sear your sausages first!', 'https://www.recipetineats.com/tachyon/2023/02/Toad-in-the-hole_4.jpg', 15, 40, 55, 4, '[{"id": "ing_sausages", "quantity": {"value": 1.4, "unit": "pack of 500g"}}, {"id": "ing_beef", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 20.833, "unit": "carton of 12"}}, {"id": "ing_flour", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.037, "unit": "jar of 400g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 2.5, "unit": "bottle"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["700g/1.4lb pork sausages, or other sausage (8 x 85g/3oz, Note 1)","10g / 2 tsp beef drippings OR canola/veg oil (Note 4)"]},{"ingredients":["250 ml / 1 cup eggs (, lightly whisked (4-5 large eggs, yes, I need you to measure! Note 2))","1 cup plain flour (all-purpose flour)","3/4 cup milk (, full fat)","1/4 cup water","1 tbsp mayonnaise (, full-fat (secret ingredient! See Note 3))","1/2 tsp cooking salt (kosher salt)","Pinch white pepper","50g (1/4 cup) beef drippings OR canola/veg oil (Note 4)"],"purpose":"Yorkshire pudding Batter:"},{"ingredients":["30g / 2 tbsp beef drippings OR unsalted butter (Note 4)","2 onions (, halved, cut into 7 mm / 1/4\" wedges)","1 garlic clove (, finely minced)","3 tbsp plain flour (all-purpose flour)","2 cups beef stock (broth) (, low sodium)","1/2 tsp Worcestershire sauce","1/2 tsp black pepper","1/4 tsp cooking salt (kosher salt)"],"purpose":"Onion gravy:"}]', '[{"title":"Batter","description":"Whisk eggs in a bowl, then whisk in flour until lump free. Whisk in water, milk, mayonnaise, salt and pepper. Place in the fridge until required.","images":[],"step":1},{"description":"Preheat oven to 220°C/425°F (200°C fan). Put the 1/4 cup beef drippings in a 23 x 33cm metal pan (9 x 13\"). Place in the oven for 15 minutes to melt and become very hot.","duration":15,"images":[],"step":2},{"title":"Brown sausages","description":"Heat the 2 tsp (10g) of drippings in a pan over medium high heat. Brown the sausages all over, but keep one side just lightly browned (this side will brown more in the oven). Keep them raw inside. Remove onto a plate.","images":[],"step":3},{"title":"Assemble","description":"Take batter out of fridge and whisk. Working quickly, take the hot pan out of oven. Spread sausages in the pan, lightly browned side up, keeping clear of the pan walls (Note 5 for arranging tip). Pour the batter in around the sausages.","images":[],"step":4},{"title":"Bake","description":"Bake 25 minutes on the top shelf until the sides puff up and is golden brown. The top of the edges should be nice and crispy!","images":[],"step":5},{"description":"Serve immediately with onion gravy! Expect some deflation - though far less than typical recipes thanks to the mayo.","images":[],"step":6},{"description":"Onion gravy (Note 6):","images":[],"step":7},{"title":"Brown onion","description":"Add beef drippings into the pan used for browning the sausages. Melt over high heat. Add onions and cook, stirring constantly, until nicely browned (~5 minutes). Add garlic and stir 30 seconds. Add flour and stir for 1 minute so it''s well mixed through the onions (= lump-free gravy!).","duration":1,"images":[],"step":8},{"title":"Add stock","description":"Slowly pour in beef stock, stirring as you go. Add Worcestershire sauce, salt and pepper.","images":[],"step":9},{"title":"Thicken","description":"Bring to a simmer, stirring, for 2 minutes until thickens into a gravy. Keep warm until ready to use!","duration":2,"images":[],"step":10}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["British","English"],"categories":["iconic-dishes","news","sausage-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cea89452d5df', 'en', 'US', 'Borek', 'Recipe video above. If you think this Borek looks amazing, just wait until you taste it!! A spiced lamb filling littered with pine nuts and currants encased in layers up on layers of flaky filo pastry arranged in a dramatic spiral, this pastry goes by various names incuding burek, bourekas, and byrek.It''s an excellent return on effort, looking so much more difficult than it actually is to make!Vegetarian version - Use the spinach feta filling from Spanakopita!', 'https://www.recipetineats.com/tachyon/2021/07/Borek_40.jpg', 30, 60, 90, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_coriander", "quantity": {"value": 0.075, "unit": "bunch"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}, {"id": "ing_currants", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_pine_nuts", "quantity": {"value": 0.5, "unit": "pack of 100g"}}, {"id": "ing_tomato", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_yogurt", "quantity": {"value": 0.06, "unit": "tub of 500g"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_sheets_phyllo_pastry", "quantity": {"value": 12.0, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.006, "unit": "kg"}}]', '[{"ingredients":["2 tbsp olive oil","1 onion (, finely diced (1 small or 1/2 a large))","2 garlic cloves (, finely minced)","600g / 1.2 lb lamb mince (ie. ground lamb, or substitute beef)","1 1/2 tsp ground cumin","3/4 tsp each of ground coriander, cinnamon, paprika (plain or sweet paprika)","1/2 tsp allspice (sub mixed spice or similar spice mix)","1/2 tsp cayenne pepper or Turkish red pepper flakes (reduce for less spicy)","1/2 tsp black pepper","1 1/4 tsp salt (cooking / kosher salt, OR 1 tsp table salt)","1/3 cup currants (or raisins or sultanas, roughly chopped)","1/3 cup pine nuts (, toasted (Note 1))","1 cup tomato passata (tomato puree in US, Note 2)","1/4 cup water"],"purpose":"Lamb Filling:"},{"ingredients":["1 egg","2 tbsp plain yogurt","30g / 2 tbsp unsalted butter (, melted)"],"purpose":"Yogurt wash for filo (stops cracking):"},{"ingredients":["12 sheets phyllo pastry (Note 3)","25g / 1 1/2 tbsp unsalted butter (, melted and cooled)","White sesame seeds (optional)"],"purpose":"Pastry:"},{"ingredients":["1 cup plain yogurt","1/4 tsp garlic (, finely grated)","1 tbsp lemon juice","1 tbsp extra virgin olive oil","Pinch of salt"],"purpose":"Lemon Yogurt Sauce:"}]', '[{"title":"Cook onion and garlic","description":"Heat oil on high in a large skillet. Cook onion and garlic for 2 to 3 minutes until softened.","duration":2.5,"images":[],"step":1},{"title":"Cook lamb and spices","description":"Add lamb and cook lamb, breaking it up as you go, until mostly changes from pink to brown. Then add all the spices and cook for 1 minute.","duration":1,"images":[],"step":2},{"title":"Simmer","description":"Add tomato passata and water, mix. Then add currants and pine nuts. Bring to simmer, turn heat down to medium low and cook until liquid reduces so the mixture is moist but not watery.","images":[],"step":3},{"title":"Cool","description":"Remove from stove and allow to fully cool before using.","images":[],"step":4},{"description":"Lemon Yogurt Sauce:","images":[],"step":5},{"description":"Mix ingredients in a small bowl. Set aside for at least 20 minutes.","images":[],"step":6},{"description":"Preheat oven to 200°C / 390°F (180°C fan).","images":[],"step":7},{"title":"Yogurt Wash (Note 4)","description":"Mix ingredients until combined.","images":[],"step":8},{"title":"Prepare filo","description":"Open the filo pastry packet and unroll the pastry. Peel one layer off and place on a piece of baking / parchment paper. Cover the remainder with a lightweight damp tea towel to stop them from drying out.","images":[],"step":9},{"title":"Brush with yogurt wash","description":"Drizzle / flick yogurt wash across filo using a pastry brush. Then lightly brush across surface in a thin layer. You don''t need to cover every inch, just mostly cover the surface.","images":[],"step":10},{"title":"Layer filo","description":"Top with another filo pastry sheet, and brush this too with yogurt wash. Then repeat so you have 4 layers in total, but do not brush the last (4th) filo with yogurt wash once laid.","images":[],"step":11},{"title":"Fill and roll","description":"Place 1/3 of the Lamb filling along the bottom edge. Using the aid of a long kitchen knife to get it started, roll up into a log. Doesn''t need to be tight and don''t try, as the pastry is delicate.","images":[],"step":12},{"title":"Make 3 logs","description":"Repeat to make 3 logs, using all the Filling.","images":[],"step":13},{"description":"Shape into spiral and bake:","images":[],"step":14},{"title":"Spiral","description":"Take one log and place on a piece of baking / parchment paper. Coil into a spiral. Join a second log to the first by stuffing the ends inside each other, using yogurt wash to adhere. Continue forming the spiral. Log sides should be in contact but not tightly squished.","images":[],"step":15},{"title":"Transfer to baking vessel","description":"Brush a 26cm / 10.5″ cast iron skillet (Note 5) with melted butter. Then use the paper to transfer the borek into the skillet, and slide the paper out.","images":[],"step":16},{"title":"Brush with butter","description":"Brush the top with butter, sprinkle with sesame seeds.","images":[],"step":17},{"description":"Bake for 40 minutes or until pastry is golden.","duration":40,"images":[],"step":18},{"description":"Serve! Remove from oven. Cut wedges like pie. Serve with Lemon Yogurt Sauce!","images":[],"step":19}]', '["egg","milk","sesame"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Mediterranean","Middle Eastern","Turkish"],"categories":["iconic-dishes","lamb-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d3ec20059fd3', 'en', 'US', 'Easy slow cooker BBQ pulled pork', 'Recipe video above. This may well be the juiciest, most flavourful pulled pork you ever have in your life! Homemade BBQ Sauce totally makes it. And there''s no denying that using a slow cooker yields the juiciest pulled pork with very little effort. BIG BATCH recipe, 100% perfect for freezing, ideal for entertaining!Love this recipe? One day, try my ultimate Pulled Pork recipe.', 'https://www.recipetineats.com/tachyon/2019/11/Close-up-of-pulled-pork-with-BBQ-Sauce.jpg', 15, 600, 615, 12, '[{"id": "ing_pork_shoulder", "quantity": {"value": 3.5, "unit": "kg"}}, {"id": "ing_beer", "quantity": {"value": 0.758, "unit": "bottle of 330ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.5, "unit": "bottle of 500ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_molasses", "quantity": {"value": 45.0, "unit": "jar"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 20.0, "unit": "bottle"}}, {"id": "ing_tabasco", "quantity": {"value": 2.0, "unit": "unit"}}]', '[{"ingredients":["3.5-4.5kg/ 5-7lb pork butt / pork shoulder (, bone in, fat cap on (Note 1))","1 cup beer (, apple cider or apple juice (Note 2))"]},{"ingredients":["3 tbsp brown sugar","1 tbsp paprika powder","1 tbsp garlic powder","2 tsp onion powder","2 tsp mustard powder","1 tsp cumin powder","1 tbsp salt","1 tsp black pepper"],"purpose":"RUB:"},{"ingredients":["1 cup apple cider vinegar (Note 3)","3 cups tomato ketchup (or Aussie tomato sauce)","1 cup water (or use remaining beer!)","3 tbsp molasses (, orginal (not blackstrap, Note 4))","2/3 cup brown sugar","4 tsp mustard powder","3 tsp garlic powder","4 tsp Worcestershire sauce","2 tsp salt","2 tsp black pepper","2 tsp Tabasco ( or cayenne pepper (optional, for spiciness))"],"purpose":"BBQ Sauce:"}]', '[{"description":"Mix the Rub together, then rub all over the pork.","images":[],"step":1},{"description":"Place in a slow cooker, pour over beer. Slow cook on low for 10 hours. Pork should be tender enough to easily shred.","images":[],"step":2},{"description":"Browning in oven (optional, recommended):","images":[],"step":3},{"description":"Preheat oven to 180°C / 350°F.","images":[],"step":4},{"description":"Transfer from slow cooker into a roasting pan (reserve liquid).","images":[],"step":5},{"description":"Scoop fat off surface of juices in slow cooker and drizzle over pork (about 1/3 cup), then roast pork for 20 minutes.","duration":20,"images":[],"step":6},{"description":"Remove from oven, cut thick layer of fat off top and discard. Spoon over 1/4 cup fat from slow cooker juices, then roast 15 minutes.","images":[],"step":7},{"description":"Shred pork using 2 forks. Pour over BBQ sauce, toss gently.","images":[],"step":8},{"description":"Serve stuffed in sliders with Coleslaw, or make a Southern dinner plate with Coleslaw, Mac and Cheese, Corn bread, steamed corn & green beans tossed in butter, with Margaritas to quench your thirst!","images":[],"step":9},{"description":"Barbecue Sauce:","images":[],"step":10},{"description":"Place all ingredients in a saucepan and simmer over medium heat, stirring occasionally, for 45 minutes or until thickened.","duration":45,"images":[],"step":11},{"title":"Add 3/4","description":"1 cup of juices from slow cooker until sauce is syrup consistency.","images":[],"step":12},{"title":"Adjust to taste","description":"sweetness with brown sugar / honey, salt and sour with vinegar. Use per recipe.","images":[],"step":13}]', '["mustard"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["BBQ","Southern","Texas","Western"],"categories":["iconic-dishes","pork-recipes","sandwiches-and-sliders","sauces","slow-cooked-fall-apart","slow-cooker-recipes","super-bowl-party-food"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_032482eb232b', 'en', 'US', 'Reuben Sandwich recipe!', 'Recipe VIDEO above. The iconic Reuben Sandwich made famous by Katz''s Deli in New York, made at home! Hands down still one of the best sandwiches I have ever had in my life, the most incredible combination of ingredients, the star of which is warm fall-apart tender homemade pastrami!', 'https://www.recipetineats.com/tachyon/2019/04/Reuben-Sandwich_8-copy.jpg', 20, 15, 35, 5, '[{"id": "ing_homemade_pastrami", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_bread", "quantity": {"value": 0.5, "unit": "loaf"}}, {"id": "ing_cheese", "quantity": {"value": 10.0, "unit": "block of 250g"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_grapes", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_cabbage", "quantity": {"value": 7.0, "unit": "head"}}, {"id": "ing_vinegar", "quantity": {"value": 0.312, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_caraway_seeds", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_dill_pickle_gherkin", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.281, "unit": "jar of 400g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.15, "unit": "tub of 250g"}}, {"id": "ing_chilli", "quantity": {"value": 0.375, "unit": "pack of 100g"}}, {"id": "ing_horseradish_to_taste", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_paprika", "quantity": {"value": 0.031, "unit": "jar of 40g"}}]', '[{"ingredients":["1 kg / 2 lb homemade pastrami (1 quantity, easy!) (Note 1)","10 slices light rye bread","10 slices Swiss cheese","Butter (, for spreading)"]},{"ingredients":["1 tbsp grapeseed oil","1/2 onion (, thinly sliced)","350g/ 12 oz white cabbage (, thinly shredded (1/4 large head, 6 - 8 big handfuls))","1 1/4 cups (300ml) cider vinegar","1/3 cup (85 ml) water","1 tsp salt","2 tsp sugar","1 tsp caraway seeds (, optional (Note 2))"],"purpose":"Quick Sauerkraut:"},{"ingredients":["1 tbsp onion (, finely minced)","1 tbsp dill pickle/gherkin (, finely minced)","3/4 cup mayonnaise","1/4 cup sour cream (can sub more mayo)","2.5 tbsp sriracha, spicy ketchup or Chili Sauce (or 1/4 cup ketchup + 2 tsp tabasco) (Note 3)","3 tsp horseradish (jar), to taste (spicy/tang)","1 tsp Worcestershire sauce","1/4 tsp sweet paprika"],"purpose":"Russian Dressing:"}]', '[{"description":"Russian Dressing:","images":[],"step":1},{"description":"Mix ingredients, refrigerate 20 minutes+ (keeps 2 weeks).","images":[],"step":2},{"description":"Quick Sauerkraut:","images":[],"step":3},{"description":"Dissolve sugar and salt in vinegar.","images":[],"step":4},{"description":"Heat oil in a large pot over medium heat. Add onion and cook for 2 minutes to soften, don''t let it brown.","duration":2,"images":[],"step":5},{"description":"Add cabbage, vinegar, water and caraway seeds, give it a toss.","images":[],"step":6},{"description":"Cover, cook on low for 15 minutes, mixing once at 10 minutes.","duration":15,"images":[],"step":7},{"description":"Transfer to container (including liquid), cool until just warm. Keeps 2 weeks in the fridge.","images":[],"step":8},{"description":"Prepare Pastrami:","images":[],"step":9},{"description":"Thinly slice still cold pastrami (Note 1). Place in a container with a couple of tablespoons of pastrami liquid (reserved from cooking, see pastrami recipe).","images":[],"step":10},{"description":"Microwave to warm through (or use other method of choice etc cover with foil and place in oven).","images":[],"step":11},{"description":"Assemble Reuben:","images":[],"step":12},{"description":"Preheat grill/broiler to medium high with shelf about 25cm/10\" from heat source.","images":[],"step":13},{"description":"Toast bread. Spread with butter, then 1 tbsp Russian Dressing on each piece.","images":[],"step":14},{"description":"Pick up pastrami and let excess juices drip away, then place on bread.","images":[],"step":15},{"description":"Do same for sauerkraut, pile onto pastrami, then top with cheese.","images":[],"step":16},{"description":"Also place cheese on other slice of bread (ie with just Russian Dressing).","images":[],"step":17},{"description":"Place under grill until cheese is just melted. Sandwich together and devour while hot!","images":[],"step":18}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["American","Jewish"],"categories":["iconic-dishes","sandwiches-and-sliders","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ca6f84ac8c5d', 'en', 'US', 'Gozleme!!', 'Recipe video above. Crispy Turkish flatbreads stuffed with juicy fillings! Choose ONE Filling - either Spinach and Feta, or spiced Lamb OR Beef with spinach and peppers. Can stretch to 5 gozlemes. Works with GLUTEN FREE flour too!', 'https://www.recipetineats.com/tachyon/2019/03/Spinach-Feta-Gozleme.jpg', 30, 20, 50, 4, '[{"id": "ing_flour", "quantity": {"value": 0.375, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_baby_spinach", "quantity": {"value": 300.0, "unit": "bag of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_feta_cheese", "quantity": {"value": 300.0, "unit": "block of 200g"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.6, "unit": "pack of 125g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.083, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_lamb_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_cumin", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cayenne", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}]', '[{"ingredients":["2.5 cups (375g) flour (, plain/all purpose (GF Note 4))","1/3 cup (85ml) extra virgin olive oil","3/4 cup (185ml) water","1/2 tsp salt"],"purpose":"Gozleme pastry:"},{"ingredients":["300g / 10oz baby spinach","2 garlic cloves (, minced)","2 eggs","1 tsp black pepper","300g / 10 oz Danish feta (soft feta, Note 2)","2 cups (200g) shredded mozzarella cheese (Note 3)"],"purpose":"Spinach & Feta:"},{"ingredients":["1 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped)","500g / 1 lb beef or lamb mince (ground)","1 capsicum / bell pepper (, chopped)","90g / 3 oz baby spinach","1.5 tsp cumin powder","1 tsp paprika","1/2 tsp cayenne (adjust spiciness to taste)","3/4 tsp each salt and pepper","1 tbsp water","120g / 4 oz Danish feta (Note 2)"],"purpose":"Spiced Lamb or Beef:"},{"ingredients":["1 - 1.5 tbsp olive oil (, per gozleme)","Lemon wedges (optional)"],"purpose":"Cooking / Serving:"}]', '[{"description":"Fit stand mixer with dough hook. Combine flour, oil, salt and water in the stand mixer bowl. Mix for 2.5 minutes on medium high speed 7 until smooth (see video for before & after). (Note 4) Dough should be a pliable, smooth ball, not sticky.","images":[],"step":1},{"description":"Cover and rest for 20 minutes.","duration":20,"images":[],"step":2},{"description":"Sprinkle work surface with flour. Cut dough into 4 pieces.","images":[],"step":3},{"description":"Roll out into 35cm/14\" x 20cm/8\" rectangle.","images":[],"step":4},{"description":"Make EITHER the lamb / beef Filling, or Spinach & Feta (or make 1/2 batch of both!).","images":[],"step":5},{"description":"Lamb or Beef Filling:","images":[],"step":6},{"description":"Heat oil in large skillet over high heat.","images":[],"step":7},{"description":"Cook garlic and onion for 1 minute. Add capsicum, cook for 2 minutes.","duration":1,"images":[],"step":8},{"description":"Add beef and cook until it changes from pink to brown, breaking it up as you go.","images":[],"step":9},{"description":"Add cumin, paprika, cayenne (if using), salt, pepper and water. Cook for 2 minutes.","duration":2,"images":[],"step":10},{"description":"Add spinach, stir until wilted.","images":[],"step":11},{"description":"Cool before using.","images":[],"step":12},{"description":"Spinach Feta Filling:","images":[],"step":13},{"description":"Place spinach, garlic, egg and pepper in a bowl. Scrunch with hands to reduce volume and make spinach \"floppy\".","images":[],"step":14},{"description":"Add feta and stir through.","images":[],"step":15},{"description":"Making Gozleme:","images":[],"step":16},{"description":"Spread Filling on half the pastry, pushing to the edge. Sprinkle Lamb/Beef Filling with crumbled feta. Sprinkle Spinach Feta with mozzarella cheese, if using.","images":[],"step":17},{"description":"Fold other side of pastry over to cover Filling. Press down edges, pressing out excess air pockets trapped inside as you go. Use water if needed to seal well.","images":[],"step":18},{"description":"Sprinkle flour on a round pizza paddle (or similar). Slide gozleme onto paddle.","images":[],"step":19},{"description":"Cooking:","images":[],"step":20},{"description":"Heat 1.5 tbsp oil in a large skillet over medium high heat. (I usually get 2 pans going)","images":[],"step":21},{"description":"Slide gozleme into skillet. Cook, lightly pressing down (including edges), until deep golden and crispy - about 3 minutes. Flip and cook, pressing down lightly, until crispy.","images":[],"step":22},{"description":"Transfer to cutting board. Cut into 6 or 8 pieces.","images":[],"step":23},{"description":"Serve immediately with lemon wedges, if desired.","images":[],"step":24}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner","snack"],"cuisine":["Turkish"],"categories":["iconic-dishes","mediterranean-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0151e07f93dd', 'en', 'US', 'Mexican Fiesta Menu', 'Round up the amigos for a Mexican Fiesta! The suggested menu plan below is a great low-effort one with wow factor. Plenty for making ahead and the Carnitas freeze perfectly! See recipes linked to each dish, or where not linked, directions are below. Cook time includes slow cooking time for Carnitas.', 'https://www.recipetineats.com/tachyon/2018/05/Mexican-Fiesta.jpg', 60, 600, 660, 8, '[{"id": "ing_pork", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_restaurant_style_salsa", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_authentic_guacamole", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_red_cabbage", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_tortillas", "quantity": {"value": 1.0, "unit": "pack of 8"}}, {"id": "ing_tortillas", "quantity": {"value": 1.0, "unit": "pack of 8"}}, {"id": "ing_corn", "quantity": {"value": 0.003, "unit": "can of 400g"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.004, "unit": "tub of 250g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_chicken", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_shrimp", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_pico_de_gallo", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_queso_dip", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_corn", "quantity": {"value": 0.003, "unit": "can of 400g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_corn", "quantity": {"value": 0.003, "unit": "can of 400g"}}, {"id": "ing_pig_out_salsa", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_rice", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_refried_beans", "quantity": {"value": 1.0, "unit": "pack"}}, {"id": "ing_cheese", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_avocado", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_hot_sauce", "quantity": {"value": 1.0, "unit": "bottle of 150ml"}}, {"id": "ing_jalapeno", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_churros", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["Pork Carnitas","Restaurant style salsa (doubles as taco sauce + dip)","Authentic Guacamole","Pickled red cabbage (Note 1)","Warmed tortillas","Homemade tortilla chips (see below)","Grilled corn (See below)","Sour Cream","Chopped white onions (Note 2)","Coriander/cilantro leaves (whole or chopped)","Lime wedges"],"purpose":"Mexican Fiesta menu plan (as pictured in post):"},{"ingredients":["Marinated Chicken for tacos","Lime marinated chicken","Chicken Fajitas","Mexican Shredded Chicken","Beef Fajitas","Mexican Shredded Beef","Fish Tacos","Prawn/shrimp Tacos"],"purpose":"Other Protein options:"},{"ingredients":["Pico de Gallo","Queso Dip (stays silky when cool!)","Mexican Corn Salad","Avocado Corn Salad","Mexican Grilled Corn with Chipotle Adobo Sauce","Pig Out Salsa (Chorizo and Corn)","Mexican Red Rice","Refried Beans (Note 3)","Shredded Cheeses","Avocado Slices (instead of guac)","Hot Sauces","Sliced Jalapeno"],"purpose":"Other Side options:"},{"ingredients":["Churros (quick, and great for make ahead)"],"purpose":"To Finish:"}]', '[{"description":"Choose one or two proteins, then sides of choice. See linked recipes for directions (except tortilla chips and grilled corn, see below).","images":[],"step":1},{"title":"Main Taco Filling Selection","description":"The most convenient big batch protein is Pork Carnitas because it freezes great and only requires a quick pan fry to freshen up, and stays good for several hours (tips are in Carnitas recipe notes). The Shredded Chicken and Beef are almost as good (pork is slightly juicier) and stored similarly. The next simplest is Fish Tacos because it''s very quick to cook, then just put them in a serving dish and break into chunks with fork. If you want to use one of the chicken recipes to make ahead, use boneless thigh fillets, cook, then keep whole, cover and cool, reserve every drop of leached juice. Before serving, chop/slice, cover and microwave reheat.","images":[],"step":2},{"title":"Taco Fixings","description":"I like to have at least one fresh thing to stuff in tacos (pickled cabbage is my choice in this Fiesta), + a sauce (the Restaurant Style Salsa,) + avocado in some form (guac or slices or in Pico de Gallo) + coriander/cilantro. Chopped white onion is very common in Mexico, and Tex Mex fans such as myself will almost always have sour cream and shredded cheese too!","images":[],"step":3},{"title":"Other Sides","description":"Tortillas + things to stuff in tortillas usually makes for a satisfying meal in itself, but to round things out I usually provide a salad or vegetables of some form. Plain grilled corn is very on theme!","images":[],"step":4},{"description":"Directions (for items listed above without recipe link):","images":[],"step":5},{"title":"Homemade Tortillas Chips","description":"Chop corn tortillas to desired shape, fry in oil until crisp and light golden. Transfer for paper towel, sprinkle with salt while hot.","images":[],"step":6},{"title":"Grilled Corn","description":"Grill corn on BBQ over high heat until nicely charred. Brush with melted salted butter and sprinkle with chipotle powder (or chilli or cayenne, to taste)","images":[],"step":7}]', '["fish","milk","shellfish"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["iconic-dishes","mexican-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6881b7104693', 'en', 'US', 'Vegetable Samosa Pie', 'Recipe video above. Take everything you know about samosas - the curried mashed potato filling, the crispy pastry - put it in giant pie form, add a stack of extra vegetables and voila! Vegetable Samosa Pie! This is a big, vegetarian main course dinner that''s something different yet also familiar, and wonderfully versatile - stuff with any veggies you want.Simplify SPICES: I''ve stayed true to traditional Samosa filling, so there''s a fairly lengthy list of spices. It can be drastically simplified - see Notes 1 to 3.SPICINESS: Very mild - just a slight warmth. Dial it up if you want, or omit it!Blind baking / Crispy Base: See Note 5.Those who tried the South Indian Eggplant Curry I shared last week will love the common ingredients in this!', 'https://www.recipetineats.com/tachyon/2020/08/Vegetable-Samosa-Pie__2.jpg', 15, 100, 115, 6, '[{"id": "ing_potato", "quantity": {"value": 700.0, "unit": "bag of 2kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_mustard", "quantity": {"value": 0.037, "unit": "jar of 200g"}}, {"id": "ing_cumin", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_curry_leaves", "quantity": {"value": 15.0, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 5.0, "unit": "pack of 3 heads"}}, {"id": "ing_ginger", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_turmeric", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_curry_powder", "quantity": {"value": 0.2, "unit": "jar of 50g"}}, {"id": "ing_chilli", "quantity": {"value": 0.025, "unit": "pack of 100g"}}, {"id": "ing_tomato", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_cauliflower", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_sheet_puff_pastry", "quantity": {"value": 2.0, "unit": "pack"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_yogurt", "quantity": {"value": 0.002, "unit": "tub of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["700g / 1.4lb potato (, cut into 2cm / 4/5\" pieces)"]},{"ingredients":["3 tbsp vegetable oil","1.5 tsp black mustard seeds (Note 1)","1 tsp cumin seeds (Note 2)","1 tsp fennel seeds (Note 2)","15 curry leaves (, fresh (Note 3))","1 tbsp garlic (, finely grated)","1 tbsp ginger (, finely grated)","1 onion (, finely chopped (brown, white, yellow))","1/2 tsp turmeric powder","2 tsp curry powder (Note 4)","1/2 tsp chilli powder (, adjust spiciness to taste (pure ground, not US Chili Spice Mi, sub cayenne)","1 tbsp tomato paste","1 tomato * (, chopped into 1.5cm / 1/2\" pieces)","1 zucchini * (, chopped into 1.5cm / 1/2\" pieces)","1 carrot * (, chopped into 1.5cm / 1/2\" pieces)","1/2 cauliflower * (small), cut/broken into small florets (~ 3 cups)","1/2 tsp black pepper","1 tsp salt","2 cups water","1 cup frozen green peas *"],"purpose":"Filling:"},{"ingredients":["2 sheets puff pastry (Note 5)","1 egg (, lightly whisked)"],"purpose":"Puff pastry crust:"},{"ingredients":["Plain yogurt","Coriander/cilantro leaves (, option (decorative only, pictured))"],"purpose":"Serving:"}]', '[{"description":"Bring a pot of water to the boil then cook potato for 12 - 15 minutes until very soft.","duration":13.5,"images":[],"step":1},{"description":"Drain, mash and set aside.","images":[],"step":2},{"title":"Sizzling spices","description":"Heat oil in a dutch oven or pot over high heat. Add black mustard seeds, cumin and fennel seeds. Let them sizzle for 15 seconds - careful, they might pop!","duration":0.25,"images":[],"step":3},{"title":"Curry leaves","description":"Then add curry leaves and stir for 15 seconds.","duration":0.25,"images":[],"step":4},{"title":"Aromatics","description":"Add garlic, ginger and onion. Cook for 4 to 5 minutes until onion is tinged with gold.","duration":4.5,"images":[],"step":5},{"title":"Tomato","description":"Add tomato paste and tomato, cook for 30 seconds.","duration":0.5,"images":[],"step":6},{"title":"Spices","description":"Add curry powder, turmeric and chilli. Cook for 30 seconds.","duration":0.5,"images":[],"step":7},{"title":"Most Veg","description":"Add zucchini, carrot and cauliflower. Stir well to coat in the spice paste.","images":[],"step":8},{"title":"Water","description":"Add water, salt and pepper. Stir, bring to a simmer then put the lid on and reduce heat to medium low (so it''s simmer gently).","images":[],"step":9},{"title":"Cook & reduce","description":"Cook for 15 minutes until vegetables are soft. Then remove lid and simmer for 5 minutes to reduce liquid a bit.","duration":15,"images":[],"step":10},{"title":"Add mash","description":"Remove from stove. Add peas and potato, mix through well.","images":[],"step":11},{"title":"Taste","description":"Taste and add more salt and pepper if needed.","images":[],"step":12},{"title":"Cool","description":"Place lid on and cool for at least 30 minutes (even overnight is fine).","images":[],"step":13},{"description":"Preheat oven to 180°C/350°F (all oven types).","images":[],"step":14},{"description":"Grease a large pie dish with butter, or oil spray (Note 6). Drape in a puff pastry sheet.(I don''t blind bake here - see Note 5)","images":[],"step":15},{"title":"Fill with Filling","description":"slightly mounded is fine.","images":[],"step":16},{"description":"Fold in the corners of the puff pastry sheet.","images":[],"step":17},{"title":"Top with puff pastry sheet","description":"turn 90 degrees to the base puff pastry sheet (see photo).","images":[],"step":18},{"title":"Fold the overhang puff pastry under itself","description":"no need to be neat here, this is a rustic pie!","images":[],"step":19},{"title":"Egg wash","description":"Brush with egg, cut a 2cm / 1\" cross in the middle (to let steam escape).","images":[],"step":20},{"description":"Bake 50 to 60 minutes, until the top is very deep golden and flaky.","images":[],"step":21},{"description":"Stand 5 minutes then slice to serve. A dollop of plain yogurt goes well with this!","images":[],"step":22}]', '["egg","milk","mustard"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["indian-recipes","main-dishes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fc11d8b13e0d', 'en', 'US', 'Penne alla Vodka', 'Recipe video above. I think this was THE viral pasta about 5 years ago - but I totally missed the trend (not cool enough 😅). While the young probably love that it''s got vodka in it, I love it because you get to use a whole packet of pasta and a whole tub of tomato paste - no measuring, no waste!Jokes aside, vodka adds depth and almost floral-like notes into the sauce without tasting boozy, and though not a standard step, cooking off the paste really lifts the flavour and cuts the sourness. Makes regular taste just as good as the pricier double-concentrate paste!', 'https://www.recipetineats.com/tachyon/2025/08/Penne-alla-vodka_2.jpg', 5, 15, 20, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 1.25, "unit": "carton of 250ml"}}, {"id": "ing_vodka", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["500g / 1 lb penne or ziti (rigatoni is also a fave, else any other pasta)","2 tsp cooking salt / kosher salt (, for pasta cooking water)","1 1/2 tbsp olive oil","1/2 small onion (, finely diced (smaller dice than usual is better))","2 garlic cloves (, finely minced)","1/2 cup (140g / 4.5 oz) tomato paste (UK: tomato puree)","1 1/4 cups heavy / thickened cream (UK: double cream - Note 2)","1/3 cup vodka (, or chicken stock/broth for alcohol free (Note 3))","1/2 tsp red pepper flakes ((chilli flakes), 100% optional)","3/4 tsp cooking salt / kosher salt (halve for table salt)","Pinch black pepper","50g / 1 loosely packed cup freshly grated parmesan (, plus more for serving (Note 4))","1/2 cup+ pasta cooking water (Note 5)","2 tsp parsley (, finely chopped, for serving (optional))"]}]', '[{"description":"Sauté garlic and onion, cook off tomato paste, simmer with cream, vodka, chilli flakes, S&P 3 min, stir in parmesan at end. Toss with pasta and 1/2 cup pasta water, eat!","images":[],"step":1},{"title":"Cook pasta","description":"Bring a large pot of water to the boil with the pasta salt. Cook pasta per the packet directions until al dente. (Meanwhile cook the sauce)","images":[],"step":2},{"title":"⭐️ Reserve pasta water","description":"Just before draining, give the pasta a big stir to agitate the starch then scoop out a cup of the water. Then drain the pasta.","images":[],"step":3},{"title":"Sauté","description":"Heat the oil in a large pot or non-stick pan over medium high heat. Cook the onion and garlic for 1 1/2 minutes until translucent. Add the tomato paste and cook, stirring constantly, for 2 minutes until it darkens in colour (lower heat if catching on base).","duration":2,"images":[],"step":4},{"title":"Make sauce","description":"Add the cream, stir well to dissolve the tomato paste. Then add the chilli flakes, salt, pepper and vodka. Simmer on low for 3 minutes, stirring regularly. Stir in the parmesan until melted, then turn off the heat until the pasta is ready.","duration":3,"images":[],"step":5},{"description":"Toss! Add the pasta and 1/2 cup of the pasta cooking water. Over medium heat on the stove, stir for 1 - 1 1/2 minutes until all the pasta is nicely coated with the rust coloured sauce, using extra pasta cooking water to loosen if needed.","images":[],"step":6},{"description":"Serve immediately in warmed pasta bowls* with a dusting of extra parmesan and pinch of parsley. Add a side of garlic bread and big Italian Salad, then finish with Tiramisu for a classic trattoria meal at home!","images":[],"step":7}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["American-Italian","Italian"],"categories":["italian-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_deba1e59e15a', 'en', 'US', 'Easy Ricotta Gnocchi with creamy mushroom sauce', 'Recipe video above. An easy recipe for pillowy soft gnocchi made using ricotta instead of potato. It''s real Italian food - fast! Takes a third of the time to make compared to potato gnocchi, and it''s lighter and softer so you won''t feel as weighed down. Served with a creamy mushroom sauce which is to-die-for sauce for pillowy soft gnocchi. See below recipe card for more gnocchi sauces. Serves 3 as a main, 4 to 5 as a starter.', 'https://www.recipetineats.com/tachyon/2024/06/Ricotta-Gnocchi-51183.jpg', 20, 15, 30, 3, '[{"id": "ing_ricotta", "quantity": {"value": 1.0, "unit": "tub of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_egg", "quantity": {"value": 83.333, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 30.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_green_onion", "quantity": {"value": 0.5, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 2.0, "unit": "bunch"}}, {"id": "ing_mushroom", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_chardonnay", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 0.667, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["250g / 8oz ricotta (, must be full fat (Note 1))","3/4 cup (75g) freshly grated parmesan cheese (Note 2)","1 large egg (55 - 60g/2oz)","1 egg yolk (egg white use ideas here)","1/4 tsp cooking salt / kosher salt","Pinch black pepper","3/4 - 1 cup flour (plain/all-purpose), plus more for dusting (Note 3)"],"purpose":"Gnocchi"},{"ingredients":["30g / 2 tbsp unsalted butter","2 garlic cloves (, finely minced )","1/2 onion or 1 eschallot ((US: shallot), finely chopped)","2 thyme sprigs (sub 1/2 tsp dried thyme)","250g / 8oz white mushrooms (, sliced in 5mm / 0.2\" slices)","1/2 tsp cooking salt / kosher salt","1/4 tsp black pepper","1/3 cup chardonnay (or other dry white wine (skip for non alcoholic))","1/2 cup chicken stock/broth (, low sodium)","2/3 cup thickened / heavy cream (or pure cream)"],"purpose":"Creamy mushroom sauce"},{"ingredients":["Freshly grated parmesan","Fresh parsley (, finely chopped (optional))"],"purpose":"Garnish"}]', '[{"description":"Homemade ricotta gnocchi","images":[],"step":1},{"title":"Mix","description":"Put all the gnocchi ingredients in a bowl except the flour. Use a rubber spatula or wooden spoon to mix until combined (smear up the wall if needed, to help cream the ricotta).","images":[],"step":2},{"title":"Add flour","description":"Add 3/4 cup of flour and mix until just combined so it is a very sticky dough that will hold its shape in a mound, but is not runny like a muffin batter (see video for consistency). Stickier dough = softer gnocchi! Use the remaining flour, 1 tbsp at a time, if needed, but try to stick with 3/4 cup. You can always add more flour in the next step. (Note 3)","images":[],"step":3},{"title":"Form disc","description":"Sprinkle a work surface with flour then scrape the dough out onto it. Sprinkle the top lightly with flour then use your hands to give the dough a light knead to bring it into a ball then pat it into a disc about 2.5cm/1\" thick. Cut it into 8 wedges, using a knife or dough scraper dusted with flour as needed between each cut","images":[],"step":4},{"title":"Roll and cut","description":"Roll each piece into a log 25cm/10\" long, about 1.25cm / 1/2\" wide. Cut into 1.5 cm / 3/5\" pieces (Can freeze at this point - Note 4)","images":[],"step":5},{"description":"Creamy mushroom sauce","images":[],"step":6},{"title":"Cook mushrooms","description":"Melt the butter in a large pan over high heat. Add the onion, garlic and thyme sprigs. Cook for 1 minute. Add mushrooms, salt and pepper. Cook for 5 minutes until the mushrooms is softened.","duration":1,"images":[],"step":7},{"title":"Sauce","description":"Add the wine and simmer rapidly for 1 to 2 minutes, stirring to scrape the base of the pan, until mostly evaporated. Add the stock/broth and cream, then stir.","duration":1.5,"images":[],"step":8},{"title":"Simmer","description":"Bring to a simmer then reduce the heat to medium low and simmer gently for 5 minutes until thickened. (It''s ok if it seems a bit thin, the starch from gnocchi will thicken it quickly, have faith!).","duration":5,"images":[],"step":9},{"description":"Cook gnocchi & sauce it","images":[],"step":10},{"title":"Cook gnocchi","description":"Bring a large pot of water to the boil with 2 teaspoons of salt. Tumble the gnocchi in and cook for around 2 1/2 minutes, or until the gnocchi is floating on the surface for around 30 seconds, no longer (else they overcook!)","images":[],"step":11},{"title":"Sauce it","description":"Use a spider or large slotted spoon to scoop the gnocchi out of the water and straight into the sauce (excess water drips in the sauce are good!). Turn the heat up to medium and toss gently for 1 minute or until the sauce thickens and coats the gnocchi. If the sauce gets too thick, add a splash of the gnocchi cooking water.","duration":1,"images":[],"step":12},{"description":"Serve immediately, garnished with freshly grated parmesan and parsley, if desired.","images":[],"step":13}]', '["egg","gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["italian-recipes","pasta-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_990e1b1052c7', 'en', 'US', 'Sausage ragu with pappardelle pasta', 'Recipe video above. Take your meat sauce to the next level by using sausages instead of plain beef to make an incredible Sausage Ragu! Like Shredded Beef Ragu, cooking this sausage pasta sauce long and slow gives it time to develop deep, complex flavours. Complete your Italian feast with Garlic Bread, a garden salad with Italian Dressing and a beautiful Tiramisu.', 'https://www.recipetineats.com/tachyon/2016/02/Sausage-ragu_7.jpg', 20, 135, 155, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_fennel_seeds", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_sausages", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_sausages", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.333, "unit": "bottle of 750ml"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.25, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_thyme", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_chilli", "quantity": {"value": 0.013, "unit": "pack of 100g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["2 tbsp olive oil","1 small onion (, finely chopped)","3 garlic cloves (, finely minced)","1 carrot (, peeled and grated using a box grater (Note 1))","2 celery stalks (, grated using a box grater (Note 1))","1 tsp fennel seeds","350g / 12 oz pork sausages (, meat removed from casings (Note 2))","350g / 12 oz beef sausages (, meat removed from casings (Note 2))","2 tbsp tomato paste","1 cup pinot noir red wine (sub 0% alcohol red wine or more chicken stock)","1 cup chicken stock/broth (, low sodium)","400g/14 oz can crushed tomato","3 thyme sprigs (or 1/2 tsp dried)","2 bay leaves (fresh better, else dried)","1/2 tsp cooking salt / kosher salt","1/2 tsp black pepper","1/4 tsp chilli flakes ( (red pepper flakes), optional (for hint of heat))"],"purpose":"Sausage ragu:"},{"ingredients":["500g/ 1 lb pappardelle pasta (, or other pasta (80g/2.8oz per serving) (Note 3))","Parmesan or parmigiano reggiano (, finely grated, for serving)","Parsley (, finely chopped, optional garnish (just a pinch))"],"purpose":"To serve:"}]', '[{"description":"Preheat oven to 180°C (160°C fan-forced).","images":[],"step":1},{"title":"Soffrito","description":"Heat the oil in a large heavy based pot (with a lid) over medium heat. Add the onion, garlic, carrot, celery and fennel seeds. Cook for 8 minutes until the carrot is soft and sweet, but not golden.","duration":8,"images":[],"step":2},{"title":"Cook sausage","description":"Turn the heat up to high and add the sausage. Cook, breaking it up as you go, as best you can. It doesn''t crumble as well as mince/ground meat but that''s ok, we will break it up more later.","images":[],"step":3},{"title":"Deglaze","description":"Once the meat is no longer pink (it doesn''t really brown), add the tomato paste. Cook for 1 minute. Add the wine and let it simmer rapidly for 2 minutes until reduced by half, stirring regularly to scrape the base of the pot clean.","duration":1,"images":[],"step":4},{"title":"Slow cook #1 (1 hr)","description":"Add the remaining ragu ingredients. Stir, bring to a simmer, put the lid on and place it in the oven for 1 hour.","images":[],"step":5},{"title":"Slow cook #2 (45 min)","description":"Remove from the oven and use a potato masher to mash the meat finer. Put the lid back on, and return to the oven for 45 minutes. The sauce will be quite thick, it gets loosened when tossed with the pasta.","duration":45,"images":[],"step":6},{"title":"Salt","description":"Taste and add more salt if desired. (Sausages vary in saltiness so I always start with less)","images":[],"step":7},{"title":"Cook pasta","description":"Cook the pappardelle according to the packet instructions. Just before draining, scoop out 1 1/2 cups of the cooking water and set it aside.","images":[],"step":8},{"title":"Toss with sauce","description":"Have the ragu pot on the stove over medium heat. Add the pasta into the pot along with 1/2 cup of the pasta cook water. Use two spatulas to toss the pasta until the ragu is tangled in the pasta strands and it is stained red from the sauce. Use extra pasta cooking water if needed to loosen it up.","images":[],"step":9},{"description":"Serve in pre-warmed bowls, garnish with parmesan and a pinch of parsley if desired. Eat immediately!","images":[],"step":10}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["italian-recipes","main-dishes","most-popular","pasta-recipes","slow-cooked-fall-apart","slow-cooker-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_10d82007651a', 'en', 'US', 'Spaghetti alla Puttanesca', 'Recipe video above. Spaghetti alla Puttanesca is a traditional Italian pasta from Naples with a sauce based on pantry essentials. This plants it firmly in the (excellent) emergency-meals collection!You don''t need much salt in Puttanesca sauce because the olives, capers and anchovies provide the seasoning. Don''t skip the anchovies - sauteeing it cooks out the fishy flavour and it just dissolves in the sauce, leaving behind savoury flavour you can''t get from just plain salt. You''d have to have a finely attuned palette to even know it''s in the sauce!', 'https://www.recipetineats.com/tachyon/2021/08/Spaghetti-Puttanesca_64-SQ.jpg', 5, 15, 20, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_fish_fillets", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_pitted_black_olives", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_capers", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_chilli", "quantity": {"value": 0.013, "unit": "pack of 100g"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.013, "unit": "jar of 50g"}}, {"id": "ing_sugar", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["200g / 7oz spaghetti (, or other long pasta)","2 tbsp extra virgin olive oil (, plus more for drizzling)","2 garlic cloves (, finely minced (knife, not garlic press))","3 anchovy fillets (, finely minced (Note 1))","1/4 cup pitted black olives (, preferably in oil, quartered (Note 2))","1 tbsp capers (, drained (Note 3))","1/4 tsp chilli flakes (red pepper flakes)","400g / 14oz can crushed tomato (or hand crush whole canned tomatoes)","1/2 cup water","1 tsp fresh oregano (, roughly chopped (sub 1/4 tsp dried))","1/8 tsp kosher / cooking salt (or 2 pinches table salt)","1/8 tsp black pepper","1/4 tsp sugar (, if needed (depends on tomato quality, Note 4))","2 tbsp fresh basil (, roughly chopped (Note 6))"]}]', '[{"title":"Prepare","description":"Bring a large pot of water to the boil, ready for the pasta. Warm serving bowls (I microwave 1 minute).","images":[],"step":1},{"title":"Cook garlic","description":"Heat olive oil in a medium skillet over medium high heat. Add garlic and cook for 15 seconds until it starts turning golden.","duration":0.25,"images":[],"step":2},{"title":"Cook anchovies","description":"Add anchovies, capers, olives and chilli flakes. Cook for 1 minute.","duration":1,"images":[],"step":3},{"title":"Tomato","description":"Add tomato, then add the 1/2 cup of water into the can. Swirl around to rinse then pour into the skillet.","images":[],"step":4},{"title":"Simmer","description":"Add oregano, salt and pepper. Stir, bring to simmer, then turn down to low and cook over medium heat for 10 minutes or until the tomato has broken down and created a sauce. Turn off stove when ready if not timed with cooked pasta.","duration":10,"images":[],"step":5},{"title":"Cook pasta","description":"Meanwhile, add 2 teaspoons salt into the pot of water. Then add pasta and cook per packet directions.","images":[],"step":6},{"title":"Reserve pasta water (Note 5)","description":"Just before draining, scoop out a mugful of pasta cooking water and set aside. Then drain pasta in a colander.","images":[],"step":7},{"title":"Toss pasta","description":"Immediately add pasta into sauce. Add 1/4 cup of pasta cooking water reserved from previous step (Note 5) then use 2 wooden spoons to toss the pasta, still on a low stove, for 1 minute or until the sauce is no longer in the skillet but rather clinging to the pasta strands (but still slick and slippery). If the pasta gets too dry, add more pasta cooking water and toss.","duration":1,"images":[],"step":8},{"title":"Serve","description":"Immediately transfer into warmed bowls. Drizzle with olive oil, sprinkle with basil. Serve immediately!","images":[],"step":9}]', '["fish","gluten"]', '[]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["dinner-tonight","italian-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_37bb95f22138', 'en', 'US', 'Pasta alla Norma (Eggplant pasta)', 'Recipe video above. This is a traditional Italian pasta dish from Sicily, usually begun by cooking eggplant on the stove in a hefty amount of oil. I prefer roasting the eggplant - less oil plus the eggplant holds its shape better, especially when you roast at a high temp to caramelise the surface!Finishing with a good amount of fresh basil is traditional but even if you don''t have any, there''s other alternatives to add a touch of other flavour - such as fresh thyme, or extra dried herbs in the sauce.This is an excellent and satisfyingly "meaty" vegetarian main dish that will have even card-carrying carnivores asking for seconds!', 'https://www.recipetineats.com/tachyon/2020/11/Pasta-alla-norma-eggplant-pasta_6.jpg', 10, 45, 55, 4, '[{"id": "ing_egg", "quantity": {"value": 66.667, "unit": "carton of 12"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.7, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_italian_herbs", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_basil", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["800g / 1.6 lb eggplant (, cut into 2.5cm/1\" cubes (2 medium/large ones))","2 tbsp extra virgin olive oil","1/2 tsp each salt and pepper"]},{"ingredients":["2 tbsp extra virgin olive oil","2 garlic cloves (, finely minced)","1/2 small onion (, very finely chopped (or 2 eschallots))","1/4 cup dry white wine (, anything not too sweet or woody (Note 1))","700g / 24 oz tomato passata (aka tomato puree, Note 2)","1/4 cup water","1 tsp dried Italian herbs (or oregano)","1/2 tsp red pepper flakes (, optional (for a hint of heat))","1/2 tsp each salt and pepper","300g / 10 oz spaghetti or other pasta, long or short (macaroni, rigatoni, penne, ziti, fettucini, bucatini)"],"purpose":"Pasta Sauce:"},{"ingredients":["1/2 cup basil leaves (, roughly chopped (Note 3))","Parmesan cheese (, grated (or ricotta salata if you have it - more traditional))"],"purpose":"Serving:"}]', '[{"description":"Roasted eggplant:","images":[],"step":1},{"description":"Preheat oven to 240°C / 450°F (220°C fan). Line a tray with baking / parchment paper.","images":[],"step":2},{"description":"Toss eggplant with oil, salt and pepper. Spread on the tray and roast for 20 minutes.","duration":20,"images":[],"step":3},{"description":"Flip, then roast for a further 5 minutes. Cool on tray (this helps the eggplant hold its shape when tossing).","images":[],"step":4},{"description":"Cooking pasta:","images":[],"step":5},{"description":"Bring a large pot of salted water to the boil. Start cooking the pasta a couple of minutes after you start making the sauce (next section), until al dente or to your liking.","images":[],"step":6},{"description":"Heat oil in a very large skillet over medium heat. Add garlic, cook for 20 seconds until golden, then add onion and cook for 2 to 3 minutes until translucent and cooked through.","duration":0.3333333333333333,"images":[],"step":7},{"description":"Increase heat to medium-high and add wine, if using. Let it simmer, scraping the base of the pan to deglaze, until the wine mostly evaporates.","images":[],"step":8},{"description":"Add tomato passata. Now pour the water into the passata bottle, screw on the lid, shake, and pour that in too (waste nothing!)","images":[],"step":9},{"description":"Add dried herbs, red pepper flakes, salt and pepper. Stir and simmer 5 minutes.","images":[],"step":10},{"description":"Stir in eggplant, then add cooked and drained pasta. GENTLY toss until pasta is coated in the sauce (so the eggplant doesn''t turn into complete mush!).","images":[],"step":11},{"description":"Serve immediately, garnished with a good pinch of fresh basil and parmesan.","images":[],"step":12}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["Italian"],"categories":["italian-recipes","pasta-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_3b53a0875c54', 'en', 'US', 'Creamy Garlic Prawn Pasta', 'Recipe VIDEO above. Pasta tossed with a garlic infused creamy sauce and plump, juicy prawns! (Shrimp) This pasta version of Creamy Garlic Prawns is a quick meal you''ll get on the table in 20 minutes, this is luscious but it''s not too rich. The key is to emulsify the sauce (i.e. thicken it) by tossing the pasta in the sauce just before serving - this is the proper Italian way to make pasta. Serves 4.', 'https://www.recipetineats.com/tachyon/2017/11/Creamy-Garlic-Prawn-Pasta-4.jpg', 5, 20, 25, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.68, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_shrimp", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_cream", "quantity": {"value": 1.25, "unit": "carton of 250ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}]', '[{"ingredients":["12 oz / 350g fettuccine (, or other long strand pasta of choice)","50 g / 3 tbsp unsalted butter (, separated)","500 g / 1 lb small or medium peeled prawns / shrimp (, raw or 1kg / 2 lb whole unpeeled (Note 1))","4 garlic cloves (, finely minced with a knife)","1/2 cup Chardonnay or other dry white wine (Note 2 for sub)","1 1/4 cups heavy / thickened cream (or regular cream, pouring cream etc, full fat (Note 3))","1/2 cup chicken broth ((or fish or vegetable broth), preferably low sodium)","3/4 cup (75 g) finely grated parmesan cheese (freshly grated) (Note 4)","2 tbsp finely chopped parsley (, optional)","Black pepper","Parmesan (, for serving)"]}]', '[{"title":"Cook pasta","description":"Bring to boil a large pot of water. Add a big pinch of salt and the pasta, then cook per packet MINUS 1 minute - it will finish cooking in the sauce later so we want it slightly under. (Note 5).","images":[],"step":1},{"title":"Reserve water","description":"Just before draining, scoop out 1 cup of pasta cooking water and set aside, we need this to thicken the sauce later. Drain pasta.","images":[],"step":2},{"title":"Lightly cook prawns in 2 batches","description":"Meanwhile, melt about 1/3 of the butter in a large non stick skillet over medium high heat. Add half the prawns, spread out, and cook for 1 1/2 minutes, then turn and toss using 2 spatulas for another 1 - 1 1/2 minutes until just barely cooked (the prawns will cook more in the sauce). Remove prawns into a bowl. Repeat - add half the remaining butter, cook the remaining prawns then remove.","images":[],"step":3},{"title":"Sauté garlic","description":"In the same skillet, add the remaining butter. Once melted, add the garlic and stir for 20 seconds until fragrant (don''t let it burn, lower heat it needed).","duration":0.3333333333333333,"images":[],"step":4},{"title":"Deglaze","description":"Add wine and stir. Simmer rapidly for 2 minutes, scraping the pan to dissolve any bits stuck to it into the liquid, until wine mostly evaporates (see video).","duration":2,"images":[],"step":5},{"title":"Sauce","description":"Add cream, broth and parmesan. Stir until the parmesan is melted, then leave to simmer for 1 1/2 minutes until it thickens slightly - it will still be quite watery though which is fine, it will thicken more in next step.","images":[],"step":6},{"title":"Toss & thicken sauce","description":"Add prawns, pasta plus about 1/4 cup of reserved pasta water. Toss pasta energetically (still on stove on medium high) and in 1 to 2 minutes, the sauce will thicken and start clinging to the pasta. It will seem like nothing is happening at first but trust the process, it will happen! If you take it too far and the sauce gets too thick, add a small splash of remaining reserved pasta cooking water to loosen and toss again (you can do this repeatedly as needed).","images":[],"step":7},{"title":"Finish","description":"Add most of the parsley and a grind of black pepper, taste and check if you need salt (I don''t need more), then give it a quick toss.","images":[],"step":8},{"description":"Serve immediately, garnished with remaining parsley and parmesan if desired.","images":[],"step":9}]', '["fish","gluten","milk","shellfish"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","italian-recipes","main-dishes","pasta-recipes","prawns-shrimp","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8833556f0dfa', 'en', 'US', '$2 Homemade Frozen Pizzas', 'VIDEO above. Stock your freezer with these quick homemade frozen pizzas! Made with store bought flatbreads, these thin and crispy pizzas are baked from frozen. Terrific economical standby meal, feel free to use your toppings of choice. Makes 10 pizzas, 25cm / 10" diameter.', 'https://www.recipetineats.com/tachyon/2017/10/Homemade-Frozen-Pizza_2.jpg', 20, 40, 60, 10, '[{"id": "ing_bread", "quantity": {"value": 0.013, "unit": "loaf"}}, {"id": "ing_salami", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_black_olives", "quantity": {"value": 112.5, "unit": "bottle"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_mushroom", "quantity": {"value": 15.0, "unit": "kg"}}, {"id": "ing_mozzarella", "quantity": {"value": 3.2, "unit": "pack of 125g"}}, {"id": "ing_cheese", "quantity": {"value": 400.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["10 Greek pita bread (thick round flatbreads, 25cm / 10\" diameter) (Note 1)","250 g / 8 oz salami sliced (, chopped)","3/4 cup / 100 g sliced black olives (, drained)","1 large green capsicum / bell pepper (, sliced)","1 large red onion (, chopped)","15 medium mushrooms (, sliced (~golf ball size))","400 g / 14 oz / 4 cups shredded mozzarella cheese","300 - 350 g / 10 - 12 oz / 3.5 cups shredded Monterey Jack"]},{"ingredients":["1/4 cup / 65 ml extra virgin olive oil","3 garlic cloves (, minced)","800 g / 28 oz crushed canned tomato","2 tbsp tomato paste","1/2 cup / 125 ml water","1 tsp dried oregano","1 tsp dried thyme","1 tsp red chilli flakes (adjust to taste)","3/4 tsp salt","1/2 tsp black pepper"],"purpose":"Easy Homemade Pizza Sauce (Note 3):"}]', '[{"description":"Heat olive oil in a large saucepan over medium heat. Add garlic and cook for 1 minute until fragrant. Add remaining ingredients, stir, and adjust heat so it is simmering gently (about medium heat). Cook down for 40 minutes, then puree with a stick (or cool a bit then transfer to blender).","duration":1,"images":[],"step":1},{"description":"COOL before using (hot sauce = soggy base). (Note 4)","images":[],"step":2},{"description":"Top a flatbread with 2.5 tbsp of Sauce. Sprinkle a tiny amount of cheese over the base, avoiding the very edges (glue for toppings - see video).","images":[],"step":3},{"description":"Sprinkle over onion, capsicum, salami, olives, mushrooms then cheese. Repeat with remaining flatbreads.","images":[],"step":4},{"description":"Stack them using paper in between each pizza. Wrap in groups of 3 or so (whatever you are comfortable handling). Transfer to a large airtight container or ziplock bag and freeze.","images":[],"step":5},{"description":"Remove oven shelf from oven and clean.","images":[],"step":6},{"description":"Preheat oven to 240C/460F (standard) / 220C / 430F (fan/convection).","images":[],"step":7},{"description":"Place frozen (or unfrozen freshly made) pizza directly on shelf. Bake for 10 minutes or until golden on the edges and the base is crispy.","duration":10,"images":[],"step":8},{"description":"Cut and serve immediately!","images":[],"step":9}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","italian-recipes","main-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_212bae0c1c61', 'en', 'US', 'Sausage Pasta', 'A super quick meal made using chopped Italian Sausages that end up looking like mini meatballs! The sausages are the flavour base for this sauce, so get the best quality ones you can afford. Look for sausages where you can see little white chunks of fat and seasoning. Avoid the cheap sausages that are a uniform pink colour.', 'https://www.recipetineats.com/tachyon/2017/08/Sausage-Pasta-3.jpg', 5, 15, 20, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_sausages", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 1.0, "unit": "bag of 250g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["250 g / 0.5 lb spiral pasta (Note 1)","500 g / 1 lb good Italian sausages (, or other quality sausages of choice)","1 tbsp olive oil","1 small onion (, finely chopped)","2 garlic cloves (, minced)","800 g / 28 oz crushed tomato (or tomato passata)","1 tsp chilli flakes / red pepper flakes (adjust to taste)","Salt and pepper","1 - 2 big handfuls baby spinach (optional)"]},{"ingredients":["Basil leaves (, finely sliced)","Parmesan"],"purpose":"Garnish:"}]', '[{"description":"Bring a large pot of water to the boil. Cook pasta per packet directions MINUS 1 -2 minutes.","images":[],"step":1},{"description":"Just before you drain, RESERVE 1 cup of pasta cooking water. Then drain pasta.","images":[],"step":2},{"description":"Use a sharp knife to cut sausages into chunks about 1.5cm/3/5\". It will get a bit smeary and the chunks will be weird shapes - don''t worry, it self fixes while cooking!","images":[],"step":3},{"description":"Heat oil in a large skillet over high heat. Add sausages and cook until quite browned on the outside, doesn''t have to be cooked through inside.","images":[],"step":4},{"description":"Add onion and garlic, cook for 2 minutes until onion is translucent and sausages are very browned.","duration":2,"images":[],"step":5},{"description":"Add tomato, chilli flakes, pinch of salt and pepper. Mix and turn heat down to medium. Lets it bubble away energetically for 8 minutes or until it is quite thickened, stirring every now and then.","duration":8,"images":[],"step":6},{"description":"Add baby spinach (if using), pasta, and about 1/2 cup pasta cooking water. Toss quickly, no longer than 1 minute (otherwise the pasta may start to break).","images":[],"step":7},{"description":"Remove from stove, and serve immediately, garnished with plenty of basil and parmesan. Enjoy!","images":[],"step":8}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["American-Italian","Western"],"categories":["dinner-tonight","italian-recipes","main-dishes","pasta-recipes","quick-and-easy","readers-choice"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8ebe6852c899', 'en', 'US', 'Easy Pumpkin Gnocchi with Sage Butter Sauce', 'VIDEO ABOVE. This is a super easy way to make gnocchi and the secret ingredient is ricotta which keeps the gnocchi soft and pillowy inside. Much easier than the classic recipe made with potato. It tastes unbelievable - soft inside, touch of sweet, golden crisp surface and finished with a classic Sage Butter Sauce! Makes 2 very generous servings or 4 as a starter.', 'https://www.recipetineats.com/tachyon/2017/06/Pumpkin-Gnocchi-a.jpg', 20, 10, 30, 4, '[{"id": "ing_pumpkin", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_ricotta", "quantity": {"value": 0.3, "unit": "tub of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_egg", "quantity": {"value": 1.0, "unit": "carton of 12"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_sage", "quantity": {"value": 20.0, "unit": "kg"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}]', '[{"ingredients":["300 g /10oz fresh pumpkin (, steamed or boiled then mashed or 2/3 cup canned pumpkin puree)","1/2 cup ricotta (, full fat (Note 2))","1 1/4 cup plain flour ((all purpose flour), plus more for dusting)","1/3 cup parmesan cheese (, finely grated)","1 egg","1/4 tsp salt","Black pepper"],"purpose":"Gnocchi Dough"},{"ingredients":["1 tsp olive oil","50g / 3.5 tbsp butter (Note 3)","20 fresh sage leaves"],"purpose":"Sage Butter Sauce:"},{"ingredients":["Black pepper (and salt if needed)","Parmesan"],"purpose":"To serve:"}]', '[{"description":"Line a colander with 4 sheets of paper towel. Spread the fresh mashed pumpkin or canned puree onto the paper towel (see photo in post) then leave for 5 minutes.","duration":5,"images":[],"step":1},{"description":"Measure out 1/2 cup of pumpkin puree (scale up if you scaled recipe, Note 6).","images":[],"step":2},{"description":"Place pumpkin and remaining Gnocchi ingredients in a bowl. Use a wooden spoon to mix well - it should be a soft dough. (Note 4)","images":[],"step":3},{"description":"Dust a work surface with flour, tip dough out, sprinkle with flour then pat into log shape.","images":[],"step":4},{"description":"Cut into 6 pieces. Roll into 1.7cm / 2/3\" ropes, then cut into squares (Note 5).","images":[],"step":5},{"title":"Optional","description":"Use a fork to press down lightly on the cut side of the gnocchi.","images":[],"step":6},{"description":"Cooking","images":[],"step":7},{"description":"Bring a large pot of water to the boil.","images":[],"step":8},{"description":"Scrape gnocchi onto parchment paper, then tip into water. Cook for 1 minute or until all the gnocchi rises to the surface (means it is cooked), then drain.","duration":1,"images":[],"step":9},{"description":"Meanwhile, melt about 1 teaspoon of the butter plus oil in a large skillet over medium high heat. Add gnocchi and cook, shaking the pan, until the gnocchi is just starting to turn brown (about 1 1/2 minutes).","images":[],"step":10},{"description":"Add remaining butter, once it melts, add sage leaves. Stir and cook for 2 1/2 minutes or until gnocchi is golden, sage is crisp and butter is slightly browned. Add salt if you used unsalted butter.","images":[],"step":11},{"description":"Serve immediately, garnished with parmesan and pepper.","images":[],"step":12}]', '["egg","gluten","milk"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner","snack"],"cuisine":["Italian","Western"],"categories":["italian-recipes","pasta-recipes","pumpkin","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1fb717cccf92', 'en', 'US', 'Pan Fried Gnocchi with Pumpkin & Spinach', '{See video below} Soft fluffy gnocchi, pan fried in butter to create a beautiful golden crust then tossed with roasted pumpkin & spinach in a butter sauce. I use pumpkin to fill out this recipe because it has far less calories than gnocchi for the same weight and it adds a gorgeous flavour to this dish!', 'https://www.recipetineats.com/tachyon/2017/02/Gnocchi-with-Roasted-Pumpkin-Spinach.jpg', 15, 20, 35, 2, '[{"id": "ing_pumpkin", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_gnocchi", "quantity": {"value": 350.0, "unit": "pack"}}, {"id": "ing_butter", "quantity": {"value": 45.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_baby_spinach", "quantity": {"value": 80.0, "unit": "bag of 250g"}}, {"id": "ing_sage", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 1.0, "unit": "pack of 200g"}}]', '[{"ingredients":["500g/1lb pumpkin, cut into 2cm / 4/5\" pieces","1 tbsp olive oil","350g/12oz gnocchi, store bought (Note 1)","45g / 3 tbsp butter, salted (unsalted also ok, just add more salt)","1 garlic clove (large), minced","80g / 2.5oz baby spinach leaves","1/2 tsp fresh sage, finely sliced","Salt & pepper","Parmesan cheese, freshly grated"]}]', '[{"description":"Preheat oven to 200C/390F. Place pumpkin in a large bowl, drizzle with oil, sprinkle with salt and pepper. Toss to coat, spread out on tray and bake for 20 - 25 minutes, turning once, until golden and soft inside. Set aside.","duration":22.5,"images":[],"step":1},{"description":"Bring a large pot of water to the boil, add a good pinch of salt. Cook gnocchi according to packet directions, or until gnocchi pops to the surface of the water (see video). SCOOP OUT a large mug of cooking water, then drain gnocchi.","images":[],"step":2},{"description":"Place butter in a skillet then put on the stove over medium high heat. Once it foams, add gnocchi immediately. Stir, turn up the heat to high, then leave to cook for about 30 seconds.","images":[],"step":3},{"description":"Add garlic and sage, then stir / toss for no longer than 1 1/2 minutes (i.e. 2 minutes in total - see note 2) until gnocchi is golden on both sides.","images":[],"step":4},{"description":"Add about 3/4 cup of gnocchi cooking water and toss - the water will evaporate quickly and transform into a sauce.","images":[],"step":5},{"description":"Then add the pumpkin, spinach and about 1/4 cup of cooking water. Stir quickly , then season with salt and pepper. Toss then serve immediately with freshly grated parmesan.","images":[],"step":6}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":[],"categories":["dinner-tonight","italian-recipes","main-dishes","pasta-recipes","pumpkin","quick-and-easy","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bfb38911c291', 'en', 'US', 'Poulet Rôti - French Roast Chicken', 'Recipe video above. You''ve been asking for a simple but delicious roast chicken? Say no more! You must try this French roast chicken. With a herbes de Provence butter tucked under its skin and cooked over potato chunks and whole cloves of garlic, this pot roast chicken will be the juiciest piece of meat you''ve had for a long time. So now it''s time to treat yourself! Say "Oui, oui!" to juicy chicken fragrant with herbs, confit garlic and melt in your mouth potatoes! Please make sure you don''t cut the potatoes too small else they will turn to mush before the chicken is cooked. Cut to the size I specify.', 'https://www.recipetineats.com/tachyon/2026/04/Poulet-Roti_6.jpg', 40, 70, 110, 4, '[{"id": "ing_chicken", "quantity": {"value": 1.8, "unit": "kg"}}, {"id": "ing_herbes_de_provence", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_potato", "quantity": {"value": 750.0, "unit": "bag of 2kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}]', '[{"ingredients":["1.8kg / 4lb whole chicken (Note 1)","1 1/2 tsp herbes de Provence (, buy or make your own (Note 2))","3 thyme sprigs (, optional)","3/4 tsp cooking salt / kosher salt (, halve for table salt, +50% for flakes)","1 tbsp extra virgin olive oil"]},{"ingredients":["100g / 1 stick unsalted butter (, softened)","2 garlic cloves (, finely grated)","3 tsp herbes de Provence (Note 2)","1 tsp cooking salt / kosher salt (, halve for table salt, +50% for flakes)"],"purpose":"Herbs Butter"},{"ingredients":["750g / 1.65lb starchy potatoes","8 garlic cloves (, whole, unpeeled)","3/4 tsp cooking salt / kosher salt (, halve for table salt, +50% for flakes)","1/2 tsp black pepper","3 tbsp extra virgin olive oil"],"purpose":"Potatoes"}]', '[{"description":"Spread Herb Butter under chicken skin. Rub chicken with oil, salt inside and skin. Roast on potatoes and garlic – covered 30 minutes at 210°C / 410°F (190°C fan-forced), then 40 minutes uncovered, basting 3 times, or until the internal temperature reaches 72°C. Rest upright 15 minutes.","images":[],"step":1},{"description":"Preheat oven to 210°C / 410°F (190°C fan-forced). Place a 28cm cast-iron pot (no lid) in the oven to heat up.","images":[],"step":2},{"title":"Bring chicken to room temp","description":"Remove the chicken from the fridge and its packaging. Place it on a plate and let it sit on the counter while you prepare everything else. (Note 4)","images":[],"step":3},{"title":"Make herb butter","description":"In a small bowl, mix the softened butter with herbes de Provence, salt and finely grated garlic until well combined. Set aside.","images":[],"step":4},{"description":"Prepare Chicken and Potatoes","images":[],"step":5},{"description":"Pat the chicken completely dry with paper towels, including the skin and inside the cavity.","images":[],"step":6},{"title":"Loosen the skin","description":"From the tail end, gently slide an upside down spoon (not too large, dessert size is ideal for this) between the skin and the breast meat using slow sweeping motions to break membrane connecting them. After the breasts, use the same technique for the thighs and drumsticks. (Note 5)","images":[],"step":7},{"title":"Add butter under the skin","description":"Start with the breast, spoon 2/3 of the butter directly onto the meat under the skin and gently press on the outside of the skin with your hands to flatten and spread it all over evenly. Then divide the remaining butter between the two legs and spread it the same way. (Note 6)","images":[],"step":8},{"title":"Season and finish the chicken","description":"Season inside the cavity with 1/4 tsp salt, Herbs de Provence and thyme sprigs. Tie the drumsticks tightly together. Rub the whole chicken with olive oil and season the outside evenly with the remaining salt. Tuck the wings under and set aside on the counter.","images":[],"step":9},{"title":"Prepare potatoes","description":"Place potatoes, whole garlic cloves, salt, pepper and olive oil in a mixing bowl. Toss well to coat, then set aside.","images":[],"step":10},{"title":"Roast covered","description":"Carefully remove the hot pot from the oven. Place the potatoes at the bottom, then place the chicken on top. Cover loosely with foil and roast for 30 minutes. (Note 7)","duration":30,"images":[],"step":11},{"title":"Baste and continue roasting","description":"Remove the pot from the oven and take off the foil. Baste the chicken with the juices in the pot, moving the potatoes aside if needed to access the liquid (a spoon works fine, though a baster is perfect for this). Return to the oven and roast uncovered for 40 minutes, basting twice more until the internal temperature at the thigh joint reaches 72°C / 162°F (if slightly over, don’t stress, this one is very forgiving). (Note 8)","duration":40,"images":[],"step":12},{"title":"Rest (very important!)","description":"Lift and rest the chicken on its side in the pot, legs up, breast side down. Baste once more with the juices, then rest for 15 minutes. (Note 9)","duration":15,"images":[],"step":13},{"title":"Serve","description":"Carve the chicken (See video. Don''t forget the oysters, the small, very tender pieces of meat on the back near the thigh. There are only two, and they are the best bites. Easy to miss, so don’t forget them!) and serve with the potatoes, all the pan juices and a sprinkle of fresh thyme leaves. Enjoy! (Note 10)","images":[],"step":14}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["French"],"categories":["jbs-recipes","main-dishes","roasts"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_529970970327', 'en', 'US', 'Coquillettes au Jambon - French Macaroni and Cheese with Ham', 'Recipe Video above. A stovetop mac & cheese, that''s what this is really! Without the hassle of baking it! This dish was a big part of my childhood diet and even now but somehow never got sick of it. Who wouldn''t? Pasta, cheese sauce and ham. A great comfort meal, done fast and done right. Enjoy!', 'https://www.recipetineats.com/tachyon/2026/04/Coquilettes-au-jambon_0.jpg', 10, 15, 25, 5, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_ham", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_flour", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_milk", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_round_nutmeg", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}]', '[{"ingredients":["500g / 1 lb elbow pasta / macaroni (, but any similar size pasta would work )","1 tsp cooking salt / kosher salt (, for pasta water, half for table salt)","200g / 7 oz ham slices (I use ham off-the-bone), diced 1cm / 0.4\" (Note 1)"]},{"ingredients":["75g / 5tbsp tbsp unsalted butter","1/2 cup plain flour / all-purpose flour","3 cups milk (, HOT, full fat preferred, but work with lite milk too)","1 tsp cooking salt / kosher salt (, halve for table salt, +50% for flakes)","3/4 tsp black pepper","1/4 tsp ground nutmeg (, (Note 2))","1 1/2 cups Gruyère cheese, grated (, shredded using a standard box grater (tightly packed if using cups) (Note 3))","1/2 cup pasta cooking water"],"purpose":"CHEESE SAUCE (MORNAY SAUCE)"}]', '[{"description":"Cook pasta per packet directions, scoop out 1 cup of water just before draining. In the same pot, melt butter, cook flour 2 min. Whisk in milk. Add salt, pepper and nutmeg, stir in cheese until melted. Stir in ham, then 1/2 cup pasta cooking water. Toss with pasta until coated, serve.","images":[],"step":1},{"title":"Cook pasta","description":"Bring a large pot of water and salt to the boil. Cook pasta according to packet instructions. I always like to give a few stirs at the beginning so they don''t stick to each other.","images":[],"step":2},{"description":"Reserve 1 cup pasta cooking water, then drain and give the pasta brief rinse under cold water. Set aside and keep the pot for the sauce.","images":[],"step":3},{"title":"Make roux","description":"Using the pasta pot, melt the butter over medium heat. Add flour and whisk for 2 minutes. At first it will look like thick and pasty then it will loosen to become a smooth, glossy paste. Make sure to use the whisk to get into the corners of the pot and don’t let it brown, reduce heat if needed.","duration":2,"images":[],"step":4},{"title":"Adding milk","description":"Add half of the hot milk to the roux while whisking vigorously, it will thicken very quickly. Once smooth, slowly pour in the remaining milk while continuing to whisk. Keep whisking for 30 seconds to 1 minute until the sauce is smooth, with no lumps. It should be thick enough that you can draw a path with a spatula through the middle, holding its shape briefly before slowly sinking back. (Note 4)","duration":0.5,"images":[],"step":5},{"title":"Season","description":"Add salt, pepper and nutmeg. Stir to combine.","images":[],"step":6},{"title":"Add cheese and ham","description":"Stir in Gruyère cheese and whisk until fully melted. You just made a Mornay sauce! Then stir in the ham with a wooden spoon.","images":[],"step":7},{"title":"Finish sauce","description":"Pour in 1/2 cup of the reserved pasta cooking water and stir until silky. Bring back to a simmer. It will be quite runny, it will thicken when the pasta is added.","images":[],"step":8},{"title":"Combine","description":"Add drained pasta and stir well until fully coated, the sauce will thicken slightly and cling to the macaroni. Add more pasta water if the sauce gets too thick.","images":[],"step":9},{"description":"Serve immediately while hot and creamy. I like to grind extra black pepper on top just before eating. Enjoy!","images":[],"step":10}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["French","Western"],"categories":["jbs-recipes","main-dishes","pasta-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_2c6b1fa7c0de', 'en', 'US', 'JB''s Mushroom Tart', 'Recipe video above. This is a simple mushroom tart that I used to make for my family back in France. Called "Tarte Fine aux Champignons" in French, buttery puff pastry is topped with melted Gruyère, sautéed mushrooms and baked until crispy and golden. It''s simple but delicious as a light meal with a fresh salad on the side.You''ll probably be surprised by the volume of mushrooms once sliced but it will reduce significantly as it cooks and bakes to an even layer on the puff.', 'https://www.recipetineats.com/tachyon/2026/03/JB-Mushroom-Tart_1.jpg', 20, 30, 50, 4, '[{"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 1.0, "unit": "jar of 40g"}}, {"id": "ing_extra_virgin_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}]', '[{"ingredients":["1 square sheet butter puff pastry (25cm / 10″ square), barely thawed (Note 1)","1 tbsp extra virgin olive oil","2 tbsp (30g) unsalted butter","400g / 14oz Swiss brown mushrooms (, sliced 0.5cm (Note 3))","1/2 tsp cooking salt / kosher salt (, use half for table salt)","1/4 tsp black pepper","1 1/2 cups (tightly packed) Gruyère cheese (, grated (Note 2))","2 tsp (10g) unsalted butter (, melted (for brushing))"]},{"ingredients":["1 1/2 tsp fresh thyme leaves","1 pinch sea salt flakes","truffle oil or good extra virgin olive oil (, to drizzle (optional) (Note 4))"],"purpose":"Toppings"}]', '[{"description":"Sauté mushrooms 5 minutes. Place puff pastry on baking paper, fold a 1 cm / 0.4\" border, brush edges with butter, top with Gruyère and mushrooms. Bake on the preheated tray for 30 minutes. Finish with fresh thyme, salt flakes and truffle oil.","duration":30,"images":[],"step":1},{"title":"Hot tray","description":"Place a baking tray in the oven. Turn the oven on and preheat to 210°C / 410°F (190°C fan).","images":[],"step":2},{"title":"Cook the mushrooms","description":"Heat the olive oil and butter in a frying pan over medium-high heat. Add mushrooms, salt and pepper. Cook for 5 minutes, stirring regularly, until soft. Transfer mushrooms to a colander over a bowl to drain in case of excess liquid.","duration":5,"images":[],"step":3},{"title":"Prepare the base","description":"Place a sheet of baking paper / parchment paper on the bench. Put the puff pastry on top. Fold the edges inwards to create a 1 cm / 0.4″ border and brush them with melted butter.","images":[],"step":4},{"title":"Assemble","description":"Spread the grated Gruyère evenly over the pastry. Top with the mushrooms, spreading them evenly too.","images":[],"step":5},{"title":"Bake","description":"Lift the baking paper and tart onto the hot tray in the oven. Bake for 30 minutes, until the pastry is golden and crisp (sides and underneath).","duration":30,"images":[],"step":6},{"title":"Finish and serve","description":"Sprinkle with fresh thyme leaves and salt flakes. Drizzle with truffle oil or a good virgin olive oil (optional but highly recommended). Cut and serve hot.","images":[],"step":7}]', '["milk"]', '["gluten_free","keto_friendly","low_calorie","vegetarian"]', '{"mealType":["lunch","dinner","snack"],"cuisine":["French"],"categories":["jbs-recipes","mushroom-recipes","mushrooms","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7a064c388856', 'en', 'US', 'JB''s French Pork Schnitzel', 'People say adding “French” to something doesn’t mean it’s better. But my passport would like to disagree! These schnitzels get a French flair with Herbes de Provence in the breadcrumbs. Now they''re French Pork Schnitzels - escalope de porc panées. Let’s go!', 'https://www.recipetineats.com/tachyon/2026/03/French-pork-schnitzel-1.jpg', 25, 10, 35, 4, '[{"id": "ing_beef_steak", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_egg", "quantity": {"value": 2.0, "unit": "carton of 12"}}, {"id": "ing_bread", "quantity": {"value": 0.281, "unit": "loaf"}}, {"id": "ing_herbes_de_provence", "quantity": {"value": 3.0, "unit": "unit"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_chilli_flakes", "quantity": {"value": 0.003, "unit": "jar of 40g"}}, {"id": "ing_thyme", "quantity": {"value": 0.4, "unit": "bunch"}}, {"id": "ing_rosemary", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_marjoram", "quantity": {"value": 1.25, "unit": "unit"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.075, "unit": "bunch"}}]', '[{"ingredients":["4 pork steaks or chops (125g to 150g / 4.4oz to 5.3oz each) (Note 1)","3/4 tsp cooking salt / kosher salt","1/2 tsp black pepper"]},{"ingredients":["1/3 cup plain flour / all-purpose flour","2 eggs, lightly whisked (, from large eggs (55g / 2oz each in shell))","1 1/2 cup panko breadcrumbs (Note 2)","3 tbsp herbes de Provence (Note 3)","1/2 cup vegetable oil (, or any other neutral flavoured oil)"],"purpose":"CRUMBING AND COOKING:"},{"ingredients":["1 lemon, cut into wedges","sea salt flakes"],"purpose":"TO FINISH:"},{"ingredients":["4 tsp dried thyme","3 tsp dried rosemary (Note 4)","1 1/4 tsp dried marjoram or savory (, sub with more thyme or rosemary)","3/4 tsp dried oregano"],"purpose":"HERBES DE PROVENCE:"}]', '[{"description":"Pound pork to 0.5cm / 0.2″, season with salt and pepper. Coat in flour, egg, then panko mixed with herbes de Provence. Fry over medium-high heat 2 minutes per side until golden.","images":[],"step":1},{"description":"Preheat the oven to 70°C / 160°F (all ovens).","images":[],"step":2},{"title":"Pound the pork","description":"Place the pork between two sheets of baking paper / parchment paper or freezer bags. (Note 5) Pound with a meat mallet until evenly 0.5 cm / 0.2 inch thick. (Note 6)","images":[],"step":3},{"title":"Season","description":"Season both sides with salt and pepper. Set aside.","images":[],"step":4},{"title":"Prepare the crumbing station","description":"Place flour, eggs, and panko mixed with herbes de Provence in three separate bowls. (Note 7)","images":[],"step":5},{"title":"Crumb","description":"Coat pork in flour and shake off excess. Dip in egg and let excess drip off. Press into the breadcrumb mixture so it sticks well. Transfer on a tray and repeat with remaining pork.","images":[],"step":6},{"title":"Cook the schnitzels","description":"Heat the oil in a frying pan over medium-high heat, it should be 0.4cm / 0.15\" deep. When hot, add 2 schnitzels. Cook 2 minutes until golden. Flip and cook the other side 2 minutes. Transfer to a rack over a tray and place in the warm oven. Repeat with the remaining two schnitzels. (Note 8)","images":[],"step":7},{"title":"Rest and Serve","description":"Let the schnitzels rest on the rack outside of the oven for 2 minutes before serving with a wedge of lemon and a sprinkle of salt flakes.","duration":2,"images":[],"step":8}]', '["egg","gluten"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["French","French influence"],"categories":["jbs-recipes","mains","pork","pork-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ea459fbbf11b', 'en', 'US', 'Lamb tagine', 'Recipe video above. My favourite of all tagines! The ras el hanout spice mix is sheer perfection with lamb, and slow cooking works wonders to develop rich flavours in the sauce and make the lamb fork tender. Serve over couscous for a stunning Moroccan meal. Your house will smell amazing!-> Also see Chicken and Vegetable Tagine.', 'https://www.recipetineats.com/tachyon/2023/08/Lamb-tagine_4.jpg', 15, 120, 135, 5, '[{"id": "ing_lamb", "quantity": {"value": 1.6, "unit": "kg"}}, {"id": "ing_lamb", "quantity": {"value": 1.6, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 45.0, "unit": "bottle"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_cinnamon_stick", "quantity": {"value": 2.0, "unit": "jar"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_apricots", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_cumin", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_turmeric", "quantity": {"value": 10.0, "unit": "jar"}}, {"id": "ing_fennel", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_round_clove", "quantity": {"value": 15.0, "unit": "jar"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_almonds", "quantity": {"value": 0.3, "unit": "pack of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_batches_couscous", "quantity": {"value": 1.5, "unit": "pack"}}]', '[{"ingredients":["1.6 kg/ 3.2lb boneless lamb shoulder, trim the fat, then ( cut in 3.5cm / 1.5\" cubes (1kg/2lb after trimming))","1 kg / 2 lb lamb stewing meat or shoulder, already trimmed of fat (cut in 3.5cm / 1.5\" cubes)"],"purpose":"Use one of these lambs (Note 1):"},{"ingredients":["1 tsp cooking/kosher salt","1/2 tsp black pepper","3 tbsp canola oil","3 garlic cloves (, finely minced)","2 brown onions (, diced (1cm / 0.3\" cubes))","1 1/2 tbsp tomato paste","2 tsp grated ginger","2 cinnamon sticks","2 1/2 cups chicken stock/broth (, low sodium)","1 cup dried apricots (, whole (Note 2 for olives option))","2 - 3 tsp lemon zest (just use 1 whole lemon, Note 3 for preserved lemon)"],"purpose":"Tagine:"},{"ingredients":["1 tbsp ground coriander","1 tbsp ground cumin","2 tsp ground cardamom","2 tsp turmeric powder","1 1/2 tsp fennel powder","1 tsp cayenne pepper (can reduce for less spicy - Note 4)","1/4 tsp ground cloves","1/4 tsp ground ginger","1/2 tsp cooking/kosher salt"],"purpose":"Ras el hanout (Note 4):"},{"ingredients":["1/2 cup slivered almonds (, toasted (Note 5))","1/2 cup coriander/cilantro leaves roughly chopped","1 1/2 batches couscous (I just use plain, but you can add the fruit and nuts if you want)"],"purpose":"For serving:"}]', '[{"description":"Preheat oven to 180°F/350°F (160°C fan). (Note 6 re: other cook methods)","images":[],"step":1},{"title":"Spice mix","description":"Mix the ingredients in a bowl then set aside.","images":[],"step":2},{"title":"Brown lamb","description":"Toss lamb with the salt and pepper. Heat the oil in a large oven-proof dutch oven (with a lid) over high heat. Brown the lamb in 3 batches, turning to colour the pieces all over, about 3 minutes. Remove into a bowl, then repeat with remaining lamb. Set aside.","images":[],"step":3},{"title":"Aromatics","description":"Turn heat down to medium high. Add onion and garlic, cook for 3 minutes until soft. Add tomato paste, ginger, cinnamon and spice mix. Cook for 1 1/2 minutes, stirring constantly.","duration":3,"images":[],"step":4},{"title":"Sauce","description":"Add chicken stock and water, stir, then return the lamb into the pot.","images":[],"step":5},{"title":"Slow cook 1 hr 45 min","description":"Bring to a simmer, cover with a lid then cook in the oven for 45 minutes. Add apricots, put the lid back on and cook for another 1 hour, checking halfway to ensure the sauce hasn''t reduced all the way (if you''re concerned, add 1/2 cup water).","duration":45,"images":[],"step":6},{"title":"Lemon finish","description":"Lamb should be tender - check! Gently stir in lemon zest.","images":[],"step":7},{"description":"Serve over plain couscous, sprinkled with almonds and coriander.","images":[],"step":8}]', '["gluten"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Moroccan","North African"],"categories":["lamb","lamb-recipes","mains","moroccan","slow-cooked-fall-apart","stews"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_ce03cd624a01', 'en', 'US', 'Persian Lamb Shanks', 'Recipe video above. A traditional Persian dish - fall apart lamb shanks with a well seasoned, delicately flavoured broth. Pair this with the iconic Persian Tachin (baked saffron rice), a Persian chopped salad and finish with a Persian Love Cake to complete your Persian feast!', 'https://www.recipetineats.com/tachyon/2018/09/Persian-Lamb-Shanks_6.jpg', 10, 180, 190, 4, '[{"id": "ing_amb_shanks", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 10.0, "unit": "pack of 3 heads"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}, {"id": "ing_chicken", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_turmeric", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_nutmeg", "quantity": {"value": 1.25, "unit": "jar"}}, {"id": "ing_cardamom_powder", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_cinnamon", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_cinnamon", "quantity": {"value": 2.5, "unit": "jar"}}, {"id": "ing_saffron_threads", "quantity": {"value": 1.25, "unit": "jar"}}]', '[{"ingredients":["4 lamb shanks (, about 300g/10oz each (Note 1))","Salt and pepper","1 - 2 tbsp vegetable oil (or canola)","1 large onion (, sliced (yellow, brown))","6 cloves garlic (, chopped)","1 litre / 4 cups water","500 ml / 2 cups chicken broth","2 medium tomatoes (, chopped)"]},{"ingredients":["1 tsp turmeric","3/4 tsp salt","1/4 tsp + 1/8 tsp nutmeg","1/4 tsp + 1/8 tsp cardamom powder","1/2 tsp cinnamon","1/8 tsp extra cinnamon (, extra for later)","1/4 tsp saffron threads (Note 2)"],"purpose":"Spices:"}]', '[{"description":"Sprinkle shanks with salt and pepper.","images":[],"step":1},{"description":"Heat 1 tbsp oil in a large heavy based pot over medium high heat. Brown shanks all over, 2 at a time. Remove from pot.","images":[],"step":2},{"description":"Discard excess oil, clean pot if it''s very dirty.","images":[],"step":3},{"description":"Add 1 tbsp oil. Cook onion and garlic for 2 minutes until translucent.","duration":2,"images":[],"step":4},{"description":"Stir in the turmeric, cinnamon, tomatoes, and salt.","images":[],"step":5},{"description":"Add chicken broth and stir well.","images":[],"step":6},{"description":"Place shanks in pot, then add water as needed so the shanks are 3/4 or fully covered, but no more than 1L/4 cups water. (Note 2)","images":[],"step":7},{"description":"If shanks not fully submerged, make a cartouche (baking paper lid, Note 3).","images":[],"step":8},{"description":"Bring up to the boil. Place the cartouche snugly on surface (if using), cover pot leaving a little crack (to ensure it doesn''t boil over).","images":[],"step":9},{"description":"Turn heat down so simmering very gently. Cook 1.5 hours, turning every 30 minutes.","images":[],"step":10},{"description":"Add cardamom and nutmeg into liquid.","images":[],"step":11},{"description":"Cook for another 1 hour until meat is very tender and falling off the bone.","images":[],"step":12},{"description":"Carefully remove meat from liquid into a bowl and cover with foil.","images":[],"step":13},{"title":"Simmer broth rapidly 30","description":"45 min until reduced by half.","images":[],"step":14},{"description":"Add saffron and remaining 1/8 tsp cinnamon.","images":[],"step":15},{"title":"Simmer further 10","description":"15 min until reduced to 500 ml / 2 cups. Should taste like a very well seasoned, intensely savoury but lightly spiced broth.","images":[],"step":16},{"description":"Return meat to pot to gently reheat for a few minutes, turning and basting the meat with the liquid to keep it moist.","images":[],"step":17},{"description":"Serve shanks with the braising liquid as a sauce. Pictured garnished with pomegranate seeds (leftover from salad, see Notes) or mint leaves, for visual only.","images":[],"step":18}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Persian"],"categories":["lamb","lamb-recipes","lamb-shanks","main-dishes","mains","quick-and-easy","slow-cooked-fall-apart","slow-cooker-recipes","stews","sunday-supper"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c94806c67199', 'en', 'US', 'Shepherd''s Pie', 'Recipe video above. Shepherd’s Pie is one of those foods that brings a smile to everyone’s face – especially when you get seconds! While it''s traditionally made with lamb, this is equally delicious made with beef (and makes it a Cottage Pie!) Terrific make ahead! GF option in Note 4.', 'https://www.recipetineats.com/tachyon/2018/06/Shepherds-Pie_1.jpg', 10, 70, 80, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_rosemary", "quantity": {"value": 0.075, "unit": "bunch"}}, {"id": "ing_lamb", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_beef", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.2, "unit": "bag of 2kg"}}, {"id": "ing_milk", "quantity": {"value": 0.167, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 2.0, "unit": "pack of 200g"}}, {"id": "ing_thyme", "quantity": {"value": 0.075, "unit": "bunch"}}]', '[{"ingredients":["1 1/2 tbsp olive oil","2 garlic cloves (, minced)","1 onion (, finely chopped)","1 carrot (, finely chopped)","1 rib celery (, finely chopped)","3/4 tsp each dried thyme and rosemary (or 2 sprigs fresh thyme + 1 sprig rosemary)","750g (1.5 lb) ground lamb (mince) OR beef","1/4 cup flour (, plain/all purpose)","1/4 cup tomato paste","2 cups beef stock / broth","1/2 cup red wine (or water)","1 beef bouillon cube (, crumbled (OXO brand crumbles easily))","1 tbsp Worcestershire sauce","2 bay leaves (, dried or fresh)","3/4 tsp cooking salt / kosher salt","1/2 tsp black pepper","1 cup frozen peas"]},{"ingredients":["1.2kg (2.2 lb) potatoes, peeled and cut into 2.5cm / 1\" cubes","2/3 cup milk (whole or low fat)","2 tbsp (30g) unsalted butter"],"purpose":"Mashed Potato"},{"ingredients":["2 – 3 tbsp grated parmesan (, optional)","2 tbsp (30g) unsalted butter (, melted)","Fresh thyme leaves, optional garnish"],"purpose":"Cheesy crust"}]', '[{"title":"Sauté","description":"Heat oil in a large skillet over medium high heat. Add onion and garlic, cook for 1 minute. Then add carrots, celery, thyme and rosemary. Cook for 3 minutes or until softened and sweet.","duration":1,"images":[],"step":1},{"title":"Cook lamb","description":"Turn heat up to high. Add lamb and cook, breaking it up as you go, until browned.","images":[],"step":2},{"title":"Make sauce","description":"Add flour and mix in. Add tomato paste, broth, red wine, bouillon cube, Worcestershire sauce and bay leaves. Stir well.","images":[],"step":3},{"title":"Simmer and thicken","description":"Bring to simmer, then turn down heat so it is simmering rapidly - I have it on medium. Cook for 30 minutes, stirring occasionally, until it reduces down to a thick gravy consistency (Note 1) (see video).","duration":30,"images":[],"step":4},{"title":"Cool","description":"Add salt and pepper, taste, then add more if you like. Transfer Filling to 1.5 litre / 1.5 quart pie baking dish. Stir through peas. Cover, then refrigerate to cool for 1 - 2 hours or overnight (optional, Note 2)","images":[],"step":5},{"description":"Preheat oven to 180°C/350°F (both fan and standard).","images":[],"step":6},{"title":"Boil potatoes","description":"Place the potatoes in a large pot. Add water so it’s 10cm / 4” above potatoes. Bring to a boil then cook for 15 minutes or until soft. Drain then return potatoes into the pot on the turned off stove. Allow to steam dry for 30 seconds or so (Note 3).","duration":15,"images":[],"step":7},{"title":"Mash","description":"Add butter and mash until melted, then add milk, salt and pepper. Mash until it''s soft and smooth (ie spreadable, but not sloppy), adjusting with a touch more milk if required.","images":[],"step":8},{"description":"Spread mash onto pie, use a fork to draw squiggles over the surface. Sprinkle with parmesan, drizzle with butter.","images":[],"step":9},{"title":"Bake for 30","description":"40 minutes or until deep golden on top and bubbling on the edges. Stick a knife into the middle to ensure it is piping hot.","duration":35,"images":[],"step":10},{"description":"Stand for 5 minutes before serving, garnished with fresh thyme leaves if desired.","duration":5,"images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Australian","British","Western"],"categories":["lamb-recipes","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_270e2df1a054', 'en', 'US', 'Lamb Shanks in Red Wine Sauce', 'Recipe video above. A classic way to prepare shanks, these are slow cooked in a deeply flavoured red wine sauce until they are meltingly tender. You can''t taste the red wine at the end, it completely transforms into a rich sauce. Make this in the oven, on your stove or even in a slow cooker - instructions provided for all!Note: This is my original lamb shanks recipe. There is also a more involved Restaurant-style red wine lamb shanks version in my cookbook which is more "fine-dining" style and involves an overnight marinade. See Note 7 for more information!', 'https://www.recipetineats.com/tachyon/2022/07/Lamb-Shanks-Red-Wine-Sauce_2_900px.jpg', 20, 210, 230, 4, '[{"id": "ing_amb_shanks", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_carrot", "quantity": {"value": 150.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 3.0, "unit": "head"}}, {"id": "ing_wine", "quantity": {"value": 0.833, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_thyme", "quantity": {"value": 0.2, "unit": "bunch"}}]', '[{"ingredients":["4 lamb shanks (, around 13 oz / 400g each (Note 1))","1 tsp EACH cooking/kosher salt and pepper","2 - 3 tbsp olive oil (, separated)","1 onion (, finely diced (brown, yellow or white))","3 garlic cloves (, minced)","1 cup carrot (, peeled, finely diced (Note 2))","1 cup celery (, finely diced (Note 2))","2 1/2 cups red wine (full bodied (good value wine, not expensive! Note 3)","800 g / 28oz can crushed tomatoes","2 tbsp tomato paste","2 cups chicken stock (, low sodium (or water))","5 sprigs of thyme ((preferably tied together), or 2 tsp dried thyme)","2 dried bay leaves (or 4 fresh)"]},{"ingredients":["Mashed potato (, polenta or pureed cauliflower)","Fresh thyme leaves (, optional garnish)"],"purpose":"To Serve:"}]', '[{"title":"Preheat the oven to 180°C/350°F (all oven types","description":"fan and standard).","images":[],"step":1},{"title":"Season shanks","description":"Pat the lamb shanks dry and sprinkle with salt and pepper.","images":[],"step":2},{"title":"Brown","description":"Heat 2 tablespoons of olive oil in a large heavy based pot over high heat. Sear the lamb shanks in 2 batches until brown all over, about 5 minutes. Remove lamb onto a plate and drain excess fat (if any) from the pot.","images":[],"step":3},{"title":"Sauté aromatics","description":"Turn the heat down to medium low. Heat remaining 1 tablespoon of olive oil in the same pot. Add the onion and garlic, cook for 2 minutes. Add carrot and celery. Cook for 5 minutes until onion is translucent and sweet.","duration":2,"images":[],"step":4},{"title":"Braising liquid","description":"Add the red wine, chicken stock, crushed tomato, tomato paste, thyme and bay leaves. Stir to combine.","images":[],"step":5},{"title":"Add shanks","description":"Place the lamb shanks into the pot, squeezing them in to fit so they are mostly submerged. (Note 1)","images":[],"step":6},{"title":"Oven 2 hours covered","description":"Turn stove up, bring liquid to a simmer. Cover, then transfer to the oven for 2 hours (see notes for other cook methods).","images":[],"step":7},{"title":"Uncovered 30 minutes","description":"Remove lid, then return to the oven for another 30 minutes (so 2 1/2 hours in total). Check to ensure lamb meat is ultra tender - if not, cover and keep cooking. Ideal is tender meat but still just holding onto bone.","images":[],"step":8},{"description":"Remove lamb onto plate and keep warm. Pick out and discard bay leaves and thyme.","images":[],"step":9},{"title":"Sauce","description":"Strain the sauce into a bowl, pressing to extract all sauce out of the veggies (Note 5 for repurposing the veggies). Pour strained sauce back into pot. If needed, bring to a simmer over medium heat and reduce slightly to a syrupy consistency (see video) - I rarely need to. Taste then add salt and pepper to taste (Note 5 on sauce taste).","images":[],"step":10},{"description":"Serve the lamb shanks on mashed potato or cauliflower puree with plenty of sauce! Garnish with thyme leaves if desired.","images":[],"step":11}]', '[]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["lamb-recipes","lamb-shanks","main-dishes","most-popular","slow-cooked-fall-apart","slow-cooker-recipes","stews","sunday-supper","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_fee8e66fd88d', 'en', 'US', 'Pea and Ham Soup (slow cooker or stove)', 'Recipe video above. This is a fabulous "throw it all in the slow cooker" soup. There''s no need to cook the onion separately - it "sautés" itself in the fat from the ham that rises to the surface. Thick, hearty soup broth infused with incredible flavour from the ham! Use leftover ham bone, or purchase a ham hock.', 'https://www.recipetineats.com/tachyon/2020/02/Pea-and-Ham-Soup_4.jpg', 10, 600, 610, 6, '[{"id": "ing_split_peas", "quantity": {"value": 500.0, "unit": "pack"}}, {"id": "ing_bacon", "quantity": {"value": 1.2, "unit": "pack of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_water", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["500g / 1lb dried split peas (Note 1)","1.2-1.5kg / 2.4-3lb ham hock (aka ham bone), bacon hock or MEATY leftover ham bone (Note 2)","1/4 tsp salt (start with less, adjust later)","3/4 tsp black pepper","2 garlic cloves (, minced)","2 bay leaves (, dried or fresh)","1 onion (, finely chopped)","1 carrot (, peeled and finely chopped)","2 celery sticks (, finely chopped)","8 cups (2 litres/qts) water"]},{"ingredients":["Parsley (, finely chopped)","Crusty bread for dunking!"],"purpose":"Garnishes / serving:"}]', '[{"description":"Place peas in slow cooker, push ham in. Scatter all ingredients around the ham bone, then pour over water.","images":[],"step":1},{"description":"Slow cook 8 to 10 hours on LOW or 6 hours on HIGH. (Or 2.5 hours on low on stove, 1 h - 1 hr 20 min pressure cooker/Instant Pot on HIGH)","images":[],"step":2},{"description":"Remove ham bone, shred ham meat. Discard bone and fatty skin.","images":[],"step":3},{"description":"Remove bay leaves. Use a stick blender to blitz 2 or 3 times - thickens soup but doesn''t make it completely smooth (my preference, you can blend completely if you want).","images":[],"step":4},{"description":"Return ham into slow cooker, stir. Taste and add more salt if needed (soup gets lots of salt from ham).","images":[],"step":5},{"description":"Serve garnished with parsley. Serve with crusty bread for dunking - make a quick Irish Soda Bread, Garlic Bread or upgrade to Cheesy Garlic Bread!","images":[],"step":6}]', '["gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["leftover-ham-recipes","slow-cooker-recipes","soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0a15d7af93bb', 'en', 'US', 'Bangers & Mash (Sausage with Onion Gravy)', 'Recipe video above. Everybody loves a good sausage recipe, and this is the great British classic! Affectionately known as "Bangers and Mash" to Aussies and Brits, this is so easy to make, you will never ever use a store bought gravy powder!', 'https://www.recipetineats.com/tachyon/2016/10/Bangers-and-Mash-with-Onion-Gravy_42.jpg', 5, 20, 25, 4, '[{"id": "ing_oil", "quantity": {"value": 7.5, "unit": "bottle"}}, {"id": "ing_sausages", "quantity": {"value": 8.0, "unit": "pack of 500g"}}, {"id": "ing_onion", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.045, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_peas", "quantity": {"value": 1.0, "unit": "unit"}}]', '[{"ingredients":["1/2 tbsp oil","8 sausages of choice (Note 1)","1 large onion (, halved and finely sliced (yellow, white or brown) (Note 2))","2 garlic cloves (, minced)","3 tbsp flour (plain)","2 cups beef stock/broth","1/4 tsp salt","1/2 tsp black pepper"]},{"ingredients":["Mashed potato","Peas"],"purpose":"To Serve"}]', '[{"title":"Cook sausages","description":"Heat oil in a large skillet / fry pan over medium high heat. Add sausages and cook, turning, until browned as much as possible all over and cooked through. Cook time will differ depending on sausage size - mine take around 8 minutes.","images":[],"step":1},{"description":"Remove sausages onto a plate. Turn heat down to medium.","images":[],"step":2},{"title":"2 tbsp oil remaining","description":"You need around 2 tbsp oil left in the skillet. If you have much less, add a bit of butter or oil.","images":[],"step":3},{"title":"Saute onion and garlic","description":"Add onion and garlic, cook until golden brown - around 4 minutes.","images":[],"step":4},{"title":"Cook off flour 2 minutes","description":"Add flour and mix through. Then cook, stirring constantly for 2 minutes.","duration":2,"images":[],"step":5},{"title":"Gradually add beef stock","description":"Add about 3/4 cup of beef broth and mix into the onion so it becomes a sludge. Then add remaining beef broth and mix until combined. If it''s lumpy, use a whisk to help make it smooth.","images":[],"step":6},{"title":"Thicken gravy","description":"Simmer, stirring, for 2 to 3 minutes until the gravy thickens but is slightly thinner than you want - it will thicken more as you serve it.","duration":2.5,"images":[],"step":7},{"title":"Season","description":"Add salt and pepper. Stir, taste, then add more salt if you want.","images":[],"step":8},{"description":"Serve sausages with plenty of gravy, with mashed potato and peas on the side. (Low carb option - Creamy Cauliflower Mash)","images":[],"step":9}]', '["gluten"]', '["high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Australian","British"],"categories":["dinner-tonight","main-dishes","most-popular","quick-and-easy","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dea186d5023f', 'en', 'US', 'Pasta with Creamy Zucchini Sauce', 'Recipe video above. This is a wonderful way to use zucchinis to make a luscious pasta dinner! It''s summery yet at the same time comforting, quick, easy and while perhaps not low fat, this makes a good dent into our daily recommended vegetable intake!', 'https://www.recipetineats.com/tachyon/2020/07/Creamy-Zucchini-Pasta-Sauce_8.jpg', 10, 15, 25, 4, '[{"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_zucchini", "quantity": {"value": 0.6, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["50g / 3 tbsp unsalted butter","2 garlic cloves (, minced)","1/2 onion (, finely sliced (brown, white, yellow))","600g / 1.2 lb zucchini ((courgette), grated using standard box grater)","1/2 tsp EACH salt and pepper","1 cup thickened/heavy cream","3/4 cup chicken or vegetable stock/broth (, low sodium)","3/4 cup parmesan (, finely grated using microplane (Note 1 for store bought))","1 cup corn (canned, drained, about 2/3 of a can, OR fresh)","300g/ 10oz spaghetti, fettucini or other long strand pasta ( (I used bucatini))"]},{"ingredients":["Parmesan","Extra finishing options: Handful of fresh basil (stir in at end), sprinkle of bacon or pangrattato"],"purpose":"Finishing & serving"}]', '[{"description":"Cook Pasta:","images":[],"step":1},{"description":"Bring a large pot of water to the boil with 1 tablespoon of salt.","images":[],"step":2},{"description":"Cook pasta per packet directions MINUS 2 minutes (yes, 2 whole minutes!) - pasta should be a bit too firm in the middle.","images":[],"step":3},{"description":"Scoop out a big mug of pasta cook water, set aside (for sauce loosening, just in case), then drain.","images":[],"step":4},{"description":"Creamy zucchini sauce:","images":[],"step":5},{"description":"Melt butter in a large skillet or pot over medium high heat.","images":[],"step":6},{"title":"Garlic and onion","description":"Add garlic and onion, cook for 1 1/2 minutes until onion is slightly golden.","images":[],"step":7},{"title":"Cook Zucchini","description":"Add zucchini, cook for 1 minute. Then add salt and pepper, then stir for 2 minutes until it reduces in volume by about 1/2.","duration":1,"images":[],"step":8},{"title":"Add liquids","description":"Stir in cream, chicken stock, parmesan and corn. Bring to simmer, then reduce heat to medium and simmer for 3 minutes. It will still seem watery because water comes out of the zucchini - don''t worry, it cooks down in the next step.","duration":3,"images":[],"step":9},{"description":"Toss! Add pasta, then use two wooden spoons to toss well for 2 minutes, or until sauce reduces and is coating the pasta instead of pooling in the skillet. If it gets too thick, add a splash of reserved pasta cooking water. Pasta will finish cooking in this step.","duration":2,"images":[],"step":10},{"title":"Serve","description":"Remove from stove, serve immediately, garnished with extra parmesan.","images":[],"step":11}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["Italian","Western"],"categories":["main-dishes","mains","pasta-recipes","quick-and-easy","vegetarian-recipes","zucchini-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_744dcc5f1955', 'en', 'US', 'Crispy Baked Shrimp in Lemon Butter Sauce (Prawns)', 'Recipe video above. People call this Magic Baked Shrimp - named as such because it''s so simple to make, yet it tastes like a million bucks! Shrimp (prawns) baked in a white wine-butter reduction with lemon and garlic, with a crunchy parmesan breadcrumb topping! Don''t skip crust bread for dunking in the incredible sauce! It''s basically a crunchy version of Shrimp Scampi!', 'https://www.recipetineats.com/tachyon/2019/08/Baked-Shrimp-Prawns_6.jpg', 10, 15, 25, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.25, "unit": "bottle of 750ml"}}, {"id": "ing_butter", "quantity": {"value": 75.0, "unit": "block of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_bread", "quantity": {"value": 0.141, "unit": "loaf"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_lemon", "quantity": {"value": 0.06, "unit": "net of 500g"}}]', '[{"ingredients":["500g/ 1 lb jumbo prawns/shrimp (, peeled and deveined (Note 1))","3/4 cup dry white wine (sub chicken broth)","75g/ 5 tbsp unsalted butter (, melted)","2 tbsp lemon juice","3 garlic cloves (, minced)","1/2 tsp salt","1/4 tsp pepper"]},{"ingredients":["3/4 cup panko breadcrumbs (Note 2)","1/4 cup parmesan (, finely shredded)","1/4 tsp salt","1.5 tbsp olive oil"],"purpose":"Crunchy Topping:"},{"ingredients":["Finely chopped parsley","Lemon"],"purpose":"Garnish:"}]', '[{"description":"Preheat oven to 220°C/430°F (all oven types).","images":[],"step":1},{"description":"Pour wine and half the butter into 9 x 13\" / 22 x 33cm baking pan (see Note 3 if using glass). Place in oven for 10 minutes to reduce.","duration":10,"images":[],"step":2},{"description":"Toss prawns with remaining butter, garlic, lemon juice, salt and pepper. Butter may harden - that''s ok.","images":[],"step":3},{"description":"Mix Crunchy Topping ingredients.","images":[],"step":4},{"title":"Remove pan from oven. Add prawns","description":"spread out in single layer, but snug.","images":[],"step":5},{"description":"Top with Crunchy Topping. Bake 12 minutes.","images":[],"step":6},{"title":"Flick to broiler/grill on high, broil for 1","description":"2 minutes (max) to brown top a bit more.","duration":1.5,"images":[],"step":7},{"description":"Sprinkle with parsley. Serve immediately with lemon wedges and crusty bread to mop up the incredible sauce!","images":[],"step":8}]', '["milk","shellfish"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","main-dishes","prawns-shrimp","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0e061b94dd4f', 'en', 'US', 'Garlic Herb Slow Cooker Turkey Breast', 'Recipe video above. Slather your turkey breast with garlic herb butter so it bastes with flavour and keeps the breast moist as it cooks in the slow cooker. Slow cooker is the easiest, safest way too cook turkey breast without brining or marinating! See here for the roasted version of this recipe. Also see the classic spice rubbed Juicy Slow Cooker Turkey Breast.', 'https://www.recipetineats.com/tachyon/2018/11/Slow-Cooker-Garlic-Herb-Turkey-Breast.jpg', 15, 360, 375, 8, '[{"id": "ing_5_6_lb_single_turkey_breast", "quantity": {"value": 2.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.007, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_oil", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_butter", "quantity": {"value": 150.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_rosemary", "quantity": {"value": 0.12, "unit": "bunch"}}, {"id": "ing_chicken", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_dark_soy_sauce", "quantity": {"value": 0.01, "unit": "bottle of 250ml"}}]', '[{"ingredients":["2.5 - 3 kg / 5-6 lb single turkey breast (, skin on, bone in (Note 1), NOT BRINED)","1 1/2 tsp salt","Black pepper","1 brown onion (, halved)","1 head of garlic (, halved horizontally)","3 sprigs rosemary, 8 sprigs thyme (optional)","Oil (, for drizzling (for skin))"]},{"ingredients":["150 g / 10 tbsp unsalted butter (, softened)","1 1/2 tsp salt","1/2 tsp black pepper","4 large garlic cloves (, minced)","1 tbsp EACH finely chopped fresh sage, rosemary leaves, thyme leaves and parsley (, fresh)"],"purpose":"Garlic Herb Butter (Note 2):"},{"ingredients":["Chicken broth/stock, for topping up (if required)","1/3 cup / 50g flour","1/2 tsp + dark soy sauce (or gravy colouring) (Note 3)"],"purpose":"Garlic Butter Gravy:"}]', '[{"title":"Garlic Herb Butter","description":"Mix ingredients together.","images":[],"step":1},{"title":"Loosen skin (video helpful)","description":"Pat breast dry. Use small knife to cut slit on one side to separate skin from flesh. Slide upside tablespoon between flesh and skin, all over turkey.","images":[],"step":2},{"title":"Slather","description":"Slather about 2/3 of the butter under the skin, then the remaining all over the surface including underside.","images":[],"step":3},{"title":"Season skin","description":"Sprinkle surface with 1/2 tsp salt + pepper. (Can leave overnight - 2 days at this stage)","images":[],"step":4},{"title":"Put in Slow Cooker","description":"Place garlic and onion in slow cooker (mine is 5L / 5 qt). Place turkey on top, skin side up. Top with thyme and rosemary sprigs.","images":[],"step":5},{"title":"Slow Cook","description":"Cook 6 hours on low, first checking at 4 hours to be safe, until internal temperature reads 75C/165F when inserted into the middle.","images":[],"step":6},{"title":"Rest","description":"Transfer turkey to baking tray (reserve juices). Cover loosely with foil, rest for 20 minutes.","duration":20,"images":[],"step":7},{"title":"Crisp","description":"Remove herb sprigs, drizzle turkey with oil (not butter, it burns / not as crispy). Place under a broiler/grill on high (~30cm/12\" from heat source) for 5 to 10 minutes until skin is crispy and bronzed - keep an eye on it, it''s quick.","duration":7.5,"images":[],"step":8},{"description":"Serve turkey with gravy on the side (below), or Cranberry Sauce.","images":[],"step":9},{"description":"Strain slow cooker juices into a bowl. Press juices out of onion and garlic. If you''ve got less than 2.5-3 cups (675-750ml) of liquid, top up with store bought broth/stock.","images":[],"step":10},{"description":"When liquid settles, spoon off about 1/4 cup fat/butter from surface.","images":[],"step":11},{"description":"Place in saucepan set over medium heat. When it bubbles, add flour and mix for 1 minute.","duration":1,"images":[],"step":12},{"description":"Add all slow cooker juices into saucepan. Stir until lump free (use whisk if necessary). Simmer for 3 to 5 minutes until it thickens.","duration":4,"images":[],"step":13},{"description":"Add dark soy (if using), pepper and salt to taste. Pour into jug and serve with turkey.","images":[],"step":14}]', '["gluten","milk","soy"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":[],"categories":["main-dishes","slow-cooker-recipes","turkey-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_bb86a7928197', 'en', 'US', 'Oven Baked Pork Chops with Potatoes', 'Recipe video above. This is a sauce made for baked pork chops. It makes them come out golden and sticky, rather than pale and bland. It''s a country-style sauce that''s savoury and a bit sweet! Potatoes are optional - or sub with other roastable veg.', 'https://www.recipetineats.com/tachyon/2016/09/Baked-Pork-Chops_2.jpg', 10, 30, 40, 4, '[{"id": "ing_worcestershire_sauce", "quantity": {"value": 5.0, "unit": "bottle"}}, {"id": "ing_ketchup", "quantity": {"value": 0.06, "unit": "bottle of 500g"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.06, "unit": "bottle of 250ml"}}, {"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.02, "unit": "bottle of 500ml"}}, {"id": "ing_pork", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 800.0, "unit": "bag of 2kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["1 tsp Worcestershire Sauce","2 tbsp ketchup (Note 1)","1 tbsp soy sauce (Note 2)","2 tbsp brown sugar (or white)","1 tbsp olive oil (or vegetable or canola oil)","1 clove garlic, (minced)","2 tsp apple cider vinegar (Note 3)"],"purpose":"Rub"},{"ingredients":["4 pork chops / cutlets (, around 200-250g/7-8oz each including bone (Note 4))","800g/ 1.6 lb baby potatoes (, larger ones cut in half (Note 5))","1 tbsp olive oil","Salt & pepper"],"purpose":"Chops"}]', '[{"description":"Preheat oven to 220C / 430F (standard oven) or 200C / 390F (fan forced / convection).","images":[],"step":1},{"description":"Toss potatoes in oil, sprinkle with salt and pepper. Scatter on baking tray.","images":[],"step":2},{"description":"Place in oven for 15 minutes (giving them a head start).","duration":15,"images":[],"step":3},{"description":"Meanwhile, mix the Rub ingredients together in a small bowl.","images":[],"step":4},{"description":"Slather the pork on both sides with the Rub, reserving some Rub for basting. (See notes for marinating)","images":[],"step":5},{"description":"Take the tray out of the oven. Toss potatoes then push them to the edge.","images":[],"step":6},{"description":"Place pork on tray. Bake for 15 minutes.","duration":15,"images":[],"step":7},{"description":"Remove tray from oven, flick to broiler/grill on high (shelf about 20cm/8\" from heat source).","images":[],"step":8},{"description":"Flip pork, spoon over reserved rub and dab on sides. (Note 4). Broil 7 - 10 minutes until pretty well caramelised.","images":[],"step":9},{"description":"Remove from oven. Use a brush to get the golden juices off the tray and dab it onto the pork - this is key for flavour and colour! Pop it back under the broiler for a couple of minutes to finish off.","images":[],"step":10},{"description":"Serve, scraping the juices on the tray onto the pork, then garnish with parsley if desired.","images":[],"step":11}]', '["gluten","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","main-dishes","most-popular","one-pot-recipes","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7d661b946f63', 'en', 'US', 'French Onion Smothered Pork Chops', 'Recipe video above. French Onion Soup meets juicy pan seared pork! A gravy made with caramelised onion that tastes like your favourite French Onion soup. For the full French Onion experience, don''t skip the cheese! Make this with any type of pork chops you want - or chicken!', 'https://www.recipetineats.com/tachyon/2018/11/French-Onion-Smothered-Pork-Chops_4.jpg', 10, 25, 35, 4, '[{"id": "ing_pork", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.005, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 2000.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_oil", "quantity": {"value": 22.5, "unit": "bottle"}}, {"id": "ing_beef", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_flour", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_rosemary", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["4 - 5 pork chops (, boneless (~ 150-200g/5-7oz each) (Note 1))","1/2 tsp garlic powder","Salt and pepper","2 large onions (, sliced into rings (brown, yellow or white))","2 garlic cloves (, minced)","1.5 tbsp / 25g butter (or olive oil)","1 tsp oil (, if needed)","Salt and pepper","1 cup/250ml beef broth/stock (, low sodium)","2 tbsp flour","4 slices cheese (Note 2)","Finely chopped fresh rosemary leaves"]}]', '[{"title":"Caramelise Onions","description":"Melt butter on medium (or medium low for strong stoves). Add onion and garlic, cook 15 minutes until golden brown and caramelised, stirring regularly (see video). Remove from skillet.","images":[],"step":1},{"title":"Prepare Chops","description":"Sprinkle chops with garlic, salt and pepper.","images":[],"step":2},{"title":"Sear","description":"Add oil into skillet if needed. Turn heat up to high. Sear chops 1 minute on each side until nicely browned but not cooked inside. Remove onto plate.","images":[],"step":3},{"title":"Gravy","description":"Turn heat down to medium. Return onion into skillet, scraping in juices. Add flour, mix.","images":[],"step":4},{"description":"Add beef broth and mix until incorporated. Season sauce to taste with salt and pepper.","images":[],"step":5},{"title":"Simmer Chops in Sauce","description":"When it comes to a simmer, give it a big stir then add pork chops.","images":[],"step":6},{"description":"Top chops with cheese, cover with lid to melt and finish cooking the chops through - only 3 minutes for thin chops like I''m using. Internal temp of 160F/70C for no pink (or 155F/68C for blush of pink).","images":[],"step":7},{"title":"Garnish","description":"Remove lid, sprinkle with rosemary. Spoon over French Onion Gravy, then sprinkle with more rosemary.","images":[],"step":8},{"description":"Serve immediately, over mashed potato or similar.","images":[],"step":9}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","main-dishes","mains","pork","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_6e7aa882995c', 'en', 'US', 'Quesadilla (Beef, Vegetable or Chicken)', 'Recipe video above. Choose ONE Filling! The spice mix adds terrific flavour - great with vegetable, chicken, beef, pork and turkey. Freezer friendly!', 'https://www.recipetineats.com/tachyon/2018/06/Quesadillas_4.jpg', 10, 15, 25, 6, '[{"id": "ing_tortillas", "quantity": {"value": 6.0, "unit": "pack of 8"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_coriander", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}, {"id": "ing_one_filling_of_choice_below", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.037, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 5.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_black_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_corn", "quantity": {"value": 0.375, "unit": "can of 400g"}}]', '[{"ingredients":["6 - 8 flour tortillas (20cm/8\")","2 cups (200g) shredded Monterey Jack cheese (or other of choice) (Note 1)","3/4 cup roughly chopped coriander/cilantro","1 cup corn kernels (frozen thawed or can drained)","ONE Filling of Choice, below (beef, chicken or vegetable)"],"purpose":"Quesadillas:"},{"ingredients":["1 tsp each onion powder, dried oregano, salt","2 tsp each cumin powder, paprika","1/4 tsp each black pepper, cayenne pepper (optional)"],"purpose":"Quesadilla Spice Mix:"},{"ingredients":["2 1/2 tbsp olive oil","2 garlic cloves (, minced)","1/2 onion (, finely chopped)","500g / 1 lb ground beef / mince","1 small red capsicum/bell peppers (, diced)","2 tbsp tomato paste","1/4 cup (65 ml) water"],"purpose":"Beef Filling:"},{"ingredients":["2 1/2 tbsp olive oil","500 g/1 lb chicken thighs (, skinless boneless (Note 2))","2 garlic cloves (, minced)","1 small onion (, quartered and sliced)","1 small red capsicum/bell pepper (, diced)"],"purpose":"Chicken Filling:"},{"ingredients":["2 tbsp vegetable oil","1 onion (, diced)","2 garlic cloves (, minced)","1 can of black beans, drained (400g/14oz)","1 capsicum/bell pepper (, diced (any colour))","1 cup corn (canned drained or frozen thawed)","1/4 cup tomato paste","1/4 cup (65 ml) water"],"purpose":"Vegetable Filling:"}]', '[{"description":"Place tortilla on work surface. Sprinkle one side with a bit of cheese, top with Filling of Choice. Sprinkle with corn*, coriander and top with cheese. Fold in half.","images":[],"step":1},{"description":"Preheat non stick skillet over medium low heat (no oil, if pan is not non-stick use 2 tsp oil).","images":[],"step":2},{"description":"Place quesadilla in skillet, press down lightly, cover with lid. Cook for 3 minutes until underside is super golden brown and crispy.","duration":3,"images":[],"step":3},{"description":"Carefully flip over the folded edge (see video). Press down lightly. Cook for 3 minutes until crispy (no lid).","duration":3,"images":[],"step":4},{"description":"Transfer to cutting board, cut in half. Serve immediately!","images":[],"step":5},{"title":"Dipping Sauce options","description":"Sour cream, salsa, Avocado Sauce (pictured)","images":[],"step":6},{"description":"Spice Mix:","images":[],"step":7},{"description":"Mix ingredients in a small bowl. Use for one of the Fillings Options below.","images":[],"step":8},{"description":"Heat oil in a skillet over high heat. Add onion and garlic, cook for 2 minutes.","duration":2,"images":[],"step":9},{"description":"Add beef and cook, breaking it up as you go. Once it changes from pink to brown, add capsicum. Cook for 1 minute.","duration":1,"images":[],"step":10},{"description":"Add tomato paste, water and Spice Mix. Cook for 2 minutes. Transfer to bowl, cool.","duration":2,"images":[],"step":11},{"description":"Chicken Filling:","images":[],"step":12},{"description":"Drizzle chicken with 1 tbsp oil, toss to coat. Sprinkle over Spice Mix, toss well to coat.","images":[],"step":13},{"description":"Heat 1 tbsp oil in a large skillet over high heat. Add onion and garlic, cook for 2 minutes. Add capsicum and cook for 1 minute. Transfer to bowl, cool.","duration":2,"images":[],"step":14},{"description":"Return pan to stove, reduce to medium heat. Add remaining 1/2 tbsp oil. Add chicken and cook for 3 minutes until deep golden. Turn and cook for 3 minutes until cooked through.","duration":3,"images":[],"step":15},{"description":"Transfer chicken to cutting board, rest for 2 minutes then dice and cool. Combine with capsicum mixture.","duration":2,"images":[],"step":16},{"description":"Vegetable Filling:","images":[],"step":17},{"description":"Heat oil in a skillet over high heat. Add onion and garlic, cook for 2 minutes. Add capsicum, cook for 1 minute.","duration":2,"images":[],"step":18},{"description":"Add beans, corn, tomato paste, water and Spice Mix. Cook for 2 minutes. Transfer to bowl, cool.","duration":2,"images":[],"step":19}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican","Tex-Mex"],"categories":["dinner-tonight","main-dishes","mexican-recipes","quesadillas","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a74262062ffa', 'en', 'US', 'Pasta with Tomato Cream Sauce', 'Recipe video above. Pasta in a pink tomato cream sauce! You''ll love how creamy this sauce is, how there''s plenty of it and yet you don''t need gallons of cream. Slurp-worthy as it is, or use it as a base for add ins of your choice - suggestions in the recipe notes.', 'https://www.recipetineats.com/tachyon/2018/03/Creamy-Tomato-Pasta_8.jpg', 5, 15, 20, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_milk", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.375, "unit": "pack of 200g"}}, {"id": "ing_basil", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.005, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.003, "unit": "jar of 50g"}}]', '[{"ingredients":["300g/10 oz spaghetti","2 tbsp / 30g unsalted butter","3 garlic cloves (, minced)","½ onion (, finely chopped)","1 cup / 250 ml tomato passata (/ tomato puree (Note 1))","3/4 cup / 185 ml heavy / thickened cream (Note 2 for subs)","1/2 cup / 125 ml milk (, low fat)","3/4 cup / 30g parmesan (, finely freshly grated (Note 3))","1 tsp dried basil, or other herb of choice","1 tsp chicken or vegetable stock powder (, or 1 bouillon cube, crumbled (Note 4))","Finely ground pepper + salt"]}]', '[{"description":"Cook pasta in a big pot of boiling water for time per packet MINUS 2 minutes. Just before draining, scoop out a mugful of pasta cooking water.","images":[],"step":1},{"description":"Melt butter in large skillet over medium heat. Add garlic and onion, cook until translucent - about 2 minutes.","images":[],"step":2},{"description":"Add remaining ingredients. Stir until parmesan is melted. Turn heat up slightly and simmer for 2 minutes. Adjust salt to taste.","duration":2,"images":[],"step":3},{"description":"Add pasta. Toss for 1 to 2 minutes or until sauce thickens and is clinging to pasta instead of swimming on the base of the skillet (video shows this well). Use reserved pasta cooking water if required to thin the sauce out if it gets too thick.","duration":1.5,"images":[],"step":4},{"description":"Serve immediately, garnished with more parmesan and parsley if desired.","images":[],"step":5}]', '["milk"]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","main-dishes","pasta-recipes","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_abdea3facba5', 'en', 'US', 'Slow Cooker BBQ Pulled Pork Sandwich', 'See recipe video above. Tender perfectly seasoned slow cooker pulled pork smothered in a homemade BBQ Sauce (see notes for using store bought). Add a classic coleslaw then pile it high onto buns! Great food for gatherings - easy and good value to feed a crowd. Make this in the slow cooker, oven or pressure cooker.', 'https://www.recipetineats.com/tachyon/2017/01/BBQ-Pulled-Pork-Sandwiches-1.jpg', 15, 480, 495, 6, '[{"id": "ing_brown_sugar", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_paprika", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_mustard", "quantity": {"value": 0.019, "unit": "jar of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_pork_shoulder", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_apples", "quantity": {"value": 0.113, "unit": "kg"}}, {"id": "ing_quantity_coleslaw", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_bread", "quantity": {"value": 6.0, "unit": "loaf"}}, {"id": "ing_pork", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_ketchup", "quantity": {"value": 0.75, "unit": "bottle of 500g"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.25, "unit": "bottle of 500ml"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_lemon", "quantity": {"value": 0.03, "unit": "net of 500g"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 15.0, "unit": "bottle"}}]', '[{"ingredients":["2 tbsp brown sugar","2 tsp paprika powder","1 tsp onion powder","1 tsp garlic powder","1/2 tsp cumin powder","3/4 tsp mustard powder","1 tsp salt","1/2 tsp black pepper"],"purpose":"Rub"},{"ingredients":["1.5 - 2.2 kg/ 3 - 4.5 lb pork shoulder or butt (, skinless and boneless (Note 1))","3/4 cup apple cider or apple juice (Note 2)","1 quantity Coleslaw","6 - 8 bread rolls"],"purpose":"Pork"},{"ingredients":["1 cup pork juices from slow cooker, once cooked","2 1/2 cups ketchup","1/2 cup apple cider vinegar","2/3 cup brown sugar","1 1/2 tsp each black pepper, onion (or garlic powder), mustard powder","1 tbsp lemon juice","1 tbsp Worcestershire sauce"],"purpose":"BBQ Sauce (Note 5)"}]', '[{"description":"Mix together Rub then rub all over the pork. Optional: Marinate for 1 hour.","images":[],"step":1},{"description":"Place in the slow cooker and pour over apple cider. Slow cook for 8 hours on low or pressure cook for 1 hr 30 minutes on high. (Note 3)","images":[],"step":2},{"description":"Remove pork from liquid into a roasting pan. Reserve liquid.","images":[],"step":3},{"title":"OPTIONAL: Roast pork for 20","description":"30 minutes at 180C/350F until browned (Note 4). Meanwhile, make BBQ Sauce.","duration":25,"images":[],"step":4},{"title":"Shred pork with forks","description":"it should be fall apart tender (see video).","images":[],"step":5},{"title":"Toss in BBQ sauce","description":"use as much as you like, the recipe makes enough to coat the pork well but not dripping in sauce, plus a bit extra on the side.","images":[],"step":6},{"description":"To make Pulled Pork Sandwiches, pile pork on warmed rolls and top with Coleslaw. I like to lay everything out for people to make their own.","images":[],"step":7},{"description":"Place all ingredients in a medium saucepan over medium heat and whisk. Bring to simmer, then turn down the heat so it simmers gently. Cook for 1 hour. Remove from stove and use per recipe.","images":[],"step":8}]', '["gluten","mustard"]', '[]', '{"mealType":["dinner"],"cuisine":["Southern"],"categories":["main-dishes","pork-recipes","quick-and-easy","sandwiches-and-sliders","slow-cooked-fall-apart","slow-cooker-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_e335e9c8a0ac', 'en', 'US', 'Cajun Baked Turkey Breast and Dressing (Stuffing)', 'This is a genius recipe for a spectacular EASY Thanksgiving centrepiece packed full of big flavours! Avoiding dry baked turkey breast is notoriously difficult, but this recipe tackles that problem in 2 ways: a) Brining the turkey with a Cajun rub; 2) baking the turkey in the same pan as the Dressing (stuffing), it keeps the turkey moist. Plus the turkey juices gets soaked up by the Dressing. No gravy needed - the Dressing has a golden crust but is so juicy underneath, you don''t need gravy. Don''t stress if you can''t get Andouille sausages - refer to the notes. See Note 4 for adjustment for different Turkey sizes. Use Scaler by putting cursor / tap on Servings then move to your turkey weight to adjust recipe scale.', 'https://www.recipetineats.com/tachyon/2016/11/Cajun-Turkey-with-Dressing-6.jpg', 15, 240, 255, 8, '[{"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_rosemary", "quantity": {"value": 0.05, "unit": "bunch"}}, {"id": "ing_pound_bone_in_turkey_breast", "quantity": {"value": 3.629, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 2000.0, "unit": "pack of 1kg"}}, {"id": "ing_beef_steak", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 0.002, "unit": "kg"}}, {"id": "ing_sausages", "quantity": {"value": 1.134, "unit": "pack of 500g"}}, {"id": "ing_tabasco_sauce", "quantity": {"value": 1.0, "unit": "bottle"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_bread", "quantity": {"value": 0.281, "unit": "loaf"}}]', '[{"ingredients":["1 tbsp kosher salt *","1 tsp each freshly cracked black pepper (, ground oregano **)","2 tsp each onion powder (, garlic powder, smoked paprika ^)","1/2 tsp cayenne pepper","1/2 tsp. each dried thyme and rosemary"],"purpose":"Cajun Rub"},{"ingredients":["8 lb / 4 kg pound bone-in turkey breast (\"crown\" or \"buffe\") (Note 1)"],"purpose":"Turkey"},{"ingredients":["4 tbsp / 50g butter","8 cloves garlic (, minced (2 tbsp))","2 large onions (, finely chopped^^ (4 cups))","2 celery ribs (, finely chopped (2 cups))","2 green peppers / capsicum (, finely chopped (2 cups))","1 1/4 lb / 650g Andouille sausages (Note 3 for subs!)","1-2 tbsp Tabasco sauce (, to taste)","2 cups chicken stock / broth","1 1/2 cups bread crumbs (panko breadcrumbs can be substituted)"],"purpose":"Dressing / Stuffing (Note 2)"}]', '[{"description":"Mix together Cajun Rub.","images":[],"step":1},{"description":"Rub turkey breast with 3 tbsp of poultry rub (Note 1). Place on a plate and refrigerate overnight, uncovered (24 - 36 hours).","images":[],"step":2},{"title":"Remove turkey from fridge","description":"leave out while making Dressing / Stuffing.","images":[],"step":3},{"description":"Use a food processor to ground the sausages, or finely chop them. If using raw substitute sausages (see Note 3), you can just squeeze the meat out of the casings.","images":[],"step":4},{"description":"Melt butter in large skillet over medium high heat. Add the garlic, half the onion, half the celery and half the capsicum. Cook for 10 minutes or until the vegetables are softened.","duration":10,"images":[],"step":5},{"description":"Transfer vegetables into a bowl. If the skillet is looking dry, add a tiny splash of oil. Add sausage and cook, breaking it up as you go.","images":[],"step":6},{"description":"Add cooked onion etc back into the skillet and add remaining onion, celery and capsicum. Stir.","images":[],"step":7},{"description":"Add tabasco (start with 1 tbsp) and chicken broth. Bring to simmer, then turn heat down to medium. Simmer for 10 minutes.","duration":10,"images":[],"step":8},{"description":"Stir in breadcrumbs then remove from heat. It should still be very moist and a bit liquidy, but not like soup.","images":[],"step":9},{"description":"While Dressing is simmering, preheat oven to 325F / 165C (standard) or 295F / 145C (fan forced / convection).","images":[],"step":10},{"description":"Place turkey breast in a roasting pan so there is 2\"/5cm (or so) around it for the dressing.","images":[],"step":11},{"description":"Spoon dressing around the turkey.","images":[],"step":12},{"title":"Cover loosely with foil then bake for 3 1/4","description":"3 1/2 hours, then uncover and roast for an additional 30 minutes to brown and crisp the skin, or until the internal temperature of the turkey is 75C / 165F (Note 4).","images":[],"step":13},{"description":"Remove from oven then loosely cover with foil. Rest for 20 minutes before serving (Note 5).","duration":20,"images":[],"step":14}]', '["gluten","milk"]', '[]', '{"mealType":["dinner"],"cuisine":["American","Cajun"],"categories":["main-dishes","roasts","turkey-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_c049a72deaf2', 'en', 'US', 'Pork Tenderloin with Creamy Marsala Sauce', 'Juicy pork tenderloin smothered in a Creamy Marsala Sauce with Mushrooms. It''s like gravy - but even better because the sauce has beautiful layers of flavour in it from the Marsala. Using wine in cooking is how posh restaurants make such beautiful sauces! Use this Marsala Sauce for other proteins like chicken, veal and beef.', 'https://www.recipetineats.com/tachyon/2016/06/Pork-Tenderloin-Creamy-Marsala-Sauce_4.jpg', 5, 30, 35, 3, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_pork", "quantity": {"value": 0.454, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.142, "unit": "kg"}}, {"id": "ing_green_onion", "quantity": {"value": 0.75, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_flour", "quantity": {"value": 0.022, "unit": "kg"}}, {"id": "ing_marsala", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_chicken", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_tarragon", "quantity": {"value": 5.0, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.25, "unit": "carton of 250ml"}}]', '[{"ingredients":["1 tbsp olive oil","1 lb / 500g pork tenderloin (Note 1)"]},{"ingredients":["2 tbsp butter (salted or unsalted)","5 oz / 150g mushrooms (, sliced (I used Swiss Brown))","1/4 cup finely chopped shallots or onion","1 garlic clove (, minced)","1 1/2 tbsp flour","1/2 cup / 125 ml marsala (Note 2)","2 cups / 500 ml chicken broth (, low sodium)","5 tarragon leaves (optional) (thyme is also lovely) (Note 3)","1/4 cup / 65 ml cream"],"purpose":"Creamy Marsala Sauce"}]', '[{"description":"Preheat oven to 200C/390F.","images":[],"step":1},{"description":"Sprinkle pork with salt and pepper.","images":[],"step":2},{"description":"Heat oil in an ovenproof skillet over high heat. Sear on all sides until nicely browned.","images":[],"step":3},{"description":"Place in the oven for 15 minutes for the faintest blush of pink (pictured) or 18 to 20 minutes for no pink. See Note 4 for internal cook temperatures.","duration":15,"images":[],"step":4},{"description":"Remove pork from skillet onto a plate, cover with foil and set aside in a warm place while you make the sauce.","images":[],"step":5},{"description":"Creamy Marsala Sauce","images":[],"step":6},{"description":"Melt 1 tbsp butter in the same skillet over high heat. Cook mushrooms until browned, then remove.","images":[],"step":7},{"description":"Reduce heat to medium high, melt 1 tbsp butter,. Add onion and garlic, cook for 2 minutes or until onion is softened. Add flour and mix.","duration":2,"images":[],"step":8},{"description":"Add marsala, cook until mostly evaporated (about 1 minute). Add tarragon and chicken broth, whisk until dissolved. Bring to simmer and cook until the liquid reduces by half - 3 to 5 minutes.","images":[],"step":9},{"description":"Add cream and mix, then return the mushrooms and pork into the skillet as well as juices pooled on the plate. Simmer for 1 - 2 minutes until the sauce thickens into a thin gravy consistency (it will thicken more as you serve).","duration":1.5,"images":[],"step":10},{"description":"Transfer to serving platter with the gravy on the side or poured over the top. Serve with mashed potatoes of course!! (Here is my Make Ahead Mashed Potatoes recipe)","images":[],"step":11}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["French-ish"],"categories":["dinner-tonight","main-dishes","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_25cdf6bb8a6a', 'en', 'US', 'Mexican Chipotle Pork and Beans', 'Recipe video above. This is a big pot of saucy, shreddable meat in a rich, spicy, chipotle sauce. Pork shoulder is slow cooked into fall-apart submission with meaty lima beans that absorbs the bold flavoured sauce. Stuff in tacos, serve over red rice, eat like stew!SPICE NOTE: This sauce is spicy. Not off-the-charts spicy, but it has a good kick! If you''re concerned, remove half the chillis from the can of chipotle in adobo (as the chillies are where the spiciness is). If you''re still worried, best to give this a miss because chipotle in adobo IS spicy!!', 'https://www.recipetineats.com/tachyon/2023/05/Mexican-Chipotle-Pork-and-Beans_6.jpg', 15, 170, 185, 6, '[{"id": "ing_pork_shoulder", "quantity": {"value": 1.5, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cumin", "quantity": {"value": 0.25, "unit": "jar of 40g"}}, {"id": "ing_chipotle_in_adobo", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.333, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_oranges", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_allspice_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}]', '[{"ingredients":["1.5kg / 3lb pork shoulder (skinless, boneless), cut into 6 equal pieces (Note 1)","1 tsp cooking/kosher salt","1/2 tsp black pepper","2 tsp cumin powder"],"purpose":"Pork:"},{"ingredients":["200g / 7 oz chipotle in adobo (- the chillis + sauce (Note 2))","2 tbsp olive oil","1 onion (, finely chopped)","4 garlic cloves (, finely minced)","1/4 cup tomato paste","1 cup orange juice (real, not reconstituted sweetened stuff - Note 3)","2 cups chicken stock/broth (, low sodium)","2 bay leaves (fresh, else dried)","1 tsp cooking/kosher salt","3 x 420g / 16 oz canned butter beans / lima beans (, or other of choice (Note 4))"],"purpose":"Sauce:"},{"ingredients":["1 tbsp dried oregano","1 tsp cumin powder","1 tsp coriander powder","1/2 tsp allspice powder"],"purpose":"Dried herbs & spices"}]', '[{"description":"Preheat oven to 180°C/350°F (160°C fan).","images":[],"step":1},{"title":"SPICINESS","description":"Read note above about spiciness!","images":[],"step":2},{"description":"Puree chipotle in adobo until smooth using a stick blender or similar.","images":[],"step":3},{"description":"Sprinkle pork all over with salt, pepper and cumin.","images":[],"step":4},{"title":"Brown pork","description":"Heat all the oil in a large oven-proof pot over high heat. Brown the pork all over in 2 batches, the remove onto a plate (~ 1 minute each side).","images":[],"step":5},{"title":"Sauté","description":"Cool the pot slightly then return to medium heat. If the pot looks dry, add 1 tbsp oil. Sauté onion, garlic, the herbs & spices for 3 minutes.","duration":3,"images":[],"step":6},{"title":"Cook off tomato & chipotle","description":"Add tomato paste and cook it off for 2 minutes. Add chipotle puree and cook for 2 minutes.","duration":2,"images":[],"step":7},{"title":"Slow cook 2 hours","description":"Add remaining ingredients EXCEPT beans. Stir, then bring to simmer. Place pork in - arrange so its submerged as best as possible. Cover with lid. Place in oven for 2 hours. (Note 6 other cook methods)","images":[],"step":8},{"title":"Add beans, cook 30 min","description":"Remove lid, add beans. Return to oven for 30 minutes without lid to caramelise the surface. The pork will be fork-tender!","duration":30,"images":[],"step":9},{"description":"Serve like stew over Mexican red rice or with tortillas for dunking. Or make wickedly food tacos with finely chopped white onion, fresh coriander/cilantro, avocado slices and a squeeze of lime. More serving options above the recipe video.","images":[],"step":10}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["mains","mexican-recipes","pork","pork-recipes","slow-cooked-fall-apart","slow-cooker-recipes","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d835d34e8e79', 'en', 'US', 'Just a great Pork Rub', 'Recipe video above. This is a real great all-rounder rub for pork chops. It gives the pork great flavour, a lovely warm red colour, and if you throw a knob of butter in at the end, you get a tasty flavoured sauce too!There''s enough spices in the rub so that if you''re missing one or two, the rub will still be tasty, see Note 1.Makes 4 tablespoons / 45g of rub which will season 4 thick-cut chops. Keeps for the shelf life of the spices you used.', 'https://www.recipetineats.com/tachyon/2021/08/Pork-Rub_06.jpg', 5, 12, 17, 4, '[{"id": "ing_smoked_paprika", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.011, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.075, "unit": "jar of 50g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_mustard", "quantity": {"value": 0.019, "unit": "jar of 200g"}}, {"id": "ing_cumin", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_sage", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_pork", "quantity": {"value": 4.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}]', '[{"ingredients":["1 tbsp smoked paprika","2 1/4 tsp salt (cooking/kosher salt, Note 2)","3/4 tsp black pepper","1 1/2 tsp garlic powder","1 1/2 tsp onion powder","1 tsp dried oregano","3/4 tsp mustard powder","1/2 tsp cumin powder","1/2 tsp sage powder"],"purpose":"Pork rub (subs Note 1):"},{"ingredients":["4 pork chops, any type (pictured: pork cutlets, 220g/7oz each, 2cm / 0.8\" thick) (Note 3)","1 1/2 tbsp olive oil (per batch you cook)","50g / 4 tbsp unsalted butter (for flavoured butter sauce, 15 g / 1 tbsp per chop)"],"purpose":"Pork:"}]', '[{"title":"Rub: Mix spices in a small bowl. Keeps for weeks","description":"even months! (Whatever the shelf life of the spices is you used).","images":[],"step":1},{"title":"Using pork rub","description":"Pat pork chops dry. Sprinkle then use your fingers to lightly rub the seasoning on both sides, as well as the sides. Shake off excess. Cook per below.","images":[],"step":2},{"title":"Cooking thin pork chops","description":"up to 1.75 cm / 0.7\" thick (Note 3):","images":[],"step":3},{"description":"Place a rack over a tray. (Note 4)","images":[],"step":4},{"description":"Heat oil in a heavy based skillet over medium-high heat.","images":[],"step":5},{"description":"Cook pork chops for 3 minutes on each side until deep golden. Don''t crowd the pan else the pork will stew instead of sear!","duration":3,"images":[],"step":6},{"description":"Rest on rack for 3 minutes.","duration":3,"images":[],"step":7},{"description":"Melt butter in skillet, stirring to dissolve rub left in pan into the butter. Serve over pork!","images":[],"step":8},{"title":"Cooking THICK pork chops","description":"2cm / 0.8\"+ (Note 3):","images":[],"step":9},{"description":"Preheat oven to 200°C/390°F (180°C fan). Place a rack over a tray. (Note 4)","images":[],"step":10},{"description":"Heat oil in a heavy based skillet over medium high heat.","images":[],"step":11},{"description":"Use tongs to sear the edge of the chops (fat strip), rotating as you go, until you get nice colour all around, about 3 minutes in total (see video demo). Then sear each side for 2 minutes until golden.","duration":2,"images":[],"step":12},{"description":"Put pan into the oven and allow to finish cooking for 3 minutes or until the internal temperature reaches 65°C/149°F. Remove pork and rest 3 minutes on rack.","duration":3,"images":[],"step":13},{"description":"Melt butter in skillet, stirring to dissolve rub left in pan into the butter. Serve over pork!","images":[],"step":14}]', '["milk","mustard"]', '["gluten_free","high_protein","keto_friendly"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","mains","pork","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_7dfcdd73275e', 'en', 'US', 'Pork Tenderloin with Creamy Mustard Sauce', 'Recipe video above. This is one of those recipe gems that proves just few ingredients and minimal effort can still deliver a knock-out dish!It''s easy enough for a weeknight meal, but can step up as a dish elegant enough for company. A pinch of fresh tarragon adds a lovely sweet aniseed flavour, while mustard brings the oomph and thickens the sauce.Note: The cook time is affected by the size of the pork fillet so a meat thermometer is highly recommended to ensure the pork is cooked perfectly.', 'https://www.recipetineats.com/tachyon/2021/05/Pork-Tenderloin-with-Creamy-Mustard-Sauce_4.jpg', 8, 20, 33, 5, '[{"id": "ing_pork", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 30.0, "unit": "bottle"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_tarragon", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_water", "quantity": {"value": 1.0, "unit": "L"}}]', '[{"ingredients":["2 pork tenderloins (, 500g / 1lb each (Note 1))","1 tsp salt","1 tsp pepper","2 tbsp oil (vegetable, canola, or olive oil)"]},{"ingredients":["1/2 cup cream (, heavy / thickened (Note 2))","1 tbsp Dijon mustard (Note 3)","1 tbsp whole grain mustard (Note 3)","2 tsp tarragon (, finely chopped (Note 4))","2 tsp parsley (, finely chopped (Note 4))","1/2 tsp salt","1/2 tsp pepper","1 - 2 tbsp water (, as needed)"],"purpose":"Sauce:"}]', '[{"title":"Preheat oven","description":"Preheat oven to 200°C / 390°F (180°C fan). Place a rack over a tray (for resting the cooked meat).","images":[],"step":1},{"title":"Season pork","description":"Sprinkle the tenderloins all over with salt and pepper.","images":[],"step":2},{"title":"Sear pork","description":"Heat oil in a large oven-proof skillet over medium-high heat. Sear pork all over until golden. This takes around 5 minutes (I sear 4 sides).","images":[],"step":3},{"title":"Bake (Note 5)","description":"Transfer the skillet with the pork in it to the oven. Bake for 12 - 15 minutes or until an instant read thermometer reads 65°C / 149°F. This will have a blush of pink, a perfect medium for optimum juiciness. (For no pink at all, add 3 minutes cooking and target an internal temperature of 68°C / 155°F.)","duration":13.5,"images":[],"step":4},{"title":"Rest","description":"Remove pork from skillet and transfer to the resting rack for 5 minutes.","duration":5,"images":[],"step":5},{"title":"Creamy Mustard Sauce","description":"Return same skillet to the stove over medium heat. Add cream and both mustards. Mix well, scraping the bottom of the pan to dissolve any golden bits stuck to the base of the pan into the sauce (free flavour!). Once it becomes hot but not simmering, stir in salt, pepper, tarragon and parsley. If the sauce seems too thick, thin with a little water as needed. No need to simmer, the sauce is done!","images":[],"step":6},{"title":"Serve: Slice into 2","description":"2.5cm (0.8 - 2\") slices. Serve with Creamy Mustard Sauce!","images":[],"step":7}]', '["milk","mustard"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","mains","pork","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1b90880ba9f8', 'en', 'US', 'Pesto pasta salad', 'Recipe video above. Don''t skimp on pesto, and don''t be shy with olive oil. If you do, you''ll end up staring at a mound of flavour-lacking, dry pesto pasta salad, thinking "darn it, I should have just followed the recipe!".PS Just 2 tablespoons of mayo is the secret here. Just gives an edge of creaminess without weighing it down, plus significantly improves the quality of next-day leftovers - prevents it from drying out.TIP: Homemade pesto obviously rules here, but if you need to resort to store-bought, get it from the fridge rather than aisle. It''s better.', 'https://www.recipetineats.com/tachyon/2023/03/Pesto-pasta-salad_9.jpg', 15, 15, 30, 5, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.7, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_pinenuts", "quantity": {"value": 30.0, "unit": "jar"}}, {"id": "ing_basil", "quantity": {"value": 1.2, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_salt", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.105, "unit": "L"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.075, "unit": "jar of 400g"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_baby_bocconcini", "quantity": {"value": 220.0, "unit": "unit"}}, {"id": "ing_baby_rocket_arugula", "quantity": {"value": 0.22, "unit": "kg"}}, {"id": "ing_basil", "quantity": {"value": 1.2, "unit": "bunch"}}]', '[{"ingredients":["350g / 12oz spiral pasta (fusilli, or other of choice, 3 1/2 cups)","1 tbsp salt (, for cooking pasta)"]},{"ingredients":["2 tbsp pinenuts (, toasted (sub walnuts, cashews, almonds))","2 cups (tightly packed) basil leaves","1 small garlic clove (, minced)","1/2 cup parmesan (, finely grated)","1/2 tsp cooking/kosher salt","1/4 tsp black pepper","7 tbsp extra virgin olive oil (or 50/50 grapeseed/olive oil)"],"purpose":"Pesto (Note 1):"},{"ingredients":["2 tbsp mayonnaise (S&W, else Hellman''s, Note 2)","250g (1 heaped cup) cherry tomatoes, cut in half","220g/ 7 oz baby bocconcini (, drained, cut in half (Note 3))","1 cup (tightly packed) baby rocket/arugula leaves (40g)","1/2 tsp cooking/kosher salt","Small basil leaves (, optional garnish)"],"purpose":"Pasta Salad:"}]', '[{"title":"Cook pasta","description":"Bring 3 litres of water to the boil with the salt. Cook for the pasta packet time + 1 minute. Drain in a colander, rinse under cold water. Shake off excess water well, then allow to fully cool and dry.","images":[],"step":1},{"title":"Pesto","description":"Place all ingredients in a tall jug just large enough to fit the head of a stick blender. Blitz under pretty smooth. Not a green smoothie, we still want some visible green bits! but not chunks.","images":[],"step":2},{"title":"Toss","description":"Place pasta in a bowl, scrape in the pesto. Add mayonnaise then toss well. Add bocconcini and tomato, toss gently just to disperse. Add rocket/arugula and toss just to disperse.","images":[],"step":3},{"title":"Serve","description":"Transfer into a serving bowl. Scatter with basil leaves, if using. Serve!","images":[],"step":4}]', '["gluten","milk"]', '["high_protein","vegetarian"]', '{"mealType":["lunch","dinner"],"cuisine":["Western"],"categories":["pasta-recipes","pasta-salads-and-rice-salads","salad-recipes-main-course","side-salads","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d9cee3c9bf0e', 'en', 'US', 'My Favourite Quinoa Salad', 'Recipe video above. Elevate your Quinoa Salad with two simple tricks: Toasting the quinoa in the oven to give it a gorgeous nutty flavour (great cheffy tip!), and use a wickedly good garlic/ginger dressing!It makes an excellent meal-worthy Asian-style salad, or colourful rainbow salad to take to gatherings. Don''t skip the sprinkle of Wasabi Pea dust. It''s the cherry on top!Serves: 10-12 as side, 5 as meal', 'https://www.recipetineats.com/tachyon/2021/03/My-Favourite-Quinoa-Salad-5.jpg', 20, 35, 55, 10, '[{"id": "ing_quinoa", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_cucumber", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_carrot", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_red_cabbage", "quantity": {"value": 9.0, "unit": "head"}}, {"id": "ing_green_onion", "quantity": {"value": 0.04, "unit": "bunch"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.0, "unit": "punnet of 250g"}}, {"id": "ing_shelled_edamame", "quantity": {"value": 150.0, "unit": "pack"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.3, "unit": "bottle of 250ml"}}, {"id": "ing_mirin", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_vinegar", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_grapes", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_mayonnaise", "quantity": {"value": 0.094, "unit": "jar of 400g"}}, {"id": "ing_sugar", "quantity": {"value": 0.013, "unit": "kg"}}, {"id": "ing_ginger", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_wasabi_peas", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}]', '[{"ingredients":["1 cup quinoa (, tri-colour (or other colour, Note 1))","2 cups water"],"purpose":"Quinoa:"},{"ingredients":["1 cup cucumber (, finely diced (Note 2))","1 carrot (, medium, peeled and finely shredded (Note 3))","3 cups red cabbage (, finely shredded (~1/4 small or 1/8 large cabbage))","2 green onions (, finely sliced)","250g/ 8oz cherry tomatoes (, small ones quartered, large ones cut into 6)","1 cup shelled edamame (, cooked per packet then cooled (Note 4))","1 red capsicum/bell pepper (, finely chopped)","1/2 cup coriander/cilantro leaves (, finely chopped)"],"purpose":"Salad:"},{"ingredients":["5 tbsp soy sauce (, light or all-purpose (Note 5))","2 tbsp mirin (Note 6)","2 tbsp rice wine vinegar (sub: cider, sherry or champagne vinegar)","2 tbsp sesame oil (, toasted (Note 7))","2 1/2 tbsp canola, vegetable or grapeseed oil","2 1/2 tbsp Kewpie mayonnaise (sub whole-egg mayo such as Hellman''s or S&W, Note 8)","2 1/2 tsp sugar (white or brown)","2 tsp ginger (, freshly grated)","1 garlic clove (, crushed using garlic press or finely grated using microplane)"],"purpose":"Dressing:"},{"ingredients":["1/3 cup wasabi peas (, crushed (Note 9))","1 tbsp sesame seeds (, toasted (Note 10))"],"purpose":"Garnishes:"}]', '[{"description":"Cook quinoa:","images":[],"step":1},{"title":"Toast for extra flavour","description":"Preheat oven to 200°C/390°F (180° fan) Spread quinoa on a tray. Bake 15 minutes, stirring halfway, until it''s lightly browned and smells nutty.","images":[],"step":2},{"title":"Rinse","description":"Transfer to fine mesh sieve or strainer. Rinse under running water for 10 seconds, shake off excess water well.","duration":0.16666666666666666,"images":[],"step":3},{"title":"Cook","description":"Scrape into a medium saucepan. Add water, place lid on. Bring to simmer on medium heat, then lower stove to low and simmer for 15 minutes (or until all water is absorbed, tilt pot to check).","duration":15,"images":[],"step":4},{"title":"Rest","description":"Remove from stove (lid still on) and rest for 10 minutes.","duration":10,"images":[],"step":5},{"title":"Fluff & cool","description":"Remove lid, fluff quinoa with a fork and allow to fully cool before using. (Spread on a tray if you want to speed things up).","images":[],"step":6},{"title":"Dressing","description":"Place ingredients in a jar and shake well.","images":[],"step":7},{"description":"Toss salad! Place quinoa in a large bowl. Add all salad ingredients. Pour over dressing, toss very well.","images":[],"step":8},{"title":"Garnish","description":"Either transfer to a large serving platter or individual bowls. Sprinkle generously with crushed Wasabi Peas and sesame seeds. Devour!","images":[],"step":9}]', '["egg","gluten","sesame","soy"]', '["low_calorie","vegetarian"]', '{"mealType":["dinner","lunch"],"cuisine":["Asian-esque"],"categories":["salad-recipes-main-course"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a48e24cde0d4', 'en', 'US', 'Creamy Goat Cheese & Roasted Red Pepper Risoni (Orzo)', 'Recipe video above. Goat''s cheese and jarred fire-roasted red peppers (capsicum) makes this dish special even though it''s quick and simple! The sauce is a little bit smoky and a little bit creamy, while olives add briny freshness. Tastes like a Mediterranean risotto!Get the risoni boiling first then start on the sauce. Serve as a meal or as a side with a simple piece of cooked fish, prawns/shrimp, chicken or pork chops.', 'https://www.recipetineats.com/tachyon/2025/01/Roasted-red-pepper-goats-cheese-risoni_2.jpg', 7, 13, 20, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 0.31, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_kalamata_olives", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_cheese", "quantity": {"value": 120.0, "unit": "block of 250g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}]', '[{"ingredients":["250g/ 8oz risoni pasta (orzo) (, or other very small pasta (tiny stars, novelty shapes like dinosaurs, ditalini))","2 tsp cooking salt/kosher salt (, for cooking the pasta)","2 tbsp extra virgin olive oil","1 red onion (, halved then cut into 5mm / 0.2\" slices (sub regular onion))","2 garlic cloves (, finely minced)","310g/ 10oz jar chargrilled / fire-roasted sliced red capsicum/peppers","2 cups tomato passata or puree (Note 2)","1/2 cup sliced Kalamata olives ( or other briny/pickly thing (like pickles, chopped))","1/4 tsp cooking salt / kosher salt","1/4 tsp black pepper","120g/4 oz goat''s cheese (, the creamy feta type (Note 3))"]},{"ingredients":["1 tightly packed cup basil leaves","1 tbsp roughly chopped parsley (, plus extra for garnish)"],"purpose":"Finishing – CHOOSE (Note 4)"}]', '[{"title":"Boil risoni","description":"Bring a small pot or large saucepan of water to the boil. Add salt and cook risoni until just under al dente (ie still a bit firm inside) as it will cook more in the sauce. 8 minutes for me.","images":[],"step":1},{"title":"Drain & rinse","description":"Just before draining, scoop out 1/2 cup pasta cooking water and set aside. Drain, rinse briefly under the tap then leave the risoni in the colander while you finish the sauce.","images":[],"step":2},{"title":"Sauté","description":"Heat the oil in a large non stick skillet (30cm/12\") over high heat. Add onion and cook for 2 minutes until starting to soften. Add garlic and capsicum strips. Cook for 2 minutes until the onion is softened.","duration":2,"images":[],"step":3},{"title":"Simmer","description":"Add tomato and olives. Bring to a simmer, lower heat to medium and simmer for 5 minutes, stirring every now and then.","duration":5,"images":[],"step":4},{"title":"Melt goat cheese","description":"Add cooked risoni, salt, pepper and the pasta cooking water. Stir to combine. Add most of the goat''s cheese (reserve some for garnish), stir so it melts.","images":[],"step":5},{"title":"Basil & serve","description":"Stir through basil or parsley just before serving. Divide between bowls. Crumble over reserved goat''s cheese, sprinkle with extra basil. Dig in with a spoon!","images":[],"step":6}]', '["gluten","milk"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["Mediterranean vibes","Western"],"categories":["dinner-tonight","mediterranean-recipes","pasta-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cdef31925f9d', 'en', 'US', 'Cheesy baked Mexican beef and beans', 'Recipe video above. A bubbly casserole of sorts, this Mexican beef and bean is like a baked version of chilli con carne with lots of melty cheese - but faster to make. Think of it like your ultimate all-purpose Mexican beef - stuff in tacos, DIY burrito wraps, dunk with corn chips - like nachos!', 'https://www.recipetineats.com/tachyon/2023/03/Cheesy-Mexican-Beef-and-Beans-Casserole_8a.jpg', 15, 30, 45, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_capsicum", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_beef_mince", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_kidney_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_tomato", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_pickled_jalape_o", "quantity": {"value": 0.333, "unit": "unit"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_cumin", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}]', '[{"ingredients":["2 tbsp olive oil","1 red onion (, finely chopped)","2 garlic cloves (, finely minced)","1 green capsicum / bell pepper (, cut into 1cm / 1/2\" cubes (or other colour))","500g/ 1 lb beef mince (ground beef) (Note 1)","400g/ 14oz can red kidney beans or black beans (, drained (or other beans))","1 cup tomato passata (Note 2)","1/3 cup pickled sliced jalapeño (Note 3)","1 1/2 cups Colby cheese (, shredded (or other cheese, Note 4))"]},{"ingredients":["1 1/2 tsp cumin powder","1 1/2 tsp smoked paprika (sub normal paprika)","1 tsp garlic powder (sub onion powder)","1 tsp garlic powder (sub onion powder)","1 tsp dried oregano","1/2 tsp cayenne pepper (sub black pepper)","1 tsp cooking/kosher salt"],"purpose":"Mexican spice mix:"}]', '[{"description":"Preheat oven to 200°C / 400°F (180°C fan).","images":[],"step":1},{"title":"Sauté","description":"Heat the olive oil in a cast-iron skillet over medium high heat (or other oven-proof pan). Cook onion, garlic and capsicum for 3 minutes.","duration":3,"images":[],"step":2},{"title":"Cook beef & spices","description":"Add beef and cook, breaking it up as you go, until you no longer see raw meat. Add spices, then cook for 1 minute.","duration":1,"images":[],"step":3},{"title":"Beans & tomato","description":"Add kidney beans and passata. Stir, then bring to a simmer.","images":[],"step":4},{"description":"Cheese it! Scatter the jalapeño across the surface, top with cheese.","images":[],"step":5},{"description":"Bake 15 minutes (no lid) then remove from the oven.","images":[],"step":6},{"description":"Serve! Scoop into bowls and serve with corn chips or tortillas with your favourite Mexican fixings (guacamole or avocado sauce pico de gallo or restaurant style salsa, fresh coriander/coriander, sour cream). Dunk like nachos, make DIY burritos or tacos!","images":[],"step":7}]', '["milk"]', '["gluten_free","high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["mexican-recipes","one-pot-recipes","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_574435a6092b', 'en', 'US', 'Beef Barbacoa - Mexican Pulled Beef for Tacos and everything!', 'Recipe video above. Ultra-juicy Mexican pulled beef, tossed in a chipotle-spiced sauce! With a unique subtly spiced, tangy flavour, use this Beef Barbacoa for tacos, burritos, enchiladas, taquitos – the possibilities are endless. This is a slow cooker version that''s simple to put together. Which means ... effortless. YES!', 'https://www.recipetineats.com/tachyon/2021/03/Beef-Barbacoa_3.jpg', 10, 495, 505, 10, '[{"id": "ing_beef_cheeks", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_vegetable_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_bay_leaf", "quantity": {"value": 4.0, "unit": "unit"}}, {"id": "ing_chipotle_chiles_in_adobo_sauce", "quantity": {"value": 4.0, "unit": "bottle"}}, {"id": "ing_beef", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.25, "unit": "bottle of 500ml"}}, {"id": "ing_lime", "quantity": {"value": 0.12, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_cumin", "quantity": {"value": 0.5, "unit": "jar of 40g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.2, "unit": "bunch"}}, {"id": "ing_round_clove", "quantity": {"value": 20.0, "unit": "jar"}}]', '[{"ingredients":["2kg / 4 lb beef cheeks (, or chuck beef(see Note 1))","1 tsp salt (, kosher/cooking)","1 tsp black pepper","2 tbsp vegetable oil (, for searing)","4 bay leaves"]},{"ingredients":["4 chipotle chiles in adobo sauce (Note 2)","3/4 cup dark ale (beer), or low sodium beef broth/stock ( (Note 3))","1/2 cup apple cider vinegar","4 tbsp lime juice","6 garlic cloves","4 tsp ground cumin","2 tsp oregano","1/2 tsp ground cloves"],"purpose":"Barbacoa Sauce:"}]', '[{"title":"Cut beef","description":"Cut large cheeks in half so you have around 12 - 15 pieces cheeks. If using chuck, cut into 12 or so pieces.","images":[],"step":1},{"title":"Season","description":"Sprinkle with salt and pepper.","images":[],"step":2},{"title":"Brown beef","description":"Heat oil in a large pot or skillet over high heat. Sear beef in batches, browning aggressively all over. Place beef in slow cooker.","images":[],"step":3},{"title":"Blitz sauce","description":"Place Barbacoa Sauce ingredients in a blender, food processor or similar (I use a Nutribullet). Blend until smooth – it shouldn''t take long.","images":[],"step":4},{"title":"Slow cooker (see Note 4 for alt. cooking methods)","description":"Pour sauce over cheeks in slow cooker. Add bay leaves. Arrange cheeks so they are submerged as much as possible. Don''t worry, they will release juice as they cook and raise the liquid level.","images":[],"step":5},{"description":"Slow-cook for 8 hours on low. The beef should be effortless to shred when done.","images":[],"step":6},{"title":"Shred","description":"Remove cheeks from slow cooker into a pan. Shred using 2 forks.","images":[],"step":7},{"title":"Sauce","description":"Pour over 3 or 4 ladles of the sauce, then toss.","images":[],"step":8},{"title":"Serve","description":"Use in tacos with taco fixings of choice! Pictured with Mexican Red Rice, Pickled Red Cabbage for Tacos (in this Fish Tacos recipe) and Lime Crema (Note 5).","images":[],"step":9}]', '[]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["mexican-recipes","slow-cooked-fall-apart","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f902cbfe2cc0', 'en', 'US', 'Prawn Tacos (Shrimp) - with Chipotle Lime Marinade', 'Recipe video above. Chipotle is the power ingredient here, adding a stack of flavour and a hit of heat to this zesty, earthy, Mexican marinade for prawns. Perfectly paired with a creamy-yet-zingy Slaw with the trademark juiciness and floppiness of traditional Coleslaw, but made lighter with no mayonnaise which is too heavy for prawns. The Pink Taco Sauce is my quick sauce of choice here, but there''s enough juiciness in the Slaw and Tacos that you could forgo it - or just add a dash of your favourite hot sauce, or just a dollop of plain sour cream.LEMON alternative - use lemon when limes are not in season. Albeit not traditional Mexican, it works perfectly!SPICE LEVEL: Medium, chipotle is a bit spicy! You can dial it down.', 'https://www.recipetineats.com/tachyon/2020/08/Prawn-tacos_shrimp__3.jpg', 15, 6, 21, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}, {"id": "ing_ime_juice", "quantity": {"value": 0.25, "unit": "unit"}}, {"id": "ing_chipotle", "quantity": {"value": 0.015, "unit": "kg"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_cabbage", "quantity": {"value": 24.0, "unit": "head"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_yogurt", "quantity": {"value": 0.225, "unit": "tub of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.062, "unit": "L"}}, {"id": "ing_sour_cream", "quantity": {"value": 0.45, "unit": "tub of 250g"}}, {"id": "ing_sriracha", "quantity": {"value": 2.0, "unit": "bottle of 400ml"}}, {"id": "ing_tortillas", "quantity": {"value": 12.0, "unit": "pack of 8"}}, {"id": "ing_lime", "quantity": {"value": 2.0, "unit": "net of 500g"}}]', '[{"ingredients":["500g/1 lb medium prawns/shrimp (, peeled (frozen thawed, or 1 kg / 2lb unpeeled whole))","Zest of 1 lime (or lemon)","1/4 cup lime juice (or lemon)","1 tbsp chipotle powder (MEDIUM spicy, can reduce to 2 tsp for MILD, Note 1)","2 tbsp coriander/cilantro (, finely chopped (sub chives))","2 garlic cloves (, minced)","1/4 cup olive oil","1/2 tsp each salt and pepper"],"purpose":"Prawn/shrimp taco marinade:"},{"ingredients":["8 cups green cabbage (, finely shredded (about 1/4 head))","1/2 onion (, very finely chopped (brown, yellow, white))","3/4 cup plain yogurt ((like Greek), unsweetened)","1/4 coriander/cilantro (, finely chopped (sub chives))","1/4 cup lime juice (or lemon)","1/4 cup extra virgin olive oil","1/2 tsp each salt and pepper"],"purpose":"Taco Slaw:"},{"ingredients":["3/4 cup sour cream (or yogurt)","2 - 3 tbsp sriracha (, adjust to taste (Note 2))"],"purpose":"PINK TACO SAUCE:"},{"ingredients":["1 tbsp olive oil","12 - 15 small tortillas ((corn or flour), warmed or charred per packet)","Lime wedges (highly recommended)","Coriander/cilantro (, roughly chopped)"],"purpose":"TO COOK & SERVE"}]', '[{"description":"Mix Marinade ingredients in a bowl, then toss the prawns in the marinade.","images":[],"step":1},{"title":"Set aside for just 20 minutes","description":"no longer. Even 5 minutes is enough.","images":[],"step":2},{"description":"Warm a serving bowl using any method (microwave 1 minute, hot water then dry).","images":[],"step":3},{"description":"Heat 1 tablespoon oil in a large skillet over high heat. Add half the prawns and cook each side for 60 seconds (or on a BBQ on high heat, suggest double skewer for easy rotation).","duration":1,"images":[],"step":4},{"description":"Transfer to warmed bowl, loosely cover with foil. Cook the remaining prawns.","images":[],"step":5},{"description":"Serve with Slaw, Pink Taco Sauce, warmed tortillas and lime wedges.","images":[],"step":6},{"description":"Place all ingredients in a very large bowl then toss well (I use my hands!).","images":[],"step":7},{"description":"Set aside for at least 1 hour until the cabbage becomes wilted and floppy. Keeps for 3 days!","images":[],"step":8},{"description":"Mix ingredients and adjust Sriracha to your taste. Mix well - sour cream becomes looser the more you mix it.","images":[],"step":9}]', '["gluten","milk","shellfish"]', '[]', '{"mealType":["dinner"],"cuisine":["Mexican"],"categories":["mexican-recipes","prawns-shrimp","quick-and-easy","taco-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cdde56200e9e', 'en', 'US', 'Mushroom Risotto', 'Recipe video above. Creamy, comforting Mushroom Risotto fully loaded with garlicky, buttery mushrooms stirred through the risotto AND piled on top. Mouthwateringly delicious, cosy food that''s elegant enough to serve at a dinner party. It takes time to make mushrooms golden brown, but it''s worth every minute - it''s amazing!!', 'https://www.recipetineats.com/tachyon/2019/10/Mushroom-Risotto_7.jpg', 15, 35, 50, 4, '[{"id": "ing_mushroom", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 3.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_arborio_rice", "quantity": {"value": 0.188, "unit": "kg"}}, {"id": "ing_chicken", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.5, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}]', '[{"ingredients":["500g (1 lb) mushrooms (, sliced 3 mm / 1/8\" thick (Note 1))","250g (1/2 lb) mushrooms (, quartered (Note 1))","3 tbsp butter","2 tbsp olive oil","2 garlic cloves (, minced)","1/2 tsp salt and pepper (, each)"],"purpose":"Mushrooms:"},{"ingredients":["1 tbsp butter","1 garlic clove (, minced)","2 eschallots / French onions (, finely chopped (or 1/2 onion))","1/4 cup dry white wine (Note 2)","1 1/4 cups arborio rice (, uncooked)","5 cups chicken broth/stock (, low sodium, warm (Note 3))"],"purpose":"Risotto:"},{"ingredients":["1/2 cup cream (, optional but recommended(Note 4))","2 tbsp (30g) butter (, optional (Note 4))","1/2 cup parmesan cheese (, finely grated)","1/2 tsp salt and pepper (, each)"],"purpose":"Finishes:"},{"ingredients":["Finely chopped parsley or chives","Parmesan (, freshly grated)"],"purpose":"Serving:"}]', '[{"description":"Garlic Butter Mushrooms","images":[],"step":1},{"description":"Add 1 tbsp oil and half the butter in a large heavy based pot over high heat (Note 5). Once melted, add half the mushrooms and cook until pretty golden brown (~4 min).","images":[],"step":2},{"description":"Add 1/2 the garlic, 1/4 tsp each salt and pepper, then continue to cook until golden brown (~1.5 min). Then remove into bowl.","images":[],"step":3},{"description":"Repeat with remaining mushrooms, then remove.","images":[],"step":4},{"description":"Turn heat down to medium. In the same pot, melt butter then add garlic and onion.","images":[],"step":5},{"description":"Cook 2 minutes until onion is translucent but not golden.","images":[],"step":6},{"description":"Add wine and allow to simmer rapidly for 2 minutes, scraping the base of the pot, until mostly evaporated.","duration":2,"images":[],"step":7},{"description":"Add rice and stir for 1 minute until semi translucent.","duration":1,"images":[],"step":8},{"description":"Add about 1.5 cups of stock. Stir, then leave for 3 minutes, stirring just a few times, until mostly absorbed (~3 min).","duration":3,"images":[],"step":9},{"description":"Add about 1.5 cups stock, stir every now and then until mostly absorbed (~3 min) - no need to stir constantly. Repeat twice more until all stock used up, rice is just cooked but risotto still creamy and sloppy (~10 min, Note 6).","images":[],"step":10},{"description":"Add cream and butter, stir vigorously to make creamy.","images":[],"step":11},{"description":"Stir in parmesan, salt and pepper.","images":[],"step":12},{"description":"Stir through half the mushrooms, then taste and add more salt and pepper if needed. Consistency should be creamy, not stodgy (Note 7).","images":[],"step":13},{"description":"Reheat remaining mushrooms (I microwave).","images":[],"step":14},{"description":"Spoon risotto into bowls, then top with reserved mushrooms (including a drizzle of buttery juices pooled in bowl!)","images":[],"step":15},{"description":"Garnish with parsley if using, and extra parmesan. Serve immediately!","images":[],"step":16}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner","snack"],"cuisine":["American-Italian","Italian","Western"],"categories":["mushroom-recipes","pasta-recipes","rice-recipes","rice-side-dishes","risotto-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_49fac396f5a9', 'en', 'US', 'Creamy Mushroom Pasta', 'Recipe video above. It''s your creamy pasta dream come true...loaded with golden buttery garlicky mushrooms! SCALING UP (slide scaler): Cook mushroom in batches, otherwise they''ll steam instead of going golden.', 'https://www.recipetineats.com/tachyon/2019/09/Creamy-Mushroom-Pasta_4.jpg', 8, 12, 20, 2, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.32, "unit": "pack of 500g"}}, {"id": "ing_butter", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_mushroom", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_wine", "quantity": {"value": 0.167, "unit": "bottle of 750ml"}}, {"id": "ing_chicken", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}]', '[{"ingredients":["160g/ 6oz fettuccine ( or linguine (Note 1))","2 tbsp (30g) unsalted butter","1/2 tbsp olive oil (Note 2)","300g/ 10 oz mushrooms (, sliced 1/3 cm / 1/8\" thick (white, cremini/swiss brown))","2 garlic cloves (, finely chopped)","1/2 cup (125 ml) white wine (, dry (or rose, sub more broth))","1/2 cup (125ml) chicken broth/stock (, low sodium (or veg))","3/4 cup (185ml) cream (, heavy / thickened (Note 3))","1/3 cup (30g) parmesan (, finely grated (Note 4))","1/2 tsp salt and pepper (, each)"]},{"ingredients":["Extra parmesan (, for serving)","Parsley (, roughly chopped (optional))"],"purpose":"Serving:"}]', '[{"description":"Cook pasta in salted water for 1 minute less than time per packet (start this mid mushroom cook). Just before draining, scoop out 1 cup cooking water, then drain.","duration":1,"images":[],"step":1},{"description":"Melt butter and heat oil in a large skillet over high heat.","images":[],"step":2},{"description":"Add mushrooms and cook, stirring regularly. When they start to sweat, add a pinch of salt and pepper.","images":[],"step":3},{"title":"When pretty golden (about 4","description":"5 minutes), add garlic and cook until garlic is golden and mushroom is golden.","images":[],"step":4},{"description":"Stand back and add wine (it will be steamy!!), stir, scraping the bottom of the skillet. Simmer rapidly until wine is mostly evaporated and winey smell is gone.","images":[],"step":5},{"description":"Add broth, cream, parmesan, salt and pepper. Stir to dissolve parmesan and simmer for 2 minutes, stirring regularly.","duration":2,"images":[],"step":6},{"title":"Transfer pasta into sauce, toss for 1","description":"2 minutes until sauce thickens and coats pasta. If sauce gets too thick (rather than slick, see video), add a splash of reserved pasta cooking water.","duration":1.5,"images":[],"step":7},{"description":"Garnish with parsley and serve immediately with extra parmesan!","images":[],"step":8}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","mushroom-recipes","pasta-recipes","quick-and-easy","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4f11597f213f', 'en', 'US', 'Green Ginger Rice Noodles', 'Recipe video above. Rice noodles tossed in a ginger-forward, "Asian-pesto" sauce that’s based on Hainanese Chicken’s Ginger Shallot Sauce. Crazy good, fast, and it even turns the noodles green which I’m weirdly obsessed with. I threw in some shredded chicken for protein to make it a meal. Cucumber would be so great to make this a refreshing side dish (deseeded, batons or thin half-moons).Serve it warm or cold. It’s a total win for hot days, lunch boxes, or whenever you’re doing an Asian-ish spread. I see myself making this A LOT this summer!', 'https://www.recipetineats.com/tachyon/2025/11/Green-ginger-noodles_4.jpg', 15, 0, 15, 4, '[{"id": "ing_chicken", "quantity": {"value": 0.35, "unit": "kg"}}, {"id": "ing_rice_noodles", "quantity": {"value": 0.08, "unit": "pack of 375g"}}, {"id": "ing_green_onion", "quantity": {"value": 12.0, "unit": "bunch"}}, {"id": "ing_ginger", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_water", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_light_soy_sauce", "quantity": {"value": 0.12, "unit": "bottle of 250ml"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 50.0, "unit": "bottle"}}, {"id": "ing_sriracha", "quantity": {"value": 1.0, "unit": "bottle of 400ml"}}, {"id": "ing_green_onion", "quantity": {"value": 12.0, "unit": "bunch"}}]', '[{"ingredients":["350g / 3 cups shredded cooked chicken (I use my foolproof poached chicken)","350g / 3 cups shredded cooked chicken (I use my foolproof poached chicken)"]},{"ingredients":["4 cups (lightly packed) green onion (, cut into ~1.25cm / 1/2\" pieces (5 - 6 BIG stems!))","1/4 cup roughly chopped ginger (, ~ 4mm / 1/6\" pieces)","2 garlic cloves (, roughly chopped)","2 tbsp rice vinegar","2 tbsp water","2 tbsp light soy sauce (, or all-purpose soy sauce (not dark soy sauce - Note 2))","1 tsp cooking salt / kosher salt (halve for table salt, +50% for flakes)","1/4 tsp white pepper (, or black)","1/3 cup grapeseed oil (, or other neutral flavoured oil (vegetable, canola etc))"],"purpose":"Ginger shallot sauce (Note 3)"},{"ingredients":["Sriracha - use as much as you dare!","1/4 cup crispy shallots (store bought)"],"purpose":"For serving:"}]', '[{"description":"Blitz (pulsing) 1/4 of the green onion with ginger, garlic, vinegar and water until ginger is pureed. Then blitz in remaining green onion and soy until pesto-like. Stir in oil and salt, set aside 10 minutes. Toss with noodles and chicken, serve with crispy shallots and sriracha!","images":[],"step":1},{"description":"Ginger shallot sauce first:","images":[],"step":2},{"title":"Blitz","description":"Put 1/4 of the green onions in a tall jug (or deep bowl), top with the ginger, garlic, vinegar and water. Blitz with a stick blender until the ginger and garlic is pureed (~ 15 seconds). Add the remaining green onions and soy sauce. Blitz until all the green onion is finely chopped but don''t let it become green smoothie, it should be a pesto-like consistency. Asian pesto! :) (Note 4 if you don''t have a stick blender)","images":[],"step":3},{"title":"Stir and set aside","description":"Stir in the oil, salt and pepper. Then set aside for 10 minutes to let the flavours meld while you rehydrate the noodles.","duration":10,"images":[],"step":4},{"description":"Toss and eat!","images":[],"step":5},{"description":"Toss the noodles with the Green Ginger Sauce first. Toss well so it coats the noodles nicely. Then add the chicken, toss well again. (If you add chicken first, too much sauce clings to it). Loosen with a touch of water if needed.","images":[],"step":6},{"title":"Warm or cold serving","description":"If serving the noodles cold, set aside for 15 minutes+ to let the noodles cool. The flavours will continue to develop. If serving warm, serve straight away.","duration":15,"images":[],"step":7},{"title":"Serve","description":"Divide between bowls, drizzled with sriracha, sprinkle with crispy shallots, eat!","images":[],"step":8}]', '["gluten","soy"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Asian"],"categories":["no-cook-food","noodles","quick-and-easy","summer"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_cd8b34b32222', 'en', 'US', 'Italian Orzo Salad (Risoni) with Crispy Salami Bits', 'Recipe video above. The crispy salami bits are the hero here. The better bacon. Why aren''t we putting crispy salami in everything??!Tossed through a risoni/orzo salad inspired by my favourite Mega Italian Salad with lots of fresh vegetables and a good handful of cheese to keep things tasty. Excellent packed lunch, keeps well for days, love that you can eat it with a spoon. Serves 4 - 5 as a meal. Make this today, find another pasta salad for next week here!', 'https://www.recipetineats.com/tachyon/2023/07/Italian-risoni-orzo-salad_3.jpg', 15, 15, 30, 5, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.5, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.01, "unit": "L"}}, {"id": "ing_salami", "quantity": {"value": 0.25, "unit": "kg"}}, {"id": "ing_kalamata_olives", "quantity": {"value": 150.0, "unit": "bottle"}}, {"id": "ing_tightly_packed_baby_rocket_arugula", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 1.6, "unit": "punnet of 250g"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_cheese", "quantity": {"value": 1.5, "unit": "block of 250g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_basil", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.013, "unit": "pack of 100g"}}, {"id": "ing_oregano_fresh", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}]', '[{"ingredients":["250g / 8oz risoni / orzo pasta ( - 1 1/4 cups (Note 1))","2 tsp salt (, for cooking pasta)","2 tsp extra virgin olive oil"]},{"ingredients":["250g/ 8 oz salami slices (, chopped into 1.25 cm / 1/2\" squares (Note 2))","1 cup sliced kalamata olives (1 x 220g/7oz jar) - or other olives or briny things (Note 4)","2 tightly packed cups baby rocket / arugula (, torn by hand)","400g/ 14oz cherry tomatoes (, quartered (2 1/2 cups))","1 large green capsicum (, cut into 1.25cm / 1/2\" squares)","1/2 red onion (, finely diced)","1 1/2 cups (tightly packed) colby cheese (, shredded into short strands (Note 5))"],"purpose":"Salad add-ins (Note 2):"},{"ingredients":["1/3 cup extra virgin olive oil","3 tbsp red wine vinegar (or white wine vinegar, sub apple cider vinegar)","1 garlic clove (, crushed using garlic press or grated using microplane)","1 tsp dried basil","1/4 tsp red chilli flakes (optional)","1 tsp dried oregano","1/2 tsp sugar","1 tsp cooking/kosher salt"],"purpose":"Italian dressing:"}]', '[{"title":"Cook pasta","description":"Bring a large pot of water to the boil. Add salt and risoni/orzo, then cook per packet directions (usually ~10 minutes). Drain in colander, rinse, shake off excess water well. Transfer to large bowl. Toss with the olive oil then let cool.","images":[],"step":1},{"title":"Dressing","description":"Shake in a jar.","images":[],"step":2},{"title":"Crispy salami","description":"Put salami in cold large non-stick pan, with no oil. Turn onto medium high - as the pan heats up, the fat will melt so it cooks in its own fat. Cook for 3 - 5 minutes, stirring regularly, until light golden. Drain on paper towels. It will crisp as it cools.","duration":4,"images":[],"step":3},{"title":"Toss","description":"Set aside 1/3 of the salami for topping. Put all remaining salad ingredients in with the risoni. Toss. Pour over dressing. Toss, toss, toss!","images":[],"step":4},{"description":"Serve! Tumble into serving bowl. Sprinkle with remaining salami. Divide between bowls. Eat with spoon! Best eaten at room temp, not fridge cold (can taste flavours better).","images":[],"step":5}]', '["gluten","milk"]', '[]', '{"mealType":["lunch","dinner"],"cuisine":["Western"],"categories":["no-cook-food","pasta-recipes","pasta-salads-and-rice-salads","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dfecc1db1a8c', 'en', 'US', 'Smoked Sausage and Rice - easy one pot dinner!', 'Recipe video above. The smoked sausage is the trick here to get great flavour into this quick one pot dinner. Tastes like Jambalaya, minus the cajun flavours, and much faster to make. Everybody loves this!I used kransky sausages but you can use any smoked sausages you want, including chorizo. You can even use raw sausages - see Note 1! Also feel free to use other vegetables - anything that can hold up to 20 minutes on the stove.', 'https://www.recipetineats.com/tachyon/2021/08/One-Pot-Sausage-and-Rice_74.jpg', 10, 30, 40, 4, '[{"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_capsicum", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_sausages", "quantity": {"value": 0.8, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.094, "unit": "jar of 40g"}}, {"id": "ing_white_rice", "quantity": {"value": 0.225, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.625, "unit": "L"}}, {"id": "ing_frozen_peas", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["3 tbsp extra virgin olive oil","5 garlic cloves (, finely minced)","2 onions (medium), chopped (or 1 large)","1 yellow capsicum (, cut into 1.5cm / 1\" squares)","1 red capsicum (, cut into 1.5cm / 1\" squares)","400 g/ 14oz (~3) kransky or other smoked sausages (, sliced 0.5cm thick / 1/4\" thick)","3/4 tsp salt","1/2 tsp pepper","3/4 tsp smoked paprika (sub normal paprika)","1 1/2 cup long grain white rice (, uncooked (Note 2 other rices))","2 1/2 cups chicken stock/broth (, low sodium (or veg stock))","2 cups frozen peas (, thawed)","2 tbsp parsley (, chopped (optional))"]}]', '[{"title":"Cook sausage","description":"Heat 2 tbsp oil in a large heavy based pot over medium high heat. Add sausages and cook until golden. Remove with a slotted spoon.","images":[],"step":1},{"title":"Cook onion and garlic","description":"Add remaining 1 tbsp oil. Add garlic and onion, cook for 2 minutes. Add capsicum and cook for 2 minutes until onion is translucent.","duration":2,"images":[],"step":2},{"title":"Add rice and liquid","description":"Add rice, chicken stock, paprika, salt, pepper and the sausage. Stir, bring to boil, then reduce heat to low so it''s simmering very gently.","images":[],"step":3},{"title":"Cover and cook","description":"Cover with lid, cook 20 minutes.","images":[],"step":4},{"title":"Add peas and rest","description":"Remove pot from stove. Working quickly, remove lid, add peas, then quickly put the lid back on. Rest 10 minutes - the residual heat with cook the peas.","images":[],"step":5},{"title":"Fluff and serve","description":"Add parsley. Use a fork to fluff the rice. Serve immediately!","images":[],"step":6}]', '[]', '["gluten_free"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["one-pot-recipes","quick-and-easy","rice-recipes","rice-side-dishes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_76ee601a8aed', 'en', 'US', 'Nagi''s Big, Easy Pasta Salad', 'Recipe video above. This is the big-batch pasta salad I make when I''m short on time. The trick that puts this into guest-serving territory is to toss the hot, freshly cooked pasta in the dressing. You will be shocked how much flavour it absorbs!Do this, and it''s delicious no matter what you add in. My combination is the bare minimum that delivers everything I seek in a pasta salad. There''s no need to add a gazillion ingredients!Workflow - Chop the veg and make the dressing while the pasta is cooking. This will cut down active cook/prep time to 15 minutes.', 'https://www.recipetineats.com/tachyon/2024/08/Big-easy-pasta-salad_2.jpg', 10, 15, 65, 6, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_tomato", "quantity": {"value": 0.45, "unit": "kg"}}, {"id": "ing_kalamata_olives", "quantity": {"value": 50.0, "unit": "bottle"}}, {"id": "ing_feta_cheese", "quantity": {"value": 200.0, "unit": "block of 200g"}}, {"id": "ing_basil", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_apple_cider_vinegar", "quantity": {"value": 0.167, "unit": "bottle of 500ml"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_mustard", "quantity": {"value": 0.05, "unit": "jar of 200g"}}, {"id": "ing_honey", "quantity": {"value": 0.02, "unit": "jar of 500g"}}, {"id": "ing_italian_herb_mix", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.004, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}]', '[{"ingredients":["500g/ 1 lb bow tie pasta (farfalle) (, or other short/medium pasta (Note 1))"]},{"ingredients":["2 cucumbers (, halved lengthways and finely sliced (~17cm/7\" long, sliced 2mm / 1/16\", I use a mandolin))","3 cups (500g) cherry or grape tomatoes (, halved (or chop 4 regular tomatoes))","1/3 cup roughly chopped Kalamata olives (3/4 cup whole pitted or 1/2 cup sliced, then chop)","200g/ 7oz Greek feta (, cut into 6mm / 1/4\" batons (they will crumble a bit, this is good))","1 packed cup basil leaves (, torn by hand (Note 2 for alternatives))"],"purpose":"Add-ins (7 cups \"anything\" – Note 2)"},{"ingredients":["1/2 cup extra virgin olive oil","1/3 cup apple cider vinegar (Note 3)","2 garlic cloves (, minced using garlic press or very finely minced using a knife)","2 tsp dijon mustard (can omit)","2 tsp honey (sub maple syrup or 1 tsp sugar, Note 4)","1 1/2 tsp Italian herbs mix (Note 5)","3/4 tsp cooking salt / kosher salt","1/4 tsp black pepper"],"purpose":"Dressing"}]', '[{"description":"Summary directions","images":[],"step":1},{"description":"Cook pasta until soft, toss with 2/3 Dressing, cool. Toss with everything else except basil, then add basil. Serve!","images":[],"step":2},{"description":"Full directions","images":[],"step":3},{"title":"Dressing","description":"Shake the Dressing ingredients in a large jar. It should be sharp, the flavour mellows once tossed.","images":[],"step":4},{"title":"Cook pasta until soft","description":"Bring a large pot of salted water to the boil. Cook the pasta until it is very soft, about 2 - 3 minutes longer than the time on the packet but taste to check because packet directions have been known to lie! Pasta firms up when it''s cold (nobody likes hard, cold pasta!), so cook the pasta until extra soft.","images":[],"step":5},{"title":"Flavour soak","description":"Drain the pasta very well, shaking off excess water. Transfer into a large bowl. Give the Dressing a good shake then pour over about two-thirds. Toss well, then leave the pasta to soak up the dressing as it cools (~40 minutes).","images":[],"step":6},{"title":"Toss","description":"Add the tomato, cucumber, feta and olives. Pour over the remaining Dressing. Toss well. Add basil, toss again.","images":[],"step":7},{"title":"Serve","description":"Tumble into big serving bowl. Dig in!","images":[],"step":8}]', '["gluten","mustard"]', '["vegetarian"]', '{"mealType":["lunch","dinner"],"cuisine":["Western"],"categories":["pasta-recipes","pasta-salads-and-rice-salads","quick-and-easy","summer","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_a3a487f89354', 'en', 'US', 'Pasta Primavera', 'Recipe video above. This is the Pasta Primavera recipe made famous by Le Cirque restaurant in NYC. It was first published in a magazine in the 1970''s! This is an excellent big creamy pasta fix with less guilt thanks to a ton of vegetables. The trick here is timing so that all the vegetables finish cooking to tender-crisp perfection at the same time. Don''t skip the pine nuts. It''s the signature finishing touch.Counting calories? See note 1 on how to lighten the dish.', 'https://www.recipetineats.com/tachyon/2022/10/Pasta-Primavera-recipe_9.jpg', 15, 20, 35, 4, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_zucchini", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_broccoli", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_snow_peas", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_asparagus", "quantity": {"value": 0.05, "unit": "kg"}}, {"id": "ing_peas", "quantity": {"value": 1.5, "unit": "unit"}}, {"id": "ing_cherry_tomatoes", "quantity": {"value": 10.0, "unit": "punnet of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_butter", "quantity": {"value": 5.0, "unit": "block of 250g"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_egg", "quantity": {"value": 0.083, "unit": "carton of 12"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.6, "unit": "pack of 500g"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_basil", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_pinenuts", "quantity": {"value": 30.0, "unit": "jar"}}]', '[{"ingredients":["300g / 10 oz linguine (fettucine, or other long and flat pasta, Note 1)"]},{"ingredients":["150g / 5oz white mushrooms (, sliced 0.4cm / 1/6\" thick (~8 pieces))","1/2 large zucchini (, cut into 0.5cm / 0.2\" rounds (100g/4 oz piece))","1 bunch broccolini","1 1/2 cup snow peas (~10 pieces, 75g/2.5oz)","1 bunch green asparagus (~8 to 10)","1 cup green peas (, defrosted)","10 cherry tomatoes (, cut in half)","2 garlic cloves (, finely minced)"],"purpose":"Vegetables (Note 2):"},{"ingredients":["5 tbsp / 75 g unsalted butter","1 cup thickened / heavy cream (Note 3)","1/2 cup Parmigiano reggiano (, finely grated (sub regular parmesan, Note 4))"],"purpose":"Cream sauce:"},{"ingredients":["3 tbsp extra virgin olive oil","1/3 cup pasta cooking water (, scoop out just before draining (Note 6))","1 tsp cooking/kosher salt","1/4 tsp black pepper","1/2 cup fresh basil leaves (, finely sliced (Note 5))","2 tbsp pinenuts (, toasted (Note 7))"],"purpose":"Cooking:"}]', '[{"description":"Cut vegetables:","images":[],"step":1},{"title":"Broccolini","description":"Cut off florets then cut in half lengthwise. Then slice the stems diagonally into 2.5 cm / 1\" lengths.","images":[],"step":2},{"title":"Snow peas","description":"Remove the tough string running down the \"seam\" of the pea. Stack several peas and slice on the diagonal about 1cm / 0.4\" wide.","images":[],"step":3},{"title":"Asparagus","description":"Snap the base off the asparagus, it will naturally break where the woody stem stars. Cut tips off, leave whole and set aside. Slice the stems diagonally into 2.5 cm / 1\" lengths.","images":[],"step":4},{"description":"Melt butter in a saucepan over medium-high heat. Add cream and Parmigiano reggiano. Stir, and once the cream starts simmering gently, stir until the cheese melts then take it off the stove and set aside.","images":[],"step":5},{"description":"Bring a large pot of water to the boil over high heat. Add 1 tablespoon of salt and add the pasta. Cook for the time per the packet minus 1 minute. Meanwhile, cook vegetables.","images":[],"step":6},{"title":"Reserve pasta water","description":"Just before draining the pasta, scoop out a mug of pasta cooking water and set aside. Drain the pasta.","images":[],"step":7},{"description":"Cook:","images":[],"step":8},{"title":"Mushrooms","description":"Heat half the olive oil in a large skillet over high heat. Cook mushrooms for 4 minutes until golden, remove to a plate.","duration":4,"images":[],"step":9},{"title":"Veg","description":"Heat remaining oil in the same skillet. Cook broccolini, snow peas and asparagus for 2 minutes. Add zucchini, tomato, green peas, garlic, salt and pepper. Cook for a further 3 minutes. Add mushroom back in, toss, then remove from heat.","duration":2,"images":[],"step":10},{"description":"Toss! Return pasta into the now-empty pot. Add vegetables, cream sauce and 1/3 cup pasta water. Toss over medium heat using 2 wooden spoons until the sauce thickens and clings to the pasta strands rather than pooling in the base of the pot, about 1 to 2 minutes. (If at any stage the pasta gets too thick, add a splash more pasta water and toss on stove).","images":[],"step":11},{"title":"Basil & pine nuts","description":"Quickly toss through basil. Divide between 4 bowls. Sprinkle with pine nuts. Devour immediately!","images":[],"step":12}]', '["gluten","milk"]', '["high_protein","vegetarian"]', '{"mealType":["dinner"],"cuisine":["American-Italian"],"categories":["pasta-recipes","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d5ee74355d38', 'en', 'US', 'Orecchiette Sausage Pasta in Creamy Tomato Sauce', 'Recipe video above. Orecchiette has one big thing going for it that other pastas do not: its cup shape makes it the perfect vehicle to hold special pasta sauces. The creamy tomato sausage pasta sauce featured in this recipe is orecchiette worthy. Decadent? Yes. Have salad tomorrow!', 'https://www.recipetineats.com/tachyon/2020/06/Orecchiette-Sausage-in-Creamy-Tomato-Sauce_5.jpg', 10, 15, 25, 5, '[{"id": "ing_pasta_of_choice", "quantity": {"value": 0.8, "unit": "pack of 500g"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_sausages", "quantity": {"value": 1.0, "unit": "pack of 500g"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_tomato", "quantity": {"value": 0.15, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 0.75, "unit": "carton of 250ml"}}, {"id": "ing_milk", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_parmesan", "quantity": {"value": 0.167, "unit": "pack of 200g"}}, {"id": "ing_italian_herbs", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_kale", "quantity": {"value": 3.0, "unit": "unit"}}]', '[{"ingredients":["400g / 14oz orecchiette pasta (or other pasta)","1 tbsp olive oil","2 garlic cloves (, minced)","500g / 1lb Italian pork sausages (, meat squeezed out of their casings (see video, Note 1))","1/4 cup white wine (, anything not too sweet (sub water))","1 cup tomato passata (called \"tomato puree\" in US, Note 2)","3/4 cup cream (, heavy/thickened)","3/4 cup milk (any fat %)","1/3 cup parmesan (, finely grated)","1 tsp Italian herbs (Note 3)","1/4 tsp red pepper flakes (chilli flakes)","1/4 tsp each salt and pepper","3 cups (packed) kale leaves (, torn into bite size pieces (or baby spinach, swiss chard, Tuscan kale etc))","Parmesan (, for serving)"]}]', '[{"description":"Bring a large pot of water to the boil and cook pasta according to packet directions MINUS 1 minute. Just before draining, scoop out 1 cup of pasta cooking water and set aside. (Note 4)","images":[],"step":1},{"description":"Heat oil in a very large skillet over high heat. Add garlic and cook for 15 seconds.","duration":0.25,"images":[],"step":2},{"description":"Add sausage meat and cook, breaking it up as you go, until there are some little golden bits - about 4 minutes.","images":[],"step":3},{"description":"Add wine and cook, scraping the bottom of the skillet to remove the golden bits, and allow wine to evaporate - the winey smell will disappear.","images":[],"step":4},{"description":"Add remaining ingredients except kale. Stir well, bring to simmer then turn stove down to low and simmer gently for 2 minutes to bring all the flavours together.","duration":2,"images":[],"step":5},{"description":"Add pasta and kale. Toss well for 1 minute to coat pasta well with the sauce - it will thicken. If the sauce gets too thick, use the reserved pasta cooking water to loosen it up (Note 4).","duration":1,"images":[],"step":6},{"description":"Serve immediately, garnished with freshly grated parmesan","images":[],"step":7}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Italian-esque","Western"],"categories":["pasta-recipes","quick-and-easy","sausage-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dbf6c42c0e1d', 'en', 'US', 'Pizza Capricciosa', 'Recipe video above. Topped with artichokes, ham, olives and mushrooms with a tomato pizza sauce, this is a pizza that''s almost uniquely Australian that we are VERY fond of! Though you can find it in some parts of Italy, you won''t see it in many other places around the world.I just love the combination - and that you can be generous with the toppings without overwhelming the pizza. Cook times:Classic yeast pizza dough - 5 to 6 hrs dough rising (total) | 10 min prep | 10 min cookNo-yeast pizza dough - 0 min dough rising | 10 min prep | 10 min oil steeping | 10 min cookStore bought pizza dough - 5 min prep | 10 min prep | 10 min cook** To make more than one pizza (who ever makes just one??!) slide the servings scaler **', 'https://www.recipetineats.com/tachyon/2024/05/Pizza-Capricciosa_8.jpg', 10, 10, 20, 1, '[{"id": "ing_classic_pizza_dough", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_yeast", "quantity": {"value": 1.0, "unit": "pack of 5 sachets"}}, {"id": "ing_uncategorized", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.037, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_sugar", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 0.167, "unit": "pack of 3 heads"}}, {"id": "ing_parsley", "quantity": {"value": 0.013, "unit": "bunch"}}, {"id": "ing_mozzarella", "quantity": {"value": 1.067, "unit": "pack of 125g"}}, {"id": "ing_artichokes", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_mushroom", "quantity": {"value": 3.0, "unit": "kg"}}, {"id": "ing_shaved_leg_ham", "quantity": {"value": 0.1, "unit": "kg"}}, {"id": "ing_kalamata_olives", "quantity": {"value": 37.5, "unit": "bottle"}}]', '[{"ingredients":["1 classic pizza dough (wood-fired Italian style)","1 fast no-yeast pizza dough (this is excellent!)","1 Store bought (30cm/12\")"],"purpose":"Pizza base – choose one (Note 1):"},{"ingredients":["1/4 cup tomato paste","1/4 tsp cooking salt / kosher salt","1/2 tsp white sugar","1/2 tbsp water","1/2 garlic clove (, finely minced (optional))","1/8 tsp EACH dried parsley , basil and oregano (optional)"],"purpose":"Pizza sauce"},{"ingredients":["1 1/3 cup (130 g) mozzarella cheese, freshly shredded (Note 2)","1/2 cup artichokes (from a jar, preferably oil, drained & sliced (Note 3))","3 button mushrooms (, cut into 3 mm / 1/8\" slices)","2/3 cup (70 g) shaved leg ham (, torn into pieces (thinner is better) (Note 4))","1/4 cup sliced kalamata olives (or black olives)"],"purpose":"Capricciosa topping:"}]', '[{"description":"Preheat oven to 250°C / 480°F (both fan and standard). Allow time to get it nice and hot!!","images":[],"step":1},{"title":"Pizza sauce","description":"Mix the ingredients in a small bowl then set aside.","images":[],"step":2},{"title":"Pizza base","description":"Make and stretch out your chosen pizza base (no rolling pin!), stretch onto a pizza pan or baking tray per the directions in your chosen pizza base. (Note 4 for pizza stone)","images":[],"step":3},{"title":"Top","description":"Spread the pizza sauce on the pizza, leaving a 1 cm/1/2\" border along the edge. Sprinkle with cheese first, then drape the ham randomly across the surface, sprinkle with olives, artichoke slices and mushrooms. (If using the no-yeast pizza base, spray/brush exposed crust with olive oil.)","images":[],"step":4},{"title":"Bake for 10","description":"12 minutes, turning after 4 minutes, or until the the cheese has golden spots and the crust is crispy. Cut and eat, stat!","duration":11,"images":[],"step":5}]', '["milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Australian","Italian"],"categories":["pizza-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_1221c3547c57', 'en', 'US', 'Garlic cheese pizza', 'Recipe video above. No visit to your favourite pizzeria start without garlic cheese pizza! My best garlic pizza calls for both parmesan and mozzarella cheese, and to infuse olive oil with garlic (it only takes 10 minutes). It''s outrageously good!Cook times:Classic yeast pizza dough - 5 to 6 hours dough rising (total) | 10 min prep | 8 min cookNo-yeast pizza dough - 0 min dough rising | 10 min prep | 10 min oil steeping | 8 min cookStore bought pizza dough - 5 min prep | 10 min oil steeping | 8 min cook', 'https://www.recipetineats.com/tachyon/2023/05/Garlic-cheese-pizza_9.jpg', 10, 8, 18, 1, '[{"id": "ing_classic_pizza_dough", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_yeast", "quantity": {"value": 1.0, "unit": "pack of 5 sachets"}}, {"id": "ing_uncategorized", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.03, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 3.333, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_mozzarella", "quantity": {"value": 0.8, "unit": "pack of 125g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}]', '[{"ingredients":["1 classic pizza dough (wood-fired Italian style)","1 fast no-yeast pizza dough (this is excellent!)","1 Store bought"],"purpose":"Pizza 30cm/12\" base – your choice (Note 1):"},{"ingredients":["2 tbsp extra virgin olive oil","2 tsp garlic (2 - 3 large cloves), crushed using garlic press or make paste using side of knife - Note 2)","1/8 tsp cooking salt / kosher salt (or table salt, or double qty for salt flakes)","1 cup mozzarella cheese (tightly packed cup), shredded using box grater (Note 3 on pre-shredded)","1/2 cup parmesan (tightly packed cup), shredded using box grater (Note 3)"],"purpose":"Garlic pizza topping:"}]', '[{"description":"Preheat oven to 250°C / 480°F (230°C fan). Allow time to get it nice and hot!!","images":[],"step":1},{"title":"Garlic infused oil","description":"Mix olive oil and garlic in a small bowl. Set aside to infuse with flavour for 10 minutes.","duration":10,"images":[],"step":2},{"title":"Pizza base","description":"Make and roll out chosen pizza base, stretch onto pan.","images":[],"step":3},{"title":"Top","description":"Spread oil (and all garlic) onto the base, leaving the crust baked. Sprinkle with salt, parmesan then mozzarella. (If using no-yeast base, spray/brush exposed crust with olive oil.)","images":[],"step":4},{"description":"Bake 8 minutes, turning after 4 minutes, or until the the cheese has golden spots. Cut and eat, stat!","images":[],"step":5}]', '["milk"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner","snack"],"cuisine":["Italian"],"categories":["pizza-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_934f113e6576', 'en', 'US', 'Pork Tenderloin with Honey Garlic Sauce', 'Recipe VIDEO above. Tender, succulent pork fillet seasoned with a rub, seared until golden then baked in a Honey Garlic Sauce until sticky on the outside and juicy on the inside. Simply incredible! (And really, it''s SIMPLE!)', 'https://www.recipetineats.com/tachyon/2019/05/Honey-Garlic-Pork-Tenderloin_1.jpg', 10, 25, 35, 5, '[{"id": "ing_pork", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_vinegar", "quantity": {"value": 0.045, "unit": "L"}}, {"id": "ing_soy_sauce", "quantity": {"value": 0.09, "unit": "bottle of 250ml"}}, {"id": "ing_honey", "quantity": {"value": 0.25, "unit": "jar of 500g"}}]', '[{"ingredients":["2 pork tenderloin (pork fillet), 500g/1lb each (Note 1)","1 1/2 tbsp olive oil (or butter)","3 garlic cloves (, very finely chopped)"]},{"ingredients":["1/2 tsp garlic powder","1/2 tsp paprika","1/2 tsp salt","1/2 tsp black pepper"],"purpose":"Pork Tenderloin Rub:"},{"ingredients":["3 tbsp cider vinegar (Note 2)","1 1/2 tbsp soy sauce, light or all purpose (Note 2)","1/2 cup honey (or maple syrup)"],"purpose":"Honey Garlic Sauce:"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Mix Sauce ingredients together.","images":[],"step":2},{"description":"Mix Rub ingredients then sprinkle over the pork.","images":[],"step":3},{"description":"Heat oil in a large oven proof skillet (Note 3) over high heat. Add pork and sear until golden all over.","images":[],"step":4},{"description":"When pork is almost seared, push to the side, add garlic and cook until golden.","images":[],"step":5},{"description":"Pour sauce in. Turn pork once, then immediately transfer to the oven.","images":[],"step":6},{"title":"Roast 15","description":"18 minutes or until the internal temperature is 68C / 155F (Note 4).","images":[],"step":7},{"description":"Remove pork onto plate, cover loosely with foil and rest 5 minutes.","images":[],"step":8},{"description":"Place skillet with sauce on stove over medium high heat, simmer rapidly for 3 minutes until liquid reduces down to thin syrup.","duration":3,"images":[],"step":9},{"description":"Remove from stove, put pork in and turn to coat in sauce.","images":[],"step":10},{"description":"Cut pork into thick slices and serve with sauce!","images":[],"step":11}]', '["fish","gluten","milk","soy"]', '["high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["dinner-tonight","pork-recipes","quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8a2b3c76a262', 'en', 'US', 'Creamy Garlic Prawns (Shrimp)', 'Recipe video above. Creamy Garlic Prawns are your favourite garlic prawns … PLUS a creamy garlic sauce! A few simple tricks give a leg-up to the sauce for a result that''s a cut above your basic recipes: deglaze the pan with a little white wine, a splash of chicken stock and sprinkle of parmesan. Because plump, sweet prawns demand the BEST sauce!', 'https://www.recipetineats.com/tachyon/2020/09/Creamy-Garlic-Prawns_7.jpg', 5, 12, 17, 4, '[{"id": "ing_shrimp", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_butter", "quantity": {"value": 15.0, "unit": "block of 250g"}}, {"id": "ing_wine", "quantity": {"value": 0.083, "unit": "bottle of 750ml"}}, {"id": "ing_vegetable_stock", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_parmesan", "quantity": {"value": 0.25, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 0.6, "unit": "bunch"}}]', '[{"ingredients":["500g / 1lb peeled prawns/shrimp (, large/jumbo best (Note 1))","1 garlic cloves (, finely minced)","1 tbsp olive oil","1/2 tsp black pepper","1/2 tsp salt"],"purpose":"Garlic marinated prawns:"},{"ingredients":["15g / 1 tbsp unsalted butter"],"purpose":"Cooking prawns:"},{"ingredients":["2 garlic clove (, finely minced)","15g / 1 tbsp unsalted butter","1/4 cup dry white wine (or more chicken stock) (Note 2)","1/2 cup chicken or vegetable stock/broth (, low sodium)","1 cup heavy/thickened cream","1/2 cup parmesan (, finely grated (grate your own, Note 3))","2 tbsp parsley (, finely chopped)"],"purpose":"Creamy garlic sauce:"}]', '[{"description":"Marinate Prawns:","images":[],"step":1},{"description":"Place prawns, garlic, oil and pepper in a bowl. Toss to coat, set aside 20 minutes if time permits (no longer).","images":[],"step":2},{"description":"Stir through salt just prior to cooking.","images":[],"step":3},{"description":"Cook prawns:","images":[],"step":4},{"description":"Melt 15g / 1 tbsp butter in a large skillet over medium high heat. Add half the prawns and cook for 1 minute on each side, then remove.","duration":1,"images":[],"step":5},{"description":"Repeat with remaining prawns (you shouldn''t need more butter), then remove. Scrape out excess remaining garlic from pan and add to cooked prawns.","images":[],"step":6},{"description":"Add butter into skillet and let it melt. Add garlic and stir for 30 seconds or until light golden.","duration":0.5,"images":[],"step":7},{"description":"Add white wine, turn up heat to high. Bring to simmer while stirring base of the pan to dissolve all the golden bits into the sauce. Cook 1 minute or until it most evaporates and the winey smell is gone.","images":[],"step":8},{"description":"Add chicken stock and reduce until mostly gone and just a thin layer remains on base of skillet.","images":[],"step":9},{"description":"Add cream, then simmer on medium heat for 2 minutes until reduced and slightly thickened.","duration":2,"images":[],"step":10},{"description":"Stir through parmesan, then add the prawns back in. Taste sauce and see if more salt and pepper is needed.","images":[],"step":11},{"description":"Serve sprinkled with parsley, over mashed potato or something to soak up that fabulous sauce!","images":[],"step":12}]', '["milk","shellfish"]', '["gluten_free","high_protein","high_protein_low_calorie","keto_friendly"]', '{"mealType":["dinner","snack"],"cuisine":["Western"],"categories":["prawns-shrimp","quick-and-easy","seafood-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_138af84f0415', 'en', 'US', '8 minute Lebanese Pizzas (Lahmacun!)', 'Recipe video above. Invented in pursuit of more interesting ways to use chicken mince, this is a SOS take on traditional manakish Lebanese pizzas made with flatbreads topped with a thin layer of meat, commonly known by the Turkish name lahmacun. Astoundingly fast to make, and extremely versatile, think of this recipe as a blueprint rather than a rule book. Use any ground meat, add shredded vegetables - and topping options are endless! Don''t skip the feta and olive oil for toppings. It really makes it. :)', 'https://www.recipetineats.com/tachyon/2025/01/Quick-Lebanese-pizza_1.jpg', 5, 3, 8, 1, '[{"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_chicken_mince", "quantity": {"value": 0.125, "unit": "kg"}}, {"id": "ing_tomato", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_baharat_spice_mix", "quantity": {"value": 5.0, "unit": "jar"}}, {"id": "ing_paprika", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_parsley", "quantity": {"value": 0.3, "unit": "bunch"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_cheese", "quantity": {"value": 2.0, "unit": "block of 250g"}}, {"id": "ing_lemon", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_pine_nuts", "quantity": {"value": 1.0, "unit": "pack of 100g"}}]', '[{"ingredients":["1 x ~30cm/12\" Lebanese bread (, (sub other thin flatbreads, Note 1))"]},{"ingredients":["125g / 4 oz chicken mince (ground chicken) (Note 2)","2 tsp tomato paste","1 tsp Baharat spice mix (aka Lebanese 7 spice) (Note 3 subs)","1/2 tsp paprika (, sweet (or smoked))","1 garlic clove (, crushed using garlic press)","1/4 tsp cooking salt / kosher salt (halve for table salt)","1 tbsp finely chopped parsley (or coriander/cilantro, totally optional (sub 1 tsp dried oregano))","1 1/2 tbsp extra virgin olive oil (, for cooking (or regular olive oil))"],"purpose":"Spiced Chicken Mince spread:"},{"ingredients":["Extra virgin olive oil","2 tbsp Danish feta or goats cheese (, crumbled (or regular feta))"],"purpose":"Toppings – essential! (Note 4)"},{"ingredients":["Lemon juice (, just a light drizzle)","Dried chilli flakes / red pepper flakes","~1 tbsp toasted pine nuts (, roughly chopped (sub pistachios, almonds, sesame seeds))","1 tsp finely chopped parsley (or coriander/cilantro)"],"purpose":"Toppings – optional (makes it even better!)"}]', '[{"description":"Trim bread to fit pan, mix filling, smear on bread. Heat oil on high, pan fry 90 seconds meat side down, then bread side 90 seconds until crispy. Top, cut, eat!","images":[],"step":1},{"description":"Use a large 30cm/12\" non-stick pan. If needed, use scissors to cut one side of the Lebanese bread so it fits in your pan (Note 1 & 5)","images":[],"step":2},{"description":"Mix the Chicken Spread ingredients in a bowl. Spread all across the surface of one side of the bread like peanut butter, smearing and pressing it onto the bread well so it sticks. Use it all! (It will be a fairly thin layer.)","images":[],"step":3},{"title":"Cook meat side","description":"Heat 1 tablespoon of oil in the pan over high heat. Place the bread in meat side down and cook for 90 seconds, pressing down lightly to encourage colour. The meat will stick to the bread!","duration":1.5,"images":[],"step":4},{"title":"Crisp bread","description":"Turn with tongs (there should be some golden patches) and cook the bread side for 90 seconds until golden and crispy (lower heat if browning too quickly).","duration":1.5,"images":[],"step":5},{"title":"Toppings","description":"Slide onto cutting board, sprinkle with feta, drizzle with extra virgin olive oil. Sprinkle with other toppings you choose. Cut into 8 like pizza, enjoy!","images":[],"step":6}]', '["gluten","milk","sesame"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["lebanese","Middle Eastern"],"categories":["quick-and-easy"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_665ad93fc3ad', 'en', 'US', 'Cowboy Butter - for steak, and so much more!', 'This goes phenomenally well with steak (try it with Tomahawk!), though I''ve been using it with everything from chicken to toast, vegetables to hot steamed rice.Most recipes just mix raw garlic in, but honestly, doing a mini sauté is so worth it - the garlic flavour is much nicer.', 'https://www.recipetineats.com/tachyon/2025/05/Cowboy-butter.jpg', 5, 1, 6, 2, '[{"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 333.333, "unit": "pack of 3 heads"}}, {"id": "ing_mustard", "quantity": {"value": 0.075, "unit": "jar of 200g"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.125, "unit": "jar of 40g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.001, "unit": "kg"}}]', '[{"ingredients":["100g / 7 tbsp unsalted butter (, softened, divided)","1 large garlic clove (, finely minced (1 tsp) - knife best (Note 1))","1 tbsp Dijon mustard","1 tsp smoked paprika (sub regular paprika)","1 tsp chilli flakes / red pepper flakes","1/4 tsp cooking salt / kosher salt (halve for table salt)"]}]', '[{"title":"Sauté garlic","description":"In a small frying pan, melt 1 tbsp (15g) of butter over medium heat until it starts foaming then add the garlic and cook for 30 seconds while stirring until it becomes very, very light golden. Remove from the stove and let it cool for 3 minutes (the garlic will go more golden).","duration":0.5,"images":[],"step":1},{"title":"Mix","description":"Put the rest of the butter and remaining ingredients in a small mixing bowl. Pour the garlic butter over. Mix until combined.","images":[],"step":2},{"description":"Serve with steak! It''s also excellent with other cooked meats, seafood and even vegetables.","images":[],"step":3},{"description":"How to use Cowboy Butter:","images":[],"step":4},{"description":"I like to use it softened as it melts thicker over hot steak. You can also melt gently then dip bites of steak in, or roll it into a log using cling wrap, refrigerate then cut slices off on an as-need basis (you can place the coins on the steak to let it melt).","images":[],"step":5}]', '["milk","mustard"]', '["gluten_free","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["roast-beef","sauces"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_0cb49661606c', 'en', 'US', 'Christmas Leftovers Toasted Bread Bowl', 'Recipe video above. This isn''t really a recipe, it''s more of an idea you can make your own. A way to completely transform leftovers into an epic sandwich for sharing! Use leftover ham, cooked meats, roasted veg, cheese platter leftovers. Imagine the possibilities! Great served fresh AND travels well!', 'https://www.recipetineats.com/tachyon/2018/12/Bread-Bowl-Sandwich-Christmas-Leftover-Ham-Turkey_6.jpg', 15, 30, 45, 4, '[{"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}, {"id": "ing_ham_turkey_and_other_meat_slices", "quantity": {"value": 0.3, "unit": "kg"}}, {"id": "ing_antipasto_things", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_cheese", "quantity": {"value": 4.0, "unit": "block of 250g"}}, {"id": "ing_baby_spinach", "quantity": {"value": 3.0, "unit": "bag of 250g"}}, {"id": "ing_butter", "quantity": {"value": 50.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.333, "unit": "pack of 3 heads"}}]', '[{"ingredients":["1 round or oval bread loaf (Note 1)","300 g / 10 oz ham, turkey and other cooked meat slices","1 cup roughly chopped antipasto things (olives, sun dried tomato, chargrilled peppers, artichokes, feta etc)","4 - 6 slices cheese of choice (I used Swiss in the video)","3 big handfuls baby spinach (~75g / 2.5oz)"]},{"ingredients":["50 g / 3 tbsp salted butter (, melted)","1 garlic clove (, minced)"],"purpose":"Garlic Butter:"}]', '[{"description":"Preheat oven to 180C/350F.","images":[],"step":1},{"description":"Mix butter and garlic.","images":[],"step":2},{"description":"Cut the top off the bread loaf. Pick out bread from the loaf and the lid, leaving a wall and floor about 1.5cm / 3/5\" thick.","images":[],"step":3},{"description":"Place bread on a large sheet of foil on a baking tray.","images":[],"step":4},{"title":"Dab / brush inside with butter. Layer with","description":"half spinach, turkey, antipasto things, remaining spinach, ham, cheese.","images":[],"step":5},{"description":"Tuck flappy bits inside the loaf, top with lid.","images":[],"step":6},{"description":"Brush with butter all over. Wrap with foil.","images":[],"step":7},{"title":"Weigh down with something flat and heavy","description":"cast iron skillet is ideal.","images":[],"step":8},{"description":"Bake for 20 minutes. Remove skillet and foil.","duration":20,"images":[],"step":9},{"description":"Bake for a further 10 minutes until golden.","images":[],"step":10},{"description":"Cut into thick slices and serve immediately!","images":[],"step":11}]', '["gluten","milk"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":[],"categories":["sandwiches-and-sliders"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_213b9d603866', 'en', 'US', 'Crispy marinated baby octopus', 'Recipe video above. Here''s an easy, outrageously delicious way to cook baby octopus: simmered until tender, marinated in bold Mediterranean flavours, seared until crispy. Add a Greek Salad, bread for mopping and a glass of chilled wine for the perfect summer meal!2 kg / 4 lb raw baby octopus will serve 5 to 6 people as a main - it shrinks quite substantially. It might even be better the next day, so look forward to leftovers!', 'https://www.recipetineats.com/tachyon/2023/02/Crispy-baby-octopus_3.jpg', 10, 75, 85, 6, '[{"id": "ing_baby_octopus", "quantity": {"value": 2.0, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 4.0, "unit": "L"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 2.0, "unit": "pack of 3 heads"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_salt", "quantity": {"value": 0.01, "unit": "kg"}}, {"id": "ing_lemon", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_parsley", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_olive_oil", "quantity": {"value": 0.125, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.09, "unit": "net of 500g"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_oil", "quantity": {"value": 75.0, "unit": "bottle"}}, {"id": "ing_parsley", "quantity": {"value": 3.0, "unit": "bunch"}}, {"id": "ing_chilli", "quantity": {"value": 0.05, "unit": "pack of 100g"}}, {"id": "ing_lemon", "quantity": {"value": 0.09, "unit": "net of 500g"}}]', '[{"ingredients":["2 kg / 4 lb baby octopus (, rinsed (Note 1))"]},{"ingredients":["4 litres / quarts water","1 onion (, halved, skin on)","6 garlic cloves (, smashed (Note 2))","1 tsp black peppercorns (sub 1/2 tsp ground pepper)","2 tsp cooking salt (kosher salt)","3 tbsp lemon juice (or apple cider vinegar)","3 parsley stems (with leaves)","2 bay leaves (, fresh or dried)"],"purpose":"Braising liquid:"},{"ingredients":["1/2 cup extra virgin olive oil","6 garlic cloves (, very finely minced (or use garlic press))","2 tsp lemon zest (one large lemon)","2 tbsp lemon juice","1 tsp dried red chilli flakes ((red pepper flakes), optional)","1/2 tsp each cooking/kosher salt and black pepper"],"purpose":"Marinade:"},{"ingredients":["1 tbsp canola oil (for BBQ or large skillet)","2 tsp parsley (, finely chopped (optional))","1 large red chilli (, finely sliced (optional))","Lemon wedges (highly recommended)"],"purpose":"Cooking & serving:"}]', '[{"title":"Braising","description":"Put all the braising liquid ingredients in a large pot and bring to a boil over high heat. Add octopus, bring back up to the boil, then reduce the heat to low so the water is simmering very, very gently. Scoop off and discard scum off the surface when it accumulates.","images":[],"step":1},{"description":"Braise 1 hour until tender, first checking at the 45 minute mark, or until octopus is tender (take a little nibble to check!).","images":[],"step":2},{"description":"Drain octopus in a colander. Pick out and discard the bay leaves, onion etc. Transfer octopus into a bowl.","images":[],"step":3},{"title":"Marinate","description":"Mix marinade ingredients in a bowl. Pour over the octopus (while still hot). Toss, allow to fully cool, cover with cling wrap then marinate overnight in the fridge. (Note 4)","images":[],"step":4},{"title":"Cook until crispy (BBQ)","description":"Heat a BBQ hot plate on medium high until hot. Spread oil across the hot plate. Use tongs to transfer the octopus onto the BBQ (leave residual oil behind), spread out and cook for 3 to 5 minutes, rotating as needed to brown all over, and most especially ensuring the legs are golden and crispy. (Stove - use a large skillet, cook in 2 or 3 batches).","duration":4,"images":[],"step":5},{"title":"Serve","description":"Pile octopus on a plate. Sprinkle with parsley and chilli, add lemon wedges. EAT and be happy! Serve with bread for mopping or see Note 4 for crushed potatoes pictured in post dressed with residual marinade.","images":[],"step":6}]', '["shellfish"]', '["gluten_free","high_protein","high_protein_low_calorie","low_calorie"]', '{"mealType":["dinner","snack"],"cuisine":["Mediterranean","Western"],"categories":["seafood-recipes","uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4d7a56f7c22f', 'en', 'US', 'Vegetable Beef Soup (Fall apart beef!)', 'Recipe VIDEO above. Melt-in-your-mouth chunks of beef, vegetables and potato in a hearty herb infused broth. You''ll love how the soup broth is slightly thickened and the extra flavour the wine or beer adds to the soup (the secret ingredient!). 20 minutes active cook/prep.', 'https://www.recipetineats.com/tachyon/2019/05/Vegetable-Beef-Soup_3.jpg', 15, 110, 125, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.022, "unit": "L"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_beef", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_wine", "quantity": {"value": 0.5, "unit": "bottle of 750ml"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.03, "unit": "kg"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_thyme", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_frozen_peas", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 2.0, "unit": "bag of 2kg"}}, {"id": "ing_butter", "quantity": {"value": 1.0, "unit": "block of 250g"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}]', '[{"ingredients":["1.5 tbsp olive oil (, separated)","500g/1 lb stewing beef (, cut into 1.75cm / 2/3\" cubes (Note 1))","1/2 tsp salt and pepper","1 onion (, chopped)","3 garlic (, minced (1 tbsp))","2 celery (, cut into 0.8 cm / 1/3\" slices)","3 carrots (, cut into 0.5 cm / 1/5\" thick slices (halve larger ones))","4 tbsp flour","2 1/2 cups (625ml) beef broth/stock (, low sodium)","1 1/2 cups (375ml) dry red wine, Guinness beer or stout (Note 2)","1.5 cups (375ml) water","2 tbsp tomato paste","2 bay leaves","1 tsp thyme dried","1 cup frozen peas","2 potatoes ((any), cut into 1.5cm / 2/3\" cubes)"]},{"ingredients":["1 tbsp (15g) butter or oil","200g/ 6oz small mushrooms (, quartered or halved)"],"purpose":"Buttery mushrooms (optional):"}]', '[{"description":"Heat 1 tbsp oil until very hot in a large, heavy based pot over high heat.","images":[],"step":1},{"description":"Pat beef dry with paper towels, then sprinkle with salt and pepper.","images":[],"step":2},{"description":"Brown beef aggressively in 2 or 3 batches, adding more oil if needed. Remove browned beef into a bowl.","images":[],"step":3},{"description":"If pot looks dry, add a touch more oil.","images":[],"step":4},{"description":"Add garlic and onion, cook for 2 minutes.","duration":2,"images":[],"step":5},{"description":"Add carrot and celery, cook for 2 minutes or until onion is translucent.","duration":2,"images":[],"step":6},{"description":"Stir in flour, then slowly pour in beef broth while constantly stirring.","images":[],"step":7},{"description":"Add beer, water, tomato paste, bay leaves and thyme, stir well. Then add the beef back in.","images":[],"step":8},{"description":"Cover, adjust heat to medium low so it''s bubbling gently. Simmer 1 hr 15 min or until beef is pretty tender.","images":[],"step":9},{"description":"Add potatoes and peas, simmer for a further 20 minutes without the lid. Add cooked mushrooms in the last 5 minutes.","images":[],"step":10},{"description":"The soup is ready when the potatoes are cooked and beef is very tender (see video).","images":[],"step":11},{"description":"Adjust salt and pepper to taste (I like lots of pepper in this!).","images":[],"step":12},{"description":"Ladle into bowls. Sprinkle with parsley and serve with crusty bread if desired. Try quick Cheesy Garlic Bread or super easy Irish Soda Bread!","images":[],"step":13},{"description":"Buttery Mushrooms (optional):","images":[],"step":14},{"description":"Melt butter in a large skillet over medium high heat. Add mushrooms and cook for 5 minutes until browned. Sprinkle with salt and pepper.","duration":5,"images":[],"step":15}]', '["gluten","milk"]', '["high_protein","high_protein_low_calorie"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["slow-cooker-recipes","soup-recipes","stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_5165fdd50aa0', 'en', 'US', 'Cold Corn Soup for Summer', 'Recipe video above. Corn Soup is one of those rare soups best served cold. For all those days when it''s too hot to even contemplate eating hot food!Sweet summer corn is the star here that makes a simple corn stock that drives home the corn flavour. If you can''t get good fresh corn where you are, use frozen corn instead but prop the flavour up with chicken or vegetable stock.Serve cold as a canape in shot glasses, tea cups as a starter, or bowls as a meal. Serves 6 as a meal.', 'https://www.recipetineats.com/tachyon/2021/06/Cold-Corn-Soup_0.jpg', 15, 45, 60, 6, '[{"id": "ing_corn", "quantity": {"value": 8.0, "unit": "can of 400g"}}, {"id": "ing_water", "quantity": {"value": 3.0, "unit": "L"}}, {"id": "ing_butter", "quantity": {"value": 100.0, "unit": "block of 250g"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 0.5, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_eek", "quantity": {"value": 0.5, "unit": "unit"}}, {"id": "ing_salt", "quantity": {"value": 0.005, "unit": "kg"}}, {"id": "ing_cream", "quantity": {"value": 1.0, "unit": "carton of 250ml"}}, {"id": "ing_thyme", "quantity": {"value": 0.08, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 1.0, "unit": "unit"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_coriander", "quantity": {"value": 0.1, "unit": "bunch"}}, {"id": "ing_corn", "quantity": {"value": 8.0, "unit": "can of 400g"}}, {"id": "ing_green_onion", "quantity": {"value": 0.75, "unit": "bunch"}}]', '[{"ingredients":["8 ears yellow corn (Note 1 for frozen corn)","3 litres / 3 quarts water"],"purpose":"Corn stock:"},{"ingredients":["100g/ 7 tbsp unsalted butter","2 garlic cloves (, chopped)","1/2 onion (, finely sliced)","1 celery stalk (, sliced)","1/2 leek (, white part only, finely sliced (sub 1/2 onion))","1 tsp salt (, cooking/kosher salt, plus more as needed)","1 cup cream (, full fat)"],"purpose":"Corn soup:"},{"ingredients":["2 sprigs of thyme","1 bay leaf (, preferably fresh otherwise dried)","1 tsp black peppercorns","1 tsp coriander seeds"],"purpose":"Herb Spice Sachet (Note 2):"},{"ingredients":["Extra corn kernels (, sautéed in butter until golden with a pinch of salt and pepper)","1/4 cup green onion (, finely sliced)"],"purpose":"Optional Garnish:"}]', '[{"title":"Cut off kernels","description":"Cut the corn kernels off the cobs and transfer to a bowl.","images":[],"step":1},{"title":"Corn stock","description":"Cut the cobs in half. Place in a large pot with the water. Bring to a boil, then reduce to medium low and simmer for 30 minutes. Strain - it should be 2 litres. If it''s much more , simmer to reduce. If less, top up with water.","duration":30,"images":[],"step":2},{"title":"Sachet","description":"Bundle the bay leaf, thyme, black peppercorns and coriander seeds loosely in a small piece of cheesecloth to create a sachet. Tie with cooking twine to secure.","images":[],"step":3},{"title":"Sauté aromatics","description":"Melt butter in a pot over medium high heat. Add onion, celery, leek and garlic. Cook for 4 - 5 minutes until soft.","duration":4.5,"images":[],"step":4},{"title":"Cook corn","description":"Add corn kernels then cook for 6 to 7 minutes.","duration":6.5,"images":[],"step":5},{"title":"Simmer","description":"Add the corn stock and the sachet. Bring it to a boil and let it simmer for 20 minutes.","duration":20,"images":[],"step":6},{"title":"Cream","description":"Add the cream and cook for 3 minutes.","duration":3,"images":[],"step":7},{"title":"Blend and sieve","description":"Remove the Sachet. Blend in batches in a blender on high speed until smooth. CAUTION! Hot liquid + tightly sealed blender lid = soup explosion! To avoid this, either cool before blending. OR remove the lid of the feeding tube in the blender lid. Cover the exposed hole with a folded tea towel as you blend hot liquid. You will see me do this in the recipe video.","images":[],"step":8},{"title":"Strain","description":"Pass through a fine sieve.","images":[],"step":9},{"title":"Adjust salt","description":"Taste and add more salt if needed.","images":[],"step":10},{"title":"Chill and serve","description":"Cool, then transfer to the fridge to chill completely. Intended to be served chilled or cool, but also great at room temperture or warm!","images":[],"step":11},{"title":"How to serve","description":"In shot glasses as a canape, tea cups as a small starter, or bowls as a meal with hunks of crusty bread. Garnish with kernels sauteed in butter with green onion slices and a drizzle of extra virgin olive oil (basil oil would be even more incredible!).","images":[],"step":12}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner","snack"],"cuisine":["Western"],"categories":["soup-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_dee5246f6808', 'en', 'US', 'Minestrone Soup', 'Recipe video above. The heartiest of all chunky soups, filled with anything your heart desires! While the add ins are endlessly customisable, stick with the soup broth recipe because I''ve made it extra tasty!* Asterix marked items can be substituted with any cookable vegetables, 6 cups in total.', 'https://www.recipetineats.com/tachyon/2020/07/Minestrone-Soup_0.jpg', 20, 45, 65, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.015, "unit": "L"}}, {"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_garlic", "quantity": {"value": 0.667, "unit": "pack of 3 heads"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_chicken_stock", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_water", "quantity": {"value": 0.5, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.8, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_kidney_beans", "quantity": {"value": 1.0, "unit": "can of 400g"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.1, "unit": "jar of 50g"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.3, "unit": "pack of 500g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_celery", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_carrot", "quantity": {"value": 1000.0, "unit": "pack of 1kg"}}, {"id": "ing_zucchini", "quantity": {"value": 1.0, "unit": "kg"}}, {"id": "ing_potato", "quantity": {"value": 1.0, "unit": "bag of 2kg"}}, {"id": "ing_green_beans", "quantity": {"value": 100.0, "unit": "pack"}}, {"id": "ing_baby_spinach", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_parmesan", "quantity": {"value": 0.125, "unit": "pack of 200g"}}, {"id": "ing_parsley", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["1 tbsp olive oil","150g / 5oz bacon (, finely chopped)","1 onion (, chopped)","2 garlic cloves (, minced)","800g/ 28oz crushed tomato (or 700g passata)","2 cups chicken stock/broth (, low sodium)","2 cups water","3 tbsp tomato paste","2 tsp Worcestershire sauce","400g/ 14oz canned kidney beans (, drained)","1 tsp EACH salt and pepper","1 cup small pasta (, like ditalini, tiny shells, risoni/orzo, baby macaroni, alphabet or star pasta)","1/4 cup parmesan (, grated)"]},{"ingredients":["1 celery rib* (, chopped 1.5cm / 1/2\" pieces)","1 large carrot* (, peeled and diced 1.5cm / 1/2\" pieces)","1 zucchini* (, chopped 1.5cm / 1/2\" pieces)","1 potato* (, cut into 1.5cm / 1/2\" pieces (peel if needed))","100g / 3oz green beans* (, trimmed then cut into 2cm / 3/5\" lengths)","2oz/ 60g baby spinach (or frozen spinach, kale or similar - can leave out)"],"purpose":"Minestrone Vegetables (Note 1):"},{"ingredients":["More parmesan","Chopped parsley","Crusty bread for dunking!"],"purpose":"For serving – optional:"}]', '[{"description":"Heat oil over high heat in a very large pot.","images":[],"step":1},{"description":"Add bacon, cook until starting to turn golden (~2 min) then add garlic and onion.","images":[],"step":2},{"description":"Cook until onion is translucent and bacon is light golden ~ 2minutes.","images":[],"step":3},{"description":"Add carrot, celery and zucchini. Stir for 1 minute to coat in flavour.","duration":1,"images":[],"step":4},{"description":"Add crushed tomato, chicken stock, water, tomato paste, Worcestershire sauce, kidney beans, salt and pepper.","images":[],"step":5},{"description":"Stir, bring to simmer, then place lid on and adjust heat so it''s simmering gently.","images":[],"step":6},{"description":"Simmer 20 minutes, then add potato and beans.","images":[],"step":7},{"description":"Simmer 5 minutes, then add pasta. Cook for time per pasta packet MINUS 1 1/2 minutes.","images":[],"step":8},{"description":"Remove from stove, stir through parmesan and baby spinach. Taste and adjust for salt and pepper.","images":[],"step":9},{"description":"Serve, garnished with extra parmesan and a sprinkle of parsley if desired. Warm crusty bread on the side would certainly be the cherry on top!","images":[],"step":10}]', '["gluten","milk"]', '["high_protein","low_calorie"]', '{"mealType":["dinner"],"cuisine":["American-Italian","Italian","Western"],"categories":["soup-recipes","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_4132fb580ca6', 'en', 'US', 'Chicken Stew (Casserole)', 'Recipe video above. This is the faster way to make a chicken stew (casserole) that''s done in an hour but tastes like it''s been simmering all day! The trick is to use boneless thigh fillets, beef instead of chicken broth, a good slug of red wine and BACON!', 'https://www.recipetineats.com/tachyon/2019/07/Chicken-Stew_5.jpg', 15, 50, 65, 5, '[{"id": "ing_olive_oil", "quantity": {"value": 0.007, "unit": "L"}}, {"id": "ing_bacon", "quantity": {"value": 0.75, "unit": "pack of 200g"}}, {"id": "ing_chicken_thigh", "quantity": {"value": 0.75, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.05, "unit": "jar of 50g"}}, {"id": "ing_garlic", "quantity": {"value": 1.0, "unit": "pack of 3 heads"}}, {"id": "ing_onion", "quantity": {"value": 1.0, "unit": "pack of 1kg"}}, {"id": "ing_carrot", "quantity": {"value": 3.0, "unit": "pack of 1kg"}}, {"id": "ing_celery", "quantity": {"value": 2.0, "unit": "head"}}, {"id": "ing_wine", "quantity": {"value": 0.5, "unit": "bottle of 750ml"}}, {"id": "ing_flour", "quantity": {"value": 0.06, "unit": "kg"}}, {"id": "ing_beef_stock", "quantity": {"value": 0.75, "unit": "L"}}, {"id": "ing_tomato", "quantity": {"value": 0.4, "unit": "kg"}}, {"id": "ing_worcestershire_sauce", "quantity": {"value": 10.0, "unit": "bottle"}}, {"id": "ing_thyme", "quantity": {"value": 0.15, "unit": "bunch"}}, {"id": "ing_bay_leaf", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_potato", "quantity": {"value": 350.0, "unit": "bag of 2kg"}}, {"id": "ing_mushroom", "quantity": {"value": 0.2, "unit": "kg"}}, {"id": "ing_green_beans", "quantity": {"value": 150.0, "unit": "pack"}}]', '[{"ingredients":["0.5 tbsp olive oil","150g/5oz bacon (, chopped)","750g/ 1.5lb boneless skinless chicken thighs (, cut into 3cm / 1.25\" pieces (Note 1))","1/2 tsp salt and pepper (, each)","3 garlic cloves (, minced (1 tbsp))","1 onion (, sliced)","3 carrots (, peeled, halved lengthwise, sliced 1cm / 1/3\" thick)","2 celery stalks (, sliced 1cm / 1/3\" thick)","1 1/2 cups (375ml) red wine (Note 2)","4 tbsp flour","3 cups (750ml) beef stock/broth (, low sodium (or chicken, Note 3))","400g/ 14oz crushed tomato (, canned)","2 tsp Worcestershire sauce","1/2 tsp salt and pepper (, each)","1 1/2 tsp dried thyme","2 dried bay leaves","350g/ 12 oz baby potatoes (, halved)","200g/ 6oz mushrooms (, halved (large quartered))","150g/ 5 oz green beans (, trimmed and halved)"]}]', '[{"description":"Place oil and bacon in a large heavy based casserole pot over high heat.","images":[],"step":1},{"description":"When the oil is heated and bacon releases some fat, add chicken.","images":[],"step":2},{"description":"Sprinkle with salt and pepper and cook, until chicken and bacon is browned.","images":[],"step":3},{"description":"Add garlic and onion, cook 1 minute.","images":[],"step":4},{"description":"Add celery and carrot, cook 2 minutes.","images":[],"step":5},{"description":"Add red wine, allow to simmer rapidly 2 minutes until the winey alcohol smell is gone.","images":[],"step":6},{"description":"Add flour, mix until incorporated.","images":[],"step":7},{"description":"Slowly pour in half the beef broth while stirring, then pour the rest in.","images":[],"step":8},{"description":"Add tomato, Worcestershire, thyme, bay leaves, salt, pepper.","images":[],"step":9},{"description":"Stir, add potato.","images":[],"step":10},{"description":"Cover, simmer 30 minutes.","images":[],"step":11},{"description":"Remove lid, add mushrooms and green beans. Simmer without lid* for a further 10 minutes.","images":[],"step":12},{"description":"Serve with crusty bread, sprinkled with parsley if desired!","images":[],"step":13}]', '["gluten"]', '["high_protein"]', '{"mealType":["dinner"],"cuisine":["Western"],"categories":["stews","winter-recipe-collection"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_f6fee28d7201', 'en', 'US', 'Sweet potato steaks', 'Recipe video above. I know the ingredients looks exorbitantly long for something I describe as "an easy way to turn sweet potatoes into a really tasty meaty dinner"! But actually, it is very straight forward. Thick slices of sweet potato roasted with a simple spice mix, then served on a bed of tahini yogurt topped with a glitter of garlic-sesame-chilli and pine nuts. It''s a fabulous flavour combination!Serve with something crunchy - toasted pita bread is my pick. (Note 5)', 'https://www.recipetineats.com/tachyon/2023/08/Roasted-Sweet-Potato-Steaks_6a.jpg', 10, 60, 70, 2, '[{"id": "ing_sweet_potato", "quantity": {"value": 0.001, "unit": "kg"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_smoked_paprika", "quantity": {"value": 0.188, "unit": "jar of 40g"}}, {"id": "ing_onion_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_garlic_powder", "quantity": {"value": 0.062, "unit": "jar of 40g"}}, {"id": "ing_cumin", "quantity": {"value": 0.031, "unit": "jar of 40g"}}, {"id": "ing_salt", "quantity": {"value": 0.003, "unit": "kg"}}, {"id": "ing_black_pepper", "quantity": {"value": 0.025, "unit": "jar of 50g"}}, {"id": "ing_yogurt", "quantity": {"value": 0.3, "unit": "tub of 500g"}}, {"id": "ing_tahini", "quantity": {"value": 37.5, "unit": "bottle"}}, {"id": "ing_lemon", "quantity": {"value": 0.045, "unit": "net of 500g"}}, {"id": "ing_garlic", "quantity": {"value": 0.833, "unit": "pack of 3 heads"}}, {"id": "ing_olive_oil", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_green_onion", "quantity": {"value": 0.45, "unit": "bunch"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_cayenne_pepper", "quantity": {"value": 0.375, "unit": "jar of 40g"}}, {"id": "ing_sesame_seeds", "quantity": {"value": 0.15, "unit": "pack of 100g"}}, {"id": "ing_pine_nuts", "quantity": {"value": 0.3, "unit": "pack of 100g"}}, {"id": "ing_coriander", "quantity": {"value": 0.6, "unit": "bunch"}}, {"id": "ing_pinch_of_sumac", "quantity": {"value": 0.003, "unit": "jar"}}, {"id": "ing_bread", "quantity": {"value": 1.0, "unit": "loaf"}}]', '[{"ingredients":["1 gigantic sweet potato - to cut 2 x “steaks” (1.8 cm thick, 17 cm long, 7 cm wide (0.7 x 6.5 x 2.75\") - Note 1)","2 - 3 tsp olive oil"]},{"ingredients":["1 1/2 tsp smoked paprika (sub ordinary)","1/2 tsp onion powder (or more garlic powder)","1/2 tsp onion powder (or more garlic powder)","1/4 tsp cumin powder","1/2 tsp cooking/kosher salt","1/4 tsp black pepper"],"purpose":"Spice mix:"},{"ingredients":["1 cup plain yogurt (250g)","2 1/2 tbsp tahini (Note 2)","1 1/2 tbsp lemon juice","1 garlic clove (, finely grated)","1/2 tsp cooking/kosher salt"],"purpose":"Whipped tahini yogurt sauce:"},{"ingredients":["2 tbsp extra virgin olive oil","3 garlic cloves (, finely minced)","1 1/2 tbsp eschallot (US: shallot), finely chopped (Note 3)","1 tbsp red cayenne pepper (, deseeded, finely chopped (not spicy, Note 4))","1 tbsp green cayenne pepper (, deseeded, finely chopped (not spicy, Note 4))","1 tbsp white sesame seeds"],"purpose":"Topping:"},{"ingredients":["2 tbsp pine nuts (, toasted)","2 tbsp coriander/cilantro leaves (, finely chopped)","Pinch of sumac (, optional (or paprika))","Pita or lebanese bread (, toasted (Note 5))"],"purpose":"Serving:"}]', '[{"description":"Preheat oven to 200°C/400°F (180°C fan-forced). Line a tray with parchment/baking paper.","images":[],"step":1},{"title":"Bake sweet potato","description":"Rub sweet potato steaks with oil, then sprinkle each side evenly with spice mix (don’t rub, it smears). Bake 45 - 50 minutes until potato is soft. Don’t flip.","images":[],"step":2},{"title":"Tahini yogurt sauce","description":"Whisk ingredients in a medium heat-proof bowl until mostly combined. Microwave for 20 seconds on high. Whisk again - it will be like softly whipped cream! Use warm or at room temp.","duration":0.3333333333333333,"images":[],"step":3},{"description":"Toast pine nuts in a small pan (no oil) preheated over medium heat. Once lightly golden, remove into a bowl.","images":[],"step":4},{"title":"Topping","description":"In the same pan, heat oil (still on medium). Add all Topping ingredients and cook, stirring, until the garlic is golden. Transfer into a bowl immediately.","images":[],"step":5},{"title":"Assemble","description":"Smear most of the yogurt sauce on plate (save some for drizzling). Put sweet potato on top. Sprinkle with Topping, drizzle with yogurt sauce, then sprinkle with pine nuts, coriander and sumac. EAT with crunchy toasted flatbread!","images":[],"step":6}]', '["gluten","milk","sesame"]', '["vegetarian"]', '{"mealType":["dinner"],"cuisine":["Middle Eastern"],"categories":["sweet-potato","vegetarian-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_d0f1163c1c7b', 'en', 'US', 'Homemade Paneer (Fresh Indian Cottage Cheese)', 'Recipe video above. Homemade paneer is far superior to store bought. It''s softer and creamier, and has much better flavour. It''s easy to make, without special equipment. All it takes is a little patience to let the cheese set in the fridge for 4 hours. Use paneer to make the great Indian classic, Palak Paneer (Spinach Curry with Paneer)', 'https://www.recipetineats.com/tachyon/2021/02/Homemade-Paneer-recipe_3.jpg', 10, 600, 610, 4, '[{"id": "ing_milk", "quantity": {"value": 2.0, "unit": "L"}}, {"id": "ing_lemon", "quantity": {"value": 0.12, "unit": "net of 500g"}}]', '[{"ingredients":["2 litres / 2 quarts milk (, full-fat (low-fat won''t work))","4 tbsp lemon juice (sub white vinegar)"]}]', '[{"description":"Heat the milk in a large saucepan over medium high heat until the top becomes foamy, just as looks like it''s about to boil.","images":[],"step":1},{"description":"Turn stove off. Add lemon juice and stir for 1 minute. The milk should begin to curdle. If it doesn’t, turn the stove back on and bring back to a gentle boil until the solids separate.","duration":1,"images":[],"step":2},{"description":"Strain & remove excess water:","images":[],"step":3},{"title":"Line strainer or colander","description":"Place over a deep bowl. Line strainer with 2 layers of cheesecloth (Note 1).","images":[],"step":4},{"title":"Strain","description":"Ladle in half of the curdled milk to begin with, then pour the rest in. Leave until all the liquid drains – this might take 5 to 10 minutes.","images":[],"step":5},{"title":"Rinse","description":"Discard liquid (whey) in the bowl. Bundle the paneer up in the cheesecloth (it will still be quite watery at this stage) then rinse bundle briefly under cold tap water. This helps to remove lemon flavour + cool for easier handling.","images":[],"step":6},{"description":"Squeeze out excess water by twisting the cheesecloth and squeezing the bundle, but not so hard that paneer squeezes out through the cloth. Once liquid no longer comes out, stop. The paneer will still be quite soft at this stage.","images":[],"step":7},{"title":"Weigh cheese down with weights","description":"Shape cheese into a disc around 2cm / ¾\" thick, still wrapped in cheesecloth. Place in a strainer or colander set over a bowl. Top with a small plate then 2 x 400g/14oz cans (or similar weight).","images":[],"step":8},{"description":"Refrigerate for 4 hours. During this time the paneer will set (become firm) and remaining liquid will drain out. (Note 2)","images":[],"step":9},{"description":"Storage / cutting:","images":[],"step":10},{"description":"Remove paneer from fridge and carefully unwrap. There will be a dent in the middle, this is normal (it''s from the draining).","images":[],"step":11},{"description":"At this stage, the paneer is now ready for use. You can either cut it immediately and use in a recipe (such as Palak Paneer!), or store the whole uncut block for another time and just cut when needed.","images":[],"step":12},{"description":"Store in the fridge for up to 2 weeks, or freeze for 3 months.","images":[],"step":13}]', '["milk"]', '["gluten_free","low_calorie","vegetarian"]', '{"mealType":["dinner"],"cuisine":["Indian"],"categories":["uncategorized"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
INSERT INTO public.recipes (id, language, country, title, description, "imageUrl", "prepTime", "cookTime", "totalTime", "defaultServings", ingredients, "ingredientGroups", steps, allergens, diet, taxonomy) VALUES ('recipe_8a27cf02cc51', 'en', 'US', 'Vietnamese pork noodle bowls (bun thit nuong)', 'Recipe video above. Popular Vietnamese street food! Fabulous combination of contrasting flavours and textures, fresh vegetables with flavourful lemongrass marinated pork, noodles and herbs, all doused in a mild nuoc cham sauce (so you can use lots).Light and fresh yet anything but dull. Excellent DIY spread for gatherings - lay it all out on tables and let everyone put their own bowls together. Chicken version here. Slightly different toppings because chicken is a white meat, pork is richer. :)', 'https://www.recipetineats.com/tachyon/2023/04/Vietnamese-noodles-lemongrass-pork-6.jpg', 30, 10, 40, 4, '[{"id": "ing_lemongrass", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_pasta_of_choice", "quantity": {"value": 0.4, "unit": "pack of 500g"}}, {"id": "ing_lettuce", "quantity": {"value": 1.0, "unit": "head"}}, {"id": "ing_cucumber", "quantity": {"value": 2.0, "unit": "unit"}}, {"id": "ing_bean_sprouts", "quantity": {"value": 2.0, "unit": "bag of 250g"}}, {"id": "ing_mint", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_coriander", "quantity": {"value": 1.0, "unit": "bunch"}}, {"id": "ing_peanuts", "quantity": {"value": 0.094, "unit": "jar"}}, {"id": "ing_chilli", "quantity": {"value": 1.0, "unit": "pack of 100g"}}, {"id": "ing_lime", "quantity": {"value": 1.0, "unit": "net of 500g"}}, {"id": "ing_carrot", "quantity": {"value": 2.0, "unit": "pack of 1kg"}}, {"id": "ing_radishes", "quantity": {"value": 0.5, "unit": "kg"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_sugar", "quantity": {"value": 0.075, "unit": "kg"}}, {"id": "ing_salt", "quantity": {"value": 0.02, "unit": "kg"}}, {"id": "ing_rice_vinegar", "quantity": {"value": 0.75, "unit": "bottle of 250ml"}}, {"id": "ing_fish_fillets", "quantity": {"value": 0.068, "unit": "kg"}}, {"id": "ing_vinegar", "quantity": {"value": 0.188, "unit": "L"}}, {"id": "ing_lime", "quantity": {"value": 3.0, "unit": "net of 500g"}}, {"id": "ing_water", "quantity": {"value": 0.375, "unit": "L"}}, {"id": "ing_chilli", "quantity": {"value": 2.0, "unit": "pack of 100g"}}, {"id": "ing_garlic", "quantity": {"value": 8.333, "unit": "pack of 3 heads"}}]', '[{"ingredients":["1 batch lemongrass marinated pork (it''s marinated overnight. 8 pieces, serves 4)","200g/ 7oz dried vermicelli noodles (Note 1)","1 head soft lettuce (like butter lettuce), torn into large bite size pieces (or 4 cups shredded iceberg, cos/romaine)","2 cucumbers (, halved lengthwise then sliced on the diagonal 3mm / 0.15\" thick)","2 cups bean sprouts","Handful mint leaves","Handful cilantro/coriander","1/4 cup finely chopped unsalted peanuts","Sliced red chilli (for garnish - optional)","Lime wedges (to serve - optional but recommended)"]},{"ingredients":["2 medium carrots (, peeled cut into 2-3mm / 1/10″ batons )","1/2 large white radish (daikon) (, peeled, cut the same as carrots)","1 1/2 cups boiling water","1/2 cup white sugar","4 tsp cooking salt (kosher salt)","3/4 cup rice vinegar (sub apple cider vinegar)"],"purpose":"Vietnamese pickled vegetables (Note 2)"},{"ingredients":["4 1/2 tbsp white sugar","4 1/2 tbsp fish sauce (Note 3)","3 tbsp rice wine vinegar","3 tbsp lime juice","1/2 cup water","2 birds eye chilli or Thai chilli (, deseeded and finely chopped (Note 4))","5 cloves garlic (, finely chopped)"],"purpose":"Nuoc cham Vietnamese sauce (Note 3):"}]', '[{"description":"Make pickled vegetables:","images":[],"step":1},{"title":"Pickle","description":"In a large bowl, dissolve the salt and sugar in the hot water. Stir in vinegar. Add carrots and daikon – they should just about be covered.","images":[],"step":2},{"title":"2 hours","description":"Leave for 2 hours until slightly floppy. Drain well then use per recipe.","images":[],"step":3},{"title":"Nuoc cham sauce","description":"Mix ingredients together. Until sugar is dissolved.","images":[],"step":4},{"title":"Vermicelli noodles","description":"Soak in boiling water for 5 minutes (or per packet directions). Drain, rinse under tap water, then cool and drain thoroughly (nobody likes watery noodles!).","duration":5,"images":[],"step":5},{"title":"Toppings","description":"Prepare all the other toppings, ready to use.","images":[],"step":6},{"description":"Cook pork per the recipe.","images":[],"step":7},{"title":"Assemble bowls","description":"Place noodles in a bowl. Top with lettuce, pickled vegetables, cucumber and bean sprouts. Slice pork, place 2 steaks on each bowl. Top with herbs, sprinkle with peanuts and sliced chilli. Add a lime wedge.","images":[],"step":8},{"description":"Serve with nuoc cham on the side so everybody can help themselves. Douse generously! Dive in and eat!","images":[],"step":9}]', '["fish","milk"]', '["gluten_free","high_protein"]', '{"mealType":["dinner"],"cuisine":["Vietnamese"],"categories":["vietnamese-recipes"]}') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, "imageUrl" = EXCLUDED."imageUrl", "prepTime" = EXCLUDED."prepTime", "cookTime" = EXCLUDED."cookTime", "totalTime" = EXCLUDED."totalTime", "defaultServings" = EXCLUDED."defaultServings", ingredients = EXCLUDED.ingredients, "ingredientGroups" = EXCLUDED."ingredientGroups", steps = EXCLUDED.steps, allergens = EXCLUDED.allergens, diet = EXCLUDED.diet, taxonomy = EXCLUDED.taxonomy;
